MultiLanguageQuestData['mx'] = {}
MultiLanguageQuestData['mx'][1] = {title = "Misión de Kanrethad", objective = "Habla con Kanrethad para que restaure tus talentos, armas y montura.", description = "<Bienvenido/Bienvenida> de vuelta del mundo de los muertos.\n\nHace mucho tiempo tus hermanos te consideraban <un orgulloso héroe/una orgullosa heroína>. Ahora caíste y estás <destrozado/destrozada>... no eres más que una reliquia del pasado. Colócate ante mí para que pueda volver a despertar la leyenda que alguna vez fuiste.\n\nTe devolveré los poderes y las armas que perdiste y así volverás a estar <completo/completa>.Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nDestrero de la muerte de Acherus\n\nTe van a lanzar el siguiente hechizo:\n\nInvocar destrero de la Muerte\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][2] = {title = "La garfa de Garfafilada", objective = "Llévale la garfa de Garfafilada a Senani Corazón Atronador en el Refugio Brisa de Plata, Vallefresno.", description = "El poderoso hipogrifo Garfafilada ha sido ejecutado, con la garfa de la bestia derribada como testimonio de tu victoria. Seguro que Senani Corazón Atronador, del Refugio Brisa de Plata, estará interesado en ver este trofeo que prueba tus actos.", progress = "¿Qué llevas ahí, <clase>? ¿Podría ser...?", completion = "¿Has matado a la bestia?\n\nTe debo mucho, amigo mío. Esa bestia ha aterrorizado a mucha gente durante años, pero su muerte tiene un significado especial para mí.\n\nVerás, hace poco mi hermano fue víctima de estas mismas garras... Ahora dormiré bien, sabiendo que se ha vengado su muerte.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5] = {title = "La hambruna de Alterio", objective = "Habla con el Chef Grual.", description = "¡Llevo semanas escondiéndome en esta ciudad fantasma y no he comido más que larvas y hierbajos! Necesito algo de comida decente. Estoy en disposición de pagar bien.\n\nSi me traes un festín, te pagaré generosamente.\n\nHe oído que el chef Grual del Mesón del Cuervo Escarlata de Villa Oscura hace unos estupendos pasteles de cangrejo oscuro...", progress = nil, completion = "Necesitas pasteles de cangrejo, ¿verdad? Bueno, quizás pueda cocinarte algunos...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6] = {title = "La recompensa por Garrick Piesuaves", objective = "Mata a Garrick Piesuaves y lleva su cabeza al ayudante de alguacil Willem a la Abadía de Villanorte.", description = "Garrick Piesuaves es un maleante que lleva semanas acosando a granjeros y mercaderes. Ha sido visto en una choza cerca de los viñedos, cruzando el puente al este de la abadía. Tráeme la cabeza de ese villano y podrás quedarte con su botín.\n\nPero ve con cuidado, <nombre>. Garrick anda con una pandilla de matones. Puede que no te sea fácil llegar hasta él.", progress = "¿Has encontrado la choza de Garrick? ¿Has acabado con él?", completion = "¡Lo has conseguido! Elwynn te estará muy agradecido por esto. ¡Acabas de ganarte una hermosa recompensa!", rewards = "Guerrera a capasCapa insigniaPantalones estrechosMitones de WillemBallesta de defensor de la abadíaVarita perdidaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][7] = {title = "La limpieza del campamento kóbold", objective = "Mata a 8 alimañas kóbold y ve a hablar con el alguacil McBride.", description = "<nombre>, lo primero que tienes que hacer es limpiar; un clan de kóbolds ha invadido los bosques del norte. Ve y liquida a todos los kóbolds que encuentres; si reducimos sus filas podremos echarlos de Villanorte.", progress = nil, completion = "Buen trabajo. Los kóbolds son ladrones y cobardes, pero en gran número pueden suponer una amenaza y lo último que necesitamos los ciudadanos de Ventormenta es una amenaza más.\n\nTe agradezco que hayas acabado con ellos.", rewards = "Cincho de abad de VillanorteBotas de corredorGuantes de cuidador de huargosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][8] = {title = "Un trato de pícaro", objective = "Lleva la carta anodina a Claros de Tirisfal y entrégasela a la tabernera Renee.", description = "¡Eh, colega! ¿Le harías un favor a un joven hombre que ha combatido contra más zombis y arañas de los que puede contar?\n\nTengo una carta que tiene que llegar a Rémol... Es para una tabernera llamada Renee no sé qué. No creo que importe cómo se apellida, la verdad.\n\nPero el sitio es muy acogedor y está lleno de víctimas de la Plaga que intentan abrirse paso en el mundo. Es el sitio ideal para descansar... si es que necesitas hacerlo. Anímate... si vas, te pagaré bien.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nChampiñón de bosqueAgua de manantial refrescante\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][9] = {title = "Campos de la muerte", objective = "El granjero Saldean quiere que mates a 20 vigías de la cosecha.", description = "¡Mira lo que le ha ocurrido a este lugar! Estas tierras estaban antes en manos de buenos granjeros. Pero los condenados ladrones los han ahuyentado a todos. ¡Pero no a mí! Eso sí, parece que algunos vigías de la cosecha han invadido los campos.\n\nSi estás <preparado/preparada> me gustaría que fueras y mataras a 20 de ellos. Vuelve cuando hayas terminado y te pagaré. Si terminas con los de mi campo, puedes limpiar también los campos vecinos.", progress = nil, completion = "Buen trabajo amigo. Te has ganado bien tu sueldo. Quién sabe, quizás los Páramos de Poniente vuelvan a ser prósperos.", rewards = "Toga de cosechadorPantalones de cosechadorRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10] = {title = "La redención de Patagolpe", objective = "Descubre qué le ha ocurrido al perito adjunto Patagolpe y llévalo a él o su equipo de análisis ante el perito jefe Picoflojo, en Gadgetzan.", description = "¡Oh, esto es horrible! Envié a mi mejor ayudante, el perito adjunto Patagolpe, al desierto situado al sudeste de aquí, una zona que se conoce como Sima Abierta. Bien, pues ha desaparecido y su último informe contenía más información acerca de esos extraños bichos que había visto por la zona. ¿Es posible que ya hayan infestado dos grandes regiones del desierto?\n\nPor favor, ¡necesito que vayas a Sima Abierta en busca de Patagolpe! Y si no lo encuentras a él, al menos a ver si aparece su equipo de análisis. Me temo que pueda ser lo único que quede de ese pobre chico.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11] = {title = "Recompensas por los gnolls Zarparrío", objective = "Lleva 8 bandas gnoll pintadas al ayudante de alguacil Rainer al Cuartel.", description = "En las fronteras del Bosque de Elwynn se han avistado gnolls, unas criaturas salvajes que seguramente no están allí por trabajo. Un grupo enorme de ellos, uno más numeroso del que podemos contener solos, ha infestado los bosques que hay al sur de la torre de vigilancia. Otro grupo ha infestado las áreas cercanas al Lago del Hito, al este.\n\nEl ejército de Ventormenta elogiará a quienquiera que le ayude a matarlos. Tráeme sus bandas gnoll pintadas como prueba de tu hazaña.", progress = "Saludos, <nombre>. ¿Has estado matando gnolls...?", completion = "¡Has estado muy ocupado! Muchas gracias, &lt;nombre&gt;.", rewards = "Pantalones de UrchinBotas de rompegnollBotas de Cairne de piedraRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][12] = {title = "La Milicia Popular", objective = "Gryan Mantorrecio quiere que mates a 15 tramperos Defias y a 15 contrabandistas Defias. Cuando lo hayas hecho vuelve a verle en la Colina del Centinela.", description = "La Milicia Popular solo tiene un objetivo: defender las tierras de los Páramos de Poniente y traer la paz a nuestro entorno. Por desgracia, el precio de la paz suele pagarse en sangre.\n\nSegún el informe de uno de mis exploradores, una banda de tramperos Defias ha sido vista cerca de la Mina de Jango al noroeste de aquí, en La Granja de Molsen y en la Plantación de Calabazas de Cejade. Si quieres unirte a nuestras filas, acaba con 15 tramperos Defias y con 15 contrabandistas Defias y vuelve a verme.", progress = nil, completion = "Bien hecho, &lt;nombre&gt;. Mi explorador ha sido testigo de tus hazañas. Estás dando muy buenas pruebas de tu valía.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13] = {title = "La Milicia Popular", objective = "Gryan Mantorrecio quiere que mates a 15 saqueadores Defias y a 15 despojadores Defias. Cuando lo hayas hecho vuelve a verle en la Colina del Centinela.", description = "Una banda de despiadados saqueadores Defias ha sido vista saqueando la Mina de la Costa del Oro, el Arroyo de la Luna y la Hacienda de Alexston. La Milicia Popular no tolerarán ese comportamiento. Avisa inmediatamente, <nombre>, y haz conocer la presencia de la Luz en los Páramos de Poniente.\n\nLa Mina de la Costa del Oro está cerca de la costa, al oeste de la torre. El siguiente paso de tu instrucción consistirá en acabar con 15 de esos saqueadores Defias y con 15 despojadores Defias.", progress = nil, completion = "Hasta ahora tus hazañas no han dejado de probar tu valía para la Milicia Popular.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14] = {title = "La Milicia Popular", objective = "Gryan Mantorrecio quiere que mates a 15 bandoleros Defias, a 5 acechacaminos Defias y a 5 nudillos Defias. Cuando lo hayas hecho vuelve a verle en la Colina del Centinela.", description = "Algunos Defias nos han esquivado. Según informa mi mejor explorador, los Defias han estado saqueando y expoliando el campo, hasta la parte sureste de los Páramos de Poniente. Creemos que se están ocultando en Las Colinas Afiladas, planeando sus siguientes pasos. Acaba con esos miserables en nombre de La Milicia Popular", progress = nil, completion = "Cuando dejé Las Tierras Devastadas de Lordaeron, regresé para encontrar mi patria sumida en una situación desalentadora. Pero aún hay esperanza para los Páramos de Poniente. Has demostrado tu valor en la batalla, y es evidente que sirves con honor a nuestra causa. Me es por ello un gran honor ordenarte como miembro de La Milicia Popular. Que la Luz guíe siempre tu camino.", rewards = "Puño de La Milicia PopularFilo de La Milicia PopularChispa de La Milicia PopularRecibirás:\n\n"}
MultiLanguageQuestData['mx'][15] = {title = "Investigar la Mina del Eco", objective = "Mata a 8 trabajadores kóbold y ve a hablar con el alguacil McBride.", description = "<nombre>, los exploradores dicen que hay más kóbolds de lo que creíamos. Un grupo de trabajadores ha acampado cerca de la Mina del Eco, al norte de aquí.\n\nVe a la mina y liquídalos; sabemos que hay al menos ocho. Comprueba que no quede ninguno más y vuelve.", progress = nil, completion = "No me gusta que haya kóbolds en la mina; eso no puede ser bueno. Bien, acepta esto como pago, y vuelve a hablar conmigo cuando quieras; puede que tengas que volver a la mina...", rewards = "Toga de abad de VillanortePantalones de maestro espíaCinturón de infantería de VentormentaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][16] = {title = "Dale de beber a Gerard", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nManzana roja lustrosa"}
MultiLanguageQuestData['mx'][17] = {title = "Componentes de Uldaman", objective = "Lleva 12 setas magenta a Ghak Sanadón a Thelsamar.", description = "Hace poco oí hablar de un organismo recién descubierto: las setas magenta. Crecen arracimadas en la excavación de Uldaman y pueden encontrarse en los túneles primitivos y en las profundidades de las zonas menos explotadas. Quiero ver qué usos potenciales pueden tener en la alquimia, por eso necesito tu ayuda.\n\nTráeme una docena de setas magenta. Es posible que se defiendan con esporas venenosas; ten cuidado.\n\n¡A cambio, te daré uno de mis famosos elixires vigorizantes!", progress = "¿Has conseguido las setas magenta que necesito para mis proyectos de alquimia? Si no hay setas, ¡no hay premio!", completion = "¡Has hecho un buen trabajo otra vez, &lt;nombre&gt;! Esto va a ser muy interesante. \n\nY como te prometí, aquí tienes uno de mis mejores elixires vigorizantes. \n\nSi te interesa la alquimia, puedo ofrecerte otros trabajos. En todo caso, te agradezco tu ayuda.", rewards = "Recibirás:\n\nPoción restauradora"}
MultiLanguageQuestData['mx'][18] = {title = "Hermandad de ladrones", objective = "Lleva 8 pañuelos de arpillera roja al ayudante de alguacil Willem cerca de la Abadía de Villanorte.", description = "Hace poco llegó una banda de maleantes a Villanorte. Se hacen llamar la Hermandad Defias; se les ha visto cruzando el río hacia el este.\n\nNo sé qué están haciendo, ¡pero seguro que no es nada bueno! Tráeme sus pañuelos y te daré un arma como recompensa.", progress = "¿Me traes los pañuelos?", completion = "Ah, traes unos pañuelos. El ejército de Ventormenta te agradece tu ayuda.", rewards = "Lanza larga de intendente de miliciaEspada corta de miliciaDaga de miliciaMartillo de guerra de miliciaMartillo de miliciaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][19] = {title = "Tharil'zun", objective = "Lleva la cabeza de Tharil'zun al alguacil Marris a Crestagrana.", description = "Hay avanzados y renegados Roca Negra tendiendo emboscadas entre aquí y el Fuerte de Petravista. El jefe de los avanzados se llama Tharil'zun y lo queremos muerto. ¡Tráeme su cabeza!", progress = "Los orcos de Roca Negra siguen atacando. ¿Has acabado con Tharil'zun?", completion = "Era fuerte y cruel; seguro que no fue fácil derrotarlo. Gracias; aquí tienes tu recompensa, &lt;nombre&gt;.", rewards = "Rodela endurecida con fuegoTriturador orcoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][20] = {title = "La amenaza de los Roca Negra", objective = "Lleva 10 hachas desgastadas por la batalla al alguacil Marris a Villa del Lago.", description = "Los orcos Roca Negra llegaron desde Las Estepas Ardientes y han invadido el Fuerte de Petravista, al norte de aquí. Andan merodeando por el norte de Villa del Lago y tienen a los ciudadanos encerrados como a ganado.\n\nLibra a Villa del Lago de esta amenaza. Mata a los orcos y tráeme 10 hachas desgastadas por la batalla como prueba.\n\nAunque nos amenazan desde el norte, sabemos que hay más al sureste de Crestagrana. Si los encuentras, mátalos también.", progress = "¿Has liquidado a muchos orcos, <nombre>? Demuéstramelo.", completion = "Ahora hay muchos menos orcos de los que ocuparse; gracias.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][21] = {title = "Refriega en el Eco", objective = "Mata 8 obreros kóbold y ve a hablar con el alguacil McBride a la Abadía de Villanorte.", description = "Ha quedado demostrado que tenemos que purgar la Mina del Eco. Vuelve allí y ayuda a eliminar a los kóbolds.\n\nDate prisa, <nombre>. Cuanto más tiempo dejemos a los kóbolds en la mina, más nos costará expulsarlos de Villanorte.", progress = nil, completion = "Has vuelto a ganarte mi respeto y la gratitud del ejército de Ventormenta. Enviaré a otro equipo para ver si quedan kóbolds en la mina; para ti tengo otras misiones.", rewards = "Cinturón de modistoBotas de modistoGuantes de modistoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][22] = {title = "Pastel de hígado de dentosangre", objective = "Salma Saldean necesita 8 hígados de dentosangre para hacer un pastel de hígado de dentosangre.", description = "Las cebollas están peladas. El ajo machacado. La corteza está tostada. Las hierbas de eneldo picadas. ¡Lo único que me falta para mi famosa empanada de carne son 8 hígados de dentosangre!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPastel de hígado de dentosangreReceta: pastel de hígado de dentosangre"}
MultiLanguageQuestData['mx'][23] = {title = "La pata de Ursangous", objective = "Llévale la pata de Ursangous al capitán Tarkan en el Refugio Brisa de Plata.", description = "¡El poderoso oso Ursangous ya es historia!\n\nLa pequeña media luna de su pata indica que a esta bestia la entrenaron los elfos de la noche para recorrer el bosque en busca de sus enemigos. Quién sabe cuántos de tus aliados de la Horda han caído ante esta criatura.\n\nDeberías llevarle la pata a Tarkan, en el Refugio Brisa de Plata.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24] = {title = "La cabeza de Shadumbra", objective = "Llévale la cabeza de Shadumbra al Capitán Goggath en la Avanzada Grito Infernal.", description = "El otrora veloz Shadumbra yace ahora inerte mientras tú reivindicas tu victoria sobre él.\n\nLos elfos de la noche aprecian a esta criatura legendaria. Su cabeza servirá como trofeo intimidatorio y como símbolo del fin de la Alianza en Vallefresno.\n\nEl Capitán Goggath, en la Avanzada Grito Infernal, estará encantado de recibir la cabeza del sable de la noche asesinado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25] = {title = "Un jarro de agua fría", objective = "El capitán Tarkan, en el Refugio Brisa de Plata, quiere que acabes con Marearess y con 12 elementales de agua podrida en el Lago Mystral.", description = "¡Deberías haberlo visto, <clase>!\n\nLos elfos pensaban que Brisa de Plata era inexpugnable. Con sus fuertes defensas y su ejército de elementales de agua, casi tenían razón.\n\nCasi.\n\nUno de nuestros magos pudo invocar un elemental corrupto para sembrar el caos y la ira entre los demás.\n\n¡Ah, la expresión de sus rostros!\n\n<Tarkan se ríe.>\n\nPor desgracia, el mago que lo invocó cayó en combate. Ahora necesito que alguien acabe con nuestra creación.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][27] = {title = "Una lección que aprender", objective = "Ve a Claro de la Luna, al poblado Amparo de la Noche y habla con Dendrita Rafagaestelar.", description = "<nombre>, he seguido tus progresos con gran gozo. Sin duda te estás convirtiendo en <un valioso protector/una valiosa protectora> de la naturaleza.\n\nHa llegado el momento de que aprendas más sobre una de las formas animales con las que Cenarius nos ha bendecido. Una forma que podemos adoptar y que nos permite controlar el agua. Tendrás que viajar al poblado Amparo de la Noche, que está en Claro de la Luna, y hablar con Dendrita Rafagaestelar del Círculo Cenarion. Él será tu guía.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28] = {title = "La prueba del lago", objective = "Lleva un adorno de altar del Lago Elune'ara al Santuario de Remulos, al noroeste de Claro de la Luna. Usa el adorno en el santuario. \n\nDespués, habla con Tajarri en el santuario para completar la prueba.", description = "En tu primera prueba, debes ir a las profundidades del Lago Elune'ara y encontrar un adorno de altar. Se descompone rápidamente, por lo que deberás ir inmediatamente al Santuario de Remulos. Coloca el adorno en el altar y habla con Tajarri; es una de las celadoras más apreciadas de Claro de la Luna.\n\nTienes un tiempo limitado para completar la tarea y es probable que tengas que competir con otros druidas en busca de adornos. Necesitarás toda tu destreza mental y física.\n\nSuerte, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][30] = {title = "La prueba del león marino", objective = "Busca el colgante de Agilidad acuática y el colgante de Resistencia acuática. Habla con la gente de Claro de la Luna para conseguir pistas sobre la ubicación de los colgantes. \n\nForma el colgante del león marino con los otros dos cuando estés cerca del Santuario de Remulos. \n\nLleva el colgante completo a Dendrita Rafagaestelar a Amparo de la Noche, en Claro de la Luna.", description = "En tu segunda prueba debes encontrar las dos mitades del colgante del león marino. Una obtiene su poder de la agilidad del león marino cuando se desliza en el agua, la otra lo obtiene de su increíble capacidad de resistencia. Los druidas se alimentan de ambos rasgos para asumir su forma acuática.\n\nHabla con la gente de Claro de la Luna para averiguar dónde están las mitades y tráemelas para que las unamos. Luego llevarás el colgante a Dendrita Rafagaestelar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][32] = {title = "La sublevación de los silítidos", objective = "Entrégale el informe a Zilzibin Tambor Sabio en Orgrimmar.", description = "Aquí tienes el informe. Te ruego que se lo entregues a alguien que tenga conocimientos de este tema.\n\nConozco a un trol erudito llamado Zilzibin Tambor Sabio que ha dedicado mucho tiempo al estudio de los seres vivos que solo se encuentran en Azeroth. ¡Es un historiador de los pies a la cabeza! Entrégale este informe si quieres que te ayude a entender a qué te enfrentas y el modo de detener esta amenaza. Vamos a necesitar toda la ayuda que podamos conseguir.\n\nZil vive en una casa en el segundo nivel de La Calle Mayor en Orgrimmar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][33] = {title = "Los lobos cruzan la frontera", objective = "Lleva 8 pelambres de lobo malsano a Eagan Desollapelambres junto a la Abadía de Villanorte.", description = "Sea lo que sea lo que está afectando a estos lobos, no se va. Cada día que pasa hay más lobos enfermos. Me puede pedirle a alguien que mate a las bestias de la naturaleza, pero debemos acabar con los lobos jóvenes malsanos antes de que esta pequeña infección se convierta en una epidemia.\n\nMata lobos jóvenes malsanos en el valle y tráeme pelambres de lobo malsano como prueba de tu hazaña.", progress = "¡Ey, <nombre>. Tengo hambre... ¿Conseguiste la carne de lobo dura?", completion = "¡Has estado ocupado! No puedo esperar a cocinar esa carne de lobo...\n\nTengo algunos artículos que quizás te sean útiles, ¡elige una!", rewards = "Zapatos de pelaje suaveBrazales de piel de loboZapatos de abad de VillanorteBrazales de zonas fronterizasJubón de cazador de lobosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][34] = {title = "Una visita poco grata", objective = "Martie Jainrose de Villa del Lago quiere que mates a Panzallena. Llévale un colmillo como prueba.", description = "Han vuelto a arrasar mi jardín, y sé quién es el responsable. Es ese maldito jabalí, ese al que el alguacil Marris llama Panzallena.\n\nYa es demasiado tarde para replantar narcisos. Ese puerco ha devastado mis flores. ¡Acaba con ese bicharraco! Si me traes un colmillo suyo, te recompensaré. Dicen que anda husmeando por los campos que hay al suroeste de Villa del Lago, pero de vez en cuando viene a mi jardín.", progress = "¿Sigue Panzallena campando a sus anchas o has conseguido librar a Villa del Lago de esa peste de una vez por todas?", completion = "¡Por fin! Gracias, &lt;nombre&gt;, me has hecho un favor enorme. ¡Este año el jardín estará precioso!", rewards = "Recibirás:\n\nRamo de begoñas escarlata"}
MultiLanguageQuestData['mx'][35] = {title = "Más preocupaciones", objective = "El alguacil Dughan quiere que hables con el guardia Thomas.", description = "Si te preocupa que los rumores sobre los múrlocs sean ciertos, viaja al puente del este de Elwynn y habla con el guardia Thomas. Esta última semana se encuentra emplazado en el puente y sabrá cuál es el estado de la situación.\n\nTengo un destrero de Ventormenta que te llevará hasta el guardia Thomas. Si quieres utilizar el caballo, dímelo.", progress = nil, completion = "Sí, los múrlocs se han asentado a lo largo de los ríos del este de Elwynn. No sabemos por qué están ahí, pero son agresivos y, además, ¡son hasta un poco inteligentes!", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][36] = {title = "Estofado de los Páramos de Poniente", objective = "Verna Cejade quiere que le entregues su receta del estofado de los Páramos de Poniente a Salma Saldean.", description = "Nunca pensé que llegaría el día en el que tuviera que dejar la granja. Pero los campos están llenos de ladrones y es demasiado peligroso que sigamos aquí. En cuanto el granjero Cejade consiga arreglar el carro nos pondremos en marcha.\n\n¿Podrías hacerme un favor? Deja que te escriba mi receta del estofado de los Páramos de Poniente. Por favor, llévasela a Salma Saldean, estará en la Finca de Saldean, nada más pasar la bifurcación del camino.", progress = "Voy a echar mucho de menos a Verna Cejade. ¿No la verías por casualidad cuando estuviste por ahí, verdad?", completion = "Esa Verna siempre fue una muchacha encantadora. La echaré de menos en los Páramos de Poniente pero, entre tú y yo, es una chica de ciudad y en Ventormenta estará muy a gusto. ¡Pero basta de chácharas! ¡Tenemos que hacer el estofado de los Páramos de Poniente!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][37] = {title = "Encuentra a los guardias perdidos", objective = "El guardia Thomas quiere que viajes al norte, río arriba, y busques a sus dos guardias, Rolf y Malakai.", description = "Hace unos días mandé a dos guardias, Rolf y Malakai, a investigar el río. Aún no han regresado. Para completar mi informe necesito saber qué les ocurrió a esos hombres.\n\nViaja al norte a lo largo del río y encuentra a mis guardias... o lo que quede de ellos.", progress = nil, completion = "Aunque el cuerpo ha sido saqueado, cerca de él hay un medallón que nadie ha recogido. Tiene una inscripción: \"Lacayo Malakai Roca\".", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][38] = {title = "Estofado de los Páramos de Poniente", objective = "Salma Saldean quiere 3 carnes fibrosas de buitre, 3 morros de dentosangre, 3 ojos de múrloc y 3 okras.", description = "¡Ayúdame a preparar el estofado de los Páramos de Poniente! Vuelve con estos ingredientes: \n\n 3 piezas de carne fibrosa de buitre \n 3 morros de dentosangre \n 3 ojos de múrloc \n 3 okras", progress = "Vuelve con estos ingredientes: \n\n 3 piezas de carne fibrosa de buitre \n 3 morros de dentosangre \n 3 ojos de múrloc \n 3 okras", completion = "¡Esa okra servirá para dar algo de consistencia al caldo, perfecto! Ahora solo nos falta por añadir carne fibrosa de buitre, unos cuantos ojos de múrloc y esos deliciosos morros de dentosangre... ¡y ya estará listo! Por toda tu ayuda, &lt;nombre&gt;, ¡quiero que te lleves el primer lote de estofado de los Páramos de Poniente!", rewards = "Recibirás:\n\nReceta: estofado de los Páramos de PonienteEstofado de los Páramos de PonienteMitones de SalmaCuchillo de cocina afilado"}
MultiLanguageQuestData['mx'][40] = {title = "Un peligro con olor a pescado", objective = "Remy \"Dos Veces\" quiere que hables con el alguacil Dughan de Villadorada.", description = "¡Hay una nueva amenaza en el Bosque de Elwynn, <nombre>! ¡Los múrlocs están subiendo por los ríos al este de Elwynn, ahuyentando a los peces y atacando a las buenas gentes de allí!\n\nAvisé al alguacil Dughan, pero le preocupan más los gnolls y los bandidos. No cree que los múrlocs sean una amenaza.\n\n¡Por favor, <nombre>! ¡Habla con Dughan y convéncele de que envíe más tropas al este!", progress = nil, completion = "Sí, hablé con Remy. Lo respeto como mercader, aunque los informes de los múrlocs del este han sido, por decirlo suavemente, demasiado superficiales. \n\nTomo nota de tu preocupación pero, si no recibo un informe militar sobre la amenaza múrloc, no puedo enviar más tropas al este.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][45] = {title = "Descubre el destino de Rolf", objective = "Busca a Rolf o alguna prueba de su muerte en el poblado múrloc.", description = "En tu exploración del área encuentras huellas palmeadas que llevan al este por la costa del Lago del Hito. Hacia el este, en la distancia, adivinas la silueta de una aldea múrloc.\n\nQuizás Rolf encontró allí su destino...", progress = nil, completion = "Alrededor del cuello del cadáver hay un medallón de metal con una inscripción que reza: \"Lacayo Rolf Hartford\".", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][46] = {title = "Recompensas por los múrlocs", objective = "Lleva 8 aletas de múrloc rotas al guardia Thomas al puente oriental de Elwynn.", description = "El ejército de Ventormenta ha puesto precio a la cabeza de los rondadores y batidores múrloc de Elwynn. Mátalos y llévale sus aletas al guardia Thomas. El ejército de Ventormenta te recompensará bien.\n\nLos múrlocs han construido una aldea en el Lago del Hito, al norte de aquí, y otra en el sur, donde se divide el río.", progress = "¿Cómo va la caza, <nombre>?", completion = "¿Tienes las aletas? ¡Genial! El alguacil Dughan está ansioso por recibir noticias del estado de la situación en Elwynn y me gustaría decirle que empezamos a controlar la situación. \n\nTus acciones han contribuido a que sea posible.", rewards = "Garrote de metal sólidoBayonetaEspada magna bien usadaBallesta ligera de MariscalRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][47] = {title = "Intercambio de polvo de oro", objective = "Lleva 10 unidades de polvo de oro a Remy \"Dos Veces\" a Villadorada. Puedes obtener polvo de oro de los kóbolds del Bosque de Elwynn.", description = "Los kóbolds de esa zona a veces llevan polvo de oro. Me vendría muy bien. Consígueme un montón de polvo de oro y te pagaré el mejor precio de la ciudad, ¡el mejor!\n\nPuedes encontrar kóbolds en la Mina Abisal, al sur, y también alrededor de la Cantera de Jaspe, al noreste.", progress = "¡Psst! ¿Tienes ese polvo de oro... para mí?", completion = "Gracias por el polvo de oro, &lt;nombre&gt;. Aquí tienes tu dinero y... este detalle de mis socios. Puede que lo encuentres útil... útil.", rewards = "Cinturón de polvo de oroCoselete de JaspeRecibirás:\n\nBolsa de canicasCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][48] = {title = "Dulce ámbar", objective = "Lleva agua del manantial sagrado a Tragoamargo Cebatruenos.", description = "Allá en el sur donde las zarzas irritan\nHay un manantial de aguas umbrías\nPura como la sagrada Hija de la Luz\nAgua del manantial sagrado me traerás tú.", progress = "¡Hip! ¡Jo, jo! ¿Quieres otra?\n\nAllá en el Sur donde las zarzas irritan\nHay un manantial de agua umbría\nPura como la sagrada Hija de la Luz\nAgua de manantial sagrado me traerás tú.", completion = "¡Hip! ¡Jo, jo!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][49] = {title = "Dulce ámbar", objective = "Tragoamargo Cebatruenos quiere un saco de cebada, un saco de centeno y un saco de maíz.", description = "Ámbar es el color del amor de mi vida\nComo las luces de un final del día\nRecupéralo y el amor volverá a mí\nUn saco de cebada, uno de centeno y otro de maíz.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][50] = {title = "Dulce ámbar", objective = "Tragoamargo Cebatruenos quiere veraplata.", description = "Mezclaré y mezclaré y un puré será todo\nSerá, amigo, nuestro más querido tesoro\nHaré un alambique fuerte y resistente\nDame veraplata y no daré la lata.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][51] = {title = "Dulce ámbar", objective = "Lleva una rama de sicomoro a Tragoamargo Cebatruenos.", description = "Recién destilada, aunque aún no esté filtrada\nComo tierra sin semilla esperando a ser arada\nAhora haré nuestra pila de carbón\nUna rama de sicomoro es tu próxima misión.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][52] = {title = "Proteger la frontera", objective = "Mata a 8 merodeadores o lobos grisáceos del bosque y a 5 osos del bosque jóvenes y vuelve con el guardia Thomas al puente oriental de Elwynn.", description = "Saludos, <nombre>. Los animales salvajes son más agresivos cuanto más nos alejamos de Villadorada. El Aserradero de la Vega del Este sufre constantes ataques de lobos y osos.\n\nNos vendría bien tu ayuda ahí fuera.", progress = "¿Has matado a esos lobos y a los osos?", completion = "Gracias por tu ayuda, &lt;nombre&gt;. Debe de haber algo en el bosque que está agitando a esos animales. \n\nSea lo que sea, espero que no salga de allí.", rewards = "Botas de pelaje de loboBrazal de fronteraChaqueta de piel de oso con tachuelasRecibirás:\n\nPoción de sanación inferiorCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][53] = {title = "Dulce ámbar", objective = "Lleva un montón de roble carbonizado a Tragoamargo Cebatruenos.", description = "Es un líquido meloso que se vuelve delicioso\nDulce líquido ambarino que merece mi cariño\nPero algo necesito para darle mis cuidados\nUn magnífico tonel del mejor roble carbonizado.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPetaca de Cebatruenos"}
MultiLanguageQuestData['mx'][54] = {title = "Informa en Villadorada", objective = "Llévale los documentos del alguacil McBride al alguacil Dughan en Villadorada.", description = "<nombre>, eres <un/una:c> <clase> que ciertamente ha demostrado que le preocupa la seguridad de Villanorte. Tu siguiente misión será proteger el Bosque de Elwynn.\n\nSi aceptas, te daré unos papeles para el alguacil Dughan, que está en Villadorada. Para ir a Villadorada, sigue el camino hacia el sur, pasada la frontera.", progress = "¿Traes noticias de McBride? Villanorte es un jardín comparada con el Bosque de Elwynn; me pregunto qué querrá McBride.\n\nDame los documentos.", completion = "Dice que te han nombrado ayudante del alguacil de Ventormenta. Enhorabuena.\n\nY buena suerte, el trabajo no será fácil ahora que el ejército parece que anda ocupado con la nobleza.\n\nQué misteriosa es la política en estos tiempos difíciles...", rewards = "Escudo de piqueroCalzaslargas de taberneroChaqueta pesada de VilladoradaCalzas de piqueroRecibirás:\n\nEscudo de piqueroCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][56] = {title = "La Guardia Nocturna", objective = "La comandante Althea Cerranegro de Villa Oscura quiere que mates a 8 guerreros esqueléticos y a 6 magos esqueléticos.", description = "Como Comandante de La Guardia Nocturna, es mi deber proteger a los ciudadanos de Villa Oscura. Ventormenta ha retirado a los guardias que estaban aquí destacados. Ahora tenemos que arreglárnoslas solos.\n\nSi crees estar a la altura de la tarea, nos vendría bien tu ayuda. Ayuda a La Guardia Nocturna aventurándote en el Jardín Sereno, al sur de Villa Oscura y matando a 8 guerreros esqueléticos y a 6 magos esqueléticos. ¡Hemos de acabar con la amenaza de los no-muertos!", progress = nil, completion = "Espléndido, &lt;nombre&gt;. Serás recompensado por los servicios prestados a la gente de Villa Oscura.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][57] = {title = "La Guardia Nocturna", objective = "La comandante Althea Cerranegro de Villa Oscura quiere que mates a 15 malignos esqueléticos y a 15 horrores esqueléticos.", description = "<nombre>, me están llegando informes de una infestación de no-muertos en el bosque. Si estás a la altura, viaja al Cementerio del Cerro del Cuervo y mata a 15 de esos malignos esqueléticos y a 15 horrores esqueléticos. También me han llegado noticias de la presencia de esqueletos al sur de Villa Oscura, en el Cementerio del Jardín Sereno y en sus alrededores. ¡Hemos de expulsar a los no-muertos del Bosque del Ocaso!", progress = nil, completion = "Las gentes de Villa Oscura te dan las gracias, &lt;nombre&gt;. Has demostrado ser un gran aliado de La Guardia Nocturna.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][58] = {title = "La Guardia Nocturna", objective = "La comandante Althea Cerranegro de Villa Oscura quiere que mates a 20 propagadores de peste en el mausoleo oriental de Cerro del Cuervo.", description = "La situación de Cerro del Cuervo sigue siendo desalentadora. La seguridad de Villa Oscura está en tus manos, <nombre>. Yo no tengo suficientes vigías para mantener la villa a salvo. Necesitamos que ayudes a Cerro del Cuervo una vez más y que liberes el mausoleo oriental de 20 propagadores de peste.", progress = nil, completion = "Te doy las gracias de parte de las gentes de Villa Oscura y de La Guardia Nocturna, &lt;nombre&gt;, por tu valor y dedicación. Que la Luz ilumine tu camino.", rewards = "Podrás elegir una de estas recompensas:\n\nBandolera de La Guardia NocturnaCarcaj de La Guardia NocturnaSaco de armas de La Guardia Nocturna\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][59] = {title = "Armadura de paño y cuero", objective = "Entrega a Sara Timberlain el marcador de armaduras de Ventormenta.", description = "Por tu astucia y valor, te entrego un marcador que vale por una pieza de armadura. Quiero que se lo lleves a Sara Timberlain al Aserradero de la Vega del Este. Dale el marcador y ella te forjará una armadura. Y cuando la recibas, <nombre>, úsala para defender Elwynn.\n\nLa Vega del Este está al este de este puesto, al otro lado del puente.", progress = "El ejército de Ventormenta me ha encargado que suministre a sus tropas tela y armaduras de cuero.\n\nSi tienes un marcador para mí, estaré encantada de hacerte algo.", completion = "Ah, gracias por el marcador. Por favor, elige la armadura que quieras. \n\nBuena suerte, valiente &lt;clase&gt;. Espero que esta armadura te sirva bien.", rewards = "Toga bien cosidaPantalones con remiendosProtector de brazos con tachuelasRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][60] = {title = "Las velas de los kóbolds", objective = "Lleva 8 velas grandes a William Mortero a Villadorada.", description = "Hola, <chico/chica>. ¿Tienes un momento?\n\nMi hermano y yo tenemos un herbolario en Ventormenta. Yo estoy aquí para conseguir velas grandes, por la cera, ya me entiendes. ¿Puedes ayudarme?\n\nPuedes conseguir velas grandes de los kóbolds. He oído rumores de que están infestando las minas de Elwynn... La Mina Abisal del sur y la Cantera de Jaspe del este. Puedes empezar la búsqueda en uno de esos lugares.", progress = "¿Has reunido las velas ya?", completion = "Estabas ocupado cazando algún kóbold que otro, ¿eh? Gracias por las velas, &lt;nombre&gt;, aquí tienes tu recompensa.", rewards = "Toga a rayas de cera de velaCinturón de trofeos de cazador kóboldRecibirás:\n\nPalo de cera resplandecienteCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][61] = {title = "Un envío para Ventormenta", objective = "Lleva el envío de William a Morgan Mortero al Distrito de Mercaderes de Ventormenta.", description = "Mi hermano Morgan espera mi envío de velas en Ventormenta. No tengo tiempo para hacer el viaje en persona, pero si quisieras llevarle el envío, te pagaría bien.\n\nHe empaquetado las velas. Encontrarás a Morgan en nuestra tienda, Herbolario Mortero, en el Distrito de Mercaderes de Ventormenta.", progress = "Oh, ¿un envío de mi hermano? ¡Espléndido! ¡Hoy la Fortuna me es favorable!", completion = "Ten, tu pago. Y, si quieres echar un vistazo ahora que estás aquí, ¡adelante! Seguro que tengo alguna poción o algún abalorio que te venga bien.", rewards = "Podrás elegir una de estas recompensas:\n\nAceite de OlafCohete explosivoElixir de fuerza de león\n\nTambién recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][62] = {title = "La Mina Abisal", objective = "Explora la Mina Abisal y vuelve junto al alguacil Dughan a Villadorada.", description = "¡La mina de Villanorte no es la única que tiene problemas! Según mis informes, la Mina Abisal de Elwynn también ha sido ocupada por los kóbolds.\n\nExplora la mina y comprueba la veracidad de mis informes. Luego vuelve aquí. La mina está hacia el sur de Villadorada, entre La Granja Pedregosa y la granja Maclure.", progress = nil, completion = "Son malas noticias. ¡¿Qué vendrá luego?! ¡¿Dragones?! Tendremos que reforzar las patrullas de esa mina. Gracias por tu ayuda, &lt;nombre&gt;. Espera un momento... podría tener otra misión para ti.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][63] = {title = "La llamada del agua", objective = "Derrota a la manifestación de agua corrupta y coloca los brazales de manifestación corrupta con las gotas restantes del agua más pura en el blandón de Siemprefuente en el Bosque de Argénteos.", description = "Por la costa del Bosque de Argénteos, al oeste de El Sepulcro, verás un altar infestado por la peste. Los espíritus de ese lugar ya no se comunican con nuestro pueblo y de ti depende acabar con esa manifestación de la Plaga y limpiar el estanque.\n\nLlévate los brazales de elemental y las gotas restantes de la poción de Salmuera y colócalos en el blandón. El ritual debería bastar para invocar a un espíritu puro con el que comunicarte.\n\nTráeme una prueba de haber completado la tarea y te recompensaré con un tótem.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][64] = {title = "La reliquia olvidada", objective = "El granjero Cejade quiere que recuperes el reloj de bolsillo que dejó olvidado en el guardarropa de su granja en la plantación de calabazas del Oeste.", description = "¡Fue horrible! Verna me despertó cuando oyó jaleo en los campos. Estaban llenos de gamberros. Nos fuimos corriendo y olvidé recoger mi reloj de bolsillo. Me lo dio el padre de Verna el día de nuestra boda y es horrible saber que está en manos de esos ladrones. Dejé el reloj de bolsillo en el guardarropa de la granja. Busca el campo de calabazas que está al Oeste... no tiene pérdida. ¡Si me lo devuelves te estaré muy agradecido!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPan recién horneadoLeche fría como el hielo"}
MultiLanguageQuestData['mx'][65] = {title = "La hermandad de los Defias", objective = "Gryan Mantorrecio quiere que hables con Wiley en Villa del Lago.", description = "La banda de desgraciados responsable de que las gentes de los Páramos de Poniente abandonaran sus tierras se llama a sí misma la Hermandad Defias. Necesito que te infiltres en este clan de matones. Debemos averiguar quién lidera el grupo y dónde se esconden. En Villa del Lago, en la posada, encontrarás a un pícaro que responde al nombre de Wiley; me debe un favor.\n\nViaja a Villa del Lago, en las Montañas Crestagrana, al este de Elwynn, y averigua todo lo que puedas.", progress = nil, completion = "¿Así que vienes de parte de Mantorrecio? Bien, estoy en deuda con él.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][66] = {title = "La leyenda de Stalvan", objective = "Busca al secretario Daltry en el Concejo de Villa Oscura.", description = "La otra noche, un terrible tumulto me recorrió las venas. Sentí que mi nieta Alyssa estaba en grave peligro. Consulté las cartas y vi a la Muerte contemplándome desde la mesa.\n\nBusqué la luz en un largo y oscuro trance... intentaba encontrar algo concreto que me ayudara a calmar el espíritu. Y un nombre vino a mí. Stalvan.\n\nAcude al secretario del Concejo e intenta averiguar algo más sobre ese nombre. Temo por todos nosotros.", progress = nil, completion = "Ah, así que te manda Lady Eva...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][67] = {title = "a leyenda de Stalvan", objective = "Viaja a la Escuela de Arroyo de la Luna y lleva cualquier información que descubras sobre Stalvan al secretario Daltry.", description = "Stalvan, ¿eh? Deja que consulte el registro.\n\nStalvan... Stalvan... Veamos... ¡Ah! ¡Aquí está! Tengo un señor Stalvan Mantoniebla. Según consta aquí, su última dirección es la Escuela de Arroyo de la Luna. ¡Pero este dato es de hace mucho tiempo!\n\nHazme un favor, ¿quieres? Si pasas por Arroyo de la Luna, hazme saber si consigues información más reciente sobre este tipo. Me gusta llevar los registros al día.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][69] = {title = "a leyenda de Stalvan", objective = "Ve a la Posada Orgullo de León a ver si alguien ha oído el nombre de Stalvan.", description = "¡Ay, ay! Esto se me debió de pasar la primera vez. En el registro, justo debajo de la primera dirección de Stalvan, hay otra dirección. Está tachada... Parece que se dirigía a la Posada Orgullo de León, en Villadorada. Quizás quieras comprobarlo, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][71] = {title = "Informa a Thomas", objective = "Entrega los medallones de Rolf y Malakai al guardia Thomas. Lo encontrarás en el puente oriental de Elwynn.", description = "Ahora que tienes los dos medallones, llévaselos al guardia Thomas al puente. Así sabrá que sus guardias murieron asesinados.", progress = "Hola, <nombre>. ¿Has averiguado qué suerte corrieron Rolf y Malakai?", completion = "Has confirmado mis temores, &lt;nombre&gt;. Los múrlocs son una amenaza que no podemos ignorar.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][74] = {title = "La leyenda de Stalvan", objective = "La página arrancada del diario que descubriste es tu siguiente pista.", description = "Dentro de la caja encuentras varios objetos: reliquias familiares mohosas, unos trofeos de caza, un retrato de familia y algunos libros antiguos. Al fondo, debajo de un jarrón, descubres una página arrancada de un diario.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][76] = {title = "La Cantera de Jaspe", objective = "Explora la Cantera de Jaspe y vuelve a informar al alguacil Dughan a Villadorada.", description = "Gracias a ti, ahora sabemos que la Mina Abisal está infestada de kóbolds. Ahora necesitamos un explorador que investigue la Cantera de Jaspe, que está más lejos.\n\nExplora la Cantera de Jaspe e infórmame si ves algún kóbold. Para llegar a la mina, viaja hacia el este por el camino hasta que llegues a la Torre de Azora. Cuando llegues allí, dirígete hacia el norte. Encontrarás la mina al pie de las colinas.", progress = nil, completion = "¿Dices que hay kóbolds en la Cantera de Jaspe? ¡Maldita sea! ¡La situación empeora cada minuto! \n\nGracias por el informe, &lt;nombre&gt;. Aunque habría preferido que trajeras buenas noticias, claro.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][77] = {title = "Una situación peliaguda", objective = "Recoge 10 botellas de calimocho dulce de las Tierras del Interior de las cajas de la base abandonada de la Horda en Roca Oculta.", description = "Tengo material de empaquetado original para el calimocho que quiere Dran Droffers. Te ayudaré a prepararlo para enviárselo a ese gruñón del padre de Malton... a cambio de dos botellas del mismo. Están en unas cajas en la base abandonada de la Horda cerca de Roca Oculta.\n\nSerá muy dificultoso; habrá babosas y mocos repugnantes por las ruinas. Dicen que su líder es una especie de jefe moco. Pero da igual; consigue el calimocho y vuelve aquí para empaquetarlo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][82] = {title = "Investigación en la Guarida Ponzoñosa", objective = "Llévale 5 trozos de insectos centipaar de La Guarida Ponzoñosa al alquimista Morterozugg de Gadgetzan.", description = "A ver, en cuanto a estos informes sobre los bichos... lo que sabemos es que están drenando las pozas de agua que antes estaban donde se ubica La Guarida Ponzoñosa. Lo que NO sabemos es... bueno, todo lo demás.\n\n¡Descubramos en primer lugar a quién nos enfrentamos! Quiero que vayas a La Guarida Ponzoñosa y que obtengas algunos trozos de esos bichos. Consigue 5 trozos de centipaar y llévaselos al alquimista Morterozugg para que se encargue de ellos. Con su ayuda podremos descubrir qué son.", progress = "Eres el perito adjunto <nombre>, ¿no es cierto? ¡Rápido, estamos en una situación muy delicada! ¡¿Tienes los trozos de insecto que Picoflojo dijo que tendrías?!", completion = "Buen trabajo, ¡empezaré ahora mismo con el análisis! A primera vista, puedo decirte que no se parecen a ningún tipo de insecto que haya visto antes. Parece que estos bichos están controlados por una fuerza externa o algo similar. \n\nDebes ir a hablar con Picoflojo inmediatamente. ¡Hay algo urgente para lo que necesita tu ayuda! No estoy seguro pero creo que tiene que ver con los bichos del Desierto de Tanaris.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][83] = {title = "Pañuelos de lino rojo", objective = "Lleva 6 pañuelos de lino rojo a Sara Timberlain al Aserradero de la Vega del Este.", description = "Los matones de Elwynn llevan lino, que me vendría bien para confeccionar prendas.\n\nSi me traes pañuelos de lino rojo, los usaré para hacerte algo bonito.\n\nEncontrarás a esos criminales en campamentos repartidos por todo el Bosque de Elwynn.", progress = "Me estoy quedando sin lino, <nombre>. ¿No tendrás tú algo de lino que me puedas dar?", completion = "Ah, qué pañuelos tan bonitos, aunque están un poco maltratados... \n\n¡Aquí tienes!", rewards = "Fajín de lino rojoFajín de cuero refinadoCinturón de malla roja reforzadoRecibirás:\n\nFajín de lino rojoCamisa de lino rojaCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][85] = {title = "El collar perdido", objective = "Habla con Billy Maclure.", description = "He perdido mi collar... creo que me lo robó ese granuja de Billy Maclure. Normalmente pasa el día escondido como una rata en Los Viñedos de Maclure, al este de aquí.\n\nRecupera mi collar y darás una alegría al corazón de una anciana viuda.", progress = nil, completion = "¿Que has perdido qué? Pues yo no he robado ningún collar, ¡no soy un ladrón! \n\nCreo que sé quién lo hizo, pero...&lt;sonríe&gt;tengo demasiada hambre para que me funcione la memoria.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][88] = {title = "¡Princesa debe morir!", objective = "Mata a Princesa, agarra su collera y llévasela a la vieja Pedregosa a La Granja Pedregosa.", description = "Los Brackwell tienen una cerda que ganaría cualquier concurso. Se llama Princesa. Está ENORME, ¡y es gracias a mí! ¡Porque se alimenta de mis verduras!\n\n¡Princesa debe morir antes de que llegue a nuestros campos! Tráeme su collera como prueba de que está muerta y te daré algo para recompensarte.\n\nPrincesa suele estar justo en medio de nuestro campo de sandías. ¡Ve por ella!", progress = "¿La has visto ya? ¿Te has ocupado de ella?", completion = "¡Menos mal! ¡Esa cerda se estaba poniendo tan gorda que se habría comido toda nuestra cosecha! Gracias, &lt;nombre&gt;.\n\n¿Cuál de estos objetos prefieres?", rewards = "Botas deterioradasBrazales de tachas de latónBotas de granjeroRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][90] = {title = "Kebab de lobo sazonado", objective = "Reúne 10 ijadas magras de lobo y hierbas aromáticas de Ventormenta y vuelve a Villa Oscura, a ver al Chef Grual.", description = "¡El kebab de lobo sazonado es el especial de la casa! ¡Claro que te puedo preparar un poco! Pero necesitaré algunos productos. Tráeme 10 ijadas magras de lobo y algunas hierbas aromatizadas de Ventormenta. En el bosque hay muchísimos lobos; encontrar ijadas no será un problema. Para las hierbas, busca a Felicia Gump. Tiene una floristería en el distrito de Los Canales de Ventormenta.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nKebab de lobo sazonadoReceta: kebab de lobo sazonado"}
MultiLanguageQuestData['mx'][91] = {title = "Ley de Solomon", objective = "Lleva 10 colgantes Pielsombra a Bailiff Conacher al Concejo de Villa del Lago.", description = "Se ha instalado un enemigo de Ventormenta en las laderas orientales de Crestagrana. Ese bellaco usa lo arcano para extender el terror entre nuestra gente. Se oculta bajo el nombre de Morganth.\n\nHa esclavizado al clan gnoll Pielsombra. De acuerdo con las leyes de Villa del Lago, asistir a un enemigo del Reino está penado con la muerte.\n\n¡Esos miserables gnolls deben morir!\n\nTráeme diez colgantes Pielsombra y te recompensaré.", progress = "Tráeme 10 colgantes Pielsombra y te recompensaré.", completion = "El Tribunal de Villa del Lago reconoce tu entrega a la justicia, &lt;nombre&gt;. Gracias por ayudar a mantener la ley y el orden en el Reino.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][92] = {title = "Estofado Crestagrana", objective = "El chef Breanna de Villa del Lago quiere 5 piezas de carne de cóndor dura, 5 morros de dentosangre grandes y 5 raciones de carne de araña crujiente.", description = "Me encantaría prepararte un estofado Crestagrana. Pero tengo un problemita; durante los disturbios con los orcos alimenté a toda la guarnición de Ventormenta. No me queda nada en la despensa, pero si tú me traes los ingredientes, cocinaré para ti.\n\nTráeme cinco filetes de carne de cóndor dura, cinco morros de dentosangre grandes y cinco raciones de carne de araña crujiente.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nEstofado CrestagranaReceta: estofado Crestagrana"}
MultiLanguageQuestData['mx'][93] = {title = "Los pasteles de cangrejo oscuro", objective = "Reúne 6 patas pegajosas de araña y llévaselas al Chef Grual a Villa Oscura.", description = "Te voy a contar un secreto: ¡los pasteles de \"cangrejo\" oscuro, en realidad se hacen con patas de araña! Sé que es un poco asqueroso, pero las patas de araña son muy sabrosas y los pasteles quedan estupendos. Tráeme patas pegajosas de araña y yo te preparo algunos pasteles.\n\nHe oído que las arañas de hilo venenoso son las mejores para cocinar. Están al norte, entre las laderas de las colinas y el río.", progress = "Saludos, <nombre>. ¿Has conseguido esas patas pegajosas de araña ya?", completion = "¡Tienes un bonito ramillete de patas ahí! Deja que las condimente con mis especias secretas (¡no mires!) y las saltearé en una sartén... \n\nY, aunque los pasteles de cangrejo oscuro son mi especialidad y no te daré nunca la receta, sí te daré la de un plato que es casi igual de bueno.", rewards = "Recibirás:\n\nReceta: pastel de araña pegajosa"}
MultiLanguageQuestData['mx'][94] = {title = "Un ojo vigilante", objective = "Lleva el Glifo de Azora a la Estatua Leonida, cerca de la Torre de Ilgalar, en Crestagrana.", description = "Mi rival, Morganth, es un malvado mago de gran poder que vive en la Torre de Ilgalar, en Crestagrana. He creado un dispositivo que me permitirá espiar sus movimientos: el Ojo de Azora. Ahora puedo verlo desde lejos.\n\nPero no puedo saber lo que piensa... Necesito más ayuda.\n\nSi quieres ayudarme tú, lleva mi Glifo de Azora a la Torre de Ilgalar. Colócalo sobre la Estatua Leonida, cerca de la Torre.\n\nCuando lo hayas hecho, el poder de Azora me permitirá ver los planes de Morganth para el futuro.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][95] = {title = "La venganza de Sven", objective = "Ve a la granja de Sven y averigua qué había enterrado detrás del viejo tocón.", description = "Yo antes trabajaba en una granja al sureste... hasta que un día que tuve que ausentarme, los Jinetes Oscuros del Paso de la Muerte arrasaron mi granja y asesinaron a mi familia.\n\nCuando regresé vi una figura misteriosa cerca de mi granero... enterrando algo. Huyó antes de que pudiera llegar a él y tampoco quería entretenerme: quería ir tras los Jinetes Oscuros. Así que nunca descubrí qué se escondía allí.\n\nTe agradecería que encontraras lo que enterró aquella figura misteriosa. El lugar en el que debes buscar está detrás del tocón que hay cerca de mi granero.", progress = nil, completion = "Hay un montón de tierra, apilada con prisas, como si alguien se hubiera visto obligado a esconder algo en poco tiempo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][98] = {title = "La leyenda de Stalvan", objective = "Mata a Stalvan Mantoniebla y muestra a Lady Eva su anillo familiar.", description = "Stalvan Mantoniebla llevó una vida de depravación. Su mano sesgó innumerables vidas inocentes. Es, sin duda alguna, culpable de incontables crímenes. Ahora ese lunático amenaza Villa Oscura. Solo la Luz sabe qué sórdidas acciones está planeando. Debes ejecutar a Stalvan, <clase>. Lo encontrarás en su casa, al norte de la ciudad.\n\nCuando lo hayas hecho, busca a Lady Eva y enséñale este anillo familiar. Después de todo, fue su premonición lo que nos guio a este terrible descubrimiento. Gracias a ella, Villa Oscura ahora es más segura.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Hacha curva de espíritus melancólicosPodrás elegir una de estas recompensas:\n\nAnillo de espíritus melancólicos\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][101] = {title = "El Tótem de castigo", objective = "Consigue 10 colmillos de necrófago, 10 dedos de esqueleto y 5 viales de veneno arácnido para Lady Eva en Villa Oscura.", description = "A medida que la corrupción mística invade el bosque, la necesidad de autoprotección se hace innegable, <nombre>. El viento me susurra y me cuenta de grandes peligros que el futuro te depara.\n\nSi deseas protegerte, noble <clase>, tráeme 10 colmillos de necrófago, 10 dedos de esqueleto y 5 viales de veneno arácnido. Te encantaré un tótem de castigo que dañará a aquellos que intenten causarte daño a ti.", progress = "Tráeme 10 colmillos de necrófago, 10 dedos de esqueleto y 5 viales de veneno arácnido. Así haré un encantamiento a un Tótem de castigo que dañará a aquellos que intenten causarte daño a ti.", completion = "Muy inteligente por tu parte, &lt;nombre&gt;. Este Tótem de castigo te protegerá del mal que acecha por todo Azeroth y más allá. Cuando te sientas amenazado, confórtate con el aura mágica de este tótem. Sé valiente, &lt;clase&gt;. Necesitarás todo el valor del que puedas hacer acopio, pues veo mucha sangre en tu futuro.", rewards = "Recibirás:\n\nTótem de castigo"}
MultiLanguageQuestData['mx'][102] = {title = "En patrulla por los Páramos de Poniente", objective = "Lleva 8 garras de gnoll al capitán Danuvin en la Colina del Centinela.", description = "Ventormenta nos ha abandonado. Nauseabundos aires de depravación soplan por las llanuras de los Páramos de Poniente. Este era mi hogar y no daré la espalda a los ciudadanos que decidieron permanecer aquí. Nosotros, los antiguos granjeros, ofreceremos resistencia.\n\nTu tarea, si decidieras aceptar, consistirá en patrullar las praderas de los Páramos de Poniente. Localiza y aniquila a los infames gnolls que parecen colaborar con los ladrones de Las Minas de la Muerte. Tráeme 8 garras de gnoll y sabré recompensar tu valentía.", progress = "¿Ya has reunido 8 garras de esos gnolls traidores?", completion = "Bien hecho, &lt;nombre&gt;. Contando con valientes aventureros como tú luchando del lado de La Milicia Popular, los Páramos de Poniente podrán volver a ser el próspero granero que una vez fueron. Por favor, acepta esto como reconocimiento por tus incansables esfuerzos.", rewards = "Brazales de La Milicia PopularCinturón de La Milicia PopularRecibirás:\n\n"}
MultiLanguageQuestData['mx'][103] = {title = "Guardián de la Llama", objective = "Lleva 5 botellas de aceite al capitán Grisillo en el Faro de Poniente.", description = "La noche en que murió la familia del guardián del Faro fue horrible. Contemplé, impotente, cómo el Viejo Ojosombrío lideraba el ataque. Pero lo pasado pasado está y lo que ahora me preocupa son las vidas de los que navegan por el Mare Magnum y se acercan demasiado a las peligrosas rocas de la costa. Como no hay nadie que vigile la llama, la responsabilidad es ahora mía.\n\nAyúdame a mantener la antorcha iluminada trayéndome 5 botellas de aceite de los monstruos de la cosecha.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nPoción de maná menorPoción de sanación menor\n\nTambién recibirás:\n\nPergamino de intelectoPergamino de aguante"}
MultiLanguageQuestData['mx'][104] = {title = "La amenaza costera", objective = "Lleva una escama del Viejo Ojosombrío al capitán Grisillo en el Faro de Poniente.", description = "Cuando acabó mi vida contra las rocas, no tenía ni idea de lo que me esperaba en el más allá. El Faro estaba sumido en la oscuridad aquella noche, ya que el Viejo Ojosombrío había asustado a la familia del guarda. Lograron regresar y volver a encender la llama, pero el Viejo Ojosombrío coaccionó a los múrlocs de mente más débil para que asaltaran el Faro con él de nuevo. La segunda vez, la familia no corrió la misma suerte y pereció inútilmente ante mis ojos.\n\nMata al Viejo Ojosombrío si lo ves por la costa y tráeme una de sus escamas, te recompensaré.", progress = "¿Aún no has conseguido aniquilar a la amenaza conocida como Viejo Ojosombrío? Ha sido visto recorriendo la costa de los Páramos de Poniente.\n\nVuelve a verme cuando esa bestia esté muerta.", completion = "Así que el infecto pagano Ojosombrío está muerto. Bien hecho, &lt;nombre&gt;. Tus manos han dado fin a una vida, pero han podido salvar muchas otras. El Mare Magnum, aun tan lleno de peligros como está, será algo más seguro esta noche gracias a tus hazañas.", rewards = "Rodela de los maresVarita antorchaPodrás elegir una de estas recompensas:\n\nAntorcha de Grisillo\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][105] = {title = "Ah, Andorhal", objective = "Lleva el trozo de filacteria de Araj al sumo ejecutor Derrington en El Baluarte en las Tierras de la Peste del Oeste.", description = "¡Ay, se acerca el momento de atacar Andorhal y de hacer salir al exánime que lo controla!\n\nEs en el interior de las ruinas de la ciudad donde el exánime, Araj el Invocador, tiene sus dominios. Está custodiado por numerosos miembros de la Plaga que rodean los restos del centro de la ciudad, y su séquito personal de guardianes es realmente formidable. Necesitarás muchos aliados para tener alguna oportunidad de enfrentarte a él con éxito.\n\n¡Acaba con Araj, <nombre>, y tráeme un trozo de su filacteria como prueba!", progress = "<nombre>, ya te ha sido asignada tu tarea. ¿Tienes un trozo de la filacteria del exánime como prueba de que has terminado tu tarea?", completion = "¡Lo has conseguido! ¡Araj... el exánime ha sido derrotado! \n\nEn el día de hoy has prestado un enorme favor a la Horda, &lt;nombre&gt;. Tu valentía y perseverancia son testimonio de lo que significa ser una auténtica heroína. Por favor, acepta esto como muestra para que todos vean y sepan que has dado una victoria a la Horda que nunca podrá ser olvidada.", rewards = "Recibirás:\n\nMarca de Resolución"}
MultiLanguageQuestData['mx'][106] = {title = "Jóvenes enamorados", objective = "Entrega a Tommy Joe Pedregosa la carta de amor de Maybell.", description = "¡Oh, estoy maldita! He entregado mi corazón a Tommy Joe Pedregosa, pero nuestras familias se odian a muerte. Así que no puedo verlo, ¡aunque me duelan los ojos por no poder mirar su hermoso rostro!\n\nTe lo ruego, lleva esta carta a Tommy Joe. Suele estar en el río que está al oeste de La Granja Pedregosa, al oeste de aquí.", progress = "¡¿Que tienes qué?! Maybell es la luz que ilumina mi tediosa vida. ¡Déjame ver su carta, deprisa!", completion = "¡Ah! No puedo soportar estar separado de ella. ¡¡Tengo que verla!!", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][109] = {title = "Habla con Gryan Mantorrecio", objective = "Habla con Gryan Mantorrecio. Puedes encontrarlo en la torre de piedra de la Colina del Centinela, saliendo de la carretera que cruza los Páramos de Poniente.", description = "Parece que has visto bastantes combates en tu vida, <clase>. Si no has tenido suficiente, busca a Gryan Mantorrecio. Comanda la Milicia Popular que protege las granjas de los Páramos de Poniente. Seguro que le vendrá bien tu ayuda. Puedes encontrarlo en la torre de piedra de la Colina del Centinela, saliendo de la carretera que cruza los Páramos de Poniente.", progress = nil, completion = "Así que te ha enviado aquí mi amigo, ¿eh? Qué amable por su parte. \n\nBien, te diré que la monarquía de Ventormenta nos ha abandonado. Ahora es la Milicia Popular la que mantiene la tierra a salvo de la corrupción. Si nuestra causa te interesa, puedo ofrecer a tus habilidades de combate un trabajo al servicio de la libertad.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][114] = {title = "La fuga", objective = "Lleva el licor de invisibilidad a Maybell Maclure.", description = "Lleva este licor de invisibilidad a la joven Maybell. Debería durar lo suficiente para que haga una visita a Tommy Joe.", progress = "¿Entregaste mi carta a Tommy Joe? ¿Y qué dijo?", completion = "¡Ay! Me siento muy culpable por engañar a mi familia, pero no puedo ignorar lo que siento por Tommy Joe. \n\nGracias, &lt;nombre&gt;. Beberé este licor en cuanto tenga la oportunidad de escaparme para ir a ver a mi amado. \n\nPor favor, acepta esto.", rewards = "Recibirás:\n\nPoción de sanación menorCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][115] = {title = "Magia de las Sombras", objective = "Lleva 3 orbes de medianoche al alguacil Marris a Villa del Lago.", description = "Los Roca Negra han traído taumaturgos oscuros a los ataques en Crestagrana. Tienen unos objetos de poder oscuro, los orbes de medianoche. Estos orbes han malherido a muchos de los que luchan en Crestagrana; tenemos que hacernos con esos objetos demoníacos.\n\nTráeme los orbes de medianoche de los cadáveres de taumaturgos umbríos Roca Negra. Me encargaré de destruirlos; el mundo estará mejor sin ellos.", progress = "¿Cómo va con los taumaturgos umbríos? ¿Tienes los orbes de medianoche?", completion = "Gracias, &lt;nombre&gt;. Acabaré con ellos de inmediato.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][116] = {title = "Tiempos de sequía", objective = "Lleva 1 barril de cerveza Cebatruenos, 1 barril de vino dulce, 1 botella de licor de luna y 1 botella de ron dulce al posadero Daniels a Villa del Lago.", description = "Tengo un problema, <nombre>. Nos estamos quedando sin bebida y el envío se está retrasando mucho. Esta invasión orca ha sido terrible.\n\n¿Buscas trabajo?\n\nNecesito que vayas a recoger un barril de cerveza Cebatruenos de Tragoamargo Cebatruenos, que está en las colinas de los Páramos de Poniente, uno de Merlot en Ventormenta, una botella de licor de luna en Villa Oscura y una de ron dulce en Villadorada. Tráeme todo eso y te ganarás una recompensa.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCapa tejida con cuidadoUn monedero abultado"}
MultiLanguageQuestData['mx'][117] = {title = "Cebatruenos", objective = "Entrega a Tragoamargo Cebatruenos 5 lúpulos para que pueda terminar su cerveza especial.", description = "Rápido, <amigo/amiga> y date prisa\nNuestra cerveza está de risa\nMás cerveza y menos comida,\nDadnos lúpulo para hacer birra.", progress = "Rápido, amigo y date prisa\nNuestra cerveza está de risa\nMás cerveza y menos comida,\nDadnos lúpulo para hacer birra.", completion = "Lúpulo y cebada, malta y levadura\nNi te imaginas cómo se disfruta, \nDeja de pedir, deja de gemir\n¡La cerveza Cebatruenos ya viene en su barril!", rewards = "Recibirás:\n\nBarril de cerveza Cebatruenos"}
MultiLanguageQuestData['mx'][118] = {title = "El precio de unas herraduras", objective = "Lleva la nota de Verner al herrero Argus a Villadorada, en el Bosque de Elwynn.", description = "¡He necesitado tanto hierro para abastecer a la guardia de Ventormenta que no tengo bastante para hacer herraduras!\n\nVe a Villadorada y dale esta nota al herrero Argus; le cuento mi problema y le hago un pedido de herraduras.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][119] = {title = "Regresa junto a Verner", objective = "Vuelve a Villa del Lago, en Crestagrana, y entrega la caja de herraduras a Verner Osbien.", description = "Muy bien, 50 herraduras...\n\n¡Aquí las tienes, listas para llevar! Dile a Verner que ha sido un placer y que lea la nota que he pegado a la caja.", progress = "¡Me alegro de verte! ¿Traes las herraduras?", completion = "Gracias, me hacía mucha falta. \n\nAh, hay una nota... ¿Cómo? ¡¿Argus quiere que le pague?! ¡Bah! \n\nBueno, gracias, &lt;nombre&gt;, por tu ayuda.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][120] = {title = "Mensajero a Ventormenta", objective = "El magistrado Solomon te ha dado un informe para el general Marcus Jonathan de Ventormenta. Quiere que vuelvas en cuanto lo hayas entregado.", description = "Estamos en tiempos difíciles, <clase>. Vivimos bajo un asedio constante. Si no llegan refuerzos, solo nos queda la derrota. El mensaje que te confío es de la mayor importancia. Llévaselo al general Marcus Jonathan de Ventormenta inmediatamente. Después vuelve, ya sean tus noticias buenas o malas.\n\n¡Apresúrate!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][121] = {title = "Mensajero a Ventormenta", objective = "Lleva la respuesta del general Marcus Jonathan al magistrado Solomon a Villa del Lago.", description = "Mientras espero la respuesta del Rey, llévale esta carta al magistrado Solomon.\n\nPuedes retirarte, <clase>.", progress = "¿Qué noticias envía el General? ¿Vienen refuerzos?", completion = "Gracias por todo, &lt;clase&gt;. Acepta estas monedas por tus servicios a Villa del Lago y Ventormenta. \n\nY ahora disculpa, pero esta correspondencia me intriga; está pasando algo turbio. Temo que se avecine otro conflicto.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][122] = {title = "Escamas de barriga", objective = "Lleva 6 escamas de barriga de cachorro de dragón Negro a Verner Osbien a Crestagrana.", description = "Necesito escamas de barriga de cachorro de dragón Negro para pagarle las herraduras que Argus me envió desde Villadorada. Si me traes 6 escamas, tendré para pagarle y también para hacerte un regalo.\n\nEsos bichos vuelan al sur de Villa del Lago, pero a menudo se alejan. Tendrás que estar ojo avizor para cazarlos en cuanto los veas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de cría negraBotas de cría negraRecibirás:\n\n"}
MultiLanguageQuestData['mx'][123] = {title = "El Coleccionista", objective = "Ve a ver al alguacil McCree en el Aserradero de la Vega del Este y dale la lista del coleccionista.", description = "Esta nota es una horario de los días y las horas a las que una persona –descrita como \"el Coleccionista\"– recibirá cargamentos de oro provenientes de las minas del Bosque de Elwynn.\n\nPor lo que pone en el horario, parece que el Coleccionista vive cerca de la Plantación de Calabazas de Brackwell, al este de Elwynn.\n\nParece importante. Deberías informar al alguacil McCree en el Aserradero de la Vega del Este.", progress = "¡¿Qué?! ¡Pero si nuestra gente lleva meses sin trabajar en las minas de Elwynn!\n\nDéjame ver esa nota...", completion = "Mm... He oído hablar de ese Coleccionista, pero no sé para quién trabaja. Gracias por la información. Nos ayudará a resolver este misterio.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][124] = {title = "El aullido de los gnolls", objective = "Mata a 10 toscos y 8 místicos Crestagrana y ve a ver a Verner Osbien.", description = "¡Como si no tuviera bastante con los orcos! Ahora tengo toscos y místicos gnolls en la cresta que hay al norte de mi establo y se llevan mis caballos cuando se pierden.\n\nSi nos libras de los gnolls, mis caballos y yo te lo agradeceremos eternamente.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][125] = {title = "Las herramientas perdidas", objective = "El supervisor Olento de Villa del Lago quiere que recojas su caja de herramientas del fondo del Lago Sempiterno.", description = "Échame una mano, <nombre>. Con todo esto del asedio, es difícil conseguir suministros. Mis herramientas venían de camino de Villadorada, pero hicieron explotar el puente. Pusimos las herramientas en una barca, pero los orcos atacaron con una catapulta y todo acabó en el fondo del lago.\n\nRecupera mi caja de herramientas, <nombre>, y te ganarás una buena recompensa.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nRefuerzo para armadura medio"}
MultiLanguageQuestData['mx'][126] = {title = "El aullido de las colinas", objective = "Lleva la zarpa de Ululante a Verner Osbien a Villa del Lago.", description = "<nombre>, los gnolls siguen ahí. Los oigo aullar mientras cazan en las colinas de Villa del Lago. El que más fuerte aúlla es Ululante, el jefe.\n\n¡Mátalo! ¡Su manada se asustará y huirá! Tráeme su garra como prueba.\n\nY ten cuidado; si es el jefe, será por algo. Ya sabes lo que dicen de los perros viejos.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Botas de milicia de oroPodrás elegir una de estas recompensas:\n\nAnillo de voluntad férrea\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][127] = {title = "Pescado a la venta", objective = "Lleva 10 peces luna moteados al maestro de embarcadero Baren a Villa del Lago.", description = "El Lago Sempiterno es famoso por su pez luna moteado. Tiene mucha demanda, ¡pero me estoy quedando sin existencias!\n\nTráeme 10 peces luna moteados; te pagaré bien. Y si no sabes pescar, intenta robárselo a los múrlocs.", progress = "¿Qué me traes?", completion = "¡Ha sido un placer!", rewards = "Recibirás:\n\nSopa de aleta de múrlocReceta: sopa de aleta de múrlocAceite de hígado de pescado"}
MultiLanguageQuestData['mx'][128] = {title = "La recompensa de Roca Negra", objective = "Mata a 15 campeones Roca Negra y el guardia Howe te recompensará en Villa del Lago.", description = "Tenemos que acabar con esos Roca Negra. El enemigo ha invadido nuestra tierra. Estas montañas pertenecen al rey de Ventormenta. Nuestras fuentes nos dicen que el jefe de cada unidad del clan se llama Campeón. Encontrarás su campamento hacia el norte, justo al oeste del camino a Las Estepas Ardientes.\n\nEl magistrado Solomon quiere que mueran. Acaba con 15 Campeones Roca Negra y vuelve a verme.", progress = nil, completion = "Has mostrado gran valor frente a los Roca Negra, &lt;clase&gt;. Nos has prestado un gran servicio.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][129] = {title = "Una comida gratis", objective = "Llévale su comida al guardia Parker. Está de patrulla en el camino a Villa Oscura.", description = "¿Puedes hacerme un favor? Le he preparado la comida al guardia Parker, pero ha salido de patrulla. Es un guardia de Ventormenta grande y fuerte que puede defenderse, pero para mí es demasiado peligroso.\n\n¡Si le llevas la comida, cuando vuelvas te invitaré a comer! ¿Qué me dices? Está de patrulla en el camino a Bosque del Ocaso.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][131] = {title = "Un ramo de narcisos", objective = "Dale el ramo de narcisos a Darcy.", description = "Aquí tienes el ramo. Lo he hecho de narcisos, mis flores favoritas.", progress = "Hola, <nombre>. ¿Le gustó la comida a Parker?", completion = "¡Qué bonitas! ¡Y qué bien huelen! \n\nPero son las flores favoritas de Martie. ¿No me digas que Parker te mandó a comprarle las flores a esa bruja? No le dijiste que eran para mí, ¿verdad? Porque si lo sabía, seguro que puso veneno. \n\nEn fin, no es culpa tuya. Gracias, y aquí tienes la comida.", rewards = "Recibirás:\n\nPezsol salteado"}
MultiLanguageQuestData['mx'][132] = {title = "La hermandad de los Defias", objective = "Lleva la Nota de Wiley a Gryan Mantorrecio en los Páramos de Poniente.", description = "Lo que voy a contarte puede costarme la vida. La banda Defias está preparando algo grande. Lo último que oí fue que estaban colaborando con varios gnolls, kóbolds e incluso goblins.\n\nLlévale esta nota a Mantorrecio. Explica todo lo que sé sobre este asunto.", progress = "Me alegro de verte de vuelta, <nombre>. ¿Qué tenía que decir Wiley?", completion = "¡Bah! Debería haber acabado con esa escoria cuando tuve oportunidad de hacerlo. Pero esta información es crucial. Buen trabajo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][133] = {title = "Un espantapájaros para necrófagos", objective = "Reúne 7 costillas de necrófago y llévaselas a Abercrombie a su cabaña.", description = "Vivo tan lejos de la protección de la ciudad que es un milagro que los necrófagos y los muertos andantes no me hayan devorado. ¡De hecho, ayer, sin ir más lejos, una manada de Mascahuesos intentó tirar abajo las paredes de mi casa!\n\nQuiero hacer un monigote... una especie de espantapájaros para necrófagos. Y para hacerlo necesito costillas de necrófago. Puedes conseguirlos de comecarnes, Mascahuesos, comesesos, podridos y propagadores de peste.\n\nConsígueme esas costillas y yo te pagaré.", progress = "Creo que estoy oyendo a una panda de necrófagos en la parte trasera de la casa... ¡tengo que colocar ese espantapájaros ya! ¿Me conseguiste las costillas de necrófago?", completion = "Ah, gracias. ¡Son justo lo que necesito!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][134] = {title = "Ladrones ogros", objective = "Devuelve a Abercrombie el cajón de Abercrombie.", description = "Hace unas pocas semanas, mientras recogía hierbas lejos de mi casa, me atacó una manada de ogros. Huí a toda prisa y tuve que dejar atrás un cajón lleno de valiosas herramientas y hierbas.\n\nLos ogros volvieron a su túmulo del sur del Bosque del Ocaso pavoneándose de su hazaña. Tengo la seguridad de que mi cajón está cerca de ese túmulo.\n\nPor favor, <nombre>, recupera ese cajón, lo necesito.", progress = "¿Tienes mi cajón? Si lo tienes, ¡dámelo! ¡Rápido!", completion = "Gracias al Nec... no, no, ¡gracias a TI, &lt;nombre&gt;! Te has ganado tu recompensa. \n\n¡Aah! ¡Qué felicidad! ¡¡Qué noches me esperan!!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][135] = {title = "La hermandad de los Defias", objective = "Lleva la Nota de Wiley a Mathias Shaw de Ventormenta.", description = "Me pregunto qué querría decir Wiley cuando habló de los Albañiles. Quizás fue un lapsus. ¿Podría estar relacionada la banda Defias con los Albañiles? El único que podría saberlo es Mathias Shaw, líder del IV:7. Enséñale la nota de Wiley, tal vez tenga algo que añadir a este misterio. Si tienes problemas para encontrarlo, busca en el Cuartel, en el Casco Antiguo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][136] = {title = "El tesoro escondido del capitán Sanders", objective = "Encuentra el baúl del capitán Sanders y busca la siguiente pista.", description = "Si estás leyendo esto, el capitán Sanders estará sepultado bajo el agua. Así que mi tesoro es tuyo, solo tienes que seguir las pistas.\n\nPrimero tienes que encontrar mi baúl. Seguramente estará enterrado en la arena, en la costa Oeste de los Páramos de Poniente, cerca de los restos de naufragios. Habrá muchos restos, pero solo un ancla oxidada en la costa. ¡Encuentra el ancla y encontrarás mi baúl! Allí encontrarás también la siguiente pista.", progress = nil, completion = "El baúl se abre lentamente. Solo parece estar lleno de agua y arena. ¡Pero espera! ¡Está saliendo un pequeño cangrejo con una pista del tesoro entre las pinzas!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][138] = {title = "El tesoro escondido del capitán Sanders", objective = "Busca el viejo barril junto a la chimenea en ruinas y busca la siguiente pista.\n\nObjeto provisto: \n", description = "Esto es lo que dice la siguiente pista: ¡Buen trabajo, compañero! Ahora tienes que ir al Este. Al Este hacia los riscos, al Este hacia el camino. Busca las ruinas de chimeneas a orillas del camino. Allí encontrarás un viejo barril con la siguiente pista.", progress = nil, completion = "¡Buen trabajo, cazatesoros!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][139] = {title = "El tesoro escondido del capitán Sanders", objective = "Busca la jarra vacía junto al molino de viento para encontrar la siguiente pista.\n\nObjeto provisto: \n", description = "Buscando en el barril descubres otro fragmento de papiro. En este se puede leer: Desde este barril, ve hacia el Norte. Tan recto como vuela el cuervo, anda hasta que veas una jarra vacía junto al solitario molino de viento sobre los riscos del mar. Si buscas alrededor de la jarra encontrarás lo que estás buscando.", progress = nil, completion = "¡Te estás acercando al premio gordo, buscatesoros!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][140] = {title = "El tesoro escondido del capitán Sanders", objective = "Localiza la arqueta del capitán Sanders y ábrela para obtener tu recompensa.\n\nObjeto provisto: \n", description = "Ciertamente, dentro de la vieja jarra hay otra pista sobre el tesoro de Sanders. La tinta se ha borrado en algunas partes y el papel huele a whisky, pero aún puedes entender algo: Ahora que has encontrado mi vieja jarra de whisky ¡casi has llegado al tesoro! Dirígete hacia el Oeste desde la botella y baja hasta la costa. Cuando llegues al agua, ¡sigue adelante! ¡Nada directo hacia el Oeste hasta encontrar la isla con la arqueta!", progress = nil, completion = "Las bisagras del viejo cofre están oxidadas, pero todavía funcionan. Fuerzas el cofre, lo abres y coges el botín. \n\n¡Felicidades!", rewards = "Recibirás:\n\nBarra de plataCamisa del capitán SandersFajín del capitán SandersBolsa de botín del capitán Sanders"}
MultiLanguageQuestData['mx'][141] = {title = "La hermandad de los Defias", objective = "Lleva el informe de Shaw a Gryan Mantorrecio de los Páramos de Poniente.", description = "La Hermandad de los Albañiles estaba dirigida por un tal Edwin VanCleef. VanCleef fue responsable de la reconstrucción de Ventormenta cuando la ciudad fue arrasada por los orcos en la Primera Guerra. Al parecer, VanCleef y sus hombres no estaban satisfechos con el tratamiento que les brindó el rey cuando terminó la reconstrucción. Pero eso solo explicaría algunas cosas.\n\nHe redactado un informe más detallado para tu maestro en los Páramos de Poniente. ¡Llévaselo de una vez!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][142] = {title = "La hermandad de los Defias", objective = "Localiza al mensajero Defias de los Páramos de Poniente y lleva su mensaje a Mantorrecio.", description = "Tenemos que descubrir la localización de la Ladronera Defias. <nombre>, según los informes de mi explorador se ha visto a un mensajero Defias en los caminos entre el Arroyo de la Luna, la Mina de la Costa del Oro y la Mina de Jango. Quiero que le captures. Si ofrece resistencia, mátalo y tráeme lo que esté llevando.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][143] = {title = "Mensajero a los Páramos de Poniente", objective = "El magistrado Solomon quiere que lleves su petición a Gryan Mantorrecio a los Páramos de Poniente.", description = "En el ejército de Ventormenta pasa algo raro; ya deberían haber llegado. No tenemos tiempo que perder. No voy a quedarme a mirar cómo se sacrifica la gente de Villa del Lago sin intentar conseguir ayuda. He oído que en los Páramos de Poniente se ha formado una Milicia Popular.\n\nLleva nuestra súplica a su jefe, Gryan Mantorrecio; puede que sus hombres nos ayuden hasta que llegue la Reserva.", progress = "Saludos, <clase>. ¿Qué te trae a hablar con la Milicia Popular?", completion = "Has servido bien a tu maestro.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][144] = {title = "Mensajero a los Páramos de Poniente", objective = "Lleva la respuesta de Gryan Mantorrecio al magistrado Solomon.", description = "Me duele leer la nota del magistrado Solomon. Evidentemente, no sabe que hay guerra en los Páramos de Poniente, si no, no pediría ayuda a la Milicia. Si Ventormenta no nos hubiera abandonado también a nosotros, no necesitaríamos una milicia.\n\nLlévale la respuesta a tu señor en Crestagrana, <clase>. Dile que lamento la pérdida de tantos hombres buenos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][145] = {title = "Mensajero a Villa Oscura", objective = "El magistrado Solomon quiere que lleves una carta a Lord Cerranegro a Villa Oscura.", description = "Necesito tu ayuda una vez más. He escrito a Lord Cerranegro para pedir que mande a su Guardia Nocturna como refuerzo de la defensa de Villa del Lago. Es imprescindible que reciba este mensaje cuanto antes, pero debes ser extremadamente prudente. Cerranegro es el alcalde de Villa Oscura, en pleno corazón del Bosque del Ocaso. No te salgas de los caminos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][146] = {title = "Mensajero a Villa Oscura", objective = "Lleva la respuesta de Lord Cerranegro al magistrado Solomon.", description = "Si no conociera a Solomon, diría que se ha vuelto loco. ¿Que envíe a La Guardia Nocturna a Villa del Lago porque Ventormenta no envía ayuda? La Guardia Nocturna se creó porque Ventormenta nos abandonó cuando nos infestó esta magia inmunda. Si envío a la Guardia, esta ciudad sería invadida antes de que mis guardias lleguen al Linde del Bosque.\n\nLlévale la respuesta a tu señor en Villa del Lago.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][147] = {title = "La persecución", objective = "Encuentra y mata al Coleccionista y vuelve junto al alguacil McCree con la sortija del coleccionista.", description = "Si el Coleccionista se está llevando oro de nuestras minas, ¡está robando al Rey! Lleva al Coleccionista ante la justicia. Y tráeme a mí el anillo que se mencionaba en la nota. Podría indicarnos para quién trabaja el Coleccionista...\n\nLa nota dice que el Coleccionista se esconde en la Plantación de Calabazas de Brackwell. Deberías buscarlo allí.\"", progress = "¿Has encontrado al Coleccionista? ¿Has averiguado para quién trabaja?", completion = "¿Lo has encontrado? Bien hecho, &lt;nombre&gt;. ¡Ya no volverá a \"coleccionar\"! \n\nY... este anillo que encontraste es muy interesante. Es un anillo de la antigua Hermandad de albañiles de Ventormenta. Hace años que no veo uno como este, desde aquellos días en que la Hermandad Defias solía infestar estas tierras.", rewards = "Guardamuñecas elásticosGuantes de anillas de VentormentaGuantes de boxeo de McCreeRecibirás:\n\nBolsa de\"recolección\"Currency Token Test Token 4"}
MultiLanguageQuestData['mx'][148] = {title = "Suministros de Villa Oscura", objective = "Habla con Lady Eva.", description = "Ay, ¿qué puede hacer un anciano como yo? Necesito suministros de Villa Oscura, pero está tan lejos y yo soy tan viejo y tan débil... No sobreviviría al viaje.\n\n¿Podrías ir a Villa Oscura y traerme un poco de hilo de cabello de fantasma? Puedes conseguirlo de Lady Eva. Ve a su casa en la plaza de Villa Oscura.", progress = nil, completion = "Ah, necesitas hilo de cabello de fantasma, ¿no es así? Pues me temo que no tengo ninguno en el almacén, pero puedo hacértelo, si tú me proporcionas el pelo de fantasma.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][149] = {title = "Hilo de cabello de fantasma", objective = "Lleva el peine espectral a Mary la Ciega.", description = "Mary la Ciega es un desgraciado y triste espíritu que mora en una vieja granja en las colinas del sur de Villa Oscura.\n\nTen, coge este peine espectral y pide a Mary la Ciega que se peine el cabello. Luego tráeme el peine y yo extraeré de él el cabello de fantasma que necesito para crear el hilo.\n\nY ten cuidado... cerca de la casa acechan seres oscuros...", progress = "<Snif> Oh, por favor, ¡no me mires! ¡Arranqué estos ojos con mis propias manos, pero puedo sentir tu mirada fija en mí!\n\n¡Soy un monstruo! ¡Un monstruo horrible! ¡¡Por favor, no me mires!!", completion = "¿Qué es eso? ¿Un peine? ¡Es precioso! Y se desliza como seda por mi cabello, como si no fuera el alambroso y grasiento horror que es. \n\nAy, si tan solo tuviera un espejo...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][150] = {title = "Cazadores furtivos", objective = "Lleva 8 aletas múrloc al maestro de embarcadero Baren a Villa del Lago.", description = "Los múrlocs nos están complicando la vida. Se están instalando en las orillas del Lago Sempiterno y pescan en cantidades increíbles. ¡Tenemos que echarlos o acabarán con todos los peces del lago!\n\n¿Te apetece cazar múrlocs? Tráeme 8 aletas y te llevarás algo a cambio...", progress = "¿Tienes las aletas? ¡Tenemos que echar a los múrlocs del lago!", completion = "Buen trabajo, &lt;nombre&gt;. \n\nEs raro que estén tan lejos del mar; puede que estuvieran huyendo de algo...", rewards = "Recibirás:\n\nCaña de pescar enana"}
MultiLanguageQuestData['mx'][151] = {title = "La pobre y vieja Blanchy", objective = "Verna Cejade de los Páramos de Poniente quiere que le lleves 8 puñados de avena.", description = "¡Pobre vieja Blanchy! La bestia está agotada después de todo el trabajo que le dimos. Le di de comer antes de dejar la granja, pero no esperábamos que se rompiera el carro. Si pudieras traerle algunos puñados de avena te estaría muy agradecida.\n\nSeguro que podrás encontrar algunos por las granjas de los Páramos de Poniente, si puedes librarte de esas horribles máquinas que los han invadido. Hay varias granjas al suroeste de aquí.", progress = "La vieja Blanchy está en las últimas. ¿Has podido encontrar algo de avena?", completion = "¡Muchísimas gracias, &lt;nombre&gt;! ¡La pobre vieja Blanchy se pondrá tan contenta!", rewards = "Recibirás:\n\nManta de la vieja BlanchyFaltriquera de la vieja Blanchy"}
MultiLanguageQuestData['mx'][152] = {title = "Hay moros en la costa", objective = "Mata 7 cazamareas, 7 guerreros, 7 oráculos y 7 correcostas y vuelve con el capitán Grisillo en el Faro de Poniente.", description = "Seguramente habrás visto todos los restos de naufragios a lo largo de la costa. El Mare Magnum es traicionero. La costa de los Páramos de Poniente tiene que estar limpia, de ese modo si algún marinero llega hasta nuestras costas, no correrá ningún peligro. Pero los múrlocs son un gran problema.\n\nMata 7 cazamareas, 7 guerreros, 7 oráculos y 7 correcostas y procuraré que seas <recompensado/recompensada>.", progress = nil, completion = "Bien hecho, &lt;nombre&gt;. Tienes talento para el combate. Gracias a ti, la Costa de los Páramos de Poniente es un lugar más seguro.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][153] = {title = "Pañuelos rojos de cuero", objective = "Lleva 15 pañuelos de cuero rojo al explorador Galiaan en la Colina del Centinela.", description = "La tapadera de los Defias cambia constantemente. He estado siguiendo sus movimientos desde hace algún tiempo. Aunque, recuerda, he averiguado que muchos miembros de la banda se identifican por sus pañuelos de cuero rojo.\n\nTráeme 15 de esos pañuelos y procuraré que seas <recompensado/recompensada>.", progress = "Tráeme 15 pañuelos de cuero rojo y te pagaré bien.", completion = "Buen trabajo, &lt;raza&gt;. Por favor, acepta uno de estos objetos como pago por tu trabajo.", rewards = "Capa de La Milicia PopularGrebas de La Milicia PopularLeotardos de La Milicia PopularRecibirás:\n\n"}
MultiLanguageQuestData['mx'][155] = {title = "La hermandad de los Defias", objective = "Escolta al Traidor de los Defias a la ladronera secreta de la Hermandad Defias. Cuando el Traidor de los Defias te enseñe dónde se esconden VanCleef y sus hombres, regresa con Gryan Mantorrecio con toda la información.", description = "¿Así que Mantorrecio envía a <un/una> <raza> enclenque para protegerme? Supongo que tendrás que hacerlo. Pero será mejor que traigas algunos amigos.\n\n¿Ya conoces el trato, verdad? Tú me guardas las espaldas y yo te llevo hasta la Ladronera Defias. La banda Defias busca mi cabeza, así que si me ven contigo, intentarán matarme.\n\nAvísame cuando tú y los amigos que puedas reunir estén listos para emprender la marcha.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][157] = {title = "Devolver el pelo", objective = "Lleva el hilo de cabello de fantasma a Abercrombie, a su choza al norte del Cementerio del Cerro del Cuervo.", description = "Aquí tienes tu hilo, <nombre>. Entre muchas otras cosas, sirve para atar espíritus malvados o para coser la vida en objetos inanimados.", progress = "Necesito colocar el hilo de cabello de fantasma en mis puertas y ventanas para mantener alejados a espíritus indeseables. ¿Me lo conseguiste?", completion = "¡Delicioso! Esto funcionará de maravilla. \n\nTen, &lt;nombre&gt;, acepta esto como pago por tu honorable acción.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][162] = {title = "La sublevación de los silítidos", objective = "Dirígete a Darnassus y entrégale el informe del análisis del insecto a Gracina Poderespíritu.", description = "Te ruego que le entregues este informe a alguien que tenga conocimientos de este tema.\n\nConozco a una erudita elfa de la noche llamada Gracina Poderespíritu que ha dedicado mucho tiempo al estudio de los seres vivos que solo se encuentran en Azeroth. ¡Es una historiadora de los pies a la cabeza! Entrégale este informe si quieres que te ayude a entender a qué te enfrentas y, lo más importante, el modo de detener esta amenaza. Necesitaremos ayuda.\n\nLo último que he sabido de ella es que residía en el Templo de la Luna, ubicado en Darnassus.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][163] = {title = "Cerro del Cuervo", objective = "Averigua qué está acechando Cerro del Cuervo.", description = "Algo ocurre en Cerro del Cuervo, <nombre>. Calor jura que alguien -o algo- está rondando los edificios de la zona. Ha visto sombras moviéndose dos noches seguidas y dice que hace tres noches vio luz en una de las ventanas.\n\nSi, como dices, te preocupa la seguridad del Bosque del Ocaso, averigua qué monstruo acecha el Cerro del Cuervo.", progress = nil, completion = "¡No! ¡Por favor, no me mates! Soy solo yo... ¡¡Alterio!! Están por todas partes... ¡No puedo escapar! ¿Monstruos en Cerro del Cuervo? No, no, no... no puede haber ninguno. Aquí solo está Alterio, el inocente Alterio.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][164] = {title = "Entrega a Sven", objective = "Entrega los suministros a Sven.", description = "¿Conoces a Sven? ¡Pues él sí que trabaja para la Luz! Él y sus seguidores están acampados en la linde noroccidental del Bosque del Ocaso.\n\nPor desgracia, son muy pocos, y no pueden permitirse enviar a nadie a buscar suministros a la ciudad. ¿No podrías llevarles tú estos suministros?", progress = "Tienes pinta de ser fuerte, <clase>. ¿Has venido a unirte a nuestra lucha?", completion = "Estos suministros serán muy útiles. La ayuda de la familia Carevin es siempre bienvenida. Aquí tienes un algo por tus molestias.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][165] = {title = "El ermitaño", objective = "Ve a ver cómo está el anciano de la choza que hay cerca del Cementerio del Cerro del Cuervo.", description = "Antes venía por aquí un anciano... venía a comprar suministros con bastante frecuencia, pero hace un tiempo que no lo veo. Vive en una choza cerca del Cementerio del Cerro del Cuervo, si no recuerdo mal. ¿Podrías ir a ver si le ha ocurrido algo?", progress = nil, completion = "¿Elaine Carevin? Je, je, sí, claro... los Carevin. \n\nNo, no pasa nada. Es que ya no puedo ir a la villa, el viaje es demasiado para mí. Los caminos son peligrosos y cada día estoy más viejo. ¿Podrías hacer algunos favores a un pobre viejo?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][166] = {title = "La hermandad de los Defias", objective = "Mata a Edwin VanCleef y lleva su cabeza a Gryan Mantorrecio.", description = "Todavía hay una tarea que debes cumplir. Edwin VanCleef debe ser asesinado. Aunque me entristece condenar a alguien a la pena de muerte, el bien común de las gentes de los Páramos de Poniente exige que VanCleef descanse de una vez por todas. Tráeme la cabeza de ese villano cuando hayas terminado tu hazaña.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guerrera de los Páramos de PonienteBastón de los Páramos de PonienteBotarga de los Páramos de PonienteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][167] = {title = "Oh, hermano...", objective = "Lleva la insignia de la Liga de Expedicionarios del supervisor Cardortiga a Wilder Cardortiga, en Ventormenta.", description = "Estábamos en las profundidades de una gran mina en los Páramos de Poniente, oculta tras un granero en el Arroyo de la Luna. No tenemos ni idea de dónde salieron esos ladrones. En fin, el túnel se derrumbó sobre nosotros. Conseguí salir, pero los otros... bueno... de los otros no sé nada.\n\nCreo que tú podrías tener más suerte ahí abajo. Si pudieras buscar a mi hermano, te lo agradecería mucho. Siempre llevaba su insignia de la Liga de Expedicionarios. Si no puedes encontrarle, al menos la insignia me daría algo de paz mental.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nRevancha de minero"}
MultiLanguageQuestData['mx'][168] = {title = "Recolección de recuerdos", objective = "Recupera 4 Tarjetas del Sindicato Minero y llévaselas a Wilder Cardortiga, en Ventormenta.", description = "Muchos de mis amigos murieron ese horrible día cuando se derrumbó el túnel de la mina. Si tus aventuras te llevan de casualidad a esa parte de la mina en el Arroyo de la Luna, por favor, busca alguna señal que pueda identificarles. Si te encuentras con alguna de sus Tarjetas del Sindicato Minero, tráemelas y me aseguraré de que sus familias reciban la resolución de este horrible accidente.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de minería polvorientosBotas de tuneladorRecibirás:\n\n"}
MultiLanguageQuestData['mx'][169] = {title = "Se busca: Gath'Ilzogg", objective = "Mata a Gath'Ilzogg y lleva su cabeza al magistrado Solomon a Villa del Lago para recibir tu recompensa.", description = "Se busca a Gath'Ilzogg por dirigir los ataques Roca Negra al Fuerte de Petravista y las incursiones en Villa del Lago.\n\nGath'Ilzogg es extremadamente peligroso. Se encuentra en el Fuerte maquinando nuevos crímenes del clan contra la humanidad. Debemos sofocar la infestación de orcos cueste lo que cueste. Se ofrece recompensa a quien presente la cabeza de Gath'Ilzogg al magistrado Solomon.", progress = "¿Qué tienes ahí, <raza>?", completion = "¡Buen trabajo, &lt;nombre&gt;! Gath'Ilzogg es responsable de la muerte de muchos humanos. Nos hemos vengado. ¡Estamos un paso más cerca de reconquistar el castillo!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][172] = {title = "Semana de los Niños", objective = "Usa el silbato de huérfano orco para hablar con el niño al que cuidarás durante la Semana de los Niños.\n\nObjeto provisto: \n", description = "¿Quieres ayudarnos aquí en el orfanato? $GBendito:Bendita; seas, <amigo/amiga>. Tu ayuda durante la Semana de los Niños no tiene precio.\n\nCoge este silbato. Solo podrás utilizarlo durante un breve período de tiempo, básicamente, hasta que se acabe la Semana de los Niños. Cuando lo uses, podrás hablar con el niño que esté a tu cuidado. Utilízalo de nuevo para que el niño se vaya.\n\nSea como sea, <nombre>, utiliza el silbato y conoce a tu pupilo. Seguro que el niño estará encantado de conocerte.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][173] = {title = "Huargen en el bosque", objective = "Mata a 6 huargen Tejesombras Penumbría para Calor de Villa Oscura.", description = "La oscuridad se siente inexorablemente atraída hacia el Bosque del Ocaso. El maestro Carevin lucha por erradicar el mal y la herejía. Y con nuestros esfuerzos mantenemos a salvo a las gentes de Villa Oscura.\n\n¿Te crees <merecedor/merecedora> de unirte a nosotros?\n\nHace tiempo pensaba como tú. La complacencia de la Guardia me decepcionó y acabé uniéndome al maestro Carevin. Si quieres probar tu valía, no utilices las palabras.\n\nMide tus habilidades con un huargen delirante tejesombras Penumbría en la Arboleda del Destello y en El Vergel Pútrido.", progress = nil, completion = "Impresionante, &lt;nombre&gt;. Parece que sabes desenvolverte solo. Quizás podamos encontrar un desafío más adecuado para una de tus habilidades. \n\nPero es curioso... los huargen aparecieron como de la nada. En fin, con todas las extrañas criaturas que han cruzado nuestras fronteras, supongo que esa es solo una más de mis preocupaciones.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][174] = {title = "ira las estrellas", objective = "Viktori Prism'Antras de Villa Oscura quiere que le lleves un tubo de bronce.", description = "Cog, mi amigo gnomo, me ha prometido ayuda para crear un instrumento que me servirá para ver las estrellas. Más allá de la magia hay una verdad que puede explicar las extrañas transformaciones del bosque.\n\nTráeme un tubo de bronce creado por un ingeniero cualificado. Ese es el primer paso según el manual de Cog.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][176] = {title = "SE BUSCA: \"Hogger\"", objective = "Encárgate de \"la situación Hogger\" y vuelve a ver al alguacil Dughan.", description = "Se busca: Hogger.\n\nUn gnoll enorme, Hogger, está al acecho en el bosque al suroeste de Elwynn. Ha sofocado todos los intentos de capturarlo.\n\nEl ejército de Ventormenta ofrece una generosa recompensa por atrapar al gnoll. Para ganarla, los cazarrecompensas tendrán que adentrarse en el bosque y eliminar a la bestia.", progress = "Sí, Hogger ha sido un auténtico estorbo para mí y para mis hombres. ¿Tienes algo de que informar sobre la bestia?", completion = "¡Jaja! ¡Bien hecho! ¡Empezaba a pensar que nadie podía matar a ese monstruo!\n\nAquí tienes, &lt;nombre&gt;. Y gracias, ¡ese gnoll me traía dolores de cabeza del tamaño de la Cumbre de Roca Negra!", rewards = "Leotardos de guardia de VentormentaGuerrera de lacayoBastón de hechizos equilibradoRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][177] = {title = "ira las estrellas", objective = "Quita el espejo de Mary la Ciega al necrófago demente y llévaselo a Viktori a Villa Oscura.", description = "El espejo era uno de mis tesoros más preciados hasta... el incidente. Después de lo que ocurrió, lo escondí detrás del granero. Antes venía por aquí un necrófago demente... Quizás lo cogió él. Se dice que esa bestia inmunda vive en el Cementerio del Jardín Sereno.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][178] = {title = "Theocritus recupera el colgante", objective = "Lleva el colgante Pielsombra descolorido a Theocritus el Mago a la Torre de Azora, en el Bosque de Elwynn.", description = "<Oyes una voz...>\n\nNo te asustes; soy Theocritus, Mago Supremo de la Torre de Azora, en el Bosque de Elwynn. El colgante es un medio de comunicación entre los gnolls Pielsombra y su señor, Morganth.\n\nHe investigado durante meses y creo que yo también puedo usar los colgantes. Si oyes este mensaje, mi hechizo ha funcionado.\n\nTráeme el colgante y te recompensaré.", progress = "¿Que te hablé mediante un colgante? Mmm, dámelo, quiero estudiarlo.", completion = "Gracias, &lt;nombre&gt;. Hace semanas que envié el mensaje a los colgantes Pielsombra, creí que no se había transmitido. Pero parece que el hechizo llegó a algunos colgantes, aunque tarde. \n\nEspero aprender a enviar ataques para inmovilizar a los gnolls que los lleven puestos. \n\nPero me queda mucha investigación por delante para llegar a eso.", rewards = "Recibirás:\n\nBálsamo restablecedor"}
MultiLanguageQuestData['mx'][179] = {title = "Los enanos modistos", objective = "Sten Brazorrecio quiere 8 piezas de carne de lobo dura.", description = "¿Qué tenemos aquí? Tienes pinta de necesitar algo para mantener las manos calientes, ¿mm?\n\nYo te diré lo que necesitas: un par de estupendos guantes bien calentitos. Y, como soy un alma generosa, me encantaría proporcionarte ese par de guantes. Pero con una condición.\n\nNecesito que me consigas carne de lobo. Es un buen trato, ¿mm? Tú me traes un poco de carne de lobo y yo evito que pierdas los dedos por congelación. ¿Y bien? ¿Qué dices?", progress = "¿Qué? ¿Los lobos te están dando problemillas? Ya sabes que tienes que evitar colmillos y patas y otras cosas afiladas, ¿verdad?", completion = "¡Ah! Estupendo. Esta carne de lobo me vendrá muy bien. Oh, no te preocupes, &lt;nombre&gt;, no he olvidado mi parte del trato. Ten, alguno de estos debería valerte.", rewards = "Guantes de cuidador de conejosGuantes de cuidador de jabalíesGuantes de cuidador de lobosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][180] = {title = "Se busca: Teniente Fangore", objective = "Mata al teniente Fangore y lleva su zarpa al magistrado Solomon a Villa del Lago.", description = "Se busca al teniente Fangore\n\nSe acusa al jefe del clan gnoll Pielsombra de colaborar con el enemigo del Reino Morganth. El magistrado Solomon ha decretado la pena de muerte para este traidor a Ventormenta. Su zarpa se considerará prueba de su muerte.", progress = "¿Qué nuevas nos traes?", completion = "¿Así que el malvado Fangore ha muerto? Pues buen viaje. Admiro tu valor, &lt;clase&gt;. Tienes la gratitud de Villa del Lago.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][181] = {title = "ira las estrellas", objective = "Localiza a Zzarc'Vul en el montículo meridional del Bosque del Ocaso y llévale su monóculo a Viktori a Villa Oscura.", description = "Necesito un objeto más para completar el instrumento. Según el manual de Cog necesito una lente de algún tipo. La única lente que conozco, aunque sería lo suficientemente grande, es difícil de conseguir.\n\nSé de un ogro que tiene un monóculo... se llama Zzarc'Vul y vive en el montículo que hay al sur del Bosque del Ocaso. Si puedes, tráeme su monóculo y lo usaremos como lente.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes del zodíacoCinturón de las EstrellasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][182] = {title = "La cueva de los trols", objective = "Grelin Barbablanca quiere que mates a 10 crías de trol Peloescarcha.", description = "A mi hermano Senir y a mí nos enviaron a distintas partes de Dun Morogh a investigar la amenaza que representan los trols. El Senado ya tiene bastante con los troggs y no tiene tiempo para más inconvenientes.\n\nPor lo que he visto, los trols no están bien ubicados aquí en Valle de Crestanevada, principalmente se encuentran en la cueva al sur. Diría que el ejército no será necesario. Un par de brazos fuertes deberían bastar.\n\n¿Te interesaría colaborar en esta tarea? Tengo autoridad como para ofrecerte una compensación por tu ayuda.", progress = nil, completion = "¡Argh! ¡Malditos trols, la Luz los maldiga!\n\n&lt;Grelin respira profundamente y se calma... un poco.&gt;\n\n¡Un grupo de ellos vino por la noche y se llevó mi diario! Sabía que no debía confiar en ese bueno para nada de...", rewards = "Hacha de mano YunquemarCuchillo YunquemarAlmádena YunquemarMosquete YunquemarRecibirás:\n\nHierba de sanación"}
MultiLanguageQuestData['mx'][183] = {title = "Cazador de jabalíes", objective = "Talin Ojo Ávido quiere que mates a 12 jabalíes del risco pequeños.", description = "No hay nada como pasar un día cazando jabalíes, ¿eh?\n\nAunque con la de jabalíes que tenemos en el Valle de Crestanevada, la cosa pierde un poco de gracia. Ni siquiera hay que provocarlos. Ya están todos enfadados e inquietos, no necesitan ayuda para eso. De hecho, últimamente hay tantos jabalíes en la zona que mi caza diaria se está convirtiendo en una actividad peligrosa.\n\nPara abreviar, si pudieras ayudarme a matar algunos jabalíes, te lo agradecería mucho.", progress = nil, completion = "¡Fantástico! Ya puedo volver a mi caza diaria tranquilamente. Gracias, &lt;nombre&gt;.", rewards = "Pantalones de cuero enanoCalzones de paño enanoBrazal de hierro enanoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][184] = {title = "Las escrituras de Cejade", objective = "Lleva las escrituras de Cejade a la Finca de Jansen en Páramos de Poniente.", description = "Estas son las viejas escrituras de una extensión de tierras de labranza de los Páramos de Poniente. Están firmadas por un tal Theodore Cejade y por su mujer, Verna. En el reverso de las escrituras hay unas palabras garabateadas con gran prisa:\n\n\"Presionamos a Cejade y conseguimos sus escrituras. Pensé que te vendría bien si querías falsificar una para ti.\n\nLos Cejade no nos darán problemas. La última vez que los vi estaban saliendo de los Páramos de Poniente con un carro roto.\"\n\nCrees que probablemente los Cejade querrán recuperar sus escrituras...", progress = "¿Tienes las escrituras de mi granja? ¡Excelentes noticias! Unos rufianes las robaron hace unos días... ¡Creí que las había perdido para siempre!\n\nDámelas, por favor. Estamos a punto de marcharnos de Páramos de Poniente y no volveremos pronto, pero si regresamos necesitaremos esos papeles...", completion = "¡Muchísimas gracias, &lt;nombre&gt;! Como te decía, estos lugares ya no son adecuados para personas honestas, pero si las cosas mejoran, con estas escrituras podremos reclamar nuestras tierras.\n\nNo tengo mucho para ofrecerte, pero toma, acepta esto.", rewards = "Recibirás:\n\nCalabaza pequeñaSandía maduraCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][185] = {title = "Caza al tigre", objective = "Caza 10 tigres jóvenes de Tuercespina.", description = "Cuando era una niña, mi padre me enseñó a cazar tigres.\n\nVerás que los felinos jóvenes son mucho más fáciles de seguir y cazar. Es fácil encontrar tigres jóvenes cerca del campamento de expedición.\n\nPon a prueba tus habilidades de rastreo y veamos si puedes dar caza a alguna de las bestias. Comienza la caza cerca de nuestro campamento, al sur.", progress = nil, completion = "Bien hecho, &lt;nombre&gt;. Estás listo para continuar.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][186] = {title = "Persigue al tigre", objective = "Caza 10 tigres de Tuercespina.", description = "Los tigres jóvenes son una cosa y los felinos adultos otra. Cazar tigres de Tuercespina adultos es un reto aún mayor.\n\nLos felinos adultos suelen pasar el día al sur de la Base de Kurzen, al este del río.", progress = nil, completion = "Estoy impresionado, &lt;clase&gt;. Estás teniendo un buen progreso.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][187] = {title = "Somete al tigre", objective = "Caza 5 tigres de Tuercespina mayores.", description = "Los tigres de Tuercespina mayores son los más fuertes de la manada. Más de <un/una> <raza> <clase> ha caído frente a esos dientes afilados como cuchillas y esas feroces garras.\n\nAjeck se entusiasmará cuando sepa que los has abatido. La mayor manada de estos tigres se encuentra al sur, cerca del Cataclismo, en la frontera de El Cabo de Tuercespina.", progress = nil, completion = "Impresionante. Creo que ya estás casi listo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][188] = {title = "Domina el tigre", objective = "Caza a Sin'Dall y regresa con su garra.", description = "Las leyendas hablan de una tigresa muy evasiva... un felino tan poderoso que hace parecer enclenques a los tigres mayores. Los cazadores de la Expedición de Nesingwary le han estado dando caza sin éxito. Muchos han caído víctimas de sus garras lacerantes; sus cuerpos se pudren en la falda de su colina, al norte de Grom'gol.\n\nLlaman a esta bestia Sin'Dall.\n\nDecídete a conseguir lo que <ningún/ninguna> <raza> ha conseguido: dar caza, matar y tomar la garra de Sin'Dall.", progress = "¿Cómo va la cacería de Sin'Dall?", completion = "¡Muy impresionante, sí! ¡Eres un cazador de tigres experto &lt;nombre&gt;!", rewards = "Fémur de Sin'DallJubón de amante de gatosGarras de Sin'DallBrazales de estrangulador de tigresRecibirás:\n\nGuantes de cazador de tigres"}
MultiLanguageQuestData['mx'][189] = {title = "Orejas de Sangrapellejo", objective = "Consigue 15 orejas Sangrapellejo y llévaselas a Kebok en la Bahía del Botín.", description = "¡Malditos trols! ¡Han estado matando a nuestros agentes en la jungla! Ya he perdido a un buen número de mis mejores guardias en esas escaramuzas. ¡Los costes se multiplican! ¿Cómo se lo voy a explicar al Barón Revilgaz?\n\nAcción decisiva... Piensa, Kebok... no te asignaron al puesto que tienes hoy por estar de brazos cruzados... ¡Lo tengo! Tú... <nombre>, ¿verdad? Me ayudarás, ¿no? ¡Hay dinero en juego!\n\nEste es el trato: tráeme las orejas de quince trols Sangrapellejo y te compensaré generosamente.", progress = "Espero que hayas tenido éxito... Hay trols por todas partes. Asquerosos demonios.\n\n¡Por cierto, eso me recuerda algo! Asegúrate de decírselo a tus amigos, ¿vale? ¡Necesitamos mucha ayuda!", completion = "Oh excelente, excelente. Esto ayudará un poco, por ahora... \n\n&lt;Su voz se hace casi imperceptible, masculla algo sobre margen de beneficio y costes...&gt; \n\n¿Qué? ¿Todavía están aquí? ¿Recompensa? Oh, vale... claro, aquí tienes... debería ser más que suficiente.", rewards = "Recibirás:\n\nCaña de pescar goblin"}
MultiLanguageQuestData['mx'][190] = {title = "Caza la pantera", objective = "Caza 10 panteras jóvenes.", description = "Si quieres formar parte del grupo de caza de Hemet Jr., tendrás que demostrar que eres capaz de cazar una pantera. No te preocupes, empezaremos con algo fácil: céntrate en las panteras jóvenes por ahora. A medida que vayas mejorando y ganando experiencia como <cazador/cazadora>, tendrás que enfrentarte a presas más peligrosas.\n\nEmpieza por dirigirte al este. Vuelve conmigo cuando te hayas convertido en <un maestro cazador/una maestra cazadora> de panteras.", progress = nil, completion = "¡Es un buen comienzo, &lt;nombre&gt;!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][191] = {title = "Persigue a la pantera", objective = "Caza 10 panteras.", description = "Las panteras más jóvenes se rindieron fácilmente ante ti. Las panteras más adultas serán más fuertes, más rápidas y más difíciles de derrotar.\n\nSus huellas se dirigen al oeste.", progress = nil, completion = "¡Magnífico, &lt;nombre&gt;!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][192] = {title = "Somete a la pantera", objective = "Caza 5 panteras Faucesombrías.", description = "Y ahora vamos con lo difícil. Cuando una pantera envejece, se vuelve más astuta, se mezcla con el entorno y es muy difícil localizarla. Estas astutas panteras se llaman \"Faucesombrías\" por su tendencia a aparecer repentinamente de entre las sombras... con una boca hambrienta llena de colmillos.\n\nSi quieres demostrar que eres <un verdadero cazador/una verdadera cazadora> de panteras, las Faucesombrías son el único modo de hacerlo. Acechan por el sureste, al otro lado del río.", progress = nil, completion = "¡Buen trabajo, &lt;nombre&gt;!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][193] = {title = "Domina la pantera", objective = "Consigue el colmillo de Bhag'thera.", description = "Casi has demostrado ser <un maestro cazador/una maestra cazadora> de panteras, pero hay una que se te ha escapado.\n\nHay canciones que hablan de una poderosa pantera llamada Bhag'thera. Veamos si puedes usar tus habilidades para matar a la gran bestia.\n\nSi le traes el colmillo de Bhag'thera a Erlgadin demostrarás ser <un maestro cazador/una maestra cazadora> de panteras.", progress = "¡Aún sigues con vida! ¡Excelente! ¿Cómo va la caza?", completion = "¡Así que la gran Bhag'thera está muerta! Enhorabuena, &lt;nombre&gt;. ¡Eres un poderoso &lt;clase&gt;!", rewards = "Manto de la panteraEscudo de la panteraRugido de Bhag'theraRecibirás:\n\nLeotardos de cazador de panteras"}
MultiLanguageQuestData['mx'][194] = {title = "Caza al raptor", objective = "Caza 10 raptores de Tuercespina.", description = "¿Así que crees que tus habilidades de caza están en buena forma? Veamos si es cierto. Vete a la jungla y mata 10 raptores de Tuercespina. Veremos lo <buen cazador/buena cazadora> que eres.\n\n¡Y no, no te diré dónde encontrarlos! Localizar a las bestias es la mitad del desafío.\n\nVale, ve al oeste.", progress = nil, completion = "¡Bien hecho, viejo amigo!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][195] = {title = "Persigue al raptor", objective = "Caza 10 raptores colazote.", description = "Ahora aumentemos la dificultad del desafío. Bastará con que te adentres en la jungla y captures 10 raptores colazote. Por supuesto, serán más fuertes que los raptores a los que ya has eliminado.\n\nLos raptores colazote suelen andar al sureste de aquí, cerca de las Ruinas de Kal'ai.", progress = nil, completion = "¡Así se adorna la chimenea con un par de trofeos! ¡Qué forma de matar, &lt;nombre&gt;!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][196] = {title = "Somete al raptor", objective = "Caza 10 acechadores de la selva.", description = "Una raza muy reservada de raptores que los locales llaman \"acechadores de la selva\" merodea por los bosques del sur, al otro lado del río. Son mucho más difíciles de rastrear y matar que las otras razas que has probado hasta ahora.\n\nSi matas a estos acechadores de la selva, sin duda tendremos una buena historia que contar alrededor de la fogata.", progress = nil, completion = "¡¡Jo, jo!! ¡Estamos frente a un auténtico asesino de raptores! Bien hecho, viejo amigo!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][197] = {title = "Domina el raptor", objective = "Caza a Tethis.", description = "Antes de regresar a la Expedición de Nesingwary, tendrás que realizar lo imposible: cazar al raptor que ningún otro cazador ha conseguido matar. La bestia se llama Tethis y se sabe que tiene aterrorizada toda la esquina sureste del Norte de la Vega de Tuercespina.\n\nSi le entregas la garfa de Tethis a ese enano cazador, demostrarás que no eres <un/una> <raza> común y corriente.", progress = "Ah, ¿estás intentando cazar a Tethis? Has conseguido seguirle la pista de vuelta al campamento, ¿no?", completion = "¡Te voy a llamar el señor &lt;nombre&gt;, el Azote de los raptores! \n\nSuena bien, ¿verdad?", rewards = "Calavera de TethisCinturón del raptorPodrás elegir una de estas recompensas:\n\nSortija de destripador de raptores\n\nTambién recibirás:\n\nGuerrera de cazador de raptores"}
MultiLanguageQuestData['mx'][198] = {title = "Suministros para el soldado Thorsen", objective = "Entrega los suministros goblin variados al soldado Thorsen.", description = "Mmm. Sí, de hecho, tengo algo que podrías hacer. El teniente Doren y sus seguidores que están al norte, necesitan que les enviemos sus suministros.\n\nTodavía no lo hemos podido hacer y, con el ataque de los trols, necesito que alguien lo haga. El campamento de Doren está en la parte noroeste del camino, en la entrada de Tuercespina desde el Bosque del Ocaso. Lleva los suministros al soldado Thorsen, si no está en el campamento, estará patrullando la zona sur. Él se encargará de todo.\n\nPor cierto, si fallas, me deberás una indemnización.", progress = "¿Sí? ¿Qué quieres? Oh, suministros de los goblins. Es extraño ver a un <raza> entregándolos, generalmente mandan a alguien de los suyos. No pasa nada... ¿no los habrás tocado, verdad? Bien, bien... No querríamos que nada pasase en nuestras minas. No, no, no.", completion = "Estas minas terrestres nos ayudan a defendernos de ese animal Kurzen y de sus hombres. Gracias por traerlas. Si buscas más trabajo, probablemente pueda encontrar algo para ti. Y no tendrás que tratar con esos goblins, ¿mm?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][201] = {title = "Investiga el campamento", objective = "Encuentra el campamento de los cazadores e informa sobre su ubicación a Krazek en la Bahía del Botín.", description = "Me han informado de un grupo de cazadores acampados río arriba del campamento minero de Ventura y Cía. en Lago Nazferiti. Normalmente los ignoraría, pero dicen que uno de los cazadores es Hemet Nesingwary Jr., que tiene muy, pero que muy buenos contactos; será mejor que no corramos ningún riesgo.\n\nVe a echar un vistazo al campamento, <nombre>, a ver qué están haciendo por ahí.", progress = nil, completion = "Mmmm, entonces mi información era correcta, como siempre. Qué interesante. Bueno, supongo que no representan ningún tipo de amenaza para nuestra operación, pero quizás necesiten alguno de nuestros productos de excelente fabricación. Mmmm...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][202] = {title = "Coronel Kurzen", objective = "Mata 6 unidades de élite de Kurzen y 4 subjefes de Kurzen. Lleva la cabeza de Kurzen al teniente Doren en el Asentamiento Rebelde.", description = "Has demostrado tu valía otra vez y tus recursos parecen rivalizar con los del mismísimo Kurzen. Quizás seas la salvación de nuestro grupo de rebeldes... si consigues enfrentarte a Kurzen y vencer.\n\nLidera a sus hombres desde las profundidades de Las Reservas. Debes entrar en la cueva, derrotar a sus defensores y enfrentarte a Kurzen y a sus líderes.\n\nAdiós, <nombre>. Mi esperanza, y el destino de mis hombres, van contigo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nLanzatralla"}
MultiLanguageQuestData['mx'][203] = {title = "La segunda rebelión", objective = "Mata a 15 jíbaros de Kurzen.\n\nVuelve a ver a la sargento Yohwa en el Asentamiento Rebelde.", description = "Estamos luchando una batalla perdida con el coronel Kurzen. No solo es un estratega brillante, sino que nos supera en número, ¡al menos 10 a 1! Para sobrevivir, tenemos que usar sus propias tácticas de cobertura contra él.\n\nVete a su campamento del este y mata a sus hombres. A muchos de ellos. Y sal de ahí antes de que los refuerzos te alcancen.", progress = nil, completion = "Bien hecho. La derrota de esos jíbaros aliviará algo la presión sobre nuestro campamento. \n\nPero ahora que has catado el tipo de fuerza al que nos enfrentamos, ¿aún deseas echar el resto con nosotros?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][204] = {title = "Mala medicina", objective = "Lleva 7 pócimas de la selva y 1 extracto de helecho venenoso a la sargento Yohwa en el Asentamiento Rebelde.", description = "Para tener una oportunidad contra Kurzen, necesitamos neutralizar su fuerza de curación. Ha reunido a un gran número de auxiliadores que curarán a sus tropas con pócimas de la selva y envenenarán a las nuestras con extractos de helecho venenoso.\n\nNecesitamos esas pócimas y extractos para nuestro propio provecho. Busca en la Base de Kurzen. Sus auxiliadores y jíbaros tendrán las pócimas y, probablemente, guardan los extractos en algunas de las cajas de suministros del campamento.", progress = "Estoy esperando las pócimas y el extracto, <nombre>.", completion = "Bien hecho, &lt;nombre&gt;. Estas pócimas conseguirán mantener a más de nosotros con vida y en buena forma. Y el extracto nos ayudarán a crear nuestras propias pócimas.", rewards = "Cuchilla de guerrillaManto de fronda de palmeraRecibirás:\n\n"}
MultiLanguageQuestData['mx'][205] = {title = "Brujería trol", objective = "Lleva 4 fetiches Machacacráneos al hermano Nimetz en el Asentamiento Rebelde.", description = "Mientras estudio esas leyendas, necesito que consigas instrumentos de magia trol maligna. Entra en el territorio de los trols Machacacráneos, la segunda tribu del sur, y consigue fetiches Machacacráneos de sus médicos brujos y místicos.", progress = "¿Tienes esos fetiches, <nombre>? Quizás guarden el secreto de la degradación de Kurzen... ¡Debo saberlo!", completion = "Gracias. Estudiaré estos fetiches y veré si puedo descubrir el secreto de la corrupción de Kurzen.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][206] = {title = "Mai'Zoth", objective = "Lleva el Ojo de la mente al hermano Nimetz en el Asentamiento Rebelde.", description = "Quizás Kurzen esté muerto, pero... eso que le volvió maligno sigue vivo. Gracias a mis estudios he descubierto esto: hay un ogro mago, Mai'Zoth, que vive en un Túmulo Ogro en las montañas del este de Tuercespina. Se dice que utiliza magia de control mental y creo que fue él quien corrompió a Kurzen.\n\nSi permitimos que Mai'Zoth siga con vida, su magia podría influenciar a otros y quizás incluso provocar que apareciese otro Kurzen.\n\nMátale y tráeme su Ojo de la mente, el artefacto que utiliza para corromper.", progress = "Te doy mi bendición. El mal aquí contenido es el único rival posible para la fuerza de Mai'Zoth.", completion = "¡Ajá! ¡Lo has conseguido! Eres una gran fuerza para el bien, &lt;nombre&gt;, ¡que las fuerzas nunca te fallen! \n\nEstudiaré este Ojo de la mente y veré si puede usarse para buenos fines. Si no... Acabaré con él.", rewards = "Recibirás:\n\nOrbe tranquilo"}
MultiLanguageQuestData['mx'][207] = {title = "El misterio de Kurzen", objective = "Encuentra las 4 tablillas y lleva las leyendas al hermano Nimetz.", description = "El coronel Kurzen fue un gran hombre de gran nobleza, ¡debo descubrir qué hizo que cayese en la depravación! Quizás está bajo el influjo de alguna magia trol. Para confirmarlo, debo estudiar algunas de sus leyendas.\n\nHay 4 tablillas escondidas en las ruinas trol de Tuercespina. ¡Necesito leer esas tablillas! Transcribe las tablillas y tráeme las transcripciones.\n\nLa primera tablilla está en las Ruinas de Bal'lal, la segunda en El Arrecife Mortal, y la tercera y cuarta en las Ruinas de Zul'Kunda.", progress = "¡<nombre>! ¿Tienes las leyendas trols? ¡Tengo que saber sus secretos!", completion = "Gracias, &lt;nombre&gt;. Estudiaré estas leyendas para ver si hay algún tipo de unión entre los trols y el mal que ha poseído al coronel Kurzen.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][208] = {title = "Caza mayor", objective = "Caza la cabeza del rey Bangalash, el gran tigre blanco.", description = "<nombre>, eres <un cazador digno/una cazadora digna> de estar en nuestro grupo. Desde los campos de batalla de Lordaeron hasta las profundidades de la jungla, muy pocas veces he visto tal destreza con las armas como la que has demostrado tú.\n\nHas matado al feroz Sin'Dall, a la esquiva Bag'thera y al traicionero Tethis. Pero el verdadero trofeo es la cabeza del rey Bangalash. Ese tigre blanco es la razón por la que estoy aquí, pero sigue provocándome desde su refugio al sur. Mata al rey Bangalash y tu dominio de la cacería será insuperable.", progress = "Veo que has vuelto, viejo amigo. El rey Bangalash me ha obligado a volver arrastrándome al campamento demasiadas veces. Espera un momento.", completion = "¡Pero qué maravilla! ¡Eso es! Enhorabuena, &lt;nombre&gt;, por triunfar ahí donde otros fracasaron. \n\nEs un honor para mí contarte entre mis camaradas de caza mayor. ¡Nadie podrá poner en duda tu pericia en la caza y el rastreo! \n\n¡Levanto mi copa por ti, salud! ¡Salud!", rewards = "Garra de BangalashFajín de NesingwaryManto del tigre blancoGuantes del rey de la junglaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][209] = {title = "Colmillos Machacacráneos", objective = "Consigue 18 colmillos Machacacráneos y llévaselos a Kebok.", description = "Matar los tigres necesarios para mantener la exportación de sus colmillos a las islas de los Mares del Sur es algo caro y complicado. Por suerte, hemos desarrollado una técnica que nos permite recoger objetos normales en forma de cuerno y convertirlos en falsificaciones perfectas.\n\nLo más parecido que hemos encontrado, sorprendentemente, son los colmillos de trols Machacacráneos.\n\nEy, antes de que digas algo, ojo de comprador que no ve, corazón de tonto que no siente, ¿no crees? Tráeme muchos colmillos para que podamos ponernos a trabajar en el pedido del mes.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][210] = {title = "La cocina de Krazek", objective = "Lleva la olla mecánica de Krazek al goblin Krazek.", description = "Yo me encargo de la mayor parte de la cocina del campamento. Y solía ser un montón de trabajo, hasta que le compré una olla mecánica a un mercader goblin en la Bahía del Botín. ¡Esa olla es una maravilla! Me ha ahorrado un montón de horas... ¡Pero se ha roto!\n\n¿Podrías llevar la olla al goblin para que me la pueda arreglar? Se llama Krazek.", progress = "¡Hola! ¿Me has traído algo?", completion = "Oh, ya veo, es una olla mecánica de Krazek. Un objeto muy ingenioso, pero, de vez en cuando, se le salta algún muelle que otro. Veamos qué le pasa... \n\n¡Ajá! El cargador de vapor está oxidado, tiene una junta rota y le faltan dientes al fobulador. ¡Me sorprende que la olla haya sido capaz incluso de cocer un nabo en este estado! \n\n¿Puedo arreglarla? Pues claro que sí. \n\nPero todo en esta vida tiene un precio. Oh, sí, siempre hay que pagar un precio...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][211] = {title = "Ah, Andorhal", objective = "Lleva el trozo de filacteria de Araj al comandante Ashlam Puñovalor del Campamento del Orvallo, en las Tierras de la Peste del Oeste.", description = "¡Ay, se acerca el momento de atacar Andorhal y de hacer salir al exánime que lo controla!\n\nEs en el interior de las ruinas de la ciudad donde el exánime, Araj el Invocador, tiene sus dominios. Está custodiado por numerosos miembros de la Plaga que rodean los restos del centro de la ciudad, y su séquito personal de guardianes es realmente formidable. Necesitarás muchos aliados para tener alguna oportunidad de enfrentarte a él con éxito.\n\n¡Acaba con Araj, <nombre>, y tráeme un trozo de su filacteria como prueba!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nMarca de Resolución"}
MultiLanguageQuestData['mx'][212] = {title = "Un plato bien frío", objective = "Mata un Basilisco Ojogélido, consigue un anca de basilisco helado y llévasela a Angus Stern en El Ermitaño Taciturno.", description = "Uno de mis platos más famosos es basilisco helado en vinagreta de lima. Pero el problema es que es imposible mantener fresca la carne y tengo que servir el plato esta noche en el cumpleaños de un noble.\n\nSi pudieras traerme un anca de basilisco helado de un Basilisco Ojogélido recién muerto y rápidamente... ¡estaré en deuda contigo!\n\nLos Basiliscos Ojogélido suelen vagar por las dunas de la playa al noroeste de la Vega de Tuercespina, así que te espera un largo viaje. ¡Y rápido!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][213] = {title = "OPA hostil", objective = "Consigue 8 cristales caídos y llévaselos a Kebok en la Bahía del Botín.", description = "¡Lo ha hecho! Ya es bastante malo que Gelriz se meta por el medio de los magnates que nombraron los príncipes mercantes como para que ahora intente meterse con el pirata más famoso.\n\nRevilgaz no lo tolerará y me ha dicho que me encargue del problema a mi manera.\n\n¿Mi manera? El robo. Los geólogos de Ventura y Cía. que están cerca del Lago Nazferiti están muy interesados en esos extraños cristales azules que han encontrado en las minas. Tráeme muestras de los cristales de los geólogos, no me importa lo que tengas que hacer para conseguirlas.", progress = "Necesito esos cristales, <nombre>. ¡Haz lo que sea para conseguirlo! Hazlo, no me des detalles.\n\nTodo se trata del resultado, <nombre>, nada más y nada menos.", completion = "Fascinante. El que los cristales se hayan caído con este proceso solo puede indicar que piensan usarlos para algún tipo de combustible o catalizador. Eso es todo lo que sé. Habrá que enviar muestras al químico jefe Gigglefont.", rewards = "Recibirás:\n\nGuantes con gemas"}
MultiLanguageQuestData['mx'][214] = {title = "Pañuelos rojos de seda", objective = "La exploradora Riell de la Colina del Centinela quiere que le lleves 10 pañuelos de seda roja.", description = "No es ningún secreto que la marca distintiva de la banda Defias son los pañuelos rojos. Pero hemos averiguado que el material del que están hechos los pañuelos sirve para identificar el rango del miembro.\n\nDicho esto, quiero que elimines tantos miembros Defias de alto rango como puedas. Podrás encontrarlos en la ladronera secreta de VanCleef. Cuando hayas terminado tráeme 10 pañuelos de seda roja y sabré recompensarte. Buena suerte, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Hoja corta sólidaDaga para tallarHacha penetranteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][215] = {title = "Los secretos de la jungla", objective = "Habla con el teniente Doren en el Asentamiento Rebelde.", description = "Gracias por salvarme, <nombre>. Sé lo que parece esto, pero... deja que te lo explique.\n\nEl teniente Doren me encargó alistarme con los hombres de Kurzen para que pudiera espiarles y llevar información a los rebeldes. Lo que has visto es lo que yo pensaba que sería mi oportunidad para infiltrarme en la Base de Kurzen. Me equivoqué y, otra vez, gracias por salvarme.\n\nEsto era una misión de alto secreto, así que no se lo puedes decir a nadie. Pero si hablas con Doren, te lo explicará.", progress = nil, completion = "Sí, lo que te contó Thorsen es cierto. Debes tener discreción con este asunto. Hubo un tiempo, cuando los rebeldes éramos absolutamente leales al coronel Kurzen. Pero debido al grado de corrupción de Kurzen, nuestra pasión se convirtió en ira. Si se supiera que el soldado Thorsen ha tenido algo que ver con los hombres de Kurzen, cualquier noche se encontraría con el pescuezo cortado. \n\nPor lo que yo sé, solo la sargento Yohwa, Thorsen y yo conocíamos la existencia de la misión de Thorsen. Pero debe de haber alguien más. Un traidor.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][216] = {title = "Entre una roca y un Piel de Cardo", objective = "Karang Amakkar en Avanzada Grito Infernal quiere que acabes con 15 fúrbolgs Piel de Cardo de cualquier tipo en el Poblado Piel de Cardo.", description = "¡Los fúrbolgs Piel de Cardo son una amenaza para nuestra expansión! El Poblado Piel de Cardo, al oeste, obstruye nuestro paso entre este lugar y el Puesto del Hachazo. Es un camino que rodearía el pueblo de Astranaar; sin él, ofrecemos a la Alianza una vía más para la expansión.\n\n<nombre>, no podemos permitir... ¡un hueco en el camino de expansión!\n\nVe al Poblado Piel de Cardo y acaba con los fúrbolgs. Recibirás una compensación por esta tarea y lo que es más importante, ¡estarás cumpliendo con tu deber para con la Horda!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][219] = {title = "Desaparecido en combate", objective = "Protege al cabo Keeshan en el camino a Crestagrana.", description = "¡Al fin, ayuda para la Alianza!\n\nAyúdame...\n\nLo último que recuerdo es que esos malditos orcos nos tenían rodeados. Los mataron a casi todos. A mí me dieron un golpe en la cabeza y perdí el conocimiento, y ahora me encuentro cautivo. Ayúdame, estoy malherido.\n\nTienes que ayudarme a volver... Por favor, eres mi única esperanza.", progress = nil, completion = "Has prestado un gran servicio al Reino, &lt;clase&gt;. Gracias por ayudar al cabo Keeshan a huir de los Roca Negra. Recibirás una recompensa por tus heroicas acciones.", rewards = "Abrigo de anillas de diputadoCuero con huesosToga de SolomonRecibirás:\n\n"}
MultiLanguageQuestData['mx'][220] = {title = "La llamada del agua", objective = "Llévale el vial del agua más pura a Islen Vidente del Agua al Escalón de la Marea, en Los Baldíos.", description = "Islen tendrá una tarea más para ti antes de recompensarte con tu siguiente tótem. Sea cual sea esa tarea, te hará falta el vial de agua que te he dado.\n\nAhora vete y encuéntrala. Volveremos a encontrarnos algún día.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSapta de agua"}
MultiLanguageQuestData['mx'][221] = {title = "Huargen en el bosque", objective = "Mata a 12 huargen sombracechadores Penumbría para Calor de Villa Oscura.", description = "Quizás te hayas fijado en esos enormes huargen que deambulan por los bosques con los tejesombras... Por lo que sabemos, esos corredores oscuros son el grueso de las filas de los huargen.\n\nEn mis patrullas también he notado que han invadido El Vergel Pútrido al suroeste de la ciudad. Esos huargen son más fuertes que los últimos a los que te enfrentaste.\n\nNo bajes la guardia.", progress = nil, completion = "Te has desenvuelto bien contra los Correoscuros, &lt;nombre&gt;. Pero parece que su número es irreducible. Cada vez que hacemos un progreso, llegan más a tomar el relevo. \n\n¿Qué maléfico poder es el que les trae aquí? ¿Por qué han irrumpido de esta manera en nuestro infeliz reino? \n\nTendré fe en el maestro Carevin. Sin duda, él llegará hasta el fondo del asunto.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][222] = {title = "Huargen en el bosque", objective = "Mata 8 Colmillovil nocturnos y 8 huargen corruptos Penumbría para Calor de Villa Oscura.", description = "Tus anteriores hazañas me han hecho pensar que ya estás <listo/lista> para afrontar a los huargen más duros del bosque.\n\nDe todos los huargen que han establecido aquí su morada, los Colmillo Vil y los Mancillados han demostrado ser los más peligrosos. Se han instalado cerca de las cuevas y en la mina que hay al sur.\n\nEl fuego de sus hogueras puede verse desde muy lejos...", progress = nil, completion = "A decir verdad, &lt;nombre&gt;, no creía que llegarías tan lejos. Pero está claro que me equivoqué contigo, &lt;clase&gt;. De hecho, si deseas unirte formalmente a la lucha del maestro Carevin, será un placer escribirte una carta de recomendación.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][224] = {title = "En defensa de las tierras del rey", objective = "El montaraz Pedernal, de Thelsamar, quiere que mates a 6 troggs y 6 exploradores Rompecantos.", description = "¡Tenemos que proteger Loch Modan, <nombre>! Casi todas nuestras tropas están luchando en otros frentes; nos hemos quedado desprotegidos. ¡Están saliendo troggs de debajo de las piedras! Esta invasión supone la mayor amenaza para Forjaz. Tenemos que acabar con esos asquerosos mutantes.\n\nNecesitamos a alguien valiente como tú para acabar con esos seres. Acaba con seis troggs Rompecantos y seis exploradores Rompecantos. Encontrarás a la mayoría de esas alimañas en los pasos hacia las montañas del sur.", progress = nil, completion = "¡Bien hecho, &lt;nombre&gt;! Has demostrado una valentía inigualable en el campo de batalla. Ganaremos la guerra contra los troggs con esfuerzos como el tuyo. Le has servido bien al rey Magni.\n\nSi crees estar bien equipado para este tipo de aventuras, te sugiero que hables con el montaraz Gravagau. El capitán lo ha asignado a una patrulla bastante ruda y seguramente necesite algo de ayuda. Ve a hablar con Gravagau dentro de la torre.", rewards = "Recibirás:\n\nPincho de Dalaran"}
MultiLanguageQuestData['mx'][225] = {title = "La lápida desgastada", objective = "Ve a Villa Oscura y habla con Sirra Von'Indi.", description = "La lápida, desgastada por el tiempo, reza sencillamente:\n\nMORGAN LADIMOR\n\n<Cuando te acercas más, te das cuenta de que la tierra que hay sobre la tumba ha sido removida recientemente; parte de ella ha sido extraída...>", progress = nil, completion = "¿Morgan Ladimor? \n\nAh, sí, claro. La suya es una historia larga y llena de desgracias. Yo lo conocía bien, bueno, antes de que se fuera a la guerra, pero esa fue la última vez que lo vi. Era un buen hombre, un hombre noble, pero tuvo un trágico final. \n\nTen, tengo algo aquí que podría contarte su historia mejor que yo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][226] = {title = "Con los lobos en los talones", objective = "Mata a 12 lobos feroces hambrientos y a 8 lobos feroces rabiosos y vuelve al campamento de Sven en la frontera oeste de Bosque del Ocaso a buscar a Lars.", description = "A Sven y a mí nos esperan días peligrosos, con el nigromántico al este... y aquí solos... tenemos que cazar nuestra propia comida. Y cada vez que vuelvo al campamento con algo de carne, aparecen lobos hambrientos o rabiosos buscando un bocado. ¡Vivir aquí es peligroso, no hace falta que lo jure!\n\nPero si consiguieras librarnos de algunos de esos lobos, nos facilitarías mucho la cosa. Se concentran sobre todo al norte y al este de aquí, cerca del río.", progress = nil, completion = "Oh, bien. Has diezmado la manada. Ahora que no tendremos a esos lobos pisándonos los talones, podremos centrarnos en Morbent Vil. \n\nTen, coge algunas de estas cargas cegadoras. Las hacen en el pueblo y muchas han sido donadas a Sven, para ayudar a su causa.", rewards = "Recibirás:\n\nFardo cegador"}
MultiLanguageQuestData['mx'][228] = {title = "Mor'Ladim", objective = "Mata a Mor'Ladim y luego lleva su calavera a la comandante Althea Cerranegro a Villa Oscura.", description = "Por lo que me dicen los exploradores, Mor'Ladim deambula por el Bosque del Ocaso; recorre un extraño y serpenteante camino por el cementerio. Lo enterramos pasada la casa de la colina, ¿sabes dónde digo?\n\nNo hay nada que pueda hacer para ayudarte, pero te deseo buena suerte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][230] = {title = "El campamento de Sven", objective = "Lleva el libro de la granja de Sven a Sven.", description = "Cavando en el montículo encuentras un pequeño libro manchado de tierra.\n\nNo tiene título pero... contiene información que a Sven le gustaría tener.", progress = "¿Que has encontrado qué? Déjame verlo, por favor...", completion = "&lt;Sven lee las páginas del libro y luego lo cierra de un golpe.&gt; \n\n¡Esa figura misteriosa que vi fue testigo de la muerte de mi familia! Hay preguntas que necesito hacerle a ese hombre... ¡si tan solo supiera quién es!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][232] = {title = "Un recado para la boticaria Zinge", objective = "Llévale la orden de compra a Alessandro Luca en Entrañas.", description = "La Sociedad Real de Boticarios necesita tu ayuda. Escucha bien esto, y puede que ambos podamos beneficiarnos con mi plan.\n\nEl boticario Keever, en la sala contigua, puede que esté... un poco tocado... pero su investigación promete dar muy buenos resultados, sobre todo si la condujera un investigador más inteligente. Afortunadamente, yo soy investigadora. Quiero que lleves esta orden de compra a Alessandro Luca, el propietario de Cachivaches Luna Azul; él te dará un equipo de estudio. Cuando lo tengas, tráemelo y yo me encargaré de explicarte tu encomienda con todo detalle.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][235] = {title = "La Caza de Vallefresno", objective = "Habla con Senani Corazón Atronador en Puesto del Hachazo, en Vallefresno.", description = "¡Atención, jóvenes aventureros! ¡Los páramos de Vallefresno les esperan!\n\nLa Horda ha aumentado su presencia en las tierras al norte de Los Baldíos. Nuestras dos avanzadas, Puesto del Hachazo y La Ensenada de Zoram, se esfuerzan por traer gloria a la Horda. Aquellos que deseen demostrar su valía deben buscar ayuda allí. Nota: Senani Corazón Atronador del Puesto del Hachazo, al norte de Los Baldíos, busca a aventureros que deseen participar en la gran Caza de Vallefresno.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][236] = {title = "Combustible para los demoledores", objective = "El maestro de asedio Durasa, en la Fortaleza de Conquista del Invierno, quiere que arrebates 10 ascuas eternas a los jugadores de la Horda en El Caldero de Llamas.", description = "¡<nombre>! Ya era hora de que aparecieras. Puede que esta batalla haya terminado, ¡pero aún tenemos que prepararnos para la siguiente! Viaja hasta El Caldero de Llamas, al sureste de Conquista del Invierno, y recoge algunas ascuas eternas.\n\nLas ascuas están mezcladas con carbón para repostar el demoledor y las máquinas de asedio.\n\nOh, y si ves a algún miembro de la Horda por El Caldero, no dudes en matarlo y quedarte con sus ascuas. No podemos dejar que nos saquen ventaja en la próxima batalla.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPuntos de honorFragmento de vigilante de piedra"}
MultiLanguageQuestData['mx'][240] = {title = "Regresa junto a Alterio", objective = "Vuelve a donde Alterio con los pasteles de cangrejo oscuro.", description = "¡¡Y voilà!! ¡Croquetas de \"cangrejo\" à la Grual!", progress = "<nombre>, ¡estás aquí! ¡¿Tienes mi comida?!", completion = "¡Ajá! Gracias, &lt;nombre&gt;. ¡Qué bien sientan estas cosas! \n\n¡Y ten, deja que te pague!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][243] = {title = "In situ", objective = "Ve a Gadgetzan y encuentra al ingeniero jefe Pasaquillas para que te explique cómo obtener una fuente de energía para el equipo de estudio.\n\nObjeto provisto: \n", description = "Dirígete al Desierto de Tanaris, y allí comprueba la consistencia del tejido de los basiliscos, escórpidos y de las hienas autóctonas del lugar. Consigue muestras de tejido con el equipo de estudio que llevas; eso sí, hazte a la idea de que parte de las muestras serán inservibles. Necesito 8 muestras buenas de cada tipo de criatura.\n\nAdemás, los goblins de Gadgetzan tienen una fuente de energía que debe emplearse con este tipo de equipo modificado. Habla con el ingeniero jefe Pasaquillas y consigue una para el equipo.\n\nVuelve a hablar conmigo cuando la tengas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][244] = {title = "Gnolls invasores", objective = "Preséntate ante el ayudante de alguacil Feldon en el puente que hay al sur de Villa del Lago, en las Montañas Crestagrana.", description = "Saludos, <clase>. Estoy patrullando esta parte del camino. De momento todo está en calma, pero he visto campamentos gnoll al norte y al este de aquí.\n\n¡Debes informar de esto en Villa del Lago! Preséntate ante el ayudante de alguacil Feldon en Villa del Lago y dile lo de los gnolls. Seguro que te paga sueldo de explorador.\n\nLo encontrarás al sur del puente a Villa del Lago.", progress = nil, completion = "¿Hay gnolls de Crestagrana tan cerca de Elwynn? Puede que planeen una invasión... ¡Los de Villa del Lago ya no serán los únicos humanos bajo asedio! \n\nAquí tienes el pago, pese a las noticias que traes. Y en qué mal momento: carecemos de recursos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][245] = {title = "as amenazas de ocho patas", objective = "Mata a 15 telarácnidas pigmeovenenosas y vuelve al Bosque del Ocaso a informar al vigía Dodds.", description = "Salve, <clase>. ¿Has visto esas arañas que han invadido la frontera occidental? Esas amenazas de ocho patas son demasiado para nosotros pero el Comandante no tiene suficientes hombres. No puede enviar a nadie tan lejos de Villa Oscura.\n\nOdio tener que pedirte esto pero, parece que tú podrías manejar a esos bichos. No puedo prometerte una gran recompensa, pero si nos ayudas a erradicar a esos arácnidos, encontraré la forma de compensarte.\n\nAh, y deja que te dé un consejo: evita su veneno a toda costa.", progress = nil, completion = "¡Ah! Has vuelto. Y no demasiado agotado, por lo que veo. La Guardia Nocturna está agradecida por tu trabajo, &lt;nombre&gt;, y yo te prometí una recompensa, aquí la tienes.", rewards = "Recibirás:\n\nGuanteletes de guardia nocturno"}
MultiLanguageQuestData['mx'][246] = {title = "Evaluar la amenaza", objective = "Mata a 10 bastardos y 6 furtivos Crestagrana e informa al ayudante de alguacil Feldon en Villa del Lago.", description = "Andamos escasos de tropas, pero hay que hacer algo con esos gnolls.\n\nRastrea el sur de Crestagrana en busca de gnolls. Espíalos, mata a tantos como puedas y vuelve para informarme de cuántos son y si suponen una amenaza. Sus campamentos están por todo el camino meridional de Crestagrana.\n\nEl ejército de Ventormenta te recompensará, <nombre>.", progress = nil, completion = "&lt;El ayudante de alguacil Feldon escucha tu informe...&gt; \n\nAsí que hay un grupo numeroso de gnolls de los duros. Seguro que no te ha sido fácil recopilar esta información. \n\nTen, &lt;nombre&gt;, y gracias por tu ayuda. \n\nHabla con el alguacil Marris y el magistrado Solomon en Villa del Lago. Necesitarán tu ayuda; la situación empeora por momentos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][248] = {title = "Ver más allá", objective = "Sube a la atalaya intacta que hay junto al Fuerte de Petravista en las Montañas Crestagrana. \n\nEncuentra un objeto en el que esconder el Glifo de Azora.", description = "He estado observando la Torre de Ilgalar; Morganth está en conflicto con los orcos en el Fuerte de Petravista. Desconozco los motivos, pero tú me ayudarás a descubrirlos.\n\nBusca otro Glifo de Azora y sube a la atalaya intacta que hay junto al Fuerte de Petravista.\n\nEncuentra un objeto en el que depositar el glifo. Un cofre o un tarro iría bien, un lugar en el que nadie se fije en él.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][249] = {title = "Morganth", objective = "Derrota a Morganth. \n\nLleva el colgante de las Sombras a Theocritus a la Torre de Azora, en el Bosque de Elwynn.", description = "Después de mucha observación, he descubierto los planes de Morganth.\n\nBusca la Guadaña de Elune, ¡y es posible que ya la haya encontrado! Si ese es el caso, pronto las Montañas Crestagrana y el Reino de Ventormenta sentirán su siniestro poder.\n\nNo estoy preparado para enfrentarme a Morganth, pero me temo que debemos ocuparnos de él cuanto antes. Debes ir a la Torre de Ilgalar y enfrentarte a Morganth.\n\nDerrótalo y tráeme su colgante de las Sombras. El reino quedará en deuda contigo.", progress = "¡<nombre>, tienes que evitar que Morganth extienda su poder!", completion = "Muy bien, &lt;nombre&gt;. Al derrotar a Morganth, has librado a Ventormenta de un grave peligro. \n\nAcepta esta recompensa. Te diría que fueras en paz, pero estos no son tiempos de paz. \n\nEn lugar de eso, te deseo suerte en tus pruebas y victoria en combates futuros.", rewards = "Recibirás:\n\nManto rosa"}
MultiLanguageQuestData['mx'][250] = {title = "Se aproxima una oscura amenaza", objective = "Investiga los alrededores de la rampa este de la Presa y lleva al ingeniero jefe Hinderweir alguna pista sobre lo que traman los Hierro Negro.", description = "Menos mal que alguien se interesa por el bienestar de la Presa. ¡Primero la destrucción del Puente Thandol y después el saqueo de Dun Modr! No dudo que el objetivo del siguiente ataque de los Hierro Negro será la Presa. Casi todos los agentes de seguridad se han destinado a luchar con la Alianza, incluido mi mejor inspector.\n\nPor eso te necesito, <nombre>. He visto algunos zapadores Hierro Negro en la rampa oriental de la Presa. Investiga la zona y trae una pista.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][255] = {title = "ercenarios", objective = "Kelt Thomasin, en la Fortaleza de Mo'grosh, te ha contratado para matar a 4 ogros, 4 toscos y 4 gorilas Mo'grosh.", description = "Cazar bestias salvajes se acaba haciendo aburrido. A mí me van las presas grandes... Muy grandes. Los ogros, concretamente.\n\nA los enanos les preocupa bastante la Fortaleza de Mo'grosh al noreste, pero no tienen hombres para hacer nada al respecto. Si te apetece unirte a la caza, ponte a matar todos los ogros que encuentres. Tráeme noticias de tus hazañas y compartiré contigo la recompensa del acuerdo que tengo con el magistrado.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nBanda FraguapiedraAnillo de llama de luzAnillo de orgullo\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][256] = {title = "SE BUSCA: Chok'sul", objective = "Mata a Chok'sul y lleva su cabeza al magistrado Narizroma a Thelsamar.", description = "Por orden del magistrado de Thelsamar:\n\nSe busca muerto a Chok'sul, ogro culpable de dirigir los ataques contra la ciudad de Thelsamar, la Presa de las Tres Cabezas y la excavación.\n\nSe ofrece recompensa a quien presente al magistrado una prueba de la muerte de Chok'sul.\n\nFue visto por última vez en el campamento ogro situado al noreste de Loch Modan.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Sobrehombros de anillas durablesBotas KimbraBrazales de cazarrecompensasMalla de anillas de ThelsamarPodrás elegir una de estas recompensas:\n\nSello Narizroma\n\nTambién recibirás:\n\nAnillo de mediación menor"}
MultiLanguageQuestData['mx'][257] = {title = "La fanfarronada de un cazador", objective = "Mata 8 águilas ratoneras montesas y ve a ver a Daryl el Jovenzuelo en la Cabaña del Errante.", description = "Crees que estás a la altura de Daryl el Audaz, ¿eh? ¡No lo creo! Por supuesto, puedes ponerte a prueba. Te propongo un desafío que seguro estará por encima de tus posibilidades, así que no te sientas mal si no eres capaz de superarlo.\n\nUna banda de águilas ratoneras ha anidado aquí, en Loch Modan. ¿Qué tal si acabas con algunas de esas bestias? Mira, si superas mi desafío, te daré mi arco o mi pistola.\n\n<Te mira por encima del hombro.>\n\nNo parece que tengas mucho que perder de todas formas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Arco de caza de DarylRifle de caza de DarylRifle de DarylArco de DarylRecibirás:\n\n"}
MultiLanguageQuestData['mx'][261] = {title = "El sendero Escarlata", objective = "Aniquila 30 devastadores no-muertos y luego ve a buscar al hermano Anton a Punta de Nijel.", description = "Te hablaré con franqueza. Estamos en guerra con la Plaga. Es un mal que corrompe a nuestra gente e infesta nuestra tierra. Hay que detenerlo antes de que nos arrolle y arrastre a nuestro mundo a las sombras. Los miembros de la Cruzada Escarlata hemos jurado combatir a la Plaga en cuerpo y alma.\n\nSi estás con nosotros, reúne valor y prueba tu lealtad: acaba con los devastadores no-muertos de Desolace. Búscalos en el Valle de los Huesos, al sur.\n\nHazlo y la Cruzada te acogerá con los brazos abiertos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][264] = {title = "Hasta que la muerte nos separe", objective = "Coloca el colgante de Clarice sobre la tumba de Yuriv en Argénteos.", description = "¡Sucia escoria! Me abandona por su maldita cruzada porque \"la Luz es lo más importante que tenemos contra la amenaza que representan los no-muertos.\"\n\n¡¿Y sus hijos?! ¡¿Y YO?! Noche tras noche me quedaba esperando por él... ¡siempre en segundo lugar después de sus condenadas obligaciones!\n\nBueno, ¡mira lo que te depara la \"justicia\", <nombre>! ¡Él está muerto y yo tengo precisamente lo que estaba intentando detener!\n\nCoge esto y ponlo encima de su tumba en El Sepulcro. ¡No quiero tener nunca más nada que ver con eso... ni con él!", progress = "La piedra está fría y su estado demuestra que se han ensañado con ella. La zona está llena de basura, el féretro presenta golpes y grietas y las malas hierbas empiezan a crecer a su alrededor.\n\nA nadie le importa quién está enterrado aquí, sobre todo a ninguna de las víctimas de la peste.", completion = "Colocas el colgante sobre la tumba y observas que la gema parece perder su brillo. \n\nCuando te incorporas para marcharte, miras de nuevo el collar, que yace inánime en las manos de la escultura que preside el féretro. Una ráfaga de viento frío recorre El Sepulcro, interrumpiendo así tus pensamientos. Por un momento, el silencio reina a tu alrededor.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][267] = {title = "La amenaza trogg", objective = "Lleva 8 dientes de trogg de piedra al capitán Rugelfuss a la torre de vigilancia sur.", description = "<clase>, es posible que no estés al corriente de la amenaza trogg que se cierne sobre tierras enanas. Con las fuerzas de reserva de Forjaz en el frente de la Alianza, solo nos queda una fracción de las fuerzas de defensa necesarias para proteger estas tierras. Mi regimiento debe quedarse aquí protegiendo la ciudad, por lo que no podemos abandonar nuestros puestos, nos arriesgaríamos a una invasión.\n\nPero tenemos que presionar un poco a esos malditos troggs que merodean por las colinas. Si te ves capaz, lanza un ataque contra los troggs. Tráeme ocho dientes de trogg de piedra como prueba de tu acción.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][269] = {title = "En busca de sabiduría", objective = "Entrega el diario completo de Alterio al obispo Lontananza de Ventormenta.", description = "Ve a la ciudad de Ventormenta y habla con el obispo Lontananza. Búscalo en la Catedral de la Luz. Dale el diario de Alterio y dile que deseas enfrentarte a Morbent Vil.\n\nAunque Ventormenta ha abandonado a Villa Oscura, Lontananza es un alma buena y sabia. Puede que te ayude a salvarnos.\n\nTu misión es peligrosa, pero date prisa, <nombre>. Las sombras del Bosque del Ocaso son más cada vez más oscuras.", progress = "Descansa, hermana. Se ve que has viajado lejos y que llevas un peso enorme. ¿Puedes decirme qué es lo que proyecta sobre ti esa sombra tan oscura?", completion = "&lt;Después de leer el diario y de oír tu intención...&gt; \n\nUna malvada mácula se ha hecho con el ya asediado Bosque del Ocaso. Doy gracias a la Luz porque ahora tenemos a una heroína como tú para hacerle frente. \n\nPero primero debes prepararte para la prueba que te espera, pues el poder del nigromántico Morbent Vil es inconmensurable y además, ha lanzado sobre sí mismo oscuros encantamientos que lo protegen de ataques físicos. Si quieres derrotarle, necesitarás un arma que pueda contrarrestar estas protecciones.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][270] = {title = "La flota maldita", objective = "Vete al Puerto de Menethil en Los Humedales y habla con Glorin Frenteacerada.", description = "Años atrás, la Tercera Flota de Kul Tiras se hundió en la costa de Los Humedales, una expansión pantanosa al norte del reino enano de Forjaz. A bordo del barco había un envío de hierro Forjaluz.\n\nEste metal es muy valioso para nosotros, porque los objetos forjados con él, golpean con toda la verdad sagrada. Si te vas a enfrentar a Morbent Vil, necesitarás un arma así.\n\nVete al Puerto de Menethil y habla con mi colega enano Glorin Frenteacerada. Si es posible encontrar ese metal perdido, él sabrá dónde.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][271] = {title = "La venganza de Vyrin", objective = "Mata al viejo Tiznado y llévale una prueba a Daryl el Jovenzuelo en la Cabaña del Errante.", description = "Supongo que no te interesa vengarte de Lord Arrogancia, ¿verdad? Daryl tiene cierta habilidad, aunque me duela reconocerlo.\n\nHace un año el objetivo de la Cabaña del Errante era un gran oso, pero ni uno solo de los cazadores logró derribarlo. Así que Daryl decidió probar suerte con él. Lo único que consiguió fue la terrible cicatriz que tiene en el ojo.\n\nMata al oso, y eso sin duda le cerrará el pico a Daryl aunque solo sea por una vez.\n\nPuedes encontrar al oso, el viejo Tiznado, en su guarida, que está en las colinas de Thelsamar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][276] = {title = "Patas sucias", objective = "Mata 15 gnolls Pellejomusgo y 10 bastardos Pellejomusgo y regresa con Rethiel el Guardaverde en Los Humedales.", description = "Los gnolls Pellejomusgo han vivido en paz en Los Humedales durante mucho tiempo, pero ahora su número está creciendo. Sus pies pisotean las flores y arbustos del pantano y sus hachas no dejan de talar árboles para alimentar sus fuegos.\n\nHan dejado de estar en equilibrio con la tierra. Para que sobrevivan Los Humedales, debemos reducir a los gnolls.\n\nMata a 15 gnolls Pellejomusgo y a 10 bastardos Pellejomusgo en el Sur, junto a la puerta enana de Algaz. Cuando lo hayas hecho vuelve aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][277] = {title = "No al fuego", objective = "Lleva 9 sílex rudimentarios a Rethiel el Guardaverde.", description = "Los Pellejomusgo están talando los árboles de Los Humedales, y utilizan su carne para darse calor. ¡No seguiré sufriendo este dolor!\n\nArrebata a los Pellejomusgo los sílex rudimentarios que utilizan para hacer fuego. Todos los Pellejomusgo llevan esos sílex rudimentarios, excepto los pequeños gnolls y bastardos Pellejomusgo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nColmenilla esponjosa"}
MultiLanguageQuestData['mx'][279] = {title = "Zarpas de las profundidades", objective = "Mata a 12 múrlocs Branquiazul.\n\nMata a Engullidor y decapítalo.\n\nLleva la cabeza de Engullidor a Karl Boran en Puerto de Menethil.", description = "Los múrlocs están emergiendo de las profundidades y construyendo sus aldeas en la costa. Están acosando a nuestros pescadores y mercaderes, y es necesario detenerlos.\n\nEngullidor, uno de esos múrlocs, anda con otros múrlocs Branquiazul y asalta a los mercaderes que pasan por el camino, regresando después a la seguridad de sus casitas. Nuestros mercaderes están amenazados y tenemos que darles seguridad.\n\nEngullidor acecha el río hacia el norte de aquí. Encuéntralo y acaba con él y sus semejantes. Tráeme su cabeza.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][287] = {title = "Poblado Peloescarcha", objective = "Explora el Poblado Peloescarcha y mata a 5 rebanacabezas Peloescarcha para Senir Barbablanca de Kharanos.", description = "Llevo mucho retraso con mi informe y me vendría bien tu ayuda, <nombre>. Conseguí averiguar dónde se esconden los trols, pero vi tantos de ellos que me dio miedo entrar.\n\nPor eso... necesito que entres en la cueva, eches un vistazo y mates a algunos de los trols. Luego vuelves aquí.\n\nSigue la carretera norte que sale de Kharanos, cuando llegues al puente, sigue el río helado hacia el oeste hasta que llegues al Lago Glacial. En la orilla oeste encontrarás Las Birras. La cueva está al suroeste del poblado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Rodela de piedraToga de invierno cálidaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][288] = {title = "La Tercera Flota", objective = "Compra un cántaro de hidromiel para el contramaestre Fistimos.", description = "En su día fui contramaestre del Dueña de las olas, una nave de alto bordo de la Tercera Flota de Kul Tiras. La flota maldita. Maldita, porque en su último viaje fue atacada por dragones rojos. ¡Dragones controlados por orcos!\n\nNo teníamos ninguna oportunidad contra el fuego de los dragones... y nuestra flota ardió y se hundió en esta costa. Soy el único superviviente de todas esas desgraciadas naves...\n\n... ¡Oh me va a estallar la cabeza! Tengo que beber algo fresco si quiero acabar con esta resaca y seguir con mi historia.", progress = "Oh, ¡tengo mucha sed! ¿No quieres comprarle algo de beber a este pobre y lamentable idiota?", completion = "¡Ah! Ah, me sienta de perlas y suelta la lengua. ¡Gracias colega!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][289] = {title = "La tripulación maldita", objective = "Mata 13 marineros malditos, 5 marinos malditos y al contramaestre Snellig. Lleva la tabaquera de Snellig al contramaestre Fistimos en Puerto de Menethil.", description = "<Algo recuperado Fistimos sigue contando su historia...>\n\nSoy el único superviviente de la Tercera Flota de Kul Tiras, naufragada en la costa del Norte. ¡Pero aunque soy el único miembro de la flota que sigue con vida, no soy el único que sigue por aquí! Uno de nuestros barcos ocultaba un gran y terrible tesoro y su espeluznante poder tiene atrapadas las almas de mis hermanos entre los descompuestos cascos de los barcos.\n\nSi quieres liberar a algunos de mis hermanos tal vez puedas romper su maldición.", progress = "¡En mis sueños a veces escucho los gemidos de mis hermanos! Por favor señor, libéralos de sus ataduras y termina con sus lamentos.", completion = "Muchas gracias, &lt;nombre&gt;. Recibe también la gratitud de mis hermanos malditos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][290] = {title = "Purga de la maldición", objective = "Obtén la llave de la caja fuerte de El Intrépido del capitán Halyndor.\n\nUtiliza la llave para abrir la caja fuerte de El Intrépido.", description = "Para romper la maldición y liberar a todos mis hermanos, hay que recuperar y purificar la... cosa... que guardaba mi barco. No sé lo que era, pero sé que estaba almacenada en la caja fuerte del barco. El capitán Halyndor era el único que tenía la llave.\n\nMi buen capitán sigue presente en mis sueños. Sé que sigue en el barco, El Intrépido. Hazte con la llave y utilízala para abrir la caja fuerte de El Intrépido.\n\nEntonces, cuando tengas esa maldita cosa, llévasela al sacerdote Glorin Frenteacerada en la ciudad.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][294] = {title = "La venganza de Ormer", objective = "Ormer Trenzaferro de la Excavación de Whelgar quiere que mates 10 estridadores jaspeados y 10 raptores jaspeados.", description = "La situación es grave, ciertamente. Cuando descubrimos estos huesos acudieron los raptores, atraídos por ellos. Esas bestias inmundas mataron a mis hermanos y nos atraparon a mí, a Merrin y al pobre prospector.\n\nLimpia Los Humedales de esos raptores, <nombre>. Encontrarás raptores jaspeados y estridadores jaspeados al oeste de este risco. Mata 10 ejemplares de cada, si puedes.\n\nSerá un buen comienzo para la venganza que he planeado.", progress = nil, completion = "Matar es un negocio sucio, pero has hecho muy bien tu trabajo, &lt;nombre&gt;. Si no tuviera que permanecer junto al prospector y a Merrin estaría a tu lado vertiendo sangre.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][295] = {title = "La venganza de Ormer", objective = "Ormer Trenzaferro quiere que mates 10 raptores segadores jaspeados y 10 raptores tajobuches jaspeados y que vuelvas a verle en la Excavación de Whelgar.", description = "Ha llegado el momento de que esos pavorosos raptores lamenten su sed de sangre. Aquí debajo podrás encontrar decenas de segadores jaspeados y tajobuches jaspeados. Haz pagar todas sus deudas a esas terribles criaturas matando a 10 de cada clase.", progress = nil, completion = "¡Hiciste un trabajo fenomenal eliminando a esos raptores, &lt;nombre&gt;!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][296] = {title = "La venganza de Ormer", objective = "Ormer Trenzaferro de la Excavación de Whelgar quiere que mates a Sarldente y que le lleves una de sus garfas cuando completes la tarea.", description = "Mientras estabas ahí abajo pude observar que una de esas bestias destacaba sobre el resto. Era más grande y amenazadora. Apuesto a que es la que condujo hasta aquí al resto para atacar la excavación.\n\nTe pido una última tarea, <nombre>. Hay que hacer justicia con ese Sarldente, y de acuerdo a la gravedad de sus crímenes, justicia no significa otra cosa que pena de muerte. Tráeme una de sus garras como prueba de su muerte.", progress = "¿Está muerto Sarldente? ¿Has redimido la memoria de los caídos?", completion = "Gracias, &lt;nombre&gt;. No olvidaremos tus esfuerzos. Muchos enanos inocentes murieron en este lugar mientras se limitaban a hacer su trabajo. Has hecho que la venganza caiga sobre esas malvadas criaturas. Se lo pensarán dos veces antes de volver a atacar a los súbditos del rey Magni.", rewards = "Fin de raptorArmadura AterraptorVara de excavaciónRecibirás:\n\nReceta: tortilla con un sabor curioso"}
MultiLanguageQuestData['mx'][297] = {title = "Recoger ídolos", objective = "Lleva 8 ídolos de piedra grabados a Magmar Ceñimal en la Excavación de Vetaferro.", description = "Hace poco, justo antes de que los troggs emergieran en esta excavación, descubrimos una gran cantidad de extraños ídolos grabados. Pero no tuvimos oportunidad de estudiarlos, ya que poco después del descubrimiento ¡los troggs nos echaron de las ruinas! Y esos ídolos tienen un efecto extraño en ellos. ¡Los vuelven locos!\n\nTráeme 8 ídolos: quiero estudiarlos, ¡y quiero quitárselos a los troggs! Encontrarás los ídolos si buscas a troggs que infestan la zona.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Hacha de ThelsamarPalo de fuego enanoCercenadora troggMaza de piedra grabadaChanclos de troggCoraza de ThelsamarRecibirás:\n\n"}
MultiLanguageQuestData['mx'][298] = {title = "Un informe sobre el avance de la excavación", objective = "Lleva el informe de Vetaferro a Jern Cornamenta a Thelsamar.", description = "Tengo que enviar un informe a Thelsamar. ¡Eso, e insistir en mi pedido de pólvora! Este es el informe. Llévaselo a Jern Cornamenta, es nuestro contacto en Thelsamar.\n\nNo es un encargo difícil, pero no tengo a nadie más para hacerlo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][299] = {title = "Desvelando el pasado", objective = "El prospector Whelgar quiere que te adentres en la excavación en busca de los 4 fragmentos de tablilla perdidos: Ados, Modr, Golm y Neru.", description = "Justo antes de la invasión descubrí una tablilla, era la llamada piedra Goaz. El texto traducido se interrumpe en cuatro puntos. Se habla de un \"plan divino\" y de una \"profecía maldita.\"\n\nTemo que nos estemos quedando sin tiempo. Soy demasiado viejo para ir a enfrentarme con esas bestias. Pero tú eres fuerte.\n\nRegistra la excavación y encuentra los 4 trozos perdidos de la tablilla: Ados, Modr, Golm y Neru. Búscalos en artefactos antiguos o donde veas tierra suelta. ¡Tráemelos y podré empezar a descifrar este misterio!", progress = "¿Ya has descubierto los cuatro trozos, <nombre>? Ados, Modr, Golm y Neru...", completion = "¡Ah, la piedra Goaz está completa! Buen trabajo, &lt;nombre&gt;. Buen trabajo, sin duda. Ahora puedo seguir con la trascripción de este escrito de los titanes. ¡Ya puedo descifrar nuevas palabras! Umm... aquí dice, \"Dioses antiguos... encadenados bajo la tierra.\" Esto debe ser el comienzo de algún relato épico.", rewards = "Recibirás:\n\nManto de Gamn de seda"}
MultiLanguageQuestData['mx'][303] = {title = "La guerra contra los Hierro Negro", objective = "Motley Garmason de Dun Modr quiere que mates 10 enanos Hierro Negro, 5 tuneladores Hierro Negro, 5 saboteadores Hierro Negro y 5 demoledores Hierro Negro.", description = "La guerra arde aquí en casa y en el extranjero. Mientras los grandes soldados enanos dan sus vidas en tierras lejanas en nombre de la Alianza, nuestras propias tierras caen víctimas de la depravación de los enanos Hierro Negro. Arrasaron el Puente Thandol y Dun Modr cayó poco después.\n\nTe necesitamos para reunir fuerzas y hacer retroceder el frente. Si puedes matar a 10 enanos Hierro Negro, 5 tuneladores, 5 saboteadores y 5 demoledores, tal vez la reserva consiga llegar a tiempo para terminar la ofensiva.\n\n¡Date prisa!", progress = nil, completion = "Cumples bien tus órdenes, &lt;clase&gt;. Has demostrado ser un valiente soldado y un leal servidor del rey Magni, ¡te rindo homenaje! Gracias a la presión que ejerciste sobre el campamento Hierro Negro tenemos ahora una oportunidad para expulsarlos definitivamente de nuestras tierras... si tan solo aparecieran las condenadas fuerzas de reserva...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][304] = {title = "Una misión hedionda", objective = "Mata a Balgaras el Hediondo y lleva su oreja a Largatrenza el Nefasto a las afueras de Dun Modr.", description = "Muchos de mis soldados murieron en la batalla de Dun Modr. Mi propio hermano murió cuando fue destruido el Paso Oeste del Puente Thandol. Sí señor, los enanos Hierro Negro son una raza diabólica. A partir de lo que Roggo pudo reunir, el líder de matones en Los Humedales es un brujo llamado Balgaras el Hediondo. Es un auténtico cobarde, que envía a sus soldados para que cumplan sus órdenes y él se queda escondido en Cerro Fraguaferoz, al sureste.\n\nSi puedes encontrar a esa escoria escurridiza, mátalo y tráeme su oreja. Sabré recompensarte, <clase>.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Escudo de león de oroPodrás elegir una de estas recompensas:\n\nAnillo tranquilo\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][305] = {title = "La búsqueda del equipo de excavación", objective = "Tarrel Tejepiedra quiere que viajes a la Excavación y que contactes con Merrin Tejepiedra.", description = "¡Oh, debes ser <el explorador enviado/la exploradora enviada> por Largatrenza! No puedes imaginar lo preocupado que he estado.\n\nDurante un mes, mi mujer, Merrin, me ha estado enviando cartas cada semana. Forma parte del equipo de la Excavación de Whelgar, pero hace casi dos semanas que he dejado de recibir sus cartas. ¡Seguro que algo va mal!\n\nLargatrenza dijo que si no recibíamos noticias del equipo enviaría a un explorador para comprobar cómo va todo. Supongo que tú eres ese explorador, <nombre>. ¡Busca a Merrin en la excavación, al Este!", progress = nil, completion = "Oh, ¡loados sean los cielos! ¡Estás aquí!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][306] = {title = "La búsqueda del equipo de excavación", objective = "Lleva la nota de Merrin a Tarrel Tejepiedra al Puerto de Menethil, en Los Humedales.", description = "¡Fue horrible! Estábamos desenterrando unos extraños artefactos cuando dimos con estos grandes huesos.\n\nAntes de poder saber qué sucedía, los raptores jaspeados inundaron la excavación. Se perdieron muchas vidas.\n\nOrmer... tan valiente... nos salvó al prospector y a mí. Nos defendió mientras corríamos a buscar refugio. Ahora estamos atrapados y todo nuestro trabajo está perdido.\n\nToma, lleva esta nota a mi querido Tarrel. En ella le explico cuál es nuestra situación.", progress = "¿Has podido encontrar a Merrin? ¿Ha enviado algún mensaje?", completion = "¡Qué noticias tan horribles! Al menos tres sobrevivieron. ¿Cuándo terminarán las muertes? Anhelo el día en el que los súbditos del rey Magni puedan vivir libres de miedo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][307] = {title = "Zarpas asquerosas", objective = "Ve a la Mina de Fuenteplata y recoge 6 cargas de equipamiento de minero. \n\nLuego ve a ver al montaraz Pico Tormenta.", description = "La Mina de Fuenteplata, que cae al este, se agotó hace tiempo. La Liga de Mineros la usaba como almacén, pero ahora se han instalado unos kóbolds allí, ¡con esas magníficas herramientas enanas a su alcance!\n\nLos expulsaremos, pero la Liga quiere que vaya alguien a recoger el material antes de que lleguemos los soldados a romperlo todo. Es muy arriesgado; será mejor que lleves compañía.\n\nEl material está en unas cajas con la marca de la Liga de Mineros a lo largo de la mina. Suerte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Rodela de placas de hierroToga del VigilanteCota de malla coraceroPata inmundaEscudo de corriente de plataCapa de malla coraceroRecibirás:\n\n"}
MultiLanguageQuestData['mx'][309] = {title = "Proteger el envío", objective = "Protege a Huldar y la caravana Vetaferro y luego informa al prospector Vetaferro.", description = "Tenemos que llevar esta pólvora a Vetaferro, pero este carro no va a ninguna parte. Es una carga muy pesada y esta zona es peligrosa. Además, quién sabe qué más nos tienen reservado los Hierro Negro ahora que Saean está con ellos.\n\nMe tranquilizaría bastante que me ayudases a vigilar. Miran puede descargar los barriles de pólvora en el campamento mientras tú y yo protegemos el carro.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Brazales ruinesGuantes de supervisorMusleras VetaferroRecibirás:\n\n"}
MultiLanguageQuestData['mx'][310] = {title = "Rivales acérrimos", objective = "Ve al sótano de la Destilería Cebatruenos de Kharanos y sustituye un barril de cerveza del Trueno con uno de brebaje de Cebadiz.", description = "Tengo que reconocer que esos Cebatruenos preparan unas bebidas estupendas. ¡Pero hay que bajarles los humos! ¡La suya no es la única bebida decente del mundo! Quizás tú puedas ayudarme a darles una lección...\n\nTen, llévate este barril de brebaje de Cebadiz. Cuélate en el sótano de la Destilería Cebatruenos de Kharanos y cámbialo por uno de sus barriles de Cerveza del Trueno. ¡Y ya veremos qué brebaje les gusta más a los clientes!\n\nY si encuentras guardias vigilando los barriles, intenta distraerlos...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][312] = {title = "La reserva robada de Tundra MacGrann", objective = "Ve a la cueva del Viejo Barbahielo y recupera la carne seca de Tundra MacGrann de la caja fuerte robada.", description = "Tenía carne seca para un mes, salada y bien guardada para la estación fría. ¡Estaba bajo llave para que los osos no se la comieran! Pero cuando salí a cazar ciervos, esa bestia, el Viejo Barbahielo, se las arregló para romper la cerradura. Eso sí, no podrá con el torio, seguro. Claro que yo me moriré de hambre si no recupero mi carne.\n\nSeguro que tú te mueves con más sigilo que yo. ¿No podrías ir a recuperar mi alijo? Con esta pierna coja no conseguiré entrar y salir de esa cueva con suficiente rapidez.", progress = "¿Conseguiste entrar en mi almacén de carne, <nombre>?", completion = "¡Qué amabilidad la tuya, &lt;nombre&gt;! ¡Y qué valor! Gracias a ti no me moriré de hambre cuando llegue la estación fría.", rewards = "Brazales de hierro forjadoMitones de lanaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][313] = {title = "Vigilando desde lejos", objective = "Comunica las órdenes del capitán Tharran al montaraz Dunstan, al montañero Lewin y al montañero Valgrum en El Cubil Pardo.", description = "El Cataclismo ha llevado hordas de troggs a la superficie, algo que ha obligado a los trols Peloescarcha a huir para salvar sus vidas. Por desgracia, han decidido establecerse frente a nuestro hogar y crearnos problemas.\n\nHe enviado al montaraz Dunstan y su pelotón a El Cubil Pardo, al suroeste de la ciudad, para que echen un ojo a los wendigos que viven allí, pero ahora necesito avisarlos para que vuelvan a Kharanos. Encuéntralos, diles que desplieguen los robots de observación remota que nos dieron los gnomos y que vuelvan a Kharanos.", progress = "Ey, <nombre>. ¿Ya has ido al Cubil Pardo? Esos wendigos pueden ser feroces.", completion = "Ah, sí, ¡estas crines funcionarán a la perfección! Tienes agallas, &lt;clase&gt;, apuesto a que harás cosas fascinantes en el futuro.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][314] = {title = "La protección del rebaño", objective = "Consigue el colmillo de Vagash.", description = "Oímos los gritos en medio de la noche. Y esta mañana faltaban dos cabezas de ganado. Esa ruin bestia conocida como Vagash ha estado alimentándose de nuestro sustento. Con la mayoría del ejército de Forjaz mermado, no queda nadie para mantener a raya a Vagash.\n\nQuizás tú tengas el valor necesario para buscar a ese animal y matarlo. Tráeme uno de sus colmillos y te daré una recompensa. Vagash acecha desde encima de este rancho. Ten cuidado, es peligroso.", progress = "¡Vagash sigue aterrorizando al ganado! Ayúdanos, por favor, ¡mata a esa maldita bestia!", completion = "¡Muy bien hecho! Veron se pondrá muy contento cuando oiga la noticia. Matar a Vagash no es tarea fácil. Imagino que un día combatirás en el frente de la Alianza, entre los hombres del rey el Magni.", rewards = "Túnica de cuero duroCalzas de rancheroJubón de ráfaga de VagashRecibirás:\n\n"}
MultiLanguageQuestData['mx'][315] = {title = "La cerveza perfecta", objective = "Llévale 7 cardaluz a Rejold Cebadiz en Kharanos.", description = "Mi misión consiste en conseguir la cerveza perfecta. Sé que puedo hacerlo, llevo la cebada en la sangre. Solo tengo que encontrar la receta adecuada...\n\nLos trols Peloescarcha cultivan una planta llamada cardaluz en lo alto de Monte Luz, al noroeste. La utilizan para rituales extraños y tribales. Nosotros los enanos casi no la usamos, pero tiene un sabor único... y quisiera experimentar con él en mis cervezas.\n\nConseguir el cardaluz puede ser peligroso, pero pagaré bien por lo que \"cojas prestado\" de las canastas del poblado trol.", progress = "¿Tienes la cardaluz ya? Ya casi tengo todo listo para la próxima cerveza y quisiera probar esa plantita en la mezcla.", completion = "¡Genial! Estoy deseando utilizarla en mis recetas. Estoy pensando en una en concreto a la que le irá de maravilla.", rewards = "Brazales tejidos con hiedraBotas cardaluzGuanteletes manchados de hierbaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][317] = {title = "Los suministros del reactor a vapor", objective = "Reúne 4 trozos de carne de jabalí y 2 pelajes de oso grueso y llévaselas al piloto Bramiz al Almacén de Brasacerada.", description = "Me estoy preparando para empezar una misión para la Brigada de Asedio. Es una misión larga y tengo que cargar un mes de suministros en mi reactor a vapor. Así que, mientras Brasacerada trabaja en mi tanque, quizás podrías ir de caza por mí...\n\nNecesito pieles para hacerme una cama y carne para comer. Puedes cazar jabalíes para la carne y osos para las pieles... ve a los campos nevados que hay al sur de El Cubil Pardo.", progress = "Los preparativos van bien. ¿Cómo va tu caza?", completion = "Por la barba de Magni, ¡sí que has cazado! Gracias, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][318] = {title = "La tajada", objective = "Consigue un tonel de tajada de Rejold Cebadiz de Las Birras.", description = "Rejold Cebadiz experimenta con sus brebajes. Algunos saben bien, otros mal y otros... bueno, esos tumbarían al enano más fuerte.\n\nVive en Las Birras, al oeste de Kharanos. Y lo que quiero es una de sus bebidas: tajada. Me mantendrá caliente en los caminos más fríos.\n\nY... ¡ese bendito líquido quema tanto que también puedo usarlo para aumentar la potencia de mi reactor a vapor! Me ha sacado de un apuro más de una vez.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][319] = {title = "Un favor a cambio de un barril de tajada", objective = "Mata a 6 osos zarpahelada, 8 jabalíes del risco mayores y 8 leopardos de la nieve y luego vuelve a Las Birras con Rejold Cebadiz.", description = "Tengo un tonel de tajada, pero... ¿podrías hacerme un favor? En Las Birras vendría bien un poco de ayuda con los animales salvajes que deambulan por las nieves de los alrededores. A veces se acercan demasiado.\n\nNo es que tengamos miedo de los osos, los gatos ni los jabalíes... ningún enano que se precie lo tiene. Pero si tú pudieras ocuparte de esos animales, tendríamos más tiempo para trabajar y hacer cerveza.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][320] = {title = "Regresa junto a Bramiz", objective = "Entrega el tonel de tajada al piloto Bramiz en el Almacén de Brasacerada.", description = "Aquí tienes tu tonel de tajada, <nombre>. Y, una vez más, gracias por la caza.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Bastón corto nudosoHacha afiladaCuchillo de acampadaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][323] = {title = "Pon a prueba tu valor", objective = "Mata a 15 asaltantes esqueléticos, 3 sanadores esqueléticos y 3 depositarios esqueléticos y vuelve a donde Sven.", description = "Morbent Vil es un nigromántico y un aliado de los Jinetes Oscuros. Te enfrentaría al poder de Morbent Vil, pero no te enviaré a luchar contra ese demonio sin conocer tu fuerza.\n\nYa me has probado tu valentía pero, si de verdad quieres enfrentarte al nigromántico, tendrás que probar primero que puedes derrotar a sus esbirros.", progress = nil, completion = "Tu habilidad en combate, &lt;nombre&gt;, es indiscutible. ¡Y tu resolución podría ayudarnos a presenciar el final de Morbent Vil!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][325] = {title = "Armado y listo", objective = "Lleva la Pesadilla de Morbent a Sven en el Bosque del Ocaso.", description = "Aquí tienes el arma para vencer al demonio ese del que me hablaste. Ya estás <preparado/preparada>, <nombre>. Te deseo mucha suerte, ¡y esperaré con ansia escuchar la leyenda de tu gloria!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][331] = {title = "Informa a Doren", objective = "Habla con el teniente Doren.", description = "¿Te pidió el teniente Doren que volvieses a informarle sobre las patrullas?", progress = nil, completion = "Me duele descubrir que fue Merle quien nos traicionó. Siempre ha sido un buen soldado y yo creí en su lealtad. Pero me alivia haberle descubierto... con un espía como él entre nosotros... no habríamos durado mucho contra el coronel Kurzen.", rewards = "Espaldares de metal escarchadosSandalias para la selvaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][332] = {title = "Publicidad de la bodega", objective = "Ve a la Bodega Galina y lleva a Suzetta Galina el cupón de vino para una botella gratis.", description = "Si hablas sobre vino con alguien, sabrás que nosotros, los Galina, vendemos el mejor vino de Ventormenta. Y no estamos lejos, seguimos en el Distrito de Mercaderes, en los preciosos canales de la ciudad.\n\nToma, agarra este panfleto. Llévaselo a mi hermana Suzetta a nuestra tienda, a cambio te dará una botella de regalo de nuestro famoso pinot noir. ¡No lo lamentarás!", progress = "Saludos y bienvenido, señor. ¿Has probado ya alguno de nuestros vinos?", completion = "¿Entonces has visto a Renato? Aquí estamos, caballero. Una botella de nuestro pinot noir especial. ¡No encontrarás nada mejor en todo Azeroth!", rewards = "Recibirás:\n\nBotella de Dalaran Noir"}
MultiLanguageQuestData['mx'][333] = {title = "Harlan necesita un nuevo suministro", objective = "Ve a Trajes y Arreglos a Medida y lleva a Rema Schneider el paño que ha pedido Harlan Bagley.", description = "Últimamente el negocio ha ido bien. Parece que todo el mundo está comprando armaduras y ropas resistentes. Es casi como si esperasen una época dura y fría...\n\nPero esas son preocupaciones futuras. Mi preocupación del día es que me estoy quedando sin ropas tejidas que vender. Necesito otro cargamento de nuestro suministrador.\n\nSi puedes llevar este pedido a Rema Schneider en Trajes y Arreglos a Medida, te lo agradecería mucho.", progress = "¿Traes noticias de Bagley?", completion = "Dice aquí que el negocio de Harlan está floreciendo. Me alegra oír eso, pero me pregunto por qué la gente necesita tantas armaduras. No he oído nada sobre una declaración de guerra... ¿Acaso los nobles nos están ocultando información? \n\nEn fin, gracias por traer el pedido. Aquí tienes el pago, me encargaré de que Harlan reciba sus suministros.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][334] = {title = "Un paquete para Thurman", objective = "Ve a Diseños Larson en el Barrio de los Magos de Ventormenta y entrega a Thurman Schneider sus herramientas de coser.", description = "Mi hijo Thurman es un aprendiz en Diseños Larson, en el Barrio de los Magos. Hoy salió con prisa y se olvidó su trasquiladora y las agujas. Sé que <un gran/una gran> <clase> como tú debe de tener importantes tareas entre manos, ¡pero sin sus herramientas, Thurman no puede hacer su trabajo de aprendiz!\n\nPor favor, <nombre>. ¿Podrías llevar las herramientas de coser a mi hijo? Diseños Larson es una de las dos tiendas de ropa en el Barrio de los Magos, la que está más al fondo, cerca de la torre de los magos.", progress = "¿Has venido a comprar ropa?", completion = "¡Oh, maldición! Creí que al haberme olvidado las herramientas, no tendría que trabajar. Aunque supongo que ahora tendré que ayudar a los Larson cosiendo... \n\nEn fin... Supongo que tendré que esperar hasta más tarde para divertirme.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][335] = {title = "Una noble cerveza", objective = "Zardeth de los Zarpanegra, quiere que le lleves una lágrima de Tilloa de Villa Oscura y una zibética de Los Humedales.", description = "Lord Wishock está causando gran agitación en la Casa de Nobles. Se ha enterado de lo de nuestro pequeño \"establecimiento\" aquí abajo y está presionando para que se realice una investigación en toda regla. Tengo un plan para mantener a Wishock \"preocupado\", pero necesito tu ayuda.\n\nEn el Jardín de Stalvan, a las afueras de Villa Oscura, crece una flor. Esta pequeña flor blanca es conocida como la lágrima de Tilloa. También necesitaré una zibética, que solo se puede encontrar en la base de las cascadas bajo la Presa de las Tres Cabezas, en Los Humedales.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][337] = {title = "Un libro viejo de Historia", objective = "Devuelve el libro: La Historia de Ventormenta a La Biblioteca de Ventormenta.", description = "Aunque la cubierta de este libro está llena de arañazos y de barro, aún se pueden leer las palabras del lomo: La Historia de Ventormenta. Al abrir el libro se ve claramente el sello de la biblioteca de Ventormenta en la primera página.\n\nParece que alguien sacó este libro y no lo llegó a devolver...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][338] = {title = "Las verdes colinas de Tuercespina", objective = "Reúne las páginas perdidas del manuscrito Las verdes colinas de Tuercespina. Cuando los cuatro capítulos estén completos, llévaselos a Barnil.", description = "¡Oh, el maestro Nesingwary se sentirá muy disgustado si lo descubre!\n\nConfiaba en mí para revisar el manuscrito de su novela, Las verdes colinas de Tuercespina. Todo iba bien, pero un golpe de viento pasó por el campamento y las páginas quedaron dispersas por todas partes.\n\nConseguí reunir la mayor parte de las páginas, pero hay muchas todavía por la jungla. Reúne las páginas para completar los cuatro capítulos.\n\nYo te ayudaré a organizarlas. Devuélveme los capítulos cuando tengas los cuatro.", progress = "¿Tienes ya los capítulos, <nombre>?", completion = "Me has ahorrado muchos problemas, &lt;nombre&gt;. No sé cómo agradecértelo. ¡No tardaremos mucho en ver el libro del maestro Nesingwary en las bibliotecas de todo el mundo!", rewards = "Recibirás:\n\nPoción de sanación excelenteRefuerzo para armadura gruesoBotas de la selva"}
MultiLanguageQuestData['mx'][339] = {title = "Capítulo I", objective = "Lleva las páginas 1, 4, 6 y 8 de Las verdes colinas de Tuercespina de Nesingwary a Barnil Jarropetra para completar el capítulo I.", description = "¡El capítulo I es fascinante! El maestro Nesingwary establece el telón de fondo de la historia y menciona a sus compañeros de caza, ¡incluyéndome a mí!\n\nPero eso no viene al caso. Déjame ver las páginas que faltan. Parece ser que las páginas 1, 4, 6 y 8 siguen todavía por algún lado en la jungla.", progress = "¿Supongo que no has conseguido las páginas 1, 4, 6 y 8? Necesitamos esas cuatro para completar el capítulo I.", completion = "¡Al fin! El capítulo I está completo.", rewards = "Recibirás:\n\nLas verdes colinas de Tuercespina: Capítulo I"}
MultiLanguageQuestData['mx'][340] = {title = "Capítulo II", objective = "Lleva las páginas 10, 11, 14 y 16 de Las verdes colinas de Tuercespina de Nesingwary a Barnil Jarropetra para completar el capítulo II.", description = "El capítulo II está lleno de historias excitantes sobre la caza de panteras y tigres. ¡Me patearía la cara por haber dejado que las páginas volaran!\n\nParece ser que conseguí recuperar todas las páginas menos las 10, 11, 14, y 16.", progress = "Seguimos necesitando las páginas 10, 11, 14 y 16 para completar el capítulo II, <nombre>.", completion = "El capítulo II está completo. ¡Bien hecho!", rewards = "Recibirás:\n\nLas verdes colinas de Tuercespina: Capítulo II"}
MultiLanguageQuestData['mx'][341] = {title = "Capítulo III", objective = "Lleva las páginas 18, 20, 21 y 24 de Las verdes colinas de Tuercespina de Nesingwary a Barnil Jarropetra para completar el capítulo III.", description = "El capítulo III es mi favorito. Habla de la primera caza de Sir Erlgadin y Lady Rouack con un rifle enano. Y, al final del capítulo III, ¡menudo suspense!\n\nMe parece que todavía necesitamos las páginas 18, 20, 21 y 24 para terminar el capítulo. Esas páginas están ahí fuera, en algún lugar...", progress = "¿Has tenido suerte con las páginas 18, 20, 21 o 24? Son las únicas que faltan para completar el capítulo III.", completion = "¡Puff! Buen trabajo, &lt;nombre&gt;. El capítulo III está completo.", rewards = "Recibirás:\n\nLas verdes colinas de Tuercespina: Capítulo III"}
MultiLanguageQuestData['mx'][342] = {title = "Capítulo IV", objective = "Lleva las páginas 25, 26, y 27 de Las verdes colinas de Tuercespina de Nesingwary a Barnil Jarropetra para completar el capítulo IV.", description = "Ah, el capítulo IV, ¡el gran final! ¡Y menudo final!\n\nSolo nos faltan tres páginas de este capítulo. Necesitamos las páginas 25, 26 y 27 para finalizar el capítulo IV.", progress = "Solo necesitamos tres páginas para acabar el capítulo IV, <nombre>. ¿Tienes las páginas 25, 26 o 27?", completion = "¡Excelente! ¡Ya tenemos el capítulo IV!", rewards = "Recibirás:\n\nLas verdes colinas de Tuercespina: Capítulo IV"}
MultiLanguageQuestData['mx'][343] = {title = "Hablando de entereza", objective = "Ve al Archivo Real en el Castillo de Ventormenta y habla con Milton Gavilla. Podrá encontrar el libro sobre metalurgia que el hermano Kristoff necesita para su charla.", description = "Voy a dar un discurso sobre la fortaleza de espíritu y me gustaría recitar unos pasajes de un libro sobre metalurgia, \"La tensión del hierro\". En el Archivo Real, en el Castillo de Ventormenta debería haber una copia del libro. ¿Podrías ir a buscarlo para mí? Si lo haces, ¡que las bendiciones de la Luz te acompañen!\n\nEl Archivo Real es enorme, pero el bibliotecario jefe, Milton Gavilla, conoce todas las estanterías como la palma de su mano. Habla con él, te dará el libro.", progress = nil, completion = "¿Metalurgia? Ah, sí, tenemos muchos libros sobre eso. Estoy encantado de poder ayudar al hermano Kristoff con su discurso. Y ahora... ¿Qué libro en particular necesita el buen hermano?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][344] = {title = "Hermano Paxton", objective = "Habla con el hermano Paxton en la Abadía de Villanorte.", description = "¿La tensión del hierro? Sí, conozco el libro. Es bastante bueno, lo escribió el minero enano Margulf Blaggon hace unas décadas. Pasó la mayor parte de su vida en las profundidades de Khaz Modan, extrayendo minerales. ¡Un tipo listo!\n\n¿Por dónde iba? ¡Oh, sí, La tensión del hierro! Me temo que el libro se llevó a la Abadía de Villanorte. El custodio de la biblioteca de la Abadía, el hermano Paxton, quería hacer una copia del libro para su biblioteca.\n\nPero eso fue hace meses. Me pregunto por qué estará tardando tanto...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][345] = {title = "Suministros de tinta", objective = "Habla con el supervisor Olento en Villa del Lago y pregúntale sobre el mineral de hierro de Rethban.", description = "Quería terminar mi copia de La tensión del Hierro, pero...\n\nBueno, verás, hago mi propia tinta para los libros que copio. Es mi propia receta. No se corre ni mancha y se seca muy rápido. Por desgracia, ¡se seca demasiado rápido! La que me quedaba se secó antes de que pudiera acabar la copia y no he tenido oportunidad de hacer más tinta.\n\nPara hacer más, necesito mineral de hierro de Rethban, de las Montañas Crestagrana. El supervisor Olento, en Villa del Lago, es quien me lo suele suministrar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][347] = {title = "La mena de Rethban", objective = "Reúne 5 montones de mineral de hierro de Rethban y llévaselos al hermano Paxton en la biblioteca de Villanorte.", description = "La mena de Rethban tiene ese nombre por el hombre que lo descubrió, Bart Rethban. Cuando se funde, no es tan fuerte como el hierro, pero tiene un color oscuro que algunos escribas utilizan en sus tintes. Se puede encontrar en las Cavernas de Rethban, al norte de aquí.\n\nGeneralmente lo tenemos almacenado, pero estamos demasiado ocupados preparándonos para los atacantes orcos que no hemos tenido tiempo de recogerlo. Y, además, los gnolls de Crestagrana viven ahora en las Cavernas de Rethban y sus esclavos se encargan de recoger el mineral.\n\nAsí que si necesitas recogerlo, tendrás que ir a por él.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][348] = {title = "La fiebre de Tuercespina", objective = "Busca al médico brujo Unbagwa y haz que invoque a Mokk el Salvaje. Lleva el corazón de Mokk a Fin Fizqueta.", description = "M... me... m... muero...\n\n... T... tengo la fiebre de Tuercespina... un virus m... mortal...\n\n... La única cura... es... comer el corazón de M... mokk el Salvaje... una esquiva bestia blanca...\n\n... El médico brujo Unbagwa... es el único que p... puede invocar...\n\n... Busca a Unbagwa en una cueva oculta en el cabo... del sur...\n\n... Rápido... m... me... muero...", progress = "... ¿Madre?\n\n... tanto frío...\n\n... hacia El Vacío Abisal... a-abrázame, madre...", completion = "... Siento que... la fuerza... vuelve a mí... \n\n¿Dónde estoy? ¿Bahía del Botín? ¡Cielos! He tenido un sueño de lo más extraño... \n\n... todavía me sigo sintiendo débil...", rewards = "Recibirás:\n\nManto medicinal"}
MultiLanguageQuestData['mx'][349] = {title = "La fiebre de Tuercespina", objective = "temp text 02 - log", description = "temp text 02 - description", progress = "El médico brujo Unbagwa sabe lo que gustar a Mokk el Salvaje. ¡Sí, sí!\n\nYo hablar con espíritus y hacer que venga, sí, sí.\n\nPero a otro espíritu de bestia-gorila gustar hablar con espíritus también. Tú proteger al médico brujo Unbagwa y yo hacer que él venir a ti.\n\nEl médico brujo Unbagwa querer algo primero. ¡Trae 10 colmillos de gorila y yo empezar a hablar con espíritus!", completion = "¡Al médico brujo Unbagwa gustarle colmillos de gorila! Por ti yo hablar con espíritus. Haz que venga Mokk el Salvaje. \n\nPero tú proteger al médico brujo Unbagwa de otra bestia gorila, ¡o no hay Mokk!", rewards = nil}
MultiLanguageQuestData['mx'][351] = {title = "¡Encontrar a OOX-17/TN!", objective = "Llévale el localizador de emergencia al robot mensajero de Oglethorpe.", description = "Has descubierto una especie de dispositivo metálico extraño con forma de huevo. Al tocar uno de sus botones el huevo cobra vida y descubres que se trata de algún tipo de artilugio robótico de invención gnómica. A continuación, una voz resuena en su interior.\n\n\"Mi nombre es Oglethorpe y he perdido a mi robot mensajero. Si lo encuentras te daré una recompensa. Por favor, llévale este localizador al robot. ¡Genial, acabo de obtener las coordenadas! ¡Parece que se estropeó cerca de Sima Abierta en Tanaris!\"", progress = "Parece que has descubierto los restos de... ¿un pollo robótico? La voz que proviene del huevo vuelve de nuevo a la vida:\n\n\"¡Sí, un trabajo excelente! Este es sin duda mi robot mensajero, aunque mis sensores indican que necesita un empujón para que pueda volar de regreso a Bahía del Botín para ser reparado. Coloca el localizador en el interior del robot. ¡El localizador hará todo lo demás!\"", completion = "Colocas el localizador de emergencia con forma de... huevo en el interior del... pollo robótico. \n\nMientras el robot lucha por ponerse en pie, se escuchan una serie de zumbidos provenientes de su interior. Cuando el robot cobra vida, se escucha una vez más la voz de Oglethorpe, en esta ocasión desde el interior del robot: \n\n\"OOX-17/TN funciona otra vez pero necesita ciertas reparaciones. Es demasiado pesado para que puedas traerlo... pero se me ocurre una idea. ¿Te apetece seguir cuidando de él?\"", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][353] = {title = "Una entrega a Pico Tormenta", objective = "Entrega el paquete Pico Tormenta al montaraz Pico Tormenta en Loch Modan.", description = "Los Pico Tormenta son unos enanos muy respetados y famosos por su exigente gusto. Así que no es sorprendente que Gringer Pico Tormenta, un montaraz de Forjaz, me encargara que forjara un arma para él.\n\nHe terminado el arma, pero... el montaraz Pico Tormenta está muy lejos, en Loch Modan. Si tienes planeado viajar al norte, ¿podrías entregarle este paquete?\n\nEl último mensaje que recibí del montaraz Pico Tormenta, decía que estaba estacionado en la torre de vigilancia del norte, en Loch Modan.", progress = "¿Has venido hasta aquí desde Ventormenta? He oído que las cosas se están poniendo feas en las tierras humanas, con forajidos y orcos campando a sus anchas. ¡Un lugar perfecto para que un <clase> demuestre su valía!", completion = "¡Ajá! ¿Así que Grimand ha terminado mi hacha por fin? ¡Me muero por probarla con algunos troggs y kóbolds! \n\nMuchas gracias, &lt;nombre&gt;. Has hecho un largo viaje para entregármela. Acepta unas monedas por tu trabajo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][354] = {title = "Muertes en la familia", objective = "Llévale los restos de Gregor, los restos de Nissa y los restos de Thurman a Coleman Farthing, que está en Rémol.", description = "Los Agamand eran una de las familias más prósperas de los Claros de Tirisfal. Yo solía trabajar en sus molinos... antes de la Peste.\n\nCuando la Plaga apareció por primera vez, los Agamand fortificaron su casa y convencieron a todos sus empleados para que se quedaran y les ayudaran a defenderse. Fuimos unos insensatos pero, al menos, fuimos unos insensatos leales.\n\nLos Agamand, a causa de su orgullo, nos abocaron a todos a la desgracia. ¡Y ahora son esbirros de la Plaga!\n\nSirve a los Renegados y derrota a los Agamand, que sucumbieron a la peste. Sírveme a mí y tráeme sus restos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][355] = {title = "Habla con Sevren", objective = "Habla con el magistrado Sevren de Rémol.", description = "Me has entregado los restos de los Agamand y con ello, has satisfecho mis deseos de venganza. Pero los Molinos de Agamand encierran una amenaza para todos los Renegados, no solo para mí.\n\nHe informado al magistrado Sevren acerca de tus hazañas contra los Agamand y desea hablar contigo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][356] = {title = "Patrulla de la retaguardia", objective = "Mata a 8 horrores sangrantes y a 8 espíritus deambulantes.", description = "En El Baluarte, debemos permanecer en alerta constante para proteger Tirisfal de las incursiones de la Plaga, pero, incluso a veces, consigue colarse.\n\nNuestro éxito en El Baluarte depende de una batalla de un solo frente. No podemos, pues, permitir un ataque desde la retaguardia ni dejar que corten la línea de abastecimiento de El Baluarte.\n\nPatrulla por el oeste y mata a todo miembro de la Plaga que encuentres. Céntrate sobre todo en la Hacienda Balnir, pues, parece que se ha convertido en el refugio de numerosos miembros de la Plaga.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][357] = {title = "La identidad del exánime", objective = "Llévale el libro de hechizos del exánime a Bethor Duroyelo en Entrañas.", description = "Hay un exánime que mora en la isla Lago Aguasclaras, en el norte. Aunque es un Renegado independiente, cree que los otros no-muertos son esclavos de la Plaga por lo que sus esbirros atacan a todo aquel que se acerca a él.\n\nPero, dado que es un Renegado, la Reina lo reclama. Y si tiene conocimientos de nigromancia, estos serán... muy útiles para nosotros.\n\nPara descubrir su identidad y talentos, debo ver su libro de hechizos. Irrumpe en su campamento, róbalo y tráemelo aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][358] = {title = "Profanadores", objective = "Mata a los asaltatumbas Putrepellejo y a los bastardos Putrepellejo. \n\nLlévale 8 icores embalsamantes al magistrado Sevren de Rémol.", description = "Las fosas comunes, al suroeste de la Granja de Garren situada hacia el norte de aquí, se hicieron para albergar la impresionante cantidad de cadáveres de aquellos que perecieron en Tirisfal cuando la Peste golpeó por primera vez.\n\nDe estas tumbas no había salido ni un solo no-muerto hasta el momento, pero ahora la Plaga envía a gnolls Putrepellejo a recoger cadáveres para que engrosen las filas de sus ejércitos. ¡Esto es inaceptable!\n\nTienes una doble tarea que cumplir: mata a los Putrepellejo de las fosas comunes y la Granja de Garren, y quítales el icor embalsamante que les da vida.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Botas de piel de zombiGuanteletes de acero fríoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][359] = {title = "Las obligaciones de los Renegados", objective = "Habla con la guardia de la muerte Linnea.", description = "Necesito conocer las últimas noticias de nuestro puesto del Guardia de la Muerte situado al este de aquí.\n\nTengo que saber si las fuerzas de la Plaga han pasado por El Baluarte y han entrado en Tirisfal. Debemos mantener la vigilancia en la frontera con las Tierras de la Peste pues no podemos permitir que la Plaga afiance su presencia aquí.\n\nViaja hacia el sur siguiendo el camino y cuando este se bifurque, continúa en dirección este hasta el puesto. Habla con la Guardia de la Muerte Linnea. Ella tiene la información que necesito.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][360] = {title = "Regresa junto al magistrado", objective = "Ve a ver de nuevo al magistrado Sevren de Rémol.", description = "Ahora llévale la información que te he dado al magistrado Sevren. Le gustará recibirla lo antes posible así que date prisa.\n\nY si ves a algún miembro de la Plaga por el camino, acaba con él. No podemos permitir que vaguen por nuestras tierras a su antojo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][361] = {title = "Una carta sin entregar", objective = "Encuentra a Yvette Farthing y entrégale la carta de Thurman Agamand.", description = "Esta carta la escribió Thurman, el hijo mayor de Gregor Agamand. Está dirigida a una tal Yvette Farthing, aunque parece que nunca llegó a recibirla...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][362] = {title = "Los molinos fantasma", objective = "Acaba con Devlin Agamand y llévale los restos de Devlin a Coleman Farthing en Rémol.", description = "Devlin Agamand era el más joven de los dos hijos de la familia Agamand y en vida ambos no podían ser más diferentes. Thurman era alto y amable mientras que su hermano pequeño era débil y tenía la lengua muy afilada.\n\nCuando la Peste llegó a los Molinos de Agamand, no me sorprendió de que Devlin sucumbiera casi de inmediato. Sus desbarres todavía pueden oírse cerca del camino que conduce a los Molinos de Agamand.\n\nEstoy recogiendo lo que queda de los Agamand y quiero al pobre Devlin. Encuéntralo, acaba con él y tráeme sus huesos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][363] = {title = "Desvelo brutal", objective = "Habla con el sacerdote de las Sombras Sarvis.", description = "Ya era hora de que despertaras. Estábamos a punto de arrojarte al fuego con los otros y, mira por dónde, ya no tenemos que hacerlo.\n\nSoy Mordo, el custodio de la cripta de Camposanto. Y tú ya no eres uno de los esclavos del Rey Exánime.\n\nHabla con el sacerdote de las Sombras Sarvis. Está en la capilla, al pie de la colina. Él te dirá lo que debes saber.\n\nPara salir de esta cripta, sube las escaleras hasta la superficie. Sigue el camino hasta la capilla para encontrarte con Sarvis.", progress = nil, completion = "Mm, otra muerta que camina... Ha debido de ser un shock... despertarse en la cripta con el frío y Mordo como única compañía... \n\nVeo en tu cara que estás muy confusa. Deja que te explique nuestra... situación. \n\nHemos sido liberados del control del Rey Exánime por nuestra nueva líder, Lady Sylvanas. La Dama Oscura nos guía en una guerra contra la odiada Plaga y contra los humanos que aún no aceptan la situación y nos acosan a cada paso.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][364] = {title = "Los autómatas", objective = "Mata a 5 zombis descerebrados y a 5 necrófagos desdichados.", description = "Desde que los primeros Renegados se arrastraron fuera de sus tumbas, hemos estado en guerra con el ejército de la Plaga del Rey Exánime: ejércitos de no-muertos reanimados mediante nigromancia, asquerosas bestias del norte, y espectros atormentados.\n\nEl Rey Exánime ya no ocupa el Trono Helado, pero la parte norte del poblado sigue estando invadida por sus esclavos. Destrúyelos, no muestres piedad, aunque sean nuestros antiguos hermanos y hermanas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de lienzoCapa maltrechaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][365] = {title = "Campos de pena", objective = "Roba 10 calabazas de la plantación que encontrarás en dirección oeste, justo al norte de Camposanto, y llévaselas al boticario Johaan a Rémol.", description = "¿Qué tenemos aquí? Pareces un poco <novato/novata>, <clase>. Si quieres demostrar tu valía a la Dama Oscura, tendrás que aprender los caminos de los Renegados.\n\nEncontrarás una plantación en dirección oeste. Los humanos infestan la tierra al igual que el moho un cuerpo en descomposición. Y lo que es peor, la Cruzada Escarlata vigila la zona desde su torre. Dales una lección a esos canallas y roba 10 de sus preciadas calabazas.\n\nCuando tengas 10, llévaselas al boticario Johaan a Rémol.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][366] = {title = "Devuelve el libro", objective = "Devuélvele el libro de hechizos de Gunther a su dueño, que se encuentra en la isla del Refugio de Gunther.", description = "Hace tiempo, Gunther y yo, junto con el ahora nigromántico de la Plaga Thule Corvozarpa, fuimos amigos y estudiamos juntos en el Kirin Tor (una sociedad de magos de Dalaran).\n\nTanto Gunther como yo sucumbimos a la Peste pero creí que él estaría muerto o sirviendo al Rey Exánime. ¡Es estupendo saber que está libre!\n\nTenemos que conseguir que se una a nosotros. He lanzado un hechizo sobre su libro de forma que, cuando lo vea, sepa que yo también estoy libre del Rey Exánime. Cuando se entere de esto, espero que se una a nosotros.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][367] = {title = "Una nueva Peste", objective = "El boticario Johaan de Rémol quiere que recojas 5 viales de sangre de can oscuro.", description = "Lady Sylvanas ha recurrido a la Sociedad Real de Boticarios. La Dama Oscura cree que nuestro conocimiento, unido a la recién descubierta magia, proporcionará la clave para derrotar a Arthas. Nos ha instado a idear una nueva peste, una peste mucho más mortífera que cualquier otra dolencia conocida en Azeroth. Esta nueva enfermedad llevará a la ruina al ejército de la Plaga de Arthas.\n\nMis estudios revelan que la clave podría estar en la sangre de las bestias. Tráeme 5 viales de sangre de can oscuro para que pueda comprobar mi teoría.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nElixir de sangre de trol débil"}
MultiLanguageQuestData['mx'][368] = {title = "Una nueva Peste", objective = "El boticario Johaan de Rémol necesita 5 escamas de Anca Vil de los múrlocs de los Claros de Tirisfal.", description = "Mientras recogías las muestras, me he dado cuenta gracias a mis experimentos de que serán necesarios más componentes para que esta nueva enfermedad se propague como es debido. Envenenar a unas cuantas víctimas es un juego de niños pero extender una plaga por todo un mundo es algo más complicado.\n\nNecesitaré 5 escamas de Anca Vil de los múrlocs de la zona. Encontrarás a estas criaturas en la costa hacia el norte o el oeste.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nArena de sueño"}
MultiLanguageQuestData['mx'][369] = {title = "Una nueva Peste", objective = "El boticario Johaan de Rémol quiere que le lleves 4 muestras de veneno de nocturácnida sañosa.", description = "Mientras recogías lo que te pedí, descubrí un viejo texto en uno de mis tomos que explica cómo una antigua peste arrasó con miles de víctimas inocentes. Más tarde se descubrió que el agente mortal de dicha peste estaba presente en el veneno de las nocturácnidas.\n\nTráeme un poco de veneno de una nocturácnida sañosa para completar este experimento. Quiero comprobar si el elemento contagioso presente en el veneno servirá para mi nuevo brebaje. Se dice que hay muchas arañas en los Claros de Tirisfal del Este.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFajín de aprendiz"}
MultiLanguageQuestData['mx'][370] = {title = "En guerra con la Cruzada Escarlata", objective = "El ejecutor Zygand de Rémol quiere que mates al capitán Perrine, a 3 zelotes Escarlata y a 3 misioneros Escarlata.", description = "Los documentos del ejecutor Arren contienen exactamente todos los detalles que necesitamos para erradicar la infestación humana de nuestras tierras. De acuerdo con esta información, la Cruzada Escarlata ha enviado al capitán Perrine y a una brigada a las ruinas de la torre situada al suroeste de Rémol.\n\nMata a Perrine, a 3 zelotes y a 3 misioneros y regresa aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][371] = {title = "En guerra con la Cruzada Escarlata", objective = "El ejecutor Zygand de Rémol te ha encargado que mates al capitán Vachon y a 5 frailes Escarlata.", description = "Seguimos en guerra y la Cruzada Escarlata se hace cada vez más fuerte. El informe que el ejecutor Arren me ha enviado indica que la Cruzada Escarlata ha estado atacando desde las ruinas de la torre situada al sudeste de Tirisfal, cerca de la Hacienda Balnir, bajo las órdenes del capitán Vachon.\n\nMata a Vachon y a 5 frailes Escarlata. ¡Será un duro golpe para la Cruzada!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][372] = {title = "En guerra con la Cruzada Escarlata", objective = "El ejecutor Zygand de Rémol quiere que asesines al capitán Melrache y a sus dos guardaespaldas.", description = "La Cruzada Escarlata ha estado atacando desde las ruinas de la torre situada al norte de Tirisfal, más allá de la Tumba de Faol. De acuerdo con los datos que tenemos, están bajo las órdenes del implacable capitán Melrache.\n\nTe voy a confiar una misión tan poco habitual como peligrosa. Mata a Melrache y a sus dos guardaespaldas en nombre de la Dama Oscura.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Hachuela de artilleroCuchillo ceremonialRecibirás:\n\n"}
MultiLanguageQuestData['mx'][373] = {title = "La carta sin enviar", objective = "Entrega la carta destinada al arquitecto jefe a Baros Alexston en Ventormenta.", description = "Registrando a Edwin VanCleef descubres, entre otras cosas, una carta sin enviar. Va dirigida a Baros Alexston, el arquitecto jefe de Ventormenta, Ayuntamiento, Plaza de la Catedral.\n\nParece ser que ha sido escrita y sellada recientemente.", progress = "¿Sí? ¿Puedo ayudarte en algo?", completion = "¿Edwin VanCleef, dices? Sería como recibir una carta de mi abuela muerta... ¿Así que le has matado? Perdona que te lo diga, pero me sorprende bastante. En su juventud, fue un luchador incomparable. Veamos por qué decidió escribirme después de tantos años. \n\n&lt;Baros lee detenidamente la carta.&gt; \n\nEdwin... Veo que los años no te han cambiado, sigues siendo un idealista y un romántico. No le importa hacer daño, &lt;nombre&gt;. La venganza le ha consumido. Aunque no estoy seguro de poder culparle por ello.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][374] = {title = "Prueba de defunción", objective = "Llévale 10 anillos con la insignia escarlata al Guardia de la Muerte Burgess de Rémol.", description = "El ejecutor Zygand me dice que has estado matando a miembros de la Cruzada Escarlata. Los Claros de Tirisfal están plagados de ellos.\n\nVarimathras, teniente de la Dama Oscura, se está encargando personalmente de exterminar a la escoria de Azeroth: la raza de los humanos. Aquí en los Claros de Tirisfal nos enfrentamos a un nuevo género de humanos: la Cruzada Escarlata.\n\nCorre el riesgo y lanza una ofensiva contra la Cruzada Escarlata, <clase>. Tráeme 10 anillos con la insignia Escarlata como muestra de tu lealtad a Varimathras y a la Dama Oscura.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Brazales de piel de zombiCinturón con brocheGuantes de redRecibirás:\n\n"}
MultiLanguageQuestData['mx'][375] = {title = "El frío de la muerte", objective = "Llévale 5 pelambres de Murciumbrío y un hilo burdo a Gretchen Dedmar, que está en Rémol.", description = "Tengo tanto frío... La Peste de los no-muertos corre por mis venas como una serpiente de hielo. Pronto me embargará el estado de automatismo pero nada me impedirá que sirva a nuestra Dama Oscura. En su momento yo misma cosí bolsas de cadáveres para los soldados caídos del poderoso ejército de Sylvanas.\n\nPero ahora mis manos tiemblan de frío. Si me trajeras 5 pelambres de Murciumbrío y un hilo burdo, podría coser yo mismo una manta. Ayúdame, <nombre>, para que así pueda seguir sirviendo a la causa.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Capa de adeptoGuantes de costuraRecibirás:\n\n"}
MultiLanguageQuestData['mx'][376] = {title = "Los Malditos", objective = "Consigue 4 garras de carroñero y 4 alas de Murciumbrío.", description = "Mis deberes son atender a nuestros guerreros heridos, suministrar ropa y armaduras y asistir al sacerdote de las Sombras Sarvis en lo que necesite.\n\nParece que tú también vas a acabar a su servicio... dando caza a los autómatas. Seguro, sé cómo piensa. Si quieres seguir de una pieza, que seguro que sí, quizás pueda ayudarte. Me estoy quedando sin patas y alas. Si me traes algunas, te buscaré una armadura. Encontrarás muchos lobos y murciélagos hacia el sur.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Cinturón de cuero viejoBrazales de lienzoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][377] = {title = "Crimen y castigo", objective = "El consejero Tallolino de Villa Oscura quiere que le lleves la mano de Dextren Ward.", description = "Como si no tuviéramos suficiente con la negligencia de los residentes del Bosque del Ocaso, ahora la Casa de Nobles escupe en el ojo al Consejo de Villa Oscura con su decisión de encarcelar a Dextren Ward en Ventormenta en lugar de decapitarlo como establecía la sentencia de Lord Cerranegro.\n\nTutor fue descubierto vendiendo cadáveres del cementerio a Morbent Vil, y ese es un delito que se castiga con la muerte. Y sin embargo, Ventormenta lo reclama como prisionero.\n\nAsesina a Ward en las Mazmorras de Ventormenta. Tráeme su mano y yo te recompensaré.", progress = "Cuando se deja vivir a un profanador como Dextren Ward, se traiciona a la justicia. Vuelve a mí cuando se haya cumplido la sentencia de muerte que Lord Cerranegro dictó contra ese rapiñador de Ward. Vamos a dar a las familias de los muertos la satisfacción que merecen y, además, enviaremos un claro mensaje a la Casa de Nobles de Ventormenta.", completion = "Así que finalmente, Dextren Ward pagó por sus crímenes contra la humanidad... Eso sí que es hacer limpieza. ¡Y enhorabuena, amigo! No solo has dado a las familias de los muertos la tranquilidad de espíritu que merecen, además has enviado un contundente mensaje a esos burócratas corruptos de la Casa de Nobles. Ventormenta debe escuchar las necesidades de la gente del Bosque del Ocaso o nos independizaremos y nos liberaremos de su tiranía.", rewards = "Botas de embajadorLeotardos de malla Villa OscuraRecibirás:\n\n"}
MultiLanguageQuestData['mx'][378] = {title = "La furia mora en las profundidades", objective = "Motley Garmason quiere que le lleves la cabeza de Kam Furiahonda a Dun Modr.", description = "Has demostrado tu lealtad al rey Magni, <clase>. Y tu odio por la escoria Hierro Negro es tan grande como el mío.\n\nHay una tarea que me gustaría hacer por mí mismo, pero el honor me obliga a permanecer junto a Largatrenza. Roggo ha conseguido reunir datos que demuestran que Kam Furiahonda fue miembro de la conspiración para el ataque del Puente Thandol. Fueron los planes de Furiahonda los que hicieron perder a Largatrenza a toda su familia.\n\nFuriahonda está retenido, por razones políticas, en las Mazmorras de Ventormenta. Le quiero muerto, <nombre>. ¡Por Largatrenza! ¡Tráeme su cabeza!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "AzotacabezasCinturón de VindicaciónRecibirás:\n\n"}
MultiLanguageQuestData['mx'][379] = {title = "Aplacar esa sed", objective = "Llévale 5 faltriqueras de agua de Vagayermos al ingeniero jefe Pasaquillas, en Gadgetzan.", description = "Si quieres una fuente de calor, yo puedo ayudarte a conseguirla. ¿Y sabes qué quiero yo? ¡Algo de beber! Tráeme cinco faltriqueras de agua de Vagayermos y yo te daré la 4711-FTZ.\n\nYa solo te falta saber dónde puedes encontrar faltriqueras de agua de Vagayermos. ¿Por qué no te diriges al este en busca de nómadas Vagayermos y les pides una? Ya me contarás cómo resulta.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFuente de alimentación modelo 4711-FTZ"}
MultiLanguageQuestData['mx'][384] = {title = "Costillas de jabalí a la cerveza", objective = "Ragnar Cebatruenos de Kharanos quiere 4 costillas de jabalí tiernas y una jarra de malta rapsódica.", description = "¡Nada les gusta más a mis clientes que unas ricas costillas de jabalí a la cerveza! El problema es que el trampero local que solía traerme los suministros, se ha alistado en el ejército del Rey para ayudar en el frente de la Alianza.\n\nQuizás puedas ayudarme tú... Si me traes seis costillas de jabalí montés y algo de malta rapsódica de la taberna, compartiré contigo una receta familiar: mis famosas costillas de jabalí a la cerveza. ¡Y te daré una muestra gratis! ¡El secreto está en la malta!", progress = "Voy a necesitar seis costillas de jabalíes del risco y una jarra de malta rapsódica, <nombre>.", completion = "La malta está lista y los jabalíes muertos\nY antes de acabar y de ponernos a hablar\nTendremos que luchar por ver quién empieza\n¡estas sabrosas costillas de jabalí a la cerveza!", rewards = "Recibirás:\n\nCostillas de jabalí a la cervezaReceta: costillas de jabalí a la cerveza"}
MultiLanguageQuestData['mx'][385] = {title = "La caza de crocoliscos", objective = "Lleva 5 piezas de carne de crocolisco y 6 pieles de crocolisco a Marek Coracero, en la Cabaña del Errante.", description = "Vienen muchos cazadores a Loch Modan por los crocoliscos. Los mercaderes compran pieles de crocolisco para hacer ropa y armaduras, e incluso hay a quien le gusta su carne.\n\nHacemos negocio, pero no mucho, porque esos bichos son muy feroces y se esconden en las islas del lago. Pero tú no te prives, enfrentarse a esos dientes es toda una experiencia.\n\nMe acuerdo de una vez que...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Daga de MarekBotas de crocopielGuantes de crocoescamasRecibirás:\n\nReceta: filete de crocoliscoManteo basto"}
MultiLanguageQuestData['mx'][386] = {title = "Lo que sucede alrededor...", objective = "Lleva la cabeza de Targorr el Pavoroso al guardia Berton a Villa del Lago.", description = "Targorr el Pavoroso sirvió bajo las órdenes de Gath'llzogg como Verdugo supremo. Sus métodos eran los más despiadados, incluso para los orcos. No dudó en torturar a hombres que habían servido lealmente en la defensa del Reino. Ahora se encuentra recluso en las Mazmorras de Ventormenta, a la espera de que se cumpla su sentencia de muerte. Aun así, hay algo que no encaja. Uno de los nobles burócratas ha detenido su ejecución. Seguro que se trata de una maniobra oscura.\n\nTienes que acabar con Targorr el Pavoroso, <nombre>. Viaja a las Mazmorras y decapítalo antes de que logre escapar a su destino.", progress = "¿Ya has estado en Las Mazmorras de Ventormenta? Temo que el poder que ha mantenido a Targor con vida acabe por conseguir liberarlo. Fue sentenciado a muerte, <nombre>, no a ser un títere político.", completion = "Targor el Pavoroso ha caído al fin. Me alegro. Buen trabajo, &lt;nombre&gt;. A veces solo se puede hacer justicia al margen de los tribunales y los políticos.", rewards = "Bastón de raíz endurecidoTizona LucineRecibirás:\n\n"}
MultiLanguageQuestData['mx'][387] = {title = "Detener el motín", objective = "El celador Thelagua de Ventormenta quiere que mates 10 prisioneros, 8 presidiarios, y 8 insurgentes en Las Mazmorras.", description = "¡Hay que detener el motín! Necesito tu ayuda. ¡Si alguien se entera de que la prisión es un caos perderé mi trabajo! Esto es juego sucio. Pero lo importante es obligar a los prisioneros a rendirse, por la seguridad de Ventormenta.\n\nEl castigo por sublevación es la muerte. Mata a alguno de esos desviados. Y verás cómo vuelven al buen camino...", progress = nil, completion = "Tus acciones en Las Mazmorras fueron muy valientes, &lt;nombre&gt;. Es obvio que este problema nos sobrepasa. Pero lo has hecho muy bien y, por ello, te doy las gracias.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][388] = {title = "El color de la sangre", objective = "Nikova Raskol, de Ventormenta, quiere que consigas 10 pañuelos de lana roja.", description = "El resentimiento corre por mis venas como una corriente fría. Mi nieto, Mac, era un chico muy bueno. 14 años recién cumplidos. Cuando el ejército fue mandado al frente, Mac cogió las armas para defender la ciudad. Fue un guardia de Las Mazmorras, donde está encerrada la banda Defias. Mac reprendió a algunos de los prisioneros por romper sus mantas de lana para hacer bufandas, un símbolo de la banda. Por hacerlo, recibió una puñalada en la espalda.\n\nQuiero venganza. Tráeme 10 de sus valiosos pañuelos de lana. Son del color de la sangre.", progress = "Veo que has vuelto, <clase>. ¿Has conseguido 10 pañuelos de lana roja de esa escoria Defias de Las Mazmorras?", completion = "¿Y estos pañuelos, símbolos asquerosos de corrupción, son por lo que mi Mac tuvo que morir? Qué gran pérdida. Qué trágico sacrificio. \n\nPero en fin, no puedo vivir en el pasado. Has de saber, &lt;nombre&gt;, que tus actos han conseguido que se haga justicia con mi familia.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][391] = {title = "El motín de Las Mazmorras", objective = "Mata a Bazil Thredd y lleva su cabeza al celador Thelagua en las Mazmorras.", description = "Dejemos esto claro, <nombre>. No confío en ti. Pero en estas circunstancias, tendré que pasarlo por alto.\n\nEsto es lo que vamos a hacer: baja ahí y habla con Thredd. Si realmente estás de nuestra parte, mátale y tráeme su cabeza como prueba. Si descubrimos que estás de su parte, cuando te encontremos... morirás junto con el resto de esos gusanos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][394] = {title = "La cabeza de la bestia", objective = "Habla con Mathias Shaw en Ventormenta.", description = "Encuentra a Shaw en el Casco Antiguo. Dile que nos hemos encargado de la amenaza de Lescovar y cuéntale lo de tu participación en los planes del señor contra la ciudad. Seguro que se sentirá orgulloso de tener a otro héroe entre los ciudadanos de Ventormenta.\n\nLo más probable es que te envíe a ver al príncipe o a otro noble. Pero que no se te suba a la cabeza, <nombre>. Los nobles pueden creer que gobiernan la ciudad, pero hay algunas cosas que se les escapan de las manos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][398] = {title = "Se busca: Ojo de cresa", objective = "Mata a Ojo de cresa y llévale su garra al ejecutor Zygand de Rémol para obtener una recompensa.", description = "Se busca: ¡Ojo de cresa!\n\nConsiderado una bestia incluso entre los propios gnolls, Ojo de cresa ha sido sentenciado a muerte por sus crímenes en contra de los Renegados. Este infame villano ha estado robando cuerpos y poniéndolos a disposición del ejército del Rey Exánime. Ojo de cresa fue visto por última vez saqueando las tierras situadas en las proximidades de la Granja de Garren, al norte de Rémol.\n\nA partir de este momento, la ciudad de Rémol ofrece una recompensa al que sea capaz de llevar a cabo su ejecución. Muéstrale al ejecutor Zygand la garra del villano una vez ejecutada la sentencia.\n\nLa clemencia queda relegada a los débiles.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Jubón de vástagoPantalones de escamas de latónRecibirás:\n\n"}
MultiLanguageQuestData['mx'][399] = {title = "Principios humildes", objective = "Ve a la casa de Baros Alexston en los Páramos de Poniente y busca su brújula. A continuación, llévasela al Distrito de la Catedral, en Ventormenta.", description = "Parece que hace una eternidad desde que tan solo era un chico trabajando en la granja de los Páramos de Poniente. Dicen que nunca puedes regresar, y es cierto. Doblemente cierto en mi caso, unos pasajeros quemaron y tomaron mi casa.\n\nHe hablado con mi padre para descubrir el destino de alguna de mis posesiones, incluyendo mi primera brújula. No fue capaz de salvarlas. Sin embargo, también dice que deberían estar escondidas en la granja.\n\nEncontrarás la Hacienda de Alexston al oeste de la Colina del Centinela. ¿Quizás podrías ir y recuperarla?", progress = "¡<nombre>! ¿Has tenido suerte?", completion = "¡Oh, muchas gracias, &lt;nombre&gt;! No me sirve de nada, pero el valor sentimental... No hace falta que te diga lo agradecido que te estoy por traerme esto... y veo que has tenido que sufrir algún que otro percance para conseguirlo, sin mencionar el tiempo que has perdido yendo a los Páramos de Poniente. Tienes mi gratitud. Acepta esto como muestra de ello.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][400] = {title = "Herramientas para Brasacerada", objective = "Entrega las herramientas de Brasacerada a Beldin Brasacerada.", description = "Beldin Brasacerada es el dueño de la tienda de mecánica local y además es el mejor técnico de máquinas de asedio. Pero es implacable con sus herramientas. ¡Te aseguro que rompe más llaves de tuerca arcoluz de las que le podemos suministrar!\n\nAcabamos de completar su último pedido. Si se lo llevas, seguro que te compensa el esfuerzo.\n\nSu tienda, el Almacén de Brasacerada, está al noreste de Kharanos. Y es un lugar en el que se reúnen los pilotos veteranos de máquinas de asedio, así que estate <atento/atenta> por si oyes algo interesante.", progress = "¿Mm? ¿No eres un poco joven para ser piloto de máquinas de asedio? Bueno, no importa. ¿Necesitas reparar algo?\n\nSi es así, toma un número y ponte cómodo. Ahora mismo estoy con un par de motores y no tendré tiempo para nada más hasta dentro de unos días.\n\n¿O venías por otro motivo?", completion = "¿Tienes mis herramientas? ¡Bien hecho, muchacho! Acabo de romper mi último destornillador hace una hora y necesitaba otro para acabar de reparar la máquina de asedio del piloto Roscapiedra. Desde luego, me has hecho un favor enorme trayendo estas herramientas hasta aquí, &lt;nombre&gt;. \n\nTen unas monedas.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][404] = {title = "Una tarea pútrida", objective = "Llévale 7 garras podridas al Guardia de la Muerte Dillinger de Rémol.", description = "La Plaga ha alcanzado los Claros de Tirisfal y ha infestado el área al oeste de Rémol, cerca del puente viejo.\n\nDirígete allí y enfréntate a los muertos podridos. Trae sus garras podridas y los Guardias de la Muerte te recompensarán.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][405] = {title = "El exánime pródigo", objective = "Comunícale las órdenes de Sevren a Bethor Duroyelo en Entrañas.", description = "Bethor Duroyelo, un poderoso mago de alto rango de Entrañas, que cae al sur, me ha pedido que le envíe a alguien capaz de hacer frente a la Plaga. Tú, <nombre>, eres <el elegido/la elegida>.\n\nPreséntate ante Bethor y él te explicará tu misión. Desconozco los detalles, pero sé que tiene algo que ver con reclutar a un exánime, y parece peligroso.\n\nPrepárate, <clase>, pues no debes fallar.\n\nBusca a Bethor en el Barrio de la Magia de Entrañas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][407] = {title = "Campos de pena", objective = "Llévale la calabaza envenenada al zelote Escarlata capturado que está encerrado en el sótano del Mesón La Horca.", description = "¿Simples e inofensivas calabazas, verdad? Eso es lo que deben parecer... Si queremos detener el avance de Arthas por el norte y la infestación humana por el sur, tenemos que comenzar a valorar nuestro propio potencial.\n\nCon un poco de ingenio, una simple calabaza se convierte en un arma de nuestra Dama Oscura. Solo hay que echarle un poco de mi última fórmula.\n\nHan capturado a otro zelote Escarlata y está encerrado en el sótano del Mesón La Horca. Llévale a ese desgraciado esta calabaza.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][408] = {title = "La Cripta de la Familia", objective = "Mata a 8 ancestros gemebundos y a 8 ancestros en podredumbre.\n\nMata al capitán Dargol y llévale su calavera al magistrado Sevren de Rémol.", description = "Los miembros de la Plaga han encontrado cobijo en los Molinos de Agamand. El punto más sólido es la Cripta de la Familia Agamand, lugar en el que su líder militar, un esqueleto llamado capitán Dargol, ha establecido su puesto de mando. Por medio de la nigromancia, ha revivido a los ancestros de los Agamand y planea utilizarlos contra nosotros.\n\nEsto no puede ocurrir y tú has de evitarlo. Viaja a la Cripta de la Familia Agamand y derrota a los ancestros de los Agamand.\n\n¡Ah! Y tráeme la calavera del capitán Dargol.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "PartehuesosBastón LeñoscuroRecibirás:\n\n"}
MultiLanguageQuestData['mx'][409] = {title = "Prueba de lealtad", objective = "Saca una vela de señalización.\n\nDespierta a Lillith Nefara y mátala.\n\nVuelve a ver a Gunther a su isla.", description = "Afirmas que no estás <sometido/sometida> a la voluntad del Rey Exánime y el encantamiento que Bethor lanzó sobre mi libro lo corrobora. Sin embargo, para que pueda confiar en ti debes darme una prueba de que estás en contra de la Plaga.\n\nHay un viejo altar, a poca distancia de la costa sur de esta isla, que utiliza un poderoso agente de la Plaga llamado Lillith Nefara.\n\nSaca una vela de señalización de este cajón. Enciéndela en el altar y Lillith se despertará. Acaba con Lillith y creeré que en verdad eres <un enemigo/una enemiga> del Rey Exánime.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][411] = {title = "El regreso del exánime pródigo", objective = "Llévale la gema abisal a Bethor Duroyelo en Entrañas.", description = "Dale esta gema abisal a mi viejo camarada Bethor. A través de ella podremos comunicarnos... y en verdad tengo mucho que contarle.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nRodela de huesos"}
MultiLanguageQuestData['mx'][412] = {title = "Operación Recombobulación", objective = "Lleva 8 engranajes giromecánicos a Razzle Engranágil.", description = "Debería regresar a Gnomeregan y seguir buscando una cura para los gnomos irradiados.\n\nSin embargo, me he quedado en Kharanos porque es mi hogar y quería ayudar a defenderlo de los ataques de los Peloescarcha. He estado trabajando en el mantenimiento y la reparación de los tanques de vapor.\n\nPor alguna razón, los carroñeros Peloescarcha se han aficionado a los engranajes giromecánicos que necesito para completar las reparaciones. Se encuentran esparcidos por todo el Frente de Peloescarcha, al sureste de la ciudad. ¿Me ayudas a conseguir traer los engranajes de vuelta?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes manchados de aceiteCinturón de piñonesRecibirás:\n\n"}
MultiLanguageQuestData['mx'][413] = {title = "Cerveza negra Brillante", objective = "Lleva el tonel de cerveza negra Brillante al montaraz Cebadiz.", description = "Me gustaría que mi hermano Wellart probara mi nueva cerveza negra Brillante. Es un montaraz. Está destacado en la torre de vigilancia del sur, en la frontera del Loch Modan.\n\nNo se dedica a hacer cerveza, como los demás Cebadiz, pero le encanta beberla y sé que esta le gustará.\n\n¿Podrías llevarle este tonel de cerveza negra Brillante de mi parte?", progress = "¡Hola, <clase>! ¿Qué te trae hasta aquí?\n\nAlgo emocionante, espero. Hace días que no consigo participar en una buena batalla y se me está acabando este barril de cerveza...", completion = "&lt;El montaraz Cebadiz prueba la cerveza negra Brillante...&gt; \n\nOh. ¡VAYA! Esta cosa le da como un brillo nuevo a la vista. ¡Creo que puedo ver en la oscuridad!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][414] = {title = "Cerveza negra para Kadrell", objective = "Lleva el tonel de cerveza negra Brillante al montaraz Kadrell.", description = "He estado bebiendo la cerveza negra Brillante esa que hizo mi hermano. ¡Está buenísima! Quiero que la pruebe un compañero mío. Se llama Kadrell y normalmente patrulla por el camino de Thelsamar en Loch Modan.\n\nPara llegar a Thelsamar, ve al sureste a través del túnel y gira al noreste cuando el camino se divida. Sigue en esa dirección y llegarás <derecho/derecha> a Thelsamar.\n\nDale este tonel de cerveza negra Brillante al montaraz Kadrell. ¡A ver qué le parece!", progress = "Saludos, <clase>. ¡Bienvenido a Thelsamar!", completion = "A ver, deja que pruebe... \n\n¡Por la barba de Magni! ¡Esta cosa te hace girar la cabeza! Y oye, te hace sentir como más ligero... \n\n¡Seguro que puedo volar!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][415] = {title = "La nueva bebida de Rejold", objective = "Habla con Rejold Cebadiz.", description = "Rejold Cebadiz de Las Birras ha estado preguntando por ti.\n\nQuiere hablar contigo sobre una nueva bebida que ha estado preparando... dijo algo de que quería que le ayudaras. Quizás quieras ir a Las Birras a ver qué necesita de ti.\n\nPodrías ganarte una cervecita...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nJarra de cerveza brillante"}
MultiLanguageQuestData['mx'][416] = {title = "Mata ratas", objective = "Lleva 8 orejas de rata de túnel al montaraz Pico Tormenta a Thelsamar.", description = "Tenemos una infestación grave. Esas ratas de túnel kóbold asquerosas se han instalado en las laderas. ¡Están cavando madrigueras y ensuciándolo todo!\n\nQueremos erradicarlos. Si los cazas y me traes sus orejas, puedes quedarte con su botín.\n\nLa mayor concentración de ratas de túnel kóbold está en el interior y en los alrededores de la Mina de Fuenteplata, al este.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Botas de hidalgoBrazales de pellejo quemadosCapa de oreja de rataEscudo AlgazRecibirás:\n\n"}
MultiLanguageQuestData['mx'][418] = {title = "Morcillas de Thelsamar", objective = "Lleva 8 trozos de carne de oso a Vidra Hogartufa, en Thelsamar.", description = "Aquí en Thelsamar siempre hay alguien que quiere comer, críos por todos lados, los obreros de la excavación y eso. Lo más conocido es la morcilla, ¿la has probado?\n\n¿No? Bueno, pues aquí hay que trabajar para comer, no creas que te libras porque seas <clase>.\n\nLo único que necesito es carne de oso, el resto está incluido en el preparado. ¡Tú trae eso y de cocinar me ocupo yo, Vidra!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nMorcillaReceta: morcilla"}
MultiLanguageQuestData['mx'][419] = {title = "El piloto perdido", objective = "El piloto Podomartillo, en la Avanzada de la Puerta Sur, quiere que encuentres al piloto Hildelve.", description = "Mi compañero y amigo, Mori Hildelve, que es piloto de máquinas de asedio, está perdido en los montes. Buscábamos un raro mineral necesario para fabricar un potente tipo de pólvora y durante nuestra búsqueda, subió con su máquina una empinada montaña ¡y la máquina se averió!\n\nAún convencido de que el mineral estaba en estas montañas, Hildelve me encargó que custodiara las máquinas mientras él continuaba a pie.\n\nPero ya han pasado días y por las noches oigo unos estremecedores aullidos al norte del Lago de Helm, al oeste del túnel. Mori es duro como una roca, pero estoy preocupado.\n\nTe lo ruego, <nombre>. Encuéntralo.", progress = nil, completion = "Encuentras el cadáver de un enano. Masacrado, congelado y saqueado por los carroñeros de la montaña. Aprieta con la mano un libro que contiene anotaciones garabateadas por Mori Hildelve. El cuerpo está envuelto en un jubón de brigadier que aún está en perfectas condiciones. \n\nEste escenario truculento es seguramente aquel en el que el piloto de máquina de asedio perdió la vida.", rewards = "Capa de MoriPalanca de cambios de MoriPodrás elegir una de estas recompensas:\n\nBrújula de Mori\n\nTambién recibirás:\n\nJubón de brigada de asedio"}
MultiLanguageQuestData['mx'][421] = {title = "Demuestra tu valía", objective = "Dalar Tejealba en El Sepulcro quiere que mates a 5 canosos Furia Lunar.", description = "Lady Sylvanas ha encomendado a Varimathras la conquista de las tierras humanas y enanas del sur.\n\nPero ese necio, Arugal, charlatán de Dalaran y ahora bestia maldita del Castillo de Colmillo Oscuro, dejó que su imprudente magia causara estragos en el bastión estratégico del Bosque de Argénteos.\n\nNecesito a alguien muy diestro en combate para ayudar a arreglar el desastre de Arugal. Demuéstrame tu valía matando a 5 canosos Furia Lunar. Es fácil encontrar a esas bestias salvajes al final del camino, hacia la colina de abajo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][426] = {title = "La invasión de los molinos", objective = "Recoge 5 costillas con cortes y 3 calaveras ennegrecidas, y después regresa ente el Guardia de la Muerte Dillinger de Rémol.", description = "Los miembros de la Plaga están intentando establecer una base en los Molinos de Agamand. Si lo consiguen, podrán lanzar más ataques sobre Tirisfal.\n\nLas órdenes son claras: hay que detener a la Plaga en los Molinos.\n\nVe a los Molinos. Recoge costillas con cortes de los soldados armadóseos y los soldados testapartida, y calaveras ennegrecidas de los tirahuesos Ojosombra.\n\nPara llegar hasta los Molinos, sigue el camino en dirección oeste. Tras cruzar el puente, toma el siguiente desvío hacia el norte y continúa en esa dirección. Cuando veas los molinos de viento, dará comienzo la batalla.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Botas de caminacriptasCalzas de paño robustoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][427] = {title = "En guerra con la Cruzada Escarlata", objective = "El ejecutor Zygand de Rémol quiere que mates a 10 guerreros Escarlata.", description = "Los documentos que el ejecutor Arren nos ha proporcionado son exactamente lo que necesitábamos para dar un giro a nuestra batalla contra la desdichada Cruzada Escarlata. Ahora sabemos sus ubicaciones exactas en Claros de Tirisfal.\n\nPero la Guardia de la Muerte tiene otras preocupaciones mayores. El ejército del Rey Exánime es más numeroso cada día que pasa. Necesitamos a alguien con un poco de \"iniciativa\" como tú para que envíe a la Cruzada Escarlata a la tumba.\n\nDemuéstrame que eres capaz de servir a la Dama Oscura; para ello, viaja al oeste hasta la torre que encontrarás pasada la Hacienda Solliden y mata a 10 guerreros Escarlata.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][428] = {title = "Los Mortacechadores desaparecidos", objective = "Encuentra a los Mortacechadores Quinn y Rane Yorick.", description = "Hace un par de semanas, dos de nuestros Mortacechadores, Rane y Quinn Yorick, fueron a una misión de reconocimiento por la parte norte de Argénteos. No hemos vuelto a tener noticias suyas.\n\nQuizás hayan caído en manos de la Plaga pero, si es así, necesito una confirmación. Encuentra a estos mortacechadores.\n\nSu primer objetivo era explorar las granjas al norte de Argénteos. Deberías comenzar por allí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][429] = {title = "Corazones salvajes", objective = "Consigue 6 corazones de huargo descoloridos y llévaselos al boticario Renferrel en El Sepulcro.", description = "El necrófago, Ivar el Hediondo, hirió de gravedad a mi hermano Quinn y no sé si podrá curarse sin ayuda mágica. Si bien yo no soy un boticario, sé que nuestros boticarios pueden preparar pociones curativas a partir de corazones de huargos descoloridos.\n\nConsigue esos corazones y llévaselos al boticario Renferrel en El Sepulcro, al sur. Después, vuelve aquí con la poción.\n\nEncontrarás muchos huargos entre aquí y la Huerta de Malden, al este.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nReceta: poción de sanación descoloridaPoción de sanación descolorida"}
MultiLanguageQuestData['mx'][432] = {title = "¡Malditos troggs!", objective = "Mata a 8 aplastacráneos Comepiedras y a 8 cascahuesos Comepiedras en la Cantera de Gol'Bolar o en la mina.", description = "¡Esos malditos troggs están destrozando mi excavación! ¡Mira! ¡Ahí va otro barril de polvo!\n\n¡Ay! ¡Cómo me gustaría bajar ahí y retorcerles a todos ese pescuezo huesudo que tienen! ¡Quiero matarlos a todos!\n\nEsto no puede ser bueno para la salud. Tanta ira, tanto estrés... ¿Qué puedo hacer sin perjudicarme la salud? ¡Nada!\n\nLos mataría yo mismo, pero mi puntería no es la que era. ¡Entra tú en la cantera y mata a un puñadito de esos bichos asquerosos! Te pagaré... ¡Tú hazles daño! ¡Mátalos!", progress = nil, completion = "Vaya, ahora me siento un poco mejor... \n\n¡Pero no conseguiré paz hasta que estén todos muertos! ¡Todos ellos!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][433] = {title = "El servidor público", objective = "Reparte 7 runas de retorno a los mineros atrapados en la Cantera de Gol'Bolar.", description = "Como miembro del Senado y de la Liga de Expedicionarios, he asumido la responsabilidad de investigar las condiciones de la cantera. ¡Los troggs se han vuelto locos!\n\nHan convertido en un caos la Cantera de Gol'Bolar. Van saliendo a medida que profundizamos en nuestra excavación, y destruyen nuestro equipo y dejan atrapados bajo tierra a nuestros mineros.\n\nTenemos que sacarlos de ahí. Algunos magos han estado haciendo horas extra para encantar estas runas de retorno. Si consigues llevárselas a los mineros atrapados, podrán regresar a la superficie a salvo.", progress = nil, completion = "Es un comienzo. Con suerte podremos aprovechar el momento y llevar a algunos montaraces para asegurar el área. Luego podremos comenzar a reconstruir nuestra infraestructura para que los mineros vuelvan al trabajo.\n\nGracias por tu ayuda, &lt;nombre&gt;.", rewards = "Pantalones dignificados de senadorBandas de PiedrasantaCinturón de minero de Gol'BolarRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][435] = {title = "Escolta a Erland", objective = "Escolta a Erland a través de los lobos, hasta llegar a Rane Yorick.", description = "Los lobos que están fuera no se mueven y me miran de forma malvada cada vez que salgo por esa puerta. Deben de estar increíblemente hambrientos si piensan que puede merecer la pena comerme.\n\nTengo que informar a mi compañero de equipo, el Mortacechador Rane Yorick. Y, para conseguir llegar donde está Rane, necesitaré ayuda con esos lobos.\n\n¡Por favor, escóltame! Hay un montón de lobos ahí fuera, así que tendríamos más oportunidades si tienes algún amigo que pueda ayudarnos...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nEspada corta de Mortacechador"}
MultiLanguageQuestData['mx'][436] = {title = "La excavación de Vetaferro", objective = "Habla con el explorador Ceñimal.", description = "El prospector Vetaferro dirige la excavación de unas antiguas ruinas al este del lago. Últimamente está haciendo pocos progresos, a pesar de todos los suministros que le hemos enviado.\n\nVetaferro es un enano honrado y tenaz que valora los resultados. Por eso sospecho que hay otros factores en su contra.\n\nVe a la Excavación de Vetaferro y habla con Magmar Ceñimal. Él se encarga de los detalles de la excavación y sabrá a qué se debe el retraso en los trabajos.\n\nPara llegar a la excavación, rodea el extremo sur del lago y luego dirígete al este.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][437] = {title = "El Campo Muerto", objective = "Mata gnolls Putrepellejo en El Campo Muerto.\n\nCuando aparezca Latipesadilla, mátala.\n\nLleva la esencia de Latipesadilla al sumo ejecutor Hadrec en El Sepulcro.", description = "Los informes iniciales de nuestros exploradores en Argénteos, muestran que los Putrepellejo tienen una base en una vieja granja del norte, El Campo Muerto. Hemos lanzado pequeños asaltos contra ellos, pero cada vez que lo intentamos, el alma en pena Latipesadilla les ayuda, utilizando su magia para diezmar nuestras tropas.\n\nQueremos acabar con Latipesadilla.\n\nVete a El Campo Muerto y ataca a los Putrepellejo. Si no ves a Latipesadilla, mata a los Putrepellejo hasta que aparezca y, después, mátala a ella.\n\nSu esencia se convertirá en polvo. Tráeme ese polvo como prueba.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBotas de reconocimiento"}
MultiLanguageQuestData['mx'][440] = {title = "El anillo grabado", objective = "Lleva el anillo de Deliah al magistrado Sevren en Rémol.", description = "Si quieres encontrar al marido o bienamado de Deliah, quien le dio el anillo... habla con el magistrado Sevren en Rémol. Debería tener registros de los fallecimientos recientes y, con suerte, podrás descubrir quién es Deliah.\n\nPero yo no contendría el aliento. Quienquiera que le dio el anillo, está probablemente muerto. Y, si no está muerto, probablemente ya no le importa Deliah.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][441] = {title = "Raleigh y Entrañas", objective = "Lleva el anillo de Deliah a Raleigh.", description = "Deliah tenía un marido, Raleigh, que ahora vive en Entrañas. Si la Deliah que vivía en Rémol es la dueña de este anillo, Raleigh lo sabrá.\n\nRaleigh está en el Barrio del Comercio, en Entrañas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][445] = {title = "Entrega a Bosque de Argénteos", objective = "Llévale los descubrimientos del boticario Holland al boticario Renferrel del Bosque de Argénteos.", description = "El tiempo es un lujo que no nos podemos permitir quienes trabajamos para Lady Sylvanas. Pero seguro que ya te habías dado cuenta.\n\nComo miembro de la Sociedad Real de Boticarios es mi deber compartir mis conocimientos con mis colegas para que con nuestro esfuerzo colectivo logremos algún día proporcionarle a la Dama Oscura su tan ansiada Nueva Peste.\n\nLlévale estas conclusiones al boticario Renferrel que está en El Sepulcro en el Bosque de Argénteos. Sigue los caminos que parten en dirección sur desde Rémol. Desde Entrañas, dirígete hacia el suroeste.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][447] = {title = "Una fórmula mortal", objective = "Consigue 6 corazones de oso grisáceo y 6 muestras de sangre de celerácnida y llévaselas al maestro boticario Faranell en Entrañas.", description = "Arthas cuenta con innumerables tropas. Pero, con una Nueva Plaga podríamos erradicar tanto al ejército de la Plaga como a la infestación humana.\n\nMis estudios han demostrado que la sangre de araña combinada con una toxina derivada del corazón de un oso grisáceo resulta en un elixir letal. Reúne muestras de las arañas en Penumbra de las Celerácnidas, al noroeste, y de los osos que vagan por el Bosque de Argénteos. Lleva los componentes al maestro boticario Faranell de la Sociedad Real de Boticarios, en Entrañas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nRaíz de senggin"}
MultiLanguageQuestData['mx'][450] = {title = "Una fórmula mortal", objective = "Recupera el Diario del boticario Berard de la Aldea Piroleña y llévaselo al boticario Renferrel en El Sepulcro.", description = "Puedes seguir ayudando a la Sociedad Real de Boticarios, <nombre>.\n\nCuando Arugal utilizó su magia maligna en el bosque, maldijo a uno de nuestros miembros más prometedores, el boticario Berard. Ahora es un sirviente de Arugal, sin dominio de sí mismo. En estas condiciones, Berard no nos sirve de nada. Pero sus descubrimientos podrían servirnos. Estaba estudiando una antigua plaga que acabó con la vida acuática del Lago Lordamere años atrás.\n\nVe a buscar el Diario de Berard. Está en su estudio, el la Posada de la Aldea Piroleña, y llévaselo al boticario Renferrel.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][452] = {title = "La emboscada de Aldea Piroleña", objective = "Ayuda a la mortacechadora Faerleia a destruir al Consejo Piroleña.", description = "¡Has llegado justo a tiempo, <nombre>!\n\nEl Consejo Piroleña está a punto de regresar. Arugal tiene que encargarse de otras cosas en el bastión. Utiliza el Consejo como si fueran marionetas, para mantener a los ineptos esbirros de la Aldea Piroleña bajo su control. Pero creo que sin la ayuda del Consejo Piroleña, los hijos de Arugal se volverían contra su maestro.\n\nNo puedo encargarme de todo sin ayuda. Te necesito. Juntos podemos acabar con el Consejo para Lady Sylvanas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Calzas de cuero elásticasChal místicoEscudo de FaerleiaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][455] = {title = "El asedio de Algaz", objective = "Atraviesa Dun Algaz.\n\nMata 8 exploradores Faucedraco y 6 brutos Faucedraco.\n\nInforma a Valstag Quijahierro de Puerto de Menethil.", description = "Los orcos del clan Faucedraco tienen un refugio en Los Humedales ¡y ahora se han adentrado en Dun Algaz! No podemos permitir que continúen afianzándose aquí o Loch Modan perderá el contacto con el Puerto de Menethil, nuestro puerto y bastión en Los Humedales.\n\nAtraviesa Dun Algaz y dirígete a Los Humedales, ¡cuando estés allí mata a tantos orcos como puedas! Informa a Valstag Quijahierro en Puerto de Menethil.\n\nMenethil está pasado Dun Algaz, siguiendo el camino hacia el Norte y al Oeste en el cruce.\n\nContamos contigo, <nombre>. No nos falles.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][456] = {title = "El equilibrio de la naturaleza", objective = "Mata a 3 sables de la noche y 3 jabalíes cardo jóvenes.", description = "Saludos, <nombre>. Soy el conservador Ilthalaine. He venido a Cañada Umbría para asegurarme de que se mantiene el equilibrio de la naturaleza.\n\nEsta primavera ha llovido más de lo normal, lo que ha beneficiado mucho a algunas criaturas del bosque, pero ha perjudicado a otras.\n\nAhora hay demasiados sables de la noche y jabalíes Cardo; Cañada Umbría no puede alimentar a tantas bestias. Joven <clase>, reduce las poblaciones de jabalí Cardo y sable de la noche para mantener la armonía de la naturaleza.", progress = nil, completion = "Buen trabajo, &lt;nombre&gt;.", rewards = "Guantes de entrenamiento en tiro con arcoBrazales de talloRecibirás:\n\n"}
MultiLanguageQuestData['mx'][458] = {title = "La protectora de los bosques", objective = "Busca a la dríade Tarindrella.", description = "Me alegro de que hayas llegado, <clase>. El susurro de los espíritus del bosque me ha traído extrañas nuevas.\n\nLa misteriosa protectora de los bosques, Tarindrella, ha regresado a Cañada Umbría. La presencia de la dríade en estos bosques no se conocía desde antes de la bendición de Teldrassil. Si ha viajado de nuevo hasta estas tierras, entonces sin duda algo va mal.\n\nBusca a Tarindrella y averigua qué asuntos la han traído aquí. Uno de los centinelas la ha avistado al suroeste de Aldrassil.", progress = nil, completion = "Veo que me has encontrado, joven &lt;raza&gt;. Melithar ha hecho bien en enviarte aquí.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][459] = {title = "Ladrones demoníacos", objective = "Recupera las judías robadas de Dellylah, el agua robada de Dellylah y las bolsas robadas de Dellylah.", description = "¡Malditos grells! Han vuelto a robar de nuestras despensas.\n\nSi no te importa echarme una mano, seguro que todo lo que han robado está esparcido por los campamentos grell del oeste. Te recompensaré si me lo traes de vuelta.", progress = "Ayúdame a confirmar mis sospechas, <nombre>. Tráeme 8 musgoviles.", completion = "El servicio que les has prestado a las criaturas de Cañada Umbría merece una recompensa, &lt;nombre&gt;.\n\nSin embargo, has confirmado mis miedos. Si los grells han sido corrompidos por el musgovil, solo puedo imaginarme el destino que habrá sufrido la tribu de fúrbolgs Tuercepinos que solía vivir aquí.\n\nSi llegas a encontrarte en Dolanaar, &lt;clase&gt;, busca al sabio druida Athridas Manto de Oso. Él comparte nuestra preocupación por el bienestar del bosque.", rewards = "Leotardos canopeBotas de rastreoGuantes de parraRecibirás:\n\nBolsa de suministros de MelitharHierba de sanación"}
MultiLanguageQuestData['mx'][460] = {title = "Descansar en piezas", objective = "Lleva la cabeza de Alaric a su tumba.", description = "\"No pareces un Putrepellejo. Bien. Ya había perdido la esperanza...\n\nMe llamo Alaric, y fui el jefe de los sirvientes y guardaespaldas de Thule. Utilizó su magia para \"protegerme\" de la peste de no-muertos, pero su hechizo me dio una no-vida de la que no puedo escapar. Después de crear a los malvados gnolls Putrepellejo, Thule me decapitó... y dio mi cabeza a los gnolls como juguete.\n\nPor favor, llévame con mi cuerpo. Creo que los gnolls lo enterraron aquí, en el Castillo de Fenris cerca del establo, en una tumba sin nombre.\"Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][463] = {title = "El Guardaverde", objective = "Encuentra al Guardaverde.", description = "¿Has oído hablar del Guardaverde? ¿No lo estarás buscando, verdad? Si lo buscas es que estás <loco/loca>, ¿pero quién soy yo para apartar a un idiota de su muerte?\n\nSi estás buscando a esa bestia, he oído decir que está en los pantanos, al este del camino cuando se divide hacia Dun Modr. Está escondido entre los crocoliscos... ¡y cosas aún peores!\n\nDeja aquí tu dinero. No lo necesitarás allí a donde vas... no querrás que Verdín se rompa un diente con tus monedas cuando te parta en dos de un bocado, ¿verdad?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][464] = {title = "Estandartes de batalla", objective = "Lleva 8 estandartes de guerra Faucedraco al capitán Puñorrecio.", description = "El clan orco Faucedraco fue prácticamente exterminado al final de la Segunda Guerra, cuando perdieron su control sobre los dragones rojos que eran sus mascotas. Los dragones no estaban muy contentos con sus antiguos dueños y dieron caza despiadadamente a todos los Faucedraco. Los pocos que quedaron huyeron de Grim Batol y se refugiaron en las montañas al este de la Excavación de Whelgar.\n\nAhora han ganado fuerza y tienen un campamento al noreste de Menethil.\n\nQueremos que ataques ese campamento. Recoge sus estandartes de guerra y tráemelos como prueba.", progress = "¿Has atacado ya el campamento Faucedraco?", completion = "Buen combate, &lt;nombre&gt;. Los Faucedraco ya no suponen la misma amenaza que cuando tenían dragones, pero siguen siendo unos duros oponentes. \n\nLos Faucedraco están liderados por Nek'rosh, hijo de Nekros, su antiguo cabecilla. Nekros utilizó poderosa magia para domar a los dragones rojos, pero cuando la magia le falló... los dragones no estaban muy contentos. \n\nNekros fue asesinado y su hijo ha jurado venganza contra los dragones que acabaron con su padre.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][465] = {title = "La estrategia de Nek'rosh", objective = "Destruye las catapultas Faucedraco.", description = "Mientras estabas combatiendo a los Faucedraco, descubrimos más cosas sobre sus planes.\n\nNek'rosh ha construido catapultas ¡y pretende asediar Menethil! ¡Además, debido a la lucha en Dun Algaz no podemos recibir refuerzos!\n\nTienes que acabar con esas catapultas. Están en el campamento Faucedraco.\n\nToma esta yesca. Ábrete camino hasta las catapultas y préndeles fuego con la yesca.\n\nCuando hayas terminado, encuentra y mata a Nek'rosh. Necesitamos acabar con esta bestia Faucedraco... de raíz.", progress = "La primera catapulta está ante ti. ¿Vas a prenderle fuego?", completion = "Colocas algo de yesca en la catapulta y haces saltar una chispa. \n\n¡Aparece una llama que se extiende rápidamente!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][466] = {title = "Búsqueda de incendicita", objective = "Lleva 6 piezas de mineral de incendicita al piloto Roscapiedra de Dun Morogh.", description = "He oído decir que se encontró un extraño mineral, incendicita, en Los Humedales, en una cueva al noroeste de la Puerta de Algaz. La incendicita es un material volátil y es difícil de utilizar sin que explote, ¡pero seguro que si se funde de la forma adecuada podría hacer proyectiles de cañón que harían un daño tremendo!\n\nTráeme mineral de incendicita y encontraré a alguien que se atreva a experimentar con él.\n\nOh, una cosa más, para extraer el mineral de un filón tendrás que saber minería. ¡Si no eres <minero/minera> lleva uno contigo a la cueva!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGuantes manchados de cerveza"}
MultiLanguageQuestData['mx'][467] = {title = "La búsqueda de los Roscapiedra", objective = "Habla con el piloto Roscapiedra.", description = "¡Al piloto Roscapiedra le encanta su máquina de asedio! ¡Y siempre anda buscando maneras de mejorar su cilindrada!\n\nHa oído hablar de un mineral muy raro y necesita a alguien que se lo consiga. Si te apetece una aventurilla, ve a hablar con él en el Almacén de Brasacerada en Dun Morogh.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][468] = {title = "Preséntate ante el montaraz Piedragar", objective = "Habla con el montaraz Piedragar.", description = "El montaraz Piedragar está buscando voluntarios para una misión que les llevará a través de Dun Algaz hasta Los Humedales.\n\nSi quieres mojarte las botas en ese embarrado condado del Norte, habla con Piedragar en Dun Algaz, siguiendo el camino hacia el Norte, pasada la torre de vigilancia.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][469] = {title = "Entrega cotidiana", objective = "Entrega el fardo de pieles de crocolisco a James Halloran, el curtidor, en Puerto de Menethil.", description = "¡Saludos <viajero/viajera>!\n\n¿Acaso te diriges hacia Menethil? Si no es así, te recomendaría ir y hacer un alto. Es un buen lugar para hacer unas compras o para disfrutar de una buena pinta y de algo de descanso.\n\nAhora bien, si ya te dirigías hacia allí, no creo que te importe llevarle este fardo de pieles de crocolisco a James Halloran, el curtidor.\n\nLo haría yo mismo, pero últimamente mi mujer no está de muy buen humor, me gustaría verla lo más tarde que pueda.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][470] = {title = "Abriéndose paso entre los mocos", objective = "Uno de los mocos de la Tumba de Barbaférrea tiene la Bolsa de Shida, recupérala y devuélvesela en Puerto de Menethil.", description = "¡Durante mi visita semanal a la Tumba de Barbaférrea fui atacada por espantosos y pringosos mocos! Por supuesto, me entró pánico.\n\nLe lancé mi bolsa a uno de ellos, ¡pero no le hizo nada! El moco la absorbió... Por fortuna eso me dio algo de tiempo para escapar.\n\n¡La mala noticia es que necesito recuperar el contenido de mi bolsa!\n\nNo sé a qué moco le lancé la bolsa, ¡todos parecían iguales! La Tumba de Barbaférrea está al noreste de aquí, cerca de Dun Modr. ¡Muchísimas gracias!", progress = "¿Encontraste mi bolsa?", completion = "¡Oh, gracias, &lt;nombre&gt;! ¡Creía que la había perdido para siempre! \n\n \n\nUmm... esto ya no me vale de mucho, pero lávalo y estoy segura de que te será muy útil.", rewards = "Recibirás:\n\nBolsa cubierta de moco"}
MultiLanguageQuestData['mx'][471] = {title = "Deberes de aprendiz", objective = "Reúne 6 pieles de crocolisco gigante y llévaselas a James Halloran en Puerto de Menethil.", description = "Envié a mi aprendiz a los pantanos para desollar algunos de nuestros famosos crocoliscos gigantes de Los Humedales. Cuando no regresó salí a buscarlo... Basta decir que no fue una visión muy agradable.\n\nLa matrona dice que el chico podría recuperarse, ¡pero hasta entonces sigo necesitando pieles!\n\n... Si quisieras matar unas cuantas de esas bestias no estaría en contra, después de todo lo que hicieron. Encontrarás a los crocoliscos al Norte, siguiendo la costa y pasadas las casuchas de los múrlocs.", progress = "Mi aprendiz es como un hijo para mí. Le va a ser difícil vivir con una sola pierna.\n\nAh, <nombre>, ¿qué tal va? ¿Tienes mis pieles?", completion = "Umm... No creo que estés interesado en convertirte en mi aprendiz, ¿verdad? \n\n¡Ja! No, estoy bromeando. Eres demasiado mayor. Además por tu aspecto se diría que tienes otras ambiciones. Bueno, en cualquier caso, me has traído buenas pieles y me serán muy útiles.", rewards = "Leotardos de anillas maleablesPoncho resistenteRecibirás:\n\nReceta: potaje de crocolisco"}
MultiLanguageQuestData['mx'][472] = {title = "La caída de Dun Modr", objective = "Busca a Largatrenza junto a la ciudad de Dun Modr.", description = "¡Dun Modr ha caído en manos de los enanos Hierro Negro!\n\nMis heridas son graves, <clase>. ¡Y casi todo mi regimiento fue asesinado! Los matones Hierro Negro nos atacaron antes de que pudiéramos reagruparnos tras la emboscada del Puente Thandol.\n\nNuestro líder, Largatrenza, hizo sonar el cuerno de retirada. Cuando dejamos la ciudad fui herido en la espalda con un hacha perdida. Todo se volvió negro.\n\nDesperté aquí, en Menethil, pero estoy preocupado por mis compañeros. Aún abrigo esperanzas. ¡Quizás Largatrenza siga con vida! ¡Ve a ver si puedes encontrarle cerca de Dun Modr, <raza>!", progress = nil, completion = "¿Qué valiente &lt;clase&gt; envía un mensaje desde Menethil? Ah &lt;nombre&gt;, te llaman. \n\nTraes algo de luz a una situación desesperada. 'Es una buena noticia que el joven Harlo sobreviviera. Al huir resultó gravemente herido. Apenas tuvimos tiempo para enviarle a lomos del único corcel que quedaba con vida de todo el regimiento. \n\nPero ahora nos enfrentamos a una situación muy peligrosa. Dun Modr ha caído y solo somos una sombra del gran regimiento que fuimos un día.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][473] = {title = "Preséntate ante el capitán Puñorrecio", objective = "Habla con el capitán Puñorrecio.", description = "<nombre>. El clan orco Faucedraco está mostrando su fuerza, y no solo en Algaz. El capitán Puñorrecio ha pedido hablar con quienes quieran ofrecer su ayuda contra esos orcos. Lo encontrarás en el castillo, en la Sala de Mandos.", progress = nil, completion = "&lt;nombre&gt;. Valstag me ha informado de tus éxitos sobre los orcos Faucedraco en Dun Algaz. Eres un &lt;raza&gt; de gran valor. \n\nY tengo una tarea para ti.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][475] = {title = "Una brisa problemática", objective = "Busca a Gaerolas Talvethren en la Aldea Brisa Estelar.", description = "Se avecinan problemas en el bosque.\n\nGaerolas Talvethren es el Gran celador de los druidas hibernantes de la Garra en Túmulo de Ban'ethil. Su función como protector de los Adormecidos es preservar su seguridad de modo que no se rompa el pacto que tienen con Ysera. \n\nPero hace tiempo que no sé nada de él y me inquieta. Viaja al este hasta la Aldea Brisa Estelar para hablar con Gaerolas y regresa para informarme de todo. Cuando sepa que mis hermanos duermen apaciblemente, me quedaré más tranquilo.", progress = nil, completion = "¡Gracias a los espíritus del bosque que estás aquí! Sabía que Athridas percibiría los problemas y enviaría ayuda.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][477] = {title = "Pasa la frontera", objective = "Recupera el contenido de una de las cajas de zahoríes de Dalaran. Encontrarás la Aldea Piroleña hacia el sur.", description = "Como sabrás, la ciudad de Molino Ámbar sigue siendo una fuente de oposición humana, principalmente gracias al apoyo que reciben de los magos de Dalaran.\n\nNo sé cuál es su plan, pero que se hayan interesado por un lugar tan remoto como Molino Ámbar, indica que tiene que ser más importante de lo que pensamos.\n\nHan estado enviando cajas por carro desde Trabalomas. Muchos de esos suministros acaban en un pequeño campamento al norte de la Aldea Piroleña. Consigue los contenidos de una caja y tráemelos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][479] = {title = "Las investigaciones de Molino Ámbar", objective = "Consigue 8 colgantes de Dalaran al sacerdote de las Sombras Allister en El Sepulcro.", description = "Dalar está intentando localizar la fuente de los hechizos de los magos. Por ahora, tendremos que ralentizar su avance como podamos...\n\nLos conjuradores, magos y protectores tienen, sin lugar a dudas, los colgantes. Quítaselos.\n\nSigue hacia el sur por el camino principal y después, dirígete al este, a Molino Ámbar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][484] = {title = "Piel de crocolisco joven", objective = "Consigue 4 pieles de crocoliscos jóvenes para James Halloran de Puerto de Menethil.", description = "Soy James Halloran, el curtidor. Mis pieles curtidas de crocolisco son las más apreciadas de todas y llegan cargamentos a todos los puertos del mundo.\n\n¿Viste a Einar? Es uno de los cazadores encargados de proporcionarme pieles de crocolisco.\n\nMe estoy quedando sin las suaves pieles de crías de crocolisco.\n\nPor eso te pagaré generosamente por una pila de esas pieles. Podrás encontrar crías de crocolisco en los pantanos que están a las mismas puertas de la ciudad.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][485] = {title = "¡Encuentra a OOX-09/TI!", objective = "Lleva el localizador al robot mensajero de Oglethorpe, en el nacimiento del río de las Tierras del Interior, cerca de Roca Oculta.", description = "Has descubierto una especie de instrumento extraño de metal y con forma de huevo. Si jugueteas con uno de los botones del huevo, este toma vida. ¡Se convierte en una especie de artilugio robótico gnomo! Y del interior del huevo sale una voz.\n\n\"Mi nombre es Oglethorpe Obnoticus, ¡y mi robot mensajero se ha averiado! Te recompensaré por su rescate. Por favor, lleva este localizador hasta el robot.\"\n\n\"He procesado las coordenadas del robot: falló en la cabecera del río, cerca de Roca Oculta.\"", progress = "Parece que has descubierto los restos de... ¿un pollo robótico? La voz que proviene del huevo vuelve de nuevo a la vida:\n\n\"¡Sí, un trabajo excelente! Este es sin duda mi robot mensajero, aunque mis sensores indican que necesita un empujón para que pueda volar de regreso a Bahía del Botín para ser reparado. Coloca el localizador en el interior del robot. ¡El localizador hará todo lo demás!\"", completion = "Colocas el huevo... localizador de emergencia... dentro del pollo... el robot mensajero.\n\nDentro se oyen zumbidos y chirridos. Cuando el robot es revivido, se vuelve a oír la voz de Oglethorpe una vez más, pero ahora, viene de dentro del robot:\n\n\"OOX-09/TI funciona, pero necesita reparaciones. Es demasiado pesado para llevarlo, pero tengo una idea. ¿Puedes vigilarlo un rato más?\"", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][487] = {title = "El camino a Darnassus", objective = "Mata 6 emboscadores Tuercepinos y regresa con la centinela Amara Noctámbula en las afueras de Dolanaar.", description = "El camino a Darnassus debe permanecer seguro. Los viajeros que se dirigen de Dolanaar a Darnassus han estado denunciando ataques brutales de fúrbolgs corruptos de la tribu Tuercepinos.\n\nEste camino se utiliza a diario para el transporte de mercancías y es la vía de comunicación más importante de Darnassus. No podemos permitir que esa pandilla de bárbaros paganos aterrorice a la gente.\n\nDefiende el bosque sagrado, <clase>. Su guarida está en algún lugar debajo de este punto de observación. Mata a 6 de estos emboscadores Tuercepinos y vuelve a verme.", progress = nil, completion = "Has servido con diligencia al pueblo de Dolanaar y Darnassus, valiente &lt;clase&gt;. Como integrante del escuadrón de centinelas de Teldrassil, te agradezco el esfuerzo.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][488] = {title = "Las apuestas de Zenn", objective = "Consigue 2 colmillos de sable de la noche, 2 plumas de lechuza estrígida y 2 muestras de seda de araña Tejemadera.", description = "Veo que tienes ganas de trabajar... Por suerte para ti, no hay un día que pase que no desee tener cerca a <un/una> inocente <clase> a quien proponerle mi oferta.\n\n¿Sabes, <nombre>? Puedo hacerte muy feliz y ofrecerte cosas que jamás hubieras soñado tener, pero para ello deberás traerme una serie de objetos.\n\nPara desempeñar mi trabajo en el bosque a veces necesito ciertos... componentes. Tráeme colmillos de sable de la noche, plumas de lechuza estrígida y muestras de seda de araña Tejemadera.\n\nY que esto quede entre nosotros, <raza>.", progress = "¿Por qué has tardado tanto, <nombre>? He estado esperando a que llegaras con todo lo que necesito.", completion = "¡Ja, ja, ja! ¡Lo has hecho! \n\n¿Quién habría imaginado que yo, Zenn Nauseapezuña, conseguiría que un &lt;raza&gt; hiciera lo que se me antojara? ¡Yo no, la verdad! Pero así es... este maravilloso mundo está lleno de sorpresas. \n\n¡Tres hurras por nuestro inocente de hoy!", rewards = "Recibirás:\n\nGarra de vudú cortadaBolsa hedionda"}
MultiLanguageQuestData['mx'][489] = {title = "¡Búsqueda de redención!", objective = "Recoge 3 bellotas viles y entrégaselas a Zenn Nauseapezuña en las afueras de Dolanaar.", description = "El Consejo del Bosque se ha enterado de que ayudaste a Zenn Nauseapezuña, un sátiro enemigo del bosque. Como <buen/buena:r> <raza> que eres, no deberías dedicarte a mancillar el bosque matando criaturas de la naturaleza.\n\nHas de reparar tu error ante el Consejo si deseas seguir siendo <amigo/amiga> de Teldrassil.\n\nDale a Nauseapezuña una lección y recibirás tu perdón. Las bellotas viles son semillas corruptas que caen de los árboles y que expulsan humo verde.\n\nDale algunas a Nauseapezuña, él creerá que se trata de un inofensivo aperitivo.", progress = "¿Qué tienes para mí, <nombre>? Parece un rico aperitivo...", completion = "¡Ah, qué maravilla de &lt;raza&gt;! Sabía que me serías de ayuda.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][491] = {title = "Una varita para Bethor", objective = "Lleva la varita tejida a Bethor Duroyelo en el Barrio de la Magia, en Entrañas.", description = "Una vez Thule me dijo que, mucho tiempo atrás, él y dos de sus colegas crearon una varita mágica, combinando las varitas de aprendiz que cada uno de los magos tenía. Esta varita fue un símbolo de su amistad y, aunque Thule llegó a despreciarla, no pudo deshacerse de ella, ni permitir que los otros la tuvieran. Así que robó la varita y la escondió en el Castillo de Fenris.\n\nAquí. Lleva la varita a Bethor Duroyelo, uno de los antiguos amigos de Thule. Seguro que la quiere.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Calzas estampadasGuantes de malla bastaCuchillo dentadoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][492] = {title = "Una nueva Peste", objective = "Llévale la bebida especial de Johaan al montaraz capturado.", description = "De acuerdo con la Guardia de la Muerte, acaban de capturar a otro de esos insensatos enanos montaraces. La Guardia de la Muerte suele encerrar a los prisioneros en el sótano del Mesón La Horca hasta que pueda encargarse \"debidamente\" de ellos.\n\n¿Por qué no vas a comprobar si al montaraz capturado le gusta la bebida especial que he preparado para él? Contiene una pequeña muestra de lo que la Dama Oscura tiene reservado para todo Azeroth.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][493] = {title = "Viaja a Laderas de Trabalomas", objective = "Lleva el descubrimiento del boticario Renferrel al boticario Lydon en la ciudad de Molino Tarren, en las Laderas de Trabalomas.", description = "La Dama Oscura está presionando mucho a la Sociedad Real de Boticarios para que creen una Nueva Plaga. Estamos trabajando diligentemente y hemos avanzado mucho. Creemos que lo conseguiríamos antes si compartiésemos información entre la Sociedad.\n\nPor esa razón, quiero que entregues mis últimos descubrimientos al boticario Lydon en el Molino Tarren, una pequeña ciudad en las Laderas de Trabalomas. El viaje será largo.\n\nDirígete al sur y no te alejes de los caminos. ¡Sigue las señales de cerca!", progress = "¿Tienes algo para mí?", completion = "¡Excelente, excelente! El boticario Renferrel se merece todo mi respeto. Me muero por estudiar su obra.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][494] = {title = "l momento de atacar", objective = "Ve a Molino Tarren para llevar el mensaje de la mortacechadora Lesh a la suma ejecutora Darthalia.", description = "Cállate y presta atención, <clase>.\n\nMe han enviado aquí para vigilar Trabalomas. La mía es una misión de reconocimiento. Debes enviar un mensaje a la suma ejecutora Darthalia, a Molino Tarren, de inmediato. Dile que la mortacechadora Lesh le envía este mensaje:\n\n\"Desde el oeste nos llega el llanto del cuervo.\"\n\nSigue el camino que va al este y fíjate bien en las indicaciones. ¡Apresúrate! ¡Ve a Molino Tarren a toda prisa!", progress = nil, completion = "\"Desde el oeste nos llega el llanto del cuervo.\" \n\n¡Qué noticia tan excelente! Todo está a punto para arrasar Trabalomas. Esto complacerá a Varimathras.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][495] = {title = "Corona de Voluntad", objective = "Preséntate ante Melisara que está en Molino Tarren, en las Laderas de Trabalomas.", description = "Jarra'thol y sus ogros debían ir a Alterac en busca de la Corona de Voluntad para Lady Sylvanas. Por desgracia, en lugar de regresar con ella, el muy idiota decidió probarla... Supongo que los ogros no se pueden resistir a nada luminoso y brillante.\n\nSin embargo, su constante incompetencia se está convirtiendo en un problema. La Corona de Voluntad le permitió resistirse a la posesión que le obligaba a servir a Lady Sylvanas.\n\nLa Dama Oscura quiere darle un castigo ejemplar; viaja al Molino Tarren en Trabalomas e informa a Melisara, mi teniente.", progress = nil, completion = "¿Te envía Shalindra? Muy bien, pues vayamos al grano. \n\nJarra'thol es un estorbo así que debemos ocuparnos de él sin perder ni un segundo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][496] = {title = "lixir de sufrimiento", objective = "El boticario Lydon de Molino Tarren quiere 10 lenguas de oso gris y un poco de icor de trepador.", description = "Otro maldito día en el Molino Tarren. Todo este aire puro me pone enfermo, <nombre>.\n\nTenemos que infestar a los humanos cuanto antes. He estado estudiando potenciales agentes letales para utilizar en mis brebajes pero no he tenido tiempo de recogerlos todos.\n\nSi quieres hacer algo útil, podrías procurarme los siguientes objetos: diez lenguas de oso gris e icor de trepador, que es muy raro y difícil de encontrar. Nada más salir del Molino Tarren encontrarás osos y trepadores.", progress = "Ah, ya estás aquí. Espero que traigas los ingredientes; me deprimo si paso más de un día sin matar nada.", completion = "Estos ejemplares son perfectos. Muy bien, &lt;nombre&gt;. Gracias por arrojar un tenue rayo de alegría a otro día sombrío.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][498] = {title = "l rescate", objective = "Krusk de Molino Tarren quiere que liberes a Drull y a Tog'thar en el Castillo de Durnholde.", description = "El Jefe de Guerra me envió con algunos compañeros a Durnholde para recoger un objeto e investigar a esa tal Hermandad.\n\nFuimos a echar un vistazo, pero un numeroso grupo de humanos nos atacó por sorpresa. Luchamos como fieras, pero estábamos en franca minoría. Nos tomaron cautivos a algunos, pero conseguí escapar.\n\nDurnholde está al otro lado del río, hacia el sureste. Drull y Tog'thar están retenidos allí; debes ir a rescatarlos.", progress = nil, completion = "Así que los humanos querían esclavizarnos, ¿eh? ¡Eso ya lo veremos! \n\nParece que han trasladado a Gol'dir; debemos encontrarlo y rescatarlo. \n\nTe avisaré cuando tengamos alguna pista de su paradero, &lt;nombre&gt;.", rewards = "Cota de malla de guerra orcaJubón de brutoRecibirás:\n\nReceta: chuleta de oso grande"}
MultiLanguageQuestData['mx'][500] = {title = "a recompensa Aplastacresta", objective = "Recoge 9 nudillos sucios de ogros Aplastacresta en las Montañas de Alterac. Llévaselos al alguacil Rutagrana a Costasur.", description = "Los ogros Aplastacresta han construido un túmulo en las Montañas de Alterac, cerca de la ciudad arrasada de Alterac. Los exploradores indican que también han invadido las ruinas.\n\nSi dejamos que se queden ahí, su siguiente paso será bajar las colinas y llegar hasta nosotros.\n\nVe a liquidar ogros en las Montañas de Alterac, hacia el norte. Si quieres ganar un buen botín, tráeme todos los nudillos sucios que llevan.", progress = "¿Estás cazando ogros, <nombre>? ¿Me traes los nudillos sucios que te pedí?", completion = "Qué buen montón de nudillos sucios me traes, &lt;nombre&gt;. \n\nEspero que ahora los ogros nos dejen tranquilos; al menos, de momento.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][501] = {title = "lixir de dolor", objective = "Lleva 10 viales de sangre de león de montaña al boticario Lydon de Molino Tarren.", description = "Oh, <nombre>. En Trabalomas todo está florecido y el aire es puro y fresco. No puedo soportarlo. Miro por mi mugrienta ventana y espero el día en que nuestra Nueva Plaga traiga a este mundo la muerte que merece.\n\nAunque me gustaría perderme en mis negras reflexiones, el deber hacia la Dama Oscura me llama. ¿Quieres ayudarme? Según mis estudios, puedo obtener una estupenda poción letal con sangre de león de montaña. Tráeme un poco, verás qué bien lo pasaremos.", progress = "Ah, sí, <nombre>; ibas a ayudarme con mi elixir. Necesito la sangre para extender el dolor y la muerte en Trabalomas.", completion = "Excelente trabajo, &lt;nombre&gt;.", rewards = "Guantes de MoleBotas de pisotónBotas de caminafuegoRecibirás:\n\nReceta: chuletillas de león picantes"}
MultiLanguageQuestData['mx'][502] = {title = "lixir de dolor", objective = "Dale el elixir de dolor a Stanley.", description = "¡No hay nada como el olor a sangre fresca!\n\nAhora añadimos un poquito de esto y una pizca de esto otro ¡y ya está! Esta poción se llama elixir de dolor. Si mis cálculos son correctos, este brebaje complacerá enormemente a Lady Sylvanas. Pero antes hay que probarlo.\n\nLlévalo a la granja norteña de Campos de Trabalomas, que está al suroeste. A ver qué le parece esta golosina a Stanley, el perrito del granjero Ray.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][504] = {title = "Belicistas Aplastacresta", objective = "Mata a 10 belicistas Aplastacresta y vuelve a hablar con el alguacil Rutagrana en Costasur.", description = "Ahora que has conocido a los ogros Aplastacresta, quiero que les revientes las narices...\n\nVe a las Ruinas de Alterac y busca a esos belicistas Aplastacrestas. Quiero que liquides a un buen número de ellos. Es la única forma de que esos brutos aprendan a mantenerse alejados del territorio de la Alianza.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Rodela lunarEsquirla ardienteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][505] = {title = "ermandad de asesinos", objective = "Mata a 12 asaltantes de caminos y 8 ladrones de la Hermandad e informa al magistrado Henry Maleb en Costasur.", description = "Soy el nuevo magistrado de Costasur. Mi ilustre predecesor fue asesinado. No se ha encontrado a los asesinos, pero la investigación apunta a que eran mercenarios de la Hermandad, un grupo de ladrones liderados por unos nobles sin honor del desaparecido reino de Alterac.\n\nLa Hermandad tiene un campamento en el Saliente de Sofera y en Daga de Corahn, al norte y al oeste de Molino Tarren, territorio ocupado por la Horda. Elimina a los miembros de la Hermandad que encuentres en estos campamentos.", progress = nil, completion = "Gracias, &lt;nombre&gt;. Espero que algunos de los asaltantes de caminos y ladrones que has matado fueran responsables de la muerte del magistrado. Y aunque no fuera así, la Hermandad es una lacra que debe ser erradicada. \n\nEn Costasur se celebran esas muertes.", rewards = "Cinturón cruzadoGuantes aislantes de sabioRecibirás:\n\n"}
MultiLanguageQuestData['mx'][509] = {title = "lixir de agonía", objective = "Lleva 6 flores Morrobarro al boticario Lydon de Molino Tarren.", description = "Un día más, un elixir más. Si por mí fuera, dejaría que esos ridículos humanos y la Plaga se mataran mutuamente. De hecho, ese parece ser su único objetivo.\n\nNuestra Dama Oscura quiere acelerar el proceso, así que ¿por qué no pasar estos negros días sembrando muerte y enfermedad por el lugar?\n\nEste es el plan, <nombre>: ve a la Granja Nethander, al sur de Molino Tarren y al este del río y de Costasur. Tráeme seis flores Morrobarro para mi próximo elixir.", progress = "¿Qué tal en Granja Nethander?", completion = "Detesto la peste de las flores Morrobarro. Al menos esos asquerosos gnolls sirven para algo.", rewards = "Recibirás:\n\nPoción de prestezaPoción de sanación"}
MultiLanguageQuestData['mx'][510] = {title = "ocumentos de planificación", objective = "Lleva los documentos de planificación al magistrado Maleb a Costasur.", description = "Entre los documentos hay un pedido de suministros. Incluye objetos de uso diario (alimentos, armas, ropas) y otros menos usuales (máscaras, combustible, veneno).\n\nPero lo más importante es la urgencia del pedido: los suministros eran necesarios para lo que se describe como \"una importante misión contra Costasur.\"", progress = "¿Qué te preocupa, <nombre>? ¿Tienes algo que decir?", completion = "&lt;Maleb lee los documentos.&gt; \n\nEsto es muy inquietante, &lt;nombre&gt;. Por lo que dice aquí y por las acciones de la Hermandad, esos rufianes han declarado la guerra a Costasur.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][511] = {title = "na carta cifrada", objective = "Lleva la carta cifrada al maestro cultural Dibbs en Costasur.", description = "Una de las cartas de la mesa está cifrada y es inescrutable.", progress = "¿Sí, señor? ¿Quieres algo de mí?", completion = "¿Qué es esto? Espera... déjame verlo de cerca.\n\n...\n\nMm, nunca había visto este tipo de clave de encriptación, pero tengo que admitir que mi conocimiento en la materia dista de ser muy completo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][512] = {title = "Muertes nobles", objective = "Lleva 7 sellos de Alterac al magistrado Maleb a Costasur.", description = "Temo que la Hermandad aspire a provocar la caída de Costasur. Debemos eliminar a la cúpula para que no puedan llevar a cabo sus planes.\n\nVe a las ruinas de Strahnbrad; están al norte, en las Montañas de Alterac. Creemos que la Hermandad se concentra en esa zona.\n\nSabemos que los jefes de estos maleantes son antiguos nobles de Alterac. Puede que estén disfrazados de agentes ordinarios de la Hermandad, pero los distinguirás por los sellos que llevan.\n\nTráeme los sellos.", progress = "¿Te estás ocupando de la Hermandad? ¿Tienes los anillos?", completion = "Este golpe reducirá la libertad de acción de la Hermandad y los reducirá a la banda de maleantes que son. \n\nSirves muy bien a la Alianza, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][513] = {title = "lixir de agonía", objective = "Lleva el compuesto Morrobarro al maestro boticario Faranell a Entrañas.", description = "Justo cuando pensaba que este sería otro día triste y sin alegría, me traes estas maravillosas flores Morrobarro.\n\nEl primer paso es molerlas. Luego el maestro boticario Faranell de Entrañas aplicará su coloide de decadencia y ya estará listo.\n\nLlévale este compuesto Morrobarro al maestro boticario Faranell a toda prisa, <nombre>.", progress = "¿No ves que estoy ocupado, <clase>? La Dama Oscura quiere que prepare una nueva plaga antes de que la Plaga nos invada desde Rasganorte. Los humanos amenazan desde el sur y a mí me falta el tiempo. ¡Espero que esto sea importante!", completion = "¿Que te envía el boticario Lydon? ¡Haberlo dicho! \n\nPese a su pesimismo innato, es uno de los mejores. \n\n¡Y me envía compuesto Morrobarro! Ya sé que se trae entre manos nuestro amigo de Trabalomas. Me gusta su línea de pensamiento. La Dama Oscura estará muy complacida con los avances en la nueva peste.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][514] = {title = "Carta a Pico Tormenta", objective = "Lleva la carta cifrada con ingenio al prospector Pico Tormenta a Forjaz.", description = "Tengo un colega en Forjaz que quizás pueda descifrarla. Ve a la biblioteca de la Sala de los Expedicionarios, en Forjaz, y habla con el prospector Pico Tormenta. Dile que vas de mi parte y enséñale la carta. Si hay alguien que pueda descifrar esto al norte de Cumbre de Roca Negra, ese es él.", progress = "Así que te envía Dibbs de Costasur, ¿eh? ¿Cómo le va a esa ratilla de biblioteca?", completion = "Ah, sí, soy un especialista en códigos cifrados. A ver...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][515] = {title = "lixir de agonía", objective = "Lleva la mezcla Morrobarro, una poción de sangre de trol fuerte, 5 escamas Espinadaga y 5 ojos de aleta rasgados al boticario Lydon a Molino Tarren.", description = "¿Una mezcla Morrobarro? ¡Brillante! ¿Cómo no se me ha ocurrido a mí?\n\nVoy a añadir mi coloide de decadencia a este maléfico brebaje.\n\nPara activar los agentes contaminantes de este preparado, Lydon necesitará una poción de sangre de trol fuerte, escamas Espinadaga y ojos de aleta rasgados de la costa sur de Trabalomas. Él ya sabrá qué hacer con esos reactivos. ¡Ardo en deseos de saber el resultado del experimento!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Fajín de meditaciónCapa de gran boticarioRecibirás:\n\n"}
MultiLanguageQuestData['mx'][516] = {title = "El Desafío de Beren", objective = "Encuentra El Desafío de Beren y, a continuación, mata 6 esclavos Corvozarpa y 6 guardianes Corvozarpa. Por último, vuelve a ver al sacerdote de las Sombras Allister en El Sepulcro.", description = "Me han informado sobre un grupo de no-muertos que están reagrupándose para preparar un ataque contra nosotros. Con esta información, podemos hacer algo y atacar primero, poniendo fin de un manotazo a su pequeño plan.\n\nPor desgracia, la información de la que dispongo es bastante incompleta. Se supone que están escondidos en El Desafío de Beren. Se desconoce la ubicación exacta, pero parece ser una cueva en las colinas, cerca de unos magos de Dalaran.\n\nConfío en tus recursos. Encuéntrales y acaba con ellos.", progress = nil, completion = "Si nuestros exploradores y agentes continúan proporcionándonos información valiosa como esta, tendremos a la Plaga del Rey Exánime fuera de nuestras tierras en un abrir y cerrar de ojos.", rewards = "Recibirás:\n\nVarita de Descomposición"}
MultiLanguageQuestData['mx'][518] = {title = "orona de Voluntad", objective = "Melisara de Molino Tarren quiere que mates a 10 aplastadores Aplastacresta.", description = "Jarra'thol y sus ogros Aplastacresta han invadido las ruinas de Alterac. Tenemos que reducir sus filas si queremos castigarlo.\n\nPrimero los debilitamos y después procedemos.\n\n¿Entendido? Bien. Adelante.", progress = nil, completion = "La nieve está roja con la sangre de los ogros, pero no debemos cejar hasta que los Aplastacresta muerdan el polvo y sean aniquilados por completo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][522] = {title = "ontrato de asesino", objective = "Lleva el contrato de asesinato al magistrado Maleb a Costasur.", description = "Esto es un contrato para el asesinato del magistrado Henry Maleb. Estaba lacrado con cera roja y un sello muy distintivo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][525] = {title = "Más misterios", objective = "Lleva la carta descifrada al magistrado Maleb a Costasur.", description = "He descifrado la carta, pero no sé cómo interpretarla. ¿Y la tenían unos ladrones en las laderas de Alterac? Qué raro...\n\nLlévasela al magistrado de Costasur. Aunque la carta es críptica, su ciudad es la más cercana a Alterac; si se está cociendo algo, es mejor que lo sepa.", progress = "<nombre>, ¿has estado de viaje por las montañas otra vez? ¿Qué noticias traes?", completion = "&lt;Maleb lee la carta.&gt; \n\n¿Esto estaba en un campamento de la Hermandad? Esto no lo escribió un ladrón ni tampoco un noble de Alterac. \n\nParece que la Hermandad está aliada con otro poder; me estremezco al pensar cuál puede ser.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][527] = {title = "a batalla de Trabalomas", objective = "Mata a 6 mozos de labranza de Trabalomas y 6 granjeros de Trabalomas, al granjero Ray y al granjero Getz e informa a Darthalia en Molino Tarren.", description = "Stand at attention while addressing me, <clase>.\n\nI am under direct command of Sylvanas.  We are to quell the human infestation until our apothecaries can develop the new plague.\n\nOur information leads us to believe that the town of Hillsbrad is vulnerable to attack.  Your first assignment is aimed at disrupting their food supply and infrastructure.\n\nTravel west.  Raid the northernmost farms of Hillsbrad Fields.  Make sure that the landowners, Farmer Ray and Farmer Getz, are executed as well.", progress = nil, completion = "Descansa, &lt;clase&gt;. Mis fuentes me indican que luchaste bien en el frente de Trabalomas.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][528] = {title = "a batalla de Trabalomas", objective = "Mata a 15 campesinos de Trabalomas e informa a Darthalia en Molino Tarren.", description = "El ataque a las granjas del norte tiene aterrados a los lugareños. Excelente.\n\nNuestros mortacechadores informan que los campesinos huyen a los campos del sur de Trabalomas. Esos necios creen que pueden escapar a su destino escondiéndose en el huerto.\n\nPero se equivocan, <nombre>. Vuelve a Campos de Trabalomas y busca a los campesinos ocultos. Aniquílalos en el nombre de nuestra Dama Oscura.\n\nPuedes retirarte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][530] = {title = "La venganza de un esposo", objective = "Mata a Valdred Moray.\n\nLlévale sus manos a Raleigh Andrean, que está en Entrañas.", description = "Valdred, el que una vez fue mi mejor amigo, es el asesino de mi esposa. Aunque soy incapaz de llorar su muerte, sí que anhelo venganza. Si matas a Valdred y me traes sus manos malditas, te recompensaré.\n\nLa última información de que dispongo es que se encuentra en La Muralla de Cringris, al sur del Bosque de Argénteos, con intención de escapar al reino de Gilneas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAnillo de Desdén"}
MultiLanguageQuestData['mx'][533] = {title = "nfiltración", objective = "Consigue información sobre el paradero de Gol'dir's e informa a Krusk en Molino Tarren.", description = "Por fin empezamos a tener noticias acerca del paradero de Gol'dir. Los humanos lo han llevado de un lado a otro, pero hemos centrado la búsqueda en el campamento de la Hermandad que está al norte de aquí.\n\nVe ahí, <nombre>, y consigue toda la información que puedas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][536] = {title = "l lo largo de la costa", objective = "Mata a 10 cazamareas y 10 oráculos Rompeanca por orden del teniente Farren Orinelle de Costasur.", description = "Me han transferido de la guardia de la Ciudad de Ventormenta a Costasur, un lugar que merecería ser abandonado, a juzgar por su aspecto. No me quito de encima el olor a puerto.\n\nPor no hablar de Rutagrana... Quiere que me encargue de los múrlocs. ¡Ja!\n\nApenas me animo a acercarme a esos pescados gigantescos de la Playa del Oeste. Te agradecería mucho que te ocuparas de ello en mi lugar.", progress = nil, completion = "Espero que esto sea suficiente para convencer a Rutagrana de que he cumplido sus órdenes y he liberado a Costasur de la horrible amenaza de los temidos múrlocs... ¡Ya que no hay nada peor que los estragos de los peces demasiado grandes!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][537] = {title = "Consejo oscuro", objective = "Mata a 4 magos de la Sombra Argus.\n\nLleva la cabeza de Nagaz al magistrado Maleb de Costasur.", description = "La carta fue escrita por un ser que responde al nombre de Nagaz, miembro del Despertar de Argus. No sé quiénes son, pero si están aliados con la Hermandad debemos considerarlos una amenaza.\n\nQuiero que localices a Nagaz y a los magos de la Sombra Argus mencionados en la carta. Localízalos y elimínalos.\n\nExplora las Tierras Altas, el bastión de la Hermandad. Está al norte de Strahnbrad.\n\nCon un poco de suerte, encontrarás a los enviados del Despertar de Argus allí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][538] = {title = "Costasur", objective = "Habla con el maestro cultural Dibbs en Costasur.", description = "<nombre>. Si no te molestan los viajes largos, tengo una tarea para ti, para ayudar a llenar la biblioteca de Ventormenta.\n\nEl viejo reino de Alterac cayó tras la Gran Guerra y tenía una gran colección de libros. Es una tragedia que la ciudad esté en ruinas, pero mucho más trágico es haber perdido todo su conocimiento. Debemos recuperar todo lo que podamos.\n\nCostasur es la ciudad más próxima a las Ruinas de Alterac. Vete allí y habla con el maestro cultural Dibbs. Podrá guiarte hasta las ruinas y sabe qué libros puedes encontrar allí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][543] = {title = "La Tiara Perenolde", objective = "Recupera la Tiara Perenolde.", description = "La Tiara Perenolde es una antigua reliquia familiar de los \"nobles\" Perenolde, la familia soberana de Alterac antes de que comenzara el declive del reino. Se dice que ha sido forjada por los maestros joyeros de Forjaz y que lleva engarzadas unas esmeraldas de gran calidad.\n\nCuando Alterac fue destruido, se perdió la Tiara, pero corren rumores de que un ogro mago, Grel'borg el Avaro, encontró la Tiara y ahora vaga por las Ruinas de Alterac en busca de más tesoros.\n\nNos gustaría que recuperases la Tiara para nosotros.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][544] = {title = "olarse en la cárcel", objective = "Localiza a los traidores y recupera los objetos robados. Luego habla otra vez con el magus Vacuamirada en Molino Tarren.", description = "Había venido a Molino Tarren para estudiar, pero ahora debo solucionar una crisis. Verás, hace unos meses, cuatro Renegados huyeron de Entrañas. Dieron la espalda a su gente, pero lo peor es que robaron a la Dama Oscura.\n\nEntraron en una cámara de seguridad y robaron cuatro objetos que usaron nuestros boticarios en algunos proyectos. Sylvanas quiere recuperar esos objetos.\n\nLos ladrones huyeron de Entrañas a Dalaran y esos magos los pusieron en cuarentena en el Campo de Reclusión de Lordamere.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][546] = {title = "ecuerdos de muerte", objective = "El Guardia de la Muerte Samsa de Molino Tarren quiere 30 calaveras humanas de Trabalomas.", description = "Oí que has sido reclutado por Darthalia para luchar contra los humanos de Trabalomas. Estoy celoso.\n\nMientras tú te diviertes matando humanos, saqueando el pueblo y aterrorizando a gente inocente... yo estoy aquí clavado haciendo guardia en el Molino Tarren.\n\n¿No podrías apiadarte de un viejo Guardia de la Muerte como yo? Verás, colecciono calaveras humanas. Y tú pasarás algún tiempo combatiendo contra humanos. Reúne 30 calaveras mientras combates tu larga batalla y tráemelas. Haré que te merezca la pena.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAnillo calavera"}
MultiLanguageQuestData['mx'][547] = {title = "a espada de Humbert", objective = "Recoge la espada del Guardia de la Muerte Humbert en Dun Garok y llévasela a Molino Tarren.", description = "La suma ejecutora Darthalia me envió a vigilar Dun Garok desde cierta distancia. Acampé donde no pudieran verme. A la mañana siguiente fui a buscar leña para el fuego.\n\nY al volver descubrí que me habían robado el equipamiento.\n\nParece que unos exploradores enanos de Dun Garok pasaron por allí y se lo llevaron todo. ¡Necesito la espada! Te agradecería mucho que me la trajeras. Aquí hay tantos enanos que será difícil descubrir al ladrón.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Coraza de canaléLeotardos de mercenarioRecibirás:\n\n"}
MultiLanguageQuestData['mx'][549] = {title = "E BUSCA: Personal de la Hermandad", objective = "Mata a 10 pícaros y 10 veladores de la Hermandad. La suma ejecutora Darthalia te dará tu recompensa en Molino Tarren.", description = "Por orden de la Lady Sylvanas, se decreta la pena de muerte para todos los miembros de la organización conocida como la Hermandad. Aquellos que sean tomados como prisioneros serán ejecutados. Se sabe que se están reuniendo en las ruinas del Castillo de Durnholde, al sureste de Molino Tarren.\n\nSe ofrece una generosa recompensa a quien pueda dar cuenta de sus actividades a la suma ejecutora Darthalia.", progress = nil, completion = "Excelente, &lt;clase&gt;. Pronto conseguiremos librarnos definitivamente de la Hermandad.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][550] = {title = "a batalla de Trabalomas", objective = "Lleva la mención de honor lacrada de Darthalia a Bragor Puñosangre, que está en Entrañas.", description = "He redactado una mención de honor describiendo tu heroica actitud en combate para que el alto mando reconozca tu valor y entrega en la Batalla de Trabalomas.\n\nLleva esta mención lacrada a Bragor Puñosangre; está en Entrañas. Ve con la frente muy alta, <clase>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Escudo calaveraHoja oscura rúnicaCalzas de entierro sacroRecibirás:\n\nSortija de Entrañas"}
MultiLanguageQuestData['mx'][551] = {title = "El papiro encantado", objective = "Lleva el pergamino encantado al maestro cultural Dibbs a Costasur en las Laderas de Trabalomas.", description = "Este papiro está encantado con un hechizo que lo hace indescifrable. Aunque se puede leer una palabra en la parte de arriba:\n\n\nNagaz\n\n", progress = "Oh. ¿Tienes algo que te gustaría que viera? Algún resto de tradición recolectado en las montañas, espero...", completion = "¿Más notas cifradas? \n\nOjalá tuviera el talento para descifrar todos estos extraños signos que nos llegan de Alterac. Pero me temo que me falta el conocimiento necesario.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][552] = {title = "a venganza de Helcular", objective = "Róbale la Vara de Helcular a los yetis y llévasela al novicio Thaivand a Molino Tarren.", description = "El maestro Helcular casi había completado su transformación en exánime cuando una multitud airada descubrió su refugio ritual en las colinas y lo asesinó brutalmente. Para empeorar las cosas, lo enterraron en el cementerio de Costasur.\n\nTamaño desprecio por tan gran mago es inaceptable. Yo, su aprendiz, me aseguraré de que el fuego de la venganza arrase Costasur.\n\nNecesitamos la Vara de Helcular. Los yeti invadieron el refugio ritual. Seguro que una de esas bestias tiene la vara.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][554] = {title = "La descodificación de Pico Tormenta", objective = "Lleva el papiro codificado al prospector Pico Tormenta a Forjaz.", description = "El prospector Pico Tormenta es un maestro de la descodificación. Llévale el papiro que has encontrado; con un poco de suerte, podrá descifrarlo. Está estudiando en la oficina central de prospección, en Forjaz.\n\nDile que has hablado conmigo; últimamente le mando bastante trabajo.", progress = "¡¿Otra interrupción?!\n\nAh, este pergamino está protegido por un hechizo muy complicado. Puedo descifrarlo, pero me llevará tiempo y no tengo mucho...\n\n¿Y si me lo vendes?", completion = "Sabia decisión. Soy el único que puede descifrarlo. Y no te preocupes, te informaré de su contenido.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][555] = {title = "opa de tortuga reconfortante", objective = "Lleva 10 piezas de carne de tortuga y al chef Jessen a Costasur.", description = "¡Lo que más vas a apreciar en Costasur es que tenemos la mejor cocina al norte de Ventormenta!\n\nPor ejemplo, mi sopa de tortuga. Sé de gente que ha venido incluso de Villa Oscura solo para probarla. Por cierto, hace mucho que no la hago. Antes iba pasado Dalaran hasta el Lago Lordamere para cazar quijafortes, pero ahora es demasiado peligroso. ¡Si me traes carne de tortuga de la de los quijafortes del norte te preparo una sopa!", progress = "¿Has encontrado los ingredientes? Esta tierra ya no es tan tranquila como antes. Ay, qué tiempos...", completion = "Todo el mundo estará encantado: ¡la sopa de tortuga del chef Jessen vuelve al menú!", rewards = "Recibirás:\n\nReceta: sopa de tortuga reconfortanteSopa de tortuga reconfortante"}
MultiLanguageQuestData['mx'][556] = {title = "uestras de piedra", objective = "Lleva 10 muestras de piedra desgastada al vigilante Bel'varil de Molino Tarren.", description = "Los magos de Dalaran tienen una notable facilidad para relacionarse con elementales, que son poderosas criaturas de otras dimensiones. Los magos controlan a los elementales con talismanes mágicos. El mago Vacuamirada quiere analizar estos talismanes.\n\nVe a buscarlos al territorio de los magos de Dalaran, al oeste de Trabalomas.\n\nCualquier ciudadano de Dalaran puede llevar uno, pero te sugiero que busques en el campo de reclusión. Es más seguro que ir a Dalaran.", progress = "¿Traes las muestras de piedra desgastada, <nombre>? El mago está deseando estudiarlas.", completion = "Estupendo; aunque su magia parece gastada, estas muestras son perfectas para estudiarlas. \n\nGracias, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][559] = {title = "La prueba de Farren", objective = "Recoge 10 cabezas de múrloc en la Playa del Oeste por orden del teniente Farren Orinelle de Costasur.", description = "¿Qué te parece, <nombre>? A Rutagrana no le basta con todos los múrlocs que hemos matado. Sí, hemos, tú también has tenido algo que ver. Ahora quiere que le traiga pruebas, que me dedique a rebanar cabezas de múrloc para que las inspeccione.", progress = "¿Me traes las cabezas, <nombre>?", completion = "¡Lo estás poniendo todo perdido! \n\nYo no puedo tocar esas cosas; el pescado vaya y pase, pero estos bichos... Puaj. Llevo semanas sin comer pescado, y en Costasur eso es mucho decir", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][560] = {title = "La prueba de Farren", objective = "Entrega las cabezas de múrloc al alguacil Rutagrana de Costasur.", description = "Verás, <nombre>, a mí esto de las cabezas me pone mal cuerpo... Ya que le has cogido el gusto a la cosa, ¿te importaría ir a llevárselas a Rutagrana por mí?", progress = "Saludos. ¿Vienes a ayudar en la defensa de Costasur?", completion = "Así que te envía Farren, ¿eh? \n\nSi tuviste algo que ver con las cabezas, te lo agradezco; en Costasur necesitamos gente dispuesta a trabajar.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][561] = {title = "La prueba de Farren", objective = "Habla con el teniente Farren Orinelle en Costasur.", description = "Informa al teniente Orinelle que debe concentrarse en los nagas que han infestado la Playa del Este. Dile que me informe personalmente del resultado de la operación.", progress = nil, completion = "Los nagas, ¿eh? Pues va listo Rutagrana si cree que va a ganarse una medalla a mi costa. Ahora te explico.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][562] = {title = "Cambio de destino", objective = "Mata a 10 cazacostas y 10 sirenas Espinadaga por orden del teniente Farren Orinelle de Costasur.", description = "Mi antiguo mentor de la guardia de la Ciudad de Ventormenta me dice que el alto mando de la Alianza está preocupado por la amenaza de los nagas. Según él, quien pueda ayudar a este respecto recibirá un ascenso, o al menos un cambio de destino.\n\nSolo hay un problema... No puedo enfrentarme a los nagas, <nombre>. Puedo intervenir en una pelea de borrachos o reducir a un indigente belicoso, pero los nagas me superan. ¡<nombre>, tienes que ayudarme!", progress = nil, completion = "Ahora que no hay nagas en Costasur, estoy más cerca de que me devuelvan a Ventormenta y salir de aquí de una vez.", rewards = "Recibirás:\n\nDestripapeces"}
MultiLanguageQuestData['mx'][563] = {title = "Nueva asignación", objective = "Entrega el informe de Farren al mayor Samuelson en el Castillo de Ventormenta.", description = "No debería ser un problema conseguir que vea mi informe. El nuevo capitán de la guardia, el mayor Samuelson, fue mi mentor cuando estuve destinado en Ventormenta. Eso debería ser excusa suficiente para que me traslade a la ciudad de nuevo. Pero necesitaré que le lleves mi informe... no quiero que Rutagrana se entere de nada.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][564] = {title = "na amenaza costosa", objective = "Darren Malavista de Costasur quiere que mates 8 leones de montaña y 10 leones de montaña descomunales.", description = "Nada me duele más que perder estos hermosos caballos. Y hemos perdido unos cuantos entre los puñeteros no-muertos, la maldita Hermandad y toda la demás chusma que corre por aquí.\n\nPero te juro por mi abuelo que la amenaza más grave para los caballos son los leones de montaña de Alterac. ¡Siempre bajan de la montaña y me complican la vida!\n\n¿Te apetece una aventura? ¡Pues ve y ocúpate de ellos!", progress = nil, completion = "¡Me alegro de oír eso! Ya sabía yo que tú me resolverías el problema... ¡Eres un orgullo para tu familia, &lt;nombre&gt;!", rewards = "Faja de pastorGuantes de pastorRecibirás:\n\nReceta: filete de león sabrosoFilete de león sabroso"}
MultiLanguageQuestData['mx'][565] = {title = "apa de piel de yeti de Bartolo", objective = "Lleva una madeja de lana, una capa de montañero, hilo refinado y 10 trozos de piel de yeti a Bartolo Ginsetti a Costasur.", description = "Yo, el gran Bartolo, te haré una de mis capas de piel de yeti, admiradas por toda la Alianza.\n\nTe desafío a recorrer el mundo en busca de una capa mejor. ¿Cómo dices, <raza>? \"¡Bartolo, no hay una capa mejor!\" Sí, sí. Ya lo había oído antes.\n\nBartolo necesita una madeja de lana, una capa de montañero hecha por un buen peletero, hilo refinado y, naturalmente, piel de yeti. ¡Tráeme todo eso y te haré una capa magnífica!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCapa de pelaje de yeti"}
MultiLanguageQuestData['mx'][567] = {title = "Peligrosos!", objective = "La suma ejecutora Darthalia de Molino Tarren ofrece recompensa por el funcionario Horraceio Corzalbal, el ciudadano Wilkes, el minero Hackett y la granjera Kalaba.", description = "¡Atención!\n\nLos siguientes humanos de Trabalomas son peligrosos. La suma ejecutora Darthalia ha designado una recompensa por su captura:\n\nFuncionario Horracio Corzalbal. Se busca por el asesinato del Guardia de la Muerte Toma.\n\nCiudadano Wilkes. Se busca por el asesinato del boticario Eli.\n\nMinero Hackett. Se busca por el asesinato del mortacechador Fry.\n\nGranjera Kalaba. Se busca por el bloqueo de suministros de Entrañas.\n\nTodos estos enemigos se encuentran fugados y su captura se hará difícil. Se recompensará a quien pueda certificar su muerte.", progress = nil, completion = "Excelente, &lt;clase&gt;. Buen trabajo.", rewards = "Arco de saqueoRodela de avizorVarita carbonizadaRecibirás:\n\nCogulla"}
MultiLanguageQuestData['mx'][568] = {title = "La defensa de Grom'gol", objective = "El comandante Aggro'gosh del Campamento Grom'gol, quiere que mates 15 raptores colazote.", description = "¡Throm'ka, <clase>!\n\nLlegas a tiempo a Grom'gol. Como Comandante del campamento base del Jefe de Guerra aquí, en la jungla, he jurado encargarme de la seguridad de todos los miembros de la Horda. Nuestra misión de proporcionar una cadena de suministros segura hasta Rocal se ha visto obstaculizada por algunos de los habitantes locales.\n\nTe pongo al cargo de disminuir la población de raptores en las afueras de Grom'gol. Cuando hayas conseguido un avance significativo, vuelve a informarme y te reasignaré.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][569] = {title = "La defensa de Grom'gol", objective = "El comandante Aggro'gosh del Campamento Grom'gol, quiere que mates 10 toscos ogros y 5 médicos brujos ogros.", description = "Cuando llegamos por primera vez a esta jungla, no pretendíamos tener que luchar con las tribus locales. Nuestra primera prioridad es enviar suministros a Rocal. Pero han surgido complicaciones. Una banda de ogros ha ocupado las Ruinas de Mizjah al sureste de Grom'gol. A pesar de las advertencias, siguen preparando emboscadas a nuestras caravanas de suministros.\n\nTe pongo al cargo de tratar con esos ogros tan poco cooperativos.\n\nVete a las Ruinas e intenta expulsarlos de la zona. Al menos, con esto les mandaremos un firme mensaje.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nRodela Grom'gol"}
MultiLanguageQuestData['mx'][570] = {title = "El encantamiento de Mok'thardin", objective = "El clarividente Mok'thardin del Campamento Grom'gol, quiere 8 garras Faucesombría y un colmillo de tigresa prístino.", description = "La Horda tiene que darse cuenta del poder de la magia de la jungla y, después, utilizarlo. Hasta ahora, mis rituales han tenido éxito. Puedo lanzar encantamientos muy poderosos. Para ti, valiente <clase>, crearé un objeto muy especial.\n\nTráeme algunas garras de panteras Faucesombría junto con un colmillo de tigresa. No valdrá cualquier colmillo. Debe estar en perfecto estado.\n\nLas bestias moran en la jungla, pero encontrarás algunas por aquí cerca, justo al otro lado del río que va desde las Ruinas de Mizjah hasta el sureste.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][571] = {title = "El encantamiento de Mok'thardin", objective = "Lleva un tendón de gorila mayor al clarividente Mok'thardin en Grom'gol.", description = "Lo que necesito ahora, es bastante difícil de conseguir.\n\nPara guardar las plumas, las zarpas y el colmillo inmaculado, necesito una cadena mágica. Solo servirá un tendón de gorila mayor.\n\nEl único lugar donde podrás encontrar uno es en un gorila Velo de Bruma anciano. Suelen ir a por comida al este de la Bahía del Botín.\n\nEl tendón debe ser perfecto. Quizás necesites usar algunas de tus habilidades para encontrar exactamente lo que necesito, pero merecerá la pena.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][572] = {title = "El encantamiento de Mok'thardin", objective = "Lleva 10 plumas de acechadores de la selva al clarividente Mok'thardin en el Campamento Grom'gol.", description = "Los objetos que has conseguido de las bestias felinas del Valle son solo el primer requisito para un poderoso objeto encantado. Estas joyas de la selva combinadas con mi ritual chamanístico, te proporcionarán una herramienta muy útil para ayudar a la Horda y al Jefe de Guerra.\n\nPero ahora debes conseguirme Plumas de acechadores de la selva. Tradicionalmente, las bestias llevan las plumas en sus brazaletes. Encontrarás una tribu de raptores directamente al sur de Grom'gol, no muy lejos de La Gran Arena.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][574] = {title = "Fuerzas especiales", objective = "Mata 10 comandos de Kurzen y 6 reductores de cabezas de Kurzen.\n\nPreséntate ante el teniente Doren en el Asentamiento Rebelde.", description = "Ahora que hemos conseguido reducir algunas de sus tropas regulares, debes enfrentarte a las tropas de élite. Cuando no están fuera matando a nuestros soldados rebeldes, se retiran a las profundidades de la parte trasera de la Base de Kurzen, a una cueva a la que llaman Las Reservas.\n\nConozco personalmente a muchas de las tropas de Kurzen y sé que son habilidosas, leales y crueles. La tarea que tienes ante ti no es fácil, <nombre>.\n\nCuando las derrotes, informa al teniente Doren, mi oficial en jefe. Quiere recibir tu informe de primera mano.", progress = "La sargento Yohwa me dice que eres muy hábil y valiente, <clase>. ¿Tienes que informarme de algo?", completion = "&lt;nombre&gt;. La sargento Yohwa confiaba en tus habilidades y yo confío en ella. La derrota de las tropas de Kurzen es casi demasiado buena para ser verdad. Temía que los rebeldes estábamos solos y que nadie se podría enfrentar a al gran coronel. \n\nQuizás todavía nos quede alguna esperanza de sobrevivir.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][575] = {title = "La oferta y la demanda", objective = "Lleva 2 pieles grandes de crocoliscos fluviales a Drizzlik en la Bahía del Botín.", description = "\"El mejor artesano peletero de los Mares del Sur, del mundo antiguo y del mundo nuevo.\" ¡Así es como me llaman! ¡A mí! ¡Drizzlik! El mejor... ejem. Bueno.\n\nMis objetos de cuero se conocen en el mundo entero como los más exquisitos, ¡la elección de los entendidos!\n\nAcabo de recibir un pedido del director Riddlevox del Gremio de Manitas, de una docena de borceguíes. El producto que más vendemos.\n\nPara el molde básico, necesitaré pieles de crocolisco de los crocoliscos que están en el río de la parte norte de Tuercespina.", progress = "Tengo todo el equipamiento listo, <nombre>, solo necesito esas pieles. No queremos que Riddlevox tenga que esperar, eso queda claro.\n\nNo es buena idea que nadie deje insatisfecho al inventor jefe del Gremio de Manitas.", completion = "Con estas pieles será suficiente. La calidad no es demasiado importante, visto que se utilizarán para la capa interior de las botas, pero es importante que sean cómodas. \n\nSi son demasiado rígidas, utilizaré sangre de tigre para ablandarlas. Trucos del oficio, ¿sabes?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][576] = {title = "¡Ojo!", objective = "Dizzy el Tuerto, en la Bahía del Botín, quiere que recuperes su ojo de los Bucaneros Velasangre.", description = "¡Alto! ¿Quién va?\n\nAaah, no soy na sin mi ojo encantao especial. ¡De entrada ya fue bah'tante malo perdel mi propio ojo en combate! Pero, por un golpe de sueh'te, atracamo en Menethil y un zahorí viajante encantó un ojo especial de cristal para que pudiera ver de nuevo.\n\nAyel por la noche uno Bucaneros Velasangre me atacaron cuando salía. ¡Y cogieron mi ojo! Parece ser que esos tipos han conseguio llegal a la Bahía del Botín.\n\n¿Quieres ayudal a un viejo lobo de mar a recuperal su ojo?", progress = "¡Ah del bac-co, cheche! Quizás no puedo vel, pero te huelo desde el otro lao del puerto.\n\nMe vendría muy bien recuperal el ojo. El capitán va a pasarme por la quilla cuando descubra que mi aujero de ver lo tienen esos asqueroso Bucaneros Velasangre.\n\n¿De qué vale un oteador que no puede vel? La cofa solía ser mi hogar... ahora, sin mi ojo, tendré sueh'te si puedo fregal la quilla.", completion = "¡Voto a bríos! ¡Has encontrao mi precioso ojo! Veamos si sigue funcionando. \n\n¡Jo, jo, jo, &lt;nombre&gt;! ¡¡Fantástico, puedo vel!!", rewards = "Recibirás:\n\nManteo marea oscura"}
MultiLanguageQuestData['mx'][577] = {title = "Hay que ensamblar", objective = "Lleva 5 pieles de crocoliscos Quijaforte a Drizzlik en la Bahía del Botín.", description = "Bien, ya tengo el molde básico y todo va bien, pero con las pieles que has traído no tendré suficiente para las capas interiores.\n\n\"¿Qué vamos a hacer, Drizzlik?\" Sin duda esa es la pregunta que ibas a hacer y, en fin, qué suerte que estés hablando con Drizzlik, porque te va a decir lo que vamos a hacer.\n\nLas capas interiores no se ven, así que podemos conseguir unas pieles más gruesas y baratas de los crocoliscos que están por el Lago Nazferiti.", progress = "Las botas de cuero estilo borceguí de Drizzlik, la mejor artesanía, cien por cien botas de piel de crocolisco marino de la mejor calidad. ¡Insuperables!\n\n¿A que no se puede superar una descripción como esa, eh?\n\nA no ser... ¿tienes esas pieles que te pedí?", completion = "Mis botas... son como salchichas, &lt;nombre&gt;. Tienen una pinta estupenda y están buenísimas. Te digo que están hechas solo con las mejores carnes e ingredientes y, si las pruebas, te encantarán. \n\nEs más seguro, y más agradable, que simplemente confíes en mí y no preguntes lo que tienen dentro.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][578] = {title = "La piedra de las mareas", objective = "Encuentra la isla encantada para el Barón Revilgaz en la Bahía del Botín.", description = "Si realmente hay un mago goblin y elementales de agua en esa isla, ¡la Piedra de las Mareas podría ser mía!\n\nQuiero que encuentres esa isla encantada... descubre lo que está pasando. Oh, y si quieres saber algo más sobre la Piedra de las Mareas, lleva este manuscrito a la Biblioteca de Ventormenta, deberían poder encontrarte una copia del libro donde me encontré la leyenda por primera vez.\n\n¿Podría ser que Gazban realmente descubriese la Piedra...?", progress = nil, completion = "¡Así que las historias eran ciertas! ¡Increíble! \n\nSin embargo, necesitaremos descubrir la forma de acabar con la maldición de la Piedra de las Mareas si queremos recuperarla. La maldición conlleva magia, así que necesitaremos a uno de esos zahoríes para que nos ayude.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][580] = {title = "El grog de Whiskey el Delgado", objective = "Whiskey el Delgado, en la Bahía del Botín, quiere que le lleves las botellas de oporto Pupellyverbos que perdió.", description = "Estábamos ajustando la braza mayor y soplaba fuerte en Los Acantilados Dominantes, veíamos las Tierras del Interior a distancia. Creí que el mar iba a tragarnos enteros.\n\nEl viejo Slim lo sabe todo sobre la valentía líquida. El capitán tenía una caja de oporto Pupellyverbos que le encargamos a un corsario que iba a Ventormenta.\n\nAsí que cuando cayó la tormenta de las Tierras del Interior, trinqué el grog. Una gran ola y todas las botellas cayeron por la borda. El capitán va a darme una buena paliza si no me ayudas a recuperarlas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nRon Rumsey"}
MultiLanguageQuestData['mx'][581] = {title = "Caza para Yenniku", objective = "Lleva 9 colmillos Sangrapellejo a Nimboya en el Campamento Grom'gol.", description = "Es su fin, sí. El fin de Yenniku, el hijo menor de mi jefe. Como es tradición entre nuestra gente, fue entregao a los trols Gurubashi Trolls de Zul'Gurub pero, deh'pués de que mi tribu, los Lanza Negra, pa'htiese con el orco Thrall, le perdimos el rastro al pobre Yenniku. Me enviaron de la distante Orgrimmar, de vuelta a Tuercespina, para buscá al hijo de mi jefe.\n\nY creo que la tribu Sangrapellejo lo tiene.\n\nSi quieres ayudarme, da caza a los Sangrapellejo. Los encontrarás al norte. Reúne sus colmillos y tráemelos.", progress = "<clase>. Demuéh'trame que has dao caza a la tribu Sangrapellejo.\n\nMuéh'trame tus trofeos.", completion = "Buenos colmillos, &lt;nombre&gt;. Has demostrao la fuerza necesaria para dar caza a los Sangrapellejo.\n\nEso eh'tá bien, aún no has terminao con ellos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][582] = {title = "Caza cabezas", objective = "Lleva 20 cabezas reducidas a Nimboya en el Campamento Grom'gol.", description = "Hemos de descubrí si Yenniku eh'tá muerto.\n\nMata a los rebanacabezas Sangrapellejo y arrebátales sus cabezas reducidas. Tienes que reuní muchas, muchas cabezas y yo las inspeccionaré para vé que la de Yenniku no eh'té entre ellas.\n\nY, si Yenniku murió a manos de los Sangrapellejo, ¡una maldición de 600 años caerá sobre el eh'píritu de Gan'zulah, su jefe!\n\nVenga, <nombre>. Encontrarás muchos rebanacabezas en la Ruinas Zuuldaia y Zul'Kunda, a lo largo de la costa del norte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Braquiales Lanza NegraPuños Lanza NegraRecibirás:\n\n"}
MultiLanguageQuestData['mx'][583] = {title = "Bienvenido a la jungla", objective = "Habla con Hemet Nesingwary Jr.", description = "¡<Bienvenido/Bienvenida> a Tuercespina!\n\nPor si no lo sabes, aquel enano de allí es el hijo del mismísimo Hemet Nesingwary, famoso héroe de guerra de la Alianza y maestro de la caza mayor. Igual que a su padre, no le gusta tener a desconocidos en el campamento, pero tú tienes cara de haber guerreado bastante, <clase>.\n\nHabla con él; ha heredado el talento cazador de su padre, así que podrá darte buenos consejos.", progress = nil, completion = "Encantado de conocerte, &lt;nombre&gt;. Llevaba tiempo sin ver a un &lt;clase&gt; por aquí. \n\nMe he ubicado aquí con esta expedición con un propósito: cazar a una bestia enorme y muy escurridiza. Como te veo muy capaz, estoy dispuesto a incluirte en la partida de caza, pero antes tienes que probar tu valía. \n\nYo te enseñaré a cazar raptores. Ajeck te enseñará a cazar tigres y Sir Erlgadin es un maestro del rastreo de panteras. \n\nDemuestra tu capacidad y te dejaré participar en la gran caza.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][584] = {title = "Las cabezas de los Sangrapellejo", objective = "Lleva la cabeza de Gan'zulah y la cabeza de Nezzliok a la caldera en ebullición en el Campamento Grom'gol.", description = "Doy gracias a la Gran serpiente de que la cabeza de Yenniku no eh'tuviese entre las que me has traído. Pero eso no nos facilita el encontrarlo.\n\nHemos de descubrir la verdad y me temo que solo el jefe de los Sangrapellejo y su médico brujo lo saben. Son los enemigos de la tribu Lanza Negra y no van a coloborá, ¡así que tenemos que sacá la verdad de sus labios muertos!\n\nTráeme las cabezas de Gan'zulah y Nezzliok el Temible y colócalas en esta caldera.\n\nEstán en las profundidades de Zul'Kunda. Trae sus cabezas... Las haremos hablá.", progress = "El caldo verde de la caldera está hirviendo.", completion = "Colocas las cabezas de Gan'zulah y Nezzliok en la caldera...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][585] = {title = "Hablando con Nezzliok", objective = "Lleva un trofeo de Balia'mah, un trofeo de Ziata'jai y un trofeo de Zul'Mamwe a la caldera en ebullición del Campamento Grom'gol.", description = "<La cabeza de Nezzliok habla.>\n\nEs cie'hto. Sé dónde se llevaron al niño de los Lanza Negra. Me has vencío y has sometido mi e'hpíritu, ¡pero no diré nada si no me apaciguas!\n\nLos Sangrapellejo eh'tán en guerra con los Machacacráneos. Para obtené mi favor, roba 3 cráneos trofeo a los Machacacráneos y colócalos aquí con nosotros, p'a que mi e'hpíritu tenga esclavos en el Vacío Abisal. Uno de los cráneos debe procedé de su pila de trofeos en Balia'mah, el otro debe vení de Ziata'jai y el último de Zul'Mamwe.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][586] = {title = "Hablando con Gan'zulah", objective = "Mata 8 cazadores Machacacráneos, 6 rebanacabezas Machacacráneos y 4 rabiosos Machacacráneos.\n\nLleva la armadura de Ana'thek rota a la caldera en ebullición del Campamento Grom'gol.", description = "<La cabeza de Gan'zulah habla.>\n\n¡Yo te maldigo! ¡Y maldigo a tus ancestros!\n\nSolo la sangre y la venganza podrán templar mi ira, así que si eso es lo que deseas... Haz esto:\n\nlánzate de pleno al corazón de los Machacacráneos, al este. Mata a los más fieros y, si sobrevives, enfréntate a su jefe, Ana'thek el Cruel. ¡Ja! Tráeme su armadura despedazada si puedes.\n\nQue te desgarre tus miembros y deje que tu carne se pudra y sea comida de buitres.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][587] = {title = "Tabaco rapé", objective = "Deeg, en la Bahía del Botín, quiere que le lleves 15 pizcas de tabaco.", description = "Ah, la vida del mar. No diré que es una buena vida, pero es mi vida.\n\nCuando llego a puet-to me guh'ta buscal una buena botella de grog y rapé de buena calidad. Unas costumbre muy mala, ¿pero qué es un pirata sin sus vicio, eh?\n\nAsí que te puede imaginal cómo me sentí cuando me enteré de que el herborih'ta de la ciudad se había ido y lo había vendio to. Parece ser que esos maldito asaltantes Velasangre secuestraron su cargamento.\n\nApuesto a que <un audaz/una audaz:c> <clase> como tú podría convencerlos para compartil las mercancías, ¿eh?", progress = "¿Has tenio suerte, camarada?", completion = "¡Muy bien hecho, &lt;nombre&gt;! ¡Y jut-to cuando yo también tengo que embarcal! No te lo puedo agradecel bah'tante, viejo amigo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][589] = {title = "Los cristales canto", objective = "Lleva 3 fragmentos azul pulsante a Kin'weelay en el Campamento Grom'gol.", description = "Las leyendas hablan de una joya oculta en las profundidades del corazón de Tuercespina. Llamamos a esa joya el Ojo de la mente, y tiene grandes poderes. Si consigues el Ojo, quizás podamos usarlo para traer de la oscuridad al joven Yenniku.\n\nPreguntaré a los espíritus de la jungla cómo encontrar el Ojo de la mente. Mientras lo hago, ve a la Mina de Cristal, al sureste de aquí y recoge fragmentos azul pulsante de los basiliscos Quijahierro. Los fragmentos son poco comunes, pero necesitamos su magia para conseguir dominar el Ojo de la mente.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][591] = {title = "El Ojo de la mente", objective = "Lleva el Ojo de la mente a Kin'weelay en el Campamento Grom'gol.", description = "El Ojo de la mente eh'tá en posesión de un ogro mago, al este de aquí, en las profundidades del Túmulo Ogro Mosh'Ogg. Se llama Mai'Zoth. Le conozco de cuando los Lanza Negra vivían en Tuercespina, es feroz y su magia es poderosa.\n\nY, si tiene el Ojo de la mente, entonces su magia será más fuerte todavía.\n\nDebes enfrentarte a Mai'Zoth y conseguí el Ojo de la mente. Se trata de una misión peligrosa, pero es la única opo'htunidad que tenemos de salvá a Yenniku.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][592] = {title = "Salvar a Yenniku", objective = "Lleva la gema de alma llena a Nimboya.", description = "He convertido el Ojo de la mente en una gema de alma. Tiene un doble propósito: debes usarla para aturdir a Yenniku y, cuando lo hayas hecho, colócala sobre su cabeza para atrapar su alma.\n\nA continuación, lleva la gema a Nimboya.\n\nYenniku vive con Zanzil el Desterrado, en las Ruinas de Aboraz, junto a La Costa de Cristal, en El Cabo de Tuercespina.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Bastón místico de NimboyaPodrás elegir una de estas recompensas:\n\nMedalla de Coraje\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][594] = {title = "Mensaje en una botella", objective = "Encuentra al autor del mensaje en la botella.", description = "La nota dice, con buena caligrafía:\n\nA quien pueda ayudarme.\n\nPor favor, necesito ayuda urgentemente. Un gran Cieloleno me tiene cautivo en una isla en los Mares del Sur.\n\nLas estrellas de la noche son extrañas y los árboles de la jungla oscurecen el firmamento pero, en los días más claros, puedo ver la Orilla Salvaje al noroeste y lo que parecen grandes barcos cargueros al suroeste.\n\nTe lo suplico, ven a rescatarme.", progress = nil, completion = "¿Has venido a liberarme?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][595] = {title = "Bucaneros Velasangre", objective = "El contramaestre Crazz quiere que eches un vistazo a la cala norte de la Bahía del Botín.", description = "Parece que tienes muchas ganas de ponerte a trabajar, colega. No tengo muy claro por qué <un/una> <raza> <clase> <marinero/marinera> de agua dulce, se ofrece a ayudar a los Asaltantes Aguasnegras, pero no voy a rechazar tu ayuda.\n\nNuestro barco acaba de atracar aquí, en la Bahía del Botín, y corren rumores de que nuestros rivales, esos malditos y asquerosos Bucaneros Velasangre, están por todo el sur de Tuercespina.\n\nTodos los hombres están muy ocupados dándole al grog y buscando damiselas. Lo que necesitamos es un explorador.\n\nExplora la cala que está justo al norte de la Bahía del Botín en La Costa Salvaje, a ver lo que descubres.", progress = nil, completion = "Encima del barril descubres un mapa que tiene escrito algo de forma apresurada y unas monedas.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][596] = {title = "Collares de huesos sangrientos", objective = "Lleva 25 collares de huesos sangrientos a Kin'weelay en el Campamento Grom'gol.", description = "Me enviaron a Grom'gol para ayudar a Nimboya en su misión, pero... yo también tengo razones para estar aquí.\n\nLa tribu Sangrapellejo es enemiga de mi tribu. Conseguir trofeos de nuestros enemigos nos da poder sobre ellos. Podrías ayudar a nuestra tribu dando caza a nuestros enemigos.\n\nViven al norte. Mata trols Sangrapellejo y coge sus collares de huesos sangrientos. Consigue muchos y tendrás una gran recompensa.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSortija de hueso de sangre"}
MultiLanguageQuestData['mx'][597] = {title = "Bucaneros Velasangre", objective = "Informa sobre tus descubrimientos al contramaestre Crazz en la Bahía del Botín.", description = "En el mapa, la Bahía del Botín aparece marcada con una \"X\" roja, dibujada exactamente en el lugar donde estás ahora.\n\nEl texto lleno de garabatos dice:\n\n\"Deben asegurar un campamento en esta ubicación y mantener la calma. Esperen la señal del puesto de mando del sur antes de atacar. Si alguien se aproxima, mátenlos.\"", progress = nil, completion = "Claro que me acuerdo de ti, &lt;clase&gt;. Veo que has vuelto de tu exploración...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][598] = {title = "Collar de hueso partido", objective = "Lleva 25 collares de hueso partidos a Kin'weelay en el Campamento Grom'gol.", description = "Ahora que has conseguido traerme trofeos de los Sangrapellejos, tengo otra misión para ti. La tribu de trols Machacacráneos vive al sureste y, durante años, hemos luchado con ellos. Si bien los Lanza Negra ya no estamos asentados en Tuercespina, estamos atados a nuestro conflicto con los Machacacráneos.\n\nVete a por ellos. Consigue sus collares de hueso partidos y vuelve a verme. Ayúdanos en nuestra guerra y conseguirás la amistad de los Lanza Negra.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Botas Lanza NegraZapatos Lanza NegraRecibirás:\n\n"}
MultiLanguageQuestData['mx'][599] = {title = "Bucaneros Velasangre", objective = "Informa del ataque planeado de los Velasangre al maestro de flota Cuernomarino.", description = "¡Voto a bríos! ¿Así que los Bucaneros Velasangre están planeando atacar la Bahía del Botín? ¡No me puedo creer lo de esos bribones! La Bahía del Botín siempre estará dominada por los Asaltantes Aguasnegras.\n\nEsto es más grande de lo que yo había pensado. Informa al maestro de flota Cuernomarino inmediatamente. Ese viejo lobo de mar está por la ciudad, en alguna parte...", progress = nil, completion = "¿Bucaneros Velasangre atacando Bahía del Botín? Para eso, podrían tirarse de Los Acantilados Dominantes abajo. De todas formas, trayendo esta información nos has hecho un gran servicio a mí y a mi flota de espadachines. Los Asaltantes Aguasnegras te dan las gracias.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][600] = {title = "La minería de Ventura y Cía.", objective = "Lleva 10 cristales canto azules a Loquillo Pinchabujas en la Bahía del Botín.", description = "Ventura y Cía. está llevando varias operaciones en Tuercespina que priva a los duros trabajadores goblins, como yo, de conseguir un dinero honrado. ¡Por favor, tienes que ayudarme!\n\nVentura y Cía. está excavando cerca de la Mina de Cristal, al norte. No pueden entrar en la Mina debido a los basiliscos, pero consiguen extraer cristales canto de las colinas de alrededor.\n\nCoge los cristales y demuéstrales que no son los amos de la jungla.\n\nY... mmm... ¡tráeme esos cristales como prueba!", progress = "¿Tienes esos cristales? ¡¡Los necesito!!\n\nVamos a ver... necesito saber que la maldita Ventura y Cía. está perdiendo terreno en Tuercespina. Porque, ¿sabes?, los profesionales honestos tenemos que vivir de algo...", completion = "¡Genial! ¡Estupendo! ¡¡Puedo conseguir mucho por esto!! \n\nEsa Ventura y Cía. eligieron la selva equivocada donde excavar, ¿eh? A todos nos vendría estupendamente bien que se fueran de aquí. \n\nGracias, &lt;nombre&gt;. Hoy has hecho una buena acción.", rewards = "Pala de plataEncendedor goblinRecibirás:\n\n"}
MultiLanguageQuestData['mx'][601] = {title = "Elementales de agua", objective = "Consigue 6 brazales de elementales de agua para el Barón Revilgaz en la Bahía del Botín.", description = "Sin duda, Gazban, el mago goblin que se rumorea que ha descubierto la Piedra de las Mareas, invocó a los elementales de agua. Como quizás sepas, la Piedra de las Mareas maldice a su portador, provocando que entre y salga del plano existencial...\n\nQuizás podamos encontrar la forma de contraatacar la maldición. Podemos conseguir que un mago de Dalaran analice el residuo mágico de uno de los brazales de un elemental de agua. Necesito que vuelvas a la isla y consigas algunos especímenes.", progress = "¿Has tenido suerte, <nombre>?", completion = "Mmm, no tengo capacidad para examinar los brazales y ver si alguno podría servirnos, pero seguro que, al menos uno, podrá ayudarnos. Llévalos a Dalaran y haz que un mago los vea. \n\nDespués de todo, yo no puedo irme tranquilamente de la Bahía del Botín para charlar con esos viejos magos cansados de la vida. \n\nNo me preocupa que alguien intente abrirse paso para convertirse en el nuevo barón. Nadie se interpone a Revilgaz y vive para contarlo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][602] = {title = "Análisis mágico", objective = "Lleva los brazales de elementales de agua al archimago Ansirem Tejerruna en el Cráter de Dalaran.", description = "Por lo que he oído, los magos de Dalaran han conseguido reconstruir su mágica ciudad. La han movido a Rasganorte y han dejado un cráter enorme. Sin embargo, algunos magos se han quedado aquí, seguro que alguno tiene algo de tiempo para echar un vistazo a los brazales. Si algo sé de los magos es que no pueden resistirse a un rompecabezas mágico.\n\nCoge la bolsa de brazales de elemental de agua y veamos si nos pueden ayudar con lo de la maldición de la Piedra. Busca al archimago Ansirem Tejerruna. Ya he tratado antes con él y es muy sabio.", progress = "Si no te importa, tengo mucho que hacer ahora mismo.", completion = "¿La Piedra de las Mareas? Muy interesante. Podría sorprenderte saber que yo escribí un libro... hace muchos años ya... sobre las leyendas del Imperio Gurubashi. Sé algo sobre la Piedra. \n\nAl menos uno de estos brazales parece tener un residuo mágico que creo poder analizar. \n\nVeamos...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][603] = {title = "Llave de Ansirem", objective = "Habla con Catelyn en la Bahía del Botín.", description = "El mago que tiene la Piedra está ampliando su poder mediante algún punto focal... un altar de algún tipo. Deberías poder detenerlo destruyéndolo.\n\nResulta que sé cómo hacerlo: hay una daga antigua, otra reliquia trol. Y solo hay un pequeño... problema.\n\nVerás, encontré la daga mientras estaba investigando en Tuercespina, pero se la di a mi testaruda hija, Catelyn, que se escapó a la Bahía del Botín para convertirse en pirata.", progress = nil, completion = "¿Mi daga? ¿Qué eres, una especie de comediante?\n\n¿Qué? ¿Quieres que repita una vez más la historia de cómo pasé del mejor luchador con cuchillos de Bahía del Botín al hazmerreír de la piratería?\n\nPerdí una pelea de cuchillos una vez contra uno de los Bucaneros Velasangre —malditos bastardos— y se llevó mi daga como botín.\n\nNo puedo ganarme la vida como luchador con cuchillos solo con un manojo de insultos y una lengua afilada...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][604] = {title = "Bucaneros Velasangre", objective = "El maestro de flota Cuernomarino en la Bahía del Botín quiere que mates 10 espadachines Velasangre y le lleves las cartas de navegación y las órdenes de los Velasangre.", description = "Crazz habla muy bien de tu entrega a los Asaltantes Aguasnegras. Voy a confiarte una misión de vital importancia para la flota.\n\nInfíltrate en el puesto de mando del sur que los Bucaneros Velasangre han establecido en la Orilla Salvaje. Asalta el campamento. Tráeme sus cartas de navegación y las órdenes escritas. Veremos exactamente qué pretenden hacer esas babosas.", progress = "Ah del barco, <nombre>. ¿Qué noticias traes del campamento Velasangre del sur?", completion = "Perfecto, &lt;nombre&gt;. Ahora que conocemos su plan, solo es cuestión de tiempo. \n\nY pensar que esos imbéciles han soltado el ancla justo fuera del cabo...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][605] = {title = "Fragmentos de cristales canto azules", objective = "Lleva 10 fragmentos de cristales canto a Loquillo Pinchabujas.", description = "Solo hay cristales canto en Tuercespina y, para ciertos grupos, son muy valiosos. Yo puedo conseguir esos cristales, pero la maldita Ventura y Cía. ha complicado las cosas para los empresarios como yo.\n\nMe gustaría contratarte.\n\nLos basiliscos de Tuercespina comen esos cristales. Eso es lo que les da su piel endurecida y, algunas veces, se pueden conseguir cristales de calidad decente de la piel.\n\nPuedes conseguirlos de cualquier basilisco, pero los menos asquerosos están en la orilla sur de Zul'Kunda, hacia el norte.", progress = "¿Tienes esos fragmentos ya? ¡Te daré un buen porcentaje de los beneficios!", completion = "¡Ajá! Esto será perfecto, &lt;nombre&gt;. ¡Sí, excelente!\n\nAquí tienes tu parte y... ha sido un placer hacer negocios contigo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][606] = {title = "Asusta al Trémulo", objective = "Lleva 5 menudillos de Velo de Bruma a Phillipe el \"Trémulo\" en la Bahía del Botín.", description = "Si hay algo que no soporto, ¡es la gente que no paga sus deudas de juego! Y hay muchos que me deben dinero. ¿Crees que podrías ayudarme?\n\nPrimero, está Phillipe el \"Trémulo\", ahí, en el muelle. Me debe mucho después del juego de la semana pasada, ¡y quiero lo que me corresponde! Pero para conseguirlo, tendremos que asustarle.\n\nSal de la ciudad y caza gorilas Velo de Bruma ancianos. Encuentra una bonita selección de menudillos y llévaselos al Trémulo. No le digas que son de un animal. Deja que piense lo peor.", progress = "¡Eh! No me gusta cómo me estás mirando, chico.", completion = "¡Aaah! ¿De dónde has sacado esto? No, no me lo digas, no quiero saberlo. \n\n¿Quién te envía? ¿Lobo de Mar?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][607] = {title = "Regresa junto a MacKinley", objective = "Lleva el pago del Trémulo a \"Lobo de Mar\" MacKinley.", description = "Toma, coge esta bolsa y dásela a Lobo de Mar. ¡Y dile que le iba a pagar! ¡¡Lo juro!!\n\nSolo que me emborraché un poco y me perdí... ya sabes cómo son estas cosas. Lo entenderá, ¡no hace falta que te pongas así!", progress = "Hola, hola, <nombre>. ¿Has conseguido el pago del Trémulo?", completion = "¡Je, je, bien hecho! Y cuando le enseñaste al Trémulo esos menudillos, ¿se puso a temblar? \n\n¡Ja! Es muy predecible, cuando juego a las cartas con él, siempre gano. \n\nGracias por tu ayuda, &lt;nombre&gt;. Ahora me toca pagarte a ti...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][608] = {title = "Bucaneros Velasangre", objective = "El maestro de flota Cuernomarino en la Bahía del Botín quiere que mates al capitán Aguasmansas, al capitán Sinquilla y al maestro de flota Firallon.", description = "¡Maldito sea Firallon! No podría navegar un esquife por el Lago de Cristal y mucho menos liderar toda una flota contra nosotros.\n\nLos Bucaneros Velasangre pagarán su descuido. Ahora que sabemos su plan de ataque, podemos atacar y tomarles por sorpresa.\n\n¿Pero por qué enviar a toda la flota para hacer el trabajo de un grupo de aventureros? <nombre>, lleva a algunos de tus camaradas más capaces, vayan al lugar de atraque de Firallon y asesinen al líder Velasangre. Su flota se hundirá poco después...", progress = nil, completion = "¡Ah, qué día tan fantástico para los Asaltantes Aguasnegras! ¡Tres hurras por ti, &lt;nombre&gt;!", rewards = "Recibirás:\n\nGuerrera Aguasnegras"}
MultiLanguageQuestData['mx'][609] = {title = "El vudú debido", objective = "Lleva la pata de palo de Maury, el catalejo dorado de Jon-Jon y el anillo enorme de Chucky a \"Lobo de Mar\" MacKinley en la Bahía del Botín.", description = "La lista empieza a menguar, pero todavía hay muchos que me deben dinero.\n\nA continuación tenemos a Maury \"Patapalo\" Wilkins, Jon-Jon el Cuervo, y Chucky \"Diez Pulgares\".\n\nLas deudas de esos malditos perros son de varios meses y creí que se habían largado de la ciudad para evitar pagarme. Pero después me enteré de que están malditos y hechizados y se dedican a vagar por las ruinas de la jungla. Pero no me importa su destino, ¡quiero lo que me pertenece!\n\nEstán en las Ruinas de Aboraz y en las Ruinas de Jubuwal, al noreste de aquí. Encuéntralos y consigue mi dinero.", progress = "<nombre>, ¿has encontrado a esos tres perros? ¿Tienes sus posesiones?", completion = "¡Fantástico! ¡Podré conseguir un buen precio! Especialmente, por lo que hay en la pata de Maury. Muchas gracias, &lt;nombre&gt;. \n\nEspero que esos tres hayan aprendido la lección: no apuestes algo que no puedes permitirte perder. \n\nY quizás sea demasiado tarde para ellos... deberían tener cuidado con quién apuestan.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][610] = {title = "El Guapo\" Duncan", objective = "Consigue la daga de Catelyn de \"El Guapo\" Duncan.", description = "¿Mi PADRE te ha enviado? Pensaba que ese viejo chocho ya habría dejado de intentar encontrarme.\n\nRealmente no me escapé por su culpa, es solo que él no debería haber supuesto que aceptaría tener una vida aburrida, leyendo libros polvorientos y tratando a magos canosos, estirados y acartonados.\n\nSi necesitas mi daga, tendrás que recuperarla, la tiene \"el Guapo\" Duncan, uno de los Bucaneros Velasangre. Pon algo entre sus hombros y seguro que te la da.", progress = "Nunca me han vencido. ¿Lo sabías, <nombre>? Sí, obviamente me han herido alguna vez, no te puedes meter en un combate sin llevarte algún que otro rasguño, pero solo consiguió golpearme en la cabeza y caí a plomo. Cuando me desperté, me faltaba la espada.\n\nA pesar de mi nombre, sigo necesitando el acero para luchar y, para mí, tenía que ser esa espada.", completion = "¿Has derrotado a Duncan? Entonces, supongo que no eres tan imbécil como parecías a primera vista. \n\nMe imagino que eso significa que no te desafiaré de aquí a un tiempo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][611] = {title = "La maldición de las mareas", objective = "Destruye el Altar de las Mareas con la daga de Catelyn, mata a Gazban y lleva la Piedra de las Mareas y la daga de Catelyn al Barón Revilgaz.", description = "¿Así que estás buscando un altar? Bueno, no soy tan experta en ruinas trol como mi padre, pero he oído hablar de una ciudad trol hundida cerca de esa isla que estás buscando. Quizás podrías probar allí.\n\nHas recuperado mi cuchillo, así que supongo que puedes usarlo... ¡Pero lo quiero de vuelta cuando hayas terminado!", progress = "¿Has recuperado ya la Piedra de las Mareas, <nombre>? Ya he dejado un espacio libre y he comprado un pedestal para ella.", completion = "¡Sorprendente! ¡La Piedra de las Mareas! Tendrá un lugar de honor en mi colección de artefactos trols antiguos. ¿Has visto que parece casi como si tuviera una marea atrapada bajo la superficie? ¡Magnífico!", rewards = "Recibirás:\n\nToga de aguas cristalinas"}
MultiLanguageQuestData['mx'][613] = {title = "Abrir la pata de Maury", objective = "Lleva la llave de Maury a \"Lobo de Mar\" Mackinley en la Bahía del Botín.", description = "¡Maldición! Ese aq-queroso de Maury ha pueh'to un candao en su pata, ¡y no consigo abril-la! Guarda el botín en el pie, ¡y es justo lo que me debe!\n\nTenemos que encontral la llave que abre el candao. Todos saben que Maury apostaba con los ogro Mosh'Ogg, en su túmulo, al noreste. Y me dijo, cuando todavía eh'taba vivo, que la última vez que fue al túmulo, acabó siendo perseguido porque había ganao mucho. Quizás los ogros de allí tengan su llave.\n\nSi es así, probablemente tengas que matal a muchos de ellos pa encontral al que la tiene...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPlaca de colección"}
MultiLanguageQuestData['mx'][616] = {title = "La isla fantasma", objective = "Habla con el Barón Revilgaz en la Bahía del Botín.", description = "El Barón Revilgaz me ha pedido permanecer alerta en busca de rumores y cosas extrañas que ocurren en la Bahía del Botín y en Tuercespina. Generalmente no creo mucho en historias de fantasmas, pero oí a unos marineros en la taberna hablando sobre una isla encantada a poca distancia de la costa. Dicen que hay elementales de agua y un fantasma goblin enloquecido.\n\nSi vas a ver a Revilgaz, ¿podrías contarle la historia?", progress = nil, completion = "Interesante. Hace algún tiempo, leí un libro que sugería que... \n\nAh, claro, se trataba de una leyenda trol. Si lo que Krazek dice es cierto, quizás pronto pueda añadir la Piedra de las Mareas a mi colección de artefactos y reliquias antiguos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][617] = {title = "Tallos de juncos akiris", objective = "Consigue 10 fajos de junco akiris para el corsario Bloads en Bahía del Botín.", description = "¿Andas buscando trabajo, <nombre>? Quizás tenga algo pa ti si t'apetece un pequeño desafío.\n\nTengo un amigo llamado Groy que se está forrando vendiendo lo que los nagas llaman junco akiris: es un tipo de valioso junco del océano. No tengo muy claro pa qué sirve, pero paga bien por fajos de esa cosa.\n\nTráeme diez fajos de eso y haremos negocios. La última vez que vimos a los nagas fue en la playa que está al norte de aquí.", progress = "Si no tienes nada que me incumba, sigue tu camino, <nombre>.", completion = "Bien hecho, &lt;nombre&gt;. Después de todo, ¿no ha sido tan difícil conseguir 10 tallos de juncos akiris, eh? Sin ofender a los nagas, ¡pero todo el mundo tiene derecho a ganarse la vida!", rewards = "Recibirás:\n\nFajín agostador"}
MultiLanguageQuestData['mx'][621] = {title = "El secreto de Zanzil", objective = "Lleva 12 muestras de la mezcla de Zanzil a Loquillo Pinchabujas en la Bahía del Botín.", description = "Zanzil el Desterrado vive con sus seguidores en las Ruinas de Jubuwal y Aboraz, al noreste de la Bahía del Botín. Está exiliado de su tribu. ¿Por qué? Bueno...\n\nZanzil sabe cómo someter la mente de otros y sus líderes le temen. Utiliza una mezcla de plantas de la jungla con sus seguidores para eliminar su voluntad y fortalecer sus cuerpos.\n\nEsa mezcla sería muy valiosa para aquellos que deseen controlar a otros.\n\nTráeme muestras de esa mezcla y seguro que encuentro un buen uso.", progress = "¿¿Tienes las muestras de la mezcla de Zanzil??", completion = "Ah, muy bien. Aquí tienes lo tuyo. \n\nY un poco más... por tu discreción.", rewards = "Recibirás:\n\nCinturón de Corrupción"}
MultiLanguageQuestData['mx'][623] = {title = "Tallos de juncos akiris", objective = "Lleva un fajo de juncos akiris al corsario Groy, en Theramore.", description = "<nombre>, ya que tás aquí, he recibío un mensaje de Groy cuando no estabas. Dijo que estaba satisfecho con el último cargamento y que tiene un cliente que quiere más de esa cosa ahora mismo.\n\nYo no voy a Theramore hasta dentro de una semana, pero si tú quieres hacer el viaje, podrías llevar los juncos por mí.\n\n¿Te apetece una aventura? Sabes dónde está el Marjal Revolcafango, ¿no? Yo iría con cuidado, Theramore puede ser peligroso dependiendo de quién seas...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][624] = {title = "El enigma de Cortello", objective = "¡Resuelve el enigma!", description = "Hay un puente ornamentado y con mucho tránsito\nAl este de Viento Muerto y al sur de Crestagrana\nBajo el puente te espera algo\nAlgunos lo llaman un consejo otros, una pista\nAllí te esperará eternamente\nViendo pasar el tiempo en el Pantano de las Penas", progress = nil, completion = "El papiro húmedo contiene la siguiente pista...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][625] = {title = "El enigma de Cortello", objective = "¡Resuelve el enigma!", description = "Te espera una tierra muy lejana, en Kalimdor\nDonde el peligro ha destruido las esperanzas y los destinos\nAl este de Los Baldíos el tiempo es severo\nLa penumbra y el peligro imperan en el Marjal Revolcafango\nPero allí hay una pista, para aquellos dispuestos a aceptar el desafío\nEsperando ser encontrada... en una cueva... al suroesteRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][626] = {title = "El enigma de Cortello", objective = "¡Resuelve el enigma!", description = "¡A Lordaeron! La gran tierra de confusión\nDonde valientes soldados juegan con la muerte\nEncuentra tu camino a través del gran disturbio\nAllí encontrarás el final de esta misión\nJunto a la costa de las Tierras del Interior, en la base de las cataratas\nDesde las profundidades del agua, te llama tu tesoro.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nMorral de expedicionario"}
MultiLanguageQuestData['mx'][627] = {title = "Un favor a Krazek", objective = "Lleva 4 fajos de mena de sangrita inferior a Krazek en la Bahía del Botín.", description = "Hay una cueva en la montaña, en el Cañón Mostacho Seco, al norte de las Tierras Altas de Arathi. En esa cueva hay un extraño mineral: sangrita. La sangrita de esta cueva no tiene una calidad superior, pero incluso la sangrita de baja calidad es valiosa... para aquellos que sepan usarla.\n\nMe gustaría conseguir sangrita.\n\nArreglaré tu olla mecánica, pero mientras lo hago... tráeme algunas muestras de sangrita. Si me traes las suficientes, te daré una bonificación.\n\nOh, y si no tienes la habilidad necesaria para extraerla... ¡encuentra a alguien que la tenga!", progress = "Hola, <nombre>. ¿Has conseguido la sangrita?", completion = "¡Menuda maravilla! Me has hecho un gran favor. \n\nAquí tienes tu pago...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][628] = {title = "Borceguí", objective = "Lleva una piel de crocolisco mayor a Drizzlik en la Bahía del Botín.", description = "Ahora que hemos terminado el interior, lo único que queda es añadir la capa exterior. Para esto, solo utilizo la mejor piel de crocolisco mayor. Duran más y son un lienzo perfecto para añadir los diseños y dibujos que completan el estilo borceguí de Drizzlik.\n\nPero no es fácil encontrar la piel perfecta, la única que podría servir es la piel de un crocolisco marino mayor. Los crocoliscos mayores solo salen fuera para defender a los otros crocoliscos marinos, así que quizás tengas que matar a unos cuantos para que salgan.", progress = "He oído por ahí que los crocoliscos marinos se están extinguiendo poco a poco... malas noticias para el negocio, ¿eh?\n\nEn fin, espero que tengas esa piel de crocolisco marino mayor para mí.", completion = "¡Genial! Gracias a tu ayuda, tendré este pedido terminado y se lo enviaré al director Riddlevox en el próximo barco que salga para Minahonda. ¡Incluso antes de la hora prevista! \n\nHe hecho algunas de más, así que, por tus esfuerzos, puedes quedarte con un par. Regalo de Drizzlik. \n\nNo hay nada que supere el estilo borceguí de Drizzlik!", rewards = "Recibirás:\n\nBotas excelsior"}
MultiLanguageQuestData['mx'][629] = {title = "El Arrecife Mortal", objective = "Lleva un fragmento de tablilla a Kin'weelay en el Campamento Grom'gol.", description = "Mucho tiempo atrás, un gran temblor de tierra sumergió una antigua ciudad trol bajo las aguas de La Costa Salvaje, al noroeste. Llamamos a ese lugar El Arrecife Mortal, ya que ahora los múrlocs residen en las ruinas de la ciudad, atacando a todo el que se acerca.\n\nEn esas ruinas hay una antigua tablilla que narra la vieja fábula de Gri'lek, un héroe de leyendas trol. La fábula es sagrada para la tribu Lanza Negra y, aunque la tablilla es muy grande como para moverla, quiero un fragmento para consagrarlo en nuestro nuevo hogar de Orgrimmar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][630] = {title = "Mensaje en una botella", objective = "Mata al rey Mukla y vuelve a por la princesa Poobah con la llave para liberarla.", description = "<nombre>, pongo mi fe en ti y en cualquiera que te ayude a liberarme. Mi secuestrador es el gran Cieloleno rey Mukla. Domina a las bestias de esta isla que me tienen aquí contra mi voluntad con ayuda de una cadena. Si puedes matarle y encuentras la llave de estos grilletes, estaré en deuda contigo eternamente.\n\nA menudo puedo oírle en la parte sureste de la isla, pero ten cuidado. Hay que tomarle muy en serio.", progress = "Agradezco a mis ancestros que alguien haya venido a ayudarme. ¿Tienes la llave para liberarme?", completion = "&lt;nombre&gt;, me has salvado de un gran deshonor. Si estuviera en mis manos, te ofrecería un lugar en mi tribu. Pero, por ahora, solo puedo ofrecerte esto por el coraje y la nobleza que has mostrado.", rewards = "Recibirás:\n\nPendiente para la nariz de Poobah"}
MultiLanguageQuestData['mx'][631] = {title = "El Puente Thandol", objective = "Rhag Garmason quiere que localices a Herrumbra.", description = "Se oyó el estruendo de una enorme explosión por todas las colinas. '¡Fue horrible, créeme!\n\nLos buenos soldados murieron en la defensa el Puente Thandol. Largatrenza dice que nos vengaremos de los Hierro Negro en un santiamén.\n\nPero estamos en un mundo lleno de dolor y no veo ningún refuerzo. Largatrenza envió a Herrumbra a explorar el puente del Este para ver si podemos ganarlo.\n\nEso fue hace días. Con Dun Modr bajo asedio no tenemos hombres suficientes para ir a buscarlo.\n\nQuizás tú puedas ayudarnos...", progress = nil, completion = "Registras el diminuto cadáver &lt;raza&gt;. Grabado en el yelmo puedes leer claramente: Ebenezer Herrumbra.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][632] = {title = "El Puente Thandol", objective = "Vuelve a informar a Rhag Garmason en Dun Modr, en Los Humedales, y enséñale el papiro que encontraste en el cadáver de Herrumbra.", description = "Parece que el pobre Herrumba cayó en una emboscada de los Hierro Negro. Descubres un papiro junto a su puño cerrado.\n\nLleva la desalentadora noticia a Rhag Garmason y enséñale lo que has descubierto.", progress = "¿Alguna señal de Herrumbra, <nombre>?", completion = "Oh, no puede ser, son malas noticias...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][633] = {title = "El Puente Thandol", objective = "Destruye el cajón de explosivos.", description = "¡¡¡Cielos!!! ¡¡¡No!!! Pobre Herrumbra. Es una tragedia.\n\nNo debemos permitir que su muerte haya sido en vano. El pergamino que has descubierto indica que Kam Furiahonda, el cerebro del ataque, ordenó atesorar un alijo de explosivos al otro lado del Puente Thandol, en las Tierras Altas de Arathi.\n\n¡Si esos explosivos llegan al puente, nuestra principal vía de suministros recibirá un duro golpe! ¡Hay que destruir el alijo, <nombre>! Vuelve a verme cuando hayas terminado tu misión.\n\nEres nuestra única esperanza.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Capa de guardia enanoCalzas Tierra pantanosaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][634] = {title = "Petición a la Alianza", objective = "Busca a la capitana Nials en el Refugio de la Zaga, en las Tierras Altas de Arathi.", description = "Voy a pedirte otro pequeño favor, <clase>. Estamos esperando las reservas de Forjaz. Pero Roggo tiene noticias de un campamento de la Alianza al norte de las Tierras Altas de Arathi, en el Refugio de la Zaga.\n\nViaja hasta allí y busca a la capitana Nials. Pregunta a la buena capitana si la Alianza puede ofrecernos algunos soldados que nos ayuden a recuperar Dun Modr y el Puente Thandol.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][635] = {title = "Cristal en las montañas", objective = "Encuentra el cristal de tu visión.\n\nObjeto provisto: \n", description = "El fragmento palpita cuando lo agarras...\n\nSientes una especie de súplica saliendo del fragmento, como si alguien estuviera intentando comunicarse contigo, alguien que necesita tu ayuda desesperadamente.\n\nUna visión llena tu mente... son las montañas septentrionales de Arathi, y ves también un cristal brillante sobresaliendo del suelo.\n\nTe sientes <atraído/atraída> hacia ese lugar.", progress = nil, completion = "Este cristal palpita, es como si tuviera una fuerza viva atrapada en su interior.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][637] = {title = "La carta de Sully Balloo", objective = "Entrégale la carta de Sully Balloo a Sara Balloo.", description = "El sobre empapado y desgastado se deshace entre tus manos, revelando varias páginas de una carta escrita con una cuidada caligrafía.\n\nLa carta está dirigida a Sara Balloo de Forjaz y comienza así: \"Querida Sara...\"Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][638] = {title = "Aterratrols", objective = "Viaja a Sentencia en las Tierras Altas de Arathi y habla con Zengu.", description = "Con Thoras Aterratrols muerto y Stromgarde en ruinas, Vol'jin ha ordenado que hagamos todo lo posible por robar la legendaria espada Trol'kalar a los humanos, para que podamos usarla en nuestras próximas batallas contra los trols de Zul'Gurub.\n\nZengu, uno de nuestros cazadores más expertos, se ha dirigido a Sentencia, al noreste de las Tierras Altas de Arathi, para encargarse de todo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][639] = {title = "El sigilo de Strom", objective = "Consigue el sigilo de Strom para Zengu en Sentencia.", description = "En tiempos ancestrales, los trols lucharon contra el Imperio Arathoriano y contra nuestro más temible adversario, Lord Ignaeus de Strom, al que llamaban Aterratrols. Acudía a la batalla empuñando a Trol'kalar, verdugo de trols en su antigua lengua.\n\nPero ahora la estirpe de Aterratrols se ha debilitado, su bastión está en ruinas.\n\nLa espada está protegida por varios sigilos que se dividieron entre los supervivientes de Stromgarde, debemos recuperarlos.\n\nLa Hermandad se llevó el primero, lo custodia uno de sus hombres en Stromgarde.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][642] = {title = "La princesa encerrada", objective = "Recolecta 12 motas de Myzrael y llévalas a los fragmentos iridiscentes en el Cañón Mostacho Seco.", description = "Me llamo Myzrael. Soy una princesa de la tierra, y mis captores, los gigantes, me han encerrado en el subsuelo de las Tierras Altas de Arathi. Estos fragmentos de cristal son mi único medio para hablar con el mundo de la superficie.\n\nPor favor, ayúdame. Los aliados de los gigantes, los kóbolds Mostacho Seco, tienen un fragmento como este en el Cañón Mostacho Seco, hacia el este. Para que ese pedazo cobre poder, debes conseguir motas de Myzrael de los kóbolds y aplicárselas.\n\nTe lo suplico, <nombre>, ¡ayúdame!", progress = "Este bloque de fragmentos se parece mucho a los fragmentos de Myzrael. Pero no late en ellos el mismo sentimiento de seguridad.", completion = "¡Ah! Has activado estos fragmentos. ¡Ya empiezo a sentirme como antes! \n\nAunque ¡qué lejos estoy aún de la liberación!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][644] = {title = "El sigilo de Aterratrols", objective = "Mata al príncipe Galen Aterratrols y llévale el sigilo de Aterratrols a Zengu en Sentencia.", description = "El último sigilo necesario para desbloquear la tumba de Thoras Aterratrols está en manos de su propio hijo. Mora en lo más recóndito de Stromgarde, en una capilla en los distritos de la milicia. El príncipe Galen está bien protegido y es él mismo un guerrero respetable, así que esta tarea podría resultar de lo más difícil.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][647] = {title = "Licor de luna de Mackreel", objective = "Llévale el licor de luna de MacKreel al maestro cervecero Bilger de Costasur.", description = "¡Anoche tomé un poco de licor de luna! Largatrenza me mataría si supiera que perdí el sentido mientras estaba de guardia.\n\nEsa bebida sí que es fuerte... Sentía como si una brigada entera de máquinas de asedio me hubiera pasado por encima.\n\n¡Oh, mira qué hora es! Le prometí al maestro cervecero Bilger de Costasur que saldaría mi deuda con él enviándole licor de luna.\n\nEl problema es que solo dispongo de 15 minutos para ello. ¿Te importaría llevárselo tú? ¡Date prisa!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][648] = {title = "¡Rescatar a OOX-17/TN!", objective = "Escolta a OOX-17/TN para que llegue sano y salvo y después preséntate ante Oglethorpe Obnoticus en Bahía del Botín.", description = "Vuelves a oír la voz del gnomo que sale del robot:\n\n\"Tengo que llevar a OOX-17/TN a un lugar abierto y seguro en el que pueda iniciar el largo proceso de despegue. Tiene un dispositivo de invisibilidad integrado, pero necesito tiempo para que vuelva a estar operativo. Escolta al robot hasta, digamos, cerca de las Cavernas del Tiempo. Allí podré tomarme mi tiempo para hacer que todo vuelva a funcionar correctamente.\"\n\n\"¡Escóltalo para que llegue sano y salvo y después ven a verme a Bahía del Botín! Oglethorpe Obnoticus. ¡Corto y cierro!\"", progress = nil, completion = "¡Ah, así que tú eres quien ha rescatado a OOX-17/TN! ¡No sé cómo darte las gracias por tu ayuda! Sin duda, tengo que perfeccionar mi robot mensajero pero gracias a ti no perderé innumerables horas de trabajo construyendo uno nuevo, lo que implicaría perder muchas piezas de oro. \n\nPor favor, elige uno de los objetos que tengo. Con suerte, alguno de ellos te resultará útil. Gracias de nuevo por tu inestimable ayuda. ¡Mis robots y yo estamos en deuda contigo!", rewards = "Deflector optomáticoPodrás elegir una de estas recompensas:\n\nTemporizador de huevos termostático\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][649] = {title = "Recupera el calimocho", objective = "Habla con Malton Droffers en Orgrimmar.", description = "Tengo un trabajito de rescate para ti, y si te gusta el buen calimocho, seguro que lo aceptas. ¿Que qué es?\n\nPues una bebida, ¿qué va a ser?\n\nHay un cargamento de calimocho dulce de las Tierras del Interior en una avanzada abandonada de la Horda. ¡Ya no se hace un calimocho como ese! Uno de esos atontados con los que trabaja Malton está interesado, así que tráeme una caja de calimocho para él y un par para mí. Habla con Malton para que te dé los detalles.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][650] = {title = "Recupera el calimocho", objective = "Habla con Gilveradin Cazasol; su campamento está en las Tierras del Interior.", description = "El elfo con el que necesitas hablar se llama Gilveradin Cazasol. ¡Puede identificar cualquier vino, con cosecha y todo, con solo olerlo! Él puede embotellar el calimocho que necesitamos, así que tendrás que hablar con él. Necesitamos seis botellas en total: dos para papá y todas las que él quiera y, créeme, querrá alguna que otra. Cuando hayas embotellado el calimocho y tengas las dos botellas de papá, vuelve aquí.\n\nEl campamento de Gilveradin está por las Tierras del Interior, cerca de la casa de un elfo noble... y esos elfos nobles no son buena gente. Créeme.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][652] = {title = "Desbloquear la piedra angular", objective = "Encuentra a Fozruk y mátalo. Lleva la vara del Orden a la piedra angular en las Tierras Altas de Arathi.", description = "Desbloquear las Piedras de Vínculo me liberó en gran parte de mi confinamiento. Pero aún queda una cerradura por abrir. Es la piedra angular que ves en ese círculo de piedras. Y la llave la tiene uno de mis captores, Fozruk, el guardián de las piedras.\n\nDebes conseguir esa llave. Los guardianes de las piedras la llaman la vara del Orden. Arrebátasela a Fozruk y úsala para abrir la piedra angular.\n\n<nombre>, me has ayudado mucho. Pero necesito un poco más de ayuda... ¡Mi gratitud hará temblar los mismísimos pilares de la tierra!", progress = "La piedra angular está cargada de energía geomántica.", completion = "Colocas la vara en la piedra angular. Y sientes cómo el suelo tiembla bajo tus pies...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][655] = {title = "Sentencia", objective = "Habla con Tor'gan en Sentencia.", description = "Lo recuerdo como si fuera ayer... Tantos años sin esperanza. Con la madera y el acero ligándome a este terrible lugar. ¡Y por fin, por fin! Ahí estaba el Jefe. Martillo Maldito, con sus agoreras placas y su martillo de guerra en alto.\n\nFue terrible... Que el golpe asestado por la mano de un cobarde acabara con nuestro héroe más admirado. Cargó por detrás con su caballo y lo atravesó con su lanza... Yo caí de rodillas. ¿Qué esperanza nos quedaba? ¿Qué esperanza nos queda...?", progress = nil, completion = "Ah, hablas de Gor'mul. Sí, por lo que cuenta, parece que nunca se repuso de la muerte de Martillo Maldito. \n\nGor'mul estuvo cautivo aquí cuando Thrall y Orgrim luchaban para liberar el campamento, pero cuando la tierra tembló y nuestros hermanos escaparon, él se quedó atrás. Estuvo vagando en soledad durante años sin rumbo ni objetivo hasta que volvimos para asentarnos aquí en Sentencia.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][656] = {title = "Invocar a la princesa", objective = "Ve a los fragmentos de Myzrael, invócala y derrótala.\n\nRecolecta sus grilletes de Eldritch y pónselos a los fragmentos de Myzrael.", description = "Debes derrotar a Myzrael antes de que se vuelva más fuerte. Si no lo haces, en cuanto tenga suficientes poderes ¡desafiará a sus captores! Hay quien piensa que puede controlarla, pero si así fuera, ¡¿por qué la encadenaron los gigantes?!\n\n¿A que no tiene ni pies ni cabeza?\n\nPara derrotarla, conjúrala en los fragmentos de Myzrael donde hablaste con ella la primera vez. Derrótala, coge sus grilletes tétricos y pónselos a los fragmentos de Myzrael.\n\nHazlo y volverá a estar presa.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFragmento cristalino pulsante"}
MultiLanguageQuestData['mx'][657] = {title = "Sospechas de una nueva Peste", objective = "Habla con Kinelory cerca de la Granja Go'shek, en las Tierras Altas de Arathi.", description = "<Quae empieza a examinar la carpeta.>\n\nEsto SÍ que es interesante. Al parecer, el boticario Jorell ha estado trabajando en unos experimentos letales aquí en Go'Shek. No estoy seguro de cuál es la relación con Trabalomas pero a Phin no le gustaría que dejásemos que siga adelante.\n\nTuvimos un roce con unos orcos cuando no estabas, por lo que no estoy en condiciones de ayudar a Kinelory. Si te apetece, va a necesitar que la protejan cuando vaya a la Granja a robar lo que sea que Jorell aún no haya enviado a Molino Tarren.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][658] = {title = "Sospechas de una nueva Peste", objective = "Encuentra a la mensajera Renegada y lleva su carpeta sellada a Quae cerca de la Granja Go'shek.", description = "¿Así que Phin te ha mandado ver qué hacemos? No me sorprende. Se preocupa demasiado.\n\nHemos vigilado la granja durante días y Kin dice que hace poco ha visto a un mensajero saliendo de esa casita que hay hacia el sur.\n\nHabla mucho, pero me fío de su instinto cuando estamos en sitios peligrosos.\n\n¿No sabrás seguir rastros, por un casual? Creemos que el mensajero podría llevar notas al Molino Tarren. Si pudiéramos echar el guante a esos documentos... Seguro que nos ayudan a entender qué está pasando en Trabalomas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][659] = {title = "Sospechas de una nueva Peste", objective = "Encuentra a Quae y a Kinelory cerca de la Granja Go'shek en las Tierras Altas de Arathi.", description = "Saludos. Te doy la bienvenida, <nombre>. Dirijo un grupo de aventureros que investigan sucesos extraños que han tenido lugar en esta zona.\n\nMi primo de Trabalomas ha tenido que sacrificar a su perro Stanley porque el animal creció místicamente hasta alcanzar un gran tamaño y empezó a atacar a todo el que se le acercara.\n\nCreo que los no-muertos están involucrados en eso y estamos buscando indicios que lo prueben.\n\nDos compañeras mías, Quae y Kinelory, fueron a la Granja Go'shek en las Tierras Altas de Arathi y hace días que no tenemos noticias suyas. ¿Podrías encontrarlas por mí? Empiezo a preocuparme de verdad.", progress = nil, completion = "Procura estar tan quieto como puedas, viajero. \n\nA los orcos no les sienta muy bien que los espíen y en esta Granja hay más de lo que se ve a simple vista.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][660] = {title = "Sospechas de una nueva Peste", objective = "Protege a Kinelory hasta que haya regresado con Quae.", description = "Muy bien, <nombre>. Si tú estás <listo/lista>, yo también.\n\n¿Vamos?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][661] = {title = "Sospechas de una nueva Peste", objective = "Encuentra a Phin Odelic en Costasur.", description = "He visto a Kinelory con mucho peor aspecto después de una noche en la taberna que ahora. No hay duda de que tu protección fue de gran ayuda.\n\nCon los objetos que trajo de la Granja, Phin debería hacerse una idea de lo que está ocurriendo en Arathi. Solo para asegurarnos de que no hay represalias después de tu incursión, nos quedaremos aquí un poco más. ¿Te gustaría volver a Costasur y hablar con Phin?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Togas guardapolvoLeotardos de paso ligeroRecibirás:\n\n"}
MultiLanguageQuestData['mx'][663] = {title = "¡Tierra a vista!", objective = "Habla con el capitán O'Breen en la Cala de Faldir, en las Tierras Altas de Arathi.", description = "Lolo ve a un minúsculo <raza>! ¡Siempre al loro, Lolo está!\n\n<Bienvenido/Bienvenida> a la Cala de Faldir. El capitán O'Breen dijo que solo estaríamos aquí durante unas horas. Lo justo para reunir el tesoro y volver a Bahía del Botín.\n\nPero Lolo piensa que vamos a estar allí más tiempo. Perdimos otros dos barcos de nuestra formación. Pobres Espíritu de argénteos y El Capricho. ¡En el fondo del mar ahora descansan!\n\nLolo sugiere que hables con el capitán O'Breen si te vas a quedar por aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][664] = {title = "Ahogar las penas", objective = "El capitán Tripacero de Cala de Faldir quiere que mates a 10 asaltantes Espinadaga y a 3 hechiceras Espinadaga.", description = "Ah, esta vida es terrible. Debería estar en una tumba de agua ahora mismo, no aquí, junto al fuego y respirando aire fresco.\n\nLa tripulación se esforzó tanto para salvar El Capricho, mi hermosa nave... Benditos sean, benditos sean sus corazones.\n\nO'Breen llegó a la costa sano y salvo, pero nosotros no tuvimos tanta suerte. La mar nos hundió, lo juro.\n\nUn momento antes estábamos a flote y después... el agua empezó a entrar. ¡Y esas bestias! Mataron a todos los supervivientes. Esa escoria naga... Yo perdí el conocimiento y acabé aquí, a salvo.\n\nQuiero ver a esas bestias muertas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGuantes de lobo marino"}
MultiLanguageQuestData['mx'][665] = {title = "El tesoro sumergido", objective = "Escolta al profesor Fiseltor hasta la cueva y a su regreso.", description = "Ahora que somos Asaltantes Aguasnegras hechos y derechos, debemos ayudar a O'Breen a encontrar el tesoro elfo perdido.\n\nEs casi imposible encontrar las gemas en el mar sin ayuda. El doctor ha creado unas gafas que ayudan a ver en la oscuridad del mar. Pero hay que cargarlas con la energía que emana una piedra encantada de la cueva que hay en la colina.\n\n¡Y la cueva está maldita! Cuando alguien se acerca, cae en una emboscada. Defiéndeme para que pueda recoger la energía de la piedra con las gafas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][669] = {title = "El tesoro sumergido", objective = "Llévale una muestra de gema de elfo al maestro de flota Cuernomarino a Bahía del Botín, en la Vega de Tuercespina.", description = "El maestro de flota Cuernomarino querrá enterarse de nuestro hallazgo sin demora.\n\nPero como puedes ver, no estamos precisamente en posición de salir de aquí No solo la marea es demasiado baja, sino que esas malditas criaturas a las que hemos perturbado no nos quitan ojo de encima.\n\nPuedes ser de gran ayuda para los incursores Aguasnegras si consigues llegar a Bahía del Botín y decirle al maestro de flota Cuernomarino que hemos descubierto el tesoro y estamos trabajando para extraer más. Llévate esta muestra como prueba.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][670] = {title = "El tesoro sumergido", objective = "Llévale la carta de Cuernomarino a Temblores O'Breen a la Cala de Faldir, en las Tierras Altas de Arathi.", description = "Tú, <nombre>, pareces tener un espíritu aventurero. Mi flota está anclada en Bahía del Botín hasta que podamos reabastecernos.\n\nEstán ocurriendo cosas graves aquí y en el extranjero y necesito hacer llegar una comunicación de alto secreto a Temblores O'Breen que está amarrado en la costa de Arathi.\n\n¿Puedo confiar en que entregues este mensaje a salvo y sin traicionar su secreto?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][671] = {title = "Magia demoníaca", objective = "Consigue 10 amuletos de sangrita para Tor'gan en Sentencia.", description = "He notado algo extraño en el aire... un sentimiento que me hace hervir la sangre. Algo sospechaba. Me puse en camino para encontrar el origen de mi desasosiego y descubrí al oeste, en la Mansión Redilnorte, restos residuales de un conjuro demoníaco. Conforme me acercaba, me empezó a hervir la sangre y crecía mi rabia.\n\nDescubrí en el suelo un amuleto de sangrita, que se usa para conjuros demoníacos. Aunque, el que encontré estaba agotado. Necesitaré otro para poder investigar pero no me atrevo a volver a la mansión. ¿Podrías traerme alguno?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][676] = {title = "La Sentencia", objective = "Mata a 8 ogros y 10 déspotas Puño de Roca; luego ve a ver a Bombo Vil a la avanzada de Sentencia, en las Tierras Altas de Arathi.", description = "Alfeñiques miserables... ¿Se puede saber qué miras, <clase>? Te crees muy especial, ¿eh? Demuéstralo.\n\nLa avanzada de Sentencia, en Arathi, está siendo atacada. La derrota es inevitable si no les enviamos ayuda de inmediato.\n\nPero antes de salir corriendo, será mejor que te pongas a prueba. Al noreste de Stromgarde, en Arathi, hay un túmulo de ogros en el que vive la tribu Puño de Roca. Cuando seas capaz de manejarte con esos ogros, preséntate ante Bombo Vil en Sentencia.", progress = nil, completion = "¿Crees que puedes ayudar a Sentencia? Muy bien. \n\nSebo te envió a ese túmulo de ogros a morir o piensa que alguna destreza tendrás. En todo caso, ando escaso de tropas. \n\nSi planeas quedarte en Sentencia, descansa un poco y luego ven a verme otra vez. Seguro que te encuentro algunos cuellos que cortar.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][677] = {title = "Un llamamiento a las armas", objective = "Mata a 10 lanzahachas Secacorteza, 10 rebanacabezas y 8 médicos brujos y vuelve junto a Bombo Vil en la avanzada de Sentencia.", description = "Los trols Secacorteza y los ogros Puño de Roca de Arathi se han unido para arrebatarnos esta tierra, pero no dejaremos nuestro sino en sus manos ni en las de nadie más. Los ejecutaremos y les demostraremos que este lugar es nuestro hogar.\n\nLos trols nos han traicionado; los ogros nos usarían de comida y de cama si les dejásemos, eso jamás ocurrirá.\n\nEmpezamos el ataque sobre los trols Secacorteza al sur de este lugar. Ejecútalos por docenas y regresa solo cuando sus campamentos estén bañados en sangre.", progress = nil, completion = "Las huellas de la guerra se evidencian en tus prendas y el sudor cae de tu frente. Bien, pero que muy bien.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][681] = {title = "Mansión Redilnorte", objective = "Mata a 10 bandoleros de la Hermandad y 6 mercenarios de la Hermandad.\n\nVuelve junto a la capitana Nials en el Refugio de la Zaga.", description = "Estamos librando una guerra por Stromgarde, y la estamos perdiendo. Los ogros, la Hermandad y nosotros mismos hemos dividido nuestra otrora gran ciudad, y cada facción se encuentra atrapada en un sangriento enfrentamiento.\n\nNuestras fuerzas menguan mientras las del enemigo aumentan.\n\nNecesitamos ayuda de la ciudad de Costasur pero es difícil recibir suministros mientras la Hermandad controle el territorio que hay que cruzar.\n\nVe a la base de la Hermandad en Mansión Redilnorte y ejecútalos. Quizás entonces disminuya la presión sobre los trenes de suministros y nos llegarán más.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][682] = {title = "Distintivos de Stromgarde", objective = "Llévale 7 distintivos de Stromgarde a la capitana Nials en el Refugio de la Zaga.", description = "La Hermandad de Stromgarde se resiste a nuestro contingente de la milicia allí desplazado. Para incentivar a la chusma a enfrentarse a nuestros más disciplinados soldados, los jefes de la Hermandad han puesto precio a los nuestros, prometiendo oro por cada distintivo de Stromgarde arrebatado a soldados muertos.\n\nQuiero que recuperes esos distintivos, ¡no podemos permitir que esos degolladores se lleven el trofeo de nuestros valientes caídos!\n\nPenetra en la zona de Stromgarde controlada por la Hermandad y busca nuestros distintivos.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nLeotardos de caballería de Stromgarde"}
MultiLanguageQuestData['mx'][684] = {title = "Se busca: Marez Cogulla", objective = "Llévale la cabeza de Marez a la capitana Nials en el Refugio de la Zaga.", description = "Le han puesto precio a la cabeza de Marez Cogulla, una consejera de alto nivel y agente de la Hermandad. La vieron por última vez en el territorio controlado por la Hermandad en Stromgarde.\n\nLa recompensa se reclama a la capitana Nials.\n\nOjo: Marez es una hábil y taimada bruja, famosa por sus trapicheos con los demonios. Se recomienda extremar la precaución en su caza.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBrazales rúnicos Arcanos"}
MultiLanguageQuestData['mx'][685] = {title = "Se busca: Otto y Lord Falconcrest", objective = "Llévale la cabeza de Otto y la de Lord Falconcrest a la capitana Nials en el Refugio de la Zaga.", description = "La Milicia de Stromgarde ha puesto precio a la cabeza de Lord Falconcrest y a la de su guardaespaldas Otto. Falconcrest dirige a la Hermandad en las Tierras Altas de Arathi y su muerte supondría un duro golpe para ellos.\n\nSu guardaespaldas Otto, aunque no sea un objetivo estratégico, es un feroz adversario y ha acabado con docenas de nuestros defensores.\n\nLas recompensas se reclaman a la capitana Nials.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Brazales de jinete de guerraVara de penaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][687] = {title = "Theldurin el Perdido", objective = "Encuentra a Theldurin el Perdido.", description = "Theldurin el Perdido fue un día miembro de nuestra orden, el Martillo Crepuscular. Pero perdió la cabeza y desdeñó nuestras enseñanzas. Antes de huir de nuestro lado, robó el Pergamino de Myzrael. No pudimos atraparlo, pero hay rumores de que se oculta en las Tierras Inhóspitas, ha enloquecido y no dice más que incoherencias.\n\nPara traer de vuelta a la Dama, debemos encontrar el pergamino. Y para hacerlo, debes encontrar a Theldurin.", progress = nil, completion = "Hola. Hola, hola, hola, hola, hola, ¡¡HOLA!! \n\nLo siento, ¡espera, no lo siento! ¡No seas grosero! \n\nOh no... no estoy diciendo más que locuras. \n\nPero... a veces la locura es mi único consuelo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][689] = {title = "Un homenaje real", objective = "El gran mampostero Marmolez de Forjaz quiere 5 piezas de granito de Alterac.", description = "¿Así que el Rey quiere un monumento en honor de un soldado llamado Sully Balloo? ¿Y dices que el pobre diablo murió durante la tragedia del Puente Thandol?\n\n¿Habrá alguna vez paz en Azeroth?\n\nSea como sea, todos los encargos del Rey son de la máxima importancia. Para crear una obra épica y duradera, necesito una de las mejores piedras disponibles. Tráeme granito de Alterac; lo encontrarás en las Colinas de Darrow, en Trabalomas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][690] = {title = "Una petición de Malin", objective = "Encuentra a Skuerto en el Refugio de la Zaga, en las Tierras Altas de Arathi.", description = "Saludos, <nombre>. Tienes aspecto de aventurero y tengo una tarea que requiere atención.\n\nEl archimago Trelane, mi primer maestro, huyó de Stromgarde en las Tierras Altas de Arathi no hace mucho, y me ha pedido que le ayude a recuperar unas cosas que se dejó.\n\nSitiaron la ciudad e intentó defender la Torre de Arathor pero fue en vano. Ya tengo a agentes en las Tierras Altas pero me han pedido que envíe refuerzos. ¿Te interesa?", progress = nil, completion = "¿Así que t'envía Malin? M'importa un bledo que Muradin resucitara y te pusiera un dragón pa' traerte aquí. ¡Estoy ocupao! Habla con Kryten pa' lo que sea.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][691] = {title = "Valer su peso en oro", objective = "Encuentra 10 colmillos Secacorteza, 4 bolsas de medicina Secacorteza y un cuchillo de cazador de las Sombras para el aprendiz Kryten en el Refugio de la Zaga.", description = "El archimago Malin nos ha enviado a Skuerto y a mí a recolectar componentes para él. No sabía ni por dónde empezar pero ahora que estás aquí, creo que el problema está resuelto.\n\nNecesito lo siguiente: colmillos Secacorteza, bolsas medicinales Secacorteza y un cuchillo de cazador de las Sombras.\n\n¿Podrías encontrar estas cosas para mí? Los Secacorteza viven al sudeste de Arathi.", progress = "¿Ha habido suerte hasta ahora, <nombre>?\n\n\n\nSi mi investigación es correcta, los colmillos deberían proceder de cualquier trol Secacorteza. Las bolsas de medicina proceden de los médicos brujos Secacorteza y el más fuerte de los cazadores oscuros Secacorteza debería llevar la navaja especial que se les entrega después de completar sus ritos de paso. No hay forma de saber qué cazador oscuro lleva la navaja hasta que te enfrentas a ellos.", completion = "¡Increíble! Ahora entiendo por qué Malin te pidió que te unieras a nosotros, ¡gran idea, digo! \n\nA este paso, Skuerto y yo estaremos de vuelta en Ventormenta antes de que nos demos cuenta. \n\nCreo que mi compañero &lt;raza&gt; ha vuelto de su exploración de la Sala de Puño de Roca; ve a hablar con él cuando estés listo. \n\nAl parecer, tuvo una escaramuza con los ogros. Aunque ni se lo mentes, es muy sensible ante las críticas a sus habilidades y a su trabajo como explorador.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][692] = {title = "Los trozos perdidos", objective = "Lleva el trozo de pergamino roto, el trozo de pergamino arrugado y el trozo de pergamino chamuscado a Theldurin el Perdido.", description = "El pergamino de Myzrael... ¡¿el pergamino de Myzrael?! ¡Yo que tú, ni me acercaba! Su magia puede sacar a Myzrael a la superficie del mundo y si lo haces, ¡estaremos en un lío!\n\nO... quizás ya es demasiado tarde. A lo mejor ya está libre. Quizás solo esté recobrando fuerzas antes de desatar toda su ira sobre nosotros. De ser así, entonces ¡NECESITAS el pergamino!\n\n... ¡qué mala suerte que esté en pedazos! Elementales iracundos lo robaron, lo desgarraron y luchan ahora por los fragmentos.\n\nPero puedes reunir esos trozos, quizás podamos arreglarlo...", progress = "¡¿Has encontrado esos fragmentos?! Necesitarás el pergamino de Myzrael para cazarla de nuevo ¡antes de que sea demasiado tarde!", completion = "¡Ah, los has encontrado! ¡Buen trabajo, &lt;nombre&gt;! ¡Puede que esta sea la única oportunidad contra la perversa Myzrael! \n\nDame un segundo para encontrar mi trinquete y ver si puedo recomponer estos fragmentos...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][694] = {title = "Las defensas de Trelane", objective = "Encuentra un ágata azur y llévasela al aprendiz Kryten en el Refugio de la Zaga.", description = "¿Has descansado?\n\nEste será nuestro siguiente paso: hay ogros rodeando la Torre de Arathor en Stromgarde. Tendremos que activar las defensas de la torre pa' tener la más mínima posibilidad de vencerles y llegar vivos hasta los objetos. Pa' eso, necesitaremos unas gemas a las que les han tomao cariño los chamanes Puño de Roca. Las arrebataron de la torre pero pa' mí que no les van a durar.\n\nConsigue una d'esas gemas y llévasela a Kryten, él conoce el hechizo pa' que funcionen de llave.", progress = "Hola otra vez, <nombre>. ¿Has encontrado ya una ágata azur?", completion = "Impresionante, &lt;nombre&gt;. Una vez más, enhorabuena. \n\nDame un momento para lanzar el hechizo apropiado para encantar la gema ¡y listo!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][698] = {title = "alta de suministros", objective = "Lleva 8 costillares de Denteserra sin preparar a Tok'Kar en el Pantano de las Penas.", description = "Estoy intentando reunir algunos suministros para enviarlos a nuestra avanzada cerca de la playa del este. Tok'Kar hace lo que puede, pero entre sus guardias y cocinar para los soldados, no le queda mucho tiempo.\n\nLes encanta cocinar carne de Denteserra cuando pueden, pero no he tenido tiempo de conseguirles otro cargamento. ¿Te importaría echarles una mano?\n\nLos Denteserra jóvenes no son tan sabrosos como los viejos, así que no los cojas. Hay que esperar un año o dos para que alcancen el tamaño ideal.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][699] = {title = "alta de suministros", objective = "Lleva 6 garras de sacudidores Denteserra a Tok'Kar en el Pantano de las Penas.", description = "Con la amenaza de múrlocs en la costa, nos hemos quedado aquí para proteger, o advertir si no podemos hacer más, de cualquier amenaza a Rocal. No nos deja mucho tiempo para relajarnos y nos vendría bien algo de ayuda...\n\nLas garras de sacudidores Denteserra son unas armas excelentes si se preparan bien. Tráeme algunas garras y te recompensaremos con una de nuestras armas como agradecimiento por la carne fresca y la buena compañía.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][703] = {title = "Alas de águila ratonera a la parrilla", objective = "Llévale 4 alas de águila ratonera a Aparejez.", description = "¡Sí señor, mis alas de águila ratonera a la parrilla son para chuparse los dedos! La salsa es cremosa y la carne, penetrante. ¡Y su aroma atraerá a los hambrientos de kilómetros a la redonda!\n\nTengo todo lo necesario para cocinar una tanda. Todo... ¡excepto las alas de águila ratonera!\n\nSi quieres algunas, tráemelas. Consígueme suficientes alas de águila ratonera ¡y hasta podría compartir la receta contigo!", progress = "Hola, <nombre>. ¿Me has traído mis alas?", completion = "Ah, empezaré con esas alas enseguida. ¡Ya casi puedo saborearlas! \n\n¡Aquí tienes la receta en caso de que las quieras preparar tú mismo!", rewards = "Recibirás:\n\nAla de águila ratonera a la parrillaReceta: ala de águila ratonera a la parrilla"}
MultiLanguageQuestData['mx'][704] = {title = "El sino de Agmond", objective = "Llévale 4 urnas de piedra labrada al prospector Vetaferro en Loch Modan.", description = "El último informe de Agmond es preocupante, ¡sobre todo ahora que ha muerto! Mencionaba que en sus excavaciones había desenterrado unas \"urnas antiguas\" en la explotación situada en las afueras de Uldaman. Me temo que las urnas que encontró instigaron a los troggs, igual que lo hicieron los ídolos que encontré aquí.\n\nNecesito que recuperes esas urnas para nuestros estudios. Ve a la excavación de Uldaman, encuentra las urnas y tráemelas aquí.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGuantes de prospector"}
MultiLanguageQuestData['mx'][705] = {title = "La pesca de perlas", objective = "Llévale 9 perlas azules a Aparejez en las Tierras Inhóspitas.", description = "Las Tierras Inhóspitas son un lugar hostil, lleno de sanguinarios depredadores y de carroñeros sin escrúpulos. Aterrador, sobre todo para un diminuto goblin. Para sobrevivir, ¡tengo que ser astuto!\n\nConozco la receta de las bombas centelleantes. Las uso para espantar a los animales. Pero se me está acabando uno de los ingredientes: polvo de perla azul triturada. Consígueme un puñado y no te arrepentirás.\n\nEh, y espero que lleves puestas unas buenas botas. Las perlas azules que necesito se encuentran en unas almejas de El Arrecife Mortal.\n\nEse mismo, ¡El Arrecife Mortal de Tuercespina!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Rifle cegadorVarita cegadoraRecibirás:\n\nBomba cegadora"}
MultiLanguageQuestData['mx'][706] = {title = "Encantamientos Llamarada ígnea", objective = "Consigue 1 corazón de draco negro para Sigrun Extracero.", description = "Cuando era aprendiz de Feranor Ferrodedo, aprendí su técnica especial para imbuir armas con encantamientos ígneos. Lo último que supe de él es que estaba trabajando en una herrería para una partida de cazadores en Lordaeron.\n\nNo puedo contarte demasiados detalles del proceso pero sí puedo decirte que requiere sangre del corazón de una cría de draco negro que aún esté latiendo. No estoy demasiado ocupado ahora, espero instrucciones de Forjaz. Si me traes un corazón de las crías del Barranco Lethlor, ¡te demostraré de lo que soy capaz!", progress = "¿Cómo va la caza, <clase>?", completion = "Ah, desde luego, ¡esto vendrá de perlas! ¡Esto hará que al atacar tus armas despidan un calor abrasador!", rewards = "Recibirás:\n\nEncantamiento Llamarada ígnea"}
MultiLanguageQuestData['mx'][707] = {title = "¡Vetaferro te necesita!", objective = "Habla con el prospector Vetaferro en la Excavación de Vetaferro en Loch Modan.", description = "<nombre>, he recibido unos informes del prospector Vetaferro sobre la excavación de Loch Modan; dice que necesita a alguien que estudie otra excavación.\n\nNo dice nada más, pero si te apetece estirar las piernas, ve a hablar con Vetaferro.", progress = nil, completion = "¿Vienes de parte de Pico Tormenta? Muy bien. \n\nTengo trabajo para ti.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][709] = {title = "La solución a la maldición", objective = "Llévale la tablilla de Ryun'eh a Theldurin el Perdido.", description = "¡Ay, ay! ¡Ay, ay! Se acerca una catástrofe. ¡Recuerda mis palabras! ¡Una catástrofe!\n\nNo, no puedo hablar de ello... no puedo pronunciar sus nombres, ¡podrían oírme! Pero si aprendemos de ellos... Sí, si aprendemos más... ¡quizás logremos frustrar sus planes!\n\nQuizás.\n\nVe a Uldaman. ¡No! ¡Ya te lo dije! Tienes que encontrar... encontrar la tablilla de... Ryun'eh. ¡Sí, encuéntrala! ¡Y no me hagas pronunciar ese nombre otra vez!\n\nSe encuentra en las profundidades de ese lugar, en un antiguo cofre. Ahí es donde se esconde... en un cofre creado antes del tiempo de los enanos.", progress = "¿Has encontrado la tablilla? ¡Debe de contener secretos! ¡Secretos para salvarnos!", completion = "¡Oh, la suerte está de nuestra parte! ¡Gracias! ¡Puede que aún nos salvemos!", rewards = "Recibirás:\n\nToga de orador del Sino"}
MultiLanguageQuestData['mx'][710] = {title = "Estudio de los elementos: roca", objective = "Encuentra 10 fragmentos de piedra pequeños y llévaselos a Lotwil Veriatus en las Tierras Inhóspitas.", description = "Aquí en las Tierras Inhóspitas, he dejado de trabajar en mi más reciente proyecto: mis grilletes de esclavitud elemental.\n\nCuando acabe, permitirán a los magos invocar a elementales aún más poderosos para fines de más alcance. Para empezar, necesito fragmentos de piedra pequeños para probar mis más recientes hechizos ofensivos y unos aparatitos que he compuesto.\n\nEs fácil reunir tales fragmentos de los elementales de piedra inferiores hacia el oeste de este lugar. ¿Podrías traerme algunos?", progress = "Este sitio es perfecto para... ¿Podrías sujetarme eso un momento? Sí, justo ahí, a lo largo del vector normal. Ahora, ¿por dónde...? Ah, sí. El lugar perfecto para probar mi proyecto más reciente. La materia prima, el espacio abierto... ¿qué más podría pedir un ilustrado y brillante practicante de las artes?", completion = "Estos nos servirán, &lt;nombre&gt;. Gracias. Mm, algo más de arena de lo que preveía. Tengo que ajustar el coeficiente de fricción. No, espera; aún debería ser marginal con el aceite de Escarcha.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][711] = {title = "Estudio de los elementos: roca", objective = "Llévale 3 losas de piedra grandes a Lotwil Veriatus en las Tierras Inhóspitas.", description = "<nombre>, has demostrado ya más valía que todos mis aprendices juntos.\n\nLas siguientes piezas que necesito requerirán algo más de fuerza. Si tienes cuidado, encontrarás grandes losas de piedra en los elementales de piedra. Sus cuerpos son más resistentes y voluminosos, así que tendrás más probabilidades de poder extraer piezas lo suficientemente grandes para mis pruebas. Los hallarás más hacia el oeste desde aquí o al sureste bordeando las faldas de las montañas.\n\nTómate tu tiempo; estaré ocupado probando estos fragmentos más pequeños que me has traído.", progress = "Estoy encantadísimo, <nombre>. Mis hechizos han afectado a las piezas más pequeñas, justo como predije. Si este experimento sale tan bien como anticipo, los elementales que podré controlar harán que cualquier cosa invocada antes quede a la altura del betún.", completion = "¡&lt;nombre&gt;, sencillamente asombroso! Creía que haría falta media docena de tauren para traerme todos estos fragmentos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][713] = {title = "Mantener la cabeza fría", objective = "Encuentra aceite de Escarcha y llévaselo a Lotwil Veriatus en las Tierras Inhóspitas.", description = "Déjame decirte algo sobre el aceite de Escarcha: nada impide que un motor o un engranaje se recalienten como ese aceite.\n\nSus propiedades de enfriamiento son extraordinarias y su longevidad como lubricante no tiene parangón. Y eso no es todo: también ayuda a retener los encantamientos de los objetos mágicos.\n\nNecesito un frasco de este aceite para aumentar la capacidad mágica de mis grilletes y hacerlos lo suficientemente poderosos para impedir que nuestros amigos invocados nos maten a todos.\n\nBro'kin, un amigo goblin, te enseñará a confeccionarlo. Se encuentra en Alterac.", progress = "¿Has encontrado el aceite que necesitaba? ¡Me vendría tan bien que encontraras un poco!", completion = "¡Formidable! Será el refrigerante perfecto para mis nuevos brazales. Si los encantamientos no duran un siglo, le daré todas mis pertenencias a Servo. \n\nTodos los magos de la Asamblea sentirán un respeto reverencial cuando acabe con esto, &lt;nombre&gt;. Espera y verás.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][716] = {title = "Es mejor la piedra que la tela", objective = "Llévale unos brazales de bronce estampados a Lucien Borlallave en las Tierras Inhóspitas.", description = "Sé lo agarrado que Lotwil puede llegar a ser, <nombre>, así que permite que te haga algo por las molestias. A lo mejor hasta te protege de la próxima atrocidad que será el más reciente invento de Lotwil.\n\nHe estado trabajando con todas las piedras sobrantes que habías recolectado para él y puedo hacerte unos buenos brazales que podrían serte de utilidad. Tienen un encantamiento, claro.\n\nSolo necesito brazales de bronce estampados confeccionados por un herrero para poder fabricar los brazales que te estoy haciendo.", progress = "Yo no esperaría demasiado para conseguir ese brazal, <nombre>.\n\n¿Quién sabe lo que puede pasar después?", completion = "Aquí tienes, &lt;nombre&gt;. Pruébatelos.", rewards = "Recibirás:\n\nBrazales de paño de piedra encantados"}
MultiLanguageQuestData['mx'][717] = {title = "Terremotos", objective = "Usa el Signo de la Tierra para activar los pilares de amatista, de ópalo y de diamante y así obtener las piedras rúnicas.\n\nColoca las piedras rúnicas en el Sello de la Tierra para liberar a Latigoscuro y a Hematus.\n\nMátalos y llévale a Garek las ataduras de Latigoscuro, las cadenas de Hematus y el Signo de la Tierra.", description = "Ha quedado claro que no podemos garantizar que Latigoscuro y Hematus permanezcan encarcelados en Lethlor. Que esos dragones negros se adueñaran del lugar y que los ogros consiguieran robar el Signo indica que se deben tomar medidas más drásticas.\n\nLa prisión de los dracos está controlada por tres piedras rúnicas que solo se pueden extraer con el Signo de la Tierra. Esas piedras rúnicas pueden entonces usarse para romper el sello que los mantiene presos.\n\n<nombre>... asegúrate de que su sueño es eterno.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Coraza Viento abrasadorCamisote de escama prismáticaPeto forjado por la guerraPodrás elegir una de estas recompensas:\n\nMedallón de ráfaga mental\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][718] = {title = "Espejismos", objective = "Recupera el cajón de suministros para Sigrun Extracero.", description = "Con las prisas por marcharnos de la excavación de Uldaman, nos obligaron a abandonar muchos carros y muchas cajas de suministros por el camino. Los ogros locales del Asentamiento Kosh se han lanzado sobre nuestro equipo abandonado como buitres sobre un cadáver en descomposición. No huele mucho mejor tampoco. Me refiero a los cadáveres.\n\nSea como fuere, se llevaron el carro en el que se transportaban todas nuestras armas y tal y tal..., bueno, esto es un poco violento, no hemos podido conseguir nada de comida.\n\nEstamos metidos en un lío, ¿nos podrías ayudar?", progress = "El desierto es mal lugar para tener hambre, amigo, te lo digo yo.\n\nEh... ¿qué es eso de ahí?...", completion = "Muchas gracias, &lt;nombre&gt;. Mientras no estabas, yo... estooo... tragué un puñado de arena. Me... \n\nBah, no importa, saldremos esta noche y conseguiremos algo de comida. ¡Comeremos como reyes!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][719] = {title = "Un enano y sus herramientas", objective = "Encuentra el pico de la suerte de Ryedol y llévaselo al prospector Ryedol al sur de la excavación de Piemartillo.", description = "Hola, <nombre>. Ten cuidado por estos lares. Hay enanos Hierro Negro por todas partes, parecía del clan Forjatiniebla.\n\nAcaban de atacar la excavación donde trabajaba, se han cargado a casi todos, hasta a mi jefe Piemartillo. Me escapé por los pelos.\n\nEl sitio está justo al norte de este lugar y estoy intentando planear la forma de recuperar parte de nuestros suministros, sobre todo mi pico de la suerte.\n\n¿Te apetecería echarme una mano? ¡Uno de esos malditos Hierro Negro tendrá mi pico! Podría ser cualquiera.", progress = "Todavía no sé con seguridad qué buscaban los Forjatiniebla pero desde luego tenían un propósito.", completion = "Eres mi salvador, &lt;clase&gt;. Me alegro de que alguien le haya dado una lección a esos Forjatiniebla. Gracias por tu ayuda.", rewards = "Recibirás:\n\nMartillo de Ryedol"}
MultiLanguageQuestData['mx'][720] = {title = "Un signo de esperanza", objective = "Localiza al prospector Ryedol y dile que Grez Piemartillo está vivo.", description = "<Hay texto garabateado de forma tosca con tiza en el mapa.>\n\n\"Ryedol, \nMe llevan a Uldaman. Envía ayuda.\n-Piemartillo\"", progress = nil, completion = "¡¿Piemartillo está vivo?! ¡Increíble, &lt;nombre&gt;!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][722] = {title = "El amuleto de los secretos", objective = "Encuentra el amuleto de Piemartillo y llévaselo a Uldaman.", description = "Eres valiente... <tose>... por venir a Uldaman para mí, <clase>.\n\nSi realmente estás aquí para ayudar... al viejo Piemartillo, entonces... <tose>... tendrás que encontrar... mi amuleto.\n\nSombraprofunda lo tiene... Magregan Sombraprofunda. está por aquí... en las ruinas, seguro. Ese amuleto los conducirá... <tose>... derechito a los pergaminos si no lo paran. Depende de ti, <nombre>. Por favor... recupera el amuleto.\n\nCon los pergaminos los Hierro Negro conseguirán crear gólems aún más poderosos. Lo sé. Me lo dicen los huesos.", progress = "El clan Forjatiniebla... <tose> es peligroso. Ten cuidado. <tose>... tienes qu’encontrar el amuleto.", completion = "¡Toma! &lt;Tose repetidamente.&gt; \n\nSabía que encontrarías mi amuleto, &lt;nombre&gt;. \n\n Muy bien, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][727] = {title = "Ir a Forjaz a buscar el \"Compendio\" de Yagyin", objective = "Dale el sigilo del Martillo a Gerrig Agarrahueso en La Caverna Abandonada de Forjaz.", description = "La tablilla es muy reveladora. ¡Aunque no lo suficiente! ¡Ni de lejos!\n\nHay un cuaderno, un compendio que Yagyin escribió en otros tiempos. La... gente de los que huí... guardan este cuaderno en muchos lugares. Y sus más eruditos lo estudian. El conocimiento en él contenido es muy vasto. ¡Conocimiento para protegernos!\n\nVe a ver a Gerrig Agarrahueso. Se encuentra en una tienda de Forjaz, en La Caverna Abandonada. Muéstrale este sigilo y creerá que eres de los suyos. Pregúntale por el Compendio de Yagyin... ¡y tráemelo!", progress = "Hola. Bienvenido a mi tienda pero ojo con lo que tocas.\n\nEl conocimiento puede ser mortal.", completion = "Oh. Saludos, hermano. \n\nY alabados sean los moradores del subsuelo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][728] = {title = "Ir a Entrañas a buscar el \"Compendio\" de Yagyin", objective = "Llévale el sigilo del Martillo al vigilante Bel'dugur en Entrañas.", description = "La tablilla es muy reveladora. ¡Aunque no lo suficiente! ¡Ni de lejos!\n\nHay un cuaderno, un compendio que Yagyin escribió en otros tiempos. La... gente de los que huí... guardan este cuaderno en muchos lugares. Y sus más eruditos lo estudian. El conocimiento en él contenido es muy vasto. ¡Conocimiento para protegernos!\n\nVe a ver al vigilante Bel'dugur en Entrañas, Lordaeron. Muéstrale este sigilo y creerá que eres de los suyos. Pregúntale por el Compendio de Yagyin... ¡y tráemelo!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][729] = {title = "El prospector despistado", objective = "Viaja al sur y asegúrate de que el prospector Tripirrem está bien.", description = "Fue un honor que el maestro Mostachogris me destinara a trabajar bajo la guía del gran prospector Tripirrem. En la Academia de Forjaz todo el mundo sabía de los grandes descubrimientos de Tripirrem.\n\nPero el prospector es un poco... mm... despistado... Vive en su mundo.\n\nPor ejemplo: habíamos descubierto pruebas de la existencia de una gran sociedad. Y un día, unos terribles gólems surgieron de la tierra e invadieron la excavación. Y Tripirrem ni se dio cuenta. Yo corrí a Auberdine a pedir ayuda.\n\n¡Te lo ruego, viaja hacia el sur y asegúrate de que el prospector está bien!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][730] = {title = "¿Problemas en Costa Oscura?", objective = "Viaja a Auberdine y busca rastros del equipo de excavación enano.", description = "Me agrada ver a <un/una> <clase> mostrando interés por las grandes maravillas arqueológicas de nuestro mundo.\n\nA menudo nuestro trabajo es considerado poco más que una afición por nuestros amigos de la Alianza. Pero es porque no se dan cuenta de que son los recientes descubrimientos de Khaz Modan los que han probado que una poderosa fuerza amenaza todo Azeroth, de Lordaeron a Kalimdor.\n\nEmpiezo a preocuparme de verdad por el personal que envié a Costa Oscura. Hace semanas que no tengo noticias suyas.\n\nViaja a Auberdine y busca pistas de su paradero.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][731] = {title = "El prospector despistado", objective = "Protege al prospector Tripirrem mientras busca el fósil misterioso. Luego vuelve a Auberdine y busca a la arqueóloga Hollee.", description = "Dime, Hollee... ah, no, que no eres Hollee. ¿Dónde está Hollee?\n\nDeja, total, no es importante. Tenemos que encontrar ese cepillo de piedra... Quiero decir, el fósil misterioso. Tenemos que encontrar ese fósil. La Liga de Expedicionarios de Darnassus querrá algún informe de lo que he estado haciendo.\n\nAvísame cuando estés <listo/lista>. Iremos a la caza de ese cepillo. Quiero decir, ¡del fósil! Así encontraremos algo palpable para satisfacer a la Liga.\n\n¿Estás <listo/lista>?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][732] = {title = "Terremotos", objective = "Recupera el Signo de la Tierra para Garek.", description = "Sigrun me ha dicho que habías sido de gran ayuda para él. Quizás te reclute para ayudarme. Mi maestro, Krasus del Kirin Tor, me envió aquí para poner fin a los disturbios que se estaban produciendo en Barranco Lethlor.\n\nNo puedo revelarte la naturaleza exacta de mi misión aquí ni de las tareas que debo acometer pero ten por seguro que son de vital importancia.\n\nUn grupo de ogros errantes, avistados en ocasiones cerca del Asentamiento Boff, robaron un objeto llamado el Signo de la Tierra; debo recuperarlo. Tráemelo y te contaré más detalles.", progress = "El grupo de ogros nómadas se desplaza entre sus campamentos por las Tierras Inhóspitas; el calor que despide la reseca tierra y los remolinos de viento dificultarán su rastreo. He oído que a veces pasan por el Asentamiento Boff. Si estás perdido, podrías empezar a buscar allí.", completion = "Es buena noticia que lleves el Signo, &lt;nombre&gt;. Los enanos Hierro Negro de la Fortaleza de Angor crearon el Signo de la Tierra para retener a dos de los más crueles tenientes de Alamuerte, los gemelos Latigoscuro y Hematus.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][733] = {title = "¡A gorronear!", objective = "Consigue 7 trocitos de armadura para Sigrun.", description = "La cosa se va a poner fea aquí si no logro gorronear algunos materiales para construir unas defensas y otras necesidades. Me he dado cuenta de que los ogros de la zona parecen estar bien surtidos de chatarra. A lo mejor las historias de máquinas de asedio en las Tierras Inhóspitas no estaban muy alejadas de la realidad después de todo...\n\nEn cualquier caso, el prospector lleva un tiempo preocupado por el estado de nuestro campamento, así que debería ponerme manos a la obra pronto si es posible.\n\nEl principal campamento de ogros está en la Gruta Rotapolvo, una buena caminata hacia el oeste desde aquí.", progress = "Bueno, me he apañado con lo que había pero... no es mucho. ¿Has encontrado más suministros?", completion = "Es un comienzo, &lt;nombre&gt;, y tendrá que servir hasta que sepamos algo de Forjaz o de la Liga de Expedicionarios. \n\nBien, y si ahora pudiera conseguir sal en algún lado para mi barril de bebida...", rewards = "Escudo SalbacBotas con talón de aceroRecibirás:\n\n"}
MultiLanguageQuestData['mx'][735] = {title = "La Estrella, la Mano y el Corazón", objective = "Devuelve los objetos de la lista a Gerrig Agarrahueso a Forjaz.", description = "El Compendio de Yagyin, ¿eh? ¿Se ha empezado a escribir otro capítulo sobre nosotros? Disculpa, no debería haber preguntado.\n\nTe ayudaré porque tengo dos ejemplares. Hay que ayudarse mutuamente, ¿eh? Así es como se prospera.\n\nQuiero tres objetos de poder. Tráemelos y te daré el Compendio.\n\nNo voy a decir los nombres en alto, nunca se sabe quién está escuchando. Te los voy a escribir.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][736] = {title = "La Estrella, la Mano y el Corazón", objective = "Llévale los objetos que aparecen en la nota de Bel'dugur al vigilante Bel'dugur de Entrañas.", description = "¿Necesitas el Compendio de Yagyin? Así que, ¿tu plan es reunir a otro grupo? Claro que sí... y por supuesto te ayudaré, <hermano/hermana>.\n\nPero tendrás que darme algo a cambio.\n\nNecesito tres objetos de poder. Tráemelos y el compendio será tuyo.\n\nNo puedo decir en alto sus nombres así que te los escribiré.\n\nSi me consigues los objetos de esta lista, serás verdaderamente <merecedor/merecedora> de crear tu propia sección dentro de nuestra orden.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][737] = {title = "El saber prohibido", objective = "Llévale el compendio de Yagyin a Theldurin.", description = "Aquí tienes la revista, <nombre>. Huelga decir que debes extremar el cuidado con ella. Además de mantenerla alejada de manos enemigas.\n\nEste cuaderno contiene muchas verdades...\n\n... Y la verdad puede encender chispas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCráneo de fatalidad inminente"}
MultiLanguageQuestData['mx'][738] = {title = "Encontrar a Agmond", objective = "Encuentra a Agmond.", description = "El prospector Agmond estaba a cargo de nuestra excavación en las Tierras Inhóspitas, hacia el suroeste. Y digo \"estaba\" porque... bueno, hace semanas que no sé nada de él. Necesito que encuentres a Agmond para poder conseguir su informe.\n\nLa última vez que oímos algo de Agmond se encontraba en la más meridional de nuestras excavaciones en las Tierras Inhóspitas, una pequeña explotación más allá de la Fortaleza de Angor. Yo empezaría a buscarlo allí.", progress = nil, completion = "Este esqueleto debe de ser lo que queda del desafortunado Agmond. Su cuerpo está destrozado y han limpiado sus huesos.", rewards = "Recibirás:\n\nCinturón de prospector rasgadoJadeMena de oro"}
MultiLanguageQuestData['mx'][742] = {title = "La Caza de Vallefresno", objective = "Habla con Senani Corazón Atronador en Puesto del Hachazo, en Vallefresno.", description = "¡Atención, jóvenes aventureros! ¡Los páramos de Vallefresno los espera!\n\nLa Horda ha aumentado su presencia en las tierras al norte de Los Baldíos. Nuestras dos avanzadas, Puesto del Hachazo y La Ensenada de Zoram, se esfuerzan por traer gloria a la Horda. Aquellos que deseen demostrar su valía deben buscar ayuda allí. Nota: Senani Corazón Atronador del Puesto del Hachazo, al norte de Los Baldíos, busca a aventureros que deseen participar en la gran Caza de Vallefresno.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][743] = {title = "Las Viento Furioso son un peligro", objective = "Lleva 8 garfas de Viento Furioso a Ruul Garra de Águila al Poblado Pezuña de Sangre.", description = "Te agradezco que te pares a hablar conmigo, <nombre>. Me llamo Ruul y soy guerrero y maestro.\n\nHas alcanzado la edad en la que debes prepararte para las pruebas que te esperan si quieres ir más allá de Mulgore.\n\nPara poner a prueba tu fuerza, ve al sureste a enfrentarte a las arpías Viento Furioso. Sus nidos están en los bordes de la montaña, alejados del camino.\n\nSon enemigas naturales de Mulgore y serán un buen indicativo de tu habilidad.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][744] = {title = "Preparación para la ceremonia", objective = "Consigue 6 plumas azur y 6 de bronce.", description = "<nombre>, mi hermano pronto se personará ante el jefe Pezuña de Sangre y será un honor para mí prepararle su penacho.\n\nMe gustaría pedirte un favor mientras acabo de curtir estas cintas de piel. No he podido reunir todas las plumas que necesito y me preguntaba si tú podrías ayudarme a conseguir más.\n\nPuedes obtener las plumas del tamaño adecuado de las arpías que habitan al norte y noroeste de Cima del Trueno. Solo necesito 6 plumas azur y 6 de bronce para completar mi diseño.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Leotardos de hierba marrónGuantes de kodo toscosArmadura para pierna de zancudo de llanuraRecibirás:\n\n"}
MultiLanguageQuestData['mx'][745] = {title = "Compartir la tierra", objective = "Mata a 10 curtidores, 8 desolladores y 5 furtivos Crines Pálidas y vuelve al Poblado Pezuña de Sangre para hablar con Baine Pezuña de Sangre.", description = "<nombre>, esta tierra está herida por muchos conflictos. Espero que no tengas que presenciar tantos como yo en mi vida. Sin embargo, te pido que vayas a uno. Verás lo peligrosa que puede ser cualquier amenaza, por pequeña que sea, si no se ataja de inmediato.\n\nUnos gnolls Crines Pálidas se han instalado al sur de Pezuña de Sangre y en una cueva del oeste. No respetan nuestros intentos de establecer comunicación y matan a placer por todo Mulgore.\n\nLas palabras ya no sirven de nada.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPerdigón cegador"}
MultiLanguageQuestData['mx'][746] = {title = "Una excavación de los enanos", objective = "Recoge 5 picos de prospector. \n\nBusca una forja para destrozar los picos. \n\nLleva 5 trozos de herramienta rota a Baine Pezuña de Sangre al Poblado Pezuña de Sangre.", description = "Al noroeste hay enanos preparando una excavación. Creen que la tierra está llena de secretos y eso es cierto, pero perforarla no es la mejor manera de descubrirlos.\n\nEncuentra las herramientas de los enanos, rómpelas y tráeme los pedazos.\n\nNecesitarás una forja para romperlas. Hay una en Cima del Trueno, pero te servirá cualquiera, incluso la del campamento enano.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Ataduras reforzadasLeotardos de kodo sin rematarRecibirás:\n\nObjeto #5Currency Token Test Token 4"}
MultiLanguageQuestData['mx'][747] = {title = "Empieza la caza", objective = "Grull Viento de Halcón quiere que le lleves 7 plumas y 7 piezas de carne de zancudo de llanura al Campamento Narache.", description = "Tienes un aire prometedor, demostrarás tu valía ante la tribu. Puede que pronto te acojan en la gran ciudad de Cima del Trueno. Pero antes de eso, tendrás que mostrar tu valía ante mi padre, el Jefe Viento de Halcón.\n\nAquí en Mesa de la Nube Roja estamos orgullosos de nuestra habilidad para la caza. Los tauren cazamos por necesidad y por deporte. Nos estamos quedando sin carne y necesitamos plumas para la ropa. Caza zancudos de llanura y demuestra tu valor mientras reabasteces al poblado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de anillas pintadosCinturón nómadaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][748] = {title = "Pozos envenenados", objective = "Lleva 6 zarpas de lobo de pradera y 4 garfas de zancudo de llanura a Mull Tronacuerno al Poblado Pezuña de Sangre.", description = "¡Los goblins han mancillado nuestros pozos de agua sagrada! No podemos permitirlo.\n\nPara limpiarlos necesito un tótem de limpieza; tú lo llevarás al pozo y realizarás el ritual de limpieza.\n\nEl primer tótem es para el Pozo Pezuña Invernal. Necesitamos la ayuda de la tierra. Tráeme zarpas de lobo de pradera y espolones de zancudo de llanura adulto. Los encontrarás al suroeste.\n\nSé prudente, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][749] = {title = "La Caravana Devastada", objective = "Morin Acechanubes quiere que registres las cajas de la Caravana Devastada.", description = "Hace unos días nos encontramos una caravana escoltada de Ventura y Cía. en la costa norte del Lago Toro de Piedra. En un combate anterior habíamos perdido a dos de los nuestros, así que atacamos la caravana.\n\nDejamos las cajas porque lo incendiamos todo, pero hemos visto a rescatadores de Ventura y Cía. cerca de las carretas quemadas; quizás quedó algo de valor.\n\nPodrías acercarte a ver qué hay en las cajas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][751] = {title = "La Caravana Devastada", objective = "Lleva los documentos de Ventura y Cía. a Morin Acechanubes cerca del Poblado Pezuña de Sangre.", description = "Al abrir la caja ves que está llena de mineral, otra prueba de las operaciones mineras de Ventura y Cía. en Mulgore. Coges el paquete de documentos que hay encima del mineral.\n\nEn las laderas del este se oyen ruidos de actividad industrial y se ve una columna de humo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][752] = {title = "Una humilde contribución", objective = "El Jefe Viento de Halcón quiere que vayas a buscar a su madre cerca del pozo que hay al sureste del Campamento Narache.", description = "Todos los miembros de la tribu contribuyen a la armonía de la vida. Vivimos juntos y trabajamos juntos.\n\nCada uno de nosotros es responsable del bienestar de los demás. Quisiera pedirte un pequeño favor.\n\nMi madre se fue esta mañana a traer agua del pozo que hay al sureste de Narache. Ya ha pasado un buen rato. ¿Podrías ir a buscarla mientras yo atiendo los asuntos de la tribu?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][754] = {title = "La purificación de Pezuña Invernal", objective = "Usa el tótem de limpieza en el Pozo Pezuña Invernal y ve a ver a Mull Tronacuerno.", description = "Este es el tótem para el Pozo Pezuña Invernal. Llévalo al pozo y lleva a cabo el ritual de limpieza. El pozo está hacia el sureste y en poder de los repugnantes goblins.\n\nEs una misión difícil, pero no podemos perder el acceso a los pozos.\n\nSuerte, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][756] = {title = "El tótem de Tronacuerno", objective = "Lleva 6 garras de acechador y 6 garras de puma a Mull Tronacuerno.", description = "Para crear el tótem para el Pozo Tronacuerno necesitamos las garras de los depredadores de Mulgore. Tráeme garras de acechador de pradera y puma de las estepas.\n\nLos encontrarás tanto hacia el este como hacia el oeste.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][758] = {title = "La purificación de Tronacuerno", objective = "Usa el tótem de limpieza en el Pozo Tronacuerno y ve a ver a Mull Tronacuerno.", description = "<nombre>, el tótem ya está listo. Debes llevar a cabo el ritual una vez más.\n\nLlévate el tótem al Pozo Tronacuerno, que está al norte. Vuelve aquí cuando termines.\n\nQue los espíritus te acompañen.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCapa Tronacuerno"}
MultiLanguageQuestData['mx'][759] = {title = "El tótem Ferocrín", objective = "Lleva 8 dientes de alfa de pradera a Mull Tronacuerno al Poblado Pezuña de Sangre.", description = "Ya solo queda por limpiar el Pozo Ferocrín. Para ello, la tierra debe ofrecernos los dientes de un depredador feroz, el lobo alfa de pradera. Los encontrarás al norte. Vuelve cuando hayas conseguido los dientes.\n\nLos alfa suelen deambular alrededor de nuestra ciudad, Cima del Trueno.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][760] = {title = "La purificación de Ferocrín", objective = "Usa el tótem de limpieza Ferocrín en el Pozo Ferocrín.", description = "Los espíritus están complacidos contigo por la limpieza del Pozo Tronacuerno y el Pozo Pezuña Invernal, joven <nombre>. El tótem de Ferocrín ya está listo y tu última tarea te espera.\n\nEl Pozo Ferocrín está al norte de Cima del Trueno. ¡Lleva a cabo el ritual! ¡Limpia la tierra del veneno de los Tótem Siniestro! Que las aguas vuelvan a fluir puras y claras.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Tomahawk ceremonialBastón de vigía de los sueñosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][761] = {title = "La caza de los aguilones", objective = "Lleva 8 péñolas trofeo de aguilón a Harken Tótem de Viento al Poblado Pezuña de Sangre.", description = "El aguilón es un ave muy astuta, difícil de encontrar y de cazar. Un trofeo de plumas de aguilón sería una prueba de tu talento cazador.\n\nVe a las llanuras y caza uno.\n\nTráeme las plumas y gana honor para tu clan.\n\nEstán por todo Mulgore, pero tendrás que estar ojo avizor para verlos y muy veloz para cazarlos.", progress = "¿Me traes las plumas de aguilón, <nombre>?", completion = "Sé que esto no ha sido fácil, &lt;nombre&gt;. Has probado tu valor, &lt;clase&gt;, nos alegramos de tenerte en el Poblado Pezuña de Sangre.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][764] = {title = "Los Ventura y Cía.", objective = "Mata a 14 trabajadores de Ventura y Cía. y a 6 supervisores de Ventura y Cía. para Morin Acechanubes en Poblado Pezuña de Sangre.", description = "Esto explica el aumento de personal y equipamiento de Ventura y Cía. que hemos visto en Mulgore. Esos goblins... su empresa se expande demasiado rápido y contra su conveniencia. Ya conoces el dicho, enséñale algo a un goblin, y escucharás el sonido de fondo de la balanza.\n\nSon unos bichejos de lo más codiciosos. Por desgracia para sus negocios, los tauren no permitiremos que lleven a cabo sus operaciones en nuestras tierras. Dirígete a su mina, al noreste de la caravana saqueada y envíales un mensaje.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][765] = {title = "Supervisor Saltatuercas", objective = "Mata al supervisor Saltatuercas y lleva su sujetapapeles a Morin Acechanubes al Poblado Pezuña de Sangre.", description = "Según los documentos que recuperaste de la caravana, Ventura y Cía. ideó varios planes para tratar de echarnos de nuestras tierras, y así tener libertad total para saquearlas.\n\nLos límites a los que estaban dispuestos a llegar para conseguir sus objetivos me asquean. Quiero ver muerto al cerebro que ideó estos planes. Se llama supervisor Saltatuercas y lo encontrarás en la Mina Ventura y Cía., al este de la caravana saqueada. Tráeme su sujetapapeles y veremos si encontramos algo útil.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "MachacagoblinsCuchillo de lucha compactoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][766] = {title = "Mazzranache", objective = "Lleva un corazón de lobo de pradera, un fémur de puma de las estepas, una escama de zancudo de llanura y una molleja de aguilón a Maur Clamalluvias en el Poblado Pezuña de Sangre.", description = "Mi abuelo solía contarme historias sobre sus batallas con un zancudo llamado Mazzranache. Me hablaba de sus demoníacos ojos rojos, de sus afiladas garras y de su mordedura venenosa.\n\nLa casualidad quiso que, mientras viajaba por las llanuras, me lo encontrase; y me diese un terrible mordisco en el hombro. Era tan espantoso como mi abuelo solía describirlo. Para desinfectar la herida necesito unas cuantas cosas: un corazón de lobo, un fémur de puma, escamas de zancudo de llanura y una molleja.\n\nApresúrate, el tiempo corre.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Botas de AbiscorredorGuardamuñecas de cazador de las llanurasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][767] = {title = "Rito de la Visión", objective = "Habla con Zarlman Dos Lunas en el Poblado Pezuña de Sangre.", description = "El Rito de la Visión, uno de los Ritos de la Madre Tierra, te enseñará cómo ganar el respeto de los ancestros de Cima del Trueno.\n\nNuestra gente ha aprendido que la tierra es la sagrada proveedora. Para tomar parte en la visión ritual, debes hablar con el guía espiritual de la aldea, Zarlman Dos Lunas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][768] = {title = "Recolecta cuero", objective = "Llévale 12 pieles de cuero ligero a Veren Zancaalta a Cima del Trueno.", description = "Saludos, joven. El brillo en tus ojos me indica que estás impaciente por continuar la caza. ¡Ojalá traigas honor a tu clan!\n\nYo trabajo con pieles y con ellas confecciono ropajes y armaduras para las gentes de Cima del Trueno.\n\nSi cazas bestias y me traes sus pieles, confeccionaré algo especialmente para ti.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes con doble capaCinturón de piel de animalRecibirás:\n\n"}
MultiLanguageQuestData['mx'][769] = {title = "Bolsa de pellejo de kodo", objective = "Llévale 4 pellejos de cuero ligero y 4 hilos gruesos a Veren Zancaalta a Cima del Trueno.", description = "Los kodos de Mulgore son fuertes y robustos, unas cualidades que apreciamos mucho. Si tienes conocimientos de peletería y deseas aprender a fabricar una bolsa de piel de kodo, tráeme suministros para mi oficio.\n\nHazlo y compartiré mis conocimientos contigo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPatrón: bolsa de pellejo de kodo"}
MultiLanguageQuestData['mx'][770] = {title = "La capa del demonio marcado", objective = "Busca a alguien que conozca a Aullido Fantasma.\n\nObjeto provisto: \n", description = "La piel destrozada de Aullido Fantasma muestra la terrible herida que recibió en combate contra la Legión Ardiente.\n\nHabría que avisar de su muerte en el Campamento Rasguño de Sol...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Rifle de SkornMartillo de SkornRecibirás:\n\nObjeto #1Currency Token Test Token 4"}
MultiLanguageQuestData['mx'][771] = {title = "Rito de la Visión", objective = "Lleva 2 piedras de pozo y 2 bellotas ámbar a Zarlman Dos Lunas al Poblado Pezuña de Sangre.", description = "Para superar el Rito de la Visión debes conseguir los componentes necesarios para crear el Agua de los Videntes.\n\nNecesito piedras de pozo, que encontrarás cerca de los pozos de Mulgore. Las mezclaré con bellota ámbar, que cae de los orgullosos árboles de nuestra tierra.\n\nEstos ingredientes son mágicos; tómate el elixir resultante junto a la hoguera tribal para tener una visión. Síguela y te llevará al siguiente paso de esta misión sagrada.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][772] = {title = "Rito de la Visión", objective = "Bebe el Agua de los Videntes frente a la hoguera tribal del Poblado Pezuña de Sangre y sigue a la visión cuando aparezca.\n\nObjeto provisto: \n", description = "Aquí tienes el Agua de los Videntes.\n\nTómatela cerca de la hoguera tribal. Al cabo de un momento la visión se materializará junto a la hoguera.\n\nA partir de ahí, de ti depende el seguirla...", progress = nil, completion = "Be not afraid, &lt;nombre&gt;. You have successfully passed the Rite of Vision.", rewards = "Botas de caminante de lluviaCapa estropeada por el solRecibirás:\n\n"}
MultiLanguageQuestData['mx'][773] = {title = "Rito de la Sabiduría", objective = "Ve a Roca Roja, al este de Cima del Trueno, y busca al espíritu ancestral.", description = "Para que los ancestros de Cima del Trueno te acepten, tienes que superar el Rito de la Sabiduría.\n\nAhora que has superado el Rito de la Visión, los espíritus ancestrales de Roca Roja te darán las bendiciones de los ancestros. Solo quien ha bebido el Agua de los Videntes merece recibir la bendición.\n\nVe a Roca Roja, al este de Cima del Trueno, y busca al espíritu ancestral, <nombre>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][775] = {title = "Viaje a Cima del Trueno", objective = "Habla con Cairne Pezuña de Sangre en Cima del Trueno.", description = "Se te venerará en nuestra gran ciudad. Te mereces tal honor, <raza>, pues has completado los Ritos de la Madre Tierra.\n\nTu última misión consiste en buscar a nuestro noble jefe, Cairne Pezuña de Sangre, que vive en la cima de la mesa más alta de Cima del Trueno.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][776] = {title = "Los ritos de la Madre Tierra", objective = "Cairne Pezuña de Sangre de Cima del Trueno quiere que le lleves el cuerno de Arra'chea.", description = "Has superado los Ritos de la Madre Tierra y te has ganado un lugar en Cima del Trueno.\n\nPero no puedes dormirte en los laureles; debes probar tu valor constantemente.\n\nSomos cazadores, <nombre>. En Mulgore vive un hermoso kodo que se llama Arra'chea. Tráeme el cuerno de Arra'chea para demostrarme tu habilidad para rastrear y cazar.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nLeotardos de cazador kodo"}
MultiLanguageQuestData['mx'][782] = {title = "Alianzas rotas", objective = "Mata al jefe Tho'grun y llévale el Signo de la Tierra a Gorn en Kargath.", description = "Por la alianza de la Horda con el dragón Alamuerte durante la Segunda Guerra, sabemos que dos de sus tenientes, Latigoscuro y Hematus, estaban encarcelados en el Barranco Lethlor, un lugar remoto hacia el este. ¡Debemos acallar a nuestros depravados aliados ancestrales para restaurar el honor de la Horda!\n\nContratamos a Tho'grun y a su grupo de ogros mercenarios para que nos ayuden a conseguir el Signo de la Tierra, una llave necesaria para desbloquear la cárcel de los dragones. Pero Tho'grun nos traicionó, nos aplastó y se lo quedó. ¡Ve al Asentamiento Boff y recupéralo!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][783] = {title = "Una amenaza interna", objective = "Habla con el alguacil McBride.", description = "Nos encontramos en un buen aprieto, joven <clase>. Alamuerte y sus ejércitos del Crepúsculo han lanzado una ofensiva en Azeroth. El rey ha instado a los ciudadanos capacitados de la Alianza a unirse a la lucha.\n\nLos guardias de Ventormenta no dan abasto, ahora que muchos de nosotros están lejos y hay tantas amenazas. Por eso estamos reclutando a quien esté dispuesto a defender su tierra.\n\nSi vienes a luchar, habla con mi superior, el alguacil McBride. Está ahí atrás, en la abadía.", progress = nil, completion = "Ah, bien. Otro voluntario. Estamos recibiendo muchos estos días.\n\nEspero que sea suficiente.\n\nLas tierras humanas están amenazadas desde el exterior, y muchas de nuestras fuerzas han marchado al extranjero. Pero varios grupos de corruptos y vándalos han aprovechado la oportunidad para actuar dentro de nuestras fronteras.\n\nEsta es una batalla con muchos frentes, &lt;nombre&gt;. Prepárate para una campaña extensa.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][784] = {title = "Vencer a los traidores", objective = "Mata a 10 navegantes Kul Tiras, 8 marineros Kul Tiras y al teniente Benedict. Luego vuelve a buscar a Gar'Thok a Cerrotajo.", description = "Bajo el mando del almirante Valiente, los humanos de Kul Tiras invadieron Durotar, violando el pacto que el Jefe de Guerra selló con Jaina Valiente años atrás para derrotar a Archimonde.\n\nEl ataque humano fue rechazado y el Fuerte de Tiragarde cayó. Pero las reservas del Almirante, comandadas por el teniente Benedict, han retomado el fuerte y vuelven a amenazar nuestro territorio. Los humanos no tienen respeto alguno por la diplomacia.\n\nPor tu honor, viaja al sur hasta el Fuerte de Tiragarde y acaba con los invasores humanos.", progress = nil, completion = "Los relatos de tu valor viajan raudos, &lt;clase&gt;. Los de tu victoria en el Fuerte de Tiragarde serán anunciados en Orgrimmar.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][786] = {title = "Frustrar los planes kolkar", objective = "Lar Colmillo Acechador, de las afueras del Poblado Sen'jin, quiere que destruyas los 3 planes de ataque de Risco Kolkar.", description = "Baja la voz, <clase>. Los centauros Kolkar están justo al otro lado de este promontorio, al oeste, en el Risco Kolkar.\n\nLa otra noche, cuando estaban fuera, en una de sus batidas, me colé en su poblado y descubrí que esas bestias inmundas tienen planeado un ataque en tres oleadas contra los trols y orcos de Durotar.\n\nDebemos frustrar sus planes de invasión. Quizás tú puedas reunir la fuerza necesaria para infiltrarte en el Risco Kolkar y destruir sus planes.\n\nLo último que vi es que los habían repartido entre tres de sus líderes.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Capa de luchador avezadoBrazales de cordón pesadosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][788] = {title = "Dientes afilados", objective = "Mata a 8 jabalíes jaspeados y vuelve con Gornek en El Cubil.", description = "El primer punto del día será fortalecer un poco tu espalda. Te podría enviar a Los Baldíos, a cazar kodos, pero, sinceramente, nos eres más útil <vivo/viva> que <muerto/muerta>.\n\nCreo que lo mejor será que empieces por los jabalíes jaspeados que encontrarás al norte de aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de cuero desgastados por la batallaBotas de lana suaveRecibirás:\n\n"}
MultiLanguageQuestData['mx'][790] = {title = "Sarkoth", objective = "Mata a Sarkoth y llévale su zarpa a Hana'zua.", description = "¡<clase>! Creía que iba morir ahí fuera sin que nadie se enterara. Cuando estaba cazando los escórpidos del valle me crucé con uno que tenía un aspecto especialmente atroz. Me lancé contra él y conseguí asestarle un enorme golpe antes de que se enrollara en mi pierna.\n\nPero no estaba listo para su aguijón, y consiguió deslizarse en mi peto, desgarrando y penetrando en mi piel y derramando mi sangre. Por favor, ¡debes matar a ese escórpido! ¡Hay que defender mi honor! Combatí con él en la meseta que está al Sur.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][791] = {title = "Asume tu responsabilidad", objective = "Furl Ceñosprecio de la Atalaya de Cerrotajo quiere 8 retales.", description = "El tiempo me ha inutilizado para el combate. A mi edad, busco otras formas de ser útil.\n\nDesde este punto estratégico puedo vigilar la llegada de invasores. A medida que nuestra fuerza aquí se consolida, me encuentro dando la alarma cada vez menos.\n\nPara pasar el tiempo, creo objetos para ayudar a guerreros jóvenes y capacitados para defender nuestro hogar.\n\nA ti podría hacerte una bolsa para que lleves tus pertenencias. Si crees que te vendría bien, tráeme un retal. Sabrás lo que es... es un artículo muy normal tanto para centauros como para humanos.", progress = "Combatí con orgullo al lado del Jefe de Guerra cuando llegamos por vez primera a estas tierras. Mi piel está surcada por las cicatrices del combate.\n\nMi hacha y mi grito de guerra defendieron el honor de la Horda en la derrota de Archimonde, cuando humanos y elfos sellaron, unidos por la necesidad, su impía alianza.\n\nAhora, sigo sintiéndome útil en mi cargo de velador y oficial de suministros.", completion = "Excelente, &lt;nombre&gt;. Esta bolsa te resultará muy útil en el campo de batalla, &lt;clase&gt;. \n\n¡Aplaudo tu vigor y tu disposición para morir en nombre de la Horda!", rewards = "Recibirás:\n\nBolsa de cuero hecha a mano"}
MultiLanguageQuestData['mx'][792] = {title = "Familiares viles", objective = "Mata a 8 familiares viles.\n\nVuelve con Zureetha Vistalonga a las puertas de El Cubil.", description = "Estoy segura de que aprenderás mucho en el Valle de los Retos, joven <clase>.\n\nFui enviada al Valle para guiarte, pero aquí he descubierto una creciente corrupción...\n\nUn grupo que se llama a sí mismo el Filo Ardiente tiene un aquelarre aquí mismo, en el Valle de los Retos. Se esconden en una cueva al Noreste, y sus familiares viles se han esparcido desde la boca de la cueva sembrando el caos y la confusión.\n\nTe ofrezco tu primera tarea contra el Filo Ardiente: derrotar a esos familiares. Aniquila a tantos como puedas y, si sobrevives, vuelve a verme.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Hachuela primitivaGarrote primitivoHoja de mano primitivaCachava primitivaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][793] = {title = "Alianzas rotas", objective = "Usa el Signo de la Tierra para activar el Pilar de diamante, el de ópalo y el de amatista y así obtener las piedras rúnicas.\n\nColoca las piedras rúnicas en el Sello de la Tierra para liberar a Latigoscuro y a Hematus.\n\nMátalos y llévale a Gorn las ataduras de Latigoscuro, las cadenas de Hematus y el Signo de la Tierra.", description = "El Sello de la Tierra está controlado por tres piedras rúnicas, que se encuentran en el Pilar de diamante, el Pilar de ópalo y el Pilar de amatista en el Barranco Lethlor. Mediante el Signo de la Tierra, podrás deshacerte de las piedras rúnicas y desbloquear el Sello de la Tierra.\n\nAunque ándate con cuidado, <nombre>, los dragones negros Latigoscuro y Hematus son de armas tomar. Acaba con ellos y tráeme sus esclavas.\n\nPara llegar al barranco, dirígete hacia los confines orientales de las Tierras Inhóspitas. Y abre bien los ojos porque el barranco es tierra de multitud de dragones.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Coraza Viento abrasadorCamisote de escama prismáticaPeto forjado por la guerraPodrás elegir una de estas recompensas:\n\nMedallón de ráfaga mental\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][806] = {title = "Oscuras tormentas", objective = "Lleva la zarpa de Fizzle a Orgnil Escaralma a Cerrotajo.", description = "¡No podemos permitir que el Filo Ardiente se establezca en Durotar! ¡Debemos acabar con él antes de que extienda su maldad!\n\nYo conduje mi propia investigación y averigüé que un brujo del Filo Ardiente, un goblin llamado Fizzle Tormenta Oscura, ha acampado en el Monte del Trueno, al noroeste. Ahí es donde están propagando el caos él y sus esbirros.\n\nEncuentra a Fizzle y acaba con él. ¡Y tráeme una zarpa suya!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBotas de pellejo de tigre"}
MultiLanguageQuestData['mx'][808] = {title = "La calavera de Minshina", objective = "Recupera la calavera de Minshina del círculo de poder de las Islas del Eco.\n\nLlévasela al maestro Gadrin al Poblado Sen'jin.", description = "En mis sueños oigo la voz de mi hermano Minshina llamándome.\n\nSe lo llevó Zalazane, el brujo de las Islas del Eco que hay al este. Y ahora está muerto.\n\nPero la muerte no lo ha liberado. Zalazane utilizó su magia para atrapar el espíritu de Minshina en su propia calavera. En mi sueño, lo veo con otras calaveras, en un círculo de poder que está en la más grande de las Islas del Eco. Mientras siga allí, el alma de mi hermano estará maldita.\n\nTe lo ruego, <nombre>. Encuentra el círculo y recupera la calavera de Minshina. Luego tráemela.\n\n¡Libera a mi hermano!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCalavera con resplandor tenue"}
MultiLanguageQuestData['mx'][809] = {title = "Ak'Zeloth", objective = "Habla con Ak'Zeloth en Los Baldíos.", description = "Desde la última Gran Guerra, aquella en la que la Legión Ardiente fue derrotada, he buscado fuentes de corrupción demoníaca entre los orcos. El collar que me has traído confirma mis temores.\n\nPertenece al Filo Ardiente, un culto que adora un objeto de gran poder demoníaco. Se llama Semilla del Demonio y se encuentra en Los Baldíos, en la Cima Calígine. ¡Debe aniquilarla!\n\nVe a la Avanzada del Puente, hacia el oeste en la frontera de Los Baldíos y habla con mi ayudante, Ak'Zeloth. Él te guiará.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][812] = {title = "Se necesita un remedio", objective = "Encuentra a Kor'ghan en Orgrimmar y consigue el antídoto para venocola. Luego lleva el antídoto a Rhinag. Está cerca del límite noroeste de Durotar.", description = "<nombre>... llegas en el momento perfecto. Solo espero poder alabar tu velocidad también.\n\nTuve un descuido combatiendo con unos venocolas aquí cerca y uno de ellos me picó. Siento que su veneno me debilita por momentos. A este paso, calculo que me queda una hora de vida. Voy a necesitar tu ayuda...\n\nKor'ghan, de Orgrimmar, sabe cómo preparar el antídoto. Encuéntralo... y deprisa, <nombre>. No viviré mucho. Debería estar en el Circo de las Sombras.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Armadura de escórpido ligeraRodela de cargaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][813] = {title = "En busca del antídoto", objective = "Lleva 4 glándulas de veneno de venocola a Kor'ghan a Orgrimmar.", description = "Los venocolas son los escórpidos más mortíferos de Durotar. Rhinag no debería haber intentado cazar uno sin llevar el antídoto... pero ahora, lo último que necesita son mis reproches.\n\nTráeme unas cuantas glándulas de veneno de cualquiera de los ejemplares de venocola que encontrarás en la entrada de Orgrimmar y yo prepararé el antídoto.\n\nY date prisa, <nombre>. Uno de los nuestros necesita nuestra ayuda.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAntídoto Venocola"}
MultiLanguageQuestData['mx'][815] = {title = "Romper huevos", objective = "Lleva 3 huevos de colazote al cocinero Torka de Cerrotajo.", description = "¡Ay! Casi me olvido de que tengo que preparar el desayuno.\n\n<nombre>, muévete y tráeme unos huevos de colazote. Necesitaré por lo menos tres si quiero tener suficientes para la comida de mañana.\n\nLos colazotes Garrasangre son animales fieros y protegen sus huevos con la vida. A veces los entierran a gran profundidad y es difícil sacarlos sin correr peligro. Si te diriges a las Islas del Eco, al sureste del Poblado Sen'jin, encontrarás muchos.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nMendrugo de pan duroCecina dura"}
MultiLanguageQuestData['mx'][816] = {title = "Perdido, pero no olvidado", objective = "Lleva un indicio del destino de Kron a Misha Tor'kren, a la granja que hay al noroeste de Cerrotajo.", description = "<nombre>, por favor, ¿podrías ayudarme? Mi hijo Kron fue a cazar hace días y aún no ha regresado. Fue hacia el oeste, hacia Los Baldíos, a cazar crocoliscos en el Río Furia del Sur. Temo lo peor.\n\nEs muy fuerte pero su orgullo le mete siempre en líos. Yo le advertí de que los crocoliscos son fuertes y aviesos. Pero solo conseguí que se fuera enfadado.\n\nSi no puedes encontrarlo, al menos tráeme algún indicio de su suerte... aunque tengas que abrir el estómago de todos los crocoliscos de las orillas del Furia del Sur.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCapa cosida a mano"}
MultiLanguageQuestData['mx'][817] = {title = "Presa práctica", objective = "Lleva 4 pelajes de tigres de Durotar a Vel'rin Colmillo al Poblado Sen'jin.", description = "Muchos de los pelajes que usamos provienen de tigres de Durotar, <nombre>. Mantas, armaduras, tiendas... tenemos muchos motivos para cazar a esas bestias y muchos también para dejar que proliferen.\n\nPero ha llegado el momento de hacer una selección en la manada, por decirlo de algún modo. Nuestros números crecen y nuestras necesidades empiezan a superar nuestras reservas. Necesito más pelajes para preparar los bienes que nuestra gente necesita.\n\nTráeme 4 pelajes de tigres de Durotar. Te recompensaré. Puedes encontrarlos en las islas que hay al sur de aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][818] = {title = "Un espíritu responsable", objective = "Lleva 4 ojos de makrura intactos y 8 viales de moco de reptador al maestro Vornal al Poblado Sen'jin.", description = "Mis ojos empiezan a fallarme, pero aún veo con claridad. Y a menudo tengo que utilizar mis habilidades alquímicas para ayudarme en hechizos que antes me salían con facilidad. Pero me niego a adoptar un aprendiz. No he encontrado ningún trol ni orco merecedor de serlo.\n\n¿Tú crees valer lo suficiente? Sí, claro... Es evidente que lo crees.\n\nNecesito unas cosillas. ¿Crees que podrás conseguírmelas?\n\nNecesito ojos de makrura intactos y frascos de moco de reptador. Puedes conseguirlos de cualquier makrura o reptador de Durotar. Volveremos a hablar pronto.", progress = "El tiempo es quien realmente pondrá a prueba tu fuerza y tu voluntad. Si pierdes la paciencia o cedes a la debilidad, se revelará tu auténtica yo.", completion = "Bien hecho, joven. Bien hecho.", rewards = "Recibirás:\n\nPegamento muy pegajoso"}
MultiLanguageQuestData['mx'][819] = {title = "El barril vacío de Chen", objective = "Encuentra a alguien que sepa algo sobre el barril vacío de Chen.", description = "Un cartelito en uno de los extremos del barril reza,\n\n\"Chen Cerveza de Trueno-\n\nQue tu ánimo se levante y con tu copa siempre brindes.\"", progress = "¿Sí?", completion = "Bueno, me... \n\nEste barril era uno de los de Chen Cerveza de Trueno. Viajaba con Rexxar hace mucho tiempo. Hace siglos que no lo veo ni sé nada de él. Te agradezco que me hayas traído esto, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][821] = {title = "El barril vacío de Chen", objective = "Llévale 5 colmillos de león de la sabana, 5 riñones de zancudo de llanura y 1 cuerno de truenagarto al maestro cervecero Drohn en Trinquete.", description = "¿Te gustaría probar la cerveza a la que le dio nombre Chen? Ah, la Cerveza de Trueno es un poderoso brebaje. Chen le enseñó la receta a mi mentor y mi mentor, a su vez, me la transmitió. Necesitaré que me consigas unas cosas pero te lo aseguro: el subidón lo merece.\n\nTráeme 5 colmillos de leones de la sabana de cualquier león de la sabana, 5 riñones de zancudo de llanura de cualquier zancudo de llanura y un asta de truenagarto de cualquier especie de truenagarto. Eso debería irnos perfectamente.\n\nPuedes encontrar estos ingredientes por Los Baldíos.", progress = "¿Cómo va la búsqueda?", completion = "Jaja... Jamás creí que volvería a preparar esto.\n\nHas despertado una nostalgia muy profunda en mí, &lt;nombre&gt;. En cierto modo, me recuerda a la última vez que preparé un lote de cerveza trogg. Gracias. Los recuerdos llenan mi estómago de calidez.", rewards = "Recibirás:\n\nCerveza de Trueno"}
MultiLanguageQuestData['mx'][822] = {title = "El barril vacío de Chen", objective = "Llévale 5 glándulas relampagueantes, 1 glándula salivaria de halcón trueno y 1 hígado de kodo al maestro cervecero Drohn en Trinquete.", description = "Esa cerveza de trueno sí que es buena, ¿eh?\n\nTengo otra receta que me enseñó Chen. ¿Te interesa? No te quitará mucho tiempo, y puede serte útil si planeas continuar con tus aventuras.\n\nTráeme 5 glándulas relampagueantes de cualquier tormentero, 1 glándula salivaria de halcón trueno de los halcones trueno superiores y un hígado de kodo de cualquiera de los kodos de Los Baldíos.\n\nComo dije, es una bebida muy potente; es la cerveza trogg que te había mencionado.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBrebaje trogg"}
MultiLanguageQuestData['mx'][823] = {title = "Informa a Orgnil", objective = "Habla con Orgnil Escaralma de Cerrotajo.", description = "En el Poblado Sen'jin no nos faltan problemas, pero te agradecemos tu ayuda. Claro que las noticias que traes del Filo Ardiente podrían significar más problemas para todo el mundo.\n\nEn Cerrotajo hay un orco llamado Orgnil Escaralma que se encarga de librar Durotar de males como el que representa el Filo Ardiente. Busca a Orgnil y háblale de nuestra situación. Cuéntale también las noticias que traes del Valle de los Retos. Querrá saber esas cosas.\n\nCerrotajo se encuentra al norte.", progress = nil, completion = "¿Sí? ¿Tienes algún informe? ¡Pues adelante, informa!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][824] = {title = "Je'neu del Anillo de la Tierra", objective = "Llévale el globo de agua contaminada a Je'neu Sancrea en Cavernas de Brazanegra.\n\nObjeto provisto: \n", description = "El Anillo de la Tierra es un grupo de chamanes dedicados al estudio y la conservación de los elementos. Les sobra conocimiento sobre lunáticos dioses antiguos, ancestrales leyendas y tradiciones como nunca alcanzará la mayoría de los eruditos.\n\nEstás de suerte, conozco a alguien del Anillo de la Tierra aquí en Vallefresno. Dirígete a la Avanzada de Zoram'gar, en la costa de La Ensenada de Zoram, y enséñale a Je'neu Sancrea lo que has encontrado. Si alguien es capaz de interpretar el significado del globo, es él.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Cinturón de equilibristaEscudo lodo acumuladoManteo de sauce suaveRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][825] = {title = "Los restos del naufragio...", objective = "Gar'Thok de Cerrotajo quiere que recuperes 3 herramientas gnómicas de los restos de naufragio de la costa.", description = "Uno de mis mejores exploradores me ha informado de que los restos de la flota naufragada de Valiente aún están en la costa de Durotar, al este del Fuerte de Tiragarde.\n\nNo es un secreto que los humanos, aliados con esas mínimas criaturas llamadas gnomos, han desarrollado sus conocimientos de mecánica. Debemos estudiar a fondo a todos nuestros enemigos potenciales. Y nosotros también nos beneficiaremos de sus conocimientos.\n\nNada entre los restos del naufragio, <nombre> y recupera las herramientas de la Alianza.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guardamuñecas CorrearenasFaja ancha metálicaBotas llenas de barroRecibirás:\n\n"}
MultiLanguageQuestData['mx'][826] = {title = "Zalazane", objective = "Derrota a Zalazane.\n\nMata a 8 trols vudú y 8 trols maléficos.\n\nLleva la cabeza de Zalazane a Gadrin.", description = "Zalazane, el curandero brujo, vive en las Islas del Eco, hacia el este. En otro tiempo, esas islas eran nuestro hogar.\n\nDesde ellas, Zalazane envía a sus trols a la península, a maldecir a nuestra gente y a esclavizarnos bajo su dominio.\n\nHay que detenerle.\n\nDerrota a Zalazane y a sus esbirros, antiguos trols Lanza Negra que hemos dado por perdidos. Tráeme su cabeza. Así sabré que su demoníaco reinado ha llegado a su fin.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Mandiletes veladosBotas de peso ligeroRecibirás:\n\n"}
MultiLanguageQuestData['mx'][827] = {title = "Roca del Cráneo", objective = "Recoge los collares abrasadores de los cultores de Roca del Cráneo. \n\nLlévaselos a Margoz a su campamento.", description = "<nombre>, el Filo Ardiente ha infestado la cueva que hay al este de Orgrimmar, Roca del Cráneo. En esa cueva celebran sus inmundos rituales y queman su propia carne con collares abrasadores.\n\nCreo que usando esos collares, los cultores entran en sintonía con los poderes demoníacos. Pero para confirmarlo, necesito estudiar esos collares.\n\nVe a Roca del Cráneo y recoge los collares abrasadores que lleven los cultores. Tráemelos y yo descubriré su secreto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Espada bastarda firmeDaga dentadaMaza hirienteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][828] = {title = "Margoz", objective = "Habla con Margoz.", description = "Uno de nuestros chamanes, Margoz, sabe más sobre la corrupción del Filo Ardiente. Habla de una cueva de las montañas llamada Roca del Cráneo... ¡justo a las afueras de Orgrimmar! Esa cueva proporciona refugio a una banda de adeptos del Filo Ardiente.\n\nAntes de ir a Roca del Cráneo, habla con Margoz. Es sabio y su consejo es valioso.\n\nEstá acampado hacia el noreste, entre la costa y el Barranco Árido.\n\nSigue su consejo pero, diga lo que diga Margoz, <nombre>, ¡aún quiero que aplastes a esos adeptos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][829] = {title = "Neeru Hojafuego", objective = "Lleva un collar de muestra a Neeru Hojafuego a Orgrimmar.", description = "Los collares abrasadores que me trajiste son potentes instrumentos demoníacos. Pero me temo que discernir su origen está más allá de mis habilidades chamánicas. Necesitamos que los estudie un brujo.\n\nLleva un collar abrasador a Neeru Hojafuego. Es un brujo muy capacitado que dice que utiliza sus poderes contra los demonios. Asegura que sus investigaciones de lo oculto son beneficiosas. Sea esto cierto o no, creo que necesitaremos su ayuda para luchar contra el culto demoníaco de Durotar.\n\nEncontrarás a Neeru en Orgrimmar, en el Circo de las Sombras.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][830] = {title = "Las órdenes del almirante", objective = "Lleva las órdenes del almirante Valiente a Gar'Thok a Cerrotajo.", description = "Abres el viejo y desgastado sobre y descubres un documento que parece oficial. Reconoces el sello del almirante Valiente.\n\nParece importante. Gar'Thok, el Comandante de Cerrotajo, podría estar interesado en esta información.", progress = "Pareces preocupado, <clase>. ¿Qué tienes ahí?", completion = "Esto no presagia nada bueno. Ha sido muy inteligente llamar mi atención sobre esta información.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][831] = {title = "Las órdenes del almirante", objective = "Entrega las órdenes del almirante Valiente a Vol'jin a la cámara de Thrall en Orgrimmar.", description = "No se puede confiar en los humanos. Luchamos junto a ellos con recelo, sabiendo que algún día nos traicionarían.\n\nLa muerte del almirante Valiente no bastó para eliminar su legado de traición; la escoria humana había preparado sus planes mucho antes de que él muriera.\n\nNi siquiera la muerte de Benedict acabará con esto; quién sabe cuándo llegará la próxima horda de hombres de Valiente.\n\nHay que llevar esta órdenes a Vol'jin a Orgrimmar de inmediato. Lo encontrarás en la cámara de Thrall.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][832] = {title = "Sombras Ardientes", objective = "Lleva este ojo a Neeru Hojafuego que está en Orgrimmar.", description = "<Del colgante emanan unas palabras que se introducen en tu mente.>\n\n¿Gazz'uz?\n\nGazz'uz... ¡informa!\n\nHay noticias sobre tu descubrimiento en la Roca del Cráneo. ¡Debes prepararte para un ataque!\n\n¡Gazz'uz! ¡Te ordeno que hables! Habla. O me aseguraré de que llegue a Neeru Hojafuego la noticia de tu presencia y dejaré que descargue sobre ti su brutalidad.\n\nY no creo que quieras medirte con Neeru...\n\n¿Gazz'uz? ¿Estás ahí...?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][833] = {title = "Cementerio sagrado", objective = "Mata a 8 intrusos Erizapúas en Roca Roja.", description = "Solo los tauren más valientes reposan en Roca Roja, nuestro cementerio sagrado. Es un honor que concedemos a los valientes guerreros que fundaron y defendieron Cima del Trueno y a aquellos que han entregado la vida por el bien de sus tribus y sus jefes.\n\nPero una vil amenaza se cierne sobre nuestra tierra sagrada. Una banda de Erizapúas está arrasando el cementerio; yo ya estoy mayor para enfrentarme a ellos.\n\nHay que emplear la fuerza, <nombre>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Zapatillas de lutoCordón de memoria trágicaPrimera coraza de CairneRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][834] = {title = "Las arpías Viento Seco", objective = "Recupera 5 sacos de suministros.", description = "Soy Rezlak, uno de los chicos de Gazlowe. El jefe me manda a ayudar a los orcos de Durotar. Las cosas han ido bien... excepto para las caravanas. ¡No consigo mantenerlas al seguro! Eso hace mi trabajo un poco más difícil, ¿sabes?\n\nEl último envío –que, dicho sea de paso, prometieron que llegaría– fue robado por arpías Viento Seco de... ¿de dónde era que eran? ¿El Cañón del Ventajo?\n\n¡Necesito conseguir esos suministros! Sigue el cañón hacia el sur. Encontrarás una brecha en las paredes este y oeste.", progress = "Hago muy bien mi trabajo, no te confundas, ¡pero esto es ridículo! ¡¿Qué se supone que tengo que hacer si no tengo con qué trabajar?!", completion = "¡Vaya, justo lo que necesitaba! Nos has traído nuestros suministros. Es genial. Así podré volver al trabajo, en cuanto encuentre a alguien que cargue con estos sacos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][835] = {title = "Asegurar las rutas", objective = "Mata a 12 arpías de Durotar. No importa el tipo de arpía.", description = "Gazlowe me dijo una vez, \"Rezlak. En la vida hay que saber una cosa: que si quieres algo bien hecho, tienes que hacerlo tú mismo.\"\n\nPues bien, como no me puedo permitir perder todas las caravanas, voy a tomar las riendas del asunto. Las arpías tienen invadidas nuestras rutas de suministros. Si matamos a todas las arpías, las rutas serán más seguras.\n\nY claro, Gazlowe me enseñó algo más: \"Todo tiene un precio.\" Así que, ¿cuento contigo, <nombre>? Bien... Te recomiendo que empieces por el cañón del este.", progress = nil, completion = "Creo que ya puedo respirar tranquilo, sabiendo que las arpías no volverán a atacar a nuestras caravanas de suministros. Y justo a tiempo, además. ¡Porque en el siguiente envío me van a llegar algunos juguetitos! \n\nSe te da bien lo que haces, &lt;nombre&gt;, deberías buscar a mi jefe en Trinquete. Seguro que él podrá darte más trabajo. \n\nAh, y no te preocupes, no me he olvidado de pagarte por el favor que me has hecho.", rewards = "Arco corto de nogalCortaalas de arpíaBastón de madera manchadoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][836] = {title = "¡Rescata a OOX-09/TI!", objective = "Escolta a OOX-09/TI para que llegue sano y salvo e informa a Oglethorpe Obnoticus en Bahía del Botín.", description = "Vuelves a oír la voz del gnomo que sale del robot:\n\n\"Tengo que llevar a OOX-09/TI a un lugar abierto y seguro en el que pueda iniciar el largo proceso de despegue. Tiene un dispositivo de invisibilidad integrado, pero necesito tiempo para que vuelva a estar operativo. ¡Escolta al robot hasta, digamos, algunas rocas donde no sea visible! Allí podré tomarme mi tiempo para hacer que todo vuelva a funcionar correctamente.\"\n\n\"¡Escóltalo para que llegue sano y salvo y después ven a verme a Bahía del Botín! Oglethorpe Obnoticus. ¡Corto y cierro!\"", progress = nil, completion = "¡Ah, tú rescataste a OOX-09/TI! ¡No tengo palabras para expresar mi gratitud! Aún tengo que perfeccionarlo, ¡pero me has ahorrado muchas monedas de oro e incontables horas de trabajo! \n\nTe ruego que aceptes uno de estos objetos en recompensa. Mis robots y yo te estamos muy agradecidos, &lt;nombre&gt;.", rewards = "Botas de inventor gnómicoAparato de hundimiento gnómicoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][837] = {title = "Invasión", objective = "Mata a 4 jabaespines Crines de Acero, 4 exploradores Crines de Acero, 4 polvorosos Crines de Acero y 4 guardias de batalla Crines de Acero para Gar'Thok, de Cerrotajo.", description = "Cuando llegamos, los jabaespines Crines de Acero poseían gran parte de la tierra... era una espinita que teníamos clavada. Con mucho esfuerzo hemos expulsado a la mayoría, pero aún quedan algunos bien fortificados en algunas zonas.\n\nPero esto ha durado ya demasiado. Por nuestro propio bien, no podemos permitir que haya Crines de Acero en nuestras tierras. Sus campamentos están al oeste de aquí. Busca las zarzas y los encontrarás. Hoy los echaremos de Durotar y mañana... puede que hasta de Kalimdor.", progress = nil, completion = "Haré correr la voz de que los jabaespines ya no están en sus guaridas y de que se puede prender fuego a sus estructuras. Erradicar a los Crines de Acero de Durotar es un gran paso para mejorar la seguridad de las fronteras de nuestro nuevo hogar.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][840] = {title = "Nuevo recluta de la Horda", objective = "Entrega tu carta de reclutamiento a Kargal Marca de Guerra, en la Avanzada de Los Baldíos.", description = "Mmm, pareces fuerte.\n\nEscucha, mi buen amigo Kargal necesita nuevos reclutas para una misión en Los Baldíos. Sé que quieres servir bien a la Horda. Pues esta es tu oportunidad.\n\nLleva esta carta de reclutamiento a Kargal, a ver si la firma.", progress = "¿Qué quieres, cachorrito? Si no estás aquí para alistarte, no tengo tiempo para ti.", completion = "¿Así que te manda Takrin?\n\n&lt;Kargal lee tu carta de reclutamiento con cansancio y se la guarda sin ceremonias.&gt;\n\nLa firmaré cuando te la hayas ganado. Me están llegando informes desde el sur que dicen que todo este continente se está partiendo en dos. Mientras tanto, las caravanas de suministros no pasan del río y están atacando todas nuestras avanzadas de aquí a Sierra Espolón. ¿Quieres demostrar tu valía a la Horda? Empieza por demostrarla aquí.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][841] = {title = "¿Otra fuente de alimentación?", objective = "Llévale 10 faltriquera de agua de Vagayermos al ingeniero jefe Pasaquillas, que está en Gadgetzan, para conseguir otra fuente de alimentación.", description = "Déjame adivinar... no has conseguido a tiempo lo que fuera que debías conseguir. No, mejor aún... ¡se te cayó en la arena! Bueno, sea lo que sea que ha pasado, tengo más fuentes de energía que puedo venderte. Sin embargo, esta vez te costarán diez, ¡SÍ, DIEZ faltriqueras de agua de Vagayermos cada una!\n\nCorren tiempos difíciles, <nombre>, y las fuentes de energía no crecen en los árboles. Mmm, ¿y qué si lo hicieran? Quizás podríamos HACER un árbol de fuentes de energía...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFuente de alimentación modelo 4711-FTZ"}
MultiLanguageQuestData['mx'][842] = {title = "Servicio militar en El Cruce", objective = "Entrega tu carta de reclutamiento firmada a Sergra Espinoscura, que está en El Cruce. Si todavía no lo has hecho, puedes pedirle a Halga Ojosangre que te lleven con la siguiente caravana.", description = "<Kargal extrae una ajada carta de reclutamiento de su bolsillo y la firma. Te la entrega con solemnidad.>\n\nBueno, <chico/chica>, has demostrado ser un fichaje formidable. Considérate <reclutado/reclutada>. Necesitamos a gente como tú en El Cruce, si puedes llegar con vida. Sigue el camino que va hacia el oeste desde aquí, y luego al sur en el cruce de caminos. Si de verdad quieres ayudar a tu nueva Horda, habla con Halga para que te lleven con la siguiente caravana. Cuando llegues, dale esta carta a Sergra Espinoscura.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][843] = {title = "La reclamación de Gann", objective = "Gann Picopiedra quiere que mates a 15 excavadores de Bael'dun y a 5 supervisores de Bael'dun.\n\nLlévale el diario de Khazgorm a Gann Picopiedra.", description = "Solitario, errante voy por estas carreteras.\n\nLos enanos de Bael Modan no muestran el menor respeto por mi tierra. Unas tremendas explosiones provocan enormes socavones en el suelo mientras sus máquinas destrozan las colinas. Esos destructivos enanos han cribado las tierras que otrora fueron nuestro hogar y de las que se alimentaba mi tribu.\n\nTodo intento de solución diplomática ha fracasado. Ha llegado la hora de una acción decisiva.\n\nExpulsa a la fuerza a los enanos de la excavación de Bael Modan y tráeme el diario de su jefe, el prospector Khazgorm.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][844] = {title = "La amenaza de los zancudos de llanura", objective = "Reúne 7 picos de zancudos de llanura.", description = "¿Conoces a los zancudos de llanura? Animales inútiles. No pueden volar. Se dejan cazar. Tienen cerebros del tamaño de mis nudillos. No tienen la sensatez de apartarse del camino de un carro. Rompí muchos ejes por culpa de sus cráneos... A veces pienso que los jabaespines espantan bandadas de zancudos hacia nuestras caravanas a propósito antes de una emboscada. \n\nHaz que me sienta orgullosa, <clase>. Abre paso para que despejen los caminos y tráeme sus picos como prueba.", progress = "¿Conseguiste los picos de los zancudos de llanura?", completion = "Muy bien, &lt;nombre&gt;. Una cosa menos de la que preocuparse en el camino.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][845] = {title = "La zhebra", objective = "Mata a galopadores zhebras para reunir 4 pezuñas de zhebras.", description = "Si quieres servir a mi amada Horda, <novato/novata>, vas a tener que demostrarme tu fuerza. Puedes entrenarte cazando zhebras. Puede que no sean las bestias más fuertes de Los Baldíos, pero evita sus coces o te arrepentirás.\n\nCaza las zhebras que hay al norte y al sur y recoge sus pezuñas. Tráemelas y a lo mejor te mandamos a por algo más difícil.", progress = "¿Cuántas zhebras has matado?", completion = "No está mal, &lt;nombre&gt;. Esas zhebras tienen unas patas muy fuertes. ¡Una coz bien dada puede derribar hasta a un tauren!\n\nPor lo visto, tú también eres fuerte.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][846] = {title = "La venganza de Gann", objective = "Gann Picopiedra quiere que le traigas 6 viales de nitroglicerina, 6 fajos de pulpa de madera y 6 muestras de nitrato sódico.", description = "Es evidente que el prospector dependía de los explosivos y de esos ruidosos vehículos para destrozar el suelo. Cabe esperar que pronto llegará otro Capataz para sustituirlo.\n\nQuiero darles a los enanos un poco de su propia medicina. Según estos planos, si combinamos nitroglicerina con pasta de madera y nitrato sódico, podemos crear una carga explosiva. Es bien sabido que el fusilero, los soldados y los oficiales tienen los suministros.\n\nReúne estos objetos y tráemelos. ¡Voy a preparar una carga que los enanos no olvidarán!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][848] = {title = "Esporas de hongos", objective = "Reúne 5 esporas de hongos de los hongos de Las Charcas del Olvido.", description = "Los oasis de Los Baldíos ocultan un misterio. La energía de la vida fluye por sus aguas, revitalizando a las plantas y a los animales que las beben.\n\nRevitalizando... y alterando.\n\nCerca de las Charcas del Olvido, al noroeste, crece un tipo de champiñón. Sus esporas tienen unas propiedades que nosotros, los boticarios de Lordaeron, encontramos útiles.\n\nTráeme esas esporas y te ganarás nuestra gratitud.", progress = "¿Tienes las esporas, <nombre>? Debo enviarle una poción a mi asociado en Cima del Trueno, y para eso necesito las esporas...", completion = "Ah, sí. Son buenos ejemplares. Potentes. \n\nSoy un Renegado y siempre cumplimos nuestros contratos. Aquí tienes tu recompensa, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][850] = {title = "Los jefes Kolkar", objective = "Asesina a Barak Aterrakodos y hazte con su cabeza.", description = "Los centauros han acosado a los tauren durante años. Y recientemente, los centauros Kolkar de Los Baldíos se han convertido en una auténtica amenaza. No solían estar organizados pero han surgido nuevos jefes entre ellos. Y se han unido.\n\nPara mantener nuestras propiedades, hay que acabar con los jefes de los centauros.\n\nTráeme la cabeza de Barak Aterrakodos. Su campamento está al oeste de Las Charcas del Olvido.\n\nDerrótalo y vuelve aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de hilo enredadoCinturón de la poza olvidadaBotas de AltazancaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][851] = {title = "Verog el Derviche", objective = "Mata a Wyneth para atraer a Verog el Derviche, después asesínalo y hazte con su cabeza.", description = "Quizás Verog sea difícil de encontrar, pero a juzgar por la información que has reunido, su compañera Wyneth está siempre en la tienda de mando, justo al oeste de aquí. Si la matamos, Verog saldrá al galope.\n\nRegthar nos envió para observar, pero también dijo que deberíamos aprovechar cualquier oportunidad que surja para desestabilizar la estructura de mando de los centauros. ¡Saca a Verog de su escondite y mátalo!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Toga de vergüenzaBrazales asesinosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][852] = {title = "Hezrul Marcasangre", objective = "Asesina a Hezrul Marcasangre y recoge su cabeza.", description = "Hezrul Marcasangre es el jefe de los centauros Kolkar en Los Baldíos. Es feroz, brutal y taimado. Si lo derrotas, sería un golpe contundente para los Kolkar y la amenaza que suponen se vería reducida en gran medida.\n\nAsí que mátalo. Tráeme su cabeza y la colgaré de un poste para que conozcan el miedo.\n\nHezrul dirige a los suyos desde el Oasis Aguaverde, hacia el sur.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Capa AguaverdeGuantes de ira no dirigidaCinturón fracturadoRecibirás:\n\nAnillo de cazarrecompensas"}
MultiLanguageQuestData['mx'][853] = {title = "Apothecary Zamah", objective = "Llévale las esporas devueltas a la boticaria Zamah en Cima del Trueno antes de que se agote el límite de tiempo.", description = "He convertido las esporas que me diste en una emulsión. Debo enviársela a mi socia, la boticaria Zamah. Si se la llevas, seguro que tendrá algo para ti de nuestro fondo de productos alquímicos.\n\nSe encuentra en las Pozas de las Visiones, una caverna en el subsuelo de los chamanes de Cima del Trueno. El camino hacia esta caverna está muy bien escondido pero la encontrarás en el risco del Alto de los Espíritus.\n\nApúrate. Esta emulsión solo conservará su efectividad por poco tiempo y se debe procesar y volver a sellar antes de que eso ocurra.", progress = "¿Traes algo del boticario Helbrim?", completion = "Ah, las esporas de Los Baldíos que Helbrim andaba recolectando. ¿Te pidió ayuda para entregarlas? Bien. \n\nY la emulsión aún tiene fuerza, así que no has debido de perder el tiempo en la entrega. Muy bien, &lt;clase&gt;.", rewards = "Podrás elegir una de estas recompensas:\n\nElixir de entereza menorElixir de agilidad menorPoción de Rejuvenecimiento menorPoción de presteza\n\nTambién recibirás:\n\nCucharón de caldera"}
MultiLanguageQuestData['mx'][854] = {title = "Viaja a El Cruce", objective = "Habla con Thork en El Cruce, en Los Baldíos.", description = "Había vaticinado tu llegada, joven <clase>. Aunque quizás ya no seas tan joven.\n\nHa llegado el momento de que te internes más en estas tierras. Tu destino es conseguir grandes cosas.\n\nTienes que ir a El Cruce; nuestra vida está ligada a la de los orcos y necesitan ayuda. Sigue este camino hacia el este y después hacia el norte hasta El Cruce. Habla con Thork, que tiene la bendición de la Madre Tierra.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][855] = {title = "Los brazales centauro", objective = "Llévale 10 brazales centauro de maleantes y videntormentos Kolkar.", description = "El liderazgo de los centauros depende de un núcleo de guerreros leales y disciplinados que mantengan a raya a los demás. Si diezmamos sus filas, los Kolkar no tendrán fuerzas para contener su ira. De modo que tengo una misión para ti.\n\nMata maleantes y videntormentos Kolkar alrededor del Oasis Aguaverde, al sur, y coge sus brazales. Vuelve cuando tengas unos cuantos y la Horda te recompensará bien.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Cinturón de maleanteBrazales imprudentesRecibirás:\n\n"}
MultiLanguageQuestData['mx'][857] = {title = "La Lágrima de las Lunas", objective = "Feegly el Exiliado quiere que le consigas la Lágrima de las Lunas.", description = "¡Yo tenía el poder de la energía! ¡La tenía en mis propias manos! ¡Y quiero recuperarla! ¡Cuanto antes!\n\nEsos canallas excavadores la descubrieron... era tal su hermosura. Se consideraba la Lágrima de las Lunas, fue el primer gran descubrimiento que hicimos en Bael Modan.\n\n¡Tenía que ser mía! ¡Mía y solo mía!\n\nAl general Trenzado lo carcomían los celos del poder que me daba. Así que la encerró en el castillo. ¡Se atrevió a decir que estaba maldita! ¡Ignorante!\n\n¡Otros la codiciaban y había que detenerlos! Ese malnacido de Trenzado me apartó.\n\nAhora quiero recuperarla. ¡Cuanto antes!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][858] = {title = "La llave de contacto", objective = "Consigue la llave de contacto del Supervisor Palarrastre.", description = "¿No te mandará Petardol? Estoy en un apuro. Me metí sin darme cuenta de que necesitaba una llave para desbloquear la columna que mueve la trituradora. Uno de los operarios de la trituradora me preguntó si todo iba bien ¡y me entró el pánico! En lugar de decirle que me faltaba la llave, le dije que había algún tipo de problema mecánico.\n\nTenemos que salir de aquí ¡a paso ligero! Busca en la parte de arriba de la grúa, el Supervisor Palarrastre debería tener una llave para esta trituradora.\n\n¡Ayúdame!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][860] = {title = "Sergra Espinoscura", objective = "Habla con Sergra Espinoscura en El Cruce.", description = "Si deseas practicar la caza debes dirigirte a Los Baldíos. Las bestias que allí habitan son tozudas y fuertes. Si cazas allí aprenderás mucho y tu espíritu crecerá.\n\nHabla con Sergra Espinoscura pues ella será tu primera guía en Los Baldíos.\n\nSergra está en El Cruce. Para llegar hasta allí, viaja hacia el este desde el Poblado Pezuña de Sangre hasta Los Baldíos y después dirígete hacia el norte cuando el camino se bifurque. Y ten mucho cuidado por el camino pues Los Baldíos pueden ser muy peligrosos para los incautos y confiados.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][861] = {title = "Los hábitos del cazador", objective = "Reúne 4 garras de merodeador de las estepas.", description = "Te veo con ganas de explorar. Yo también era así antes...\n\nMe gustaba explorar y cazar. Salir a cazar es un gran honor para los tauren.\n\nSi de verdad quieres dedicarte al arte de la caza, demuéstrame tu habilidad y determinación. Tráeme las garras de los merodeadores de las estepas de Mulgore. Son peligrosos y astutos... digna presa de <un/una> joven <clase> que sigue el camino de la caza.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][862] = {title = "Estofado de ratas de madriguera", objective = "Llévale 8 ratas de madriguera a Larva al este de El Cruce.", description = "<Un/Una> <clase> debe de pasar hambre por Los Baldíos. Al menos yo, me muero de hambre.\n\n¿Sabes qué? Voy a preparar un rico estofado. Solo necesito unas ratas de madriguera.\n\nAl parecer, a esos condenados enanos de Bael Modan les sobra lo mejor de lo mejor. Dirígete hacia el sur a Bael Modan y tráeme unas ratas de excavación.\n\nNo eres digno de llamarte aventurero curtido ¡hasta que has pasado un tiempo matando ratas! ¡Andando!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nEstofado de ratas de madrigueraGuantes de boticarioReceta: estofado de ratas de madriguera"}
MultiLanguageQuestData['mx'][863] = {title = "La fuga", objective = "Protege a Rabiaire y la trituradora goblin robada hasta que salgan de El Fangal.", description = "Supongo que aprenderé sobre la marcha... No puede ser muy difícil. Unos botones por aquí, una palanca o dos... Bueno, ¿<listo/lista>?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Pistola de PetardolBrazales de farfulleo enfadadoLeotardos de OllaboquillaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][864] = {title = "Regresa junto a la boticaria Zinge", objective = "Llévale el equipo de prueba de campo sellado a la boticaria Zinge, que está en Entrañas.", description = "\"Aquí tienes, la fuente de poder se ha quitado con seguridad y la información se ha mantenido intacta. Bueno, lo de viajes seguros y todo eso. Espero que este nefasto experimento científico haya funcionado para ti y todo eso.\"\n\nEl goblin se aleja para atender sus labores con la Compañía de Aguas de Gadgetzan. Cierras bien el paquete, en preparación de tu viaje a Entrañas. La boticaria Zinge te espera allí para probar el objeto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes aptos para la cargaManteo de maestro boticarioSobrehombros de piel de conocimientoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][865] = {title = "El secreto está en el cuerno", objective = "Consigue el cuerno del rey Zarpagarra.", description = "Los raptores de Los Baldíos son más inteligentes que los de cualquier otro sitio, y creo que se debe precisamente a sus cuernos. Si es así, quizás podría moler algunos para fabricar \"bebidas de inteligencia\". ¡Podría amasar fortunas!\n\nAhí entras tú: quiero el cuerno del raptor más listo que hay. \"El rey Zarpagarra\" lidera toda una manada de raptores inteligentes en las colinas al norte de Trinquete. ¡Tráeme su cuerno! ¡Y no dejes que te arranquen la piel a tiras como a todo el mundo!", progress = "¿Conseguiste los cuernos, <nombre>? ¡Ganaré una fortuna con esas cosas!", completion = "¡Genial, los conseguiste! Ahora solo tengo que molerlos y mezclarlos con un poco de vino, y...", rewards = "Atizador afiladoZapatos inteligentesBallesta arteraRecibirás:\n\nPonche de raptorCapa de posadero"}
MultiLanguageQuestData['mx'][866] = {title = "Recoge muestras de raíces", objective = "Llévale 8 muestras de raíces de hierbas de los alrededores de Los Baldíos del Norte.", description = "Las hierbas de Los Baldíos no son como las de otras regiones. Sus propiedades son casi idénticas pero el agua de oasis las altera por lo que hay diferencias apenas perceptibles.\n\nDeseo estudiar esas diferencias... ¡para ver si se les puede sacar partido!\n\nSi eres un entendido en herboristería, recolecta muestras de raíces de las hierbas que encuentres en Los Baldíos. Tráeme esas muestras para que las pueda comparar con las de otras regiones.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGuerrera cubierta de esporas"}
MultiLanguageQuestData['mx'][867] = {title = "Arpías saqueadoras", objective = "Reúne 6 garras de Alabruja de arpías Alabruja.", description = "Ya que estás aquí, <clase>, quizás puedas ayudarme con un pequeño problema. Las malditas arpías han estado saqueando los suministros de nuestras caravanas demasiado tiempo. Es hora de rebanarles la garganta y acabar con unas cuantas.\n\nEl ataque más devastador acabará con una buena parte de su cadena inferior de mando y entonces podemos seguir hacia arriba.\n\nVe a por las arpías Alabruja de cualquier tipo hacia el noroeste y tráeme 6 garras de Alabruja. No debería estar mal para empezar...", progress = "¿Ya cercenaste suficientes? Sigue cortando y acumulando trofeos. Quiero 8 garras de alabruja.", completion = "Oh, estas se ven bien. Muy bien... Buen trabajo, &lt;nombre&gt;. Espero ver más de tu trabajo en el futuro.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][868] = {title = "¡A cazar huevos!", objective = "Llévale 12 huevos de silítido y la garra de excavación a Korran en El Cruce.", description = "Hola, <nombre>. Mis maestros de Orgrimmar me han enviado a El Cruce para patrullar por estas tierras e informar de los acontecimientos.\n\nUno de los objetos de mis pesquisas son esos insectoides que se encuentran al sur de la Tierra de Gigantes. No sabemos mucho de estas criaturas, así que me he propuesto averiguar más. Parecen tener inteligencia, una inteligencia superior a la de los animales corrientes.\n\nToma esta garra de excavación y recolecta unos huevos de sus montículos, pero ándate con ojo: si se dan cuenta, te atacarán.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Armadura de escamas violetaTogas de arlequínRecibirás:\n\n"}
MultiLanguageQuestData['mx'][869] = {title = "El rastro del ladrón", objective = "Las huellas llevan al lado este de Colina Espinosa. Síguelas para ver si encuentras algo.", description = "Hay huellas de animales por todo el lugar, huellas de garras enormes y curvadas. Parecen huellas de raptor.\n\nTu primera idea es que los jinetes raptor asaltaron la caravana, pero las huellas no son profundas y no hay ninguna pisada que no sea animal.\n\nLas huellas se dirigen al noreste de aquí, hacia el este de Colina Espinosa. La respuesta a este misterio debe estar bajo su sombra.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][870] = {title = "Las Charcas del Olvido", objective = "Busca en Las Charcas del Olvido, al noroeste de El Cruce.", description = "¿Has sentido el temblor, <clase>? Algo ha partido estas tierras en dos. Pero los druidas también percibimos temblores de otros tipos.\n\nHay vida en tierras que antes estaban secas y muertas. La vida vuelve a despertar en los oasis alrededor de El Cruce. Puedo sentir que se está filtrando una energía hacia la superficie, ¿pero de dónde? ¿Tiene algo que ver con el desastre que ha destrozado Los Baldíos?\n\nDebemos encontrar la fuente. Dirígete a Las Charcas del Olvido, al noroeste de El Cruce. Busca en sus aguas una fuente de energía y entonces vuelve aquí.", progress = nil, completion = "¿Encontraste una grieta en la tierra? ¿Y había gases que salían de allí? Qué extraño. Puede que sea una respuesta a nuestras preguntas, pero aún no podemos estar seguros.\n\nLo que es seguro es que es una pista. Y te agradezco por haberla encontrado.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][871] = {title = "Defender la Avanzada del Puente", objective = "Mata a 8 desvalijadores y a 3 cazadores de la tribu Crines de Acero.", description = "Todos los jabaespines son nuestros enemigos, <nombre>. Es solo que unos son aún más molestos que otros.\n\nLa tribu de los Crines de Acero ha estado atacando nuestras líneas de suministros procedentes de Orgrimmar. Tengo a exploradores buscando al jefe de estos asaltos pero hasta que lo logren, cualquier baja que podamos infligirles a esos malditos hombres jabalí nos vendrá bien.\n\nEmpieza por el sur, en los lugares donde atacaron nuestros campamentos cerca del río. Búscalos y ejecútalos.", progress = nil, completion = "Lo has hecho muy bien, &lt;nombre&gt;. Esos insolentes jabaespines al fin aprenderán que el poder de la Horda no se debe ignorar.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][872] = {title = "La ofensiva de Avanzada del Puente", objective = "Mata a 5 defensores Crines de Acero, a 5 tejespinas Crines de Acero y a Kreenig Gruñucico. Consigue el colmillo de Gruñucico.", description = "¿Hombres jabalí sueltos por la frontera con Durotar? ¡No lo permitiré! Ya sabes lo que dicen, <nombre>: la mejor defensa es acabar con todo lo que se interponga en tu camino.\n\nUno de mis exploradores siguió a los jabaespines tras su último ataque contra una de nuestras caravanas, así que ya sabemos dónde atacar. Kreenig Gruñucico es el responsable de los ataques a lo largo del río. Machácalo, <clase>. Derrótalo y dispersa sus fuerzas para que cesen los ataques contra nuestro campamento.\n\nBusca una cueva llena de jabaespines por el río, justo al sur de nuestros establos.", progress = "Córtale la cabeza al jefe y el caos se instaurará, <nombre>. Aprende bien esta lección. Te será útil en el futuro.", completion = "Muy bien, &lt;nombre&gt;. Sin Kreenig al frente de los saqueadores, mis hombres podrán defender la Avanzada del Puente. \n\nTu pueblo debería estar orgulloso de tu lealtad.", rewards = "Leotardos ErizapúasCinturón del hombre cerdoCoraza de KargalRecibirás:\n\n"}
MultiLanguageQuestData['mx'][873] = {title = "Isha Awak", objective = "Llévale el corazón de Isha Awak a Mahren Vidente del Cielo.", description = "El gran Isha Awak es dueño y señor de estas aguas. Grande es su fuerza y solemne su orgullo. Los humanos de la costa lo temen, porque les ha infligido muchas bajas.\n\nPero no lo temo. Incluso doy las gracias por su presencia. Es un desafío digno y una presa honorable.\n\nSi estás <listo/lista>, nada mar adentro en busca de Isha Awak, la Condena Abisal.\n\nSu ánimo mora en su corazón y oírlo latir es conocer tu sino.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Vara para marcarEscudo del ValleRecibirás:\n\nFaja de maestro de bestias"}
MultiLanguageQuestData['mx'][874] = {title = "Mahren Vidente del Cielo", objective = "Habla con Mahren Vidente del Cielo.", description = "Has cazado las fieras de Los Baldíos. Eso demuestra fortaleza de espíritu. Pero <un cazador/una cazadora> siempre debe estar <preparado/preparada>. En cualquier terreno, <un auténtico cazador/una auténtica cazadora>, puede seguirle la pista a una presa. No se detendrá ante montañas ni ciénagas.\n\nNi siquiera ante el mar.\n\nEncuentra a mi hermana, Mahren. Se dedica a cazar a los grandes monstruos marinos de la costa. Te enseñará todo lo que hay que saber sobre ellos.\n\nPero ándate con cuidado cuando la busques, ya que la costa de Los Baldíos está en manos de los humanos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][875] = {title = "Las tenientes arpías", objective = "Reúne 6 anillos de tenientes arpías de las destripadoras Alabruja en Los Baldíos del Norte.", description = "La única forma de detener a esas arpías saqueadoras es destruir su cadena de mando. Las arpías siguen a intrépidas tenientes, destripadoras Alabruja. Si caen las destripadoras, el resto las seguirá.\n\nVe a Las Colina Áridas y mata a destripadoras Alabruja. Asegúrate de que sufran una muerte dolorosa, <nombre>. Queremos que esas muchachas arpías aprendan cuán descabellado es buscar pelea con la Horda.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][876] = {title = "Serena Sangrepluma", objective = "Mata a Serena Sangrepluma y hazte con su cabeza.", description = "Las arpías que mataste mencionaron a su matrona, Serena Sangrepluma. A juzgar por su encarnizado odio hacia la Horda, debe de ser algún tipo de vieja rencilla. Debes acabar con Serena Sangrepluma y zanjar este asunto de una vez por todas.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nBanda degolladoraAnillo SangreplumaAnillo de Darsok\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][877] = {title = "El Oasis Estancado", objective = "Usa las semillas secas para investigar las fisuras en el Oasis Estancado.", description = "¿Es posible que lo que está pasando al sur pase aquí también? A juzgar por tus descubrimientos en las Charcas del Olvido, puede que estos oasis sean la clave. Hagamos un experimento.\n\nTen, toma estas semillas que he recogido de la montaña. Están muertas y no son fértiles, pero llévalas a El Oasis Estancado justo al sur. Si allí también hay una grieta, coloca las semillas en su interior... y observa. Informa de tus descubrimientos a Tonga, en El Cruce.", progress = nil, completion = "¡Tus descubrimientos son sorprendentes! Las semillas que te di estaban secas y muertas. ¡Lo que sea que descanse bajo estos oasis tiene la capacidad de crear vida!\n\nDebemos seguir investigando...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][878] = {title = "Tribus en guerra", objective = "Mata a 6 buscaquas Erizapúas, 12 tejespinas Erizapúas y 12 geománticas Erizapúas y vuelve junto a Quebrantadientes en el Campamento Taurajo en Los Baldíos.", description = "Debes acabar con mis enemigos. <Gruñe.> Debes ayudar a Quebrantadientes y a los Crines de Acero a debilitar a los Erizapúas. Ambas tribus son muy espirituales, vinculadas a la tierra y a su poder. <Gruñe.> Nos da fuerza en todo... especialmente en la guerra.\n\nSi quieres saber quién le causa realmente este suplicio a Thork <gruñe> y a la Horda, entonces ¡ayuda a Quebrantadientes! Ataca a los líderes espirituales de los Erizapúas hacia el norte; debilítalos lo suficiente para que los Crines de Acero puedan vencerlos y dominar Los Baldíos.", progress = nil, completion = "Sí, sí... me llena de alegría &lt;gruñe&gt; los Erizapúas conocen el dolor de mi tribu, &lt;raza&gt;. Así es cómo debería sentirme pero  no es el caso. \n\nAyudas a tu pueblo y te rinden honores. Quebrantadientes ayuda a su pueblo ¿y qué hacen? Le dan la espalda. ¡Lo olvidan y lo abandonan para que se pudra en una jaula! \n\nIncluso los ayudo entre rejas ¡y no mandan a nadie a rescatarme!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][879] = {title = "Traidores", objective = "Mata a Nak, Kuz y Lok Aterraorcos y lleva sus calaveras a Quebrantadientes en el Campamento Taurajo en Los Baldíos.", description = "Tres miembros de mi tribu salieron del Horado para encabezar unas incursiones contra la Horda, <raza>. <Gruñe.> Son crueles y taimados, y si los derrotas, entonces El Cruce y la mayor parte de Los Baldíos conocerán la paz... <gruñe> al menos por lo que respecta a la tribu Crines de Acero <gruñe.>\n\nNak, Kuz y Lok Aterraorcos son a los que tienes que buscar. Se encuentran en un lugar remoto del sur de Los Baldíos. Uno lanza hechizos, otro es un rastreador y su líder, llamado Aterraorcos <gruñe> es un guerrero. Mátalos, <raza>, como ellos me han matado a mí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][880] = {title = "Seres alterados", objective = "Reúne 6 caparazones de quijafortes alterados de los quijafortes de El Oasis Estancado.", description = "Es importante estudiar la vida, tanto animal como vegetal, afectada por los oasis y las energías extrañas que descubriste. El Oasis Estancado es el hábitat de una especie de tortugas quijaforte. La población aumentó recientemente. Además, estos animales antes pacíficos se han vuelto agresivos, como pude comprobar mientras venía hacia aquí.\n\n<Jerrik te muestra un dedo vendado.>\n\nSospecho que las ha alterado el oasis. Recoge sus caparazones y llévaselos a Tonga en El Cruce para que los estudie.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][881] = {title = "Echeyakee", objective = "Toca el cuerno en la guarida de Echeyakee para invocarlo. Mátalo o subyúgalo.", description = "Albineblina, Echeyakee en la lengua de los Tauren, es el rey de los felinos de la sabana. Es tan sigiloso al cazar que dicen que es como una neblina blanca y etérea sobre la tierra. Y tan raudo mata a sus presas que no tienen tiempo de sentir miedo ni dolor.\n\nLos tauren dicen que es muerte y misericordia a la vez.\n\n<nombre> te encomiendo que caces a Echeyakee. Su guarida está al noroeste de aquí, en el lado norte de una pequeña colina, entre los huesos de un kodo gigante.\n\nY ahora vete. Haz sonar este cuerno cuando hayas alcanzado su guarida. Hazlo sonar y él acudirá.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTe van a lanzar el siguiente hechizo:\n\nGracia de Echeyakee\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][882] = {title = "Ishamuhale", objective = "Llévale el colmillo de Ishamuhale a Jorn en el Campamento Taurajo.", description = "Ishamuhale, Dientarpón, es el más feroz de los raptores Solescama de Los Baldíos. No caza por deporte, ni por comida. Caza porque le apasiona la caza. Mata porque está en su naturaleza.\n\nY tendrás la oportunidad de conocer su naturaleza, <nombre>, porque tu camino sigue ahora las huellas de las garras de Ishamuhale.\n\nEmpieza la caza. Mata a su presa favorita, una zhebra, y trae entonces sus despojos al árbol muerto al noroeste de Trinquete. Ishamuhale olerá los despojos y esto lo atraerá.\n\nPrepárate para cuando llegue.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][883] = {title = "Lakota'mani", objective = "Llévale la pezuña de Lakota'mani a Jorn en el Campamento Taurajo.", description = "La pezuña de Lakota'mani es un símbolo de la fuerza del gran kodo.", progress = "<nombre>, cuando te acercabas noté un renovado poder en tus pasos. Dime, ¿se ha reunido tu espíritu con el gran Lakota'mani?", completion = "\"Lakota'mani se llama \"Sacuditerra\" en nuestro idioma y sus pasos retumban como el trueno. Ahora está contigo y su valor se funde con el tuyo. Juntos no hay conflicto que no puedan acometer. \n\nAnda con la cabeza alta, &lt;nombre&gt;. Anda con la cabeza alta, Sacuditerra.\"", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][884] = {title = "Owatanka", objective = "Llévale la espina caudal de Owatanka a Jorn en el Campamento Taurajo.", description = "Al tocarla, saltan chispas de la espina caudal de Owatanka.", progress = "<nombre>, ¡detecto un nuevo poder en tu mirada! ¿A que te has reunido con el poderoso Owatanka?", completion = "Los tauren llaman \"Rayo Azul\" al truenagarto Owatanka porque en él reside una velocidad que no se espera de su tamaño. Se dice que un rayo lo alcanzó hace mucho tiempo y, alimentada por la furia del cielo, la energía de la bestia no conoce límites. \n\nQue su energía fluya por ti, &lt;nombre&gt;. Puesto que ahora igualas el paso de Owatanka.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][885] = {title = "Washte Pawne", objective = "Llévale la pluma de Washte Pawne a Jorn Vidente del Cielo en el Campamento Taurajo.", description = "La pluma de Washte Pawne hace daño al tocarla.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][886] = {title = "El oasis de Los Baldíos", objective = "Habla con Tonga Tótem de Runa en El Cruce.", description = "Los druidas de Cima del Trueno sentimos la presencia de un extraño poder en Los Baldíos, al este de Mulgore.\n\nEnviamos a Tonga Tótem de Runa para que descubra la fuente de dicho poder pero tememos que necesite ayuda.\n\nVe a Los Baldíos y habla con Tonga. Lo encontrarás en El Cruce. Para llegar hasta allí, sigue el camino que sale del Poblado Pezuña de Sangre en dirección este. Una vez en Los Baldíos, coge hacia el norte cuando el camino se bifurque. Continúa en dirección norte y encontrarás El Cruce.\n\nTen cuidado de no abandonar el camino, <nombre>, pues Los Baldíos es un terreno muy abrupto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][887] = {title = "Los filibusteros de los Mares del Sur", objective = "Mata a 8 degolladores o corsarios de los Mares del Sur en Isla de Batalla.", description = "Gazlowe me prometió un ascenso si le ayudo con el problema de piratas en Trinquete. El problema son los nuevos bucaneros que han venido y ocupado Isla de Batalla, al sur de aquí. No buscan solo nuestras cosas: ¡tienen agravios pendientes! La otra noche incluso fueron a por uno de nuestros galeones de guerra.\n\nTengo planes para manejar la situación, pero Gazlowe quiere resultados inmediatos. Vete a Isla de Batalla y empieza a rebanar cabezas, ¿quieres?", progress = nil, completion = "Hiciste un buen trabajo, muchacha. Si sigues así un poco más, tendré un problema menos del que preocuparme. Espero que esto los convenza de reubicar su operación.\n\nMientras tanto, ¡está el pequeño problema de recuperar los bienes que me robaron!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][890] = {title = "El envío perdido", objective = "Llévale el libro de contabilidad de Gazlowe al maestro de muelles Vertipeluca.", description = "¡Llevo siglos esperando mi último cargamento de mercancías de Bahía del Botín! Pondría la mano en el fuego a que lo robaron los filibusteros pero para asegurarnos, podrías acercarte hasta el muelle y preguntarle a Vertipeluca si ya han guardado mi mercancía en el almacén sin notificármelo.\n\nToma mi libro de contabilidad y dile a Vertipeluca que coteje mis datos de inventario con sus registros.", progress = "¿Mercancías para enviar en el siguiente barco, <nombre>?", completion = "Ah, Gazlowe te envía, ¿no? Solo un momento, déjame echar un vistazo para comprobar mis registros y asegurarme de que ningún envío de Gazlowe ha sido despachado al lugar equivocado. \n\nApuesto que espera esas botas de Drizzlek...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][891] = {title = "La venganza de un capitán", objective = "Consigue 10 medallas de Theramore de marinos de Theramore y marineros de cubierta de Theramore. Mata a los tenientes Pira y Terraciervo.", description = "¡Otro barco más que ha caído ante los intransigentes humanos de Theramore!\n\nSu nuevo contraalmirante se ha asentado en la costa, cerca de aquí. Se dedica a abordar o hundir todos los barcos que no se someten a sus caprichos.\n\nViaja al sur, siguiendo la Costa Mercante, y encontrarás su campamento. Tráeme las medallas de sus marinos y sus marineros de cubierta. Ejecuta a sus tenientes principales, Pira y Terraciervo. ¡Destrózalos como ellos han destrozado mi flota!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Mosquete de SoldadoCalzones de lobo marinoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][893] = {title = "Una selección de armas", objective = "Llévale 1 puñal Crines de Acero, 1 varita Crines de Acero carbonizada y 1 escudo de guerra Crines de Acero a Jironack Forjacero en Campamento Taurajo en Los Baldíos.", description = "Por lo que me han contado, los jabaespines Crines de Acero hacia el sur, más allá de la Tierra de Gigantes, no cuentan con herreros cualificados pero, al parecer, han empezado a desarrollar armas resistentes. Me gustaría ponerles la mano encima a varios tipos diferentes para aprender su técnica si fuera posible.\n\nSi deseas contribuir con honor a la Horda, tráeme algunas muestras de sus armas. Encuentra una daga de sus acechadores, una varita de sus videntes y un escudo de sus frenéticos bélicos. ¡Con eso debería bastar!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Martillo de demoliciónPodrás elegir una de estas recompensas:\n\nLinterna eterna\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][894] = {title = "El churumbele", objective = "Accede a la consola de control del laboratorio de investigación de Ventura y Cía.\n\nObjeto provisto: \n", description = "Ventura y Cía. ha montado un pequeño centro de investigación al oeste, pasando El Fangal. No tengo muy claro qué hacen allí pero logré descubrir que están haciendo pruebas con algo llamado \"churumbele\".\n\nY digo yo, ¿qué leches es un churumbele? Bueno, sea lo que sea, quiero examinarlo, así que necesito que alguien me lo consiga.\n\nConseguí una copia de su manual de instrucciones del sistema de control, gracias al cual deberías poder encontrar la forma de desconectar el churumbele.", progress = nil, completion = "En el frente de la consola de control hay varios botones, palancas y lucecitas parpadeantes que se distribuyen de forma algo desordenada. Un pequeño indicador muestra que el aparato está funcionando dentro de los niveles óptimos y que las tres primeras válvulas de control están abiertas. Hay una pequeña cerradura en la parte inferior derecha del panel de control.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][895] = {title = "SE BUSCA: Capitán Garvey", objective = "Llévale la cabeza del capitán Garvey a Gazlowe en Trinquete.", description = "SE BUSCA\n\n\"Capitán\" J. Garvey, capitán del Daga de Doncella.\n\nSe le han imputado cargos en todos los mares por robo, secuestro, extorsión, incendio provocado, esclavitud, etc. Garvey atracó recientemente en estas aguas con su tripulación de filibusteros de los Mares del Sur y, la última vez, se le vio atacando la Isla de Batalla. ¡Tráeme sus restos en condiciones de poder ser identificados!\n\n-- Gazlowe", progress = "¿Qué ocurre? ¿Puedo ayudarte en algo? Mercancías que despachar, ¿acaso un trabajo de ingeniería?", completion = "¡Ahhhh! Estos tipos... Sabes, una vez vi a El Temerario en mar abierto. Un barco realmente aterrador... ¿O era un bote? ¡Esos marineros son tan particulares!\n\nEn fin, verlo deslizarse por el agua fue una experiencia increíble. Me alegra que su infame capitán ya no vaya a molestar a mis naves.", rewards = "Jubón de retenedorLeotardos de navegador marinoGuantes de GazloweCertificadora de defunciónRecibirás:\n\n"}
MultiLanguageQuestData['mx'][896] = {title = "La fortuna de un minero", objective = "Recupera la esmeralda ojo de gato de un sobrestante o un déspota de Ventura y Cía.", description = "Oye, <raza>, ¿te interesaría algún tesoro? Sabía que eso llamaría tu atención.\n\nPor el muelle del río se dice que uno de los mineros de Mina Pedrusco de Ventura y Cía. al noreste de aquí descubrió una esmeralda del tamaño de tu puño.\n\nSé de unos cuantos compradores que estarían interesados en ponerle las manos encima y no me importaría ir a medias en la venta. ¿Qué dices?", progress = "Si al menos supiéramos qué minero encontró la esmeralda, sería un paseo...", completion = "¡Mira el tamaño de esa cosa, &lt;nombre&gt;! ¡Nos vamos a hacer ricos! A ver, según la cotización que he visto en las gemas que van a Minahonda, debería poder calcular tu parte: cincuenta por ciento, ¡no te preocupes!\n\nAhora veamos... Creo que esto debería bastar. ¡Un placer hacer negocios contigo, &lt;nombre&gt;.", rewards = "Recibirás:\n\nUn costal de monedas"}
MultiLanguageQuestData['mx'][897] = {title = "El Cosechador", objective = "Llévale la cabeza del Cosechador a Jorn Vidente del Cielo.", description = "Esta extraña criatura insectoide parece de un orden natural por fuera, como si no perteneciera a Los Baldíos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][898] = {title = "Escapar del fuerte", objective = "Escolta a Gilthares Ramafuego de vuelta hasta Trinquete con el Capitán Solbrillante.", description = "¡Por fin! ¡Alguien que viene a rescatarme!\n\nNo puedo creer que hayas logrado superar a los guardias. Estos zelotes de Theramore están completamente desquiciados. Hundieron nuestro barco y a mí, el único superviviente, me encarcelaron. Me calificaron de enemigo y de amenaza para la Alianza.\n\n¡Yo! ¿Una amenaza para su gran farsa de Alianza? Solo era un marinero de un envío de licor de luna entre Trinquete y Bahía del Botín.\n\nPero basta de charla. Me ayudarás a volver a Trinquete, ¿verdad? Dime cuando estés <listo/lista> y saldremos para allá.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Botas con hebillasGuanteletes ribeteadosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][899] = {title = "Consumido por el odio", objective = "Reúne 30 colmillos de jabaespín.", description = "Asesinaron a mi esposa. Incendiaron mi hogar. Desde aquella fatídica noche he viajado por estas tierras, desde que el sol nace hasta que se pone, escudriñando el horizonte en busca de monstruos. He matado a cada hombre jabalí que se me ha cruzado pero mi sed de su sangre está lejos de estar saciada.\n\nTú, <clase>, tú podrías ayudarme.\n\nMátalos. Mata a tantos como puedas. Tráeme sus colmillos y celebraremos juntos su muerte.", progress = "El jabaespín pagará por esto, <nombre>. Lo juro.", completion = "&lt;clase&gt;, te has tomado en serio mi tarea y te lo agradezco. \n\nAunque persiste mi deseo de venganza, al menos puedo sonreír al ver que los jabaespines también han sentido dolor.", rewards = "Viejo traje de boda de MankrikGuantes de pellejo de jabaespínCercenadora de jabalíes de MankrikRecibirás:\n\n"}
MultiLanguageQuestData['mx'][900] = {title = "El churumbele", objective = "Cierra la válvula de control de combustible, la válvula reguladora y la válvula de control principal y usa entonces de nuevo la consola de control.", description = "Ahora las tres válvulas de control están abiertas. Por los indicadores del panel de control cabe suponer que se deberían apagar antes de que se pueda apagar el dispositivo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][901] = {title = "El churumbele", objective = "Consigue la llave de la consola de Manitas el Risitas.", description = "Una vez apagado el aparato, se puede abrir el panel de control y extraer el churumbele de la consola. Con todo lo demás listo, solo queda conseguir la llave que desbloquea la consola.", progress = "Los pilotos de la consola están atenuados y los diales están todos a cero, todo está parado.", completion = "Al girar la llave en la cerradura, la consola de control queda libre. Se apaga una luz roja en la parte superior de la consola y no queda corriente en el terminal.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][902] = {title = "El churumbele", objective = "Llévale el churumbele a Petardol a la Avanzada de Ollaboquilla en Los Baldíos del Norte.", description = "Al abrir el panel frontal de la consola de control se accede al denso cableado, conducciones y otros extraños mecanismos, la mayoría de los cuales no parece tener ninguna función práctica. Si se apartan y se mira hacia el interior de la consola, se verá el churumbele. Basta con tirar de él para sacarlo de su compartimento.", progress = "¡Eh, has vuelto, <nombre>! ¿Tienes el churumbele?", completion = "Esto es... eh... interesante... sí. Tendré que enviárselo al cuartel general del Gremio de Manitas en Minahonda. Estoy seguro de que después de un poco de investigación y disecciones cuidadosas, podrán encontrarle algún sentido.\n\nAunque puede que primero le eche un vistazo yo mismo primero...", rewards = "Martillo de ingenieroEscudo de soldaduraCinturón de pobre fabricaciónBotas de cuarto limpioRecibirás:\n\n"}
MultiLanguageQuestData['mx'][903] = {title = "Cazar a las cazadoras", objective = "Reúne 5 garras de cazadora de las cazadoras de la sabana.", description = "Si de verdad quieres demostrarme tu coraje, te enviaré a por algo de mayor calibre. Las cazadoras de la sabana de Los Baldíos son una especie dura de roer. Resistentes, con recursos, taimadas... y mortales. Han estado atacando a nuestros exploradores alrededor del pueblo, especialmente al noreste.\n\nExtrema la precaución al cazarlas, <nombre>, o pasarás de ser el depredador a ser la presa.", progress = "¿Cómo va la caza, <nombre>?", completion = "Ah, veo que has estado ocupado. Espero que hayas aprendido mucho de esta presa, &lt;nombre&gt;. Te hará falta la fuerza y la astucia de bestias como estas para servir a mi amada Horda.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][905] = {title = "En la guarida del raptor", objective = "Mata a raptores Solescama y recoge sus plumas. Después usa las plumas en los 3 nidos de Solescama.", description = "<nombre>, la caza se intensifica. Ahora debes encontrar y derrotar a la presa en su guarida.\n\nCaza a los raptores Solescama hacia el sur, allí han construido una madriguera entre las colinas, cerca del camino. Ejecútalos y desplúmalos. ¡Coloca las plumas en los nidos de segadores para demostrar a sus semejantes que no les temes!\n\nTen cuidado, <clase>. Los raptores cazan en manada y te rodearán si te descuidas.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Capa de SolescamaPerforadora OscuraspinaPodrás elegir una de estas recompensas:\n\nObjeto #3\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][906] = {title = "Traidores", objective = "Llévale la calavera de Lok a Thork en El Cruce, en Los Baldíos.", description = "Llévale la cabeza de Lok a Thork en El Cruce, <raza>. <Gruñe.> Debería saber lo que le ha ocurrido a mi tribu sin más explicaciones, ¡vaya!, y no es que él se creyera que Quebrantadientes tuviera nada que ver con <gruñe> tales cosas. Pero seguro que te recompensará por llevarle tan gran trofeo <gruñe.>\n\nSeguiré bendiciéndote con el poder de Agamaggan por todo el tiempo que permanezca en esta jaula, <raza>. Hasta entonces, adiós.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guerrera de malla de cortezaGuerrera de moho secoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][907] = {title = "Los truenagartos iracundos", objective = "Llévale 3 unidades de sangre de truenagarto a Jorn Vidente del Cielo en el Campamento Taurajo.", description = "Bien, <nombre>, ahora debes enfrentarte a los colosales truenagartos. Son fieras tan monumentales que el suelo de las llanuras tiembla bajo sus pisadas. Ten cuidado cuando luches contra ellos, un paso en falso y te aplastarían como a una hormiga.\n\nEncontrarás a los truenagartos en Los Baldíos del Sur. Se llaman morrotormenta, Tormentero y Tronatesta. Vuelve cuando los hayas vencido.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][908] = {title = "Entre ruinas", objective = "Llévale el núcleo de las profundidades a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno.", description = "El Martillo Crepuscular se ha trasladado a las ruinas del Santuario Lunar de las Cavernas de Brazanegra. Su presencia solo puede servir para forzar a los elementos a actuar contra nosotros. Si no nos ocupamos de ella, esta región caerá en sus manos definitivamente.\n\n<nombre>, dirígete a Brazanegra y encuentra la piedra de las profundidades en las ruinas; debería estar cerca, en el agua. En su interior hay un núcleo de las profundidades, un dispositivo que cuando se lee correctamente, revela la historia de toda actividad elemental. Si lo consigo, y con la ayuda de los miembros del Anillo de la Tierra, ¡quizás podamos detenerlos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][910] = {title = "Un paseo por los embarcaderos", objective = "Lleva a tu pupilo a los embarcaderos de Trinquete en Los Baldíos.", description = "¡He oído hablar de los grandes barcos que navegan entre Trinquete y Bahía del Botín! Sería una pasada navegar por el mar y luchar en grandes batallas. ¡Quizás cuando sea mayor me haga un poderoso marinero de la Horda! ¡Sí!\n\n¿Quieres llevarme a ver los embarcaderos de Trinquete, por favor? Te prometo que no me tiraré al agua ni te daré problemas... ¡solo quiero ver los grandes barcos y oler el agua salada del mar! ¡Sí!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][911] = {title = "El acceso a la frontera", objective = "Lleva a tu pupilo a La Empalizada de Mor'shan en la zona norte de Los Baldíos, antes de la entrada a Vallefresno.", description = "Dicen que Vallefresno es la nueva frontera y que La Empalizada de Mor'shan en Los Baldíos es su puerta de entrada. ¡Sería genial ser uno de los pioneros y recoger todo lo que necesitas de la naturaleza virgen! Dicen que ese será el principal campo de batalla entre la Horda y la Alianza ¡y yo quiero verlo, <nombre>!\n\n¿Me llevarías a La Empalizada de Mor'shan para que pueda ver cómo es la frontera, por favor? ¡Quiero ver el sitio donde la Horda está combatiendo a esos apestosos elfos de la noche!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][913] = {title = "El chillido del halcón trueno", objective = "Encuentra 1 halcón trueno, mátalo y llévale sus alas a Jorn Vidente del Cielo en el Campamento Taurajo.", description = "<nombre>, el halcón trueno es un animal de lo más feroz. Ha llegado la hora de que te enfrentes a uno de ellos. Debes averiguar por donde andan y traerme sus alas como prueba de haber cazado a uno.\n\nHazlo y ya casi habrás acabado tus tareas conmigo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Rodela de cobaltoBastón de jinete del vientoRecibirás:\n\nGuantes de la luna"}
MultiLanguageQuestData['mx'][914] = {title = "Líderes del Colmillo", objective = "Lleva las gemas de Cobrahn, Anacondra, Pythas y Serpentis a Nara Ferocrín en Cima del Trueno.", description = "Los druidas de las Cuevas de los Lamentos, los Druidas del colmillo, son una aberración. Fueron parte de una orden de nobles druidas que pretendían sanar Los Baldíos, pero ahora tan solo pretender cambiar esta tierra para amoldarla a sus propios y retorcidos sueños.\n\nLos Druidas del colmillo tienen cuatro líderes, y cada uno de ellos posee una gema de sueño. ¡Sus rostros aún me siguen atormentando! Derrota a los líderes y tráeme sus gemas. Así Los Baldíos recuperarán la paz.\n\nVete, <nombre>. Los encontrarás escondidos en las profundidades de las Cuevas de los Lamentos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Espada de alaBastón crecienteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][916] = {title = "Corrupción Tejemadera", objective = "Mata 12 arañas Tejemadera.", description = "He venido a Cañada Umbría para observar a las arañas Tejemadera de la Gruta Narácnida. Me dijeron que tras la reciente bendición de Teldrassil deberían ser mucho menos agresivas. Parece que me informaron mal.\n\nHace poco obtuve algunas de sus glándulas venenosas, y me chocó encontrar una corrupción dañina en su interior. Huelga decir que me preocupa pensar lo que podría pasar si dejáramos animales corruptos como estos campar a sus anchas.\n\nQuiero que reduzcas su población para ganar tiempo.", progress = "¿Conseguiste las glándulas de veneno, <nombre>?", completion = "Gracias, &lt;nombre&gt;. Cuando regrese a Darnassus compararé el veneno de estas glándulas con el de otras arañas. Creo que sus propiedades estarán relacionadas con el crecimiento reciente de nuestro nuevo Árbol del Mundo.", rewards = "Daga CardoleñoBastón CardoleñoEspada CardoleñoGran maza CardoleñoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][917] = {title = "Huevo de Tejemadera", objective = "Consigue un huevo Tejemadera.", description = "Ahora que lo pienso, a lo mejor me puedes ayudar un poco más. Vine para recoger un huevo de Tejemadera del fondo de la cueva, pero las arañas no están por la labor. Si pudieras coger un huevo y llevárselo a Dirania los dos te estaríamos muy agradecidos.", progress = "¿Has entrado a la Gruta Narácnida, <nombre>? ¿Encontraste algún huevo de araña?", completion = "Ah, muy bien. Ordenaré que envíen este huevo y el veneno a Darnassus, y luego retomaré mis estudios allí cuando terminemos aquí. Espero aprender mucho con estos especímenes, &lt;nombre&gt;. Has sido de gran ayuda.", rewards = "Guerrera de los bosquesEscudo de los bosquesTogas de los bosquesRecibirás:\n\n"}
MultiLanguageQuestData['mx'][918] = {title = "Semillas de Brezomadera", objective = "Recoge 6 semillas de Brezomadera.", description = "Los Brezomadera de Teldrassil son elementales de la naturaleza. En cierto modo, representan el orden natural de las plantas y los animales de nuestro gran árbol.\n\nPor eso es desagradable ver lo malhumorados que están últimamente, especialmente cuando tenemos en cuenta que la situación debería estar mejorando.\n\nQuiero ayudar a localizar el origen. He estado trabajando en diferentes métodos de nutrición de plantas y me gustaría probarlos con semillas de Brezomadera. ¿Podrías recoger semillas de Brezomadera alrededor del Lago Al'Ameth y traérmelas?", progress = "¿Tienes las semillas? Estoy deseando plantarlas.", completion = "Las has conseguido. ¡Estupendo!\n\nPlantaré estas semillas en una tierra muy especial que he preparado. Creo que las semillas germinarán y darán lugar a brezomadera mucho más dóciles. ¡Quizá más adelante puedas ver el resultado!", rewards = "Recibirás:\n\nChampiñón de bosqueCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][919] = {title = "Brotes de Brezomadera", objective = "Lleva 12 brotes de brezomadera a Denalan en el Lago Al'Ameth.", description = "Están brotando pequeños Brezomadera alrededor de las aguas del Lago Al'Ameth. Me temo que ya no es posible ayudarlos por lo que deberíamos eliminarlos antes de que crezcan más y empiecen a causar problemas.\n\nCuando pases por el lago, si ves algún brote de Brezomadera, arráncalo. ¡Ayúdanos a mantener la tierra limpia!", progress = "Hola, <nombre>. ¿Has encontrado algún brote cerca del agua?", completion = "¡Esto es demasiado! Me temo que su número está creciendo peligrosamente. Espero poder descubrir qué está provocando su corrupción. \n\nGracias por tu ayuda, &lt;nombre&gt;. Esta tierra es un lugar más limpio gracias a tus esfuerzos.", rewards = "Guantes de jardineríaBrazales de piedra grisRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][924] = {title = "La Semilla del Demonio", objective = "Coge 1 piedra de energía imperfecta. Llévala al Altar de Fuego antes de que su energía desaparezca y vuelve junto a Ak'Zeloth.", description = "La Semilla del Demonio es una poderosa herramienta para la Legión Ardiente. Se encuentra en una caverna en la Cima Calígine, sobre un altar de fuego demoníaco.\n\nHe preparado piedras de energía que cuando se colocan cerca de la semilla interfieren en su conexión con la Legión.\n\nCoge una piedra de la mesa y llévala al altar de fuego en lo más alto de la Cima Calígine. Dirígete hacia el oeste, luego hacia el norte en el cruce de caminos. Verás la montaña a tu izquierda. La cara norte es la más segura de escalar.\n\nY date prisa, la energía de la piedra se agota con el tiempo.", progress = nil, completion = "Has completado la tarea. Has destruido La Semilla del Demonio como Neeru pedía. Pero esto no es el fin... \n\nLa destrucción de La Semilla del Demonio envió oleadas de energía a través del éter, oleadas de colosal fuerza. Las he sentido y seguro que otros seres también. Y ellos se preguntarán por qué se ha roto su juguete... \n\nPero independientemente de los problemas futuros, tengo algo para ti. Neeru lo envió como pago. Y me pidió que te transmitiera su agradecimiento. \n\nAsí que gracias.", rewards = "Recibirás:\n\nArmadura de alma en pena"}
MultiLanguageQuestData['mx'][927] = {title = "El corazón musgoso", objective = "Llévale el corazón musgoso a Denalan, que está en el Lago Al'Ameth.", description = "El corazón de Negromusgo el Fétido está recubierto de un musgo oscuro y grasiento. De hecho, se sabe que es un corazón porque late lenta y rítmicamente... Incluso ahora se sigue oyendo su latido.\n\nPuede que Denalan quiera verlo.Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nTrigger Denalan, Moss-Twined Heart Turn-in\n\nRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][929] = {title = "Teldrassil: La negativa de los Aspectos", objective = "Llena la ampolla de jade.", description = "Deja que te cuente más sobre el cometido que debes realizar. Los druidas de Darnassus usan el agua de las pozas de la luna de Teldrassil, que deben rellenarse de vez en cuando. Usando estas ampollas especiales puedes recoger agua de las pozas de la luna.\n\nCoge esta vasija y ve hasta la poza de la luna que está a las afueras de la Aldea Brisa Estelar, al este. Llénala de agua y tráemela de vuelta. Presta atención a las lecciones de las pozas, para evitar repetir nuestros errores.", progress = "Hola otra vez, <nombre>. ¿Has terminado tu tarea?", completion = "Tras la Batalla del Monte Hyjal, habíamos perdido el rumbo. Nordrassil humeaba tras el fuego que se desató y perdimos nuestra inmortalidad: ¡nuestra esencia!\n\nEn estos tiempos tan difíciles, liberaron al Traidor de su prisión, y Shan'do Tempestira desapareció. Fue una época oscura para todos.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][930] = {title = "El fruto resplandeciente", objective = "Llévale el fruto resplandeciente a Denalan, que está en el Lago Al'Ameth.", description = "Un gran fruto redondo pende entre las hojas de esta resplandeciente planta.\n\nTienes la certeza de que a Denalan le gustaría analizarlo.", progress = "<nombre>, parece que tienes algo que contarme. ¿Sabes algo nuevo de los Brezomadera?", completion = "¿Y esto lo encontraste en Teldrassil? Fascinante... Se trata de un fruto exótico. Quizás sus semillas fueran traídas hasta aquí desde un lugar muy lejano. ¡Incluso tan lejano como Azeroth! Hay algo en este fruto... parece que ha reaccionado de modo extraño tras entrar en contacto con la tierra de Teldrassil. \n\nGracias, &lt;nombre&gt;. Ahora, si me disculpas, voy a analizarlo en detalle...", rewards = "Te van a lanzar el siguiente hechizo:\n\nTrigger Denalan, Glowing Fruit Turn-in\n\nRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][931] = {title = "Fronda fulgurante", objective = "Llévale una fronda fulgurante a Denalan. Normalmente está en el Lago Al'Amethm, pero a veces viaja hasta el Cobertizo Primigenio.", description = "Las hojas de esta planta fulguran con la luz del bosque, creando un aura intermitente.\n\nCrees que a Denalan le gustaría tener una muestra.Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nTrigger Denalan, Shimmering Frond Turn-in\n\nRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][932] = {title = "Odio enraizado", objective = "Mata a Lord Melenas y llévale su cabeza a Tallonkai Cruzarraíz en Dolanaar.", description = "Debo advertirte, <nombre>, que este asunto debe quedar entre nosotros. Los sátiros ya son toda una vergüenza para nosotros, y este en concreto está demasiado cerca.\n\nSe llama Lord Melenas y habita en la cercana cueva de Roca Mácula, donde ha reunido a un numeroso grupo de guerreros grells. Su corazón es negro como la noche, pero lo que trama es incluso más repugnante.\n\nDebes encontrarlo en su cueva cercana, al norte de aquí, y traerme su cabeza.", progress = "¿Has matado ya a Lord Melenas? Es muy importante que alguien se ocupe de él rápido y con discreción, <nombre>. Su existencia es una vergüenza para todos nosotros.", completion = "Con Lord Melenas criando malvas al fin puedo encargarme de otros asuntos. Gracias, &lt;nombre&gt;.", rewards = "Envolturas de parraBrazales feralesBotas de CruzarraízRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][935] = {title = "Las aguas de Teldrassil", objective = "Llévale la vasija llena a Corithras Furia Lunar en el cruce que hay enfrente de Darnassus.", description = "Nuestras tareas están cumplidas, por ahora. El agua ha demostrado ser de gran importancia, pero yo no soy su destinataria original. Ve y devuélvesela a Corithras Furia Lunar en el cruce, seguro que quiere que la lleves a su destino.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Martillo de matorralArco de fresnoLeotardos verdigrisAtaduras grasientasRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][936] = {title = "Ayuda al archidruida Tótem de Runa", objective = "Habla con el archidruida Hamuul Tótem de Runa en Cima del Trueno.", description = "¿Tienes un minuto, <clase>?\n\nEl Círculo Cenarion de Cima del Trueno está buscando aventureros curtidos para un importante proyecto de investigación. No conozco los detalles, pero has de saber que quien dirige el proyecto es el mismísimo archidruida Hamuul Tótem de Runa.\n\nSi te interesa, habla con él directamente. Lo encontrarás en el Alto de los Ancestros, en Cima del Trueno.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][937] = {title = "El claro encantado", objective = "Consigue 6 cinturones Sangrepluma.", description = "Me enviaron aquí con un pequeño grupo de centinelas para proteger el Árbol del Oráculo de las arpías que han anidado en el claro. Poco a poco estamos intentando expulsarlas.\n\nCuando el Árbol del Oráculo envió a un mensajero a Darnassus con un informe, este fue atacado y asesinado por un grupo de arpías.\n\nSi te sientes <capacitado/capacitada> para esta tarea, ve a sus nidos y acaba con ellas, y después tráeme sus cinturones como prueba de ello.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Manteo chispeadoAtaduras apretadasRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][938] = {title = "Niebla", objective = "Lleva a Niebla ante la centinela Arynia Quiebranubes que se encuentra en la Poza de la Luna situada cerca del Árbol del Oráculo.", description = "La piel de la dientes de sable es de un color gris característico que armoniza con el del bosque en el que se encuentra. Mientras permanece allí tendida, observas que está malherida, con profundas laceraciones en la espalda y el estómago.\n\nLevanta la cabeza y te observa fijamente, dejando ver a través de sus azules ojos la gran inteligencia que posee. Parece que desea seguirte.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Brazales de cordónRodela de riscoGuantes rompenubesRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][939] = {title = "a Flauta de Xavaric", objective = "Lleva la Flauta de Xavaric y 5 muestras de lazo vil de fuego de jade a Eridan Vientoazul al Frondavil meridional.", description = "Estudias la sencilla flauta de madera que recogiste tras derrotar a Xavaric.\n\nLa madera parece sólida, pero cuando giras la flauta en tus manos, te da la sensación de que los dibujos y espirales de su superficie empiezan a retorcerse. Entonces te invade un repentino pavor...\n\nSacudes la cabeza <seguro/segura> de que tu mente te está jugando una mala pasada.\n\nPuede que otros sátiros tengan más pistas sobre lo que has encontrado. Lleva lo que has descubierto al druida Eridan Vientoazul que vive al sur de Frondavil.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][942] = {title = "El prospector despistado", objective = "Lleva el fósil misterioso al arqueólogo Gargavino al Puerto de Menethil.", description = "Este fósil tiene un parecido asombroso con uno que vi en Forjaz una vez. Un arqueólogo llamado Gargavino lo trajo a nuestra conferencia anual de la Liga de Expedicionarios. Creía que el fósil encerraba un poder y que este podría liberarse de alguna forma.\n\nLo último que supe de Gargavino es que se había refugiado en el Mesón Aguahonda, en el Puerto de Menethil y que esperaba una escolta para llegar a la Excavación de Whelgar. Búscalo y muéstrale el fósil de Tripirrem. Quizás él consiga revelar los secretos del pasado.\n\nEl barco para Menethil zarpa de Ventormenta.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][943] = {title = "El prospector despistado", objective = "El arqueólogo Gargavino, del Puerto de Menethil, quiere que le lleves la Piedra de Relu y el fósil de Gargavino.", description = "El fósil original lo tiene ahora el prospector Whelgar, en su excavación de Los Humedales. Cuando descubrí la Piedra de Relu, creía que era la clave para desvelar el misterio del fósil.\n\nCuando me dirigía a reunirme con Whelgar, fui atacado por raptores y perdí la reliquia. No sé cuál de esas bestias se tragó la reliquia pero, si la recuperas, podré liberar el poder de esos artefactos.\n\nTráeme la Piedra de Relu y el fósil original.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "AstillacalaverasHoja reliquiaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][945] = {title = "La fuga de Therylune", objective = "Ayuda a escapar a Therylune y luego dile a Therysil, en el Santuario de Aessina, que su hermana está a salvo.", description = "¡Socorro!\n\nEstaba paseando por La Espada del Maestro cuando esos asquerosos del Culto me rodearon. ¡Menos mal que se me da bien esconderme!\n\n¿Puedes ayudarme a salir de aquí? También necesito avisar a mi hermana Therysil de que estoy bien. Está al sur, en Vallefresno, en el Santuario de Aessina.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][947] = {title = "La cueva de las setas", objective = "Lleva 5 boletos rudos y 1 oronja verde a Barithras Sombra Lunar a Auberdine.", description = "Estoy ideando una poción para la que necesito unas setas muy raras, unas que solo crecen en una cueva determinada. Esa cueva se encuentra más allá del Salto de Fonroca, al este y un poco al norte por las montañas.\n\nIría hasta allí en persona, pero en el Páramo de los Ancianos me aconsejaron que me mantuviera lejos de ese lugar. Nuestros venerables aliados creen que la cueva es el refugio de un nuevo mal de Costa Oscura.\n\nTe lo ruego, <nombre>, tráeme algunas de esas setas. Y aprovecha para explorar la cueva y confirmar los temores de los ancianos.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCapa de ráfagasChampiñón con motas rojas"}
MultiLanguageQuestData['mx'][951] = {title = "Las reliquias de Mathystra", objective = "Lleva 6 reliquias de Mathystra a Onus al Páramo de los Ancianos.", description = "El papiro que encontraste en La Espada del Maestro es una página de un antiguo texto escrito por los elfos. Está terriblemente mancillado por la corrupción del Martillo Crepuscular, pero parece que el Culto está sirviéndose de una antigua magia élfica para devolver a sus maestros a nuestro mundo\n\nViaja hacia el noreste, hasta las Ruinas de Mathystra y busca antiguas reliquias entre los hierbajos y las piedras. Estudiándolas, podríamos averiguar cómo pretende explotar el Martillo Crepuscular la magia de los elfos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Espada de leñadorCayada de madera duraRecibirás:\n\n"}
MultiLanguageQuestData['mx'][953] = {title = "La caída de Ameth'Aran", objective = "Estudia las tablillas que hablan de Ameth'Aran y de su caída y reúnete con la centinela Tysha Filoluna en Costa Oscura.", description = "Encontrarás las ruinas de Ameth'Aran hacia el este. Ahora las habitan los inquietos espíritus de los Altonato que en vida moraban entre sus muros, unos muros entre los que los siervos de Azshara practicaban libremente su poderosa magia.\n\nCuando me enviaron a explorar las ruinas encontré dos grandes tablillas con grabados que relataban la historia de Ameth'Aran y de su caída. Mientras leía las runas me abordaron los espíritus y tuve que huir.\n\nPor favor, si puedes, aventúrate entre las ruinas e intenta descifrar las tablillas en mi lugar.", progress = nil, completion = "We have few records from the time around the War of the Ancients, especially near the destruction of the Well of Eternity. Given the upheaval and cataclysmic events that were taking place, it is no big surprise.\n\nThank you, &lt;nombre&gt;. With your help, my work here is finished, and I will be able to deliver a full report to the Circle.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][954] = {title = "Bashal'Aran", objective = "Encuentra la fuente de la extraña aura azul en las Ruinas de Bashal'Aran.", description = "Las ruinas de Bashal'Aran, al este, están invadidas por esbirros demoníacos. Los espíritus y los sátiros que han establecido su morada en la zona se alimentan de la energía mágica del lugar. Sus poderes crecen continuamente.\n\nAun así, he notado que hay un santuario al que no se acercan jamás. En la parte occidental de las ruinas, sobre un pequeño acantilado, se ve una extraña aura azul... Debe haber una explicación a la reluctancia de los demonios.\n\nQuisiera que lo investigaras.", progress = nil, completion = "Ahh... To what could I possibly owe the exceedingly special honor of a &lt;raza&gt; such as yourself as company. Truly it says much of my current companions--with no offense to my hosts, the noble grells and satyrs--that your presence could be considered an improvement.\n\nBut please, do not let my uncivil tongue drive you from the place. It has indeed been many years, decades even, since I had civil accompaniment.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][957] = {title = "Bashal'Aran", objective = "Destruye el sello de piedra lunar antiguo en la antigua llama de Ameth'Aran y vuelve a reunirte con Asterion en Bashal'Aran.", description = "El sello que conforma mi prisión fue obra de uno de los Altonato más poderosos. En Ameth'Aran, al sur, hay unas ruinas idénticas a estas. En ellas persiste, incluso hoy, una antigua llama, una llama azul. Esa llama podría destruir el sello.\n\nPero no bajes la guardia en las ruinas, <nombre>...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Varita élficaLeotardos de vagabundoJubón de expedicionarioRecibirás:\n\n"}
MultiLanguageQuestData['mx'][958] = {title = "Las herramientas de los Altonato", objective = "Reúne 7 reliquias de los Altonato y llévaselas a Thundris Tejevientos a Auberdine.", description = "<clase>. Tengo que pedirte un favor.\n\n¿Has visto las ruinas de Ameth'Aran? Si no las has visto, las puedes encontrar en el lado este del camino principal, viajando hacia el sur. En otro tiempo fueron el hogar de los poderosos Altonato. Hoy son testimonios de la destrucción que sus errores produjeron.\n\nLos centinelas me han dicho que los espíritus de los Altonato persisten y que aún poseen sus antiguos instrumentos mágicos. Hemos de hacernos con esas reliquias para poder destruirlas.", progress = "If only the tools of their undoing could have been destroyed in the cataclysm that destroyed our world... Nonetheless, we must do what we can to ensure that the horrors of our past are not repeated in the future.", completion = "Though it is surely a figment of my imagination, I feel as though I can almost feel the taint of foul Highborne magic upon them. I will have these destroyed, so that their long dormant evil might never be released again.", rewards = "Recibirás:\n\nPuños de hiedra"}
MultiLanguageQuestData['mx'][959] = {title = "¡A por la botella!", objective = "El operador de grúa Pelardo de Trinquete quiere que le consigas una botella de Oporto con 99 años de antigüedad de Loco Magglish, que se esconde en las Cuevas de los Lamentos.", description = "¡Vaya!\n\n¡He tenido un pequeño percance, como puedes ver! El envío del carguero de la mañana de Bahía del Botín era enorme. ¡Lo que se dice enorme de verdad! Nunca había visto tantas cajas. Bueno, estaba intentando acelerar las cosas, así que empecé a descargar un poco más de lo que podía manejar. Y ahí es cuando todo se vino abajo.\n\nAntes de que me pudiera dar cuenta, vi que esa amenaza de Loco Magglish salía corriendo con una botella de Oporto con 99 años de antigüedad. Lo perseguí hasta las Cuevas de los Lamentos. Pero ni hablar de meterme en ellas.\n\n¿Eres suficientemente valiente para encontrarlo?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][962] = {title = "Reptilia", objective = "La boticaria Zamah de Cima del Trueno quiere que recojas 10 reptilias.", description = "La Sociedad Real de Boticarios, establecida en la gran Entrañas de Lordaeron, me ha enviado aquí con un propósito muy concreto, <nombre>. Quizás quieras ayudarme a mí y, de paso, también a la Dama Oscura en nuestro intento de mejorar la forma física de los Renegados.\n\nÚltimamente he estado estudiando una extraña planta llamada reptilia y creo que en grandes cantidades tiene un gran potencial.\n\nLamentablemente, la reptilia solo se encuentra en los recesos más oscuros de las Cuevas de los Lamentos, un sistema de cuevas muy peligroso situado en Los Baldíos.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGuantes de boticario"}
MultiLanguageQuestData['mx'][963] = {title = "Un amor eterno", objective = "Libera el espíritu de Anaia Correalba y lleva su colgante a Cerellean Zarpablanca a Auberdine.", description = "En el período que siguió a las batallas en el Pozo de la Eternidad, oí que Ameth'Aran había sido destruido y que su gente había muerto... y entre ellos, Anaia, mi amada.\n\nJamás habría pensado que, miles de años después, el recuerdo de Anaia seguiría atormentando mis sueños. Un día, deambulando por los bosques de Costa Oscura como en un letargo, me encontré en las ruinas de Ameth'Aran... y allí vi el espíritu atormentado de mi amada.\n\nDebo liberarla, pero me faltan las fuerzas. Sin embargo, su espíritu debe ser destruido.", progress = "With a great sorrow in my heart, I followed the Shan'do Stormrage into hibernation, and took my sorrow to my dreams, sleeping for the passing of thousands of years.", completion = "Thank you, &lt;nombre&gt;. Perhaps it would have been better... if I had done it myself. But even after these thousands of years, I could not bear to raise my hand against my beloved.\n\nPlease, I would be alone with my grief...", rewards = "Recibirás:\n\nLágrima de dolor"}
MultiLanguageQuestData['mx'][964] = {title = "Trozos esqueléticos", objective = "Lleva 15 trozos esqueléticos al boticario Dithers en El Baluarte, en las Tierras de la Peste del Oeste.", description = "La llave de Scholomance es la llamada Llave esqueleto. Debe forjarse a partir de los restos de un esqueleto (varios, en realidad) y endurecerse con los metales más fuertes en el molde adecuado. Un sello de poder obtenido de un ser que pueda abrir el portal de Scholomance por medios naturales será el último componente de la llave.\n\nPero empecemos por el principio, <nombre>. Necesitaremos trozos esqueléticos para forjar la llave. Los podrás obtener de los esqueletos que se encuentran dentro de Andorhal, aunque también deberían servirte los que están fuera de los muros de la ciudad.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][965] = {title = "La Torre de Althalaxx", objective = "Encuentra a Balthule Tenebroso cerca de La Torre de Althalaxx en Costa Oscura.", description = "Saludos, joven <raza>. Soy Elissa Brisa Estelar y soy la encargada de proteger Auberdine de todo mal.\n\nCon tal propósito envié a Balthule Tenebroso a observar los extraños sucesos de la Torre de Althalaxx, al noreste.\n\nY ya debería haber regresado. Me preocupa que haya encontrado algún peligro imprevisto en el bosque. Apreciaría sobremanera que fueras en su busca y te aseguraras de que se encuentra bien.", progress = nil, completion = "Elissa sent you? Then it is good tidings you bring. I have troubling news to report to her, and had no means with which to deliver it.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][967] = {title = "La Torre de Althalaxx", objective = "Entrega la carta de Balthule a Delgren el Purificador que está en el Bosque de Vallefresno.", description = "Mi maestro, Delgren el Purificador es un paladín que ha ofrecido gentilmente su ayuda en la defensa de nuestros bosques de los demonios y los no-muertos. Me ha enseñado mucho sobre la Luz Sagrada y el arte de la guerra.\n\nDelgren debe saber de las operaciones del culto cuanto antes.\n\nLo encontrarás al sur de aquí, en la Atalaya de Maestra del Bosque de Vallefresno. Debes apresurarte: la amenaza de la Facción Oscura crece cada hora.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][968] = {title = "Los Poderes Subyacentes", objective = "Lleva el libro Los Poderes Subyacentes a Gerrig Agarrahueso a La Caverna Abandonada, en Forjaz.", description = "Aunque la cubierta de este libro está gastada y arañada, aún se puede leer el título:\n\nLos Poderes Subyacentes\n\nEn el interior del libro hay una lista de nombres impronunciables con títulos terribles, rituales de adoración y sacrificios preferidos... muchos de los cuales incluyen criaturas vivas, humanoides.\n\nEn la cubierta interior del libro hay unas palabras escritas: \"Runas y Maldiciones de Agarrahueso, La Caverna Abandonada, Forjaz. Propiedad de: Gerrig Agarrahueso.\"\n\nSi Agarrahueso vende libros de este tipo, quizás me vuelva a comprar este.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][969] = {title = "ue la suerte sea contigo", objective = "Recoge 4 esquirlas de Machacahielo para la médica bruja Mau'ari de Vista Eterna.", description = "Ah, verte basta para saber que lo que quieres es un talismán de la suerte. ¡Mau'ari todo sabe!\n\nAl Sur, encontrarás un cañón y gigantes hechos de hielo duro. A veces los gigantes las llevan, pero puedes recoger tú <mismo/misma> las esquirlas en el cañón. Las esquirlas tienen una poderosa cualidad reflectante.\n\nTráeme 4 esquirlas de los Machacahielo y mi talismán de la suerte será tuyo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][970] = {title = "La Torre de Althalaxx", objective = "Reúne una gema de alma resplandeciente y vuelve junto a Delgren el Purificador en la Atalaya de Maestra.", description = "La carta de Balthule es espantosa. Este culto de la Facción Oscura es una espina clavada que debo eliminar. Me las he visto con algunos de los miembros de la Facción Oscura al noreste de este lugar, en Ordil'Aran. Uno de ellos posee una gema de almas que, creo, guarda el secreto del poder del culto.\n\nTráemela y podré descifrar el secreto de su interior.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][971] = {title = "Conocimiento en las Cavernas", objective = "Lleva el manuscrito de Lorgalis a la centinela practicante Issara que está en el Campamento Brazanegra.", description = "Recopilo conocimiento. Conocimiento antiguo. Conocimiento con poder. Conocimiento que abre puertas y puede despertar a los Durmientes si no se maneja con cuidado.\n\nSe dice que un antiguo documento, el manuscrito de Lorgalis, se halla en las Cavernas de Brazanegra al oeste. Es el hogar de nuestros antepasados que murieron hace mucho. Acumularon mucha sabiduría antes de que su ciudad se arruinara.\n\nBusca el manuscrito en las Cavernas de Brazanegra. Nunca olvidaré este favor. Ni siquiera después del fin de los días.", progress = nil, completion = "¡Encontraste el manuscrito! ¡Oh, qué dicha! ¡Haremos copias para que el conocimiento antiguo de Lorgalis se distribuya entre mis hermanos y hermanas!\n\nTu servicio es invaluable para nosotros, &lt;nombre&gt;. Pero espero que este regalo sirva como ejemplo de la gratitud que tenemos con nuestros aliados.", rewards = "Arco del Manto de la NocheCapa manchada de polvoPodrás elegir una de estas recompensas:\n\nBanda anochecedora\n\nTambién recibirás:\n\nAnillo de apoyo"}
MultiLanguageQuestData['mx'][973] = {title = "La Torre de Althalaxx", objective = "Llévale el Libro de Ilkrud Magthrull a Delgren el Purificador en la Atalaya de Maestra.", description = "Ilkrud Magthrull. Sí, sé algo acerca de él. Es un poderoso orco brujo que mora en el Santuario de la Escara, un lugar de extrema maldad al suroeste de Vallefresno.\n\nHasta ahora no había pasado de ser una molestia menor y no he tenido que tratarlo pero, por lo visto, ha llegado su hora.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Bastón del PurificadorPodrás elegir una de estas recompensas:\n\nAnillo de clero\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][974] = {title = "Busca la fuente", objective = "Krakle, en el Cráter de Un'Goro, quiere que encuentres la zona más caliente de la Cresta del Penacho en Llamas.\n\nSiempre que des con un punto caliente, pulsa con el botón derecho sobre el termómetro para comprobar la temperatura. Sigue buscando hasta que encuentres el punto más caliente.", description = "Las fuentes termales de esta zona son un auténtico misterio. ¿De dónde viene el calor?\n\nTeniendo en cuenta su proximidad con las fuentes de la Cresta del Penacho en Llamas, me pregunto si el volcán puede tener algo que ver. He creado un termómetro para tomar lecturas de las temperaturas del volcán y me gustaría localizar la zona más caliente. ¡Mide las temperaturas en grados Kraklenheit!\n\nToma, cógelo, ¡y haz mediciones de las temperaturas en la cresta cada vez que localices una zona caliente!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][976] = {title = "Suministros a Auberdine", objective = "Habla con Delgren el Purificador en la Atalaya de Maestra después ayudar a Feero a cruzar el Bosque de Vallefresno y dejarlo a buen recaudo.", description = "Delgren me ha pedido que le entregue varios mensajes y unos suministros a la centinela Brisa Estelar en Auberdine pero odio marcharme solo. Peligrosos enemigos acechan en el bosque y no me gustaría correr el riesgo de que esta información y estos suministros cayeran en manos malintencionadas.\n\nSi tú y alguien más pudieseis ser mis guardias, podría marcharme ahora. Con tu protección, seguro que estas cosas llegarán a buen puerto en Auberdine.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Peto de KorPodrás elegir una de estas recompensas:\n\nLinterna eterna\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][978] = {title = "Lechúcico Lunadón", objective = "Recoge 10 plumas Lunadón de Cuna del Invierno y regresa con Erelas Cieloámbar en Aldea Rut'theran.", description = "Las plumas de lechúcico salvaje de las Tierras del Interior parecen tener rastros de cualidades mágicas. Estos poderes... no parece que las criaturas se valgan de ellos, es más bien algo inherente a la especie... parte de su esencia.\n\nDurante mis estudios pude oír que hay un gran número de lechúcicos salvajes en las tierras nevadas de Cuna del Invierno. ¿Tendrán esas criaturas los mismos poderes? Por favor, ayúdame a encontrar una respuesta, <nombre>. Ve a Cuna del Invierno y recoge del suelo las plumas que se hayan caído. Cuando las tengas, vuelve a verme.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][980] = {title = "Nuevos manantiales", objective = "Viaja hasta Cuna del Invierno y habla con Donova Cubilnevado.", description = "Bien, he oído hablar de otras fuentes termales en un lugar llamado Cuna del Invierno, muy al norte de aquí. Lo extraño es que no hay volcanes cerca de ellas. Interesante, lo sé.\n\nBien, si quieres averiguar más cosas, deberías ir a Cuna del Invierno y hablar con una amiga mía llamada Donova Cubilnevado, se encuentra junto a las fuentes termales de esa zona.\n\n¡Gracias de nuevo por ayudarme con mi termómetro! ¡Hasta la vista!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][982] = {title = "Profundo océano, mar inmenso", objective = "Recupera el arcón del Amanecer de Plata y la caja fuerte del Halo de Bruma para Gorbold Mano de Acero de Auberdine. Ambos objetos deberían estar en los cascos de los navíos naufragados al norte de la aldea.", description = "En Costa Oscura, al norte de aquí, naufragaron dos barcos, el Amanecer de Plata y el Halo de Bruma. Hace un tiempo, los dos barcos fueron abordados por unos múrlocs cuando navegaban hacia Auberdine. Ahora yacen en el fondo del océano como trofeos de esos demonios.\n\nLos capitanes no sobrevivieron y sus cuadernos de bitácora y otros efectos aún siguen en sus cajas fuertes. Me gustaría que los recuperaras para nosotros. Es importante para los miembros de la tripulación que aún están por aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de gota de pozoGuanteletes de NoosegripRecibirás:\n\n"}
MultiLanguageQuestData['mx'][983] = {title = "La caja mecánica 827", objective = "Reúne 6 patas de reptador y colócalas en la caja mecánica 827.", description = "¡Eh! Necesito ayuda con mi último invento, la caja mecánica. ¡Sirve para hablar con gente que está lejos!\n\nPuede que hayas visto alguna ya. Son unas cajas con muchas palancas. El problema que tienen es que necesitan un mantenimiento constante.\n\nCada una tiene un problema diferente, pero yo he hecho una cosa muy inteligente. He colocado cada caja cerca de las criaturas que tienen las piezas adecuadas para repararlas. Y ahora, hay que reparar la caja mecánica 827. Está al sur de Auberdine, muy cerca. Hacen falta 6 patas de reptador para arreglarla. Te pagaré...", progress = "Buzzbox 827 sits with an eerie silence. A single flashing light indicates that it needs 6 Crawler Legs to be placed in its holding box.", completion = "As you place the Crawler Legs inside the machine, you hear gears begin to grind. Judging from the banging sounds coming from the Buzzbox, you believe the Crawler Legs are being put in their proper place. Soon the machine begins to hum, and you hear a tiny voice calling out from within.\n\n\"Hello? Uhh... Hello! You fixed it! This is Wizbang by the way! Thanks a lot... Hey, you wouldn't want to fix another one, would ya?\"", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][984] = {title = "La extensión de la amenaza", objective = "Encuentra el campamento de fúrbolgs corruptos en Costa Oscura, vuelve a Auberdine y busca a Terenthis.", description = "Algunos de mis hermanos fueron salvados de un fúrbolg corrupto en Teldrassil y yo he jurado impedir otras atrocidades. No permitiré que los nuestros resulten heridos... o algo peor.\n\nYa he detectado un par de indicios de corrupción en Costa Oscura, pero aún he de encontrar signos de que se haya extendido. Creo que lo lógico sería continuar la investigación con los fúrbolgs. ¿Podrías buscar alguno de sus campamentos y decirme si has visto algún signo de corrupción?", progress = nil, completion = "This is terrible news indeed, &lt;nombre&gt;.\n\nWith the furbolgs this close to Auberdine, we will have to prepare ourselves for the inevitable.\n\nThank you, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][985] = {title = "La extensión de la amenaza", objective = "Mata a 5 soplavientos y a 8 abrecaminos Bosque Negro y vuelve a Auberdine a buscar a Terenthis.", description = "Ya has demostrado que sabes rastrear a nuestros enemigos, <nombre>. ¿Crees que también podrás enfrentarte a ellos?\n\nLo pregunto porque algunos aventureros prefieren eludir el combate directo...\n\nSi crees que estás a la altura de la tarea, puedo decirte que la mayor amenaza para nuestra gente proviene del campamento que hay al sur de Auberdine. Allí encontrarás una parte de la tribu Bosque Negro. Mata a 8 abrecaminos y a 5 soplavientos y vuelve aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][986] = {title = "El maestro perdido", objective = "Encuentra 5 pelambres de Acechalunas refinadas y llévaselas a Terenthis a Auberdine.", description = "<nombre>, con tus habilidades me has ayudado mucho en mi empresa. ¿Podría abusar una vez más de tu buena disposición y pedirte que ayudes a Zarpadura y a su maestro Volcor? Puedo crear para ti una capa mágica que te permitirá caminar entre las criaturas de Costa Oscura sin ser <detectado/detectada>.\n\nPero para tener suficiente material para crear la capa necesitaré 5 buenas pelambres de algún patriarca acechalunas o de una matriarca acechalunas. Puedes encontrar felinos de esos al sur, cerca del Río Culebra o cerca de Vallefresno, más al sur todavía.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][991] = {title = "Encontrar a Teronis", objective = "Encuentra a Teronis en el Lago Falathim en Vallefresno.", description = "Una amiga mía de Astranaar, Raene Correlobo, me pidió que enviara a un explorador al oeste, a Lago Falathim. Teronis se fue hace días, antes de que atacara la Horda.\n\nBuscaba un objeto que creía que podía detener los ataques de los fúrbolgs sobre nuestra gente: una vara creada por un difunto mago malvado.\n\nAntes de irse mencionó una gema para la vara; según él, estaría en un templo en una isla del lago.\n\nPor desgracia, ahora sabemos que una fuerza maligna ha invadido el lago. Por favor, <nombre>, encuentra a mi amigo.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][992] = {title = "Un estudio de agua de Gadgetzan", objective = "Utiliza la pipeta de muestras abierta en la poza de agua de Vigía Penas de Arena. Cuando hayas recogido la muestra, llévale la pipeta de muestras cerrada al perito jefe Picoflojo, que está en Gadgetzan.", description = "Por si te interesa, tenemos un puesto vacante para perito adjunto temporal en la compañía de aguas de Gadgetzan.\n\nDado que los nómadas se aprovechan de nuestros pozos, tenemos que explotar más fuentes gratuitas de agua. En el desierto hay agua pero solo para aquellos que sepan encontrarla.\n\nCoge esta pipeta y toma una muestra del agua de la poza situada al lado de Vigía Penas de Arena. Está a la vista de los trols que andan por allí. ¡Tráeme la pipeta cerrada cuando hayas acabado!", progress = "¡Bienvenido de nuevo, perito adjunto <nombre>! ¿Ya has terminado tu tarea?", completion = "¿Cómo? ¿Te han tendido una emboscada una especie de bichejos de mojo malo? Vaya, esto no augura nada bueno para la compañía de aguas de Gadgetzan... \n\nSupongo que tenía que haberte hablado de los peligrosos bichos que al parecer están consumiendo toda el agua del desierto. Al principio, le resté importancia pues ya tenemos bastantes problemas con los nómadas y creí que era una más de sus artimañas. Al menos ahora sabemos lo que está pasando.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][997] = {title = "Las tierras de Denalan", objective = "Llévale el paquete con tierras raras a Denalan, que está en el Lago Al'Ameth.", description = "¿Te diriges hacia el sur? ¿Al Lago Al'Ameth? De ser así hay algo que quiero pedirte...\n\nMi compañero Denalan tiene un campamento en el extremo oriental del lago, donde está estudiando y haciendo experimentos con la flora de Teldrassil. Encargó un paquete con tierras raras de Darnassus que llegó con retraso pues no hace mucho que lo recibimos aquí en Dolanaar.\n\n¿Podrías llevarle tú el paquete?", progress = "¿Tienes algo para mí?", completion = "¡Ah, aquí está! Llevo tiempo esperando este paquete con tierra rara. Espero que todavía esté en buen estado... \n\nGracias por traérmela, &lt;nombre&gt;. Eres un &lt;raza&gt; comprometido con su tiempo.", rewards = "Te van a lanzar el siguiente hechizo:\n\nTrigger Denalan, Denalans Earth Turn-in\n\nRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][1000] = {title = "La nueva frontera", objective = "Habla con el archidruida Hamuul Tótem de Runa en el Alto de los Ancestros de Cima del Trueno acerca de la llamada del Círculo Cenarion para explorar las fronteras de Kalimdor.", description = "¡Atención, héroes!\n\n¡El Círculo Cenarion busca voluntarios sanos para que les ayuden a explorar las vastas nuevas fronteras de Kalimdor! Al oeste de Tanaris y Gadgetzan se extiende un páramo lleno de inimaginables peligros. El Círculo necesita voluntarios honorables para explorarlos en su lugar.\n\nTodos aquellos que estén interesados pueden solicitar audiencia con el Círculo Cenarion. ¡Hablad con el archidruida Hamuul Tótem de Runa en el Alto de los Ancestros en Cima del Trueno para más información!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1001] = {title = "La caja mecánica 411", objective = "Consigue 3 ojos de trillador de los trilladores de Costa Oscura en las profundidades del mar, cerca de la caja mecánica 411.", description = "Del interior de la máquina sale una vocecita.\n\n\"¡Soy Zumbang! La siguiente caja mecánica está al norte de Auberdine, en la playa.\n\nEs la número 411 y requiere 3 ojos de trillador para ser reparada. ¡Están cerca de la costa! Los trilladores de Costa Oscura... *Hip*... Uy, perdón...\n\nComo la vez anterior, cuando le das los artículos a la caja mecánica, te escupe tu recompensa. *Hip*... ¿Qué? No, ¡estoy bien!\"", progress = "The machine's hatch is open and it seems to wait expectantly for 3 Thresher Eyes to be placed inside.", completion = "The Buzzbox hums to life soon after you place the Thresher Eyes inside. There is a moment of static before you hear a familiar tiny voice call out.\n\n\"Crawler wine is the best...\" *hic*\n\n\"What? Oh, you fixed it already? Wow, you're a fasht one. Sho, would ya like to fix another?\"\n\nYou believe you hear a liquid being poured into a cup, followed by loud gulping sounds.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1004] = {title = "La nueva frontera", objective = "Habla con el archidruida Hamuul Tótem de Runa en el Alto de los Ancestros de Cima del Trueno acerca de la llamada del Círculo Cenarion para explorar las fronteras de Kalimdor.", description = "¡Atención, héroes!\n\n¡El Círculo Cenarion busca voluntarios sanos para que les ayuden a explorar las vastas nuevas fronteras de Kalimdor! Al oeste de Tanaris y Gadgetzan se extiende un páramo lleno de inimaginables peligros. El Círculo necesita voluntarios honorables para explorarlos en su lugar.\n\nTodos aquellos que estén interesados pueden solicitar audiencia con el Círculo Cenarion. ¡Hablad con el archidruida Hamuul Tótem de Runa en el Alto de los Ancestros en Cima del Trueno para más información!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1007] = {title = "Las antiguas estatuillas", objective = "Consigue 10 estatuillas antiguas.", description = "Te encargaría una tarea, <clase>.\n\nEstaba en mi barca, navegando sobre las sumergidas ruinas de Zoram, cuando los nagas me atacaron ¡surgiendo del agua y tratando de hacerme jirones con sus garras! Me escapé y el resto, según dicen, es historia.\n\nSoy una especie de arqueólogo, y estoy intentando recuperar algunos artefactos de la ciudad perdida.\n\n¿Irías a La Ensenada de Zoram, al suroeste, para recuperar las estatuillas antiguas que encuentres? Ellas son la razón por la que me enfrenté a los peligros de La Ensenada de Zoram.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1008] = {title = "La Ensenada de Zoram", objective = "Llévale 20 cabezas de Colafuria a Shindrell Fuegoveloz en Astranaar.", description = "El mal nos acecha desde la costa noroeste conocida como La Ensenada de Zoram.\n\nEs el lugar de descanso de la ciudad maldita de Zoram, destruida en el Diluvio y desde entonces sumergida bajo los mares. Se perdió para los elfos de la noche durante siglos. Perdida y casi olvidada.\n\nAhora, los nagas han regresado y en cuanto a sus motivos... los ignoramos. Pero el porqué importa poco; debemos ejecutar a estos desalmados ¡y devolverlos a los abismos!\n\nVuelve a mí cuando hayas completado tu misión.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1009] = {title = "Ruuzel", objective = "Consigue el Anillo de Zoram.", description = "Temo que los secretos de las estatuillas antiguas permanecerán ocultos para siempre a menos que encuentres las llaves de su cerradura antigua.\n\nELa llave es un anillo, el anillo de Zoram. Les perteneció a los gobernadores de la ciudad antes de que las olas del Cataclismo la hundieran.\n\nDurante años, la ubicación del anillo fue un misterio, pero los naga lo encontraron hace poco.\n\nSu líder, Ruuzel, habita en una isla en la frontera norte de Zoram. Por favor, <nombre>, ¡recupera el anillo por mi!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nTogas de Antigüedad"}
MultiLanguageQuestData['mx'][1010] = {title = "Cabello de Bathran", objective = "Consigue 8 cabellos de Bathran.", description = "Existe una planta que crece entre las Ruinas de Bathran al otro lado de la carretera, al este. La planta se llamaba cabello de Bathran y era famosa por curar enfermedades espirituales.\n\nAhora la Horda se dedica a recolectarla para sus propios planes malvados.\n\nHay una niña enferma en Astranaar y creo que se trata de algo más que una enfermedad física. Prometí a mi maestro que ayudaría a encontrar una cura, pero no soy un guerrero.\n\n¿Irás a las Ruinas de Bathran a por las plantas?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1011] = {title = "Los males de los Renegados", objective = "Llévale una botella de enfermedad a Kayneth Ventoleve en Canción del Bosque.", description = "Los Renegados, el brazo de no-muertos de la Horda, se han infiltrado en Vallefresno y merodean entre nuestras ruinas y túmulos. Creemos que su objetivo es propagar enfermedades por la tierra de los elfos de la noche. ¡Tenemos que saberlo con seguridad!\n\nLos Renegados tienen un campamento al sur de este lugar, cerca de El Túmulo de Dor'danil, donde crean venenos y enfermedades y los embotellan. Infíltrate en su campamento y roba una botella de enfermedades. Vuelve con esa botella. La probaré y averiguaré para qué sirve.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1012] = {title = "Druidas dementes", objective = "Mata a los druidas enloquecidos: Taneel Leñoscuro, Uthil Llamaluna y Mavoris Quiebranubes.", description = "Los druidas han muerto a manos de sus líderes, que enloquecieron cuando la Horda corrompió el corazón del bosque. Puedo sentir la corrupción incluso desde aquí y no me atrevo a ir más allá.\n\nMientras que yo me armonizo con Vallefresno y el corazón del bosque, tú podrías... bajar hasta el túmulo y hacer lo debido. Te he dejado algunas pistas por allí.\n\nBien que me pese, debo pedirte que hagas descansar en paz a Taneel Leñoscuro, Uthil Llamaluna y Mavoris Quiebranubes, los que un día fueron grandes líderes druidas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nEnseña de Emil"}
MultiLanguageQuestData['mx'][1013] = {title = "El Libro de Ur", objective = "Lleva el Libro de Ur al vigilante Bel'dugur al Apothecarium de Entrañas.", description = "<nombre>, en el Castillo de Colmillo Oscuro hay un libro que deseo para mi colección: el Libro de Ur. Ur era un gran mago de Dalaran antes de que llegara la Plaga; sus estudios sobre otros mundos son muy valiosos para... ciertas facciones entre los Renegados.\n\nVe al Castillo de Colmillo Oscuro y tráeme el libro. Informaré a la Dama Oscura de tus servicios...", progress = "¿Encontraste el libro, <nombre>?", completion = "Perfecto; esto completa mi colección de obras de Ur. Era sabio, pero su conciencia lo mantenía alejado del poder verdadero. Así, cuando la Plaga lo puso a prueba, falló. \n\nLos Renegados no podemos permitirnos tal debilidad. \n\nNo si queremos vencer.", rewards = "Brazales con cierre de aceroBotas grisáceasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1014] = {title = "Arugal debe morir", objective = "Mata a Arugal y lleva su cabeza a Dalar Tejealba en El Sepulcro.", description = "Arugal sigue viviendo en el Castillo de Colmillo Oscuro. No podemos reclamar Argénteos como bastión estratégico para la Dama Oscura hasta que no hayamos matado a Arugal.\n\nMe encargaré de erradicar su magia, <nombre>. Pero dejo en tus manos que Arugal se encuentre con la muerte que tanto merece.\n\nVe al Castillo de Colmillo Oscuro y pon fin de una vez por todas a los terribles hechizos de Arugal. ¡Tráeme la cabeza del malvado mago!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de Sylvanas"}
MultiLanguageQuestData['mx'][1015] = {title = "La nueva frontera", objective = "Habla con el archidruida Fandral Corzocelada en el Enclave Cenarion de Darnassus sobre la llamada del Círculo Cenarion para explorar las fronteras de Kalimdor.", description = "¡Atención, héroes!\n\n¡El Círculo Cenarion busca voluntarios sanos para explorar las vastas fronteras nuevas de Kalimdor! Al oeste de Tanaris y Gadgetzan se extiende un páramo lleno de inimaginables peligros. El Círculo necesita voluntarios honorables para explorarlos en representación suya.\n\nTodos aquellos que estén interesados pueden solicitar audiencia en el Círculo Cenarion. ¡Hablad con el archidruida Fandral Corzocelada de Darnassus para más información!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1016] = {title = "Retomar el Lago Mystral", objective = "Mata a 12 elementales de agua podrida y marearess.", description = "Podríamos haber defendido el Refugio Brisa de Plata si la Horda no se hubiera adueñado de nuestros elementales de agua del Lago Mystral.\n\nUno de sus chamanes invocó a Marearess, un antiguo y rencoroso espíritu del agua que contaminó a nuestros elementales y los volvió en nuestra contra. Frente al ataque del lago y de la Horda, no tuvimos más remedio que retirarnos a esta torre.\n\nVe al este. Retoma el lago para que algún día podamos recuperar el refugio.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1017] = {title = "Mago invocador", objective = "Mata a Sarilus Fuenteviciosa y lleva su cabeza a la centinela Velene Golpe Estelar en el Refugio Brisa de Plata.", description = "Solo hay un mago no-muerto en Los Baldíos capaz de envilecer a tantos elementales de agua. También es el único lo suficientemente inconsciente para intentarlo. Sarilus Fuenteviciosa probablemente se encuentre en la cumbre de Cima Calígine, riéndose de mí.\n\n<nombre>, debes aventurarte en territorio enemigo y acabar con ese malhechor. Ya estoy cansada de su insensatez y tenemos que demostrarle lo que les ocurre a quienes irritan a las centinelas.\n\n¡Destrúyelo y tráeme su cabeza! Ve con cuidado, la Horda podría estar vigilándote.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nLuz de Elune"}
MultiLanguageQuestData['mx'][1018] = {title = "La nueva frontera", objective = "Habla con el archidruida Hamuul Tótem de Runa en el Alto de los Ancestros de Cima del Trueno acerca de la llamada del Círculo Cenarion para explorar las fronteras de Kalimdor.", description = "¡Atención, héroes!\n\n¡El Círculo Cenarion busca voluntarios sanos para que les ayuden a explorar las vastas nuevas fronteras de Kalimdor! Al oeste de Tanaris y Gadgetzan se extiende un páramo lleno de inimaginables peligros. El Círculo necesita voluntarios honorables para explorarlos en su lugar.\n\nTodos aquellos que estén interesados pueden solicitar audiencia con el Círculo Cenarion. ¡Hablad con el archidruida Hamuul Tótem de Runa en el Alto de los Ancestros en Cima del Trueno para más información!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1019] = {title = "La nueva frontera", objective = "Habla con el archidruida Fandral Corzocelada en el Enclave Cenarion de Darnassus sobre la llamada del Círculo Cenarion para explorar las fronteras de Kalimdor.", description = "¡Atención, héroes!\n\n¡El Círculo Cenarion busca voluntarios sanos para explorar las vastas fronteras nuevas de Kalimdor! Al oeste de Tanaris y Gadgetzan se extiende un páramo lleno de inimaginables peligros. El Círculo necesita voluntarios honorables para explorarlos en representación suya.\n\nTodos aquellos que estén interesados pueden solicitar audiencia en el Círculo Cenarion. ¡Hablad con el archidruida Fandral Corzocelada de Darnassus para más información!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1021] = {title = "¡Vil sátiro! ¡Dríades en peligro!", objective = "Encuentra a Anilia en Xavian, en Vallefresno.", description = "No sé de dónde has salido, pero necesito que me ayudes. Mis hermanas se fueron a quitarle la Rama de Cenarius al sátiro. Dijeron que volverían pronto, ¡pero hace ya dos días que se fueron!\n\n¡Encuéntralas, <nombre>! Iban a buscar las ruinas de un templo de los elfos de la noche en Xavian, al noroeste. Busca a Anilia, era la líder del grupo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1022] = {title = "La Vega del Aullido", objective = "Ve a La Vega del Aullido y estudia el Libro de Mel'Thandris, vuelve entonces junto a la Centinela Melyria Sombrigélida en la Canción del Bosque.", description = "Aunque hemos puesto muchos recursos y esfuerzo en expulsar hacia el norte a los demonios restantes en Frondavil, no hemos tenido mucho éxito. Hemos logrado mantener apartados de Vallefresno a casi todos los demonios.\n\nHacia el norte, cerca de los límites de Frondavil, el altar en ruinas de Mel'Thandris ha sido tomado por unos misteriosos hombres lobo. Sus llamadas te hielan la sangre y han hecho que se conozca esa zona como la Vega del Aullido. Es posible que el Libro de Mel'Thandris que se conserva en el altar arroje algo de luz sobre el motivo que ha traído a estos hombres lobo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1024] = {title = "La entrega a la dríade", objective = "Habla con Shael'dryn en la Torre de la Algaba en Vallefresno.", description = "Ah, ahí estás, <nombre>. He leído con cautela las notas que redactó Teronis y parece que tu siguiente paso será encontrar las demás piezas de la vara de Dartol.\n\nYo empezaría por dirigirme al este por el camino que conduce a la Torre de la Algaba.\n\nUna dríade llamada Shael'dryn podrá indicarte mejor. Búscala.\n\nLleva la gema contigo, Shael'dryn la necesitará si te va a ayudar a recrear la vara.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1025] = {title = "Una defensa agresiva", objective = "Mata a 1 vigía del cubil, 2 ursas, 10 totémicos y 12 guerreros de la tribu de los Maderiza y vuelve junto a Raene Correlobo en Astranaar.", description = "Antes de que vayas a la Poza de la Luna, tengo otra tarea que ayudará al pueblo de Vallefresno si te apetece poner a prueba tus habilidades.\n\nPor la carretera que va hacia el este antes de llegar al Río Falfarren, los fúrbolgs han estado asaltando a los viajeros. Sus torturadas mentes alimentándose del miedo y su apetito saciándose con sangre inocente.\n\nAyuda a las centinelas a proteger las tierras mostrando hacia esos monstruos la misma misericordia que ellos para con los de nuestra clase.\n\nMe parece que sus campamentos están al sur de la carretera... ve con cuidado.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPan de maíz húmedoZumo de melón"}
MultiLanguageQuestData['mx'][1026] = {title = "¿Dónde están las llaves?", objective = "Encuentra la llave de madera y úsala para conseguir un trozo de asta de hierro de la vara de Dartol.", description = "Ojalá tus nuevas fueran mejores.\n\nRaene tiene razón, he oído hablar de la creación de Dartol y de los antárboles de la región, al menos una vez. Ahora se han corrompido, su naturaleza se ha pervertido.\n\nPara encontrar la siguiente pieza de la vara, tendrás que encontrar la llave que abre el cofre en el que se encuentra.\n\nLa llave de madera está en uno de los antárboles al noreste desde aquí, en la Vega del Aullido, cerca de los límites de Frondavil. Cuando la tengas, busca un pequeño claro en la vega a través del túnel. El cofre debería estar escondido por ahí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1027] = {title = "Hacerse el muerto", objective = "Consigue el pomo de hierro, la última pieza de la vara de Dartol.", description = "Los druidas de la Zarpa poseen la última pieza de la vara. Cuando pedí a su líder, Oso Rajazarza, que la devolviera, ¡casi me matan sus guardias! Se les veía claramente afectados por la corrupción del corazón del bosque perpetrada por la Horda.\n\nSin embargo, tengo una idea sobre cómo puedes introducirte en la cueva de Oso y obtener la empuñadura.\n\nDesde que era un fauno, se me ha dado bastante bien hacerme el muerto. ¡Funciona de maravilla con los osos! ¡Te puedo enseñar! Dirígete hacia el este a El Rincón Lóbrego, y si intentan atraparte, utiliza mi técnica.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Brazales de Shael'drynBotas de pies muertosBrazales de disecciónRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1030] = {title = "La vara de Dartol", objective = "Usa la vara de Dartol para comunicarte con Krolg en la Cabaña de Krolg, en Vallefresno.\n\nObjeto provisto: \n", description = "No estoy del todo segura de cuál era la intención de Teronis. Si era cierto lo que contaba del poder de la vara, entonces hasta te permitirá adoptar otra forma, probablemente la de un fúrbolg.\n\nQuizás pretendía usar sus poderes para acercarse a ellos, pero incluso la criaturas sin corromper lo asesinarían si no iba con cuidado. Transformado gracias a la vara, Dartol tendría que hablar con un fúrbolg que no estuviera corrupto.\n\nEmpezaría la búsqueda por uno al que llaman Krolg. Encontrarás su cabaña al sureste del Lago Mystral.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1031] = {title = "La Rama de Cenarius", objective = "Consigue la Rama de Cenarius.", description = "Anilia te pone las manos en los hombros y te acerca. Entre jadeos, señala el arco al norte, antes de que sus ojos se cierren y el último soplo de vida salga de su boca. \"Se la ha llevado... Geltharis...\" En tu corazón sabes que el deseo póstumo de Anilia es que la Rama de Cenarius vuelva a las manos de la dríade.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Manto feéricoFaja de escamas brillantesRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1032] = {title = "¡Muerte a los sátiros!", objective = "Consigue 16 cuernos de sátiro.", description = "No puedo creer que Anilia ya no esté... Solíamos pasarnos los días jugando juntas en el bosque. Casi siento... tristeza.\n\nSé de algo que podría hacer que me sienta mejor. ¡Por favor, ejecuta a los sátiros que me han arrebatado a Anilia! Tráeme sus cuernos como prueba de tus actos y tendrás mi gratitud eterna.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1033] = {title = "Lágrima de Elune", objective = "Consigue la lágrima de Elune.", description = "Esperaba que la cura de Orendil salvara a Relara pero me temo que solo ha frenado su enfermedad. ¡Tenemos que encontrar una medicina más eficaz! Por suerte, Orendil me habló de otros remedios que debía intentar si el suyo no funcionaba.\n\nLa lágrima de Elune es un tipo de piedra que solo se halla en un lugar: las ruinas del Lago Iris, destruidas por la erupción del Pico del Trueno, al noreste de Astranaar. Orendil dijo que la piedra se llevaría la corrupción.\n\nPor favor, <nombre>, ¡tráeme la lágrima de Elune y reza para que acabe con la enfermedad de mi niña!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1034] = {title = "Las Ruinas del Polvo Estelar", objective = "Llévale 5 puñados de polvo estelar a Pelturas en Astranaar.", description = "La lágrima de Elune logró curar en parte la enfermedad de mi hija. Tiene menos pesadillas y le estoy agradecido a la diosa por su bendición. Pero... sigue teniendo la fiebre muy alta.\n\nOrendil me habló de un polvo de escarcha que se encuentra en Las Ruinas del Polvo Estelar. Quizás mitigue la fiebre de Relara. Te ruego que consigas un poco de ese polvo y me lo traigas.\n\nLas Ruinas del Polvo Estelar se encuentran en el sur, <nombre>. Que Elune haga breve tu viaje.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1035] = {title = "Lago Cielo Estrellado", objective = "Recupera una piedra lunar caída del Oráculo Sombramatorral y llévasela a Pelturas en Astranaar.", description = "La fiebre de Relara ya queda atrás, pero todavía sigue débil. No creo que con el tiempo solamente logre recuperar la energía perdida. Creo que va a necesitar la energía de una piedra lunar.\n\nLas solíamos recoger en el Lago Cielo Estrellado, al sureste... hasta que los Sombramatorral llegaron.\n\nSu líder, un oráculo Sombramatorral, recogió todas las que había y las esconde como su tesoro. Tu misión consiste en recuperar una.\n\nY para hacerlo, creo que deberás matar al líder.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Armadura riachueloEsposas bestialesAmito luminiscenteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1036] = {title = "¡Adelante, pillín!", objective = "Habla con el maestro de flota Firallon a bordo de El Velo Carmesí cerca de la costa de la Vega de Tuercespina.", description = "<nombre>... sí, he oído hablar de ti. Me han dicho que no eres <amigo/amiga> de la Bahía del Botín, igual que nosotros, los Bucaneros Velasangre. El maestro de flota Firallon está buscando reclutas robustos y fuertes como tú para una misión especial.\n\nSi te interesa, dirígete a El Velo Carmesí y habla con él bajo cubierta. Está en La Costa Salvaje, al este de aquí, junto a Las Mareas Vivas y La Damisela Afortunada.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1037] = {title = "Velinde Cantoestelar", objective = "Habla con Thyn'tel Tejespada en el Bancal del Guerrero en Darnassus.", description = "Velinde Cantoestelar era mi predecesora aquí en el Bosque de Vallefresno. Al principio parecía que tenía la situación en Frondavil bajo control pero poco a poco sus esfuerzos flaquearon. Un buen día desapareció sin más.\n\nMe enviaron aquí para continuar su trabajo. Aunque me temo que no sé nada de la sacerdotisa. Quizás Thyn'tel Tejespada, una Comandante de las centinelas, sepa algo sobre su desaparición que no me haya comentado.\n\nSeguro que entenderá la trascendencia de tal información.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1039] = {title = "El puerto de Los Baldíos", objective = "Ve a Trinquete, en Los Baldíos, y habla con el maestro de muelles Vertipeluca.", description = "Trinquete es el único puerto de Los Baldíos. Seguramente Velinde encontró un navío mercante en Trinquete que la llevó a la Cala Aguasnegras, en Azeroth. Hemos tratado poco con los goblins que llevan el puerto, pero el capataz del puerto debería tener información sobre los barcos de pasajeros.\n\nSigue el camino del sureste que atraviesa Vallefresno y te encontrarás en Los Baldíos. Pero ve con cuidado, <nombre>. Hay guerreros de la Horda patrullando esa tierra. En el puerto estarás a salvo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1040] = {title = "Pasaje a Bahía del Botín", objective = "Viaja en barco a Bahía del Botín y habla con el caravanero Ruzzgot.", description = "Ah sí, por fin lo encontré. Tenía que haberme dicho que había estado por aquí hace tanto tiempo. Veamos.\n\nVelinde. Reservó un billete para Bahía del Botín en el Pigargo negro. No figura nada más, así que se supone que llegaron a puerto sanos y salvos.\n\nMe temo que no puedo ayudarte mucho más... bueno, ella preguntó sobre una expedición por tierra en esa parte del mundo y le hablé de Ruzzgot, un conductor de caravanas establecido en Bahía del Botín. Puede que la tal Velinde viajara con él.\n\nVenga, vete ya. Tengo otras cosas que hacer.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1045] = {title = "Un nuevo adorno", objective = "Consigue la calavera de Ran Sangradientes y la vara de Dartol.", description = "Estoy seguro de que Dartol, el difunto mago, pretendía usar su vara para someternos y destruirnos igual que lo han hecho los orcos y los elfos de la noche. Ahora le daremos un uso nuevo.\n\nRan Sangradientes es el rey de todos los fúrbolgs de Vallefresno. Su tribu, los Sangradientes, son los más poderosos y se recluyen en un campamento justo al este.\n\nMátalos a todos y tráeme la calavera de Ran. Veamos si le podemos dar un buen uso.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1047] = {title = "La nueva frontera", objective = "Habla con el archidruida Fandral Corzocelada en el Enclave Cenarion de Darnassus sobre la llamada del Círculo Cenarion para explorar las fronteras de Kalimdor.", description = "¡Atención, héroes!\n\n¡El Círculo Cenarion busca voluntarios sanos para explorar las vastas fronteras nuevas de Kalimdor! Al oeste de Tanaris y Gadgetzan se extiende un páramo lleno de inimaginables peligros. El Círculo necesita voluntarios honorables para explorarlos en representación suya.\n\nTodos aquellos que estén interesados pueden solicitar audiencia en el Círculo Cenarion. ¡Hablad con el archidruida Fandral Corzocelada de Darnassus para más información!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1048] = {title = "En el Monasterio Escarlata", objective = "Mata a la alta inquisidora Melenablanca, al comandante Escarlata Mograine, a Herod el Campeón Escarlata y al maestro de canes Loksey, y después ve a ver de nuevo a Varimathras a Entrañas.", description = "Mientras la Dama Oscura se encarga de retener el avance del Rey Exánime por el norte, yo me ocupo de los problemas que tienen lugar cerca de nuestro hogar.\n\nSin duda, los humanos que se hacen llamar la Cruzada Escarlata representan la mayor amenaza en nuestra zona. Los Claros de Tirisfal están atestados de estas pequeñas hormigas rojas.\n\nVe al Monasterio, <clase>, y acaba con la alta inquisidora Melenablanca y sus principales tenientes.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Espada de AugurioPodrás elegir una de estas recompensas:\n\nCaña proféticaCollar de sangre de dragón\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][1049] = {title = "El Compendio de los Caídos", objective = "Recupera el Compendio de los Caídos del Monasterio que se encuentra en los Claros de Tirisfal y regresa ante Sabio Buscador de la Verdad, que está en Cima del Trueno.", description = "Las intenciones del Anillo de la Tierra para con nuestros hermanos eran puras. ¿Pero quién sabe las motivaciones de los que confabulaban con el Consejo de los Ancianos?\n\nLa historia de los Renegados con los que nos aliamos está plagada de grandes engaños, de ahí que nuestro pacto con ellos haya sido breve. Quizás Cairne fue lo suficientemente inteligente para atender a las advertencias de Orgrimmar...\n\nEn lo más profundo del Monasterio Escarlata se encuentra el Compendio de los Caídos, custodiado por agresivos y fanáticos humanos. Su método proviene de la locura pero su trabajo de investigación puede resultar de utilidad.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Protector vilRodela piedra de fuerzaPodrás elegir una de estas recompensas:\n\nOrbe omega\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][1050] = {title = "Mitología de los titanes", objective = "Busca Mitología de los titanes en el monasterio y llévaselo a la bibliotecaria Mae Palipolvo a Forjaz.", description = "¡El futuro es ineludible! Nos estrellamos contra él como las gotas de lluvia contra el Mare Magnum.\n\nPero quizás el estudio del pasado nos ayude a prepararnos mejor para lo desconocido.\n\nAntes de que la tragedia se abatiera sobre Lordaeron, existía un templo del saber oculto en los Claros de Tirisfal. Se dice que la biblioteca del antiguo Monasterio albergaba un libro llamado Mitología de los titanes.\n\nSi me lo traes, puede que consigamos desvelar los secretos del pasado.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nMención de honor de la Liga de Expedicionarios"}
MultiLanguageQuestData['mx'][1051] = {title = "La venganza de Vorrel", objective = "Lleva la alianza de Vorrel Sengutz a Monika Sengutz de Molino Tarren.", description = "Aunque tengo libre albedrío, no puedo seguir sirviendo a la Dama Oscura. Siento que se acaba mi tiempo en Azeroth. Mi fuerza vital está mermada.\n\n¡Es culpa del interrogador Vishas! ¡Me torturó durante semanas! Me quitó la alianza y se la dio a su mujer. ¡Maldito!\n\nMe vengaré... ¡Juro que me vengaré!\n\nEse cretino pomposo anda presumiendo de su mujer, Nancy, que vive junto al Lago Lordamere. Liquida a esa bruja y llévale la alianza a mi mujer, Monika, a Molino Tarren.\n\nCumple mi último deseo...", progress = "¿Qué quieres?", completion = "Vorrel tenía muchos problemas, pero era un buen compañero... \n\n¡Malditos humanos! \n\nPero al menos te vengaste en su nombre y te lo agradezco. \n\nPor favor, déjame sola...", rewards = "Manteo de acero rictusManto de TragediaRecibirás:\n\nBotas de Vorrel"}
MultiLanguageQuestData['mx'][1052] = {title = "El sendero Escarlata", objective = "Lleva la carta de mención honorífica del hermano Anton a Raleigh el Devoto, en Costasur.", description = "Nosotros, los de la Cruzada Escarlata, hemos reclamado las fortalezas desde la Vega del Amparo hasta los Claros de Tirisfal. Nos sentimos bastante orgullosos de haber conseguido nuestros bastiones en Lordaeron.\n\nHas demostrado estar en contra de los no-muertos en Desolace. Pero el corazón de la Plaga está en Lordaeron.\n\nVe a la ciudad de Costasur, en los Reinos del Este. Busca a un cruzado llamado Raleigh el Devoto. Dale esta carta de recomendación que lleva mi sello y te escoltará a un lugar de honor en nuestro Monasterio Escarlata.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1053] = {title = "En el nombre de la Luz", objective = "Mata a la alta inquisidora Melenablanca, al Comandante Escarlata Mograine, a Herod, el Campeón Escarlata y al maestro de canes Loksey. A continuación, preséntate ante Raleigh el Devoto, en Costasur.", description = "Una vez serví a la Cruzada Escarlata con honor, lealtad y orgullo. Creí que su causa era noble: Librar Azeroth de los no-muertos.\n\nPero según pasé más y más tiempo en el Monasterio, en los Claros de Tirisfal, me di cuenta de que habían perdido la noción de la realidad. Ahora creen que todo aquel que no lleva el tabardo de la Cruzada, está apestado. Hombres y mujeres inocentes torturados porque, supuestamente, estaban apestados.\n\nHay que poner fin a la Cruzada Escarlata, en el nombre de la Luz. Tú, <nombre>, debes destruir al enloquecido régimen.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Espada de SerenidadMasticahuesosAmenaza negraPodrás elegir una de estas recompensas:\n\nOrbe de Lorica\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][1054] = {title = "Matanza selectiva", objective = "Llévale la calavera de Dal Zarpasangrante a Raene Correlobo en Astranaar.", description = "Directamente al norte de Astranaar están los fúrbolgs Piel de Cardo. Mis exploradores me informan de que en los últimos meses han aumentado mucho sus efectivos. Si acaban siendo demasiados, podrían envalentonarse y atacar directamente Astranaar.\n\nMata a tantos de su clase como puedas pero tráeme la calavera de su jefe como prueba de que hemos reprimido el movimiento... por ahora.\n\nSeguiré aquí en Astranaar y esperaré tus noticias. Que Elune esté contigo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBálsamo restablecedor"}
MultiLanguageQuestData['mx'][1055] = {title = "La limpieza de Raene", objective = "Vuelve junto a Shael'dryn en la Poza de la Luna.", description = "La vara, ahora completa, está en tus manos. Shael'dryn se alegrará al enterarse de tu éxito.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1056] = {title = "Viaje a Cima del Espolón", objective = "Ve junto al vigilante Albagorm en la Cima del Espolón.", description = "Según los espíritus del bosque, eres valiente y no te importa viajar.\n\nHacia el sur, cerca del Lago Mystral, se encuentra un túnel conocido como El Paso del Espolón. Este túnel lleva a una zona llamada Risco Cortaviento en Sierra Espolón. Cuando llegues allí, prosigue tu camino hacia el suroeste hasta pasar el Lago del Peñasco, dirígete entonces hacia el norte por una cuesta empinada hasta alcanzar la Cima del Espolón.\n\nAllí aguarda el vigilante Albagorm. Presta atención a su encargo, <raza>.\n\nEl viaje será peligroso.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1057] = {title = "La reconquista de La Vega Carbonizada", objective = "El vigilante Albagorm en la Cima del Espolón quiere que mates a 7 arpías Furia Sangrienta, a 7 emboscadoras Furia Sangrienta, a 7 destripadoras Furia Sangrienta y a 7 malaplumas Furia Sangrienta.", description = "Como <protector/protectora> de los espíritus, sin duda sabrás por qué siento tanta inquietud.\n\nHas viajado a través de estas montañas para llegar a la cumbre. Seguro que has visto la parodia en la que se ha convertido esta tierra. La codicia ha llevado a la destrucción de estas colinas sagradas.\n\nEl ambicioso ejército de industriales mecanizados, incendió La Vega Carbonizada, al sur. Peor aún, los Furia Sangrienta que han invadido la tierra, nos niegan el paso para comenzar a reconstruir.\n\n¡Expulsa a las malvadas arpías, <nombre>!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1058] = {title = "Magia del bosque de Jin'Zil", objective = "El médico brujo Jin'Zil en Malaka'jin quiere 5 porciones de savia del Espolón, 5 mostachos Crepusculares, 30 ojos de trotadores y una escama de dragón hada.", description = "¡Qué bien, qué bien!\n\n¡Tres cajitas para tres elfitos! ¿Pero qué haremos con nuestros simpáticos amiguitos \"abraza-árboles\"? Mmm... Démosles un poco de... ¿Cómo la llaman...? ¡Magia del bosque!\n\n¡Necesitaré un buen montón de savia del Espolón! Tráeme algunos mostachos Crepusculares de esos horribles felinos. Y muchos ojos de trotadores... Nunca se puede tener suficientes ojos de trotadores. Oh, y que no nos olvidemos, una preciosa escama de dragón hada.\n\n¡Vete rápidamente a la Cima del Espolón, <nombre>! Así podré crear algo de magia del bosque.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Manto vudúBrazales embrujadosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1059] = {title = "La reconquista de La Vega Carbonizada", objective = "Ve a ver al Díscolo Falfindel en la frontera entre Las Mil Agujas y Feralas.", description = "Hemos sometido a los Furia Sangrienta. Pero volverán a reagruparse pronto si no hacemos nada por remediarlo.\n\nAl sur de Los Baldíos hay una tierra conocida como Las Mil Agujas. Si te diriges hacia el oeste en Las Mil Agujas, hasta que llegues al Linde del Bosque de Feralas, encontrarás a un druida llamado el Díscolo Falfindel.\n\nEste sabio druida es capaz de invocar poderosos espíritus del bosque que podrán ayudarnos a reclamar La Vega Carbonizada.\n\n¡Háblale de nuestra gran necesidad! ¡Ve a buscarlo!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Brazales templadosRodela de agenteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1060] = {title = "Una carta para Jin'Zil", objective = "Entrégale la carta de Darsok a Jin'Zil en su cueva de Malaka'jin, en Espolón.", description = "Has hecho un gran trabajo para mí, <nombre>. Eres como una pata de conejo de la suerte y eso es algo que siempre me alegro de ver.\n\nLas arpías no son de los alrededores de Los Baldíos. Proceden de un lugar llamado Espolón, muy lejos al noroeste desde aquí. Aunque es probablemente un lugar peligroso para ti, necesito que le entregues esta misiva a un viejo amigo que vive allí, un médico brujo que responde al nombre de Jin'Zil.\n\nSe alegrará de saber que Serena Sangrepluma ha muerto y creo que Espolón te parecerá un lugar interesante.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1061] = {title = "Los espíritus del Espolón", objective = "Habla con Seereth Petrajada en la frontera entre Sierra Espolón y Los Baldíos.", description = "Los espíritus de Sierra Espolón están enojados por la intrusión de los goblins y sus siervos. Por eso la tierra se ha lamentado y aquellos que aún escuchan han oído su súplica.\n\nSe envió a Seereth Petrajada, una prometedora chamán de la Horda. Nos dijo que los goblins están deforestando la tierra a gran velocidad y pidió ayuda.\n\nVe a Sierra Espolón a hablar con ella; su campamento está cerca de la Vega del Gran Bosque. Lo mejor será que sigas el camino hacia el oeste desde El Cruce, en Los Baldíos.", progress = nil, completion = "Ah, &lt;clase&gt;. Perfecto, tu habilidad nos ayudará con esos invasores.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1062] = {title = "Los invasores goblin", objective = "Mata a 15 leñadores de Ventura y Cía. y vuelve a ver a Seereth Petrajada, en la frontera entre Espolón y Los Baldíos.", description = "La empresa goblin Ventura y Cía. llegó a Sierra Espolón, cortando árboles y quemando enormes secciones de bosque. Los espíritus del lugar están prácticamente ciegos de dolor e ira. ¡Debemos detener a Ventura y Cía.!\n\nDirígete al noroeste, más allá de la Vega del Gran Bosque hasta el Risco Cortaviento. Encontrarás a los goblins y a sus siervos en pleno trabajo. Demuéstrales que la Horda no permitirá la explotación de Espolón. Y hazlo utilizando el único idioma que comprenden...\n\nLa violencia.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1063] = {title = "La bruja anciana", objective = "Habla con Magatha en Cima del Trueno.", description = "Para conectar realmente con los espíritus de Espolón, debemos consultar con los ancestros tauren.\n\nNo sé el nombre de muchos de los líderes, pero sí conozco uno: Magatha. He oído que es muy vieja y muy sabia. Si hay alguien que pueda conseguir ayuda espiritual de los tauren, es ella.\n\nMagatha vive en la capital tauren de Cima del Trueno, en el Alto de los Ancestros. En el risco que queda al noreste de la ciudad. Habla con Magatha y cuéntale el peligro que corre Sierra Espolón.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1064] = {title = "a ayuda de los Renegados", objective = "Habla con la boticaria Zamah en las Pozas de las Visiones de Cima del Trueno.", description = "Los tauren tienen un vínculo con la tierra y me apena conocer la difícil situación de Espolón pero me temo que para salvar a la tierra primero debemos eliminar el mal que la puebla.\n\n¿No es una suerte, pues, que los Renegados sean nuestros aliados? Ellos saben mucho del mal y creo que podrán ayudarnos. De ese modo, reforzarán la confianza entre nuestros pueblos.\n\nHabla con la boticaria Zamah, una erudita y emisaria de los Renegados. La podrás encontrar en las Pozas de las Visiones, al pie del Alto de los Espíritus.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1065] = {title = "iaja a Molino Tarren", objective = "Entrégale la nota de Zamah al boticario Lydon, que está en Molino Tarren.", description = "Para liberar a Espolón de Ventura y Cía., debemos tomar medidas extremas pero evitar el derramamiento de sangre.\n\nPuede que un colega mío tenga lo que necesitamos. Su nombre es Lydon y se encuentra en la ciudad de Molino Tarren en las Laderas de Trabalomas, en la lejana tierra de Lordaeron.\n\nPara llegar a Trabalomas viaja en zepelín hasta nuestra capital, Entrañas. Después ve en dirección norte a los Claros de Tirisfal, al sudeste hasta Argénteos y en dirección sur para llegar a Trabalomas.\n\nBusca a Lydon y entrégale esta nota en la que se detalla todo lo que necesitamos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1066] = {title = "angre inocente", objective = "Lleva 5 viales de sangre inocente al boticario Lydon de Molino Tarren.", description = "Voy a crear una toxina que drene la violencia de Ventura y Cía.; así se volverán débiles y dóciles. Eso solucionará el problema de la Horda en Sierra Espolón.\n\nPero necesito sangre inocente, que es difícil de conseguir.\n\nPor suerte, la Hermandad, que es un grupo de maleantes humanos de esta zona, emplea a magos de la sombra, que recolectan sangre inocente para sus turbios propósitos.\n\nLos encontrarás en el Castillo de Durnholde, al sureste de aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1067] = {title = "egresa a Cima del Trueno", objective = "Lleva la toxina de Lydon a la boticaria Zamah de Cima del Trueno.", description = "Aquí está la toxina. Tendrá un efecto favorable, quizás incluso contagioso, en Ventura y Cía. ¡Me emociona ver una demostración práctica de mi trabajo!\n\nPero antes de usarla, llévasela a la boticaria Zamah. Tiene que diseñar un proceso que intensifique el efecto de la toxina.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1068] = {title = "Las sierras XT:4 y XT:9", objective = "Destruye las sierras XT:4 y XT:9, a continuación vuelve a ver a Seereth Petrajada, en la frontera entre Sierra Espolón y Los Baldíos.", description = "Existe una relación entre la magia espiritual del chamán y la magia natural del druida. Es por ello que el chamán puede escuchar la llamada de los espíritus del Espolón. Yo casi no puedo escuchar muchos de sus susurros, pero existe una visión, un mensaje, muy claro...\n\nTuve una visión... dos máquinas parecidas a dos hombres en el Risco Cortaviento, al noroeste de la Vega del Gran Bosque, derribando árboles a gran velocidad. Debemos detener a estas bestias metálicas.\n\nEn mi visión, las máquinas estaban marcadas con extraños símbolos:\n\nXT:4 y XT:9.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1070] = {title = "Estar de guardia en Espolón", objective = "Encuentra a Kaela Lanzasombra contemplando la vista del valle a la entrada del Risco Cortaviento, en Sierra Espolón.", description = "Hola, <nombre>.\n\nPareces tener ansias de conocer mundo. ¿Has estado en Sierra Espolón? Es una tierra apestada por Ventura y Cía. y otros enemigos de los elfos nocturnos.\n\nRecientemente, la centinela Correlobo envió a mi amiga Kaela Lanzasombra allí para investigar lo que está pasando en la tierra, pero todavía no sé nada de ella. Y me preocupa mucho, porque la Alianza envió a un mago gnomo con ella... y eso es sin duda una señal de problemas.\n\n¿Podrías encontrarla y venir a informarme?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1078] = {title = "Escamas cristalizadas para Mauren", objective = "Lleva 8 escamas cristalizadas a Collin Mauren en Ventormenta.", description = "Todos los viajeros siguen preguntándome por Sierra Espolón. Parece ser un lugar muy popular para aventureros... No importa si buscas dracoleones, elementales, o tienes algo que hacer con Ventura y Cía.\n\nEn La Vega Carbonizada, en Espolón, solía haber una especie de basiliscos cuyas escamas, al molerlas, producían un increíble componente para alguno de los hechizos que he creado.\n\nSi esos basiliscos siguen con vida, me encantaría conseguir algunas escamas.\n\nTómate tu tiempo, no corre prisa, pero puedo pagarte generosamente.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nVarita de artesano de hechizos"}
MultiLanguageQuestData['mx'][1086] = {title = "l aeropuerto", objective = "Lleva el nublador tóxico al aeropuerto de Ventura y Cía. e informa a la boticaria Zamah.", description = "La toxina ya está lista. Solo queda entregarla. Y eso te toca a ti, <nombre>.\n\nVentura y Cía. tiene que disponer de un sistema para enviar mensajes y paquetes ligeros entre su administración central y las operaciones de Sierra Espolón. Probablemente sea un aeropuerto, no lo bastante grande para un zepelín, pero sí para un transportador aéreo. Recorre las zonas de influencia de Ventura y Cía. en Sierra Espolón y encuentra el aeropuerto. Si lo localizas, planta la toxina.\n\nY sal de ahí inmediatamente.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1087] = {title = "El legado de Cenarius", objective = "Mata a 4 Hijos de Cenarius, 4 Hijas de Cenarius y 4 botánicas Cenarion para Braelyn Manofuego, cerca del Refugio Roca del Sol.", description = "No puedes ni imaginarte el odio que siento por esta tierra maldita. Los de Cenarius y los druidas kaldorei de la cima, utilizan sus patéticos poderes para reprimir el flujo de la magia, incluso muy lejos, al sur de sus patéticas posesiones... sus amados bosques.\n\nYo podría regresar a Jaedenar y regocijarme con el flujo de la magia, pero mi maestro no me permite volver hasta que no haya finalizado mi trabajo.\n\nNo me cabe la menor duda de que sientes tanto aprecio por los elfos de la noche y sus pequeños aliados como yo. Ayúdame y ambos quedaremos satisfechos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1088] = {title = "Ordanus", objective = "Lleva la cabeza de Ordanus a Braelyn Manofuego cerca del Refugio Roca del Sol.", description = "Creyeron poder detener el flujo de la magia. Se equivocaron. Creyeron que podían ocultar a Ordanus, ¡pero conseguiré su cabeza!\n\nLa magia me otorga la visión verdadera. Sí... ahí está. Una encrucijada... En la copa de un gran árbol en el Bosque de Vallefresno. Un nombre... Algaba. Uno de los hijos mayores del dios del bosque. Le hicieron desaparecer de la cima antes de que pudiera encontrarle, pero se está quedando sin tiempo.\n\nTráemelo y compartiré contigo un poderoso regalo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1090] = {title = "Órdenes de Gerenzo", objective = "Consigue el misterioso mineral de Piznik cuando termine de extraerlo.", description = "¿Sabes? Una vez fui la segunda persona más importante de este lugar. Pero todo cambió con la llegada de Gerenzo. Despidió a mi jefe, Ziz Fizziks, y me envió a trabajar a las minas. Sin embargo, Ziz me dijo que permaneciese aquí y reuniese algo de información. Su nuevo jefe nos pagará bien si podemos descubrir los planes de Gerenzo.\n\nDe todas formas, lo que sí sé es que Gerenzo ha ordenado excavar grandes cantidades de su mineral dorado verdoso. Puedo conseguirte una muestra para que se la lleves a Ziz, pero tendrás que vigilar por si aparecen patrullas mientras lo hago.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1093] = {title = "Súper Segadora 6000", objective = "Consigue los planos de la Súper Segadora 6000 para Ziz Fizziks en Sierra Espolón.", description = "Es terrible lo que Ventura y Cía. ha hecho aquí, ¿verdad? ¿En qué estaban pensando? ¡Una compañía goblin contratando a un gnomo!\n\nPor suerte para mí, Petardol puede distinguir a un genio en cuanto lo ve. ¡Me contrató justo después de que me despidieran!\n\nMe dice que han construido una enorme máquina cortaleña y Petardol quiere que robe los planos para él. El problema es que Gerenzo, maldito gnomo, me quiere muerto... Quizás tú podrías robar los planos por mí... Seguro que los lleva encima alguno de sus operadores.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1095] = {title = "Más instrucciones", objective = "Lleva las nuevas órdenes a Ziz Fizziks en Sierra Espolón.", description = "El asunto de este gnomo contratado por Ventura y Cía. ha provocado algo de revuelo en Minahonda. Los grandes comerciantes no aprueban la asociación de Razdunk con el tal Gerenzo.\n\nRiddlevox me ha pedido que me ocupe del problema y seguro que la orden viene de los grandes comerciantes. Por supuesto, el Director no me lo ha dicho. Digamos que... tengo un presentimiento.\n\nSea como fuere, hay que apartar a Gerenzo y eso parece una prueba a la medida de Fizziks.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1096] = {title = "Gerenzo Silbillave", objective = "Lleva el brazo mecánico de Gerenzo Silbillave a Ziz Fizziks, en Sierra Espolón.", description = "Una vez vi a Gerenzo, pero te diré algo, es difícil de mirar... Su carne parece podrida y tiene injertos de metal y engranajes por todo su cuerpo. Ha reemplazado algunos de sus miembros por otros mecánicos.\n\nGerenzo vigila toda la zona, desde el noreste de aquí, más arriba del Lago del Peñasco, cerca de la noria. Yo no podría llegar hasta ahí arriba, por no mencionar enfrentarme a Gerenzo... Pero tú pareces muy capaz de hacerlo.\n\nSi le matas por mí, ¡te recompensaré!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Capa de ingenieroBotas de dibujanteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1097] = {title = "La tarea de Elmore", objective = "Habla con Grimand Elmore en Ventormenta.", description = "Hay un enano forjador de armas en Ventormenta, Grimand Elmore, que ha enviado un mensaje diciendo que necesita ayuda con una entrega. Creo que quiere enviar un paquete a su hogar, en el norte.\n\n¡Tienes unas piernas muy fuertes! Si te interesa ponerlas en marcha, vete a hablar con Grimand. Podrías sernos muy útil aquí, pero también debemos mantener nuestros tratos con los enanos.\n\nPuedes encontrar a Grimand Elmore en la tienda de armas del Distrito de los Enanos de Ventormenta, en la sección noreste de la ciudad.", progress = nil, completion = "¿Estás aquí para ayudar con la entrega? ¡Estupendo!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1098] = {title = "Mortacechadores en Colmillo Oscuro", objective = "Encuentra a los mortacechadores Adamant y Vincent.", description = "Estamos preparando un ataque a Colmillo Oscuro y enviamos a dos mortacechadores a investigar. De eso hace ya muchos días ¡y necesitamos su informe para preparar el ataque!\n\n<nombre>, tienes que ir al Castillo de Colmillo Oscuro, hacia el sur, y localizar a los mortacechadores Adamant y Vincent. Ayúdalos si lo necesitan.\n\nEsta misión es tan peligrosa como crítica, <nombre>. No falles.", progress = nil, completion = "El cuerpo de Vincent yace inmóvil. \n\nAunque el mortacechador Adamant enviará un informe a Hadrec, Vincent se llevó a la tumba otros secretos. \n\nPero tiene en la mano un abalorio...", rewards = "Recibirás:\n\nManto fantasmal"}
MultiLanguageQuestData['mx'][1100] = {title = "El diario de Soliceja", objective = "Lee el diario de Henrig Soliceja.", description = "Abres lentamente el desgastado diario de Henrig Soliceja...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1102] = {title = "Un destino vengador", objective = "Llévale el corazón de Filonavaja a Auld Picopiedra, que está en Cima del Trueno.", description = "Cairne es un líder noble que ha unido a nuestro pueblo aquí en Cima del Trueno.\n\nPero no puedo perdonar a aquellos que nos han echado de nuestras tierras ancestrales. Mi pueblo habitó en Los Baldíos del Sur durante décadas, una tierra que era sagrada para nosotros, hasta que numerosos enemigos nos expulsaron de ellas.\n\nEl destino le depara venganza a Charlga Filonavaja, que tiene a un ejército congregado en Horado Rajacieno.\n\nTráeme el corazón de Filonavaja y podré morir en paz, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Protectores de BeriloRodela de mármolFaja Puño de piedraRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1103] = {title = "La llamada del agua", objective = "Llévale una sapta de agua a Tiev Mordune en el Bosque de Argénteos si no consigues hablar con la manifestación de agua menor.", description = "¡Saluditos, <hermano/hermana>! ¿También has venío a purificar las aguas y a demostrarle a Islen que l'has captao to'?\n\nYo mesmamente m'he cargao al espíritu del agua corrupto y estaba a punto de colocar los brazales y las gotas restantes d'agua en el blandón.\n\n¿Qué pasha? Ah, ya. Tiev s'entera cuando algo no anda bien. Vale, Tiev podrá ayudarte mogollón si tienes que volver a ver al espíritu del agua pura.\n\nTráeme una sapta d'agua de Islen como prueba de qu'estás <listo/lista> y esperaré pa' cumplir mi parte.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][1104] = {title = "Veneno de El Desierto de Sal", objective = "Llévale 6 glándulas de veneno de escórpidos salados a Fizzle Pernolatón, que está en El Desierto de Sal.", description = "¡Tengo un montón de diseños para nuestro coche cohete! ¡Muchos! ¡Y tengo que probarlos todos!\n\nEstoy trabajando en un nuevo tipo de combustible. ¡Uno que arde a muy, muy, muy alta temperatura! Aún no he conseguido la fórmula perfecta pero creo que ya sé lo que necesito...\n\nEl veneno de los escórpidos que rondan El Desierto de Sal contiene gran cantidad de sal. ¡Es algo único y es justo lo que necesito!\n\nTráeme ese veneno y... créeme, ¡nuestro coche volará!", progress = "¡Hola, hola, hola! ¿¿Conseguiste el veneno??", completion = "¡Genial! ¡Este veneno será perfecto! ¡Gracias, &lt;nombre&gt;! \n\nAhora solo tengo que espesarlo algo, echarle un poco de correcina, añadir un negacatalizador y... ¡Maldición! ¿¡Dónde están mis notas!?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1105] = {title = "Caparazones endurecidos", objective = "Llévale 9 caparazones de tortuga endurecidos a Wizzle Pernolatón, que está en El Desierto de Sal.", description = "Mi hermano está trabajando en un nuevo tipo de combustible para su coche cohete. Es un coco, en serio. Es tan inteligente que... ¡creo que el nuevo combustible que está diseñando es tan potente que podría corroer el chasis del coche!\n\nQuiero reforzar sus depósitos de combustible antes de que eso ocurra.\n\nLas tortugas que habitan El Desierto de Sal tienen unas conchas muy resistentes y quiero utilizarlas para hacer nuevos depósitos para nuestro coche cohete que sean capaces de contener el nuevo combustible de mi hermano.\n\nTú pareces alguien responsable. ¿Podrías conseguirme esos caparazones?", progress = "Mi hermano está haciendo progresos en su nuevo combustible y eso me intranquiliza. ¡Quiero ponerme manos a la obra con el depósito de caparazón de tortuga lo antes posible!\n\n<nombre>, ¿tienes ya los caparazones?", completion = "¡Los has conseguido! ¡Gracias, &lt;nombre&gt;! \n\nVaya, estos caparazones son más duros de lo que yo pensaba. ¡Voy a romper todas mis herramientas!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1106] = {title = "Martek el Exiliado", objective = "Llévale la carta de Fizzle Pernolatón a Martek el Exiliado, que está en las Tierras Inhóspitas.", description = "Estoy trabajando en un nuevo motor que hará que el coche corra como el viento. ¡Podrá incluso volar, lo sé! Lo único que tengo que hacer es crear unos pistones que puedan aguantar una presión realmente alta. ¡Todos mis ensayos fueron un fracaso porque no consigo que los pistones sean lo suficientemente resistentes!\n\nAunque hay alguien que puede que sepa cómo conseguirlo.\n\nSu nombre es Martek el Exiliado. Es un gran herrero y sabe más sobre metales que ningún otro. Llévale esta carta, ¡seguro que nos puede ayudar!\n\nAunque está muy, muy lejos, en las Tierras Inhóspitas de Azeroth, en un campamento con un goblin.\n\n¡Ve y encuéntralo!", progress = "Genial, me has encontrado. Bien por ti.\n\n¿Vienes por el hacha que le hice a Gath'Ilzogg? ¿O acaso vienes a reclamar el honor de la duquesa Pamay?\n\nEn realidad, no me interesan tus motivos. Así que si estás aquí para pelear, acabemos cuanto antes...", completion = "¿Te envía Fizzle? ¡Eso lo cambia todo! Pues claro que te voy a ayudar. ¡Fizzle y su hermano son de los pocos a los que no les gustaría verme muerto! \n\nAsí que Fizzle quiere unos pistones, ¿verdad? ¿Unos que aguanten bastante presión? Conociendo a Fizzle, ¡seguro que su nuevo coche será un volcán con ruedas!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1107] = {title = "Aletas dorsales taraceadas", objective = "Llévale 10 aletas dorsales taraceadas a Wizzle Pernolatón, que está en El Desierto de Sal.", description = "¡Nuestro coche cohete es el más rápido de El Desierto de Sal! Es tan rápido que... ¡tengo miedo de que la fricción lo haga reventar en pedazos!\n\nPara evitarlo, tengo que crear un compuesto para recubrir con él las piezas móviles del coche. Tiene que ser duro pero que no se rompa, y tiene que ser resistente a la corrosión de la sal o después de un tiempo en El Desierto de Sal acabará desgastándose.\n\n¿Has oído hablar de El Arrecife Mortal, <nombre>? Está en la costa, más allá de Vega de Tuercespina. Allí habitan múrlocs de escamas saladas, y sus aletas dorsales son el ingrediente imprescindible para mi compuesto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1109] = {title = "Guano del Horado", objective = "Llévale una pila de guano del Horado al maestro boticario Faranell en Entrañas.", description = "Como puedes comprobar, <nombre>, tenemos unos interesantes experimentos entre manos aquí en la Sociedad Real de Boticarios.\n\nDado que yo soy el maestro aquí, mi trabajo consiste en supervisar nuestros proyectos de alquimia más ambiciosos. ¡Hay tanto trabajo y tan poco tiempo!\n\nParece que tienes muchos kilómetros a tus espaldas, <clase>, así que quizás puedas ayudarnos.\n\nNecesito una sustancia no muy común y un tanto nauseabunda que proviene de una extraña especie de murciélagos que solo se encuentran en ese agujero apestoso conocido como Horado Rajacieno. Tráeme el guano de los murciélagos del Horado para que podamos ponernos manos a la obra.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1110] = {title = "Las piezas de coche cohete", objective = "Llévale 30 piezas de coche cohete a Kravel Karbarbán, que está en El Desierto de Sal.", description = "Je, je, con tantas carreras que se celebran aquí no es de extrañar que haya tantos accidentes. Si echas un vistazo por El Desierto de Sal te darás cuenta de que está plagado de restos de accidentes. ¡Hay piezas de coches cohete por todas partes!\n\nY tienen mucho valor para los gnomos y los goblins, que siempre están en busca de nuevos artilugios que instalar en sus coches.\n\nAsí que sal ahí fuera y consígueme algunas piezas. Tráeme un buen montón y te pagaré como mereces.", progress = "<nombre>, ¿has estado en El Desierto de Sal? ¿Me has traído las piezas que quería?", completion = "¡Vaya, mira todo eso! Hay algunas cosas interesantes en ese montón de basura. Seguro que saco un buen pellizco por ellas. \n\nEspera... ¿eso que está ahí espachurrado es una oreja? ¡Qué dolor! No me gustaría ser ese piloto... \n\nGracias, &lt;nombre&gt;. Aquí tienes tu dinero. Y te voy a dar un consejo gratis... \n\nSiempre se puede sacar beneficio de las desgracias ajenas.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1111] = {title = "Maestro de muelles Vertipeluca", objective = "Llévale el pedido de piezas de Kravel al maestro de muelles Vertipeluca en Trinquete, en Los Baldíos.", description = "Mi trabajo consiste en proporcionar a los demás lo que necesitan, y en este caso los gnomos me han hecho un pedido de piezas. Las piezas llegaron a Trinquete hace una semana pero yo no he podido ir a recogerlas.\n\nAsí pues, ¿te apetece ir a dar un paseo? Ve a Trinquete y entrégale este pedido de piezas al maestro de muelles Vertipeluca, que seguramente esté en el puerto.\n\nHaz esto por mí y te encargaré más trabajos.\n\nTrabajos, <amigo mío/amiga mía>, que te reportarán grandes beneficios...", progress = "¡Habla! Dime... ¿vienes a entregar o a recoger mercancía?", completion = "Ah, sí. Las piezas para Kravel... Me alegro de que hayas venido. Llevan días aquí y tenía miedo de que se oxidaran.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1112] = {title = "Las piezas de Kravel", objective = "Llévale las piezas de Kravel a Kravel Karbarbán, que está en El Desierto de Sal en Las Mil Agujas.", description = "Aquí está el paquete para Kravel, <nombre>. Cuando se lo entregues, dile que si quiere más pedidos especiales ¡tendrá que correr con los gastos!", progress = "¿Conseguiste llegar a Trinquete y hacerte con las piezas?", completion = "¡Genial, las tienes! Ahora hay que llevárselas a los gnomos, pero antes... \n\nVoy a elegir una de ellas para quedármela.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1113] = {title = "Corazones de fanatismo", objective = "El maestro boticario Faranell de Entrañas quiere 20 corazones de fanatismo.", description = "Por qué necesito un tipo de guano tan poco común, te preguntarás. Bueno, para este experimento quiero ver el efecto que dos sustancias químicas diametralmente opuestas tienen entre sí, sobre todo cuando se combinan con un agente incluso más tóxico para obtener... los resultados más horripilantes.\n\nEn las cumbres más nororientales de los Claros de Tirisfal se encuentra el Monasterio Escarlata, lugar en el que se reúnen los fervientes discípulos de la Cruzada Escarlata, tanto dentro como fuera del edificio. Aunque los mates, dará igual, ninguno tiene el corazón que necesito.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1115] = {title = "Rumores", objective = "Habla con Krazek en Bahía del Botín, en la Vega de Tuercespina.", description = "Ahora que ya hemos prestado servicio a los gnomos, ha llegado el momento de hacerles un favor a los goblins.\n\nHe oído que el piloto de carreras goblin, Nazz Vaporio, no siempre ha sido conocido por ese nombre. Me pregunto por qué se lo habrá cambiado, si será un secreto y si realmente valora ese secreto.\n\nSi alguien sabe la verdad de todo esto, ese es Krazek de Bahía del Botín, en el extremo meridional de Tuercespina. Habla con Krazek y pregúntale acerca del piloto goblin.\n\nSi consigues información relevante, puede que le saquemos beneficios.", progress = nil, completion = "¿Preguntas por Nazz Vaporio? Es un piloto de carreras en El Desierto de Sal, ¿no? \n\nSí, puede que averigüe algo sobre él, pero no será fácil. Ni rápido... \n\n¡Y menos barato!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1116] = {title = "Polvo onírico en el pantano", objective = "Llévale 10 pizcas de polvo onírico a Krazek a Bahía del Botín. El polvo onírico se obtiene de las crías de dragón que habitan en el Pantano de las Penas.", description = "Si te diera información sobre Nazz te estaría haciendo un favor, <nombre>, un gran favor. Pero has venido desde el Desierto de Sal para conseguirla... ¿estás <dispuesto/dispuesta> a viajar un poco más?\n\nMientras contacto a mis fuentes, ¿por qué no vas a recoger algo para mí, eh?\n\nVeamos, qué podría ser... ¿Qué te parece polvo onírico de las crías de dragón que hay en el Pantano de las Penas? ¡Sí, me encantaría tener pizcas de polvo onírico para mezclarlas con mi tabaco!\n\n<nombre>, consígueme un poco y te daré la información que andas buscando.", progress = "¿Ya has vuelto? ¿Tienes mi polvo onírico?", completion = "Eh, mira eso. ¡Encontraste el polvo onírico! \n\n¿Y qué, te gustó el pantano, &lt;nombre&gt;? No es fácil conseguir comida allí, ¿verdad?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1117] = {title = "Rumores para Kravel", objective = "Llévale los rumores goblin a Kravel Karbarbán, que está en El Desierto de Sal en Las Mil Agujas.", description = "¡Tuve que hacer algunos favores a cambio, regalar una botella muy especial de vino élfico y atar cabos! Pero finalmente conseguí la información que querías.\n\nAquí tienes, escribí una carta en la que explico lo más destacado de nuestro amigo, Nazz Vaporio. Haz con ella lo que creas oportuno pues es demasiado peligrosa para que yo la guarde.\n\n¡Pero no le digas a nadie de dónde la has sacado!", progress = "¿Has averiguado algo de Nazz Vaporio? ¿Algún secreto que no quiere que se sepa, quizás?", completion = "¡Vaya, vaya! Esto es interesante... muy interesante. Eh, quizás la próxima vez que vea al piloto goblin debería hacerle una reverencia. \n\nLo que has averiguado vale oro, &lt;nombre&gt;. Seguro que Nazz pagará una pequeña fortuna para mantener su secreto... en secreto.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1118] = {title = "De vuelta a Bahía del Botín", objective = "Llévale el esquema de Kravel a Loquillo Pinchabujas a Bahía del Botín, en Vega de Tuercespina.", description = "<nombre>, sé que eres <un/una> <clase> en quien puedo confiar, tanto para realizar un trabajo como para mantener la boca cerrada mientras lo haces.\n\nHe ideado un nuevo plan. Es arriesgado pero si sale bien... ¡podríamos ganar un dineral! Y creo que tú eres la persona adecuada para conocer todos los detalles.\n\nPara empezar, debes volver a Bahía del Botín. Lo siento, <nombre>. Sé que para el último encargo también tuviste que ir allí pero, en esta ocasión, tendrás que hablar con Loquillo Pinchabujas.\n\nEntrégale esta carta y si necesita ayuda haz todo lo posible por echarle una mano. El esfuerzo merecerá la pena.", progress = "Hola, hola. ¿Qué trae a un noble <raza> como tú a Bahía del Botín?", completion = "Entiendo. Kravel ha ideado un nuevo plan. Este Kravel es un tanto siniestro, y eso me gusta. \n\nAsí que necesitas algo para confundir los sentidos, ¿no es cierto? Algo fuerte... \n\nMe pregunto si la mezcla que Zanzil les da a los zombis serviría...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1120] = {title = "Emborrachar a los gnomos", objective = "Llévale la cerveza de tontos al encargado de foso gnomo al Circuito del Espejismo, en Las Mil Agujas.", description = "Tenemos que probar la cerveza de tontos con uno de los equipos técnicos. Si quieres probarla con los gnomos, llévasela al encargado de foso gnomo.\n\nY no tardes mucho, pues la cerveza podría estropearse.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1121] = {title = "Emborrachar a los goblins", objective = "Llévale la cerveza de tontos al encargado de foso goblin al Circuito del Espejismo, en Las Mil Agujas.", description = "Tenemos que probar la cerveza de tontos con uno de los equipos técnicos. Si quieres probarla con los goblins, llévasela al encargado de foso goblin.\n\nY no tardes mucho pues la cerveza podría estropearse.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1122] = {title = "Volver a informar a Pinchabujas", objective = "Llévale el informe de cerveza de tontos a Loquillo Pinchabujas, que está en Bahía del Botín en la Vega de Tuercespina.", description = "¡Esa cerveza de tontos funciona a las mil maravillas! He apostado en la próxima carrera así que esperemos que los técnicos la hayan hecho buena con los coches.\n\nHay una cosa más que debes hacer: llévale esta nota a Loquillo Pinchabujas a Bahía del Botín. Le gustará saber que la prueba ha sido todo un éxito.\n\nCon un poco de suerte, podremos además conseguir más cerveza de tontos para otras carreras.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1123] = {title = "Rabine Saturna", objective = "Ve a Claro de la Luna, al poblado Amparo de la Noche y habla con Rabine Saturna. Claro de la Luna se encuentra entre Frondavil y Cuna del Invierno; para llegar, tienes que seguir el camino que sale del Bastión Fauces de Madera.", description = "El mayordomo del guardián Remulos, Rabine Saturna, está en Claro de la Luna buscando ayuda para explorar los vastos páramos al oeste de Tanaris y Un'Goro. Se encuentra en Amparo de la Noche, el poblado principal de Claro de la Luna.\n\nQuiero que seas consciente de lo importante que es que estés allí pues hay ciertas tensiones entre los elfos de la noche de Darnassus y el Círculo Cenarion de Claro de la Luna. Obvia los límites raciales y aplica la sabiduría heredada de tus ancestros a la hora de tratar con el Círculo, <nombre>. Buena suerte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1125] = {title = "Los espíritus de Viento del Sur", objective = "Libera los espíritus de 8 druidas torturados y 8 centinelas torturados en la Aldea del Viento del Sur. A continuación, reúnete con Layo Golpe Estelar en el cementerio de Sosiego del Valor en Silithus.", description = "Al suroeste de aquí hay un lugar trágico, las ruinas de la Aldea del Viento del Sur. Ahí es donde deberíamos empezar a trabajar, <nombre>.\n\nPor lo que he descubierto, antiguamente, esa aldea era una base de operaciones de los elfos de la noche en Silithus. Mucho tiempo atrás fue tomada por las colmenas de silítidos que infestan los restos. Solo puedo imaginarme el horror de la destrucción de la aldea...\n\nLos espíritus torturados de los druidas y centinelas caídos, vagan por las ruinas sin rumbo fijo. Explora el lugar y libera las almas de esos pobres seres.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1130] = {title = "Melor manda saludos", objective = "Habla con Melor Pezuña Pétrea en Cima del Trueno.", description = "<nombre>, Melor Pezuña Pétrea ha oído hablar de tus hazañas y ha trazado un camino para ti.\n\nSi deseas seguirlo, ve a Cima del Trueno y habla con Melor. Lo encontrarás en el Alto de los Cazadores.", progress = nil, completion = "Has venido, &lt;nombre&gt;. ¿Estás preparada para tu viaje por tierras lejanas? \n\nSi es así, joven &lt;clase&gt;, escucha atentamente.", rewards = nil}
MultiLanguageQuestData['mx'][1131] = {title = "Metaleador", objective = "Llévale la costilla de Metaleador a Melor Pezuña Pétrea, que está en Cima del Trueno.", description = "A veces se caza para conseguir alimento, otras por honor e incluso se puede cazar para aprender las lecciones que enseña la Madre Tierra.\n\nPero la caza que yo te encargo no pertenece a ninguno de estos tipos. Se trata de matar a una criatura que no cuenta con la bendición de la Madre Tierra.\n\nLa hiena Metaleador vaga por Las Mil Agujas, al sur de Los Baldíos. Es un tirano que intenta atraer a otras hienas y que infunde miedo a otras criaturas más pacíficas, provocando un derramamiento de sangre.\n\nEncuentra a Metaleador, <nombre>. Encuéntralo y derrótalo.", progress = "¿Has derrotado a Metaleador, <nombre>?", completion = "Has derrotado a Metaleador y con ello has liberado a Las Mil Agujas de una auténtica pesadilla. \n\nEsa era la lección que quería enseñarte hoy, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1133] = {title = "Viaje a Astranaar", objective = "Habla con Shindrell Fuegoveloz en Astranaar.", description = "<nombre>, ve a Astranaar. Seguro que un miembro de la Alianza entusiasta como tú podrá hacer mucho bien allí. Habla con Shindrell Fuegoveloz y ofrécele tus servicios.\n\nPero no le digas quién te envía pues Shindrell no me conoce...", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][1134] = {title = "Alaorgullo del Espolón", objective = "Lleva 12 sacos de veneno de alaorgullo a Shindrell Fuegoveloz en Astranaar.", description = "No tenemos la guerra declarada a la Horda, pero nuestra paz es frágil. A menudo encontramos a sus agentes actuando en nuestra contra, pero lo hacen encubiertamente.\n\nNos enteramos de uno de esos avances mediante unas fuentes ocultas en Theramore, decían que los orcos recogen veneno de las alaorgullo, cerca del Lago Mirkfallon en Sierra Espolón, hacia el sur. Los asesinos orcos utilizan el veneno en sus asaltos secretos contra la Alianza.\n\nSi esto es cierto, debemos detenerlos, <nombre>. Tenemos que impedir que accedan a su fuente de veneno.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1135] = {title = "Glándulas de veneno de Nido Alto", objective = "Llévale 10 glándulas de veneno de Nido Alto a Fiora Orejona, que está en Theramore.", description = "Como ya sabrás, los orcos suelen domar a dracoleones para utilizarlos como montura. Lo que quizás no sepas es que el veneno de un dracoleón es, en algunos círculos, mucho más valioso que la propia bestia. Así que si no te da miedo ir a la caza del dracoleón, entonces... tengo un trabajo para ti.\n\nHay un lugar llamado Nido Alto en la tierra de Las Mil Agujas, al oeste de aquí. Los dracoleones de Nido Alto tienen un potente veneno. Potente y muy valioso...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCinturón Natoviento"}
MultiLanguageQuestData['mx'][1136] = {title = "aucehielo", objective = "Lleva la crin de Faucehielo a Melor Pezuña Pétrea en Cima del Trueno.", description = "<nombre>, ha llegado la hora de que viajes a lejanas tierras. Estás <preparado/preparada>.\n\nAhora vas a cazar a Faucehielo, un yeti de las Montañas de Alterac. Es escurridizo, su inmaculado pelaje se confunde con la nieve de la montaña en la que mora. Rara vez se deja ver.\n\nPero te enseñaré a engatusar a una criatura como él. Aquí tienes, toma este pergamino. En él explico cómo atraer a Faucehielo.\n\nAhora vete, <nombre>. Tu viaje es largo y te aguardan innumerables desafíos. Solo cuando vuelvas con la crin de Faucehielo habrás completado tu tarea.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nOrnato de espíritu cazador"}
MultiLanguageQuestData['mx'][1137] = {title = "Noticias para Fizzle", objective = "Habla con Fizzle Pernolatón en El Desierto de Sal, en Las Mil Agujas.", description = "¡El indurio tiene una extraordinaria resistencia al calor! Seguro que será perfecto para los pistones de Fizzle. Pero necesitará indurio de verdad, no tan solo unas láminas.\n\nPara poder acceder a él, habrá que extraerlo de las mismísimas profundidades de Uldaman, en el extremo norte de las Tierras Inhóspitas. Esa es la auténtica fuente del indurio.\n\nMándale recuerdos a Fizzle Pernolatón de mi parte y dile lo que te he contado.\n\nBuen viaje, <nombre>. No me sorprendería que volviéramos a vernos pues cuando Fizzle compruebe las propiedades del indurio, es probable que te envíe a Uldaman a por él.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Encendedor vigoroso de FizzleGuantes de mecánico gnómicoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1138] = {title = "Rico marisco", objective = "Reúne 6 trozos de cangrejo de gran calidad para Gubber Blump de Auberdine.", description = "Adoro los cangrejos. ¡Los cangrejos son el fruto del mar! Puedes asarlos, hervirlos, guisarlos, hacerlos a la plancha... Se hacen en sartén, en olla, en hogueras... Y también hay ensalada de cangrejo, sopa de cangrejo, guiso de cangrejo, cangrejo a la pimienta, cangrejo al limón y cangrejo-sorpresa de Forjaz. Creo que no me dejo nada.\n\nPero ahora estoy pescando. No voy a conseguir ningún cangrejo. Se pueden conseguir de reptadores de arrecife y de reptadores de marea escamados. Y se pueden hacer mil cosas con ellos. Puedes asarlos, hervirlos, guisarlos, hacerlos a la plancha...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de cribaBotas crustáceoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1139] = {title = "Las tablillas perdidas de Voluntad", objective = "Encuentra la tablilla de Voluntad y llévasela al consejero Belgrum en Forjaz.", description = "Hemos conseguido frenar al clan Forjatiniebla al aislarlos de la Cumbre de Roca Negra pero aún no hemos completado la misión de Piemartillo. Su muerte no debe ser en vano. Soñaba con encontrar la tablilla de Voluntad: un fragmento de piedra grabado con magia de los mismísimos titanes para ayudar a imbuir de vida a sus creaciones dándoles voluntad propia, o al menos eso cuenta la leyenda.\n\nDebemos recuperar la tablilla antes de que lo haga el clan Forjatiniebla.\n\nRegresa a Uldaman, encuentra la tablilla y vuelve aquí inmediatamente.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nMedalla de Coraje"}
MultiLanguageQuestData['mx'][1140] = {title = "La Torre de Althalaxx", objective = "Libera las almas de los Altonato atrapadas en la Senda de la Noche y en Satyrnaar y vuelve junto a Delgren el Purificador en la Atalaya de Maestra.", description = "La letra de los orcos es un poco mejor que los garabatos de un niño. Muchos de los de mi orden se burlaron cuando decidí aprender su lengua pero me ha resultado de provecho tener un conocimiento más profundo de mis enemigos.\n\nPor los garabatos de Ilkrud, parece que Athrikus aún posee dos gemas de almas que se guardan en la Senda de la Noche y en Satyrnaar, áreas bajo el dominio de los sátiros al noreste de Vallefresno.\n\nVe con cuidado, <nombre>, los templos de los sátiros bañados en sangre pueden ser perturbadores hasta para <un/una> <clase> <curtido/curtida> como tú.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1141] = {title = "La familia y la caña de pescar", objective = "Pesca 6 meros de Costa Oscura para Gubber Blump de Auberdine.", description = "Me encanta pescar. Los Blump somos una famosa familia de pescadores. Yo soy Gubber Blump. Yo también pesco.\n\nEn esta zona hay un pez que me gusta pescar: el mero de Costa Oscura. Yo solía salir en un barco a pescar meros, pero desde que aparecieron los múrlocs, ya no sale ningún barco. Además, seguro que los múrlocs se han comido todos los meros.\n\nOye, ¿quieres ayudarme a pescar un mero de Costa Oscura? Si lo haces, ¡te daré una auténtica caña de pescar de la familia Blump! Es una caña estupenda para pescar.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCaña de pescar de la familia Blump"}
MultiLanguageQuestData['mx'][1142] = {title = "Decaída mortal", objective = "Encuentra el colgante de Treshala Arroyobarbecho y llévaselo a Darnassus.", description = "No voy a durar mucho... Estoy débil.\n\nEl valiente enano Cimahuraña ha ido a advertir a Falfindel...\n\nAntes de morir, quisiera...\n\nSe han llevado el colgante de vínculo de mi esposa, Treshala...\n\nEncuéntralo, por favor... Llévaselo a Treshala a Darnassus...\n\nY dile que he... muerto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Chal de lutoBotas de lanceroRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1144] = {title = "Willix el Importador", objective = "Escolta a Willix el Importador hasta la salida de Horado Rajacieno.", description = "¡Por fin llega ayuda!\n\nNo sabes cuánto hace que me tienen aquí prisionero. Ya ni recuerdo la última vez que estuve fuera.\n\nVerás, es que soy empresario, siempre ando olfateando negocios. Oí decir que Mebok Mizzyrix pagaba bien el tubérculo hojazul para su porqueriza, y me pareció un negocio redondo y fácil. Como puedes ver, ¡calculé mal!\n\nPero si me ayudas a salir de aquí, te recompensaré.", progress = nil, completion = "¡Gracias otra vez! Y ahora, la recompensa prometida.", rewards = "Podrás elegir una de estas recompensas:\n\nAnillo de monoSortija de tigreAro de culebra\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][1145] = {title = "El enjambre crece", objective = "Entrégale la nota lacrada de Korran a Belgrom Destrozarroca en Orgrimmar.", description = "Muchos viajeros que han pasado por El Cruce me han ayudado a recoger huevos de la Tierra de Gigantes y muchos de ellos podrán contarte historias de lo peligrosas que son esas bestias. Yo ya he oído las suficientes como para poder afirmar que esos insectos representan una amenaza mayor de lo que mis maestros pensaban.\n\nNecesito enviar a un mensajero a Orgrimmar, a ver a Belgrom Destrozarroca. No se trata de un asunto cualquiera por eso necesito que vaya alguien que se tome esta tarea en serio.\n\nBelgrom suele andar por las inmediaciones de la Casa de la Hermandad de Guerreros.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1146] = {title = "El enjambre crece", objective = "Entrégale la nota lacrada de Belgrom a Moktar Krin en Las Mil Agujas.", description = "Por lo que veo, Korran ha llegado a la misma conclusión que yo acerca de esos insectos... parece que representan una amenaza mayor de lo que yo pensaba.\n\nHace unos días, un cazador regresó agonizante de Las Mil Agujas. Formaba parte de un destacamento de asalto enviado a El Desierto de Sal para expulsar de allí a un equipo de excavación formado por enanos. Durante el ataque, empezaron a salir insectos de una cueva que formaba parte de la excavación y casi acaban con todo el destacamento.\n\nEstaban liderados por Moktar Krin y se han refugiado en la frontera de El Desierto de Sal. Llévale esta nota.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1147] = {title = "El enjambre crece", objective = "Mata a 5 buscadores silítidos, 5 zánganos de colmena silítidos y 5 invasores silítidos, y después ve a ver de nuevo a Moktar Krin a Las Mil Agujas.", description = "¡Vaya! Parece que Belgrom piensa que esos monstruos representan una amenaza y quiere que sean devueltos al lugar al que pertenecen.\n\nSupongo que haber matado a los enanos enviados por la Liga de Expedicionarios no ha sido suficiente y ahora tengo que enviar a un destacamento de guerra exhausto a otra batalla. No lo conseguiremos... no en estas condiciones. La excavación se encuentra al sur de aquí, y ya no debería quedar ningún enano por allí. ¿Te sientes con ánimos de blandir una espada o un bastón y echarnos una mano?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1148] = {title = "Pedazos del enjambre", objective = "Llévale 1 corazón de silítido, 5 garfas de silítido y 3 caparazones de silítido intactos a Korran, que está en El Cruce.", description = "Inspeccionas el caparazón detenidamente. A medida que lo giras, te das cuenta de que la coraza de quitina está entrelazada de tal forma que le confiere una resistencia increíble. No se parece a nada que hayas visto antes. Observas el resto del cuerpo y te das cuenta de que estas criaturas son muy poderosas y están muy evolucionadas.\n\nAl mirar de nuevo el caparazón, crees que a Korran le gustaría recibir más muestras de estas criaturas. Le resultarían útiles para descubrir qué son y de dónde proceden.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1149] = {title = "Prueba de fe", objective = "Si tienes fe, salta desde las tablas que dominan Las Mil Agujas.", description = "¿Me has estado buscando o quizás ha sido el destino el que te ha traído a mí? No tiene importancia... Ahora estás aquí y tu viaje encontrará un nuevo punto de partida.\n\nSon muchas las facetas que conforman un ser, tanto su espíritu como su cuerpo y su mente. Algunas de ellas son mensurables por las tradiciones de una cultura. Otras, sin embargo, solo podemos esperar que encuentren un lugar dentro de nosotros. Si no te opones, pondré a prueba algunas de tus facetas.\n\nSi superas las pruebas, te harás más fuerte. De lo contrario, descubrirás la inmensidad de El Vacío Abisal.\n\nLa primera es una prueba de fe.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1150] = {title = "Prueba de resistencia", objective = "Llévale la garra de Grenka a Dorn Acechallanos, que está en Las Mil Agujas.", description = "Me complace comprobar que tu valor permanece inquebrantable después de lo que acabas de hacer. Dado que tu fe está intacta, ha llegado el momento de poner a prueba tu cuerpo.\n\nEn primer lugar, harás una prueba de resistencia. Ve a Guarida Malapluma al oeste del Poblado Viento Libre. Consigue llegar hasta las profundidades de su guarida y destruye sus alimentos. Con eso provocarás su ira. Si eres capaz de aguantar con vida el tiempo suficiente, la propia Grenka Aullasangre irá a por ti. Acaba con ella y tráeme su garra para superar tu prueba.", progress = "Debes estar preparado espiritual, física y mentalmente para los desafíos que tienes por delante.\n\nMuchas veces, queremos avanzar sin estar preparados. Mi obligación con los jóvenes, sean de la tribu que sean, es prepararlos para enfrentarse a los peligros con los que se puedan topar cuando abandonen el calor del hogar.", completion = "Incluso basándonos en los parámetros de un &lt;raza&gt;, Grenka era muy poderosa. Debes sentirte orgulloso de lo que has logrado hoy. \n\nDurante tu prueba de fe, demostraste poseer gran fuerza de espíritu y, al acabar con las arpías Malapluma, has demostrado tener gran resistencia en combate. Ha llegado la hora de que afrontes una nueva prueba.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1151] = {title = "Prueba de fuerza", objective = "Llévale fragmentos de Rok'Alim a Dorn Acechallanos, que está en Las Mil Agujas.", description = "En los tiempos de los dioses antiguos, los elementales ocupaban la mayor parte de este mundo. Ellos veneraban a los dioses antiguos y estos, haciendo uso de su poder, relegaron a los elementales a este mundo. Cuando los dioses antiguos desaparecieron, los elementales se desvanecieron de nuestro mundo y ahora solamente regresan cuando los poderosos magos requieren su presencia.\n\nAun así, hay algunas excepciones. Algunos elementales eran más poderosos y consiguieron permanecer aquí por su cuenta. Uno de ellos es Rok'Alim.\n\nPara poner a prueba tu fuerza, encuentra a Rok'Alim en Las Mil Agujas y acaba con él.", progress = "Las tribus de centauros de Las Mil Agujas denominan a Rok'Alim el Aporreador debido a la fuerza con la que sus puños golpean a las criaturas lo suficientemente valientes o demasiado insensatas como para cruzarse en su camino.", completion = "La prueba de fuerza ha concluido. Has demostrado ser fuerte y valiente, y ahora estás preparado para la prueba final.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1152] = {title = "Prueba de conocimiento", objective = "Encuentra a Braug Espíritu Tenue cerca de la entrada de El Paso del Espolón en Sierra Espolón.", description = "Tu tiempo conmigo está llegando a su fin. Tengo una amplia cultura mas la prueba de conocimiento no seré yo quien te la haga. Hay lecciones que aprender y lugares que visitar que corresponden a otros.\n\nSi estás <preparado/preparada>, busca a Braug Espíritu Tenue, un chamán muy sabio. Él continuará poniéndote a prueba, así que sigue sus indicaciones, <nombre>.\n\nCuando lo desees, busca el túnel que comunica Sierra Espolón con Vallefresno pues Braug anda por esa zona. Y ten cuidado, <nombre>, a los elfos de la noche les encantaría impedir que acabaras tus pruebas.", progress = nil, completion = "El desasosiego crece en este mundo a medida que los goblins expolian la tierra y los elfos de la noche ponen el punto de mira en las razas más jóvenes. Los Renegados y los orcos no son los únicos culpables de las penurias sufridas por Kalimdor y Lordaeron. Muchas de las razas inteligentes han contribuido al malestar que reina en el mundo. Dorn lo sabe y te ha enviado a verme porque has demostrado ser capaz de entender la situación. \n\nTe encuentras ante Braug.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1153] = {title = "Una nueva muestra de mineral", objective = "Arrebátale una muestra bruta de mena a un cavador o a un perito Gravamorro y llévasela a Jironack Forjacero al Campamento Taurajo de Los Baldíos.", description = "<clase>, me has ayudado con eficacia en el pasado. El Jefe de Guerra está satisfecho con mis logros y quiere que continúe con renovada determinación. Según me dicta mi honor, informaré al Jefe de Guerra de tu valía para que te otorgue el reconocimiento que te mereces. Pero antes he de pedirte que me ayudes otra vez.\n\nRecientemente han llegado unos viajeros del sur, de un lugar llamado Las Mil Agujas. Estos afirman que allí mataron a un kóbold que tenía una muestra de un extraño mineral, pero no están dispuestos a vendérmelo. Quiero una muestra de ese mineral para analizarlo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nEspada de guerra orca"}
MultiLanguageQuestData['mx'][1154] = {title = "Prueba de conocimiento", objective = "Encuentra el Legado de los Aspectos y devuélveselo a Braug Espíritu Tenue que se encuentra cerca de la entrada de El Paso del Espolón en Sierra Espolón.", description = "Has superado con éxito las pruebas de Dorn y sé que quieres hacer lo mismo con la siguiente. Muy bien, pero ten en cuenta que hasta el momento las pruebas han sido demasiado sencillas. Es fácil poner a prueba el cuerpo... pero la mente es un tema aparte.\n\nTe lo explicaré bien para que lo entiendas: encuentra el libro que yo te diga, estúdiatelo bien y responde la pregunta que te haga acerca de su contenido.\n\nQué libro, te estarás preguntando... El Legado de los Aspectos. Lo encontrarás en la parte baja de Dor'danil, en el sur de Vallefresno, bajo la protección de los druidas muertos y sus asesinos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1159] = {title = "Prueba de conocimiento", objective = "Encuentra a Parqual Fintallas en Entrañas.", description = "Bien hecho, <nombre>. Has superado la primera parte de la prueba de conocimiento pero aún hay otra pregunta que debes responder. Sin embargo, no seré yo quien te la haga.\n\nBusca a Parqual Fintallas en Entrañas de Lordaeron. Él era un gran historiador al servicio de los humanos antes de que la Plaga lo sorprendiera. Ahora sigue persiguiendo el conocimiento, pero de un modo distinto.\n\nAntes de formularte ninguna pregunta, te asignará otro encargo. Lo has hecho tan bien hasta el momento que no tengo ninguna duda de que superarás este obstáculo sin problemas.", progress = nil, completion = "¿Te envía Braug? No es posible... \n\n&lt;Parqual te mira de arriba abajo.&gt;\n\n¿Estuviste en Dor'danil, diste el salto de fe y luchaste y derrotaste a un poderoso elemental? ¡Bah! Seguro que eres un impostor. Alguien que escuchó una conversación en alguna taberna y cree estar preparado para superar mi prueba. Ya lo veremos..., &lt;clase&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1160] = {title = "Prueba de conocimiento", objective = "Encuentra el libro Comienzos de la amenaza de los no-muertos y devuélveselo a Parqual Fintallas, que está en Entrañas.", description = "Te diré lo que tienes que buscar, e incluso te formularé mi pregunta, pero no porque desees ponerte a prueba. El conocimiento va más allá de la fuerza física. Aunque otros puedan superarte en habilidad, el conocimiento del mundo te dará ventaja.\n\nDirígete al monasterio que está al norte de los Claros de Tirisfal. En la biblioteca que encontrarás allí, verás un libro titulado Comienzos de la amenaza de los no-muertos. Lo utilizaban los ahora corruptos paladines de allí para instruir a los no-muertos para luchar contra los de mi especie.\n\nTráemelo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1164] = {title = "Robar a un ladrón...", objective = "Llévale las cabezas de Kenata, Fardel y Marcel Dabyrie a Genavie Callow, que está en Entrañas.", description = "¡Desgraciada! ¡Canalla! Kenata sigue viva, y su familia está sana y sigue prosperando mientras yo sufro. ¡Renegados tenían que ser!\n\nMi familia ha muerto debido a la peste. Arruinaron nuestra finca durante la guerra, la saquearon y le plantaron fuego. Y después de todo esto, ella y sus despreciables hijos tuvieron el descaro de robar las únicas posesiones de valor que me quedaban.\n\nYa no me preocupa lo que me fue robado. ¡Lo que quiero ahora son sus cabezas!\n\n¡Mátalos por mí! Ve a la Granja de los Dabyrie en Arathi, al noreste del Refugio de la Zaga.", progress = "¡Mátalos y tráeme sus cabezas!", completion = "Has cumplido mi venganza y me inclino ante ti en agradecimiento. \n\nAhora que están todos muertos y que se ha acabado su progenie en Azeroth, puedo concentrar mis energías en algo más lucrativo. Espero que hayas saqueado su granja tras haberles dado muerte.", rewards = "Puños de galanteEspaldares macabrosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1166] = {title = "as pertenencias del señor supremo Mok'Morokk", objective = "El señor supremo Mok'Morokk del Poblado Murohelecho quiere que recuperes su grog, su barril de tabaco y su caja fuerte del Pantano Revolcafango.", description = "¡Inclínate ante señor supremo Mok'Morokk!\n\n¡Rexxar hacerme líder poderoso del clan Quebrantarrocas!\n\nYo buen jefe. Yo cuidar del clan.\n\nGrandes dragones vienen y hacen fuego en otra casa. Pero yo soy un ogro listo. Encontré nueva casa para el clan.\n\nClaro que dejamos casa vieja tan rápido que yo olvidé cosas. <Pequeño/Pequeña:r> <raza>, ve a por mis cosas. Ir al sur y encontrar mi rico grog, mi barril de tabaco y mi caja fuerte. Si haces eso, me caerás bien. Busca en Cubil de la Llama y en Ruinas Quebrantarrocas... Estar ahí, ¡yo seguro!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Guantes QuebrantarrocasPodrás elegir una de estas recompensas:\n\nBotella de grog de Mok'Morokk\n\nTambién recibirás:\n\nBotas de ogro enigma"}
MultiLanguageQuestData['mx'][1167] = {title = "La Torre de Althalaxx", objective = "Habla con Balthule Golpesombra cerca de La Torre de Althalaxx.", description = "Antes de enfrentarte a Athrikus, probablemente sería prudente que consultaras a Balthule. No me cabe la menor duda de que habrá estado muy atento en su observatorio de la torre y podría tener información sobre los últimos movimientos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1168] = {title = "El ejército de los dragones Negros", objective = "Tharg en el Poblado Murohelecho quiere que mates a 10 exploradores Pirocabello, 10 ceniazotes Pirocabello y 5 horrocrustos Pirocabello.", description = "Mok'Morokk fue nombrado señor supremo por Rexxar. Le preocupa más el poder que los ogros.\n\nLos dragones Negros matan a muchos ogros. Matan a la mujer de Tharg. Mok'Morokk nos dice que huir. Nos hace venir aquí.\n\nLos ogros deben luchar. Los ogros no huir. No buenos corredores. Mok'Morokk solo preocupa de Mok'Morokk.\n\nYo llamo casa a las Ruinas Quebrantarrocas. A mí gustar el sur. Este lugar no casa.\n\nAyuda ogros combatir ejército de los dragones Negros. Quiero venganza. Quiero ir a casa.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Disco de ThargBotas de ogro enigmaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1169] = {title = "dentifica a los cachorros", objective = "Draz'Zilb del Poblado Murohelecho quiere que le lleves 7 lenguas abrasadoras y 7 corazones abrasadores.", description = "Mientras ese loco cobarde de Mok'Morokk se revuelca en poder y Tharg lucha contra los demonios de su pena y su venganza y compite por el liderazgo del clan, solo yo me preocupo de identificar la fuente de la agresión a nuestro antiguo hogar.\n\n¿Por qué me miras así, <nombre>? ¿Esperabas que hablara como un burdo pueblerino solo porque soy un ogro?\n\nEn fin, volvamos a nuestros asuntos. Tráeme los corazones y las lenguas de los cachorros y las crías. Yo buscaré la raíz de este mal...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Manteo agostadoGuantes de cuatreroMáscara inquietanteDaga abrasadoraHacha para matar algasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1173] = {title = "Desafía al señor supremo Mok'Morokk", objective = "Derrota a Mok'Morokk y ve al Poblado Murohelecho a informar a Draz'Zilb.", description = "¿Osas desafiar al señor supremo Mok'Morokk?\n\n¡Ja!\n\n¡Yo aplastar insignificante <raza>!\n\nDime cuándo estar <listo/lista> para la paliza.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Pincho malignoAstilla UñafríaSobrehombros trofeo de Señor SupremoPalo de pegar de Mok'MorokkEmpalador RevolcafangoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1175] = {title = "Un bache en la carretera", objective = "El maestro rastreador Zherin quiere que mates a 10 basiliscos Piedra de sal, 10 vitropieles Piedra de sal y 6 observadores Piedra de sal en El Desierto de Sal.", description = "Tras el choque del Trueno Rojo de los goblins con un basilisco, Kronkpiloto me contrató para que me ocupe de la pista. Yo no sé lo que comerán esos animales en el desierto para crecer tanto pero tenemos que encargarnos de ellos si no queremos que deambulen por la pista durante la celebración de una carrera.\n\nTe diré lo que vamos a hacer. Si quieres ir ahí fuera y hacer algo de provecho, sal y acaba con los basiliscos que encuentres por la zona.", progress = nil, completion = "¡Espero que no hayas matado a ningún basilisco en la pista! Sus cuerpos tardan mucho en descomponerse al sol y prefiero no tener que recoger una pala para despejar la pista.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1176] = {title = "Menos peso", objective = "Consigue 10 huesos huecos de buitre para Pozzik en El Desierto de Sal.", description = "¡Cuando se trata de correr, todo cuenta! Ya sea un pequeño ajuste en la salida de potencia, que se afloja la bobina de tensión o que se aligera el peso del cuadro. ¡Hay que tener todo en cuenta!\n\nUtilizamos huesos de buitre para la mayor parte de los pequeños cambios que hacemos en la estructura de los coches, por su perfecto equilibrio entre resistencia y peso. Y lo mejor de todo es que son muy fáciles de encontrar pues en el Desierto de Sal hay muchos buitres.\n\nTráeme algunos y te pagaré bien por ellos.", progress = "¿Tienes los huesos? Estaba pensando en aligerar la dirección pero no quiero empezar hasta tener todas las piezas que necesito.", completion = "¡Genial! Ya puedo poner al equipo técnico a trabajar en esto. ¡Gracias, &lt;nombre&gt;!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1177] = {title = "¡Qué hambre!", objective = "Fangolpe Piesucio del norte de Revolcafango quiere 8 cabezas de Ancalodo.", description = "Fango ogro grande.\n\nYo tiene hambre.\n\nTú buscar peces. Trae comida a Fango.\n\nTú das de comer a Fango o Fango te come a ti.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Trituradores de barroApisonadoras PiesuciosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1178] = {title = "Patrocinio goblin", objective = "Habla con Gazlowe en Trinquete, en Los Baldíos.", description = "Nuestro equipo de carreras es el orgullo de todos los goblins. Te sorprendería saber quiénes contribuyen de un modo u otro en esto.\n\n¿Conoces a Gazlowe? Él nos busca piezas por todo el mundo. ¡Incluso en una ocasión vino aquí para arreglar uno de estos trastos!\n\nHace unas cuantas semanas, dijo que nos enviaría un prototipo de un nuevo regulador de combustible pero todavía no nos ha llegado. Y él suele ser muy rápido... ¿Te importaría ir a Trinquete y preguntarle por el regulador? ¡No me gusta meter prisa pero los gnomos nos están ganando!", progress = nil, completion = "¿Te envía Pozzik, eh? Sabes, Pozzik era uno de los manitas más respetados de Minahonda hasta que decidió dejarlo todo para dedicarse a las carreras. \n\nLo primero que hizo tras unirse al equipo fue desarrollar el coche de doble motor. Puede ser que el negocio experimente un bajón ahora que él ya no trabaja en el Gremio de Manitas pero... ¿a quién le importa? ¡No hay nada como las carreras!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1179] = {title = "Los hermanos Pernolatón", objective = "Llévale el cajón de cascos de choque a Wizzle Pernolatón, que está en el Circuito del Espejismo en Las Mil Agujas.", description = "¿Has oído hablar del Desierto de Sal? Es una franja de tierra salada y llana de Kalimdor, al sur del cañón de Las Mil Agujas. ¡Es un lugar ideal para echar una carrera ya que es totalmente llano!\n\nUn par de hermanos gnomos amigos míos están allí probando su nuevo coche cohete y, por lo que tengo entendido, ¡es una bala! Eh, es tan rápido que los pilotos se estrellan continuamente y sufren conmociones.\n\nPor eso me han pedido algunos cascos de máquinas de asedio pero tengo cosas que hacer aquí, ¡y no puedo ir!\n\n¿Podrías ir tú?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1180] = {title = "Patrocinio goblin", objective = "Habla con el jefe de embarcadero Lozgil en Bahía del Botín.", description = "Has vuelto por lo que habías venido a buscar. Sé que le prometí a Pozzik que le entregaría un nuevo regulador de combustible pero aún no lo he recibido. Revilgaz de Bahía del Botín dijo que lo había enviado pero se debe de haber perdido por algún lado.\n\nSi es cierto, no hay mucho que podamos hacer. Al menos podemos averiguar si salió realmente de Bahía del Botín.\n\nVe para allá y compruébalo con el jefe de embarcadero Lozgil. Podrá comprobarlo en los registros de cargamentos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1181] = {title = "Patrocinio goblin", objective = "Habla con el Barón Revilgaz en la Bahía del Botín.", description = "Me temo que no puedo ayudarte más, <nombre>. Si quieres seguir investigando, te sugiero que vayas a ver al Barón. Si alguien sabe lo que está haciendo Revilgaz, es Revilgaz.\n\nLe encontrarás en la taberna al otro lado del puerto, en el piso de arriba.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1182] = {title = "Patrocinio goblin", objective = "Lleva los planos de regulador de combustible al Barón Revilgaz en la Bahía del Botín.", description = "Verás, las trituradoras de Ventura y Cía. del Lago Nazferiti (en la parte norte de Tuercespina) están equipadas con un nuevo modelo de regulador de combustible. Creo que Pozzik podría sacar ventaja de eso si pudiera conseguir algunos detalles. Por desgracia, Cozzle, el supervisor que está ahí fuera, parece más inteligente de lo que yo había pensado.\n\nQuizás tú tengas más suerte para encontrar los planos. Sé que los guarda en su casa, pero seguro que los tiene bajo llave.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][1183] = {title = "Patrocinio goblin", objective = "Entrega los planos de regulador de combustible a Pozzik en El Desierto de Sal.", description = "Creo que ya estás <listo/lista> para irte. Da recuerdos a Pozzik de mi parte y dile que, si alguna vez necesita algo, no dude en pedírmelo. ¡Estaré esperando la noticia de que ha conseguido batir el récord!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1184] = {title = "Pedazos del enjambre", objective = "Ve a ver de nuevo a Belgrom Destrozarroca a Orgrimmar.", description = "Ve a ver a Belgrom a Orgrimmar y dile que Moktar está cumpliendo con su cometido en Las Mil Agujas. Dile también que yo he progresado en mis investigaciones y que espero saber más cosas pronto. Seguro que se alegra de saberlo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Pantalones de hojas secasHacha curva sangranteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1187] = {title = "Los ajustes de Razzeric", objective = "Consigue el propulsor de seforio para Razzeric, en El Desierto de Sal.", description = "Pozzik es un gran mecánico, lo sé, pero tiene miedo de aumentar la potencia y lanzarse a la carrera. Yo no, sin embargo.\n\nCuando Pozzik acaba con un coche, yo me tomo un tiempo para realizar mis propios ajustes... ya sabes, aflojo los mandos, quito algunas piezas del cuadro y le pongo más combustible.\n\nLe encargué un propulsor de seforio a Shreev para que me lo enviara desde la Cacharrería de Gadgetzan pero parece que el zepelín en el que venía se estrelló en Marjal Revolcafango. ¡Lo necesito, <nombre>!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1188] = {title = "La seguridad primero", objective = "Llévale el propulsor de seforio a Shreev, que está en Gadgetzan en Tanaris.", description = "Pero espera, ¿qué es esto? Shreev dejó el seguro puesto y eso limitará la potencia del propulsor. ¡Le dije que se lo quitara! Esto no me gusta.\n\nTienes que llevar esto a la Cacharrería de Gadgetzan en el Desierto de Tanaris y decirle a Shreev que se lo quite.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1190] = {title = "Mantener la velocidad", objective = "Consigue que Zamek haga una artimaña de distracción y roba los diseños de Rizzle para Pozzik en El Desierto de Sal, en Las Mil Agujas.", description = "Los hermanos Pernolatón han descubierto un nuevo material de construcción, es la única explicación posible. Sus coches cada vez son más rápidos pero sus diseños y todos los datos que reunimos durante sus carreras son los de siempre.\n\nLo que sí sabemos es que Rizzle Pernolatón tiene unos diseños de ese nuevo descubrimiento.\n\nMientras Zamek los entretiene, tú roba los diseños.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1191] = {title = "La distracción de Zamek", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][1193] = {title = "Una trampa rota", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][1195] = {title = "La llama sacra", objective = "Llévale una ampolla con grabados llena a Zangen Pezuña Pétrea, que está en Cima del Trueno.", description = "Los centauros Galak de Las Mil Agujas custodian un artefacto desde el comienzo de sus tiempos.\n\nNos gustaría arrebatárselo pero para ello necesitamos una ampolla de agua de una de las Pozas de la Luna de los elfos de la noche.\n\nPara conseguir el agua, primero tendrás que hacerte con una de las ampollas que portan los dríades cerca del Refugio de la Algaba en el corazón del Bosque de Vallefresno. Hay una Poza de la Luna cerca de la orilla occidental del Río Falfarren, al sur de la carretera principal, donde podrás llenar la ampolla de agua.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1196] = {title = "La llama sacra", objective = "Entrégale la ampolla con grabados llena a Rau Abiscorredor del Poblado Viento Libre.", description = "Llévale la ampolla con agua a Rau Abiscorredor en el Poblado Viento Libre en la zona sudeste de Las Mil Agujas. Podrás llegar a Las Mil Agujas cogiendo El Gran Elevador que encontrarás en el extremo sur de Los Baldíos.\n\nNo me sorprendería que pudieras seguir ayudándonos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1197] = {title = "La llama sacra", objective = "Consigue la pezuña hendida para Rau Abiscorredor del Poblado Viento Libre.", description = "Con el agua que has traído podrás apagar temporalmente la llama que protege la reliquia de los centauros. Sin embargo, su efecto no es permanente por lo que tendrás que darte prisa.\n\nEncontrarás el Risco Pezuña Quebrada, el fuerte de los centauros, en dirección norte. La llama se encuentra en el Campamento Pezuña Quebrada, un lugar fuertemente custodiado del risco.\n\nTen cuidado pues los centauros Galak tienen a muchos hombres allí y no dejarán que les arrebates algo tan preciado para ellos con facilidad.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Objetivo de AbiscorredorFajín azurRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1198] = {title = "Buscando a Thaelrid", objective = "Busca al explorador Thaelrid en las Cavernas de Brazanegra.", description = "Estos últimos días circulan muchos rumores sobre la reunión del Martillo Crepuscular y los nagas en las Cavernas de Brazanegra al oeste.\n\nEstoy aquí para reunir toda la información que pueda para que sepamos dónde y cuándo necesitaremos ayuda.\n\nHace unos días envié a un explorador para observar la actividad de las Cavernas de Brazanegra... Pero el explorador Thaelrid aún no ha regresado.\n\nMis otros exploradores están ocupados con asuntos más urgentes.\n\nBusca a Thaelrid por mí, <nombre>.", progress = nil, completion = "El vigía del alba Shaedlass ha sido muy considerado al enviarte. Sin duda en este corrupto lugar se está tramando un oscuro complot.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1199] = {title = "Cascada Crepuscular", objective = "Lleva 10 colgantes Crepusculares a la centinela Aluwyn en el Campamento Brazanegra.", description = "Con el poder que les confieren los ritos de los caóticos dioses antiguos, los miembros del Martillo Crepuscular trabajan para devolver a sus oscuros Señores a este mundo y así extender la muerte y el terror por él.\n\nCreemos que el Martillo Crepuscular se ha aliado con los nagas. Se están concentrando en las Cavernas de Brazanegra, al oeste.\n\nDebemos frustrar los planes que se forjan en las profundidades del viejo santuario, sean cuales sean.\n\nEnfréntate al Martillo y tráenos pruebas de tus hazañas. Tus esfuerzos serán ampliamente recompensados.", progress = "Las Cavernas de Brazanegra una vez fueron un templo de los elfos de la noche. Albergaban una Poza de la Luna de gran poder. Quién sabe qué mal se está fraguando allí a manos del Martillo Crepuscular.\n\n¿Has hecho algún progreso en tu misión de eliminarlos?", completion = "Sin duda eres valiente y de sangre noble, &lt;nombre&gt;. El Alba Argenta te felicita por tus actos contra el mal.", rewards = "Maza de BrazanegraOfrenda del árbol enigmáticoMusleras de AluwynRecibirás:\n\nBotas NimbusFaja de duramen"}
MultiLanguageQuestData['mx'][1200] = {title = "La vileza de Brazanegra", objective = "Llévale la cabeza del señor crepuscular Kelris a Ashelan Bosquenorte en el Campamento Brazanegra.", description = "Las fuerzas me han abandonado. ¡Necesito tu ayuda!\n\nOtrora este lugar era un gran templo de Elune. Pero la desgracia lo ha llevado a la ruina cuando la corrupción de un dios antiguo empezó a calar desde el subsuelo y contaminó la sagrada Poza de la Luna.\n\nAku'Mai, sirviente del dios antiguo, surgió de las aguas.\n\nLos adeptos del Martillo Crepuscular se han unido a los nagas para ocupar esas tierras. Esos adeptos, cuyo jefe es Kelris, sacrifican a inocentes a Aku'Mai a cambio de poder.\n\nMata a Kelris y llévale su cabeza a Ashelan en el Campamento Brazanegra, <nombre>, te lo ruego.", progress = "El tiempo es un recurso muy preciado, <clase>.\n\nMi rol aquí en Darnassus es asegurarme de que el Alba Argenta prospere y las fuerzas malignas que amenazan Kalimdor sean eliminadas.\n\nDi a qué viniste de una vez o márchate.", completion = "Kelris nos ha evitado por mucho tiempo.\n\nParece que siempre que el mal se hacía presente en estas partes, Kelris estaba involucrado. Por mucho tiempo creímos que estaba muerto o había desaparecido.\n\nPero esto tiene mucho sentido. Al poner fin a su reino de tiranía has salvado las vidas de muchos inocentes.\n\n¡Por la Luz! ¡Sacrificar a alguien ante un sirviente de un dios oscuro a cambio de un beneficio personal es más que despreciable!\n\nHas realizado una gran hazaña, &lt;nombre&gt;. Te saludo en nombre del Alba Argenta.", rewards = "Cetro de lápidaRodela árticaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1201] = {title = "Los espías de Theramore", objective = "Mata a 9 infiltrados de Theramore y luego reúnete con Nazeer Picasangre en el Poblado Murohelecho.", description = "La tregua de Horda y la Alianza peligra. Ambas partes intentan dañar a la otra. Refriegas, acciones encubiertas... ¡Nuestro deber es asegurarnos de que gane la Horda!\n\nY esta es nuestra oportunidad de conseguirlo.\n\nHay infiltrados de la Alianza al este del Poblado Murohelecho. Espían el poblado e informan de nuestros movimientos a Theramore, cosa que no podemos permitir.\n\nDa caza a los infiltrados y mátalos. Envía un claro mensaje a sus superiores: ¡no toleraremos la presencia de sus espías!", progress = nil, completion = "Buen trabajo. Sus infiltrados son buenos, ¡pero no lo suficiente para escapar al ojo vigilante de la Horda!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1202] = {title = "El puerto de Theramore", objective = "Lleva los documentos del Capitán a Nazeer Picasangre al Poblado Murohelecho.", description = "<nombre>, enviamos a dos de nuestros espías a robar documentos de un navío de los puertos de Theramore. Consiguieron los papeles, pero fueron descubiertos y se vieron obligados a tirarlos al mar.\n\nUno de ellos consiguió escapar más tarde, pero no logró recuperar los documentos. Vino a mí a informar de su fracaso y ahora yo te encargo a ti la misión.\n\nLos documentos están en un baúl, en las aguas del puerto de Theramore. Encuéntralos y tráemelos aquí, <nombre>.", progress = "¿Encontraste los documentos, <nombre>? Contienen información vital para la estabilidad de la Alianza y, por tanto, vital para la seguridad de la Horda.", completion = "Buen trabajo, &lt;nombre&gt;. Y no era una misión fácil. Pero nuestros superiores valoran muchísimo los documentos que has conseguido.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1203] = {title = "Jarl necesita una hoja", objective = "Lleva la espada de Espinafilada a \"Ojolodo\" Jarl, en la Mansión Cienaluz.", description = "Tengo algo que cortar. No puedo decirte qué voy a cortar, pero... Necesito una hoja. Una en concreto...\n\nHay quien la llama espada. Yo prefiero llamarla hoja.\n\n¿Me ayudas? Esos hombres-pez, ya sabes, los múrlocs o como se llamen. Hay uno al que llaman Espinafilada, que lleva una gran espada y vive al norte, cerca de la playa. ¡Esa es la espada que necesito!\n\nPero no te duermas en los laureles. Lo que quiero cortar no esperará para siempre...Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Calzas de artesanoCinturón \"Ojo del pantano\"Podrás elegir una de estas recompensas:\n\nAnillo Nudo de Junco\n\nTambién recibirás:\n\nCalzas de artesanoAnillo Nudo de Junco"}
MultiLanguageQuestData['mx'][1204] = {title = "Sopa de Fangorroca con tropezones", objective = "Lleva 8 lenguas Fangorroca bífidas a Morgan Stern a Theramore.", description = "Estoy trabajando en un plato que llamaré \"sopa de Fangorroca con tropezones\". Pero necesito los ingredientes principales y... bueno, no puedo ir a buscarlos al Marjal Revolcafango, ¡no creo que durara mucho allí!\n\nQuizás podrías ir tú por mí, <nombre>. Para empezar, necesito lenguas de tortugas Fangorroca. Puedes encontrar tortugas Fangorroca en la costa, sobre todo en la bahía.\n\n¡Pero no me sirve cualquier lengua! Sé que algunas Fangorroca tienen lenguas bífidas...\n\nY se dice que las lenguas bífidas tienen un sabor especial... Quiero ese sabor en mi plato.", progress = "¿Has conseguido las lenguas bífidas?", completion = "¡Estas son estupendas! ¡Gracias, &lt;nombre&gt;! \n\nAhora probaré a cocinar estas lenguas con diferentes técnicas para encontrar la que más realce su sabor. \n\n¡Conseguiré un plato digno de servirse en El Ermitaño Taciturno de Ventormenta!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1205] = {title = "Lodomuerto", objective = "Lleva el Diente de Lodomuerto a Melor a Cima del Trueno.", description = "Lodomuerto es un anciano crocolisco del Marjal Revolcafango. Y ha llegado su hora.\n\nSus viejos huesos crujen cuando desplaza su enorme cuerpo por el pantano y aunque aún se mueve con el vigor y la velocidad de un joven, su anciano cuerpo tortura al gran espíritu que lo habita, un espíritu cuya llama no se extinguirá.\n\nSigue viviendo con constantes y enloquecedores dolores. Debes poner fin a la vida de esta noble criatura, <nombre>. Debes dar paz a Lodomuerto.", progress = "¿Tienes el diente de Lodomuerto, <nombre>? ¿Has acabado con los sufrimientos de la criatura?", completion = "Muy bien, &lt;nombre&gt;. \n\nSeguro que la caza no fue fácil, pero me alegra saber que has puesto fin al sufrimiento de la pobre bestia.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1206] = {title = "Jarl necesita ojos", objective = "Lleva 20 ojos de Niebla Negra sin reventar a \"Ojolodo\" Jarl a la Mansión Cienaluz.", description = "El zumo de ojo es una bebida estupenda. Es una pena que la mayoría de los bichos solo tengan dos ojos.\n\nPero las arañas tienen muchos. Muchos, muchos. Y el zumo de ojo de araña Niebla Negra está muy rico. ¡Suavecito y salado! Redonditos ojos de araña... Se me hace la boca agua...\n\nLas arañas Niebla Negra están al oeste de aquí, en la Cueva Niebla Negra. Está claro que las arañas llevan el nombre de la cueva en la que viven... ¿o será al revés?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1218] = {title = "Ancas de rana de marisma", objective = "Lleva 10 ancas de rana de marisma a \"Ojolodo\" Jarl al Marjal Revolcafango.", description = "Me gusta cocinar. Sobre todo, la buena cocina del pantano. Ancas de rana verdes fritas y esas cosas.\n\nY me he quedado sin ancas. Pero, la casa está llena de ranas. Ranas de marisma gigantes. ¿Podrías traerme algunas de esas ancas? No es muy difícil, solo golpéalas en la cabeza y tráeme las ancas.\n\nLo removeré y removeré y luego me lo comeré. Y también te daré un poco a ti.\n\n¿Te gustan los guisos?Recibirás:\n\n", progress = nil, completion = nil, rewards = "Botas de ranaBraciles de pantanoRecibirás:\n\nEstofado de anca de rana"}
MultiLanguageQuestData['mx'][1219] = {title = "l informe orco", objective = "Lleva el informe de espía al teniente Aden a Theramore.", description = "Una criba de la tierra revela la mano cortada de un orco. En la mano hay un tubo de hueso. Y en el tubo, un papiro manchado de tierra.\n\nEl pergamino está escrito en lenguaje orco... y parece importante.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1220] = {title = "Capitán Vimes", objective = "Lleva el informe de espía al capitán Garran Vimes.", description = "El capitán Vimes debería ver el informe orco que encontraste, <nombre>. Conoce el idioma orco mejor que muchos. ¡Y debería saber que hay espías de la Horda cerca de Theramore!\n\nEl Capitán está en los barracones que hay en la parte noreste de la Isla Theramore.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1221] = {title = "Los tubérculos hojazul", objective = "Coge un cajón con agujeros.\nCoge una vara de mando de husmeador.\nLee el manual de propietario de husmeador. \n\nCuando llegues a Horado Rajacieno, usa el cajón con agujeros para invocar un husmeador taltuza; usa la vara para que busque tubérculos. \n\nLleva 6 tubérculos hojazul, la vara de mando de husmeador y el cajón con agujeros a Mebok Mizzyrix a Trinquete.", description = "Los tubérculos hojazul son muy apreciados en todo el mundo. Pero son muy raros. Solo se encuentran aquí, en Los Baldíos, enterrados profundamente en Horado Rajacieno.\n\n¡Y es imposible encontrarlos a no ser que sepas dónde mirar! Por eso he amaestrado husmeadores taltuza para que los busquen. Tienen un olfato extraordinario, huelen los tubérculos a una distancia de 50 pasos.\n\nNo será fácil, pero si me traes tubérculos te pagaré muy bien.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nUn pequeño contenedor de gemas"}
MultiLanguageQuestData['mx'][1222] = {title = "La fuga de Apestoso", objective = "Escolta a \"Apestoso\" Ignatz y luego ve a Theramore a hablar con Morgan Stern.", description = "¡Genial! ¡Por fin algo que no quiere comerme!\n\nNecesito ayuda con los bichos de por aquí. Y tú pareces ser justo lo que necesito, <chaval/señorita>.\n\nEl cocinero Morgan Stern está trabajando en una nueva receta y me ha mandado aquí a recoger hojas de cienagrana. Creo que opina que son sabrosas.\n\nEs lo mismo... el caso es que cuando buscaba una planta de cienagrana... ¡Me vi rodeado! ¿Podrías ayudarme a salir de aquí y vigilarme las espaldas mientras busco la cienagrana?", progress = nil, completion = "El señor Ignatz ha estado aquí con las hojas de cienagrana y me dijo que le habías ayudado a salir de un auténtico atolladero.\n\nTe lo agradezco, &lt;nombre&gt;. Pediré a mi tío que te invite a un festín la próxima vez que vayas a El Ermitaño Taciturno de Ventormenta.", rewards = "Recibirás:\n\nElixir de entereza"}
MultiLanguageQuestData['mx'][1238] = {title = "El informe perdido", objective = "Lleva el informe de espía a Nazeer Picasangre al Poblado Murohelecho.", description = "Una criba de la tierra revela la mano cortada de un orco. En la mano hay un tubo de hueso. Y en el tubo, un papiro manchado de tierra.\n\nEl pergamino es el informe de un orco que pasó semanas espiando la ciudad de Theramore.\n\nCon una rápida lectura del pergamino te das cuenta de que debes llevarlo al maestro de espías orco del Poblado Murohelecho.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1240] = {title = "El trol médico brujo", objective = "Lleva la cabeza de orco desafiante a Kin'weelay al Campamento Grom'Gol de Vega de Tuercespina.", description = "¡Debemos conocer las circunstancias de la muerte de Marg! Y la única forma de conocerlas, <nombre>, es a través de la magia de los trols.\n\nLleva la cabeza de Marg a Kin'weelay. Está en el Campamento Grom'Gol, en la Vega de Tuercespina.\n\nKin'weelay es el médico brujo de los trols Lanza Negra. Es muy poderoso. Si alguien puede hablar al espíritu de Marg Ojonocturno, ese es él.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1241] = {title = "El diplomático desaparecido", objective = "Encuentra a Jorgen en la Ciudad de Ventormenta.", description = "Recientemente, un diplomático fue enviado a Theramore para encontrarse con Jaina Valiente. Ese diplomático nunca llegó a su destino.\n\nCreo que los Defias están implicados, aunque no sé exactamente cómo. La desaparición del diplomático sigue sin ser del dominio público, pero no seguirá así mucho tiempo.\n\nHay unos agentes del rey explorando la ciudad en busca de pistas, pero tengo a mis propios contactos que me gustaría que trabajasen en esto.\n\nEn el Valle de los Héroes hay un viejo amigo mío llamado Jorgen. Encuéntrale, dale esta nota y sigue sus instrucciones.", progress = "Mmm, será mejor que tengas una buena razón para interrumpir a un hombre que está pescando. No me gustan mucho los vendedores ambulantes y mucho menos los vagabundos.", completion = "Mmm... &lt;Jorgen te mira con los ojos entrecerrados.&gt; \n\nMuy bien. Te ayudaré, pero no porque quiero hacerlo, sino porque estoy obligado. \n\nY dejemos una cosa clara: sabes más de lo que deberías saber. Mantengamos esto en secreto y no vayas por las tabernas por ahí hablando de tus descubrimientos. ¿Comprendido?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1243] = {title = "El diplomático desaparecido", objective = "Entrega la nota lacrada al vigía Backus en el Bosque del Ocaso.", description = "Jorgen, viejo hijo de... Así que, ¿así es como va a ser, eh?\n\nPues muy bien, puedo con eso. Espero que encuentre El Vacío Abisal muy pronto.\n\nEsto es lo que va a pasar, <nombre>. Empezaré a usar mis contactos aquí, pero tú vas a encargarte de los paseítos, no quiero perder dinero.\n\nVete a Villa Oscura en el Bosque del Ocaso y encuentra al vigía Backus. Generalmente patrulla el camino del norte justo fuera de la ciudad. Dile que estás buscando actividad Defias, que yo te lo he pedido y te ayudará dándote toda la información que pueda.", progress = "No es demasiado seguro ir por el bosque, <nombre>. Ten cuidado y, si ves algo sospechoso o peligroso, avisa a los vigilantes inmediatamente. No intentes nada sin ayuda. No nos hacemos responsables de ninguna cosa terrible que te pueda suceder.\n\nPero ambos sabemos que vas a pasar de mí y a luchar contra cualquier cosa que aparezca en medio de la oscuridad, ¿verdad? ¡Ja, ja! Sí, ustedes, los aventureros... son todos iguales.", completion = "¿Te envía Trias, eh? Eso cambia la cosa. \n\nEntonces, puedes luchar contra cualquier monstruosidad que salga de la oscuridad. Seguro que podrás vencer lo que sea fácilmente, ya que eres capaz de tratar con gente de su calaña. \n\nY bien, ¿para qué me necesita mi amigo en un día tan fúnebre como este?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1244] = {title = "El diplomático desaparecido", objective = "Encuentra el certificado Defias y llévaselo al vigía Backus en el Bosque del Ocaso.", description = "¿Actividad Defias? Bueno, siempre hay actividad; incluso si están tranquilitos, les seguimos considerando una amenaza.\n\nPero ahora que lo pienso, hace poco tiempo vimos algo extraño. Debe de haber sido hace un par de semanas, algunos de sus agentes se habían reunido en la Granja de Addle. Según el informe, supuse que algo grande estaba pasando.\n\n¿Por qué no vas a echar un vistazo y me traes lo que encuentres?\n\nLa granja está al sur del camino de los Páramos de Poniente, justo al entrar en el Bosque del Ocaso.", progress = "Ten cuidado ahí fuera, <nombre>. Sé que Trias fue quien te envió, pero eso no significa que no haya nada acechando en los bosques que podría causarte un par de problemas... especialmente contigo investigando a los Defias.", completion = "Has vuelto de una pieza. Y no se puede pedir mucho más que eso, ¿eh? \n\nAhora, veamos lo que tenemos aquí. Esto parece bastante oficial, a juzgar por los documentos Defias que he visto. Pero podría ser una falsificación, solo para hacerte perder la pista de lo que estés buscando.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1251] = {title = "l escudo negro", objective = "Lleva el escudo de hierro ennegrecido a Krog al Poblado Murohelecho.", description = "Un escudo de hierro, ennegrecido por el fuego que arrasó la posada, cuelga de la chimenea, una de las pocas partes de la estructura de la Posada Reposo Umbrío que han sobrevivido.\n\nEl escudo puede separarse del ladrillo de la chimenea.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1252] = {title = "Teniente Paval Reethe", objective = "Lleva el distintivo de Reethe al capitán Garran Vimes de Theramore.", description = "Debajo de los escombros, en el suelo, ves un destello de luz. Apartas los escombros y la ceniza y descubres una insignia de esmalte blanco con un ancla de oro: el sello de Theramore.\n\nDebajo del ancla hay un nombre grabado: \"Teniente Paval Reethe\".Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1253] = {title = "El escudo negro", objective = "Lleva el escudo de hierro ennegrecido al capitán Garran Vimes a Theramore.", description = "Un escudo de hierro, ennegrecido por el fuego que arrasó la posada, cuelga de la chimenea, una de las pocas partes de la estructura de la Posada Reposo Umbrío que han sobrevivido.\n\nEl escudo puede separarse del ladrillo de la chimenea.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1258] = {title = "...con tropezones", objective = "Lleva 12 patas de reptador prístinas a Morgan Stern a Theramore.", description = "Otro ingrediente para mi nueva receta es la pata de cangrejo gigante sin pelar. Para ello, los cangrejos del Marjal Revolcafango, esos que llaman reptadores de roca espinosos, ¡serían perfectos!\n\nLa cáscara de la pata de cangrejo es un elemento clave de la presentación del plato, así que necesito patas impolutas, sin marcas. Un cangrejo adulto solo tiene una o dos patas de esas y yo necesitaré muchas para mis pruebas.\n\nDirígete a las rocas que rodean Theramore y ¡consígueme esas patas!", progress = "Mis experimentos con las lenguas Fangorroca bífidas van estupendamente. Espero que tu caza de cangrejos esté yendo bien también...", completion = "¡Estupendos ejemplares, &lt;nombre&gt;! Están en perfectas condiciones, y la carne está rosadita y tierna. ¡Tienes sangre de chef corriendo por tus venas!", rewards = "Escudo barrocoVarita trepadoraRecibirás:\n\nMandil barroco"}
MultiLanguageQuestData['mx'][1259] = {title = "Teniente Paval Reethe", objective = "Averigua más sobre Reethe hablando con el ayudante Tesoran en Theramore.", description = "No reconozco el nombre... Teniente Paval Reethe... Será mejor que consultes al ayudante Tesoran. Él lleva todos los registros de la Guardia de Theramore, desde el personal hasta el equipamiento.\n\nÉl debería poder decirte quién es Reethe, solo tendrá que echar un vistazo a los libros.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1260] = {title = "organ Stern", objective = "Habla con Morgan Stern en Theramore.", description = "Estoy preparando un nuevo menú para el restaurante. Estará lleno de platos rurales con un mismo tema: el pantano. ¡Seguro que a mis clientes de El Ermitaño Taciturno les encanta!\n\nEnvié a mi sobrino Morgan a Theramore, una ciudad que hay en la frontera del Marjal Revolcafango. Está recogiendo recetas de sus habitantes y necesito saber qué ha conseguido hasta ahora.\n\nEl viaje a Theramore es largo. Demasiado para mí. Pero seguro que <un/una> <clase> como tú, aprovecha cualquier oportunidad para viajar.", progress = nil, completion = "Ah, así que te envía mi tío, ¿eh? \n\nBueno, he estado investigando unas recetas, y tengo algunas pistas, pero necesito ayuda. \n\nAyuda de alguien a quien no le importe mojarse los pies.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1261] = {title = "Las declaraciones de Marg", objective = "Lleva el colgante enjoyado a Nazeer al Poblado Murohelecho.", description = "¡Maldito Valvafango! ¡No puedes matar a Marg! Ah... pero estoy muerto. Así que debió de matarme...\n\n¡Mi misión! ¡Mi misión! <nombre>, debes completarla.\n\nCuando estaba cerca de Theramore, estuve espiando a un grupo de soldados de la Alianza que había acampado en la playa. Uno de esos soldados llevaba un colgante cargado de gemas. ¡Ningún soldado puede permitirse un colgante así!\n\nUna noche me colé en su campamento y robé el colgante, ¡pero cuando regresaba a la base, uno de esos hombres-cangrejo Valvafango me mató!\n\n¡<nombre>, debes encontrar a ese Valvafango y recuperar el colgante!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1265] = {title = "El diplomático desaparecido", objective = "Explora el Alto del Centinela en busca de alguna señal del soldado Hendel.", description = "¿Hendel? Sí, le conozco. ¿Pero para qué necesitas a uno de mis soldados?\n\n¿Elling te ha enviado a buscarle? Mmm, no me gusta cómo suena eso. Elling no te habría pedido que vinieses primero a hablar conmigo si no se tratase de algo preocupante. Comprendo que no puedas decirme de qué va el tema, pero has de saber algo. Mi deber es proteger estas tierras. Si vas a causar problemas, te sugiero que me informes de todo lo que puedas.\n\nCreo que Hendel estaba destinado a la primera torre de las afueras de Theramore. Ten cuidado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1266] = {title = "El diplomático desaparecido", objective = "Encuentra al soldado Hendel en el Marjal Revolcafango.", description = "El soldado Hendel está al oeste de aquí. Actualmente está de guardia, protegiendo a algunos de los infiltrados de Theramore mientras descansan. Han estado vigilando la base de la Horda, Murohelecho, y atentos a cualquier otra amenaza potencial en nuestras fronteras.\n\nNo deberías tener problemas para encontrarle. Busca las tiendas que están junto al camino.\n\nTengo que encargarme de otro asunto, pero hablaremos pronto. Si me necesitas, puedes encontrarme en la torre de Lady Valiente.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1267] = {title = "El diplomático desaparecido", objective = "Habla con Jaina Valiente en el Pantano Revolcafango.", description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de Jaina"}
MultiLanguageQuestData['mx'][1268] = {title = "uellas de pezuñas sospechosas", objective = "Informa a Krog en el Poblado Murohelecho sobre las huellas sospechosas de la Posada Reposo Umbrío.", description = "Hay hileras de huellas que se alejan del esqueleto, aún humeante, de la Posada Reposo Umbrío. Hay unas pocas impresiones visibles y algunas hileras de huellas casi imperceptibles en el barro blando del pantano.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1269] = {title = "eniente Paval Reethe", objective = "Lleva el distintivo de Reethe a Krog al Poblado Murohelecho.", description = "Debajo de los escombros, en el suelo, ves un destello de luz. Apartas los escombros y la ceniza y descubres una insignia de esmalte blanco con un ancla de oro: el sello de Theramore.\n\nDebajo del ancla hay un nombre grabado: \"Teniente Paval Reethe\".Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1270] = {title = "La fuga de Apestoso", objective = "Escolta a \"Apestoso\" Ignatz y luego ve a Trinquete a hablar con Mebok Mizzyrix.", description = "¡Genial! ¡Por fin algo que no quiere comerme!\n\nNecesito ayuda con los bichos de por aquí. Y tú pareces ser justo lo que necesito, <chaval/señorita>.\n\nUn goblin de Trinquete llamado Mebok Mizzyrix necesita unas hojas de cienagrana para una poción o algo así... Tampoco es que me importe mucho. Me dio un buen dinero y conozco el pantano, así que...\n\n¡Una pena que me rodearan antes de que encontrara la cienagrana! ¿Puedes ayudarme? ¿Podrías cubrirme las espaldas mientras busco la planta de Mebok?", progress = nil, completion = "Vino Apestoso con las hierbas que le pedí y me dijo que le habías ayudado a salir de un aprieto. ¡Bien hecho! ¡Un amigo de Apestoso es amigo mío! \n\nPoco antes de dirigirse hacia el sur, hacia el pantano, me pidió que te diera esto si te veía.", rewards = "Recibirás:\n\nElixir de entereza"}
MultiLanguageQuestData['mx'][1271] = {title = "¡Una fiesta en tu honor!", objective = "Mi sobrino me dijo que le habías ayudado en su investigación en Revolcafango y que sacaste a su socio de un buen apuro. ¡Pues los Stern estamos muy unidos y atendemos a nuestros amigos! \n\nAsí que lávate las manos, <nombre>, ¡porque estamos a punto de montar una fiesta en tu honor!", description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nToallita húmeda"}
MultiLanguageQuestData['mx'][1274] = {title = "El diplomático desaparecido", objective = "Encuentra al Obispo DeLavey en el Castillo de Ventormenta.", description = "Disculpa, noble <caballero/gentil dama>. El Obispo DeLavey me pidió que buscara la ayuda de aventureros que quizás puedan ayudarle.\n\nSi pudieras ir discretamente al Castillo de Ventormenta a hablar con él, seguro que te lo agradecería mucho. Y, de nuevo, por favor, con mucha discreción. Se trata de un asunto muy importante.", progress = nil, completion = "Hola, &lt;nombre&gt;. Soy el Obispo DeLavey. \n\nSin duda, si estás aquí preguntándome sobre mi asunto del Castillo, es porque el joven Thomas ha tenido éxito a la hora de pedirte ayuda para nuestro reino. Siempre ha sido experto en hacer lo que le pido. \n\nMe temo que no tengo mucho tiempo para explicarme, así que iré directo al problema... y, por favor, intenta que nadie se entere de esto.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1275] = {title = "Investigaciones acerca de la corrupción", objective = "Relwyn Sombrestrella en el Campamento Brazanegra quiere 8 bulbos raquídeos corruptos.", description = "Esos insensatos elfos de sangre están estudiando la magia demoníaca. ¿Acaso no vieron lo que ocurrió con los nagas y los sátiros de Kalimdor?\n\nTemo que los elfos de sangre acabarán sufriendo una deformación similar. Azeroth no puede permitirse el surgimiento de otra raza de monstruos maléficos.\n\nQuisiera estudiar los cerebros de los sátiros y los nagas. Quizás consiga averiguar qué destino espera a los sin'dorei. Puedes encontrar sátiros y naga en las Cavernas de Brazanegra, al oeste.", progress = "Cuando tenga suficientes muestras, podré empezar a trabajar de verdad. Con los bulbos raquídeos corruptos de los sátiros y los nagas de las Cavernas de Brazanegra podré encontrar la correlación entre las mutaciones.\n\nQuizás, una vez identificada, podré impedir que la deformidad y el mal arraiguen más en los elfos de sangre.", completion = "Has viajado mucho y sin duda te has enfrentado a grandes peligros.\n\nTus acciones han sido altruistas. Es por el bien de todo Azeroth que me ayudas con esta investigación. Te agradezco todo lo que has hecho, &lt;nombre&gt;.\n\nAhora, si me disculpas, tengo mucho trabajo que hacer...", rewards = "Broches de alfazaquesManteo de prelaciónDisectorMaza SombrestrellaVarita de búsquedaPodrás elegir una de estas recompensas:\n\nSortija del Trituracráneos\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][1282] = {title = "e llaman Jim Sonrisas", objective = "Habla con el capitán Garran Vimes que está en el piso de arriba de la Ciudadela Garrida.", description = "El viejo Jim me da mucha pena. Antes no era así. Llevó una posada en la marisma durante un tiempo; un lugar fantástico.\n\nMira, no me apetece mucho hablar del tema. Si realmente quieres saber qué ocurrió, habla con el capitán Vimes. Está apostado en el piso de arriba de la Ciudadela Garrida, en los grandes barracones que hay al este de la torre de Lady Jaina.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1284] = {title = "Huellas de pezuñas sospechosas", objective = "Informa al capitán Garran Vimes de Theramore sobre las huellas sospechosas de la Posada Reposo Umbrío.", description = "Hay hileras de huellas que se alejan del esqueleto, aún humeante, de la Posada Reposo Umbrío. Hay unas pocas impresiones visibles y algunas hileras de huellas casi imperceptibles en el barro blando del pantano.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1285] = {title = "Los hombres de Daelin", objective = "Lleva la información sobre Reethe al capitán Garran Vimes a Theramore.", description = "Reddon... Redpath... Ah, aquí está. Teniente Paval Reethe.\n\nSe unió a la Guardia de Theramore junto con los reclutas que llegaron del mar con Lady Valiente. Se alistó con los marinos de Kul Tiras a la edad de dieciséis años. Servicio distinguido, ascensos...\n\nConsta como desaparecido.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1286] = {title = "Los desertores", objective = "Consigue información sobre Reethe hablando con Balos Jacken y los desertores del Marjal Revolcafango.", description = "Mantener nuestra presencia en la marisma ha sido una lucha constante. Pero con la fuerza de nuestra determinación, hemos conseguido mantener varias atalayas defensivas en la zona.\n\nLos últimos informes que he recibido de los exploradores indican que hay un grupo de desertores en una de nuestras torres abandonadas en Punta Perdida, al sureste de la posada.\n\nEl teniente que los lidera se llama Balos Jacken. Ve a ver si consigues algo de información de él.\n\nPero ten cuidado, <nombre>. Será duro de pelar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1287] = {title = "Los desertores", objective = "Ve a Theramore y habla con el capitán Garran Vimes sobre Reethe.", description = "¿Reethe? ¿Ese cobarde?\n\nLo expulsamos del campamento porque insistía en robar los suministros de los ogros del Poblado Murohelecho. Y no somos tantos como para afrontar a esos brutos inconscientes.\n\nCruzó la línea demasiadas veces, así que dejamos que se las apañara solito.\n\nBien, yo te he ayudado... ¿Qué tal si ahora nos ayudas tú olvidando que nos has visto?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1301] = {title = "ames Hyal", objective = "Ve al Puerto de Menethil y habla con Vincent Hyal.", description = "Antes de trabajar aquí, en El Ermitaño Taciturno, me formó uno de los mejores chefs y taberneros que he conocido en mi vida. Su nombre era James Hyal. Todo lo que tengo se lo debo a él. Gracias a él he llegado hasta aquí.\n\nMe pregunto cómo le va... Su hermano Vincent y él fueron a trabajar a una posada del Puerto de Menethil, pero no sé nada de él desde hace un tiempo.\n\nSi alguna vez te acercas por allí, ¿podrías saludarlo de mi parte?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1302] = {title = "ames Hyal", objective = "Habla con el secretario Lendry, que está en la Ciudadela Garrida en Theramore.", description = "Mi hermano James cruzó el mar con Lady Valiente. Lo último que oí es que la lucha había cesado en la zona y que James había abierto una posada en algún lugar del continente. Esté donde esté, seguro que el negocio le va bien. Era un cocinero estupendo.\n\nHace tiempo que no sé nada de él... estará ocupado con su posada. Seguro que el secretario de Theramore puede decirte algo más. Búscale en el piso de arriba del asentamiento que hay cerca del centro de la ciudad. ¿Cómo se llama...? Ciudadela Garrida, eso es.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1319] = {title = "El escudo negro", objective = "Ve a Theramore y enseña el escudo de hierro ennegrecido a Caz Dosdientes.", description = "Siento no ser de más ayuda, <nombre>, pero puedo remitirte a alguien que podrá serlo. Caz Dosdientes, uno de nuestros mejores herreros. Trabaja en la forja de la herrería.\n\nLlévale el escudo. A ver qué puede decirte sobre él.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1320] = {title = "El escudo negro", objective = "Ve a Theramore y habla con el capitán Garran Vimes.", description = "Ah, casi se me escapa esto... La tira de cuero del reverso ha debido de quemarse... pero parece que se hizo para una persona de gran tamaño. Creo que para un tauren, de hecho.\n\nNo puedo decirte nada más. Di al capitán Vimes que siento no poder ser de más ayuda.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1324] = {title = "El diplomático desaparecido", objective = "Derrota al soldado Hendel en el Marjal Revolcafango.", description = "¡¿Qué?! ¡¿Vienes aquí acusándome de ser aliado de los Defias y crees que me voy a quedar callado mientras me insultas?! Algo me dice que llevas mucho tiempo planeando esto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1338] = {title = "Un pedido de Pico Tormenta", objective = "Lleva el pedido de Pico Tormenta a Furen Barbalarga a Ventormenta.", description = "Hay un forjador de armaduras enano cuyo trabajo me gusta mucho. Se llama Furen Barbalarga y es el mejor de su gremio. Necesito un escudo nuevo, y quiero que me lo haga él.\n\nSolo hay un problema... Furen vive muy al sur, en el Distrito de los Enanos de Ventormenta. ¡En tierra humana! No entiendo por qué vive ahí, tan lejos de Forjaz. ¡Será que los humanos le pagan una fortuna!\n\nSi te apetece viajar y ganar algo de dinero, ve a ver a Furen para hacer mi pedido de un escudo.", progress = "¿Una carta de tierras enanas? No sé quién me escribirá de tan al norte...\n\nA ver, déjame ese pedido.", completion = "Ah, un pedido de un Pico Tormenta... Es un orgulloso clan que cuenta con enanos de gran calidad. Ricos también.\n\nGracias, &lt;nombre&gt;. Al final del día me pondré con el pedido del escudo del montaraz Pico Tormenta.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1339] = {title = "La tarea del montaraz Pico Tormenta", objective = "Habla con el montaraz Pico Tormenta.", description = "Dicen que el montaraz Pico Tormenta busca alguien que le haga de mensajero. Alguien con ganas de viajar un poco. ¿Qué te parece? ¿Te ves capaz, <raza>?\n\nEntonces, ve a hablar con Pico Tormenta en la cima de la torre norte.", progress = nil, completion = "Pues sí, tengo un trabajito que te llevará lejos de Loch Modan. \n\n¡Ya tienes otra aventura servida!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1358] = {title = "Muestra para Helbrim", objective = "Lleva la muestra de corazón de lobo al boticario Helbrim en Los Baldíos.", description = "Un colega de Kalimdor, el boticario Helbrim, está investigando los efectos de las toxinas de Lordaeron en las bestias de Kalimdor. Estaría muy interesado en una muestra de los corazones de lobo que Renferrel me envió.\n\nHelbrim está en Los Baldíos, en una aldea conocida como El Cruce. Para llegar a él, deberás viajar en zepelín hasta la capital orca de Orgrimmar y, a continuación, dirigirte a pie hacia Durotar. Sigue en dirección oeste por Los Baldíos y pronto llegarás a la aldea El Cruce.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de cerveceroManteo de caída largaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1359] = {title = "Una entrega de Zinge", objective = "Lleva las muestras de corazón de lobo a la boticaria Zinge en Entrañas.", description = "Los corazones de lobo que conseguiste, poseen una calidad nunca vista antes en especímenes similares. Tienen tal grado de toxicidad que deberían ser mortales incluso para los lobos en los que laten esos corazones.\n\nEs bastante impresionante, y debemos estudiarlo en profundidad. He guardado algunas muestras de los corazones. Llévaselas a mi colega, la boticaria Zinge. La encontrarás en nuestro puesto de mando, en Entrañas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1360] = {title = "Los tesoros reclamados", objective = "Recoge la posesión más preciada de Krom Brazorrecio de su cofre, que está en la Sala Comunal Norte de Uldaman, y llévasela a Forjaz.", description = "Tenía un trabajo estupendo en la excavación de Uldaman en las Tierras Inhóspitas; todo iba bien hasta que aparecieron los malditos troggs. Escapé por los pelos y con lo puesto. Me dejé mi posesión más preciada. Está en mi cofre, a salvo de los troggs, pero claro, está allí.\n\n¡Te agradecería mucho que me lo trajeras! Está al fondo de la Sala Comunal Norte; tiene mi nombre. Anda, ve.", progress = "Bueno, ¿conseguiste recuperar mi posesión de mi cofre?", completion = "¡Por fin! Te lo agradezco mucho. \n\nAlgunos enanos aman el brillo del metal, otros el resplandor de las gemas... ¡Pero un Brazorrecio tiene sus reliquias personales!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1361] = {title = "Regthar Portamorta", objective = "Habla con Regthar Portamorta.", description = "Un guerrero de la Horda, Regthar Portamorta, está reclutando agentes para una misión en la tierra de Desolace. Habla con él si quieres unirte a los voluntarios. Se encuentra en Los Baldíos, en una serie de búnkeres que hay al oeste de El Cruce.\n\nY afila bien tus armas. Desolace está en guerra.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1362] = {title = "Los Kolkar de Desolace", objective = "Habla con Felgur Doscortes. Está en el Campamento del Espíritu Errante, en Desolace.", description = "Los centauros Kolkar viven en Desolace y sus fuerzas se han extendido hasta Los Baldíos. Es un hecho. Por eso tenemos agentes de la Horda lidiando con ellos allí.\n\nPero mientras los centauros conserven su fuerza en Desolace, seguirán siendo una amenaza. Es hora de que nos deshagamos de esa amenaza.\n\nHabla con Felgur Doscortes. Está en el Campamento del Espíritu Errante, en Desolace. Fue enviado a reunir información sobre los centauros. Él sabrá cuál es la mejor manera de tratar con los Kolkar de Desolace.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1363] = {title = "La orden de Mazen", objective = "Habla con el acólito Dellis en Ventormenta.", description = "Cuido de los libros que tenemos aquí, en la biblioteca de la Academia de Artes y Ciencias Arcanas y es mi deber asegurar que todos los tomos y pergaminos mágicos están registrados en todo momento. ¿Quién sabe qué podría ocurrir si alguno de estos textos encantados cayese en las manos equivocadas?\n\nLo que me recuerda... Mi ayudante, Dellis, cometió un terrible error la semana pasada. Es bastante competente en la biblioteca, pero un gran incompetente en cuanto sale por las puertas de Ventormenta. Sé <un héroe/una heroína> y ayuda a Dellis, ¿lo harás?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1364] = {title = "La orden de Mazen", objective = "Recupera los ensayos de Khadgar sobre convergencia dimensional y entrégaselos al vigilante Mahar Ba en el Castillo de Nethergarde.", description = "Las órdenes del maestro Mazen fueron bastante sencillas: llevar un ensayo muy importante al vigilante Mahar Ba en el Castillo de Nethergarde.\n\n¡Pero nunca antes había ido a Las Tierras Devastadas! ¡El viaje fue aterrador!\n\nCuando llegué al Pantano de las Penas, me equivoqué de camino y acabé en el medio de horribles criaturas en forma de planta. Empezaron a acercarse como si fueran a atacar, así que salí corriendo. Pero, al huir, se me cayó el ensayo. Seguro que lo cogió una de las bestias.\n\n¿Podrías recuperarlo y entregárselo a Mahar Ba?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Fajín de maestroBotas del placer erranteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1365] = {title = "Khan Dez'hepah", objective = "Lleva la cabeza del khan Dez'hepah a Felgur Doscortes a Desolace.", description = "Los Kolkar no son los únicos centauros de Desolace. En sus áridas llanuras hay muchos otros clanes, combatiendo y matándose entre ellos. Y eso es bueno. Son fuertes y brutales, nos conviene que luchen entre sí. Si los centauros se unieran contra nosotros, serían un fiero enemigo.\n\nDebemos encargarnos de ellos antes de que unan sus fuerzas.\n\nTu primera tarea será causar un problema al clan Kolkar. Matarás a su líder, el khan Dez'hepah.\n\nEl Poblado Kolkar está al noreste de aquí. Ve. Y que la suerte te acompañe.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1366] = {title = "Colección de orejas", objective = "Lleva 15 orejas de centauro a Felgur Doscortes a Desolace.", description = "Ahora que has asustado a los clanes de centauros, es hora de sangrarlos. Cuando viajes por Desolace, caza centauros. De cualquier clan, no me importa. Pero recolecta orejas. Una horda de orejas.\n\nReduciendo su número reducirás su determinación y borrarás de su cabeza cualquier plan de expansión.\n\nBuena caza, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Fajín lilaManoplas con abrazaderasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1367] = {title = "La alianza con los Magram", objective = "Gana un nivel de reputación de amistoso con los Magram y luego habla con Warug.", description = "Para derrotar a los centauros debemos usar contra ellos su odio natural. Nos aliaremos con uno de los clanes y, a través de ese clan, aprenderemos a derrotar a los demás.\n\nSi eliges aliarte con los Magram, mata a sus enemigos, los Gelkis. Así te ganarás el respeto de los Magram. Cuando creas que tienes su respeto, habla con el portavoz de los Magram, Warug. Está en las afueras del Poblado Magram, al sureste de Desolace.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1368] = {title = "La alianza con los Gelkis", objective = "Gana un nivel de reputación de amistoso con los Gelkis y luego habla con Uthek la Sabia.", description = "Para derrotar a los centauros debemos usar contra ellos su odio natural. Nos aliaremos con uno de los clanes y a través de ese clan, aprenderemos a derrotar a los demás.\n\nSi eliges aliarte con los Gelkis, mata a sus enemigos, los Magram. Cuando te hayas ganado el respeto de los Gelkis, habla con su chamán, Uthek la sabia. Está en las afueras del Poblado Gelkis, al suroeste de Desolace.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1369] = {title = "Lágrimas rotas", objective = "Mantén tu reputación con los Magram y lleva 3 lágrimas rotas a Warug al Poblado Magram.", description = "Los Gelkis creen que nuestra madre, Theradras, nos protege. Son estúpidos. Nadie protege a un centauro. ¡Los Magram no necesitamos protección! ¡Somos los más fuertes!\n\nDemuestra a los Gelkis lo estúpidos que son. Ve a la cueva que hay en su poblado. Allí esconden unos cristales, las lágrimas de Theradras. Destruye las lágrimas y tráeme los fragmentos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1370] = {title = "¡A robar provisiones!", objective = "Lleva 6 bolsas de carne secada de forma rudimentaria a Uthek la Sabia al Poblado Gelkis.", description = "Cuando no estamos combatiendo, cazamos para conseguir carne. La carne nos hace fuertes. Y un estómago satisfecho combate mejor que uno vacío.\n\nLo mismo ocurre con los Magram. Almacenan carne para poder combatir más tiempo seguido sin tener que ir a cazar. Si asaltas su poblado del este y les robas su reserva de carne, les fallarán las fuerzas.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nFlecha de plumasProyectil detonanteEstrella de plata\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][1371] = {title = "Un cacharro para Warug", objective = "Mantén tu reputación con los Magram y lleva 1 muñeco-diana avanzado a Warug al Poblado Magram de Desolace.", description = "Hace mucho tiempo, llegó un pequeño gnomo a Desolace. Tenía caballos y una carreta y en la carreta llevaba cosas muy extrañas. Cosas divertidas. Cosas que se quemaban con humo de diferentes colores. Cosas que se movían aunque no estaban vivas. Yo maté al pequeño gnomo, pero antes de eso... me hizo reír.\n\nY me quedé lo que más me gustó de su carreta. Era un humano hecho de madera que me saludaba hasta que un día le pegué y se rompió.\n\nQuiero otro. ¡Consígueme uno nuevo!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1372] = {title = "El suero de la verdad", objective = "Ve al Refugio de los Mendigos y habla con el boticario Faustin.", description = "Nuestra fuerza expedicionaria fue enviada a bajo Azeroth a instancias de Varimathras.\n\nMientras rastreábamos el terreno, vi a un infiltrador humano espiando el Refugio de los Mendigos. Antes de que pudiera aprehenderlo, algunos de nuestros... hermanos orcos... lo capturaron y se lo llevaron a Rocal, su fortaleza en el Pantano de las Penas.\n\nQuiero... ayudar... a nuestros aliados orcos. No vieron nuestro campamento, pero aun así, quiero echarles una mano.\n\nColabora con Faustin para preparar... un suero de la verdad para nuestro amigo de Rocal.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1373] = {title = "Ongeku", objective = "Mantén tu reputación con los Gelkis y lleva 1 fragmento de draenetista a Uthek la Sabia al Poblado Gelkis de Desolace.", description = "Tienes más que demostrar. Tu siguiente cometido te llevará lejos así que, de momento, los Gelkis combatirán a los Magram sin tu ayuda.\n\nLa tierra susurra muchos secretos a quienes saben escuchar. Uno de los secretos que he oído tiene que ver con un cristal rojo. Se llama draenetista y es nuevo en nuestra tierra. Proviene de un lugar en el que las montañas vuelan y gobiernan los demonios.\n\nTráeme un fragmento de draenetista para que fortalezca mi magia. Encontrarás un fragmento en un lugar llamado Pantano de las Penas. Lo controla Ongeku, uno de Los Perdidos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1374] = {title = "Khan Jehn", objective = "Lleva la cabeza del khan Jehn a Uthek la Sabia al Poblado Gelkis de Desolace.", description = "La tierra me habla y me dice que los Magram se están debilitando. ¡Es el momento de matar a su Khan!\n\n¡Tráeme la cabeza de Jehn, el khan Magram!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1375] = {title = "Khan Shaka", objective = "Mantén tu reputación con los Magram y lleva la cabeza de Khan Shaka a Warug al Poblado Magram de Desolace.", description = "Tú ayudas a los Magram. Me gustas. Ahora, ¡mata al Khan de los Gelkis! ¡Quiero la cabeza de Khan Shaka! ¡Quiero mirarle a la cara y reírme de él!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1382] = {title = "Extraña alianza", objective = "Gana un nivel de reputación de amistoso con los Gelkis y luego habla con Uthek la Sabia.", description = "Tenemos suerte de que los clanes de centauros combatan entre sí porque, si se unieran, serían imparables. Sí, tenemos suerte. Y deberíamos aprovechar esta ventaja.\n\nEl clan Gelkis está combatiendo una sangrienta guerra contra el clan Magram. Si atacamos a los Magram, quizás podamos forjar una alianza con los Gelkis.\n\nHabla con Uthek la Sabia. La encontrarás a las afueras del campamento Gelkis, en el Desolace suroccidental. Con su ayuda, quizás consigamos sellar esa alianza.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1383] = {title = "El suero de la verdad", objective = "El boticario Faustin del Refugio de los Mendigos necesita 5 corazones de pantera sombría, hongos de Señor del Lodo y sangre de cría verde.", description = "Conozco el suero perfecto. Trata la verdad justo como la verdad debe ser tratada.\n\nPara preparar el brebaje necesitaré varios corazones de pantera de las Sombras del pantano. También necesito unos hongos encantados del Lord fangoso que vive allí. Seguro que alguien con tu habilidad, <nombre>, podrá convencerle de que le dé algunos hongos.\n\nEl último objeto que necesitaré para crear el suero es sangre de una cría soñadora, como las que habitan a la entrada de la cueva de Itharius, en el pantano.\n\nHala, ¡en marcha!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Capa de AñubloGran maza de riscoleñoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1385] = {title = "Políticas brutales", objective = "Gana un nivel de reputación de amistoso con los Magram y luego habla con Warug.", description = "Desolace es una tierra en guerra. Los centauros están en guerra entre ellos y creemos que quien salga victorioso podría convertirse en una amenaza para nuestras fortalezas. Y eso no podemos permitirlo.\n\nTenemos que averiguar cómo vencer a los centauros. Y para eso, hemos de aliarnos con uno de los clanes. Los centauros Magram están en guerra con los Gelkis. Si combates contra los Gelkis, quizás los Magram tomen en consideración la creación de una alianza.\n\nGánate el favor de los Magram y luego habla con Warug. Lo encontrarás en el Poblado Magram, al sureste de Desolace.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1387] = {title = "Colección de orejas", objective = "Lleva 15 orejas de centauro al cabo Melkins que está en Punta de Nijel, en Desolace.", description = "La raza de los centauros está dividida en muchos clanes. Cada uno tiene su propio jefe y sus objetivos. Pero todos tienen algo en común: su crueldad.\n\nSi queremos conocer la paz, debemos eliminar a los centauros. Y precisamente, eso es lo que quiero que hagas.\n\nMientras viajes por Desolace, da caza a los centauros y córtales las orejas. Tráeme muchas, muchas orejas.\n\nHazlo por la Alianza, <nombre>, y estaremos un paso más cerca del final de la guerra.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAnillo de Calma"}
MultiLanguageQuestData['mx'][1389] = {title = "ristales draenetistas", objective = "Llévale 6 cristales draenetistas a Magtoor que está en El Puerto del Pantano de las Penas.", description = "Los Perdidos que habitan en Retiro Fangoso son como nosotros en apariencia pero, en realidad, son monstruos que enloquecieron debido a los rigores sufridos durante nuestro viaje a Azeroth. En su día hermanos nuestros, viven ahora en Retiro Fangoso hacia el este, donde atrapan o matan a todo aquel que vague por la zona.\n\nAdemás, nos han robado algo sagrado para nosotros: los cristales draenetistas.\n\nCarecemos de la fuerza necesaria para aventurarnos en Retiro Fangoso y recuperar los cristales que nos han sido robados de entre sus cabañas y hogueras, pero sin ellos... quizás perdamos nosotros también nuestro camino.", progress = "¿Tienes los cristales?", completion = "Gracias, &lt;nombre&gt;. Estamos en deuda contigo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1392] = {title = "Noboru el Garrote", objective = "Llévale el garrote de Noboru al líder de El Puerto del Pantano de las Penas.", description = "Noboru ha asediado a los draenei de El Puerto durante meses y su garrote es un símbolo de la brutalidad sufrida a manos de Los Perdidos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1393] = {title = "La huida de Galen", objective = "Pon a salvo a Galen, y después encuentra su campamento en el Pantano de las Penas y abre su caja fuerte.", description = "Por favor, necesito ayuda. ¡Estas criaturas van a devorarme!\n\n¡Sácame de aquí y te recompensaré con un gran tesoro! Está en mi campamento, en el pantano situado al norte de Rocal, pero está guardado en una caja fuerte que solo yo puedo abrir.\n\nSi me ayudas a escapar, te enseñaré cómo se hace.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nRodela visionaria"}
MultiLanguageQuestData['mx'][1394] = {title = "La recta final", objective = "Habla con Dorn Acechallanos en Las Mil Agujas.", description = "Lo has hecho muy bien, <nombre>. Has superado mi prueba y todas las anteriores. Vuelve a ver a Dorn a Las Mil Agujas. Podrá ver los cambios que has experimentado y comprobará que tu mente, tu cuerpo y tu espíritu son lo suficientemente fuertes, por lo que te recompensará por tus esfuerzos.\n\nPermanece fiel al equilibrio que has demostrado a lo largo de estas pruebas, <nombre>. Dorn te pondrá a prueba más adelante si así lo haces.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Martillo tormenta de vientoLlama danzarinaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1395] = {title = "Suministros para Nethergarde", objective = "Llévale caja de piedras de potencia al intendente Lungertz antes de que caduquen.", description = "Hay que llevar esta caja de piedras de potencia al Castillo de Nethergarde, en Las Tierras Devastadas. No conservarán la potencia mucho tiempo, así que no podemos esperar a la siguiente caravana.\n\nTienes que llevarlas, y debes hacerlo si perder ni un minuto.\n\nLlévaselas al intendente Lungertz en el Castillo de Nethergarde. Para llegar al castillo, debes dirigirte al Paso de la Muerte, luego ir hacia el este a través del Pantano de las Penas, y por último cruzar Las Tierras Devastadas.\n\nTen mucha precaución, <nombre>. Pasarás por tierras muy peligrosas y no puedes fracasar.", progress = "¡Hola! No hagas caso del revuelo, es lo normal en el Castillo de Nethergarde.\n\n¿Tienes algo para mí?", completion = "¡Ah, las piedras de potencia! ¡Los magos se alegrarán de verlas! \n\nMuchas gracias, &lt;nombre&gt;. Sé que tu viaje desde Villa Oscura no fue fácil.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1396] = {title = "ontra la fauna feroz", objective = "Mata a 8 crocoliscos Denteserra jóvenes, 10 hilapenas y 10 jaguares del pantano, y después ve a ver al vigía Biggs al Pantano de las Penas.", description = "Mi caravana iba destinada a la costa oriental pero no alcanzamos nuestro objetivo. Los Perdidos nos atacaron: mataron a los guardias y destrozaron los suministros.\n\nTan solo yo sobreviví a su ataque. He jurado proteger los suministros restantes pero hay criaturas salvajes vagando por aquí. ¡Por favor, ayúdame a defender mi campamento de las bestias!", progress = nil, completion = "Los sonidos de los animales ahora son débiles y distantes. Gracias, &lt;nombre&gt;. ¡Esperemos que no vuelvan!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1398] = {title = "Madera a la deriva", objective = "Llévale 8 piezas de madera a la deriva desecada al vigilante Biggs en el Pantano de las Penas.", description = "Te debo mucho, <nombre>. En tu interior late un corazón noble. Y ahora tengo otra tarea para la que humildemente pido tu ayuda.\n\nSi he de llegar hasta Nethergarde, tendré que arreglar este carro. Y para ello... necesitaré madera. Madera fuerte y seca, no como la madera esponjosa de los árboles del pantano.\n\n<nombre>, ve hacia el este hasta llegar a la costa y busca madera que haya sido arrastrada por el mar y secada por el sol. Cuando la tengas, tráemela.", progress = "¿Encontraste la madera, <nombre>?", completion = "Esta madera es ligera pero muy resistente. Gracias, &lt;nombre&gt;. Es justo lo que necesito.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1418] = {title = "Neeka Marca de Sangre", objective = "Habla con Neeka Marca de Sangre.", description = "Las Tierras Inhóspitas son escabrosas y están situadas cerca de las tierras de Loch Modan dominadas por la Alianza, por lo que la comunicación entre Rocal y la avanzada de Kargath de las Tierras Inhóspitas en ocasiones se corta.\n\nDemuestra tu valía, <nombre>. Viaja a las Tierras Inhóspitas y habla con Neeka Marca de Sangre, la jefa de exploradores la avanzada de Kargath. Habla con ella y regresa para contarme lo que averigües.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1419] = {title = "Ladrones coyote", objective = "Llévale 30 mandíbulas de coyote a Neeka Marca de Sangre, que está en Kargath.", description = "¿Has estado muchos días en las Tierras Inhóspitas, <clase>? ¿Has sentido el calor que hace allí? ¿Te has topado con las bestias que vagan por sus áridas llanuras? Pues es hora de que lo hagas.\n\nLos coyotes monteses son muy fuertes. Fuertes y lo suficientemente audaces para acercarse con sigilo a Kargath y robar las provisiones de comida. ¡Ayuda a la avanzada a deshacerse de estos ladrones!\n\nCaza a los coyotes monteses, <nombre>, y tráeme sus mandíbulas. Si me traes bastantes quizás te crea cuando afirmas que conoces bien las Tierras Inhóspitas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1420] = {title = "Un informe para Helgrum", objective = "Llévale el informe de Neeka a Helgrum el Veloz, que está en Rocal.", description = "He redactado un nuevo informe para Helgrum, que está en Rocal, y quiero que se lo lleves.\n\nSi te consideras <un buen avanzado/una buena avanzada>, entonces no te pierdas por el camino ni dejes que te atrape el enemigo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1421] = {title = "La caravana perdida", objective = "Encuentra el cofre de la caravana en Retiro Fangoso, consigue los componentes de zahorí y llévaselos al vigía Biggs.", description = "Yo perdí el sentido durante el ataque de Los Perdidos pero, antes de que mi vista se nublara, vi cómo uno de nuestros carros era conducido hasta Retiro Fangoso, la ciudad perdida situada al norte.\n\nUno de los cofres de la caravana que contenía componentes muy importantes iba en ese carro, unos componentes esenciales para que los zahoríes del Castillo de Nethergarde puedan continuar con sus estudios. Encuentra ese cofre y recupera los componentes, <nombre>. Consíguelos y tráemelos aquí.", progress = "¿Tienes los componentes de zahorí, <nombre>?", completion = "¡Ah, los has encontrado! Con ellos, los zahoríes de Nethergarde podrán continuar con su trabajo. No sé con exactitud lo que hacen pero tiene que ver con El Portal Oscuro de Las Tierras Devastadas y es crucial para la seguridad de la Alianza.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1423] = {title = "Los suministros perdidos", objective = "Llévale los suministros perdidos al intendente Lungertz.", description = "Este barril es pequeño pero resistente. Sus juntas están selladas con una cera acre de color amarillo. En el fondo del barril están estampadas las palabras:\n\nINTENDENTE LUNGERTZ\n\nCASTILLO DE NETHERGARDERecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCaja de suministros"}
MultiLanguageQuestData['mx'][1424] = {title = "harca de Lágrimas", objective = "Fel'zerul, en Rocal, quiere que consigas 5 artefactos Atal'ai.", description = "El Jefe de Guerra nos envió a investigar los extraños sucesos que están ocurriendo en El Templo de Atal'Hakkar.\n\nLos trols Atal'ai son una tribu de magos oscuros, famosos por practicar la magia prohibida. Te puedes imaginar lo sorprendidos que nos quedamos cuando llegamos y descubrimos que el templo estaba sumergido.\n\nAhora, los dragones verdes protegen el lugar, erigiéndose como protectores de Azeroth.\n\nNecesitamos descubrir qué ha pasado. Explora la Charca de Lágrimas y consigue artefactos Atal'ai. Con eso, podré empezar a unir las piezas del puzle.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1425] = {title = "Entrega el cargamento", objective = "Entrégale los suministros al intendente Lungertz del Castillo de Nethergarde.", description = "Mientras yo arreglo el carro, <nombre>, tengo una última tarea que encomendarte.\n\nHe empaquetado los suministros más importantes que se salvaron del ataque de los ogros. Llévalos hasta el Castillo de Nethergarde. El castillo está enclavado en las colinas del norte de Las Tierras Devastadas y su misión es vigilar El Portal Oscuro.\n\nPara llegar a Nethergarde, sigue el camino del este. Cuando se bifurque, ve en dirección sur hacia Las Tierras Devastadas y a continuación gira a la izquierda en el siguiente cruce. Sigue el camino, <nombre>, y ve con cuidado.", progress = "¿Tienes algo que tratar conmigo?", completion = "¿Qué? ¿Un paquete de la caravana de Biggs? Ya lo dábamos todo por perdido... \n\nGracias, &lt;nombre&gt;. Con un poco de suerte contendrá el componente que tanto necesitamos, los cristales de Azora. Nos estamos quedando sin ellos...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1426] = {title = "a amenaza marítima", objective = "Mata a 10 múrlocs de marisma, 10 vomitatintas de marisma y 10 comecarnes de marisma, y después ve a ver a Katar al Pantano de las Penas.", description = "No siento aprecio por el mar ni por ninguna de las criaturas que he visto emerger de sus profundidades. Es una entidad poderosa pero ciega, a la vez cruel y brutal. Sería un placer para mí dar muerte a los hombres-pez de cien en cien si estuviera en mi mano pero he de conformarme con ver cómo caen ante aquellos que cumplen la voluntad de la Horda.\n\nLo cual nos lleva a ti, <clase>. ¿Cuántos serías capaz de matar? ¿Te atreverías a ponerte a prueba ante los más poderosos de su especie?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1428] = {title = "a amenaza continua", objective = "Mata a 10 vomitatintas de marisma, 10 comecarnes de marisma y 10 oráculos de marisma, y después ve a ver a Katar al Pantano de las Penas.", description = "Me complace comprobar que tu odio por los hombres-pez crece con el mío.\n\nBúscalos a lo largo de la playa y cuando te hayas hartado de combatir, vuelve a verme. Entonces hablaremos de una recompensa por tu diligencia.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1429] = {title = "l exiliado Atal'ai", objective = "Lleva los artefactos Atal'ai al exiliado Atal'ai en las Tierras del Interior.", description = "Mientras te enfrentabas a los peligros de la Charca de Lágrimas, uno de mis exploradores encontró un pergamino hecho de carne seca y escrito con sangre. Parece ser una sentencia judicial contra un sacerdote de la tribu Atal'ai.\n\nEste sacerdote fue condenado a un destino considerado como mucho peor que la muerte entre los Atal'ai.\n\nFue exiliado al norte de las Tierras del Interior, con los trols Secacorteza.\n\nGuardaré estos artefactos. Tienes que encontrar al exiliado y descubrir para qué se usan. Regresa cuando hayas completado tu viaje.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1430] = {title = "arne fresca", objective = "Lleva 10 patas de reptadores monstruosos a Dar en el Pantano de las Penas.", description = "Entre mis clientes, hay una gran demanda de la suculenta carne de reptador, especialmente la carne de los reptadores monstruosos.\n\nSi planeas dirigirte a la costa, podría hacer que sacaras algún provecho de tu viaje, si me traes algunas patas para transportarlas a Orgrimmar.\n\nLa costa queda al este de aquí y no creo que tengas problemas para encontrar a las criaturas que reptan por las playas y bajo el mar.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPatas de rey reptador a la parrillaCinturón de cuero de jefe"}
MultiLanguageQuestData['mx'][1431] = {title = "Las relaciones de la Alianza", objective = "Habla con Keldran en Orgrimmar.", description = "Guarda silencio, <clase>, y deja que te hable de algo que tiene mucha importancia para mi gente.\n\nSomos orgullosos y la guerra con los humanos ha impacientado incluso a Thrall. Verás, nuestro Jefe de Guerra es sabio y prudente y siempre piensa primero en su pueblo. También es diplomático y aprendió mucho de los humanos cuando estuvo con ellos.\n\nSi la historia te interesa, ve a ver a Keldran, que está cerca de la salida oeste de la ciudad.", progress = nil, completion = "Saludos, noble &lt;clase&gt;. Me llamo Keldran, estudioso de la magia y otras artes místicas. \n\nEl asunto por el que vienes a verme requiere sutileza, pero creo que podrás ayudarnos. \n\nSiéntate y escucha por qué necesitamos tu ayuda. \n\nTodo está relacionado con las apariencias, &lt;nombre&gt;, con cómo la Horda se ve a sí misma. Y cómo la ven los enemigos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1432] = {title = "Las relaciones de la Alianza", objective = "Habla con Takata Hoja de Acero en Desolace.", description = "A medida que la Alianza avanza en Kalimdor, podría extenderse la errónea creencia de que la Horda ha pactado con la Legión Ardiente. El Jefe de Guerra no puede permitirlo y me ha autorizado a atajar estas creencias erróneas.\n\nTengo agentes en la región de Desolace, en el Campamento del Espíritu Errante que está al norte del Cementerio de Kodos. Para encontrarlo, ve hacia el sur desde La Vega Carbonizada, en Sierra Espolón. Cuando llegues, busca a Takata Hoja de Acero.", progress = nil, completion = "Saludos, &lt;clase&gt;. Veo que traes noticias de Orgrimmar. \n\nLa tierra está ahogada por la infestación demoníaca. Los centauros se consideran dueños de la tierra, pero hay fuerzas que escapan a su control y pueden acabar aplastándolos. \n\nMe disgusta ayudar a los centauros aunque sea indirectamente, pero tengo que pensar en el bien de la Horda, por lo que hago lo que tengo que hacer como Jefe de Guerra, incluso si esto significa ayudar a los brujos dentro de la Horda.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1433] = {title = "Las relaciones de la Alianza", objective = "Habla con Maurin Partehuesos en Desolace.", description = "Los miembros de Filo Ardiente son malvados y corruptos hasta la médula; la única forma de impedir que lleven a cabo sus planes es acabar con todos ellos.\n\nKeldran envió también a Maurin porque conoce bien a esos brujos.\n\nÉl se ocupa de los planes contra el Filo y yo me encargo de las otras amenazas demoníacas de Desolace.\n\nHabla con él y te dirá sus planes.", progress = nil, completion = "Siempre se agradece la ayuda de los leales al Jefe de Guerra. \n\nMe llamo Maurin y estoy aquí a petición de Keldran y de Thrall. Quiero combatir contra los males que acechan a mi jefe. \n\nAcércate, &lt;clase&gt;, te voy a explicar mi plan para erradicar a Filo Ardiente.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1434] = {title = "La contaminación del sátiro", objective = "Mata a 7 pícaros, 7 jurapenas, 7 traidores y 7 clamainfernos Odio Feroz y ve a ver a Takata Hoja de Acero a Desolace.", description = "Las infestaciones demoníacas no ocurren por sí solas; alguna otra fuerza les permite establecerse.\n\nPuede ser un espíritu debilitado, el ansia injustificada de poder, un deseo de venganza o de justicia. Cuando nos atenaza el dolor, el mal aprovecha su oportunidad con seres como el sátiro.\n\nLos sátiros han pactado con el Filo Ardiente y Thrall quiere eliminarlos. Los encontrarás hacia el noreste. Vuelve cuando los hayas expulsado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1435] = {title = "Los espíritus ardientes", objective = "Lleva la gema ardiente y 15 gemas ardientes imbuidas a Maurin Partehuesos a Desolace.", description = "Esas despreciables criaturas prefieren la muerte antes que dar la espalda a su señor. Pero la muerte no basta cuando tratas con aquellos que se han entregado a las tinieblas.\n\nTen esta gema; actívala cuando algún miembro de Filo Ardiente esté a punto de morir. El hechizo hará que el espíritu corrupto abandone a su víctima y deje una gema imbuida.\n\nTráeme las gemas para que me encargue de ellas.\n\nVe, y que la muerte te eluda.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1436] = {title = "Las relaciones de la Alianza", objective = "Habla con Keldran en Orgrimmar.", description = "Esto va bien, <nombre>. Si la lucha contra los demonios y sus huestes sigue yendo así, puede que el Jefe de Guerra nos deje volver a casa antes de que cambie la estación.\n\nVe a ver a Keldran y dile lo que hemos hecho. Seguro que te recompensará por tu ayuda. Su causa es importante para él y seguro que se enorgullece de saber que el Jefe de Guerra lo tiene en alta estima.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de KapelanManteo CorreprestoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1437] = {title = "Buscando para Vahlarriel", objective = "Busca y registra el carro de Tyranis y Dalinda Malem en Desolace.", description = "Yo soy Vahlarriel, <nombre>. He venido aquí a descubrir el paradero de dos nobles de una familia de mercaderes de Darnassus, los Malem. El padre se teme lo peor y yo debo hacer todo lo que pueda para encontrar a sus hijos. Tengo que empezar mi búsqueda por Tyranis o Dalinda, pero espero no estar aquí demasiado.\n\nLo último que se sabe es que cruzaron la Sierra Espolón hace pocas semanas.\n\nSi encuentras su carro, por favor, ven a buscarme de inmediato.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1438] = {title = "Buscando para Vahlarriel", objective = "Encuentra a Dalinda Malem en Desolace.", description = "Busca a Dalinda y a Tyranis y vuelve a contarme tus progresos. Empieza la búsqueda en la fortaleza. Yo me pondré inmediatamente en contacto con mis superiores en Darnassus y les informaré de la situación.\n\n<nombre>, hay algo más que quiero transmitirte. Mis superiores han manifestado su preocupación por los motivos que pueda tener Tyranis para venir aquí. Consideran más importante encontrar a Dalinda y ponerla a salvo. Tyranis debe ser... evaluado antes de ser llevado a casa.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1442] = {title = "La búsqueda de la gema Kor", objective = "Lleva una gema Kor a Thundris Tejevientos a Costa Oscura.", description = "Saludos, <nombre>. ¿Cómo puedo ayudar a quien sigue una senda sagrada?\n\nAh, sí, Fontana, el herrero... Cuánto tiempo. Lo recuerdo bien, aunque hacía tiempo que no oía hablar de él.\n\nNo lo tengo por avaricioso, luego su deseo de tener una gema Kor solo puede tener un motivo noble.\n\nPara encontrar una de esas gemas tendrás que ir hacia el noroeste de Vallefresno. Allí encontrarás unas ruinas antiguas y las Cavernas de Brazanegra. Allí viven los nagas que siguen usando esas gemas. No vayas por tu cuenta, <clase>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGema kor purificada"}
MultiLanguageQuestData['mx'][1445] = {title = "l Templo de Atal'Hakkar", objective = "Reúne 20 fetiches de Hakkar y llévaselos a Fel'Zerul en Rocal.", description = "¿Así que habló de la profecía de Jammal'an?\n\nEl líder espiritual de los Atal'ai cree que cuando Hakkar vuelva a Azeroth desde El Vacío Abisal, el dios concederá la inmortalidad a la tribu Atal'ai.\n\nArtimañas estúpidas para conseguir una muerte temprana, si me lo preguntas.\n\n¿Pero dices que el exiliado habló sobre unos fetiches encantados? Eso me preocupa. Si esos fetiches son, realmente, la llave del ritual Atal'ai que ha causado todo este caos, debemos comprender los poderes intrínsecos.\n\nVete al Templo y consigue los fetiches.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDije guardián"}
MultiLanguageQuestData['mx'][1446] = {title = "Jammal'an el Profeta", objective = "El exiliado Atal'ai, en las Tierras del Interior, quiere la cabeza de Jammal'an.", description = "A mis compañeros Secacorteza no les gustan los extraños errantes.\n\n¿Yo? Yo ya no tengo hogar. Vivo en el exilio, lejos de mi gente, los Atal'ai del Pantano de las Penas.\n\nNuestro líder espiritual, Jammal'an, tuvo lo que él llama una visión. Cree que invocar al dios Hakkar traerá la inmortalidad a los Atal'ai.\n\nPero yo pedí prudencia. ¿Y si la visión no es más que manipulación?\n\nQuiero vengarme por estar en el exilio. Tráeme la cabeza de Jammal'an. A lo mejor así mi gente podrá ser libre.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Leotardos de zancalluviaYelmo de ExilioRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1448] = {title = "En búsqueda del templo", objective = "Brohann Barriliga, en Ventormenta, quiere que busques El Templo de Atal'Hakkar.", description = "Hace tiempo, yo era joven y rebosaba vigor como tú, <clase>.\n\nPero ahora soy mayor e incapaz de explorar el mundo como hice antaño. ¡Ah, las cosas que vi!\n\nPero un misterio me eludió siempre. En mi última misión, la Liga de Expedicionarios me envió a buscar El Templo de Atal'Hakkar. Se decía que estaba situado en el Pantano de las Penas.\n\nDebido a mi delicado estado, viajé surcando los cielos sobre un grifo buscándolo, pero no conseguí encontrarlo.\n\n¿Ayudarías a un viejo enano? Quizás tengas más suerte que yo si vas a pie.", progress = nil, completion = "¿El Templo de Atal'Hakkar está sumergido bajo la Charca de Lágrimas? ¿Y rodeado del Vuelo Verde? \n\nUn descubrimiento increíble, &lt;clase&gt;. Pero, obviamente, algo ha salido terriblemente mal.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1449] = {title = "A las Tierras del Interior", objective = "Habla con el Gran señor feudal Falstad Martillo Salvaje en el Pico Nidal, en las Tierras del Interior.", description = "Como mencioné antes, intenté buscar el templo desde el aire. Aunque no estaba exactamente solo.\n\nFui a la famosa pajarera de grifos en Pico Nidal, en las Tierras del Interior. Allí recluté a uno de sus mejores pilotos. El piloto se cayó de la montura, al pantano...\n\nA mis años, no soy capaz de recordar el nombre del pobre piloto. Pero, sin duda, el maestro de la pajarera se acordará.\n\nVe allí y busca a Falstad Martillo Salvaje.\n\nTenemos que saber lo que le ocurrió a ese piloto.", progress = nil, completion = "¿Qué quieres, muchacho? ¿No ves que tengo cosas que hacer aquí? ¿A quién le sobra el tiempo para perderlo con un &lt;raza&gt; charlatán? \n\n¡Hay trols saliendo de la carpintería! Habla rápido.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1452] = {title = "El cubata de Kalimdor de Rapsodio", objective = "Rapsodio Machacacanillas, en las Tierras del Interior, quiere que le lleves 3 mollejas de roc, 3 hígados de Groddoc y 3 hígados de Cueracero.", description = "¡Hip!\n\n¿Así que te ha mandao ese loco de Brohann? Pedazo de aventura que tuvimos... ¡Hip!\n\nSi quieres que te cuente lo que pasó allí en el pantano, voy a necesitar beber algo fuerte. No fue nada bonito, ¿sabes? ¡Hip!\n\nMira... Tráeme lo que necesito pa hacer un cubata de Kalimdor y te lo contaré.\n\nVoy a necesitar mollejas de roc de Tanaris y... veamos... algunos hígados de Groddoc e hígados de Cueracero de Feralas...\n\nUn buen cubata de Kalimdor... ¡Con eso hablaré!", progress = "¿Alguna vez te has tomao una malta rapsódica? Una de mis mejores bebidas, si me se permite decirlo. ¡Hip!\n\nPero si voy a revivir los horrores de aquel espantoso vuelo sobre... hip... el Pantano, bueno, voy a necesitar beber algo un pelín más fuerte. ¡Hip!\n\n¿Supongo que no habrás encontrado esas mollejas y los hígados que necesito pa darle tono a mi cubata de Kalimdor, no?\n\n¡Hip!", completion = "¡Ya veo que no has tenio problemas pa traerme lo que necesitaba! Tiene que haber sido complicao lo de allí, en el lejano Kalimdor. \n\nNo me llevará ni un momento extraer lo que necesito de estos hígados y mollejas. ¡Hip! \n\nDespués podré destilar una bebida bastante fuerte y entonces podré contarte lo que quieres saber. \n\n¡Hip! \n\nMe da escalofríos pensar en ese viejo pantano. \n\n¡Hip! \n\nDeja que me tome primero una copita rápida.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1453] = {title = "Los negocios de los Recuperadores en Desolace", objective = "Habla con Kreldig Ungor en Desolace.", description = "Hay mucho que hacer en Desolace, <nombre>. Es un lugar atroz, mancillado por centauros y otros seres desagradables. Pero si buscas un trabajito honrado, ve, busca a Kreldig Ungor y dile que vas de mi parte.\n\nEstará en Punta de Nijel, un campamento pequeño oculto en las montañas del norte de Desolace. Si entras por la Sierra Espolón, ve hacia el este. Es difícil de ver, así que estate pendiente.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1454] = {title = "El naufragio de Karnitol", objective = "Encuentra el cofre de Karnitol en Desolace.", description = "Saludos, <amigo/amiga>. Siéntate...\n\nMi primer encargo es para el mago Karnitol, una especie de noble de Ventormenta. Por lo visto, su barco fue atacado por gigantes marinos cuando navegaba al noroeste de Desolace. Él y sus sirvientes intentaron llevar a la costa uno de sus cofres más valiosos, pero cuando los gigantes marinos atacaron en manada, decidió abandonarlo y teletransportarse con sus sirvientes.\n\nQuiere que encontremos su cofre y su contenido y que se lo llevemos a Ventormenta.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1455] = {title = "El naufragio de Karnitol", objective = "Vuelve a Desolace a hablar con Kreldig Ungor.", description = "Inviertes unos segundos en intentar averiguar qué abrió el cofre y notas que en los laterales y la tapa del cofre hay unos profundos arañazos que indican que algo que no era un hombre ni un gigante se interesó por él. Las marcas no parecen haber sido causadas por una daga o una espada.\n\nRevisas el cofre y lo encuentras totalmente vacío.\n\nNo hay nada que hacer. Cierras el cofre y te preparas para irte. Kreldig estará decepcionado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1456] = {title = "El naufragio de Karnitol", objective = "Encuentra la cartera de Karnitol y devuélvesela a Kreldig Ungor, que está en Desolace.", description = "Intrigante.\n\nBueno, puede que aún no debamos perder la esperanza.\n\nA lo largo de esa misma costa pero hacia el norte, cerca de la Isla Ranazjar, en el fondo del mar, hay unas ruinas de los elfos de la noche. Una tribu de nagas, los Filozante, han hecho de ellas su hogar. Creo que es nuestra mejor baza.\n\nSi una partida de exploradores llegó tan al sur, debía de ser bastante poderosa. Si quieres encontrar las pertenencias de Karnitol, yo empezaría con los nagas más poderosos: los cazamareas o las brujas de mar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Hacha de batalla de buscadorToga de sobra de KarnitolBotines del buscadorRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1457] = {title = "El naufragio de Karnitol", objective = "Lleva la cartera de Karnitol a Roetten Rocamartillo a Forjaz.", description = "Lleva las cosas de Karnitol a Forjaz. Dáselas a Roetten y él te pagará por un trabajo bien hecho.\n\nJa, ja, si no tienes cuidado, va a estar tan contento contigo que te pedirá que te unas a nosotros a jornada completa.\n\nUna vez más, buen trabajo, <nombre>.\n\nCuidado en el camino de regreso. Y no te entretengas mucho, Karnitol no es el más paciente de los hombres, aunque sí es muy generoso.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Botas de demonioEspaldares sanguinosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1458] = {title = "Componentes para Recuperadores S.A.", objective = "Lleva 10 zarpas de Odio Feroz y 10 cuernos de Odio Feroz a Kreldig Ungor a Desolace.", description = "Uno de mis cometidos es recoger componentes para Zurdibrujo, un mago gnomo de Kharanos. Roetten parece pensar que es fácil porque ya estamos aquí. Y no le preocupa que nos falte gente.\n\nLos primeros artículos de la lista deberían ser fáciles de encontrar. Y habría una buena recompensa para quien me ayudara.\n\nNecesito algunos cuernos y patas de los sátiros Odio Feroz que están al este de aquí. Tráemelos y seguiremos con el resto de la lista.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1459] = {title = "Componentes para Recuperadores S.A.", objective = "Lleva 7 viales de veneno de Scorpashi y 3 pellejos de kodo envejecido a Kreldig Ungor a Desolace.", description = "Lo siguiente de la lista de Zurdibrujo es... veamos... mmm. Ah, aquí está.\n\nEs simple. Suele ser muy explícito cuando da instrucciones. Necesita veneno de scorpashi y el pellejo de algún kodo. La letra pequeña dice que ambas cosas deben ser de criaturas específicas. El veneno tiene que venir de cualquiera de los scorpashi y el pellejo tiene que ser de un kodo envejecido, no de uno anciano o moribundo.\n\n¡Magos! De verdad, a veces piden unas cosas...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1467] = {title = "Componentes para Recuperadores S.A.", objective = "Lleva el paquete de Zurdibrujo a Roetten Rocamartillo a Forjaz.", description = "Si quieres que te paguen, tendrás que volver a Forjaz y hablar con Roetten en persona. Estará encantado de quitar de en medio el paquete de Zurdibrujo. Tú dale esto. Debería bastar para conseguir tu recompensa.\n\nY no te preocupes, hablaré bien de ti cuando vuelva. No debería quedarme mucho más en Desolace.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Brazales áuricosGuanteletes TempesfuegoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1468] = {title = "Semana de los Niños", objective = "Usa el silbato de huérfano humano para hablar con el niño al que cuidarás durante la Semana de los Niños.\n\nObjeto provisto: \n", description = "¿Quieres ayudarnos aquí en el orfanato? $GBendito:Bendita; seas, <amigo/amiga>. Tu ayuda durante la Semana de los Niños no tiene precio.\n\nCoge este silbato. Solo podrás utilizarlo durante un breve período de tiempo, básicamente, hasta que se acabe la Semana de los Niños. Cuando lo uses, podrás hablar con el niño que esté a tu cuidado. Utilízalo de nuevo para que el niño se vaya.\n\nSea como sea, <nombre>, utiliza el silbato y conoce a tu pupilo. Seguro que el niño estará encantado de conocerte.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][1473] = {title = "Criatura Abisal", objective = "Recupera el grimorio de Egalin y dáselo a Carendin Halgar, que está en el Templo de los Condenados.", description = "Parece que todo apunta a que estás <preparado/preparada> para aprender a invocar a un abisario.\n\nSe trata de un ser creado a partir del caos y, si lo invocas pero eres incapaz de dominarlo, será tu fin.\n\nEgalin fue el primero en invocar a un abisario, y explica el proceso en su grimorio.\n\nDesgraciadamente, nos lo robó un agente de la Cruzada Escarlata y ahora está escondido en la base que tienen en una torre hacia el oeste. Tráemelo y compartiré ese conocimiento contigo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1474] = {title = "El vínculo", objective = "Utilizando los corazones puros, invoca y domina a un súcubo, y después devuélvele los corazones puros a Carendin Halgar, que está en el Barrio de la Magia de Entrañas.", description = "Usando estos corazones, lanza un hechizo al Círculo de Invocación para abrir una puerta por la que el súcubo pueda entrar. Tus poderes son enormes ahora, pero los necesitarás todos para dominar al súcubo.\n\nTen cuidado con sus encantos, <nombre>, muchas mentes regias han sucumbido a su voluntad. Cuando lo hayas dominado, el súcubo volverá al vacío, y entonces te enseñaré el hechizo para invocarlo a tu antojo en el futuro.Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nInvocar súcubo\n\nTambién recibirás:\n\nFaltriquera de almas pequeña"}
MultiLanguageQuestData['mx'][1475] = {title = "En El Templo de Atal'Hakkar", objective = "Consigue 10 tablillas de Atal'ai para Brohann Barriliga, en Ventormenta.", description = "Según la leyenda, El Templo de Atal'Hakkar es un santuario sagrado dedicado al dios ancestral, Hakkar el Cazador de Almas. Está protegido por una feroz tribu de trols, los Atal'ai, y se rumorea que el templo es impenetrable.\n\nAhora está hundido en la Charca de Lágrimas, con lo que sacar artefactos del templo es mucho más difícil. Pero eso es lo que necesito que hagas, <nombre>.\n\nAyúdame, tráeme las tablillas de Atal'ai intactas. Tráemelas y podré volver con los Exploradores convertido en un héroe. Juntos compartiremos la gloria.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDije guardián"}
MultiLanguageQuestData['mx'][1476] = {title = "Corazones puros", objective = "Llévale los corazones de Dalin Forjador y Corma Villardo a Carendin Halgar, que está en el Templo de los Condenados.", description = "Para atraer a una súcubo, se necesitan corazones puros. ¿Pero siquiera existen mortales así?\n\nA juzgar por los rumores que escuché por ahí, creo que encontré a dos humanos que bastarán.\n\nEl primero es Dalin Forjador, que se consagró al cuidado de los refugiados de Lordaeron, quienes fueron rechazados por los suyos en la Muralla de Cringris.\n\nLa otra es Corma Villardo, una mujer que sigue siendo fiel a su amor perdido y vaga por Los Humedales en busca de una señal de su mujer.\n\nEntrégale sus corazones a Carendin. Pero primero, deja que te muestre tus presas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1477] = {title = "Suministros de vital importancia", objective = "Habla con el maestro de vigilantes Sorigal en Villa Oscura, en el Bosque del Ocaso.", description = "Nuestros magos están realizando una investigación en el Castillo de Nethergarde en Las Tierras Devastadas, una investigación vital para entender El Portal Oscuro. Necesitan suministros prácticamente ininterrumpidos pero nuestra línea de suministros a Nethergarde es débil.\n\nTienes que ayudarnos para que los suministros lleguen a Nethergarde. Preséntate al maestro de vigilantes Sorigal en Villa Oscura y sigue sus instrucciones. Esta tarea te llevará a tierras inhóspitas, <nombre>. Prepárate.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1478] = {title = "Las invocaciones de Halgar", objective = "Habla con Carendin Halgar en Entrañas.", description = "¡Ah, <nombre>! Parece que Carendin Halgar desea verte para continuar con tu instrucción.\n\nDeberías sentirte muy <orgulloso/orgullosa>, <nombre>. No todos los días el maestro Halgar se digna a instruir a <un joven brujo/una joven bruja>.\n\nLo encontrarás en el Barrio de la Magia de Entrañas, cerca del Templo de los Condenados.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1480] = {title = "El corruptor", objective = "Lleva la piel de demonio a Maurin Partehuesos a Desolace.", description = "La piel desgarrada huele a podrido y es muy flexible pese a lo seca y frágil que parece.\n\nAl desenrollarla ves que tiene símbolos gráficos en rojo en un lado. En la parte inferior se ve muy claro un símbolo; supones que es una firma.\n\nQuizás Maurin te pueda explicar lo que es.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1481] = {title = "El corruptor", objective = "Lleva 1 cabellera de acechasombras a Maurin Partehuesos a Desolace.", description = "Creo que puedo encontrar a este señor demoníaco con los ingredientes apropiados.\n\nSi es tan poderoso como sospecho, necesitaré objetos cogidos de criaturas mortales. Pero actúas en nombre del Jefe de Guerra, así que seguro que aceptarás mi encargo.\n\nPrimero, tendré que romper las defensas que pueda tener contra la adivinación. Para ello, necesitaré la cabellera de un sátiro, pero no de cualquier sátiro. La cabellera debe proceder de un acechasombras Odio Feroz.\n\nBúscalos entre las antiguas ruinas al noreste de Desolace.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1482] = {title = "El corruptor", objective = "Lleva 1 cristal del oráculo a Maurin Partehuesos a Desolace.", description = "Un cristal del oráculo me iría muy bien. Los fabrican los nagas para sus oráculos.\n\nA lo largo de la costa, hacia el noroeste, hay un arrecife de coral en el que se han instalado los nagas. Allí encontrarás los oráculos. Los Filozante son mortales y no van a tomarse bien tu intrusión, así que ten cuidado y date prisa.\n\nCuando vuelvas nos ocuparemos de buscar a ese Azrethoc señor demoníaco.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1483] = {title = "Ziz Fizziks", objective = "Habla con Ziz Fizziks en Risco Cortaviento.", description = "Ventura y Cía. se quedó con muchos de los cerebros goblins más brillantes pero de vez en cuando, conseguimos robarle alguno.\n\nHace algún tiempo, la delegación de Ventura y Cía. en Sierra Espolón contrató a Gerenzo Silbillave, ¡un gnomo! Esto afectó tanto a su otro ingeniero, Ziz Fizziks, que me rogó que le encontrara un nuevo empleo con el sindicato de manitas. Le asigné unas tareas pero puede que necesite ayuda.\n\n¿Podrías ir a ver cómo le va por mí? Se encuentra en el extremo occidental del Risco Cortaviento.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1486] = {title = "Pellejos descarriados", objective = "Nalpak de las Cuevas de los Lamentos quiere 20 pellejos descarriados.", description = "Cuando Naralex se hundió en su pesadilla, una extraña raza de bestias salió de debajo de Los Baldíos y se adentró en las Cuevas de los Lamentos.\n\nEstas criaturas descarriadas tienen propiedades extrañas y como de otro mundo. Aunque su naturaleza es malvada, creo que puede venir algo bueno de su presencia aquí en Kalimdor. Creo que sus pellejos serán especialmente útiles para la peletería.\n\nSi crees que estás <preparado/preparada> para emprender esta tarea, aventúrate en las cuevas y hazte con algunos pellejos descarriados.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Leotardos descarriados escurridizosPodrás elegir una de estas recompensas:\n\nTalega de pellejo descarriado\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][1487] = {title = "Erradicación de descarriados", objective = "Ebru de las Cuevas de los Lamentos quiere que mates 7 devastadores descarriados, 7 víboras descarriadas, 7 arrastrapiés descarriados y 7 colminfernos descarriados.", description = "Naralex tiene un fin muy noble.\n\nNuestro gran líder aspiraba a entrar en el Sueño Esmeralda y a ayudar a que estas duras tierras volvieran a convertirse en el exuberante bosque que fueron un día. Pero algo fue terriblemente mal.\n\nEl sueño de Naralex se convirtió en pesadilla y criaturas corruptas comenzaron a habitar las cavernas.\n\nMientras algunos discípulos de Naralex se esfuerzan por despertar a nuestro maestro, yo me ocupo de librar a las cuevas de esas malvadas bestias.\n\nAventúrate a las cavernas, <nombre>, y erradica esos engendros descarriados.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Guanteletes de DamirePalo de frituraPodrás elegir una de estas recompensas:\n\nPatrón: cinturón de escamas descarriadas\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][1488] = {title = "El corruptor", objective = "Mata a Lord Azrethoc y a Jugkar Lug'vara y ve a ver a Takata Hoja de Acero a Desolace.", description = "Aunque no sé nada de ese Lord Azrethoc, coincido con Maurin en que debemos detenerlo, sobre todo si está intentando ganar influencia en Filo Ardiente.\n\nYa has demostrado tu voluntad de ayudar al Jefe de Guerra; te confío la tarea de buscar un equipo para eliminar al señor demoníaco y su siervo brujo.\n\nEncontrarás al demonio hacia el sur; vuelve cuando hayas terminado con él.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Rodela de basaltoEspaldares DéspotaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1489] = {title = "Hamuul Tótem de Runa", objective = "Habla con Hamuul Tótem de Runa.", description = "Los caparazones que me has traído están contaminados, nunca había visto algo así. Seguro que el agua de los oasis es la causa, y puedo sentir la confusión que causan en esta tierra. Es como si la tierra soñara y no pudiera despertar.\n\nLas Cuevas de los Lamentos deben de ser la fuente de la contaminación. Pero antes de ir allí habla con Hamuul Tótem de Runa, el druida anciano. Ya le hice saber lo que está ocurriendo en Los Baldíos. Es sabio y podrá ofrecerte consejo.\n\nLo encontrarás en Cima del Trueno, en el Alto de los Ancestros.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1491] = {title = "Bebidas de inteligencia", objective = "Reúne 6 unidades de esencia de lamentos.", description = "Bueno, los cuernos de raptor no funcionaron como esperaba. Pero no hay problema, ¡nadie se volvió rico en su primer intento! Además, ¡creo que encontré algo que funcionará todavía mejor en mis bebidas de inteligencia!\n\nHay una sustancia llamada esencia de lamentos que creo que es el motivo del origen de las plantas y animales extraños en los Baldíos. ¡Tráeme algunas y probaré agregarlas a mis bebidas!\n\nOí que la esencia se acumula en criaturas ectoplásmicas en las Cuevas de los Lamentos, al oeste. Caza a esas criaturas y consigue la esencia.", progress = "¿Dónde está mi esencia de lamentos?", completion = "¡Genial, la tienes! Me muero por probarla. Conseguiré una fortuna con esto, ¡estoy seguro! \n\nGracias, &lt;nombre&gt;. Esto es para ti, y cuando me haga rico, te enviaré más, ¡prometido!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1498] = {title = "Camino de defensa", objective = "Lleva 5 escamas chamuscadas a Uzzek en Avanzada del Puente en Los Baldíos.", description = "Una de las tareas más importantes de un guerrero es... la protección. Somos el escudo de la Horda y mantenemos a salvo a nuestros hermanos más débiles. Si vas a unirte a nuestras filas debes demostrarme tu entereza.\n\nVe al Monte del Trueno en Durotar, donde viven las rayopieles y los truenagartos. ¡Caza a esas bestias! ¡Demuéstrame que eres más fuerte que ellos! Resiste sus ataques y tráeme un fardo de sus escamas chamuscadas como prueba.\n\nHazlo y te instruiré.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1501] = {title = "Criatura Abisal", objective = "Lleva la tablilla de Vergua a Gan'rul Ojosangre a Orgrimmar.", description = "Quedan tan pocos brujos... Tienes que perfeccionar tus habilidades rápidamente si quieres ser útil a la Horda y al Jefe de Guerra.\n\nTe voy a enseñar otro hechizo de invocación.\n\nPero antes tienes que recuperar la tablilla de Vergua; la robaron unos brujos de Filo Ardiente y ahora está en su guarida de Roca del Cráneo, al este de la ciudad. La tablilla tiene las runas necesarias para invocar a un abisario.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1502] = {title = "Thun'grim Vistafuego", objective = "Habla con Thun'grim Vistafuego en Los Baldíos.", description = "Es fundamental que el arma de un guerrero sea de calidad. Y si hay un orco que pueda hacer armas así es Thun'grim Vistafuego. Es un ermitaño que vive en la cumbre de las colinas al este de El Cruce.\n\nSi buscas un arma, <guerrero/guerrera>, viaja hacia el Oeste, hasta El Cruce, y cuando llegues sigue hacia el Este, a las colinas. Su campamento está en la cumbre.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1503] = {title = "Acero fundido", objective = "Lleva los lingotes de acero fundido a Thun'grim Vistafuego en Los Baldíos.", description = "Te daré un arma, <nombre>, pero antes debes ayudarme. Los Crines de Acero del Noroeste, vinieron a mi campamento hace unas noches. No se enfrentarían a mí en combate, pero saben que mis ojos no son buenos... unos cuantos me distrajeron con bramidos, ¡y mientras el resto se dedicaba a robarme! ¡Cobardes!\n\nCogieron un cofre de hierro en el que había algunos lingotes de acero fundido. Si puedes recuperarlos te daré el arma que deseas.\n\nBusca la caja de hierro en los campamentos de jabaespines y vuelve con los lingotes de acero fundido.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Hacha de Thun'grimDaga de Thun'grimMaza de Thun'grimEspada de Thun'grimRecibirás:\n\n"}
MultiLanguageQuestData['mx'][1504] = {title = "El vínculo", objective = "Usa los glifos de invocación para invocar y dominar a un abisario y lleva los glifos a Gan'rul Ojosangre a Orgrimmar.", description = "Verás que la tablilla contiene los glifos de invocación. Llévatela al círculo de la carpa de Neeru Hojafuego, que está al otro lado de la caverna; allí podrás invocar al abisario.\n\nDerrótalo con cualquier medio físico o mágico de que dispongas. Luego devuélveme los glifos de invocación y te enseñaré cómo ligar a la criatura a tu voluntad.Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nInvocar abisario\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][1505] = {title = "Uzzek, el veterano", objective = "Habla con Uzzek en Avanzada del Puente.", description = "La Horda honra a sus guerreros, ya que su fuerza es incuestionable. Pero los grandes guerreros también son excelentes estudiantes.\n\nBusca a Uzzek. Es veterano de muchas batallas y ahora instruye a jóvenes guerreros. Lo encontrarás al sur de la Avanzada del Puente, la guarnición de los orcos en la frontera que divide los Baldíos y Durotar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1506] = {title = "Las invocaciones de Gan'rul", objective = "Habla con Gan'rul Ojosangre en Orgrimmar.", description = "¡Eh, tú! <nombre>, ¿verdad?\n\nEspero que no tengas la agenda muy llena porque Gan'rul quiere verte ahora mismo. Lo encontrarás con los brujos mayores en el Circo de las Sombras.\n\nSegún mi experiencia con Gan'rul, esto de que te convoque solo puede ser muy bueno o muy malo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1508] = {title = "Cazul, el ciego", objective = "Habla con Zankaja en Orgrimmar.", description = "Si vienes de parte de Gan'rul, quiere decir que vas a invocar una súcubo, una hembra de la raza sayaad, y necesitas un objeto que la atraiga.\n\nMmm... Si confías en que un hombre ciego te guíe, <nombre>, escucha. En los riscos de Orgrimmar, al oeste de la torre del jinete del viento, vive Zankaja, que espera el regreso de su compañero.\n\nVe a hablar con ella.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1509] = {title = "Noticias de Dogran", objective = "Habla con Gazrog en El Cruce.", description = "A Dogran lo ascendieron y lo destinaron a El Cruce. Estaba muy contento.\n\nMe daba pena que se fuera, pero no se lo dije. Y también estaba preocupada. Los Baldíos son más peligrosos que Orgrimmar y me temía lo peor.\n\nYa hace una semana que tendría que haber vuelto y no sé nada de él...\n\n¿Puedes ir a El Cruce a preguntar? Habla con Gazrog, estaban destinados juntos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1510] = {title = "Noticias de Dogran", objective = "Habla con Ken'zigla en Malaka'jin.", description = "Estaba destinado al Campamento Taurajo, intentando erradicar a los jabaespines. Un día los siguió hasta el campamento, donde fue atacado por esas bestias. Sus compañeros lo rescataron, pero estaba muy grave. Sus heridas tenían muy mala pinta y no se atrevían a moverlo.\n\nNos pidieron un jarabe curativo de los trols de Malaka'jin, al pie de Sierra Espolón. Enviamos a un mensajero, pero todavía no ha vuelto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1512] = {title = "Un regalo de amor", objective = "Lleva el colgante cubierto de tierra a Gan'rul Ojosangre a Orgrimmar.", description = "Zankaja es joven y guapa, no puede encadenarse a un lisiado; no permitiré que malgaste su vida.\n\nDéjame solo, <nombre>. Y gracias. Así puedo caer honrosamente en combate, en lugar de extinguirme como un vegetal.\n\nY por favor, no le digas nada a ella, no quiero que se sienta culpable.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1513] = {title = "El vínculo", objective = "Usa el colgante de Dogran para invocar y dominar a un súcubo y lleva el colgante a Gan'rul Ojosangre a Orgrimmar.", description = "<nombre>, lleva eso al círculo de invocación de la carpa de Neeru. Invoca a un súcubo y demuéstrale lo que puedes hacer. Eres lo suficientemente fuerte. Pero sé prudente; la arrogancia y el exceso de confianza han sido la perdición de más de un buen brujo.\n\nCuando lo hayas derrotado, devuélveme el colgante para que pueda decirle a Zankaja lo que ha pasado.Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nInvocar súcubo\n\nTambién recibirás:\n\nFaltriquera de almas pequeña"}
MultiLanguageQuestData['mx'][1515] = {title = "El cautiverio de Dogran", objective = "Lleva el jarabe de Ken'zigla a Dogran a Los Baldíos.", description = "Ya que has llegado hasta aquí, no seré yo quien te detenga. Pero no tengo personal que te acompañe, tendrás que ir por tu cuenta.\n\nLo tienen retenido en un campamento de jabaespines al norte de aquí; busca dos chozas juntas. Estará muy vigilado, si es que no lo han matado ya sus heridas o esos animales.\n\nSuerte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1517] = {title = "La llamada de la tierra", objective = "Encuentra la Roca de los Espíritus y bebe la Sapta de tierra.\n\nObjeto provisto: \n", description = "Una sapta es una bebida creada para unir nuestros espíritus con los elementos. Cargada de magia, la poción permite a quien tiene fuerza de voluntad ver los elementos que nadie más puede ver. Tu espíritu se conectará con los elementos para los que fue creada la sapta, y son pocos los chamanes que conocen la receta.\n\nLa sapta siempre se bebe en un lugar sagrado, y en ningún otro sitio... recuérdalo.\n\nBusca la Roca de los Espíritus al suroeste de aquí, la encontrarás al final del Sendero Oculto. Cuando llegues, bebe la sapta, y... deberías poder ver.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1519] = {title = "La llamada de la tierra", objective = "Lleva 2 dosis de bálsamo ritual a la vidente Pluma de Cuervo al Campamento Narache.", description = "<clase>, ha llegado el momento; tu cuerpo crece en edad y en fuerza, y tu espíritu gana profundidad, como la tierra. Veo en tus ojos la sabiduría de tu alma.\n\nLa tierra guía a mi gente y nos habla, como te hablará a ti tarde o temprano. Pero debes ponerte a prueba. Si tu momento ha llegado, verás cosas que solo los nuestros pueden ver.\n\nBusca a los chamanes Erizapúas en el barranco que hay al este y procura un bálsamo que usan en sus rituales. Regresa cuando hayas conseguido la cantidad suficiente para crear tu propia poción.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1522] = {title = "La llamada del fuego", objective = "Busca a Kranal Fiss en Los Baldíos.", description = "Que el fuego te acompañe, colega. Veo que te manejas bien con la tierra. Creo que ya estás <listo/lista> para hablar con Kranal.\n\nKranal vive al norte de El Cruce, en Los Baldíos. Él sabe mucho de los elementos y puede enseñarte cosas del fuego... si crees que estás <listo/lista>.\n\nTe será fácil encontrarlo, pero no vayas muy lejos, o acabarás en las tierras de los elfos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1523] = {title = "La llamada del fuego", objective = "Busca a Kranal Fiss en Los Baldíos.", description = "Ha pasado tiempo desde tu última prueba, <nombre>. Hasta ahora has demostrado paciencia en tus estudios, pero ha llegado el momento de que aprendas algo más. Debes aprender de la destrucción... y el caos. De un elemento: el fuego. Podrás comprenderlo, si estás <dispuesto/dispuesta> a pagar el precio.\n\nBusca a Kranal Fiss en Los Baldíos. Vive en una pequeña casa al norte de El Cruce. Pero cuidado: si llegas hasta las tierras de los elfos de la noche, habrás ido demasiado lejos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1524] = {title = "La llamada del fuego", objective = "Lleva la antorcha de la Llama Latente a Telf Joolam a Durotar.", description = "Ya tienes poder suficiente para llevar el Tótem del Fuego, pero eso no quiere decir que estés <listo/lista>.\n\nA lo largo del Río Furia del Sur de Durotar, antes del Mare Magnum, hay una senda oculta que lleva a uno de los picos más altos de la tierra. Ábrete camino hasta la cima. Allí, custodiado por Telf Joolam, encontrarás uno de nuestros santuarios: el Santuario de la Llama Latente.\n\nLleva esta antorcha a Joolam. Así sabrá que intentas domar el fuego. Enciéndela en el blandón del santuario y tráemela. Yo me encargaré de que te sea concedido el Tótem de Fuego.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1525] = {title = "La llamada del fuego", objective = "Lleva 1 alquitrán y 1 faltriquera de componentes a Telf Joolam a Durotar.", description = "Pero tú no has venido aquí a recibir lecciones de historia, ¿verdad? Has venido aquí por la Llama Eterna y el Tótem de Fuego.\n\nEl primer paso es crear una sapta y unirte a la llama.\n\nPuedo crearte la sapta de fuego si me traes dos objetos. Primero necesito alquitrán. Un objeto sencillo que suelen llevar los taumaturgos de los Crines de Acero de la región este de Los Baldíos.\n\nEl segundo objeto será más difícil: una faltriquera de componentes de uno de los cultores del Filo Ardiente. Los encontrarás en una cueva que está sobre los barrancos del noreste de Cerrotajo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSapta de fuego"}
MultiLanguageQuestData['mx'][1528] = {title = "La llamada del agua", objective = "Encuentra a Islen Vidente del Agua en Los Baldíos.", description = "Haber agua'n tu futuro, colega. Veo tú ser ya familiar con fuego, así qu'estarás <listo/lista> pa' hablar con Islen.\n\nIslen vivir pa'llá por la costa de Los Baldíos. Si vas pa'l sur por el Río Furia del Sur, no se t'escapa, ¡buscar gran tiburón! Ella ser muy buena pa' temas d'agua... si creer que tú estar <listo/lista>.\n\n'star tirao encontrarla, ir to' pa'l sur, ella estar pasao Trinquete.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1529] = {title = "La llamada del agua", objective = "Encuentra a Islen Vidente del Agua en Los Baldíos.", description = "Mucho tiempo ha pasado desde que a prueba te pusieron, <nombre>. Paciencia en tus estudios hasta ahora has mostrado pero de aprender aún más la hora ha llegado. Ha llegado la hora de que aprendas cosas sobre la pureza del agua.\n\nBusca a Islen Vidente del Agua en Los Baldíos. Se encuentra por la costa oriental, al sur del Río Furia del Sur y de Trinquete. La encontrarás en su cabaña de pesca. Que la Fortuna te sea favorable, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1530] = {title = "La llamada del agua", objective = "Encuentra a Salmuera en la Loma Espina Negra, en Los Baldíos del Sur.", description = "Si hay una lección que has de aprender acerca del agua, es esta: el agua significa renacimiento.\n\nSu energía fluye, erosiona y limpia todo tipo de cosas. Su capacidad de curación y de reconstitución te parecerá sin parangón pero solo se da cuando es pura.\n\nCuando entiendas que si el agua está contaminada, puede causar estragos en todo aquello que toca, te darás cuenta de cuán vital es este recurso.\n\nSi deseas la sapta del agua, encuentra a Salmuera en lo más recóndito de Los Baldíos del Sur. Los jabaespines la importunan constantemente en su hogar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1531] = {title = "La llamada del aire", objective = "Encuentra a Prate Vidente de las Nubes en Las Mil Agujas.", description = "Tú estar haciendo progresos, colega. Estar <preparado/preparada> para demostrar si merecer recibir Tótem de aire, pero antes encontrar a Prate Vidente de las Nubes en Las Mil Agujas debes. Si tratas a ella con respeto, ella dirá lo que tener que hacer para conseguir tu Tótem de aire.\n\nVe al sur por Los Baldíos y al llegar a Las Mil Agujas, hacia el este. Encontrarás a ella por allí escondida con su novio... ¡Ja, ja, ja! No digas que yo dije... ¡a ella no gustar!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nTótem de aire"}
MultiLanguageQuestData['mx'][1532] = {title = "La llamada del aire", objective = "Encuentra a Prate Vidente de las Nubes en Las Mil Agujas.", description = "Los vientos de Kalimdor se apresuran por conocerte. Tú serás <uno/una> de <nuestros/nuestras> más <poderosos/poderosas> <hermanos/hermanas>. Me llena de orgullo comprobar que has llegado hasta aquí y que cuentas con un prometedor futuro.\n\nEl aire es un elemento difícil de controlar pero confío en que tus habilidades te sirvan para superar todos los obstáculos que te encuentres.\n\nDirígete al sur de Los Baldíos y ve a Las Mil Agujas. Allí, en la zona este, encontrarás a Prate Vidente de las Nubes. Ella te podrá enseñar mejor.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nTótem de aire"}
MultiLanguageQuestData['mx'][1534] = {title = "La llamada del agua", objective = "Llena el odre de agua azul vacío en Las Ruinas del Polvo Estelar en Vallefresno y llévasela a Salmuera en Los Baldíos.", description = "Toma este odre de agua y adéntrate en el frondoso bosque que los elfos de la noche llaman Vallefresno. Está en un lugar remoto del norte de Los Baldíos.\n\nCuando hayas penetrado en el bosque, dirígete hacia el oeste. Por las montañas que separan Espolón y Vallefresno, y más allá del Lago Mystral, encontrarás un lugar sagrado: Las Ruinas del Polvo Estelar. En el centro del lago encontrarás una fuentecilla.\n\nTráeme una muestra del agua de esa fuente. Será el último componente que necesitarás antes de que te mande de nuevo con Islen.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1535] = {title = "La llamada del agua", objective = "Llena el odre de agua marrón vacío en el abrevadero que está debajo de la cabaña de Salmuera y llévaselo a Los Baldíos.", description = "Para adquirir el conocimiento y ganarte la sapta, debes buscar solo las formas más puras de agua. Conforme recoges muestras para mí, observa a tu alrededor. Ten cuidado con las criaturas que dependen del agua, que la protegen. Fíjate en cómo afecta a los bosques y a los desiertos. Presencia cómo la mismísima sustancia en la que se sustenta la vida, obliga a las criaturas a arrebatar vidas.\n\nEmpezaremos con una tarea simple: debajo de mi cabaña hay un abrevadero con el preciado líquido. Llena este odre y vuelve aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1536] = {title = "La llamada del agua", objective = "Llena el odre de agua rojo vacío en el pozo de Molino Tarren y llévasela a Salmuera en Los Baldíos.", description = "Hace mucho tiempo seguí a unos compañeros hasta las Laderas de Trabalomas. Nos defendimos de tenaces humanos que allí moran y acabamos en un pueblecito que los Renegados habían tomado: Molino Tarren.\n\nAllí fue donde encontré algo muy especial: en el centro del pueblo había un pequeño pozo con agua dulce de manantial. No sé muy bien si los lugareños apestados se daban cuenta de su valor, es un pequeño vestigio sagrado en un mar sin consagrar.\n\nTráeme una muestra de esa agua en este odre.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1560] = {title = "La misión de Tooga", objective = "Muéstrale a Tooga el camino de vuelta con su esposa, Thorta.", description = "¡Estoy totalmente perdido!\n\nMi esposa, Thorta, me envió a buscar la cena y en algún momento debí haber tomado el camino equivocado.\n\n¿Serías tan amable de llevarme de vuelta con mi esposa Thorta? Ella me está esperando al sur del Puerto Bonvapor.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Puños quelónidosPodrás elegir una de estas recompensas:\n\nSortija de la Gran Tortuga\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][1578] = {title = "Abastecer al frente", objective = "Lleva 6 hachas y 6 cinturones de anillas de cobre a Thorvald a la torre de vigilancia sur de Loch Modan.", description = "Los montaraces de Loch Modan están luchando denodadamente contra los troggs. Necesitan un suministro constante de armaduras y armas.\n\nPor eso está allí mi colega Thorvald, encargándose del equipamiento de los montaraces. Seguro que te agradecerá que le fabriques unas hachas y unos cinturones de anillas de cobre. Puede incluso que comparta su sabiduría contigo.\n\nThorvald está en la torre sur de Loch Modan.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDiseño: tizona de cobre pesada"}
MultiLanguageQuestData['mx'][1579] = {title = "Mecanismos eléctricos", objective = "Lleva 8 mecanismos eléctricos a Maniveo Zumbang a Auberdine.", description = "Vine a Auberdine por su tranquilidad. Quería inventar mis inventos en un sitio tranquilo. El ajetreo de Forjaz era demasiado para mí cuando había pasado la noche bebiendo.\n\nAsí que me embarqué hacia Auberdine. Pero bebí demasiado durante la travesía. ¡Y se me cayó la caja de mecanismos eléctricos por la borda! ¡Necesito mis mecanismos!\n\nNo sé exactamente dónde se me cayeron, pero si puedes ir de pesca al océano, quizás tengas suerte...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1581] = {title = "Elixires para Filohoja", objective = "Llévale 6 elixires de fuerza de león y 2 elixires de defensa menor a Syral Filohoja, que está en Dolanaar.", description = "Nuestra tienda de alquimia y hierbas marcha bien, pero mi marido pasa tanto tiempo preparando pociones que casi nunca tenemos tiempo para nosotros.\n\n¿Podrías ayudarnos?\n\nSi me pudieras traer un pedido de elixires prefabricados, estaría encantada de hacer negocios contigo. Tengo algunas hierbas raras que puede que encuentres útiles.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][1582] = {title = "El jubón resplandor lunar", objective = "Trae 1 par de guantes de cuero estampados, 5 botas de cuero estampadas y 5 capas de cuero estampadas para Lotherias en Darnassus.", description = "En Darnassus estamos muy ocupados, sobre todo los artesanos. Los jóvenes aventureros están impacientes por probar sus habilidades en las tierras salvajes y encargan suministros constantemente.\n\nSi pudieras ayudarme a atender mis pedidos de artículos de cuero, yo podría enseñarte una técnica de peletería avanzada.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPatrón: jubón resplandor lunar"}
MultiLanguageQuestData['mx'][1618] = {title = "Equipar Crestagrana", objective = "Tormus Forjahonda quiere que le lleves 4 cinturones rúnicos de cobre y 4 mazas grandes de cobre pesadas a Verner Osbien a Crestagrana.", description = "Los enanos no somos los únicos que luchamos. ¡Nuestros aliados humanos también están muy ocupados!\n\nCrestagrana sufre ataques constantes de los orcos Roca Negra y siempre anda mal de equipamiento. Si decides ayudarles, seguro que su herrero, Verner Osbien, te enseñará lo que sepa.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDiseño: coraza de Forjaz"}
MultiLanguageQuestData['mx'][1638] = {title = "Instrucción de guerrero", objective = "Habla con Harry Burlguard en Ventormenta.", description = "Has demostrado ser <un guerrero/una guerrera> excelente, <nombre>, pero todavía eres joven y tienes mucho que aprender.\n\nVe a hablar con Harry Burlguard, suele estar en la taberna El Cerdo Borracho, en el Casco Antiguo de Ventormenta. Harry es un viejo veterano y un buen instructor. Puede enseñarte algunos movimientos que te ayudarán a seguir con vida algo más tiempo.", progress = nil, completion = "¡Oh, jo! Tómate un trago conmigo, muchacho. A primera vista pareces muy duro, pero veamos si puedes arreglártelas con algunas jarras de las especialidades más potentes de El Cerdo Borracho \n\nO bien... ¿has venido para recibir instrucción?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1641] = {title = "Escrito sobre divinidad", objective = "Aquí, en Ventormenta, yo me encargo de poner en el camino de la virtud a los paladines que se consagran a la Luz y defienden Azeroth de la Plaga y otras amenazas. \n\nY ha llegado el momento de que tú des tus primeros pasos hacia la virtud verdadera. Si aceptas, te daré un escrito sobre divinidad. Estudiándolo, aprenderás algo sobre la Luz y sobre lo que se espera de ti. Si lo entiendes y tienes capacidad para ello, conseguirás mayores habilidades.", description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nEscrito sobre divinidad"}
MultiLanguageQuestData['mx'][1642] = {title = "Escrito sobre divinidad", objective = "Habla con Duthorian Rall en Ventormenta.", description = "Un paladín debe reflejar en todas las cosas la Luz que complementa su fuerza. El esfuerzo por alcanzar la divinidad, para uno de nosotros, no significa aspirar al bien, pues aspiramos al bien en todas nuestras acciones.\n\nAunque en estos duros tiempos somos convocados para atacar al mal, debes recordar que será la ayuda que prestes a los demás lo que te distinguirá de los ciudadanos de Azeroth. La compasión, la paciencia y el valor tienen tanta importancia en un paladín como su fuerza en la batalla.\n\nAprende esto ahora y nunca lo olvides.", progress = nil, completion = "Hola de nuevo, &lt;nombre&gt;. ¿Cómo van tus estudios del escrito sobre divinidad? \n\nSi lo has estudiado, deberías estar preparada para pasar una prueba. Siempre hay cosas que hacer en la ciudad y en nuestras tierras. Actos de compasión y comprensión, gente a la que ayudar, criaturas a las que matar... \n\nSi demuestras que tienes la paciencia necesaria para ayudar a otros, especialmente a los menos afortunados, demostrarás que estás en pleno uso de tus facultades y que eres una sierva de la Luz.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1643] = {title = "Escrito sobre divinidad", objective = "Busca a Stephanie Turner en el Distrito de Mercaderes de Ventormenta.", description = "Ahora, tu tarea, <nombre>, es encontrar en Ventormenta a alguien que necesite ayuda. Alguien de intenciones y corazón puros. Quizás alguien que ayude a los demás. Alguien que necesite ser guiado. En cualquier caso, esa persona debe tener intenciones nobles y depender de tu bondad.\n\nVuelve a mí cuando hayas acabado. Entonces seguiremos hablando de tu camino y de lo que significa ser un paladín de la Luz.", progress = nil, completion = "Oh, hola, cielo. ¿Cómo van tus aventuras? Me alegro mucho de que te vaya tan bien. \n\n¿Que qué tal yo? Pues gracias por interesarte por mí. En general, estoy bien. \n\nEl aumento de mercaderes ha reducido un poco las cantidades de cuero y tela que dona la gente, así que últimamente está resultando difícil hacer ropa para los niños del orfanato... Pero nos las arreglaremos. Y con \"nos\", quiero decir mi marido y yo. Él está en Forjaz ahora, intentando conseguir ayuda de sus habitantes.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1644] = {title = "Escrito sobre divinidad", objective = "Lleva 10 retales de paño de lino a Stephanie Turner a Ventormenta.", description = "Benditos sean, la mayoría de ellos han perdido a su familia en la última década... a manos de la Plaga.\n\nMi marido John recoge material para que yo haga camisas y pantalones para los niños, pero no he tenido tiempo de hacerlo. Mi primera preocupación ha sido ponerles comida que en el plato y procurarles un techo.\n\n¿Cómo dices? ¿Que quieres ayudar? ¡Oh, gracias a la Luz! ¡Y gracias a ti, <nombre>!\n\nSi pudieras traerme paño de lino para que cosa ropa para los niños, me ayudarías mucho.", progress = "Espero que mi John esté teniendo más suerte en Forjaz. No le gusta ir allí porque tiene que dejarnos a mí y a los niños solos, pero sabe que tiene que hacerse. Es tan bueno...\n\nAlgunos años han sido más difíciles que otros, pero este desde luego, ha sido el más duro de todos. Parece que haya algo en el aire que anuncia un gran cambio. Pero... ¿quién sabe?", completion = "¡Muchas gracias, &lt;nombre&gt;! ¡Muchas, muchas gracias! \n\nLos niños estarán felices, de verdad. ¡Y a mí me has ahorrado tanto tiempo! Ahora podré concentrarme en las otras necesidades de los niños. Y, con suerte, mi John podrá volver a casa antes de lo que pensábamos. \n\nGracias de nuevo, &lt;nombre&gt;. Sabía que podía contar con la caridad de los demás. Que la Luz sea contigo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1649] = {title = "Escrito sobre valor", objective = "Habla con Duthorian Rall en Ventormenta.", description = "El valor y todas las virtudes que lo acompañan, son como minerales preciosos y poco comunes: debes apreciarlos cuando los encuentras porque son valiosos, pero también debes invertir tiempo en cuidarlos... refinarlos. Cuando se mezclan correctamente, se forma una fuerte aleación que, algunas veces, resulta imposible de romper, incluso con los golpes más poderosos.\n\nTodo esto debe ser puesto a prueba: la fuerza, tu fe, tu valentía. Debes aprender a no perder la fe y darte cuenta de que con el poder de la Luz, puedes conseguir cosas que otros no pueden.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1650] = {title = "Escrito sobre valor", objective = "Encuentra a Daphne Fontana en los Páramos de Poniente.", description = "¡Bien! Que no vaciles es una señal inequívoca de que estás <preparado/preparada> y <dispuesto/dispuesta> a ponerte a prueba. Que así sea.\n\nJusto al final de Playa Larga, en los Páramos de Poniente, hay una pequeña casa con vistas al océano. Allí vive una pareja, los Fontana. Jordan es un herrero fabuloso y ha ido a Forjaz a pasar una temporada con los enanos. Pero esto ha dejado a Daphne, su mujer, sola y desprotegida.\n\nLos informes sugieren que los Defias han tomado casi toda la zona, es posible que Daphne necesite protección. Ve allí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1651] = {title = "Escrito sobre valor", objective = "Defiende a Daphne Fontana del ataque de los Defias.\n\nSi quieres tener éxito, sus espíritus no pueden salir de sus espirales mortales.\n\nCuando lo hayas conseguido, vuelve a hablar con Daphne Fontana.", description = "Apuesto a que volverán pronto, así que debes prepararte.\n\nTengo una pistola en la casa. La traeré y me prepararé para ayudarte pero, en general, estarás <solo/sola>.\n\nNo tengo ni idea de cuántos mandarán, pero seguro que serán más de los que mandaron antes.\n\nRuega a la Luz que nos bendiga porque... ¿Has oído eso? Creo que ahí vienen.\n\n¡Nos ubicaremos cerca de la casa!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1652] = {title = "Escrito sobre valor", objective = "Habla con Duthorian Rall en Ventormenta.", description = "Por favor, vuelve a ver a Duthorian y dile que, por ahora, estoy a salvo. Y todo gracias a ti y a la iglesia.\n\nÉl enviará el mensaje a Forjaz para que mi querido Jordan sepa que no tiene nada que temer.\n\n¡Oh, cómo echo de menos a mi marido! Qué ganas tengo de que vuelva.También recibirás:\n\n", progress = nil, completion = nil, rewards = "También recibirás:\n\nBastión de Ventormenta"}
MultiLanguageQuestData['mx'][1653] = {title = "La prueba de rectitud", objective = "Habla con Jordan Fontana en Forjaz.", description = "No dudo que Jordan desea darte las gracias personalmente, y puesto que debo enviarle mensaje de que su esposa está bien, creo que eres la mejor elección.\n\nJordan iba a ser paladín de la Luz hasta que su dedicación al arte de su padre lo llevó por otros derroteros; conoce bien nuestro modo de vida y lo consideramos uno de nuestros más devotos.\n\nEstará en Forjaz; le gusta trabajar en el exterior por algo relacionado con el aire fresco.", progress = nil, completion = "Saludos, &lt;nombre&gt;, que la Luz esté contigo. \n\n¿Que vienes de parte de Duthorian? ¿Cómo está mi esposa? Gracias a la Luz, me alegro de saber que está bien. Los consejeros del Rey ya no pueden negar la evidente amenaza. \n\n¿Qué más dijo Duthorian? \n\n&lt;nombre&gt;, no sabes cuánto te agradezco que protegieras a mi esposa. Es la mejor prueba de coraje.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1654] = {title = "La prueba de rectitud", objective = "Consulta la lista y llévale a Jordan Fontana de Forjaz lo siguiente: madera de roble de Piedrablanca, envío de oro refinado de Bailor, el martillo de herrero de Jordan y una gema Kor.", description = "Si aceptas, te recompensaré. Entiéndeme bien, mi generosidad depende de hasta qué punto me ayudes, pero creo que una alianza nos sería beneficiosa.\n\nTe haré un arma digna de tus logros, un símbolo de los paladines y de la Luz, pero tienes que traerme los objetos que necesito para crearla. Tengo aquí la lista; solo necesito a alguien valiente que vaya a buscar los objetos. ¿Qué me dices, <clase>?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1655] = {title = "Envío de mena de Bailor", objective = "Lleva el envío de Jordan a Bailor Petramano a Loch Modan.", description = "¡Me has asustado, <tío/tía>! ¿No ves que estaba reflexionando?\n\n¿Qué es eso? El cargamento de Jordan para Forjaz. Vale, ya lo pillo. Los ogros de Mo'grosh son los que afanaron los minerales de mi amigo. Atacaron la caravana cuando venía de Los Humedales. El único guardia que sobrevivió palmó hace poco; los sanadores no sabían qué hacer.\n\nSi quieres el cargamento, tendrás que cruzar Loch Modan hacia el noreste. Tiene que estar por ahí.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nEnvío de mena refinada de Jordan"}
MultiLanguageQuestData['mx'][1656] = {title = "Una tarea por terminar", objective = "Lleva el fardo de pelajes al tabernero Kauth al Poblado Pezuña de Sangre.", description = "Por favor, <nombre>, ¿puedes ayudarme? Estoy cumpliendo la prueba del Rito de la Fuerza; mi padre me pidió que entregara estas pieles en la posada de Pezuña de Sangre.\n\nNo puedo completar el rito y el recado de mi padre; no tengo fuerzas. ¿Puedes hacer la entrega por mí?\n\nLa posada es un sitio muy agradable para descansar de tanto viaje; seguro que me lo agradecerás.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nMendrugo de pan duroAgua de manantial refrescante\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][1657] = {title = "Apesta Costasur", objective = "Lanza 3 bombas fétidas de los Renegados en el corazón de Costasur en Trabalomas, y después ve a ver a la clamasombras Yanka, que está en el Festival del Hombre de Mimbre en los Claros de Tirisfal.", description = "Para celebrar la fiesta de Halloween con estilo... ¡infríngeles dolor a nuestros enemigos de Costasur!\n\nCoge una de estas bombas fétidas especialmente diseñadas. Contiene una sustancia apestosa que ningún humano u otra bestia cualquiera de poca voluntad pueden soportar. Tendrás que lanzarla en el mismísimo centro de Costasur para que surta efecto, así que prepárate para una batalla contra la Alianza.\n\nCuando hayas realizado esta tarea, este tributo a nuestra liberación... ¡ven a verme!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGolosinas de calabaza de Halloween"}
MultiLanguageQuestData['mx'][1658] = {title = "Arruinar el Festival del Hombre de Mimbre", objective = "Localiza el Festival del Hombre de Mimbre de los Renegados en Claros de Tirisfal. Cuando acabes, ve a ver al sargento Hartman a Costasur.", description = "Necesito gente valiente para ir a Claros de Tirisfal y echar un ojo al Festival del Hombre de Mimbre. No te voy a mentir: llegar hasta allí es peligroso. Los guardas del festival serán excepcionalmente brutales. Pero tenemos que saber cómo será el festival de este año y cuántos problemas nos van a dar los Renegados en Halloween.\n\nVe a Tirisfal y echa un vistazo por el festival... si te atreves. Vuelve con la información y me aseguraré de que recibes una buena recompensa.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGolosinas de calabaza de Halloween"}
MultiLanguageQuestData['mx'][1661] = {title = "Escrito sobre nobleza", objective = "Habla con Duthorian Rall en Ventormenta.", description = "Te saludo de nuevo, <nombre>. Siento más orgullo que nunca por poder llamarte <hermano/hermana>. Tu dedicación es un honor para todos nosotros.\n\nHa llegado el momento de que te haga un gran regalo. Pero has de saber algo: por ahora, te doy esto libremente pero, más tarde, cuando sea el momento preciso, esto será un desafío mucho mayor para todos los paladines que decidan aceptar mi misión.\n\nVuelve a hablar conmigo y te concederé un gran favor.", progress = nil, completion = "Enhorabuena y que la Luz te proteja.", rewards = "Aprenderás:\n\nInvocar caballo de guerra"}
MultiLanguageQuestData['mx'][1680] = {title = "Tormus Forjahonda", objective = "Habla con Tormus Forjahonda.", description = "Ahora que ya has aprendido nuevos movimientos, es el momento de darte un arma decente. Ve a hablar con Tormus Forjahonda. Te hará un arma que seguro que te gustará.\n\nLo encontrarás aquí, en Forjaz, en La Gran Fundición.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1681] = {title = "Complejo Vetaferro", objective = "Lleva una pieza de mena umbría a Tormus Forjahonda en Forjaz.", description = "Mi mentor, Sturgy Vetaferro, tenía un complejo al sur del Lago de Helm, en la parte oriental de Dun Morogh. Allí enseñaba herrería y era el mejor.\n\nPero un día, uno de sus estudiantes le llevó una extraña mena. El maestro Vetaferro la llamó mena umbría y estaba ansioso por trabajar con ella, pero tan pronto como llegó el cargamento un grupo de enanos Hierro Negro atacaron su complejo. ¡Mataron a todo el mundo!\n\nEntra en el Complejo Vetaferro, <nombre>, y venga la muerte de mi maestro. Tráeme también el cargamento de mena umbría que le causó la muerte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1685] = {title = "La invocación de Gakin", objective = "Preséntate ante Gakin el Presotenebra en el Barrio de los Magos de Ventormenta.", description = "Si es que... siempre igual. Me he pasado el día buscándote sin encontrarte y ahora, cuando ya ni te esperaba, te plantas aquí, sin más.\n\nYa he perdido demasiado tiempo buscándote. No perdamos más. El maestro Gakin te ha convocado para instruirte. Creo que deberías ir en su busca lo antes posible.\n\nLo encontrarás en el sótano de la posada El Cordero Degollado. Por cierto, será mejor que no comentes por ahí ese detalle de la posada... No queremos que se corra la voz de dónde se encuentra...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1686] = {title = "La sombra de Elura", objective = "Lleva 8 piezas de mineral de elunita y el Medallón de Elura a Elanaria en Darnassus.", description = "Has aprendido mucho, <nombre>. Ahora podremos fabricarte un arma. Un arma de <auténtico guerrero/auténtica guerrera>.\n\nPara hacerlo debes viajar a la Costa Oscura.\n\nHace mucho tiempo, un barco naufragó junto a las rocas, cerca del faro de Auberdine, esparciendo muchos cajones de mena de elunita por todo el fondo marino.\n\nPara empezar, debes derrotar a la guardiana de la elunita, la Sombra de Elura. La que fue capitana del barco se condenó a sí misma a vagar por las profundidades y a proteger el cargamento por el resto de los tiempos. Acaba con ella, hazte con su medallón y recoge los cajones de elunita perdidos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1688] = {title = "Surena Caledon", objective = "Consigue la gargantilla de Surena para Gakin el Presotenebra de Ventormenta.", description = "Tuve a una estudiante llamada Surena Caledon. Estaba justo donde estás tú ahora, dispuesta a aprender brujería y sin una pizca de talento. A pesar de eso, era joven y muy bonita. Tenía que haberlo visto venir, ¡esa mujerzuela traidora!\n\nLa ladronzuela escapó con un matón, Erlan Morosiervo. Si bien su pérdida no es muy importante, le regalé una gargantilla de sangrita que debo recuperar.\n\nAhora, su vida no significa nada para mí. La encontrarás en la Plantación de Calabazas de Brackwell. Recupera lo que me pertenece.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1690] = {title = "Justicia para los Vagayermos", objective = "Acaba con 10 bandidos y ladrones Vagayermos al este de Gadgetzan y después vuelve a ver al ingeniero jefe Pasaquillas.", description = "¡Eh, tú! Es hora de que ayudes a la compañía de aguas de Gadgetzan.\n\n¡Los nómadas Vagayermo de Tanaris se han hecho con el poder de todos los pozos de agua! Ahora que ya no tenemos acceso a ellos, el suministro de agua se agotará en poco tiempo. Si deseas recibir nuestra gratitud, ayúdanos a impartir justicia a esos nómadas.\n\nDirígete hacia el este, captura a 10 bandidos y ladrones Vagayermos y regresa aquí inmediatamente. ¡La justicia no espera a ningún hombre... goblin... lo que sea! ¡Ponte ya en marcha!", progress = nil, completion = "¡A eso le llamo yo ser eficiente! Has acabado con tantos nómadas que ya se dibuja la posibilidad de recuperar nuestros pozos de agua. \n\nLa compañía de aguas de Gadgetzan te agradece tu inestimable ayuda, aunque todavía queda mucho trabajo que hacer con estos nómadas. Escucha atentamente, esto es lo próximo que necesitamos que hagas...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1691] = {title = "Más justicia para los Vagayermos", objective = "Acaba con 10 magos oscuros Vagayermos, 8 pícaros Vagayermos y 6 asesinos Vagayermos para el ingeniero jefe Pasaquillas de Gadgetzan.|n", description = "Necesitamos que te encargues de las filas más fuertes de los nómadas Vagayermos. Has hecho un buen trabajo hasta el momento pero si queremos recuperar los pozos de agua, lo más inteligente es que nos enfrentemos al menor número de nómadas posible.\n\nEn esta ocasión te pedimos que acabes con sus pícaros, asesinos y magos oscuros. Los encontrarás en dirección este y sudeste.\n\nNo voy a mentirte: son unos seres repugnantes. Si finalmente haces esto por nosotros, ¡estaremos un paso más cerca de recuperar lo que nos pertenece!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1701] = {title = "Armadura de malla endurecida con fuego", objective = "Reúne los materiales que necesita Furen Barbalarga y llévaselos a Ventormenta.", description = "Te he dado un buen escudo, pero la cosa no termina aquí. Conozco los secretos para hacer una armadura de malla extremadamente dura. No es fácil y se necesitan algunos materiales bastante extraños, pero si quieres hacer tú los preparativos te haré una pieza.\n\n¿Qué me dices, <nombre>? Si estás <listo/lista> para el desafío, te daré una lista de lo que necesitas y dónde conseguirlo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1702] = {title = "El forjador de escudos", objective = "Lleva el barril de brebaje a Furen Barbalarga.", description = "Superando El guantelete de Rethban has demostrado de qué estás <hecho/hecha>, <nombre>. Y yo soy fiel a mi palabra. Te daré la recompensa prometida...\n\nEl único problema es que está en Ventormenta.\n\nVe a hablar con mi amigo, Furen Barbalarga, en el Distrito de los Enanos de Ventormenta. Es el mejor forjador de escudos que podrás encontrar, y me debe un gran favor.\n\nToma, llévale este barril de brebaje de Cebadiz a Furen y pídele un escudo. Seguro que te dará uno estupendo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFavor de Furen"}
MultiLanguageQuestData['mx'][1707] = {title = "Cazador de faltriqueras de agua", objective = "Llévale 5 faltriqueras de agua de Vagayermos al grifoperador Llantalunket, que está en Gadgetzan.", description = "Saludos, <nombre>. Mi nombre es Llantalunket y, si quieres, te puedo ofrecer una misión. ¡Hurra!\n\nNada me agradaría más como grifoperador que me trajeses las faltriqueras de agua de Vagayermos que encuentres por el desierto. Al fin y al cabo, es nuestra agua. Los nómadas la han robado. La compañía de aguas de Gadgetzan te ofrecerá un botiquín oficial por cada cinco faltriqueras que entregues. Y lo más importante, ¡estarás ayudando a Gadgetzan!", progress = nil, completion = "Excelente, ¡cuantas más faltriqueras de agua consigamos, más nos alejaremos del desastre! Consigue tantas como puedas y te daré una recompensa por cada 5 faltriqueras de agua que me traigas.", rewards = "Recibirás:\n\nBotiquín de la compañía de aguas de Gadgetzan"}
MultiLanguageQuestData['mx'][1712] = {title = "Ciclonio", objective = "Lleva los objetos sobre el papiro de Bath'rah a Bath'rah el Vigía del viento en Alterac.", description = "He pasado años observando este sitio. Vigilo para poder ver un día el descenso del gran Ciclonio. Pero todavía no he encontrado a ningún campeón que pueda derrotar al Señor del viento.\n\nQuizás tú seas ese campeón.\n\nDemuéstramelo. Reúne los objetos necesarios para invocarle y sabré que eres <un gran guerrero/una gran guerrera>. Quizás entonces puedas derrotarle y hacerte con su corazón de espirálico.\n\nSi lo haces imbuiré el poder del corazón en un arma y te la daré a ti.\n\nEste es el papiro con los objetos que necesito.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1715] = {title = "El Cordero Degollado", objective = "Preséntate ante Gakin el Presotenebra en el Barrio de los Magos de Ventormenta.", description = "Bah. Antes, todos los brujos de Khaz Modan estudiaban con los maestros de Gnomeregan, pero ahora que hemos tenido que venir a este pueblucho que es Forjaz y que Magni ha decidido vigilarnos, tenemos que enviar a los novicios a estudiar a Ventormenta.\n\nPor suerte, con Gakin aprenderás todo lo que necesites saber, pero aun así, ¡este asunto me hace hervir la sangre!\n\nLo encontrarás en el sótano de El Cordero Degollado en Ventormenta.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1716] = {title = "Devoradora de almas", objective = "Habla con Takar el Vidente en Los Baldíos.", description = "Un sayaad es un devorador de almas, un dominador de voluntades con la capacidad de tentar corazones. Lo único que sabe hacer es el mal.\n\nLos relatos más lujuriosos se refieren al demonio por su nombre común: “súcubo” para las hembras, “íncubo” para los machos.\n\nSe requiere de un estímulo para invocar a la criatura. Con un símbolo de amor como carnada, seguramente atenderá tu llamado. Si la derrotas, se convertirá en tu instrumento.\n\nPero no será fácil encontrar algo así. Deberías hablar con Takar el Vidente. Puedes encontrarlo en Los Baldíos de Kalimdor, cerca del Campamento Taurajo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1718] = {title = "El isleño", objective = "Habla con Klannoc Macleod.", description = "Tu fama como <guerrero/guerrera> no deja de crecer, <nombre>. Ha llegado el momento de enfrentarte a tus pares y ver cuál es tu posición entre ellos.\n\nHay una isla en la costa de Los Baldíos, al sur de Trinquete. Es conocida como Isla de Batalla y en ella se encuentran los guerreros.\n\nSe encuentran y combaten.\n\nHabla con el jefe guerrero de Isla de Batalla, Klannoc Macleod. Si te juzga <digno/digna> te guiará por la senda del guerrero.\n\nPara llegar a Isla de Batalla, busca el banco de arena que cubre La Costa Mercante.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1719] = {title = "La Reyerta", objective = "Mata a Will el Grande y habla con Klannoc Macleod en Isla de Batalla.", description = "Si quieres instruirte conmigo tendrás que superar La Reyerta. Es un desafío que ofrecemos aquí, en Isla de Batalla, a los guerreros que se creen fuertes, si superas la prueba sabremos que lo eres.\n\nPara empezar dirígete al centro de esa multitud y ponte en la rejilla. Así indicarás a Twiggy Cabezaplana que estás <preparado/preparada> y enviará a tus contrincantes.\n\nDerrótalos y llamará a Will el Grande. Mata a Will el Grande y vuelve a verme dentro del tiempo permitido.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1738] = {title = "Duramen", objective = "Recupera el duramen de Vallefresno y llévaselo a Gakin el Presotenebra en el Barrio de los Magos de Ventormenta.", description = "Para preparar tu llegada, utilicé mi visión para ver por encima del mundo y a través de la niebla del tiempo. He encontrado lo que buscas.\n\nEn la Guerra de los Ancestros, dos amantes cayeron juntos en combate. En el lugar donde exhalaron su último aliento, nació un árbol conocido como el duramen, un símbolo de su amor imperecedero.\n\nEso debería ser suficiente para tentar a un súcubo. Lo encontrarás en las Ruinas de Ordil'Aran, en la parte noroeste del Bosque de Vallefresno.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1740] = {title = "El orbe de Soran'ruk", objective = "Encuentra 3 fragmentos de Soran'ruk y 1 fragmento grande de Soran'ruk y llévaselos a Doan Karhan en Los Baldíos.", description = "Cuando los demonios de la Legión caen en desgracia, sus espíritus se encarcelan en unos orbes que se distribuyen entre sus magos y brujos.\n\nMuchos fueron llevados por sus sirvientes en Azeroth. Incluso rotos en trozos, poseen los poderes de los demonios atrapados en ellos.\n\nEl orbe de Soran'ruk se partió en dos piezas, una de las cuales se rompió en pedazos aún más pequeños para los acólitos del Martillo Crepuscular de las Cavernas de Brazanegra. La otra, la de mayor tamaño, acabó en manos de un mago del Castillo de Colmillo Oscuro. Encuéntralas y podré reconstituirlo.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Bastón de Soran'rukPodrás elegir una de estas recompensas:\n\nOrbe de Soran'ruk\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][1758] = {title = "Libro del conciliábulo", objective = "Habla con Krom Brazorrecio en Forjaz.", description = "Hará falta algo más que un simple círculo de conjuro para invocar a un manáfago al que quieres desafiar.\n\nMis tres acólitos y yo te ayudaremos a crear los círculos mágicos. Necesitas un ejemplar del libro del conciliábulo, que lleva un tiempo desaparecido. Lo escribieron los primeros brujos que invocaron a un manáfago por sus propios medios.\n\nA lo mejor Krom Brazorrecio puede ayudarnos. Hoy en día es un brujo itinerante, se pasa el tiempo acumulando textos antiguos y merodeando por la biblioteca de Forjaz.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1780] = {title = "Escrito sobre divinidad", objective = "Habla con Duthorian Rall en Ventormenta.", description = "Llevaré esto a los niños hoy mismo. Cuídate, por favor, <buen/buena> <clase>. No encuentra una a menudo personas como tú en la ciudad. Has demostrado que los paladines de Ventormenta nunca vuelven la espalda a quienes los necesitan.\n\nAdiós.", progress = nil, completion = "Qué pronto has vuelto, &lt;nombre&gt;. ¿Y qué has conseguido en este tiempo que no has estado en la Catedral? \n\n¿Has conseguido ayudar en alguna noble causa? Quizás hayas aprendido el valor de la caridad o algo más sobre tus obligaciones para con los habitantes de Azeroth. Dime a quién has ayudado y cómo... Vaya, estoy impresionado, &lt;nombre&gt;, las tuyas son sin duda acciones de alguien que sigue el camino de la Luz y antepone el bien de los demás al propio. \n\nTu sacrificio se verá recompensado con el tiempo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1781] = {title = "Escrito sobre divinidad", objective = "Lleva el Símbolo de la Vida a Gazin Tenorm a Ventormenta.\n\nObjeto provisto: \n", description = "Coge esto, <nombre>. Se llama Símbolo de la Vida.\n\nHas demostrado ser paciente y <caritativo/caritativa> y ahora ha llegado el momento de ver si tienes poder suficiente para centrarte en uno de los mayores dones de la Luz.\n\nMi amigo Gazin tuvo hace poco un encuentro con unos Defias en Elwynn, cerca de la Vigilia de los Héroes... casi le cuesta la vida. Está cerca del altar. Uno de nuestros sacerdotes está curando sus heridas.\n\nLlévale el Símbolo y habla con él. Si puedes ayudarle, volveremos a hablar. Pronto. Que la gloria de la Luz sea contigo.", progress = nil, completion = "*tose* \n\nEs un placer conocerte, &lt;clase&gt;. No prestes atención a mis heridas. Este buen sacerdote se ocupará del viejo Gazin. No necesitaré el poder de ese Símbolo de la Vida que has traído... al menos, no todavía. \n\nAsí que te envía Duthorian, ¿eh? Muy bien. Te diré exactamente lo que nos ocurrió a mí y a mi amigo Henze. Y, con un poco de suerte y algo de habilidad por tu parte, quizás puedas ayudarnos a todos.", rewards = nil}
MultiLanguageQuestData['mx'][1786] = {title = "Escrito sobre divinidad", objective = "Llévate el Símbolo de la Vida y resucita a Henze Faulk en Elwynn.", description = "Henze y yo conseguimos llegar a la Vigilia de los Héroes, una isla que hay en el centro del Lago del Hito, al noreste de Elwynn. Habíamos oído que los Defias habían cruzado nuestras fronteras y queríamos conseguir pruebas para los consejeros del Rey.\n\nVimos a un par de esos tipos leyendo unos documentos y atacamos. Por desgracia, llegaron más magos y pronto nos vimos superados.\n\nHenze los contuvo mientras yo escapaba... ese tonto, haciéndose el héroe...\n\nAhora está ahí, solo... ¿Puedes ayudarnos, <nombre>?", progress = nil, completion = "Gracias, hermana. \n\nVeo que portas el Símbolo de la Vida, ¿puedo deducir de eso que te envían Duthorian o Gazin? \n\nCaí ante los hechizos de los Defias cuando Gazin y yo intentábamos hacernos con sus planes. Conseguí aguantar el tiempo suficiente para que Gazin escapara, pero al final, su magia me superó. \n\nY entonces llegaste tú y me trajiste de nuevo a la vida. La habilidad de utilizar el Símbolo no la tiene cualquiera, &lt;nombre&gt;. Debes apreciar lo que significa que pudieras utilizarlo con ayuda de tu fe.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1787] = {title = "Escrito sobre divinidad", objective = "Recupera 1 misiva Defias de los zahoríes bribones Defias de Elwynn y vuelve con Gazin Tenorm a Ventormenta.", description = "Ya tendremos ocasión de hablar sobre el Símbolo más adelante. Lo importante ahora es conseguir esos papeles que tenían los Defias. Si logramos hacernos con ellos, podremos probar que la banda Defias se ha infiltrado en Elwynn y, con suerte, averiguaremos cuáles son sus planes.\n\nYo ahora no estoy en disposición de combatir, <nombre>. ¿Crees que tienes la fuerza necesaria para arrebatar esos papeles a los Defias de la isla?\n\nSi consigues hacerte con ellos, llévaselos a Gazin. Y dile también que estoy bien.", progress = "¿Henze está a salvo, <nombre>? ¿Tuviste éxito?\n\nEntre tu habilidad con las armas y el poder de la Luz, creo que la Vigilia de los Héroes estará a salvo de cualquier amenaza de los Defias, pero eso deben decirlo el Rey y sus consejeros.", completion = "¡Estupendo! Lo has conseguido, has salvado a Henze. ¡Es evidente que la Luz está en ti, &lt;nombre&gt;!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1788] = {title = "Escrito sobre divinidad", objective = "Habla con Duthorian Rall en Ventormenta.", description = "Cuando Duthorian haya echado un vistazo a este texto, se lo llevaré a los consejeros del Rey. Pero tú deberías ir a hablar con Duthorian ya. ¡Querrá darte una palmadita en la espalda!\n\nGracias otra vez, <nombre>. Espero que volvamos a encontrarnos. Eres <un aliado al/una aliada a la> que me enorgullece considerar <un amigo/una amiga> también.", progress = nil, completion = "Has actuado bien, &lt;nombre&gt;. Deberías enorgullecerte de lo que has conseguido. \n\nDeberías estar orgullosa de tus habilidades. No todo el mundo puede utilizar el poder del Símbolo de la Vida. Si puedes invocar a la Luz para devolver a los muertos a la vida, es que estás preparada para uno de los mayores honores de los paladines: el poder de resucitar. \n\nPodrás devolver a la vida a compañeros caídos, tal y como hiciste con Henze. \n\nCuídate, &lt;nombre&gt;. La Luz te ilumina. Recíbela en ti.", rewards = "Aprenderás:\n\nRedención\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][1790] = {title = "El Símbolo de la Vida", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nSímbolo de la vida"}
MultiLanguageQuestData['mx'][1791] = {title = "El Vigía del viento", objective = "Habla con Bath'rah el Vigía del viento.", description = "Ahora que has aprendido la actitud rabiosa, querrás tener una buena arma.\n\nVe a hablar con Bath'rah el Vigía del viento, un ermitaño trol que vive entre las Montañas de Alterac y las Tierras de la Peste del Oeste. Es un forjador de armas muy diestro y un poderoso chamán.\n\nPara encontrar a Bath'rah ve hasta el río que fluye en el lado oriental del Molino Tarren. Síguelo hacia el Norte. Bath'rah está acampado junto a las ruinas que encontrarás en la orilla oriental del río.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1793] = {title = "Escrito sobre valor", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nEscrito sobre Valor"}
MultiLanguageQuestData['mx'][1794] = {title = "Escrito sobre valor", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nEscrito sobre Valor"}
MultiLanguageQuestData['mx'][1796] = {title = "Los componentes para la toga de sangre dorada encantada", objective = "Llévale las togas de Arcana a Menara Nadiz en Los Baldíos.", description = "El primer objeto que te ayudaré a crear es una toga. Tú recolectarás los elementos para mí y yo los uniré. Después, y siempre que lo consigas, obtendrás el primero de muchos objetos que te harán más <poderoso/poderosa> y que te ayudarán en tus esfuerzos.\n\nPara empezar, tendrás que haber confeccionado togas de Arcana. Un sastre puede hacer esto por ti, o quizás puedas comprarle una a alguien, pero estaría de lo más impresionada si la hicieras tú <mismo/misma> pero sea como fuere, tráeme las togas y ya veremos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1798] = {title = "Buscando a Strahad", objective = "Habla con Strahad Farsan en Los Baldíos.", description = "Es hora de que aprendas a invocar a un manáfago, <nombre>. No tengo los componentes ni los objetos necesarios para enseñarte aquí, así que tendrás que buscar a otro, Strahad Farsan, otro de nuestro círculo interno.\n\nVive en el puerto goblin de Trinquete. Enviaré un mensaje para informarle de tu llegada.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1799] = {title = "Los trozos del orbe de Orahil", objective = "Habla con los acólitos de Menara que están en el interior de la torre que domina Trinquete y elige uno de sus caminos para seguirlo.\n\nDespués, llévale un orbe infernal a Tabetha en Marjal Revolcafango.", description = "Bien, entonces empezaremos.\n\nPrimero debes hablar con mis acólitos de ahí adentro. Elige uno de los caminos que te ofrezcan, ellos te darán más detalles.\n\nEn segundo lugar, debes viajar hasta Desolace y encontrar un orbe infernal en manos de uno de los brujos del Aquelarre Mannoroc. Este es el orbe que limpiarás con la ayuda de una maga llamada Tabetha que se encuentra en lo más recóndito al sur de Marjal Revolcafango. Te ayudará por nuestro pasado común.\n\nInsisto, no vuelvas hasta que hayas completado las dos cosas que te he pedido.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1800] = {title = "Sala del Trono de Lordaeron", objective = "Lleva a tu pupilo a la antigua Sala del Trono de Lordaeron. La encontrarás justo antes de llegar al acceso a Entrañas.|n", description = "Por la noche, si éramos buenos y hacíamos los deberes, las supervisoras de huérfanos nos contaban historias impresionantes de combates y tradiciones. Una historia era la de la caída de Lordaeron y de cómo el malvado Arthas mató a su propio padre para hacerse con el poder.\n\nNo tiene ningún honor, <nombre>. Cuando crezca y sea un poderoso guerrero de la Horda, mi espada estará guiada por el honor, ¡nunca por el mal!\n\n¿Me quieres llevar a ver la sala del trono, por favor? Está justo antes de llegar a la entrada de Entrañas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1801] = {title = "Libro del conciliábulo", objective = "Habla con Jorah Annison en Entrañas.", description = "Hará falta algo más que un simple círculo de conjuro para invocar a un manáfago al que quieres desafiar.\n\nMis tres acólitos y yo te ayudaremos a crear los círculos mágicos. Necesitas un ejemplar del libro del conciliábulo, que lleva un tiempo desaparecido. Lo escribieron los primeros brujos que invocaron a un manáfago por sus propios medios.\n\nA lo mejor Jorah Annison puede ayudarte. Ahora trabaja de cartógrafo en Entrañas pero sigue siendo el que más sabe de textos antiguos de todos mis conocidos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1802] = {title = "Libro del conciliábulo", objective = "Lleva el escrito mohoso y el manuscrito maltrecho a Krom Brazorrecio a Forjaz.", description = "Se cree perdido, pero sospecho dónde podría estar.\n\nSolo hay un ejemplar y en algún momento alguien le arrancó una gran parte. Se dice que pasó a manos de los centauros de Las Mil Agujas.\n\nEl resto se perdió en la costa al oeste de Costasur, desde donde iba a ser transportado por barco al Puerto de Menethil. Nunca llegó a su destino.\n\nLo único que te pido a cambio de esta información es que me lo traigas si lo encuentras.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1803] = {title = "Libro del conciliábulo", objective = "Recupera el escrito mohoso y el manuscrito andrajoso para Jorah Annison de Entrañas.", description = "¡Ah, veo que eres <un brujo/una bruja> con gustos similares a los míos! De hecho, la adquisición del libro del conciliábulo es una noble aspiración. ¿Sabías que una vez estuvo guardado entre los muros de Lordaeron? Pero lo destrozaron y arrancaron casi la mitad de sus páginas. ¿Quién podría estar detrás de un acto tan atroz?\n\nEsa mitad se perdió, aunque algunos rumores apuntan a que cayó en manos de los centauros de Las Mil Agujas.\n\nEl resto del texto debía ser conducido a Forjaz pero se perdió por el camino en la costa occidental de Costasur.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1805] = {title = "Libro del conciliábulo", objective = "Lleva el tomo restaurado y las 3 varas de mediación a Strahad Farsan a Trinquete.", description = "Es uno de los textos más interesantes que he estado buscando en estos últimos años. La selección que tengo aquí es bastante limitada, la mayoría son libros de geografía, y ya los he leído todos. Espero que Strahad me envíe una copia de ese libro cuando tenga ocasión de hacerlo.\n\nHablando de él, me envió noticias cuando tú estabas ausente. Para completar tu misión, debes conseguir tres varas de mediación.\n\nDado que me has dado la oportunidad de mirar este texto, voy a compartir un secreto contigo. Podrás encontrar las varas en los orcos del clan Faucedraco de Los Humedales.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1818] = {title = "Habla con Dillinger", objective = "Habla con el Guardia de la Muerte Dillinger en Rémol.", description = "Me han dicho que el Guardia de la Muerte Dillinger tiene un trabajo para alguien como tú. Si quieres probar tu valor para las fuerzas de la Dama Oscura, informa inmediatamente a Dillinger.\n\nEl puesto del Guardia de la Muerte Dillinger está en el extremo occidental de Rémol, junto al cementerio.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1821] = {title = "Reliquias Agamand", objective = "Lleva a Coleman Farthing el hacha de la familia Agamand, la espada de la familia Agamand, la maza de la familia Agamand y la daga de la familia Agamand.", description = "Los miembros de la familia Agamand fueron mis patrones en vida, ¡y también fueron la causa de mi muerte! ¡Qué apropiado que los Agamand sean ahora unos esbirros insignificantes del Rey Exánime!\n\nMe gustaría tener los últimos vestigios de su honor. Ve a la cripta de la familia y róbales sus reliquias familiares: una espada, un hacha, una daga y una maza. ¡Tráemelos!\n\nLa Cripta de la Familia Agamand está en el extremo norte de los Molinos de Agamand, protegida por la Plaga y por los Agamand muertos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1823] = {title = "Habla con Ruga", objective = "Habla con Ruga Tótem de Ira.", description = "Eres <un guerrero/una guerrera> de fama y talento. ¿Estás <preparado/preparada> para la prueba de Ruga Tótem de Ira? Si lo estás, encontrarás a Ruga en Campamento Taurajo, en Los Baldíos.\n\nEstá esperando a todo guerrero que responda a su llamada.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1824] = {title = "Prueba en Tierra de Gigantes", objective = "Lleva 5 antenas agitadas a Ruga Tótem de Ira de Campamento Taurajo.", description = "Para superar la prueba debes viajar hacia el Sur, hasta Tierra de Gigantes. Allí encontrarás gran cantidad de criaturas reptantes, insectos. Son nuevas en Los Baldíos y no me gusta lo que presagian.\n\nTráeme sus antenas cuando aún sigan agitándose y no pierdas tiempo, <nombre>, o las antenas dejarán de agitarse. Tráeme las antenas en el tiempo previsto y superarás la prueba.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBastión de Ruga"}
MultiLanguageQuestData['mx'][1825] = {title = "Habla con Thun'grim", objective = "Habla con Thun'grim Vistafuego en Los Baldíos.", description = "Thun'grim Vistafuego, un afamado herrero orco, ha oído hablar de tus hazañas y del valor mostrado a la Horda. Le gustaría hacerte una armadura, te conviene ir a hablar con él inmediatamente.\n\nThun'grim está acampado al este de El Cruce, en Los Baldíos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1838] = {title = "Armadura brutal", objective = "Lleva 15 lingotes de hierro humeantes, 10 azuritas en polvo, 10 barras de hierro y un vial de flogisto a Thun'grim Vistafuego.", description = "He oído hablar de tu fuerza y valor y me gustaría hacerte una armadura, una compañera que te ayudará en tus nuevas hazañas.\n\nPero la elaboración de la armadura será una auténtica misión, <nombre>. Necesitaré tu ayuda y la de otros herreros de la Horda.\n\nToma, coge este pergamino. He pasado muchas noches luchando con mis ojos casi ciegos, escribiendo lo que necesito para la armadura. Tráeme los objetos que aparecen en el pergamino y crearé la primera pieza de la armadura.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1841] = {title = "Velora Noctis y las musleras brutal", objective = "Habla con Velora Noctis en Entrañas.", description = "Se dice que, antes de su muerte, Velora Noctis era una de las mejores forjadoras de armaduras de Lordaeron. La muerte, al parecer, no ha menguado su talento. Habla con Velora, te hará tus musleras Brutal.\n\nVelora comercia en Entrañas de Lordaeron, en el Barrio del Comercio.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1842] = {title = "Pezuñas de sátiro", objective = "Lleva 7 pezuñas de sátiro sin rajar a Ula'elek de Poblado Sen'jin en Durotar.", description = "Puedo hacerte un par de guanteletes brutales que tendrán una enorme fuerza mágica. Pero antes debes reunir esa magia y traérmela.\n\nLos sátiros habitan en la parte noreste de Vallefresno por el poder del bosque. Se alimentan de su pureza, corrompiéndola y exprimiéndola. Puedo decirte cuáles son los sátiros que extraen la mayor parte de la magia de Vallefresno con sus pezuñas hinchadas y unguladas.\n\nEsas pezuñas albergan un poder enorme. Las necesitaremos para elaborar tus guanteletes.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1844] = {title = "Cuerno de quimera", objective = "Lleva un cuerno galvanizado a Orm Pezuña Pétrea de Cima del Trueno.", description = "Te haré el yelmo, pero debes demostrar que lo mereces.\n\nEscondida en el límite suroeste de la Sierra Espolón encontrarás La Vega Carbonizada. Fue un día un auténtico vergel, pero hoy está desolada y reducida a cenizas y las criaturas que quedaron allí están locas de terror y desesperación.\n\nAllí es a donde te envío, <nombre>.\n\nDebes ir a La Vega Carbonizada y encontrar una matriarca quimera. Mátala, libérala de su miseria y tráeme su cuerno galvanizado como prueba. Si lo haces te haré el yelmo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1846] = {title = "Tibias de Faucedraco", objective = "Lleva 8 tibias de Faucedraco robustas a Velora Noctis de Entrañas.", description = "Para elaborar las musleras Brutal necesito una llave de tibias robustas. Los orcos Faucedraco de Los Humedales tienen unas tibias perfectas, muy resistentes. Las necesito.\n\nDeben ser robustas. Asegúrate de probar las tibias que recojas. Si puedes romperlas con las manos no serán lo bastante robustas para trabajar con ellas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1858] = {title = "Mano Destrozada", objective = "Roba la llave de Tazan, abre su cartera y llévale el contenido a Therzok al Circo de las Sombras, en Orgrimmar.", description = "Tú te encargas de abrirla, luego tráeme el contenido. La cerradura es complicada, así que lo más fácil será que consigas la llave.\n\nComo Tazan no la llevaba encima, debemos suponer que se la dio a alguien... Ah, claro. Tenía un secretario, un borracho que se llama Gamon. Lo más seguro es que esté en la taberna; intenta quitarle la llave.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nHoja de astucia"}
MultiLanguageQuestData['mx'][1859] = {title = "Therzok", objective = "Ve a Orgrimmar, al Circo de las Sombras, y habla con Therzok.", description = "Baja la voz, <nombre>. Sé quién eres. Tenía tu descripción y te esperaba.\n\nPor lo que he oído de ti, te manejas bien en combate y no te opones a alguna incursioncilla que otra de vez en cuando.\n\n¿Me equivoco?\n\nEs lo mismo. Tienes que ir a Orgrimmar a ver a Therzok. Tiene una oferta que hacerte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1860] = {title = "Habla con Jennea", objective = "Habla con Jennea Cañón en Ventormenta.", description = "Los magos tenemos una tarea por hacer, y es vital para la seguridad de Ventormenta y del Bosque de Elwynn.\n\nJennea Cañón sabe los detalles. Estudia en el Sagrario del Mago, en el Barrio de los Magos de Ventormenta. Deberías ir a verla lo antes posible.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1861] = {title = "Lago Espejo", objective = "Lleva una muestra del Lago Espejo a Jennea Cañón en Ventormenta.", description = "Este mundo ha padecido enormes luchas místicas, que desbordaron corrientes de magia de canales antes estables. Nos esforzamos en determinar los efectos que han causado esos cambios y hay quien teme lo peor.\n\nPero ya te hablaré de todo ello más adelante. Por ahora, necesitamos que reúnas información.\n\nToma, coge esta botella. Ve a la base de la cascada del Lago Espejo, al suroeste de las puertas de Ventormenta y recoge una muestra de agua. Vuelve a verme para que pueda comprobar si tiene contaminación mágica.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Bastón LeyPodrás elegir una de estas recompensas:\n\nOrbe Ley\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][1878] = {title = "Cazador de faltriqueras de agua", objective = "¿Ya has vuelto, <nombre>? Si tienes cinco faltriqueras más de agua te puedo dar ya mismo tu recompensa.", description = nil, progress = "¿Ya has vuelto, <nombre>? Si tienes cinco faltriqueras más de agua te puedo dar ya mismo tu recompensa.", completion = "Excelente, ¡cuantas más faltriqueras de agua consigamos, más nos alejaremos del desastre! Consigue tantas como puedas y te daré una recompensa por cada 5 faltriqueras de agua que me traigas.", rewards = "Recibirás:\n\nBotiquín de la compañía de aguas de Gadgetzan"}
MultiLanguageQuestData['mx'][1879] = {title = "Habla con Bink", objective = "Habla con Bink en Forjaz.", description = "¡<nombre>! Bink, mi colega gnomo de Forjaz, ha enviado un mensaje. ¡Tiene una tarea que hacer y solo confía en un mago para hacerlo! ¿Serás tú ese mago, <nombre>?\n\nSi es así, ve a hablar con Bink. La encontrarás en la Sala de los Misterios en La Sala Mística de Forjaz.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1880] = {title = "Trastónitor maguitronic", objective = "Llévale a Bink su trastónitor maguitrónic.", description = "¡Los magos hacemos mucho más que menear los dedos y sacar chispas! ¡Controlamos la magia, la estructura básica de nuestro mundo! Exige mucho cuidado, resolución y conocimiento... sí, ¡mucho conocimiento!\n\nUno de mis instrumentos, el trastónitor maguitrónic recoge y almacena ese conocimiento en grandes cantidades, ¡pero lo he perdido! Cuando dejamos nuestro hogar, Gnomeregan, lo dejé en un cofre en una de las cabañas a las puertas de la ciudad. ¡Y ahora el lugar está plagado de gnomos leprosos!\n\n¡Por favor, <nombre>, recupera mi trastónitor!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Bastón ArcanoPodrás elegir una de estas recompensas:\n\nOrbe Arcano\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][1881] = {title = "Habla con Anastasia", objective = "Habla con Anastasia Hartwell.", description = "<nombre>, Anastasia Hartwell tiene una misión para alguien con tus aptitudes. Habla con ella en el Barrio de la Magia en Entrañas y prepárate para tu primera tarea como mago de los Renegados.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1882] = {title = "La Hacienda Balnir", objective = "Lleva las Bocas de dragón de Balnir a Anastasia Hartwell en el Barrio de los Magos de Entrañas.", description = "Las Tierras de la Peste del Este son una aberración. Ideadas por el Rey Exánime, propagan su magia a la tierra, corrompiendo y matando toda forma de vida. Aunque las fuerzas destructivas de la Peste tienen un cierto encanto, nosotros, los magos de los Renegados, creemos que es indomable y que debe ser reducida.\n\nPero antes de nada, debemos medir hasta qué punto se ha propagado en Tirisfal. Ve a la Hacienda Balnir en la parte oriental de Tirisfal. En el jardín encontrarás flores: Bocas de dragón. Recógelas y vuelve a verme.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Bastón ArcanoPodrás elegir una de estas recompensas:\n\nOrbe Arcano\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][1883] = {title = "Habla con Un'thuwa", objective = "Habla con Un'thuwa.", description = "Un'thuwa, mago tribal de Poblado Sen'jin, detecta una alteración en las corrientes mágicas de Durotar y está buscando ayuda. Habla con Un'thuwa y haz lo que puedas para ayudarle.\n\nHazlo y con el tiempo se te revelarán nuevos secretos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1884] = {title = "Montones de Ju-Ju", objective = "Destruye 4 montones de Juju y vuelve con Un'thuwa en Poblado Sen'jin.", description = "El brujo Zalazane de las Islas del Eco ha interrumpido el flujo normal de la magia en Durotar. Lo hace a través de fetiches corruptos, montones de Juju, que ha colocado entre sus cabañas en la Isla del Eco principal.\n\nEstos montones corrompen nuestra naturaleza y dan poder a los brujos y a las criaturas infernales que merodean las zonas más oscuras del país.\n\nDebes destruir los montones de Juju, <nombre>, antes de que el flujo de magia quede alterado para siempre.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Bastón LeyPodrás elegir una de estas recompensas:\n\nOrbe Ley\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][1885] = {title = "Mennet Carkad", objective = "Habla con Mennet Carkad en el Barrio de los Pícaros de Entrañas.", description = "¿<nombre>? No eres exactamente como esperaba, teniendo en cuenta que el mismísimo Carkad se ha interesado por ti. Si bien es cierto que la primera impresión no siempre es la que cuenta, ¿no crees?\n\nEn cualquier caso, deberías ir a verlo tan pronto como puedas. No te gustaría saber lo que les ocurrió a los que hicieron caso omiso a su llamada.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1886] = {title = "Los mortacechadores", objective = "Consigue la carta de presentación de Astor y devuélvesela a Mennet Carkad, en el Barrio de los Pícaros.", description = "Si quieres formar parte de los mortacechadores, la guardia de élite de Lord Varimathras, tendrás que demostrar tu valía.\n\nNo quiero mentirte, <nombre>, esta misión puede suponer tu muerte.\n\nYo tengo otras cosas que requieren de mi atención. Necesito los efectos personales de Astor Hadren, un mensajero que viaja entre el Bosque de Argénteos y Entrañas. Te dejo a tu elección el método que debes utilizar.\n\nCuanto menos sepas sobre la naturaleza de su negocio, mejor para ti. Si realizas con éxito está misión, te contaré más.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1918] = {title = "El elemento contaminado", objective = "Llévale el globo de agua contaminada a Mastok Bufido en el Puesto del Hachazo, Vallefresno.", description = "El elemental caído ha producido un globo de agua de brillo intenso. El contenido del globo es, cuando menos, repulsivo. No me parece descabellado suponer que lo que contaminara el Lago Mystral se encontrase casi con toda seguridad en el agua del globo.\n\nNo es fácil saber quién podría estar interesado en semejante hallazgo; quizás Mastok Bufido del Puesto del Hachazo, podría tener una idea.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1919] = {title = "Preséntate ante Jennea", objective = "Habla con Jennea Cañón en Ventormenta.", description = "Tu conocimiento sobre esta disciplina no deja de crecer, joven <nombre>. ¿Estás <listo/lista> para comenzar las auténticas lecciones? ¿Estás <listo/lista> para ocupar tu lugar en la guerra secreta en la que estamos embarcados?\n\nSi es así, ve a hablar con Jennea Cañón, en el Sagrario del Mago, en el Barrio de los Magos de Ventormenta. Tiene una tarea para ti y esa tarea te abrirá la primera ventana al mundo de lo invisible.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1920] = {title = "Investiga lo que pasa en El Ermitaño Taciturno", objective = "Detrás de Jennea Cañón encontrarás un Canto de manifestación y un cofre de arcas de contención. Cógelos y lleva 3 arcas de contención llenas a Jennea, en el Sagrario del Mago.", description = "Han llegado informes de una alteración en la taberna El Ermitaño Taciturno del Barrio de los Magos. Criaturas invisibles y extrañas vagan por la taberna y temo que se haya formado una falla de maná.\n\nQuiero que investigues la taberna y que captures a esas criaturas. Utiliza el Canto de manifestación en la taberna para hacer visibles a las criaturas, cuando las tengas dominadas utiliza un arca de contención para capturarlas. Cuando tengas bastantes vuelve a verme trayendo contigo las arcas llenas y vacías y el Canto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1939] = {title = "Sumo Hechicero Andromath", objective = "Habla con el sumo hechicero Andromath.", description = "El sumo hechicero Andromath quiere hablar contigo, <nombre>. Está en la parte superior del Sagrario del Mago, en el Barrio de los Magos de Ventormenta.\n\nDeberías ir a hablar con él, Andromath es uno de los magos más poderosos fuera de Dalaran. Su consejo es, sin duda, muy valioso.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1943] = {title = "Habla con Deino", objective = "Habla con Deino.", description = "Deino, la maga trol, necesita tu ayuda, <nombre>. Vive en Orgrimmar, en la Cabaña de Brezo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1944] = {title = "Aguas de Xavian", objective = "Lleva la muestra de agua de Xavian a Deino en Orgrimmar.", description = "La legendaria ciudad de Xavian se encuentra escondida en las profundidades de la parte oriental de Vallefresno. Los eruditos conocen historias de su antigua sabiduría, se dice, por ejemplo, que las aguas de Xavian albergan grandes poderes mágicos.\n\nMe gustaría tener una muestra de esas aguas, tomada de las propias fuentes.\n\nToma esta botella y ve a Xavian. Recoge agua del fondo de su cascada más alta y vuelve a verme. Ten mucho cuidado cuando atravieses la antigua ciudad, los sátiros protegen las ruinas y no les gusta ver a magos entrometiéndose en sus asuntos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1945] = {title = "Hermanas sonrientes", objective = "Lleva 12 cabellos de hermana sonriente a Kil'hala en El Cruce.", description = "A cambio de tus servicios he dispuesto la creación de tus nuevas túnicas, siempre que puedas reunir los materiales necesarios...\n\nPara hacerlo debes volver a Vallefresno y conseguir mechones de cabello de las hermanas sonrientes, las dríades que se reúnen junto al Refugio de la Algaba.\n\nCuando tengas su cabello llévaselo a Kil'hala, un sastre trol de El Cruce en Los Baldíos. Te estará esperando y elaborará tu túnica.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1947] = {title = "Viaje al pantano", objective = "Habla con Tabetha.", description = "Ha llegado el momento de que obtengas tu varita de mago. Para comenzar esta búsqueda habla con Tabetha, una ermitaña humana que habita en el Marjal Revolcafango. Encontrarás su choza en las profundidades del marjal, al oeste de Theramore.\n\nHabla con ella, su saber es enorme. Encontrarás su casucha al oeste de Theramore y al norte de las Ruinas Quebrantarrocas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1948] = {title = "Objetos de poder", objective = "Lleva 1 jade y la zarza electrificada a Tabetha en el Marjal Revolcafango.", description = "Crear la varita de un mago no es fácil. Se necesitan sustancias extrañas y debe hacerse un recipiente que pueda almacenar grandes cantidades de energía mágica. Debes reunir estas cosas y traérmelas.\n\nHe escrito en este papiro todo lo que necesitas e instrucciones para conseguirlo. Tráeme exactamente lo que está en la lista y sigue las indicaciones al pie de la letra, si no la varita podría hacer cosas... no muy buenas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1949] = {title = "Secretos escondidos", objective = "Habla con Magus Tirth en El Desierto de Sal.", description = "Para hacer tu varita, necesito leer unos pasajes clave de un libro determinado. El libro se llama Rituales de poder, y fue escrito por Magus Tirth.\n\nNo tengo ninguna copia del libro y ninguna de las grandes bibliotecas del mundo lo tiene. Debes hablar con Tirth y conseguir que te lo dé.\n\nBuena suerte. Tirth era un gran mago y erudito, pero ahora se pasa el día en las carreras de los goblins y de los gnomos en El Desierto de Sal, bebiendo y haciendo apuestas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1950] = {title = "Santo y seña", objective = "Averigua la frase para la caja fuerte de Tirth y regresa con Tirth.", description = "¡Puedo ayudarte con el libro, pero antes tienes que ayudarme!\n\nEl tomo que buscas está en mi caja fuerte cerrada mágicamente. Para abrirla hay que pronunciar una determinada frase, ¡y no puedo recordarla! Normalmente mi asistente me ayuda a recordar esas cosas, pero no hay forma de encontrarlo.\n\nSi quieres mi libro debes encontrar a mi aprendiz. Pregunta por la pista de carreras, si tienes suerte lo habrá visto alguien. ¡Tráelo de vuelta aquí o consigue que te diga mi frase mágica para poder abrir la caja!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1951] = {title = "Rituales de poder", objective = "Lleva el libro Rituales de poder a Tabetha en el Marjal Revolcafango.", description = "Umm... ahora que lo pienso... ¡no tengo el libro! Verás, tenía algunas deudas de juego y para pagarlas vendí la última copia de Rituales de poder a un miembro del clero...\n\nUn miembro de la Hermandad Escarlata. ¡Debe haberlo llevado a su biblioteca en el Monasterio Escarlata de los Claros de Tirisfal!\n\nSi quieres el libro, tendrás que ir al monasterio a buscarlo. Y perdona por todo este lío... últimamente no soy yo mismo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1953] = {title = "Regresa a la Marisma", objective = "Habla con Tabetha.", description = "<nombre>, es hora de que vayas a hablar con Tabetha... la ermitaña del Marjal Revolcafango. Te instruirá sobre la creación de un instrumento muy poderoso para un mago.\n\nLa choza de Tabetha está en las profundidades del Marjal Revolcafango, al oeste de Theramore.", progress = nil, completion = "Ah, sí. ¿Has venido buscando un orbe o un bastón, &lt;nombre&gt;? Muy bien. Te ayudaré a construirlo. \n\nPero te lo advierto: el proceso es peligroso y puede significar tu muerte. \n\nO la mía. En cualquier caso, la muerte de alguien... \n\nPero vamos a esperar que sea la muerte de otro, ¿eh?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1954] = {title = "El orbe infernal", objective = "Lleva un orbe infernal a Tabetha en el Marjal Revolcafango.", description = "El primer paso es adquirir un orbe con poder. Los brujos del Filo Ardiente tienen orbes fantásticos, de gran calidad... ¡lo malo es que tienen atados demonios en su interior! Pero podemos arreglarlo, sí, podemos.\n\nVe a Desolace y hazte con un orbe infernal de un invocador Filo Ardiente. Encontrarás invocadores en el Aquelarre Mannoroc.\n\nCuando tengas el orbe, vuelve a verme.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1959] = {title = "Preséntate ante Anastasia", objective = "Habla con Anastasia Hartwell.", description = "Los magos de Entrañas han notado una perturbación mágica dentro de la ciudad y han dado la orden a toda la Horda de investigar el suceso.\n\nAnastasia Hartwell te puede contar más. Habla con ella en el Barrio de la Magia de Entrañas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1960] = {title = "Investiga la tienda de alquimia", objective = "Detrás de Anastasia Hartwell encontrarás un Canto de manifestación y un cofre de arcas de contención. Cógelos y lleva 3 arcas de contención llenas, el cofre de arcas de contención y el Canto de manifestación a Anastasia en Entrañas.", description = "La tienda de alquimia de Algernon, en El Apothecarium, es el centro de una extraña alteración. Criaturas invisibles, hechas tan solo de magia, vagan por la tienda... ¡debe haber una razón y debemos descubrirla!\n\nInvestiga la alteración y captura a esas criaturas. Coge el cofre de arcas y el pergamino que hay detrás de mí. Utiliza el pergamino en la tienda para hacer visibles a las criaturas, cuando las hayas dominado con tus hechizos, arroja un arca para capturarlas. Vuelve con las arcas llenas, el cofre y el canto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1961] = {title = "Recolección de materiales", objective = "Consigue 10 trozos de paño de lino y 6 gemas de maná de Dalaran para Josef Gregorian.", description = "Ha llegado la hora de que tengas tus primeras togas mágicas, <nombre>. Son un símbolo de tu condición y un testimonio de tu valor.\n\nPara obtenerlas, deberás recoger gemas de maná de los magos de Dalaran, en los Argénteos. Sus creencias son similares a las nuestras, por lo que matarlos no es nada placentero, pero bueno, si no son capaces de hacernos frente, la verdad que merecen morir.\n\nTrae las gemas y un poco de lino para Josef Gregorian en la tienda de sastrería del Barrio de la Magia.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1963] = {title = "Mano Destrozada", objective = "Mata a Tazan y llévale su cartera a Therzok al Circo de las Sombras, en Orgrimmar.", description = "El Jefe de Guerra es demasiado cauteloso a la hora de usar el poder de la Horda. En el pasado fuimos conquistadores y debemos volver a serlo. Mano Destrozada se encargará de eso.\n\nAtacamos al enemigo expuesto desde la sombra, para reducir sus filas en secreto. Hay algo que debes hacer para probar tu valía.\n\nEl trol Tazan, que comercia con los piratas cerca de Trinquete, tiene información que me interesa. Mátalo y tráeme su cartera.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1998] = {title = "Fenwick Thatros", objective = "Mata a Fenwick Thatros y llévale su cabeza a Mennet Carkad, que está en el Barrio de los Pícaros de Entrañas.", description = "Lord Varimathras me ha enviado una misiva sobre una amenaza para los no-muertos que debe ser eliminada de inmediato. Su nombre es Fenwick Thatros, el que Lord Varimathras cree que es el líder de los no-muertos que se han asentado en el Bosque de Argénteos.\n\nTu nombre me vino a la mente rápidamente, <nombre>. Confío en tus facultades y sé que podrás realizar esta misión a la perfección.\n\nSegún los mortacechadores del Bosque de Argénteos, puedes encontrar a Thatros cerca del embarcadero destartalado de Lordamere.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][1999] = {title = "Herramientas de comercio", objective = "Encuentra el informe de estado de Dalaran y devuélveselo a Mennet Carkad, que está en el Barrio de los Pícaros de Entrañas.", description = "Uno de nuestros prisioneros ha confesado que los zahorís del Kirin Tor en el Molino Ámbar esconden importantes documentos relativos al estado actual de Dalaran. Lord Varimathras ha encomendado a los mortacechadores la tarea de recuperarlos.\n\nAhora esta tarea te corresponde a ti, <nombre>. Sin embargo, necesitarás algún equipamiento y saber forzar cerraduras. Habla con Estelle Gendry, nuestra modista, y pídele un juego de herramientas antes de partir.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2038] = {title = "Suministros de Bingles", objective = "Localiza las herramientas de Bingles y devuélveselas:\n\nllave inglesa, destornillador, martillo y cartucho de explosivos.", description = "Por si no fuera bastante haberme estrellado en Loch Modan, me atacaron unos troggs de una isla cercana y me robaron las herramientas y mis cartuchos de explosivos Pimpampum. ¡Sin girocóptero y sin explosivos no hay nada que hacer!\n\nTráeme mis herramientas y mis explosivos, <nombre>. ¡Por Gnomeregan!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Guadaña de MonteVarita mecánicaPistola de rayos multiusos gnómicaRecibirás:\n\nGuantes voladores de Bingles"}
MultiLanguageQuestData['mx'][2039] = {title = "Encuentra a Bingles", objective = "Encuentra a Bingles Pimpampum en Loch Modan.", description = "¡Hemos perdido contacto con Bingles! Fue a una misión de reconocimiento a Gnomeregan hace una semana y no ha vuelto a dar señales de vida. Seguro que ha saltado por los aires.\n\nLa última vez que se le vio, volaba sobre Loch Modan. Quizás tú puedas enterarte de qué ha pasado, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2040] = {title = "Asalto subterráneo", objective = "Recupera la Dentrituradora goblin de Las Minas de la Muerte y devuélveselo a Shoni la Shilenshiosha, en Ventormenta.", description = "¡Esos malditos troggs han tomado Gnomeregan! La situación es grave, pero quizás puedas ayudar, <nombre>.\n\nEn las profundidades de Las Minas de la Muerte hay una trituradora goblin operativa. Encuentra la trituradora y trae su batería intacta. Con la batería de la trituradora, podemos dar a nuestras excavadoras gyroagujereamáticas la energía necesaria para atravesar los rocosos límites subterráneos de Gnomeregan, ¡y nos abrirán el camino para el asalto gnomo!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guanteletes polaresVarita de dientes de sableRecibirás:\n\n"}
MultiLanguageQuestData['mx'][2041] = {title = "Habla con Shoni", objective = "Habla con Shoni la Shilenshiosha en el Distrito de los Enanos en Ventormenta.", description = "A lo mejor... A lo mejor puedes ayudarnos en la batalla por Gnomeregan.\n\nVe a Ventormenta a hablar con Shoni la Shilenshiosha, la jefa de trabajos subterráneos. Necesita un cable con las excavadoras gyroagujereamáticas.\n\nLo más seguro es que esté con los enanos en Ventormenta.\n\nSuerte, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2098] = {title = "La búsqueda de Gyromast", objective = "Encuentra y devuelve los tres fragmentos de la llave de Gelkak Gyromast.", description = "La vida del pirata no es fácil, te lo digo yo. ¡No es todo abordajes y ron! También hay desgracia... Mi barco se hundió cerca de la costa por culpa de esos malditos trillanodontes.\n\n¡Necesito tener conmigo a mi contramaestre! ¡Cuanto antes!\n\nCuando alcancé la costa se me cayó la llave de mi segundo de a bordo en las rocas y me la robaron esas bestias de Costa Oscura. Por el rabillo del ojo pude ver reptadores furiosos, feroces zancudos de bosque y múrlocs rebuscando entre los restos del naufragio.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2118] = {title = "Tierras apestadas", objective = "Captura un oso cardo rabioso vivo y llévaselo a Tharnariun. \n\nSi no consigues capturar un oso cardo rabioso y pierdes la trampa, pídele otra a Tharnariun Espinarbolado.", description = "Por Costa Oscura se extiende una enfermedad que se hace con la mente y el cuerpo de todo lo que toca.\n\nLos osos cardo han sido los más afectados por esta plaga. Eran nobles animales que se han convertido en rabiosos objetos de destrucción. Creo que yo podría tener una cura para este mal.\n\nLleva esta trampa al bosque y colócala en el suelo. Cualquier oso cardo rabioso que cruce la luz será manso por un breve período de tiempo. Y cuando esto ocurra, te seguirá. Guía uno hasta aquí, <nombre>.", progress = nil, completion = "Our work has only just begun, &lt;nombre&gt;. Are you prepared for your next task?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2139] = {title = "La esperanza de Tharnariun", objective = "Encuentra a la madre del cubil y mátala.", description = "El precio por la supervivencia de nuestra gente y nuestras tierras es muy alto, <nombre>.\n\nHas derramado la sangre de muchos siervos de la naturaleza. Has derribado a muchos animales enfermos. Los habitantes de Auberdine están en deuda contigo, pues, aunque sea solo por un tiempo, has mitigado el dolor del bosque...\n\nTengo una última tarea para ti. Pero te advierto, tendrás que volver a matar. Tengo la esperanza de que esta sea la última vez que recurro a ti, <nombre>.\n\nAl noreste hay una cueva, cerca de Bashal'Aran. En ella reside la madre del cubil. Mátala.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes siempreverdeManteo de maderaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][2158] = {title = "Descanso y relajación", objective = "Habla con el tabernero Farley de la Posada Orgullo de León.", description = "Todos los aventureros deben descansar cuando les invade el agotamiento, ¡y no hay mejor lugar para descansar que la Posada Orgullo de León!\n\nMi mejor amigo, el tabernero Farley, lleva la Posada Orgullo de León. Si le dices que te envío yo, puede que te haga un descuento en la comida y la bebida.\n\nPara encontrar la Posada Orgullo de León, viaja al sur por el camino que sale de aquí, ¡no tiene pérdida!", progress = nil, completion = "¡Descanso y relax para quien no puede más! ¡Ese es nuestro lema! Por favor, toma asiento cerca del fuego y da un respiro a tus cansados huesos. \n\n¿Te gustaría probar una selección de nuestra excelente comida y bebida?", rewards = "Brazal de orgullo del leónGuantes de taberneroBrazal de hierro de VilladoradaRecibirás:\n\nAgua de manantial refrescanteCalabaza pequeñaCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][2159] = {title = "Paquete de Dolanaar", objective = "Llévale el paquete de Dolanaar al tabernero Keldamyr.", description = "Saludos, joven <clase>. ¿Me podrías prestar tu ayuda? Tengo un paquete de hierbas que debo entregar en la ciudad de Dolanaar pero todavía tengo asuntos pendientes con los druidas de Cañada Umbría y no puedo irme.\n\n¿Puedes entregar este paquete por mí? Su destinatario es el tabernero Keldamyr de la posada de Dolanaar, que se encuentra un poco más adelante en dirección sur.", progress = "¿Cómo puedo ayudarte, joven? ¿Vienes para alojarte en la posada? ¿Necesitas una piedra de hogar?", completion = "Ah sí, el paquete de hierbas de Cañada Umbría. Es una lástima que no lo haya podido traer el propio Porthannius pues él y yo tenemos mucho de qué hablar. No obstante, me alegro de hayas venido a traerme las hierbas. \n\nYa que estás aquí, aprovecha para descansar. Los héroes han de velar por su fuerza y ánimo, y buscar descanso y solaz cuando sea necesario. Si no se proporciona paz al cuerpo y a la mente, el fracaso es inevitable. \n\nAsí pues... descansa.", rewards = "Podrás elegir una de estas recompensas:\n\nAgua de manantial refrescanteQueso azul de Darnassus\n\nTambién recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][2160] = {title = "Suministros para Tannok", objective = "Lleva a Kharanos el cajón de suministros del mesón y entrégaselo a Tannok Martilloescarcha.", description = "¡Eh! Tienes pinta de ser de corazón aventurero. Si vas a arriesgarte a atravesar el paso, ¿crees que podrías llevar un paquete a la posada de Kharanos?\n\nPorque pensabas hacer un alto en la posada, ¿no? Sí, seguro, si consigues cruzar el paso, necesitarás descansar un poco.\n\nY como vas a pasar por allí, no te costará nada entregar esto a Tannok Martilloescarcha, el ayudante del tabernero. Yo no puedo cruzar el paso ¡y pasarán días hasta que llegue una escolta de montaraces!", progress = "¡Eh, sé bienvenido! Venga, siéntate junto al fuego y entra en calor con una jarra de cerveza.", completion = "¡Ah, por fin! ¡Los suministros! Empezaba a preocuparme. Hemos tenido pocas noticias de Yunquemar desde que los troggs se hicieron con el paso. \n\nGracias por traerme esto, &lt;nombre&gt;. Te lo ruego, ponte cómodo. Debes de estar cansado del viaje.", rewards = "Brazal MartilloescarchaCinturón de KharanosBotas aplastanievePodrás elegir una de estas recompensas:\n\nCecina duraAgua de manantial refrescante\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][2161] = {title = "Un cargamento de peón", objective = "Lleva la carga de Ukor al tabernero Grosk a Cerrotajo.", description = "Perdón... ¿Puedes ayudarme?\n\nTengo un montón de comida aquí. ¡Y por el camino he tenido que afrontar escórpidos y arañas y cosas peores! Traje la comida al Valle de los Retos porque pensaba que la necesitarían y quería ayudar. ¡Pero no necesitan comida! Y ahora tengo que llevármela de vuelta a Cerrotajo y tengo miedo de las bestias que pueda encontrarme por el camino...\n\n¿Podrías llevarla tú por mí? Yo soy una criatura insignificante y tú, sin embargo, eres un ser aguerrido. ¡No temes a nada!\n\nLlévaselo al tabernero Grosk de la posada de Cerrotajo. ¡Gracias!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nMendrugo de pan duroAgua de manantial refrescante\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][2178] = {title = "Guiso de zancudo", objective = "Llévale 5 piezas de carne de zancudo a Alanndarian Arrullanoche a Auberdine.", description = "¿Hueles ese delicioso aroma? Es mi receta secreta, <nombre>: guiso de zancudo recién hecho. ¡Es una delicia!\n\nQuizás te interese aprender la receta...\n\nPues para que te la enseñe, tendrás que probarme que eres capaz de dominar a las bestias.\n\nNo espero que salgas, domestiques a un zancudo y vuelvas cabalgando en él, pero si consigues matar a unos pocos y traerme algo de su suculenta carne, me dejaría convencer para compartir mi receta.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nReceta: estofado de zancudoEstofado de zancudo"}
MultiLanguageQuestData['mx'][2198] = {title = "El collar hecho añicos", objective = "Busca al creador del collar hecho añicos y descubre para qué sirve.", description = "Has encontrado un collar deslustroso, que todavía deja ver el minucioso y mágico trabajo de artesanía del que ha sido fruto. El collar está dañado y parece que faltan tres gemas. En la parte de atrás del collar hay una inscripción apenas visible con el sello de la ciudad de Forjaz. Debajo hay tres pequeñas iniciales grabadas. \"TdK\".\n\nSi este collar significa algo, tendrás que descubrir de qué se trata. El sello y las iniciales serán un buen punto de partida...", progress = "¡Te has equivocado de gnomo, amigo! ¡Yo nunca he estado allí! ¡No puedes probar nada!\n\nEspera un momento... ¿quién eres? ¿Pero qué...? ¿Dónde encontraste este collar?", completion = "Sí... Yo soy el joyero que ha hecho el collar pero no soy de los que dan información a cambio de nada. La información se paga, amigo. Si quieres que te ayuda, primero has de ayudarme tú a MÍ.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2200] = {title = "El regreso a Uldaman", objective = "Busca pistas sobre el paradero del collar de Talvash en Uldaman. Dijo que un paladín muerto fue su último dueño.\n\nObjeto provisto: \n", description = "Un competidor hizo correr el rumor de que mi collar tenía una maldición que cayó sobre el paladín. Evidentemente, nadie quiere comprar joyas malditas.\n\nHagamos un trato, <nombre>: tráeme las gemas y yo arreglaré el collar, ¡siempre que hagas publicidad de que mis joyas no están malditas!\n\nBusca pistas en Uldaman; puede que encuentres el cadáver del paladín, su último dueño conocido. Usa esto cuando encuentres las gemas; así podrás comunicarte conmigo aquí en Forjaz.", progress = nil, completion = "El diario revela que el paladín consiguió localizar las 3 gemas del collar: \n\nlos enanos Forjatiniebla tenían el rubí en zona segura durante su lucha contra los troggs por el control de Uldaman. \n\nEstos, a su vez, guardaban el topacio en una urna situada cerca de algunos habitantes de Uldaman poco comunes. \n\nY el ancestro trogg se quedó el zafiro para sí.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2204] = {title = "Restaurar el collar", objective = "Obtén una fuente de energía del ensamblaje más poderoso que encuentres en Uldaman, y entrégasela a Talvash del Kissel en Forjaz.", description = "Vas a tener que darle \"vidilla\" a ese collar y Uldaman probablemente es el mejor lugar para conseguir lo que necesitas. Supongo que hay muchos ensamblajes por allí, ¿no? Bien, pues elige el más grande de todos los ensamblajes que encuentres y extrae su fuente de energía. Seguro que podré insertar esa fuente en el interior del collar.\n\nSin la fuente de energía no es posible restaurar el collar. Regresa a Forjaz cuando la tengas y podremos arreglarlo para ti.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2205] = {title = "Busca el IV:7", objective = "Entrega el paquete de Keryn Sylvius al maestro Mathias Shaw que está en el Cuartel de Ventormenta.", description = "¿La insignia? Oh, no es nada, pescadito. Al menos nada que tú puedas arreglar. Por la pinta que tienes, diría que Mathias, más que pensar que eres <un pícaro/una pícara>, te tomaría por <el chico/la chica> de los recados del quesero. Además, el trabajo me fue asignado a mí y fui yo quien se comprometió a hacerlo.\n\nHablando de lo cual... lleva este paquete a Mathias. Quizás te dé un par de pequeñas tareas.\n\nEn marcha. \nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2240] = {title = "La cámara oculta", objective = "Lee el diario de Baelog, inspecciona la cámara oculta y ve a informar al prospector Pico Tormenta.", description = "Pasemos a la siguiente tarea.\n\nExiste una cámara secreta, la cámara de Khaz'mul, que hay que examinar. ¡El problema es que esta cámara se encuentra tras una enorme puerta cerrada con llave! Es una suerte que sepa cómo abrirla.\n\nLo explico todo en mi diario, que está sobre la mesa. Mi equipo y yo no podemos salir de aquí... así que tú, <nombre>, debes encontrar la cámara de Khaz'mul por nosotros.\n\nLee mi diario, examina la cámara y ve a informar al prospector Pico Tormenta de la Liga de Expedicionarios en Forjaz.", progress = nil, completion = "¿Has visto la cámara de Khaz'mul? ¡No puedo creerlo! Baelog estaba seguro de su existencia pero yo he de reconocer que tenía mis dudas. \n\nGracias, &lt;nombre&gt;. Con un poco de suerte, tu hallazgo incitará a nuestros líderes a seguir luchando por recuperar Uldaman. Y, si algún día vuelve a estar bajo el control de Forjaz, ¡los secretos de la cámara de Khaz'mul serán nuestros!", rewards = "Carga de enanoPodrás elegir una de estas recompensas:\n\nEstrella polar de la Liga de Expedicionarios\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][2241] = {title = "Cuando cae la manzana", objective = "Llévale la rosa de Jannok a Syurna, que está en Darnassus.", description = "Dicen que soy un \"amante furibundo\", aunque no sé muy bien a qué se refieren.\n\nEs cierto que pienso en todo momento en Syurna, que mi casa está repleta de retratos de ella, y que paso días enteros sin comer, beber o dormir lamentándome por el amor que podríamos haber tenido. ¿Acaso es algo malo?\n\n¡Y ella no quiere verme! ¡A MÍ! He intentado enviarle mensajes pero ya no habla con nadie que no sea un pícaro.\n\n¿Podrías llevarle tú esta flor? No olvides decirle que es de parte de Jannok.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2258] = {title = "Componentes de Tierras Inhóspitas", objective = "Llévale 5 mollejas de águila ratonera, 10 colmillos de coyote del risco y 5 fragmentos de elemental de roca a Jarkal Musgofusión en Kargath, en las Tierras Inhóspitas.", description = "<nombre>, no me vendría mal tu ayuda si te apetece echar una mano. Soy un alquimista de cierto renombre y necesitaría tu ayuda para conseguir unos componentes que se hallan en las Tierras Inhóspitas.\n\nMe hacen falta los siguientes objetos para reponer mis existencias: 5 mollejas de águila ratonera, 10 colmillos de coyote del risco y 5 fragmentos de elemental de roca. Como es lógico, puedes conseguirlos de los propios animalitos; si no eres del tipo luchador, llévate a unos amigos que lo sean.\n\nConsígueme esos objetos y acabarás con unas monedas más en el bolsillo. ¿Qué me dices? ¿Te hace?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2278] = {title = "Los discos de platino", objective = "Habla con el vigía de piedra y descubre qué conocimiento antiguo alberga. Cuando hayas adquirido el conocimiento que te ofrece, activa los Discos de Norgannon.", description = "En el centro de esta cámara del tesoro se encuentran cuatro discos de platino gigantes, cada uno de ellos adornado con sigilos de origen desconocido. Al tocarlos sientes un cosquilleo en la mano. Tras haber tocado los discos, se muestra ante ti un enorme vigía de piedra.\n\n\"Saludos. Soy un guardián del conocimiento. La síntesis de los Creadores de los terráneos se describe y almacena para este mundo en los Discos de Norgannon.\"\n\n¡Acabas de encontrar una fuente de conocimiento nunca antes descubierta por nadie!", progress = nil, completion = "Siguiendo las indicaciones del vigía de piedra, accedes de nuevo a los discos de Norgannon ahora que ya conoces la historia de los terráneos, los troggs y los enanos. Se oye un ligero que proviene del interior de los discos. Entonces, el vigía de piedra habla de nuevo: \n\n\"Los discos han sido sintetizados. Accede de nuevo a los discos de Norgannon para recibir una copia personal.\"", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2279] = {title = "Los discos de platino", objective = "Lleva la reproducción en miniatura de los Discos de Norgannon a la Liga de Expedicionarios de Forjaz.", description = "Al tocar los Discos de Norgannon de nuevo, sientes un cosquilleo en la mano. En esta ocasión, sin embargo, se oye un extraño ruido proveniente de su interior.\n\nSientes cómo tu mochila de repente es mucho más pesada que antes. ¡En su interior descubres una reproducción en miniatura de los discos!\n\nSin duda, un objeto de este tipo tendría un valor incalculable para alguien interesado en la historia antigua de Azeroth. Piensas en los miembros de la Liga de Expedicionarios de Forjaz, muy conocidos en la Alianza, y supones que ellos les sacarían provecho.", progress = "¿Puedo ayudarte en algo? Te aseguro que tengo mucho que hacer. Sin embargo, si se trata de algo importante para la Liga de Expedicionarios... ¡entonces soy todo oídos!", completion = "¿Qué tienes ahí? ¡Vaya! ¿Dónde encontraste esto? \n\n¿De verdad? \n\n¿Qué hablaste de qué con quién? \n\n¡NO PUEDE SER VERDAD! \n\nMi querido &lt;clase&gt;, ¡este puede ser el descubrimiento arqueológico del año! ¿¡Qué digo del año!? ¡Del siglo! Si estos discos son lo que creo que son, ¡tenemos delante la última pieza del rompecabezas! Esto podría demostrar de una vez por todas la legitimidad de la creación encantada de los enanos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2280] = {title = "Los discos de platino", objective = "Lleva la reproducción en miniatura de los Discos de Norgannon a alguien que esté muy interesado.", description = "Al tocar los Discos de Norgannon de nuevo, sientes un cosquilleo en la mano. En esta ocasión, sin embargo, se oye un extraño ruido proveniente de su interior.\n\nSientes cómo tu mochila de repente es más pesada que antes. ¡En su interior descubres una reproducción en miniatura de los discos!\n\nSin duda, un objeto de este tipo tendría un valor incalculable para alguien interesado en la historia antigua de Azeroth. ¡A alguien le va a interesar mucho!", progress = "¿Qué tienes ahí? ¿Qué has descubierto sobre los discos?", completion = "Estos discos lo cambiarán todo. Ahora sus secretos nos pertenecen.", rewards = "Martillo de DurdinEspada de platinoPodrás elegir una de estas recompensas:\n\nSortija de Uldaman\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][2281] = {title = "Cita en Crestagrana", objective = "Adéntrate en Villa del Lago, en las Montañas Crestagrana, y habla con Lucius.", description = "Enviarte ahora a la batalla sería suicida. Renzik no necesita otro pícaro muerto en sus manos. Pero no te apresures, <nombre>, ya te meterá prisa Renzik.\n\nDirígete hacia las Montañas Crestagrana y habla con Lucius, es un miembro del IV:7. Lo encontrarás en el embarcadero de Villa del Lago, con los demás vagos y maleantes.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2283] = {title = "La recuperación del collar", objective = "Busca el collar en la excavación de Uldaman y llévaselo a Dran Droffers a Orgrimmar. Puede que el collar esté estropeado.", description = "Tenemos un trabajillo para ti. ¿Te atreves?\n\nAl parecer, hace poco que un idiota de paladín murió en la excavación Uldaman, en medio de las Tierras Inhóspitas. Lo que nos interesa de esto es que llevaba un collar muy valioso con tres gemas: un rubí, un zafiro y un topacio.\n\nEn resumen: queremos el collar y cubriremos de plata a quien lo traiga. Aunque esté deteriorado, no importa; ya lo arreglaremos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2284] = {title = "La recuperación del collar, 2ª parte", objective = "Busca pistas sobre el paradero de las gemas en las profundidades de Uldaman.", description = "Me juego el cuello a que las gemas están en Uldaman.\n\nComo dije antes, si lo que hemos oído es correcto, el collar lleva un rubí, un zafiro y un topacio. Encuentra las gemas y colócalas en el collar.\n\nEn cuanto a dónde están esas gemas... no lo sabemos. Con un poco de suerte, estarán en el cadáver del paladín, si es que no lo ha saqueado alguien ya.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2342] = {title = "Los tesoros reclamados", objective = "Saca el tesoro de la familia de Patrick Garrett del cofre de su familia que se encuentra en la Sala Comunal Sur de Uldaman y llévasela a él a Entrañas.", description = "¡Espantar murciélagos con una escoba no es apropiado para un Garrett! He ahorrado algo con este sórdido trabajo, y quiero entregártelo a ti para que me ayudes.\n\nEl arma elegida por la familia Garrett está guardada en nuestro cofre de la Sala Comunal Sur de Uldaman desde que nosotros, los Garrett, trabajábamos allí como excavadores. Sin ella, estaré atrapado aquí para siempre, literalmente, limpiando este lugar de estos murciélagos infernales.\n\n¡Reclama el tesoro de mi familia y tráemelo! ¡Ayúdame a recuperar mis derechos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2358] = {title = "Cuernos de Nez'ra", objective = "Lleva los Cuernos de Nez'ra a Arantir a Villa del Lago.", description = "Hace muchos años robaron los Cuernos de Nez'ra de la Mansión Ravenholdt. Los he buscado por mar y tierra y resulta que han estado en poder de estas insignificantes criaturas todo este tiempo.\n\nAcaba con todos los orcos Roca Negra que veas hasta recuperar los Cuernos de Nez'ra. Si lo consigues, ven a verme a Villa del Lago.\n\nSi me haces este favor, Ravenholdt oirá hablar de ti, <nombre>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nTé de cardo"}
MultiLanguageQuestData['mx'][2360] = {title = "Mathias y los Defias", objective = "Ve a los Páramos de Poniente y encuentra a la agente Kearnen para dar parte.", description = "Justo a tiempo, <nombre>. La división de reconocimiento del IV:7 ha informado sobre un aumento de actividad Defias en los Páramos de Poniente.\n\nParece ser que los Defias han tomado una atalaya abandonada de la Alianza al sureste de la Colina del Centinela y la están utilizando como base de operaciones para robar mercancías de la ruta de suministros de Crestagrana.\n\nVe a los Páramos de Poniente y contacta con la agente Kearnen para dar parte. La encontrarás escondida, cerca de la torre.\n\n... Y <nombre>, si te descubrieran, el IV:7 negaría todo conocimiento de tu existencia.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2378] = {title = "Encuentra a los Mano Destrozada", objective = "Viaja a Orgrimmar y habla con Shenthul, que estará en el Circo de las Sombras.|n", description = "Has servido con diligencia a los mortacechadores, <nombre>, pero quizás sea hora de que vayas más allá. Aunque tengas cualidades para el sigilo y el engaño, debes continuar con tu instrucción.\n\nLos mortacechadores cuentan con aliados entre los Mano Destrozada. Busca a los que nos puedan echar una mano; encuentra a Shenthul en Orgrimmar.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2379] = {title = "Zando'zan", objective = "Habla con Zando'zan en el Circo de las Sombras.", description = "No conseguirás superar los obstáculos que nos esperan solo con fuerza de voluntad.\n\nHabla con Zando'zan para empezar tu formación como miembro de Mano Destrozada.\n\nSolo cuando domines el sigilo y el robo podrás seguir tu camino hacia tu destino.\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][2380] = {title = "Ve a Orgrimmar", objective = "Ve a Orgrimmar, al Circo de las Sombras, y habla con Shenthul.", description = "No eres <el rey/la reina> del sigilo pero eso puede cambiar. Y cambiará. Evidentemente, has impresionado a los de arriba con tus pobres habilidades, porque el gran Shenthul desea verte.\n\nSigue la carretera que hay al norte de aquí. Te llevará a Orgrimmar. Habla con Shenthul, estará en el Circo de las Sombras.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2381] = {title = "Saquear a los saqueadores", objective = "Llévale el tesoro de los Mares del Sur a Desdio el Desdichado en Trinquete. No olvides conseguir una G.E.A.Q. y herramientas de ladrones del aparato Gizmotrónico de Wrenix. Necesitarás todo eso para completar tu misión.\n\nSi te atacaran unos loros anormalmente agresivos, ¡usa la G.E.A.Q.!|n|n", description = "No quiero asustarte, <nombre>, pero los cinco últimos ladrones a los que había enviado a robar el tesoro de los Mares del Sur acabaron en pedacitos.\n\nHacia el sur, bordeando la costa, encontrarás el Surcamareas, el barco de los filibusteros de los Mares del Sur. A buen recaudo en la bodega se encuentra el premio: el tesoro de los Mares del Sur. En el segundo nivel de ese barco está la guarida de los piratas, un lugar donde practican todos sus ladrones.\n\nSube a bordo de ese barco, roba el tesoro y tráemelo. Usa la guarida de los piratas si necesitas practicar cómo robar ¡pero ten cuidado!\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nTé de cardo"}
MultiLanguageQuestData['mx'][2382] = {title = "Desdio de Trinquete", objective = "Ve a Trinquete, en Los Baldíos, y habla con Desdio el Desdichado.", description = "Zando'zan ha visto que se acerca, sí, la muerte se acerca a Thrall. Será un puñal en la espalda, o un veneno que recorra su cuerpo... Zando'zan ha dicho demasiado.\n\n¡<nombre>! Zando'zan tiene una misión para <nombre>. <nombre> tiene que ir a Trinquete, que está al este de El Cruce, y hablar con Desdio el Desdichado. Ve.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2398] = {title = "Los enanos desaparecidos", objective = "Encuentra a Baelog en Uldaman.", description = "La excavación de Uldaman no siempre estuvo ocupada por extraños. Nosotros, los enanos de Forjaz, solíamos controlar la zona... pero eso era antes de que los troggs hicieran su aparición. ¡Llegaron tan rápido y eran tan numerosos que ni los enanos fuimos capaces de hacerles frente!\n\nDe hecho, su ataque fue tan repentino que yo mismo temí que algunos de los nuestros hubieran podido quedar atrapados tras las líneas enemigas.\n\nMi amigo Baelog estaba al frente de un pequeño grupo de enanos en las profundidades de la excavación en el momento en el que aparecieron los troggs. Si él y quienes lo acompañaban siguen con vida, quiero que los encuentres.", progress = nil, completion = "Ya era hora de que aparecieras. ¡Temía perder la apuesta que hice con Olaf! \n\nÉl apostó que su barba le crecería hasta las rodillas antes de que algún &lt;raza&gt; viniera a buscarnos. Aquí estás y, como puedes observar, ¡a la barba de Olaf aún le queda un buen trecho para llegar hasta sus rodillas! \n\nGracias, &lt;nombre&gt;. Repartiré las ganancias contigo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2418] = {title = "Las piedras de energía", objective = "Llévale 8 piedras de energía de dentrio y 8 piedras de energía de An'Alleum a Aparejez en las Tierras Inhóspitas.", description = "Hace algún tiempo, me ocurrió un incidente con los enanos de Forjatiniebla. Me trajeron a la Fortaleza de Angor para estudiar dos tipos de extrañas piedras de Uldaman. Descubrí que las piedras eran fuentes de energía estable y continua si se manipulaban correctamente. ¡Es asombroso las cosas que te puedes encontrar en esa vieja excavación!\n\nEn fin, después de compartir con ellos el secreto de las piedras, me echaron de la Fortaleza de Angor y siguieron excavando para conseguir más en Uldaman.\n\n¡Quiero esas piedras para mí! Tráeme de los dos tipos ¡y no escatimaré en gastos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Círculo de Piedras energizadoBrazales de DuracinBotas perpetuasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][2438] = {title = "El atrapasueños esmeralda", objective = "Consigue el atrapasueños esmeralda.", description = "Gaerolas Talvethen, el celador de los druidas de Túmulo de Ban'ethil, me dio una vez un atrapasueños esmeralda. Este poderoso amuleto es capaz de extraer energía del Sueño Esmeralda y dar buena suerte a quien lo porta.\n\nPor desgracia, lo dejé en la aldea Brisa Estelar... Aunque antes Brisa Estelar era un lugar tranquilo, ahora sucumbió a la corrupción de los fúrbolgs que allí habitan.\n\n¿Estás <dispuesto/dispuesta> a recuperar mi atrapasueños, <clase>?", progress = "Date prisa, por favor. Solo espero que los fúrbolgs no hayan estropeado mi atrapasueños esmeralda.\n\n¿Lo has recuperado ya, <nombre>?", completion = "Mi atrapasueños esmeralda es muy importante para mí. Es un regalo reservado a unos pocos. Gracias por devolvérmelo, &lt;nombre&gt;.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][2440] = {title = "Los discos de platino", objective = "Llévale este vale de recompensa a Bena Pezuña Invernal, que está en Cima del Trueno.", description = "Concentraré mis energías en estos discos pues tarde o temprano me acabarán revelando su auténtico propósito.\n\nEn cuanto a ti, <nombre>, te recompensaré por haberme informado con tanta presteza. Entrégale este vale a Bena Pezuña Invernal, la instructora de alquimia de Cima del Trueno. Ella te dará un objeto muy especial que confío te resultará tentador y te entregará una selección de pociones de mi reserva personal.\n\nVuelve pronto a mi lado pues presiento que nos quedan muchas cosas por hacer en relación a este hallazgo.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nPoción de sanación excelentePoción de maná superior\n\nTambién recibirás:\n\nSaco de pelambre descongelada"}
MultiLanguageQuestData['mx'][2458] = {title = "Agente encubierto", objective = "Ve a la torre de Ventura y Cía., al norte de El Fangal, y localiza al capataz Fizzule, el agente de Mano Destrozada. \n\nCuando veas la torre, usa la pistola de bengalas para avisar de tu llegada al capataz Fizzule. Lanza 2 bengalas y acércate al capataz para darle el /saludo de los Mano Destrozada. \n\nTienes que hacerlo en este orden, porque Fizzule te matará si no te reconoce.\n\nObjeto provisto: \n", description = "¿Has oído hablar de Ventura y Cía.?\n\nNos ha costado un año de duros esfuerzos, pero hemos conseguido infiltrar un agente.\n\nHemos descubierto que planean algo a gran escala. Ve hacia el norte, a El Fangal; en la torre de Ventura y Cía. Encontrarás a nuestro agente, el capataz Fizzule.\n\nCuando encuentres la torre, dispara la pistola de bengalas, busca a Fizzule y dale el saludo de Mano Destrozada.\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSilbato de Fizzule"}
MultiLanguageQuestData['mx'][2460] = {title = "El saludo de los Mano Destrozada", objective = "Da el saludo de los Mano Destrozada a Shenthul.", description = "Si quieres pertenecer a Mano Destrozada, tendrás que aprender el saludo. Es la única forma de identificar a los miembros.\n\nMírame, apréndelo y repite.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2478] = {title = "Misión: Posible, pero no probable", objective = "Roba la llave de la torre del supervisor Silixiz, mata a 2 zánganos mutados de Ventura y Cía., 2 patrullas de Ventura y Cía. y 2 oteadores de Ventura y Cía.\n\nAsesina al gran supervisor Puzik Gallywix y quédate con su cabeza, fuerza la cerradura del arcón de Gallywix y roba la mezcla de Zanzil modificada que allí está oculta. Lleva el alijo y la cabeza de Gallywix a Shenthul en Orgrimmar, él te dará más instrucciones.|n", description = "Tendrás que robarle la llave de la torre al supervisor Silixiz, <nombre>. Cuando la llave esté en tus manos, quédatela, podría necesitarla más tarde.\n\nRecuerda, el veneno lo ha debilitado todo en esta torre. Usa todos tus recursos para sembrar el caos y la destrucción entre sus habitantes. Masácralos a todos ¡sin piedad!\n\nCuando todo esté bañado en sangre, toma la caja fuerte de Gallywix y roba el preparado de Zanzil ahí guardado. Lleva la cabeza de Gallywix y el preparado a Shenthul en Orgrimmar.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nReceta: té de cardo"}
MultiLanguageQuestData['mx'][2479] = {title = "La ayuda de Hinott", objective = "Ve a Molino Tarren, en Laderas de Trabalomas, para entregar la muestra de Zanzil a Serge Hinott. \n\nPara llegar a Molino Tarren, sube al zepelín que va a Entrañas y sigue el camino hacia el sur por el Bosque de Argénteos hacia Trabalomas. ¡Sigue las indicaciones!|n|n", description = "Llévale una muestra de la mixtura a Serge Hinott, que está en Molino Tarren.\n\nSi hay alguien que pueda curarte, ese es él. Si vives lo suficiente, te enseñará a crear y usar venenos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2500] = {title = "Componentes de Tierras Inhóspitas", objective = "Ve a las Tierras Inhóspitas a buscar los ingredientes que te ha pedido Ghak Sanadón y llévaselos a Thelsamar.", description = "<clase>, necesito asistencia. Soy un alquimista de cierto renombre y necesito que me ayudes a conseguir ingredientes que se encuentran en las Tierras Inhóspitas.\n\nEsto es lo que necesito: 5 mollejas de águila ratonera, 10 colmillos de coyote montés y 5 fragmentos de elemental de roca. Evidentemente, estos ingredientes están en las propias bestias; si la lucha no es lo tuyo, lleva a un par de amigos duros.\n\nSi me traes todo esto, te ganarás unas monedas.\n\nDime, ¿aceptas?", progress = "¿Tienes las cosas que necesitaba? No te pagaré a menos que hayas traído esos componentes.", completion = "Buen trabajo, &lt;nombre&gt;; con esto ya tengo para una temporada. Ten, tu recompensa. \n\nY tengo otro trabajo para ti, si te interesa. Lo que busco está en la excavación de Uldaman y no es fácil de conseguir, pero te recompensaré bien. \n\nY con algo más tentador que las monedas, ¿qué me dices?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2518] = {title = "Las lágrimas de la Luna", objective = "Recupera las hileras de plata de Lady Sathrah.", description = "Lady Sathrah estuvo una vez en gracia de Elune. Grácil y pura, la araña tejió sus telas de plata a la luz de la luna, atrapando la niebla de la noche. El rocío plateado tenía grandes poderes de curación por lo que se guardó en el templo.\n\nPero en los últimos tiempos, Sathrah cayó en la locura y ahora sus generaciones futuras también están en peligro.\n\n<nombre>, encuentra a Lady Sathrah y pon fin a su sufrimiento. Suele estar al noreste de aquí, cerca del río. Atrápala y tráeme sus hileras de plata.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][2519] = {title = "El templo de la Luna", objective = "La hermana Aquinne quiere que hables con la sacerdotisa A'moora en el Templo de la Luna.", description = "Una criatura del bosque, en su día grandiosa, necesita ayuda, <raza>.\n\nHay una difícil tarea que cumplir.\n\nPor favor, busca a la sacerdotisa A'moora; ella te lo explicará todo. La encontrarás al sudeste de aquí, dentro del Templo de la Luna.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2521] = {title = "Al servicio de Kum'isha", objective = "En tus viajes por Las Tierras Devastadas, si te encontraras con una esfera draenetista perfecta, llévasela a Kum'isha el Coleccionista.\n\nTen cuidado, esta gema es uno de los cristales más raros de todo Azeroth. Cualquier criatura de estas tierras podría tener una.\n\nSe te recompensará por cada esfera draenetista perfecta que consigas.", description = "<raza>, ¿será capaz tu cerebro de mosquito de entender cuán rara es una esfera draenetista perfecta? Generaciones de draenei han buscado uno solo de estos cristales y solo lograron un destino fatal, su objetivo por cumplir.\n\nAsí que te presentas ante Kum'isha, sabiendo lo que Kum'isha ha pedido ¿y aún deseas ayudar? Tú verás, <raza>... En el momento que sea a lo largo de tus viajes por estas tierras, en cuanto encuentres una esfera draenetista perfecta, tráemela y te recompensaré con riquezas con las que ni siquiera puedes soñar.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCofre taraceado esmeralda"}
MultiLanguageQuestData['mx'][2541] = {title = "El druida durmiente", objective = "Llévale un talismán de vudú chamán a Oben Garrafuria al Túmulo de Ban'ethil.", description = "Los chamanes Tuercepinos que habitan este lugar han descubierto un modo de separar el espíritu de un druida durmiente de su cuerpo físico. Los fúrbolgs han reanimado mi representación física y la están utilizando para atacar a todo el que intente entrar en Túmulo de Ban'ethil. Yo estoy atrapado en el Sueño Esmeralda y no puedo hacer nada para detenerlos.\n\nTienes que ayudarme. Los chamanes Tuercepinos portan un extraño talismán para llevar a cabo el ritual y me gustaría examinarlo. Por favor <nombre>, tráeme uno.", progress = "Si pudiera examinar el talismán, podría descubrir cómo romper el encantamiento. ¿Has encontrado alguno?", completion = "Gracias, &lt;nombre&gt;. \n\nQué objeto más extraño... Puedo sentir el aura de maldad que emana de él. Se trata de un potente encantamiento.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][2581] = {title = "Papadas de hiena risitas", objective = "Llévale 3 papadas de hiena risitas, 2 pulmones de jabalí maldito y 1 pinza de scorpok al mago sangriento Drazial.", description = "Es bien sabido que las hienas poseen una gran fuerza en sus papadas pero ¿tanta como para morder a través de 7.5 centímetros de acero de torio? Imposible, improbable, y lo cierto es que lo he visto con mis propios ojos.\n\nAdéntrate en Las Tierras Devastadas y tráeme 3 papadas de hiena risitas. Cuando busques la hiena risitas, estate <atento/atenta> a los jabalíes y a los scorpoks. Para la preparación inicial de polvo también hacen falta 2 pulmones de jabalí maldito y 1 pinza de scorpok.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nIFRDHR"}
MultiLanguageQuestData['mx'][2582] = {title = "Ira de las Eras", objective = "Llévale 3 papadas de hiena risitas, 2 pulmones de jabalí maldito y 1 pinza de scorpok al mago sangriento Drazial.", description = "Ah, <nombre>, <bienvenido/bienvenida> de nuevo. Parece que has disfrutado del efecto de impregnación operativa y robusta que la hiena risitas produce. Ten cuidado, aunque el efecto inmediato es un impulso titánico de fuerza, los efectos a largo plazo sobre tu ánimo y tu inteligencia podrían ser peligrosos.\n\nHecha la advertencia, ¿necesitas más? Si es así, tráeme otras 3 papadas de hiena risitas, 2 pulmones de jabalí maldito y 1 pinza de scorpok.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nIFRDHR"}
MultiLanguageQuestData['mx'][2583] = {title = "La vitalidad del jabalí", objective = "Llévale 3 pulmones de jabalí maldito, 2 pinzas de scorpok y 1 cerebro de basilisco al mago sangriento Drazial.|n", description = "En Las Tierras Devastadas hay dos especies de jabalí: el cenicrín y el jabinferno.\n\nAl parecer, la fortaleza de estas bestias los vuelve prácticamente inmunes a cualquier daño, ya que los demás animales los encuentran demasiado difíciles de matar y, por lo tanto, que no merece la pena tal esfuerzo.\n\nTenemos que examinarlos más a fondo, <nombre>. Si me traes 3 pulmones de jabalí maldito, 2 pinzas de scorpok y 1 cerebro de basilisco, con ellos crearé un elixir divino a partir de los residuos del polvo. ¡Serás mi <primer/primera> cobaya!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCóctel de zumo de pulmón"}
MultiLanguageQuestData['mx'][2584] = {title = "El espíritu del jabalí", objective = "Llévale 3 pulmones de jabalí maldito, 2 pinzas de scorpok y 1 cerebro de basilisco al mago sangriento Drazial.|n", description = "La primera vez que te administré el elixir, <nombre>, sabía que una o dos aplicaciones no bastarían para saciar tu apetito. Incluso ahora veo la ansiedad en tus ojos. Ese brebaje tiene propiedades adictivas a las que, al parecer, no se resiste ni la voluntad más férrea.\n\n¡Que así sea! Si necesitas más cóctel de zumo de pulmón, vuelve al páramo y encuéntrame 3 pulmones de jabalí maldito, 2 pinzas de scorpok y 1 cerebro de basilisco.", progress = "¡¿Dónde están los órganos, <nombre>?!", completion = "Debo advertirte, &lt;nombre&gt;, no intentes mezclar las fórmulas que he creado. Las propiedades químicas de la fórmula ingerida en último lugar siempre prevalece sobre encantamientos anteriores, por lo que se anularían los efectos de las fórmulas precedentes.|n", rewards = "Recibirás:\n\nCóctel de zumo de pulmón"}
MultiLanguageQuestData['mx'][2585] = {title = "El golpe decisivo", objective = "Llévale 3 pinzas de scorpok, 2 mollejas de buitre y 1 pulmón de jabalí maldito al mago sangriento Drazial.|n", description = "¿Los has visto combatir alguna vez, <nombre>? Me refiero a los scorpoks. ¿Has visto alguna vez la gracia y la agilidad de sus movimientos? ¿La firmeza de sus golpes?\n\nSi pudiéramos aislar de alguna manera esa agilidad y envasarla, nuestra riqueza sería más... digo... sería un tremendo impulso para la comunidad científica.\n\nAyúdame, <nombre>, y te regalaré una muestra del polvo.\n\nPara crear una muestra estable, voy a necesitar 3 pinzas de scorpok, 2 mollejas de buitre y 1 pulmón de jabalí maldito.", progress = "¡¿Dónde están los órganos, <nombre>?!|n", completion = "Fascinante. Este ha sido el polvo más difícil de analizar. \n\nToma esta pizca de sal residual y colócala debajo de tu lengua. Deberías sentir una leve sensación de euforia seguida de un estado de agilidad y velocidad nunca visto.", rewards = "Recibirás:\n\nPolvo de scorpok machacado"}
MultiLanguageQuestData['mx'][2586] = {title = "La sal del Scorpok", objective = "Llévale 3 pinzas de scorpok, 2 mollejas de buitre y 1 pulmón de jabalí maldito al mago sangriento Drazial.", description = "¡Estás <vivo/viva>! Esto sí que es una buena noticia. Supongo que has vuelto a por más polvo de scorpok, ¿no?\n\nMuy bien, <nombre>, vuelve al páramo y no regreses hasta que hayas recolectado 3 pinzas de scorpok, 2 mollejas de buitre y 1 pulmón de jabalí maldito.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPolvo de scorpok machacado"}
MultiLanguageQuestData['mx'][2601] = {title = "El bocado de basilisco", objective = "Llévale 10 cerebros de basilisco y 2 mollejas de buitre a la maga sangrienta Lynnore.|n", description = "Estos páramos están plagados de basiliscos Rocarroja, <nombre>. Estos basiliscos se han adaptado y se han multiplicado más que cualquier otra especie de la región.\n\nLos he observado a cierta distancia cuando cazan y en sus actividades cotidianas; esas bestias muestran un comportamiento reflexivo más complejo incluso que el de ciertos humanoides.\n\n¡Debo estudiar sus cerebros!\n\nConsígueme 10 cerebros, <nombre>. Aunque el preparado no estará completo si no tengo además 2 mollejas de buitre para crear la base de la solución.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCompuesto de córtex cerebral"}
MultiLanguageQuestData['mx'][2602] = {title = "La mente infalible", objective = "Llévale 10 cerebros de basilisco y 2 mollejas de buitre a la maga sangrienta Lynnore.", description = "¿Ya has perdido la concentración? ¡Debo seguir investigando!\n\nAh, sí, el precio sigue siendo el mismo, <nombre>. Adéntrate en Las Tierras Devastadas y tráeme 10 cerebros de basilisco Rocarroja y 2 mollejas de buitre.\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCompuesto de córtex cerebral"}
MultiLanguageQuestData['mx'][2603] = {title = "El vigor del buitre", objective = "Llévale 10 mollejas de buitre y 2 papadas de hiena risitas a la maga sangrienta Lynnore.|n", description = "La muerte tiene alas en estas tierras devastadas, <raza>. Yo he visto a esos negros asesinos y carroñeros dándose festines con los cadáveres de muchos exploradores... alimentándose incluso de los cadáveres más viles y enfermos. Es un milagro que sus organismos hayan sobrevivido a la pestilencia que reclama estas tierras.\n\n¡Ayúdame con mis estudios, <nombre>! ¡Necesito mollejas! También necesitaré dos papadas de hiena para el brebaje.\n\nSerás doblemente recompensado por tus esfuerzos.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nChicle de mollejas"}
MultiLanguageQuestData['mx'][2605] = {title = "El goblin sediento", objective = "Consigue una glándula cargada de rocío y llévasela a Marin Tragonublo a Gadgetzan.", description = "He tenido una idea. He oído hablar de unas extrañas criaturas llamadas colectores de rocío que habitan hacia el suroeste... capaces de almacenar agua en unas glándulas especiales.\n\nCreo que si pudiera hacerme con una de esas glándulas, sería capaz de idear una bebida para saciar mi espantosa sed. ¿Crees que podrías ayudarme, <nombre>?\n\nBusca el jardín de cactos, <nombre>, pues allí encontrarás a los colectores de rocío.", progress = "Por favor, dime que has encontrado a los colectores de rocío.", completion = "¡Oh, maravilloso! ¡Trae, me lo voy a beber!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2606] = {title = "Un buen sabor", objective = "Marin Tragonublo quiere que hables con Roxio en Gadgetzan.", description = "¡Puaj! ¡Esto sabe fatal! Menuda idea...\n\nEspera, ¿qué? Ah, ya veo. Crees que debería tirarlo. Está bien.\n\n¡Eh, tengo una idea! ¡Es perfecto! Llévale este rocío a mi amiga Roxio, que es una gran cocinera. Dile lo que pasa y a ver si consigue que baje algo mejor.\n\nEs decir, si va a seguir sabiendo igual de mal, al menos que dé un buen pelotazo... Yo de momento no siento nada...", progress = "Así que Marin está otra vez en ello, ¿eh? ¿De qué está hecho este brebaje?", completion = "Marin es un buen tipo pero un poco excéntrico, diría yo. \n\nEn cualquier caso, está claro que necesita mi ayuda una vez más.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2609] = {title = "Toque de Zanzil", objective = "Lleva a Doc Mixilpixil un ramo de flores silvestres simples, un vial emplomado, un tubo de bronce y una bobina de hilo de seda verde pistacho. La 'itis' no se cura sola, <jovencito/jovencita>.", description = "Es unánime, <nombre>. Tienes la 'itis'.\n\nPor suerte para ti, tengo la cura para la 'itis'.\n\nEsto es lo que necesito: un ramo de flores silvestres simples, un vial emplomado, un tubo de bronce y por último, pero no menos importante, una bobina de hilo de seda verde pistacho. La vieja Emma dejó una bobina para mí en 'El Paño Fino'. Podrás encontrar la tienda en los canales.\n\nY ahora date prisa, <nombre>, e intenta no tocar a nadie hasta que estés <curado/curada>. Oh, y el doctor Montgomery dice que necesitas una ducha... Lo dice él, no yo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAgua de Mixilpixil"}
MultiLanguageQuestData['mx'][2621] = {title = "El deshonrado", objective = "Habla con el comandante de envíos Ruag en Rocal, en el Pantano de las Penas.", description = "Arrepentimiento. Eso es lo que me queda. Una mal decisión que desembocó en varias tragedias. ¡¿Por qué diablos no esperaría las órdenes?! ¡A lo mejor habrían descrito el horror que nos aguardaba en esas malditas tierras! ¿O quizás nos habrían enviado a otro destino? A fin de cuentas, fue culpa mía. Todo fue culpa mía.\n\nAsí que aquí estoy, esperando órdenes. Debo conocerlas. Debo tener esas órdenes.\n\nEl comandante de envíos Ruag vive en Rocal. Encuéntralo y averigua qué fue de esas órdenes.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2623] = {title = "La voz del pantano", objective = "Recupera las órdenes del Jefe de Guerra y vuelve junto al héroe caído de la Horda.", description = "El Comandante de envíos dio las órdenes. Tomamos... tomamos las órdenes. Camino de Las Tierras Devastadas, emboscada.\n\nMúrlocs... Muchos múrlocs... Uno llamado voz del pantano. Me arrancó las órdenes de las manos cuando una lanza me atravesó la cabeza. Este... caverna...\n\n<Bengor fallece.>\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2641] = {title = "El ingrediente secreto de Roxio", objective = "Roxio de Gadgetzan quiere que consigas un tragano violeta y se lo lleves.", description = "Cuando era niña, siempre cocinaba mi hermana. ¡Era espantoso! Muchos de sus brebajes no se tragaban... hasta que descubrí lo que yo llamo mi ingrediente \"secreto\". Échaselo a lo que sea y... ¡HALA! ¡Sabe a gloria!\n\nY qué es, te preguntarás. Es un champiñón que se conoce como tragano violeta. Si quieres que te ayude a hacer de este nauseabundo brebaje algo pasable, dirígete a las Tierras del Interior y localiza un pequeño lago que hay allí.\n\nAh, y recuerda que el tragano violeta solamente crece bajo el agua.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2681] = {title = "Las piedras que nos vinculan", objective = "Libera a 9 sirvientes de Razelikh, 3 sirvientes de Sevine, 3 sirvientes de Allistarj y 3 sirvientes de Grol. Vuelve junto al Héroe Caído cuando hayas acabado la tarea. Debes permanecer cerca de las piedras o el proceso no funcionará.", description = "No podrás vencer a las tropas de Razelikh y a sus seguidores tú <solo/sola>.\n\nReúne a un grupo de aguerridos aventureros ¡y libera a mis hombres de su eterna tortura! 18 piedras has de hacer añicos.\n\nCombate con brío y muere con honor, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2741] = {title = "El Superhuevomático", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nCajón de huevos"}
MultiLanguageQuestData['mx'][2742] = {title = "¡Capturaron a Rin'ji!", objective = "Ayuda a Rin'ji a salir de la Avanzada Quel'Danil y encuentra su secreto oculto en los Acantilados Dominantes.", description = "¡<raza>!\n\n¡Rin'ji perdió el hacha y fue capturado! Ayuda a Rin'ji a escapar, por favor. ¡Rin'ji sabe que a <un/una> <raza> no te gusta su gente, pero por favor! ¡Quiero salir!\n\nTengo algo para amable <raza> si me ayudas a escapar...\n\nAlgo secreto escondido en los Acantilados Dominantes.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2744] = {title = "El cazademonios", objective = "Habla con Loramus Thalimedes en Azshara.", description = "La tríade está protegida por Razelikh.\n\nA cambio de su servidumbre, Razelikh les concedió a cada uno poderes casi ilimitados sobre Las Tierras Devastadas. Cada pieza de amuleto está adaptada a la fuerza vital de su propietario y le confiere la inmortalidad. Mientras permanezcan en Las Tierras Devastadas no se les puede matar, su vida se extiende hasta el final de los días.\n\nSé de alguien que podrá ofrecerte más ayuda, <nombre>. Ve a Azshara y encuentra al cazademonios, Loramus Thalimedes. Busca en las islas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2745] = {title = "Infíltrate en el castillo", objective = "Habla con Tyrion en el Castillo de Ventormenta.", description = "Mmm, una historia interesante, y bastante grave. Sí, puedo ayudarte, pero si quieres que esto salga bien, lo que necesitas es impartir una forma de justicia que no es... legal.\n\nHay que encargarse de Lescovar y Marzon y lo más rápido posible. ¿Crees que eres capaz de algo así?\n\nTú decides. Si es así, apresúrate al castillo y busca a un viejo amigo mío, un gnomo llamado Tyrion. Lleva un par de semanas vigilando a Lescovar. Debería poder ayudarte con esto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2746] = {title = "Objetos importantes", objective = "Lleva 3 paños de seda y 2 manzanas frescas de Clara a Tyrion en Ventormenta.", description = "Trias quiere que adelantemos el plan, ¿eh? Muy bien, podemos hacerlo, pero todavía tengo que terminar de prepararme. Y, has de saber una cosa, yo me encargo de la parte difícil, pero tú eres quien se va a ensuciar las manos. Bien.\n\nDe acuerdo, necesito que me consigas un par de cosas antes de poder poner mi plan en marcha. Tengo el disfraz perfecto para que el robot espía pase por delante de esos guardias.\n\nTráeme seda y un par de manzanas. La seda la tienes que buscar, pero la pequeña granja de Clara, justo en las afueras de la ciudad, tiene las manzanas del tamaño perfecto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2751] = {title = "Almenas barbáricas", objective = "Lleva 2 brazales de bronce estampados, 2 espadas magnas de bronce y 2 garras afiladas a Orokk Omosh a Orgrimmar.|n", description = "Este martillo ha pasado por 20 generaciones de Omosh, <nombre>. Hemos moldeado cien mil toneladas de metal. Por desgracia, todo se acabará con Orokk, la vergüenza de los Omosh: no puedo tener descendencia.\n\n¡Las recetas secretas de Omosh no pueden morir conmigo! Alguien tiene que aceptar este legado, aunque no sea Omosh.\n\nDemuestra tu valía, <nombre>. Tráeme dos brazales de bronce estampados, dos espadas magnas de bronce y dos garras afiladas. Entonces seguiremos.", progress = "Bronce, <nombre>. ¡Más bronce!", completion = "¡La leyenda de los Omosh perdurará! \n\nHas demostrado tu habilidad, &lt;nombre&gt;, y tu premio será ver tus armas y armaduras bañadas con la sangre de tus enemigos. \n\n¡Que tus creaciones protejan a tus aliados y destruyan a tus enemigos!|n", rewards = "Recibirás:\n\nDiseño: coraza barbárica de hierro"}
MultiLanguageQuestData['mx'][2752] = {title = "Espaldares de hierro", objective = "Lleva 4 hachas de batalla de bronce y 4 martillos de guerra de bronce a Orokk Omosh a Orgrimmar.", description = "Veo que tienes muchas ganas de aprender, <nombre>. Quieres absorber toda la sabiduría Omosh.\n\nTe daré tres lecciones.\n\nVuelve al yunque, empápate del calor de la forja y crea cuatro hachas de batalla de bronce y cuatro martillos de guerra de bronce. Entonces te enseñaré a fabricar unos espaldares de hierro.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDiseño: sobrehombros barbáricos de hierro"}
MultiLanguageQuestData['mx'][2753] = {title = "¡Aplástalos!", objective = "Lleva 4 yelmos de hierro verde, 4 brazales de hierro verdes y 2 pares de leotardos de hierro verdes a Orokk Omosh a Orgrimmar.", description = "Solo te daré dos lecciones más, <nombre>. Sé que te duelen los músculos, pero hazlo por los Omosh.\n\nTráeme cuatro yelmos, cuatro brazales y dos pares de leotardos, todo de hierro verde. ¡Así aprendes y perjudicas al enemigo!", progress = "¡Aplástales el cráneo con las botas!", completion = "Me recuerdas al jefe Gorokk, abuelo de Orokk. Lee y aprende.", rewards = "Recibirás:\n\nDiseño: botas barbáricas de hierro"}
MultiLanguageQuestData['mx'][2754] = {title = "Cuernos de frenesí", objective = "Lleva 2 grandes mazas de hierro sólido, 2 botas de bronce bañadas en plata y 2 guanteletes de bronce bañados en plata a Orokk Omosh en Orgrimmar.", description = "Esta es la última lección de Orokk, <nombre>. Regresa a la forja sagrada. Trae a Orokk dos grandes mazas de hierro sólido, dos botas de bronce bañadas en plata y dos guanteletes de bronce bañados en plata.\n\n¡Se morirán de miedo con solo verte!\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDiseño: yelmo barbárico de hierro"}
MultiLanguageQuestData['mx'][2755] = {title = "Las alegrías de los Omosh", objective = "Mira la danza de la alegría de los Omosh.", description = "Orokk no llora, <nombre>.\n\n<Se seca una lágrima.>\n\nOrokk tiene otro secreto de la familia Omosh que enseñarte. Orokk morirá feliz gracias a <nombre>.\n\nAprende la danza de la alegría de los Omosh y te enseñaré lo que sé de los puños de hierro.\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDiseño: guantes barbáricos de hierro"}
MultiLanguageQuestData['mx'][2756] = {title = "Los viejos hábitos", objective = "Lleva 4 corazas de acero y 4 yelmos de placas de acero a Aturk el Yunque a Orgrimmar.|n", description = "En las leyendas, Aturk trituraba las calaveras de sus enemigos hasta convertirlas en un polvillo fino. Esos días ya se fueron, <raza>. El Jefe de Guerra pide la concordia entre los clanes. ¡Ahora solo se vigila a los enemigos de reojo!\n\nEs increíble, pero esta es la voluntad de Thrall.\n\n¡Pero basta de batallitas! Has venido a aprender y eso es lo que harás. Tráeme cuatro corazas de acero y cuatro yelmos de placas de acero y probarás el sabor de la guerra.Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nEnseñar leotardos de combate orcos\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][2757] = {title = "¡Bahía del Botín o nada!", objective = "Habla con McGavan en Bahía del Botín.", description = "Mira, no vas a aprender nada si andas perdiendo el tiempo por aquí.\n\nConozco a un tipo que suele estar por la herrería de Bahía del Botín. Enséñale esta insignia y te enseñará todo lo que hay que saber del mitril.\n\n¿Qué me dices, eh? Ya es hora de que aprendas cosas nuevas, <nombre>.\n\nSi te animas, ve a ver a ese tipo, McGavan. Enséñale esto y así verá que vas en serio.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2758] = {title = "El origen de la herrería", objective = "Lleva seis brazales de escamas doradas a Hank el Martillo en Ventormenta.", description = "Cuando tenía más o menos tu edad, un enano llamado Galvan me acogió y me enseñó a forjar armaduras. Antes de partir a Bahía del Botín, me hizo prometer que instruiría a todos aquellos que sintieran una férrea determinación por aprender el oficio de la herrería. Así que, aquí estoy, muchos años después.\n\nAhora, ha llegado la hora de que aprendas algo. Hazme seis brazales de escamas doradas y aprenderás el significado de la herrería, <nombre>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDiseño: guanteletes de escamas doradas"}
MultiLanguageQuestData['mx'][2761] = {title = "Funde o no funde", objective = "Lleva cuarenta barras de mitril y cuarenta barras de hierro a Galvan el Antiguo en Tuercespina.", description = "Muchos herreros creen que la minería y la herrería van por separado, son trabajos independientes. ¿Pero podría existir la herrería sin la minería? ¡Ajá, es imposible! El buen herrero debe ser también un buen minero.\n\nDemuestra a Galvan de lo que eres capaz, <nombre>. Tráeme cuarenta barras de hierro y cuarenta de mitril. A cambio, Galvan te enseñará el secreto de los pantalones de mitril ornamentado.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDiseño: pantalones de mitril ornamentado"}
MultiLanguageQuestData['mx'][2762] = {title = "La veraplata no es verídica", objective = "Lleva cuarenta barras de mitril y cinco barras de veraplata a Galvan el Antiguo en Tuercespina.", description = "Dicen que la veraplata es más fuerte y duradera que el mitril. Galvan está de acuerdo con esta valoración de los minerales pero, al contrario de su nombre, ¡la veraplata no es verídica! ¡El mitril es un mineral mucho más noble! ¡JA! A pesar de todo, para esta lección necesitarás encontrar al mentiroso mineral, <nombre>.\n\nTráeme cuarenta barras de mitril y cinco de veraplata. A cambio, aprenderás el secreto de los guantes de mitril ornamentado y, lo más importante, ¡aprenderás que la veraplata no tiene nada de verdad!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDiseño: guantes de mitril ornamentado"}
MultiLanguageQuestData['mx'][2763] = {title = "El arte de imbuir", objective = "Lleva cuarenta barras de mitril y cuatro citrinos a Galvan el Antiguo en Tuercespina.", description = "Recoger gemas preciosas es de gran importancia para nuestro oficio, <nombre>. Y pocas gemas son más preciosas que el citrino. Las propiedades mágicas de las que están imbuidos los objetos se amplifican enormemente con la presencia de citrino.\n\nPara esta lección, fortificaremos cuarenta barras de mitril con cuatro citrinos. El resultado será una mejor comprensión de la gemología mágica y el conocimiento para crear sobrehombros de mitril ornamentado.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDiseño: sobrehombros de mitril ornamentado"}
MultiLanguageQuestData['mx'][2766] = {title = "¡Encuentra a OOX-22/FE!", objective = "Lleva el localizador de emergencia al robot mensajero de Oglethorpe a una cueva que hay cerca de Vega Cicatriz Feral.", description = "Has descubierto un extraño instrumento metálico con forma de huevo. Jugueteas con uno de los botones del huevo y este cobra vida y se convierte en una especie de artilugio robótico gnomo. Del interior del huevo robótico sale una voz.\n\n\"Mi nombre es Oglethorpe Obnoticus, ¡y mi robot mensajero se ha averiado! Te recompensaré por su rescate. Por favor, lleva este localizador hasta el robot.\"\n\n\"He procesado las coordenadas del robot: se encuentra en una cueva, cerca de la Vega Cicatriz Feral.\"Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2767] = {title = "¡Escolta a OOX-22/FE!", objective = "Escolta a OOX-22/FE para que llegue sano y salvo y después preséntate ante Oglethorpe Obnoticus en Bahía del Botín.", description = "Vuelves a oír la voz del gnomo que sale del robot:\n\n\"Tengo que llevar a OOX-22/FE a un lugar abierto y seguro en el que pueda iniciar el largo proceso de despegue. Tiene un dispositivo de invisibilidad integrado, pero necesito tiempo para que vuelva a estar operativo. ¡Escolta al robot hasta, digamos, el camino principal! Allí podré tomarme mi tiempo para hacer que todo vuelva a funcionar correctamente.\"\n\n\"¡Escóltalo para que llegue sano y salvo y después ven a verme a Bahía del Botín! Oglethorpe Obnoticus. ¡Corto y cierro!\"Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Experimento volador fallidoFelpa de tela metálicaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][2768] = {title = "Vara divinomática", objective = "Lleva la vara divinomática al ingeniero jefe Pasaquillas en Gadgetzan.", description = "¡El sargento Bly me ha robado! Dijo que solo lo cogía prestado, ¡pero me robó mi querida vara divinomática! Sin la vara, ¿cómo puedo saber dónde hacer nuevos pozos?\n\n¡Encuentra a Bly y tráeme mi vara! He oído que condujo a su panda de aventureros a buscar tesoros en Zul'Farrak, al Oeste. Seguro que lo encontrarás allí.\n\nEsperemos que los trols se hayan ocupado de él porque si tuvieras que combatir con él por la vara sería un combate realmente duro.", progress = "¿Encontraste al sargento Bly? ¿Tienes mi vara divinomática?", completion = "¡La encontraste! ¡Bien hecho, &lt;nombre&gt;! ¿Tuviste que luchar con Bly para conseguirla? Espero que le dieras bien fuerte a él y a toda su banda.", rewards = "Sombrero de hermandad de ingenieroPodrás elegir una de estas recompensas:\n\nAnillo de fraternidad masona\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][2769] = {title = "Los hermanos Pernolatón", objective = "Habla con Wizzle Pernolatón en El Desierto de Sal.", description = "¿Conoces a los hermanos Pernolatón? Están haciendo carreras contra los goblins en su coche cohete en El Desierto de Sal, en Kalimdor. Suelen ganar, lo que es normal: ¡el coche de los goblins es tan malo que apenas llega a cruzar la línea de meta!\n\nAun así, los Pernolatón siempre quieren mejorar su velocidad media y Wizzle me dijo que necesita una pieza muy rara para su próximo experimento.\n\nNecesitará a alguien que vaya a buscarla. Habla con él.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2770] = {title = "Gahz'rilla", objective = "Llévale la escama electrificada de Gahz'rilla a Wizzle Pernolatón, que está en El Desierto de Sal.", description = "En las profundidades de Zul'Farrak, la ciudad de arena de los trols de Tanaris, se encuentra una poza sagrada en la que los trols invocan a una bestia gigante... ¡Gahz'rilla! Es tan violento que hasta sus escamas crepitan con energía. ¡Esa es la energía que busco para mi coche!\n\n¡Tráeme la escama electrificada de Gahz'rilla!\n\nPara ello tendrás que invocar a Gahz'rilla y ese ritual es un secreto bien guardado por los trols. Para enfrentarte a él, primero tienes que arrebatarles el secreto.", progress = "¿Tienes la escama? ¡Estoy deseando averiguar cómo aprovechar su energía!", completion = "¡Vaya, has conseguido la escama! Gracias, &lt;nombre&gt;. ¡Estoy deseando ponerme manos a la obra con ella! \n\nAsí que has visto a Gahz'rilla... ¿¿Es tan grande como dicen??", rewards = "Recibirás:\n\nZanahoria pinchada en un palo"}
MultiLanguageQuestData['mx'][2771] = {title = "La cabeza sobre los hombros", objective = "Llévale un par de almófares de mitril y unos sobrehombros de mitril ornamentado a Trenton Mazaligera.", description = "Parece como si el maestro lo tuviera todo planeado. A mí no me enseñó a crear los objetos que te enseñó a crear a ti, y a ti no te enseñó a crear los objetos que me enseñó a crear a mí.\n\nEl maestro es sabio, <nombre>. ¡Podremos instruirnos el uno al otro!\n\nEnséñame a hacer un almófar de mitril y sobrehombros de mitril ornamentado y yo te enseñaré a crear un yelmo de mitril ornamentado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2772] = {title = "El mundo a tus pies", objective = "Llévale un par de botas de mitril pesado y unos pantalones de mitril ornamentado a Trenton Mazaligera.|n", description = "Durante el Campeonato de herrería del valle del año pasado, todos los que estaban atentos vieron cómo un cobarde de la Fundición de Ventura y Cía. vino directo a mi pierna. Sin embargo, lo que no saben es la razón por la cual pude continuar y finalmente ganar el torneo. ¡Eso es, botas de mitril ornamentado!\n\nSin embargo, tengo que aprender a hacer pantalones de mitril ornamentado para el campeonato de este año pues participa un machacador de Ventura y Cía. ¡Enséñame a hacer los pantalones y yo te enseñaré a hacer las botas!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2773] = {title = "El chico de mitril", objective = "Llévale un par de corazas de mitril pesado y unos guantes de mitril ornamentado a Trenton Mazaligera.", description = "Por aquí me conocen como el chico de mitril. Yo abastezco de mitril ornamentado a todos los aventureros del mundo.\n\n<Trenton susurra.>\n\nPocos saben que desconozco la técnica de creación de guantes de mitril ornamentado. ¡Sh! Este será nuestro pequeño secreto.\n\n<nombre>, enséñame la técnica para crear guantes de mitril ornamentado y, a cambio, yo te mostraré el resultado de la culminación de mi instrucción a las órdenes de Galvan: la coraza de mitril ornamentado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2781] = {title = "SE BUSCA: Califa Escorpijón", objective = "Llévale la cabeza de Califa Escorpijón al ingeniero jefe Pasaquillas, que está en Gadgetzan.", description = "SE BUSCA: Califa Escorpijón.\n\nLa compañía de aguas de Gadgetzan en Gadgetzan, Tanaris ofrece una generosa recompensa por la cabeza del Califa Escorpijón, el líder de los Vagayermos. Entre los crímenes que se le atribuyen se incluyen:\n\n1. ¡El asesinato de empleados de la compañía de aguas de Gadgetzan!\n2. ¡El robo de recursos de la compañía de aguas de Gadgetzan!\n3. ¡El allanamiento de las instalaciones de la compañía de aguas de Gadgetzan!\n\nEntrega una prueba del fallecimiento del Califa Escorpijón al ingeniero jefe Pasaquillas y recibirás una recompensa al momento.", progress = "Sí <clase>, yo soy un oficial de la compañía de aguas de Gadgetzan. ¿En qué puedo ayudarte?", completion = "¡Al fin se ha hecho justicia! ¡Has asestado un duro golpe a esos infames nómadas! La muerte de Escorpijón será clave para expulsar finalmente a los que se están aprovechando de los pozos de agua de Gadgetzan. \n\nPor la autoridad que me confiere la compañía de aguas de Gadgetzan, te hago entrega de tu recompensa. Nos has prestado un gran servicio a todos nosotros.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2783] = {title = "Peleas mezquinas", objective = "Habla con el héroe caído de la Horda donde Las Tierras Devastadas lindan con El pantano.", description = "Luchamos contra el enemigo equivocado, <nombre>.\n\nEl verdadero poder de estas tierras continúa creciendo en fuerza y número mientras nos peleamos con los orcos por estos terrenos moribundos.\n\n¿No te parece que estamos librando una batalla contra la Horda para un buen día terminar exterminados por los ejércitos de la Legión Ardiente? Es fútil.\n\nDebemos dejar las diferencias de lado, <nombre>, así que habla con el héroe caído de la Horda. Él sabe la verdad que se oculta detrás de Las Tierras Devastadas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2784] = {title = "Pérdida de honor", objective = "Escucha la historia del héroe caído de la Horda.", description = "Esta es mi historia, <raza>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2821] = {title = "La marca de la calidad", objective = "Lleva 10 pellejos de yeti gruesos a Pratt McGrubben al Bastión Plumaluna.", description = "Tengo mi filosofía: en peletería, la calidad del trabajo debe ser la mejor posible, sin excusas. Cualquiera que te diga que la calidad no es importante, está intentando venderte un chalé en primera fila de playa en Dun Morogh.\n\nSiempre estoy buscando materiales de primera calidad y los pellejos de yeti son mi gran hallazgo. Los yetis son criaturas de Feralas. Se encuentran muchos en la Vega Cicatriz Feral. Quiero algunos pellejos. Te daré uno de mis artículos de cuero si me traes 10. Si te parece justo, tenemos un trato.", progress = "Si me traes 10 pellejos de yeti gruesos, te daré uno de mis artículos a elegir. Y como valoro la calidad, ¡puedo asegurarte de que será un buen artículo!\n\nSi no sabes dónde encontrar yetis, puedo indicarte un lugar en el que podrían estar. Busca tierra adentro desde La Costa Olvidada, por la Vega Cicatriz Feral.", completion = "¿Te paraste a examinar la textura de estos pellejos? Con el tratamiento adecuado, podrían ser más fuertes que el hierro. No mucha gente sabe de la existencia de estos pellejos. Eso, combinado con los tratamientos que solo yo conozco, me permitirá crear objetos únicos, con un sello de calidad exclusivo y auténtico... ¡gracias a ti, claro! \n\nY ahora, por favor elige algo de lo que puedo ofrecerte por tus servicios.", rewards = "Botas hechas a mano de PrattGuantes hechos a mano de PrattRecibirás:\n\n"}
MultiLanguageQuestData['mx'][2822] = {title = "La marca de la calidad", objective = "Lleva 10 pellejos de yeti gruesos a Jangdor Zanco Veloz al Campamento Mojache.", description = "Me enorgullezco de mi trabajo de peletería y creo que jamás se debería renunciar a la calidad. Cualquiera que te diga que la calidad no es importante, ¡intentará también convencerte de que la tierra no tiene secretos!\n\nSiempre estoy buscando materiales de primera calidad y en mi búsqueda he descubierto los pellejos de yeti. Los yetis son nativos de Feralas y a menudo se encuentran al oeste de aquí, en la Vega Cicatriz Feral. Te dejaré elegir uno de mis artículos de cuero si me traes 10 pellejos. Si te parece una buena oferta, ¡tenemos un trato!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes hechos a mano de JangdorBotas hechas a mano de JangdorRecibirás:\n\n"}
MultiLanguageQuestData['mx'][2841] = {title = "Las guerras de la plataforma", objective = "Consigue la combinación de la caja fuerte de Termochufe en Gnomeregan y lleva los planos de la plataforma a Nogg a Orgrimmar.|n", description = "Hasta hace dos años, la tecnología gnómica solo servía para echarse unas risas. Las cosas han cambiado mucho; han construido una plataforma mejor que todas las nuestras juntas. ¡Quiero los planos, <nombre>!\n\nEstán en una caja fuerte cerca del mekigeniero Termochufe. Para empeorar las cosas, él es el único que sabe la combinación.\n\nHaz lo que sea por conseguirla, <nombre>. ¡Tienes que abrir la caja y traerme los planos!\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Togas civinadPeto de corredorLeotardos duales reforzadosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][2842] = {title = "Scooty, ingeniero jefe", objective = "Habla con Scooty en Bahía del Botín.", description = "En cuanto Kernobee nos avisó acerca de la plataforma gnómica, Scooty y yo empezamos a trabajar en el Transpoliportador 6000. Es el medio más seguro y rápido para ir a Gnomeregan.\n\nYa está listo para despegar. Si quieres probarlo, <nombre>, ve a Bahía del Botín y habla con Scooty en el Nidal de los Jinetes del Viento. Para ir a Bahía del Botín tienes que tomar el barco en Trinquete.\n\nPor supuesto que puedes ir a Gnomeregan cruzando las montañas de Dun Morogh, que están infestadas de enanos.", progress = nil, completion = "Magnífico, ¿verdad? Es lo mejor de la tecnología goblin, solo ha explotado una docena de veces. \n\nNo te preocupes, &lt;nombre&gt;, ya está arreglado y no explotará. O si lo hace, al menos no te enterarás de nada.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2844] = {title = "El guardián gigante", objective = "Localiza a la elfa de la noche perdida.", description = "No valgo para nada, <nombre>. Se supone que tenía que vigilar a mi amiguita Shay y, no sé cómo, se me perdió. No sé muy bien qué ocurrió, pero la última vez que la vi estábamos andando por las ruinas que hay al norte de aquí.\n\nIba todo bien. Y de repente, me giro... ¡y ella ya no estaba!\n\nNo sé qué hacer... ¿Alguna idea, <nombre>? Estoy terriblemente preocupado.\n\n¡Espera! ¡Tú puedes ir a buscar a Shay! Con tus piernas, irás más rápido que yo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2846] = {title = "Tiara de las profundidades", objective = "Lleva la tiara de las profundidades a Tabetha en el Marjal Revolcafango.", description = "Hace mucho tiempo tenía una bonita joya, la tiara de las profundidades. No solo era hermosa... tenía un gran poder para quien sabía usarlo.\n\nPor eso, cuando la hidromántica Velratha oyó hablar de ella quiso tenerla. Envío a sus agentes a mi hogar y me la robaron cuando estaba fuera. ¡Ladrones!\n\n¡Quiero recuperar mi tiara! Ve a Zul'Farrak, la ciudad trol de Tanaris, encuentra a Velratha y quítale la tiara. Cuando la tengas vuelve a verme y te ganarás mi favor.", progress = "¿Tienes la tiara, <nombre>? ¿Ha aprendido ya Velratha cuál es el precio de contrariarme?", completion = "¡Maravilloso! ¡La encontraste! Y lo que es más importante... ¡Velratha ya no la tiene! Gracias, &lt;nombre&gt;. ¡Te estaré siempre en deuda! \n\nY si antes te pareció que tenía algo de mal humor... no hagas caso. Verás que soy mucho más agradable con aquellos que no me han robado nada.", rewards = "Recibirás:\n\nVara de tramoyista de hechizosEspaldares de pizarra"}
MultiLanguageQuestData['mx'][2854] = {title = "Armadura de cuero salvaje", objective = "Lleva 10 cueros gruesos a Jangdor Zanco Veloz al Campamento Mojache.", description = "<nombre>, tu habilidad como <peletero/peletera> te precede. Yo poseo un conocimiento de la peletería que harías bien en aprender... Por ejemplo, ¡el de la armadura de cuero salvaje! El cuero salvaje aprovecha las potentes y caóticas propiedades de la atriplex salvaje que se encuentra en áreas de exuberante vegetación y en algunas criaturas de la región. Las armaduras que se forjan con ella son las mejores para <un artesano/una artesana> de tu habilidad, te lo garantizo.\n\nTe enseñaré a crearla, pero tendrás que trabajar para mí durante un tiempo. Para empezar, tendrás que traerme 10 piezas de cuero pesado. Ya detallaremos algo más después.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2855] = {title = "Sobrehombros de cuero salvaje", objective = "Lleva 6 refuerzos para armadura gruesos y una atriplex salvaje a Jangdor Zanco Veloz al Campamento Mojache.", description = "Los sobrehombros de cuero salvaje ofrecen una gran protección a la parte superior de los brazos y a los hombros de quien las lleva. Como ocurre con la armadura de cuero salvaje, cuando se cose la atriplex salvaje a las hombreras, esta les imbuye una mejora potente aleatoria.\n\nPara este patrón necesitaré seis refuerzos para armadura gruesa y una atriplex salvaje. No deberías tener problemas para conseguirlos.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPatrón: sobrehombros de cuero salvaje"}
MultiLanguageQuestData['mx'][2856] = {title = "El Jubón de cuero salvaje", objective = "Lleva 2 corazas de caparazón de tortuga, 2 guantes de caparazón de tortuga y una atriplex salvaje a Jangdor Zanco Veloz al Campamento Mojache.", description = "Los jubones de cuero salvaje son la pieza principal de cualquier conjunto de armadura de cuero salvaje. La tela del jubón se amalgama con la atriplex salvaje para crear un producto que ofrece la máxima protección para el torso a la vez que permite que su potente magia se abra paso a través de ella.\n\nPara este patrón, necesitaré 2 petos de caparazón de tortuga, 2 pares de guantes de caparazón de tortuga y 1 atriplex salvaje. No es una lección fácil, pero tú tienes sin duda la habilidad necesaria para aprenderla.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPatrón: jubón de cuero salvaje"}
MultiLanguageQuestData['mx'][2857] = {title = "Casco de cuero salvaje", objective = "Lleva 2 guerreras Nochefugaz, 2 cintas de pelo Nochefugaz y una atriplex salvaje a Jangdor Zanco Veloz al Campamento Mojache.", description = "Un casco de cuero salvaje ofrece a quien lo lleva una gran protección de las áreas vitales de la cabeza sin sacrificar el confort. Como en todas las partes de las armaduras de cuero salvaje, la atriplex salvaje integrada en el casco, le imbuye una potente mejora mágica aleatoria. ¡Quienes aprecian el cuero, sin duda desearán tener esta pieza!\n\nPara este patrón necesitaré dos guerreras Nochefugaz, 2 cintas de pelo Nochefugaz y una atriplex salvaje. ¡Si me traes eso, el patrón será tuyo!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPatrón: casco de cuero salvaje"}
MultiLanguageQuestData['mx'][2860] = {title = "Maestro de cuero salvaje", objective = "Entrega la carta de Jangdor a Una, el maestro curtidor de Cima del Trueno.", description = "<nombre>, ya has aprendido todo lo que yo puedo enseñarte. Pero te queda por aprender un último patrón de la armadura de cuero salvaje. No te pediré que trabajes más, pues ya te has ganado el derecho de aprender este patrón. Pero no es un patrón que sea libre de compartir contigo.\n\nMi profesor, el que me inició en la peletería, es quien debe enseñártelo. Lleva esta nota a Una. Enseña peletería en Cima del Trueno. Muéstrale la carta y te tratará como a <un/Una> igual, como hago yo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPatrón: capa de cuero salvaje"}
MultiLanguageQuestData['mx'][2861] = {title = "La tarea de Tabetha", objective = "Habla con Tabetha en el Marjal Revolcafango.", description = "Se rumorea que Tabetha, una compañera maga que vive en las profundidades del Marjal Revolcafango, tiene que arreglar cuentas con un trol de arena de Zul'Farrak. Si hablas con Tabetha te dirá más.\n\nY lleva contigo algunos amigos, <nombre>. Si Tabetha quiere que vayas a Zul'Farrak no querrás ir <solo/sola>.\n\nEncontrarás la cabaña de Tabetha al oeste de Theramore, al norte de las Ruinas Quebrantarrocas.", progress = nil, completion = "Es cierto. Tengo unas cuentas que arreglar con un trol. Algunas cuentas. ¡Todas! \n\n¿Quieres ayudarme?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2862] = {title = "En guerra con los Zarpaleña", objective = "Lleva 10 cabelleras de gnolls Zarpaleña a Hadoken Zanco Veloz al Campamento Mojache.", description = "Los gnolls... son algo más que una molestia. ¡Son una amenaza constante para este campamento! Que sean o no de Feralas es irrelevante. Si no redoblamos nuestros esfuerzos por controlarlos, acabarán por expulsarnos de la región entera.\n\nLos ataques de los gnolls al campamento se han intensificado últimamente. Necesitamos que nos ayudes a reducir su número. Tráeme 10 de sus cabelleras. Recompensaré generosamente tu esfuerzo.\n\n¡Ve!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2863] = {title = "Ataca a los Alfas", objective = "Mata a 5 Alfas Zarpaleña y vuelve con Hadoken Zanco Veloz en 1 hora.", description = "El plan es para varios líderes de los gnolls, esos que se hacen llamar Alfas. Para acabar con ellos en rápida sucesión. Si logramos ejecutarlo con la rapidez y precisión necesarias, haríamos que cundiera el caos entre sus filas. Y quizás conseguiríamos que en esas estúpidas cabezas piojosas entrara el mensaje de que podemos destruirlos ¡y lo haremos!\n\nQuiero que seas tú <el mensajero/la mensajera> de mi voluntad, <nombre>. Elimina a 5 de sus Alfas en una hora. ¡Si tardas más, el plan no funcionará y empeorarás nuestra situación!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2864] = {title = "Tran'rek", objective = "Habla con Tran'rek en Gadgetzan.", description = "Mi primo Tran'rek está en un aprieto. Me prometió un cargamento de caparazones de escarabajo hace semanas y todavía no lo ha traído. Es mi primo, así que odio tener que enviar a alguien a Gadgetzan para que le eche la bronca.\n\n¿Puedes hablar con Tran'rek por mí? Hazle saber que tiene que conseguir ese cargamento antes de que haga algo malo.\n\nGadgetzan está en el norte de Tanaris, en Kalimdor.", progress = nil, completion = "¡Hola! \n\nOh, ¿hablaste con mi primo Krazek? ¿Cómo está? Espero que le vaya bien en Bahía del Botín... \n\n¿Caparazones de escarabajo dices? Bien... cuéntame tu historia...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2865] = {title = "Caparazones de escarabajo", objective = "Lleva 5 caparazones de escarabajo sin rajar a Tran'rek en Gadgetzan.", description = "¡Los escarabajos de Tanaris tienen unos caparazones muy duros! Tan duros que se pueden utilizar para construir muchas cosas. ¡Muchísimas!\n\nDe hecho, esos caparazones son tan útiles y cazamos tantos escarabajos... ¡que casi se han extinguido!\n\nSé dónde hay más escarabajos, y si me prometes traerme sus caparazones te diré dónde están. ¿Prometido?\n\nMuy bien, hay una colonia de escarabajos en Zul'Farrak. Supongo que los trols no los cazan en busca de caparazones.\n\n¡Pero tú sí! ¡Ve a Zul'Farrak y consígueme caparazones sin rajar!", progress = "¿Tienes los caparazones? Mi primo de Bahía del Botín sigue esperando el cargamento, ¡y se está impacientando!", completion = "¡Oh, genial! ¡Los conseguiste! \n\nGracias, &lt;nombre&gt;. ¡Eres un auténtico salvavidas!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2866] = {title = "Las Ruinas de Solarsal", objective = "Explora las Ruinas de Solarsal e investiga la presencia de los nagas allí.", description = "Al sur de aquí están las Ruinas de Solarsal, una zona que ya era antigua antes de nuestro tiempo. Exploramos las ruinas en su momento y no encontramos nada relevante, así que no volvimos a enturbiar la paz del lugar.\n\nHace poco, los nagas Crestafuria han ocupado las ruinas en número alarmante. Al principio, lo interpretamos como el anuncio de un ataque. Aún consideramos esa posibilidad, pero además, creemos que podría estar ocurriendo alguna otra cosa.\n\nVe a explorar las ruinas y busca cualquier cosa que te llame la atención. Buena suerte, <nombre>.", progress = nil, completion = "Un examen minucioso de la glorieta revela tres cosas interesantes y poco habituales que contrastan con las ruinas que la rodean. \n\nPrimero, la glorieta es evidentemente más reciente que las demás estructuras de las ruinas. Segundo, tiene una serie de glifos pequeños grabados en los lados. Los glifos parecen repetirse, pero su significado y su origen son desconocidos. Tercero, la piedra de la glorieta está caliente al tacto. \n\n¡Esto es sin duda algo que \"llama la atención\"!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2867] = {title = "Regresa al Bastión Plumaluna", objective = "Vuelve al Bastión Plumaluna e informa a Shandris Plumaluna del resultado de tu exploración.", description = "Tras descubrir la extraña glorieta en el corazón de las Ruinas de Solarsal, sabes que ha llegado el momento de regresar al Bastión Plumaluna e informar a la general Shandris Plumaluna del resultado de tu exploración.", progress = nil, completion = "Bienvenido, &lt;nombre&gt;. Tu informe sobre la glorieta es... preocupante. Parece que, aunque los nagas no estuvieran planeando un ataque, su presencia es una mala señal para nuestra ofensiva en Feralas. En cualquier caso, aquí tienes tu compensación por tu servicio. \n\nParece que el Bastión Plumaluna necesita desesperadamente ayuda con el problema de los nagas Crestafuria. Quisiera ofrecerte a ti la misión, si te parece. Hay mucho que hacer.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2870] = {title = "En contra de Lord Shalzaru", objective = "Elimina a Lord Shalzaru y luego lleva la reliquia misteriosa que desenterró a Latronicus Lanzaluna al Bastión Plumaluna.", description = "<nombre>, nos han llegado informes de los exploradores que nos han dado una buena idea de cómo es la cadena de mando de los nagas. Entre sus filas hay Regios, que son los que mandan.\n\nEn concreto, hemos identificado a uno de los regios más crueles: Lord Shalzaru. Según mis exploradores, él en persona ha desenterrado una extraña reliquia en una excavación naga de una cueva del sur de las ruinas principales, en la Isla del Terror.\n\nAcaba con él y tráeme esa reliquia para que podamos estudiarla.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2872] = {title = "La deuda de Stoley", objective = "Habla con Stoley en el Puerto Bonvapor.", description = "Mi viejo amigo Stoley me debe una botella muy especial de ron. Él atiende el bar del Puerto Bonvapor en Tanaris, Kalimdor, y me aseguró que el ron allí es más fuerte que cualquier cosa que podamos encontrar en Bahía del Botín. Está tan seguro de lo que dice que prometió darme el doble de dinero del que me debe si después de probarlo no opino lo mismo.\n\nBueno, yo creo que ahora ya no está tan seguro como en su día y no quiere que pruebe el ron. Sin embargo, yo nunca me echo atrás ante una apuesta, así que por qué no vas a hablar con él...", progress = nil, completion = "Ah, has estado hablando con MacKinley, ¿no es cierto? \n\n¡No es lo que él piensa! No tengo miedo de dejarle probar el ron de la sentina Bonvapor... \n\n¡Simplemente no me queda ni gota!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2873] = {title = "El envío de Stoley", objective = "Llévale el envío de Stoley a Stoley, que está en el Puerto Bonvapor.", description = "Le debo algo de ron a \"Lobo de Mar\" MacKinley de Bahía del Botín por una apuesta, ¡pero no me queda ni gota! El capitán Cuergo robó mi último cargamento y lo escondió en esa ciudad pirata amurallada situada al sur.\n\nSi encuentras mi cargamento de ron y me lo devuelves, quizás pueda demostrarle a MacKinley que el ron de Bahía del Botín no le llega a este ni a la suela del zapato.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2874] = {title = "Un envío para MacKinley", objective = "Llévale la botella de Stoley a \"Lobo de Mar\" MacKinley, en Bahía del Botín.", description = "Gracias de nuevo por tu ayuda, <nombre>. Aquí tienes una botella de ron de la sentina Bonvapor. Llévasela a MacKinley para que pueda comprobar por fin lo que se dice del ron de Bahía del Botín.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Fajín de espadachínBotas lustrosasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][2875] = {title = "SE BUSCA: Andre Barbafuego", objective = "Llévale la cabeza de Andre al jefe de seguridad Pasaquillas, que está en el Puerto Bonvapor.", description = "Se busca al malvado pirata Andre Barbafuego por crímenes contra Bonvapor y Gadgetzan.\n\nPor decreto del consejo de gobierno, todo el que lea esto tiene autorización expresa para utilizar fuerza letal durante la ejecución del arresto de Andre y sus cómplices.\n\nPor nuevo decreto, de producirse el fallecimiento de Andre o de sufrir este algún tipo de perjuicio durante la sesión de interrogatorio posterior a su detención, su cabeza actuará como prueba irrefutable de este hecho y su entrega ante el jefe de seguridad Pasaquillas constituye contrato vinculante.", progress = "Pareces un tanto aturdido. ¿Has estado leyendo nuestros documentos legales?", completion = "¡Ah, la cabeza de Andre! ¡Supongo que al final recibió su merecido! \n\nMuchas gracias, &lt;nombre&gt;. Y ahora si me firmas aquí, te pagaré por los servicios prestados. \n\nNo te preocupes por la letra pequeña, no pone nada interesante y... de todos modos, no creo que exista una lupa lo suficientemente buena como para poder leerla.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2876] = {title = "El registro náutico", objective = "Informa del registro de envíos a alguna autoridad del Puerto Bonvapor.", description = "Este pergamino contiene el registro de envíos realizados entre el Puerto Bonvapor y Bahía del Botín. Están incluidos tanto los envíos ya hechos como los pendientes, así como los nombres de los barcos, algunos con una X al lado y otros con anotaciones del tipo \"GRAN BOTÍN\" y \"DURA LUCHA\".\n\nSeguro que hay alguien en el Puerto Bonvapor interesado en echarle un vistazo a este documento.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2877] = {title = "La limpieza de Roca Oculta", objective = "Mata 10 lodos verdes y 10 mocos de jade e informa a Fraggar Mantrueno en Pico Nidal.", description = "Los Martillo Salvaje recordamos el pasado mejor que nuestros hermanos de Forjaz. ¡Si quieres hacer amigos aquí, tendrás que ensuciarte las manos!\n\nLa Horda ha abandonado sus puestos de Roca Oculta en las Tierras del Interior; ahora todo está infestado de babosas y mocos. Tenemos planes para la región, pero antes hay que enviar una brigada de limpieza.\n\n¡Ese es tu trabajo, hermosura! Ve allí y elimina 10 lodos verdes y 10 mocos de jade. ¡Andando!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2880] = {title = "Los collares de trols", objective = "Lleva 5 collares tribales trol a Fraggar Mantrueno a Pico Nidal.", description = "Que quede claro, <raza>: ¡NO formamos parte de la Alianza! Los Martillo Salvaje somos independientes, creemos que el valor se tiene que probar con actos y no con bonitos discursos.\n\n¡Si quieres que te aceptemos, tendrás que probar tu valía! Esos inmundos trols que ensucian las Tierras del Interior suelen llevar collares tribales. Tráeme cinco y lo consideraremos un acto de buena voluntad hacia nosotros.", progress = "Quiero 5 collares tribales trol. Y la forma más efectiva y segura de quitárselos es matarlos.\n\n¡Demuestra lo que vales a los Martillo Salvaje!", completion = "Con estos collares nos demuestras tu valor; los Martillo Salvaje apreciamos el coraje. \n\nSigue así y llegarás lejos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2881] = {title = "Los collares de trols", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][2882] = {title = "El oro de Cuergo", objective = "¡Encuentra el oro de Cuergo!", description = "Este mapa muestra un trecho de playa orientado hacia el sur. Debajo del mapa hay unas palabras escritas de manera elegante...\n\nMás al sur de Bonvapor\nAl sur del lar de tu corazón\nEncontrarás huesos, mástil y bandera\nExcava allí si tienes alma aventurera\nExcava y el oro de Cuergo reclama\nUna llave necesitarás y una llave encontrarás\nLos hombres a los que te enfrentarás\nen sangre pagarás.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nTesoro escondido de Cuergo"}
MultiLanguageQuestData['mx'][2902] = {title = "Investiga a los Zarpaleña", objective = "Encuentra los planes de batalla de los gnolls por los campamentos que hay al sur del Campamento Mojache.", description = "Los gnolls no son los tipos más rápidos del lugar, pero seguramente tendrán algún tipo de documentación sobre sus actividades. Si encontráramos sus planes, podríamos tener una idea más clara de lo que les está agitando tanto.\n\nQuiero que vuelvas a Zarpaleña y busques cualquier cosa que pueda parecer un plan de batalla. Tienen que tener algo: sus ataques han sido demasiado coordinados, han tenido que seguir un plan. Encuentra la documentación de sus planes y vuelve cuando la tengas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2904] = {title = "Un buen lío", objective = "Acompaña a Kernobee a La Rampa del Engranaje y luego ve a ver a Scooty a Bahía del Botín.", description = "<Kernobee gruñe.> ¿Qué...? ¿Qué ha pasado?\n\nSolo recuerdo que me capturó un grupo de enanos Hierro Negro, me dieron una paliza de muerte y me echaron aquí, con estos asquerosos troggs.\n\n¡Sácame de aquí, <nombre>!\n\nEste es el plan: llévame a la salida; si sobrevivimos, tú te vas a la Bahía del Botín y le dices a Scooty que he ido a Trinquete para avisar a Manitas de Oro que los Hierro Negro están metidos en lo de la superplataforma.\n\n¡Andando!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Brazales soldados con fuegoManto alas de hadaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][2922] = {title = "¡Salva el cerebro de Tecnobot!", objective = "Lleva el procesador central de memoria del Tecnobot al maestro manitas Sobrechispa a Forjaz.", description = "Supongo que mi pobre Tecnobot recibió algún chispazo perdido cuando cayó nuestra amada Gnomeregan. Antes nos era muy útil gracias a sus incontables funciones y su capacidad ilimitada de almacenaje de información, pero su cerebro positrónico se ha polarizado. Ahora es negatrónico y la conducta del Tecnobot se ha invertido. ¡Anda descontrolado por Gnomeregan!\n\nPero quizás podamos recuperarlo. Si me trajeras el procesador central de memoria del Tecnobot, podría descubrir la causa de la polarización y repararlo.\n\n", progress = "¿Encontraste al Tecnobot? ¿Tienes el procesador central de memoria?", completion = "¡Excelente! ¡Gracias, &lt;nombre&gt;, voy a ponerme a trabajar de inmediato! \n\nPobre Tecnobot, vaya susto te has llevado. \n\nEnseguida te arreglo; a ver, dónde estará mi llave de tuerca giratoria con gato hidráulico...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2923] = {title = "Maestro manitas Sobrechispa", objective = "Habla con el maestro manitas Sobrechispa en Forjaz.", description = "El maestro manitas Sobrechispa está muy disgustado con lo ocurrido a su obra mecánica, el Tecnobot. Por lo que sé, el Tecnobot era una herramienta muy útil para los gnomos, pero dice que se ha averiado.\n\nLástima. ¡Aunque con suerte se podrá arreglar!\n\nVe a hablar con Sobrechispa a Ciudad Manitas, en Forjaz. Se alegrará de que vayas a ayudarlo.", progress = nil, completion = "Sí, hemos perdido el control del Tecnobot. ¿Puedes ayudarme?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2924] = {title = "Esencias artificiales", objective = "Lleva 12 esencias artificiales a Klockmort Palmalicate a Forjaz.", description = "Los herreros y manitas de Gnomeregan usaban un componente mecánico casi universal, la esencia artificial, en su trabajo. Pero durante la huida de la ciudad, ¡nadie pensó en recoger esencia! Necesitaré mucha para un trabajo que estoy a punto de empezar.\n\nTe ruego que vayas a Gnomeregan a conseguirme esencia artificial. Está en las zonas más profundas de la ciudad, en unos contenedores que se llaman extrapoladores artificiales.\n\n¡Date prisa y muchas gracias, <nombre>!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2925] = {title = "Klockmort Palmalicate", objective = "Habla con Klockmort Palmalicate en Forjaz.", description = "Klockmort Palmalicate, un amigo gnomo, me ha enviado un mensaje desde Forjaz. Dice que necesita ayuda en una misión peligrosa pero crucial en Gnomeregan, la gran ciudad hoy contaminada e invadida por gnomos dementes y sus aparatos.\n\nYo debo quedarme aquí, pero quiero ayudar a mi amigo. Si vas en mi lugar tendrás mi agradecimiento eterno.\n\nEncontrarás a Klockmort en Ciudad Manitas, en Forjaz.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2926] = {title = "Gnogaine", objective = "Usa la ampolla de plomo con invasores o saqueadores radiactivos para recoger restos radiactivos. Cuando esté llena, llévasela a Ozzie Voltiflop a Kharanos.", description = "Desde el accidente, Gnoarn no piensa en otra cosa que en expulsar a los troggs de Gnomeregan y encontrar una cura para la plaga. <nombre>.\n\nPor suerte, Razzle y yo estamos a punto de conseguirlo; o eso, o hemos destilado un ron muy potente. ¡No lo sabremos hasta que lo probemos! Claro que para poner a prueba nuestra teoría, necesitamos algunas cosas, como restos de los troggs radiactivos en Gnomeregan. ¡Llena este frasco de material verdoso radiactivo y tráelo!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2927] = {title = "Al día siguiente", objective = "Ve a hablar con Ozzie Voltiflop en Kharanos, en Dun Morogh.", description = "¿Crees que siempre he sido calvo? ¡Pues no <señor/señorita>! Perdí todo el pelo por culpa de la fuga radiactiva de Gnomeregan. Hasta entonces, tenía una mata de pelognomo única en todo Azeroth.\n\n<Sacude los puños.>\n\n¡Así se pudran esos malditos troggs en las simas del averno!\n\nA lo mejor no es tarde, <nombre>. Aún podemos salvarla. ¡A la ciudad, me refiero! Ve a hablar con Ozzie Voltiflop en Kharanos. Está buscando una solución con su colega Razzle.", progress = nil, completion = "Creí que no soportaría la pérdida de su preciosa melena, ¡pero sobrevivió!\n\nEstábamos juntos cuando le cayó la descarga de radiación. Aquellos encantadores mechones empezaron a caérsele a montones. ¡A puñados! La situación se agravó cuando a Gnoarn le entró el pánico... ¡Te juro que se volvió loco! ¡Empezó a tocarse la cabeza, incrédulo, se le pusieron los ojos rojos y juró venganza, &lt;nombre&gt;! Desde entonces la tomó con los troggs.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2928] = {title = "Excavadoras gyroagujereamáticas", objective = "Lleva veinticuatro entrañas robomecánicas a Shoni en Ventormenta.", description = "Es terrible, <nombre>. No vamos a tener suficientes repuestos para llevar nuestra flota de excavadoras gyroagujereamáticas a Dun Morogh.\n\nLo que necesitamos son repuestos, <nombre>. ¿Y qué mejor lugar que Gnomeregan para conseguir repuestos para nuestros vehículos? He oído que robots y mecazancudos vagan libremente por ese lugar.\n\nNecesito que vayas a Gnomeregan y destruyas a esos robots. Tráeme sus entrañas robot. Con dos docenas tendré suficiente.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Herramienta de desarme de ShoniMitones llamativosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][2929] = {title = "La gran traición", objective = "Ve a Gnomeregan y mata al mekigeniero Termochufe. Ve a ver al Manitas Mayor Mekkatorque cuando hayas terminado.", description = "Yo confiaba en Termochufe, <raza>. Nunca pensé que me traicionaría a mí y a todos los gnomos. ¿Y por qué? ¿Por el poder? ¿Por el dinero? Habría conseguido todo eso por sí mismo. Ahora nos han echado de nuestro hogar y ese chiflado es el que manda. Rey de pacotilla...\n\nVamos a recuperar Gnomeregan, <nombre>. No cejaremos hasta que la ciudad vuelva a nuestras manos. Si quieres ayudarnos, tengo un trabajito para ti. Mata al traidor. Acaba con el mekigeniero Termochufe.", progress = nil, completion = "Cuéntame otra vez cómo le aplastaste el cráneo con la bota, &lt;raza&gt;. Ahora que Termochufe ha muerto, estamos más cerca de recuperar Gnomeregan.|n", rewards = "Togas civinadPeto de corredorLeotardos duales reforzadosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][2930] = {title = "Rescatar los datos", objective = "Lleva una tarjeta perforada prismática al maestro mecánico Funditubo a Forjaz.", description = "¡Cuando tuvimos que huir de Gnomeregan, dejamos atrás información muy valiosa! ¡Qué digo, valiosa! ¡Vital!\n\nNecesito los datos de la tarjeta perforada prismática de un Perforágrafo Matriz 3005-D de alta seguridad oculto en Gnomeregan. Tienes que acceder a la terminal, pero para eso necesitas un permiso... Y para eso tienes que acceder a una terminal de baja seguridad de los modelos -A, -B y -C. Y para eso, necesitas tarjetas perforadas de seguridad en blanco... y todas se quedaron en la ciudad.\n\n¡Qué desastre! ¿Puedes ayudarme?Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nManteo de mecánicoMartillo de mecánico"}
MultiLanguageQuestData['mx'][2931] = {title = "Trabajar para Funditubo", objective = "Habla con el maestro mecánico Funditubo en Forjaz.", description = "¡El maestro mecánico Funditubo de Forjaz busca gente aventurera! Quiere volver a Gnomeregan para recuperar datos; es una misión muy importante.\n\nAunque no sea miembro de la Asamblea Iluminada de Arcanología, alquimia e Ingeniería como yo, es un gnomo inteligente, así que si piensa que algo es importante, según mis cálculos hay un 48 por ciento de posibilidades de que, en efecto, sea importante.\n\n¡Es una probabilidad muy alta!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2932] = {title = "Un mensaje siniestro", objective = "Recoge cráneos Secacorteza y luego clava la pica cargada de Nimboya en uno de los poblados Secacorteza, en las Tierras del Interior. Luego ve a ver a Nimboya a Tuercespina.", description = "Los trols Secacorteza fueron aliados de la Horda, ¡pero traicionaron a Thrall y deben ser castigados!\n\nToma mi pica y vete a las Tierras del Interior. Están al noreste de Molino Tarren, que está bajo control de nuestros aliados, los Renegados.\n\nCuando llegues, busca trols Secacorteza. Recoge sus cráneos y clava mi pica en el suelo en uno de sus poblados más pequeños, Hiri'watha o Zun'watha.\n\n¡Que aprendan que sus ruines acciones tienen consecuencias!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2933] = {title = "Botellas de veneno", objective = "Lleva una botella de veneno a algún boticario de Molino Tarren.", description = "En estas botellas hay un veneno verde e infame.\n\nVista la cantidad de botellas que hay en el poblado, los Secacorteza deben de considerarlo muy importante. A lo mejor algún boticario de Molino Tarren estaría interesado en esto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2935] = {title = "Consulta al maestro Gadrin", objective = "Habla con el maestro Gadrin en el Poblado Sen'jin.", description = "El veneno de las guardias del linaje no era tan potente como el que me trajiste primero. Debía de ser de otra araña.\n\nQuiero que me traigas más de ese veneno. Para averiguar de dónde viene, ve al Poblado Sen'jin y habla con el maestro Gadrin. Es un trol que conoce bien a los Secacorteza. Ve a Durotar y habla con Gadrin. Con un poco de suerte, sabrá de dónde sacan el veneno los Secacorteza.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2936] = {title = "Diosa araña", objective = "Lee el nombre de la diosa araña de los Secacorteza en la tablilla de Theka y vuelve a ver al maestro Gadrin.", description = "Los Secacorteza adoran a una diosa araña, de la cual extraen su veneno más potente. Así que, si quieres el veneno, ¡tienes que invocar a la diosa!\n\nPara ello debes conocer su verdadero nombre, inscrito en una tablilla enterrada en Tanaris, en la ciudad trol de Zul'Farrak, en una tumba custodiada por el Mártir Theka.\n\nDerrótalo y lee el nombre en la tablilla. Después, vuelve.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2937] = {title = "Invocar a Shadra", objective = "Derrota a Shadra en el altar de Shadra'Alor y lleva su veneno al boticario Lydon de Molino Tarren.", description = "Lee este papiro en el altar de Shadra'Alor, que está escondido en el reino de los Secacorteza, en las Tierras del Interior. Así invocarás a Shadra, la diosa araña.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2939] = {title = "La búsqueda del conocimiento", objective = "Habla con Daryn Brisela de la Aldea Rut'theran.", description = "Las ruinas de Feralas pueden ser muy peligrosas, pero tienen mucho que decir acerca de lo que aquí pasó.\n\nEntre los escombros, hace unos días, descubrí lo que parecía ser un báculo normal y corriente. Sin embargo, creo que hay algo en él. Angelas y yo hemos estado leyendo buscando algo al respecto, pero no aparece nada.\n\nTengo una amiga en Darnassus que nos podría decir lo que es, <nombre>. ¿Por qué no vas a verla y le preguntas si nos ayuda?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2944] = {title = "La Superinstantánea FX", objective = "Utiliza la Superinstantánea FX para sacar una instantánea de Gammerita y luego vuelve a la Aldea Rut'theran con Daryn Brisela.", description = "Echa un vistazo a mi nuevo invento, <nombre>. Lo único que hay que hacer es apuntar a lo que quieras retratar y pulsar el botón.\n\n¿Cuál era esa criatura de las Tierras del Interior que mencionaste? ¿Gammerita? Pues espero que la encuentres. Buena suerte. Estoy segura de que Daryn quedará satisfecha con la instantánea que le llevas.\n\nEn cualquier caso, ¡aquí tienes la Superinstantánea! ¡Diviértete!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2945] = {title = "Un anillo sucio", objective = "Encuentra la manera de limpiar el anillo sucio.", description = "Has encontrado algo que parece un anillo en el cadáver de un enano Hierro Negro. Está cubierto de barro y restos secos y endurecidos, por lo que no se puede llevar ni se puede ver qué tipo de anillo es. Entre el barro, te parece entrever el brillo de metal precioso y quizás una gema.\n\nSi quieres ponértelo, tendrás que encontrar la manera de limpiarlo.Cuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][2948] = {title = "Mejora gnómica", objective = "Lleva tu anillo de oro luminoso, una barra de plata, una ágata musgosa y 30 monedas de plata a Talvash del Kissel a Forjaz.", description = "Oye, <nombre>, ¡puedo hacerte un anillo mejor que el que llevas! Como decía, ese diseño es muy sencillo. Ahora soy mucho mejor, así que por 30 monedas de plata de nada mejoraré tu anillo. Bueno, en realidad, es algo más de 30...\n\nAhora mismo estoy sin material. ¡Si me traes una barra de plata y una ágata musgosa, las usaré para añadir detalle a tu anillo y darle otro aire!\n\nConfía en mí.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAnillo de oro de Talvash"}
MultiLanguageQuestData['mx'][2949] = {title = "La devolución del anillo", objective = "Puedes quedarte el anillo o buscar a quien realizó los grabados de la parte interior.", description = "¡Al abrir la caja del Destellamatic 5200 verás un anillo reluciente! Cuando te lo pongas sentirás que te recorre una fuerza mágica.\n\nEn la parte interior está grabado, pequeño pero legible, el sello de Orgrimmar. Junto al sello hay algo más, pero incluso después de limpiar el anillo, solo se lee: \"NOG...\"\n\nPueden ser las iniciales del dueño o las del artesano que forjó el anillo. Quédate con el anillo o busca a \"NOG\". Tú verás...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2950] = {title = "Nogg mejora el anillo", objective = "Lleva tu anillo de oro luminoso, una barra de plata, una ágata musgosa y 30 monedas de plata a Nogg a Orgrimmar.", description = "No, no es que de pronto haya decidido que el anillo es mío. Normalmente no hago estas cosas, pero tu información sobre los Hierro Negro me ha sido muy útil. Mejoraré tu anillo de una forma que nunca se le habría ocurrido a su creador. Seguro que era un gnomo...\n\n¡Si me traes una barra de plata y una ágata musgosa, además de 30 monedas de plata, añadiré detalle a tu anillo y reforzaré su magia! ¿Te interesa la cosa?Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAnillo de oro de Nogg"}
MultiLanguageQuestData['mx'][2951] = {title = "¡El Destellamatic 5200!", objective = "Inserta un objeto con mugre incrustada en el Destellamatic 5200 y asegúrate de tener 3 monedas de plata a mano.", description = "Este aparato destaca entre los gnomos que se mantienen firmes frente a la locura que acecha fuera de la sala. Tiene una plaquita que dice: \"Destellamatic 5200\" y:\n\n\"¿La suciedad arruina sus destellos? ¡El Destellamatic 5200 devuelve el brillo de forma brillante! Inserte el objeto que desea limpiar e introduzca tres monedas de plata en la ranura. Espere unos momentos, ¡y ya está! ¡Sus objetos de valor aparecerán limpios y resplandecientes!\"", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][2952] = {title = "¡El Destellamatic 5200!", objective = "El Destellamatic 5200 se para tan bruscamente como había arrancado. Se oye un simple \"ping\" y se abre la boca de la máquina. Dentro del Destellamatic 5200 hay una cajita con un lazo. Parece que la máquina envuelve los objetos después de limpiarlos. Incluso si la máquina no ha funcionado, al menos ahora el objeto está envuelto en una linda cajita.\n\nBueno, solo hay una forma de saber si el objeto está bien limpio...", description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nCaja envuelta del Destellamatic"}
MultiLanguageQuestData['mx'][2953] = {title = "El Destellamatic en acción", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nCaja envuelta del Destellamatic"}
MultiLanguageQuestData['mx'][2954] = {title = "El vigía de piedra", objective = "Averigua qué quiere el vigía de piedra de Norgannon y después interactúa con el pedestal de Uldum en el Desierto de Tanaris.", description = "\"Saludos, soy un guardián de la entrada. A menos que ya tengas las Placas de Uldum integradas con los discos, no permitiré tu entrada en Uldum.\"\n\nLa aparición del vigía de piedra de Norgannon debe ser el objetivo de haberte enviado al desierto de Tanaris con los discos de platino. Para poder continuar, deberás escuchar lo que el vigía de piedra tenga que contarte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2962] = {title = "Necesitamos más material verdoso", objective = "Viaja hasta Gnomeregan y recupera los restos radiactivos de gran potencia. Pero ten cuidado, ya que es inestable y podría explotar en cualquier momento.\n\nOzzie también quiere que traigas la ampolla pesada de plomo una vez que hayas terminado el trabajo.|n", description = "Tu muestra no solo era insuficiente en cuanto a cantidad, además era impura.\n\nNecesitamos más material verdoso radiactivo. Es evidente que los troggs no han sido suficientemente irradiados. Tendrás que ir a Gnomeregan y traer restos radiactivos, directamente de la fuente. Estoy hablando de babosas, rondadores y horrores irradiados. Y ten cuidado: contener este tipo de restos es difícil. Es posible que tengas que hacer varios intentos hasta que hayas reunido una muestra adecuada.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2963] = {title = "Presagios de Uldum", objective = "Habla con Karnik el Historiador en la Sala de los Expedicionarios de Forjaz.", description = "¡Saludos de nuevo, <nombre>! Lo que descubriste en Uldaman ha interesado muchísimo a la Liga de Expedicionarios. Están intentando descifrar los discos de platino en miniatura que encontraste. ¡Deja que te diga que probablemente sea algo importante!\n\nKarnik el Historiador ha descubierto pistas importantes sobre los verdaderos orígenes del Valle de los Vigías en el Desierto de Tanaris. Quiere hablar contigo lo antes posible.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2965] = {title = "Presagios de Uldum", objective = "Habla con Nara Ferocrín en el Alto de los Ancestros de Cima del Trueno.", description = "Ah, <nombre>, qué casualidad que hayas vuelto a mí. Tus descubrimiento en la excavación de Uldaman nos han dado mucho de qué hablar a los sabios. De hecho, estaba discutiendo con una druida llamada Nara Ferocrín cuando caí en la cuenta de que sus antiguos viajes podrían resultar importantes para el próximo paso que hemos de dar.\n\nMe gustaría que fueras a hablar con ella acerca de sus viajes al Valle de los Vigías en el Desierto de Tanaris. Ella te está esperando en el Alto de los Ancestros.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2966] = {title = "A ver qué pasa", objective = "Lleva los discos de platino en miniatura a las puertas de Uldum, en Tanaris. Busca pistas sobre la conexión entre discos y puertas.", description = "A Sabio Buscador de la Verdad y a mí nos gustaría que llevaras los discos en miniatura que encontraste a las puertas selladas de Uldum. No estamos seguros de qué pasará, la verdad.\n\nSabemos que la operación entraña un riesgo. Aunque puede que no ocurra nada. Puede que tengas que usar los discos de algún modo. Es posible que las puertas se abran si llevas los discos. Mantén una actitud abierta y prepárate para cualquier cosa.\n\nCuando averigües lo que pasa vuelve a verme. Tendremos mucho de qué hablar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2967] = {title = "Regresa a Cima del Trueno", objective = "Habla con Nara Ferocrín en Cima del Trueno.", description = "Accedes de nuevo al pedestal y los discos de platino aparecen de repente en tu mochila.\n\nCon lo que te ha enseñado el vigía de piedra y los discos de platino de nuevo en tu poder, ha llegado el momento de regresar a Cima del Trueno e informar a Nara Ferocrín de tu hallazgo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2969] = {title = "Libertad para todas las criaturas", objective = "Utiliza la llave de jaula de bambú para liberar a los duendes dardo del campamento Tótem Siniestro. Deben sobrevivir al menos 6 duendes dardo y Kindal Tejeluna.\n\nTienes 6 minutos antes de que Kindal decida que es hora de retirarse, entonces tu misión fracasará.", description = "Esos asquerosos del clan Tótem Siniestro están capturando dragones feéricos, <nombre> Jer'kai y yo no sabemos qué están planeando hacer con ellos, pero está claro que no es nada bueno.\n\nY no podemos entrar en el campamento a liberar a los dragones a brazo partido, pero quizás, con tu ayuda...\n\nSi quieres ayudar y tienes amigos fuertes, libera a las criaturas de sus jaulas con esta llave y asegúrate de que logran escapar. Yo estaré a tu lado todo el tiempo. Jer'kai se quedará aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2972] = {title = "La justicia del castigo", objective = "Lleva el sello de Jer'kai a la suma sacerdotisa Tyrande Susurravientos a Darnassus.", description = "Kindal y yo no tenemos aquí los medios para recompensar tu ayuda, pero no queremos que sientas que no la apreciamos. Llévate mi sello. Si alguna vez te encuentras en Teldrassil, ve al Templo de la Luna que está en el corazón de Darnassus. Allí encontrarás a la suma sacerdotisa Tyrande Susurravientos. El sello le hará saber que nosotras estamos bien y dará crédito a tu historia.\n\nAmbas te damos las gracias, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Braciles de abeto y sauceFaja de escama nocturnaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][2973] = {title = "El lustre de una nueva capa", objective = "Lleva 10 alas de duende dardo iridiscente a Krueg Machacacráneos al Campamento Mojache.", description = "Saludos, <clase>. He viajado con mis compañeros hasta Feralas en una misión de nuestros maestros de Orgrimmar.\n\nMi compañera Korrin adora la ropa nueva, así que voy a hacerle una nueva capa adornada con las ligeras alas de los dragones feéricos. ¿Podrías ayudarme? Los duendes dardo con las mejores alas están al oeste del Campamento Mojache.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2974] = {title = "Un descubrimiento siniestro", objective = "Lleva 20 cuernos de Tótem Siniestro a Krueg Machacacráneos en el Campamento Mojache.", description = "¡¿Qué?! ¿Que te has cruzado con tauren en esta zona? ¡Será broma! ¡¿Qué aspecto tenían?!\n\n¡El clan Tótem Siniestro! ¿Te has encontrado con ellos? Belgrom, uno de nuestros maestros, tiene un gran interés por ellos... ¡Hasta ha ofrecido una recompensa!\n\nTienes que volver, <clase>. Vuelve y tráeme sus cuernos... Tráeme montones de ellos, todos los que puedas. Pero no subestimes a los Tótem Siniestro. Ve con cuidado. Vuelve y mátalos, deja que los ríos de Feralas bajen enrojecidos con su sangre oscura.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2975] = {title = "Los ogros de Feralas", objective = "Rok Orhan del Campamento Mojache quiere que mates a 10 ogros Gordunni, 10 magi ogro Gordunni y 5 toscos Gordunni.", description = "Los efectos de la invasión de la tribu Gordunni no pasan desapercibidos en la zona. Mira a tu alrededor, <nombre>; su mera presencia marca esta tierra. Debemos hacerles retroceder antes de que empiecen a extenderse por todo Feralas.\n\nSigue el río hacia el norte y encontrarás su puesto de avanzada. Reduce su número, <nombre>. Debemos hacerles ver que no son bienvenidos aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2976] = {title = "Un descubrimiento siniestro", objective = "Lleva el cajón de cuernos de Tótem Siniestro a Belgrom Destrozarroca a Orgrimmar.", description = "¡¿Qué?!\n\nAh, así que te hablé de la recompensa... Eso me pasa por abrir la bocaza, no aprenderé nunca.\n\nBueno, supongo que, como tú hiciste el trabajo duro, es justo que recibas la recompensa. Llévate los cuernos. Yo haré que te los metan en una caja. Busca a Belgrom Destrozarroca en el Valle del Honor. Querrá saber qué viste y te recompensará por tu duro trabajo.\n\nCuídate, <clase>, y gracias de nuevo por todo.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Manteo de batalla duraPodrás elegir una de estas recompensas:\n\nOrbe Luna de jade\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][2977] = {title = "Regresa a Forjaz", objective = "Habla con Karnik el Historiador de Forjaz.", description = "Accedes de nuevo al pedestal y los discos de platino aparecen de repente en tu mochila.\n\nCon lo que te ha enseñado el vigía de piedra y los discos de platino de nuevo en tu poder, ha llegado el momento de regresar a Forjaz e informar a la Liga de Expedicionarios de tu hallazgo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2978] = {title = "El pergamino Gordunni", objective = "Lleva el pergamino Gordunni a Rok Orhan al Campamento Mojache.", description = "Cuando recoges el sucio pergamino, notas que parece describir algún tipo de reunión o ceremonia. A Rok Orhan le interesará este pergamino por lo que pueda significar para los Gordunni.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2979] = {title = "Una ceremonia oscura", objective = "Rok Orhan del Campamento Mojache quiere que encuentres 1 orbe Gordunni.", description = "Parecen ser planes para algún tipo de ceremonia oscura, <nombre>. Por lo que puedo entender, este es un ritual celebrado por los Señores de la Magia Gordunni.\n\nEncuentra a uno de estos Señores de la Magia y quítale su orbe.\n\nEl orbe de un mago encierra un gran poder. Nos ayudará a descubrir más sobre esta ceremonia y sobre la magia de los Gordunni.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2980] = {title = "Los ogros de Feralas", objective = "Rok Orhan del Campamento Mojache quiere que mates a 10 chamanes Gordunni, 10 brujos Gordunni y 5 aplastadores Gordunni.", description = "Ahora que has demostrado que eres <un auténtico guerrero/una auténtica guerrera>, confío en que tengas el valor para continuar tu misión.\n\nViaja a las Altas Tierras Salvajes, al suroeste de aquí. Ahí encontrarás unas estructuras abandonadas cuyos restos yacen en una tierra que antaño perteneciera a los elfos de la noche. Busca esas ruinas y, cuando veas árboles marchitos y tierra profanada, encontrarás a los Gordunni. Hazlos retroceder.\n\nEsos ogros son mucho más fuertes que los que has afrontado hasta ahora, <nombre>, ten cuidado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2981] = {title = "Una amenaza en Feralas", objective = "Belgrom Destrozarroca quiere que hables con Rok Orhan, del Campamento Mojache.", description = "Feralas es el lugar ideal para que cualquier <clase> ponga a prueba sus cualidades. Allí los ogros Gordunni son los amos y señores y cada día crecen en número. Hay que detenerlos antes de que pongan en peligro nuestra presencia en Feralas.\n\nConozco a una guerrera que vive en el Campamento Mojache, en Feralas. Se llama Rok Orhan. Ve a buscarla. Ella te dará más detalles del estado de la situación.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2982] = {title = "Las Altas Tierras Salvajes", objective = "Angelas Brisaluna quiere que mates a 8 brujos Gordunni, 8 chamanes Gordunni y 8 toscos Gordunni.", description = "Aunque es peligroso, Troyas y yo hemos estado investigando las ruinas que cubren los bosques de Feralas.\n\nPero últimamente, Troyas ha empezado a ir solo a las Altas Tierras Salvajes y eso me preocupa mucho. Los ogros Gordunni han invadido la zona y no son muy simpáticos con los que entran en su territorio.\n\nEsperaba que pudieras viajar a las ruinas, que están al sureste, y que eliminaras a algunos de los ogros. Así el área será más segura para Troyas. Y yo te lo agradecería mucho.", progress = nil, completion = "Te agradezco mucho lo que has hecho por mí. \n\nPero, por favor, ni una palabra a Troyas sobre esto.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2983] = {title = "La llamada del fuego", objective = "Busca a Kranal Fiss en Los Baldíos.", description = "Ha pasado algún tiempo desde tu última prueba, <nombre>. Hasta el momento has sido paciente en tus estudios, pero llegó el momento de que adquieras mayores poderes... es hora de que aprendas el auténtico poder. El elemento del fuego será tuyo si estás <dispuesto/dispuesta> a pagar el precio.\n\nBusca a Kranal Fiss en Los Baldíos. Vive en una pequeña casa al norte de El Cruce. Pero cuidado: si llegas hasta las devastadas tierras de los elfos de la noche, habrás ido demasiado lejos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2984] = {title = "La llamada del fuego", objective = "Busca a Kranal Fiss en Los Baldíos.", description = "Ha pasado tiempo desde tu última prueba, <nombre>. Hasta ahora has demostrado paciencia en tus estudios, pero ha llegado el momento de que aprendas algo más. Debes aprender de la destrucción... y el caos. De un elemento: el fuego. Podrás comprenderlo, si estás <dispuesto/dispuesta> a pagar el precio.\n\nBusca a Kranal Fiss en Los Baldíos. Vive en una pequeña casa al norte de El Cruce. Pero cuidado: si llegas hasta las tierras de los elfos de la noche, habrás ido demasiado lejos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2985] = {title = "La llamada del agua", objective = "Encuentra a Islen Vidente del Agua en Los Baldíos.", description = "<Dispuesto/Dispuesta> pareces para la prueba siguiente, <nombre>. Paciencia en tus estudios has mostrado pero de aprender aún más la hora ha llegado. Ha llegado la hora de que aprendas cosas sobre la pureza del agua.\n\nBusca a Islen Vidente del Agua en Los Baldíos. Se encuentra por la costa oriental, al sur del Río Furia del Sur y de Trinquete. La encontrarás en su cabaña de pesca. Que la Fortuna te sea favorable, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2986] = {title = "La llamada del agua", objective = "Encuentra a Islen Vidente del Agua en Los Baldíos.", description = "Mucho tiempo ha pasado desde que a prueba te pusieron, <nombre>. Paciencia en tus estudios hasta ahora has mostrado pero de aprender aún más la hora ha llegado. Ha llegado la hora de que aprendas cosas sobre la pureza del agua.\n\nBusca a Islen Vidente del Agua en Los Baldíos. Se encuentra por la costa oriental, al sur del Río Furia del Sur y de Trinquete. La encontrarás en su cabaña de pesca. Que la Fortuna te sea favorable, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2987] = {title = "El cobalto Gordunni", objective = "Orwin Cacharrejos, del Campamento Mojache, quiere 12 muestras de cobalto Gordunni.", description = "Acabo de llegar a Feralas y he oído que los ogros Gordunni del norte tienen minerales interesantes. No sé qué estarán tramando, ¡pero protegen sus minerales casi de forma sospechosa! No los dejan por ahí, no, los entierran para que gente como yo no consiga echarles el guante.\n\nSi quieres ayudarme, te daré mi pala. Ve a la Avanzada Gordunni que hay al norte de aquí y desentiérrame un poco de cobalto Gordunni. Cuando veas un brillo azul, ¡empieza a cavar!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Botas del MaharishiCapa de mirada estelarRecibirás:\n\n"}
MultiLanguageQuestData['mx'][2988] = {title = "Las jaulas de Secacorteza", objective = "Mira en las jaulas de los poblados Secacorteza y vuelve a ver al maestro de grifos Garracha.", description = "¡El hijo de nuestro mejor grifo ha desaparecido! El hijo de Alarrápida, Picoafilado, se perdió hace unos días cuando cazaba. Creemos que lo tienen los trols.\n\n¡Ayúdanos! Busca entre las jaulas de los dos poblados Secacorteza, a ver si lo encuentras.", progress = nil, completion = "¿Que no has encontrado a Picoafilado? Eso es una mala noticia; es el jefe de la futura generación de grifos. Sin él se perderá gran parte de su fuerza y empuje.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2989] = {title = "El Altar de Zul", objective = "Mira en el Altar de Zul y vuelve a ver al maestro de grifos Garracha.", description = "Los Secacorteza no tienen a Picoafilado. A lo mejor fueron los trols Vilrama. Busca al grifito en el Altar de Zul, en el extremo occidental del territorio Vilrama.", progress = nil, completion = "¿No has encontrado a Picoafilado? Eso es malo y bueno. \n\nAl menos no estaba en el altar de los sacrificios. \n\nGracias por tu ayuda, aunque me queda la tarea más difícil por delante.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2990] = {title = "Thadius Sombramacabra", objective = "Lleva la pluma de Picoafilado a Thadius Sombramacabra a Las Tierras Devastadas.", description = "Llévale esta pluma al adivino Thadius Sombramacabra. Se fue de Pico Nidal hace años para estudiar ciencias oscuras, pero sigue siendo un Martillo Salvaje.\n\nA lo mejor puede ayudarnos a encontrar a Picoafilado.\n\nEsta pluma estaba en su nido. Con ella y un poco de suerte, Thadius usará sus poderes de adivinación para localizar al grifo.\n\nSuerte, <nombre>. Thadius vive en Las Tierras Devastadas, en la torre de los magos del Castillo de Nethergarde.", progress = "¿Traes un regalo, <nombre>?", completion = "Ah, sí. Esta pluma pertenece a un noble grifo destinado a grandes cosas... si llega a la edad adulta. \n\nEscúchame si quieres encontrarlo, &lt;clase&gt;...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2991] = {title = "Medallón de Nekrum", objective = "Lleva el medallón de Nekrum a Thadius Sombramacabra a Las Tierras Devastadas.", description = "Voy a averiguar en dónde está tu grifo, pero primero haz algo por mí. Hay un trol en Zul'Farrak, Nekrum Cometripas, que tiene un medallón que me gustaría estudiar. Tráeme ese medallón y usaré mis poderes para encontrar a Picoafilado.\n\nZul'Farrak está al otro lado del océano, al oeste, en el desierto de Tanaris.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2993] = {title = "Regresa a las Tierras del Interior", objective = "Habla con el maestro de grifos Garracha.", description = "Picoafilado está enjaulado en un precipicio en la cumbre de Jintha'Alor, en las Tierras del Interior. La llave de la jaula está en poder de la sacerdotisa vil Hexx, suma sacerdotisa de los trols Vilrama.\n\nYa está. He terminado. Te deseo suerte en tu misión, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2995] = {title = "Líneas de comunicación", objective = "Quema los registros de Vallealto, el informe de Vallealto y las notas de Vallealto.", description = "La Avanzada Quel'Danil es el centro de comunicación de los elfos nobles de las Tierras del Interior. Sus embajadores están trabajando para establecer relaciones con otras razas con las que compartir sus conocimientos sobre los trols Secacorteza que viven en la zona sur de las Tierras del Interior. Todos los documentos relativos a sus comunicaciones se guardan en la avanzada.\n\nTenemos que evitar las alianzas entre Vallealto y otros pueblos, <nombre>.\n\nDestruye los documentos de Vallealto. Tenemos que quemar sus líneas de comunicación... literalmente.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2996] = {title = "Buscando a Strahad", objective = "Habla con Strahad Farsan en Trinquete.", description = "Te he enseñado mucho, pero ha llegado el momento de que cambies de instructor. Se llama Strahad y vive en Trinquete. Es humano, pero no vayas a creer por eso que es débil. Su aspecto no refleja su poder; te enseñará invocaciones más potentes. Lo encontrarás en el puerto de Trinquete, cerca de su torre.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][2998] = {title = "Escrito sobre divinidad", objective = "Habla con Duthorian Rall en Ventormenta.", description = "Saludos, <hermano/hermana>. Duthorian Rall, uno de nuestros paladines más influyentes, estuvo hablando de ti hace poco. Le oí decir que era hora de ponerte a la prueba... Y bueno, también dijo algo sobre lo bien que estás yendo hasta ahora y eso.\n\nSi yo fuera tú, iría a Ventormenta y hablaría con él. Seguramente estará en la Catedral de la Luz. Ahí es donde pasa la mayor parte de su tiempo.", progress = nil, completion = "En Ventormenta se está de maravilla, ¿no te parece? \n\nNo podías llegar en mejor momento, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3001] = {title = "Buscando a Strahad", objective = "Habla con Strahad Farsan en Trinquete.", description = "Yo te he instruido hasta ahora pero ha llegado el momento de que cambies de instructor. Se llama Strahad y vive en Trinquete. Es un humano, pero no vayas a creer por eso que es débil ni que ha de ser tu enemigo... al menos de momento... Es muy poderoso y merecedor de respeto, y puede enseñarte hechizos de invocación superior, hechizos que creo que estás <preparado/preparada> para conocer. Ve a buscarlo.\n\nLo encontrarás en el puerto de Trinquete, cerca de su torre.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3002] = {title = "El orbe Gordunni", objective = "Lleva el orbe Gordunni a Uthel'nay, que está en la Cabaña de Brezo de Orgrimmar.", description = "Aunque conozco bien a mi enemigo, soy solo un guerrero, <nombre>. No puedo ni empezar a decirte de qué es capaz este orbe.\n\nPero conozco a un mago de Orgrimmar que podrá decirnos más cosas sobre el orbe. Llévaselo a él.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3022] = {title = "Un envío frágil", objective = "Llévale la caja cuidadosamente empaquetada a Erelas Cieloámbar, que está en Aldea Rut'theran.", description = "<nombre>, veo que ansías dedicarte a mi valerosa causa. ¡Pues claro que puedes hacer algo por mí!\n\nLlévale esta caja de huevos a Erelas Cieloámbar. Él es un druida que los sabe cuidar muy bien pues ayuda a salir del cascarón a los pequeños hipogrifos y después los instruye. Lo encontrarás en Teldrassil, en una pequeña aldea situada al sur que se llama Rut'theran.", progress = "Otro envío de parte de Curgle, ¿verdad?", completion = "Gracias por tu ayuda, &lt;nombre&gt;. La población de hipogrifos no crecería de no ser por nosotros. Pero seguro que eso ya lo sabes pues has estado en Feralas y has visto con tus propios ojos la devastación causada por los Gordunni. \n\nBien, como puedes observar, tengo mucho trabajo así que será mejor que te vayas. \n\nGracias de nuevo, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3042] = {title = "Temple trol", objective = "Lleva 20 viales de temple trol a Trenton Mazaligera en Gadgetzan.", description = "Los trols Furiarena de Zul'Farrak utilizan arenisca para crear sus materiales de temple y yo también puedo utilizarlo para templar mis creaciones. Es muy valorado entre los expertos, así que si me traes un buen suministro de temple, te recompensaré muy bien.\n\nZul'Farrak está al noroeste de Gadgetzan. Buena suerte.", progress = "¿Has traído el temple, <nombre>?", completion = "¡Ah, es un temple excelente! ¡Y hay mucho! ¡Podré trabajar muchos días antes de que se acabe! \n\nGracias, &lt;nombre&gt;. Por favor, acepta esto como pago.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3062] = {title = "Corazón oscuro", objective = "Talo Pezuñahendida, del Campamento Mojache quiere el corazón oscuro de Edana Garfaodio.", description = "Edana Garfaodio es la reina de las arpías de Nortearroyo que viven en las ruinas del oeste. Es el mal encarnado. He oído que su corazón es de cristal. Carece de sentimientos... aparte del odio que siente por todo lo que no sea ella. Debes enfrentarte a Edana y traerme su corazón oscuro.\n\nHe oído hablar de un cuerno que llevan esas arpías... Si lo tocan en las Piedras Garfaodio, en la parte norte de las ruinas, su reina acude.\n\nImagina su sorpresa cuando vea que no son sus semejantes quienes la llaman, sino la muerte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes CrestalaFaja de Cuerno FuerteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][3063] = {title = "Venganza contra Nortearroyo", objective = "Talo Pezuñahendida quiere que mates a 4 arpías Nortearroyo, 4 Malaplumas Nortearroyo, 4 clamavientos Nortearroyo y 4 destripadoras Nortearroyo.", description = "En mis tiempos fui un avezado cazador. No había criatura a la que yo temiera. Hasta que...\n\nUn día estaba en el bosque, afilando mi espada después de una dura batalla y caí en una emboscada. Unas arpías me rodearon y... casi no lo cuento. Tuve que arrastrarme para ponerme a salvo.\n\nTodavía puedo oír el eco de sus gritos...\n\nDespués de aquello, no he vuelto a ser el mismo. Han pasado muchos años, pero el odio sigue hirviéndome en las venas. Debo desquitarme.\n\nPuedes encontrar a las arpías de Nortearroyo al oeste de aquí. Véngame, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3087] = {title = "Papiro con grabados", objective = "Lee el papiro con grabados y habla con Karranisha en el Valle de los Retos.", description = "Ah, mientras estabas fuera llegó un papiro para ti, <nombre>.\n\nLéelo cuando tengas tiempo, si no me equivoco viene de parte del instructor de cazadores, Karranisha. Querrá tener unas palabras contigo cuando estés <listo/lista>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][3097] = {title = "Un pergamino sacralizado", objective = "Lee el pergamino sagrado, luego ve a la iglesia de Camposanto y habla con el clérigo oscuro Duesten.", description = "Oye, mientras estabas por ahí ocupándote de la Plaga esa, llegó este pergamino para ti. Debe de ser importante porque parece que lleva el sello del instructor de sacerdotes Duesten. Yo me tomaría un momento para leerlo antes de ponerme en marcha otra vez.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][3098] = {title = "Un pergamino glífico", objective = "Lee el pergamino glífico, luego ve a la iglesia de Camposanto y habla con Isabella.", description = "Oye, mientras estabas por ahí ocupándote de la Plaga esa, llegó este pergamino para ti. Debe de ser importante porque parece que lleva el sello de la instructora de magos Isabella. Yo me tomaría un momento para leerlo antes de ponerme en marcha otra vez.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][3099] = {title = "Un pergamino corrupto", objective = "Lee el pergamino corrupto, luego ve a Camposanto y habla con Maximillion.", description = "Oye, mientras estabas por ahí ocupándote de la Plaga esa, llegó este pergamino para ti. Debe de ser importante porque parece que lleva el sello de Maximillion, el instructor de brujos. Yo me tomaría un momento para leerlo antes de ponerme en marcha otra vez.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][3100] = {title = "Una carta simple", objective = "Lee la carta simple y habla con Llane Beshere en la Abadía de Villanorte.", description = "Me pidieron que te trajera esto en cuanto regresaras de los campamentos kóbold, <nombre>. Parece ser una carta sellada con la insignia de Llane, uno de nuestros instructores de guerreros locales. Deberías leerla antes de continuar con tus tareas en la abadía.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][3104] = {title = "Una carta glífica", objective = "Lee la carta glífica y habla con Khelden Bremen en la Abadía de Villanorte.", description = "Me pidieron que te trajera esto en cuanto regresaras de los campamentos kóbold, <nombre>. Parece ser una carta sellada con la insignia de Khelden, uno de nuestros instructores de magos locales. Deberías leerla antes de continuar con tus tareas en la abadía.", progress = "Hola, <nombre>, me llamo Khelden. ¿Querías algo?", completion = "Sabía que mi carta no te apartaría de tu camino. Bien, ¿vienes a aceptar tu destino y enfrentarte a quienes se oponen a tu búsqueda de sabiduría y poder? \n\nTe temerán tanto como te respetarán, &lt;nombre&gt;. Y yo siempre estaré aquí para instruirte; solo tienes que venir a buscarme.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][3106] = {title = "Runa simple", objective = "Lee la runa simple, luego ve al Valle de Crestanevada y habla con Thran Khorman.", description = "<nombre>, me fue confiada esta runa para que te la entregara. Cuando tengas la oportunidad, léela. Creo que es de Thran, el instructor de guerreros. Échale un vistazo y, cuando puedas, ve a buscar a Thran a Yunquemar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3109] = {title = "Runa codificada", objective = "Lee la runa codificada, luego ve a Yunquemar y habla con Solm Hargrin.", description = "<nombre>, me fue confiada esta runa para que te la entregara. Cuando tengas la oportunidad, léela. Creo que es de Solm, el instructor de pícaros. Échale un vistazo y, cuando puedas, ve a buscar a Solm a Yunquemar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3110] = {title = "Runa sacralizada", objective = "Lee la runa sacralizada, luego ve a Yunquemar y habla con Silo Khalder.", description = "<nombre>, me fue confiada esta runa para que te la entregara. Cuando tengas la oportunidad, léela. Creo que es de Silo, el instructor de sacerdotes. Échale un vistazo y, cuando puedas, ve a buscar a Silo a Yunquemar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3117] = {title = "El sigilo con grabados", objective = "Habla con Ayanna Semprerguida dentro de Aldrassil, en Cañada Umbría.", description = "Este siglo me lo entregó un mensajero de nuestra instructora de cazadores, Ayanna. Parece que quiere hablar contigo. Léelo y luego llévaselo.", progress = "Te doy la bienvenida a Cañada Umbría, <nombre>.\n\n¿Todo va bien?\n\nVoy a enseñarte técnicas de caza, a domar animales para que luchen junto a ti, a disparar con el arco y a respetar toda la tierra.", completion = "Ven a verme a menudo mientras estés en Cañada Umbría; te ayudaré a entender el rol del &lt;clase&gt; y tus capacidades. \n\nCorren tiempos inseguros, &lt;nombre&gt;, no confíes demasiado en la ayuda de tus mascotas. En estos tiempos hay cosas más peligrosas de lo que puedas imaginar.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][3118] = {title = "El sigilo cifrado", objective = "Habla con Frahun Sombrusurro dentro de Aldrassil, en Cañada Umbría.", description = "Un mensajero de nuestro instructor de pícaros, Frahun, ha traído este sigilo. Parece que quiere hablar contigo. Léelo y luego llévaselo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][3119] = {title = "Sigilo sacralizado", objective = "Habla con Shanda dentro de Aldrassil, en Cañada Umbría.", description = "Un mensajero de nuestra instructora de sacerdotes, Shanda, ha traído este sigilo. Parece que quiere hablar contigo. Léelo y luego llévaselo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3121] = {title = "Una extraña petición", objective = "Lleva la cabeza reducida a Xerash Hojafuego al Pabellón de Lariss en Feralas.", description = "¡Xerash Hojafuego, en el Pabellón de Lariss al norte del Campamento Mojache, tiene lo que necesito para empezar aquí! Ha preparado un mejunje que necesito para mi... bueno, ya lo verás.\n\nPonte en marcha. ¡A Xerash! Y llévate esto contigo. Es una cabeza reducida que le prometí a Xerash a cambio de las hierbas. Es la cabeza de un pobre enano que se tropezó conmigo en el bosque. Seguro que le encantará.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3122] = {title = "Regresa junto al médico brujo Uzer'i", objective = "Entrega la faltriquera de hierbas de Xerash al médico brujo Uzer'i en Feralas.", description = "Aquí tienes las hierbas, <nombre>. Llévaselas al médico brujo Uzer'i.\n\nY dile por favor que estoy muy satisfecho con la cabeza reducida.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3123] = {title = "Probar la vasija", objective = "Mata a 10 osos Cueracero o corredores Dientelargo y usa la vasija de muisek de bestia para reducir y capturar a las bestias caídas.\n\nLleva 10 muestras de muisek de bestia y la vasija de muisek de bestia al médico brujo Uzer'i en Feralas.", description = "Esto va a ser una prueba. Del ritual que celebré y de tus habilidades. Coge esta vasija, <nombre>. Con ella tendrás el poder de reducir y capturar a una criatura.\n\nViaja a las tierras que hay al este de aquí y busca bestias. Los sañosos osos Cueracero y los corredores Dientelargo serán tu objetivo, <nombre>. Mátalos y utiliza la vasija de muisek para reducirlos y capturarlos antes de que sus espíritus escapen.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3124] = {title = "Muisek de hipogrifo", objective = "Acaba con 10 hipogrifos Plumavieja de cualquier tipo y utiliza la vasija de muisek para encogerlos y capturarlos.", description = "Has demostrado merecer mi confianza y tener facultad suficiente para utilizar a las vasijas de muisek. Ahora quisiera que capturases a otra criatura.\n\nLos hipogrifos han sido compañeros leales de los elfos de la noche durante muchos años; sus espíritus son leales e inquebrantables.\n\nTu tarea consiste en acabar con 10 hipogrifos Plumavieja y, rápidamente, encogerlos y capturarlos usando la vasija, de forma que podamos conservar su muisek. Podrás encontrarlos en las Altas Tierras Salvajes, al sur de aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3125] = {title = "Muisek de dragón feérico", objective = "Mata a 8 duendes dardo o duendes dragón. Utiliza la vasija de muisek para reducir y capturar a los dragones feéricos caídos.", description = "<nombre>, ahora quiero que captures a una criatura que es de apariencia frágil pero que posee un espíritu poderoso, que es lo que me interesa de ella. Hablo de los dragones feéricos, unas criaturas que han servido como aliadas a los elfos de la noche. Debemos capturar uno para que la Horda pueda beneficiarse de la fuerza de su espíritu.\n\nAquí tienes la vasija, <nombre>. Mata a 8 duendes dardo o duendes dragón y captura su muisek. Puedes encontrarlos al oeste de aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3126] = {title = "Muisek de antárbol", objective = "Mata a 3 caminabosques deambulantes. Utiliza la vasija de muisek de antárbol para reducir y capturar a los antárboles caídos.", description = "Los caminabosques deambulantes que vagan por el bosque son nuestro siguiente objetivo, <nombre>. Los elfos de la noche se han aliado con los antárboles para combatir a la Horda. Se mueven con lentitud, pero su papel como protectores es innegable.\n\nPronto podrán usar ese poder en nuestro beneficio.\n\nEncuentra a 3 Caminabosques deambulantes, mátalos y utiliza la vasija de muisek para reducirlos y capturarlos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3127] = {title = "Muisek de gigante montés", objective = "Mata a 7 caminantes de la tierra o gigantes del risco. Utiliza la vasija de muisek para reducir y capturar a los gigantes monteses caídos.", description = "La última tarea que te encargaré es que viajes al noroeste y encuentres al enemigo definitivo.\n\nLos gigantes monteses dejaron sus montañas para ir a ayudar a los elfos de la noche cuando la Legión Ardiente apareció en el mundo. Los reconocerás por su descomunal talla y los encontrarás por la forma en la que el suelo temblará cuando viajes por su rocosa tierra.\n\nEstoy deseando controlar ese descomunal poder. Mata a 7 gigantes monteses y luego utiliza la vasija de muisek para capturar su potente muisek.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3128] = {title = "Materiales naturales", objective = "Lleva 2 troncos astillados, 6 minerales taraceados, 20 tendones resistentes y 40 trozos metálicos al médico brujo Uzer'i al Campamento Mojache.", description = "Necesitaré algunos materiales para completar mi tarea... Podrías conseguírmelos a la vez que cumples otras tareas que te asignaré.\n\nNecesitaré un tronco astillado de un antárbol de Feralas. Y minerales taraceados. Los llevan los gigantes monteses y los dragones feéricos del oeste. También necesito algún tendón resistente de las lechubestias de las Tierras del Interior o de los hipogrifos de Feralas. Y por último, necesito una gran cantidad de fragmentos metálicos de cualquiera de las criaturas que he mencionado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3161] = {title = "Gahz'rilo", objective = "Marvon Buscarroblones de Tanaris quiere que reúnas 30 adornos de gahz'rilo.", description = "¡<nombre>, yo soy un científico pero tengo alma de cazador de tesoros!\n\nMucho tiempo atrás, cuando los trols ocupaban estas tierras, crearon gran cantidad de adornos inspirados en Gahz'rilla, una hidra a la que rindieron culto como a una deidad. Estos adornos están tallados en un material que yo denomino \"gahz'rilo\", derivado del propio nombre de la diosa hidra.\n\nYo mismo encontré algunos pero me gustaría tener más para poder estudiarlos a fondo. Quizás tú puedas buscarlos...\n\n¡Incluso he ideado un detector que hace de buscar gahz'rilo un juego de niños! ¡Simplemente enciéndelo y que empiece la búsqueda!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Bastón de ConocimientoGuerrera de peritoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][3181] = {title = "El cuerno de la bestia", objective = "Lleva el cuerno enorme de Margol a la montaraz Guijarro.|n", description = "El enorme cuerno está lleno de arañazos y grietas. Hay un objeto metálico peculiar incrustado.\n\nAl observarlo de cerca, ves que es una cabeza de hacha rota. En el metal están inscritas las palabras:\n\nPropiedad de la montaraz Guijarro.\n\nCuando saques la cabeza de hacha, se romperá en mil pedazos.\n\n¡Qué cosas!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3281] = {title = "La plata robada", objective = "Llévale la plata robada a Gazrog en El Cruce.", description = "Puede que hayas matado a los raptores ¡pero aún hay que recuperar la plata que robaron! Me han informado que los raptores tienen un gran número de nidos al sur de Trinquete, llaman a ese lugar Tierras de los Raptores. Es probable que llevaran allí nuestra plata robada.\n\nVe a ese refugio de raptores y busca la plata robada. Cuando la encuentres, devuélvemela.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Leotardos de colonoBotas de senderismoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][3301] = {title = "Mura Tótem de Runa", objective = "Habla con Mura Tótem de Runa en El Sepulcro, en el Bosque de Argénteos.", description = "Mi compañera de clan, Mura Tótem de Runa, se dirigía al Bosque de Argénteos así que podría ayudar a nuestros aliados no-muertos. Este bosque está enfermo, se está muriendo, y Mura tenía la esperanza de devolverle la vida. Quizás la extraña vida que hemos encontrado aquí en Los Baldíos pueda ayudarla en su trabajo en el Bosque de Argénteos.\n\nToma uno de los caparazones que recolectaste y llévaselo a Mura en el Bosque de Argénteos. La encontrarás en El Sepulcro. Con un poco de suerte, el estudio del caparazón le dará una idea de lo que necesita para curar ese lugar agonizante.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Cinturón de siembraCapa de sembradorEscudo de brillo interiorCinturón de ayuda no deseadaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][3341] = {title = "Acaba con la amenaza", objective = "Andrew Brownell quiere que mates a Amnennar el Gélido y que le lleves su cráneo.", description = "En Los Baldíos se encuentra una horrible maraña de vides llamadas Zahúrda Rajacieno. Aunque los primeros estudios de este lugar indicaban que no representaba una seria amenaza, nuestros últimos descubrimientos son un poco más desconcertantes...\n\nLos jabaespines de Zahúrda Rajacieno se han aliado con la Plaga. Un exánime llamado Amnennar el Gélido los gobierna, usando el poder de su vasto conocimiento para controlar cada uno de sus movimientos.\n\n<nombre>, Amnennar tiene un vínculo telepático directo con Ner'zhul que debemos eliminar y, para ello, hay que acabar con el Gélido cuanto antes.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nEspada del vencedorDije del Resplandor Ámbar"}
MultiLanguageQuestData['mx'][3361] = {title = "Las penurias de un refugiado", objective = "Llévale la caja de Félix, el cofre de Félix y el cubo de tornillos de Félix a Félix Rayaullido en Yunquemar.", description = "Expulsamos a los troggs de Gnomeregan, ¡pero luego todo salió terriblemente mal! Ahora nuestro hogar está contaminado por la radiación, y los gnomos estamos dispersos por todo Dun Morogh.\n\nEn el apuro por huir de la radiación, perdí todas mis herramientas y pertenencias personales. Los trols se las llevaron. ¡Robaron mi cofre, mi caja y mi cubo de tornillos! Se los llevaron a sus campamentos al sudoeste de Yunquemar.\n\nYo no soy aventurero. ¿Podrías buscar mis cosas y recuperarlas?", progress = "Esto es terrible, <nombre>, esta ciudad no es adecuada para individuos como yo. ¡Hay tantas criaturas horribles aquí como en Gnomeregan antes del accidente!\n\n¿Tienes mis pertenencias? Si no es así, quién sabe lo que los trols habrán hecho con ellas a esta altura...", completion = "¡Hurra, los has encontrado! Eres todo un salvador. Toma, no es mucho, pero acéptalo por los problemas que te he causado. ¡Gracias!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3362] = {title = "El Valle Cardizal", objective = "Tran'rek de Gadgetzan quiere que mates a 8 Cardizales nudosos y a 8 enraizadores Cardizales.", description = "¿Has estado alguna vez en el Valle Cardizal? Es un lugar muy peligroso, <nombre>.\n\nEsas extrañas bestias que hay allí... ¡no me fío ni un pelo de ellas! Creo que se llaman Cardizales nudosos y enraizadores Cardizales, o algo parecido...\n\nDe cualquier forma, quiero ir al valle pero con todos esos Cardizales deambulando por ahí, no creo que consiga volver con vida. Y aquí es donde entras tú. Si pudieras acabar con algunos de ellos, quizás consiga regresar de una pieza. ¿Qué te parece, <nombre>? ¿Me ayudas?", progress = nil, completion = "No sabía que eran tan grandes. Creo que tengo que perfeccionar mi plan... \n\nPero tú has cumplido con tu parte, así que aquí tienes lo que te prometí.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3364] = {title = "Entrega una infusión de albaza hirviendo", objective = "Lleva la infusión de albaza hirviendo a Durnan Cortapieles a Yunquemar antes de que se enfríe, ¡tienes 5 minutos!", description = "¡Ay! Se supone que tenía que llevar esta deliciosa infusión de albaza a Durnan Cortapieles, de Yunquemar, pero antes tengo que entregar una a Grelin. ¡Se enfriará antes de que llegue a Yunquemar!\n\nTú pareces <rápido/rápida>. Seguro que tú lo consigues. Esta taza estará caliente solo unos cinco minutos más y Durnan no pidió infusión fría de albaza, así que, ¡en marcha! Yunquemar está al noreste. Es un emplazamiento excavado en la montaña.\n\nGracias, <nombre>. ¡Y no olvides devolverme la taza!", progress = "Sí, soy Durnan Cortapieles. ¿Tienes algo para mí?", completion = "¡Oh, qué bien me va a sentar esto! Deja que me tome un descansito mientras disfruto esta infusión de albaza hirviendo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3367] = {title = "Piedras de Suntara", objective = "Ayuda a Dorius a volver a Forjaz.|n", description = "<Dorius gruñe.>\n\nEstoy malherido, <raza>. Todo me da vueltas... Seguro que tengo hemorragias internas.\n\nTengo que volver a Forjaz. Ayúdame, <nombre>.\n", progress = nil, completion = "Dorius dejó caer esta carta cuando le dispararon.|n", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3369] = {title = "En las pesadillas", objective = "Lleva el Fragmento de Pesadilla a Hamuul Tótem de Runa en el Alto de los Ancestros.", description = "Este fragmento alberga grandes secretos, es la esencia pura del Sueño Esmeralda. Sin embargo, lo que veo en él no es un sueño; hay quien llamaría a esta especie de visión una auténtica pesadilla.\n\nNo quiero alarmarte, <nombre>, pero creo que lo mejor será que lleves este fragmento a manos de un sabio druida tan pronto como puedas...\n\nNecesitas encontrar a Hamuul Tótem de Runa del Alto de los Ancestros. Dirígete a Cima del Trueno. No puedo decirte nada más.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Manto TalbarGalochas del LodazalRecibirás:\n\n"}
MultiLanguageQuestData['mx'][3373] = {title = "La esencia de Eranikus", objective = "Coloca la esencia de Eranikus en la fuente de esencia situada en su guarida del Templo Sumergido.", description = "Cuando tocas la gema, una voz profunda resuena en tu cabeza.\n\n\"Mortal, escucha esta súplica. Soy Eranikus del Vuelo Verde, guardián de este templo maldito. Mi deber de asegurarme de que los trols nunca jamás vuelvan a traer su abominación de dios, ha fracasado. Mientras esta gema queda imbuida de parte de mi esencia, puedo sentir que mi vínculo con el Sueño se dirige hacia el caos. Por favor, coloca esta gema en la fuente de esencia de mi guarida, y deja que nuestra magia purgue la corrupción de mi psique, para que pueda descansar.\"Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nEsencia encadenada de Eranikus"}
MultiLanguageQuestData['mx'][3374] = {title = "La esencia de Eranikus", objective = "Llévale la piedra de juramento del Vuelo de Ysera y la esencia encadenada de Eranikus a Itharius, que está en el Pantano de las Penas. Una vez allí, deberás decidir si quieres ayudar al Vuelo de Ysera o no.", description = "Interactúas con la piedra de juramento y oyes en tu cabeza la voz de Itharius que te habla a través de ella.\n\n\"Al aceptar la orden que contiene esta piedra de juramento, te comprometes a ayudarme a mí y al Vuelo de Ysera a redimir la corrupta alma de Eranikus. El primero de los muchos sacrificios que con toda seguridad tú y yo haremos consiste en que me entregues la gema que está mermando lo poco de la psique de Eranikus que todavía estaba libre de malvadas influencias.\"\n\n\"<nombre>, hazlo y entonces podremos ofrecerle redención a un alma que bien la merece.\"Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3376] = {title = "La cabeza de Cornapunta", objective = "Lleva la cabeza del Jefe Cornapunta Mantospina a la Valiente Pluma de Viento en Mesa de la Nube Roja.", description = "He oído hablar de ti, <nombre>. Quizás tú puedas ayudarnos donde otros han fallado.\n\nLos tauren hemos hecho un hogar de esta tierra, pero a un precio alto. Los jabaespines Erizapúas del Barranco Cortazarza, liderados por el Jefe Cornapunta Mantospina, nos acosan continuamente. ¡Quiero la cabeza del jefe! ¡Tráemela!\n\nEstará en el barranco que hay al este de su aldea.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Leotardos de anillas pintadosGuantes nómadasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][3377] = {title = "El rezo a Elune", objective = "Escucha a Zamael.", description = "¿Quieres ayudarme, mortal? Escucha lo que tengo que decir.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3379] = {title = "Las tejedoras de sombra", objective = "Mata a los furtivos Sedaumbría de La Garganta de Fuego. Nilith cree que son 5. Ve a ver a Nilith en La Garganta de Fuego cuando hayas terminado.|n", description = "Las arañas de La Garganta de Fuego son una fuente increíble de seda de las Sombras. Como ya sabrás, este elemento tiene mucha demanda.\n\nRecientemente, un grupo de furtivos ha invadido estas tierras, acabando con las arañas de forma masiva y sin pensar en los efectos a largo plazo de sus actos. Lo primero que te voy a pedir es muy sencillo: encuéntralos y acaba con ellos.\n\nComienza tu búsqueda por el norte.\n\nSi necesitas ayuda, habla con Arrasa.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBrazales enigmáticos"}
MultiLanguageQuestData['mx'][3380] = {title = "El Templo Sumergido", objective = "Encuentra a Marvon Buscarroblones en Tanaris.", description = "En este mundo, hay espíritus inquietos, <nombre>. Espíritus marcados por su aislamiento, atados a un mal ancestral...\n\nHe oído hablar de un lugar en el fondo de las profundidades de la tierra. Ha sido desterrado allí por poderes muy superiores a los que jamás he visto.\n\nSi quieres saber más cosas sobre este lugar, el Templo Sumergido, busca a un goblin llamado Marvon Buscarroblones. Ha estudiado muchas zonas antiguas del mundo. Se sabe que dejó su hogar en Trinquete para estudiar las ruinas trols en Tanaris.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3382] = {title = "Un equipo bajo el fuego enemigo", objective = "Defiende a la capitana Vanessa Beltis, su tripulación y los pasajeros del Explorador del horizonte frente al ataque de los nagas. La capitana Vanessa Beltis tiene que sobrevivir.", description = "Estábamos a escasa distancia de la costa buscando un puerto seguro donde echar anclas. El sol se había puesto más de una hora antes cuando atacaron... ¡malditos nagas!\n\nNo estoy seguro de lo que buscaban pero está claro que no lo encontraron, ya han vuelto una vez. Tengo a un par de exploradores vigilando la entrada del valle para que nos puedan avisar con tiempo si ven otro ataque venir.\n\nSiento que hayas venido ahora, <nombre>, pero no depende de mí.\n\n¿Estás <listo/lista> para el combate de tu vida?", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][3421] = {title = "El viaje de vuelta", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nTeletransporte desde la torre de Azshara"}
MultiLanguageQuestData['mx'][3441] = {title = "Castigo divino", objective = "Escucha a Velarok Espada del Viento.", description = "Escúchame bien.", progress = nil, completion = "¿Has escuchado lo suficiente como para decidir?|n", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3442] = {title = "La llama pura", objective = "Lleva 4 corazones de llama y 4 globos de aceite gólem a Velarok Espada del Viento.", description = "Has tomado la decisión correcta, <nombre>. \n\nDebemos atacar donde más daño hagamos: en las 4 torres del centinela. \n\nSi las incendiamos, podremos atacar sin darles tiempo a reaccionar. \n\nPara incendiar las torres necesitarás una herramienta. Necesito algunas cosas para fabricarla. \n\nTráeme 4 corazones de llama y 4 aceites de gólem; con eso te haré la antorcha de llama pura. \n\nBusca primero a los gólems y elementales de estas tierras.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3444] = {title = "El círculo de piedra", objective = "Recupera el círculo de piedra del taller de Marvon Buscarroblones, en Trinquete.", description = "Una vez entré en las cámaras prohibidas del Templo Sumergido. El mal que yace en ese lugar penetra en todo lo que entra. Casi no consigo salir de allí, vadeando entre el lodo que cubre el suelo. Todo lo que puedo recordar es que pasé a trompicones por una gran sala circular llena de estatuas de la Serpiente...\n\nHace poco, descubrí una piedra redonda que parece tener el mismo símbolo de la Serpiente grabado. Hice que me la enviaran a mi taller en Trinquete. Recupérala y podré decirte más cosas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3445] = {title = "El Templo Sumergido", objective = "Encuentra a Marvon Buscarroblones en Tanaris.", description = "He oído hablar de un lugar que yace en la profundidad de la tierra... Ha sido desterrado allí por poderes muy superiores a los que jamás he visto.\n\nSi quieres saber más cosas sobre este lugar, el Templo Sumergido, busca a un goblin llamado Marvon Buscarroblones. Al igual que Troyas y yo, ha estudiado muchas zonas antiguas del mundo. Dejó su hogar en Trinquete para estudiar las ruinas trols en Tanaris.\n\nTe deseo buena suerte para encontrarle, hace mucho tiempo que no se oye nada de él.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3446] = {title = "En las profundidades", objective = "Encuentra el Altar de Hakkar en el Templo Sumergido, en el Pantano de las Penas.", description = "Dentro del templo, encontré una sala circular con seis balcones. Cada uno de ellos tenía una estatua de la Serpiente en el borde. Curioso, empujé una de ellas para ver lo que pasaba, ¡era una trampa! Casi encuentro la muerte en la explosión que surgió. Allí, en el borde, miré hacia abajo y vi otra estatua en el fondo de la sala, una especie de altar... Creo que se llamaba Hakkar.\n\nMe da la impresión de que ese altar es el secreto. Debes llevar este objeto al altar del Templo Sumergido.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3447] = {title = "El secreto del círculo", objective = "Ve al Templo Sumergido y descubre el secreto oculto en el círculo de estatuas.", description = "Mis recuerdos son borrosos, pero te diré lo que pueda. Aunque el círculo de estatuas del Templo Sumergido es peligroso, creo que contiene el secreto para encontrar un tesoro mucho mayor.\n\nDesde el altar principal, conseguí activar una serie de luces. Si puedes descubrir el significado de esas luces, quizás puedas revelar el secreto que se esconde en esa sala.\n\nPero te lo advierto, <nombre>. Un gran mal yace en el templo. Lo más probable es, que si hay algo de valor, estará muy protegido...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nUrna Hakkari"}
MultiLanguageQuestData['mx'][3448] = {title = "Encargarse de la investigación", objective = "Habla con Tymor en Forjaz.", description = "Me han encargado que investigue Azshara, una tierra que fue hermosa y que los elfos llamaban hogar. Eso fue en la época en la que practicaban la magia. Ahora es un lugar más peligroso que hermoso, pero debemos buscar respuestas sobre nuestro pasado.\n\nUn compañero llamado Tymor se interesa por estas cosas y se ofreció a ayudarme.\n\nTiene una pequeña tienda a la derecha de la Sala de los Misterios, aquí en la ciudad.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3449] = {title = "Runas Arcanas", objective = "Haz calcos de la Runa de Beth'Amara, la Runa de Jin'yael, la Runa de Markri y la Runa de Sael'hai. Luego ve a la isla frente a la península meridional de Azshara y avisa al piloto Xiggs Botafuego para que recoja los calcos.", description = "Hubo un tiempo en que algunos elfos veneraban la magia tanto como a Elune. Sus magos más poderosos crearon runas y tablillas con leyes de lo arcano y reflexiones sobre sus descubrimientos. Las dejaban en lugares públicos para quien quisiera estudiarlas.\n\nQuisiera que calcaras las runas de las Ruinas de Eldarath. Te daré el material necesario para calcar, pero las runas tendrás que encontrarlas tú. Pero ten cuidado; la Liga de Expedicionarios no es el único grupo interesado en Eldarath.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3463] = {title = "¡Préndeles fuego!", objective = "Entra en las 4 torres del centinela e incéndialas con la antorcha de reprensión.|n", description = "Escúchame bien, <nombre>. Aunque no es posible destruir las torres, con la antorcha de reprensión provocarás unos incendios muy difíciles de extinguir, un fuego que no puede apagar ninguna fuerza ni elemento.\n\nMientras ardan no podrá haber centinelas ni guardias; su primera línea de defensa quedará anulada.\n\nTienes que entrar en cada torre y usar la antorcha de reprensión dentro de las fortificaciones. Ten cuidado con los oteadores de los Hierro Negro, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Leotardos de VueloProtegecabezas PirodracoHacha del draco ébanoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][3483] = {title = "Una señal para el envío", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nPistola de bengalas de venta estándar"}
MultiLanguageQuestData['mx'][3501] = {title = "Todo cuenta en grandes cantidades", objective = "Llévale a Kum'isha trozos draenetistas imperfectos y te recompensará por cada fragmento entregado.|n", description = "Aunque probablemente no encuentres nunca una esfera draenetista perfecta, seguro que encontrarás trozos draenetistas imperfectos al explorar estas tierras.\n\nAunque es improbable que Kum'isha pueda usar los trozos imperfectos para volver a su hogar, las piezas podrían ser de utilidad para otros fines de los draenei.\n\nTráeme todos los trozos draenetistas imperfectos que encuentres y te recompensaré.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBasura de Kum'isha"}
MultiLanguageQuestData['mx'][3502] = {title = "Un trasto de Draenei...", objective = "Llévale a Kum'isha trozos draenetistas imperfectos. Cualquier forma de monstruo de Las Tierras Devastadas podría llevar uno de estos fragmentos.|n", description = "Vaya, después de semejante despliegue de voraz codicia, siento náuseas.\n\nEn fin, no me detendré en tu materialismo.\n\nPor cada trozo draenetista imperfecto que traigas, te recompensaré con más baratijas. Mi pila de chatarra se reduce mientras la tuya crece. Como se dice en Draenor, no hay nada que perder.\n", progress = "¿Y bien? ¿Draenetista? ¿Te acuerdas?\n\n<Kum'isha cierra el puño y te da en la cabeza.>\n\n¿Alguna neurona en casa?|n", completion = "Me produces asco, &lt;raza&gt;. ¿Un hombre hecho y derecho babeando sobre una pila de baratijas? ¡Qué pena das! Toma tu recompensa y desaparece de mi vista. \n\n¿Te suena? Debería, porque lo digo mil veces al día. \n\n¡Oh, cómo aborrezco este mundo!|n", rewards = "Recibirás:\n\nBasura de Kum'isha"}
MultiLanguageQuestData['mx'][3503] = {title = "Encuentro con el maestro", objective = "Hubo un tiempo en que podía pedirles lo que fuera a los que buscaban a mi maestro. Pero ahora, solo tienes que pedirlo y te haré llegar hasta él. \n\nMe molesta pero no cuestiono sus órdenes. Solo puedo disfrutar de hacer bromas sobre tu ridículo atuendo o esa estúpida mirada que luces. Hasta eso me aburre... \n\n¡Hasta esta divagación me aburre! Bueno, ¿quieres ver a mi maestro o no?", description = nil, progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nTeletransporte a la Torre de Azshara"}
MultiLanguageQuestData['mx'][3504] = {title = "Traición", objective = "Entrega la carta lacrada a Ag'tor Puñosangre en Azshara.", description = "¡Elfa ladrona! Es el único nombre por el que merece ser llamada.\n\nHe cometido un gravísimo error, <nombre>. Confié en una elfa de sangre.\n\nAfirmaba que Azshara estaba llena de tesoros, de objetos de poder. Le concedí algunos guerreros como escolta esperando obtener beneficio, y mira lo que obtuve: los mató a todos.\n\nQuiero vengarme, pero no puedo prescindir de nadie más, <nombre>. Ve a ver a Ag'tor a Valormok, al norte del Campamento Haldarr. Te dará más información.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3506] = {title = "Traición", objective = "Destruye el cristal de enfoque Arcano de Maga Rimtori y entonces mátala. Lleva su cabeza a Ag'tor Puñosangre a Azshara.", description = "Piensas un poco y se te ocurre algo que te hace sonreír: puede que destruir los cristales irrite a la responsable de la muerte de tantos orcos y la traición de Belgrom.\n\nSigues descifrando las imágenes y el texto y ves que uno de los cristales está unido al creador del círculo; los demás están unidos a algo mucho más siniestro.\n\nCierras el libro y te pones a pensar en qué cristal vas a destruir.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3510] = {title = "El nombre de la bestia", objective = "Mata a Hetaera y lleva la cabeza ensangrentada, la cabeza golpeada y la cabeza amoratada a Lord Arkkoroc.", description = "Ella mata a mis hijos, mortal. La misma que se atribuye el dominio sobre estos océanos. Una deidad de pacotilla, eso es lo que es. Aplástala y tráeme todas sus cabezas.\n\nA cambio, te daré el nombre que buscas y algo más de igual importancia.\n\nRonda la nidada... La llaman Hetaera.\n\n<Lord Arkkoroc señala hacia el suroeste.>\n\n¡Ve!\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3513] = {title = "El pergamino rúnico", objective = "Llévale el pergamino rúnico de la torre de vigilancia norte en Los Baldíos.", description = "El pergamino con aspecto oficial está firmemente atado con un lazo plateado. Seguro que alguien estará interesado en verlo, ¿pero quién?\n\nHay una avanzada cerca de la frontera con Vallefresno hacia el norte y si la información de este pergamino tiene que ver con los elfos de la noche, este es el lugar al que se debe llevar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3514] = {title = "La presencia de la Horda", objective = "Mata a la jefa de El Cubil del Espolón, Rynthariel la Maestra de llaves.", description = "Este pergamino es de esa intrigante dríade de Rynthariel, la maestra de llaves de El Cubil del Espolón en la Cima del Espolón.\n\nYa no se pondrá en contacto con el mensajero al que le robaste esto, ja, pero debemos mantener la posición aquí. La Horda no tolerará a sus mensajeros aquí.\n\n<nombre>, dirígete a El Cubil del Espolón. Mata a Rynthariel y deja un símbolo para que todos lo vean. Llévate esta bandera de la Horda, <nombre>. Colócala en El Cubil del Espolón para que se lo piensen dos veces antes de enviar a otro mensajero por nuestro territorio.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Botas TraillamaradaGuantes de trenza de yuteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][3517] = {title = "El robo de conocimientos", objective = "Encuentra la tablilla de Beth'Amara, la tablilla de Jin'yael, la tablilla de Markri y la tablilla de Sael'hai antes de volver junto a Jediga en Azshara.", description = "Lo reconozco, <nombre>, he sacado provecho de mi situación en Azshara. Del castigo de Belgrom han resultado algunas cosas buenas.\n\nAntes de marcharme, hice algunas pesquisas y te sorprendería saber cuántos objetos valiosos hay por los alrededores.\n\nTe contaré más detalles de mis asuntos y hasta te daré una parte de los beneficios si me ayudas a recolectarlos.\n\nHay unas tablillas esparcidas por las Ruinas de Eldarath hacia el este que necesito. Son cuatro y cada una recibe el nombre de cuatro zahoríes Altonato. Consíguelas y seguiremos hablando.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3518] = {title = "Entrega a Magatha", objective = "Llévale la tablilla de Beth'Amara a Magatha en Cima del Trueno.", description = "La primera tablilla es para una tauren... una tauren llamada Magatha. Forma parte de los Ancianos Cima del Trueno y está entre los que han propuesto una alianza entre los tauren y los Renegados. Ella, más que ningún otro Anciano, piensa que los tauren y sus métodos pueden ayudar a que los Renegados encuentren una vía para volver a ser humanos.\n\nLlévale la tablilla de Beth'Amara. Es posible que la tablilla sea lo que le permita encontrar la forma de ayudar a los Renegados... o al menos eso dice.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3519] = {title = "Un amigo en apuros", objective = "Habla con Dirania Brillargente en Cañada Umbría.", description = "Uy... Me ha picado una araña llamada Gythyiss la Vil mientras exploraba la cueva de las arañas cerca de aquí. Seguro que me ha envenenado así que tienes que ayudarme.\n\nPor favor, habla con Dirania Brillargente. Ella podrá ayudarme.\n\nDate prisa... me estoy mareando...", progress = nil, completion = "¡Oh, no! Me preguntaba por qué no había visto hoy a Iverron. Y eso que siempre le he dicho que tuviera cuidado con esas arañas...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3520] = {title = "Los espíritus de los estridadores", objective = "Captura el espíritu de 3 estridadores en Feralas y después ve a ver a Yeh'kinya al Puerto Bonvapor.", description = "Busco espíritus de los estridadores del valle de Feralas. Son primos lejanos de un viejo dios y sus espíritus están unidos al suyo.\n\nCoge esta rama de zarza y ve a Feralas. Busca estridadores del valle en la zona sur y central de Feralas y derrótalos. Después agita mi rama sobre sus cuerpos para que sus espíritus se muestren. Toca el espíritu y recoge su esencia.\n\nRegresa con mi rama y con la esencia que hayas recogido y te contaré más acerca del viejo dios del que te hablé.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3521] = {title = "El antídoto de Iverron", objective = "Reúne 7 champiñones jacinto, 4 lirios alunados y 1 icor Tejemadera.", description = "Estoy muy preocupada por mi amigo Iverron. Lleva fuera casi un día entero y temo que se haya envenenado... o algo peor.\n\nQuiero que reúnas los materiales para preparar un antídoto, por si acaso. Recoge champiñones jacinto, que nacen al lado de los árboles, lirios alunados, que solamente nacen cerca del agua, e icor Tejemadera, de las arañas que hay al norte.\n\nMezclarlo todo es muy fácil, incluso si está envenenado. Se dirigía hacia el norte, a la Gruta Narácnida. Espero que puedas encontrarlo.", progress = "Por favor, busca los ingredientes, <nombre>. Iverron necesita nuestra ayuda.", completion = "¡Gracias a Elune! Los conseguiste muy rápido\n\nTendré el antídoto preparado en un instante.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3522] = {title = "El antídoto de Iverron", objective = "Llévale el antídoto de Iverron a Iverron antes de que se acabe el tiempo. Lo encontrarás junto a la cueva situada al norte.", description = "El antídoto está listo, <nombre>. Por favor, encárgate de que Iverron se lo tome.\n\nHay algo más que debes saber; el antídoto solamente será efectivo durante los próximos 5 minutos. Debes llevárselo a tiempo.\n\nEspero que lo logres, <nombre>.", progress = "Oh... <nombre>, me alegro de que hayas vuelto.", completion = "¿Qué es esto, &lt;nombre&gt;? \n\n¡Ah, sabía que Dirania podría ayudarme! \n\n \n\nSiempre me estoy metiendo en problemas y Dirania... bueno, ella siempre se las arregla para echarme una mano. \n\nYa me siento mucho mejor pero creo que me quedaré aquí sentado un rato hasta que esté totalmente recuperado. Mientras tanto, esperaba que pudieras despejar un camino de esas arañas Tejemadera sanguinarias...", rewards = "Calzones de currucaJubón de malla de cortezaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][3523] = {title = "La plaga de la Zahúrda", objective = "Si decides ayudar a Belnistrasz, habla con él otra vez y devuélvele la piedra de juramento.", description = "¡Fantástico! Me llamo Belnistrasz, gracias por rescatarme. Esperaba la muerte o algo peor, como servir de cena a estas alimañas infectadas de Plaga. Sí, la Plaga. Han sellado algún pacto con los jabaespines y el resultado es esta pesadilla.\n\nNo quiero limitarme a huir; quiero cambiar las cosas, por el bien de todos. ¿Quieres ayudarme? Seguro que es peligroso, pero no parece que el peligro te preocupe mucho.", progress = "No me interesa la política, me da igual que estés con la Horda o con la Alianza. Lo que quiero es acabar con las amenazas a todas las razas, y aquí tenemos una importante.\n\nSi aceptas ayudarnos, dame la piedra de juramento como prueba de lealtad. Yo no soy de por aquí; las piedras de juramento son importantes para mi gente.", completion = "¡Estupendo, pensaba que eras uno de esos haciéndose el héroe! Ya lo tenemos todo hecho, &lt;nombre&gt;. No te voy a mentir, si nos concentramos en lo que tenemos que hacer, todo irá bien. \n\nVoy a ponerte al día de los acontecimientos...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3524] = {title = "Varado", objective = "Recoge huesos de la criatura marina varada que está al sur de Auberdine y llévaselos a Gwennyth Bly'Leggonde a Auberdine.", description = "Se dice que hay unas majestuosas criaturas que van a las playas de Costa Oscura a morir encalladas. Últimamente, estas criaturas han empezado a llegar cada vez en mayor número a la costa. Yo he venido aquí a petición del Templo de la Luna para investigar el suceso, pero la gran cantidad de múrlocs que he encontrado en el agua dificulta mucho mis estudios.\n\nUna de esas gigantes criaturas llegó a la costa al sur de Auberdine para acabar rodeada de rabiosos múrlocs Bruma Gris. ¿Podrías ir a traerme algunos huesos de la criatura para que los estudie?", progress = "It is only recently that these creatures started landing on the coast of Darkshore in such alarming numbers.  I can't help but think that this is an ill omen of some sort.  Recovering a sample of that creature's bones to the south would help us in Darnassus assess this situation!", completion = "I hope the murloc did not give you much trouble in collecting this for us!  I will be sure to get this on the next hippogryph to Darnassus.  The Temple of the Moon has given me some funds to hand out for assistance; please have some with our thanks.\n\nYour success here emboldens me to offer you a chance to aid the Temple of the Moon further, if you are interested...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3525] = {title = "Extinguir el ídolo", objective = "Acompaña a Belnistrasz al ídolo jabaespín en Zahúrda Rajacieno. \n\nProtégelo mientras realiza el ritual para inutilizar el ídolo.", description = "Cerca de la entrada hay un ídolo que sirve de horno macabro para los jabaespines. Esas bestias consumen literalmente a quienes secuestran en Los Baldíos. Puedo cerrar el ídolo e impedir que vuelvan a usarlo, pero necesito tu ayuda. Llévame hasta el ídolo y ejecutaré mi ritual. Apenas si podré comunicarme contigo, por no hablar de defenderme. Protégeme; si me matan, será el fin para todos nosotros.\n\n¿Estás conmigo?Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAnillo garra de dragón"}
MultiLanguageQuestData['mx'][3526] = {title = "Ingeniería goblin", objective = "Si quieres saber más sobre ingeniería goblin, llévale el Manual de disciplinas de ingeniería a Nixx Muellepiñón de Gadgetzan.", description = "La ingeniería avanzada se divide en dos disciplinas: la de los gnomos y la de los goblins. Claramente, la ingeniería goblin es la elección de todos los ingenieros brillantes. ¡Aprende a controlar el mundo a través del juicioso uso de potentes explosivos e increíbles aparatos!\n\n<nombre>, lee este manual. Si quieres aprender ingeniería goblin, llévaselo a Nixx Muellepiñón que está en Gadgetzan. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3527] = {title = "La profecía de Mosh'aru", objective = "Llévale la primera y segunda tablillas Mosh'aru a Yeh'kinya, que está en Tanaris.", description = "La antigua profecía de Mosh'aru cuenta el modo de encerrar la esencia del dios Hakkar. Está escrita en dos tablillas que fueron depositadas en la ciudad trol de Zul'Farrak, al oeste de Gadgetzan.\n\n¡Tráeme las Tablillas Mosh'aru!\n\nLa primera tablilla obra en poder de un trol difunto llamado Theka el Mártir. Se dice que sus perseguidores fueron transformados en escarabajos que ahora vagan por los alrededores de su sepulcro.\n\nLa segunda tablilla está en manos de la hidromántica Velratha, cerca de la poza sagrada de Gahz'rilla.\n\nCuando tengas las tablillas, tráemelas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3528] = {title = "El dios Hakkar", objective = "Llévale el huevo de Hakkar relleno a Yeh'kinya, que está en Tanaris.", description = "Ha llegado la hora de atrapar la esencia del avatar de Hakkar.\n\nLleva el huevo de Hakkar a El Sagrario del Dios Caído que se encuentra en el Templo Sumergido de Azeroth. Convoca el poder del huevo para agitar al dios muerto.\n\nÉl enviará a sus esbirros a atacarte. Derrota a sus chupasangres y extráeles su sangre Hakkari. A continuación, utiliza la sangre para apagar las llamas eternas que protegen el espíritu de Hakkar. Cuando el fuego haya sido sofocado, el avatar de Hakkar entrará en nuestro mundo.\n\nDerrótalo y coloca su esencia en el interior del huevo de Hakkar.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Yelmo de guardia vengadorPuntilla de fuerza de vidaAro Ráfaga de gemasRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][3541] = {title = "Entrega a Jes'rimon", objective = "Envía la tablilla de Jin'yael a Jes'rimon en Orgrimmar.", description = "Tengo un perista en Orgrimmar. Reside en La Calle Mayor. No es fácil dar con él si no sabes dónde buscar pero si miras en uno de los edificios más altos, no deberías tardar en encontrarlo.\n\nAunque hazme un favor, no vayas pregonando por todo Kalimdor que está allí y a qué se dedica, sería perjudicial para ambos.\n\nTe dará un precio más que correcto por la tablilla de Jin'yael. No sé muy bien por qué pero deberías haber visto lo nervioso que se puso cuando supo su paradero.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3542] = {title = "Entrega a Andron Gant", objective = "Llévale la tablilla de Markri a Andron Gant en Entrañas.", description = "Andron Gant es mi siguiente contacto. Suele andar por Entrañas... al ladito de El Apothecarium.\n\nTenía la lengua algo más suelta cuando se trataba de hablar de para qué quería la tablilla. Al parecer, algunos de los magos de Entrañas están estudiando algunos hechizos arcanos que los Altonato usaban. Piensan que esta tablilla los ayudará. Markri era un adepto a los conjuros de criaturas, sobre todo los elementales.\n\nLleva la tablilla de Markri y vuelve aquí para tu parte de la recompensa.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3561] = {title = "Entrega al archimago Xylem", objective = "Llévale la tablilla de Sael'hai al archimago Xylem en Azshara.", description = "Esta última tablilla es para alguien muy peligroso, <nombre>. Créeme cuando te digo que confío menos en esta persona que en cualquiera de los otros a los que te he pedido que vayas a ver.\n\nEl archimago Xylem tiene una torre en las colinas que se elevan junto a Azshara. Es humano pero no se comporta como los humanos que he conocido... o matado. Exuda poder y no oso preguntarle cuáles son sus intenciones con la tablilla.\n\nVino a mi encuentro pero me dijo que su guardaespaldas Sanath me ayudaría a llegar a la torre cuando estuviera listo para verle. Busca a Sanath hacia el norte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3562] = {title = "l pago de Magatha a Jediga", objective = "Entrega la nota de Magatha a Jediga en Azshara.", description = "Llévale esta nota a Jediga. Dile que el pago estará aquí para ella cuando regrese. Y dile que estoy satisfecha con su trabajo.\n\nCorre, <nombre>. Dile a tu maestra que estaré esperándola aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3563] = {title = "El pago de Jes'rimon a Jediga", objective = "Entrega la nota de Jes'rimon a Jediga en Azshara.", description = "Lleva esta carta a Jediga. Dile que nuestro trato ha sido provechoso y que estoy satisfecho con su trabajo.\n\nDile que regrese rápidamente a Orgrimmar y que Jes'rimon se asegurará de cuidar bien de ella.\n\nDile eso, y quizás en el futuro ya no necesitaré tus servicios otra vez, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3564] = {title = "El pago de Andron a Jediga", objective = "Entrega la nota de Andron a Jediga en Azshara.", description = "Ahí va... lleva... (hic) esto a Jediga. ¡Que te vaya daguten!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3565] = {title = "El pago de Xylem a Jediga", objective = "Entrega la nota de Xylem a Jediga en Azshara.", description = "¡¿Qué ocurre?! Ah sí, tu pago. Desde luego.\n\nToma esto y hasta luego. Seguro que Jediga aguarda con santa paciencia tu regreso.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3567] = {title = "A la cima", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][3568] = {title = "La filtración de la corrupción", objective = "Llena los 4 viales vacíos en las pozas de las mareas que se encuentran a lo largo de la costa de las Ruinas de Eldarath en Azshara y después ve a ver al químico Cuely.", description = "¿Ves a la tauren que se encuentra detrás de mí, la que parece que va a estirar la pata de un momento a otro? Hace poco estuvo en Azshara. Afirma que unos nagas la hirieron cuando atravesaba las Ruinas de Eldarath.\n\nTras su enfrentamiento con ellos, se tomó un descanso en la playa y bebió de una de las pozas de las mareas. Ahora tiene náuseas... entre otros síntomas.\n\nMe gustaría descubrir qué ha bebido. Coge esta caja que contiene algunos viales vacíos que he etiquetado. Recoge muestras en las distintas pozas y regresa aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3601] = {title = "¡Kim'jael, claro!", objective = "Busca en el Campamento base thalassiano la brújula de Kim'jael, la mira, el pollo relleno y el cachivache y llévaselo todo a Azshara.", description = "¡¡Kim'jael, claro!! ¿Sabes lo que significa Kim'jael para los elfos de sangre, <nombre>? Ratita... o algo parecido. ¡Abusones!\n\nMe contrataron para que los ayudara a rastrear el área en busca de algún tipo de tesoro perdido. Por supuesto, no me lo pensé un momento cuando mencionaron el \"tesoro\" y el dinero que me iban a pagar pero claro, se volvieron contra mí e intentaron matarme... ¡A MÍ!\n\nToma prueba, un elfo de sangre no es de fiar.\n\nEl problema es que aún tienen mi equipo y no puedo recuperarlo. ¿Me ayudas?Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGranada de fragmentación M73"}
MultiLanguageQuestData['mx'][3621] = {title = "La formación de Aterravil", objective = "Llévale el envío a Galvan el Antiguo en la Vega de Tuercespina.", description = "Las armas están listas para ser forjadas. Debes lograr que la azsharita adquiera un temple con potencia para dañar la energía vil.\n\nEn la Vega de Tuercespina encontrarás al herrero a la altura de esta tarea. Galvan el Antiguo, jefe de la Orden del mitril, fabricará las armas como tú se lo encargues. Encontrarás su campamento entre Zul'Gurub y el Túmulo Ogro Mosh'Ogg.\n\nQue tu determinación y fe te acompañen en tu odisea. Si fracasas, ten la certeza de que cuentas con el orgullo de tu dios, mortal.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3628] = {title = "Eres Rakh'likh, demonio", objective = "Destruye a Razelikh el Rapiñador y llévale el cuerno de Rapiñador cortado al héroe caído de la Horda. También tendrás que devolver el Resguardo del Rapiñador para que el héroe caído pueda destruirlo y así impedir que caiga en las manos equivocadas.|n", description = "La guarida de Razelikh está en la cima de la montaña más alta de Las Tierras Devastadas. La única forma de acceder es mediante las runas de teletransporte próximas a la montaña. Siempre que tengas el amuleto, podrás teletransportarte sin problemas hasta la guarida. Cuando llegues allí, debes invocar a la bestia. La clave está en el amuleto, <nombre>. Utilízalo en el Altar de los Rapiñadores.\n\nSi logras derrotar al Rapiñador, tráeme su cuerno. Se convertirá en un símbolo de esperanza para quien lo vea, una prueba de que existen héroes en este mundo desgarrado por la guerra.\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCollar de SantuarioSangre de demonioSaco de pellejo de demonio"}
MultiLanguageQuestData['mx'][3629] = {title = "Ingeniería goblin", objective = "Si quieres saber más sobre ingeniería goblin, llévale el Manual de disciplinas de ingeniería a Nixx Muellepiñón de Gadgetzan.", description = "La ingeniería avanzada se divide en dos disciplinas: la de los gnomos y la de los goblins. Menciono a los goblins puramente porque existen. Les gustan las cosas que explotan y les da igual quién esté en medio, aun ellos mismos.\n\nLéete este manual, <nombre>. Si quieres hacerte saltar por los aires, ve a ver a Nixx Muellepiñón en Gadgetzan. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3630] = {title = "Ingeniería gnómica", objective = "Si quieres saber más sobre ingeniería gnómica, lleva el Manual de disciplinas de ingeniería al maestro manitas Sobrechispa en Forjaz.", description = "En ingeniería avanzada te encuentras con dos escuelas: la de los gnomos y la de los goblins. ¡La ingeniería de los gnomos es mejor con diferencia! Se concentra en la creación de aparatos e instrumentos que hacen la vida más fácil.\n\nLéete este manual, <nombre>. Si quieres saber más sobre el tema, llévaselo aI maestro manitas Sobrechispa, en Forjaz. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3631] = {title = "Invoca un corcel vil", objective = "Habla con Strahad Farsan en Los Baldíos.", description = "Bah. Creo que no estás a punto, pero no soy yo quien decide. Strahad piensa lo contrario, así que haremos lo que quiere... por esta vez.\n\nQuiere hablar contigo lo antes posible. Estará en su torre con sus acólitos, más allá de Trinquete, en Los Baldíos.\n\nNo te entretengas por el camino.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3632] = {title = "Ingeniería gnómica", objective = "Si quieres saber más sobre ingeniería gnómica, lleva el Manual de disciplinas de ingeniería al maestro manitas Sobrechispa en Forjaz.", description = "En ingeniería avanzada te encuentras con dos escuelas: la de los gnomos y la de los goblins. ¡La ingeniería de los gnomos es mejor con diferencia! Se concentra en la creación de aparatos e instrumentos que hacen la vida más fácil.\n\nLéete este manual, <nombre>. Si quieres saber más sobre el tema, llévaselo aI maestro manitas Sobrechispa, aquí en Forjaz. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3633] = {title = "Ingeniería goblin", objective = "Si quieres saber más sobre ingeniería goblin, llévale el Manual de disciplinas de ingeniería a Nixx Muellepiñón de Gadgetzan, en Tanaris.", description = "La ingeniería avanzada se divide en dos disciplinas: la de los gnomos y la de los goblins. Claramente, la ingeniería goblin es la elección de todos los ingenieros brillantes. ¡Aprende a controlar el mundo a través del juicioso uso de potentes explosivos e increíbles aparatos!\n\n<nombre>, lee este manual. Si quieres aprender ingeniería goblin, llévaselo a Nixx Muellepiñón que está en Gadgetzan. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3634] = {title = "Ingeniería gnómica", objective = "Si quieres saber más sobre ingeniería gnómica, lleva el Manual de disciplinas de ingeniería al maestro manitas Sobrechispa en Forjaz.", description = "En ingeniería avanzada te encuentras con dos escuelas: la de los gnomos y la de los goblins. Aunque yo piense que no sirve para nada, deberías de estar al corriente de la especialización de los gnomos. Crean objetos y aparatos que piensan van a cambiar el mundo, pero que raras veces funcionan.\n\n<nombre>, lee este manual. Si deseas aprender a hacer pisapapeles metálicos, lleva el manual aI maestro manitas Sobrechispa que está en Forjaz. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3635] = {title = "Ingeniería gnómica", objective = "Si quieres aprender más cosas sobre ingeniería gnómica, lleva el Manual de disciplinas de ingeniería a Oglethorpe Obnoticus en Bahía del Botín.", description = "En ingeniería avanzada te encuentras con dos escuelas: la de los gnomos y la de los goblins. Aunque yo piense que no sirve para nada, deberías de estar al corriente de la especialización de los gnomos. Crean objetos y aparatos que piensan van a cambiar el mundo, pero que raras veces funcionan.\n\n<nombre>, lee este manual. Si deseas aprender a hacer pisapapeles metálicos, lleva el manual a Oglethorpe Obnoticus que está en Bahía del Botín. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3636] = {title = "Trae la Luz", objective = "El arzobispo Benedictus quiere que mates a Amnennar el Gélido en Zahúrda Rajacieno.", description = "La Plaga es una amenaza constante para la Alianza, lo cual no es nada nuevo. Hace poco, nos topamos con unos hallazgos muy peculiares, <nombre>.\n\nEn los Baldíos existe un laberinto de púas llamado Zahúrda Rajacieno. Solía ser el hogar de jabaespines, pero ahora parece ser que han hecho algún tipo de pacto con la Plaga, creando criaturas mucho peores... Las gobierna el exánime Amnennar el Gélido.\n\nÚnete a la Luz, <nombre>, y acaba con tal pacto.", progress = nil, completion = "Gracias, &lt;nombre&gt;. La Plaga ahora se lo pensará dos veces antes de intentar incrementar sus ejércitos. \n\nQue la Luz te bendiga.", rewards = "Recibirás:\n\nEspada del vencedorDije del Resplandor Ámbar"}
MultiLanguageQuestData['mx'][3637] = {title = "Ingeniería gnómica", objective = "Si quieres aprender más cosas sobre ingeniería gnómica, lleva el Manual de disciplinas de ingeniería a Oglethorpe Obnoticus en Bahía del Botín.", description = "En ingeniería avanzada te encuentras con dos escuelas: la de los gnomos y la de los goblins. Aunque yo piense que no sirve para nada, deberías de estar al corriente de la especialización de los gnomos. Crean objetos y aparatos que piensan van a cambiar el mundo, pero que raras veces funcionan.\n\n<nombre>, lee este manual. Si deseas aprender a hacer pisapapeles metálicos, lleva el manual a Oglethorpe Obnoticus que está en Bahía del Botín. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3639] = {title = "Muestra tu trabajo", objective = "Llévale 20 bombas grandes de hierro, 20 cartuchos de dinamita sólida y 5 ovejas explosivas a Nixx Muellepiñón de Gadgetzan.", description = "El brillo de tus ojos lo dice todo; quieres reventar cosas. Tienes talento en ciernes, <nombre>. Sin embargo, quiero muestras de tu trabajo para poder examinarlas y ver si te puedo orientar hacia técnicas más propias de la ingeniería de los goblins. Necesito lo siguiente: 20 bombas de hierro grandes, 20 cartuchos de dinamita sólida y 5 ovejas explosivas. ¡Y mantente alerta!\n\n¡Entrégame todo esto y serás <un ingeniero/una ingeniera> goblin oficial!Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nIngeniero goblin\n\nTe van a lanzar el siguiente hechizo:\n\ningeniería goblin\n\nTambién recibirás:\n\nTarjeta de miembro del Club de Ingeniería Goblin"}
MultiLanguageQuestData['mx'][3641] = {title = "Muestra tu trabajo", objective = "Lleva 6 tubos de mitril, una mira de precisión y 2 muñecos-diana avanzados al maestro manitas Sobrechispa a Forjaz.", description = "Si lo que quieres es crear aparatos fantásticos, has venido al lugar adecuado. Puedo ver tu destreza en ingeniería, pero quiero algunas muestras de tu trabajo. Me gustaría ver si te puedo orientar hacia técnicas más gnómicas para el futuro. Necesito lo siguiente: 6 tubos de mitril, una mira de precisión y 2 muñecos-diana avanzados.\n\n¡Dame todo esto y te convertirás en <un ingeniero gnómico/una ingeniera gnómica> con acceso a todos los esquemas!Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nIngeniero gnómico\n\nTambién recibirás:\n\nTarjeta de miembro del Club de Ingeniería Gnómica"}
MultiLanguageQuestData['mx'][3643] = {title = "Muestra tu trabajo", objective = "Lleva 6 tubos de mitril, 1 mira de precisión y 2 muñecos-diana avanzados a Oglethorpe Obnoticus en la Bahía del Botín.", description = "Si lo que quieres es crear aparatos fantásticos, has venido al lugar adecuado. Puedo ver tu destreza en ingeniería, pero quiero algunas muestras de tu trabajo. Me gustaría ver si te puedo orientar hacia técnicas más gnómicas para el futuro. Necesito lo siguiente: 6 tubos de mitril, una mira de precisión y 2 muñecos-diana avanzados.\n\n¡Dame todo esto y te convertirás en <un ingeniero gnómico/una ingeniera gnómica> con acceso a todos los esquemas!Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nIngeniero gnómico\n\nTambién recibirás:\n\nTarjeta de miembro del Club de Ingeniería Gnómica"}
MultiLanguageQuestData['mx'][3661] = {title = "¿Creados por Elune?", objective = "Recoge 15 plumas de lechúcico salvaje de las Tierras del Interior y llévaselas a Erelas Cieloámbar a la Aldea Rut'theran.", description = "Los lechúcicos salvajes son muy impredecibles, <nombre>. Pueden ser muy mansos, pero si se sienten amenazados se vuelven extremadamente feroces.\n\nSe dice que fueron creados por Elune; me gustaría saber si es verdad.\n\nHe oído que hay lechúcicos salvajes en las Tierras del Interior: las lechubestias feroces, primitivas y salvajes. Las encontrarás con el resto de la fauna local. ¿Me traerás unas cuantas plumas?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3701] = {title = "Las humeantes Ruinas de Thaurissan", objective = "Ve a las Ruinas de Thaurissan, en Las Estepas Ardientes, y recopila información sobre los tesoros de Thaurissan. Informa a la historiadora real Archesonus.", description = "Intérnate en las ruinas de Thaurissan, en Las Estepas Ardientes, y consigue toda la información que puedas.\n\nDicen que las ruinas están plagadas de tesoros misteriosos. Empieza tu búsqueda por ahí, <nombre>. Ten cuidado con los guardias de Thaurissan: son asesinos que protegen las ruinas y los secretos que hay en ellas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAnillo del Aristócrata"}
MultiLanguageQuestData['mx'][3702] = {title = "Las humeantes Ruinas de Thaurissan", objective = "Escucha a la historiadora real Archesonus relatar la historia de Thaurissan.", description = "¿Te cuento la historia de los enanos Hierro Negro?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3721] = {title = "Tu propio OOX", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nGallina mecánica"}
MultiLanguageQuestData['mx'][3741] = {title = "El collar de Hilary", objective = "Encuentra el collar de Hilary y llévaselo a Villa del Lago.", description = "Mi amiga Hilary ha perdido su collar. Hemos estado pescando todo el día justo aquí, pero ya hemos mirado. Tiene que haberse caído en el lago. Nuestros padres no nos dejan nadar porque dicen que hay cosas malas en el lago. Pero seguro que tú no tienes miedo de las cosas malas.\n\n¿Puedes buscar su collar, por favor?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3761] = {title = "Tierra de Un'Goro", objective = "Llévale 20 muestras de la tierra de Un'Goro a Ghede, en el Alto de los Ancestros de Cima del Trueno.", description = "Se dice que la tierra del Cráter de Un'Goro ha sido enriquecida con potentes cualidades mágicas por lo que el Círculo Cenarion quiere estudiarla en grandes cantidades; ve a los páramos de Un'Goro y consigue suficientes muestras para que podamos continuar con nuestras investigaciones.\n\nEl suelo enriquecido formará pilas de cuando en cuando y es posible que las bestias que allí habitan posean muestras que te pudieran servir. Simplemente busca las pilas y estate <atento/atenta> a los tauren, y después llévale todo a Ghede. ¡Él tiene buenas intenciones pero más te vale que no lo cabrees!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3762] = {title = "Ayuda al archidruida Tótem de Runa", objective = "Habla con el archidruida Hamuul Tótem de Runa en Cima del Trueno.", description = "¿Tienes un minuto, <clase>?\n\nEl Círculo Cenarion de Cima del Trueno está buscando aventureros curtidos para un importante proyecto de investigación. No conozco los detalles, pero has de saber que quien dirige el proyecto es el mismísimo archidruida Hamuul Tótem de Runa.\n\nSi te interesa, habla con él directamente. Lo encontrarás en el Alto de los Ancestros, en Cima del Trueno.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3763] = {title = "Ayuda al archidruida Corzocelada", objective = "Habla con el archidruida Fandral Corzocelada en Darnassus.", description = "Perdona, <clase>, ¿podrías concederme un momento?\n\nEl Círculo Cenarion de Darnassus está buscando la ayuda de aventureros curtidos para un importante proyecto de investigación. No tengo muchos detalles pero puedo decirte que es el mismísimo archidruida Fandral Corzocelada quien encabeza esta investigación.\n\nSi la cosa te interesa, habla con él directamente. Lo encontrarás en el Enclave Cenarion, en Darnassus.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3764] = {title = "Tierra de Un'Goro", objective = "Lleva 20 muestras de tierra de Un'Goro Soil a Jenal, en el Enclave Cenarion de Darnassus.", description = "Se dice que el suelo del Cráter de Un'Goro ha sido enriquecido con potentes cualidades mágicas. Quiero saber qué hay de cierto en esto. Ve a los páramos de Un'Goro y consigue muestras fiables del suelo para que podamos estudiarlas.\n\nY si crees que estás muy por encima de tareas de recogida, no conseguirás ni mi respeto ni el del Círculo Cenarion. Lleva las muestras a Jenal que sin duda estará perdiendo el tiempo detrás de este árbol. Busca los montones de tierra. Él se encarga de la logística. No yo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3765] = {title = "Lejana corrupción", objective = "Ve a ver a Gershala Susurro Nocturno en Auberdine.", description = "Ventormenta... un centro de mucho movimiento.\n\nVengo desde muy lejos buscando ayuda. A menudo se dice que hay valientes aventureros caminando por las calles de esta ciudad.\n\nMi hermano, Gershala, necesita ayuda en Costa Oscura. Vive en la ciudad costera de Auberdine.\n\nEl viaje es largo y épico. Por esta razón, necesito la ayuda de <un/una> <clase> con experiencia como tú.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3783] = {title = "eti... ¿ya hemos llegado?", objective = "Reúne 10 pelajes de yeti gruesos para Umi Risitas en Vista Eterna.", description = "Mis amigos siempre aparecen con grandes ideas. Siempre me ha parecido que no estaba a su altura... ¡hasta hoy! ¡Acabo de trazar el diseño de algo tremendo! Si me prometes no decir nada, te dejaré conocer el secreto...\n\n¡Voy a hacer un yeti mecánico! No solo servirá para asustar a mis amigos... ¡cuando esté listo será realmente impresionante!\n\nPara empezar necesito pelaje de yeti grueso. ¿Me ayudarás? Podrás encontrarla al sureste de aquí.", progress = "Tengo muchas cosas que hacer. Por favor, ¡tráeme los pelajes lo antes que puedas!", completion = "Estos pelajes son perfectos, &lt;nombre&gt;. ¡Esto es un gran comienzo!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3784] = {title = "Ayuda al archidruida Tótem de Runa", objective = "Habla con el archidruida Hamuul Tótem de Runa en Cima del Trueno.", description = "¿Tienes un minuto, <clase>?\n\nEl Círculo Cenarion de Cima del Trueno está buscando aventureros curtidos para un importante proyecto de investigación. No conozco los detalles, pero has de saber que quien dirige el proyecto es el mismísimo archidruida Hamuul Tótem de Runa.\n\nSi te interesa, habla con él directamente. Lo encontrarás en el Alto de los Ancestros, en Cima del Trueno.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3785] = {title = "Investigar la mañagrana", objective = "Utiliza una faltriquera de siempreverde con 1 paquete de semillas de Tharlendris y 2 muestras de tierra de Un'Goro para intentar cultivar mañagrana. \n\nLleva 10 plantas de mañagrana a Mathrengyl Garroso a Darnassus.", description = "Aquí tienes la faltriquera de siempreverde que necesitarás para las semillas de Tharlendris. También necesitarás algo de tierra de Un'Goro. Servirá de fertilizante para las semillas. Usa la bolsa cuando tengas todo. La bolsa se encargará de lo demás.\n\nCuando tengas suficiente mañagrana, tráemela aquí, al Enclave. Y por favor, no molestes al archidruida. Es un hombre muy ocupado y no es necesario interrumpirle cada vez que llega alguien con un poco de mañagrana.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCarretilla del Círculo Cenarion"}
MultiLanguageQuestData['mx'][3786] = {title = "Investigar la mañagrana", objective = "Mete en la faltriquera de siempreverde un paquete de Tharlendris y dos muestras de tierra de Un'Goro para cultivar muestras de mañagrana.\n\nLlévale 10 mañagranas a Bashana Tótem de Runa, que está en Cima del Trueno.", description = "Aquí tienes la faltriquera de siempreverde que necesitarás para las semillas de Tharlendris. También necesitarás algo de tierra de Un'Goro que servirá de fertilizante para las semillas. Usa la bolsa cuando tengas todo y esta se encargará de lo demás.\n\nCuando tengas suficiente mañagrana, tráemela aquí, al Alto de los Ancestros. Y por favor, no molestes al archidruida. Estará muy ocupado con sus investigaciones y además tiene muchos asuntos más de los que ocuparse.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCarretilla del Círculo Cenarion"}
MultiLanguageQuestData['mx'][3787] = {title = "La petición de Jonguja", objective = "Habla con Quintis Jonguja en el Bastión Plumaluna.", description = "Oye, perdona...\n\nTengo un colega que querría hablar contigo sobre la investigación que estás llevando a cabo en colaboración con el Círculo Cenarion. Es un druida y se llama Quintis Jonguja. Vive aquí, en el Bastión Plumaluna, en Feralas. Quiere hablar contigo sobre la mañagrana. Y me ha pedido mucha discreción. No quiere que nada de esto llegue a oídos del archidruida.\n\nSi te interesa, habla con él. Sin duda, aclararemos muchas cosas cuando hayan hablado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3788] = {title = "La petición de Jonguja", objective = "Habla con Quintis Jonguja en el Bastión Plumaluna.", description = "Oye, perdona...\n\nTengo un colega que querría hablar contigo sobre la investigación que estás llevando a cabo en colaboración con el Círculo Cenarion. Es un druida y se llama Quintis Jonguja. Vive aquí, en el Bastión Plumaluna. Quiere hablar contigo sobre la mañagrana. Y me ha pedido mucha discreción. No quiere que nada de esto llegue a oídos del archidruida.\n\nSi te interesa, habla con él. Sin duda, aclararemos muchas cosas cuando hayan hablado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3789] = {title = "Ayuda al archidruida Corzocelada", objective = "Habla con el archidruida Fandral Corzocelada en Darnassus.", description = "Perdona, <clase>, ¿podrías concederme un momento?\n\nEl Círculo Cenarion de Darnassus está buscando la ayuda de aventureros curtidos para un importante proyecto de investigación. No tengo muchos detalles pero puedo decirte que es el mismísimo archidruida Fandral Corzocelada quien encabeza esta investigación.\n\nSi la cosa te interesa, habla con él directamente. Lo encontrarás en el Enclave Cenarion, en Darnassus.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3790] = {title = "Ayuda al archidruida Corzocelada", objective = "Habla con el archidruida Fandral Corzocelada en Darnassus.", description = "Perdona, <clase>, ¿podrías concederme un momento?\n\nEl Círculo Cenarion de Darnassus está buscando la ayuda de aventureros curtidos para un importante proyecto de investigación. No tengo muchos detalles pero puedo decirte que es el mismísimo archidruida Fandral Corzocelada quien encabeza esta investigación.\n\nSi la cosa te interesa, habla con él directamente. Lo encontrarás en el Enclave Cenarion, en Darnassus.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3791] = {title = "El misterio de mañagrana", objective = "Lleva 10 plantas de mañagrana a Quintis Jonguja al Bastión Plumaluna.", description = "Permite que sea sincero contigo, <nombre>. Estoy interesado, no, más bien preocupado por el hecho de que el archidruida de Darnassus esté utilizando el nombre del Círculo Cenarion además de sus recursos para procurarse grandes cantidades de mañagrana. Soy un investigador. Mi especialidad son las maldiciones. He oído que la mañagrana, en determinadas condiciones, exuda las mismas cualidades que las hierbas que se utilizaban en maldiciones primitivas.\n\nQuiero saber más y para eso necesito tu ayuda. Tráeme 10 plantas de mañagrana y yo cuidaré de ti.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de investigación de QuintisEspaldares de cortezaférreaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][3792] = {title = "Mañagrana a Bastión Plumaluna", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nPaquete de semillas Tharlendris"}
MultiLanguageQuestData['mx'][3801] = {title = "El legado de los Hierro Negro", objective = "Habla con Franclorn Forjador en la Tumba de Forjador, en la Montaña Roca Negra, si te interesa obtener una llave de la ciudad.Saludos, <nombre>. Me llamo Franclorn Forjador. Sí, el Franclorn Forjador responsable del revolucionario método de arquitectura. Seguro que has cruzado o has estado en alguna de mis obras a lo largo de tus aventuras en este mundo desgarrado por la guerra.\n\nDebes de estar preguntándote qué hago aquí y qué quiero de ti, dos preguntas muy válidas.\n\nNecesito tu ayuda, claro. A cambio de esa ayuda, te concederé la llave de las profundidades de mi execrable ciudad.", description = "Saludos, <nombre>. Me llamo Franclorn Forjador. Sí, el Franclorn Forjador responsable del revolucionario método de arquitectura. Seguro que has cruzado o has estado en alguna de mis obras a lo largo de tus aventuras en este mundo desgarrado por la guerra.\n\nDebes de estar preguntándote qué hago aquí y qué quiero de ti, dos preguntas muy válidas.\n\nNecesito tu ayuda, claro. A cambio de esa ayuda, te concederé la llave de las profundidades de mi execrable ciudad.", progress = nil, completion = "Ya sea la codicia lo que te trajo aquí o un acto de entrega altruista, lo que estás a punto de acometer es bueno para todos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3802] = {title = "El legado de los Hierro Negro", objective = "Mata a Finoso Virunegro y recupera el gran martillo, Ferrovil. Lleva a Ferrovil al Santuario de Thaurissan y coloca el martillo en la estatua de Franclorn Forjador.|n", description = "Encontrarás a Finoso Virunegro pasado el Círculo de la Ley, en la Sala de los Oficios. Mata al miserable bellaco y recupera a Ferrovil.\n\nLleva a Ferrovil al Santuario de Thaurissan y coloca el martillo en su ubicación legítima: entre las manos de la estatua erigida en mi honor.\n\nCuando lo hayas hecho, el compartimento en el que guardé la llave maestra estará abierto. Y lo que es más importante, Ferrovil permanecerá para siempre jamás en mis manos. Si intentaran extraer el martillo, tanto la estatua como el martillo se harán añicos y se perderán para siempre.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nLlave de Forjatiniebla"}
MultiLanguageQuestData['mx'][3821] = {title = "Roca Machacamiedo", objective = "Adéntrate en Las Estepas Ardientes y averigua qué le ha ocurrido a Sha'ni Colmillo Orgulloso.", description = "Enviaron a Sha'ni para investigar los informes sobre una extraña actividad ritualista procedente de los ogros Pirontraña de Las Estepas Ardientes hace unas tres semanas.\n\nDientegore dice que no ha tenido noticias de nadie de esa sección y que es mejor que siga adelante y me centre en mi tarea actual. ¿Te lo puedes creer? ¡Se trata de mi esposa!\n\nNo puedo abandonar mi puesto, <nombre>, pero necesito saber qué le ha ocurrido a Sha'ni. Ve a Las Estepas Ardientes y búscala.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3823] = {title = "El exterminio de los Pirontraña", objective = "Mata a 15 magos ogros Pirontraña, 7 ogros Pirontraña y 7 ogros toscos Pirontraña.", description = "¡Debemos atacar al enemigo antes de que ellos lo hagan!\n\nSeré breve, soldado.\n\nLos ogros Pirontraña de Las Estepas Ardientes son aliados de los ogros Roca Negra. Colaboran estrechamente con esos malvados orcos, manteniendo la vigilancia sobre la Roca Machacamiedo y sus abundantes minerales, así como garantizando que el suministro sea constante.\n\nQue noten tu presencia, <nombre>. Diezma sus tropas y vuelve aquí cuando hayas hecho tu trabajo.\n\n<Oralius hace un gesto como estrangulando el aire.>\n\n¡TE MATARÉ, WINKY!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3844] = {title = "Un secreto bien guardado", objective = "Busca alrededor del estanque alguna pista sobre a quién perteneció la balsa destrozada.", description = "Descubres una balsa destrozada junto a la orilla. Esto es solo un pequeño estanque así que no puedes hacerte a la idea de cómo terminó aquí. No obstante, cuando miras a los árboles descubres que el nivel del agua puede no ser constante.\n\nQuizás si exploras un poco la zona descubras más pistas...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3845] = {title = "Un secreto bien guardado", objective = "Examina los objetos de la talega y devuélveselos a su propietario.", description = "Tomas la talega y la llevas hasta la orilla. Tal vez examinando los objetos que contiene puedas averiguar a quién perteneció.\n\nHay algunos viajeros en el Refugio de Marshal. Quizás allí averigües algo más.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3861] = {title = "¡CLOQUEA!", objective = "Consigue comida para pollos especial y vuelve junto a tu nuevo amigo pollo. Cuando lo encuentres, anímalo con el comando /animar antes de darle la comida para pollos especial.", description = "\"Coo-co-co-ri-cooo... ¡COOC!\n\nCoo-co-cooo.\"\n\nEl pollo te mira y empieza a rascar el suelo. Te parece que está escribiendo algo, pero no lo lees bien. ¿Podría ser... S-A-L-D-E-A-N? El pollo se marcha antes de que puedas preguntar.Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nInvocar huevo de gallina"}
MultiLanguageQuestData['mx'][3881] = {title = "Salvar a la expedición", objective = "Lleva un cajón de comestibles y el equipo de investigación a Williden Marshal en el Cráter de Un'Goro.", description = "No sé cómo conseguiste llegar hasta aquí, ¡pero eres una auténtica alegría para la vista! Soy Williden Marshal, y dirijo un grupo expedicionario independiente. Nuestro último y mayor esfuerzo se enfrentó a una serie innumerable de desastres, y el mayor de todos ellos fue la subestimada barbarie del Cráter de Un'Goro.\n\nCuando abandonamos nuestros campamentos base en las partes suroeste y noreste del cráter, dejamos atrás suministros de vital importancia. Pareces suficientemente <capacitado/capacitada>, ¿puedes ayudarnos a recuperarlos?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3882] = {title = "Choca esos huesos", objective = "Lleva 8 huesos de dinosaurio a Chispik Minamal en el Cráter de Un'Goro.", description = "Tal vez viendo que soy el jefe de excavaciones de las Expediciones Marshal, pienses que me gusta excavar. La verdad es que puede haber cosas peores en el mundo... pero no salto de alegría.\n\nSe supone que estábamos excavando en el Camino del Terror (un nombre FANTÁSTICO, por cierto) buscando diemetradones y stegodones muertos. ¡Y todavía quedan muchos vivos! Wil y Hol siguen estudiando este lugar, así que necesitamos huesos de esos dinosaurios. Pero entre tú y yo, también valdrá si traes huesos de ejemplares vivos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Botas de cantera de arqueólogoCinturón de herramientas de excavadorRecibirás:\n\n"}
MultiLanguageQuestData['mx'][3883] = {title = "Ecología alienígena", objective = "Utiliza el vial de raspadura para recoger una Muestra de pared de colmena de uno de los criaderos Gorishi del Cráter de Un'Goro. Busca las cámaras con los huevos de larva colgantes.\n\nLleva la Muestra de pared de colmena a Hol'anyee Marshal en el Cráter de Un'Goro.", description = "¡Solo porque hayamos sufrido un contratiempo no debemos detener nuestra investigación! Antes de acabar aquí estábamos estudiando los insectos Gorishi en la parte meridional del Cráter. Su presencia es invasora y extraña en el sistema ecológico de Un'Goro y queremos descubrir por qué están aquí.\n\nEn su red de colmenas debe haber criaderos de larvas. Podrás identificar esos lugares por los huevos de larva que cuelgan por todas partes. Utiliza este vial para recoger muestras de pared de la colmena cerca de cualquier criadero y trae esas muestras para que las estudiemos. ¡Pero ten mucho cuidado!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3884] = {title = "Diario de Williden", objective = "Devuelve el diario a Williden Marshal en algún lugar del Cráter de Un'Goro.", description = "Has descubierto un diario destrozado. Algunas partes siguen siendo legibles y, al parecer, el contenido es obra de un tal Williden Marshal. Si el diario no miente, Williden estará en algún lugar en el norte del Cráter. De acuerdo al diario, Williden y sus compañeros huyeron hacia las zonas más elevadas para refugiarse de las bestias salvajes del Cráter cuando sus campamentos base fueron invadidos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3903] = {title = "Milly Osworth", objective = "Habla con Milly Osworth.", description = "<nombre>, has demostrado que eres <un/una> <clase> de confianza y que no temes al trabajo duro.\n\nMi amiga Milly Osworth está en apuros. Tiene la carreta al otro lado de la abadía, cerca del establo. Seguro que le va bien que le eches una mano.", progress = nil, completion = "¿Que te envía el ayudante del alguacil Willem? Es valiente y voluntarioso, pero está en la Abadía de Villanorte...\n\n¿Tú podrías ayudarme?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3904] = {title = "La cosecha de Milly", objective = "Lleva 8 cajas de cosecha a Milly Osworth a la Abadía de Villanorte.", description = "¡Esa panda de bribones de Los Defias se instalaron en Viñedos de Villanorte mientras estaba vendimiando! Los denuncié a los guardias de Villanorte, que me dijeron que ya se encargarían, pero... ¡Temo por mis viñas! Si los Defias no las roban, me temo que entonces nuestros guardias las aplastarán cuando vayan a echarlos.\n\n¡Tienes que ayudarme! Ya tengo casi toda la uva recogida, pero dejé las cajas en los viñedos que hay al sureste.\n\n¡Tráemelas y salva mi cosecha!", progress = "¿Traes la cosecha, <nombre>?", completion = "¡Gracias, &lt;nombre&gt;! ¡Has salvado mi cosecha! Espero que hayas dado una lección a unos cuantos Defias.\n\n¡Aunque tengamos pocas tropas, tenemos la suerte de contar con valientes como tú!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3905] = {title = "Informe de la vendimia", objective = "Lleva el Informe de la vendimia al hermano Neals a la Abadía de Villanorte.", description = "Ahora que has salvado mis uvas, llévale el Informe de la vendimia al hermano Neals. Se encarga del almacén de abastos de Villanorte; se alegrará de saber que la vendimia ha sido buena.\n\nEstá en el campanario de la abadía; le gusta sentarse allí a probar el vino.", progress = "¡Te veo muy bien! ¡Siéntate y tómate algo!", completion = "Veamos...\n\nOh, has salvado la uva; me preocupé cuando me habló de esos villanos en los viñedos. Por suerte, nunca perdí la fe en la Luz.\n\nY ahora, gracias a tu valor, podremos hacer vino. Que la Luz te acompañe y te proteja, &lt;nombre&gt;.", rewards = "Cinturón con pasadorCapa manchada de vinoRecibirás:\n\nCapa manchada de vinoSaco de vendimia"}
MultiLanguageQuestData['mx'][3906] = {title = "La discordia de las llamas", objective = "Ve a la cantera de la Montaña Roca Negra y ejecuta al Maestro Supremo Pyron. Vuelve junto a Corazón Atronador cuando hayas completado este encargo.|n", description = "Los miembros del consejo han sentido una perturbación en los elementos. Los enanos Hierro Negro han invocado a un espíritu maligno en nuestro mundo que amenaza con una catástrofe en nuestras tierras en forma de inundación permanente. Hay que investigar la discordancia de las llamas.\n\nVe hasta la Montaña Roca Negra, atraviesa el Abismo de Llama y hasta la cantera. Allí encontrarás al Señor del Fuego: Maestro Supremo Pyron.\n\nPon fin a la perturbación y vuelve aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3907] = {title = "La discordia del fuego", objective = "Adéntrate en las Profundidades de Roca Negra y localiza a Lord Incendius. Mátalo y llévale toda la información que encuentres a Corazón Atronador.|n", description = "Puedo oler que el aire que te rodea está viciado, <nombre>. Hay otro ente, oculto en las profundidades de Roca Negra, que lo controla.\n\nEl viento y la tierra gritan su nombre: Lord Incendius... pero alguien... algo... manda en este ente. Es un mero emisario.\n\n¡Encuéntralo y descubre dónde se oculta su maestro! Vuelve a mí cuando hayas obtenido esta información.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Brazales de demonio de criptaManteo nacido del SolGuantes OcasoAgarre de adeptoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][3908] = {title = "Un secreto bien guardado", objective = "Lleva la Espada de Linken a Donova Cubilnevado en Cuna del Invierno.", description = "Verás, no tengo ni idea de cómo terminé aquí. Nadie lo sabe... ¡es un secreto para todos! Es como si no pudiera acordarme de nada...\n\nPero estos objetos que me has traído... Estoy recordando algo.\n\nMi espada. Creo tengo que reforzarla por alguna razón, pero no sé muy bien el motivo. Lo siento, no puedo decirte más, ¡pero es que no puedo recordarlo!\n\nEn cualquier caso, sí que sé adónde puedes llevarla: con Donova Cubilnevado de Cuna del Invierno. La encontrarás junto a las fuentes termales. Ella podrá templar la espada junto a las pozas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3909] = {title = "El Elixir de Videre", objective = "Busca a Gregan Tirabirras en el norte de Feralas. Con él, aprende cómo puedes obtener el Elixir de Videre. Cuando lo sepas, vuelve con Donova Cubilnevado en Cuna del Invierno.", description = "¿Y ahora qué pasa? Linken... ¿SE OLVIDÓ?\n\nOh, entiendo... Ha perdido la memoria...\n\nBueno, aquí está su espada. Pero no está terminada. Sé quién podría hacerlo, pero... hablar con él puede ser difícil.\n\nEscucha, sé de alguien que puede ayudarte. Es una larga historia y no puedo explicártela ahora, pero debes hacerte con un Elixir de Videre. Solo sé de una persona que pueda ayudarte a conseguirlo, Gregan Tirabirras. No es fácil dar con él, pero lo último que supe es que estaba acampado en las tierras salvajes de Feralas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3911] = {title = "El último elemento", objective = "Viaja a las Profundidades de Roca Negra y recupera 10 esencias de los elementos. Tu primer impulso es buscar los gólems y a los creadores de gólems. Recuerdas que Vivian Lagrave también murmuró entre dientes algo sobre los elementales.|n", description = "Hay trabajo a mansalva para quien se aventure en las profundidades, <nombre>.\n\nLos Hierro Negro han perfeccionado la creación de gólems extremadamente poderosos.\n\nLos primeros informes de nuestros espías indican que los enanos usan una fuente de poder única para conferir a sus creaciones una potencia destructora sin igual.\n\n¡Tan solo imagínate lo que podríamos hacer con nuestras abominaciones si nos hiciéramos con esta esencia de los elementos! No dejes piedra por remover en esa ciudad si es necesario, ¡pero no vuelvas hasta haber encontrado la esencia! Recibirás un justo pago por el riesgo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de Lagrave"}
MultiLanguageQuestData['mx'][3921] = {title = "Wenikee Tuercasmil", objective = "Llévale el churumbele roto y maltrecho a Wenikee Tuercasmil. Habla con Brak para teletransportarte directamente hasta ella.", description = "Creo que he metido la pata de verdad: me parece que he metido uno de los fluxores de soporte entre los radios del engranaje desregulador. Podemos arreglarlo sin problemas. Conozco a una experta en pistones de triple expansión que se moriría por echarle el guante a un churumbele. Llévale el churumbele averiado a Wenikee Tuercasmil, al sur de La Empalizada de Mor'shan, y lo reparará en un periquete.\n\nOye, no hace falta que camines. ¡Esta es una oportunidad de oro para probar mi artefacto de teletransporte personal!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3922] = {title = "Engranajes", objective = "Reúne 10 engranajes de los cubos que encuentres por la zona de El Fangal.", description = "Quiero arreglar este churumbele pero para eso voy a necesitar algunas cosas. Se me han acabado los engranajes del calibre diecisiete y medio y voy a necesitar un puñado para ese trabajo.\n\nEl lugar más cercano donde puedes conseguirlos es una estación de investigación no muy lejos de aquí y El Fangal, hacia el este. Ventura y Cía. suele tenerlos en sus cubos de herramientas. Mira en los cubos de herramientas que encuentres en cualquiera de las dos zonas y vuelve cuando hayas recolectado suficientes engranajes.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3923] = {title = "Rilli Gapegajoso", objective = "Llévale el churumbele roto y maltrecho a Rilli Gapegajoso en Orgrimmar.", description = "Bueno, eso no funcionó. Puse unos calibres adicionales en el churumbele para medir su integridad estructural y las lecturas dan mínimos históricos. Podría añadir algún dial más y quizás una palanca o dos para intentar repararlo pero... creo que solo empeoraría las cosas.\n\nDeberías llevarle el churumbele a Rilli Gapegajoso. Antes trabajaba para Ventura y Cía., si alguien sabe cómo arreglarlo, ese es Rilli.\n\nLo encontrarás en el Rincón de la Maquinaria de Nogg en Orgrimmar, en el Valle del Honor.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][3981] = {title = "Comandante Gor'shak", objective = "Encuentra al comandante Gor'shak en las Profundidades de Roca Negra.\n\nRecuerdas que en el dibujo burdo había rejas sobre el rostro del orco. Quizás deberías buscar una cárcel o algo similar.", description = "Pobre Gargal... no le dio tiempo ni a olerla. ¡BAM! La flecha se le clavó en el mismísimo centro de la cabeza. No es que fuera una lumbrera antes pero ahora...\n\n<Galamav esboza una mueca.>\n\nCuando le extrajimos la flecha, descubrimos una nota enrollada en el asta. En la nota había un dibujo burdo de un orco entre rejas con la firma del comandante Gor'shak adjunta.\n\nSi aún está vivo en las Profundidades, tendrás que encontrarlo.\n\n¿Una trampa? No estoy de broma, ¡pezuñas entumecidas! ¡Por eso vas!\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4003] = {title = "El rescate real", objective = "Mata al emperador Dagran Thaurissan para liberar a la princesa Moira Barbabronce del hechizo.|n", description = "Si sale bien, este golpe a los Hierro Negro sacudirá los cimientos de su reino.\n\nLa princesa Barbabronce está bajo el control del emperador Thaurissan; para liberarla, tendrás que matarlo. Ten en cuenta que tu misión es doblemente peligrosa, porque la princesa intentará atacarte mientras esté controlada por el Emperador.\n\n¡¡Asegúrate de que no sufra daños!!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4005] = {title = "Aquamentas", objective = "Lleva el Libro de Aquor, las zarpas plateadas y el corazón de Troncoferro a Tanaris.\n\nUtiliza el Libro de Aquor para invocar Aquamentas.\n\nCuando tengas el tótem completo llévaselo a J.D. Collie en el Refugio de Marshal.", description = "Lleva esta bolsa de suministros a Tanaris. Dirígete a la Cala del Aparejo Perdido y busca un círculo de piedras.\n\nEl secreto reside en la península más oriental...\n\nSolo cuando te encuentres en el círculo, lee el Libro de Aquor e invoca la única criatura que puede transformar los objetos que has reunido en un tótem que te ayudará a combatir a Correfuego.\n\nA Aquamentas no le gustará que lo despierten, pero recuerda, debes permanecer en el círculo para poder transformar los objetos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4021] = {title = "¡Contraataca!", objective = "Mata centauros Kolkar hasta que aparezca Krom'zar, después asesínalo y coge una pieza del estandarte de Krom'zar.", description = "La Horda elogia tu éxito frente a los Kolkar pero estos están enfurecidos. Según varios informes, un contingente Kolkar ha viajado hasta Los Baldíos desde sus dominios en Desolace en busca de venganza. Las últimas noticias eran que, ahora mismo, ¡se dirigen a estos búnkeres desde el oeste!\n\nHaz frente a los invasores Kolkar y pon fin a esa amenaza en Los Baldíos. Mátalos hasta que aparezca su jefe, el señor de la guerra Krom'zar. Derrótalo y tráeme un pedazo de su estandarte como prueba.\n\nContamos contigo, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Escudo de los BaldíosVarita de supresorEscudo PortamortaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4022] = {title = "Un sabor a llamarada", objective = "Enséñale a Cyrus Therepentio la escama de Vuelo Negro que recibiste de Velarok Espada del Viento.", description = "El Vuelo tiene conocimiento de tu trabajo en La Garganta de Fuego.\n\nEnséñamela, <raza>. La escama, imbécil.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4023] = {title = "Un sabor a llamarada", objective = "Demuéstrale a Cyrus Therepentio lo que vales.\n\nTe da la impresión de que Cyrus ya sabe que no eres digno.", description = "¿Buscas al Vuelo? Apórtame una prueba de lo que vales, mortal.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4024] = {title = "Un sabor a llamarada", objective = "Viaja hasta las Profundidades de Roca Negra y mata a Bael'Gar.\n\nSolo sabes que el gigante vive en las Profundidades de Roca Negra. Acuérdate de usar la escama alterada de Vuelo Negro sobre los restos de Bael'Gar para capturar la esencia ígnea.\n\nLlévale la esencia ígnea encerrada a Cyrus Therepentio.|n", description = "Deseo probar las ardientes llamas de la montaña de fuego. Dejar que el calor del magma de Roca Negra recorra todo mi ser. Esa esencia, ese calor abrasador, es lo que ansío.\n\nBael'Gar mora en las Profundidades de Roca Negra: un ser que es llama pura, nacido de los fuegos de Ragnaros. Ejecuta a Bael'Gar y tráeme un poco de su fuego interno de entre sus ardientes restos.\n\nUsa la escama de sus restos para extraer sin peligro la llama interior.\n\nConsíguelo y recibirás tu merecida recompensa.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Manteo Piel de esquistoBufas de pellejo de vermisFajín valconianoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4061] = {title = "La revuelta de las máquinas", objective = "Adéntrate en Las Estepas Ardientes y recupera 10 fragmentos elementales fracturados para Hierofante Theodora Mulvadania.\n\nRecuerdas que Theodora mencionó que los gólems y elementales de esa región eran la fuente de estos fragmentos.", description = "Las máquinas se hicieron notar en nuestras primeras incursiones en La Garganta de Fuego. Después de investigar el asunto, descubrimos que las estaban importando de Las Estepas Ardientes, posiblemente desde las Profundidades de Roca Negra. Por eso te necesitamos, <nombre>.\n\nTu tarea consistirá en aventurarte en Las Estepas Ardientes y recuperar los fragmentos de elementales de los robots de piedra y de otras creaciones de piedra menores de la región. Cuando hayas reunido la cantidad suficiente, vuelve aquí y determinaré la fuente de procedencia.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4063] = {title = "La revuelta de las máquinas", objective = "Encuentra al Señor Gólem Argelmach y mátalo. Llévale su cabeza a Lotwil. Asimismo tendrás que reunir 10 núcleos de elemental intactos de los gólems Furiatracadores y de los ensamblajes belisario que protegen a Argelmach. Lo sabes porque eres <un adivino/una adivina>.", description = "¡No puede ser Argelmach! Mataron a Argelmach hace diez años. ¿Que cómo puedo estar seguro? Yo mismo lo maté.\n\nEra un enano despreciable, empeñado en pervertir el trabajo de mi vida para satisfacer sus diabólicas necesidades. Parece que los malvados siempre consiguen escurrirse de la justicia.\n\nSi este es el trabajo de Argelmach, debe ser destruido. Necesitaré muestras de sus creaciones más recientes. Con las muestras adecuadas, puede que consiga detener esta revuelta. Las creaciones protegen a Argelmach en las Profundidades de Roca Negra.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Armadura de escamas de basaltoAmito de luna azurMantón de lanzalluviasGuanteletes de placas de lavaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4081] = {title = "MATAR INMEDIATAMENTE: enanos Hierro Negro", objective = "Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores!\n\nEl señor de la guerra Dientegore quiere que mates a 15 celadores Yunque Colérico, 10 alcaides Yunque Colérico y 5 lacayos Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea.|n", description = "Por orden del señor de la guerra Dientegore, Comandante de la Fuerza Expedicionaria de Kargath:\n\nTodos y cada uno de los efectivos del general Forjainquina en las Profundidades de Roca Negra debe ser aniquilado.\n\nLos hombres de Forjainquina son crueles asesinos, responsables del asesinato masivo de la 109ª división de la Fuerza Expedicionaria de Kargath. Se recomienda a los héroes extremar la precaución al enfrentarse a estos animales.\n\nCualquier persona que destruya la primera línea del general Forjainquina en las Profundidades de Roca Negra recibirá un tributo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4082] = {title = "MATAR INMEDIATAMENTE: oficiales Hierro Negro de alto rango", objective = "Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores!\n\nEl señor de la guerra Dientegore quiere que mates a 10 médicos Yunque Colérico, 10 soldados Yunque Colérico y 10 oficiales Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea.", description = "Por orden del señor de la guerra Dientegore, Comandante de la Fuerza Expedicionaria de Kargath:\n\nEl jefe de la división de reconocimiento de la F.E.K., maestro mayor Lexlort, ha vuelto con noticias sobre el paradero de oficiales Hierro Negro de alto rango. A puerta cerrada, cerca del corazón de la ciudad, entrenan a sus tropas para acabar con nuestros hombres. Ve a las Profundidades de Roca Negra ¡y destrúyelos!\n\nEl éxito en esta misión se traducirá en un tributo.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4083] = {title = "El cáliz espectral", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4101] = {title = "impiar Frondavil", objective = "Lleva 15 unidades de ámbar de sangre a Arathandris Cielargento a Frondavil.", description = "Las plantas dan vida a Frondavil, pero incluso ellas sufren la mácula de la corrupción. Conozco formas de limpiarlas, pero no puedo confiar tal conocimiento a alguien de quien no me fíe. Demuéstrame que realmente deseas apoyar la causa del Círculo Cenarion.\n\nAl norte están las Cavernas de Troncoferro. Los elementales alabeos que viven en ellas ya no pueden ser salvados. Te pido que me traigas su savia. La llaman ámbar de sangre. Quiero estudiarla para ver si puedo salvar a otras formas de vida de aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4102] = {title = "impiar Frondavil", objective = "Lleva 15 unidades de ámbar de sangre a Maybess Brisa de Río a Frondavil.", description = "Las plantas dan vida a Frondavil, pero incluso ellas sufren la mácula de la corrupción. Conozco formas de limpiarlas, pero no puedo confiar tal conocimiento a alguien de quien no me fíe. Demuéstrame que realmente deseas apoyar la causa del Círculo Cenarion.\n\nAl norte están las Cavernas de Troncoferro. Los elementales alabeos que viven en ellas ya no pueden ser salvados. Te pido que me traigas su savia. La llaman ámbar de sangre. Quiero estudiarla para ver si puedo salvar a otras formas de vida de aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4103] = {title = "Bálsamo por caza", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nBálsamo de planta Cenarion"}
MultiLanguageQuestData['mx'][4104] = {title = "Bálsamo por minería", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nBálsamo de planta Cenarion"}
MultiLanguageQuestData['mx'][4120] = {title = "La fuerza de la corrupción", objective = "Talo Pezuñahendida, del Campamento Mojache de Feralas, quiere que mates a 12 pardos Zarpira y 12 devastadores Zarpayel de Frondavil.", description = "Como cazador, me esfuerzo por emular los puntos fuertes de mis adversarios. Uno puede inclinar la balanza a su favor solo con conocer bien a su enemigo, <nombre>.\n\nLas criaturas de un lugar llamado Frondavil, al norte de Vallefresno, han sido contaminadas por una sustancia energía vil. Ha desquiciado a los osos y lobos del lugar, pero yo creo que también los ha fortalecido.\n\nVe, <nombre>. Viaja a Frondavil y afronta a esas bestias. Comprueba si son tan fuertes como creo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4123] = {title = "El corazón de la montaña", objective = "Llévale el corazón de la montaña a Maxwort Suprandor en Las Estepas Ardientes.", description = "Durante años he buscado cierta gema. Se llama corazón de la montaña ¡y es tan grande como uno de tus puños! Los enanos Hierro Negro la tienen bajo llave en su cámara acorazada y, aunque lo he intentado, no me dejan comprarla.\n\nAsí que tengo recurrir a la fuerza.\n\nÁbrete paso hasta la cámara inferior de las Profundidades de Roca Negra, descubre la caja fuerte secreta y hazte con el corazón. Para ello, tendrás que derrotar al velador Presaletal ¡y solo se manifestará cuando hayas abierto todas las arcas con reliquias de la cámara!\n\nSuerte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4124] = {title = "El mensajero desaparecido", objective = "Ve al Bastión Plumaluna y habla con Ginro Mechogar.", description = "Tengo un socio, Ginro Mechogar, que está buscando ayuda para localizar a un mensajero perdido y los paquetes que llevaba. El mensajero desapareció hace aproximadamente una semana y nuestras búsquedas no han dado fruto, estamos atascados. Por desgracia, he tenido que declarar al mensajero desaparecido en combate.\n\nSi tienes tiempo y recursos que dedicar a su búsqueda, habla con Ginro. Debería estar aquí, en el bastión. Quizás en las dependencias.", progress = nil, completion = "Supongo que te envía Latro. Creo que a estas alturas es una causa perdida, pero aceptaré cualquier ayuda que me puedas proporcionar. He de reconocer que me alegraré cuando este asunto esté resuelto. Cada día me adentro en Feralas buscando a Raschal y cada noche regreso con las manos vacías... bueno, en realidad, llenas de colmillos de gnolls y de decepción.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4125] = {title = "El mensajero desaparecido", objective = "Localiza el bote del mensajero por la costa de Feralas.", description = "Raschal, el mensajero, salió para Thalanaar hace aproximadamente una semana. Conoce bien Feralas y está con nosotros desde que la general Plumaluna guio hasta aquí a las fuerzas expedicionarias. Sé que había planeado tomar un bote de remos en la costa para intentar atravesar el sur de Feralas y evitar el campamento de la Horda.\n\nYo no pude encontrar su bote, pero quizás tú sí puedas. Puede que lo escondiera o quizás se hundió. En cualquier caso, podría darte alguna pista de su paradero. Si descubres algo, házmelo saber, por favor.", progress = nil, completion = "Has encontrado lo que parecen ser los restos de un bote de remos. A través del agua, ves unos enormes agujeros en el lado de babor. El bote está casi reducido a su simple estructura de madera. Lo que quiera que rompiera el bote, probablemente intentó partirlo en dos. En la parte de estribor hay un pequeño blasón del Bastión Plumaluna.\n\nEn el barro de la base del bote, hay un brillo metálico que te llama la atención...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4126] = {title = "Hurley Negrálito", objective = "Llévale la receta de Cebatruenos perdida a Ragnar Cebatruenos en Kharanos.", description = "Los enanos Hierro Negro, dirigidos por el granuja de Hurley Negrálito, han robado una de las mejores recetas de cervezas de Cebatruenos, la rubia Cebatruenos. ¡Los muy pillastres! ¡Su paladar es indigno de tan fino brebaje!\n\n<nombre>, tengo una tarea para ti. Ve a las Profundidades de Roca Negra en Las Estepas Ardientes, destruye cualquier barril de cerveza Cebatruenos que encuentres ¡y devuélvenos la receta de la cerveza Cebatruenos!\n\nRecupera esa receta ¡aunque para ello tengas que remover cielo y tierra en las Profundidades de Roca Negra!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Cayada GolpeprestoCuchilla de extremidadRecibirás:\n\nCerveza negra enana"}
MultiLanguageQuestData['mx'][4128] = {title = "Ragnar Cebatruenos", objective = "Habla con Ragnar Cebatruenos.", description = "Hola, <nombre>. He oído que Ragnar Cebatruenos está que echa chispas por el robo de su cerveza. Está buscando fornidos aventureros y les pagará bien.\n\nHabla con Ragnar, si te interesa. Se encuentra en la Destilería Cebatruenos en Kharanos, en Dun Morogh.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4131] = {title = "Los gnolls Zarpaleña", objective = "Busca el rastro del mensajero o sus pertenencias en los campamentos de los gnoll Zarpaleña del sur de Feralas.", description = "Puede ser que nuestros \"amigos\" los Zarpaleña acabaran con Raschal al final, pero algo me dice que no es eso lo que ocurrió. Aun así, es mejor empezar por ellos.\n\nDesearía que tuviéramos una idea más clara de lo que tenemos que hacer, pero de momento tendremos que empezar por buscar en los campamentos Zarpaleña. Sé que los gnolls guardan los objetos que rapiñan y los defienden bien. Quizás encontraron las mochilas que Quint mencionó. En condiciones normales no arriesgaría un ataque directo, pero sabiendo lo que ha visto Quint, solo puedo decir: \"¡a por ellos!\"", progress = nil, completion = "En un árbol cercano hay dos grandes mochilas de piel. Ambas tienen la insignia del Bastión Plumaluna en la parte delantera...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4133] = {title = "Vivian Lagrave", objective = "Habla con la taumaturgo oscuro Vivian Lagrave en Kargath.", description = "La taumaturgo oscuro Vivian Lagrave necesita tus servicios. Se encuentra en las Tierras Inhóspitas, en la avanzada de los orcos de Kargath, le sigue la pista a unos rumores sobre cierto brebaje que preparan los enanos Hierro Negro de las Profundidades de Roca Negra.\n\nHabla con Vivian. Te aguarda.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4134] = {title = "La receta de Cebatruenos perdida", objective = "Llévale la receta de Cebatruenos perdida a Vivian Lagrave en Kargath.", description = "Se rumorea que el Hierro Negro Hurley Negrálito ha robado una receta de cerveza. Dicen que esta cerveza, la rubia de Cebatruenos, infunde gran fuerza y valor a quien la ingiere. Queremos estudiar esa bebida. A lo mejor, encontraremos otras aplicaciones para sus virtudes... aplicaciones más acordes con los objetivos de los Renegados.\n\nAdéntrate en las Profundidades de Roca Negra, encuentra a Hurley, quítale la receta de la cerveza de Cebatruenos y tráemela.\n\nY para encontrarlo, puede que tengas que engatusarlo amenazando su preciada cerveza.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Cayada GolpeprestoCuchilla de extremidadRecibirás:\n\nPoción de sanación excelentePoción de maná superior"}
MultiLanguageQuestData['mx'][4136] = {title = "Ribbly Llavenrosca", objective = "Llévale la cabeza de Ribbly a Yuka Llavenrosca en Las Estepas Ardientes.", description = "Mi hermano Ribbly siempre ha sido un pozo sin fondo para la familia, sacándonos el dinero para malgastarlo en un plan tras otro.\n\nBueno, pues su último proyecto fue el peor porque el Barón Revilgaz de Bahía del Botín acaba de ponerle precio a la cabeza de Ribbly. ¡Puedes imaginarte la alegría para los Llavenrosca! ¡Nuestro pequeño Ribbly por fin vale algo!\n\nPero ahora está escondido, en lo más remoto de las Profundidades de Roca Negra. ¡Encuéntralo y tráemelo!\n\nO, si no quiere acompañarte, entonces... basta con que me traigas su cabeza.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Botas de rencorBufas de penitenciaArmadura de acero seccionadorRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4141] = {title = "Muigin y Larion", objective = "Recoge 15 Sangrepétalos y ve a ver a Muigin.", description = "¿Has visto a Larion por ahí? ¡Es culpa SUYA que estemos aquí!\n\nLe dije que íbamos por mal camino, pero ¿acaso escuchó? ¿Puedes creerte que encima él es el que no me habla? Bueno, hasta que cambie de opinión, vamos a divertirnos un poco a su costa.\n\n¿Has visto las extrañas criaturas con forma de planta que hay por aquí? Solo son un montón de problemas, en serio, pero creo que si las instruyo como es debido, puedo hacer que obedezcan órdenes.\n\nAunque, antes de nada, voy a necesitar unas muestras para estudiarlas. ¿Crees que podrías reunir algunas muestras?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4142] = {title = "Visita a Gregan", objective = "Llévale un Sangrepétalo a Gregan Tirabirras de Feralas.", description = "No sé qué voy a hacer con esto, <nombre>. Las plantas... parecen tener una inteligencia muy reducida.\n\nAunque yo no soy ningún experto... ¡conozco a alguien que sí lo es!\n\nDirígete al norte de Feralas y busca a un colega mío llamado Gregan Tirabirras. Él es un experto en este tipo de cosas.\n\nSeguro que Gregan nos podría ayudar con esto. Lo encontrarás en plena naturaleza pues no es un tipo al que le guste vivir en una gran ciudad.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4143] = {title = "Bruma del mal", objective = "Reúne 5 muestras de calima Atal'ai y después ve a ver de nuevo a Muigin al Cráter de Un'Goro.", description = "A decir verdad, <nombre>, nunca he visto unas plantas como estas en ninguno de mis viajes. Puede que deba emprender un viaje a ese cráter... \n\nEn todo caso, sé exactamente qué es lo que está buscando Muigin: la calima Atal'ai. Se trata de algo horrible, muy difícil de conseguir, pero es justo lo que él necesita para controlar a esos pequeños monstruos.\n\nTendrás que hacer una visita a El Templo de Atal'Hakkar, en el Pantano de las Penas. La calima Atal'ai se puede obtener de los rondadores de lo profundo, los gusanos de la oscuridad y los mocos que hay allí. ¡Buena suerte, <nombre>!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4145] = {title = "Larion y Muigin", objective = "Caza 5 azotadores Sangrepétalo, 5 trilladores Sangrepétalo, 5 desolladores Sangrepétalo y 5 tramperos Sangrepétalo para Larion en el Refugio de Marshal.", description = "¿Has visto a Muigin por allí? ¡Es culpa SUYA que estemos perdidos!\n\nYo era el que conocía el camino, pero él insistió en tomar un atajo, ¡y mira dónde acabamos!\n\nY por si fuera poco, no para de mandarme sus plagas vegetales para fastidiarme. Estoy tan enfadado que no pienso hablarle en un buen tiempo, pero estas plagas son demasiado.\n\nLo primero que deberíamos hacer es intentar limitar su suministro. Sal y caza algunos Sangrepétalos. Cuando los tengas, vuelve a verme.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4146] = {title = "Combustible de irradior", objective = "Entrega el Controlador descargado y 5 muestras de calima Atal'ai a Larion, en el Refugio de Marshal.", description = "¡Estás de suerte, <nombre>! He estado trabajando en algunos experimentos mientras Marvon estaba fuera, y uno de ellos es un controlador vírico de corto alcance. Con algunos ajustes debería ayudarte a librarte de esas pestes Sangrepétalo.\n\nPuedo dejarte uno de los prototipos del controlador, pero tendrás que hacerte tú con el combustible. Podrás conseguir la calima Atal'ai necesaria para el controlador en El Templo de Atal'Hakkar. La obtendrás de los rondadores de lo profundo, de los gusanos de la oscuridad y de los mocos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4147] = {title = "El taller de Marvon", objective = "Viaja hasta el taller de Marvon Buscarroblones en Trinquete.", description = "He conseguido espiar a Muigin y ya sé qué está haciendo, ¡está cultivando esas malditas cosas ahí mismo!\n\nCreo que la única opción que nos queda... no, no es ir a hablar con él... ¿en qué estás pensando? ¡La solución es contraatacar!\n\nNecesitaremos la ayuda de mi amigo, Marvon, tiene un taller en Trinquete. Seguro que podrá crear algún artilugio para ayudarnos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4161] = {title = "La receta de los kaldorei", objective = "Collect 7 Small Spider Legs.", description = "Hace mucho tiempo, los elfos de la noche se conocían como los kaldorei, un nombre que significa \"hijos de las estrellas\". Aprender del pasado es un paso muy importante en tu camino como <clase>, <nombre>. Por ello, debes escuchar atentamente lo que tengo que decirte.\n\nLos kaldorei siempre se han sentido muy orgullosos de su armoniosa relación con la naturaleza. Esto significa que solamente cogemos de la naturaleza lo que necesitamos y lo que podemos devolverle. Este equilibrio nos ha beneficiado mucho, <nombre>.\n\nVe y recoge 7 patas de araña pequeña, ni una más ni una menos, y regresa aquí con ellas.", progress = "Recuerda el equilibrio, <nombre>. Quiero que comprendas y te compenetres con los bosques.", completion = "Recuerda siempre lo que te he enseñado hoy, &lt;nombre&gt;. Tú formas parte del equilibrio que los elfos de la noche se esfuerzan por conservar, incluso en tiempos difíciles.", rewards = "Recibirás:\n\nReceta: kebab de araña kaldoreiKebab de araña kaldorei"}
MultiLanguageQuestData['mx'][4181] = {title = "Ingeniería goblin", objective = "Si quieres saber más sobre ingeniería goblin, llévale el Manual de disciplinas de ingeniería a Nixx Muellepiñón de Gadgetzan.", description = "La ingeniería avanzada se divide en dos disciplinas: la de los gnomos y la de los goblins. Menciono a los goblins puramente porque existen. Les gustan las cosas que explotan y les da igual quién esté en medio, aun ellos mismos.\n\nLéete este manual, <nombre>. Si quieres hacerte saltar por los aires, ve a ver a Nixx Muellepiñón en Gadgetzan. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!Cuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][4182] = {title = "La amenaza de los dragonantes", objective = "Mata 15 estirpes negras, 10 dragauros negros, 4 vermintes negros y 1 draco negro.", description = "La vida en Las Estepas Ardientes está plagada de enfrentamientos.\n\n¡Fíjate en este lugar! No sabemos mucho de lo que ha ocurrido con estos edificios, pero sí sabemos que antaño, antes de la gran explosión, esto era parte de las Montañas Crestagrana.\n\n¡Basta de lamentos! Tenemos un problema, <nombre>. Puede que te hayas fijado en los dragonantes al pie de estas colinas. Necesitamos ayuda para ahuyentarlos. Mata a tantos como puedas y vuelve aquí. Si lo logras, a lo mejor seguimos hablando.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4183] = {title = "Los verdaderos maestros", objective = "Viaja a Villa del Lago, en las Montañas Crestagrana, y entrégale la carta de Helendis Rivacuerno al magistrado Solomon.", description = "Siempre habíamos creído que los orcos Roca Negra eran el producto de su salvaje educación. Lo que hemos hallado aquí, en su patria, nos muestra una cara diferente.\n\nDesde luego, la sed de sangre y de enfrentamientos los mueve pero son los Vuelo Negro quienes controlan a los orcos Roca Negra. Sospechamos que el Vuelo Negro no hace más que echar leña al fuego de su furia y hostilidad.\n\nLlévale esta carta al magistrado Solomon. Él sabrá qué hacer.\n\n<Helendis te entrega una carta sellada.>Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4184] = {title = "Los verdaderos maestros", objective = "Ve a Ventormenta para entregar la petición de ayuda de Solomon al rey Varian Wrynn. \n\nVive en el Castillo de Ventormenta.", description = "Qué sombrías nuevas, <nombre>. Descubrir que nuestros enemigos mortales no son más que marionetas de una amenaza mayor es muy desalentador. Villa del Lago no podría hacer frente a un ataque común de los orcos Roca Negra y el Vuelo Negro. Si Villa del Lago cae, Villa Oscura caerá también, ¿y qué pasará entonces? ¿Villadorada? ¿La mismísima Ventormenta? \n\n¡Debes llevar estas nuevas al rey Varian Wrynn en Ventormenta de inmediato! Si Ventormenta no nos ayuda, nada lo hará y todo se habrá perdido.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4185] = {title = "Los verdaderos maestros", objective = "Habla con el alto señor Bolvar Fordragón después de hablar con Lady Katrana Prestor.", description = "Solomon describe una imagen terrible. Sin embargo, no podemos permitirnos enviar a nuestras escasas tropas en ayuda de Villa del Lago basándonos en especulaciones. Necesitaré pruebas de esos hechos antes de poder actuar.\n\nHabla con Lady Prestor, <nombre>. Es una mujer inteligente y sabe mucho sobre dragones y dragonantes. Quizás pueda ayudarnos a comprender mejor la situación.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4186] = {title = "Los verdaderos maestros", objective = "Lleva el decreto de Wrynn al magistrado Solomon en la Villa del Lago.|n", description = "Voy a nombrarte ayudante del alguacil de Ventormenta, <nombre>.\n\nVuelve a ver al magistrado Solomon en Villa del Lago y entrégale este decreto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4201] = {title = "La poción de enamoramiento", objective = "Llévale 4 gromsanguinas, 10 venas de plata gigantescas y el vial lleno de Nagmara a la coima Nagmara en las Profundidades de Roca Negra.", description = "¡Ah, el sufrimiento del amor! Mi querido soldado Sinroca es inmune a mis encantos. ¡Me rechaza! ¡Me lleva por la calle de la amargura!\n\n¡Tienes que ayudarme! Las súcubos sabemos mucho de amor y puedo hacer una poción para que derrita el telón de acero que rodea el corazón de Sinroca. Para hacerla, necesito estos elementos: hierba gromsanguina, venas de plata gigantescas de los gigantes de los acantilados de Azshara, y agua del Cráter Manantial de Golakka en Un'Goro. Toma este vial para el agua.\n\nTe lo ruego, <nombre>, ¡ayuda a un alma desgraciada a alcanzar su felicidad!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Cinturón de castigo de NagmaraEsposasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4243] = {title = "Buscando a Memo 01", objective = "Encuentra a Memo 01 en el Cráter de Un'Goro.", description = "Desafortunadamente, le ha ocurrido algo a una de mis mejores invenciones. Has visto las ardillas mecánicas, ¿verdad? Bien, para poder estudiar de cerca a los simios del Cráter de Un'Goro he creado un simio mecánico hembra que he bautizado como Memo 01.\n\nSus ojos son dos gemas de visión y por ellas puedo ver todo lo que ella ve. Sé que consiguió llegar a la guarida de los simios de Roca Fungal, al este desde aquí, pero allí perdí el contacto con ella. ¡Lo último que vi fue a uno de los machos alfa corriendo hacia ella para saludarla!\n\n¿Podrías ayudarme a encontrarla?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4244] = {title = "Buscando a Memo 01", objective = "Encuentra una envoltura de mitril y reúnete de nuevo con Memo 01 en el Cráter de Un'Goro.", description = "Una investigación más profunda muestra un panel abierto. Encima del cableado, está escrito con claridad el siguiente mensaje: \"Sustituir la envoltura de mitril, y apagar y volver a encender la corriente\".\"\n\nMientras sustituyes el panel, te preguntas si será tan fácil reparar a Memo 01 y llevársela de vuelta a Karna Tripirrem hasta el Refugio de Marshal.\n\nSolo lo sabrás si lo intentas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4262] = {title = "Maestro supremo Pyron", objective = "Mata al Maestro Supremo Pyron.\n\nRecuerdas que Jalinda dijo que Pyron guardaba la cantera. Quizás deberías empezar a buscar allí.", description = "Mis últimos cinco magos que salieron a husmear por la Montaña Roca Negra volvieron rustiditos y crujientes o algo peor.\n\n<Jalinda recoge unas cenizas del suelo y las suelta en el aire.>\n\nUn asqueroso granuja en especial, el Maestro Supremo Pyron, parece estar causando más de un quebradero de cabeza. ¡Tenemos que aniquilar a ese elemental para que los miembros de nuestra expedición puedan llegar a las Profundidades de Roca Negra!\n\nLo encontrarás custodiando la entrada de la cantera de Roca Negra.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4264] = {title = "Una nota arrugada", objective = "Puede que acabes de toparte con algo que le interesaría ver al mariscal Windsor. Puede que haya esperanza, después de todo.", description = "La nota está cubierta de manchas. Es apenas legible, aunque se llega a ver lo siguiente: \n\n... qué ironía tan oportuna...\n\n... la caída de la Alianza rota...\n\n... si no fuera por la diligencia del general Forjainquina, es posible que jamás hubiésemos descubierto la clave de la codificación...\n\n... Argelmach casi ha acabado de descifrar los apuntes de Windsor.\n\nNuestro señor surgirá de las profundidades y aplastará cualquier resto...\n\n-Emperador Dagran Thaurissan.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4265] = {title = "Liberado de la colmena", objective = "Libera a Raschal de la vaina de los Zukk'ash.\n\nVuelve al Bastión Plumaluna con Ginro Mechogar e infórmale de que Raschal está bien.", description = "La vaina se abre cuando la tocas, revelando en su interior a un elfo de la noche que, sorprendentemente, sigue con vida. Parece estar bien, aunque terriblemente aturdido. Mientras le ayudas a salir de la vaina, empieza a recuperarse.\n\n\"¡Gracias a Elune! ¡Me has salvado! Yo... Me llamo Raschal. Fui atacado por unos insectos y me desperté paralizado dentro de esta vaina. ¿Te envían del Bastión?\"\n\n¡Diría que has encontrado al mensajero desaparecido!", progress = nil, completion = "Bienvenido a casa, &lt;nombre&gt;. Raschal llegó hace no mucho y me contó lo que ocurrió.\n\nYo... no, todo el Bastión, te agradece enormemente lo que has hecho. Raschal habría muerto si no hubieras llegado tú, y tu ayuda nos ha llegado por apenas la tasa de un mercenario. Eres un auténtico héroe. Siempre contarás con la amistad de Ginro Mechogar.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4267] = {title = "La sublevación de los silítidos", objective = "Lleva el informe de Raschal a Gracina Poderespíritu a Darnassus.", description = "Te confío una copia del informe que Raschal redactó sobre las criaturas del sur de Feralas. El informe original se ha enviado a Darnassus, pero yo quiero que entregues esta copia a una persona del Protectorado. Se llama Gracina Poderespíritu y es una sacerdotisa que vive en el Templo de la Luna, en Darnassus. Tiene unos grandes conocimientos sobre este tipo de criaturas. Sería beneficioso para todos que leyera este informe.\n\nRetírate, <nombre>. Y buena suerte, que Elune vele por todos nosotros.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de la dunaManijas de maleanteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4281] = {title = "Una entrega en Thalanaar", objective = "Lleva el paquete sin entregar a Díscolo Falfindel a Thalanaar.", description = "Este paquete que encontraste en los campos gnoll de Zarpaleña estaba destinado al pequeño apeadero de Thalanaar del sureste de Feralas. No sabemos qué suerte corrió el mensajero, pero de momento nos preocupa más que el paquete no fue entregado.\n\nExaminas el paquete y en la parte exterior ves un nombre: Díscolo Falfindel. Quizás sea el destinatario final del paquete.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4283] = {title = "¡CINCUENTA! ¡SÍ!", objective = "Reúne 50 medallones Roca Negra.", description = "Voy a contarte un secretito, soldado. Acércate un poco más.\n\n¡SOY EL ÚNICO CUERDO AQUÍ!\n\n¡Fíjate en esta gente! ¿¡Quién diría que están todos locos!? ¡Pues lo están! ¡TARADOS! ¡COMPLETAMENTE IDOS!\n\n<Oralius baja la voz.>\n\nQue esto quede entre tú y yo, y mi amigo el capitán Winky.\n\n<Oralius hace un gesto como queriendo atrapar el aire.>\n\nDa iguaaaal... Estoy recolectando insignias para mi colección de orejas de ogro. Orco es el sabor del día. 50. ¡Vete!\n\n<Oralius sopla en una corneta.>\n\n¡ANDANDO!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4284] = {title = "Cristales de poder", objective = "Recoge 7 cristales de poder de cada color: rojo, azul, amarillo y verde. Llévaselos a J.D. Collie en el Refugio de Marshal.", description = "Estoy segura de que ya los habrás visto, <nombre>. ¡Están por todas partes!\n\n¿De qué estoy hablando? ¡De los cristales, por supuesto!\n\nLos cristales... Están por todo el cráter. La mayoría los ignoran, pero tengo la sensación de que albergan un inmenso poder. He estado haciendo experimentos con ellos, pero no puedo averiguar nada. Bueno, todavía no lo he hecho.\n\nMe estoy quedando sin cristales... ¿crees que podrías ayudarme a reunir algunos más?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4285] = {title = "La Torre de cristal del Norte", objective = "Descubre la localización de la Torre de Cristal del Norte en el Cráter de Un'Goro.", description = "¿Para qué podrán servir? ¡No puedo dejar de darle vueltas!\n\nMe estoy volviendo loca... quizás todos los rumores que he oído sobre las torres de cristal sean ciertos. Llámame ingenua, pero suelo creer todo lo que me cuentan.\n\nEn cualquier caso, he oído que una de esas torres de cristal está aquí cerca, hacia el Norte... Por favor, encuéntrala, <nombre>. Sé que existen.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4286] = {title = "Buena mercancía", objective = "Recupera 20 riñoneras Hierro Negro.", description = "El capitán Winky me dice que los Hierro Negro de las Profundidades tienen todo lo bueno. ¿No es cierto, Winky?\n\n<Oralius imita lo mejor que puede a un pirata.>\n\n¡ARRR COLEGA! ¡DAGUTEN!\n\n¿Ves a qué me refiero? Tienes que ir allí y traerme unas muestras de esa mercancía tan buena.\n\n¡Ve y al rico dinerito!\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nUna riñonera deslucida"}
MultiLanguageQuestData['mx'][4287] = {title = "La Torre de cristal del Este", objective = "Descubre la localización de la Torre de Cristal del Este en el Cráter de Un'Goro.", description = "Durante mi estancia aquí, he oído extraños rumores sobre unas misteriosas torres repartidas por todo el cráter, <nombre>. Supongo que son bastante grandes, con cristales en su interior.\n\nAunque lo cierto es que todavía no he visto ninguna. No puedo ayudarte, pero creo que los rumores son ciertos y que las torres tienen algo que ver con todos los cristales que encontramos por esta zona.\n\n¿Por qué no me ayudas a saciar esta curiosidad? Al parecer hay una de esas torres en la zona oriental del cráter. ¿Crees que podrás encontrarla?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4288] = {title = "La Torre de cristal del Oeste", objective = "Descubre la localización de la Torre de Cristal del Oeste.", description = "Hasta ahora mis experimentos no han dado ningún resultado positivo, <nombre>. No puedo ayudarte, pero espero que puedas encontrar una solución buscando una de las torres de las que he oído hablar.\n\nTal vez si combináramos en ellas determinados colores... Pero estoy yendo demasiado deprisa. ¡Lo primero es dar con ellas!\n\n<nombre>, busca en la zona occidental del Cráter, al parecer por esa zona hay una de esas torres.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4289] = {title = "Los simios de Un'Goro", objective = "Llévale 2 pelambres de gorila de Un'Goro, 2 pelambres de vapuleador de Un'Goro y 2 pelambres de tronador de Un'Goro a Torwa Abrecaminos, que está a la entrada del Cráter de Un'Goro.", description = "Este cráter está lleno de criaturas extrañas; parecen ser versiones más refinadas de las criaturas que habitan en mi tierra y más allá. No puedo explicarlo, pero este lugar es una vergüenza para la Madre Tierra. Por ello, perseguir a estas criaturas es una muestra de respeto hacia ella.\n\nSi deseas complacerla, dirígete al norte. Allí encontrarás a grandes simios que ponen a prueba la fuerza de cualquier mortal. Tráeme sus pieles como prueba de tu éxito.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4290] = {title = "La comida de Lar'korwi", objective = "Encuentra la última presa muerta de Lar'korwi y roba un trozo de trillanodonte muerto, y después ve a ver de nuevo a Torwa Abrecaminos al Cráter de Un'Goro.", description = "Una vez, mucho tiempo atrás, uno de mis hermanos robó carne de una de las presas de Lar'korwi. En aquel momento él no lo sabía, pero Lar'korwi lo estaba observando desde el bosque. Lar'korwi persiguió a mi hermano durante días, destruyó todo a su paso. Mi hermano, asustado, decidió escapar del cráter y dejar atrás a Lar'korwi.\n\nFinalmente, Lar'korwi lo mató no lejos de su morada.\n\nSi deseas provocar la ira de Lar'korwi, busca una de sus presas frescas y roba un poco de carne.\n\nDespués vuelve aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4292] = {title = "El cebo para Lar'korwi", objective = "Utiliza el contenido de la faltriquera de Torwa para atraer la presencia de Lar'korwi y derrótalo. Después llévale la cabeza de Lar'korwi a Torwa Abrecaminos, que está cerca de la entrada del Cráter de Un'Goro.", description = "Esta es la parte más difícil debido a la complejidad que entraña el plan. Al norte de aquí encontrarás un pequeño rastro que te conducirá a las montañas. Fue allí donde vi a Lar'korwi por última vez. Sabrás que estás en el lugar correcto por los huesos de animales gigantescos que una vez vivieron en los alrededores. Lleva la carne que recogiste antes y déjala allí. Después, aplícale esta mezcla que he preparado. Si ambos señuelos juntos no son capaces de llevar a Lar'korwi hasta ti, entonces nada podrá hacerlo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guerrera de acechador de las llanurasLeotardos de escoltaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4293] = {title = "Muestras de babosa...", objective = "Recoge muestras de babosa de Frondavil de cualquiera de las babosas que encuentres en Frondavil. Después utiliza el equipo de estudio que el químico Fuely tiene al lado, en Entrañas, para ver qué muestras están más corruptas. Llévale 5 de las muestras de Frondavil corruptas que encuentres al químico Fuely.", description = "Frondavil es un bosque situado muy lejos al norte de Los Baldíos, incluso más lejos que Vallefresno. Allí, las babosas pueblan los alrededores de las pozas de agua bendecidas con un toque de vileza. La Plaga provocó muchos daños en la zona con los ataques de los infernales y otras magias demoníacas, y se dice que las babosas brotaron de la tierra durante estos ataques.\n\nRecoge muestras de las babosas de Frondavil y utilizaremos el equipo de estudio que tengo a mi lado para crear un grupo de control para diferenciarlas de otras muestras que recojas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4294] = {title = "... y unos mocos", objective = "Recoge muestras de babosa de Un'Goro de cualquiera de las babosas que encuentres en el Cráter de Un'Goro. Después utiliza el equipo de estudio que el químico Fuely tiene al lado, en Entrañas, para ver qué muestras son más puras. Llévale 5 de las muestras de Un'Goro puras que encuentres al químico Fuely.", description = "¿Has oído hablar del Cráter de Un'Goro, <nombre>? Está cerca del Desierto de Tanaris y es un lugar fascinante: exuberante, vibrante, lleno de fauna y de flora.\n\nAllí es adonde debes ir. Me he enterado de que ese lugar nunca había sido mancillado y es ahora cuando los expedicionarios comienzan a descubrir sus secretos.\n\nQuiero que estudies las babosas y mocos que hay allí. Si es cierto lo que dicen, que se trata de un lugar incorrupto, me gustaría descubrir la evolución de estas criaturas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4296] = {title = "La tablilla de los Siete", objective = "Obtén la transcripción de tablilla.", description = "Vine a Las Estepas Ardientes siguiendo por la leyenda de los Siete. Eran enanos de profundos conocimientos y enorme poder, y si tienes ambos, seguro que consigues grandes riquezas.\n\nEso quiero yo. ¡Riquezas!\n\nSi conseguimos averiguar más sobre los Siete, a lo mejor conseguimos enriquecernos. Corren rumores de que en las Ruinas de Thaurissan se halla la Tablilla de los Siete, que contiene el conocimiento de los ancestrales enanos. Encuentra esta tablilla, copia el texto y tráemela. ¡Descifremos juntos sus secretos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4300] = {title = "Armas con filo de hueso", objective = "Lleva 8 garras blancas de ravasaurio a Jes'rimon a Orgrimmar.", description = "Mmm, a lo mejor sí puedes hacer algo por la Mano, ahora que lo pienso. Seguro que puedes ayudar a Jes'rimon.\n\nEn el Cráter de Un'Goro hay raptores con unas garras mortales. Algunos las tienen blancas en vez de negras como la muerte. Hay \"clientes\" aficionados a las armas fabricadas con estas garras. Tráeme garras blancas y te pagaré bien. Si lo haces lo bastante rápido, a lo mejor puedo hacer algo más por ti.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Trituradora de hueso blancaLanza de hueso blancaPodrás elegir una de estas recompensas:\n\nSortija de hueso blanca\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][4301] = {title = "El poderoso U'cha", objective = "Llévale la pelambre de U'cha a Torwa Abrecaminos, que está a la entrada del Cráter de Un'Goro.", description = "Mientras explorabas Un'Goro, he visto algo que a <un poderoso cazador/una poderosa cazadora> como tú seguramente le interese. Se trata del gorila más grande de entre todos los que habitan hacia el norte. Ya has estado antes en esa cueva, aunque ahora, temo que no sobrevivas a esta empresa si aceptas la tarea.\n\nLo llamo U'cha, y es uno de los hijos pródigos de la Madre Tierra, de eso puedes estar <seguro/segura>. Vence a U'cha y tráeme su pelambre. Hazlo y demuestra que eres <un/una> gran <cazador/cazadora>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "MachacabestiasDestripadora de bestiasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4324] = {title = "Yuka Llavenrosca", objective = "Habla con Yuka Llavenrosca en Las Estepas Ardientes.", description = "Aunque mi hermano pequeño Ribbly ha sido un inútil toda su vida, ¡creo que por fin tiene algún valor! Pero... podríamos necesitar tu ayuda para sacar partido a ese nuevo valor de Ribbly.\n\nMi hermana Yuka lleva semanas buscándolo y la pista lleva a Las Estepas Ardientes. Me ha pedido que contrate ayuda.\n\nBueno, ¿qué me dices? ¿Quieres ayudar? Si estás de acuerdo, habla con mi hermana. La encontrarás escondida en el Peñasco Llamarada, una cueva al noroeste de la Roca Machacamiedo.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][4341] = {title = "Kharan Martillo Poderoso", objective = "Ve a las Profundidades de Roca Negra y encuentra a Kharan Martillo Poderoso.\n\nEl rey dijo que estaba prisionero allí; busca una cárcel.", description = "¿Has estado en las requemadas Ruinas de Thaurissan? ¿No te encontrarías con un patán que se llama Kharan Martillo Poderoso? ¡Ese enano tenía que cuidar a mi nena!\n\n<Solloza.>\n\n¡Ha desaparecido, <nombre>!\n\nMis hombres han recorrido las Estepas de punta a punta buscándola. La única pista que tienen sobre mi hija es que puede estar en las profundidades. ¡Ni siquiera sé si aún vive!\n\nParece que tienen a Kharan prisionero... ¡ve y encuéntralo! ¡Quiero respuestas!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4362] = {title = "El destino del reino", objective = "Vuelve a las Profundidades de Roca Negra y rescata a la princesa Moira Barbabronce de las garras del emperador Dragan Thaurissan.|n", description = "Parece que tanto yo como el reino de Forjaz estamos a merced de mi antiguo enemigo, Dagran Thaurissan.\n\nEres mi última esperanza, <nombre>. ¡Rescata a mi querida Moira!\n\nSolo hay una forma de romper el hechizo que Thaurissan ha lanzado sobre mi hija: matarlo.\n\n¡Y tráeme a mi hija sana y salva, <nombre>! ¡Recuerda que está embrujada por Thaurissan! ¡Lo que haga o diga será por culpa de ese maléfico hechizo!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4363] = {title = "La sorpresa de la princesa", objective = "Regresa a Forjaz y habla con el rey Magni Barbabronce.", description = "Thaurissan era un gran y honorable enano. ¡Me has destrozado la vida y la de mi futuro hijo!\n\n<Crees que la Princesa Barbabronce aún puede estar sufriendo algún efecto del hechizo del Emperador.>\n\nVuelve a Forjaz y dile a mi padre que el heredero del Reino de Forjaz será un enano Hierro Negro.\n\nTanto si lo aprueba como no, así será.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nTestamento de MagniPiedracanto de Forjaz\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][4421] = {title = "a corrupción de los Fuego de Jade", objective = "Mata a 11 jurapenas Fuego de Jade, 9 acechasombras Fuego de Jade, 9 pícaros Fuego de Jade y a Xavathras. Vuelve con Eridan Vientoazul a Frondavil cuando hayas completado la misión.", description = "No son muchos los que buscan aventuras aquí... La corrupción de Frondavil está muy extendida.\n\nComo miembro del Círculo Esmeralda, intento curar esta tierra, pero hay quienes desean que acabe de corromperse.\n\nEsos \"quienes\" son los sátiros Fuego de Jade que moran al noroeste de aquí, en las Ruinas de Constellas. Están al mando de un sátiro particularmente cruel llamado Xavathras. Y contagian el mal a cualquier criatura que encuentran.\n\nDebemos defender esta tierra que antaño fuera nuestra. Derrota a Xavathras y destruye a sus esbirros.", progress = nil, completion = "Liberar a Frondavil de Xavathras es el primer paso de un largo proceso. Reparar el daño que se ha hecho aquí requerirá mucho trabajo. \n\nPercibo que hay algo más grande actuando aquí... más poderoso que los sátiros. Pero solo el tiempo nos revelará la verdad...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4449] = {title = "Atrapado", objective = "Mata a 8 geólogos Hierro Negro y lleva 15 paños de seda a la persona encerrada en las letrinas de La Garganta de Fuego.", description = "¡Eh! ¡Oye, tú! ¡Ven aquí!\n\nAyúdame. Me escondí aquí para huir de los Hierro Negro. ¡Malditos sean los geólogos y sus trucos mágicos! Supongo que me vieron entrar y bloquearon la puerta.\n\n¡Dales una lección! Ah, y tráeme unos cuantos paños de seda para... Esto, para... Para nada.", progress = "¡Que no tengo todo el día! Tráeme la seda, digo mata a los geólogos. Que sientan el peso de mi ira. Bueno, de la tuya.", completion = "¡Qué tacto tan suave! \n\n¿Qué? Ah, sí, los geólogos... ¿Has acabado con ellos? Gracias, &lt;nombre&gt;. Ahora tendré tiempo de acabar. Gracias de nuevo, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4450] = {title = "El libro de contabilidad de Tanaris", objective = "Lleva el libro de contabilidad de Buenacero y busca los objetos de la lista antes de ir a verlo a Tanaris.", description = "Ah, ahora que me acuerdo:\n\n¿quieres acabar un trabajito que acepté en Tanaris? Es fácil...\n\nKrinkle Buenacero, de Gadgetzan, anda buscando unos objetos en La Garganta de Fuego y otros sitios. ¿Qué tal si te encargas tú?\n\nSi te interesa, te pasaré su libro de contabilidad por debajo de la puerta. Dáselo a Buenacero cuando vayas a llevarle los objetos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Vara relámpago cargadaFaja de RepresaliaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4451] = {title = "La llave de la libertad", objective = "Busca en La Garganta de Fuego para ver cómo se usa la llave de la letrina de Limugre.", description = "Esta pequeña llave de latón es muy sencilla. Lo único que destaca es un grabado:\n\n\"Letrina Hierro Negro. No hacer copia.\"\n\nNo tienes ni idea de qué significa o qué abre.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4463] = {title = "Tratado sobre Reflexión", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][4481] = {title = "Tratado sobre Constitución", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][4482] = {title = "Tratado sobre Tenacidad", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][4483] = {title = "Tratado sobre Resistencia", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nArcanum de Temple inferior"}
MultiLanguageQuestData['mx'][4484] = {title = "Tratado sobre Voracidad", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nArcanum de Voracidad inferiorArcanum de Voracidad inferiorArcanum de Voracidad inferiorArcanum de Voracidad inferiorArcanum de Voracidad inferior"}
MultiLanguageQuestData['mx'][4485] = {title = "Escrito sobre nobleza", objective = "Habla con Duthorian Rall en Ventormenta.", description = "Hola, <nombre>. Veo que tu entrega sigue siendo absoluta, al igual que tu fe.\n\nCreo que ha llegado el momento de que hables con Duthorian Rall en Ventormenta. Todavía tienes que aprender más lecciones y creo que estás <preparado/preparada>.\n\nBúscale en la Catedral de la Luz, y <nombre>, tómate las lecciones en serio. Has conseguido llegar donde estás mediante humildad y trabajo duro, no nos decepciones volviéndote arrogante.\n\nCuídate.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4486] = {title = "Escrito sobre nobleza", objective = "Habla con Duthorian Rall en Ventormenta.", description = "Bien, bien, bien, mira al poderoso paladín en toda su gloria.\n\nLo siento, <nombre>, no pretendía ofenderte... Es solo que, algunas veces, siento celos cuando veo lo que has logrado. Tiza me dice que es mi debilidad y le he jurado intentar superarlo. Pero algunas veces es difícil, ¿sabes?\n\nQuería hablar contigo porque Duthorian Rall, de Ventormenta, quiere verte en la Catedral de la Luz cuando estés <listo/lista>. Parecía importante. Como si algo estuviera pasando.", progress = nil, completion = "Ah, has vuelto a la Catedral, &lt;nombre&gt;. Bien. Últimamente han ocurrido muchas cosas y me gustaría pedirte ayuda si demuestras ser digno de ella. \n\nTenemos a muchos enemigos traicioneros por aquí. Necesito que me ayudes a detenerlos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4487] = {title = "Invoca un corcel vil", objective = "Habla con Strahad Farsan en Trinquete.", description = "Ah, ya estás aquí. Había enviado un <súcubo/infernal> a avisarte, pero veo que has llegado antes de que te encontrara. No importa.\n\nÚltimamente ha habido rumores sobre tu creciente poder, lo que es bueno para ti y seguramente malo para otros. Pero eso es irrelevante. Lo importante es que has demostrado tu valía y te mereces una especie de... bendición.\n\nMás allá de Trinquete, en Los Baldíos, vive un hombre llamado Strahad; creo que ya lo conoces.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4488] = {title = "Invoca un corcel vil", objective = "Habla con Strahad Farsan en Trinquete.", description = "Ah, <nombre>, es maravilloso que te hayas dignado visitarnos.\n\nSupongo que no esperas música ni grandes honores. Estás aprendiendo deprisa, pero te falta mucho camino para llegar a la verdadera sabiduría. Si no tienes cuidado, la corrupción se apoderará de ti y tu débil voluntad.\n\nPero bueno, a lo que iba: Strahad quiere hablar contigo. Sigue viviendo en su torre de Trinquete, en Los Baldíos. Y te sugiero que no tardes mucho en ir.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4489] = {title = "Invoca un corcel vil", objective = "Habla con Strahad Farsan en Trinquete.", description = "¡Eh, <raza>! ¡Ven aquí!\n\nTú eres <nombre>, ¿no?\n\nEso pensaba. Seré breve: no ha pasado desapercibido que estás ganando poder. Ha llegado el momento de recibir una recompensa por tus esfuerzos.\n\nVe a Los Baldíos; en la torre de Trinquete encontrarás a Strahad Farsan, ¿te acuerdas de él? Quiere hablar contigo. No tardes mucho en ir.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4490] = {title = "Invoca un corcel vil", objective = "Habla con Strahad Farsan en Trinquete para aprender a invocar a un corcel vil.", description = "Quiero recompensarte por tu paciencia y tus esfuerzos. Pero debes saber que la habilidad para invocar un corcel vil será mucho más difícil en el futuro. Tendrás que ganártela, y no será fácil.\n\nPor el momento, tienes el poder de invocar a esta criatura a tu voluntad.Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nCorcel vil\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][4492] = {title = "¡Perdido!", objective = "Encuentra a Ringo en la Cresta del Penacho en Llamas.", description = "¡Tienes que ayudarme, <nombre>! Mi amigo, Ringo, partió para explorar el volcán que está al sur de aquí y ha estado fuera demasiado tiempo. Estoy muy preocupada por él.\n\n¿Crees que podrás encontrarlo? Llévate mi cantimplora, ¡si encuentras a Ringo estoy segura de que le hará falta!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4493] = {title = "La marcha de los silítidos", objective = "Habla con el alquimista Morterozugg en Gadgetzan.", description = "Parece que el propósito de los silítidos o, mejor dicho, su razón de ser, es devorar todo lo que no comparta su naturaleza y esté en su camino. Su objetivo es singular y por este motivo representan una grave amenaza para la vida de Azeroth.\n\nLo que hemos visto hasta hoy es solo el principio. Sospecho que su fuerza proviene de las profundidades de Kalimdor. Del Cráter de Un'Goro. Ve a Gadgetzan, en el Desierto de Tanaris, y habla con el alquimista Morterozugg. Háblale de mi teoría. Él nos ayudará a combatir a los silítidos, sin duda.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4494] = {title = "La marcha de los silítidos", objective = "Habla con el alquimista Morterozugg en Gadgetzan.", description = "Parece que el propósito de los silítidos o, mejor dicho, su razón de ser, es devorar todo lo que no comparta su naturaleza y esté en su camino. Su objetivo es singular y por este motivo representan una grave amenaza para la vida de Azeroth.\n\nLo que hemos visto hasta hoy es solo el principio. Sospecho que su fuerza proviene de las profundidades de Kalimdor. Del Cráter de Un'Goro. Ve a Gadgetzan, en el Desierto de Tanaris, y habla con el alquimista Morterozugg. Háblale de mi teoría. Él nos ayudará a combatir a los silítidos, sin duda.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4495] = {title = "Un buen amigo", objective = "Encuentra a Iverron cerca de la cueva que hay al norte.", description = "Tengo un amigo llamado Iverron que suele venir a verme a la misma hora cada día. Pero hoy no ha venido.\n\nReconozco que su ausencia me inquieta, <nombre>. Pasa mucho tiempo en la cueva que hay al norte, y ya sabes lo peligroso que es, con todas esas arañas por allí.\n\nSi vas hacia allí, ¿te importa buscar a mi amigo?", progress = nil, completion = "Me alegro de verte, &lt;nombre&gt;. ¿Cómo sabías que estaba aquí?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4496] = {title = "Que jungla tan chunga", objective = "Llévale una glándula secretora de olor Gorishi y 5 muestras de la tierra de Un'Goro al alquimista Morterozugg de Gadgetzan.", description = "Mi investigación revela que los silítidos son como las abejas: si matas a la reina de la colmena, los demás se verán sumidos en la confusión. Prepararé un señuelo para atraer a la reina y, una vez fuera, tú acabarás con ella.\n\nPara ello, necesitamos algunos componentes pues no es conveniente que te aventures sin estar bien <preparado/preparada>. Ve al oeste y localiza una colmena de silítidos en el Cráter de Un'Goro. Cuando la hayas encontrado, consigue una glándula secretora de olor de uno de esos bichos. También necesitaré algunas muestras de la tierra de Un'Goro.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4501] = {title = "Cuidado con los pterrordáctilos", objective = "Mata a 10 pterrordáctilos demenciados. Cuando lo hayas hecho habla con Spraggle Frock en el Refugio de Marshal.", description = "Se busca: Diestro guerrero que se encargue de la amenaza de los pterrordáctilos que habitan en el Cráter de Un'Goro. Su número está creciendo y se están convirtiendo en una seria amenaza para los viajeros de la zona.\n\nReduce su población matando a 10 pterrordáctilos demenciados.\n\nCuando termines tu tarea dirígete a Spraggle Frock para pedir tu recompensa.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de grutaGrebas de placas de riscoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4502] = {title = "Actividad volcánica", objective = "Lleva 9 muestras de ceniza de los elementales de fuego del Cráter de Un'Goro a Liv Rizzlefix a Trinquete.", description = "He aprendido mucho con Marvon Buscarroblones. Pero hace tanto que se fue que creo que voy a ocuparme de algunos experimentos míos.\n\nHe estado leyendo acerca del Cráter de Un'Goro y la extraña actividad volcánica de su centro. Creo que podría averiguar mucho si consiguiera ceniza de los elementales que hay allí.\n\nSi vas hacia allí, ¿puedes recoger algo de ceniza para traérmela?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4503] = {title = "El aparato volador de Shizzle", objective = "Recoge 8 escamas de diemetradón palmeadas y 8 escamas de pterrordáctilo palmeadas para Shizzle, en el Refugio de Marshal.", description = "¡Estoy construyendo una máquina voladora!\n\nMe he quedado varado aquí, y soy un desastre para orientarme. Utilizaría un grifo o un Jinete del Viento para regresar a Gadgetzan pero esas bestias me ponen los pelos como escarpias.\n\n¿Me ayudarás? Lo único que me queda por construir son las alas, y estaba pensando que las escamas palmeadas de los pterrordáctilos y diemetradones serían ideales. De ninguna manera me enfrentaría a uno de esos, pero tú pareces bastante fuerte. ¿Por qué no lo intentas?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Frenalloviznas de ShizzleBozal de ShizzleEscamondador de ShizzleRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4504] = {title = "Superpegajoso", objective = "Reúne 12 muestras de alquitrán muy pegajoso para Tran'rek de Gadgetzan.", description = "Siempre estoy pensando en un modo rápido de ganar un poco de oro, <nombre>. Si me ayudas en mi nueva idea, te daré parte de las ganancias. ¿Qué te parece?\n\n¡Me lo imaginé!\n\nVe a las fosas de alquitrán en la parte norte del Cráter de Un'Goro y recoge algo de alquitrán. Pero no cualquier alquitrán... Tendrás que recoger el que queda depositado sobre las bestias que habitan en las proximidades de las fosas, pues el alquitrán normal no es muy buen pegamento.\n\nLa piel de esas criaturas con aspecto de plantas contiene clorofila que, si se mezcla con el alquitrán, da como resultado una sustancia extremadamente pegajosa.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4505] = {title = "l pozo de la corrupción", objective = "Recoge una muestra de agua corrupta de la Poza de la Luna de los sátiros Fuego de Jade y llévasela a Winna Riessgo al Puesto del Veneno.", description = "Hay quien opina que soy excepcionalmente cruel... Pero en verdad, siento solo un fortísimo deseo de que la Horda gane ventaja frente a la Alianza, y para eso me valgo de cualquier medio.\n\nMi interés más reciente es una Poza de la Luna que hay en las Ruinas de Constellas, al sur de aquí y que está cuidada por sátiros Fuego de Jade. La Poza, que antaño fue un símbolo de renovación para los insufribles elfos de la noche, ahora está corrupta y se utiliza para traer más sátiros al mundo.\n\nTengo una idea, <nombre> y quisiera probar una cosa. Necesito que me traigas una muestra del agua para mi pequeño amigo felino.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4507] = {title = "El señuelo atrapa a la reina", objective = "Derrota a la reina de la colmena Gorishi cuando hayas conseguido que salga al exterior.\n\nLlévale el cerebro de la reina Gorishi al alquimista Morterozugg de Gadgetzan.", description = "¡Aquí tienes el señuelo! Dentro de la colmena debería haber un cristal. Creemos que este cristal constituye el punto central de la colmena. Yo diría que para localizarlo deberías buscar los criaderos en el interior de la colmena.\n\nSi colocas el señuelo sobre el cristal, la reina debería sentirse atraída. Pero ten cuidado pues podría contar con la protección de varios guardias. Saca a la reina de la colmena y extrae su cerebro. Aunque pueda parecer repugnante, necesitamos estudiarlo urgentemente. ¡Buena suerte, <nombre>!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4509] = {title = "La calma que precede a la tormenta", objective = "Llévale el informe de Un'Goro de Morterozugg a Zilzibin Tambor Sabio, que está en Orgrimmar.", description = "Mis recientes descubrimientos y lo que hemos averiguado aquí deben ser transmitidos a alguien que sepa interpretar toda esta información. Por muchos recursos que tengamos aquí en Gadgetzan, no podemos hacer esto solos.\n\nLlévale mi último informe a Zilzibin Tambor Sabio, que está en Orgrimmar. ¿Sigue viviendo en el nivel superior de La Calle Mayor, verdad? Él tiene amigos muy influyentes dentro de la Horda. Si conseguimos que se involucren en este tema, <nombre>, quizás podamos salir con vida de todo esto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4511] = {title = "La calma que precede a la tormenta", objective = "Lleva el vale a Karus al banco de Orgrimmar.", description = "<nombre>, sin ti nunca habríamos llegado tan lejos. Llegará el momento en el que tendré que volver a pedirte que nos ayudes a combatir a los silítidos. Temo que mi idea de que los silítidos tenían su origen en Un'Goro era equivocada... Hay sin duda una presencia más fuerte en algún lugar.\n\nLleva esta nota al banco y dásela a Karus. Te dará algo de mi arca que debes aceptar como una muestra de mi gratitud. Gracias por tu ayuda, valiente <clase>.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Bufas de ladinoGrebas de rehuidaPodrás elegir una de estas recompensas:\n\nOrbe de olvido\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][4512] = {title = "Un largo camino para unas babosas", objective = "Consigue 6 jarros llenos de moco maldito y 6 jarros llenos de moco corrupto para Laris Mecaparra en Forjaz.", description = "Pero lo que más he estudiado son los mocos. Sé que suena raro, ¡pero están por todas partes!\n\nHace poco ayudé a una dama de Menethil a buscar su bolso; estaba comido por los mocos. He visto a miembros de la Sociedad Real de Boticarios de Entrañas recogiendo muestras. ¡Quiero saber por qué! ¿De dónde salen?\n\nDicen que también hay en Frondavil. Necesito muestras de moco para seguir investigando. Te daré unos contenedores para que recojas alguna de estas criaturas muertas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4513] = {title = "Un largo camino para unas babosas", objective = "Lleva 10 tarros de muestra pura a Laris Mecaparra a Forjaz.\n\nSi no los encuentras, habla con Laris.", description = "<nombre>, voy a necesitar más muestras. Pero necesito que sean puras. Lo sé, lo sé. Eso de \"puras\" no te dice gran cosa. No sé qué decirte, sé que estas muestras están corrompidas, como lo está Frondavil. Y esto es lo que hace que mi descubrimiento sea tan importante. Al parecer, los mocos se adaptan al espacio que ocupan. Necesito muestras de moco no contaminado. ¿Que dónde buscar? No lo sé.\n\nMira, <nombre>, llévate estos contenedores por si encontraras algún moco puro.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Botas de calimaGuanteletes de latónRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4521] = {title = "Guardianes salvajes", objective = "Trull Fallarruina de Frondavil quiere que mates 15 lechubestias enfurecidas y 15 lechubestias pulgosas.", description = "Cuna del Invierno se encuentra nada más atravesar el Bastión Fauces de Madera, al norte de Frondavil. ¿Has estado allí?\n\nHe oído que la zona está repleta de unas criaturas llamadas lechúcicos salvajes. Se sabe que esas bestias guardan secretos, secretos de los elfos de la noche.\n\nDebemos descubrir qué es lo que se oculta en Cuna del Invierno.\n\nHe oído que pueden encontrarse lechubestias pulgosas al sur del camino, y que hay otras llamadas lechubestias enfurecidas en el centro de Cuna del Invierno. Acaba con ellas y accede a esas tierras.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4542] = {title = "Mensaje para el Poblado Viento Libre", objective = "Entrégale el mensaje urgente al vigiarrisco Cuerno Largo en el Poblado Viento Libre.", description = "Valiente <viajero/viajera>, los centauros atacan cada vez con más frecuencia en la zona. ¡El Poblado Viento Libre tiene que saberlo inmediatamente! Busca al vigiarrisco Cuerno Largo en el Poblado Viento Libre al sudeste y entrégale este mensaje urgente.\n\nTen cuidado de no cruzarte con el Clan Tótem Siniestro... últimamente tienen una actitud muy extraña con nosotros.\n\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4581] = {title = "Kayneth Ventoleve", objective = "Llévale la nota de Shindrell a Kayneth Ventoleve en Canción del Bosque.", description = "El druida Kayneth Ventoleve me ha enviado un mensaje. Le gustaría obtener un informe de los acontecimientos en nuestras costas y en los bosques que rodean Astranaar. Teme que haya corrupción recorriendo Vallefresno... y puede que tenga razón.\n\nToma, llévale mi informe. Lo encontrarás en el altar de la Canción del Bosque, en el Bosque Arrullanoche hacia el este.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4621] = {title = "¡Adelante, almirante!", objective = "Mata al maestro de flota Cuernomarino y al Barón Revilgaz de la Bahía del Botín y, a continuación, vuelve a reunirte con el maestro de flota Firallon a bordo del Velo Carmesí, cerca de la costa de la Vega de Tuercespina.", description = "Escucha con atención, lobo de mar... los poderes de la Bahía del Botín es lo que no nos permite a los Velasangre navegar por donde queremos ni coger lo que queremos como botín. Si atravesaras con un cuchillo al maestro de flota Cuernomarino, nunca se nos interpondría en el camino un barco de la Bahía del Botín. Si atravesaras con un cuchillo al Barón Revilgaz, nunca nos tendríamos que enfrentar a la ley, a su ley.\n\nSi quieres convertirte en <un/una> almirante entre nosotros, sí, ALMIRANTE, utiliza un cuchillo con esos dos como yo te digo. Vete, <muchacho/muchacha>, y vuelve a verme cuando hayas acabado.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSombrero de almirante Velasangre"}
MultiLanguageQuestData['mx'][4641] = {title = "Tu lugar en el mundo", objective = "Habla con Gornek. Recuerda que Kaltunk marcó en tu mapa su ubicación y que te mencionó que Gornek reside en El Cubil, un edificio que está al oeste.|n|n", description = "Por fin ha llegado el momento, <nombre>... el momento de que combatas en nombre de la Horda. Conquistarás por la gloria de nuestro Jefe de Guerra.\n\nSí...\n\n<Kaltunk te examina.>\n\nLo harás bien.\n\nSupongo que estarás deseando encontrar un dragón o un demonio enorme para estrangularlo con las manos, pero quizás sería más inteligente empezar por algo menos... peligroso.\n\n<Kaltunk se ríe.>\n\nBusca a Gornek. Él podrá asignarte una tarea adecuada para ti, joven <clase>. Lo encontrarás en El Cubil, al oeste.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4642] = {title = "Fusión de influencias", objective = "Llévale una muestra de moco fusionado al químico Fuely de Entrañas.", description = "Esta caja contiene un moco creado a partir de las muestras que recogiste en Frondavil. Llévala contigo al Cráter de Un'Goro y encuentra un moco de los de verdad... uno de la variedad primaria servirá. Cuando estés lo suficientemente cerca, libera el moco de la caja y veamos qué piensan uno del otro.\n\nCuando concluya el experimento, tráeme una muestra de lo que haya resultado. Yo te estaré esperando aquí, en El Apothecarium.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Guardapolvo de químicoPodrás elegir una de estas recompensas:\n\nAnillo de químico\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][4701] = {title = "Acaba con el origen de la amenaza", objective = "Viaja hasta la Cumbre de Roca Negra y destruye el origen de la amenaza del huargo. Cuando dejaste a Helendis, gritó un nombre: Halycon. Es la palabra que los orcos usan para referirse al huargo.", description = "No cabe duda de que has visto a los huargos a las órdenes de los orcos Roca Negra.\n\nEs extraño, matemos a los que matemos, no parece reducirse su número. Según los informes de mis exploradores, los huargos se crían, se amaestran y se exportan desde la Cumbre de Roca Negra: la capital de los orcos Roca Negra. Debes viajar hasta la Cumbre de Roca Negra y descubrir el origen de esta amenaza. Descúbrelo... y destrúyelo.\n\nSuerte, <nombre>. Que Cenarius te proteja...\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Togas de AstoriaChaleco de caladorCoraza de Luna de jadeRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4722] = {title = "Tortuga marina varada", objective = "Lleva los restos de la tortuga marina a Gwennyth Bly'Leggonde a Auberdine.", description = "Encuentras el cadáver de una tortuga marina que fue a encallarse a Costa Oscura hace algún tiempo. Los múrlocs se han instalado a su alrededor y ya han hurgado entre los restos de la criatura. Aun así, parece que quedan algunas muestras de los restos que podrían resultar útiles a Gwennyth Bly'Leggonde de Auberdine.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4723] = {title = "Criatura marina varada", objective = "Lleva los huesos de la criatura marina a Gwennyth Bly'Leggonde a Auberdine.", description = "En la costa de Cabo de la Niebla yacen los restos de un trillador gigante... uno mucho mayor de lo que podría esperar encontrar en Costa Oscura... Es un misterio cómo llegó esta criatura hasta aquí. Los múrlocs que ahora se alimentan de su cadáver parecen demasiado débiles para derribar a una criatura semejante, incluso en gran número. \n\nNo queda mucho de la criatura, pero sí lo suficiente para recoger una muestra y llevársela a Gwennyth Bly'Leggonde de Auberdine para que la estudie.", progress = "Perhaps one day we'll find a means to prevent these poor creatures from ending their lives needlessly on the coast of Darkshore.  Until then, we must continue our research!\n\nGreetings <nombre> - what news do you bring?", completion = "Another discovery - well done &lt;nombre&gt;!  These remains will be properly studied once they get to Darnassus.  Please accept this small honorarium in exchange for the remains you have provided for our study.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4724] = {title = "La maestra de la manada", objective = "Mata a Halycon, la maestra de la manada de los huargos Hacha de Sangre.", description = "Hay quien dice que los huargos controlados por los orcos Roca Negra son una creación de una fuerza sobrenatural. Otros dicen que no son auténticos huargos sino una variedad de perro demoníaco, concedida a los orcos por un señor del infierno caído.\n\nLa verdad no es tan artificiosa aunque ciertamente igual de aterradora. Los huargos de Roca Negra proceden de Halycon y su pareja. Halycon la gigantesca Madre de El Cubil del huargo. ¿Su pareja? Nadie ha vivido nunca para contarlo.\n\nDispara al corazón del huargo. Acaba con Halycon... y, <nombre>, que no te sorprendan por la espalda.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Togas de AstoriaChaleco de caladorCoraza de Luna de jadeRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4725] = {title = "Tortuga marina varada", objective = "Lleva la caja con símbolos extraños a Gwennyth Bly'Leggonde a Auberdine.", description = "Hay muchos restos de tortugas marinas a lo largo de la costa. Esta en concreto tiene una especie de carruaje abandonado atado a la concha de la tortuga. Quizás esta criatura no vino a morir a la costa como parece que han hecho las demás, sino que fue traída por algún ser. Los múrlocs Bruma Gris han convertido los restos de esta criatura en su hogar y se alimentan de su cuerpo.\n\nEn el carruaje encuentras una caja con símbolos extraños. Quizás Gwennyth Bly'Leggonde de Auberdine sepa interpretarlos.", progress = "It is a pleasure to see you again, <nombre>.  We are making great strives in uncovering the mystery of why majestic sea creatures beach themselves on the Darkshore coastline, but with every question answered, two more are raised it seems.\n\nAre you here to offer us more aid in our research?", completion = "I have heard of the kinds of carriages found on the back of the turtle you found.  Those I do believe are naga carriages, used both in battle and in transportation of their supplies on to land.  The markings on the box you found are of the naga; this would explain their invasive presence in far-northern Darkshore.\n\nI will send this box to Darnassus along with the rest of your discoveries.  This is for you - thank you again for your assistance.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4726] = {title = "Esencia de cría", objective = "Llévale 8 esencias de cría y el Draco-Incarcinatrix 900 a Tinkee Vaporio en el Peñasco Llamarada, en Las Estepas Ardientes.", description = "He estado estudiando a los dragonantes de Las Estepas Ardientes durante semanas ¡y creo que por fin tengo algo importante! He creado un dispositivo al que he llamado Draco-Incarcinatrix 900. ¡Es capaz de capturar la esencia de los cachorros de dragón!\n\nO al menos eso pienso yo.\n\nToma, llévate el dispositivo a Las Estepas Ardientes y dispárale a un cachorro de dragón con él. Mientras está bajo los efectos del dispositivo, derrota al dragón y entonces se debería liberar su esencia.\n\nY si así es, ¡fantástico! ¡Tráeme muestras para que pueda examinarlas!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4728] = {title = "Criatura marina varada", objective = "Lleva los huesos de la criatura marina a Gwennyth Bly'Leggonde a Auberdine.", description = "El cadáver, que parece ser de una especie de mamífero marino, yace medio destripado en la playa. Alrededor de esta enorme criatura encallada hay una carretilla y algunas herramientas, como si alguien hubiera intentado examinar los restos. Aunque los múrlocs ya han saqueado los restos, queda suficiente para reunir una muestra adecuada para Gwennyth Bly'Leggonde de Auberdine.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4729] = {title = "Las mascotas exóticas de Kibler", objective = "Viaja hasta la Cumbre de Roca Negra y encuentra cachorros de huargo Hacha de Sangre. Usa la jaula para transportar a esas feroces fierecillas. Llévale a Kibler 1 cachorro de huargo enjaulado.", description = "Debes de estar preguntándote qué hago aquí. ¡Fíjate en las jaulas! ¿Acaso no salta a la vista?\n\nSoy un amante de los animales ante todo aunque sea vendedor de profesión. Les sigo la pista a los animales exóticos para los ricos y los famosos y amaestro a esas bestias para que se comporten como mascotas normales.\n\nY ahora te preguntarás, \"¿Qué puedo hacer por ti, Kibler?\" La respuesta es sencilla: Llévate esta jaula de bestia y encuéntrame unos cachorros de huargo. Si lo haces, ¡amaestraré a un huargo para ti!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nTransportador de huargos"}
MultiLanguageQuestData['mx'][4730] = {title = "Criatura marina varada", objective = "Lleva los huesos de la criatura marina a Gwennyth Bly'Leggonde a Auberdine.", description = "El cuerpo medio devorado de lo que podría ser un gigante mamífero marino yace en la playa. Una banda de múrlocs, más fuertes que los que encontraste cerca de Auberdine, se ha instalado alrededor de la criatura. Quedan suficientes restos del esqueleto de la criatura para llevar una muestra de sus huesos a Gwennyth Bly'Leggonde a Auberdine.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4731] = {title = "Tortuga marina varada", objective = "Lleva la caja con símbolos extraños a Gwennyth Bly'Leggonde a Auberdine.", description = "Hay otro grupo de restos de una tortuga marina encallada en la costa. Estos restos tienen una especie de carruaje abandonado atado a la concha de la tortuga. Quizás esta criatura no vino a morir a la costa como parece que han hecho las demás, sino que fue traída por algún ser. Unos poderosos múrlocs Bruma Gris han hecho de los restos de esta criatura su hogar.\n\nEn el carruaje encuentras una caja con símbolos extraños. Quizás Gwennyth Bly'Leggonde de Auberdine sepa interpretarlos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4732] = {title = "Tortuga marina varada", objective = "Lleva los restos de la tortuga marina a Gwennyth Bly'Leggonde a Auberdine.", description = "Encuentras el cadáver de una tortuga marina que fue a encallarse a la Costa Oscura hace algún tiempo. Los múrlocs Bruma Gris que han acampado alrededor de la criatura han limpiado prácticamente todos los restos. Aun así, parece que quedan algunas muestras que podrían resultar útiles a Gwennyth Bly'Leggonde de Auberdine.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4733] = {title = "Criatura marina varada", objective = "Lleva los huesos de la criatura marina a Gwennyth Bly'Leggonde a Auberdine.", description = "Los restos de lo que parece ser un trillador gigante han aparecido encallados en una ensenada rocosa de la Orilla Crepuscular. El trillador es varias veces más grande que los trilladores que suelen verse en esta zona. Viniera de donde viniera, esta criatura no parece ser de Costa Oscura. Aunque la criatura ha sido rapiñada, quedan suficientes restos para reunir una muestra adecuada para Gwennyth Bly'Leggonde de Auberdine.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4737] = {title = "Buscando a Menara Nadiz", objective = "Habla con Menara Nadiz en Los Baldíos.", description = "Mm... te sigues esforzando por hacerte más <poderoso/poderosa>. Mantengo que es solo una cuestión de tiempo antes de que la corrupción y la adicción se apoderen de ti y te conviertas en <un esclavo/una esclava> de aquello que intentas dominar.\n\n¡Bah! ¡Habrase visto semejante <necio/necia>! El tiempo me dará la razón, nada más... basta con dejarlo pasar.\n\nPero por lo visto, no todos están de acuerdo con Zevrost. Al parecer, Menara ha creado herramientas para que adquieras aún más poder y que aproveches tu fuerza. Si te interesa, ve a Trinquete en Los Baldíos. Está allí en la torre que domina la ciudad.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4738] = {title = "Buscando a Menara Nadiz", objective = "Habla con Menara Nadiz en Los Baldíos.", description = "Dejemos algo claro, <nombre>: no creo que estés <listo/lista> para tales responsabilidades. No creo que ayudar a la creación de ningún objeto de poder sea algo en lo que debería intervenir ningún principiante; especialmente uno apenas probado.\n\nPero esa decisión no depende de mí. Los poderes establecidos, o al menos los que desean que te transmita tales bienes así lo han decidido.\n\nSi te interesa aprender más, te sugiero que busques a Menara Nadiz en Trinquete. Suele encontrarse en la torre que domina la ciudad portuaria.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4739] = {title = "Buscando a Menara Nadiz", objective = "Habla con Menara Nadiz en Los Baldíos.", description = "¡<clase>! ¡<El/La> que viste y calza!\n\nNo tienes todo el equipo pero es fácil ver que estás a punto, exudas mayor seguridad en ti <mismo/misma>. Así es, ahora lo veo.\n\nMenara Nadiz te enseñaría unas cuantas cosas si te sientes <preparado/preparada>. Se pasa el tiempo formando a alumnos más jóvenes en la magia arcana. Incluso ofrece regalos a quien supera sus pruebas.\n\nVe a Trinquete en Los Baldíos, si te interesa. Ella está en la ciudad, en la torre de Strahad que la domina.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4740] = {title = "SE BUSCA: ¡Viscoso!", objective = "Encuentra y mata al múrloc conocido como Viscoso. Se cree que la criatura está defendiendo el emplazamiento múrloc al sur de Auberdine, cerca del agua. \n\nInforma de la muerte de Viscoso a la centinela Glynda Nal'Shea, en Auberdine.", description = "¡Atención!\n\nSe ofrece una recompensa por la cabeza del múrloc \"Viscoso\". Esta inmunda bestia es responsable de la muerte de al menos un centinela y sospechosa de haber provocado el hundimiento de al menos dos navíos de carga en las aguas de Costa Oscura.\n\nViscoso fue visto por última vez en un campamento múrloc al sur de Auberdine. Se cree que está protegiendo el emplazamiento. Quien desee reclamar la recompensa, debe acudir a la centinela Glynda Nal'Shea, en Auberdine.\n\nEl Concejo de Auberdine.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guardabrazos de maderaBrazales CrestaFaja arrecifeRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4741] = {title = "Guardianes salvajes", objective = "Trull Fallarruina de Frondavil quiere que caces 13 lechubestias lunadón.", description = "En las zonas septentrionales de Cuna del Invierno, los lechúcicos salvajes son todavía más feroces. Debemos seguir allí con nuestras medidas.\n\nDa caza a las lechubestias lunadón de Cuna del Invierno y explora la zona en la que habitan.\n\nEs un terreno muy peligroso, pero sé que podrás enfrentarte al desafío. Vuelve a verme cuando hayas acabado con 13 de esos lechúcicos salvajes.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4742] = {title = "El sello de ascensión", objective = "Encuentra las 3 gemas del mando: La gema de Espina Ahumada, la gema de Cumbrerroca y la gema de Hacha de Sangre. Llévaselas, junto con el sello de ascensión sin adornar a Vaelan.\n\nLos generales, como te dijo Vaelan, son: el maestro de guerra Voone de los Espina Ahumada, el alto señor Omokk de los Cumbrerroca y el señor supremo Vermiothalak de los Hacha de Sangre.", description = "Como verás, el sello sin adornos tiene tres ranuras vacías. En cada ranura hay que encajar una gema que representa el mando del liderazgo. Por último, el señor supremo Vermiothalak, maestro de la ciudadela inferior, debe forjar el sello con las llamas del Vuelo Negro.\n\nDebes entender esto, mortal: la probabilidad de que uno de los tres generales de la ciudadela inferior lleve una gema en cualquier momento es escasa. Debes estar muy atento en tu misión. ¡Mantén la determinación!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4743] = {title = "El sello de ascensión", objective = "Viaja a la Ciénaga de Fuego en Marjal Revolcafango. Encuentra al anciano draco Brasaliza y derrótalo sin contemplaciones hasta doblegar su voluntad.\n\nEste es el preciso momento en el que debes colocar el Sello de ascensión sin forjar ante la colosal bestia. Debes entonces ser rápido en usar el orbe de energía dracónica sobre su debilitada forma y reclamar el dominio sobre sus facultades mentales. ¡Controla la bestia y dirige las llamas del Vuelo Negro sobre el Sello de ascensión sin forjar!", description = "Pocos dragonantes, que no sean los de la ciudadela superior, tienen la habilidad de forjar el sello con su propio aliento llameante. Vermiothalak es uno de esos dragonantes pero su voluntad es inquebrantable.\n\nDebes ir a la Ciénaga de Fuego en Marjal Revolcafango. Allí encontrarás a un anciano draco llamado Brasaliza. Debes romper su voluntad, <nombre>. Rómpela y usa este orbe cuando esté debilitado. Tendrás escasos segundos para controlar su mente y avivar las llamas que forjarán el sello.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de ascensión"}
MultiLanguageQuestData['mx'][4763] = {title = "La corrupción de los Bosque Negro", objective = "Llena el cuenco purificador vacío en la Poza de la Luna de Auberdine. \n\nRecoge una muestra de fruta, nueces y grano del campamento del norte de los fúrbolgs Bosque Negro. \n\nMezcla todo en el cuenco, llévalo al campamento norte y colócalo cerca de la hoguera más cercana al Río Fonroca; así convocarás al sátiro corruptor. \n\nCoge el dije de corrupción y llévaselo a Thundris Tejevientos a Auberdine.", description = "Hemos descubierto que la fuente de la corrupción de los fúrbolgs es el sátiro. Los domina por medio de dijes con los que canaliza su magia. Si queremos salvar a los fúrbolgs, debemos atrapar al sátiro corruptor y hacernos con su dije.\n\nLlena este cuenco en la Poza de la Luna y toma muestras de comida del campamento norte de los fúrbolgs. Mezcla ambas cosas y colócalas en la hoguera, cerca del río. Cualquier fúrbolg que coma de esa mezcla quedará purificado durante el tiempo que necesitas para hacer salir al sátiro corruptor... ¡y matarlo!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Leotardos de protector salvajeMusleras de tormenta de ráfagasVarita de piedra lunarRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4764] = {title = "El Broche de Equipasino", objective = "Llévale el broche de Equipasino a Mayara Alasol en Las Estepas Ardientes.", description = "En lo más alto de la Cumbre de Roca Negra, hay una cámara antaño llamada Sala de la Fortuna. Allí era donde los enanos Hierro Negro guardaban sus reliquias, trofeos y obras de arte.\n\nEso era hace mucho tiempo. Se dice que la sala se ha derrumbado y se usa hoy para... tareas menos limpias. Pero me parece que aún se encuentran allí antiguas reliquias de los enanos.\n\nUna de esas reliquias es el Broche de Equipasino, en cuya superficie hay engarzadas gemas tan raras que, al parecer, cualquier enano que posa su vista en él se echa a llorar.\n\nEse broche, <nombre>, es nuestro objetivo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4766] = {title = "Mayara Alasol", objective = "Habla con Mayara Alasol en Vigilia de Morgan en Las Estepas Ardientes.", description = "Envié a una espía, Mayara Alasol, a Las Estepas Ardientes para que rastreara la ciudad en ruinas de Thaurissan. Puede que la asolada ciudad de los enanos Hierro Negro oculte objetos de gran valor... objetos que quedarían muy bien en el museo de nuestra familia.\n\nMayara dice que encontró algo y que necesitaría ayuda para recuperarlo pero no está en Thaurissan. Es en la Cumbre de Roca Negra adonde haría falta realizar una incursión.\n\nDesconozco los detalles pero si estás <interesado/interesada>, habla con Mayara en Las Estepas Ardientes.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4767] = {title = "Jinete del viento", objective = "Consigue 10 huevos de dracoleón de Nido Alto para Elu en el Poblado Viento Libre.", description = "Me ha sido encomendada la tarea de reclutar más dracoleones para los jinetes del viento. Cada vez son más y yo espero algún día convertirme en un jinete del viento como ellos. Sin embargo, la demanda de dracoleones es tan elevada que no somos capaces de instruir a todos los necesarios. Quizás tú puedas ayudarme, <nombre>.\n\nNecesito que vayas a Nido Alto y que consigas unos cuantos huevos de dracoleón. Desde aquí, dirígete hacia el noroeste siguiendo las paredes del cañón hasta llegar a una rampa que te conducirá a Nido Alto. Ten cuidado pues los dracoleones son muy protectores con sus huevos y no les gustará nada la presencia de <un intruso/una intrusa>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nRefuerzo para armadura pesado"}
MultiLanguageQuestData['mx'][4768] = {title = "La tablilla de Rocanegra", objective = "Llévale la tablilla de Rocanegra a la maga oscura Vivian Lagrave en Kargath.", description = "La tablilla de Rocanegra contiene los escritos del enano Urheld Rocanegra fallecido mucho tiempo ha. Alquimista de gran talento, sus coetáneos lo tomaban por loco, de ahí que no compartiera sus hallazgos.\n\nPero sí lo dejó grabado en unas tablillas y creo que una de ellas se encuentra en la Cumbre de Roca Negra, en una cámara antaño llamada Sala de la Fortuna. Desconozco su nombre actual ya que pocos son los que han entrado en Roca Negra y han regresado.\n\nPero si estás <dispuesto/dispuesta> a afrontar sus peligros y traerme la tablilla, te recompensaré con creces.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guardabrazos golpeguiñoBotines PieprestoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4769] = {title = "Vivian Lagrave y la tablilla de Rocanegra", objective = "Habla con la maga oscura Vivian Lagrave.", description = "Vivian Lagrave me ha enviado un mensaje desde Kargath, en las Tierras Inhóspitas. Sus estudios la llevan a creer que en la Cumbre de Roca Negra se encuentra un antiguo texto que podría ayudarnos en nuestra investigación. Para confirmarlo, necesita que alguien consiga el texto de la Cumbre. Ardua tarea sin duda.\n\nSi estás <interesado/interesada>, habla con Vivian en Kargath.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4770] = {title = "De vuelta a casa", objective = "Saca a Pao'ka Monte Presto de Nido Alto y después habla con Motega Pirocabello en Campamento del Tramo Blanco.", description = "¡Por favor ayúdame, <clase>! Llevo tiempo ocultándome en Nido Alto y hace días que no veo una cara amiga. Vine aquí para estudiar a los dracoleones pero creo que me acerqué demasiado. Me echaron de uno de los nidos y entonces me perdí.\n\n¡Necesito volver a Campamento del Tramo Blanco! Motega no sabe que estoy aquí y se pondría furioso si se enterara de que me aventuré en Nido Alto yo solo.\n\nEl Campamento del Tramo Blanco está justo al este de aquí... ¡Por favor, llévame hasta allí!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4781] = {title = "Los componentes para la toga de sangre dorada encantada", objective = "Llévale un lingote de oro a Xizk Cortefino en la Vega de Tuercespina.", description = "Tu siguiente tarea es tan sencilla como la primera pero hará falta que busques ayuda.\n\nNecesito hilo de oro para los bordados de la capa pero no es fácil de obtener, y muy pocos saben cómo fabricarlo. Por suerte, uno que es fiel a nuestra causa conoce sus secretos y está deseando contribuir al auge de nuestras filas.\n\nLlévale un lingote de oro a Xizk Cortefino en Bahía del Botín. Es un maestro sastre y se alegrará de hilar una bobina para ti. Los mineros expertos funden los lingotes de oro. Pídele ayuda a un minero.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4783] = {title = "Los componentes para la toga de sangre dorada encantada", objective = "Llévale 10 viales de sangre Odio Feroz y 1 piedra Infernal inferior a Menara Nadiz en Los Baldíos.", description = "Encontrarás los siguientes componentes en Desolace, lejos hacia el oeste de Los Baldíos e incluso en Sierra Espolón.\n\nAllí, sigue el caos sembrado por el Diluvio. Tu fuerza y astucia se pondrán a prueba, tendrás que enfrentarte a criaturas de odio así como a la Legión Ardiente.\n\nDel sátiro Odio Feroz al noreste, tráeme la sangre. De los infernales inferiores en el Aquelarre Mannoroc, tráeme una piedra infernal inferior.\n\nSon dos elementos que usaremos en la confección de tu túnica.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4784] = {title = "Los componentes para la toga de sangre dorada encantada", objective = "Llévale unos hilos finos de oro, 2 trozos de ascuas humeantes y 1 fragmento de alma a Menara Nadiz en Los Baldíos.", description = "Ahora solo necesito tres cosas para acabar tu túnica, <nombre>.\n\nEn primer lugar, el hilo de oro que Xizk te está preparando. Vuelve con él a Bahía del Botín y tráelo.\n\nEn segundo lugar, tráeme dos fragmentos de carbón ardiente de los elementales de fuego de las Tierras Altas de Arathi. Si no me falla la memoria, están hacia el oeste, cerca de la Muralla de Thoradin.\n\nPor último, un fragmento de alma creado por ti.\n\nCuando tengas todos los componentes, vuelve aquí a la torre y te remataré la túnica.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4787] = {title = "El huevo antiguo", objective = "Llévale el huevo antiguo a Yeh'kinya, que está en Tanaris.", description = "La profecía de Mosh'aru habla de un huevo antiguo. Es una reliquia de un tiempo en el que los trols gobernaban extensos imperios y tiene el poder de retener la esencia de Hakkar. Puede que sea el único modo de proteger nuestro mundo de su maldad.\n\nTráeme el huevo antiguo, <nombre>. Se dice que permanece oculto en Jintha'Alor en las Tierras del Interior, en una cueva bajo el anfiteatro en la parte alta de la ciudad.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4788] = {title = "Las últimas tablillas", objective = "Llévale la quinta y sexta tablillas Mosh'aru al prospector Ferrobota, que está en Tanaris.", description = "Mientras yo examino la tercera y cuarta tablillas Mosh'aru, ¡tú tienes que encontrar la quinta y la sexta! No será fácil pues obran en poder de los trols Espina Ahumada en Cumbre de Roca Negra. Esta cumbre es una oscura montaña de fuego situada entre Las Estepas Ardientes y La Garganta de Fuego.\n\nBuena suerte, <nombre>. Cumbre de Roca Negra no es un lugar para pundonorosos...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4808] = {title = "Felnok Acerovera", objective = "Entrégale la carta de Tinkee a Felnok Acerovera en Vista Eterna, en Cuna del Invierno.", description = "Necesitaría otro favor de ti.\n\nMi estudio inicial de la esencia que has recolectado indica que ¡cabría la posibilidad de congelar huevos de dragón y conservarlos! Quiero probar esta teoría pero antes necesito unos componentes especialmente diseñados para este fin. Mi colega, Felnok Acerovera, puede fabricarlos.\n\nAquí tienes una carta para Felnok. En ella le cuento lo que necesito. Encontrarás a Felnok en la Cuna del Invierno, en la ciudad de Vista Eterna.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4809] = {title = "Cuernos de Orvallo", objective = "Reúne 8 cuernos de quimera del Orvallo.", description = "Ya tengo la mayoría de lo que necesita Tinkee, aunque me falta un componente importante: cuernos de quimera. Los podrás encontrar en Cuna del Invierno. Estos cuernos son una fuente concentrada de frío, pero solo sirven los prístinos e intactos. Para completar la orden de Tinkee voy a necesitar algunos.\n\nTráemelos y prepararé el paquete.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4811] = {title = "El cristal rojo", objective = "Viaja al este de Auberdine y busca un gran cristal rojo en la zona montañosa que hay al este de Costa Oscura. Vuelve a Auberdine e informa de lo que has encontrado a la centinela Glynda Nal'Shea.", description = "Hay lechúcicos lunares hostiles dirigiéndose hacia el este, cada vez en mayor número. Antes se consideraban criaturas amables, casi místicas. Y aunque hay quien sigue sintiendo veneración por ellos, la seguridad de Auberdine me fuerza a tener una visión más realista.\n\nSegún mis informes, los lechúcicos lunares están siendo conducidos hacia un gran cristal rojo que se encuentra en las montañas del sur de Costa Oscura. Nadie sabe qué es ese cristal. Ni siquiera si existe realmente. Quiero que lo busques y vengas a informarme de lo que encuentres.", progress = nil, completion = "So the crystal exists, &lt;nombre&gt;?  Fascinating... anyway, your task has been well executed; good work!\n\nWhat exactly is this crystal?  This is but a single question in a sea of questions.  Another question that comes to mind is why the moonkin would be drawn to this object?  Is the crystal benign in nature, or does it hold a more sinister purpose?\n\nI have many more questions, but we're going to need to examine that crystal closely to get some answers.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4812] = {title = "Agua en cascada", objective = "Llena el tubo de agua vacío en la Poza de la Luna de Auberdine y luego examina el cristal rojo a lo largo de la pared montañosa oriental de Costa Oscura.", description = "Utiliza este vial vacío para recoger algo de agua de la Poza de la Luna de Auberdine. Su potente magia debería ayudarnos a averiguar cuál es la composición del cristal. Para hacerlo, vierte el líquido sobre el cristal. Él debería hacer el resto.\n\nNo espero que encuentres ningún peligro, pero quiero que seas prudente por si acaso. Frondavil está al este de aquí. Si ese cristal está vinculado a ese lugar, como yo sospecho, podría resultar muy peligroso.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4813] = {title = "Los trozos del interior", objective = "Vuelve a Auberdine e informa de lo que has averiguado a la centinela Glynda Nal'Shea.", description = "El agua de la Poza de la Luna ha revelado que en el interior del cristal hay unos pequeños trozos de hueso y media mandíbula. El hueso maxilar parece ser de un humanoide, pero no hay forma de confirmarlo sin romper el cristal, tarea que incluso la magia más potente encontraría virtualmente imposible.\n\nUna vez completada esta tarea, solo queda ir a Auberdine a informar a la centinela Glynda Nal'Shea.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Espada corta de acero brezoDaga de madera curvaBastón de robleRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4821] = {title = "Un huevo extraño", objective = "Devuélvele el huevo extraño a Hagar Pezuña del Rayo, que está en el Poblado Viento Libre.", description = "Ha surgido un rumor acerca de un extraño huevo aquí en Las Mil Agujas. Aquellos que afirman haberlo visto ni siquiera han podido acercarse a él para examinarlo al detalle pues está protegido por serpientes que lo defienden como si fuera uno de sus propios huevos.\n\nQuiero que encuentres ese huevo extraño y me lo traigas para poder examinarlo. Parece ser que el huevo está situado en una guarida de serpientes, pero hay varias en la base de los riscos sur y noreste del Poblado Viento Libre.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4841] = {title = "Apaciguar al centauro", objective = "Mata a 12 exploradores Galak, 10 retadores Galak y 6 cazavientos Galak, y después ve a ver de nuevo al vigiarrisco Cuerno Largo al Poblado Viento Libre.", description = "<nombre>, te ruego que mates a estos centauros. ¡Que sientan la cólera de nuestra venganza! Ataca el campamento de los centauros situado al norte del Poblado Viento Libre. ¡Que la cólera guíe tu mano!\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4861] = {title = "Lechúcico salvaje iracundo", objective = "Localiza el campamento arrasado y los suministros de Jaron Tallapiedras en la parte sur de Cuna del Invierno.", description = "¡Hola <muchacho/muchacha>! ¡Unos sanguinarios lechúcicos salvajes me persiguieron desde mi campamento, en el sur de Cuna del Invierno! Creo que me acerqué demasiado a algo que estaban protegiendo.\n\nA duras penas conseguí escapar, pero por desgracia un compañero mío no tuvo tanta suerte. ¿Querrías enfrentarte a los lechúcicos salvajes y dirigirte al campamento? Necesito mis suministros y también debería recuperar el amuleto que desenterré ayer en la excavación.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4862] = {title = "Bestia amaestrada", objective = "Viaja a la Cumbre de Roca Negra y reúne 15 huevos de araña de la cumbre para Kibler.\n\nYo diría que se pueden encontrar estos huevos cerca de arañas.|n", description = "Lo creas o no, ¡hay gente dispuesta a pagar por la más malvada de las bestias amaestradas!\n\nHabía enviado a Bijou a la Cumbre para tratar de recolectar algunos de esos huevos de araña pero hace semanas que no sé nada de ella. ¿A lo mejor puedes ayudarme?\n\nPues, verás, <nombre>, ve a la Cumbre de Roca Negra y recoge unos huevos de araña para mí. Tráemelos aquí y no solo te daré dinero sino que además ¡amaestraré a uno para ti!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nJaula de Telabrasada"}
MultiLanguageQuestData['mx'][4865] = {title = "Venganza", objective = "Cuéntale lo que has descubierto a Motega Crin de Fuego en el Campamento del Tramo Blanco, en Las Mil Agujas.", description = "Si no lo hubiera visto con mis propios ojos jamás habría creído que fuera cierto. ¡Venganza ha venido a Las Mil Agujas!\n\n<Hagar se seca la frente.>\n\n¡<nombre>, debes actuar con rapidez! Márchate y busca a Motega Pirocabello. Lo encontrarás en el Campamento del Tramo Blanco, al noroeste del Poblado Viento Libre. ¡Él sabrá lo que hay que hacer!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4866] = {title = "La leche de la madre", objective = "En el corazón de la Cumbre de Roca Negra encontrarás a Madre Telabrasada. Provócala para que te envenene. Lo más seguro es que tendrás que matarla también. Vuelve junto a John Andrajoso cuando estés envenenado para que pueda extraer el veneno de ti.", description = "¡Es probablemente uno de los venenos más potentes del mundo, <raza>!\n\nSorprendí a los Roca Negra hablando sobre cuán letal era en una de mis incursiones en la Cumbre. Lo llaman \"la leche de la madre\" por Madre Telabrasada, la enorme y asquerosa araña de la caverna Arácnida.\n\nBien, esto es lo que necesito de ti: una muestra viva de la leche, fluyendo por TUS venas. ¡No bastará con traerme la glándula! ¡Consigue que te envenene y vuelve aquí!\n\nEntonces... ¡te ordeño!\n\n<Se frota las manos anticipando el éxito.>Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCopa interminable de John Andrajoso"}
MultiLanguageQuestData['mx'][4867] = {title = "Urok Aullasino", objective = "Lee el pergamino de Warosh. Llévale el mojo de Warosh a Warosh.", description = "¡Argh! ¡Cuesta tanto hablar!\n\n¡Toma esta nota! ¡Consigue mi mojo!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nTalismán prismático"}
MultiLanguageQuestData['mx'][4881] = {title = "Complot de asesinato", objective = "Avisa a Kanati Nube Gris, en el Campamento del Tramo Blanco, acerca de la conspiración para acabar con su vida.", description = "El tauren Kanati Nube Gris ha tenido la osadía de establecer un campamento de caza en Las Mil Agujas. Debemos darle muerte a él y a los que lo apoyan, y acabar así con el campamento de caza. Nos reuniremos en el pequeño campamento situado al suroeste de El Gran Elevador.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4882] = {title = "Guardar un secreto", objective = "Lleva el Collar de plumas azules a Trull Fallarruina en el Puesto del Veneno.", description = "No estás <seguro/segura> de la importancia que pueda tener el collar que se desprendió del cuello del lechúcico salvaje recién asesinado. Brilla intensamente, desvaneciéndose y ganando brillo lentamente.\n\nTal vez Trull Fallarruina pueda decirte algo más, su saber sobre los lechúcicos parece enorme. Deberías ir a preguntarle.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4903] = {title = "La orden del Señor de la Guerra", objective = "Mata al alto señor Omokk, al maestro de guerra Voone y al señor supremo Vermiothalak. Recupera importantes documentos Roca Negra. Vuelve junto al señor de la guerra Dientegore en Kargath cuando hayas cumplido la misión.", description = "Por orden del señor de la guerra Dientegore, los siguientes habitantes de la Cumbre de Roca Negra deben ser destruidos:\n\nEl rotundo y amenazante alto señor Omokk.\n\nEl cruel y malvado trol, maestro de guerra Voone.\n\nY el señor supremo Vermiothalak, maestro de tareas de la ciudad inferior.\n\nSe requerirá asimismo la devolución de cualquier documento importante que se encuentre.\n\nConsíguelo y tuyos serán los honores.\n\nFracasa y caerás en el olvido.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Grilletes VermiothalakLimitador de circunferencia de OmokkBozal de HalyconCeñidor de Vosh'gajinMandiletes de maña de VooneRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4904] = {title = "Al fin libre", objective = "Saca a Lakota Son del Viento de Cumbre de la Nube Negra y después habla con Thalia Ocultaámbar, que está en el Poblado Viento Libre.", description = "Arnak cree que me casaré con él... pero después de rechazar su proposición, él volvió aquella noche y me raptó. Mi hermano intentó impedírselo pero Arnak era demasiado fuerte. Él... asesinó a mi hermano y después me trajo hasta aquí. Mi pobre hermano...\n\n<nombre>, ¿podrías sacarme de Cumbre de la Nube Negra? Por favor... ¡Necesito ver a Thalia! Debe de estar muy preocupada por mí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Mantón Son del VientoCincho Son del VientoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4921] = {title = "Perdida en la batalla", objective = "Encuentra a la esposa de Mankrik y llévala a El Cruce.", description = "Luchábamos juntos en un pequeño campamento tauren cuando nos separaron, ella solita le estaba plantando cara a tres Erizapúas. Pero la diferencia de efectivos empezó a desbordarnos. Estaba alejando a unos cuantos cuando la vi superada por los refuerzos. Ciego de ira, volví para enfrentarme a mis enemigos pero no tardaron en dominarme fácilmente con sus ingentes efectivos.\n\nCuando me desperté, un druida tauren estaba curando mis heridas, se había topado conmigo en el Camino del Oro donde caí.\n\nTe lo ruego, <clase>, encuentra alguna pista sobre mi esposa.", progress = nil, completion = "Lo entiendo. Gracias, &lt;clase&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4941] = {title = "La sabiduría de Eitrigg", objective = "Habla con Eitrigg en Orgrimmar. Cuando hayas tratado unos asuntos con Eitrigg, busca el consejo de Thrall.\n\nRecuerdas haber visto a Eitrigg en la Cámara de Thrall.", description = "¿Rend vive?\n\n¡Imposible!\n\nSe pensaba que Rend había sido ejecutado hace décadas.\n\nVe en busca de la sabiduría de Eitrigg, <nombre>. Nadie conoce a los Roca Negra mejor que él y si hay algo de verdad en este escrito, debemos informar a Eitrigg. A nadie se le debería negar el derecho a vengarse.\n\nLo encontrarás en Orgrimmar.\n\nCuando hayas hablado con Eitrigg, consulta con el Jefe de Guerra para ver qué desea hacer para resolver este problema.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4962] = {title = "Fragmento de can manáfago", objective = "Lleva el rubí de Felhas y úsalo en uno de los canes manáfagos de Desolace. Cuando lo consigas, llévale el rubí de Felhas y el espíritu del can manáfago encarcelado a Menara Nadiz en Los Baldíos.", description = "Así que has decidido capturar el alma de un can manáfago, bien.\n\nToma este rubí, con él podrás capturar el alma de la criatura. Funciona de forma muy parecida a los hechizos que ya conoces: Cuando la criatura está agonizando, usa la gema y esta hará el resto del trabajo por ti.\n\nTe recomiendo que vayas a Desolace y pruebes suerte con alguno de los canes manáfagos que por allí andan. Deberían servir.\n\nCuando lo consigas, llévale el espíritu capturado y tu rubí a Menara.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4963] = {title = "Fragmento de infernal", objective = "Lleva la esmeralda de Infus y úsala en uno de los infernales de Desolace. Cuando lo consigas, llévale la esmeralda de Infus y el espíritu del infernal encarcelado a Menara Nadiz en Los Baldíos.", description = "Así que has decidido capturar el alma de un infernal, bien.\n\nToma esta esmeralda, con ella podrás capturar el alma de la criatura. Funciona de forma muy parecida a los hechizos que ya conoces: Cuando la criatura está agonizando, usa la gema y esta hará el resto del trabajo por ti.\n\nTe recomiendo que vayas a Desolace y pruebes suerte con alguno de los infernales que por allí andan. Deberían servir.\n\nCuando lo consigas, llévale el espíritu capturado y tu esmeralda a Menara.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4965] = {title = "El conocimiento del orbe de Orahil", objective = "Habla con Menara Nadiz en Los Baldíos.", description = "Vaya, vaya, vaya... cómo me alegra ver que tienes cada vez más poder, <nombre>. Apostaría a que estás a punto para hablar con Menara Nadiz en Los Baldíos. Si nunca la has tratado, te diré que no creo haber conocido nunca a ningún experto en la creación de objetos <sobre todo los orbes> que pueda atrapar a un demonio para que nos sirva con tanta facilidad.\n\nSi te interesa, se encuentra en la torre de Strahad que domina Trinquete en Los Baldíos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4966] = {title = "Defensa de Kanati Nube Gris", objective = "Defiende a Kanati Nube Gris contra el ataque de los centauros.", description = "Creo que los centauros son más numerosos de lo que yo pensaba. Te pido que luches conmigo contra estos viles asesinos, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Botas con tacón ligeroBrazales de margaGuantes de zancudo pálidoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4967] = {title = "El conocimiento del orbe de Orahil", objective = "Habla con Menara Nadiz en Los Baldíos.", description = "Sigues siendo <un necio/una necia> aún persigues los símbolos de los mortales. Así es, te hablo con arrogancia. Te veo ante mí y me río. ¡Eres patético!\n\nAunque lo que piense es lo de menos. ¡Solo importa lo que piensan quienes desean tratar contigo! Y en este caso, contra mi juicio más cualificado, los que deciden consideran que necesitas más.\n\nSi esto es algo por lo que luchas, entonces deberías hablar con Menara Nadiz en la torre que domina Trinquete. Creo que la conociste hace ya algún tiempo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4968] = {title = "El conocimiento del orbe de Orahil", objective = "Habla con Menara Nadiz en Los Baldíos.", description = "Ajá, has llegado así de lejos... verdaderamente sorprendente. Creía que la corrupción de la canalización de la magia arcana te habría calado hasta el alma y te habría hecho perder el juicio a estas alturas. ¿Qué tal si te ponemos algo más al límite?\n\nSi deseas probar tu habilidad, ve en busca de Menara Nadiz en la torre de Strahad que domina Trinquete. Ella te guiará.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4969] = {title = "El conocimiento del orbe de Orahil", objective = "Habla con Menara Nadiz en Los Baldíos.", description = "¡Ea! No lo estás haciendo nada mal, joven <clase>.\n\n¡Con un poco de tiempo, las criaturas del infierno y los señores del terror se inclinarán ante ti!\n\nPero hasta que llegue esa hora, aún debes contar con las armas forjadas por manos de razas mortales.\n\nPareces estar <preparado/preparada> para otra de estas creaciones y, si lo deseas, ¡Menara Nadiz hablará contigo! Está cerca de la torre de Strahad que domina la ciudad portuaria de Trinquete. Ve cuando estés <listo/lista>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4970] = {title = "Provisiones de sable de hielo", objective = "Recoge 5 carnes de Dentoesquirla y 5 carnes de Orvallo para Rivern Ventogélido de Cuna del Invierno.", description = "Si quieres probar tu valía puedes comenzar con una tarea muy sencilla, pero de vital importancia.\n\nRecoge carne de quimera y de los osos Dentoesquirla de la arena. Tráemela para que dé de comer a los Sables de Hielo que estoy entrenando.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][4971] = {title = "Una cuestión de tiempo", objective = "Utiliza el desplazador temporal junto a uno de los silos de Andorhal y saca a la luz los parásitos temporales.\n\nMata a 10 parásitos temporales y devuélvele el desplazador temporal a Cromi en la posada de Andorhal, en las Tierras de la Peste del Oeste.", description = "¡Andorhal ha sufrido una alteración de la línea de tiempo a manos de una fuerza siniestra, seguramente la Plaga! Puedo intentar mantener el paso del tiempo inalterado aquí y reparar lo que ha sido dañado, pero necesitaré tu ayuda para hacerlo sin interrupciones.\n\nLos silos de Andorhal están infestados de parásitos temporales, carroñeros que se alimentan del flujo alterado del devenir del tiempo. Su única marca visual es un pulso azul de distorsión. Ralentizan mis augurios. Por favor, <nombre>, ayúdame: utiliza este desplazador temporal para erradicar a esos parásitos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Amito orquídeaCinturón de oroRecibirás:\n\n"}
MultiLanguageQuestData['mx'][4973] = {title = "Contar el tiempo", objective = "Localiza 5 relojes de Andorhal entre las ruinas de la ciudad y llévaselos a Cromi, en la posada de Andorhal, en las Tierras de la Peste del Oeste.", description = "Si quieres ayudarme una vez más, me serás muy útil. Estaría encantada de tener todos los relojes que puedas descubrir en las ruinas de Andorhal. Me ayudan a mantener el equilibrio contra la fuerza maligna que está alterando nuestra línea del tiempo.\n\nA cambio de esos relojes te daré un objeto que sospecho encontrarás bastante útil en el futuro.", progress = "Los relojes de Andorhal, como el gran reloj de las ruinas del ayuntamiento, están parados a las tres en punto. En esa hora los efectos de la peste comenzaron a propagarse por la ciudad, aniquilando toda forma de vida.\n\nTodo el dolor por lo que sucedió ese día ha modelado el flujo del tiempo tal y como ustedes, mortales, lo perciben. ¡El Vuelo Bronce debe seguir protegiendo la línea de tiempo!", completion = "Te agradezco de nuevo tu ayuda. Por favor, acepta este regalo. Aunque tal vez no sepas cómo ni cuándo utilizar este objeto, puede que en el futuro la senda del tiempo te revele sus verdaderos propósitos. Podría decirse que he visto que va a ser así, &lt;nombre&gt;.", rewards = "Recibirás:\n\nAtenuador armonizado"}
MultiLanguageQuestData['mx'][4974] = {title = "¡Por la Horda!", objective = "Ve a Cumbre de Roca Negra para matar al Jefe de Guerra Rend Puño Negro. Lleva su cabeza a Orgrimmar.", description = "Rend osa actuar así porque cuenta con la protección de Vuelo Negro.\n\nHas de encontrar el modo de cruzar las Salas de la Ascensión, <nombre>. Debes localizar a Rend Puño Negro y acabar con él, ¡por la Horda!\n\n<Thrall da un puñetazo en el trono.>\n\nLa próxima vez que vengas, llevarás su cabeza en la mano. Después irás a enseñársela a tu Jefe de Guerra. La Horda te honrará como te mereces.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nMarca de TiraníaOjo de la bestiaAmplitud de Puño Negro\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][4976] = {title = "Devolver el orbe purificado", objective = "Llévale el orbe infernal limpio a Menara Nadiz en Los Baldíos.", description = "Llévale el orbe limpio a Menara en Trinquete, <nombre>. Salúdala de mi parte y que viajes sin percances. Espero de veras que puedas resistir la tentación y la corrupción que sin duda te asaltarán mientras sigues tu camino.\n\nSuerte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4981] = {title = "La espía Bijou", objective = "Viaja hasta la Cumbre de Roca Negra y averigua qué le ha ocurrido a Bijou.", description = "Nunca te fíes de un goblin. De eso se trata, <nombre>.\n\nSe llama Bijou, una de nuestras agentes más escurridizas. Averigüé que estaba trabajando para algún sospechoso vendedor de mascotas exóticas de Las Estepas Ardientes llamado Kibler, en esencia, dos compitiendo con nosotros. Y lo que es peor, estaba usando fondos de la Horda para financiar sus operaciones.\n\nLa quiero de vuelta aquí viva.\n\nLa vieron por última vez entrando en la Cumbre de Roca Negra. Encuéntrala y tráela.\n\nY, <nombre>, que no te engatuse con sus zalamerías.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4982] = {title = "Las pertenencias de Bijou", objective = "Encuentra las pertenencias de Bijou y devuélveselas. Recuerdas que ella mencionó haberlas ocultado en la planta baja de la ciudad.|n", description = "De noche la vigilancia de este lugar no es muy fuerte, merodeo por la ciudad anotando todo lo que veo y que pueda tener algún valor estratégico para la F.E.K.\n\nSin embargo, anoche todo salió fatal. Tropecé con un cable trampa y se disparó una alarma. ¡Oculté mi equipo de reconocimiento y salí corriendo! Por desgracia, no puedo volver donde dejé el equipo. ¡Han doblado y hasta triplicado las patrullas! Toda esa información se ha perdido.\n\nRecupera mis pertenencias y volveré tranquilamente a la F.E.K.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4984] = {title = "La naturaleza también sufre", objective = "Destruye 8 lobos malsanos y regresa con Mulgris Río Hondo en El Tormento, en las Tierras de la Peste del Oeste.|n|n", description = "Aunque podía hacer muy poco para combatir a la Plaga, vine a estas tierras para intentar reparar el daño hecho a la naturaleza. La Peste que sigue azotando estas tierras hace sufrir a los animales, incapaces de encontrar paz ni clemencia. Te pido continuar con lo que no pude terminar.\n\nNo hay ninguna salvación para los animales ni para su sufrimiento, tan solo una liberación dulce y piadosa. Busca lobos malsanos y termina con ellos. Por favor, <nombre>, pon fin a su desgracia... si lo haces también aliviarás la mía.", progress = nil, completion = "Si... siento que las almas de los lobos que mataste han encontrado por fin su descanso. Ellos, y yo, te agradecemos tu piadosa liberación. \n\nLos lobos no son los únicos que sufren en este detestable lugar, &lt;nombre&gt;. Por favor, te necesito una vez más.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][4987] = {title = "Rama de roble con inscripciones", objective = "Según la magia con la que está encantada de La rama de roble con inscripciones, el siguiente paso del druida tauren debía ser su entrega al Círculo Cenarion de Cima del Trueno. Pide ayuda a uno de los druidas que encontrarás allí.", description = "La mano inerte del druida tauren aferra una rama de roble que parece lleno de vida. Cuando examinas la rama descubres unos glifos de naturaleza druídica tallados en la corteza.\n\nAgarras la rama y observas que es cálida al tacto, más de lo que debería ser. A tu mente llega la imagen de Cima del Trueno en Mulgore (del Alto de los Ancestros, concretamente) y tienes las palabras \"Círculo Cenarion\" en la punta de la lengua. Es como si la sugestión del lugar al que llevar la rama estuviera grabada en su interior.", progress = "En nombre del Círculo Cenarion te doy la bienvenida a este enclave, <clase>. ¿Qué te trae a nosotros?", completion = "¿Dices que esto es para Mulgris? Oímos que intentaba ayudar a las criaturas sufrientes de las Tierras de la Peste, pero no esperábamos esto... qué tragedia. Mulgris es... era un buen amigo. Lloraré su partida amargamente. \n\nPero sus esfuerzos no han sido en vano, gracias a tu diligencia. En esta rama hay mucha información sobre la peste que propaga la Plaga por el país. La estudiaremos con detalle. En cuanto a ti, por favor, acepta esto. Es lo menos que puedo hacer por tus nobles esfuerzos.", rewards = "Recibirás:\n\nMantón color guinda"}
MultiLanguageQuestData['mx'][5001] = {title = "Las pertenencias de Bijou", objective = "Encuentra las pertenencias de Bijou y devuélveselas. ¡Suerte!|n", description = "No suelo tratar con <ningún/ninguna> <raza>, pero parece que estoy atrapado entre un trol y un lugar hostil. Verás, mi misión aquí es de la más alta importancia para la Horda. La información que he descubierto, sin embargo, también se aplica al bienestar de la Alianza. Créeme, no simpatizo en absoluto con la Alianza, pero la amenaza de los Roca Negra es mucho mayor que la de un puñado de orcos.\n\nTú me ayudas a recuperar mis pertenencias y yo te facilitaré información que será útil para los de tu especie.\n\n¿Hay trato?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5021] = {title = "Más vale tarde que nunca", objective = "Entre lamentos, la mujer fantasmal recordaba tener que entregar un paquete. Según ella estaba junto a su caballo. No puedes entender dónde está el caballo o dónde había que entregar el paquete.", description = "Hay que entregar el paquete... ¡entregarlo antes de quedar aquí atrapada!\"\n\nLos gritos de pánico de una mujer se sienten casi como un susurro a través de toda la casa. Escaleras arriba, acurrucada en la esquina, ves la aparición de una mujer. No parece ser plenamente consciente de lo que la rodea, y solo parece advertirte vagamente.\n\n\"¿Has venido a entregar mi paquete? Por favor, ¡antes de que sea mucho peor! Estaba a punto de salir de aquí. Todavía estará con mi caballo... ¿o ya es demasiado tarde?", progress = nil, completion = "En el establo adviertes un paquete que de otra forma hubieras pasado por alto, pero que ahora destaca entre las ruinas y los escombros. Quizás es el paquete que pedía a gritos el fantasma de Janice Piedra Mácula...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5023] = {title = "Más vale tarde que nunca", objective = "Consulta con los supervisores reales de Entrañas para averiguar el paradero de Jeremiah Piedra Mácula. Suele haber un oficial del censo junto a la oficina de registro de hermandades y tabardos.", description = "Coges el paquete y limpias la delgada capa de polvo y mugre que lo cubría. Está dirigido a un tal Jeremiah Piedra Mácula de Lordaeron y parece que fue escrito apresuradamente. El envío está datado hace más de cuatro años.\n\nAunque no está claro si Jeremiah Piedra Mácula sigue siquiera con vida, todo el mundo sabe que Entrañas, antes conocido como Lordaeron, guarda un registro de la población de la ciudad. Se encargan de él los supervisores reales del Censo de Entrañas.", progress = "¿Has venido buscando la ayuda del Censo de Entrañas o solo para preguntarme si ha muerto alguien que conocías? Me hacen esta pregunta muchas veces.", completion = "Un paquete para un tal Jeremiah Piedra Mácula cuya última dirección conocida es Lordaeron... debería poder ayudarte. \n\nJeremiah Piedra Mácula estaba en la ciudad antes de la peste. Bueno, más bien debería decir el antiguo Jeremiah Piedra Mácula. Algunos de los Renegados han cambiados sus apellidos para librarse de su antiguo rostro. Este caso no es ninguna excepción, el antiguo Jeremiah Piedra Mácula es ahora conocido como Jeremiah Payson. \n\nEspera un momento... ¿no es el vendedor de cucarachas?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5041] = {title = "Suministros para El Cruce", objective = "Reúne 5 cajones de suministros de El Cruce en el interior de la cueva de los Crines de Acero.", description = "Sea lo que sea que haya ocurrido en Los Baldíos del Sur está provocando que algunas de las tribus de jabaespines huyan en nuestra dirección. En concreto, los Crines de Acero desplazados empiezan a desesperarse, y sus ataques se envalentonan cada vez más. ¡Solo esta semana he perdido ya dos caravanas!\n\nNuestros guerreros de El Cruce necesitan esos suministros desesperadamente, y no pienso permitir que los jabaespines se ceben en sus fechorías. Encuentra los cajones de suministros perdidos y tráemelos. Yo buscaría en la casucha de los jabaespines al sur de aquí, siguiendo el río.", progress = "¿Cómo va tu búsqueda de los suministros, <nombre>? Confío que en que los jabaespines caerán fácilmente bajo tu fuerza.", completion = "¡Ea! ¡Gracias, &lt;nombre&gt;! Esto será de gran ayuda. Empaquetaré estos suministros y los enviaré a El Cruce inmediatamente.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5047] = {title = "¡Pip Perspicaz, a tu servicio!", objective = "Habla con Malyfous Martilloscuro en Vista Eterna.", description = "Encontrarás a Malyfous Martilloscuro en Vista Eterna, <clase>. Dile que \"Pip está muy contento\" y que el traje funciona de perlas.\n\nEntonces entrégale esto:\n\n<Pip te tiende un trozo de carne resplandeciente.>\n\nEs un pedazo de las entrañas de la bestia en la que pasé mis \"vacaciones\".\n\n¡Apuesto a que Malyfous te dará una idea bastante precisa de lo que puede hacer con una parte de un monstruo como este!\n\nAh, supongo que no sabes dónde está Vista Eterna, ¿verdad? ¡Pon rumbo a la Cuna del Invierno, <amigo/amiga>!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5050] = {title = "Talismán de buena suerte", objective = "Devuelve a Janice Piedra Mácula en las Tierras de la Peste del Oeste su Medio talismán de buena suerte.", description = "Parece que me equivoqué contigo, <nombre>, y te debo mis disculpas. Mi hermana me envió algunos efectos personales, entre ellos, tiene gracia, las escrituras del Campo de Piedramácula. Creo que por ahora no voy a reclamarla.\n\nSi el espíritu de mi hermana sigue atado a la granja y no encuentra descanso, por favor... ¿puedes devolverle esto? Es la mitad de un talismán que ella tenía, su marido tenía la otra mitad.\n\nQuizás si sabe que tengo estas cosas dejará que su alma descanse.", progress = "John, querido... ¿eres tú? Tengo mucho frío...", completion = "Devuelves la mitad del talismán a la aparecida. Lo mira y luego te mira a ti con expectación.\n\n\"Cariño, ¿dónde dejaste la otra mitad? No podemos estar juntos si no tenemos las dos mitades. Cariño... ¿puedes verme?\"", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5052] = {title = "Esquirlas de sangre de Agamaggan", objective = "Llévale una esquirla de sangre a Quebrantadientes en el Campamento Taurajo en Los Baldíos.\n\nReúne más esquirlas de sangre si quieres que te bendiga con el poder de Agamaggan.", description = "Además de las espinas, la sangre afectó a <gruñe> otros aspectos de la tierra: piedras teñidas de rojo sangre mezcladas con otros minerales. Los Erizapúas excavan en busca de estas esquirlas y las llevan como tótems <gruñe> para que les den fuerza en la batalla y para su magia <gruñe.>\n\nConozco los secretos de esa magia.\n\nLlévale a Quebrantadientes una de estas esquirlas de sangre para demostrarle que entiendes de qué va el asunto. Llévale a Quebrantadientes muchas esquirlas y te bendecirá con la magia de los jabaespines, es decir, ¡la magia de Agamaggan! <gruñe.>", progress = "Nuestras tribus se reúnen a las espinosas regiones de Los Baldíos <gruñe> porque hay lugares sagrados, aunque ninguno tan sagrado como Rajacieno. El cuerpo de Agamaggan compensa por todo Rajacieno, <gruñe> pero la Zahúrda está especialmente protegida ¡porque la entrada está hecha con sus enormes fauces! <Gruñe> ¡Se tragará enterito a todo aquel que no le sea leal y escupirá su cuerpo después de masticarlo! <Gruñe>\n\nAgamaggan nos dejó su cuerpo para protegernos y entrega su espíritu para que podamos protegerlo a él. <Gruñe>", completion = "Ah, entiendes. &lt;Gruñe&gt; Mis palabras no cayeron en oído sordo, &lt;raza&gt;. Puede que Quebrantadientes esté enjaulado ¡pero no hay jaula que detenga el poder de Agamaggan!  \n\nEl contacto con el fragmento, solo tocarlo... ha pasado tanto tiempo, &lt;raza&gt;. \n\n¿Tienes idea de lo que se siente? ¿Que te aparten de tu poder? \n\nPero ya contaremos esa historia en otra ocasión. Te prometí información. Te prometí el poder de Agamaggan. Mi propio pueblo me dio la espalda, a mí, a Quebrantadientes. Ahora, te envío para que mi furia caiga sobre ellos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5054] = {title = "Ursius de los Dentoesquirla", objective = "Ventisca Pezuña Umbría de Vista Eterna, en Cuna del Invierno, quiere que mates a Ursius.", description = "En las nevadas montañas de Cuna del Invierno, al Noroeste, un diestro cazador acecha a su presa... me refiero a Ursius de los osos Dentoesquirla, una bestia ágil e inteligente.\n\nTe envío a enfrentarte con él. Vaga por las escarpadas colinas al noroeste de Vista Eterna. Da con él y cázalo antes de que advierta tus intenciones.\n\nTodo el que ha tenido un encuentro con Ursius se ha visto convertido en presa y a él en cazador. Mantente en guardia.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5056] = {title = "Shi-Rotam", objective = "Ventisca Pezuña Umbría de Vista Eterna, en Cuna del Invierno, quiere que acabes con Shi-Rotam.", description = "En la parte norte de Cuna del Invierno, los grandes felinos se reúnen en torno a un lugar conocido como Roca Sable de Hielo. La líder de los felinos responde al nombre de Shi-Rotam. Si derrotaras a la matriarca de los sables de hielo ganarías mucho respeto a ojos de cualquier <raza>.\n\nVuelve a esas inhóspitas tierras y, cuando estés allí, recoge carne de sable de hielo sacra. Encuentra la Piedra de Shi-Rotam y colócala allí. Cuando pongas la carne de sus prójimos en la piedra, invocarás a Shi-Rotam, estará furiosa.\n\nDebes estar <preparado/preparada> para su ira y derrotarla.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Hoja de acechabestiasDaga cazabestiasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][5058] = {title = "El diario de la señorita Dalson", objective = "Un diario con páginas que comienzan a amarillear descansa abierto por la última entrada:\n\n\"No sé lo que va a ocurrir ahora que Harold se ha transformado. Gasté todas mis fuerzas en arrastrarlo hasta el único lugar que pude encontrar y en el que pudiera quedar encerrado. Escondí en mí la llave y ruego porque funcione...\n\nEspero poder salir de aquí, pero necesito dinero para hacerlo. Creo que todas nuestras cosas están en el armario... y ahora que lo pienso, ¿no tiene Harold la llave con él?\n\nDescansaré, estoy terriblemente cansada.\"", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][5059] = {title = "Encierro", objective = "La puerta de la letrina ha comenzado a astillarse en los bordes del marco, como si hubieran intentado forzarla varias veces y con insistencia. En este momento está cerrada desde fuera.\n\n¡Cuando mueves la puerta oyes un gemido gutural en el interior! Sea lo que sea, no parece muy amistoso.", description = nil, progress = "La puerta de la letrina ha comenzado a astillarse en los bordes del marco, como si hubieran intentado forzarla varias veces y con insistencia. En este momento está cerrada desde fuera.\n\n¡Cuando mueves la puerta oyes un gemido gutural en el interior! Sea lo que sea, no parece muy amistoso.", completion = "Con la llave que encontraste en el esqueleto de la que fue la señora Dalson abres la puerta de la letrina. Un necrófago sanguinario salta fuera de la letrina, debe de haber estado ahí atrapado desde hace mucho tiempo.\n\nEl desgarrador grito del necrófago al advertir tu presencia deja claro que el antiguo granjero Dalson ya no puede ser salvado.", rewards = nil}
MultiLanguageQuestData['mx'][5062] = {title = "El fuego Sagrado", objective = "Recoge 10 pitas incendiarias y después pide consejo a Magatha Tótem Siniestro en el Alto de los Ancestros de Cima del Trueno.", description = "Arikara es una criatura mortífera contra la que hay que actuar con rapidez. Para poder atraparla tendrás que encender el fuego sagrado de la vida, que hará que Arikara aparezca.\n\nVe y recoge pitas incendiarias, una planta poco común. Cuando tengas suficientes pitas, pide consejo a Magatha Tótem Siniestro en el Alto de los Ancestros de Cima del Trueno. Ella es una poderosa chamán que puede encantar la planta y obtener así unos polvos con los que encender el fuego.\n\nViaja en dirección noreste hasta Poza Hirviendo y recoge pitas incendiarias.", progress = "Así que Motega Pirocabello envía noticias de Arikara... eso es mala señal.\n\n<Magatha mira a su alrededor.>\n\nArikara es una criatura muy peligrosa cuyo único propósito es castigar a todo aquel que haya cometido actos abyectos.\n\n<Magatha sonríe.>", completion = "Bien, has recogido la cantidad necesaria de pitas incendiarias. Esta rara hierba que solo se encuentra en Las Mil Agujas servirá para encender el fuego sagrado de la vida. \n\n&lt;Magatha comienza a encantar las pitas incendiarias.&gt;", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5064] = {title = "Espiando a los Tótem Siniestro", objective = "Localiza y reúne las 3 notas secretas que hay en Cumbre de la Nube Negra.", description = "<nombre>, nos has servido con diligencia en el pasado por lo que ahora te confío una importante misión. El clan Tótem Siniestro está tramando algo. Sabemos que tres agentes de origen desconocido se han estado reuniendo con los Tótem Siniestro durante las últimas semanas. Descubrimos que hay varios cofres en Cumbre de la Nube Negra que contienen mensajes reveladores.\n\n<nombre>, si tienes éxito en esta peligrosa misión, te recompensaré debidamente.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Sobrehombros del desiertoBotas tundraGuardamuñecas tañidos rictusRecibirás:\n\n"}
MultiLanguageQuestData['mx'][5065] = {title = "Las tablillas perdidas Mosh'aru", objective = "Llévale la tercera y cuarta tablillas Mosh'aru al prospector Ferrobota, que está en Tanaris.", description = "El trol con el que has hablado no te ha dicho la verdad. Es cierto que las dos tablillas que conseguiste para él explican el modo de retener la esencia de Hakkar, pero la leyenda no acaba ahí. Llevo mucho tiempo investigando y he descubierto que existen seis tablillas Mosh'aru y no dos. ¡Seis!\n\nY mucho me temo que los secretos que albergan no serán de nuestro agrado...\n\nLocaliza la tercera y cuarta tablillas Mosh'aru. Se encuentran en las Tierras de la Peste del Este en posesión de los trols Fustamusgo. Encuéntralas y tráemelas aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5066] = {title = "Un llamamiento a las armas: las Tierras de la Peste", objective = "Busca al comandante Ashlam Puñovalor. Su campamento base se encuentra en Campamento del Orvallo, al norte de las Montañas de Alterac.", description = "¡Atención, atención! ¡Atención todos los héroes!\n\n¡El Reino de Ventormenta ha hecho una llamada a las armas! ¡Tomen las armas para hacer frente a la amenaza de la Plaga en las tierras al norte de los Reinos del Este! ¡Se dice que de las ruinas de las Tierras de la Peste surgen nuevas amenazas!\n\n¡Héroes del reino, preséntense ante el comandante Ashlam Puñovalor en el Campamento del Orvallo, al norte de las Montañas de Alterac!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5081] = {title = "La misión de Maxwell", objective = "Viaja a la Cumbre de Roca Negra y acaba con el maestro de guerra Voone, el alto señor Omokk y el señor supremo Vermiothalak.", description = "Esta información completa lo que se les había escapado a nuestros sin embargo siempre avezados espías de la Cumbre de Roca Negra.\n\nEl ataque ha de ser contundente, <nombre>.\n\nHay que empezar por destruir a su maestro de guerra, el trol Voone. Sin sus planes de guerra, los orcos Roca Negra se encontrarán inmersos en el caos.\n\nDespués debes liquidar al ogro alto señor Omokk. Esos ogros cobardes de los Roca Negra están indefensos sin su liderazgo.\n\nPor último, el señor supremo de la ciudadela: Vermiothalak. Una vez muerto Vermiothalak, su unidad de mando central está perdida.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Grilletes VermiothalakLimitador de circunferencia de OmokkBozal de HalyconCeñidor de Vosh'gajinMandiletes de maña de VooneRecibirás:\n\n"}
MultiLanguageQuestData['mx'][5082] = {title = "a amenaza de los Nevada", objective = "Donova Cubilnevado de Cuna del Invierno quiere que mates 8 abrecaminos Nevada, 8 vigías del cubil Nevada y 8 totémicos Nevada.", description = "Vine a Cuna del Invierno para investigar los Baños Escarchados. He observado que el agua parece tener... cualidades extrañas. Todavía no he podido descubrir la fuente y, para serte sincera, últimamente he tenido algunos problemas a causa de los fúrbolgs Nevada.\n\nParecen sentirse atraídos por las fuentes, igual que yo. Se han vuelto extremadamente protectores con el agua, no permiten que me acerque a los dos manantiales más grandes, al norte de aquí.\n\nMe gustaría seguir con mis estudios, ¿me ayudarás?", progress = nil, completion = "¡!Muchas gracias, &lt;nombre&gt;! Ya puedo seguir trabajando aquí\n\n¿Encontraste algo interesante en el campamento Nevada?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5083] = {title = "guardiente Nevada", objective = "Lleva el frasco vacío de aguardiente a Donova Cubilnevado de Cuna del Invierno.", description = "El vial que recogiste de los fúrbolgs Nevada está vacío, pero detectas unas gotas de un extraño líquido verdoso en su interior. Casi brilla.\n\n¿Puede ser importante?\n\nSeguramente Donova Cubilnevado podrá decirte algo más ya que lleva un tiempo acampada junto a las fuentes termales de Cuna del Invierno.", progress = "¿Qué has encontrado?", completion = "¿Lo obtuviste de los Nevada?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5084] = {title = "ucumbir a la corrupción", objective = "Busca una pista en el campamento fúrbolg Muertobosque en el norte de Frondavil.", description = "Este líquido verdoso... me recuerda algo al barro que vi durante mis viajes por Frondavil. He visto algunos corredores Nevada entre los Fauces de Madera... Quizás esto tenga algo que ver con la botella que has encontrado, <nombre>.\n\nHay un grupo grande de fúrbolgs nada más pasar el Bastión Fauces de Madera, en Frondavil. La energía vil ha corrompido y llevado a la locura a esa tribu, los Muertobosque. ¿Por qué no vas a echar un vistazo y a ver si puedes encontrar alguna evidencia de acuerdos entre los Nevada y los Muertobosque?", progress = nil, completion = "En la caldera burbujea una sustancia putrefacta y de olor repulsivo...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5088] = {title = "Arikara", objective = "Mata a Arikara. Llévale sus restos y el polvo de incendiaria a Motega Pirocabello al Campamento del Tramo Blanco como prueba de tus actos.", description = "Lleva este refinado y depurado polvo de incendiaria a Las Mil Agujas y échalo sobre el fuego sagrado de la vida. Está situado en Cumbre de la Nube Negra en una aguja aislada en la que entierran a sus muertos.\n\nEl encantamiento que he lanzado sobre el polvo de incendiaria atraerá a Arikara, <nombre>.\n\nTemo que esté persiguiendo a Cairne Pezuña de Sangre; han cambiado mucho las tradiciones de los tauren y eso ha enojado a Arikara. ¡Actúa con rapidez antes de que todo esté perdido, <clase>!", progress = "¿Has matado a la despiadada serpiente Arikara, <nombre>?", completion = "Esto no tiene sentido. ¿Por qué iba Arikara a andar tras Cairne Pezuña de Sangre? Magatha no puede estar equivocada, es una de nuestras chamanes más poderosas. \n\n&lt;Motega niega con la cabeza.&gt; \n\nSea como sea, tu hazaña en favor de la Horda no pasará inadvertida. Por favor, elige uno de estos como recompensa por tu ayuda.", rewards = "Martillo de toscoVarita de picaduraEscudo tintineanteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][5089] = {title = "Orden del general Drakkisath", objective = "Llévale la orden del general Drakkisath al mariscal Maxwell en Las Estepas Ardientes.", description = "En el cadáver del reptil derrotado descubres lo que parece ser una nota de cierta importancia: una carta de su superior, el general Drakkisath, sobre protocolo.\n\nTu instinto te dice que deberías llevársela al mariscal Maxwell.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5090] = {title = "Un llamamiento a las armas: las Tierras de la Peste", objective = "Busca al comandante Ashlam Puñovalor. Su campamento base se encuentra en Campamento del Orvallo, al norte de las Montañas de Alterac.", description = "¡Atención, atención! ¡Atención todos los héroes!\n\n¡El Reino de Ventormenta ha hecho una llamada a las armas! ¡Tomen las armas para hacer frente a la amenaza de la Plaga en las tierras al norte de los Reinos del Este! ¡Se dice que de las ruinas de las Tierras de la Peste surgen nuevas amenazas!\n\n¡Héroes del reino, preséntense ante el comandante Ashlam Puñovalor en el Campamento del Orvallo, al norte de las Montañas de Alterac!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5091] = {title = "Un llamamiento a las armas: las Tierras de la Peste", objective = "Busca al comandante Ashlam Puñovalor. Su campamento base se encuentra en Campamento del Orvallo, al norte de las Montañas de Alterac.", description = "¡Atención, atención! ¡Atención todos los héroes!\n\n¡El Reino de Ventormenta ha hecho una llamada a las armas! ¡Tomen las armas para hacer frente a la amenaza de la Plaga en las tierras al norte de los Reinos del Este! ¡Se dice que de las ruinas de las Tierras de la Peste surgen nuevas amenazas!\n\n¡Héroes del reino, preséntense ante el comandante Ashlam Puñovalor en el Campamento del Orvallo, al norte de las Montañas de Alterac!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5092] = {title = "Despejar el camino", objective = "Mata 10 despellejadores esqueléticos y 10 necrófagos esclavizantes en la Colina de las Penas.\n\nVuelve con el comandante Ashlam Puñovalor en el Campamento del Orvallo, en las Tierras de la Peste del Oeste.", description = "Los caminos de Andorhal que entran por el oeste y por el norte a la ciudad están bien fortificados, por eso pretendo atacar desde el camino del este, con menos defensas. La Plaga confía en la protección de los no-muertos que infestan la Colina de las Penas como su primera línea de defensa. Si vamos a avanzar sobre Andorhal tendremos que hacerlo a través de la Colina de las Penas.\n\nTu primera tarea será limpiar el camino que atraviesa la Colina de las Penas. Límpialo de los esqueletos y necrófagos que frecuentan la zona. ¡Vuelve a informarme cuando hayas terminado!", progress = nil, completion = "¡Misión cumplida, &lt;nombre&gt;! Buena jugada, buena jugada.\n\nDéjame recompensarte por tu trabajo con algunas monedas de las arcas de Ventormenta. Te recomendaría gastar el dinero en algo que te ayude en tu próxima misión... la que te llevará a las ruinas de Andorhal.\n\n¡Deberás estar preparado! ¡Mantente alerta!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5093] = {title = "Un llamamiento a las armas: las Tierras de la Peste", objective = "Busca al sumo ejecutor Derrington; su campamento base está en El Baluarte, al este de Claros de Tirisfal y Entrañas.", description = "¡Héroes del reino, la Horda los llama a la acción!\n\nSe llama a las armas a quien esté dispuesto a luchar contra la Plaga. Se dice que están surgiendo nuevas amenazas en las ruinas de los Reinos del Este. Acechan al este de Entrañas, en el territorio norteño hoy conocido como las Tierras de la Peste.\n\nLos interesados deben ponerse en contacto con el sumo ejecutor Derrington, acampado en El Baluarte, al este de Claros de Tirisfal.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5094] = {title = "Un llamamiento a las armas: las Tierras de la Peste", objective = "Busca al sumo ejecutor Derrington; su campamento base está en El Baluarte, al este de Claros de Tirisfal y Entrañas.", description = "¡Héroes del reino, la Horda los llama a la acción!\n\nSe llama a las armas a quien esté dispuesto a luchar contra la Plaga. Se dice que están surgiendo nuevas amenazas en las ruinas de los Reinos del Este. Acechan al este de Entrañas, en el territorio norteño hoy conocido como las Tierras de la Peste.\n\nLos interesados deben ponerse en contacto con el sumo ejecutor Derrington, acampado en El Baluarte, al este de Claros de Tirisfal.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5095] = {title = "Un llamamiento a las armas: las Tierras de la Peste", objective = "Busca al sumo ejecutor Derrington; su campamento base está en El Baluarte, al este de Claros de Tirisfal y Entrañas.", description = "¡Héroes del reino, la Horda los llama a la acción!\n\nSe llama a las armas a quien esté dispuesto a luchar contra la Plaga. Se dice que están surgiendo nuevas amenazas en las ruinas de los Reinos del Este. Acechan al este de Entrañas, en el territorio norteño hoy conocido como las Tierras de la Peste.\n\nLos interesados deben ponerse en contacto con el sumo ejecutor Derrington, acampado en El Baluarte, al este de Claros de Tirisfal.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5096] = {title = "Distracción Escarlata", objective = "Adéntrate en el campamento base de la Cruzada Escarlata entre el Campo de Piedramácula y el Llanto de Dalson y destruye su tienda de mando.\n\nColoca el estandarte de la Plaga en el campamento y vuelve con el sumo ejecutor Derrington en El Baluarte en las Tierras de la Peste del Oeste.", description = "Antes de ocuparnos de Andorhal, debemos afrontar el avance de la amenaza de la Cruzada Escarlata desde la Vega del Amparo. Han acampado entre el Campo de Piedramácula y el Llanto de Dalson, haciendo que corramos el riesgo de enfrentarnos a la Plaga y a la Cruzada al mismo tiempo.\n\nMi plan consiste en hacer que ambos se enfrenten, enviándote a destruir su tienda de mando. Utiliza algo de fuego en botella que encontrarás en esta caja de explosivos. Cuando esté arrasada, coloca este estandarte de la Plaga junto a la tienda. Con algo de suerte nos ignorarán y se centrarán en la Plaga en busca de venganza.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5098] = {title = "Todas las atalayas", objective = "Con la antorcha de aviso, marca las atalayas de Andorhal. Tendrás que estar en la entrada de la atalaya para poder marcarla.\n\nCuando estén marcadas las cuatro atalayas, devuelve la antorcha de aviso al sumo ejecutor Derrington en El Baluarte, en las Tierras de la Peste del Oeste.", description = "Utilizando un instrumento mágico conocido como antorcha de aviso, puedo marcar objetivos a nuestra elección para futuras acciones de nuestras tropas. Para ese fin, pensamos que la Plaga está sirviéndose de las atalayas de Andorhal para controlar sus movimientos de tropas.\n\nTu misión: rompe las defensas de Andorhal y coloca antorchas en sus cuatro atalayas. Tendrás que estar en la entrada de las atalayas para colocar la antorcha, solo entonces quedarán marcadas. La antorcha de aviso solo tiene cinco cargas, así que úsalas con prudencia.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5101] = {title = "Misión de prueba suprema de Lee... ¡apocalíptica!", objective = "Mata 6 ovejas para Benny ¡y corre como el demonio!\n\n\n\n\nEs una broma... lo de correr como un demonio.", description = "¡Bah! ¿Qué crees que esto, una especie de búsqueda de prueba? ¡Estaré allí aunque haya erratas!\n\nSi te parece que mi búsqueda va a estar tirada, ¡prepárate!\n\nMata a diez ovejas (1933) ¡y no vuelvas hasta que hayas terminado!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5102] = {title = "Muerte al general Drakkisath", objective = "Viaja hasta la Cumbre de Roca Negra y mata al general Drakkisath.", description = "Luchamos contra estos animales en dos frentes: Desde nuestra capital de Ventormenta luchamos desde el interior y aquí, en Las Estepas Ardientes, libramos la batalla en su puerta. Debemos estar atentos, <nombre>. Nadie debe librarse de nuestra ira, como ellos tampoco perdonaron nada en su asalto a nuestros hogares y familias.\n\nEncuentra al general Drakkisath ¡y destrúyelo!\n\nCiertamente la tarea no será sencilla pero la recompensa será extraordinaria.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nMarca de TiraníaOjo de la bestiaAmplitud de Puño Negro\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][5122] = {title = "El medallón de Fe", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][5123] = {title = "a pieza final", objective = "Lleva el diario mal escrito a Donova Cubilnevado de Cuna del Invierno.", description = "El diario que llevaba consigo el gran jefe parece muy extenso, pero echas un vistazo a un par de páginas y descubres que no puedes leer el texto. Los signos son tan toscos y están tan mal escritos que no estás <seguro/segura> de que nadie pueda leerlo.\n\nPero quizás Donova pueda decirte lo que dice...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5141] = {title = "Peletería dragontina", objective = "Consigue 2 corazas de escórpido resistentes, 2 guantes de escórpido resistentes, y 10 dragontinas desgastadas para Peter Galen, en Azshara.\n\nSi completas esta misión tendrás acceso al arte de la peletería dragontina.\n\nSi lo haces, también dejarás de tener acceso a la peletería elemental y tribal. Tienes que asegurarte de querer seguir este camino antes de completarla.", description = "La peletería dragontina no es fácil pero es muy gratificante. Te enseñaré a hacer estas magníficas mallas de armadura pero solo si aceptas ciertas condiciones.\n\nSi eliges este camino, aceptas no aprender nunca la peletería elemental ni la tribal; solo hay lugar para una de las tres en la cúspide del oficio. Es más, necesitaré muestras de tu mejor trabajo con armaduras de escórpidos. Por último, tendré que comprobar que eres capaz de adquirir la materia prima del negocio: las escamas de dragonante.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5142] = {title = "La pequeña Pamela", objective = "Encuentra a Pamela Rutagrana en Villa Darrow.", description = "¡Cuántas vidas se perdieron en la Batalla de Villa Darrow! Muchos murieron... o peor.\n\nCuando la batalla comenzó, escondí a mi sobrina Pamela... Y no sé qué fue de ella. No soy más que un espíritu errante, pero mi corazón aún ansía conocer la suerte de Pamela.\n\nPor favor, <buen/buena> <clase>, ¿podrías ir a Villa Darrow a buscarla? Está al este, más allá de Gangrena de Gahrron.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5144] = {title = "Peletería elemental", objective = "Lleva 2 corazones de fuego, 2 globos de agua, 2 núcleos de tierra y 2 alientos de viento a Sarah Peletero a La Garganta de Fuego. \n\nAl completar esta tarea aprenderás peletería elemental. \n\nSi te dedicas a este arte, no podrás aprender peletería dragontina ni peletería tribal; piénsatelo bien antes de decidirte.", description = "Mi especialidad es la peletería elemental. Si quieres abrir tu mente a los poderes mayores de la sustancia, te enseñaré todo lo que sé.\n\nDebes saber, <clase>, que si aceptas estas lecciones te comprometes a no aprender peletería tribal ni dragontina; solo puedes aprender una de las tres artes. Además, tienes que probarme que estás en armonía con los elementos naturales; tráeme esencia pura de agua, tierra, viento y fuego.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5147] = {title = "Se busca: Arnak Tótem Siniestro", objective = "Mata a Arnak Tótem Siniestro y llévale una prueba de tu hazaña al vigiarrisco Cuerno Largo, que está en el Poblado Viento Libre.", description = "Se busca: Arnak Tótem Siniestro\n\nSe busca a Arnak el Paria por los atroces crímenes de asesinato y secuestro. Quienes tengan la valentía de traer a este criminal ante la justicia recibirán una generosa recompensa.\n\nArnak fue visto por última vez en los riscos situados al lado de Cumbre de la Nube Negra. Para reclamar tu recompensa enseña una prueba de tus acciones al vigiarrisco Cuerno Largo en Poblado Viento Libre.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Leotardos de guardia de las llanurasArmadura pellejomúsculoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][5149] = {title = "La muñeca de Pamela", objective = "Encuentra la muñeca de Pamela.", description = "Mi tía Marlene me dijo que me quedara aquí en casa porque mi padre tenía que ir a luchar. ¡Mi padre es el hombre más valiente del mundo!\n\nPero llevo aquí mucho tiempo y no ha venido a buscarme. A veces viene gente mala y me susurra... y yo quiero que mi papá los eche ¡pero no está aquí!\n\nY a veces, cuando está oscuro, quiero jugar con mi muñeca, pero no puedo porque me la dejé en la aldea.\n\n¿Irás a buscar a mi muñeca?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5150] = {title = "¡Dadanga tiene hambre!", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nPaquete con envoltorio marrón pequeño"}
MultiLanguageQuestData['mx'][5151] = {title = "Hipercondensador", objective = "Acaba con la bestia y trae de regreso el hipercondensador y la llave de la jaula de pantera a Wizlo Rodabrillante.", description = "Soy el único superviviente del ataque centauro a nuestra caravana. Una extraña aunque poderosa pantera está custodiando mi mejor invención, y la tiene alrededor del cuello. ¡Ja! Hasta los centauros tiemblan al verla.\n\nAquí tienes la llave de la jaula de pantera. Ya no queda nada allí, solo la pantera. Acaba con esa bestia, tráeme el hipercondensador y te recompensaré.\n\nLos restos de la caravana están al norte de aquí.\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAnillo de la Liga de los Inventores"}
MultiLanguageQuestData['mx'][5155] = {title = "as fuerzas de Jaedenar", objective = "Entra en Jaedenar y mata a 4 canes Jaedenar, 4 guardianes Jaedenar, 6 adeptos Jaedenar y 6 cultores Jaedenar antes de volver con Greta Pezuñamusgo a Frondavil.", description = "Si he de confiar en ti para esto, primero tienes que demostrarme que mereces mi confianza.\n\nHe de saber que eres <un enemigo/una enemiga> del Consejo de la Sombra que tanta maldad ha causado aquí y al otro lado de nuestras fronteras.\n\nAdéntrate en la profundidad de Frondavil. Al oeste verás un camino que te conducirá a Jaedenar. Ahí es donde el Consejo trama sus complots con la Legión Ardiente.\n\nAdéntrate en la profundidad de uno de los Túmulos corruptos en los que viven y mata a todos. Vuelve a mí cuando hayas acabado. Entonces sabré que de verdad quieres ayudarnos.", progress = nil, completion = "¡Bien, &lt;nombre&gt;! Ahora que su número se debilita, podemos presionarles más. \n\n¿Qué tal te supo esa primera cata de su poder? ¿Son tan fuertes como pensaste que serían? ¿Más fuertes? ¿O resultaron no ser un desafío a tu altura? Eso sería fantástico. \n\nPero ya discutiremos los detalles de tus hazañas más tarde. Ahora tenemos que concentrarnos en otras cosas.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5156] = {title = "nvestigación acerca de la corrupción", objective = "Busca y destruye a 2 bestias entrópicas y 2 horrores entrópicos a la vez que exploras la Cañada Gran Cicatriz. Cuando hayas comprobado si los cráteres del lugar aún contienen agua vil corrupta, vuelve con Taronn Plumarroja a Frondavil.", description = "Al norte, al lado este del camino, en lo que se llama la Cañada Gran Cicatriz, hay una zona en la que los infernales fueron invocados durante la Gran Guerra... los cráteres aún marcan la tierra... como lo hacen los propios infernales.\n\nSiento curiosidad por dos cosas. Primera: ¿aún vagan los elementales entrópicos por esta área? Y segunda: ¿los cráteres contienen aún el agua corrupta y fétida que se acumuló allí hace años? ¿Me ayudarás a saciar mi curiosidad, <nombre>? Pero ve con cuidado, los infernales destruyen todo lo que encuentran en su camino.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5158] = {title = "uscando ayuda espiritual", objective = "Lleva el agua de la Poza de la Luna corrupta a Islen Vidente del Agua a Los Baldíos.", description = "Lleva el agua corrupta a Los Baldíos, <nombre>. Al sur de Trinquete, escondida en la costa, vive una vieja amiga mía, una chamán llamada Islen Vidente del Agua. Es poderosa y nos ayudará. Siempre ha tenido una fuerte relación con los Espíritus del Agua. La nuestra es una noble misión. Eso convencerá a Islen y a los espíritus. Nos ayudarán.\n\nLa encontrarás en un pequeño campamento en la orilla. Y, <nombre>, ignora a los piratas. Son ruidosos y molestos, pero no representan una amenaza para ti.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5159] = {title = "l agua purificada vuelve a Frondavil", objective = "Lleva el agua de la Poza de la Luna purificada a Greta Pezuñamusgo en Frondavil.", description = "Da gracias a los espíritus, <nombre>. Son ellos los que han acudido en tu ayuda, no yo.\n\nAhora te doy esta agua purificada. Saluda a Greta de mi parte y transmítele mis mejores deseos. Está enfrentándose a algo que nos supera a muchos de nosotros... Pronto se dará cuenta.\n\nEl Consejo de la Sombra no es una fuerza que pueda subestimarse, <nombre>. Recuérdalo.\n\nAhora ve. Coge el agua y vuelve con Greta.", progress = "Ah, veo que has vuelto, <nombre>. Bien. ¿Encontraste a Islen en Los Baldíos? ¿O tenemos que encontrar otra manera de lograr nuestros objetivos?", completion = "Esta agua debería ser suficiente para nuestros propósitos. \n\nMe alegra que Islen pudiera ayudarnos. Su fuerza sobre los espíritus del agua ha sido siempre considerable. Y también es sabia. Raras son las veces que los espíritus no están de acuerdo con ella. El hecho de que ambos hayan bendecido nuestra causa me da esperanza: estamos en el buen camino.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5160] = {title = "El Protectorado de la matrona", objective = "Viaja hasta la Cuna del Invierno y encuentra a Haleh. Dale la escama de Awbee.", description = "Viaja a Kalimdor, <raza>. Nuestro Vuelo encuentra su hogar en el gélido paisaje de la Cuna del Invierno. Cuando llegues a la Cuna del Invierno, encuentra las cavernas de Mazthoril.\n\nEn los helados suelos de Mazthoril encontrarás runas de cobalto. Con una de mis escamas en la mano, ponte de pie sobre una runa y te verás transportado hasta Haleh, nuestra madre protectora.\n\nDale la escama para que pueda ver lo que he visto y sentido, aquí en este condenado lugar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5163] = {title = "eti... ¿ya hemos llegado?", objective = "Coge el yeti mecánico de Umi y asusta con él a sus amigos:\n\nLegacki en Vista Eterna (Cuna del Invierno)\nRoxio en Gadgetzan (Tanaris)\nQuixxil en el Refugio de Marshal (Cráter de Un'Goro)\n\nCuando hayas terminado, devuelve el yeti mecánico a Umi.", description = "¡Ya está todo listo, <nombre>!\n\nYa he escrito a mis amigos diciéndoles que tengo una sorpresa para ellos. ¡Y aquí es donde tú entras en juego!\n\nVoy a darte mi yeti mecánico. Para sorprender a mis amigos, les harás una visita, encenderás el yeti y lo mandarás hacia ellos.\n\nCuando se lo hayas enseñado a Legacki en Vista Eterna, a Roxio en Gadgetzan y a Quixxil en el Refugio de Marshal, ¡vuelve aquí y cuéntame lo que ha pasado!\n\nPor favor, cuando vuelvas devuélveme también mi yeti.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nYeti mecánico"}
MultiLanguageQuestData['mx'][5168] = {title = "Los héroes de Villa Darrow", objective = "Lleva el Tratado de Davil y el Escudo de Rutagrana a Carlin Rutagrana.", description = "Los héroes de Villa Darrow tienen un lugar en mi corazón y el libro que me trajiste, las Crónicas de Villa Darrow, cuenta sus historias.\n\nHabla del paladín Davil Fuegoluz y de cómo la Cruzada se llevó su tratado al concejo de Vega del Amparo.\n\nTambién hay pasajes que hablan de mi hermano, el capitán Rutagrana. Después de su traición, su escudo fue quebrado y desechado y ahora yace en el más improbable de los lugares: cerca del granero de Gangrena de Gahrron.\n\nReúne esas reliquias, <nombre>. La fatalidad y la tragedia las rodea.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5181] = {title = "Los villanos de Villa Darrow", objective = "Lleva el cráneo de Horgus y la espada destrozada de Marduk a Carlin Rutagrana a la Capilla de la Esperanza de la Luz.", description = "Las Crónicas de Villa Darrow hablan de los villanos de esa batalla. Cuentan cómo el Señor de los necrófagos Horgus el Devastador fue destruido por las fuerzas de la Alianza durante la batalla. Su cuerpo fue arrojado a un lago al noroeste del Cruce de Corin y su calavera aún está allí.\n\nMarduk el Negro nunca fue derrotado, pero su mítica espada se rompió y se perdió. Yace al fondo de una garganta al oeste del Cruce de Corin.\n\nRecupera esos objetos, <nombre>. No sé por qué, pero sé que su destino está en tus manos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5202] = {title = "na extraña llave roja", objective = "Recorre Jaedenar y descubre para qué se utiliza la llave roja de sangre.", description = "La pequeña llave roja parece estar hecha con algún tipo de hueso. Pesa bastante, pero parece muy frágil. ¿Por qué tendría un miembro del Consejo de la Sombra algo así? Quizás esta llave abra algo que está en Jaedenar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5211] = {title = "Los defensores de Villa Darrow", objective = "Libera a 15 espíritus de Villa Darrow y vuelve con Carlin Rutagrana.", description = "Muchos de los defensores perecieron en la Batalla de Villa Darrow. Y muchos de ellos vagan ahora como fantasmas al servicio de la Plaga. Debes encontrar a estas pobres almas y acabar con su miseria.\n\nCaza necrófagos caníbales, necrófagos balbuceantes y despellejadores malsanos. Muchos de estos mefistos antaño eran ciudadanos de Villa Darrow. Si destruyes su forma actual, liberarás sus almas.\n\nLos puedes encontrar en el Bosque de la Peste y en el Cruce de Corin, así como en otros bastiones de la Plaga esparcidos por las Tierras de la Peste del Este.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5212] = {title = "La carne no miente", objective = "Recoge 10 muestras de carne apestada de Stratholme y vuelve con Betina Bigglezink. Sospechas que podrías obtener una muestra de cualquier criatura de Stratholme.", description = "Los boticarios Renegados no son los únicos seres de este mundo versados en las ciencias.\n\nYo he estudiado la peste de la Plaga durante años, <raza>. Pensábamos que la potencia de la plaga había mermado, pero lo que he descubierto aquí, en las Tierras de la Peste es alarmante. ¡La plaga está cobrando fuerza!\n\n¡Necesito hacer más pruebas! La fuente más potente de plaga se encuentra en la carne infestada de sus víctimas más recientes. Viaja a Stratholme y tráeme algunas muestras, <nombre>.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5214] = {title = "El gran Ezra Grimm", objective = "Encuentra la Tienda de humo de Ezra Grimm en Stratholme y recupera una caja del tabaco de calidad de Grimm. Cuando lo hayas hecho, vuelve con Smokey LaRue.|n", description = "Es terrible... lo que le ocurrió a Ezra. Verás, saquearon el pueblo y Ezra no quería dejar sus preciados bienes atrás. Lo último que recuerdo es que decía que quemaría hasta la última hoja antes de permitir que ellos les pusieran sus sucias y malditas manos encima.\n\nDisfruto un buen cigarro como el primero, pero no soy tonto. Aquel día dejé atrás a Ezra y a su aromático almacén. Supongo que todo fue pasto de las llamas, pero si hubiera sobrevivido aunque fuera una sola caja de su famoso tabaco...\n\n¿Qué dices, <nombre>? ¿Encontrarás una caja para el viejo Smokey?Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nMechero de Smokey"}
MultiLanguageQuestData['mx'][5215] = {title = "Las calderas de la Plaga", objective = "Habla con la suma sacerdotisa MacDonnell en el Alto del Orvallo, en las Tierras de la Peste del Oeste.", description = "En las tierras del antiguo Lordaeron hay ocho calderas, cuatro aquí, en el Oeste, y cuatro más ocultas en el Este. Estas calderas vomitan veneno en el aire, propagando la Peste de la Plaga por todo el país.\n\nEl poder nigromántico de Kel'Thuzad es demasiado fuerte para desactivar por completo esas calderas pero creemos tener un modo de subvertirlas en nuestro provecho. Mi segunda, la suma sacerdotisa MacDonnell, será tu guía en esta misión, ella seguirá dándote información a partir de este momento.", progress = nil, completion = "Que el poder de la Luz te ilumine en estos tiempos sombríos, &lt;clase&gt;. Me complace servirte como coordinadora en nuestro plan para sabotear las calderas de la Plaga. \n\nNuestro objetivo será alterar la composición de la peste que crean las calderas, convirtiéndola en algo que afecte negativamente a la Plaga. Para conseguir este cambio tendrás que acceder a las cuatro calderas de las Tierras de la Peste del Oeste. \n\nHas de estar preparado, héroe, ¡te espera una batalla gloriosa contra la vil Plaga!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5218] = {title = "La caldera del Campo de Piedramácula", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][5221] = {title = "La caldera del Llanto de Dalson", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][5224] = {title = "La caldera de El Tormento", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][5227] = {title = "La caldera de la Gangrena de Gahrron", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][5229] = {title = "Objetivo: Campo de Piedramácula", objective = "Ve al Campo de Piedramácula en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Seguramente tendrá una llave para acceder a la caldera. Debes llevar contigo la Botella vacía del Campo de Piedramácula para obtener una muestra de los venenos utilizados en el interior de la caldera.", description = "De las cuatro calderas de las Tierras de la Peste del Oeste, la localizada en el Campo de Piedramácula puede ser la más fácil de acceder. La Plaga tiene allí las tropas menos experimentadas, aunque no hay que subestimarlas.\n\nVe al Campo de Piedramácula, al este de aquí y al noroeste de Andorhal y ocúpate del señor de la caldera. Tendrá una llave que abrirá el acceso a la caldera. Cuando lo hayas conseguido, utiliza esta botella para obtener una muestra de las toxinas de la caldera. La necesitaremos para estudiar el desarrollo de un contraagente.", progress = "Un panel de acceso a la caldera sigue estando cerrado. Para abrirlo tendrás que encontrar la llave.", completion = "La llave que has conseguido del señor de la caldera Garravil encaja perfectamente y abre el panel de acceso, pero desaparece cuando la utilizas. Sin embargo te parece que ahora podrás abrir el panel sin la llave. Un hedor nauseabundo emana del panel una vez abierto, al tiempo que una mezcla desconocida de sustancias concentradas se arremolina en el interior de la caldera. \n\nHay una pequeña espita en la que encaja la botella y puedes recoger una muestra para la sacerdotisa de las Sombras Vandis en El Baluarte.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5231] = {title = "Objetivo: Llanto de Dalson", objective = "Ve al Llanto de Dalson en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la botella vacía del Llanto de Dalson para obtener una muestra de los venenos utilizados en el interior de la caldera.", description = "Una de las calderas de peste está localizada en el campo de una antigua granja, ahora conocida como el Llanto de Dalson. Hoy no se derramará ninguna lágrima, <clase>, debemos atacar esa caldera y acceder a ella.\n\nVe al Llanto de Dalson, al norte de Andorhal, y elimina al señor de la caldera que encontrarás en él. Como el anterior, debería tener una llave para acceder a las entrañas de la caldera. Utiliza esta botella para obtener una muestra del interior de la caldera. Cada una de ellas tiene su propia mezcla de toxinas.", progress = "Un panel de acceso a la caldera sigue estando cerrado. Para abrirlo tendrás que encontrar la llave.", completion = "La llave esquelética que encontraste en el señor de la caldera se desliza suavemente en la cerradura y desaparece, permitiéndote acceder permanentemente al panel. Unos icores crudos y viscosos palpitan a través de tubos retorcidos en el interior de la caldera. \n\nHay una pequeña espita en la que encaja la botella y puedes recoger una muestra para la sacerdotisa de las Sombras Vandis en El Baluarte.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5233] = {title = "Objetivo: El Tormento", objective = "Ve a El Tormento en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de El Tormento para obtener una muestra de los venenos utilizados en el interior de la caldera.", description = "Dos de las calderas han sido abiertas con éxito, puedes acceder a ellas indefinidamente pero todavía queremos que abras las otras dos. ¡Eso nos dará a todos más oportunidades para introducir el contraagente!\n\nEsta vez, te dirigirás contra la caldera de El Tormento. Está al este de Andorhal, bastante cerca de los muros de la ciudad en ruinas. De nuevo, elimina al señor de la caldera y recoge la llave. Utiliza esta botella para obtener la muestra de la caldera.\n\n¡Buena caza, <nombre>!", progress = "Un panel de acceso a la caldera sigue estando cerrado. Para abrirlo tendrás que encontrar la llave.", completion = "La llave del señor de la caldera abre el panel de acceso a la caldera y desaparece como ya ocurrió en las anteriores calderas. Un olor putrefacto se agita violentamente bajo la plataforma de la caldera. \n\nHay una pequeña espita en la que encaja la botella y puedes recoger una muestra para la sacerdotisa de las Sombras Vandis en El Baluarte.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5235] = {title = "Objetivo: Gangrena de Gahrron", objective = "Ve a la Gangrena de Gahrron en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de la Gangrena de Gahrron para obtener una muestra de los venenos utilizados en el interior de la caldera.", description = "La última de las calderas está situada en una granja ahora conocida como la Gangrena de Gahrron. Está custodiada por algunos de los esbirros más duros de la Plaga, concretamente fantasmas y espectros. No se puede jugar con ellos, <nombre>.\n\nLa Gangrena de Gahrron está muy al este de El Baluarte, cerca del comienzo de las Tierras de la Peste del Este. De nuevo, elimina a su señor de la caldera y hazte con la llave. Toma esta botella de muestras y devuélvemela cuando esté llena. Que las sombras te protejan en esta peligrosa misión, <clase>.", progress = "Un panel de acceso a la caldera sigue estando cerrado. Para abrirlo tendrás que encontrar la llave.", completion = "La llave del señor de la caldera Iralma se desintegra al tocar el candado del panel de acceso a la base de la plataforma de la caldera. Se oye un débil sonido metálico en el interior y el panel de acceso se abre para mostrar más toxinas viscosas en el interior de la caldera. \n\nHay una pequeña espita en la que encaja la botella y puedes recoger una muestra para la sacerdotisa de las Sombras Vandis en El Baluarte.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5242] = {title = "El golpe final", objective = "Mata a Moora y Salia y lleva la cabeza de Señor de las Sombras Fel'dan a Greta Pezuñamusgo a Frondavil.", description = "Por desgracia, veo que la única forma de detener esta amenaza a Frondavil es un ataque frontal. No hay otra forma de entrar en la Guarida Sombría y no tengo medios para teletransportarte al interior. El único camino es el que lleva directamente hasta el fondo... y también sé a quién deberías buscar. Su nombre es Fel'dan... Señor de las Sombras Lord Fel'dan es el mortal que manda ahí abajo... Es la cabeza de la serpiente. Mátalo a él y a sus dos súcubos siervos y vuelve a mí. Fel'dan es el que está haciendo pactos con la Legión. Hay que detenerlo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Fajín BarnaleñoGuantes de cuero de añubloFaja de ForjaengranajeRecibirás:\n\n"}
MultiLanguageQuestData['mx'][5243] = {title = "Las casas de lo sagrado", objective = "Viaja al norte, a Stratholme. Registra los cajones de provisiones que hay por toda la ciudad y recupera 5 de agua bendita de Stratholme. Vuelve junto a Leonid Barthalomew el Venerado cuando hayas reunido suficiente líquido bendecido.", description = "Yo considero mi no-muerte como una enfermedad, <raza>. Una que hay que curar, sin más. Pero también la considero una gran bendición para El Alba Argenta. ¿Qué mejor medio hay para atacar a los paganos de la Plaga que los no-muertos?\n\nMis colegas me veneran por los sacrificios que he hecho, pero los elogios para mí no significan nada.\n\nSi te interesa ayudar a El Alba Argenta, puedo ofrecerte un trabajo.\n\nVe a Stratholme y recupera nuestro excedente de agua sagrada. Busca en las cajas de suministros.\nPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Corona del PenitentePodrás elegir una de estas recompensas:\n\nSortija del Penitente\n\nTambién recibirás:\n\nPoción de sanación excelentePoción de maná superior"}
MultiLanguageQuestData['mx'][5244] = {title = "Las Ruinas de Kel'Theril", objective = "Habla con Jaron Tallapiedras en Aldea Estrella Fugaz.", description = "La historia que oculta Kel'Theril es la de una raza maldita, atada al lugar en el que intentaron culminar un desafortunado ritual...\n\nLos Altonato que encontrarás allí robaron un día un artefacto sagrado, creyendo que podrían absorber su poder y apropiárselo, haciéndose todavía más poderosos. En sus esfuerzos, una enorme explosión rompió la reliquia en mil pedazos, que quedaron ocultos bajo el hielo del lago...\n\nSi quieres saber más habla con Jaron Tallapiedras, visitó recientemente la zona y podrá darte más información.", progress = nil, completion = "Sí, claro, puedo darte más información sobre Kel'Theril. Sabes, no soy historiador, pero puedo contarte todo lo que vi...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5245] = {title = "Espíritus afligidos de Kel'Theril", objective = "Usa el pico de Jaron para encontrar los cuatro trozos de reliquia de Altonato. Llévaselos a Aurora Clamacielos en las Tierras de la Peste del Este.", description = "Los espíritus altonato son criaturas miserables, de eso no quedan dudas. Aún buscan piezas del objeto que los maldijo a permanecer en Kel'Theril por siempre: la reliquia robada.\n\nSi te interesa, llévate mi pico y ve hacia el lago que está al sur. Intenta extraer las piezas que están dentro del hielo.\n\nNo tengo idea de qué encontrarás, pero conozco a alguien que quizás sepa algo... Aurora Clamacielos. Se encuentra cerca de la Torre del Paso Norte en la parte norte de las Tierras de la Peste del Este.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5246] = {title = "Trozos del pasado", objective = "Encuentra las Sagradas escrituras de los Altonato del Templo de Zin-Malor en Azshara y tráelas para Aurora Clamacielos en la Torre del Paso Norte en las Tierras de la Peste del Este.", description = "No me daba cuenta... Perdona mis crueles palabras, <clase>.\n\nNo querría recordar los errores de mis antepasados pero si tu búsqueda es realmente sincera, te ayudaré.\n\n<Aurora examina los fragmentos.>\n\nCreo que es el Cristal de Zin-Malor, un artefacto que puede contener y controlar poderosas fuerzas Arcanas. Podría utilizarse para hacer el bien, pero los malignos propósitos de quienes lo robaron lo destrozaron.\n\nVe al Templo de Zin-Malor, en Azshara... tan solo espero que el libro siga allí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5247] = {title = "Trozos del pasado", objective = "Consigue una barra de torio encantado, 5 cristales de restauración y un vial de agua funesta para Aurora Clamacielos en la Torre del Paso Norte, en las Tierras de la Peste del Este.", description = "Si realmente deseas volver a crear el artefacto, podré ayudarte.\n\nPara volver a sellar las piezas necesitaré objetos con fuertes cualidades mágicas. Una barra de torio encantado y cinco cristales de restauración... También tendrás que reunir agua de lo que podría parecer un lugar insólito... Encuentra el Estanque Funesto a lo largo del Pasaje de Eldreth, en La Masacre de Feralas, y rellena este vial.\n\nMientras estés fuera intentaré deducir de estas páginas el saber necesario para reparar el daño hecho a la reliquia.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5249] = {title = "A la Cuna del Invierno!", objective = "Encuentra la Aldea Estrella Fugaz en Cuna del Invierno y habla con Wynd Cazanoche.", description = "En Cuna del Invierno, al norte de aquí, abundan las ruinas élficas. Es una tierra dura, pero alberga muchos secretos y lugares que explorar.\n\nCon todo el trabajo que tengo aquí, en Frondavil, nunca he tenido la oportunidad de viajar a Cuna del Invierno. Pero no hay ninguna razón por la que tú no debieras ir.\n\nCuando estés allí busca a Wynd Cazanoche. Suele encontrarse en Aldea Estrella Fugaz y sabe mucho sobre la zona.", progress = nil, completion = "¿Un amigo de Ivy Correhoja? Un placer conocerte, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5250] = {title = "Estrella Fugaz", objective = "Encuentra la Aldea Estrella Fugaz en Cuna del Invierno y habla con Wynd Cazanoche.", description = "En Cuna del Invierno, al norte de Frondavil, abundan las ruinas élficas. Es una tierra dura, pero alberga muchos secretos y lugares que explorar.\n\nMis estudios me mantienen tan ocupada que nunca he tenido la oportunidad de viajar a Cuna del Invierno por un tiempo. Pero no hay ninguna razón por la que tú no pudieras viajar allí y estudiar las ruinas.\n\nCuando estés allí busca a Wynd Cazanoche. Suele encontrarse en Estrella Fugaz y sabe mucho sobre la zona.\n\nDile que eres mi <alumno/alumna>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5251] = {title = "El archivista", objective = "Viaja a Stratholme y encuentra al archivista Galford de La Cruzada Escarlata. Acaba con él y quema el Archivo Escarlata.", description = "Cualquier cosa llevada al extremo es dañina para nuestro mundo, <nombre>. Piensa, por ejemplo, en la Cruzada Escarlata. ¿Crees que su ciego fanatismo sirve de verdad a un buen superior? ¿A cuántos inocentes han matado en nombre de la Luz?\n\n¡Son todos unos blasfemos! ¡Todos y cada uno de ellos!\n\nPero a mí me interesa uno en concreto: el archivista Galford de Stratholme, un hombre por cuyas manos pasan los más valiosos documentos de la Cruzada. ¡Acaba con él y quema su archivo! Si lo consigues, vuelve a mí y serás <recompensado/recompensada>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5261] = {title = "Eagan Desollapelambres", objective = "Habla con Eagan Desollapelambres.", description = "Eagan Desollapelambres anda buscando a alquien para cazar lobos malsanos. Me alegro, porque últimamente vemos muchos lobos malsanos en Valle de Villanorte.\n\nSi te interesa, ve a hablar con Eagan; está a la izquierda de la abadía.", progress = nil, completion = "Es cierto. ¡Estoy buscando a alguien que pueda cazar lobos! ¿Te interesa?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5262] = {title = "La verdad cae del cielo", objective = "Lleva la cabeza de Balnazzar al duque Nicolas Zverenhoff en las Tierras de la Peste del Este.", description = "Intentas poner tus pensamientos en orden mientras el polvo se asienta en la sala. Repasas los sucesos que han ocurrido y todavía no llegas a comprender la gravedad de la situación.\n\n¿El gran cruzado de la Cruzada Escarlata es un demonio? Y no cualquier demonio, ¡sino el hermano de Varimathras, archiseñor de Entrañas!\n\nGuardas con cuidado la cabeza cortada del Señor del Terror en tu talega. Seguro que nadie se creería lo que ha pasado sin ver una prueba.\n\n¡Hay que decírselo al duque Nicolas Zverenhoff inmediatamente!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5281] = {title = "Espíritus inquietos", objective = "Encuentra a Egan. Solo sabes que fue visto por última vez en los alrededores de Stratholme.", description = "Ahí están aquellos que murieron trágicamente en la caída de Stratholme. Muchos se quitaron la vida. Prefirieron arrojarse a las llamas que arrasaban la ciudad a convertirse en miembros de la Plaga.\n\nAhora sus espíritus inquietos deambulan por las calles de Stratholme.\n\nDebemos ayudarles, <nombre>.\n\nTengo un socio llamado Egan que hace un trabajo maravilloso, casi milagroso, con fantasmas y almas. Ve a buscarlo. Estará por las Tierras de la Peste del Este, cerca de Stratholme, probando sus innovaciones.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5282] = {title = "Espíritus inquietos", objective = "Utiliza el libertador de Egan en los ciudadanos espectrales y fantasmas de Stratholme. Cuando las almas se liberen de sus recipientes fantasmales, vuelve a usarlo y lograrás liberarlos para siempre.\n\nLibera 15 almas y regresa a Egan.", description = "Yo extraigo mi poder -mi voluntad de seguir viviendo y respirando- del ardiente odio que siento por la Plaga y por todo lo que ha hecho. Sin embargo, no soy un zelote. Hay quienes preferirían destruir a los inocentes no-muertos antes que mostrarles siquiera una migaja de compasión, como la Cruzada Escarlata.\n\nY eso es lo que me hizo crear esto: mi libertador. Liberará a las almas atormentadas de Stratholme.\n\nUtilízalo en los fantasmas que vagan por sus calles ruinosas. Libera sus almas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nTestamento de Esperanza"}
MultiLanguageQuestData['mx'][5283] = {title = "El arte del forjador de armaduras", objective = "Para convertirte en <forjador/forjadora> de armaduras tienes que fabricar lo siguiente y llevárselo a Grumnus: 4 yelmos de mitril ornamentado, 2 pares de botas de mitril ornamentado y 1 coraza de mitril ornamentado.", description = "Sabia decisión.\n\nAprecio no tengo por Ironus. Ese chapucero sabe quién buen artesano es.\n\nLas guerras se ganan con una buena defensa solo. A la hora de la verdad, la ofensiva no ayuda.\n\nVenga, a trabajar. Tú haz lo que puedas, que ya te puliré hasta que la creación de armaduras domines. Sabes grabar el mitril, ¿sí?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5284] = {title = "El arte del forjador de armas", objective = "Para convertirte en <armero/armera> tienes que fabricar lo siguiente y llevárselo a Ironus: 4 espadas anchas de acero lunar, 4 hachas de hierro macizo, 2 hachas de mitril pesado y 2 mazas negras grandes.|n", description = "Si en fabricar armas te especializas, muchos héroes y aventureros entre tus clientes te encontrarás. Mucho vas a trabajar, pero las ganancias el dolor de espalda compensan.\n\n¡Que sepas, <nombre>, que fabricando armas mucho oro ganarás!\n\nSi a ello te deseas dedicar, demuéstrame que el talento necesario posees para armas de calidad superior fabricar. ¡A trabajar!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5301] = {title = "El arte del forjador de armaduras", objective = "Para convertirte en <forjador/forjadora> de armaduras tienes que fabricar lo siguiente y llevárselo a Okothos: 4 yelmos de mitril ornamentado, 2 pares de botas de mitril ornamentado y 1 coraza de mitril ornamentado.", description = "Satisfacción. Eso es lo que me dan el yunque y el martillo. Saber que gracias a mi arte con el acero se protegen los guerreros de la Horda me llena de orgullo. No me veo haciendo otro trabajo, <nombre>.\n\nNo puedo jurar que a ti te gustará tanto, pero puedes intentarlo. Llegar a ser forjador de armaduras exige un largo camino de preparación.\n\nSi tú quieres, te enseñaré, pero antes debes cumplir una misión.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5302] = {title = "El arte del forjador de armas", objective = "Para convertirte en <forjador/forjadora> de armas tienes que fabricar lo siguiente y llevárselo a Borgosh: 4 espadas anchas de acero lunar, 4 hachas de hierro macizo, 2 hachas de mitril pesado y 2 mazas negras grandes.|n", description = "Un día crearé un martillo legendario, digno de un Jefe de Guerra.\n\nEse es el objetivo de mi vida, <nombre>. Veo que tienes madera de armero. Puedo ayudarte en tu formación.\n\nSolo tendrás que cumplir con una tarea. Será fácil para alguien con tu habilidad.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5305] = {title = "Dulce serenidad", objective = "Viaja a Stratholme y mata al forjamartillos Carmesí. Consigue el delantal del forjamartillos Carmesí y regresa con Lilith.|n", description = "En los confines de El Bastión Escarlata se encuentra la dulce Serenidad. El forjamartillos Carmesí custodia el diseño con su propia vida. Acaba con él y tráeme su delantal. A cambio te instruiré para convertirte en <forjador/forjadora> de martillos.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDiseño: martillo de batalla encantado"}
MultiLanguageQuestData['mx'][5306] = {title = "Piedra culebra de la cazadora de las Sombras", objective = "Viaja a la Cumbre de Roca Negra y mata a la cazadora de las Sombras Vosh'gajin. Recupera la piedra culebra de Vosh'gajin y vuelve con Kilram.", description = "No te dejes engañar por su belleza, <clase>. Vosh'gajin, la cazadora de las Sombras, es mortífera y está alienada.\n\n<Kilram señala una cicatriz que lleva en la cara.>\n\nSí señor, ella me la hizo, un \"toquecito\" de amor, me dijo.\n\nPor fin ha llegado la hora de la venganza.\n\nPodrás encontrar a Vosh'gajin en la Cumbre de Roca Negra. Mátala y tráeme su piedra culebra. Hazlo y te enseñaré las artes del forjador del Filo del Alba.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDiseño: Filo del Alba"}
MultiLanguageQuestData['mx'][5307] = {title = "Corrupción", objective = "Encuentra al armero Guardia Negra en Stratholme y acaba con él. Recupera la Insignia de La Guardia Negra y regresa con Seril Finiquiplaga.", description = "Siento ser algo brusco contigo, pero tengo mis motivos. La Guardia Negra, las unidades esqueléticas de élite del Barón Osahendido, han robado el diseño de la gran espada Corrupción.\n\nSí, el Barón Osahendido de Stratholme.\n\nEl armero Guardia Negra custodia ahora ese diseño con su... no-muerte.\n\nAcaba con él y tráeme una muestra de esa hazaña. Si lo haces te instruiré en las artes de la forja de espadas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDiseño: Estoque llameante"}
MultiLanguageQuestData['mx'][5321] = {title = "El despertar", objective = "Escolta a Kerlonian Semprumbrío hasta Liladris Rioluna en la Atalaya de Maestra de Vallefresno.", description = "Estaba de camino hacia la Atalaya de Maestra para encontrarme con Liladris Rioluna, pero decidí detenerme aquí a echar una siestecita. Desde que me desperté de mi Sueño Esmeralda me invade un gran sopor...\n\n<bostezo>\n\n¿Te importaría indicarme el camino? Tengo entendido que la Atalaya de Maestra está al sur de aquí, por el camino de Vallefresno. Es peligroso, espero que tengas amigos que se unan a nuestra expedición.\n\nOtra cosa: puede que me duerma, así que, si necesitas despertarme, utiliza mi cuerno. Lo encontrarás en este cofre.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Rifle con vista de búhoEscudo de aceroPodrás elegir una de estas recompensas:\n\nBordón de fuego de jade\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][5341] = {title = "La fortuna de la familia Barov", objective = "Aventúrate a Scholomance y recupera la fortuna familiar de los Barov. La fortuna se compone de cuatro escrituras: Las escrituras de Castel Darrow, Las escrituras de Rémol, Las escrituras de Molino Tarren y Las escrituras de Costasur. Regresa con Alexi Barov cuando hayas terminado esta tarea.", description = "En el interior de Scholomance se encuentra la fortuna familiar de los Barov. Yo, Alexi Barov, soy uno de los dos últimos herederos de la casa Barov. Mi hermano, Weldon, es el otro.\n\nWeldon, ese despreciable cobarde, huyó durante la guerra y pudo conservar su miserable existencia humana.\n\nAhora está buscando las escrituras para poder reclamar para sí esa fortuna. ¡Recupera las escrituras antes que mi hermano y te haré más <rico/rica> que en tus sueños más descabellados!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5342] = {title = "El último de los Barov", objective = "Viaja al Campamento del Orvallo, territorio de la Alianza, y asesina a Weldon Barov. Coge su cabeza y regresa con Alexi Barov.\n\nTen cuidado, Alexi seguramente estará muy protegido por la escoria de la Alianza.", description = "Por supuesto, si mi hermano sigue con vida, puede haber algo de controversia sobre quién sea el principal beneficiario de la fortuna familiar. No puede ser.\n\nUn vulgar pilluelo como tú no está por encima de un asesino de sangre fría... espero.\n\nEs una tarea fácil y espero que la cumplas... siempre que quieras tu recompensa.\n\nWeldon está protegido por la Alianza, en el Campamento del Orvallo, al Este. Mátalo y tráeme su cabeza.\n\n<Alexi bosteza.>\n\nY ahora, date prisa.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nLlamador de campesino Barov"}
MultiLanguageQuestData['mx'][5343] = {title = "La fortuna de la familia Barov", objective = "Aventúrate a Scholomance y recupera la fortuna familiar de los Barov. La fortuna se compone de cuatro escrituras: Las escrituras de Castel Darrow, Las escrituras de Rémol, Las escrituras de Molino Tarren y Las escrituras de Costasur. Regresa con Weldon Barov cuando hayas terminado esta tarea.", description = "Mi querido hermano Alexi. Qué idiota fui perdonándole la vida. Miré a los ojos de mi enemigo, uno de los no-muertos, y le dejé vivir.\n\n<Weldon escupe.>\n\nY ahora busca MI herencia. No puede ocurrir.\n\nEncuentra las escrituras de mi familia antes de que sus manos huesudas las encuentren y te recompensaré con enormes riquezas. Podrás encontrarlas en las ruinas de Scholomance. ¡Date prisa!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5344] = {title = "El último de los Barov", objective = "Viaja a El Baluarte, territorio de la Horda, y asesina a Alexi Barov. Coge su cabeza y regresa con Weldon Barov.\n\nTen cuidado, Alexi seguramente estará muy protegido por la escoria de la Horda.", description = "Ahora que he recuperado las escrituras, solo queda una cosa por hacer. Alexi debe morir. Cuando esté muerto no tendré que preocuparme nunca más por tener a una banda de mercenarios sin escrúpulos buscando mi cabeza.\n\nEs una tarea fácil. Alexi está protegido por la Horda, en El Baluarte.\n\nPero no, no quiero que vayas allí y lo mates, ¡quiero su cabeza! Cómo conseguirla... es asunto tuyo. Ese tipo de comportamiento está por debajo de mi noble educación.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nLlamador de campesino Barov"}
MultiLanguageQuestData['mx'][5361] = {title = "Árbol genealógico", objective = "Entrégale el informe de Vigiarisco Cuerno Largo a Nataka Cuerno Largo que se encuentra en el Campamento del Espíritu Errante de Desolace.", description = "Mi hermano Nataka está destacado en el Campamento del Espíritu Errante en Desolace. Me gustaría pedirte que le entregaras este informe de mi parte. Ha pasado un año desde la última vez que escribí y desde entonces ha habido mucha actividad de los centauros de la que debería ser informado.\n\nViaja a Sierra Espolón al norte de El Cruce, y después dirígete hacia el oeste hasta La Vega Carbonizada. Desde allí, ve en dirección sur hasta Desolace, donde encontrarás un camino que se extiende en dirección sur y que conduce hasta el Campamento del Espíritu Errante.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5381] = {title = "La Mano de Iruxos", objective = "Extrae la caja de demonio de la Fortaleza del Hacha de Trueno y llévasela a Taiga Crin Sabia a la Aldea Cazasombras junto con el pico de demonio.|n", description = "El Filo Ardiente posee la caja de demonio. En su interior se encuentra la poderosa Mano de Iruxos. El Filo Ardiente la utiliza para abrir portales demoníacos en el Aquelarre Mannoroc. ¡Debemos impedir que esa oleada de demonios entre en nuestro mundo, <nombre>!\n\nUtiliza este pico de demonio con el cristal rojo de la Fortaleza del Hacha de Trueno para acceder a la caja de demonio.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5382] = {title = "Doctor Theolen Krastinov, el Carnicero", objective = "Busca al doctor Theolen Krastinov en el interior de Scholomance. Acaba con él y quema los restos de Eva Sarkhoff y los restos de Lucien Sarkhoff. Cuando hayas terminado tu tarea regresa con Eva Sarkhoff.|n", description = "Krastinov es responsable de la muerte de miles. Debe ser castigado, debe hacerse justicia.\n\nBúscale y hazle rendir cuentas por la agonía que ha infligido a incontables inocentes. Cuando haya sido destruido, quema nuestros restos. Redúcelos a cenizas, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5386] = {title = "La pesca del día", objective = "Habla con Jinar'Zillen, en la Aldea Cazasombras, y luego lleva 2 panzasangres a Nataka Cuerno Largo.", description = "Hace tiempo que no se huele el aroma del pescado cocinado en el Campamento del Espíritu Errante. Los trols de la Aldea Cazasombras son los mejores pescadores pero... con toda la actividad que están desplegando los centauros, tengo poco tiempo para ir a donde los trols. Mm...\n\nHazme el favor de ir tú a la Aldea Cazasombras. Habla con el pescador Jinar'Zillen y tráeme mi pescado favorito, el panzasangre. El camino que hay al sur de aquí te llevará hacia el oeste, hasta la aldea trol.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nMena de mitrilCuero gruesoPaño de tejido mágico\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][5401] = {title = "Comisión de El Alba Argenta", objective = "Todos los que combaten el mal en nombre de El Alba Argenta deben vestir nuestra Comisión. Al hacerlo obtendrás el derecho de reclamar recompensas a nuestros intendentes.\n\nMientras estés bajo nuestra comisión podrás adquirir piedras de la Plaga de sus miembros caídos ya que esas piedras son insignias que a veces llevan consigo. Hazte con esas insignias y tráemelas. Por cada juego que traigas recibirás nuestras señales de heroísmo: las muestras de valor de El Alba Argenta.\n\nSigue tu destino, <clase>, ¡únete hoy mismo a la lucha!", description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nComisión de El Alba Argenta"}
MultiLanguageQuestData['mx'][5402] = {title = "Piedras de la Plaga del esbirro", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nMuestra de valor de El Alba Argenta"}
MultiLanguageQuestData['mx'][5403] = {title = "Piedras de la Plaga del invasor", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nMuestra de valor de El Alba Argenta"}
MultiLanguageQuestData['mx'][5404] = {title = "Piedras de la Plaga del corruptor", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nMuestra de valor de El Alba Argenta"}
MultiLanguageQuestData['mx'][5405] = {title = "Comisión de El Alba Argenta", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nComisión de El Alba Argenta"}
MultiLanguageQuestData['mx'][5406] = {title = "Piedras de la Plaga del corruptor", objective = "Una piedra de la Plaga del corruptor es la insignia de los Señores Supremos de la Plaga. Todo ser poderoso y con autoridad sobre la Plaga posee una de esas piedras. Acabar con una criatura tan malévola sería un gran paso adelante para la causa de El Alba Argenta y para todas las causas justas.\n\nEn nombre de El Alba Argenta te daré una muestra de valor a cambio de una sola de esas insignias. Ten cuidado al obtenerlas, <nombre>... no hay que andar jugando con criaturas tan poderosas.", description = nil, progress = "Una piedra de la Plaga del corruptor es la insignia de los Señores Supremos de la Plaga. Todo ser poderoso y con autoridad sobre la Plaga posee una de esas piedras. Acabar con una criatura tan malévola sería un gran paso adelante para la causa de El Alba Argenta y para todas las causas justas.\n\nEn nombre de El Alba Argenta te daré una muestra de valor a cambio de una sola de esas insignias. Ten cuidado al obtenerlas, <nombre>... no hay que andar jugando con criaturas tan poderosas.", completion = "Felicidades, &lt;nombre&gt;. ¡Es un placer recompensarte con una muestra de valor de El Alba Argenta!\n\nAdquirir una muestra de valor de esta forma indica que eres una auténtica heroína de la causa del bien. Valoramos todo esfuerzo hecho contra la Plaga, ¡pero acabar con uno de sus líderes es un auténtico avance hacia su derrota!\n\n¡Por El Alba, hermana!", rewards = "Recibirás:\n\nMuestra de valor de El Alba Argenta"}
MultiLanguageQuestData['mx'][5407] = {title = "Piedras de la Plaga del invasor", objective = "Una piedra de la Plaga del invasor es la insignia de las tropas de élite de la Plaga. A veces pueden encontrarse entre los más fuertes de las tropas destacadas en las Tierras de la Peste. Derrotar una criatura así es, sin duda, todo un reto, pero uno del que se disfruta cuando se está comprometido con la aniquilación del mal. \n\nEn este momento, El Alba Argenta ofrece una muestra de valor a cambio de diez de esas insignias. Tráemelas y me aseguraré de que recibas tu recompensa.", description = nil, progress = "Una piedra de la Plaga del invasor es la insignia de las tropas de élite de la Plaga. A veces pueden encontrarse entre los más fuertes de las tropas destacadas en las Tierras de la Peste. Derrotar una criatura así es, sin duda, todo un reto, pero uno del que se disfruta cuando se está comprometido con la aniquilación del mal. \n\nEn este momento, El Alba Argenta ofrece una muestra de valor a cambio de diez de esas insignias. Tráemelas y me aseguraré de que recibas tu recompensa.", completion = "Felicidades, &lt;nombre&gt;. ¡Es un placer recompensarte con una muestra de valor de El Alba Argenta!\n\nCada muestra de valor entregada a alguien digno de ella es un símbolo de la oleada que se está abriendo contra la Plaga. Cada vez son más los héroes que combaten a la Plaga en nuestras tierras, lo que asegura que El Alba Argenta ocupará un puesto destacado cuando llegue el momento de hacer frente al mal último de la Plaga. ¡Espero que el valor que has demostrado y que te permitió conseguir una de estas muestras también esté presente ese día!", rewards = "Recibirás:\n\nMuestra de valor de El Alba Argenta"}
MultiLanguageQuestData['mx'][5408] = {title = "Piedras de la Plaga del esbirro", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nMuestra de valor de El Alba Argenta"}
MultiLanguageQuestData['mx'][5421] = {title = "Pescado en un balde", objective = "Jinar'Zillen quiere que recojas 5 mariscos de las trampas que hay cerca de la Aldea Cazasombras.", description = "Recompensaré a cualquiera que haga mi vida un poco más fácil... ¡Mi vida se rige por la ley del mínimo esfuerzo, colega!\n\nBajo el embarcadero, aquí en la Aldea Cazasombras, tengo muchas trampas para marisco. Si fueras tan amable... podrías hacer mi trabajo y recoger mi marisco... Y luego yo te doy algo que quieres, ¿pillas el sistema, colega?", progress = "Recompensaré a cualquiera que haga mi vida un poco más fácil... ¡Mi vida se rige por la ley del mínimo esfuerzo, colega!\n\nBajo el embarcadero, aquí en la Aldea Cazasombras, tengo muchas trampas para mariscos. Si fueras tan amable... podrías hacer mi trabajo y recoger mis mariscos... Y luego yo te daría algo que quieras, ¿entiendes el sistema, colega? ¡Por cada cinco mariscos que me traigas te daré un delicioso panzasangre!", completion = "Genial. Nada mejor que un trabajo bien hecho... sobre todo si lo hace otro, ¿eh?", rewards = "Recibirás:\n\nPanzasangre"}
MultiLanguageQuestData['mx'][5441] = {title = "Peones vagos", objective = "Utiliza la Cachiporra del supervisor con los peones vagos que estén durmiendo. Despierta a 5 peones y devuélvele la cachiporra al supervisor Thazz'ril en el Valle de los Retos.", description = "¡Malditos peones! Trabajan muy duro recogiendo madera de los árboles del valle, ¡pero siempre se están echando siestas! Necesito a alguien que me ayude a mantener firmes a esos peones.\n\nPareces <el/la:r> <raza> <adecuado/adecuada> para esta tarea. Toma, coge esta cachiporra y utilízala con los perezosos peones que encontrarás durmiendo por ahí durante el trabajo. ¡Un buen golpe y volverán al trabajo! Devuélveme la cachiporra cuando hayas terminado.\n\nQué vagos y flojos son estos peones...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5461] = {title = "El humano, Ras Murmuhielo", objective = "Viaja a las Tierras Altas de Arathi, a las Ruinas de Stromgarde. En Stromgarde busca un Libro de los Recuerdos. Si lo encuentras llévaselo al magistrado Marduke.", description = "Los no-muertos temen tanto la vida como los vivos la muerte. No es extraño que un no-muerto sensible destruya todo resto de su vida anterior tras haberse convertido.\n\nPor desgracia, para crear un artefacto capaz de devolver a Ras Murmuhielo a la mortalidad, necesitamos un recuerdo del tiempo que pasó entre los vivos.\n\nDebes adentrarte en la ciudad en ruinas de Stromgarde, el hogar de Murmuhielo y buscar algo así. Que la suerte te acompañe, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5481] = {title = "La tarea de Gordo", objective = "Recoge 3 hierbas luminiscentes y entrégaselas al boticario auxiliar Holland en el cementerio de Rémol.", description = "Maestro querer hierbas. Nosotros manos grandes y no poder recoger. Si tú ayudas nosotros no hacer daño. Nosotros necesitar hierba luminiscente. Haber muchas por aquí y cerca de camino.\n\nCuando tú tener hierba luminiscente, llevar a maestro Holland a cementerio de Rémol.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5482] = {title = "Apocalíseas", objective = "Recoge 10 apocalíseas y entrégaselas al boticario auxiliar Holland.|n", description = "Estoy en un aprieto, <nombre>. ¡Esa cosa está ahí fuera recogiendo las plantas que no son! Te recompensaré si recoges lo que necesito. Tráeme suficientes apocalíseas y te daré una recompensa apropiada.\n\nTengo entendido que abundan en las proximidades de la fosa común, al norte del cementerio de Rémol. Date prisa y ten cuidado con los gnolls que vagan por la zona.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5501] = {title = "Recolección de kodos", objective = "Lleva 10 huesos de kodo del Cementerio de Kodos a Bibbly F'utzhebilla a la Cabaña de Kormek.", description = "Tenemos todo un filón aquí, ¡un auténtico filón! Los huesos de kodo cambiarán el mundo para siempre... Tengo clientes que hacen muebles, instrumentos musicales e incluso pólvora con ellos.\n\nHay una caravana que viene a recoger mis huesos de kodo y los vende en la Aldea Cazasombras. Si puedes ir al Cementerio de Kodos que está al sur de aquí y traerme diez huesos de kodo, te daré algo a cambio. ¿Trato hecho?", progress = "¿Tienes los huesos? La caravana llegará de un momento a otro. Solo necesito 10 huesos de kodo más para llegar a la cumbre. ¡A la cumbre de mi carrera, sí señor!", completion = "¡Ah, qué visión tan estupenda! ¡Mis huesos! \n\nEstoy deseando que los de casa vean mi cara en la portada de Grandes fortunas goblin. Seré el goblin más rico del mundo. ¡Y mi profesor de gimnasia decía que nunca llegaría a nada!", rewards = "Recibirás:\n\nCollar de huesos de kodo"}
MultiLanguageQuestData['mx'][5502] = {title = "Alcaide de la Horda", objective = "Compra un expositor para espadas de gomaespuma a Blax Botemisil en La Calle Mayor de Orgrimmar. Después, habla con la supervisora de huérfanos Llantobatalla en La Calle Mayor para llevar a tu pupilo de vuelta al orfanato de Orgrimmar.", description = "Has sido muy <bueno/buena> conmigo, <nombre>. Nunca había soñado con divertirme tanto en la Semana de los Niños. Gracias.\n\nOjalá todos los huérfanos tuvieran la suerte de ver lo que hemos visto nosotros. ¿Quieres que vayamos a buscar a Blax Botemisil de nuevo y que le compremos un expositor para espadas de gomaespuma? Creo que todavía está empujando esa vagoneta en La Calle Mayor. ¡Así todo el mundo en el orfanato podrá hacer algo divertido!\n\nDespués, ya será hora de que me vaya a casa.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nCollera de cochinilloJaula de ratasCarcasa de tortugaCaracolaGalleta de mascota mágicaPago de cascarrabias\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][5503] = {title = "Comisión de El Alba Argenta", objective = "Todos los que combaten el mal en nombre de El Alba Argenta deben vestir nuestra Comisión. Al hacerlo obtendrás el derecho de reclamar recompensas a nuestros intendentes.\n\nMientras estés bajo nuestra comisión podrás adquirir piedras de la Plaga de sus miembros caídos ya que esas piedras son insignias que a veces llevan consigo. Hazte con esas insignias y tráemelas. Por cada juego que traigas recibirás nuestras señales de heroísmo: las muestras de valor de El Alba Argenta.\n\nSigue tu destino, <clase>, ¡únete hoy mismo a la lucha!", description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nComisión de El Alba Argenta"}
MultiLanguageQuestData['mx'][5504] = {title = "Mantos del Alba", objective = "Lleva 10 muestras de valor de El Alba Argenta al intendente Hasana en El Baluarte, en las Tierras de la Peste del Oeste.", description = "Los servicios que has prestado a El Alba Argenta son dignos de elogio, <nombre>. Te has convertido en <nuestro venerado/nuestra venerada>. He sido autorizado para poner a tu disposición uno de los objetos más valorados de El Alba: nuestros mantos de resistencia mágica.\n\nSi aplicas uno de estos mantos a tus hombreras aumentará tu resistencia a los poderes mágicos en una de sus cinco formas posibles. Como símbolo de tu dedicación a nuestra causa, te pido, a cambio de acceder a estos mantos, un mínimo de diez muestras de valor.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5507] = {title = "Mantos del Alba", objective = "Lleva 10 muestras de valor de El Alba Argenta al intendente Chispillo en el Campamento del Orvallo, en las Tierras de la Peste del Oeste.", description = "Los servicios que has prestado a El Alba Argenta son dignos de elogio, <nombre>. Te has convertido en <nuestro venerado/nuestra venerada>. He sido autorizado para poner a tu disposición uno de los objetos más valorados de El Alba: nuestros mantos de resistencia mágica.\n\nSi aplicas uno de estos mantos a tus hombreras aumentará tu resistencia a los poderes mágicos en una de sus cinco formas posibles. Como símbolo de tu dedicación a nuestra causa, te pido, a cambio de acceder a estos mantos, un mínimo de diez muestras de valor.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5508] = {title = "Piedras de la Plaga del corruptor", objective = "La piedra de la Plaga del corruptor es la insignia de los Señores Supremos de la Plaga. Unos seres poderosos que disfrutan de una posición de autoridad en la Plaga. Siempre llevan una. Matar a esas criaturas tan malévolas ayudaría sin duda a la causa de El Alba Argenta... ¡y a todas las buenas causas del mundo!\n\nDe parte de El Alba Argenta, te daré una muestra de valor a cambio de una sola de estas insignias. Sé prudente cuando quieras hacerte con una, <nombre>, los seres que las poseen son poderosos.", description = nil, progress = "La piedra de la Plaga del corruptor es la insignia de los Señores Supremos de la Plaga. Unos seres poderosos que disfrutan de una posición de autoridad en la Plaga. Siempre llevan una. Matar a esas criaturas tan malévolas ayudaría sin duda a la causa de El Alba Argenta... ¡y a todas las buenas causas del mundo!\n\nDe parte de El Alba Argenta, te daré una muestra de valor a cambio de una sola de estas insignias. Sé prudente cuando quieras hacerte con una, <nombre>, los seres que las poseen son poderosos.", completion = "Felicidades, &lt;nombre&gt;. ¡Es un placer recompensarte con una muestra de valor de El Alba Argenta!\n\nAdquirir una muestra de valor de esta forma indica que eres una auténtica heroína de la causa del bien. Valoramos todo esfuerzo hecho contra la Plaga, ¡pero acabar con uno de sus líderes es un auténtico avance hacia su derrota!\n\n¡Por El Alba, hermana!", rewards = "Recibirás:\n\nMuestra de valor de El Alba Argenta"}
MultiLanguageQuestData['mx'][5509] = {title = "Piedras de la Plaga del invasor", objective = "Una piedra de la Plaga del invasor es la insignia de las tropas de élite de la Plaga. A veces pueden encontrarse entre los más fuertes de las tropas destacadas en las Tierras de la Peste. Derrotar una criatura así es, sin duda, todo un reto, pero uno del que se disfruta cuando se está comprometido con la aniquilación del mal. \n\nEn este momento, El Alba Argenta ofrece una muestra de valor a cambio de diez de esas insignias. Tráemelas y me aseguraré de que recibas tu recompensa.", description = nil, progress = "Una piedra de la Plaga del invasor es la insignia de las tropas de élite de la Plaga. A veces pueden encontrarse entre los más fuertes de las tropas destacadas en las Tierras de la Peste. Derrotar una criatura así es, sin duda, todo un reto, pero uno del que se disfruta cuando se está comprometido con la aniquilación del mal. \n\nEn este momento, El Alba Argenta ofrece una muestra de valor a cambio de diez de esas insignias. Tráemelas y me aseguraré de que recibas tu recompensa.", completion = "Felicidades, &lt;nombre&gt;. ¡Es un placer recompensarte con una muestra de valor de El Alba Argenta!\n\nCada muestra de valor entregada a alguien digno de ella es un símbolo de la oleada que se está abriendo contra la Plaga. Cada vez son más los héroes que combaten a la Plaga en nuestras tierras, lo que asegura que El Alba Argenta ocupará un puesto destacado cuando llegue el momento de hacer frente al mal último de la Plaga. ¡Espero que el valor que has demostrado y que te permitió conseguir una de estas muestras también esté presente ese día!", rewards = "Recibirás:\n\nMuestra de valor de El Alba Argenta"}
MultiLanguageQuestData['mx'][5510] = {title = "Piedras de la Plaga del esbirro", objective = "Una piedra de la Plaga del esbirro es la insignia de las filas de la Plaga. A veces pueden encontrarse en los miembros más débiles de las tropas destacadas en las Tierras de la Peste, aunque la palabra \"débil\" es muy relativa. La Plaga, da igual de quién se trate, nunca debe ser subestimada.\n\nEn este momento El Alba Argenta ofrece una muestra de valor a cambio de veinte de esas insignias... un intercambio que me encantaría hacer, ¡siempre y cuando tengas suficientes piedras de la Plaga!", description = nil, progress = "Una piedra de la Plaga del esbirro es la insignia de las filas de la Plaga. A veces pueden encontrarse en los miembros más débiles de las tropas destacadas en las Tierras de la Peste, aunque la palabra \"débil\" es muy relativa. La Plaga, da igual de quién se trate, nunca debe ser subestimada.\n\nEn este momento El Alba Argenta ofrece una muestra de valor a cambio de veinte de esas insignias... un intercambio que me encantaría hacer, ¡siempre y cuando tengas suficientes piedras de la Plaga!", completion = "Felicidades, &lt;nombre&gt;. ¡Es un placer recompensarte con una muestra de valor de El Alba Argenta!\n\nLas muestras tienen dos propósitos. En primer lugar, pueden utilizarse para aumentar tu reputación con El Alba Argenta, de ese modo tendrás a tu disposición oportunidades y recompensas reservadas a nuestros aliados honorables y venerados. En segundo lugar, puedes entregarlas a nuestros intendentes, junto con algunas monedas, como pago por algunos de los objetos más valiosos de El Alba.\n\nDecidas lo que decidas, te estás ganando tu comisión. ¡Bien hecho!", rewards = "Recibirás:\n\nMuestra de valor de El Alba Argenta"}
MultiLanguageQuestData['mx'][5513] = {title = "Mantos del Alba", objective = "Lleva 10 muestras de valor de El Alba Argenta al intendente Cerrobrecha a la Capilla de la Esperanza de la Luz de las Tierras de la Peste del Este.", description = "Los servicios que has prestado a El Alba Argenta son dignos de elogio, <nombre>. Te has convertido en <nuestro venerado/nuestra venerada>. He sido autorizado para poner a tu disposición uno de los objetos más valorados de El Alba: nuestros mantos de resistencia mágica.\n\nSi aplicas uno de estos mantos a tus hombreras aumentará tu resistencia a los poderes mágicos en una de sus cinco formas posibles. Como símbolo de tu dedicación a nuestra causa, te pido, a cambio de acceder a estos mantos, un mínimo de diez muestras de valor.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5514] = {title = "Molde rima con... ¿oro?", objective = "Lleva los trozos esqueléticos imbuidos y 15 piezas de oro a Krinkle Buenacero en Gadgetzan.", description = "El goblin con el que tienes que hablar es Krinkle Buenacero. Ofrece sus servicios al mejor postor en Gadgetzan, en el Desierto de Tanaris. Probablemente sea el único que puede producir el molde que necesitamos, y sus servicios no serán baratos. Te pedimos una generosa contribución pagando los honorarios que te cobre.\n\nYo soy boticario, no un banquero. Si tuviera montones de oro no estaría aquí.\n\nCreo que he vuelto a pensar en voz alta... ups.\n\n¡Gadgetzan te espera! ¡Buena suerte!Cuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][5517] = {title = "Manto del Alba cromático", objective = "Lleva 25 muestras de valor de El Alba Argenta al intendente Cerrobrecha a la Capilla de la Esperanza de la Luz de las Tierras de la Peste del Este.", description = "<Hermano/Hermana> <nombre>, tus hazañas en nombre de El Alba Argenta son tantas que a penas pueden contarse. Como tributo me desprenderé de uno de nuestros mantos cromáticos de El Alba, una versión que protege a quien los viste de todas las formas de magia para las que existe resistencia simultáneamente. ¡Los mantos cromáticos de El Alba están reservados para los más poderosos héroes de El Alba!\n\nEntrégame veinticinco muestras de valor como símbolo de tu homenaje y te daré el mejor de nuestros mantos.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nManto del Alba cromático"}
MultiLanguageQuestData['mx'][5518] = {title = "El disfraz de ogro Gordok", objective = "Lleva 4 madejas de paño rúnico, 8 cueros bastos, 2 hilos rúnicos y tanino de ogro a Knot Llavededo. Actualmente está encadenado en el interior del ala Gordok de La Masacre.", description = "Si vas a combatir con el rey de este basurero -y creo que es lo que vas a hacer- vas a tener que pasar por el capitán Kromcrush. Puedes limitarte a matarlo, claro, pero quizás te convendría dejarlo vivir.\n\n¿Que cómo? Pues... durante el tiempo que he estado aquí, he aprendido a hacer un traje de ogro que durará lo suficiente como para engañar a esos tipos. El único problema es la estabilidad... máximo diez minutos. Tráeme lo que necesito y te haré uno. Yo no voy a ir a ninguna parte...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDisfraz de ogro Gordok"}
MultiLanguageQuestData['mx'][5525] = {title = "¡Libera a Knot!", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5526] = {title = "Fragmentos de gangrevid", objective = "Encuentra gangrevid en La Masacre y coge un fragmento. Es probable que solo puedas conseguirlo si derrotas a Alzzin el Formaferal. Usa el relicario de Pureza para guardar el fragmento y llévaselo a Rabine Saturna a Amparo de la Noche, en Claro de la Luna.", description = "Lo que sabes de Eldre'Thalas - La Masacre - en Feralas te será muy útil, <nombre>. Alzzin el Formaferal ha instalado sus corruptos dominios al este de la ciudad en ruinas. Ve a la mayor brevedad y enfréntate al desafío que te está esperando.\n\nLa fruta de la fertilidad, ahora corrompida en forma de gangrevid, estará cerca de Alzzin. Cuando caiga, recupera tanta esencia de gangrevid como puedas. Sella el relicario y tráemelo.\n\nSuerte y que Cenarius te acompañe.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Escudo de MilliPodrás elegir una de estas recompensas:\n\nLexicón de Milli\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][5527] = {title = "Un relicario de Pureza", objective = "Ve a Silithus a buscar un relicario de Pureza en las ruinas de la Aldea del Viento del Sur. Llévaselo a Rabine Saturna a Amparo de la Noche, en Claro de la Luna.", description = "Lo primero es encontrar un contenedor en el que mantener una sustancia extremadamente delicada sin causar daños a quien lo porte. Solo se me ocurre una cosa que pudiera contener algo tan vil como la gangrevid: un relicario de Pureza.\n\nEn los eriales de Silithus se encuentran los restos de la Villa Elfo de la Noche de Viento del Sur. Sé que había un relicario allí, hace años. Necesito que vayas a buscarlo entre las ruinas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5528] = {title = "La cata de los Gordok", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nGrog verde de GordokCerveza negra de Kreeg"}
MultiLanguageQuestData['mx'][5529] = {title = "Crías de dragón apestadas", objective = "Mata a 20 crías de dragón apestadas y ve a ver a Betina Bigglezink a la Capilla de la Esperanza de la Luz.", description = "¡El Alba Argenta ha descubierto hace poco que la Plaga está criando Vuelos apestados por su cuenta! Debemos detenerlos; ¡con una tropa de dragones podrían arrasar Azeroth!\n\nSus nigrománticos crían dragones apestados en Scholomance, en pleno Lago Darrowmere.\n\nVe allí y mata tantas crías de dragón como puedas... ¡y mientras puedas!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5534] = {title = "El equipamiento \"perdido\" de Kim'jael", objective = "Encuentra una runa que los nagas guardan en las Ruinas de Eldarath y llévasela a Kim'jael en Azshara.", description = "¡¿Qué?! ¡No me lo puedo creer!\n\n¿Eso no te bastaba? ¿Sabes lo caros que son esos explosivos? Los venden a... bah, da igual. Vale, ¿quieres ganar dinero pero en serio? Porque así es cómo se hacen los negocios: demuestras que eres un buen empleado y se te recompensa debidamente después de que hayas aguantado algo.\n\nSi eres \"<un buen/una buena>\" <empleado/empleada>, entonces ve a las Ruinas de Eldarath y encuéntrame una runa que los elfos de sangre andaban buscando. Al parecer, está en manos de los nagas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5535] = {title = "Agitación espiritual", objective = "Mata a 6 aparecidas Altonato y 6 exanimatos Altonato antes de volver junto a Loh'atu en Azshara.", description = "Hace mucho tiempo, los Altonato se encontraban entre los más poderosos alumnos de magia arcana que los elfos de la noche hubieran formado nunca. La corrupción que suele acompañar esos estudios causó mucho daño a la sociedad elfa y afectó en gran medida a todo Azeroth... como seguramente ya sabrás.\n\nLes prometí a las centinelas que liberaría a los espíritus de sus vínculos mortales a medida que los encontrara. Si hicieras lo mismo, te recompensaría.\n\nLos espíritus habitan el Santuario Cantosombrío al noreste de aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5536] = {title = "Una tierra llena de odio", objective = "Mata 6 sátiros Haldarr, 2 tramposos Haldarr, 2 jurapenas Haldarr y vuelve junto a Loh'atu en la frontera de Vallefresno.", description = "Los sátiros, una alteración maligna y desfigurada de los elfos de la noche, infectan ahora los dominios sagrados por los que otrora viajara Cenarius. No puedo hablar por los elfos de noche cuando se trata de todas las atrocidades que esas criaturas demoníacas han cometido pero he prestado juramento a la Madre Tierra de que ayudaría a los elfos a librar estas tierras de semejante incordio.\n\nSeguro que demostrarías lo que vales si me ayudaras a erradicarlos.\n\nAl noreste de este lugar encontrarás al clan Haldarr. Vuelve a mí cuando te hayas puesto a prueba frente a su fuerza.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5541] = {title = "Municiones para Estruendo", objective = "Lleva la munición de Estruendo a Hegnar Estruendo a Dun Morogh.", description = "Hegnar Estruendo vende armas de fuego en la carretera de Yunquemar. Los fusileros y los equipos de mortero pasan mucho tiempo practicando en la parte exterior de su tienda y siempre necesita munición fresca.\n\nPero la última caja de munición que le envié se perdió por el camino. Mi mensajero acampó cerca de El Cubil Pardo. Cuando un wendigo lo expulsó de allí, ¡el muy inútil, se dejó la munición de Estruendo!\n\n<nombre>, ¿podrías recuperar esa munición y llevársela a Estruendo? Lleva mucho tiempo esperándola y se le estarán acabando las reservas.", progress = "Espero que no hayas venido a por munición, ¡porque casi se me ha agotado!", completion = "¡Genial, más munición! ¡Por fin ha llegado el cargamento del viejo Loslor! La munición llega con algo de retraso, pero como decía mi abuelo: ¡más vale tarde que nunca!\n\nMuchas gracias, &lt;nombre&gt;. ¡Voy a atender a mis ansiosos compradores!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5542] = {title = "Perros demoníacos", objective = "Mata 20 cachorros de can de peste, 5 canes de peste y 5 canes de peste demenciados. Cuando hayas terminado tu tarea regresa con Tirion Vadín.", description = "Si vas a quedarte aquí, solo te pido que te ganes tu sustento. Tenemos muchos problemas que podrían necesitar algo de \"disciplina\".\n\nPuedes empezar con los canes de peste y sus cachorros.\n\nNo puedo darte mucho a cambio, pero si tienes éxito no te faltará la comida caliente y algo de conversación.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5543] = {title = "Cielos sangrientos", objective = "Mata 30 murcipestes y vuelve con Tirion Vadín.", description = "Ay de los que se adentran en las Tierras de la Peste. Todo tipo de inmundicia habita esos bosques, desde la fanática Cruzada Escarlata, que mata a todo el que no porta la marca de la Cruzada, hasta la Plaga asesina, que solo quiere aumentar su número sumando nuevos no-muertos a sus filas.\n\nHasta la naturaleza se ha transformado en bestias feroces, devoradoras de hombres. Te pido que destruyas a aquellos que golpean desde las alturas: los murcípestes.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5544] = {title = "Gusanos carroñeros", objective = "Busca las larvas y devoradores carroñeros de la zona. Mátalos y recoge su carne. Regresa con Tirion Vadín cuando tengas 15 trozos de carne de gusano carroñero.|n", description = "Mis suministros de comida se están agotando, <raza>. Me avergüenza reconocer que no tengo bastante comida para compartir contigo.\n\n¿Podrías ayudar a un anciano con una sencilla misión? En los alrededores, la única bestia que no se ha visto afectada por los estragos de la peste es el gusano carroñero. Aunque tiene un sabor bastante soso, la carne de esos gusanos puede conservarse durante meses. ¡Necesitaré varios cientos de kilos para reponer las reservas para este invierno!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5545] = {title = "El cumplimiento del plazo", objective = "Lleva 8 fardos de madera a Raelen al Aserradero de la Vega del Este.", description = "Tengo un auténtico problema entre manos. Se acerca peligrosamente la fecha en la que tengo que entregar un pedido de madera... Los lobos y los osos que hay al norte de aquí ahuyentaron a mis trabajadores, que tuvieron que dejar atrás los fajos de madera que tenían talada.\n\nYa he hablado con el ayudante de alguacil Rainer sobre la necesidad de deshacernos de esos animales, pero necesito que alguien vaya a recoger la madera. Si pudieras recoger ocho fajos de madera, conseguiría cumplir el plazo.", progress = "Ese plazo se acerca cada vez más, <clase>. Te lo ruego, date prisa en recoger la madera.", completion = "¡Fantástico! Gracias a ti, debería poder cumplir con el plazo. Quisiera demostrarte mi agradecimiento dándote algunas monedas.\n\nGracias y adiós.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5561] = {title = "El rodeo kodo", objective = "Lleva 3 kodos domados y el kombobulador kodo a Smeed Mezclatornillos, al Campamento de los Mezclatornillos.", description = "Bibbly cree que es el único goblin de Desolace que sabe cómo ganar dinero. Pues bien, la única caravana que se atreve a viajar por estas partes depende de mí. Desde que aprendí a rejuvenecer y controlar a los kodos viejos y moribundos con mi kombobulador, Cork, que es el dueño de la caravana, Rigger y yo, formamos una sociedad.\n\nCoge el kombobulador y úsalo en cualquier kodo envejecido o anciano. Domesticará a la bestia y la obligará a seguirte. Cuando tengas un kodo domado, tráemelo.", progress = "La caravana llegará pronto. ¿Tienes los cinco kodos domados nuevos que necesito?", completion = "&lt;Smeed Mezclatornillos empieza a contar.&gt;\n\nTres, cuatro y cinco... Excelente. Pedí cinco kodos domados y cinco kodos domados tengo. Voy a ser rico, ¡muy, muy rico! ¡Qué ganas de ver la cara de Bibbly cuando se entere de mi éxito! ¡Se pondrá verde!", rewards = "Botas de cuatrero kodoBufas de riñaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][5581] = {title = "Los portales de la Legión", objective = "Destruye 6 Portales en el Aquelarre Mannoroc y vuelve al Campamento del Espíritu Errante a hablar con Felgur Doscortes.|n", description = "Aquí está: la Mano de Iruxos.\n\nSe la he arrebatado a uno de los líderes del Filo Ardiente yo mismo.\n\nSi queremos erradicar los portales demoníacos del Aquelarre Mannoroc, debes portarla. Y es precisamente lo que te pido que hagas.\n\nCon una amenaza demoniaca creciente, debemos cerrar esos portales para impedir que entren más demonios en este mundo.\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Bastón vinculanteBrazales de portalesBufas de estampaRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][5601] = {title = "Pamela, mi hermana", objective = "Encuentra a Pamela Rutagrana en Villa Darrow.", description = "Huí de Lordaeron durante la Gran Guerra. Y tuve suerte, pues escapé poco antes de que la Plaga arrasara mi hogar y lo convirtiera en una pesadilla apestada. Yo tuve suerte, pero mi familia no. Temo que fueran asesinados en la Batalla de Villa Darrow.\n\nVilla Darrow es una aldea de los Reinos del Este que se encuentra emplazada en las colinas del sur, de lo que ahora son las Tierras de la Peste del Este. ¿Podrías ir allí y buscar a mi familia? Los echo tanto de menos a todos... sobre todo a mi hermana pequeña, Pamela.\n\n¡Te lo ruego! ¡Encuéntrala!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5627] = {title = "Estrellas de Elune", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][5641] = {title = "Sin miedo", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Aprenderás:\n\nResguardo de miedo"}
MultiLanguageQuestData['mx'][5647] = {title = "Sin miedo", objective = "Habla con el sumo sacerdote Rohan en Forjaz.", description = "Tu raza es muy fuerte, <nombre>. Nos enorgullece consideraros aliados. Y cada día que pasa se acercan más no solo a encontrar su auténtico origen, sino a obtener la certeza de que van por buen camino en muchas cosas. Eso debe de hacerte sentir exultante.\n\nAcaba de llegar un mensaje de Forjaz. Dice que debes volver y hablar con el sumo sacerdote Rohan en la Sala Mística. Yo no lo haría esperar. Que Elune guíe tus pasos.Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nResguardo de miedo\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][5648] = {title = "Prendas de espiritualidad", objective = "Encuentra a la bruta Kor'ja y cura sus heridas usando la Sanación inferior (Rango 2). Después, concédele Palabra de Poder: Entereza y vuelve a Cerrotajo a hablar con Tai'jin.", description = "Ya estás <preparado/preparada> para tu primera prueba, <nombre>. Una de nuestras brutas fue herida en combate por unas tropas de Valiente, al sur de Cerrotajo, nada más salir de la ciudad. No está muy bien y no le vendría mal que uno de nosotros acudiera en su ayuda. Encuéntrala. Se llama Kor'ja. Cura sus heridas y dale la bendición de nuestros antepasados.\n\nSi haces esto, consideraré que has demostrado que estás <listo/lista> para moverte en nuestra cultura.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nTogas de maleficio Juju"}
MultiLanguageQuestData['mx'][5650] = {title = "Las prendas de la Oscuridad", objective = "Encuentra al Guardia de la Muerte Kel y cura sus heridas utilizando un hechizo de Sanación inferior (Rango 2). A continuación, concédele la Palabra de poder: entereza, y después ve a ver de nuevo al clérigo oscuro Beryl a Rémol.", description = "Nuestro poder proviene de la oscuridad y la sombra, <nombre>, pero eso no es lo único que debes saber. Has reconocido la importancia de dominar las artes de curación, lo cual es muy sensato por tu parte. Pero para conocer la oscuridad, debes conocer también la luz. Con este fin, tengo una prueba preparada para ti.\n\nAl norte del cementerio hay un Guardia de la Muerte herido, el Guardia de la Muerte Kel. Él nos ha protegido de los gnolls durante un tiempo y ahora necesita que lo curen. Es más, también deberás fortalecer su cuerpo para que así pueda desempeñar de nuevo sus funciones. Utiliza tus hechizos para conseguir estos dos objetivos y después regresa aquí.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nTogas de sacrificio de acólito"}
MultiLanguageQuestData['mx'][5658] = {title = "Toque de debilidad", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][5679] = {title = "Peste devoradora", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Aprenderás:\n\nPeste devoradora"}
MultiLanguageQuestData['mx'][5680] = {title = "Guardia de las Sombras", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][5713] = {title = "Un disparo, una baja", objective = "Protege a la centinela Aynasha y luego ve a Vallefresno, a la Atalaya de Maestra, y habla con Onaeya.", description = "Viajaba a Lor'danel con un importante mensaje cuando fui atacada por el fúrbolg Marosh y sus rastreadores. Me envenenaron... apenas puedo permanecer en pie. Puedo preparar un antídoto, pero pasará algún tiempo antes de que esté listo.\n\nMe gustaría que me defendieras hasta que pueda tomar el antídoto. Yo te ayudaré con mi arco como mejor pueda.\n\nSi sobrevivimos, podré llevar mi mensaje a Lor'danel, mientras tú informas de este incidente a Onaeya, que está en la Atalaya de Maestra.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5721] = {title = "La Batalla de Villa Darrow", objective = "Coloca el fardo de reliquias en la plaza de Villa Darrow.\n\nImpide que Davil Fuegoluz muera antes que Horgus.\n\nImpide que el capitán Rutagrana muera hasta que aparezca Rutagrana el Corrompido.\n\nDerrota a Rutagrana el Corrompido.\n\nHabla con el espíritu de Joseph Rutagrana cuando aparezca en la Plaza de la Ciudad y luego habla con Pamela en su casa.", description = "Ahora, <nombre>, tomarás parte en la Batalla de Villa Darrow. Salvarás a Joseph Rutagrana.\n\nColoca este fardo de reliquias en la Plaza de la Ciudad de Villa Darrow. Así se alzarán los espíritus de Villa Darrow. Únete a ellos en su batalla y asegúrate de que ocurran estas dos cosas: Davil debe sobrevivir a la muerte de Horgus y Rutagrana debe vivir para ser corrompido y luego derrotado.\n\nDespués de derrotar al corrupto Rutagrana, su espíritu estará a salvo. Habla con él y luego vuelve con su hija Pamela.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nTé con azúcar"}
MultiLanguageQuestData['mx'][5722] = {title = "Buscando la cartera perdida", objective = "Inspecciona la Sima Ígnea en busca del cuerpo de Maur Tótem Siniestro y comprueba si porta algún objeto de interés.", description = "Los troggs no eran lo único que le interesaba a Magatha de la Sima Ígnea. Ella ha oído decir que uno de sus sirvientes, Maur Tótem Siniestro, encontró algo muy especial en la Sima pero que nunca consiguió salir con vida para enseñárselo. Le gustaría encontrar el cuerpo de Maur, si es que todavía queda algo de él, y cualquier indicio de lo que él había encontrado en su intento de hablar con los troggs.\n\nLlévale a Magatha cualquier objeto que pueda ser de su interés y seguro que te recompensará con generosidad.\n\nDe nuevo, busca la Sima en la zona más oscura de Orgrimmar.", progress = nil, completion = "El cuerpo presenta muchos golpes pero la ropa y el equipo están intactos. Parece que a los troggs no les interesa mucho la riqueza material.\n\nEmpiezas a inspeccionar el cuerpo en busca de algo que le pueda resultar de interés a Magatha.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5723] = {title = "Midiendo fuerzas con el enemigo", objective = "Localiza la Sima Ígnea en Orgrimmar y después mata a 8 troggs Furia Ardiente y 8 chamanes Furia Ardiente y después ve a ver de nuevo a Rahauro a Cima del Trueno.", description = "En la ciudad de Orgrimmar, robustas criaturas conocidas como troggs comenzaron a salir a la superficie desde las profundidades de los túneles llenos de lava. En su benevolencia, Magatha trató de negociar con las criaturas pero estas se echaron encima de sus diplomáticos y los mataron. No permitiría un trato semejante al pueblo tauren por lo que estas criaturas ahora son consideradas como una amenaza para todos los de la Horda.\n\nElla te pide que pongas fin a la amenaza de los troggs antes de que acaben con la Horda. Encuentra la Sima Ígnea y acaba con todos ellos.", progress = nil, completion = "Me alegro de que te hayas tomado en serio la tarea que te encomendó Magatha. Gracias, &lt;nombre&gt;. Seguro que los troggs no se recuperarán tan fácilmente después de haber sufrido tantas bajas.\n\nQuizás en un futuro tengamos tiempo de investigar de dónde proceden estas criaturas y cuál es su auténtico propósito.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5724] = {title = "La vuelta de la cartera perdida", objective = "Lleva la cartera de Tótem Siniestro hasta Rahauro, en Cima del Trueno.", description = "Encuentras una cartera bajo el cuerpo del tauren. Todavía está fuertemente aprisionada entre sus brazos como si la hubiera estado protegiendo mientras fue atacado por los troggs.\n\nCoges la cartera, la guardas con tu equipo y te dispones a salir de los túneles de vuelta a Rahauro en Cima del Trueno.", progress = "¿Encontraste algo, <nombre>? Nos vendría bien cualquier pista que ayude a explicar por qué un miembro de su clan ha tenido que morir innecesariamente.", completion = "Excelente, &lt;nombre&gt;. Gracias.\n\nMagatha me dijo que te entregara esto si encontrabas al miembro de su clan. Por favor, cógelo como muestra de agradecimiento.", rewards = "Brazales de cuentas emplumadasBrazales de sabanaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][5725] = {title = "Poder destructivo", objective = "Llévale los libros Hechizos de las Sombras y Encantamientos desde el infierno a Varimathras, que está en Entrañas.", description = "Muchos integrantes de la Legión ofrecen regalos a sus seguidores, como seguro que ya sabes. La Dama Oscura cree que muchos de estos regalos estarían mejor en su poder que en manos de esos... que no son tan avezados.\n\nUna secta del Consejo de la Sombra, oculta en las cavernas situadas bajo Orgrimmar y conocida como Hoja Abrasadora, es un excelente ejemplo. La Dama sabe que los miembros de la secta Hoja Abrasadora se han hecho con dos poderosos libros de hechizos que le gustaría \"tomar prestados\". Tú serás quien los consiga para ella.", progress = "Tengo muchas cosas de las que ocuparme, <clase>. ¿Tienes los libros?", completion = "Bien, &lt;clase&gt;. Has servido con eficacia a la Dama Oscura. Tu perseverancia y ambición serán de gran utilidad para ella. Ven a verme más adelante pues es posible que tenga otras tareas para ti con las que puedas ayudar a la Dama Oscura a derrotar al Rey Exánime y liberar totalmente a la Plaga.", rewards = "Calzas espantosasLeotardos de cenagalLeotardos gárgolaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][5726] = {title = "Enemigos ocultos", objective = "Lleva una insignia de Teniente a Thrall a Orgrimmar.", description = "No tolero a los traidores, <nombre>. Pero sería necio mostrar mis cartas demasiado pronto; no eliminaría la corrupción de nuestras tierras y la infestación sería aún peor.\n\nPero tú, joven errante, podrías ir hasta donde no llegaron mis agentes y averiguar la verdad.\n\nSi eres lo bastante valiente, ve a Roca del Cráneo, al este de Orgrimmar, consigue una insignia de Teniente de Filo Ardiente y tráemela.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5727] = {title = "Enemigos ocultos", objective = "Lleva la insignia de Teniente a Neeru Hojafuego. Averigua si cree que eres miembro de Filo Ardiente; luego ve a ver a Thrall a Orgrimmar.", description = "Veamos si la insignia vale la pena el esfuerzo.\n\nEn la ciudad hay un brujo que cree que aún confío en él. No sabe que he descubierto su traición: es el jefe de Filo Ardiente. Pero no te enfrentes con él ahora; podemos usarlo contra nuestros enemigos.\n\nLlévale esta insignia; está en el Circo de las Sombras, aquí en Orgrimmar. Vuelve después de hablar con él y dime si ha creído que eras de los suyos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5728] = {title = "Enemigos ocultos", objective = "Mata a Bazzalan y a Jergosh el Convocador y ve a ver a Thrall a Orgrimmar.", description = "Así que jefes de Hoja Abrasadora, ¿eh? Interesante... Si son los más cercanos a Neeru, tienen que ser nuestro primer objetivo. El sátiro Bazzalan y el otro que mencionó Neeru, creo que era un brujo, deben ser eliminados.\n\n<nombre>, vuelve al Circo de las Sombras y entra en la Sima Ígnea. Liquida al sátiro y al brujo, pero que Neeru no se entere de que has sido tú. Tiene que seguir creyendo que eres de <los suyos/las suyas>.", progress = nil, completion = "Me alegro de verte, &lt;nombre&gt;. Al parecer, ahora que los líderes han muerto reina el caos en las cavernas de Orgrimmar. He oído decir que Neeru estaba muy agitado; hemos hecho diana. Aunque la victoria sea pírrica, es una victoria.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5729] = {title = "Enemigos ocultos", objective = "Habla con Neeru Hojafuego en Orgrimmar.", description = "Ahora deberíamos situarte cerca de Neeru. Si está tan inquieto como dicen, podemos conseguir dos cosas: que averigües más cosas sobre el Consejo y Filo Ardiente y que empiece a confiar en ti y te pida ayuda. La necesitará ahora que hay agitación en la cúpula dirigente.\n\nVe otra vez a la Grieta a hablar con él, pero sé sutil.", progress = nil, completion = "¿Qué quieres? Oh, &lt;clase&gt;, disculpa. Estoy furioso como un kodo con dolor de muelas, pero es culpa mía. Debí prever las consecuencias de enviar a gente a la Sima Ígnea. Parece que Bazzalan y Jergosh fueron asesinados por algún enviado de Thrall. Qué inoportuno, pero ya no se puede hacer nada.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5730] = {title = "Enemigos ocultos", objective = "Habla con Thrall en Orgrimmar y cuéntale lo que has averiguado.", description = "Eres <uno/una> de mis generales. Prepárate, <clase>; pronto pasarás a la acción.\n\nAl parecer he perdido el tiempo con Hoja Abrasadora, pero no por eso tienen que alterarse los demás planes del Consejo de la Sombra. Haré lo que pueda para paliar los daños en la Sima Ígnea; mientras tanto, mis agentes se pondrán a trabajar en nuestro nuevo proyecto en Los Baldíos y Vallefresno. Regresa pronto.", progress = nil, completion = "¿Vallefresno? Mmm... No sabía que Filo Ardiente estuviera en Vallefresno. Mis espías se encargarán. Buen trabajo, &lt;nombre&gt;.\n\nAhora descansa y dedícate a otras tareas; te llamaré pronto.\n\nLok-Tar Ogar", rewards = "Hacha de OrgrimmarKris de OrgrimmarBastón de OrgrimmarMartillo de OrgrimmarRecibirás:\n\n"}
MultiLanguageQuestData['mx'][5741] = {title = "El Cetro de Luz", objective = "Consigue el Cetro de Luz y llévaselo a Azore Aldamort a la torre de Ethel Rethor.|n", description = "Se rumorea que el Filo Ardiente, que está en la Fortaleza del Hacha de Trueno, al este, se ha hecho con el Cetro de Luz de los nagas. La leyenda cuenta que ese cetro puede hundir ciudades enteras bajo los mares. El Filo Ardiente no debe poseer tal poder.\n\nY con el fin de privarles de él, debes arrebatarles ese cetro. Está en manos de un vidente del Filo Ardiente, que estudia el cetro en la parte superior de una de las atalayas del Hacha de Trueno.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5761] = {title = "Matar a la bestia", objective = "Ve a la Sima Ígnea, mata a Taragaman el Hambriento y llévale su corazón a Neeru Hojafuego a Orgrimmar.", description = "Mi trabajo principal consiste en erradicar a las criaturas responsables de la infestación demoníaca en nuestra maravillosa ciudad. Filo Ardiente es una amenaza, pero hay otras, como Hoja Abrasadora, que reside en la Sima Ígnea e intenta subvertir a miembros de la Horda en secreto.\n\nPara detenerlos debemos eliminar a su jefe, un guardia vil llamado Taragaman el Hambriento.\n\nMátalo y entrégale su corazón a Thrall; eso lo tranquilizará.", progress = "¿Has aniquilado ya a la bestia? Debía de ser el jefe de Hoja Abrasadora en la Sima Ígnea.", completion = "¡Magnífico! Thrall estará encantado.\n\nVoy a poner el corazón a buen recaudo.\n\nDe momento, celebra tu victoria; yo voy a comunicársela a Thrall.\n\nGracias, &lt;clase&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5762] = {title = "Hemet Nesingwary Jr.", objective = "Lleva el cajón de Kravel a Hemet Nesingwary Jr. a Tuercespina.", description = "Tengo un paquete para un cliente nuevo, un enano que se llama Hemet Nesingwary Jr.. El paquete ha tardado semanas en llegar y Hemet ya se ha ido. Dijo que se iba a Tuercespina a cazar y dejó el envío pagado para que se lo enviase allí.\n\nEs muy rico; siempre viene bien tenerlos contentos, ¿verdad? Bueno, ¿quieres ir a entregar el paquete?\n\nHe oído que el campamento está en Tuercespina, al norte de Grom'gol.", progress = "¿Lo que tienes en el cuello es polvo del desierto...?\n\nMmm... si mi olfato no me engaña, no se trata de polvo... ¡sino de sal! Has estado en El Desierto de Sal, ¿no es así?", completion = "¡Estupendo, el paquete de Karbarbán! Gracias, &lt;nombre&gt;. En esta caja hay munición especial, la favorita de mi padre, que nos irá muy bien en la jungla.\n\nAquí tienes tu paga. Y dime, ¿cómo está el viejo Kravel? Haciendo de las suyas, seguro...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5763] = {title = "La caza en Tuercespina", objective = "Lleva el cuerno de kodo de Roon a Hemet Nesingwary Jr. a Tuercespina.", description = "Hace mucho tiempo, vino un enano llamado Hemet para cazar bestias grandes. Tenía una habilidad extraordinaria con el rifle y pasamos muchos días cazando juntos; incluso olvidamos la enemistad entre nuestros pueblos.\n\nCuando se fue a Tuercespina juré que volvería a acogerle. Ahora caza en tierras desconocidas, pero su hijo ha ocupado su lugar.\n\nVe a ofrecer este cuerno de kodo a Hemet Jr.; lo encontrarás en Tuercespina, al norte del Campamento Grom'gol.", progress = "Siéntate, <clase>. No tardarás en volver a la jungla.", completion = "Ah, este cuerno es de un tauren, Roon Ferocrín. Mi padre siempre hablaba de los buenos ratos que pasaron cazando juntos en Desolace. Así que Roon me invita a unirme a él.\n\nAhora mismo estamos muy ocupados en la jungla, pero gracias, &lt;nombre&gt;. A lo mejor mi próxima expedición me lleva a Desolace, la tierra de los centauros.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5801] = {title = "La forja del Penacho en Llamas", objective = "Lleva el molde para llave esqueleto y 2 barras de torio a la cima de la Cresta del Penacho en Llamas en el Cráter de Un'Goro. Utiliza el molde para llave esqueleto en el lago de lava para forjar la llave esqueleto sin terminar.\n\nLlévale la llave esqueleto sin terminar al alquimista Arbington al Alto del Orvallo, en las Tierras de la Peste del Oeste.", description = "Necesitas dos barras de torio y una poderosa fuente de calor para forjar la llave. Con el torio no puedo ayudarte pero sí con la fuente de calor.\n\nAl oeste en el Cráter de Un'Goro se encuentra la Cresta del Penacho en Llamas, un volcán en activo. El lago de lava de su cima está lo suficientemente caliente como para derretir el torio. Con el molde que has adquirido, lo único que tendrás que hacer es sumergirlo en el lago de la cima y la lava se encargará del resto.\n\nEso es todo lo que puedo decirte. Para acabar tu llave, tendrás que hablar de nuevo con Arbington.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5802] = {title = "La forja del Penacho en Llamas", objective = "Lleva el molde para llave esqueleto y 2 barras de torio a la cima de la Cresta del Penacho en Llamas en el Cráter de Un'Goro. Utiliza el molde para llave esqueleto en el lago de lava para forjar la llave esqueleto sin terminar.\n\nLlévale la llave esqueleto sin terminar al boticario Dithers a El Baluarte, en las Tierras de la Peste del Oeste.", description = "Necesitas dos barras de torio y una poderosa fuente de calor para forjar la llave. Con el torio no puedo ayudarte pero sí con la fuente de calor.\n\nAl oeste en el Cráter de Un'Goro se encuentra la Cresta del Penacho en Llamas, un volcán en activo. El lago de lava de su cima está lo suficientemente caliente como para derretir el torio. Con el molde que has adquirido, lo único que tendrás que hacer es sumergirlo en el lago de la cima y la lava se encargará del resto.\n\nEso es todo lo que puedo decirte. Para acabar tu llave, tendrás que hablar de nuevo con Dithers.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5803] = {title = "El escarabeo de Araj", objective = "Destruye a Araj el Invocador y lleva el Escarabeo de Araj al alquimista Arbington en el Alto del Orvallo, en las Tierras de la Peste del Oeste.", description = "Araj el Invocador gobierna Andorhal desde el corazón de la ciudad en ruinas. Sabemos que fue el antiguo líder de Scholomance antes de reclamar para sí la ciudad. Para terminar la llave necesitaremos su sello, el llamado escarabeo, que montaremos como la cabeza de la llave.\n\nDirígete al corazón de Andorhal, y acaba con su control sobre la ciudad ahora que ha sido llevado al exterior. ¡Cuando lo hayas destruido arranca el escarabeo de su filacteria!\n\n¡Te aguarda la llave de acceso a Scholomance, <nombre>!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5804] = {title = "El escarabeo de Araj", objective = "Destruye a Araj el Invocador y lleva el Escarabeo de Araj al boticario Dithers en El Baluarte, en las Tierras de la Peste del Oeste.", description = "Araj el Invocador gobierna Andorhal desde el corazón de la ciudad en ruinas. Sabemos que fue el antiguo líder de Scholomance antes de reclamar para sí la ciudad. Para terminar la llave necesitaremos su sello, el llamado escarabeo, que montaremos como la cabeza de la llave.\n\nDirígete al corazón de Andorhal, y acaba con su control sobre la ciudad ahora que ha sido llevado al exterior. ¡Cuando lo hayas destruido arranca el escarabeo de su filacteria!\n\n¡Te aguarda la llave de acceso a Scholomance, <nombre>!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5821] = {title = "Guardaespaldas de alquiler", objective = "Escolta la caravana Gizelton a través del poblado de los centauros Kolkar. Habla con Smeed en el Campamento de los Mezclatornillos para recibir tu recompensa.", description = "En circunstancias normales, Rigger y yo guiaríamos a nuestros kodos más allá del Poblado Kolkar. De vez en cuando oímos los tambores de guerra centauros y entonces, nos detenemos. ¡No sería bueno para el negocio que nos mataran!\n\nTe propongo una cosa, <clase>: si nos proteges para atravesar el Poblado Kolkar, haremos que te merezca la pena.\n\nNo es un tramo muy largo. Y lo único que tendrías que hacer es conseguir que la caravana pase intacta. Luego podrás seguir el camino y pedir tu recompensa a Smeed Mezclatornillos. Hacemos negocios juntos.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAnillo de comerciante"}
MultiLanguageQuestData['mx'][5841] = {title = "¡Te damos la bienvenida!", objective = "Lleva el vale regalo de Kharanos a Yori Yelmopartido en Kharanos.", description = "¡<Bienvenido/Bienvenida> a World of Warcraft!\n\nAcepta este vale regalo como agradecimiento especial por haber comprado la Edición de Coleccionista de World of Warcraft y entrégaselo a Yori Yelmopartido en Kharanos. Te dará un regalo: un pequeño compañero que se unirá a ti en tu aventura en pos de la gloria.\n\n¡Gracias otra vez! ¡Y disfruta de tu estancia en World of Warcraft!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nCorrea ZergueznoCollera de pandaPiedra de diablo"}
MultiLanguageQuestData['mx'][5843] = {title = "¡Te damos la bienvenida!", objective = "Lleva el vale regalo de Cerrotajo a Magga en Cerrotajo.", description = "¡<Bienvenido/Bienvenida> a World of Warcraft!\n\nComo agradecimiento por la adquisición de la edición de coleccionista de World of Warcraft, entrega este vale regalo a Magga, en Cerrotajo. Te dará un regalo: un pequeño compañero que se unirá a ti en tu búsqueda de gloria y aventuras.\n\n¡Gracias de nuevo y disfruta de tu estancia en World of Warcraft!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nCorrea ZergueznoCollera de pandaPiedra de diablo"}
MultiLanguageQuestData['mx'][5844] = {title = "¡Te damos la bienvenida!", objective = "Lleva el vale regalo del Poblado Pezuña de Sangre a Vorn Vidente del Cielo en el Poblado Pezuña de Sangre.", description = "¡Bienvenido a World of Warcraft! \n\nComo agradecimiento especial por haber comprado la Edición de coleccionista de World of Warcraft, entrega este vale a Vom Vidente del Cielo, que está en el Poblado Pezuña de Sangre. Conseguirás un regalo: Un pequeño compañero que te acompañará en tu búsqueda de aventuras y gloria. \n\n¡Gracias de nuevo, y que disfrutes con World of Warcraft!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nCorrea ZergueznoCollera de pandaPiedra de diablo"}
MultiLanguageQuestData['mx'][5847] = {title = "¡Te damos la bienvenida!", objective = "Lleva el vale regalo de Rémol a Claire Willower en Rémol.", description = "¡<Bienvenido/Bienvenida> a World of Warcraft!\n\nAcepta este vale regalo como agradecimiento especial por haber comprado la Edición de Coleccionista de World of Warcraft y entrégaselo a Claire Willower en Rémol. Te dará un regalo: un pequeño compañero que se unirá a ti en tu búsqueda de aventuras y gloria.\n\n¡Gracias otra vez! ¡Y disfruta de tu estancia en World of Warcraft!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nCorrea ZergueznoCollera de pandaPiedra de diablo"}
MultiLanguageQuestData['mx'][5848] = {title = "Del amor y la familia", objective = "Viaja a Stratholme, en la zona norte de las Tierras de la Peste. En El Bastión Escarlata encontrarás el cuadro 'Del amor y la familia', oculto tras otra pintura que representa las lunas gemelas de nuestro mundo.\n\nDevuelve la pintura a Tirion Vadín.", description = "El cuadro... estuvo colgado en la pared de mi estudio (en los cuarteles de la Orden) durante años.\n\nCuando terminó el juicio de Tirion, supe que no podía seguir teniendo el cuadro a la vista. Lo oculté en un lugar en el que nunca lo buscarían.\n\nViaja a Stratholme, ábrete camino hacia las profundidades de lo que hoy se conoce como El Bastión Escarlata y busca un cuadro de nuestras lunas gemelas. Desprende la pintura hasta que descubras mi obra maestra, \"Del amor y la familia\".\n\nQue la Luz guíe tus actos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5863] = {title = "La Base Machacaduna", objective = "Andi Lynn de Gadgetzan quiere que destruyas la Base Machacaduna y para conseguirlo tendrás que matar 10 toscos Machacadunas, 10 déspotas Machacadunas y a Gor'marok el Devastador.", description = "No hace mucho, un numeroso grupo de ogros nómadas llegó a Tanaris. Al sur de aquí, se apoderaron de una extensa área del desierto donde decidieron instalarse. Otros grupos más pequeños vagan actualmente por el desierto, incluyendo algunos de los que invadieron las viejas ruinas trol.\n\n¡La Base Machacaduna debe ser destruida! No podemos permitir que esos ogros se hagan fuertes.\n\nEl jefe del grupo se llama Gor'marok el Devastador y creo que acabar con él significaría el comienzo del fin de los ogros.", progress = nil, completion = "¡Me alegro de que hayas podido hacer esto por mí, &lt;nombre&gt;! ¡Gracias por tu ayuda!", rewards = "Guantes de semilla marchitaManto de Madera BastaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][5881] = {title = "La sustitución", objective = "Maggran quiere que le entregues una carta a Grish Largo Camino en El Gran Elevador, en Los Baldíos.", description = "La Horda hace bien manteniendo a nuestras tropas frescas... Desde la Gran Guerra, hemos disfrutado de una gran prosperidad aquí, en Kalimdor.\n\nNecesito que me hagas un favor. Hay un tipo, Grish Largo Camino, que protege El Gran Elevador, en Los Baldíos del Sur. Entrégale esta carta. La carta le informará de que un guerrero de reserva va de camino para relevarle, así podrá ir a visitar a su familia. Lo solicitó hace bastante tiempo y estará encantado de conocer las buenas noticias.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5882] = {title = "Bálsamo por caza", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nBálsamo de planta Cenarion"}
MultiLanguageQuestData['mx'][5887] = {title = "Bálsamo por caza", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nBálsamo de planta Cenarion"}
MultiLanguageQuestData['mx'][5892] = {title = "Suministros de Ferrohondo", objective = "Lleva 10 suministros de Ferrohondo al intendente de la Alianza en Dun Baldar.", description = "Antes de que empezara el combate, almacenamos suministros para Dun Baldar en Mina Ferrohondo. Los troggs que emergieron no fueron un gran problema cuando teníamos soldados de sobras para vigilar la mina, pero ahora que estamos en guerra contra la Horda, resulta más difícil mantener el control sobre Ferro Hondo.\n\nNecesitamos los suministros de Ferro Hondo, <nombre>. Penetra en la mina y tráeme una buena carga.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5893] = {title = "Suministros de Dentefrío", objective = "Lleva 10 suministros de Dentefrío al intendente de la Horda en el Bastión Lobo Gélido.", description = "Mina Dentefrío, al norte, era otrora un lugar ideal para guardar suministros pero ahora que recrudecen las hostilidades con los Pico Tormenta, no siempre tenemos guerreros de sobra para dejarlos apostados en la mina y protegerla. De ahí que el control de la mina con frecuencia caiga en manos de la Alianza o de habitantes del subsuelo...\n\n¡Pero aún necesitamos nuestros suministros, <nombre>! Ve a Mina Dentefrío y tráeme una carga de suministros. Y ten cuidado con los enemigos; las mareas de la batalla cambian rápidamente en ese lugar...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5901] = {title = "Una Peste en la Cruzada", objective = "Utiliza el tarro de termitas vacío en los montones de termitas de las Tierras de la Peste del Este. Cuando hayas reunido 100 termitas de las Tierras de la Peste, vuelve con Mickey Levine, que está en El Baluarte, en Claros de Tirisfal.", description = "Quiero causar dolor a la Cruzada Escarlata. Quiero hacer un estrago y arrebatarles su preciada Serrería. Sé que la pérdida de un recurso tan vital menoscabará la defensa y reconstrucción de su ciudad. ¿Me ayudarás, <nombre>?\n\nEmpieza por llevar este tarro al Bosque de la Peste que está en las Tierras de la Peste del Este. Llénalo con las termitas que encontrarás en cualquiera de los nidos que hay por todo el bosque. Vuelve cuando tengas suficientes.", progress = "¿Tienes ya las termitas, <nombre>? Seguro que una <clase> tan inteligente como tú ya lo ha deducido.\n\nCuando tengamos suficientes termitas, ¡nos aseguremos de que nadie pueda usar la Serrería nunca más!", completion = "Gracias, &lt;nombre&gt;. Estas nos servirán.\n\nSi estás lista, podemos pasar a la fase siguiente.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5902] = {title = "Una Peste en la Cruzada", objective = "Encuentra un lugar adecuado en el centro del Aserradero Crestanorte, en las Tierras de la Peste del Oeste, para colocar la barrica de termitas de las Tierras de la Peste.\n\nObjeto provisto: \n", description = "Ahora que tenemos las termitas, lleva esta barrica de acero reforzado al Aserradero Crestanorte, al sur de la Vega del Amparo. Lo encontrarás al oeste de la carretera que lleva a la ciudad.\n\nUna vez allí, coloca la barrica en el centro del aserradero. Busca un lugar adecuado, como una caja, y abre la barrica.\n\nAhí acaba tu parte, lo demás ocurrirá solo. Solo te quedará volver aquí y recoger la recompensa que te daré por tu ayuda.", progress = nil, completion = "Notas que las termitas empiezan a inquietarse cuando colocas el barril sobre la caja.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5903] = {title = "Una Peste en la Cruzada", objective = "Utiliza el tarro de termitas vacío en los montones de termitas de las Tierras de la Peste del Este. Cuando hayas reunido 100 termitas de las Tierras de la Peste, vuelve con Nathaniel Dumah al Campamento del Orvallo en las Tierras de la Peste del Oeste.", description = "He intentado muchas veces derrotar a la Cruzada Escarlata usando la fuerza, pero sin resultado. Así que, como alternativa, he decidido hacerles la vida un poco más difícil.\n\nPor si te apetece ayudar, mi plan es infestar esa serrería con la especie de termitas más virulenta que he conseguido encontrar.\n\nEn el Bosque de la Peste, cerca de la que fuera la gran Stratholme, hay una variedad que ha sobrevivido tanto a la Peste como a la Plaga. Busca sus nidos y llena este tarro con ellas. Luego las prepararemos para lanzarlas contra la Cruzada.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5922] = {title = "Claro de la Luna", objective = "Utiliza el hechizo \"Teletransporte: Claro de la Luna\" para viajar a Claro de la Luna. Cuando llegues, ve al poblado Amparo de la Noche y habla con Dendrita Rafagaestelar.", description = "En las sagradas tierras de Claro de la Luna todos los druidas son bienvenidos, al igual que los tauren y los elfos de la noche. El guardián Remulos de Claro de la Luna sigue custodiando a los druidas que hibernan allí. Ahora que estás aprendiendo el camino de la zarpa, te enseñaré el hechizo que te permite teletransportarte allí. Utilízalo cuando busques el conocimiento o el consuelo del Claro de la Luna.\n\nComo primera lección, ve a Claro de la Luna. Busca a Dendrita Rafagaestelar en Amparo de la Noche y háblale del camino que recorres. Buena suerte, joven druida.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5926] = {title = "Escucha la llamada", objective = "Habla con Turak Tótem de Runa en Alto de los Ancestros, en Cima del Trueno.", description = "Oye, perdona...\n\nHe sabido que Turak Tótem de Runa quiere hablar contigo. Por lo visto, tu instrucción de druida va a dar un giro, porque te va a entrenar él personalmente. Turak es uno de los ayudantes del archidruida; es sabio y paciente, te enseñará bien.\n\nEstá en Cima del Trueno, dentro de la carpa principal del Círculo Cenarion en el Alto de los Ancestros.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5927] = {title = "Escucha la llamada", objective = "Habla con Turak Tótem de Runa en Alto de los Ancestros, en Cima del Trueno.", description = "Oye, perdona...\n\nHe sabido que Turak Tótem de Runa quiere hablar contigo. Por lo visto, tu instrucción de druida va a dar un giro, porque te va a entrenar él personalmente. Turak es uno de los ayudantes del archidruida; es sabio y paciente, te enseñará bien.\n\nEstá en Cima del Trueno, dentro de la carpa principal del Círculo Cenarion en el Alto de los Ancestros.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5928] = {title = "Escucha la llamada", objective = "Habla con Turak Tótem de Runa en Alto de los Ancestros, en Cima del Trueno.", description = "Oye, perdona...\n\nHe sabido que Turak Tótem de Runa quiere hablar contigo. Por lo visto, tu instrucción de druida va a dar un giro, porque te va a entrenar él personalmente. Turak es uno de los ayudantes del archidruida; es sabio y paciente, te enseñará bien.\n\nEstá en Cima del Trueno, dentro de la carpa principal del Círculo Cenarion en el Alto de los Ancestros.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5932] = {title = "Vuelve a Cima del Trueno", objective = "Vuelve a Cima del Trueno para hablar con Turak Tótem de Runa en Alto de los Ancestros.", description = "Ha llegado el momento de separarnos, puesto que para poner en práctica lo que has aprendido debes volver a quien te envió a mí. Aunque se dice que los tauren son inexpertos en la sabiduría de Cenarius, Turak Tótem de Runa vive en armonía con la naturaleza. Escúchalo bien y pronto habrá terminado tu preparación como <protector/protectora> del equilibrio.\n\nVete, joven. Volveremos a vernos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][5943] = {title = "La caravana Gizelton", objective = "Escolta la caravana Gizelton a través del Aquelarre Mannoroc. Habla con Smeed en el Campamento de los Mezclatornillos para recibir tu recompensa.", description = "Pareces muy competente, <raza>. ¿Quieres ganar algo de dinero? Cork y yo empezamos con esta caravana para ganar dinero... ¡cómo íbamos a imaginar los peligros que tendríamos que afrontar!\n\nMás adelante está el Aquelarre Mannoroc. Normalmente los demonios nos ignoran pero... algo tiene a los kodos muy agitados últimamente. Te pagaré para que protejas la caravana mientras atravesamos el Aquelarre Mannoroc. Una vez estemos a salvo al otro lado, podrás pedir tu recompensa a nuestro socio Smeed. Está en el Campamento de los Mezclatornillos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Pistolero ShottieMarcador de kodosEscudo circular con tachuelasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][5961] = {title = "Campeón de la Reina alma en pena", objective = "Habla con Nathanos Clamañublo en las Tierras de la Peste del Este. Se dice que ahora vive en la Hacienda de Marris.|n", description = "Me complace comprobar que <el experto/la experta> en batallas se une a nuestra causa. Cada día que pasa, somos más numerosos y fuertes. ¿Te sientes <preparado/preparada> para poner a prueba tu temple, <clase>?\n\nEntre mis mejores hombres estaba Nathanos, ahora conocido como el Clamañublo. Pocos hay en nuestras filas con semejante dedicación y vigor.\n\nBúscalo en las Tierras de la Peste del Este. Reside en la Hacienda de Marris y, de cuando en cuando, vaga por las diezmadas inmensidades matando a todo miembro de la Plaga o la Alianza que se cruza en su camino.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6002] = {title = "Cuerpo y corazón", objective = "Aplica el polvo de luna Cenarion a la piedra de lechúcico lunar que se encuentra entre Mulgore y Los Baldíos para provocar a Garraluna. Hecho esto, has de enfrentarte a Garraluna para obtener la fuerza física y de corazón que posee.\n\nHabla con Turak Tótem de Runa en Cima del Trueno cuando hayas acabado.", description = "Al oeste de Taurajo en Los Baldíos, justo antes de Mulgore, yace una piedra de lechúcico lunar. Los lechúcicos lunares son criaturas muy especiales no nativas de estas tierras. Garraluna, el guardián de la piedra, se enfrentará a ti cuando le apliques a la piedra polvo de luna Cenarion. Garraluna posee una fuerza que debes usar como miembro de la zarpa.\n\nTe has ganado el derecho a usar este polvo de luna Cenarion, <nombre>... ¡Ahora demuéstrame que también te has ganado el derecho a poseer la fuerza física y de corazón que necesitas como druida!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6004] = {title = "Negocios inconclusos", objective = "Mata a 2 médicos Escarlata, 2 cazadores Escarlata, 2 magos Escarlata y 2 caballeros Escarlata antes de regresar con Kirsta Sombraprofunda en las Tierras de la Peste del Oeste.", description = "Fui enviada como exploradora para dañar y calibrar la fuerza de las defensas de la Vega del Amparo. Algunos miembros de la Alianza tenían la sensación de que la pequeña ciudad tenía algo más que importancia histórica. Mi trabajo no consiste en preguntarme cuál pueda ser esa importancia pero no estoy en condiciones de seguir adelante hasta que descanse.\n\nSi lo deseas, pagaría generosamente tu ayuda. Comienza al sur de aquí, en un campamento cercano al pequeño baluarte que han levantado. Si demuestras ser lo suficientemente fuerte, tal vez pueda unir tu ayuda con mi objetivo principal.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6021] = {title = "Zaeldarr el Marginado", objective = "Lleva la cabeza de Zaeldarr al custodio Alen a la Capilla de la Esperanza de la Luz.", description = "¿No te parece increíble? Con todos los problemas que tenemos en las Tierras de la Peste... ¡ahora resulta que nos toca ocuparnos también de los ladrones! Y no de ladrones normales, no, ¡ladrones trols!\n\nY tampoco son ladrones trols convencionales... ¡¡Son ladrones trols muertos!!\n\nSu líder es un enorme trol muerto llamado Zaeldarr el Marginado. Vienen de noche, roban los cuerpos del foso de abajo y se los llevan a su maldita madriguera de trols muertos: La Subgranja del oeste.\n\nVe allí y elimina a Zaeldarr, <nombre>. ¡Me he hartado de sus fechorías!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6022] = {title = "Matar con un propósito", objective = "Viaja al Cruce de Corin al este y mata a los miembros de la Plaga que habitan allí. Recoge 7 piezas de putrefacción viva en 10 minutos. Utiliza el mortero y el majadero para convertir la putrefacción viva en putrefacción coagulada.", description = "Mientras trabajes para mí, matarás con un propósito concreto.\n\nTu primera misión es alimentar a mis canes.\n\nCoge este mortero y este majadero y viaja al Cruce de Corin. Allí encontrarás una nutrida selección de miembros de la Plaga que matar. Necesito putrefacción viva de sus cadáveres frescos. Coge esa putrefacción y colócala en el mortero. Deja que repose y se coagule. Y luego, tráeme esa putrefacción coagulada.\n\nY recuerda que esa putrefacción viva de los no-muertos, no dura \"viva\" mucho tiempo. ¡Debes matar con rapidez!", progress = "¿Estás llorando? Si esto te resulta demasiado tedioso, \"heroína\", te aconsejo que vayas a buscar a la Dama Oscura y le llores a ella. Cuéntale cómo te he maltratado.\n\n¡Y ahora fuera de mi vista!", completion = "Decepcionante. Esperaba tener que usarte a ti para alimentar a mis canes.\n\n&lt;Nathanos suspira.&gt;\n\nBueno, al menos tienen algo que comer.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6024] = {title = "La súplica de Hameya", objective = "Mata al infiltrador Hameya. Usa su llave en el túmulo detrás de La Subgranja.", description = "Mátame. Antes de que sea demasiado tarde.\n\nMe llamo Hameya. Cuando viajábamos hacia Zul'Mashar, mis hermanos y yo comimos carne en mal estado y... cambiamos. Estamos infestados.\n\nAhora puedo oír las palabras del Rey Exánime, instándome a llegar a Zul'Mashar a infectar a mi gente. Sé que no podré resistir mucho... por eso escribí el pergamino... antes de que mi voluntad me abandonara.\n\nEnterré un cofre cerca de un carro que hay detrás de esta cripta, pero solo se abrirá con mi llave. Y yo tengo la llave. Si quieres mi tesoro, tendrás que encontrarme a mí.\n\nMátame... antes de que sea demasiado tarde.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDestripador de HameyaCapa de Hameya"}
MultiLanguageQuestData['mx'][6025] = {title = "Negocios inconclusos", objective = "Entra en la Vega del Amparo y busca un punto elevado desde el que puedas ver la ciudad y calcular las fuerzas de la Cruzada Escarlata. Cuando lo hayas hecho regresa con Kirsta Sombraprofunda en las Tierras de la Peste del Oeste.", description = "¿Qué? ¿De verdad? ¿Quieres saber más? Pero ya has hecho mucho por mí, <nombre>, no podría pedirte entrar en la Vega del Amparo en mi nombre.\n\n¿Estás <seguro/segura>, <nombre>? La Vega del Amparo es mucho más peligrosa que el Paso... no puedo darte ningún tipo de protección, ni siquiera información sobre lo que puedas encontrarte allí.\n\nBien, si de verdad quieres ayudar, entra en la ciudad y busca un lugar elevado para hacerte con una buena perspectiva de la ciudad. Desde allí podrás calcular su número, cuando lo hayas hecho vuelve a informarme. Pero ten cuidado...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6026] = {title = "Eso pide mucho", objective = "Smokey LaRue quiere que consigas 2 barras de torio, 1 vara dorada, 8 bombas de gran carga y 8 disparadores inestables.\n\nTendrás que encontrar a un herrero y a un ingeniero para conseguir esos objetos.", description = "Unos tipos de El Alba Argenta encargaron al viejo Smokey un pequeño trabajo de demolición. Y la mamá de Smokey no crió a un tonto. Si hay monedas de oro sobre la mesa, los servicios de Smokey están disponibles. ¡Ese es mi lema!\n\nEstaría dispuesto a compartir la comisión contigo si te apetece hacer un poco de trabajo de campo. Este es el trato: yo iré al Bosque de la Peste y marcaré los edificios que tenemos que destruir. Tú reúnes los componentes para las bombas. Y te reúnes aquí conmigo cuando tengas todo. ¿Trato hecho?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6027] = {title = "El Libro de los Ancestros", objective = "Consigue el Libro de los Ancestros y llévaselo a Azore Aldamort a la torre de Ethel Rethor.|n", description = "<nombre>, te confío la gema de la Serpiente. Coloca esta gema en la mano de la estatua de la Serpiente que está en una pequeña isla al noroeste de aquí, la Isla Ranazjar. Cuando la coloques, invocarás a quien protege el Libro de los Ancestros. Ese libro contiene los secretos de los nagas. Secretos que se han guardado durante siglos. Tráeme ese libro. ¡Aprenderemos mucho sobre nuestros escamosos enemigos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Puños corrientes de sedaSobrehombros ArcometalRecibirás:\n\n"}
MultiLanguageQuestData['mx'][6028] = {title = "El informe Vista Eterna", objective = "Entrega el informe de Vista Eterna a la oficial Argenta Purocorazón en el Campamento del Orvallo, en las Tierras de la Peste del Oeste.", description = "Estoy buscando a un individuo responsable que me ayude en una pequeña pero importante cuestión. Estoy aquí como representante de los intereses de El Alba Argenta en el gobierno local de Vista Eterna. Necesito hacer llegar un informe a la oficial Argenta Purocorazón, en el Campamento del Orvallo; está algo alejado de aquí, en el límite meridional de las Tierras de la Peste del Oeste.\n\nSi se me permite decirlo creo que sería una forma perfecta de presentarte a mi superiora, ¡e incluso puede que tenga algún trabajo para ti!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6029] = {title = "El informe Vista Eterna", objective = "Entrega el informe de Vista Eterna al oficial Argenta Garush en El Baluarte, en las Tierras de la Peste del Oeste.", description = "Estoy buscando a un individuo responsable que me ayude en una pequeña pero importante cuestión. Estoy aquí como representante de los intereses de El Alba Argenta en el gobierno local de Vista Eterna. Necesito hacer llegar un informe al oficial Argenta Garush en el Baluarte; está algo alejado de aquí, en el límite occidental de las Tierras de la Peste del Oeste, al este de los Claros de Tirisfal.\n\nSi se me permite decirlo creo que sería una forma perfecta de presentarte a mi superior, ¡e incluso puede que tenga algún trabajo para ti!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6030] = {title = "El duque Nicolas Zverenhoff", objective = "Entrega el libro, \"Estudios sobre la Comunicación con los Espíritus\", al duque Nicolas Zverenhoff en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Un solitario médium que habita esta región y que responde al nombre de Umbranse ha dado a El Alba Argenta una obra maestra de la literatura... posiblemente sea la mayor colección de verborrea que he visto escrita nunca.\n\nUno de los líderes más respetados de El Alba, el duque Nicolas Zverenhoff, es un destacado lingüista. ¿Podrías llevarle esto de mi parte? Por supuesto, a cambio de una recompensa. Podrás encontrarlo en la Capilla de la Esperanza de la Luz, en la parte oriental de las Tierras de la Peste del Este.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6031] = {title = "Paño rúnico", objective = "Llévale 30 paños rúnicos a Meilosh, que está en el Bastión Fauces de Madera.", description = "Estamos muy bien en el Bastión Fauces de Madera y no nos gustan los extraños. Esto es bueno para nosotros pero no para el comercio.\n\nNo hace mucho, una singular elfa de la noche vino al Bastión Fauces de Madera vistiendo una capa de paño rúnico. El paño rúnico no es algo muy común entre nosotros pero la capa le gustó tanto a mi gente que me pidieron que les hiciera más ropajes con paño rúnico.\n\n¿Me traerías paño rúnico? Si me traes bastante cantidad, te daré algo a cambio.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Bufas sombradermasGuanteletes de ladrillo de aceroRecibirás:\n\n"}
MultiLanguageQuestData['mx'][6032] = {title = "Tela sagrada", objective = "Llévale 2 retales de tela lunar a Meilosh, que está en el Bastión Fauces de Madera.", description = "A pesar de que a la gente de Fauces de Madera le encanta el paño rúnico, no es sagrado para nosotros. Sin embargo, la tela lunar sí lo es.\n\nConsígueme un poco de esta tela sagrada y te enseñaré una técnica de diseño secreta.Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nBotas de tela lunar\n\nTe van a lanzar el siguiente hechizo:\n\nBotas de tela lunar\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][6041] = {title = "Cuando Smokey canta, me pongo violento", objective = "Viaja al Bosque de la Peste, al noroeste de la Esperanza de la Luz. Destruye 8 estructuras de la Plaga utilizando el compuesto especial de Smokey en la marca de detonación que hay en el interior de cada edificio. Smokey ha hecho marcar los zigurats y los degolladeros.\n\nCuando plantes la bomba, sal del edificio y disfruta del espectáculo.\n\nPor cierto, el compuesto especial de Smokey es... bastante inestable.", description = "Mientras tú reunías los suministros, yo hice que mi gente marcara los edificios de la Plaga que debemos demoler.\n\nEste es el plan: voy a darte diez palos de mi compuesto especial. Tú los llevas al Bosque de la Peste y los plantas dentro de los edificios de la Plaga que he hecho marcar.\n\n<Smokey chasquea los dedos.>\n\n¡Y ya está! Es facilísimo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Lanzaexplosivos de SmokeyPistola de fuego de SmokeyRecibirás:\n\nToallita húmedaMantón de Smokey"}
MultiLanguageQuestData['mx'][6042] = {title = "Los pequeños problemas de la no-vida", objective = "Mata a 20 murcipestes tóxicos y 10 murcipestes monstruosos. Vuelve con Nathanos Clamañublo cuando hayas acabado.", description = "No se puede uno alejar dos pasos de la granja sin encontrarse con uno de esos repugnantes murciélagos. Quiero poder sacar a los canes y acabar con la Plaga sin que me molesten esos malditos y sucios murciélagos. Obviamente, tengo cosas mejores que hacer con mi tiempo que matar murciélagos un día sí y otro también. Pero tú no.\n\n¿Qué? ¿Tu entrenamiento? ¡Esto es tu entrenamiento! Ahora fuera de mi vista y no vuelvas hasta que no hayas matado a un buen número de esos demonios alados. Procura no decepcionarme.", progress = nil, completion = "Es increíble lo que se puede conseguir con un poquito de ira y mala leche.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6061] = {title = "Domesticar la bestia", objective = "Usa la fusta de doma para domar un zancudo de llanura adulto. Practica un poco y devuélvele la fusta a Yaw Crinafilada en el Poblado Pezuña de Sangre.", description = "Para los tauren es importante seguir la tradición ancestral de luchar contra criaturas poderosas. Al someterlas absorbemos su espíritu, lo que nos acerca a la Madre Tierra.\n\nDel mismo modo, domar a una bestia para que luche de nuestro lado es una forma de unirse a la naturaleza. Aprenderás a domar criaturas. Pero estas cosas requieren tiempo y práctica. Para empezar, usa esta fusta de doma para domar un zancudo de llanura adulto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6068] = {title = "El camino del cazador", objective = "Habla con Thotar en Cerrotajo, en Durotar.", description = "Hola, joven <cazador/cazadora>. Me estás mirando como si fueras capaz de domar a cualquier bestia y entrenarla para convertirla en tu compañera.\n\nDebes ir a ver a Thotar en Cerrotajo. Él puede guiarte para que consigas tu propia mascota.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6081] = {title = "Domesticar la bestia", objective = "Habla con Ormak Tirosiniestro en Orgrimmar.", description = "Ahora tienes el poder de domar una mascota, pero también debes adquirir las habilidades necesarias para entrenarla.\n\nViaja a Orgrimmar. Allí debes hablar con uno de nuestros más venerados cazadores, Ormak Tirosiniestro. Él te dará la habilidad de entrenar a tu mascota. Lo encontrarás cerca del Valle del Honor.\n\nBuena suerte, <nombre>.También recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "También recibirás:\n\n"}
MultiLanguageQuestData['mx'][6083] = {title = "Domesticar la bestia", objective = "Usa la fusta de doma para domar un reptador de espuma. Practica un poco y devuélvele la fusta de doma a Thotar en Cerrotajo.", description = "La ventaja que te concede una mascota frente a tus rivales es de sobra conocida, <nombre>. Cuando controlas a otra criatura, potencias tu propia fuerza. Tu mascota debe convertirse en una extensión de ti <mismo/misma>.\n\nTu siguiente cometido requiere que te alejes de la tierra: encontrarás a la siguiente criatura en las aguas de la costa. Cruza el Poblado Sen'jin, cerca de las Islas del Eco. Busca un reptador de espuma, un enérgico cangrejo. Utiliza la fusta para domarlo y luego practica tus habilidades.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6089] = {title = "Domesticar la bestia", objective = "Habla con Holt Tronacuerno en el Alto de los Cazadores, en Cima del Trueno.", description = "Ahora tienes la capacidad de domar a un animal, pero también necesitas la habilidad para amaestrarlo.\n\nVe a Cima del Trueno y habla con Holt Tronacuerno. Es uno de nuestros mejores cazadores. Te dará la habilidad de amaestrar a tu mascota si considera que la mereces.\n\nHa dominado a las bestias más feroces de Azeroth y tiene a varias criaturas a su mando. Vive en armonía con la Madre Tierra; aprenderás mucho de él. Suerte, <nombre>.\nTambién recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "También recibirás:\n\n"}
MultiLanguageQuestData['mx'][6122] = {title = "La fuente del envenenamiento", objective = "Recoge agua de Salto de Fonroca a la entrada de la cueva.\n\nEntrégale la muestra llena de Salto de Fonroca a Alanndarian Arrullanoche; en Auberdine, en Costa Oscura.", description = "Casi toda el agua potable de la región proviene de Salto de Fonroca, en Costa Oscura. Sospecho que allí está el foco del envenenamiento que afecta a los ciervos. Recoge agua de la boca de la cueva con este recipiente. Ten cuidado; en una cueva al lado de la cascada viven unos nagas muy peligrosos.\n\nLlévaselo a Alanndarian Arrullanoche; está en Auberdine. Fue ella quien nos pidió ayuda y trabajarás con ella para solucionar este problema.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6123] = {title = "Reunir los ingredientes del remedio", objective = "Lleva 5 raíces de tierra y 12 hongos lunares a Alanndarian Arrullanoche a Auberdine, para que pueda preparar un bálsamo curativo.", description = "El agua servirá como base para el bálsamo curativo que prepararé para los ciervos. Pero necesitaré raíz de tierra para potenciar sus propiedades curativas. Los herboristas saben cómo encontrarla, así que si no entiendes mucho de este tema, tendrás que encontrar a uno que nos ayude.\n\nPor último, para darle potencia, necesito hongos lunares. No es difícil encontrar flores de hongo lunar. Solo tienes que ir hacia el este y buscar en cualquier cueva. Pero ten cuidado, en las cuevas hay lechúcicos lunares y últimamente están muy irritables.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6126] = {title = "Nuevas lecciones", objective = "Viaja a Claro de la Luna, al poblado Amparo de la Noche, y habla con Dendrita Rafagaestelar.", description = "Ha llegado el momento de que aprendas algo sobre el veneno y el poder que los druidas tenemos sobre él, <nombre>. Cenarius nos ha bendecido con la habilidad de purgar el veneno más agresivo con un mero conjuro. Este es un don que no debe tomarse a la ligera. Y para asegurarme de que aprendes esta lección, tratarás los efectos del envenenamiento como lo haría un seglar.\n\nViaja a Claro de la Luna y habla con Dendrita Rafagaestelar. Espera tu llegada para dar comienzo a tu lección.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6127] = {title = "La fuente del envenenamiento", objective = "Usa el muestrario de Cima Calígine vacío para recoger una muestra de agua de uno de los estanques de la cima.\n\nLuego llévale el muestrario de Cima Calígine lleno a Tonga Tótem de Runa a El Cruce, en Los Baldíos.", description = "Lo más probable es que el foco del envenenamiento sea Cima Calígine, al noroeste de El Cruce. En las cimas hay estanques que influyen en el clima de la zona. Sospecho que el agua ha sido emponzoñada por los adoradores de demonios Filo Ardiente.\n\nRecoge agua del estanque de la cima en este recipiente. Luego llévaselo a Tonga Tótem de Runa en El Cruce. Fue él quien nos pidió ayuda y trabajarás con él para solucionar este problema.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6128] = {title = "Reunir los ingredientes del remedio", objective = "Llévale 5 raíces de tierra y 5 cuernos de kodo a Tonga Tótem de Runa en El Cruce para que pueda confeccionar un bálsamo curativo.", description = "El agua será la base del bálsamo curativo que voy a preparar para las gacelas. Pero necesitaré raíz de tierra para potenciar sus propiedades curativas. Los herboristas saben cómo encontrarla, así que si no entiendes mucho de este tema, tendrás que encontrar a uno que nos ayude.\n\nPor último, para darle potencia, necesito cuernos de kodo, unas simples astillas o unos trozos no bastarán. Los kodos asequibles para ti deambulan por la parte norte de Los Baldíos; abate a algunos por el bien superior del equilibrio, <nombre>, y tráeme sus cuernos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6129] = {title = "Curar la dolencia", objective = "Usa el bálsamo animal curativo sobre las 10 gacelas enfermas que se encuentran en la parte norte de Los Baldíos; así se curarán. Hemos recibido informes según los cuales se han avistado gacelas enfermas por la carretera que va de este a oeste en El Cruce.", description = "He podido preparar suficiente bálsamo para diez dosis curativas, <nombre>. Mientras trabajo con las autoridades locales para tratar de hacer más bálsamo, me gustaría que nos ayudaras a iniciar la tarea. En Los Baldíos del Norte hay gacelas enfermas; usa el bálsamo con ellas y cura su malestar.\n\nDendrita Rafagaestelar del Claro de la Luna querrá hablar contigo cuando acabes, estoy seguro. Por favor transmite también nuestro agradecimiento al Círculo Cenarion allí... ¡y permite que te agradezca directamente la ayuda prestada!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBolsa de remedio polvo de velo"}
MultiLanguageQuestData['mx'][6130] = {title = "Poder contra el veneno", objective = "Vuelve a Cima del Trueno para hablar con Turak Tótem de Runa en Alto de los Ancestros.", description = "Has aprendido lo que significa curar un envenenamiento sin ayuda espiritual. No dejes que tu poder sobre el veneno te haga olvidar lo que los demás sufren a causa de él.\n\nEs hora de que vuelvas a ver a Turak Tótem de Runa a Cima del Trueno, <nombre>. Seguro que ahora que has entendido la lección, tendrá algún hechizo importante que enseñarte.\n\nBuena suerte, joven druida. Volveremos a vernos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6132] = {title = "¡Sácame de aquí!", objective = "Escolta a Melizza Zumbala.", description = "¡Sácame de aquí!\n\nVine al Valle de las Lanzas para hablar con los Maraudine. Creía que podría hacer negocios con ellos... ¡pero no quieren negociar! ¡Creo que solo quieren comerme!\n\n¡Sácame de aquí! ¡Mi hermano Hornizz te pagará bien! Está en nuestro campamento, cerca del Cementerio de Kodos, al este.\n\nDémonos prisa, <nombre>. Hace dos minutos escasos oí a unos centauros diciendo que iban a por leña para la caldera...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6133] = {title = "La orden del Señor forestal", objective = "Viaja a la frontera norte de las Tierras de la Peste del Este y recupera el Registro de Quel'Thalas. Se encuentra en algún lugar del Refugio Quel'Lithien.\n\nTambién tienes que matar a 8 forestales, 8 zancaminos y 8 leñadores.", description = "Los elfos nobles del Refugio Quel'Lithien poseen algo que me pertenece, <clase>: un documento que detalla mi vida como mortal.\n\nAntes de que preguntes: no, desde luego no compartiré contigo tal información. Haz solo lo que te diga, gusano: recupera el documento.\n\nY, tontolaba, asegúrate de dejar tanta sangre y pena a tu paso como te sea posible. Haz que sufran...", progress = "No me dejes aquí esperando, <clase>.", completion = "Espero que no leyeras el documento. Aunque supongo que ni siquiera tú harías algo tan estúpido...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6134] = {title = "La caza de ectoplasmas", objective = "Reúne 8 ectoplasmas.", description = "Hacia el sureste hay un valle, el Valle de los Huesos, que está infestado de fantasmas Magram. La cosa da miedo, ¿no? ¡Pues imagina el miedo que pasarán los Magram! Si sacamos la energía fantasmal de ese sitio, seguro que los centauros estarán agradecidos.\n\nTen, coge este cajón de imanes fantasmales. Colocas uno entre los dos esqueletos grandes del valle, los goliat muertos. Los fantasmas irán hacia él. Aléjate, elimina a los fantasmas y captura su ectoplasma. Eso es lo que venderemos a los Magram.", progress = "¿Dónde está mi ectoplasma, <nombre>?", completion = "¡Ahí está! Y parece que también llevas un poco encima. Es pegajosillo, ¿eh? \n\nBueno, gracias por todo, &lt;nombre&gt;. Esta cosa me hará ganar una fortuna... ¡si consigo convencer a los centauros de que la vale!", rewards = "Brazales de cóndorRodela garranclaRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][6141] = {title = "Hermano Anton", objective = "Habla con el hermano Anton en Desolace.", description = "Mi compañero de armas, el hermano Anton, oyó rumores de una infestación de no-muertos en el lejano Kalimdor, en una tierra llamada Desolace. Antón reservó de inmediato un pasaje para ese lugar, para destruir a los no-muertos y acabar con la amenaza que representan.\n\nEstá buscando a voluntarios valientes y decididos que le ayuden. Si amas la justicia, ve a hablar con Anton. Está en Desolace, en Punta de Nijel, la ciudad de la Alianza.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6142] = {title = "Almejas", objective = "Encuentra 10 piezas de carne de almeja blanda y llévaselas a Mai'Lahii a la Aldea Cazasombras.", description = "¡Tienes pinta de <pescador/pescadora>, <clase>! A mí me encantan los peces... he pescado toda mi vida. El mejor cebo es la carne de almeja blanda. El pez no puede resistirse a ella, ¿sabes?\n\nHacia el norte, lejos de la costa, encontrarás un navío naufragado. En esa zona hay muchísimas almejas blandas. Si me traes 10 piezas de carne de almeja blanda, te daré algo a cambio.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Mandiletes PardocFaja ColaroCinturón con brazales de aceroRecibirás:\n\nObjeto #10"}
MultiLanguageQuestData['mx'][6143] = {title = "Otros pescados para freír", objective = "Mata a 7 mirmidones Filozante, 7 nagas Filozante y 5 hechiceras Filozante y luego ve a Cazasombras, en Desolace, a hablar con Drulzegar.", description = "Puede que lo hayas oído, puede que no... mi tripulación y yo estábamos pescando cerca de la Isla Ranazjar, hacia el norte y al norte del navío naufragado. Siempre hemos pescado ahí. Ahora lo único que hago es pensar en la forma de vengar a mis compañeros caídos.\n\nUna mañana fuimos atacados por los nagas, que mataron a todos menos a mí.\n\nMi conciencia no puede con esa carga, <clase>. Necesito que vayas y frías a esos nagas por mí. Haré que te merezca la pena. ¿Quieres ayudarme?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6144] = {title = "La llamada del teniente", objective = "Viaja a Entrañas y habla con Bragor Puñosangre.", description = "Ha llegado la orden, <clase>. Bragor Puñosangre ha solicitado que envíe a mis mejores agentes a Entrañas para una operación táctica muy delicada.\n\nPor desgracia, mis mejores agentes murieron hace más de tres años. Ahora solo cuento con un mísero grupo de chusma descerebrada.\n\n<Nathanos te lanza una fría mirada.>\n\nParte de inmediato hacia Entrañas y preséntate a Bragor Puñosangre. ¡Y no me hagas quedar mal, <clase>!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6145] = {title = "El mensajero carmesí", objective = "Vuelve a las Tierras de la Peste del Este y encuentra al mensajero carmesí. Mata al mensajero y recupera la Orden del Gran Cruzado.\n\nLleva el documento a Nathanos Clamañublo y espera sus instrucciones.", description = "Igual que el cuerpo no puede sobrevivir sin cabeza, la cabeza no puede sobrevivir sin cuerpo. Las defensas de la Cruzada Escarlata que hay en el interior de Stratholme son prácticamente impenetrables. Solo podemos separar el cuerpo de la cabeza.\n\nMis mortacechadores han estado reuniendo datos sobre la actividad de la Cruzada fuera de Stratholme. Envían cada día un informe de su centro de mando a Mano de Tyr. ¡Ese informe es la clave, <raza>! Encuentra al mensajero carmesí y arrebátale ese informe. Llévalo a Nathanos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6146] = {title = "La estratagema de Nathanos", objective = "Viaja a Mano de Tyr, al sureste de la Hacienda de Marris. Una vez allí, da un mordisco a la manzana podrida. Entrega la Orden del Gran Cruzado al señor cruzado Valdemar con la protección de la forma de la Cruzada Escarlata.", description = "He hecho algunos ajustes en esta orden. Si nuestra pequeña estratagema funciona, les haremos exponer al Oráculo escarlata ¡y entonces atacaremos!\n\nPresta atención, <clase>. Tú entregarás esta orden al señor cruzado Valdelmar.\n\n¿Que cómo? Pues vas y se la das, tontolaba.\n\nLleva la orden y esta manzana podrida a Mano de Tyr. Cuando entres en la ciudad, cómete la manzana. Te transformará en algo más... digerible para los humanos. Entrega la orden en mano al señor cruzado Valdelmar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6161] = {title = "La búsqueda del tesoro de Masatormento", objective = "Encuentra la llave de plata de Masatormento. Encuentra la llave de oro de Masatormento. Encuentra y abre el cofre de Masatormento.", description = "El diario de Masatormento te cuenta cómo su nave fue atacada por unas criaturas marinas cuando navegaba hacia el Bastión Plumaluna. Para impedir que su tesoro cayera en manos enemigas, escondió su cofre en la Isla Ranazjar.\n\nPara abrir ese cofre se necesitan dos llaves, una de oro y otra de plata. Y esas llaves se perdieron. Pero si encontramos las llaves y el cofre... ¡el tesoro será nuestro!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nTimón del capitán MasatormentoCaña del timón del capitán Masatormento"}
MultiLanguageQuestData['mx'][6162] = {title = "a última batalla de un marido", objective = "Mata al señor supremo Ror y lleva su garra a Dreka'Sur al Puesto del Veneno de Frondavil.", description = "Mi marido viajó por Frondavil, combatiendo contra el Consejo de la Sombra y otras atrocidades corruptas por el honor de nuestro clan.\n\nEscapó de la muerte en numerosas ocasiones y un día recibí una carta suya en la que decía que un druida le había pedido ayuda para luchar contra un gran fúrbolg podrido llamado señor supremo Ror. Nunca más se supo de ninguno de ellos.\n\nQuiero la garra de ese Ror, <nombre>. ¡Quiero que pague por dejarme viuda! Creo que la criatura se encuentra al sur... cerca de la frontera de Vallefresno.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6163] = {title = "Ramstein", objective = "Viaja a Stratholme y mata a Ramstein el Empachador. Coge su cabeza y llévasela como souvenir a Nathanos.", description = "Me superaron. Estaba en este mismo lugar... firme, defendiendo el terreno por Lordaeron. La granja fue atacada por una gigante ola de la Plaga.\n\nEsos malditos... Esa escoria... Algo planeó sobre mí... Sus vísceras colgaban de su cavidad torácica...\n\nMe desperté como miembro de la Plaga. Durante tanto tiempo me sentí tan impotente... Mi mente se unió a la del Rey Exánime.\n\nElla vino a por mí... de alguna forma, sabía que lo haría. Libre.\n\nY ahora debo cobrar mi venganza. Debo vengarme de lo que se llevó mi vida. Destrúyelo tú.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nSello real de AlexisCírculo elemental\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][6164] = {title = "Libro de entradas de Augustus", objective = "Consigue el libro de entradas de Augustus en la posada del Valle del Terror.", description = "¡Ya estoy! ¿Qué quieres?\n\nAy, espera... No puedo abrir la tienda sin mi libro de entradas. ¿Cómo voy a hacer nada sin registrarlo en mi libro de entradas?\n\nHe debido de dejarlo en la ciudad, en alguna parte. En mi habitación de la posada... debe de estar allí.\n\nTráeme mi libro. ¡Por favor, tráemelo! ¡Tráeme mi libro y verás! ¡Montaré la tienda y verás mis precios! ¡Son DE LOCOS!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6181] = {title = "Mensajero a toda prisa", objective = "Lleva la Nota de Lewis a Thor, el maestro de grifos.", description = "Aunque no tenemos mucha ayuda directa desde Ventormenta, tengo un contacto en la ciudad que nos ayuda con los suministros de armaduras. Su nombre es Osric Strang. Su tienda, Inmunidad Limitada, está en el Casco Antiguo de Ventormenta.\n\nNuestro suministro se está agotando y debemos contactar con Osric para pedirle más. ¿Puedes llevarle esta nota?\n\nEl camino más rápido hasta Ventormenta es con Thor, nuestro maestro de grifos. Está justo bajo la colina, llévale mi nota y coge un grifo hasta Ventormenta.", progress = "Parece que tienes prisa. ¡Entonces has venido al lugar adecuado!", completion = "¿Tienes que llevar esta nota a Ventormenta? Ningún problema, ¡puedes tomar uno de mis grifos!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6182] = {title = "El primero y el último", objective = "Habla con Mathias Shaw en el Casco Antiguo, en Ventormenta. Vive en los Cuarteles.", description = "Nathanos Marris fue el primer y último Señor forestal Discípulo de Sylvanas Brisaveloz, ahora la Reina alma en pena de los Renegados.\n\nHabíamos creído que Nathanos había caído en acción, en la defensa de Lordaeron cinco años atrás. Si bien nunca se recuperó su cadáver, se creyó que no consiguió salir de las Tierras de la Peste del Este.\n\nMathias Shaw ha estado investigando la desaparición, y quizás tenga nueva información. Preséntate ante él inmediatamente. Vive en el Casco Antiguo, en los Cuarteles.", progress = nil, completion = "Tras algunos informes sobre extraña actividad de los Renegados en las Tierras de la Peste del Este, se enviaron agentes del IV:7 a investigar. Los resultados de esa investigación son inquietantes.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6183] = {title = "Honra a los muertos", objective = "Vuelve a hablar con Mathias Shaw si quieres aceptar esta misión.", description = "El caso Marris se asignó a cinco de mis mejores agentes de campo. Uno regresó, solo para morir mientras dormía tres días después.\n\nLa poca información que conseguimos de él, eran cosas absolutamente incoherentes. Pudimos descifrar dos palabras: \"Nathanos,\" y \"Clamañublo.\"\n\nNo tengo personal disponible para continuar con esta investigación, y Ravenholdt no nos ayudará. Debemos llegar al fondo del asunto. Al menos para proporcionar respuestas a las familias de los fallecidos. ¿Nos ayudarás?", progress = nil, completion = "&lt;Mathias asiente.&gt;\n\nConfiaba en que Wrynn me enviaría hombres y mujeres de honor... los soldados más dedicados de la Alianza.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6184] = {title = "Flint Sombramás", objective = "Vete al Campamento del Orvallo en las Tierras de la Peste del Oeste y reúnete con tu contacto, Flint Sombramás.|n", description = "Lo único que sabemos hasta ahora, es que este tal Clamañublo podría haber matado a Nathanos Marris. Suponemos que este Clamañublo es el mismo demonio que mató a mis agentes.\n\nFlint Sombramás, otro operativo del IV:7, está estacionado en el campamento de la Alianza del Alto del Orvallo, en las Tierras de la Peste del Oeste. Búscale. Te pondrá al corriente de la situación actual en la zona y te dará una misión.\n\nBuena suerte, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6185] = {title = "Las pestes del este", objective = "Explora las Tierras de la Peste del Este en busca de pistas sobre el \"Clamañublo\" y los agentes perdidos del IV:7. Si encuentras alguna insignia del IV:7 llévasela a Flint Sombramás en el Campamento del Orvallo.", description = "Como he dicho, tu primera misión será de reconocimiento. Nada extravagante, <nombre>. Debes viajar a las Tierras de la Peste del Este y buscar cualquier pista sobre ese Clamañublo.\n\nEstate al acecho de información sobre nuestros espías perdidos. Tenemos que suponer que están muertos y si lo están, debe haber cadáveres... en algún sitio.\n\n<Flint traga saliva.>\n\nTodos los agentes del IV:7 llevan esta insignia.\n\n<Flint te muestra su insignia del IV:7.>\n\nSi encontraras alguna de estas insignias, devuélvemela.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6187] = {title = "Restaurar el orden", objective = "Reúne un ejército y viaja a las Tierras de la Peste del Este. Lanza un asalto contra Nathanos Clamañublo y cualquier miembro de la Horda que pueda intentar protegerle.\n\nTienes que permanecer alerta, <nombre>. Los de la Horda defenderán al Señor forestal con su vida.", description = "¿Sabes cuántos Señores forestales existen en este mundo? ¿Cuántos Señores forestales humanos han existido alguna vez?\n\nLos logros de Nathanos no tenían precedente. Era un genio táctico, responsable de todas las victorias de la Alianza durante una década del conflicto.\n\nY ahora... el Campeón de los Renegados.\n\nNo. ¡¡No puede ser!! Hay que restaurar el orden.\n\nReúne un ejército, <nombre>. Vuelve a las Tierras de la Peste con el ejército y destruye a Clamañublo.\n\nTe deseo suerte, <nombre>. En serio, la necesitarás para esta batalla.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Arco de madera goreHabitante de TempestiraProtector sacroRecibirás:\n\n"}
MultiLanguageQuestData['mx'][6261] = {title = "Dungar Tragolargo", objective = "Lleva el cajón de Osric a Dungar Tragolargo, el maestro de grifos.", description = "<nombre>, he reunido en este cajón todo lo que me pidió Lewis. ¿Puedes llevárselo?\n\nSi ya has hablado con Thor, en los Páramos de Poniente, podrás tomar un grifo de vuelta. Dungar Tragolargo es nuestro maestro de grifos, lo encontrarás en el Distrito de Mercaderes.\n\nHabla con Dungar y llévale este cajón a Lewis tan rápido como puedas. ¡No queremos que nuestros combatientes de los Páramos de Poniente vayan mal equipados!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6281] = {title = "Prosigue hasta Ventormenta", objective = "Cómprale al maestro de grifos Thor un vuelo en grifo y lleva la Nota de Lewis a Osric Strang, en la tienda Inmunidad Limitada, en el Casco Antiguo de Ventormenta.", description = "A cambio de una pequeña tarifa puedes tomar un grifo hasta Ventormenta y llevarle a Osric la nota de Lewis. No encontrarás un modo más rápido para ir hasta allí.\n\nSi te parece aceptable, vuelve a hablar conmigo cuando estés <listo/lista> para el viaje. Te cobraré algo pero, créeme, ¡merece la pena!", progress = "Has estado viajando, ¿eh? ¿Has estado en algún sitio interesante?", completion = "Ah, ¿una nota del intendente Lewis? No me sorprende que necesite más equipo. La Colina del Centinela está bastante lejos, en una tierra casi olvidada por Ventormenta.\n\nMuchas gracias, &lt;nombre&gt;. Toma algo de dinero para cubrir los gastos del viaje.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6282] = {title = "La amenaza de las arpías", objective = "Maggran Vinculador Terrestre, en el Refugio Roca del Sol, quiere que mates 7 arpías Furia Sangrienta, 7 emboscadoras Furia Sangrienta, 7 destripadoras Furia Sangrienta y 7 malaplumas Furia Sangrienta.", description = "Los tauren se enorgullecen de ser los protectores de estas tierras. Sin duda comprenderás que me preocupe la gran cantidad de arpías que viven aquí, en Espolón.\n\nLos Furia Sangrienta son la razón del aumento de las arpías en Kalimdor. Dan caza a toda forma de vida, impidiendo que los inocentes pasen de las fronteras.\n\n¡Necesito que acabes con las arpías, <nombre>!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6283] = {title = "El linaje Furia Sangrienta", objective = "Maggran, en el Refugio Roca del Sol, quiere que mates a la desgarradora Furia Sangrienta y le lleves sus restos como prueba de tu hazaña.", description = "Diezmar el número de arpías Furia Sangrienta no será suficiente. La única cura posible para su enfermedad, sería asesinar a su líder, desgarradora Furia Sangrienta.\n\nPara esas asquerosas criaturas, lo es todo menos su reina. Mátala y seguro que sus filas se reducen.\n\nVuelve a La Vega Carbonizada. La encontrarás allí, en las colinas del oeste. No será fácil acabar con ella, pero la recompensa merecerá la pena.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Cinturón de estridadorCapa de duendecilloRecibirás:\n\n"}
MultiLanguageQuestData['mx'][6284] = {title = "Aracnofobia", objective = "Mata a Besseleth y lleva el colmillo de Besseleth a Maggran en el Refugio Roca del Sol.", description = "Advertencia: Penetra en el Cañón Sishir al oeste de aquí por tu cuenta y riesgo.\n\nBesseleth y sus hijos del bosque de ocho patas, han reclamado este cañón como su guarida de telarañas.\n\nMaggran Vinculador terrestre en el Refugio Roca del Sol, ha puesto precio a la cabeza de Besseleth. Mátala y lleva una prueba de su muerte a Maggran. Recibirás una recompensa por poner fin a la amenaza de ocho patas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Espada corta de arcillaVara de cristal claroRecibirás:\n\n"}
MultiLanguageQuestData['mx'][6285] = {title = "Regresa junto a Lewis", objective = "Compra un vuelo en grifo hasta la Colina del Centinela al maestro de grifos Dungar Tragolargo y lleva el cajón de Osric a Lewis de la Colina del Centinela.", description = "El maestro de grifos de los Páramos de Poniente es Thor. Si ya has hablado con él puedes tomar uno de los grifos para ir hasta allí.\n\nTe conviene saber algo: los grifos siempre están entrenados para volar a su capital pero solo te llevarán a otro maestro de grifos si ya has estado con él.\n\nYa has hablado con Thor, así que vuelve a hablar conmigo cuando estés <listo/lista> para volar hasta los Páramos de Poniente. Cuando estés allí podrás entregar el Cajón de Osric al intendente Lewis.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6301] = {title = "El ciclo del renacimiento", objective = "Tammra Campo de Viento, en el Refugio Roca del Sol, quiere que le consigas 10 semillas de Gaia.", description = "La avaricia industrial y la guerra continua han destrozado las tierras de Espolón. Solo la bendición de la Madre Tierra podría curarlas.\n\n<nombre>, necesito que busques una semilla especial, la semilla de Gaia. Solo es posible encontrarlas en Sierra Espolón, al norte del Refugio Roca del Sol en el Lago Mirkfallon, cerca de la orilla.\n\nCuando me traigas las semillas, las imbuiré de poder chamanístico para acelerar su crecimiento.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6321] = {title = "Suministros para El Rémol", objective = "Lleva el pedido de Morris a la cuidadora de murciélagos Anette.", description = "El ejecutor Zygand me pidió que llevara parte de nuestro equipamiento hasta El Rémol. Con la Plaga y cosas mucho peores acechando en los bosques, no quiere que los Guardias de la Muerte tengan escasez de equipamiento.\n\nEn general, tenemos bastantes suministros, pero necesitamos más armas para remplazar las que perdimos en el campo de batalla.\n\nAquí tienes el pedido de lo que se necesita, para el vendedor de armas Gordon Wendham en Entrañas. Lleva el pedido a la cuidadora de murciélagos Anette, y habla con ella sobre cómo transportarlas a Entrañas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][6322] = {title = "Michael Garrett", objective = "Lleva el cajón de Gordok a Michael Garrett.", description = "He metido los suministros para El Rémol en esta caja. Si ya has visitado El Rémol y hablado con el maestro de murciélagos, entonces puedes volver en murciélago hasta donde está.\n\nHabla con el maestro de murciélagos de Entrañas, Michael Garrett. Puede proporcionarte un murciélago para ir a El Rémol.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][6323] = {title = "Vuela a Entrañas", objective = "Pídele un viaje en murciélago a Entrañas a la cuidadora de murciélagos Anette. Después, lleva el pedido de Morris a Gordon Wendham en Entrañas.", description = "Uno de mis murciélagos puede llevarte a Entrañas. Normalmente hay que pagar un módico precio, pero el vuelo a Entrañas es gratis para <un apuesto/una encantadora> <raza> como tú. Vuelve a hablar conmigo cuando estés <listo/lista> y organizaremos el transporte.\n\nEncontrarás a Gordon Wendham en el Barrio del Comercio de Entrañas. Es el mismo barrio donde aterrizará mi murciélago.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][6324] = {title = "Regresa junto a Morris", objective = "Compra un viaje en murciélago a El Rémol al maestro de murciélagos Michael Garrett. Después, lleva el cajón de Gordok al Guardia de la Muerte Morris en El Rémol.", description = "La maestra de murciélagos de Rémol es la cuidadora de murciélagos Anette. Si ya has hablado con ella, puedo dejarte un murciélago para que vueles hasta donde está.\n\nNuestros murciélagos siempre vuelan a Entrañas, pero, para realizar viajes más largos, su jinete primero debe visitar la zona y hablar con el maestro de murciélagos.\n\nYa has conocido a Anette en Rémol, así que ahora puedes volar en un murciélago hasta allí. Vuelve a hablar conmigo cuando estés <listo/lista>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][6344] = {title = "Recuerdos nostálgicos", objective = "Lleva el libro de recetas de Dolanaar a Fidelio en Dolanaar.", description = "Una amiga mía, la hermana Aquinne, se está formando para convertirse en sacerdotisa de la Luna en Darnassus. Dejó Dolanaar para estudiar en el templo el año pasado. En sus cartas dice que se encuentra bien y que está aprendiendo mucho, pero que echa de menos su casa y a sus antiguos amigos. He recopilado un libro con sus recetas favoritas de Dolanaar.\n\nSi tienes tiempo, ¿podrías llevárselo a Darnassus? Puedes pagarle un viaje en hipogrifo a Fidelio. Se encuentra en el centro de la ciudad, justo al otro lado de la taberna.", progress = nil, completion = "Sí, preciso un una mensajera que lleve un paquete a Costa Oscura. ¿Me ayudarías?", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][6361] = {title = "Un fardo de pellejos", objective = "Llévale el fardo de pellejos al maestro de jinetes del viento Tak en el Poblado Pezuña de Sangre.", description = "Tengo un fardo de pellejos de los animales de Mulgore y los tengo que enviar a Cima del Trueno. Un colega de allá, Ahanu, usará estos pellejos para crear artículos de cuero.\n\n¿Podrías llevárselas por mí?\n\nEl camino más rápido a Cima del Trueno es montado en un jinete del viento. Llévale el fardo de pellejos a Tak, el maestro de jinetes del viento en el Poblado Pezuña de Sangre, y coméntale lo del transporte a Cima del Trueno.", progress = "¿Vienes a por un jinete del viento? ¿Tienes que transportar algo?", completion = "Si tienes que llevar estos pellejos a Cima del Trueno, ¡has venido al lugar adecuado!", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][6362] = {title = "Un viaje a Cima del Trueno", objective = "Cómprale un trayecto en jinete del viento hasta Cima del Trueno al maestro de jinetes del viento Tak y llévale entonces el fardo de pellejos a Ahanu en Cima del Trueno.", description = "Por una módica cantidad, te daré un jinete del viento a Cima del Trueno. ¡No verás un medio más rápido a la ciudad!\n\nSi te parece bien, vuelve para hablar conmigo cuando estés <listo/lista> para salir.\n\nSi vas a llevar esos pellejos a Ahanu, me parece que se encuentra en La Armería de Hewa, en la base de la torre de los jinetes del viento de Cima del Trueno. ¡Y aterrizarás precisamente allí!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][6363] = {title = "Tal, maestro de jinetes del viento", objective = "Lleva los artículos de cuero de Ahanu a Tal en Cima del Trueno.", description = "He preparado unos artículos de cuero para que Varg los venda en el Poblado Pezuña de Sangre. ¿Podrías llevárselos?\n\nSi ya has estado en el Poblado Pezuña de Sangre y has hablado con el maestro de jinetes del viento, entonces puedes volver a usar el mismo medio de transporte para volver allá.\n\nToma los artículos de cuero y ve a ver a Tal, el maestro de jinetes del viento de Cima del Trueno, y coméntale lo de organizar el transporte al Poblado Pezuña de Sangre.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][6364] = {title = "Regresa junto a Varg", objective = "Cómprale un viaje en jinete del viento hasta el Poblado Pezuña de Sangre al maestro de jinetes del viento Tal y llévale entonces los artículos de cuero de Ahanu a Varg Susurravientos.", description = "Para volar a una ciudad, tienes que haber estado allí antes y haber hablado con el maestro de jinetes del viento de esa ciudad. Ya has estado en el Poblado Pezuña de Sangre y has hablado con el maestro de jinetes del viento Tak, así que por una módica cantidad puedes coger un jinete del viento desde aquí.\n\nVuelve para hablar conmigo cuando estés <listo/lista>. Cuando llegues al Poblado Pezuña de Sangre, puedes entregarle los artículos de cuero a Varg Susurravientos.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][6365] = {title = "Entrega de carne a Orgrimmar", objective = "Llévale la carne de Grimtak a Burok en Cerrotajo.", description = "Tengo un surtido de carnes que desearía enviarle a una amiga. Se llama Gryshka, regenta la posada de Orgrimmar. ¿Podrías entregarle la carne de mi parte?\n\nEl camino más rápido a Orgrimmar es mediante jinete del viento. Llévale la carne a Burok, el maestro de jinetes del viento en Cerrotajo, y coméntale lo del transporte a Orgrimmar.", progress = "¿Necesitas llegar a algún lugar rápido? ¡Entonces has dado con el <raza> apropiado!", completion = "¿Tienes que llevar esta carne a Orgrimmar? Ningún problema. Por una módica cantidad mi jinete del viento puede llevarte.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6382] = {title = "La Caza de Vallefresno", objective = "Habla con Senani Corazón Atronador en Puesto del Hachazo, en Vallefresno.", description = "Tu fuerza es impresionante, <clase>. Tu determinación y dedicación a la caza me da la seguridad de que podrías pasar a algo más fuerte... a retos mayores.\n\nLos bosques de Vallefresno constituyen un vasto e indómito espacio natural sobre el que la Horda desea imponer su voluntad, tanto política como espiritual. Si quieres demostrar lo que vales en una tierra por descubrir, busca los consejos de Senani Corazón Atronador en el Puesto del Hachazo. La avanzada se encuentra al norte del camino procedente de Los Baldíos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6383] = {title = "La Caza de Vallefresno", objective = "Tres legendarias criaturas componen la Caza de Vallefresno; puedes buscarlas y ponerte a prueba frente a su astucia y fuerza. En ese proceso, espero que aprendas algo sobre ti misma. Estas criaturas son: el oso Ursangous, el felino sable de la noche Shadumbra y el hipogrifo Garrafilada.\n\nLas criaturas de la Caza de Vallefresno son poderosas y es posible que necesites ayuda para derrotarlas. Si llegas a hacerlo, tráeme la prueba de tu caza.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][6384] = {title = "Un viaje a Orgrimmar", objective = "Cómprale un jinete del viento al maestro de jinetes del viento Burok y llévale entonces la carne de Grimtak a Gryshka en Orgrimmar.", description = "Por unas monedas te procuraré un jinete del viento que te lleve a Orgrimmar. Cuando llegues, podrás llevarle la carne de Grimtak a Gryshka. Su posada se encuentra en el Valle de la Fuerza.\n\nVuelve aquí para hablar conmigo cuando estés <listo/lista> para el viaje.", progress = "¡Algo huele muy bien! ¿No tendrás carne cruda contigo?", completion = "¡Oh, qué maravilla! ¡Unas tajadas estupendas! Son de Grimtak, ¿verdad? Ese &lt;raza&gt; sí que sabe robarle el corazón a una dama...\n\nMe muero por cocinarlos. ¡Aunque no demasiado! La carne es mejor poco hecha, ¿no te parece?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6385] = {title = "Doras, maestro de jinetes del viento", objective = "Llévale la carta de Gryshka a Doras en Orgrimmar.", description = "Le he escrito una carta de agradecimiento a Grimtak. ¿Serías tan amable de entregársela? Si ya has estado en Cerrotajo y has hablado con su maestro de jinetes del viento, entonces puedes volver a usar ese medio de transporte.\n\nLlévale mi carta a Doras, el maestro de jinetes del viento de Orgrimmar, y coméntale lo del transporte a Cerrotajo.", progress = "¿Necesitas uno de mis jinetes del viento?", completion = "¿Tienes que llevar esto a Cerrotajo en Durotar? Sí, claro, puedo llevarte...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6386] = {title = "Regresa a Cerrotajo", objective = "Cómprale un jinete del viento para Cerrotajo al maestro de jinetes del viento Doras y llévale entonces la carta de Gryshka a Grimtak en Cerrotajo.", description = "Mis jinetes del viento están entrenados para volar a muchos lugares diferentes, siempre que ya hayas estado en ese lugar y hayas hablado con el maestro de jinetes del viento de dicho lugar.\n\nYa has estado en Cerrotajo y has hablado con el maestro de jinetes del viento Burok, así que puedes volar directamente hasta allí desde aquí. Cuando llegues a Cerrotajo, podrás entregarle la carta de Gryshka a Grimtak.\n\nHabla conmigo cuando estés <listo/lista> para salir.", progress = "¿Has regresado de Orgrimmar? ¿Le gustó a Gryshka la carne que le envié?", completion = "¡Ja! ¡Supongo que le gustó! ¡Nada ruboriza tanto a una dama como un hermoso y jugoso filete de carne!\n\nGracias, &lt;nombre&gt;. Me has hecho un gran favor. Aquí tienes algo de dinero por las molestias ¡y no te sorprendas si te invito a mi boda!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6387] = {title = "Estudiantes de honor", objective = "Lleva la lista de Gremlock a Brolan Barbaviento a Kharanos.", description = "Vienen a verme muchos enanos deseosos de aprender el arte de la cocina. ¡Y el objeto más preciado para un cocinero es una cuchilla!\n\nTengo una lista de estudiantes que han ganado una cuchilla honorífica por sus buenas notas. Llévasela a Golnir Dedorroca. Está en Forjaz. Él preparará las cuchillas.\n\nLo más rápido es ir en grifo, así que llévale la lista al maestro de grifos, Brolan Barbaviento, y que te arregle lo del transporte a Forjaz.", progress = "¿Ya te marchas de Thelsamar? ¿Estás listo para mudarte de ciudad?", completion = "¿Transporte a Forjaz? Por supuesto. Ir en grifo solo te costará unas monedas. ¿Qué te parece?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6388] = {title = "Gryth Thurden", objective = "Lleva los picos honorarios a Gryth Thurden a Forjaz.", description = "Aquí tienes los picos honorarios para los alumnos de Gremlock. Si ya has estado en Kharanos, lo mejor es que vuelvas en grifo.\n\nLlévale las cuchillas al maestro de grifos, Gryth Thurden, y comenta con él lo del regreso a Kharanos.", progress = "Parece que tienes prisa. ¿Necesitas un grifo?", completion = "¿Tienes que llevar esto a Thelsamar? Por supuesto. Si ya has estado allí y has hablado con Thorgrum Borrelson, puedes volver en uno de mis grifos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6391] = {title = "Vuela a Forjaz", objective = "Contrata un vuelo en grifo a Forjaz con el maestro de grifos Brolan Barbaviento y lleva la lista de Gremlock a Golnir Dedorroca, en Forjaz.", description = "Uno de mis grifos te llevará a Forjaz por unas monedas. Dale la lista de Gremlock a Golnir Dedorroca. Estará en el Gremio de minería de Montehondo. Eso está en el Distrito de La Gran Fundición en Forjaz; el grifo te dejará justo ahí.\n\nVen a verme cuando ya estés a punto para salir.", progress = "¿Qué puedo hacer por ti?", completion = "Ah, la última lista con los mejores alumnos de Brock. Tengo un envío de picos honorarios listo para salir. Solo tengo que grabar los nombres de los estudiantes...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6392] = {title = "Regresa junto a Gremlock", objective = "Contrata un vuelo en grifo a Kharanos con el maestro de grifos Gryth Thurden para llevar los picos honorarios a Gremlock Pilsnor en Kharanos.", description = "Puedes ir a Kharanos en grifo por poco dinero, pero solo si ya has estado allí. Los grifos solo van a sitios en los que ya has estado, así que acuérdate de hablar con el maestro de grifos de todos los sitios a los que vayas para poder volver más adelante.\n\nComo ya has hablado con Brolan, el maestro de grifos de Kharanos, ahora puedes ir de vuelta en grifo. Cuando llegues a Kharanos, llévale los picos a Gremlock Pilsnor.\n\nVen a verme cuando ya estés a punto para salir.", progress = "Ah, <nombre>, ¿ya estás de vuelta de Forjaz?", completion = "Trajiste los picos. ¡Excelente! Se los daré a mis estudiantes de minería. Seguro que están ansiosos por usarlos en los depósitos de minerales de Loch Modan.\n\nGracias por tu ayuda, &lt;nombre&gt;. Estoy en deuda contigo, pero espero que al menos este dinero cubra los gastos del viaje.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6393] = {title = "Guerra elemental", objective = "Lleva 10 incendritas a Tsunaman en el Refugio Roca del Sol.", description = "El Tribunal de las Mareas me ha enviado a declarar la guerra a los elementales de fuego que habitan aquí, en Sierra Espolón. Neptulon el Cazamareas, Señor de todos los elementales de agua, tiene un interés personal en extinguir a nuestros feroces parientes.\n\n<nombre>, puedes ayudarme a conseguir el favor del Tribunal destruyendo a los elementales de fuego de La Vega Carbonizada. Al ser destruidos, los elementos de fuego dejan incendritas. Tráemelas y recibirás una recompensa.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6394] = {title = "Pico de Thazz'ril", objective = "Lleva el pico de Thazz'ril al supervisor Thazz'ril.", description = "<nombre>, eres <un/una:r> <raza> de confianza. ¿Puedo contar contigo para otra tarea?\n\nHace algún tiempo estaba inspeccionando la cueva del Norte en busca de minerales y olvidé allí mi pico favorito. ¡Pero cuando volví a recuperarlo descubrí que la cueva estaba plagada de despiadadas criaturas! ¿Irás a la cueva, el Aquelarre del Filo Ardiente, para recuperar mi pico?\n\nLo dejé en una caverna con cascadas. El pico tiene un hechizo que te permitirá verlo en la oscuridad, así que no tienes que preocuparte mucho por encontrarlo... ¡solo por lo que lo esté custodiando!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6395] = {title = "El último deseo de Marla", objective = "Lleva los restos de Samuel Fipps a la tumba de Marla y luego vuelve con la novicia Elreth.", description = "Mi amiga Marla Fipps vivía con su marido Samuel. Cuando llegó la plaga, Samuel sucumbió a ella y se unió a las filas de la Plaga.\n\nMarla escapó a la no-muerte, solo para morir a manos de su enajenado marido. Pero su amor era tan fuerte que su último deseo fue ser enterrada con su amado Samuel.\n\nAhora Samuel Fipps vaga por un campamento en ruinas que se encuentra en un camino al noreste de Camposanto. Acaba con él. Haz realidad el deseo de Marla. Entiérralo con ella, en la primera fila de nuestro cementerio.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6401] = {title = "Kaya está viva", objective = "Da las buenas noticias a Tammra Campo de Viento en el Refugio Roca del Sol.|n", description = "Vete a dar las buenas noticias a Tammra Campo de Viento, la tía de Kaya. Está en el Refugio Roca del Sol. ¡Kaya está viva! Pensábamos que la habíamos perdido tras el brutal ataque a nuestra aldea. Sigue el camino hacia el oeste para llegar al Refugio Roca del Sol.\n\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6421] = {title = "Barranco del Alud", objective = "Explora las profundidades de la cueva del Barranco del Alud y lleva 10 cristales de resonita al Refugio Roca del Sol para que Mor'rogal las estudie.", description = "Aquí en el Espolón pasa algo. ¿Sientes la tensión en el aire, <nombre>?\n\nAl sureste de aquí existe una profunda caverna en el Barranco del Alud. Los kóbolds de allí están extrayendo un extraño mineral llamado resonita. Necesito que me traigas algunas muestras para poder entender lo que sucede allí. También necesito que investigues las profundidades de la cueva.\n\nVe allí, joven <clase>. Tenemos que saber lo que se oculta bajo esas montañas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6441] = {title = "Los cuernos de sátiro", objective = "Reúne 16 cuernos de sátiro para Pixie en el Puesto del Hachazo.", description = "¡Eh! He estado viajando por Vallefresno, camino de Trinquete, y decidí hacer un alto aquí en el Hachazo. Siempre estoy en busca de una oportunidad y, al parecer, los cuernos de sátiro están muy demandados en Trinquete en estos tiempos.\n\nDespués de preguntar por aquí, parece que los sátiros de la Senda de la Noche, Satyrnaar y Xavian tienen todos el tipo de cuernos que ando buscando. No puedo medirme a esos sátiros... ¡pero tú sí que pareces dar la talla!\n\nOye, ¿por qué no consigues los cuernos para mí y te compenso debidamente por tu tiempo?", progress = "Espero que no tardes en recuperar esos cuernos, <nombre>. ¡Pronto volveré a Trinquete!", completion = "¡Nos vendrán de perlas, &lt;nombre&gt;! ¡Gracias por toda tu ayuda! \n\nAh, y aquí tienes por tu tiempo...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6442] = {title = "Nagas en la Ensenada de Zoram", objective = "Llévale 20 cabezas de Colafuria a Marukai en La Ensenada de Zoram.", description = "El mal nos acecha desde la costa, <raza>.\n\nEs el lugar de descanso de la ciudad maldita de Zoram, destruida hace mucho tiempo y desde entonces sumergida bajo los mares. Perdida y casi olvidada.\n\nAhora, los nagas han regresado y en cuanto a sus motivos... los ignoramos. Pero el porqué importa poco; debemos defender la tierra en la que hemos trabajado con tanto ahínco para reclamarla.\n\n¡Vuelve a mí con 20 de sus cabezas! ¡Manda a los nagas de vuelta a los abismos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6461] = {title = "Chupasangres", objective = "Xen'zilla, en Malaka'Jin, necesita que mates a 10 trepadores Musgondo y a 7 escupevenenos Musgondo.", description = "Los trols de Malaka'Jin hemos prosperado gracias a la tierra. Sierra Espolón nos proporciona un gran terreno de caza para poder conseguir comida.\n\nÚltimamente hemos atraído a los visitantes inadecuados... Las arañas de estas montañas han estado asaltando nuestros campamentos por las noches, para robar nuestra caza.\n\nSi quisieras ayudarnos a matar a esas espantosas bestias, Malaka'Jin estaría en deuda contigo. En Espolón hay arañas por todas partes. Dirígete hacia el norte y verás lo que estoy diciendo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6462] = {title = "El talismán trol", objective = "Llévale 8 talismanes trols a Mitsuwa en la Avanzada Grito Infernal.", description = "Los de mi especie estaban viajando hacia aquí con muchos talismanes trols sagrados ¡pero los fúrbolgs Piel de Cardo los atacaron y los mataron antes de que pudieran alcanzar Zoram'gar! ¡Esos malvados fúrbolgs!\n\nAñoro a mis hermanos y hermanas que fueron masacrados pero nos volveremos a encontrar en la otra vida. Aunque sus talismanes trols tienen un gran valor en este mundo. ¡Es un ultraje que estén en manos de los fúrbolgs!\n\n<nombre>, ¡debes recuperar los talismanes! Están en baúles en el Bastión Piel de Cardo, una cueva al final del Poblado Piel de Cardo, al norte de Astranaar.", progress = "¿Has encontrado los talismanes, <nombre>? Por cada momento que los fúrbolgs tienen en su posesión esos objetos sagrados, ¡me hierve la sangre!", completion = "¡Los encontraste! ¡Gracias! ¡Gracias, &lt;nombre&gt;! No sabes el gran favor que me has hecho.\n\nUn trol sin talismán es como un orco sin cicatrices de guerra...\n\nSin ningún valor.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6481] = {title = "El despertar del terráneo", objective = "Abre el barril de resonita con el cristal de resonita encantado y, a continuación, mata a Goggeroc. Vuelve a ver a Mor'rogal para contarle lo ocurrido y entregarle el cristal de resonita encantado.", description = "Has descubierto una oscura amenaza para la tierra, <clase>. El barril de resonita que has encontrado en esa cueva, contiene a un terráneo dormido llamado Goggeroc.\n\nHe cambiado la mezcla de los cristales de resonita que encontraste con mis poderes chamanísticos. Coge el cristal de resonita encantado y abre el barril de resonita que contiene al terráneo.\n\nAl despertarse, Goggeroc estará debilitado... ¡Mátale, <nombre>!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guardamuñecas crin de loboBrazales de barba de búhoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][6482] = {title = "Liberar a Ruul", objective = "Escolta a Ruul y después habla con Yama Pezuña Nevada en el Puesto del Hachazo.", description = "¿Qué? ¿Quién eres?\n\n¿<nombre>? No eres <un/una> fúrbolg. ¡Están malditos! Pensaba, que era un oso y me capturaron ¡y ahora me matan de hambre! Las fuerzas me fallan...\n\nAyúdame a escapar y después habla con mi hermana Yama en el Puesto del Hachazo hacia el este.\n\n¡<nombre>! ¡Debo escapar!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6503] = {title = "Avanzada de Vallefresno", objective = "Mata a 9 avanzadas de Vallefresno.", description = "¡Malditas elfas! ¡Sabían exactamente dónde atacarnos!\n\nFueron las avanzadas... Intenté avisar de que nos estaban espiando, pero nadie me hizo caso. Y ahora míranos, ¡hacinados aquí como gallinas!\n\n¡Nunca es tarde para la venganza, <tron/titi>! ¡Cázalas y hazles pagar por lo que han hecho!", progress = nil, completion = "Muy bien, &lt;nombre&gt;. Tus habilidades de cacería son impresionantes...\n\nLa Alianza quedará ciega sin la ayuda de esas avanzadas, y sin información confiable es menos probable que ataquen.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6504] = {title = "Las páginas perdidas", objective = "Encuentra las 12 páginas que faltan del manual de instrucciones de trituradora y vuelve a componer con ellas los 3 primeros capítulos. Devuélvele las páginas a Gurda Cicafuria cerca del Puesto del Hachazo.|n", description = "Acabo de recoger esta trituradora en Trinquete y regresaba al Aserradero Grito de Guerra, donde se supone que estoy de servicio. Me dieron un manual sobre el funcionamiento de la trituradora pero en el camino de vuelta una ráfaga de viento impresionante me lo arrancó de las manos. Las páginas se esparcieron en todas las direcciones y solo me quedó la cubierta.\n\nLas páginas podrían estar en cualquier sitio ahora, supongo... ¡pero es que no sé cómo usar la trituradora sin ellas! ¿Podrías encontrarlas para mí?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de manejo de trituradoraManijas de aceiteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][6522] = {title = "Una alianza impía", objective = "Lleva el pergamino pequeño a Bragor Puñosangre que está en el Barrio Real en Entrañas.", description = "Estimada señora:\n\nComo muy bien sabe, le estamos ofreciendo la gran oportunidad de tomar Los Baldíos y tierras circundantes. A cambio, solo pedimos ayuda, y con ello nos referimos a la libertad de acción.\n\nRogamos que lo considere. Tenemos mucho poder y deseamos compartirlo con nuestros aliados. De momento me mantendré alejado de Zahúrda Rajacieno.\n\nSaludos.\nEmbajador MalcinRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6523] = {title = "Protege a Kaya", objective = "Escolta a Kaya Pezuña Plana hasta el Campamento Aparaje y ve a ver a Makaba Pezuña Plana cerca del límite sureste de Espolón.|n", description = "¡Gracias por rescatarme! Debemos irnos rápidamente antes de que descubran que soy libre. Por favor, escóltame hasta el Campamento Aparaje. Desde ahí, ya sé cómo seguir.\n\nMi padre, Makaba Pezuña Plana, estará muy preocupado hasta que llegue sana y salva.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6541] = {title = "Preséntate ante Kadrak", objective = "Preséntate ante Kadrak en la torre de vigilancia en Los Baldíos del Norte.", description = "¿Alguna vez has estado en Vallefresno, hacia el norte? La Horda ha montado recientemente una avanzada en La Ensenada de Zoram y siempre nos viene bien incorporar nuevos reclutas para defender los nuevos frentes.\n\nSi crees que te puede interesar, ve a ver a Kadrak en Los Baldíos del Norte, está en la torre de vigilancia. Se dirige a la campaña de Vallefresno y te dará más detalles.", progress = nil, completion = "Vallefresno es una tierra dividida pero nuestros más recientes esfuerzos han dado sus frutos. No solo tenemos una avanzada en La Ensenada de Zoram, sino que también nos hemos hecho con otra justo al norte llamada Puesto del Hachazo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6542] = {title = "Preséntate ante Kadrak", objective = "Preséntate ante Kadrak en la torre de vigilancia en Los Baldíos del Norte.", description = "¿Alguna vez has estado en Vallefresno, hacia el norte? La Horda ha montado recientemente una avanzada en La Ensenada de Zoram y siempre nos viene bien incorporar nuevos reclutas para defender los nuevos frentes.\n\nSi crees que te puede interesar, ve a ver a Kadrak en Los Baldíos del Norte, está en la torre de vigilancia. Se dirige a la campaña de Vallefresno y te dará más detalles.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6543] = {title = "Los informes Grito de Guerra", objective = "Abre el fardo de informes. Lleva los informes Grito de Guerra al explorador Grito de Guerra, al corredor Grito de Guerra y al escolta Grito de Guerra. Preséntate ante Kadrak en la torre de vigilancia norte en los Baldíos con la información que te hayan dado.", description = "Hace poco envié a unos exploradores a Vallefresno y necesito un mensajero para llevarles órdenes y traer los informes de lo que hayan observado.\n\nTu primera parada sería la Avanzada de Zoram'gar, en la costa oeste, en La Ensenada de Zoram, para encontrar al primer mensajero. También tendrás que detenerte en el Puesto del Hachazo, hacia el norte, y por la carretera que va hacia el este, cerca de Azshara. Allí encontrarás un explorador y un mensajero.\n\nDales a cada uno un informe y que ellos te den sus últimas pesquisas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6544] = {title = "El asalto de Torek", objective = "Escolta a Torek en su ataque sobre la Avanzada Ala de Plata contra Duriel Fuegolunar e informa después a Ertog Colmillorrabioso en el Puesto del Hachazo.", description = "¡Eh! ¡<clase>! ¡Ven aquí!\n\nMis asaltantes y yo estamos a punto de atacar la Avanzada Ala de Plata hacia el oeste. Nuestro objetivo es su líder, Duriel Fuegolunar. Según los informes de los exploradores, la avanzada está fuertemente defendida por centinelas y guerreros. ¡La batalla será gloriosa!\n\n¿Quieres ser parte de esta gloria, <nombre>, y ayudarnos? Si así lo deseas, cuando todo acabe, puedes informar de nuestro éxito a mi superior, Ertog Colmillorrabioso en el Hachazo.\n\n¿Qué me dices? ¿Podemos contar contigo?", progress = nil, completion = "¡Así que el ataque de Torek salió bien! Muy bien, &lt;nombre&gt;. Los elfos de la noche son enemigos respetables. Algo delgados ¡pero fuertes y feroces! Seguro que la batalla fue digna de ver...\n\n¡Y espero que te ganaras alguna que otra cicatriz!", rewards = "Bastón de apoyo pulidoAlfanje de metal de pizarraRecibirás:\n\n"}
MultiLanguageQuestData['mx'][6548] = {title = "Venga mi aldea", objective = "Mata a 8 rufianes Tótem Siniestro y a 6 mercenarios Tótem Siniestro. A continuación, ve a ver a Makaba Pezuña Plana cerca del límite sureste de Espolón.|n", description = "El clan Tótem Siniestro asaltó mi aldea y mató a casi todo el mundo. Yo maté a todos los que pude, pero conseguí escapar por los pelos.\n\n<nombre>, solo deseo más muertes en sus filas. Los encontrarás justo al oeste de aquí.\n\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6561] = {title = "La vileza de Brazanegra", objective = "Llévale la cabeza del señor crepuscular Kelris a Bashana Tótem de Runa en Cima del Trueno.", description = "Las fuerzas me han abandonado. ¡Necesito tu ayuda!\n\nOtrora este lugar era un gran templo de Elune. Pero la desgracia lo ha llevado a la ruina cuando la corrupción de un dios antiguo empezó a calar desde el subsuelo y contaminó la sagrada Poza de la Luna.\n\nAku'Mai, sirviente del dios antiguo, surgió de las aguas.\n\nLos adeptos del Martillo Crepuscular se han unido a los nagas para ocupar esas tierras. Esos adeptos, cuyo jefe es Kelris, sacrifican a inocentes a Aku'Mai a cambio de poder.\n\nMata a Kelris y llévale su cabeza a Bashana en Cima del Trueno, <nombre>, te lo ruego.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Cetro de lápidaRodela árticaRecibirás:\n\nCurrency Token Test Token 2"}
MultiLanguageQuestData['mx'][6562] = {title = "Problemas en las profundidades", objective = "Habla con Je'neu Sancrea en Vallefresno.", description = "Je'neu Sancrea necesita ayuda. Se encuentra en las Cavernas de Brazanegra en Vallefresno. El bosque de los elfos de la noche se encuentra al norte de Sierra Espolón. Puedes llegar hasta allí viajando por Risco Cortaviento o dirigiéndote hacia el norte a través de Los Baldíos. La Ensenada de Zoram está bastante al oeste del bosque. Ten cuidado, <nombre>. Allí hay fuerzas que no se tomarán con alegría tu presencia.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6563] = {title = "La esencia de Aku'Mai", objective = "Llévale 20 zafiros de Aku'Mai a Je'neu Sancrea en Vallefresno.", description = "Al principio de los túneles de las Cavernas de Brazanegra, se pueden encontrar grandes bloques de zafiros en las paredes de las cuevas. Recientemente se observó que los nagas estaban reuniendo los cristales. Hasta que se aclare el porqué, presiento que deberíamos impedírselo. Los cristales tienen un gran poder elemental y si este no se usa apropiadamente, podría producir un poderoso componente arcano.\n\n¿Me ayudarás, <nombre>? Las Cavernas de Brazanegra bordean La Ensenada de Zoram al norte de nuestra avanzada.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6564] = {title = "Lealtad a los dioses antiguos", objective = "Llévale la nota mojada a Je'neu Sancrea en Vallefresno.", description = "Hay unas líneas con mala caligrafía garabateadas en la arrugada nota:\n\n\"Sí, díganles a todas las sacerdotisas que me traigan los cristales. Los espíritus elementales de agua son fuertes en su interior y ayudarán a nuestros acuamánticos en sus conjuros.\n\nSi controlamos el poder de los cristales, apaciguaremos a Aku'Mai. Algún día tendremos suficiente poder para devolvernos a Aku'Mai ¡y el mundo conocerá una vuelta a su era más grandiosa! ¡Una era de reinado de los dioses antiguos!\"Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6565] = {title = "Lealtad a los dioses antiguos", objective = "Mata a Lorgus Jett.", description = "Debemos impedir que este seguidor del Martillo Crepuscular complete su plan. El Martillo Crepuscular no entiende a los espíritus de la naturaleza. Creen en los dioses antiguos, unas criaturas del caos y la destrucción que fueron derrotados hace mucho tiempo. No podemos permitir que el tal Lorgus consiga su propósito. Debes detenerlo, <nombre>. No puedo hacerlo personalmente, soy demasiado débil.\n\nDirígete a las Cavernas de Brazanegra, encuéntralo y mátalo. Después vuelve a encontrarte conmigo aquí.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Manto de castañoPodrás elegir una de estas recompensas:\n\nSortija del Puño\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][6567] = {title = "El Campeón de la Horda", objective = "Busca a Rokaro en la Aldea Cazasombras, en Desolace.", description = "Rexxar, uno de mis campeones más leales, descubrió que puede haber una forma de entrar en la guarida del dragón. Se ha marchado a Azeroth para unirse a una expedición rumbo a Terrallende.\n\nSin embargo, su compañero, Rokaro, de la Aldea Cazasombras sabe esta información. Búscalo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6571] = {title = "Suministros Grito de Guerra", objective = "Reúne los suministros Grito de Guerra: las espadas dentadas Grito de Guerra, cuerda, aceite Grito de Guerra y el envío de hachas de los Grito de Guerra para Locke Okarr en el Puesto del Hachazo.", description = "¡Andamos cortos de unos cuantos artículos en el Aserradero Grito de Guerra!\n\nPixie tiene nuestro cargamento de hojas de sierra en el Puesto del Hachazo. Habrá que ir a Bahía del Botín para recoger una caja de hachas del jefe de embarcadero Lozgil.\n\nSerá más difícil conseguir nuestro cargamento de aceite y cuerdas. Los fúrbolgs Piel de Cardo y Maderiza robaron las cuerdas y los sátiros interceptaron el envío de aceite ¡y lo usan ahora en repugnantes ritos en la Senda de la Noche, Satyrnaar y Xavian!\n\n¿Puedes ayudarme?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Fajín Grito de GuerraBotas Grito de GuerraGuanteletes Grito de GuerraRecibirás:\n\n"}
MultiLanguageQuestData['mx'][6583] = {title = "La prueba de los cráneos, Somnus", objective = "Destruye al Campeón del Vuelo Verde, Somnus. Lleva su cráneo a Brasaliza.", description = "Mientras Padre aplasta a los Aspectos, nosotros debemos encargarnos de envolver en caos y destrucción a su prole.\n\nDebes probar tu habilidad en combate con los insomnes: la prole del Vuelo Verde.\n\nVe al Pantano de las Penas y encuentra a Somnus, el Campeón del Vuelo Verde. Da rienda suelta a tu odio; domina a ese insecto... Y vuelve aquí con su cráneo...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6584] = {title = "La prueba de los cráneos, Chronalis", objective = "Chronalis, hijo de Nozdormu, custodia las Cavernas del Tiempo en el Desierto de Tanaris. Destrúyelo y lleva su cráneo a Brasaliza.", description = "Los guardianes del tiempo, los hijos de Nozdormu, el Señor de los Siglosss...\n\nLos tres custodian las Cavernas del Tiempo, pero solo uno interesa al Vuelo Negro: El Dueño del Tiempo, Chronalis, el draconizo favorito de Nozdormu.\n\nGolpea a este Campeón. Aséstale un golpe que haga llorar incluso a las estoicas arenas del tiempo. Y vuelve aquí con su cráneo...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6601] = {title = "El ascenso", objective = "Diría que se acabaron las charadas. Ya sabes que el amuleto de Subversión Dracónica que Myranda la Fada creó para ti no funcionará en el interior de la Cumbre de Roca Negra. Quizás deberías buscar a Rokaro y explicarle el apuro en el que te encuentras. Enséñale el amuleto Pirodraco apagado. Con un poco de suerte, él sabrá que hay que hacer ahora.", description = "Las calaveras de nuestros enemigos conforman un medallón. Conoces ese medallón, ¿verdad? Lo habrás visto, sin duda, pues lo llevan tus ancestros.\n\nCógelo, <mocoso/mocosa>. Vuelve a la cumbre y entrégaselo al general Drakkisath. El General imbuirá el encantamiento final al medallón y lo sintonizará con tu espíritu.\n\nLlevarás el medallón acabado como insignia de honor. Una insignia que simbolizará tu ascenso a uno de nuestros rangos más exclusivos: guardián de la madre de linaje.\n\n¡Ve!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6602] = {title = "La sangre de dragón Negro Campeón", objective = "Viaja a la Cumbre de Roca Negra y mata al general Drakkisath. Recoge su sangre y llévasela a Rokaro.", description = "¿Qué te parece visitar al Gran general? Pero sin ilusiones esta vez.\n\n¿Ceremonia? Bonita palabra para describir las sangrías que le gustan al Vuelo Negro.\n\nTodo lo que este amuleto necesita para activarse es la sangre del general Drakkisath.\n\nVuelve a la Cumbre de Roca Negra y elimina a Drakkisath. Trae aquí su sangre y yo activaré la llave de la Guarida de Onyxia.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAmuleto Pirodraco"}
MultiLanguageQuestData['mx'][6603] = {title = "Problemas en Cuna del Invierno", objective = "Encuentra a Donova Cubilnevado cerca de las fuentes termales de Cuna del Invierno.", description = "¡Hay problemas en Cuna del Invierno!\n\nEs que paso mucho tiempo por ahí... y me entero de estas cosas... Me enorgullece poder decirlo. Creo que las horas que paso por ahí, en las colinas, son horas bien invertidas. Me ayudan a desarrollar reflejos rápidos, una cabeza fría y un ojo astuto...\n\nHace falta juicio, cerebro y madurez para apreciar el mundo salvaje como lo hago yo.\n\nEste... estábamos hablando de algo, ¿de qué era?\n\nAh, sí, de problemas. Ve a ver a Donova Cubilnevado en las fuentes termales. Ella podrá decirte más.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6604] = {title = "Lechúcico salvaje iracundo", objective = "Habla con Jaron Tallapiedras en Aldea Estrella Fugaz.", description = "¿Has visto el campamento abandonado al sur de aquí? ¡Es como si los lechúcicos salvajes se hubieran vuelto locos y hubieran destruido todo lo que encontraban a su paso!\n\nHe oído rumores de que uno de los supervivientes del ataque está descansando en Aldea Estrella Fugaz, al oeste de aquí. Siento curiosidad por saber qué es lo que ocurrió... ¿tú no?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6605] = {title = "Algo extraño", objective = "Habla con Winna Riessgo en Frondavil.", description = "Acabo de regresar de Frondavil, <nombre>. En mi camino hice un alto en el Puesto del Veneno y me encontré con un personaje muy extraño... Parecía absorta en algo. Supongo que podría decirte de qué se trataba, pero seguramente ella prefiera explicártelo en persona.\n\nSi estás <interesado/interesada> ve al Puesto del Veneno en la parte oeste de Frondavil y busca a Winna Riessgo.\n\nQuién sabe, tal vez necesite tu ayuda...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6607] = {title = "Nat Pagle, pescador extremo", objective = "Nat Pagle quiere que pesques los siguientes peces:\n\nMahi mahi juncobruma de la Playa Juncobruma del Pantano de las Penas.\n\n1 artillero Sar'theris de la Playa de Sar'theris de Desolace.\n\n1 Ahi de Feralas del Río Verdantis de Feralas.\n\nLatipinia azul de La Costa Salvaje de Vega de Tuercespina.\n\nCuando los tengas todos, vuelve a buscar a Nat Pagle.", description = "No puedo decir que pescar me guste. Y llevo pescando unos 20 o 30 años.\n\nYo creo que la gente hace lo que hace por diferentes motivos.\n\nY no digo que haya que pescar durante 30 años o pescar cada pez del mar para convertirse en un maestro de la pesca. Solo hay que tener determinación. La suficiente para sentarse horas y horas sin conseguir nada más que desgastarse el trasero.\n\nMira, si me pescas algunos peces raros, te enseñaré un par de cosas. Ten una lista:Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCaña de pescar de la suerte de Nat"}
MultiLanguageQuestData['mx'][6608] = {title = "¡Qué bueno eres!", objective = "Parece que Lumak piensa que ya no puede enseñarte nada más sobre la pesca. Ve a buscar a su amigo, Nat Pagle, un humano pescador que vive en una isla al sur de Theramore (o eso parece que ha dicho).", description = "Lumak no puede enseñar nada ya a <nombre>. ¡Lo haces demasiado bien! Busca al Nat Pagle. ¡No te come, es amigo de Lumak! Nat te enseñará a pescar.\n\nEstá en el Marjal Revolcafango, al sur de Humie, Thermornoséqué. Nat seguro está pescando. ¡Ve!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6609] = {title = "¡Me has dejado seco!", objective = "Ve a Kalimdor, a la ciudad costera de Theramore. Busca una isla hacia el sur. ¡Nat Pagle te espera!", description = "¡Soy un enano, <niño/niña>! ¡Nací para pescar! ¡Mira, mira! Es como si fuera de piedra.\n\nMe has dejado seco. ¡Te he enseñado todo lo que sé!\n\n¿No lo pillas? En fin, tengo un amigo que puede echarte un cable. Nat Pagle se llama, un buen tipo. Lo encontrarás por las islas que hay al sur de Theramore. Venga, ¡arreando!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6610] = {title = "Sorpresa de almejate", objective = "Dirge Hojágil quiere que le consigas lo siguiente:\n\n10 huevos gigantes. Pueden ser huevos de los rocs que deambulan por Tanaris o de cualquier otro pájaro de grandes dimensiones.\n\n10 piezas de carne de almeja sabrosa. ¡Esta la podrás obtener de las almejas, por supuesto!\n\n20 piezas de queso cheddar curado bueno. ¡Podrás encontrarlo en cualquier quesería!\n\nConsigue todo lo que Dirge necesita y llévaselo.", description = "¿Has oído hablar de los almejates? ¡Pues claro que no! Son mi última y exquisita creación culinaria. ¡Ay, <nombre>, solo pensar en un almejate se me hace la boca agua!\n\nPor desgracia, no tengo los ingredientes necesarios para prepararte uno. ¿Qué te parece si hacemos un trato? Tú me consigues las provisiones necesarias para preparar un almejate y yo te enseño los más refinados trucos de la cocina exótica. ¡E incluso puede que te invite a un par de almejates! ¿¿¿Trato hecho???\n\nEsto es lo que necesito:", progress = "¡Ya no aguanto más! Date prisa, <nombre>, antes de que eche mano de mis propias provisiones.", completion = "¡Verás qué festín, &lt;nombre&gt;! ¡Mira y aprende!", rewards = "Aprenderás:\n\nAlmejate magnífico\n\nTe van a lanzar el siguiente hechizo:\n\nAlmejate magnífico\n\nTambién recibirás:\n\nSorpresa de almejate"}
MultiLanguageQuestData['mx'][6611] = {title = "Ve a Gadgetzan", objective = "Ve a Gadgetzan, en el Desierto de Tanaris, y habla con Dirge Hojágil sobre tus habilidades culinarias.", description = "¿Cómo quieres que Zamja te enseñe nada? ¡Tienes todo el mojo de cocina de Zamja y aún pides más!\n\nZamja no puede ayudar. El gordo <raza> necesita que vayas a Gadgetzan. Allí hay un goblin, Dirge. Él te ayudará, tragaldabas.\n\nCuando cocines muy bien, vuelve y enséñale a Zamja, ¿eh? Y ahora, vete.", progress = nil, completion = "&lt;Dirge escupe trozos de cuero.&gt; \n\nPuaj. \n\n&lt;Tose violentamente.&gt; \n\n¿Qué pasa? Que sepas que el cuero tiene muchas proteínas y es bajo en carbohidratos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6612] = {title = "Conozco a un tío...", objective = "Ve a Gadgetzan, en el Desierto de Tanaris, y habla con Dirge Hojágil sobre tus habilidades culinarias.|n", description = "Veo que tiés las ideas claras. La pena es que yo no te puedo decir ná.\n\nPero por suerte, conozco a un fulano, un goblin que es el mejor cocinero de tó Kalimdor.\n\nAsí que <zagal/zagala>, pallá que te tiés que ir, a Kalimdor. Vete pa Gadgetzan y habla con Dirge Hojágil, ese t'echará una mano.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6621] = {title = "El rey de los Maderiza", objective = "Coloca el estandarte de Senani en el montículo del tótem de los Maderiza. No permitas que los fúrbolgs destruyan el estandarte. Derrota al jefe Murgut y lleva el tótem de Murgut a Senani en el Refugio Brisa de Plata.", description = "Mi investigación ha dado fruto.\n\nCreo que podemos disminuir la agresividad de los fúrbolgs mediante una demostración de fuerza.\n\nLleva este estandarte un poco al noreste y colócalo en el montículo del tótem de los fúrbolgs. Intentarán destruirlo, pero defiéndelo hasta que salga su jefe, Murgut, para proteger la reputación de su tribu. Tráeme su tótem.\n\nLlama a tus compañeros, <nombre>. No es misión fácil para <un solo/una sola> <clase>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guerrera de guardia groseroMusleras de cobaltoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][6622] = {title = "Orden de gravedad", objective = "Salva a pacientes asignando vendas identificativas para atender sus heridas por orden de gravedad. Debes salvar a 15 pacientes antes de que 6 mueran a consecuencia de sus heridas.\n\n¡Ten presente el orden de prioridad! Los soldados con heridas graves mueren antes que los soldados con heridas de gravedad media. Los soldados heridos leves son los que más tardan en morir y solo hay que salvarlos DESPUÉS de identificar y atender a los soldados con heridas graves y medias.", description = "Buenos días, <doctor/doctora>. Se pondrá a prueba tu capacidad para seleccionar pacientes esta tarde. En caso de superar el examen, pasarás a formar parte de las prestigiosas filas del Dispensario de la Horda.\n\n¡Presta atención! En primer lugar hay que ocuparse de los soldados con heridas graves. Después de los que sufren heridas de gravedad media. En último lugar hay que ocuparse de los heridos leves. Debes salvar a 15 pacientes para superar este examen. Suspenderás si mueren 6 de tus pacientes en la selección.\n\nSe te facilitarán vendas de selección. Que tengas suerte, <doctor/doctora>.", progress = nil, completion = "Doctor &lt;nombre&gt;, bienvenido al Dispensario de la Horda.", rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\nVenda de paño rúnico gruesaCertificación de traumatología de la Horda"}
MultiLanguageQuestData['mx'][6623] = {title = "Dispensario de la Horda", objective = "Ve a Sentencia, en las Tierras Altas de Arathi, y habla con el doctor Gregory Victor sobre tu incorporación al Dispensario de la Horda.|n", description = "¿Eres <nombre>? Me alegra verte de nuevo.\n\n¡Tengo muy buenas noticias! Gregory Victor, el jefe médico del Dispensario de la Horda, ha solicitado personalmente que te reúnas con él en Sentencia. ¡Podría ser la oportunidad de tu vida! ¡Daría lo que fuera por poder estudiar con el gran Gregory Victor! ¡Aprovecha tú que puedes!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6624] = {title = "Orden de gravedad", objective = "Salva a pacientes asignando vendas identificativas para atender sus heridas por orden de gravedad. Debes salvar a 15 pacientes antes de que 6 mueran a consecuencia de sus heridas.\n\n¡Ten presente el orden de prioridad! Los soldados con heridas graves mueren antes que los soldados con heridas de gravedad media. Los soldados heridos leves son los que más tardan en morir y solo hay que salvarlos DESPUÉS de identificar y atender a los soldados con heridas graves y medias.", description = "Buenos días, <doctor/doctora>. Se pondrá a prueba tu capacidad para seleccionar pacientes esta tarde. En caso de superar el examen, pasarás a formar parte de las prestigiosas filas del Dispensario de la Alianza.\n\n¡Presta atención! En primer lugar hay que ocuparse de los soldados con heridas graves. Después de los que sufren heridas de gravedad media. En último lugar hay que ocuparse de los heridos leves. Debes salvar a 15 pacientes para superar este examen. Suspenderás si mueren 6 de tus pacientes en la selección.\n\nQue tengas suerte, <doctor/doctora>.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\nVenda de paño rúnico gruesaCertificación de traumatología de la Alianza"}
MultiLanguageQuestData['mx'][6625] = {title = "El Dispensario de la Alianza", objective = "Ve a Theramore, en el Marjal Revolcafango, y habla con el doctor Gustaf VanHowzen sobre tu incorporación al Dispensario de la Alianza.", description = "¿Eres <nombre>? Me alegro de conocerte.\n\n¡Tengo muy buenas noticias para ti! Gustaf VanHowzen, el jefe médico del Dispensario de la Alianza, ha solicitado personalmente que te reúnas con él en Theramore. ¡Podría ser la oportunidad de tu vida! ¡Daría lo que fuera por poder estudiar con el gran Gustaf VanHowzen! ¡Aprovecha tú que puedes!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6626] = {title = "Un anfitrión del mal", objective = "Mata a 8 guardias de batalla de Rajacieno y 8 tejespinas Rajacieno y 8 cultores Caramuerte y ve a ver a Myriam Lunacanta cerca de la entrada a Zahúrda Rajacieno.", description = "Los Renegados no son contagiosos, por así decir. Al parecer, este enviado promete la no-muerte a quien se una a él. Creo que pertenece a la Plaga.\n\nAunque ahora no me preocupa él, sino la gente arracimada a su alrededor. Salen día a día de las sombras, suplicándole más poder.\n\nNo puedo luchar contra ellos sin ayuda, <nombre>. ¿Qué me dices? ¿Te apetece cazar?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6629] = {title = "Mata a Grundig Nube Negra", objective = "Mata a Grundig Nube Negra y a 6 toscos Tótem Siniestro. A continuación, ve a ver a Makaba Pezuña Plana cerca del límite sureste de Espolón.|n", description = "<nombre>, has hecho un buen trabajo matando a esos Tótem Siniestro. Si te atreves, Grundig Nube Negra y su banda personal de toscos son, con diferencia, los peores de todos. Él fue quien lideró el ataque contra mi aldea.\n\nLe encontrarás en el Poblado Tótem Siniestro, un poco más adelante del camino, hacia el oeste. Mátale y te lo agradeceré eternamente.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6641] = {title = "Vorsha la Azotadora", objective = "Derrota a Vorsha la Azotadora.", description = "Vorsha la Azotadora... la monstruosa hidra que recorre los mares...\n\nHa atacado nuestra avanzada, sin que nadie la provoque, arrasando allá por donde pasa.\n\nPero estoy listo, <nombre>. Me he preparado para vencer a la hidra y poner fin a estos ataques sobre Zoram'gar.\n\nLos nagas honran la malvada naturaleza de este monstruo con un blandón que permanece encendido en una isla a escasa distancia de la costa. Creo que si lo apagamos, provocaremos la ira de Vorsha y aparecerá.\n\nNecesitaremos ayuda, así que asegúrate de traer aliados fuertes contigo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAnillo de cuerno"}
MultiLanguageQuestData['mx'][6642] = {title = "El favor de la Hermandad, mena de hierro negro", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][6643] = {title = "El favor de la Hermandad, núcleos ígneos", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][6644] = {title = "El favor de la Hermandad, núcleo de lava", objective = "Hermandad del Torio, S.A. comprende tu difícil situación, <raza>. Por eso se ha autorizado a Lokthos a negociar.\n\nOfréceme 1 núcleo de lava y se te concederá el favor de la Hermandad.", description = nil, progress = "Hermandad del Torio, S.A. comprende tu difícil situación, <raza>. Por eso se ha autorizado a Lokthos a negociar.\n\nOfréceme 1 núcleo de lava y se te concederá el favor de la Hermandad.", completion = "Tu ofrenda ha sido aceptada. El favor has obtenido. Sigue así y se te permitirá el acceso a los negocios ancestrales.", rewards = nil}
MultiLanguageQuestData['mx'][6645] = {title = "El favor de la Hermandad, cuero del núcleo", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][6646] = {title = "El favor de la Hermandad, gota de sangre de la montaña", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][6661] = {title = "A por las ratas del tranvía subterráneo", objective = "Captura a 5 ratas del subterráneo usando la flauta cazarratas. Guía a las ratas hasta Monty.", description = "Alto ahí, pillastre. Eeeh... ¿Eeestás buscando curro? Nos tenemos un problemón de ratas aquí abajo y nos faltan manos en la cubierta de popa.\n\n¿Qué respondes? Solo tienes que coger esta flauta atrapa-ratas y tocar la canción alrededor de esas alimañas. ¡Te seguirán al fin del mundo!\n\nCaptúranos cinco de esos bichos y tráenoslos acá. Nos los queremos vivos.\n\nEeeh...", progress = "¡Eeeeeh! ¿Por qué estás tardando tanto?", completion = "Fantástico, nos gustan. Mi hermano las necesita vivitas y coleando, si no, se vuelven amargas... Y no nos gustan los kebabs de rata amargos, ¿verdad?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6662] = {title = "Mi hermano Niblis", objective = "Lleva el envase de carne misteriosa a Niblis, que está en el Depósito del Tranvía Subterráneo de Ventormenta.", description = "Mi hermano Niblis dirige una operación de kebab de rata al otro lado de la estación de Ventormenta. Tú le llevas este envase de carne misteriosa a él, antes de que se estropeen. ¡Venga, en marcha, tú!\n\nHas viajado antes en tren, ¿no? Es fácil. Cuando llega, te subes a bordo y disfrutas del trayecto. Eso sí, brazos y piernas dentro durante el viaje, si no quieres lisiarte de por vida.", progress = "<Niblis mete el índice por uno de los agujeros del cartón.>\n\nVivitas y coleando... ¡y justo a tiempo!", completion = "Pobre Monty. Desde el incidente de Gnomeregan, no ha vuelto a ser el mismo. Ese chico no ha visto el océano en su vida y nunca ha sido pirata, claro. \n\n&lt;Niblis suspira.&gt; \n\nAl menos se ocupa de que sigan entrando criaturejas.", rewards = "Recibirás:\n\nKebab de rata del subterráneo"}
MultiLanguageQuestData['mx'][6681] = {title = "Mansión Ravenholdt", objective = "Lleva el Sello de Ravenholdt a Fahrad, que está en la Mansión Ravenholdt, en las colinas de Trabalomas.\n\nTendrás que poner a prueba tu ingenio por el camino. Ándate con ojo.", description = "<nombre>,\n\nRavenholdt se ha interesado por ti, maleante. Hemos estado observando. Tu estilo es un poco torpe, pero se puede arreglar.\n\nSi deseas aprender del maestro Ravenholdt y ser miembro de la liga de Asesinos, tienes que llevar el Sello de Ravenholdt, incluido en esta carta, a la Mansión Ravenholdt.\n\nTu primera prueba es encontrar la mansión, que está escondida en las colinas de Trabalomas.\n\nSaludos,\n\nFahradRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6762] = {title = "Rabine Saturna", objective = "Ve a Claro de la Luna, al poblado Amparo de la Noche y habla con Rabine Saturna. Claro de la Luna se encuentra entre Frondavil y Cuna del Invierno; para llegar, tienes que seguir el camino que sale del Bastión Fauces de Madera.", description = "El mayordomo del guardián Remulos, Rabine Saturna, está en Claro de la Luna buscando ayuda para explorar los vastos páramos al oeste de Tanaris e incluso más al oeste de Un'Goro. Podrás encontrarlo en Amparo de la Noche, la aldea más grande de Claro de la Luna.\n\nAunque tu trabajo será sin duda un beneficio tremendo para todos, te aconsejo que vayas con cuidado. Entre Darnassus y Claro de la Luna hay ciertas tensiones que... podrían crecer a lo largo del tiempo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6781] = {title = "Más restos de armadura", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][6801] = {title = "Lokholar, el Señor del Hielo", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][6804] = {title = "Agua envenenada", objective = "Aplica el aspecto de Neptulon a los elementales infectados de las Tierras de la Peste del Este. Lleva 12 de sus brazales discordantes y el aspecto de Neptulon al duque Hydraxis a Azshara.", description = "Una fuerza de exploradores elementales enviada a las Tierras de la Peste del Este de Lordaeron fue apestada por la corrupción del lugar. ¡Los Señores del Agua no podemos tolerar este insulto a nuestra pureza!\n\nToma este frasco. Contiene un aspecto de Neptulon. Eliminará el veneno de los elementales apestados. Pero el conflicto interno les conducirá a una enajenación transitoria.\n\nDomina a los descontrolados y tráeme sus brazales de vínculo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6805] = {title = "Sirocosos y reptarenas", objective = "Acaba con 15 agitadores sirocosos y 15 estruendores del desierto. Después, regresa con el duque Hydraxis en Azshara.", description = "Nosotros, los elementales del agua, estamos en guerra con los seres de los elementos menores. ¡Demuestra que estás de nuestra parte!\n\nMuy lejos hacia el sur, en el desierto de Silithus, viven los siervos del aire y la tierra, en un pedazo de roca llamado La Vega de Cristal. Protegen objetos de poder frente a seres inferiores, mortales, y aunque ignoro por qué lo hacen, deseo contrariarlos.\n\nVe a La Vega de Cristal, en Silithus, y derrota a nuestros enemigos. Después vuelve a verme.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6821] = {title = "Ojo del Brasadivino", objective = "Lleva el ojo del Brasadivino al duque Hydraxis a Azshara.", description = "Has demostrado que puedes derrotar a nuestros enemigos y encargarte de misiones para la causa de los Señores del Agua. Pero hasta ahora solo te has enfrentado a enemigos menores... ¿Podrás vencer a un enemigo más poderoso?\n\nEsa es tu nueva misión.\n\nLos orcos han apresado a un siervo del fuego, el Piroguardián Brasadivino, en Cumbre de Roca Negra. Encuentra dónde lo tienen cautivo, mata a sus captores y luego al piroguardián. Tráeme su ojo; me mostrará tu valor.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6822] = {title = "El Núcleo de Magma", objective = "Mata a 1 señor del Fuego, 1 gigante fundido, 1 can del Núcleo anciano y 1 marea de lava y ve a ver al duque Hydraxis a Azshara.", description = "<nombre>, ha llegado el momento de ponerte a prueba de verdad. ¿Te atreves?\n\nHay un pasaje al Núcleo de Magma en lo más hondo de las Profundidades de Roca Negra. Es un bastión del enemigo, defendido por los siervos del fuego más fuertes de este mundo.\n\n<nombre>, ve al Núcleo de Magma y demuéstrame que tienes fuerza y determinación para vencer a lo que te encuentres allí.\n\nSi tienes algún aliado, llévalo contigo. Para salir con vida del Núcleo de Magma necesitarás todo un ejército.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6824] = {title = "Las manos de los enemigos", objective = "Lleva las manos de Lucifron, Sulfuron, Gehennas y Shazzrah al duque Hydraxis a Azshara.", description = "<nombre>, te tenemos en alta estima. Por eso nos resistimos a enviarte a esta última misión; no queremos perder a alguien tan útil como tú.\n\nPero si tienes éxito, la ayuda a nuestro esfuerzo de guerra sería tan grande que merece la pena arriesgar tu vida.\n\nDebes ir al Núcleo de Magma y asesinar a estos capitanes: Lucifron, Sulfuron, Gehennas y Shazzrah. ¡Mátalos y tráeme sus manos!\n\nEsta misión exigirá toda tu capacidad, <nombre>, pero si lo consigues asestarás un terrible golpe a los señores del Fuego.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
