MultiLanguageQuestData['mx'][6826] = {title = "La llamada del aire: flota de Jeztor", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][6827] = {title = "La llamada del aire: flota de Mulverick", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][6861] = {title = "La unidad trituradora portátil de Zinfizzlex", objective = "El maestro ingeniero Zinfizzlex quiere que le lleves lo siguiente:\n\n*30 barras de torio.\n\n*50 barras de mitril.\n\n*75 barras de hierro.\n\n*1 sierra de vapor.|n", description = "Estoy tan ansioso como tú por probar mi nueva trituradora, <raza>, pero antes de que pueda fabricarla, voy a necesitar materiales, ¡muchos materiales!\n\nPara ser exactos, voy a necesitar una montaña de torio, mitril y hierro. También necesitaré una sierra de vapor por unidad. Tendrás que conseguirlas en la serrería.\n\nCuando estaba curioseando por aquí (antes de mi captura) me fijé en una pila de sierras de vapor en el aserradero Pico Tormenta.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][6862] = {title = "La unidad trituradora portátil de Zinfizzlex", objective = "El maestro ingeniero Zinfizzlex quiere que le lleves lo siguiente:\n\n*30 barras de torio.\n\n*50 barras de mitril.\n\n*75 barras de hierro.\n\n*1 sierra de vapor.|n", description = "Estoy tan ansioso como tú por probar mi nueva trituradora, <raza>, pero antes de que pueda fabricarla, voy a necesitar materiales, ¡muchos materiales!\n\nPara ser exactos, voy a necesitar una montaña de torio, mitril y hierro. También necesitaré una sierra de vapor por unidad. Tendrás que conseguirlas en la serrería.\n\nCuando estaba curioseando por aquí (antes de mi captura) me fijé en una pila de sierras de vapor en el aserradero Lobo Gélido.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][6881] = {title = "Ivus, el Señor del Bosque", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][6921] = {title = "Entre ruinas", objective = "Llévale el núcleo de las profundidades a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno.", description = "El Martillo Crepuscular se ha trasladado a las ruinas del Santuario Lunar de las Cavernas de Brazanegra. Su presencia solo puede servir para forzar a los elementos a actuar contra nosotros. Si no nos ocupamos de ella, esta región caerá en sus manos definitivamente.\n\n<nombre>, dirígete a Brazanegra y encuentra la piedra de las profundidades en las ruinas; debería estar cerca, en el agua. En su interior hay un núcleo de las profundidades, un dispositivo que cuando se lee correctamente, revela la historia de toda actividad elemental. Si lo consigo, y con la ayuda de los miembros del Anillo de la Tierra, ¡quizás podamos detenerlos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6922] = {title = "Barón Aquanis", objective = "Llévale el extraño globo de agua a Je'neu Sancrea en las Cavernas de Brazanegra.", description = "El elemental de agua derrotado ha dejado tras de sí un extraño globo de agua. Supones que el objeto de alguna forma alimentaba la energía de la bestia. En el interior del globo chapotea masa líquida repulsiva. El propio globo parece impermeable a todo tipo de fuerza física.\n\nSi alguien es capaz de interpretar este artilugio, es Je'neu Sancrea del Anillo de la Tierra.", progress = "Eh, hola otra vez, <nombre>. Yo por aquí, leyendo las olas del mar, lo de siempre, vamos. ¿Qué te trae hasta mí?", completion = "Esto... esto es un hallazgo, &lt;nombre&gt;.\n\n¿Y dices que lo conseguiste del barón Aquanis en Brazanegra? Hace tiempo que se cree que el barón Aquanis es un poder elemental corrupto; este globo demostrará qué fue exactamente lo que lo corrompió. Aunque no nos sorprendería que resultara ser el Martillo Crepuscular, nuestros estudios revelarán también cómo lo hicieron.\n\nHas hecho bien en traerme esto. Te lo ruego, llévale esto junto con los mejores deseos del Anillo de la Tierra.", rewards = "Sable de forajidoPodrás elegir una de estas recompensas:\n\nDedo de bruja\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][6941] = {title = "La llamada del aire: la flota de Vipore", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][6942] = {title = "La llamada del aire: la flota de Slidore", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][6943] = {title = "La llamada del aire: la flota de Ichman", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][6961] = {title = "¡El Gran Padre Invierno está aquí!", objective = "Habla con el Gran Padre Invierno. Lo encontrarás cerca de la zona de comercio de los Pastos de Bosquehumeante, en Orgrimmar.", description = "¡Feliz Festival de Invierno! ¡No dejes de saludar al Gran Padre Invierno! Si te has portado bien, recibirás regalos magníficos el día del festín del Festival de Invierno. ¡No te olvides de decirle lo que quieres!\n\nY asegúrate de tener regalitos para los que se han portado bien. Disponemos de una estupenda selección. De la granja a la mesa, ¡todo lo bueno de los Pastos de Bosquehumeante!", progress = nil, completion = "Hola, hola. Soy el Gran Padre Invierno y quiero desearte un maravilloso Festival de Invierno por cortesía de Pastos de Bosquehumeante... \"De la granja a la mesa, todo lo bueno de los Pastos de Bosquehumeante\".\n\nSi te has portado bien este año, quizás recibas regalos de los Pastos de Bosquehumeante durante el festín del Festival de Invierno. ¿A que es genial?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6962] = {title = "Golosinas para el Gran Padre Invierno", objective = "Lleva 5 galletas de jengibre y leche fría como el hielo al Gran Padre Invierno en Orgrimmar.", description = "¿Puedes hacerle un favor al Gran Padre Invierno, eh, mi <niño/niña>?\n\nNo es que me guste hablar de mí mismo en tercera persona, pero el Gran Padre Invierno ha trabajado todo el día y se merece un regalito. Unas galletitas de jengibre y un vaso de leche fresquita me irían de perlas. Sé <un buen amigo/una buena amiga> del Gran Padre y tráele algo para picar, anda.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCaja con obsequio de Pastos de Bosquehumeante"}
MultiLanguageQuestData['mx'][6963] = {title = "El robo de las golosinas del Festival de Invierno", objective = "Localiza al agente de Pastos de Bosquehumeante desaparecido en las zonas nevadas de las Laderas de Trabalomas.", description = "Oye, no es por fastidiarte la fiesta, pero Pastos de Bosquehumeante necesita la ayuda de alguien con temperamento aventurero.\n\nHemos perdido una importante carga de regalitos para la temporada, ¡y ahora hemos perdido al agente de Pastos de Bosquehumeante que había ido a investigar qué pasa! La última vez que se vio la carga fue en las Montañas de Alterac y allí es donde fue nuestro hombre.\n\n¡Ve a ver si los encuentras sanos y salvos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6964] = {title = "El espíritu de esta fiesta", objective = "Habla con Sagorne Zanca Cresta en el Valle de la Sabiduría de Orgrimmar sobre el festín del Festival de Invierno.", description = "Regalos, golosinas, felicitaciones... ¡Bah!\n\nEsos goblins ensucian el verdadero sentido del festín del Festival de Invierno. Es una época de renovación, en la que la tierra descansa bajo el manto de nieve tendido por el Gran Padre Invierno, ¡que NO es ese idiota del trajecito rojo!\n\nSi quieres saber el verdadero significado de la fiesta, ve a hablar con Sagorne Zanca Cresta. Seguro que le sorprende que alguien se interese por la historia en vez de por los regalos.", progress = nil, completion = "¿El festín del Festival de Invierno? Por desgracia, con el tiempo ha ido perdiendo significado para los tauren. \n\nDebo decir que comparto el disgusto de Furmund; para él y su grupo, el pasado es como un pendón de guerra. A mí me parece bien que haya festejos, pero sin olvidar el verdadero espíritu del Festival.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6981] = {title = "El fragmento resplandeciente", objective = "Viaja a Trinquete y busca a alguien que pueda decirte algo más sobre el fragmento resplandeciente.\n\nEntrega el fragmento como se te indique.", description = "El fragmento es verde y brillante y, aunque sólido, parece que hubiera humo arremolinándose bajo su superficie. No se puede evitar perder la mirada en las profundidades del cristal y, al mismo tiempo, uno sabe que hay algo muy desconcertante.\n\nQuizás deberías ir a ver si alguien de Trinquete puede decirte algo más sobre este extraño fragmento.", progress = "Hola, <raza>. ¿Qué puedo hacer por ti?", completion = "Oh... Nunca había visto algo así...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6982] = {title = "Suministros de Dentefrío", objective = "Lleva 10 suministros de Dentefrío al intendente de la Alianza en Dun Baldar.", description = "Mina Dentefrío es un almacén de la Horda. No puedo tragar la comida que les dan a sus soldados ¡y el estado de sus armas y armaduras es lamentable! Pero... en tiempos como estos cuando los suministros son tan importantes, podemos arreglarnos con lo que tienen.\n\nEntra en Mina Dentefrío y tráeme sus suministros. Eso mantendrá a la Alianza en condiciones para el combate y privará a los guerreros de la Horda de un equipamiento de lo más necesario.\n\nSuerte, <nombre>. La mina está lejos al sur, en lo más profundo del territorio de la Horda.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][6983] = {title = "¡Qué ruin!", objective = "Recupera los dulces robados y libera a Metzen el Reno después de derrotar a Grinch, el Abominable, que se esconde cerca de la Caverna Estrecha en las Laderas de Trabalomas.", description = "Una c-c-criatura llamada \"Grinch el Abominable\" es el q-q-que ha robado nuestro envío de d-d-dulces, <nombre>. ¡Y ten c-c-cuidado! ¡Es m-m-malvado y tiene a un p-p-puñado de gnomos verdes a su s-s-servicio!\n\nVas a n-n-necesitar ayuda p-p-para enfrentarte a él. ¡Se rumorea que t-t-tiene nuestros d-d-dulces y a nuestro q-q-querido Metzen el Reno en la Caverna Estrecha, en las Laderas de Trabalomas! Encuentra los d-d-dulces, <nombre>, ¡tráelos de vuelta antes de q-q-que se arruine la fiesta y los n-n-niños de Orgrimmar se decepcionen!", progress = "¡<nombre>, nuestro festín del Festival de Invierno será un desastre sin esos dulces que hay que reponer! El propio Graccu no podrá compartir sus deliciosas empanadas de carne con todos los niños y niñas esta temporada...", completion = "¡Lo encontraste! ¡Has salvado el Festival de Invierno de los Pastos de Bosquehumeante!\n\n¡Eres un auténtico héroe para todos los habitantes de Bosquehumeante y, desde luego, para todos los niños!", rewards = "Recibirás:\n\nRegalo robado"}
MultiLanguageQuestData['mx'][6984] = {title = "Un agradecimiento de Pastos de Bosquehumeante", objective = "Habla con el Gran Padre Invierno en Orgrimmar.", description = "Pastos de Bosquehumeante te agradece que hayas recuperado los dulces robados, <nombre>. Queremos ofrecerte un obsequio muy especial, ¡de manos del propio Gran Padre Invierno!\n\nHabla con él; te dará nuestro obsequio. De la granja a la mesa: ¡deliciosos manjares de Pastos de Bosquehumeante... y todo gracias a ti!", progress = nil, completion = "¡Saludos!\n\nLos goblins me han dicho que te has ganado un regalito especial. Aquí tienes. ¡Feliz Festival de Invierno!", rewards = "Recibirás:\n\nObsequio especial de Pastos de Bosquehumeante"}
MultiLanguageQuestData['mx'][6985] = {title = "Suministros de Ferrohondo", objective = "Lleva 10 suministros de Ferrohondo al intendente de la Horda en el Bastión Lobo Gélido.", description = "Los enanos Pico Tormenta están usando Mina Ferrohondo como almacén. Quiero que realices una incursión en esa mina y me traigas sus suministros. Esto recortará los recursos de los Pico Tormenta en el Valle de Alterac ¡y nos aportará un equipo de lo más necesario!\n\nPero ándate con ojo, <nombre>. Mina Ferrohondo está en lo más recóndito del territorio de la Alianza y el control de la mina cambia como las nieves de Alterac.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7002] = {title = "Arneses de pellejo de carnero", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][7003] = {title = "Gigantes reducidos", objective = "Utiliza el Ultra-reductor de Zorbin para encoger a cualquier gigante que encuentres en Feralas a un tamaño más manejable. Lleva 15 residuos de miniaturización encontrados en las versiones encogidas de los gigantes a Zorbin Hipnoviento, al embarcadero de La Costa Olvidada de Feralas.", description = "¡Voy a tener que solucionar esto de los gigantes si quiero quedarme aquí! Porque no son buenos para el negocio, ¿no te parece?\n\nHe estado trabajando en una variante del rayo reductor gnomo, pero estoy utilizando los últimos avances tecnológicos goblin para construirla. Quisiera probarla pero me gustaría evitar esos pequeños inconvenientes que tiene la fase de experimentación, como la muerte, así que me gustaría que la probaras con los gigantes de Feralas. Después de encogerlos deberías encontrar un residuo de miniaturización, ¡tráeme un poco!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nMegacercenadora de Zorbin"}
MultiLanguageQuestData['mx'][7021] = {title = "¡El Gran Padre Invierno está aquí!", objective = "Habla con el Gran Padre Invierno. Lo encontrarás cerca de la zona de comercio de los Pastos de Bosquehumeante, en Orgrimmar.", description = "¡Feliz Festival de Invierno! ¡No dejes de saludar al Gran Padre Invierno, que ahora mismo está en Orgrimmar! Si te has portado bien, recibirás regalos magníficos el día del festín del Festival de Invierno. ¡No te olvides de decirle lo que quieres!\n\nY asegúrate de tener regalitos para los que se han portado bien. Disponemos de una estupenda selección. De la granja a la mesa, ¡todo lo bueno de los Pastos de Bosquehumeante!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7024] = {title = "¡El Gran Padre Invierno está aquí!", objective = "Habla con el Gran Padre Invierno. Lo encontrarás cerca de la zona de comercio de los Pastos de Bosquehumeante, en Orgrimmar.", description = "¡Feliz Festival de Invierno! ¡No dejes de saludar al Gran Padre Invierno, que ahora mismo está en Orgrimmar! Si te has portado bien, recibirás regalos magníficos el día del festín del Festival de Invierno. ¡No te olvides de decirle lo que quieres!\n\nY asegúrate de tener regalitos para los que se han portado bien. Disponemos de una estupenda selección. De la granja a la mesa, ¡todo lo bueno de los Pastos de Bosquehumeante!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7025] = {title = "Golosinas para el Gran Padre Invierno", objective = "Lleva 5 galletas de jengibre y leche fría como el hielo al Gran Padre Invierno a Forjaz.", description = "¿Puedes hacerle un favor al Gran Padre Invierno, eh, mi <niño/niña>?\n\nNo es que me guste hablar de mí mismo en tercera persona, pero el Gran Padre Invierno ha trabajado todo el día y se merece un regalito. Unas galletitas de jengibre y un vaso de leche fresquita me irían de perlas. Sé <un buen amigo/una buena amiga> del Gran Padre y tráele algo para picar, anda.", progress = "Tanto hablar de regalitos me ha dado hambre. Mmm, me encantarían unas galletas de jengibre y un vaso de leche...", completion = "Muchas gracias por ayudar al Gran Padre Invierno, &lt;nombre&gt;. Te deseo un feliz Festival de Invierno. \n\nTen, una cosita para agradecerte el favor.", rewards = "Recibirás:\n\nCaja con obsequio de Pastos de Bosquehumeante"}
MultiLanguageQuestData['mx'][7026] = {title = "Arneses de pellejo de carnero", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][7028] = {title = "Los males de Maraudon", objective = "Recoge 15 tallas de cristal terádrico y llévaselas a Willow a Desolace.", description = "Las cavernas de cristal de Terramok están al oeste, en pleno corazón de Maraudon... Es un lugar antiguo y cargado de historia. Quiero una parte de esa historia, <clase>. Tras las puertas gigantes hay reliquias de los dioses antiguos.\n\nSi te atreves a enfrentarte a los males de Maraudon, te compensaré generosamente. Tráeme todas las tallas de cristal terádrico que encuentres.\n\nAsí podré... estudiarlas. Los poderes que contienen llevan demasiado tiempo dormidos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Togas de sagacidadYelmo de argollas de duendeCota de malla incansableEspaldares de mole de piedraRecibirás:\n\n"}
MultiLanguageQuestData['mx'][7029] = {title = "La corrupción de Lenguavil", objective = "Llena el vial cerúleo cubierto en el estanque naranja de Maraudon. \n\nAplica el vial cerúleo lleno a la hiedravil para que emerja el sucesor tóxico. \n\nCura 8 plantas eliminando su sucesor tóxico e informa a Vark Marca de Guerra en la Aldea Cazasombras.", description = "Un sátiro llamado Lenguavil ha corrompido las cavernas de Maraudon y ha detenido el desarrollo de muchas de las plantas.\n\nToma este vial, <nombre>. Llénalo en el estanque de cristal naranja de las cavernas; el relleno del vial contrarrestará las toxinas y las transformará en agentes sanadores.\n\nEsparce el líquido purificado en la hiedra Tallovil de las cavernas naranja. Aunque se eliminará la corrupción de la planta, debes saber que seguirá bajo el control de Lenguavil. Puede que intente atacarte...Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Guanteletes ramazarzaFaja de arbustoPodrás elegir una de estas recompensas:\n\nAro de Semillaleña\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][7041] = {title = "La corrupción de Lenguavil", objective = "Llena el vial cerúleo cubierto en el estanque naranja de Maraudon. \n\nAplica el vial cerúleo lleno a la hiedravil para que emerja el sucesor tóxico. \n\nCura 8 plantas eliminando su sucesor tóxico e informa a Talendria en Punta de Nijel.", description = "Un sátiro llamado Lenguavil ha corrompido las cavernas de Maraudon y ha detenido el desarrollo de muchas de las plantas.\n\nToma este vial, <nombre>. Llénalo en el estanque de cristal naranja de las cavernas; el relleno del vial contrarrestará las toxinas y las transformará en agentes sanadores.\n\nEsparce el líquido purificado en la hiedravil de las cavernas naranja. Aunque se eliminará la corrupción de la planta, debes saber que seguirá bajo el control de Lenguavil. Puede que intente atacarte...Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Guanteletes ramazarzaFaja de arbustoPodrás elegir una de estas recompensas:\n\nAro de Semillaleña\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][7044] = {title = "Leyendas de Maraudon", objective = "Recupera las 2 partes del cetro de Celebras: la vara y el diamante de Celebras. \n\nEncuentra el modo de hablar con Celebras.", description = "Un siniestro sátiro llamado Lord Lenguavil extiende su maldad por estas cuevas, envenenando las mentes. Sigue viviendo detrás de los cristales morados.\n\nTambién creó un símbolo viviente de su corrupción llamado Noxxion, que vive tras los cristales naranja. Han robado las dos piezas del cetro de mi hermano. Celebras, mi hermano, ha caído víctima de la corrupción y deambula ahí dentro.\n\n¡Tienes que ayudarlo! Busca las piezas y encuentra el modo de hablar con mi hermano.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7045] = {title = "Un agradecimiento de Pastos de Bosquehumeante", objective = "Habla con el Gran Padre Invierno en Forjaz.", description = "Pastos de Bosquehumeante te agradece que hayas recuperado los dulces robados, <nombre>. Queremos ofrecerte un obsequio muy especial, ¡de manos del propio Gran Padre Invierno!\n\nHabla con él; te dará nuestro obsequio. De la granja a la mesa: ¡deliciosos manjares de Pastos de Bosquehumeante... y todo gracias a ti!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObsequio especial de Pastos de Bosquehumeante"}
MultiLanguageQuestData['mx'][7061] = {title = "El festín del Festival de Invierno", objective = "Lee el libro \"El festín del Festival de Invierno\" si quieres saber más sobre esta fiesta. Cuando termines, entrégaselo a Baine Pezuña de Sangre en Cima del Trueno.", description = "Toma. Si quieres saber más sobre el festín del Festival de Invierno, lee este libro. Opino que nuestra interpretación de la leyenda es la correcta, pero como estudiante de leyendas comprendo que es mejor que toda la información esté recopilada en una única fuente.\n\nCuando termines, llévale el libro a Baine Pezuña de Sangre en Cima del Trueno. Sé bien que le gustará saber que hay otros interesados en las antiguas leyendas.", progress = "Te doy la bienvenida a Mulgore y a Cima del Trueno. Me agrada la gente que se interesa por el reino y sus gentes. ¿Es esa la razón por la que estás aquí?", completion = "Las leyendas y la tradición del Festival de Invierno se han ido borrando de la memoria de nuestra gente con el paso de los años. Sí, sé que los goblins ayudan a revivir el Festival en su propio beneficio, pero eso al menos ayuda a que no caiga en el olvido.\n\nAdmiro tu interés en nuestra historia es un hecho admirable, joven &lt;clase&gt;. Me impresiona tu sabiduría.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7064] = {title = "Corrupción de la tierra y de la semilla", objective = "Mata a la princesa Theradras y ve a ver a Selendra cerca de la Aldea Cazasombras, en Desolace.", description = "En las profundidades de Maraudon vive una criatura de gran maldad. La princesa Theradras es una fuerza elemental de la tierra relacionada con los dioses antiguos. Hace eones se unió a Zaetar, el primogénito de Cenarius. El fruto de su relación fueron las criaturas llamadas centauros en Kalimdor. Esas criaturas mataron a Zaetar y se quedaron sus restos. Mi objetivo es encontrar a quien tenga fuerza suficiente para matar a Theradras y recuperar los restos de Zaetar antes de volver a Cima del Espolón.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "ZumbaespadaVara de resurgimientoObjetivo del vigilante verdeanteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][7065] = {title = "Corrupción de la tierra y de la semilla", objective = "Mata a la princesa Theradras y ve a ver al vigilante Marandis a Punta de Nijel, en Desolace.", description = "En las profundidades de Maraudon vive una criatura de gran maldad, <nombre>. La princesa Theradras es una fuerza elemental de la tierra relacionada con los dioses antiguos. Hace eones se unió a Zaetar, el primogénito de Cenarius. El fruto de su relación fueron las criaturas llamadas centauros. Esas criaturas mataron a Zaetar y Theradras guardó sus restos. Mi objetivo es encontrar a quien tenga fuerza suficiente para matar a Theradras y recuperar los restos de Zaetar antes de volver a Cima del Espolón.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "ZumbaespadaVara de resurgimientoObjetivo del vigilante verdeanteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][7066] = {title = "La semilla de vida", objective = "Busca a Remulos en Claro de la Luna y dale la semilla de vida.", description = "Mis hijos e hijas, los desdichados centauros, necesitan a su padre.\n\nMira: este lugar está lleno de esperanza y todas las cosas que venera mi padre, Cenarius. ¡Todo eso salió de mí! Y ahora no voy a quitárselo, ni siquiera por el crimen que cometieron contra mí.\n\nPero voy a pedirte un favor para tranquilizar a mi hermano. Toma; es la primera semilla que nació de la vida alimentada por mis restos. Dile que mi espíritu está aquí y que seguiré viviendo. Lo entenderá.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7067] = {title = "Las instrucciones del Paria", objective = "Lee las instrucciones del Paria. Busca el Amuleto de Unidad en Maraudon y llévaselo al sur de Desolace.", description = "Aunque me exiliaron por hereje, sé que digo la verdad y eso me anima a seguir adelante. Pero para completar mi destino, necesito la ayuda de alguien que no sea centauro.\n\nHay que entrar en las salas sagradas de Maraudon; mi gente protege la tumba y solo los más devotos pueden entrar.\n\nSi aceptas ayudarme, afirma con la cabeza. Te daré un papiro con instrucciones. Léelo y considera mi propuesta.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nMarca del elegido"}
MultiLanguageQuestData['mx'][7068] = {title = "Trozos Oscuros", objective = "Recoge 10 fragmentos oscuros en Maraudon y llévaselos a Uthel'nay a Orgrimmar.", description = "En Maraudon, el lugar sagrado de los centauros, se concentra una magia muy fuerte. Los centauros de Desolace protegen el lugar con su vida, pero no podrán impedir que cojamos lo que necesitemos.\n\nVe a Maraudon y encuentra a las criaturas de piedra hechas de fragmentos oscuros. Trae los cristales morados y Uthel'nay te compensará.\n\nEs un sitio peligroso, mejor llévate compañía.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nColgante de fragmento oscuro entusiastaColgante de fragmento de sombras prodigioso\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][7070] = {title = "Trozos Oscuros", objective = "Recoge 10 fragmentos oscuros en Maraudon y llévaselos al archimago Tervosh a Theramore, en la costa de Marjal Revolcafango.", description = "He empezado a hacer pruebas con las propiedades Arcanas de varios cristales. Lady Valiente me ha autorizado a pedir a los viajeros que se dirigen a Desolace que busquen un lugar llamado Maraudon. En el templo en ruinas hay grandes elementales compuestos por unas piedras moradas que llamo fragmentos oscuros.\n\nTe agradecería que te acercaras e intentaras encontrarme algún cristal. Incluso podría fabricarte un adorno con ellos, si quieres.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nColgante de fragmento oscuro entusiastaColgante de fragmento de sombras prodigioso\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][7081] = {title = "Los cementerios del Valle de Alterac", objective = "Asalta un cementerio y vuelve con el sargento Durgen Pico Tormenta en las Montañas de Alterac.", description = "Los cementerios del Valle de Alterac están muy codiciados. Tanto la Horda como la Alianza luchan encarnizadamente por este suelo sagrado. ¿<nombre>, estás <dispuesto/dispuesta> a unirte a la lucha?\n\nQuiero que asaltes un cementerio enemigo. Encuentra un cementerio con un estandarte de la Horda ¡y arráncalo del suelo! Hazlo y habrás completado tu tarea...\n\nPero si además puedes resistir en el cementerio durante unos minutos, nuestros soldados vendrán pronto a apoyarte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7082] = {title = "Los cementerios de Alterac", objective = "Asalta un cementerio y vuelve con el cabo Teeka Gruñido Sangriento en las Montañas de Alterac.", description = "Las líneas del frente en el Valle de Alterac cambian constantemente. Los límites del territorio avanzan y retroceden conforme nos enfrentamos a nuestros adversarios en combate mortal. Y es en los cementerios, <nombre>, donde se libran las batallas más encarnizadas.\n\n¡Quiero que asaltes un cementerio en manos de la Alianza! Encuentra un cementerio con un estandarte de la Alianza y arráncalo del suelo.\n\nHazlo y habrás completado tu tarea... pero si además puedes resistir en el cementerio durante unos minutos, será nuestro y nuestros soldados vendrán pronto a relevarte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7101] = {title = "Las torres y los búnkeres", objective = "Captura una torre enemiga y vuelve con el cabo Teeka Gruñido Sangriento en las Montañas de Alterac.", description = "Las torres y los búnkeres son posiciones importantes ¡y debemos capturarlas y hacernos con el control de todas! Por eso quiero que captures un búnker controlado por el enemigo.\n\nPara ello, fíjate donde haya un estandarte de la Alianza. En el interior verás otro estandarte. Saca ese estandarte y en su lugar aparecerá uno de la Horda. ¡Muy bien!\n\nEn ese momento habrás completado tu misión, pero si además puedes resistir en la posición lo suficiente sin que la Alianza lo recupere ¡será destruida!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7102] = {title = "Las torres y los búnkeres", objective = "Destruye el estandarte de una torre enemiga o de un búnker y vuelve junto al sargento Durgen Pico Tormenta en las Montañas de Alterac.", description = "Las torres y los búnkeres son posiciones defensivas clave ¡y debemos controlar tantas como sea posible! Quiero que ataques una torre o un búnker en el Valle de Alterac.\n\nPara ello, entra en una torre donde veas un estandarte de la Horda en la parte superior. En el interior verás otro estandarte enemigo. Saca ese estandarte y en su lugar aparecerá uno de la Alianza. ¡Muy bien!\n\nEn ese momento habrás completado tu misión, si además puedes resistir en la posición lo suficiente sin que la Horda lo recupere ¡será destruida!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7121] = {title = "El intendente", objective = "Habla con el intendente Pico Tormenta.", description = "<nombre>, nuestro intendente me ha encargado que le mande a los nuevos reclutas. Necesita suministros de los alijos ocultos en las minas de Alterac y probablemente te envíe para recuperarlos.\n\nSigue la carretera. Encontrarás a nuestro intendente al oeste.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7122] = {title = "Capturar una mina", objective = "Captura una mina que no esté bajo control de los Pico Tormenta y vuelve junto al sargento Durgen Pico Tormenta en las Montañas de Alterac.", description = "Las minas del Valle de Alterac contienen algo más que minerales. Tanto los Lobo Gélido como los Pico Tormenta tienen alijos con suministros extras en las minas de Ferro Hondo y Mina Dentefrío... una buena idea, ¡ojalá logremos hacernos con su control!\n\nToma posesión de una mina y tráemelos. Para capturar una mina, penetra en una que no controlemos y mata a su líder. Cuando lo hagas la mina será nuestra ¡y mandaremos soldados para proteger la posición!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7123] = {title = "Habla con nuestro intendente", objective = "Habla con el intendente de Lobo Gélido.", description = "<nombre>, el intendente de los Lobo Gélido está buscando reclutas para tareas que llevan a las minas del Valle de Alterac. Habla con él, te contará más detalles.\n\nSigue la carretera hacia el oeste hasta el búnker, toma entonces la salida del oeste y encontrarás a nuestro intendente.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7124] = {title = "Capturar una mina", objective = "Captura una mina y vuelve con el cabo Teeka Gruñido Sangriento en las Montañas de Alterac.", description = "Mientras se libra una encarnizada batalla en el Valle de Alterac, también hay enfrentamientos en Mina Dentefrío y en Mina Ferrohondo. Ambas contienen minerales en abundancia y se utilizan además para almacenar suministros; ¡es normal que se codicien tanto!\n\n¡Únete a nuestro movimiento bélico, <nombre>! ¡Captura una de las minas para la Horda! Para capturar una mina, penetra en una que no controlemos y mata a su líder. Cuando lo hagas la mina será nuestra ¡y mandaremos soldados para proteger la posición!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7141] = {title = "La batalla de Alterac", objective = "Adéntrate en el Valle de Alterac, derrota al general Drek'thar de la Horda y vuelve junto a la prospectora Tallapiedra en las Montañas de Alterac.", description = "La Liga de Expedicionarios cree que hay artefactos en el Valle de Alterac pero los orcos Lobo Gélido no nos dejan explorarlo. ¡No podemos permitir que la Horda se interponga en nuestros objetivos de erudición! Derrota al general Lobo Gélido, Drek'Thar. Con él muerto, los orcos perderán su ventaja.\n\nDrek'Thar se encuentra en el Bastión Lobo Gélido, al sur del Valle de Alterac. Véncelo y tráemelo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7142] = {title = "La batalla por Alterac", objective = "Adéntrate en el Valle de Alterac y derrota al general enano Vanndar Pico Tormenta. Vuelve entonces junto a Voggah Agarre Letal en las Montañas de Alterac.", description = "Los enanos Pico Tormenta y sus aliados han invadido el Valle de Alterac ¡y tenemos que expulsarlos! Para ganar la batalla de Alterac, tenemos que derrotar a su general, Vanndar Pico Tormenta!\n\nEncontrarás a Vanndar en Dun Baldar, al norte del Valle de Alterac.\n\nDestrúyelo, <nombre>, y vuelve aquí.", progress = nil, completion = "¡Muy bien, &lt;nombre&gt;! Los Pico Tormenta no tienen ninguna posibilidad en esta insensata invasión.\n\n¡Ja! Hasta ahora, ¡solo han conseguido que maten a su general!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7161] = {title = "Terreno de Pruebas", objective = "Viaja hasta la caverna Zarpa Salvaje, al sureste del campamento base en el Valle de Alterac y encuentra el estandarte Lobo Gélido. Devuélveselo al maestro de guerra Laggrond.", description = "Salve, <clase>. Mucho tiempo ha pasado desde que hemos tenido la oportunidad de responder a la llamada de la batalla. Los antiguos sentimientos tardan en emerger pero una vez despiertos, la sangre fluye cual torrente. La furia de la batalla vuelve...\n\nLos recién llegados al valle deben completar primero el rito de la batalla.\n\nEn lo más profundo de la cueva gnoll de Zarpa Salvaje se encuentra un estandarte de Lobo Gélido. Adéntrate hasta ese lugar y recupera el estandarte. Devuélvemelo y te concederé una insignia de Iniciado de los Lobo Gélido.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nInsignia Lobo Gélido Rango 1Pelar la cebolla"}
MultiLanguageQuestData['mx'][7162] = {title = "Terreno de Pruebas", objective = "Viaja hasta la cueva Ala Gélida ubicada al suroeste de Dun Baldar en el Valle de Alterac y recupera el estandarte Pico Tormenta. Devuélveselo al teniente Haggerdin en las Montañas de Alterac.", description = "Has llegado justo a tiempo, <clase>. ¡Estos salvajes Lobo Gélido no se rinden! Tenemos que demostrarles el poder de los Pico Tormenta. Deben inclinarse ante nuestra superioridad.\n\nAntes de que te dirijas al campo de batalla, deberías unirte a las filas de los Pico Tormenta.\n\nAl suroeste de Dun Baldar encontrarás la Cueva Ala Gélida. En lo más profundo de las cavernas hay clavado un estandarte Pico Tormenta. Adéntrate hasta ese lugar y recupera ese estandarte. Devuélvemelo y te ganarás una insignia de Iniciado de los Pico Tormenta.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nInsignia Pico Tormenta Rango 1La alcachofa Lobo Gélido"}
MultiLanguageQuestData['mx'][7163] = {title = "Ascender y darse a conocer", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nInsignia Lobo Gélido Rango 2"}
MultiLanguageQuestData['mx'][7164] = {title = "Honorable con el clan", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nInsignia Lobo Gélido Rango 3"}
MultiLanguageQuestData['mx'][7181] = {title = "La leyenda de Korrak", objective = "Según cuenta la leyenda, el jefe de los poderosos trols Hacha Invernal parece dispuesto a sembrar el caos entre los habitantes del Valle de Alterac.\n\nSi Korrak se digna aparecer, destrúyelo y vuelve con el maestro de guerra Laggrond.", description = "Los invasores Pico Tormenta no son la única amenaza de la región, soldado. La guerra en el valle se está librando en dos frentes. Los trols caníbales Hacha Invernal también rivalizan por el poder.\n\nSu líder es Korrak el Sanguinario, una cruel y taimada fiera.\n\nUn buen golpe sobre Korrak podría ser aplastante para el clan Hacha Invernal. Ejecuta a la fiera ¡y recibirás tu recompensa!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7201] = {title = "El último elemento", objective = "Viaja a las Profundidades de Roca Negra y recupera 10 esencias de los elementos. Tu primer impulso es buscar los gólems y a los creadores de gólems. Recuerdas que Vivian Lagrave también murmuró entre dientes algo sobre los elementales.|n", description = "Hay trabajo a mansalva para quien se aventure en las profundidades, <nombre>.\n\nLos Hierro Negro han perfeccionado la creación de gólems extremadamente poderosos.\n\nLos primeros informes de nuestros espías indican que los enanos usan una fuente de poder única para conferir a sus creaciones una potencia destructora sin igual.\n\n¡Tan solo imagínate lo que podríamos hacer con nuestras abominaciones si nos hiciéramos con esta esencia de los elementos! No dejes piedra por remover en esa ciudad si es necesario, ¡pero no vuelvas hasta haber encontrado la esencia! Recibirás un justo pago por el riesgo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de Lagrave"}
MultiLanguageQuestData['mx'][7202] = {title = "Korrak el Sanguinario", objective = "Según cuenta la leyenda, el jefe de los poderosos trols Hacha Invernal parece dispuesto a sembrar el caos entre los habitantes del Valle de Alterac.\n\nSi Korrak se digna aparecer, destrúyelo y vuelve con el teniente Haggerdin en las Montañas de Alterac.", description = "Los trols indígenas Hacha Invernal de esa región son salvajes despiadados a los que nada complacería más que añadir nuestros huesos a su hediondo estofado.\n\n¡Debemos demostrarles nuestro poder!\n\nHemos recuperado unos libros de sus cuevas donde se describe su jerarquía de poder. Los artefactos apuntan a que su líder, Korrak el Sanguinario, tiende a permanecer oculto hasta que surge un motivo para manifestarse.\n\n¡La muerte de Korrak significaría el fin del clan Hacha Invernal! Mátalo y vuelve aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7223] = {title = "Los restos de armadura", objective = "Llévale 20 restos de armadura a Murgot Forjahonda en Dun Baldar.", description = "La batalla es encarnizada en el Valle de Alterac y los suministros que conseguimos de Forjaz no bastan para vestir a nuestros expertos soldados.\n\nSi encuentras restos de armadura en el campo de batalla, ¡contribuye a nuestro esfuerzo bélico y tráemelos!Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nArmadura pulida\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][7224] = {title = "Botín enemigo", objective = "Llévale 20 restos de armadura al herrero Regzar en Aldea Lobo Gélido.", description = "Cuando te enfrentes al enemigo, reúne los restos de sus armaduras y tráemelos. ¡Los usaré para hacer armaduras para nuestros soldados!Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nArmadura pulida\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][7241] = {title = "En defensa de Lobo Gélido", objective = "Dirígete al Valle de Alterac en las Montañas de Alterac. Encuentra al maestro de guerra Laggrond y habla con él para empezar tu carrera como soldado Lobo Gélido; lo encontrarás en la entrada del túnel. El Valle de Alterac se sitúa al norte de Molino Tarren en la falda de las Montañas de Alterac.", description = "Retumban los tambores de guerra en una tierra distante, <clase>. La abominable guardia de los Pico Tormenta de Forjaz está atacando al clan partidario de tu Jefe de Guerra.\n\nSolo con verte, deduzco que tienes resistencia para el combate y que estás <preparado/preparada> para hacer tuya la causa de los Lobo Gélido.\n\nTú eres quien debe ahora dar el paso siguiente en tu evolución.\n\nAl norte del Molino Tarren, en Alterac, hallarás la entrada del Valle de Alterac. Allí encontrarás al maestro de guerra Laggrond. ¡Date prisa, <clase>, que la batalla está próxima!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7261] = {title = "El imperativo soberano", objective = "Dirígete al Valle de Alterac en las Laderas de Trabalomas. Delante de la entrada del túnel, encuentra al teniente Haggerdin y habla con él.\n\n¡Por la gloria de Barbabronce!", description = "Estamos librando una brutal batalla en el Valle de Alterac. El salvaje clan Lobo Gélido desafía el poder a los Pico Tormenta. ¡Deben ser exterminados en el nombre del rey Magni Barbabronce! La toma, sacrificio y devolución de esa tierra es un imperativo soberano y territorial para el Reino de Forjaz.\n\n¡Por desgracia, los soldados no crecen en los árboles! Ponte a las órdenes del teniente Haggerdin en las afueras del Valle de Alterac para empezar tu recorrido de deber y honor entre los Pico Tormenta.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7281] = {title = "Amor fraternal", objective = "Viaja hasta el territorio de los Pico Tormenta y mata al comandante Karl Filis. Vuelve con el comandante Luis Philips cuando hayas completado la tarea.|n", description = "Una tragedia... Mi hermano y yo enfrentados en el campo de batalla: un Comandante de los Pico Tormenta.\n\nDe los cuatro Comandantes de los Pico Tormenta, es sin duda alguna el más peligroso. Quizás si lo ejecutan, la reina alma en pena podría convertirlo como hizo conmigo, demostrarle cuán equivocado está...\n\nEn lo más profundo del territorio enemigo encontrarás a mi hermano. Ejecútalo y vuelve aquí. Confío en que serás capaz de cumplir esta misión, soldado.\n\nAh, soldado, no vayas en solitario.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7282] = {title = "Amor fraternal", objective = "Viaja hasta el territorio de los Lobo Gélido y mata al comandante Luis Philips Vuelve con el comandante Karl Filis cuando hayas completado la tarea.|n", description = "¡Hay que acabar con su sufrimiento, soldado! No sabe lo que hace Se ha convertido en un sirviente ciego de la temida reina alma en pena.\n\nRealiza una incursión por la Tierra de Disputa y hasta lo más recóndito del territorio de los Lobo Gélido. Encuentra a mi hermano y acaba con él. Hay que poner fin a su tormento.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7301] = {title = "Señores del Cielo caídos", objective = "Viaja hasta el territorio de los Lobo Gélido y busca al Comandante del aire Slidore, al comandante del aire Vipore y al comandante del aire Ichman. Vuelve con el comandante Duffy cuando hayas completado la misión.", description = "Los tenemos prisioneros, <raza>. Me refiero a sus Comandantes del aire. Fue una batalla encarnizada en los cielos pero ¡al final cayeron! Desgraciadamente, abatieron a nuestros mejores pilotos en un contraataque sobre el Bastión Lobo Gélido. Tienes que averiguar qué ha sido de ellos.\n\nBusca al oeste de Torre de la Punta y por el Bastión Lobo Gélido. Allí es donde se les vio por última vez. No dejes piedra por remover en estas zonas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7302] = {title = "Señores del Cielo caídos", objective = "Averigua qué fue del comandante del aire Guse, el Comandante del aire Jeztor y el comandante del aire Mulverick. Vuelve con el comandante Mulfort cuando hayas completado la misión.", description = "Nuestro apoyo aéreo es un caos, <nombre>. Han abatido a los Comandantes del aire sobre territorio enemigo. ¡Tienes que averiguar qué ha sido de ellos para que podamos intentar rescatarlos!\n\nSe vio por última vez a Guse sobrevolando el Búnker Ala Gélida. Al alas de guerra de Jeztor se le avistó cerca de la Serrería Pico Tormenta. Mulverick... ese chalado temerario se estrelló cerca del Búnker Norte de Dun'Baldar.\n\nEso es todo lo que sé. ¡Vamos! No dejes piedra por remover en estas zonas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7321] = {title = "opa de tortuga reconfortante", objective = "Llévale 10 trozos de carne de tortuga a Christoph Jeffcoat a Molino Tarren.", description = "¿Quién dijo que los no-muertos no tenemos ni idea de cocinar? Mira mi receta secreta de sopa de tortuga, por ejemplo. ¡Sé de algunos que incluso se levantarían de su tumba solo para probarla! Je, je...\n\nPor cierto, hace mucho que no la hago. Antes solía ir yo mismo al Lago Lordamere a cazar Quijafortes, esas cosas repelentes, pero ahora no puedo dejar mi trabajo.\n\nSi me traes carne de tortuga Quijaforte, ¡te enseñaré a prepararla!", progress = "¿Has encontrado los ingredientes? Debo advertirte de que los gusanos de la Alianza son muy numerosos en esta zona... En mi opinión, creo que ya están demasiado cerca...", completion = "Mi sopa de tortuga reconfortante te mantendrá caliente en una noche fría... por si te interesa saberlo.", rewards = "Recibirás:\n\nSopa de tortuga reconfortanteReceta: sopa de tortuga reconfortante"}
MultiLanguageQuestData['mx'][7341] = {title = "Un trato justo", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nEspada con punta de torio"}
MultiLanguageQuestData['mx'][7342] = {title = "Las flechas no valen para nada", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nEspada con punta de torio"}
MultiLanguageQuestData['mx'][7385] = {title = "Un galón de sangre", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][7386] = {title = "Recogida de cristal", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][7441] = {title = "Pusillín y el ancestro Azj'Tordin", objective = "Viaja a La Masacre y encuentra al diablillo Pusillín. Convence a Pusillín de que te dé el libro de Conjuros de Azj'Tordin, por cualquier medio. \n\nSi consigues hacerte con el libro de Conjuros, vuelve al Pabellón de Lariss de Feralas y busca a Azj'Tordin.", description = "Bajé la guardia un solo momento... Intentaba escapar de las garras del príncipe caído y, en la confusión... me robaron. Un ser abominable, el diablillo Pusillín, me robó el libro de Conjuros y la llave de las antaño magníficas salas de Eldre'Thalas.\n\nLa llave ya no me preocupa, pues ya cambié mi inmortalidad por la libertad, pero necesito desesperadamente mi libro de Conjuros.\n\nEncuentra a ese diablillo Pusillín y recupera mi libro.\n\nEmpieza a buscarlo en el Barrio Alabeo de La Masacre.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Espada de esprínterBotas de solturaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][7461] = {title = "Locura interior", objective = "Debes destruir a los guardianes que rodean las 5 torres que controlan la Prisión de Immol'thar. Una vez desactivadas las torres, el campo de fuerza que rodea a Immol'thar se disipará. \n\nEntra en la Prisión de Immol'thar y erradica al demonio que hace guardia en su interior. Por último, haz frente al príncipe Tortheldrin en El Athenaeum. \n\nSi consigues completar esta misión, ve al patio a buscar a la ancestro Shen'dralar.", description = "¿Has oído suficiente? ¿Eres <un hombre/una mujer> de acción?\n\nEsta locura debe acabar. El tiempo de los inmortales expiró hace mucho tiempo. Destruye a los guardianes que rodean las torres para debilitar el campo de fuerza. Una vez hecho eso, destruye a Immol'thar. Cuando el poder del Príncipe esté muy mermado, ataca y acaba con él. Deja que el espíritu de la ciudad descanse.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7463] = {title = "El refresco arcano", objective = "Viaja al Barrio Alabeo de La Masacre y mata al elemental de agua, Hidromilecio. Lleva la esencia de Hidromilecio al Tradicionalista Lydros que está en El Athenaeum.", description = "¡Vaya, <un mago/una maga> <raza>! Esto es increíble. No he visto a nadie de tu clase en... ¿cuánto? ¡500 años!\n\nTengo algo que saciará tu sed, pero primero tienes que hacer algo por mí.\n\n<Lydros se ríe.>\n\nHay una anomalía en Eldre'Thalas. Un elemental de agua se ha instalado en el ala este. ¡Hay que catalogar su presencia!\n\nVe al Barrio Alabeo y extrae una porción de esencia elemental del Hidromilecio. Devuélvemela y te enseñaré un conjuro útil.También recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "También recibirás:\n\n"}
MultiLanguageQuestData['mx'][7481] = {title = "Leyendas élficas", objective = "Busca a Telmius Buscasueños en La Masacre. Vuelve al Campamento Mojache e informa al Sabio Korolusk de cualquier cosa que encuentres.", description = "Hace muchos años, un maestro élfico solitario llamado Telmius Buscasueños huyó de la devastación de su hogar llevándose varios artefactos élficos antiguos.\n\nNuestra búsqueda de este maestro perdido nos ha llevado desde las ruinas de Quel'Thalas, por las Estepas Ardientes, a través de las grandes extensiones marítimas, y hasta Feralas.\n\nCreemos que el elfo buscó refugio en los salones de Eldre'Thalas (lo que ahora se conoce como La Matanza).\n\nDebes encontrarlo, <aventurero/aventurera>. Vivo o muerto, ¡debemos recuperar el conocimiento que se llevó!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7482] = {title = "Leyendas élficas", objective = "Busca a Telmius Buscasueños en La Masacre. Vuelve al Bastión Plumaluna a informar a la erudita Runaespina de lo que hayas encontrado.", description = "Hace muchos años, un maestro élfico solitario llamado Telmius Buscasueños huyó de la devastación de su hogar llevándose varios artefactos élficos antiguos.\n\nNuestra búsqueda de este maestro perdido nos ha llevado desde las ruinas de Quel'Thalas, por las Estepas Ardientes, a través de las grandes extensiones marítimas, y hasta Feralas.\n\nCreemos que el elfo buscó refugio en los salones de Eldre'Thalas (lo que ahora se conoce como La Matanza).\n\nDebes encontrarlo, <aventurero/aventurera>. Vivo o muerto, ¡debemos recuperar el conocimiento que se llevó!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7483] = {title = "El tratado sobre rapidez", objective = "Lleva 1 tratado sobre rapidez, 1 diamante negro prístino, 2 fragmentos luminosos grandes y 2 sangres de héroes al Tradicionalista Lydros a La Masacre para conseguir un arcanum de rapidez.", description = "El maestro Buscasueños perdió el tratado sobre rapidez en el ala este. El tratado nos permitirá lanzar un conjuro menor de rapidez a tu equipo. Es más bien un conjuro pequeño, nada espectacular...\n\nEn cualquier caso, si la cosa te interesa, tendrás que conseguir el tratado y algunos componentes básicos.\n\nMmm... Y creo que podríamos necesitar también sangre de los héroes, un diamante negro prístino y unos fragmentos luminosos grandes. Pero podría equivocarme.\n\n<Lydros se encoge de hombros.>Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nArcanum de rapidez"}
MultiLanguageQuestData['mx'][7484] = {title = "El tratado sobre enfoque", objective = "Lleva 1 tratado sobre enfoque, 1 diamante negro prístino, 4 fragmentos luminosos grandes y 2 pieles de Sombra al Tradicionalista Lydros a La Masacre para conseguir un arcanum de enfoque.", description = "Este tratado casi despertó interés en uno de los familiares más jóvenes del Tradicionalista. La pobre criatura solo tenía unas semanas.\n\nAquellos de entre ustedes que tengan una mayor inclinación hacia la magia, podrían encontrar esto interesante.\n\nEl tratado sobre enfoque se perdió en esta ala. Solo puedo deducir que lo tiene uno de los espíritus de los Altonato.\n\nTrae el tratado con algunos fragmentos luminosos grandes, piel de Sombra y un diamante negro prístino y yo invocaré el arcanum.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nArcanum de enfoque"}
MultiLanguageQuestData['mx'][7485] = {title = "El tratado sobre protección", objective = "Lleva 1 tratado sobre protección, 1 diamante negro prístino, 2 fragmentos luminosos grandes y 1 costura desgarrada de abominación al Tradicionalista Lydros a La Masacre para conseguir un arcanum de protección.", description = "Lloraba como un bebé por la pérdida de su tratado. Y ojo, yo también he llorado por algún texto, porque no hay mayor pérdida que la del conocimiento y la historia, pero llorar por una caótica recopilación de conjuros inútiles como esta... ¡es absurdo! Cualquiera diría que el Príncipe le estaba haciendo un favor arrancándole la carne de los huesos...\n\nTráeme el Tratado con un diamante negro prístino, fragmentos luminosos grandes y una costura desgarrada de abominación y yo recrearé el arcanum.\n\nAh, comprueba también el ala norte.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nArcanum de protección"}
MultiLanguageQuestData['mx'][7486] = {title = "Una recompensa de héroe", objective = "Recoge tu recompensa en el arca de Hydraxis.", description = "<nombre>, tus servicios a los Señores del Agua sobrepasan cuanto habríamos esperado de los habitantes de este mundo.\n\nLos conceptos de gratitud y recompensa de tu gente nos son ajenos, pero en este caso haremos una excepción.\n\nEncontrarás un arca bajo la espuma en la base sur de la isla. Dentro está tu... recompensa.\n\nVe a por tu recompensa, <nombre>.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nBrisa del marAro de la marea\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][7487] = {title = "Armonización con el Núcleo", objective = "Acércate al portal de entrada del Núcleo de Magma en las Profundidades de Roca Negra y recoge un trozo del Núcleo. Llévaselo a Lothos Levantagrietas a la Montaña Roca Negra.", description = "Se abren y cierran grietas por todas partes, <raza>. A dos pasos de aquí hay una grieta que va a las profundidades de la Montaña Roca Negra, a las fauces mismas del Señor del Fuego.\n\n¿Te sorprende? Lástima... Las razas mortales no pueden comprender lo que no pueden tocar, ver o sentir.\n\nPero el portal está aquí y el acceso es posible.\n\n¿He despertado tu curiosidad? La Armonización es muy sencilla. Aventúrate en las Profundidades de Roca Negra y consigue un trozo del Núcleo. Tráemelo y armonizaré tu esencia con el portal.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7488] = {title = "La membrana de Lethtendris", objective = "Lleva la Membrana de Lethtendris a Latronicus Lanzaluna al Bastión Plumaluna de Feralas.", description = "La maga Lethtendris, una despiadada elfa sanguinaria cuya brutalidad solo es comparable a su adicción a la magia, se ha refugiado en La Masacre. Ha creado un dispositivo, una red que atrapa la energía mágica de ese lugar y tememos que, si no intervenimos, causará daños irreparables a nuestro mundo.\n\nDetenla, <nombre>. Encuéntrala y arrebátale la red. Probablemente la encontrarás cerca de los sátiros del Barrio Alabeo, en La Masacre. Tráeme la red para que pueda liberar su poder y devolverlo con seguridad a su lugar...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nHilador de conocimiento"}
MultiLanguageQuestData['mx'][7489] = {title = "La membrana de Lethtendris", objective = "Lleva la Membrana de Lethtendris a Talo Pezuñahendida al Campamento Mojache de Feralas.", description = "Lethtendris, la elfa sanguinaria, ha superado sus límites. Tan ansiosa estaba de acumular poder, que desafió a sus hermanos y creó un instrumento de insidioso diseño... una red destinada a recoger las impías energías mágicas de La Masacre. En este momento sigue reuniendo esas energías y planea lanzarlas contra sus enemigos.\n\nLethtendris ha de ser detenida. Encuéntrala. Estará en el Barrio Alabeo de La Masacre. Derrótala y tráeme su red para que pueda entregarla a elfos sanguinarios más cuerdos para que la estudien.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nHilador de conocimiento"}
MultiLanguageQuestData['mx'][7490] = {title = "Victoria para la Horda", objective = "Lleva la cabeza de Onyxia a Garrosh a Orgrimmar.", description = "Has conseguido lo imposible. Has matado a la madre de los Vuelo Negro. Llévale la cabeza a tu Jefe de Guerra.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7491] = {title = "Para que todos lo vean", objective = "Busca al señor supremo Runthak en el Valle de la Fuerza.", description = "El señor supremo Runthak te espera en el Valle de la Fuerza.\n\n<El Jefe de Guerra te saluda.>\n\nNo lo dejes esperando, valiente.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nSello de matadragonesColgante de diente de OnyxiaDije de sangre de Onyxia\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][7492] = {title = "Campamento Mojache", objective = "Ve al Campamento Mojache de Feralas y habla con Talo Pezuñahendida.", description = "Talo Pezuñahendida, un ancestro Tauren de Feralas, envía una petición de ayuda. Dio pocos detalles, pero sí dijo que necesita agentes para un asunto tan delicado como... grave.\n\nSirve a la Horda, <nombre>. Ve al Campamento Mojache de Feralas y habla con Talo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7493] = {title = "El viaje acaba de empezar", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nPatrón: capa de escamas de Onyxia"}
MultiLanguageQuestData['mx'][7494] = {title = "Bastión Plumaluna", objective = "Habla con Latronicus Lanzaluna. Lo encontrarás en el Bastión Plumaluna de Feralas.", description = "¡<nombre>! ¡Necesitan tu ayuda en Feralas!\n\nUna maga proscrita, Lethtendris, ha huido a las antiguas ruinas élficas de Eldre'Thalas que ahora se conocen como La Masacre. Se cree que lleva consigo un peligroso objeto de gran energía mágica. Debemos recuperarlo.\n\nLatronicus Lanzaluna solicita agentes para entrar en La Masacre y arrebatar el objeto a Lethtendris.\n\n¡Sirve a la Alianza! Busca a Latronicus en el Bastión Plumaluna de Feralas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7495] = {title = "Victoria para la Alianza", objective = "Lleva la cabeza de Onyxia al rey Varian Wrynn en Ventormenta.", description = "Has logrado lo imposible. La madre del Vuelo Negro está muerta, a tus pies. Coge su cabeza y llévasela al rey Varian Wrynn.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
