MultiLanguageQuestData['mx'][7562] = {title = "Mor'zul Sangredoble", objective = "Habla con Mor'zul Sangredoble en el Altar de la Tempestad en Las Estepas Ardientes.", description = "<nombre>, has profundizado mucho en la práctica de las artes oscuras. Tu dominio sobre habitantes de otros mundos se ha consolidado... quizás estés <listo/lista> para asignarte uno de los infames corceles de la Muerte.\n\nEl ritual para invocar a la bestia desde su hogar requiere gran poder y recursos pero si deseas dominar al épico corcel, habla con Mor'zul Sangredoble. Tiene su campamento en el Altar de la Tempestad, en Las Estepas Ardientes\n\nVete, <nombre>. Esta misión será peligrosa ¡pero un brujo de tu talla no debe retroceder ante el peligro!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7563] = {title = "La ira de sangre", objective = "Llévale 30 botellas de sangre de bestia embravecida a Mor'zul Sangredoble en Las Estepas Ardientes.", description = "Los corceles de la Muerte viven en otro mundo, en las abrasadoras Llanuras de Xoroth y para amarrar a una de esas afamadas bestias, debes convocar a poderosos glifos. Puedo escribir los glifos para ti en un papiro pero antes necesitaré una tinta especial.\n\nEn la remota Cuna del Invierno habita una raza de bestias búho. Otrora criaturas puras, enloquecieron debido a unas emanaciones diabólicas de la Garganta Negro Rumor y ahora deambulan histéricos por las nieves.\n\nNecesito su sangre para la tinta de tu papiro. Tráemela.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7581] = {title = "Las selladuras de la prisión", objective = "Viaja a La Masacre en Feralas y consigue 15 muestras de sangre de sátiro del sátiro Mala Hierba que habita en el Barrio Alabeo. Cuando hayas acabado, ve a ver a Daio a la Escara Impía.|n", description = "Debes arrebatarles a los demonios inferiores lo necesario para sellar la prisión para Guardias apocalípticos.\n\nLa sangre del sátiro Mala Hierba que habita en La Masacre servirá. La sangre coagulada pegará los fragmentos de Hederine, formando una prisión de cristal.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7582] = {title = "El revestimiento de la prisión", objective = "Viaja a la Garganta Negro Rumor en Cuna del Invierno y recoge 5 Lágrimas de los Hederine de los demonios Hederine que ocupan la garganta. Cuando hayas cumplido tu tarea, ve a ver a Daio a la Escara Impía.", description = "Los demonios Hederine que ocupan las estribaciones del Monte Hyjal segregan un poderoso veneno vil que, si se deja madurar, se convierte en un resistente cristal antimagia. Estos cristales se conocen como las Lágrimas de los Hederine.\n\nNi la inmensa fuerza de un Guardia apocalíptico sería suficiente para destruir las paredes de una prisión construida con este material.\n\nViaja a la Garganta Negro Rumor en Cuna del Invierno y recoge lágrimas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7602] = {title = "Esencia de energía vil pura", objective = "Diblis de Frondavil te ha pedido que le lleves 3 esencias viles impecables que provengan de 3 lugares distintos.\n\nLos sátiros Legashi de Azshara tienen la esencia vil impecable de su región. Los Legionarios Jaedenar de Jaedenar tienen la esencia vil impecable de su región. Los guardias viles de Las Tierras Devastadas tienen la esencia vil impecable de su región.\n\nReúne las esencias viles impecables y vuelve con Diblis a Frondavil.", description = "Si quieres reanimar a Kroshius, vas a necesitar fuego vil. Yo puedo hacer fuego vil, pero para eso necesito algunos componentes.\n\nTienes que traerme esencia vil impecable de tres regiones diferentes del mundo.\n\nLos sátiros Legashi de Azshara tienen el primer tipo de esencia. Los Legionarios Jaedenar, de Jaedenar, tienen el segundo y los guardias viles de Las Tierras Devastadas, el tercero.\n\nTráeme una esencia de cada tipo y yo crearé el fuego vil que te permitirá reanimar a Kroshius.", progress = "No se lo digas a nadie, pero Niby es tonto.|n", completion = "Dame un minuto. Combinaré las esencias y crearé un fuego vil.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7604] = {title = "Un contrato vinculante", objective = "Entrégale el contrato de La Hermandad del Torio a Lokhtos Tratoscuro si quieres recibir los planes de Sulfuron.", description = "Los abajo firmantes declaran que el lingote de Sulfuron del que hacen entrega a la empresa Hermandad del Torio (HT S.A.) es auténtico y no una falsificación. Los abajo firmantes asimismo declaran que cualquier daño que pudiere resultar del intento de construir, forjar, encontrar, crear, vender, o ingerir a Sulfuras, no podrá ser imputado a HT S.A.\n\nPor la firma del presente contrato, acepta las cláusulas en él estipuladas.\n\n_________________\n\nFirmaRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDiseño: martillo de Sulfuron"}
MultiLanguageQuestData['mx'][7623] = {title = "Lord Pesadilla", objective = "Cómprale pociones enigmáticas a Gorzeeki Ojovago en el Altar de la Tempestad en Las Estepas Ardientes.\n\nUsa las pociones para viajar por Jaedenar en Frondavil y habla con Lord Pesadilla en el interior de la Guarida Sombría.", description = "Mor'zul dice que quieres abrir un portal a Xoroth. Para ello, necesitarás polvo estelar xorothiano. ¡No es fácil de encontrar en Azeroth!\n\nHay un ser que podría tener algo de este polvo: Lord Pesadilla en Jaedenar, el miembro del Consejo de la Sombra! Habla con él y puede que te dé algo de polvo estelar.\n\nAunque si vas a Jaedenar, tendrás que revestirte del toque maligno del Consejo de la Sombra. Para ello, hará falta alguna de mis pociones enigmáticas y eso te costará...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7629] = {title = "Entrega de diablillo", objective = "Llévale el diablillo en un tarro al laboratorio de alquimia de Scholomance. Después de crear el papiro llévale el tarro a Gorzeeki Ojovago.", description = "Hay un requisito más para el proceso del papiro de Mor'zul; necesito papel imbuido de polvo estelar xorothiano. Y... me temo que no puedo hacerlo aquí. ¡No tengo el equipo necesario!\n\nSin embargo, hay un laboratorio de alquimia con todo lo que hace falta. Se encuentra en Scholomance, en la isla de Castel Darrow en las Tierras de la Peste.\n\nNo puedo hacer el viaje pero toma este tarro. En su interior hay un diablillo bastante listo. Libéralo en el laboratorio de alquimia y se ocupará de imbuir el papiro.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7631] = {title = "Corcel nefasto xorothiano", objective = "Lee las instrucciones de Mor'zul. Invoca a un corcel nefasto xorothiano, derrótalo y después vincula su espíritu al tuyo.\n\nObjeto provisto: \n", description = "Ya están todos los preparativos. Ahora debes llevar a cabo el ritual para crear un Círculo de invocación superior, después usar el pergamino imbuido de polvo estelar xorothiano... para abrir un portal a Xoroth.\n\nTe he escrito las instrucciones del ritual en un papiro. Estúdialo atentamente, ya que debes seguir al pie de la letra cada paso si quieres que salga bien.\n\nQue la Fortuna te acompañe, <nombre>. Y que las almas de tus enemigos encuentren raudamente su camino hacia tu bolsa de fragmentos.Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nCorcel nefasto\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][7632] = {title = "La hoja antigua", objective = "Encuentra al dueño de la hoja petrificada vieja. Buena suerte, <nombre>; este es un mundo enorme...", description = "La epidermis de la hoja tiene un luminoso brillo verde. La superficie es muy rugosa, y tiene muchas venas y arrugas.\n\nSi tuvieras que arriesgar una opinión, dirías que esta hoja proviene de algo antiguo y poderoso.\n\nQuizás deberías encontrar al dueño de esta hoja...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7637] = {title = "Énfasis en el sacrificio", objective = "Viaja a Forjaz y consigue el incensario de exorcismos del sumo sacerdote Rohan. Tendrás que hacer una donación de 150 monedas de oro para conseguirlo.", description = "Para prepararte para esta tarea, primero debes demostrar tener voluntad de sacrificio y buen juicio... con énfasis en lo del sacrificio.\n\nPara la tarea, debes adquirir el incensario de exorcismos del sumo sacerdote Rohan. Incluso aunque su uso será para hacer el bien y la justicia, hay que dar una compensación a cambio.\n\nVete a Forjaz y habla con el sumo sacerdote. Al llevar suficientes monedas para ayudarle a superar la pérdida de su incensario, estarás demostrando tu sacrificio.\n\nY ahora vete, <nombre>, el tiempo es vital.Cuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][7638] = {title = "Lord Grisillo Quiebrasombras", objective = "Habla con Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta.", description = "<nombre>, ha llegado la hora de que sepas lo que necesitarás para adquirir algo que, sin duda, llevas un tiempo esperando... tu destrero.\n\nHabla con Lord Grisillo Quiebrasombras aquí, en el Distrito de la Catedral de Ventormenta. Te enseñará a cuidar de tu montura y te dirá qué tareas debes completar para conseguir una.\n\nTe deseo lo mejor. ¡Por la Luz, mi noble <hermano/hermana>!Cuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][7642] = {title = "Recopilación de artículos", objective = "Lleva 40 paños rúnicos, 6 barras de arcanita, 10 lágrimas de Arthas, 5 viales de agua sagrada de Stratholme y 150 monedas de oro a Grimand Elmore en el Distrito de los Enanos de Ventormenta.", description = "Para la gualdrapa necesitarás cuatro objetos: paño rúnico para las costuras, barras de arcanita para las placas, lágrimas de Arthas para la sintonía espiritual y agua sagrada de Stratholme para la infusión espiritual. En verdad, son cinco cosas... Oro también, para pagarme a mí. El precio incluye la mano de obra así como sillín y estribos artesanales.\n\nUna vez que tengas todo eso podré terminar la montura. Hasta ese momento, hay algunas cosas con las que puedo empezar mientras te haces con lo que te pedí.Cuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][7649] = {title = "Las mallas de placas en torio encantado: volumen I", objective = "Devuelve el libro a sus legítimos dueños.", description = "El libro lleva la marca de El Athenaeum.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDiseño: coraza de torio encantado"}
