MultiLanguageQuestData['mx'][7651] = {title = "Las mallas de placas en torio encantado: volumen III", objective = "Devuelve el libro a sus legítimos dueños.", description = "El libro lleva la marca de El Athenaeum.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDiseño: yelmo de torio encantado"}
MultiLanguageQuestData['mx'][7666] = {title = "El regreso a El Gran Osario", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nCristal de adivinación"}
MultiLanguageQuestData['mx'][7667] = {title = "Asistencia material", objective = "Si te interesa ayudar a Sagorne Montacresta, llévale 1 diamante de Azeroth y 1 diamante negro prístino al Valle de la Sabiduría, en Orgrimmar.", description = "<nombre>, hay un asunto urgente que creo que te interesará material y espiritualmente.\n\nEscondida en Scholomance, en Lordaeron, hay una cámara que se llama El Gran Osario. Quiero ultimar un instrumento que ahuyente las sombras de esa horrible sala. Para eso, necesito dos diamantes: uno de Azeroth y uno negro prístino. Sé que lo que pido no es fácil, pero no puedo hacerlo por mí mismo.\n\n¿Puedes traérmelos tú?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7670] = {title = "Lord Grisillo Quiebrasombras", objective = "Habla con Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta.", description = "<nombre>, voy a explicarte lo que debes hacer para conseguir una montura.\n\nHabla con Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta. Te enseñará a cuidar de tu montura y te dirá qué tareas debes completar para conseguir una.\n\nTe deseo lo mejor. ¡Por la Luz, mi noble <hermano/hermana>!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7681] = {title = "Hunter test quest", objective = "Dale de comer a tu mascota y habla con tu personaje con misión.Dale de comer a tu mascota.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", description = "Dale de comer a tu mascota.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7682] = {title = "Hunter test quest2", objective = "Dale de comer a tu mascota y habla con tu personaje con misión.Dale de comer a tu mascota.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", description = "Dale de comer a tu mascota.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7701] = {title = "SE BUSCA: Sobrestante Maltorius", objective = "El traidor Hierro Negro llamado sobrestante Maltorius está en La Fosa de la Escoria de La Caldera, en La Garganta de Fuego. \n\nMátalo y lleva su cabeza al capitán de vigía Lolo Zancalarga a La Garganta de Fuego para recibir tu recompensa.", description = "Por orden de su eminencia el sobrestante Puñaceite: el sobrestante Maltorius, agente pícaro de la Hermandad del Torio y recién ascendido jefe del personal Hierro Negro de La Caldera de La Fosa de la Escoria, debe morir. Trae su cabeza como prueba. \n\nLo de la recompensa háblalo con el capitán de vigía Lolo Zancalarga.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guerrera de cuero carbonizadaJubón de malla chamuscadoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][7702] = {title = "¡Mátalos de sueño!", objective = "Los dormitorios de los Hierro Negro están en La Fosa de la Escoria de La Caldera, en La Garganta de Fuego. \n\nRoba 20 almohadas y ve a ver a Evonis Fumollín.", description = "Si queremos reducir la productividad de los Hierro Negro que trabajan en La Fosa de la Escoria, tenemos que darles donde más les duela. \n\nPoca gente lo sabe, pero los enanos, sobre todo los Hierro Negro, necesitan muchas horas de sueño. \n\nPero claro, para dormir necesitan almohadas, ¿verdad, <nombre>? Así que tienes que colarte en La Fosa de la Escoria y robárselas todas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nToga Resplandor eterno"}
MultiLanguageQuestData['mx'][7703] = {title = "Asunto Gordok sin finiquitar", objective = "Encuentra el guante del Poderío de Gordok y llévaselo al capitán Kromcrush a La Masacre. \n\nSegún Kromcrush, una \"historia muy, muy vieja\" dice que Tortheldrin, un elfo \"asqueroso\" que se llamaba a sí mismo príncipe, robó el guantelete a uno de los reyes de Gordok.", description = "Así que tú ser Rey... ¡pues a lo mejor recuperar artefacto Gordok de asqueroso elfo, él ir de \"Príncipe\"! Rey anterior fracasar, como resto reyes antes Tortheldrin, asqueroso elfo robar rey Gordok mucho tiempo!\n\nArtefacto llamarse guante del Poderío de Gordok. Historia muy, muy vieja decir solo rey verdadero de Gordok poder recuperar. Historia muy, muy vieja también decir asqueroso elfo aún estar cerca, tú encontrar, ¡tú llevar poderoso guante siempre jamás! ¡Ea, yo enseñar tú!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Manoplas de GordokGuanteletes de GordokGuantes de GordokManijas de GordokRecibirás:\n\n"}
MultiLanguageQuestData['mx'][7704] = {title = "¡Mira el tamaño de esto!", objective = "Lleva la almohada de la ayudante de cámara Pilaprieta a Evonis Fumollín a La Garganta de Fuego.", description = "Vaya, vaya... La ayudante de cámara tenía una enorme almohada bordada y ahora es tuya. Seguro que Evonis Fumollín estará encantada; llévale la almohada, a ver si te recompensa con algo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPilar de aterrizaje de Evonice"}
MultiLanguageQuestData['mx'][7721] = {title = "Combustible para el Ultra-reductor", objective = "Reúne 10 núcleos de elemental de agua de los elementales marinos y de los rocíos marinos que hay en La Costa Olvidada de Feralas, y llévaselos a Zorbin Hipnoviento, que está cerca del embarcadero.", description = "Si en contra de lo que me dicta el sentido común, me quedo en La Costa Olvidada para montar una tienda de ingeniería, tendré que tratar con esos apestosos elementales. ¡Malditos sean esos descontrolados poderes de elementalismo!\n\nPor suerte para mí —y también para ti, mi <estimado/estimada> agente provocador— los elementales son una estupenda fuente de alimentación para mi Ultra-reductor. ¡Démosles un propósito en la vida! Eso sí, cuando los reduzcas, ¡guárdame los núcleos de elementales de agua!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSombrero resistente al agua de Zorbin"}
MultiLanguageQuestData['mx'][7722] = {title = "¿Qué pasa con el flujo?", objective = "Busca los diseños secretos: flujo ígneo robados por el sobrestante Maltorius en La Fosa de la Escoria de La Caldera. Llévaselos al herrero maestro Burninate a La Garganta de Fuego.|n", description = "Cuando ese traidor de Maltorius se marchó, se llevó algo más valioso que un cristal Arcano prístino: ¡nuestros diseños secretos del flujo ígneo! Seguro que con el pagó su ascenso entre los Hierro Negro. \n\nQuiero que recuperes nuestros diseños secretos, <nombre>. Estarán cerca de Maltorius, en lo más profundo de La Fosa de la Escoria.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7723] = {title = "¡Malditos dedos gordos!", objective = "Hansel Manospesadas quiere que mates 20 gólems de guerra pesados. \n\nSuelen estar cerca de La Caldera en La Garganta de Fuego. Después ve a ver a Hansel a La Garganta de Fuego.", description = "Por desgracia, yo no puedo ocuparme del asunto con los dedos así. Es que el clima de aquí y las bajas presiones hacen que se me hinchen. Morcillas de Thelsamar parecen, mira, mira... \n\nVas a tener que hacerlo tú a mis órdenes. \n\nLo primero que hay que hacer: zurrar a los gólems de guerra de la Garganta. Venga, arreando.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGuanteletes de placas de escoria"}
MultiLanguageQuestData['mx'][7724] = {title = "Amenaza abrasadora", objective = "Hansel Manospesadas quiere que mates 20 arañas de lava superiores en La Garganta de Fuego. Las encontrarás en las mesetas y los estanques de lava de La Garganta de Fuego. \n\nCuando hayas matado suficientes arañas de lava superiores ve a ver a Hansel Manospesadas a La Garganta de Fuego.", description = "Está claro: cada vez que el viejo Hansel decide sentarse a descansar, los dioses le envían trabajo. \n\nEso me hace pensar, ¿entiendes? \n\nEn fin, hay unas arañas de lava gigantescas que están dando problemas. Puñaceite dice que echan fuego por el... Bueno, que no es agradable, dice. \n\nSupongo que tenemos que matarlas. Más bien, tú tienes que matarlas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFaja de malla chamuscada"}
MultiLanguageQuestData['mx'][7726] = {title = "Más combustible para el Ultra-reductor", objective = "Reúne 6 núcleos de elemental de agua de los elementales marinos y los rocíos marinos que hay en La Costa Olvidada de Feralas, y llévaselos a Zorbin Hipnoviento, que está cerca del embarcadero.", description = "¿Dices que quieres más trabajo? ¿No sacié tu sed de aventura cuando te mandé a extraer restos chorreantes de dentro de los cuerpos de los elementales? Parece que si te envío a hacer más de lo mismo, no conseguiré llenar ese pozo sin fondo que es tu ansia de aventuras...\n\nPero dejémonos de frases bonitas, porque lo que necesito es precisamente eso: más núcleos de elementales de agua. Estoy luchando mucho por sacar el negocio adelante, así que la recompensa no sería gran cosa, pero te prometo que contaré a todos los que me escuchen lo que me has ayudado. ¡Y conozco a mucha gente que escucha en el Cártel!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7727] = {title = "¿Incendosaurio? Loqueseasaurio más bien", objective = "Hansel Manospesadas quiere que mates 20 incendosaurios.\n\nSuelen estar en los estanques de lava de La Fosa de la Escoria. La Fosa de la Escoria está en La Caldera de La Garganta de Fuego. \n\nCuando hayas matado suficientes incendosaurios ve a ver a Hansel Manospesadas a La Garganta de Fuego.", description = "¡Buenas, <chaval/chavala>! Me han salido sabañones en los pies. ¿Cómo voy a salir por ahí a matar cosas con los pinreles así? Necesito que me eches una mano y unos pies. \n\nScrange y Burninate me encargaron que matara a esos bichos porque quieren mandar una expedición a los lagos de lava de La Fosa de la Escoria. Se ve que ahí abajo hay unos incendosaurios nada amistosos. Vete para allá y no vuelvas hasta que no quede ni uno.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nLufa"}
MultiLanguageQuestData['mx'][7728] = {title = "OBJETOS ROBADOS: Tobera y catalejo", objective = "Encuentra la tobera y el catalejo y llévaselos al capataz Scrange a La Garganta de Fuego. \n\nLo único que sabes es que fueron robados por enanos Hierro Negro. La tobera es una herramienta de herrero y el catalejo es un instrumento muy valioso para los oteadores.", description = "Los siguientes objetos han sido robados: \n\n*una tobera Hierro Negro. \n\n*un catalejo.\n\nSe ofrece recompensa a quien devuelva estos objetos.\n\nLa Hermandad del Torio sabe que estos objetos fueron robados por Hierro Negro celosos y faltos de escrúpulos de La Garganta de Fuego.\n\nEl catalejo es un objeto muy útil para los vigías y la tobera es imprescindible en la herrería.\n\nSi recuperas estos objetos, llévaselos a Scrange.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Manijas siempre cálidasLeotardos de placas de escoriaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][7729] = {title = "OPORTUNIDAD LABORAL: Acabar con la competencia", objective = "Mata a 15 Capataces y 15 esclavistas Hierro Negro y ve a ver al capataz Scrange a La Garganta de Fuego.", description = "El capataz Scrange busca personal para acabar con la competencia en La Garganta de Fuego.\n\nSi te interesa, ve a La Garganta de Fuego y mata a todos los capataces y esclavistas Hierro Negro que veas.\n\nVe a ver al capataz Scrange cuando haya suficiente sangre en tu ropa.\n\nNo preguntes: cuando haya sangre suficiente, lo sabrás.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7730] = {title = "Infestación de Zukk'ash", objective = "Lleva 20 caparazones Zukk'ash a Hadoken Zanco Veloz al Campamento Mojache en Feralas.", description = "Por lo que hemos podido deducir de nuestras exploraciones, los enemigos que están al sur de los gnolls son una raza de insectos. Y francamente, me da igual que sean o no conscientes de lo que nos hacen. Si con sus actos empujan a los gnolls contra nosotros, entonces son una amenaza, como lo son los gnolls, si no peor.\n\nAdéntrate en Las Galerías Retorcidas, que es donde viven estos insectos Zukk'ash. Reduce su número y vuelve a informarme de lo que encuentres. Trae contigo sus caparazones como prueba de que has cumplido.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7731] = {title = "Latigador con aguijón", objective = "Derrota al latigador con aguijón en Las Galerías Retorcidas y lleva sus glándulas a Hadoken Zanco Veloz al Campamento Mojache en Feralas.", description = "Uno de los exploradores que vigilaba Las Galerías Retorcidas avistó un insecto gigante, uno mucho más grande que los otros, deambulando por la zona. No solo es más grande que los demás, además parece secretar una especie de aura, cosa que los demás insectos no hacen. Le hemos dado un nombre: latigador con aguijón.\n\nNos vendría bien estudiar las tripas de esta bestia mientras intentamos averiguar cuál es la mejor manera de afrontar esta nueva amenaza. Corta sus glándulas secretoras y tráemelas de inmediato.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7732] = {title = "El informe Zukk'ash", objective = "Entrega a Zilzibin Tambor Sabio el informe del campamento Mojache Zukk'ash. Reside en La Calle Mayor de Orgrimmar.", description = "Has hecho un buen trabajo señalando la amenaza que los insectos Zukk'ash suponen para el Campamento Mojache. No podemos bajar la guardia con esos bichos. Por eso quiero pedirte que hagas algo más por la Horda.\n\nEn este documento se detalla toda la información que hemos reunido sobre esos insectos Zukk'ash. Quiero que se lo lleves a Zilzibin Tambor Sabio a La Calle Mayor de Orgrimmar. Es un experto en criaturas alienígenas como estas, espero que él pueda hacer algo con el conocimiento que hemos adquirido.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Bufas de pico esmeraldaPodrás elegir una de estas recompensas:\n\nAnillo de Sutileza\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][7733] = {title = "Calidad mejorada", objective = "Lleva 10 pellejos de yeti Cicatriz de Rabia a Pratt McGrubben al Bastión Plumaluna en Feralas.", description = "He encontrado una fuente de pieles aún mejor, ¡aunque sea casi imposible de creer! En la región norte de Feralas -en las profundidades de los Dominios de los Cicatriz de Rabia- hay otros yetis. Son más fuertes que los que has conocido hasta ahora, así que, si te apetece aceptar un nuevo desafío, ¡ponte en camino!\n\nTe recompensaré ampliamente por un hatajo de 10 pieles. Tráemelas y cerraremos nuestro trato.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGuerrera hecha a mano de Pratt"}
MultiLanguageQuestData['mx'][7734] = {title = "Calidad mejorada", objective = "Lleva 10 pellejos de yeti Cicatriz de Rabia a Jangdor Zanco Veloz al Campamento Mojache de Feralas.", description = "He encontrado una fuente de pieles aún mejor, ¡aunque sea casi imposible de creer! En la región norte de Feralas -en las profundidades de los Dominios de los Cicatriz de Rabia- hay otros yetis. Son más fuertes que los que has conocido hasta ahora, así que, si te apetece aceptar un nuevo desafío, ¡ponte en camino!\n\nTe recompensaré ampliamente por un hatajo de 10 pieles. Tráemelas y cerraremos nuestro trato.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGuerrera hecha a mano de Jangdor"}
MultiLanguageQuestData['mx'][7735] = {title = "Pellejo de yeti prístino", objective = "Lleva el pellejo de yeti prístino a Pratt McGrubben al Bastión Plumaluna de Feralas.", description = "Has encontrado un pellejo de yeti impecable, increíblemente grueso y robusto. Mucho más que las que has visto en la Cicatriz de Rabia.\n\nSabes que Pratt McGrubben del Bastión Plumaluna busca siempre pellejos de yeti. Seguro que este pellejo le interesa.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7736] = {title = "Fabricar flujo ígneo con sangrerregia", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][7738] = {title = "Pellejo de yeti perfecto", objective = "Lleva los pellejos de yeti perfecto a Jangdor Zanco Veloz al Campamento Mojache de Feralas.", description = "Has encontrado algo que podría ser el pellejo de yeti perfecto. Este pellejo es excepcionalmente grueso y robusto. Mucho más que las de los yetis Cicatriz de Rabia.\n\nSabes que Jangdor Zancoveliz del Campamento Mojache busca siempre pellejos de yeti. Este pellejo en concreto le interesará mucho.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7761] = {title = "Orden de Puño Negro", objective = "¡Será estúpido ese orco! Al parecer, tienes que encontrar la enseña y ganar la marca de Drakkisath para poder acceder al orbe de orden.\n\nSegún la carta, el general Drakkisath guarda la enseña. Quizás deberías investigarlo.", description = "¡Imbécil!\n\nTengo muy poca fe en tu capacidad para impedir que los extraños se infiltren en la guarida del maestro. En el muy probable caso de que mueras, este orbe tiene su propio sistema integrado a prueba de fallos para impedir que ningún desconocido se teletransporte directamente a Alanegra.\n\nSolo aquellos con la marca de Drakkisath en la mano pueden usar este orbe. Por suerte, Drakkisath es mucho más competente que tú, intendente. ¡Él mismo guarda la enseña!\n\n-Jefe de Guerra Rend Puño Negro\n\nP.D. Destruye esta carta, idiota.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7781] = {title = "Señor de Roca Negra", objective = "Lleva la cabeza de Nefarian al rey Varian Wrynn en Ventormenta.", description = "Vuelves a sentir esa vieja sensación. Las punzadas de victoria retumban por todo tu cuerpo. Ante ti está la cabeza monolítica y marcada por la guerra de Nefarian. Llévasela al Rey Varian, <campeón/campeona>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7783] = {title = "Señor de Roca Negra", objective = "Lleva la cabeza de Nefarian a Garrosh a Orgrimmar.", description = "Vuelves a sentir esa vieja sensación. Las punzadas de victoria retumban por todo tu cuerpo. Ante ti está la cabeza monolítica y marcada por la guerra de Nefarian. Llévasela a tu Jefe de Guerra, <campeón/campeona>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7784] = {title = "Señor de Roca Negra", objective = "Habla con el señor supremo Colmillosauro en Orgrimmar. Te espera en el Valle de la Fuerza.", description = "Busca al señor supremo Colmillosauro en el Valle de la Fuerza.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nOrbe de maestro matadragonesMedallón de maestro matadragonesAnillo de maestro matadragones\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][7785] = {title = "Examina la vasija", objective = "Examina la vasija de renacer y devuélvesela al alto señor Demitrian.", description = "Examina la vasija de su renacimiento, mortal. ¡De aquí renacerá el Hijo del Viento!", progress = nil, completion = nil, rewards = nil}
