MultiLanguageQuestData['mx'][7877] = {title = "El tesoro de los Shen'dralar", objective = "Vuelve a El Athenaeum y encuentra el tesoro de los Shen'dralar. ¡Reclama tu recompensa!", description = "En la biblioteca, El Athenaeum, encontrarás un baúl antiguo escondido debajo de las escaleras. De lo que veas en él, toma cuanto desees.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "AplastahuesosYelmo provincianoBotas de junciaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][7905] = {title = "La Feria de la Luna Negra", objective = "Entrega el vale de entrada gratuita a Gelvas Roñoso en la Feria de la Luna Negra.", description = "¡La Feria de la Luna Negra está al caer! ¡No te pierdas nuestros emocionantes juegos, gana premios increíbles y averigua qué te depara el futuro!\n\nSi te decides, ¡puedes canjear este cupón por vales gratuitos y una copia de la mundialmente famosa guía de campo de la Luna Negra para que te ayude a identificar los tesoros que te encuentres en tus viajes!\n\nLlévale el cupón a Gelvas Roñoso dentro de la feria.\n\nAhora mismo, la feria se encuentra en Villadorada, en el Bosque de Elwynn.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nVale para la Feria de la Luna Negra destrozadoGuía del aventurero de la Luna NegraVale de la Luna Negra"}
MultiLanguageQuestData['mx'][7908] = {title = "El maestro de la arena", objective = "Habla con Corto John Mitril en la Arena de la Vega de Tuercespina.\n\nObjeto provisto: \n", description = "¡Ser un maestro de la arena tiene que ser algo más que esto! ¡Quizás lo sepa el pirata que lleva el evento en Gurubashi!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][7926] = {title = "La Feria de la Luna Negra", objective = "Entrega el vale de entrada gratuita a Gelvas Roñoso en la Feria de la Luna Negra.", description = "¡La Feria de la Luna Negra está al caer! ¡No te pierdas nuestros emocionantes juegos, gana premios increíbles y averigua qué te depara el futuro!\n\nSi te decides, ¡puedes canjear este cupón por vales gratuitos y una copia de la mundialmente famosa guía de campo de la Luna Negra para que te ayude a identificar los tesoros que te encuentres en tus viajes!\n\nLlévale el cupón a Gelvas Roñoso dentro de la feria.\n\nAhora mismo, la feria se encuentra en Cima del Trueno, en Mulgore.", progress = "¿Querías algo? ¿Tienes un vale?", completion = "¡Te doy la bienvenida a la Feria de la Luna Negra! ¡Este vale te da derecho a 5, has oído bien, 5 boletos de tómbola y una copia gratuita de la mundialmente conocida guía de campo de la Luna Negra!\n\nCuando tengas suficientes boletos, ven a verme para cambiarlos por premios. ¡Esta práctica guía de campo te ayudará a localizar e identificar los objetos de valor de los coleccionistas que hay en la feria!", rewards = "Recibirás:\n\nVale para la Feria de la Luna Negra destrozadoGuía del aventurero de la Luna NegraVale de la Luna Negra"}
MultiLanguageQuestData['mx'][7944] = {title = "La Fortuna te espera...", objective = "Ve a las Cuevas de los Lamentos de Los Baldíos y busca tu fortuna.", description = "\"La Fortuna te espera en las Cuevas de los Lamentos.\"\n\nEl papelito de la Fortuna que te dio Sayge está caliente. Cuando lo aprietas, ves una imagen de una cueva al suroeste de El Cruce, en Los Baldíos. Te acercas más y te encuentras moviéndote a gran velocidad por unos enrevesados pasadizos hasta que llegas a un resplandeciente portal que lleva al mismísimo corazón de la cueva. Cuando lo cruzas, aparece de la nada un extraño cofre.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nArcón misterioso"}
MultiLanguageQuestData['mx'][7945] = {title = "La Fortuna te espera...", objective = "Ve a la Roca Crines Pálidas de Mulgore y busca tu fortuna.", description = "\"La Fortuna te espera fuera de la Roca Crines Pálidas.\"\n\nEl papelito de la Fortuna que te dio Sayge está caliente. Cuando lo aprietas, ves una imagen de la Roca Crines Pálidas de Mulgore. Te acercas más y ves un tocón de árbol al lado de la entrada de la cueva.", progress = nil, completion = nil, rewards = nil}
