MultiLanguageQuestData['mx'][8399] = {title = "Lucha por Garganta Grito de Guerra", objective = "Entrega 3 marcas de honor de la Garganta Grito de Guerra a un general de brigada de la Alianza fuera de los campos de batalla.", description = "Las centinelas Ala de Plata están en guerra con los escoltas Grito de Guerra por la destrucción que los orcos están provocando en el bosque. Pero hay más razones para defender este bosque y que van más allá del amor por la naturaleza.\n\nEl bosque forma una barrera estratégica que permite defender Vallefresno contra un ataque a gran escala. Sin él perderíamos Astranaar en un solo día y pasaría a integrarse en Los Baldíos.\n\n¡Colabora en la lucha contra los escoltas Grito de Guerra, <nombre>! ¡Por la Alianza!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8400] = {title = "Lucha por Garganta Grito de Guerra", objective = "Entrega 3 marcas de honor de la Garganta Grito de Guerra a un general de brigada de la Alianza fuera de los campos de batalla.", description = "Las centinelas Ala de Plata están en guerra con los escoltas Grito de Guerra por la destrucción que los orcos están provocando en el bosque. Pero hay más razones para defender este bosque y que van más allá del amor por la naturaleza.\n\nEl bosque forma una barrera estratégica que permite defender Vallefresno contra un ataque a gran escala. Sin él perderíamos Astranaar en un solo día y pasaría a integrarse en Los Baldíos.\n\n¡Colabora en la lucha contra los escoltas Grito de Guerra, <nombre>! ¡Por la Alianza!", progress = "¿Has vuelto con noticias del frente, <nombre>?", completion = "¡Bien hecho, &lt;nombre&gt;! Has servido bien a la Alianza.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8401] = {title = "Lucha por Garganta Grito de Guerra", objective = "Entrega 3 marcas de honor de la Garganta Grito de Guerra a un general de brigada de la Alianza fuera de los campos de batalla.", description = "Las centinelas Ala de Plata están en guerra con los escoltas Grito de Guerra por la destrucción que los orcos están provocando en el bosque. Pero hay más razones para defender este bosque y que van más allá del amor por la naturaleza.\n\nEl bosque forma una barrera estratégica que permite defender Vallefresno contra un ataque a gran escala. Sin él perderíamos Astranaar en un solo día y pasaría a integrarse en Los Baldíos. ¡Colabora en la lucha contra los escoltas Grito de Guerra! ¡Por la Alianza!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8402] = {title = "Lucha por Garganta Grito de Guerra", objective = "Entrega 3 marcas de honor de la Garganta Grito de Guerra a un general de brigada de la Alianza fuera de los campos de batalla.", description = "Las centinelas Ala de Plata están en guerra con los escoltas Grito de Guerra por la destrucción que los orcos están provocando en el bosque. Pero hay más razones para defender este bosque y que van más allá del amor por la naturaleza.\n\nEl bosque forma una barrera estratégica que permite defender Vallefresno contra un ataque a gran escala. Sin él perderíamos Astranaar en un solo día y pasaría a integrarse en Los Baldíos.\n\n¡Colabora en la lucha contra los escoltas Grito de Guerra, <nombre>! ¡Por la Alianza!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8403] = {title = "Lucha por Garganta Grito de Guerra", objective = "Entrega 3 marcas de honor de la Garganta Grito de Guerra a un general de brigada de la Alianza fuera de los campos de batalla.", description = "Las centinelas Ala de Plata están en guerra con los escoltas Grito de Guerra por la destrucción que los orcos están provocando en el bosque. Pero hay más razones para defender este bosque y que van más allá del amor por la naturaleza.\n\nEl bosque forma una barrera estratégica que permite defender Vallefresno contra un ataque a gran escala. Sin él perderíamos Astranaar en un solo día y pasaría a integrarse en Los Baldíos.\n\n¡Colabora en la lucha contra los escoltas Grito de Guerra, <nombre>! ¡Por la Alianza!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8410] = {title = "Maestría elemental", objective = "Recoge una muestra de aire, fuego, tierra y agua para Bath'rah el Vigía del viento.", description = "Bath'rah el Vigía del viento ha reclamado un chamán de tu sabiduría. Pide que lleves contigo una muestra de cada uno de los elementos para mostrar que estás <preparado/preparada>.\n\nPara encontrar a Bath'rah dirígete al río al este del Molino Tarren. Sigue el río hacia el Norte, hasta que des con las ruinas en las que vive Bath'rah.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8413] = {title = "Vudú", objective = "Lleva las plumas vudú a Bath'rah el Vigía del viento.", description = "El tótem de espíritu no alcanza. Vamos a necesitar un poco de magia vudú.\n\nLos trols del Templo Sumergido tienen plumas mágicas muy poderosas. Debes ir allí y matar a Gasher, Mijan, Zolo, Hukku, Zul'lor y Loh'ro. Entonces tendremos suficiente magia para un verdadero tótem de espíritu.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Puños azuritaBastón salvajePodrás elegir una de estas recompensas:\n\nEspíritu de agua enamorado\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][8414] = {title = "Expulsión de los demonios", objective = "Recoge 20 piedras de la Plaga del esbirro y entrégaselas al sumo sacerdote Thel'danis en las Tierras de la Peste del Oeste.", description = "Saludos, <clase>. Los cruzados como tú siempre son bienvenidos en esta tierra desolada.\n\nTu sagrada fuerza es necesaria para combatir al número infinito de no-muertos. Necesitamos que reúnas un gran número de piedras de la Plaga y que las entregues al sumo sacerdote Thel'danis. Podrás encontrarlo custodiando la Tumba de Uther en la Colina de las Penas, no lejos de aquí.\n\nSolo quien lleve una Comisión de El Alba Argenta podrá encontrar piedras de la Plaga, así que habla con la oficial Purocorazón si aún no tienes ninguna.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8415] = {title = "Campamento del Orvallo", objective = "Habla con el comandante Ashlam Puñovalor en el Campamento del Orvallo.", description = "El comandante Ashlam Puñovalor ha hecho un llamamiento en busca de un paladín de tu pureza y valor, <nombre>. Podrás encontrarle en el Campamento del Orvallo, en la parte meridional de las Tierras de la Peste del Oeste. ¡Búscalo y contribuye a su causa en defensa de la Luz!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8417] = {title = "Un espíritu afligido", objective = "Habla con el héroe caído de la Horda en la entrada de Las Tierras Devastadas.", description = "En Las Tierras Devastadas habita un espíritu preocupado que fue un día un gran héroe de la Horda. El honor de un guerrero no perece con su cuerpo, debería serte de ayuda hablar con él.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8418] = {title = "La forja de la piedra de poderío", objective = "Obtén plumas vudú ámbar, azules y verdes de los trols del Templo Sumergido.", description = "Ahora tenemos que combinar las piedras de la Plaga inertes y crear un arma que destroce las filas de no-muertos. No es una tarea sencilla, <nombre>. Solo los trols del Templo Sumergido son portadores del tipo de extraña magia que puede convertir el mal en algo contrario a sí mismo.\n\nLos trols del Templo son conocidos como Gasher, Mijan, Zolo, Hukku, Zul'lor y Loh'ro. No sientas ningún remordimiento por sus corruptas almas... no están libres de mal.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Hoja forjada con luzPodrás elegir una de estas recompensas:\n\nOrbe santificadoSello caballeresco\n\nTambién recibirás:\n\nPiedra de poderío sagrada"}
MultiLanguageQuestData['mx'][8419] = {title = "Pedido de un diablillo", objective = "Lleva un retal de tela vil a Diblis a Frondavil.", description = "<nombre>, un diablillo de Frondavil, llamado Diblis, ha pedido tu presencia. Es algo extraño, pidió que llevaras contiguo una pieza de tela vil como símbolo de tu buena fe. Teniendo en cuenta tu poder como brujo supongo que ya sabrás que los sátiros de Frondavil llevan consigo telas viles.\n\nEncontrarás a Diblis al norte de las Cascadas del Veneno, un lugar realmente encantador en esta época del año.", progress = "¿Tienes mi tela vil?", completion = "¡Eres una &lt;clase&gt; excelente!\n\n\n\nOh, me encanta el tacto de la tela, cómo quema la piel y cómo entreteje pensamientos malvados en la mente...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8421] = {title = "La mercancía equivocada", objective = "Lleva 10 maderas putrefactas y 4 esencias de veneno a Diblis a Frondavil.", description = "Ahora que tengo mi tela vil, puedo empezar a hacer mi mascota.\n\nPero va a necesitar unos ojos... Quizás puedas robar un poco de madera podrida de los Troncoferro, para que pueda tallarle unos bonitos ojos. Están al norte, en el Bosque de Troncoferro.\n\nY también necesitaré un poco de esencia de veneno para que tenga olorcillo a demonio. Los mocos corruptos tienen esa esencia. Suelen estar por aquí, cerquita de Niby y de mí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8422] = {title = "Plumas de trol", objective = "Reúne un total de 6 plumas vudú en el Templo Sumergido.", description = "Casi he acabado mi mascota. Ahora necesito algo para rellenarla.\n\nY solo pueden ser plumas vudú de los trols del Templo Sumergido. Se llaman Gasher, Mijan, Zolo, Hukku, Zul'lor y Loh'ro. Mátalos. Mátalos a todos.\n\nNo será tarea fácil, <nombre>, pero haré que te merezca la pena correr el riesgo. Te daré una cosa de Niby... no creo que vaya a necesitarla de todas formas.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Togas de ServidumbreCosechador de almasPodrás elegir una de estas recompensas:\n\nFragmento Abisal\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][8423] = {title = "Parentesco guerrero", objective = "Mata a 7 jabinfernos de Las Tierras Devastadas y vuelve junto al héroe caído de la Horda.", description = "<El Héroe te mira detenidamente.>\n\nEres <un/una> <clase>, vaya si lo eres. Te encargaría una tarea honorable pero primero debo poner a prueba tu fuerza.\n\nDicen que Rexxar mide el filo de sus espadas matando a un jabinferno de un solo sablazo. Así que mediré la fuerza que tienes por cómo los matas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8424] = {title = "La guerra contra los Sombra Jurada", objective = "Acaba con los Sombra Jurada en Las Tierras Devastadas y regresa junto al héroe caído de la Horda.", description = "La continuada presencia de los Sombra Jurada en Las Tierras Devastadas me entristece sobremanera. Sus oscuros rituales y hechizos causan agonía como nada que yo sufriera en vida.\n\nA través de ti puedo enviar mi mensaje de dolor. Adelante y transmíteles mi ira.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8425] = {title = "Plumas Vudú", objective = "Llévale las plumas vudú de los trols del Templo Sumergido al héroe caído de la Horda.", description = "Tu honor me ha devuelto algo de paz. Es de justicia que te entregue algo a cambio.\n\nMis armas y armadura eran espléndidas en vida pero ahora ya no me sirven. Cumplirán mejor su función en tu posesión.\n\nVe al Templo Sumergido y destruye a los trols guardianes Gasher, Mijan, Zolo, Hukku, Zul'lor y Loh'ro. Llevan plumas mágicas que pueden recrear mi cuerpo físico lo suficiente para que te pueda dar tu premio.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Sobrehombros Acero afiladoVisor de furiaPodrás elegir una de estas recompensas:\n\nFrasco de diamante\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][8426] = {title = "La batalla por Garganta Grito de Guerra", objective = "Entrega 3 marcas de honor de la Garganta Grito de Guerra a un Belisario de la Horda fuera de los campos de batalla.", description = "La batalla de la Garganta Grito de Guerra contra las centinelas Ala de Plata tiene una importancia vital. Con la excusa de estar protegiendo un bosque que no les pertenece, la Alianza intenta negar a la Horda una de sus principales fuentes de recursos madereros.\n\n¡No debemos permitirlo, <nombre>! ¡Vuelve a verme cuando puedas demostrar que has servido a la Horda dignamente!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8427] = {title = "La batalla por Garganta Grito de Guerra", objective = "Entrega 3 marcas de honor de la Garganta Grito de Guerra a un Belisario de la Horda fuera de los campos de batalla.", description = "La batalla de la Garganta Grito de Guerra contra las centinelas Ala de Plata tiene una importancia vital. Con la excusa de estar protegiendo un bosque que no les pertenece, la Alianza intenta negar a la Horda una de sus principales fuentes de recursos madereros.\n\n¡No debemos permitirlo, <nombre>! ¡Vuelve a verme cuando puedas demostrar que has servido a la Horda dignamente!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
