MultiLanguageQuestData['mx'][8436] = {title = "La conquista de la Cuenca de Arathi", objective = "Entrega 3 marcas de honor de la Cuenca de Arathi a un Belisario de la Horda fuera de los campos de batalla.", description = "Nuestro conflicto con la Alianza se ha convertido en una auténtica guerra. En este momento ya no valen falsas excusas para entrar en la batalla.\n\nLa batalla por la Cuenca de Arathi es por los recursos, llana y simplemente. Si la Alianza se hace con ellos y los utiliza contra nosotros o si somos nosotros los que los obtenemos y los utilizamos para mantener nuestro esfuerzo bélico. ¡Ayuda a Los Rapiñadores a mantener el flujo de recursos que necesitamos, <nombre>!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8437] = {title = "La conquista de la Cuenca de Arathi", objective = "Entrega 3 marcas de honor de la Cuenca de Arathi a un Belisario de la Horda fuera de los campos de batalla.", description = "Nuestro conflicto con la Alianza se ha convertido en una auténtica guerra. En este momento ya no valen falsas excusas para entrar en la batalla.\n\nLa batalla por la Cuenca de Arathi es por los recursos, llana y simplemente. Si la Alianza se hace con ellos y los utiliza contra nosotros o si somos nosotros los que los obtenemos y los utilizamos para mantener nuestro esfuerzo bélico. ¡Ayuda a Los Rapiñadores a mantener el flujo de recursos que necesitamos, <nombre>!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
