MultiLanguageQuestData['mx'][8656] = {title = "El camisote de asediador", objective = "Llévale el caparazón del dios antiguo, 2 ídolos de la vida, 5 escarabajos de oro y 5 escarabajos de terracota a Vethsera en Ahn'Qiraj. También debes alcanzar la reputación de honorable ante el Linaje de Nozdormu para completar esta misión.", description = "El inmencionable dios antiguo se despierta despacio de su sueño bajo Ahn'Qiraj. El terrible sino que aguarda a Azeroth podría llegar dentro de unos días o unos años; el tiempo nada significa para seres con su poder.\n\nCuando los astros sean favorables, desatará su ira contra todo ser viviente. Debes hallarlo antes de que ocurra y encontrar la forma de poner fin a su existencia.\n\nHazlo y tráeme un pedazo de sus restos. Te concederé una armadura como ningún mortal ha llevado... ¡una armadura hecha para quien ha acabado con un Dios!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCamisote de asediadorCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8657] = {title = "La diadema de asediador", objective = "Llévale la diadema de Vek'lor, 2 ídolos de la disputa, 5 escarabajos de bronce y 5 escarabajos de marfil a Andorgos en Ahn'Qiraj. También debes alcanzar la reputación de amistoso ante el Linaje de Nozdormu para completar esta misión.", description = "Los Emperadores Gemelos... sus incesantes susurros se cobran lentamente un precio sobre mi sano juicio. Se mofan de mí, a sabiendas de que no puedo dar un paso más en sus dominios para salvar a mi hermano Arygos.\n\nTengo visiones de sus monstruosos rostros y su poderosa corona. Pero me vengaré... Transformaré esos símbolos de poder Qiraji en unos más adecuados a nuestras necesidades.\n\nTráeme los componentes que necesito, <nombre>. Te fabricaré una celada de poder único.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDiadema de asediador"}
MultiLanguageQuestData['mx'][8658] = {title = "Los leotardos de asediador", objective = "Trae la piel de un gran gusano de arena, 2 ídolos del sol, 5 escarabajos de plata y 5 escarabajos de hueso para Kandrostrasz dentro de Ahn'Qiraj. Asimismo, también debes tener reputación Amistosa con el Linaje de Nozdormu para completar esta misión.", description = "¿Deseas demostrar cuánto vales a los de mi especie, mortal? Vale, quizás podemos ayudarnos mutuamente.\n\nEl antiguo gusano de arena, Ouro, es un ser cuyo poder es legendario. Se rumorea que el propio dios antiguo lo creó como una burla a la vida.\n\nSu piel no es natural... gruesa, casi impenetrable aunque flexible, lo que le permite desplazarse velozmente y con la gracia de criaturas mucho más pequeñas.\n\nTráeme una muestra de su piel y otros componentes menores y te fabricaré unas poderosas mallas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nLeotardos de asediadorCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8659] = {title = "Los espaldares de asediador", objective = "Llévale las ataduras de mando qiraji, 2 ídolos de la guerra, 5 escarabajos de cristal y 5 escarabajos de marfil a Andorgos en Ahn'Qiraj. También debes alcanzar la reputación neutral ante el Linaje de Nozdormu para completar esta misión.", description = "Se cuenta entre nosotros que el adorno de la armadura de los hombros que llevan las razas mortales se inspiró en un intento de emular las alas de un dragón.\n\nTráeme las esclavas que llevan los más importantes líderes qiraji y con ellas te forjaré unas hombreras ¡más temidas que las alas del mismísimo Nefarian!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nEspaldares de asediadorCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8660] = {title = "Borceguíes de clamacondenas", objective = "Llévale las ataduras de dominancia qiraji, 2 ídolos de la noche, 5 escarabajos de terracota y 5 escarabajos de marfil a Kandrostrasz en Ahn'Qiraj. Esta misión requiere la reputación neutral con la facción Linaje de Nozdormu.", description = "La magia qiraji es poderosa y antigua. Los más poderosos qiraji empuñan objetos de tal potencia que harían vacilar hasta a un dragón.\n\nTráeme las ataduras de dominancia qiraji y otros componentes menores y crearé un par de poderosas botas para ti.\n\nTe servirán cuando te enfrentes al enemigo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8661] = {title = "Las togas clamacondenas", objective = "Llévale la coraza del dios antiguo, 2 ídolos de la noche, 5 escarabajos de hueso y 5 escarabajos de cristal a Vethsera en Ahn'Qiraj. También debes alcanzar la reputación de honorable ante el Linaje de Nozdormu para completar esta misión.", description = "El inmencionable dios antiguo se despierta despacio de su sueño bajo Ahn'Qiraj. El terrible sino que aguarda a Azeroth podría llegar dentro de unos días o unos años; el tiempo nada significa para seres con su poder.\n\nCuando los astros sean favorables, desatará su ira contra todo ser viviente. Debes hallarlo antes de que ocurra y encontrar la forma de poner fin a su existencia.\n\nHazlo y tráeme un pedazo de sus restos. Te concederé una armadura como ningún mortal ha llevado... ¡una armadura hecha para quien ha acabado con un Dios!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8662] = {title = "El aro de clamacondenas", objective = "Llévale el aro de Vek'lor, 2 ídolos de muerte, 5 escarabajos de plata y 5 escarabajos de hueso a Andorgos en Ahn'Qiraj. También debes alcanzar la reputación de amistoso ante el Linaje de Nozdormu para completar esta misión.", description = "Los Emperadores Gemelos... sus incesantes susurros se cobran lentamente un precio sobre mi sano juicio. Se mofan de mí, a sabiendas de que no puedo dar un paso más en sus dominios para salvar a mi hermano Arygos.\n\nTengo visiones de sus monstruosos rostros y su poderosa corona. Pero me vengaré... Transformaré esos símbolos de poder qiraji en unos más adecuados a nuestras necesidades.\n\nTráeme los componentes que necesito, <nombre>. Te daré una celada de poder único.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][8663] = {title = "Las calzas clamacondenas", objective = "Llévale la piel del gran gusano de arena, 2 ídolos de Renacer, 5 escarabajos de oro y 5 escarabajos de terracota a Kandrostrasz en Ahn'Qiraj. También debes alcanzar la reputación de amistoso ante el Linaje de Nozdormu para completar esta misión.", description = "¿Deseas demostrar cuánto vales a los de mi especie, mortal? Vale, quizás podemos ayudarnos mutuamente.\n\nEl antiguo gusano de arena, Ouro, es un ser cuyo poder es legendario. Se rumorea que el propio dios antiguo lo creó como una burla a la vida.\n\nSu piel no es natural... gruesa, casi impenetrable aunque flexible, lo que le permite desplazarse velozmente y con la gracia de criaturas mucho más pequeñas.\n\nTráeme una muestra de su piel y otros componentes menores y te fabricaré unas poderosas mallas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
