MultiLanguageQuestData['mx'][8725] = {title = "Riosona el Ancestro", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nAutoforzarse: reverencia\n\nRecibirás:\n\nMoneda de linajeSobre rojo de la suerte"}
MultiLanguageQuestData['mx'][8726] = {title = "Lanza Reluciente el ancestro", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nAutoforzarse: reverencia\n\nRecibirás:\n\nMoneda de linajeSobre rojo de la suerte"}
MultiLanguageQuestData['mx'][8727] = {title = "Levesusurro el Ancestro", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nAutoforzarse: reverencia\n\nRecibirás:\n\nMoneda de linajeSobre rojo de la suerte"}
MultiLanguageQuestData['mx'][8729] = {title = "La cólera de Neptulon", objective = "Utiliza la boya de arcanita en La Vorágine espiral de la Bahía de la Tempestad de Azshara.", description = "¿Te he dado ya la mala noticia? Se llama Fauces: 30 metros de muerte y destrucción. Supongo que me he olvidado esa menudencia.\n\nMi superior clarividencia psico-psiónica me indica que el mejor lugar para lanzar esta boya está en la costa de Azshara: la Bahía de la Tempestad.\n\nBusca un remolino lleno de restos de naufragios.\n\nPor cierto, espero que tengas amigos.\n\nY, si por algún milagro, tienes éxito, lleva el fragmento de cetro a Anacronos.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Togas AguaoscuraPodrás elegir una de estas recompensas:\n\nSortija de Prolavades heladas\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][8731] = {title = "Servicio de campo", objective = "Preséntate ante Krug Machacacráneos en la Avanzada de la Legión de Orgrimmar delante de Colmen'Regal. Prepara tu documentación de instrucción de campo sin firmar, consigue la documentación de instrucción de campo firmada y llévaselas a Clamavientos Kaldon en el Fuerte Cenarion.\n\nNota: curar o lanzar hechizos benéficos a un miembro de la Legión de Orgrimmar, te marcará como JcJ.", description = "Hola, <nombre>. Antes de poder asignarte tareas más complicadas en la guerra, tendrás que hacer tu parte en el campo de batalla.\n\nEncontrarás al capitán Machacacráneos de la Legión de Orgrimmar fuera de Colmen'Regal.\n\nPreséntate ante él y vuelve a verme con alguna prueba de tu servicio. Tendré una misión más avanzada lista para ti.\n\nOh y, por favor, no te acerques a la Brigada de Forjaz. Hay mucha tensión entre nuestros voluntarios de la Alianza y la Horda.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nEncargo de combateEncargo de logísticaEncargo de táctica"}
MultiLanguageQuestData['mx'][8735] = {title = "La corrupción de Pesadilla", objective = "Ve a los 4 Portales del Sueño Esmeralda de Azeroth y recoge un fragmento de Corrupción de Pesadilla en cada uno. Habla otra vez con el guardián Remulos en Claro de la Luna cuando hayas completado la tarea.|n", description = "Debes ir a los cuatro portales del Sueño de Azeroth. Debes conseguir un fragmento de Corrupción de Pesadilla en cada uno de ellos. Están en poder de los dragonantes que viven allí. Regresa cuando hayas conseguido los fragmentos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8737] = {title = "Templario azur", objective = "Invoca y mata a un Templario azur y preséntate ante Bor Ferocrín en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas I para poder completar la misión.", description = "El Martillo Crepuscular y los nobles elementales a quienes adoran, suponen una amenaza formidable para nuestras operaciones en Silithus. Con los nuevos enemigos a los que nos enfrentamos dentro de Ahn'Qiraj, no podemos permitirnos bajar la guardia con nuestros enemigos del exterior.\n\nEncuentra la forma de invocar y destruir a un Templario azur y vete a informar a Bor Ferocrín.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de táctica CenarionSeguimiento del encargo táctico"}
MultiLanguageQuestData['mx'][8738] = {title = "Informe de exploración de Colmen'Regal", objective = "Contacta con el explorador Cenarion Landion en Colmen'Regal y entrega el informe de exploración de Colmen'Regal a Clamavientos Cuerno Digno en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas VII para poder completar la misión.", description = "Hemos enviado a nuestros mejores exploradores a las colmenas de silítidos para reunir información. El explorador Landion lleva varios días observando los movimientos de los silítidos en Colmen'Regal. Encuéntrale y consigue un informe por escrito. Necesitamos esa información lo antes posible para saber cómo actuar, <nombre>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de táctica CenarionSeguimiento del encargo táctico"}
MultiLanguageQuestData['mx'][8739] = {title = "Informe de exploración de Colmen'Ashi", objective = "Contacta con el explorador Cenarion Jalia en Colmen'Ashi y entrega el informe de exploración de Colmen'Ashi a Clamavientos Cuerno Digno en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas VIII para poder completar la misión.", description = "Hemos enviado a nuestros mejores exploradores a las colmenas de silítidos para reunir información. La exploradora Jalia lleva varios días observando los movimientos de los silítidos en Colmen'Ashi. Encuéntrala y consigue un informe por escrito. Necesitamos esa información lo antes posible para saber cómo actuar, <nombre>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de táctica CenarionEncargo de táctica"}
MultiLanguageQuestData['mx'][8740] = {title = "Los merodeadores Crepusculares", objective = "Mata a la maleante Crepuscular Morna y a 2 maleantes Crepusculares. Informa a Clamavientos Cuerno Digno cuando hayas completado tu misión. También debes llevar el Informe de tareas tácticas IX para poder completar la misión.", description = "Hemos avistado bandas de adeptos montados del Martillo Crepuscular asaltando a nuestras patrullas y caravanas más pequeñas, pero quedan fuera del alcance de nuestras tropas en el Fuerte Cenarion.\n\nEncuentra y derrota a los forajidos y a su líder, un terrible guerrero llamado Morna. Vete a informar a Clamavientos Cuerno Digno cuando completes la misión.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de táctica CenarionSeguimiento del encargo táctico"}
MultiLanguageQuestData['mx'][8744] = {title = "Un presente envuelto con cuidado", objective = "La etiqueta de este regalo dice:\n\nPara <nombre>,\n\n¡Que pases unas dulces y felices fiestas del Gran Invierno!", description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nPresente envuelto con cuidado"}
MultiLanguageQuestData['mx'][8746] = {title = "Metzen el reno", objective = "Rescata a Metzen el reno de sus captores cerca de la Caverna Estrecha, en las Laderas de Trabalomas.", description = "¡Qué desastre! ¡Han secuestrado a Metzen el Reno!\n\nEs uno de los ocho renos de Padre Invierno y propiedad de Pastos de Bosquehumeante. Creemos que se lo ha llevado el ruin de Grinch el Abominable, que se esconde en las Laderas de Trabalomas. ¡Y precisamente ahora, con la fiesta, andamos ajustados de dinero! Por favor, ¡tráenos a Metzen, derrota a sus captores y tráenoslo de vuelta!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\nAcebo en conserva"}
