MultiLanguageQuestData['mx'][8762] = {title = "Metzen el reno", objective = "Rescata a Metzen el reno de sus captores cerca de la Caverna Estrecha, en las Laderas de Trabalomas.", description = "¡Qué desastre! ¡Han secuestrado a Metzen el Reno!\n\nEs uno de los ocho renos de Padre Invierno y propiedad de Pastos de Bosquehumeante. Creemos que se lo ha llevado el ruin de Grinch el Abominable, que se esconde en las Laderas de Trabalomas. ¡Y precisamente ahora, con la fiesta, andamos ajustados de dinero! Por favor, ¡tráenos a Metzen, derrota a sus captores y tráenoslo de vuelta!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAcebo en conserva"}
