MultiLanguageQuestData['mx'][8767] = {title = "Un obsequio ligeramente agitado", objective = "Parece que han agitado este regalo un par de veces. Su etiqueta dice: \n\nPara un <raza> <clase> muy especial.", description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nObsequio ligeramente agitado"}
MultiLanguageQuestData['mx'][8768] = {title = "Un presente con envoltorio alegre", objective = "El regalo está envuelto con motivos propios de estas fiestas y tiene tu nombre. \n\nEspera, ¿no acaba de moverse?", description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nPresente con envoltorio alegre"}
MultiLanguageQuestData['mx'][8769] = {title = "Un presente que hace tic-tac", objective = "Tus amigos de los Pastos de Bosquehumeante te desean unas felices Fiestas del Gran Invierno.", description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nPresente que hace tic-tac"}
MultiLanguageQuestData['mx'][8770] = {title = "Objetivo: los defensores Colmen'Ashi", objective = "Mata 30 defensores Colmen'Ashi y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate I para poder completar la misión.", description = "Según progresa la guerra, la presencia de silítidos en la zona supone una amenaza constante para nuestras operaciones. Te han seleccionado para participar en un asalto a Colmen'Ashi donde tu objetivo principal consistirá en los defensores Colmen'Ashi.\n\nInforma a la comandante Mar'alith cuando hayas terminado tu misión.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de combate CenarionCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8771] = {title = "Objetivo: los acecharenas Colmen'Ashi", objective = "Mata 30 acecharenas Colmen'Ashi y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate II para poder completar la misión.", description = "Según progresa la guerra, la presencia de silítidos en la zona supone una amenaza constante para nuestras operaciones. Te han seleccionado para participar en un asalto a Colmen'Ashi donde tu objetivo principal consistirá en los acecharenas Colmen'Ashi.\n\nInforma al comandante Mar'alith cuando hayas terminado u misión.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de combate CenarionCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8772] = {title = "Objetivo: los oteadores de Colmen'Zora", objective = "Mata 30 oteadores de Colmen'Zora y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate VI para poder completar la misión.|n", description = "Se han pedido refuerzos para unirse al asalto a Colmen'Zora. Te han seleccionado para atacar a los oteadores de Colmen'Zora. Informa a la comandante Mar’alith cuando hayas completado tu misión.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de combate CenarionCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8773] = {title = "Objetivo: los atracadores de Colmen'Zora", objective = "Mata 30 atracadores de Colmen'Zora y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate IV para poder completar la misión.", description = "Se han pedido refuerzos para unirse al asalto a Colmen'Zora. Te han seleccionado para atacar a los atracadores de Colmen'Zora. Informa a la comandante Mar’alith cuando hayas completado tu misión.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de combate Cenarion"}
MultiLanguageQuestData['mx'][8774] = {title = "Objetivo: los emboscadores Colmen'Regal", objective = "Mata 30 emboscadores Colmen'Regal y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate VIII para poder completar la misión.|n", description = "Según progresa la guerra, la presencia de silítidos en la zona supone una amenaza constante para nuestras operaciones. Te han seleccionado para participar en un asalto a Colmen'Regal donde tu objetivo principal consistirá en los emboscadores Colmen'Regal.\n\nInforma al comandante Mar'alith cuando hayas terminado tu misión.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de combate CenarionCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8775] = {title = "Objetivo: los escupefuegos Colmen'Regal", objective = "Mata 30 escupefuegos Colmen'Regal y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate IX para poder completar la misión.|n", description = "Según progresa la guerra, la presencia de silítidos en la zona supone una amenaza constante para nuestras operaciones. Te han seleccionado para participar en un asalto a Colmen'Regal donde tu objetivo principal consistirá en los escupefuegos aéreos Colmen'Regal.\n\nInforma al comandante Mar'alith cuando hayas terminado tu misión.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de combate CenarionCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8776] = {title = "Objetivo: los esclavizadores Colmen'Regal", objective = "Mata 30 esclavizadores Colmen'Regal y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate X para poder completar la misión.|n", description = "Según progresa la guerra, la presencia de silítidos en la zona supone una amenaza constante para nuestras operaciones. Te han seleccionado para participar en un asalto a Colmen'Regal donde tu objetivo principal consistirá en los esclavizadores Colmen'Regal.\n\nInforma al comandante Mar'alith cuando hayas terminado tu misión.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de combate CenarionCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8777] = {title = "Objetivo: los perforadores Colmen'Regal", objective = "Mata 30 perforadores Colmen'Regal y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate XI para poder completar la misión.|n", description = "Según progresa la guerra, la presencia de silítidos en la zona supone una amenaza constante para nuestras operaciones. Te han seleccionado para participar en un asalto a Colmen'Regal donde tu objetivo principal consistirá en los perforadores Colmen'Regal.\n\nInforma al comandante Mar'alith cuando hayas terminado tu misión.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de combate CenarionCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8778] = {title = "¡La Brigada de Forjaz necesita explosivos!", objective = "Lleva 6 aceites de inmolación, 5 combustibles de cohete goblin y 10 unidades de pólvora densa al arcanista Bocafuente cerca de Colmen'Zora en Silithus. También debes llevar el Informe de tareas logísticas IV para poder completar la misión.", description = "La Brigada de Forjaz ha solicitado un extraño pedido de componentes... muy volátiles. Reúnelos y llévaselos al señor Bocafuente de la Brigada de Forjaz.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de logística CenarionSeguimiento del encargo de logística"}
MultiLanguageQuestData['mx'][8779] = {title = "Materiales de visión", objective = "Lleva 1 fragmento luminoso grande, 1 fragmento radiante grande y 1 esmeralda enorme a la Geóloga Trotuina en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas V para poder completar la misión.", description = "Los estudios de la Geóloga Trotuina han demostrado ser de gran valor para nuestras operaciones en Silithus. Recientemente, ha solicitado materiales de visión para utilizar en su investigación.\n\nPor favor, consigue esos materiales y llévaselos directamente a ella para que pueda continuar con su investigación.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de logística CenarionSeguimiento del encargo de logística"}
MultiLanguageQuestData['mx'][8780] = {title = "Refuerzos para armadura para el campo de batalla", objective = "Lleva 8 refuerzos para armadura bastos y 8 refuerzos para armadura pesados a Janela Martillotenaz en la Avanzada de la Brigada de Forjaz, cerca de Colmen'Zora, en Silithus. También debes llevar el Informe de tareas logísticas VII para poder completar la misión.", description = "El suministro de refuerzos para armadura de la Brigada de Forjaz en el campo de batalla, está empezando a escasear peligrosamente. Consigue un lote de refuerzos y llévaselo a Janela Martillotenaz en la Avanzada de la Brigada de Forjaz, justo fuera de Colmen'Zora.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de logística CenarionSeguimiento del encargo de logística"}
MultiLanguageQuestData['mx'][8781] = {title = "Armas para el campo de batalla", objective = "Lleva 2 espadas anchas de acero lunar a Janela Martillotenaz en la Avanzada de la Brigada de Forjaz, en las afueras de Colmen'Zora. También debes llevar el Informe de tareas logísticas VI para poder completar la misión.", description = "La Brigada de Forjaz ha sido un poderoso aliado en nuestra batalla en Silithus. Por desgracia, perdieron muchos suministros de camino hacia aquí. Consigue un lote de armas y llévaselo a Janela Martillotenaz, está cerca de Colmen'Zora.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de logística CenarionSeguimiento del encargo de logística"}
MultiLanguageQuestData['mx'][8782] = {title = "Suministros para uniformes", objective = "Lleva 1 tela lunar, 2 madejas de paño rúnico y 1 seda de araña Tejehierro a Clamavientos Cuerno Digno en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas VIII para poder completar la misión.", description = "La última entrada de voluntarios ha provocado escasez de uniformes. Consigue un lote de materiales de uniforme y llévaselo a Clamavientos Cuerno Digno.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de logística CenarionEncargo de logística"}
MultiLanguageQuestData['mx'][8783] = {title = "Materiales encantados", objective = "Lleva 2 barras de torio encantado y 2 cueros encantados a Vargus en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas IX para poder completar la misión.", description = "Vargus, el herrero del Fuerte Cenarion, ha solicitado materiales encantados para crear poderosas armas para nuestras tropas. Consíguelos y llévaselos directamente a Vargus para que las tropas del Fuerte Cenarion puedan seguir estando bien equipadas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de logística CenarionEncargo de logística"}
MultiLanguageQuestData['mx'][8784] = {title = "Los secretos de los qiraji", objective = "Llévale el artefacto antiguo qiraji a los dragones ocultos cerca de la entrada del templo.|n", description = "¡Has descubierto un antiguo artefacto de Ahn'Qiraj! Esta reliquia quizás sea de utilidad para uno de los dragones que se encuentra cerca de la puerta del templo.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][8785] = {title = "¡La Legión de Orgrimmar necesita mojo!", objective = "Lleva 6 mojos potentes, 6 frascos de gran mojo y 8 aceites de inmolación a la sacerdotisa de las Sombras Shai cerca de Colmen'Regal, en Silithus. También debes llevar el Informe de tareas logísticas IV para poder completar la misión.", description = "La Legión de Orgrimmar ha solicitado varios ingredientes muy poco usuales. Dada su situación actual en Silithus, queremos entregarles los suministros tan pronto como podamos. Reúne los materiales y llévaselos a la trol llamada Shai.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de logística CenarionSeguimiento del encargo de logística"}
MultiLanguageQuestData['mx'][8786] = {title = "Armas para el campo de batalla", objective = "Lleva 3 hachas de hierro macizo a Merok Zancada Larga en el campamento de la Legión de Orgrimmar, en las afueras de Colmen'Regal. También debes llevar el Informe de tareas logísticas VI para poder completar la misión.", description = "La Legión de Orgrimmar ha solicitado unas armas adicionales que no hemos sido capaces de suministrar. Consigue las armas que nos han pedido y llévaselas a Merok Zancada Larga fuera de Colmen'Regal.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de logística CenarionSeguimiento del encargo de logística"}
MultiLanguageQuestData['mx'][8787] = {title = "Refuerzos para armadura para el campo de batalla", objective = "Lleva 8 refuerzos para armadura bastos y 8 refuerzos para armadura pesados a Merok Zancada Larga, cerca de Colmen'Regal. También debes llevar el Informe de tareas logísticas VII para poder completar la misión.", description = "Los valientes voluntarios de la Legión de Orgrimmar han venido a Silithus para ayudarnos en nuestra causa. De alguna forma, perdieron sus refuerzos para armadura durante el viaje. Consigue un lote de armaduras y llévaselas a Merok Zancada Larga al campamento de la Legión de Orgrimmar.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de logística CenarionSeguimiento del encargo de logística"}
MultiLanguageQuestData['mx'][8788] = {title = "Un obsequio ligeramente agitado", objective = "Parece que han agitado este regalo un par de veces. Su etiqueta dice:\n\nPara un <raza> <clase> muy especial.", description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nObsequio ligeramente agitado"}
MultiLanguageQuestData['mx'][8789] = {title = "Armamentos imperiales qiraji", objective = "Arygos en el Templo de Ahn'Qiraj creará armamento imbuido de elementium para ti si le llevas armamento imperial qiraji y 3 lingotes de elementium.", description = "No hemos estado ociosos durante un milenio, <nombre>.\n\nHemos estado observando cómo estas bestias lo celebraban a solas cuando habían cumplido su propósito. Hemos estado escuchando cómo tramaban y se confabulaban para destruir nuestro mundo. Y nos hemos enterado de sus propias traiciones internas.\n\nExisten puntos débiles y sabemos cómo usarlos a nuestro favor.\n\nEncuentra sus armamentos ceremoniales y tráemelos. Combinados con el elemento creado a partir de la volatilidad de su propio Dios, se convertirán en una fuerza considerable.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Hacha de guerra qiraji benditaPugio qiraji benditoBaluarte qiraji benditoMosquete qiraji benditoRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8790] = {title = "Atavío imperial qiraji", objective = "Merithra del Sueño en el Templo de Ahn'Qiraj creará armamento imbuido de elementium para ti si le llevas un atavío imperial qiraji y 3 lingotes de elementium.|n", description = "Según una teoría de Arygos el elemento nacido de conflictos entre los dioses antiguos y sus esbirros también es extremadamente fatal para ellos si se dan las condiciones adecuadas. Me refiero al elementium, mortal.\n\nEncuentra un atavío imperial qiraji y tráemelo junto con el elemento tóxico para infundir con ellos armas de gran poder.\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Martillo de guerra qiraji benditoBastón de acólito qiraji benditoBastón de augur qiraji benditoRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8791] = {title = "La caída de Osirio", objective = "Entrégale la cabeza de Osirio el Sinmarcas al comandante Mar'alith de Fuerte Cenarion en Silithus.|n", description = "Se acabó esa terrible amenaza. El cruel Osirio ha sido derrotado.\n\nLos vecinos de Kalimdor sentirán gran alivio cuando conozcan la noticia. Coge la cabeza de Osirio y llévasela al comandante Mar'alith de Fuerte Cenarion.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nTalismán del Mar de DunasGargantilla del Mar de DunasColgante del Mar de DunasAmuleto del Mar de Dunas\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][8792] = {title = "¡La Horda te necesita!", objective = "Habla con el señor de la guerra Gorchuk en el Valle de los Espíritus de Orgrimmar.", description = "Hola, ¡qué bien que hayas decidido escucharme! La Horda necesita toda la ayuda posible para preparar la guerra de Ahn'Qiraj ¡y eso significa que te necesitamos a ti también! En este mismo instante, los recolectores oficiales están reuniendo el material necesario para la guerra que se avecina, pero no lograremos nuestro objetivo sin tu ayuda, <nombre>!\n\nDeberías hablar con quien está al mando, el señor de la guerra Gorchuk. ¿Qué me dices, <clase>? ¿Nos ayudarás con estos preparativos vitales?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8793] = {title = "¡La Horda te necesita!", objective = "Habla con el señor de la guerra Gorchuk en el Valle de los Espíritus de Orgrimmar.", description = "Hola, ¡qué bien que hayas decidido escucharme! La Horda necesita toda la ayuda posible para preparar la guerra de Ahn'Qiraj ¡y eso significa que te necesitamos a ti también! En este mismo instante, los recolectores oficiales están reuniendo el material necesario para la guerra que se avecina, pero no lograremos nuestro objetivo sin tu ayuda, <nombre>!\n\nDeberías hablar con quien está al mando, el señor de la guerra Gorchuk. ¿Qué me dices, <clase>? ¿Nos ayudarás con estos preparativos vitales?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8799] = {title = "El héroe del día", objective = "Lleva 1 porción de sal de roca y 5 monedas de oro al conservante de acebo; recibirás 5 acebos conservados.", description = "Oye, se supone que no tendría que decirte esto, pero como todo el mundo te admira y tal...\n\nEn esta época del año hay mucho acebo, pero no dura nada. Tenemos una máquina que lo conserva siempre fresco. Lo usamos para dar color durante las fiestas... ¡y para hacer negocio en verano!\n\nTe dejo usar el conservador si demuestras tu habilidad en la cocina. Necesitas sal de roca y unos cinco oros. Te prepararé una hornada toda para ti.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAcebo en conserva"}
MultiLanguageQuestData['mx'][8800] = {title = "Equipamiento de Cenarius", objective = "Habla con Vargus en el Fuerte Cenarion, en Silithus.", description = "Cuando vayas completando las misiones que te asignen en la guerra, vete a hablar con Vargus, el herrero. Muéstrale las insignias que hayas obtenido. Te proporcionará equipamiento afín a tu nivel de entrega a nuestra causa.Cuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][8801] = {title = "El legado de C'Thun", objective = "Llévale el ojo de C'Thun a Caelastrasz en el Templo de Ahn'Qiraj.", description = "Los muros de Ahn'Qiraj tiemblan. Una fuerza del mal, más antigua que el mismo mundo, ha sido destruida.\n\nAl mirar los restos de esa colosal abominación, casi se te congela el corazón. Incluso después de <muerto/muerta>, puedes sentir la herencia de la maldad de C'Thun a tu alrededor.\n\nHas logrado lo que parecía imposible.\n\nConsigues sacar el ojo de ese monstruo y lo pones a buen recaudo en tu bolsa.\n\nLleva el ojo de C'Thun a los dragones de la cámara siguiente.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8803] = {title = "Un obsequio festivo", objective = "La nota de este regalo dice:\n\nPara <nombre>,\n\ncon la esperanza de que te ayude a repartir calor y felicidad por todo Azeroth.\n\nDe parte del Gran Padre Invierno.", description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nObsequio festivo"}
MultiLanguageQuestData['mx'][8804] = {title = "Material de supervivencia en el desierto", objective = "Lleva 4 globos de agua, 4 contravenenos potentes y 4 albóndigas del desierto ahumadas a Calandrath en la taberna del Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas I para poder completar la misión.", description = "Con la llegada de reclutas frescos al Fuerte Cenarion llega también el problema de su supervivencia en el desierto. Las innumerables criaturas venenosas que viven en él y la deshidratación son serias amenazas para los voluntarios poco experimentados. Reúne los suministros necesarios para un equipo de supervivencia en el desierto y llévaselos a Calandrath al Fuerte Cenarion.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de logística CenarionEncargo de logística"}
MultiLanguageQuestData['mx'][8805] = {title = "Botas para la guardia", objective = "Lleva 3 botas de mitril ornamentado a Vish Kozus, Capitán de la guardia del Fuerte Cenarion en Silithus. También debes llevar el Informe de tareas logísticas II para poder completar la misión.", description = "La división montada de la guardia del Fuerte Cenarion tiene escasez de botas de mitril ornamentado. Consigue un cargamento y entrégaselo inmediatamente al capitán Vish Kozus en el Fuerte Cenarion.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de logística CenarionEncargo de logística"}
MultiLanguageQuestData['mx'][8806] = {title = "Piedra de pulir para la guardia", objective = "Lleva 10 piedras de pulir densas, 10 piedras de pulir sólidas y 10 piedras de pulir pesadas a Vish Kozus, Capitán de la guardia del Fuerte Cenarion en Silithus. También debes llevar el Informe de tareas logísticas III para poder completar la misión.", description = "La guardia del Fuerte Cenarion tiene escasez de muelas. Consigue un cargamento y entrégaselo inmediatamente al capitán Vish Kozus en el Fuerte Cenarion.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de logística CenarionEncargo de logística"}
MultiLanguageQuestData['mx'][8807] = {title = "Materiales de visión", objective = "Lleva 1 fragmento luminoso grande, 1 fragmento radiante grande y 1 esmeralda enorme a la Geóloga Trotuina en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas V para poder completar la misión.", description = "Los estudios de la Geóloga Trotuina han demostrado ser de gran valor para nuestras operaciones en Silithus. Recientemente, ha solicitado materiales de visión para utilizar en su investigación.\n\nPor favor, consigue esos materiales y llévaselos directamente a ella para que pueda continuar con su investigación.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de logística CenarionSeguimiento del encargo de logística"}
MultiLanguageQuestData['mx'][8808] = {title = "Suministros para uniformes", objective = "Lleva 1 tela lunar, 2 madejas de paño rúnico y 1 seda de araña Tejehierro a Clamavientos Cuerno Digno en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas VIII para poder completar la misión.", description = "La última entrada de voluntarios ha provocado escasez de uniformes. Consigue un lote de materiales de uniforme y llévaselo a Clamavientos Cuerno Digno.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de logística CenarionEncargo de logística"}
MultiLanguageQuestData['mx'][8809] = {title = "Materiales encantados", objective = "Lleva 2 barras de torio encantado y 2 cueros encantados a Vargus en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas IX para poder completar la misión.", description = "Vargus, el herrero del Fuerte Cenarion, ha solicitado materiales encantados para crear poderosas armas para nuestras tropas. Consíguelos y llévaselos directamente a Vargus para que las tropas del Fuerte Cenarion puedan seguir estando bien equipadas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de logística CenarionEncargo de logística"}
MultiLanguageQuestData['mx'][8810] = {title = "Vendas para el campo de batalla", objective = "Lleva 30 vendas de paño rúnico gruesas, 30 vendas de seda gruesas y 30 vendas de tejido mágico gruesas a Clamavientos Cuerno Digno en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas X para poder completar la misión.", description = "Debido a las víctimas que hemos tenido recientemente, nuestro suministro de vendajes en el campo de batalla empieza a escasear peligrosamente. Consigue un lote de suministros de primeros auxilios y llévaselo a Clamavientos Cuerno Digno en el Fuerte Cenarion.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDistintivo de logística CenarionSeguimiento del encargo de logística"}
