MultiLanguageQuestData['mx'][8827] = {title = "Regalos del invierno", objective = "Habla con el Gran Padre Invierno. Lo encontrarás junto a la zona de comercio de los Pastos de Bosquehumeante de Forjaz.", description = "He oído que el Gran Padre Invierno (con la generosa ayuda de los Pastos de Bosquehumeante) ha dejado regalos para todos bajo el árbol de Forjaz. Ojalá pudiera ir, pero tengo que vigilar el PX-238 Maravoltio Nevada.\n\nPero tú no deberías perdértelo. Seguro que el Gran Padre Invierno ha dejado algún regalo con tu nombre.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8828] = {title = "Regalos del invierno", objective = "Habla con el Gran Padre Invierno. Lo encontrarás junto a la zona de comercio de los Pastos de Bosquehumeante de Orgrimmar.", description = "He oído que el Gran Padre Invierno (con la generosa ayuda de los Pastos de Bosquehumeante) ha dejado regalos para todos bajo el árbol de Orgrimmar. Ojalá pudiera ir, pero tengo que vigilar el PX-238 Maravoltio Nevada.\n\nPero tú no deberías perdértelo. Seguro que el Gran Padre Invierno ha dejado algún regalo con tu nombre.", progress = nil, completion = "¡Oh, hola! Solo puedes haber venido por una razón: para abrir tus regalos del Festival de Invierno.\n\nNo, no te preocupes, el Gran Padre Invierno no se ha olvidado de su &lt;raza&gt; &lt;clase&gt; favorito. Mira debajo del árbol y encontrarás tus regalos.\n\nEn estos días de generosidad, ¿no crees que a tus amigos les gustaría tener alguno de los excelentes productos de los Pastos de Bosquehumeante?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8829] = {title = "El último engaño", objective = "Lleva 1 piel de Sombra, 3 costuras desgarradas de abominación y 1 toga de cultor Crepuscular a Aurel Hojaurea en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas XI para poder completar la misión.|n", description = "El Martillo Crepuscular opera a través de innumerables capas de secretismo y engaños. Mientras que sus acciones toman forma en nuestro mundo, se planean en un lugar donde todavía no hemos conseguido llegar.\n\nHemos llegado a pensar que las piedras que el Martillo Crepuscular utiliza para invocar a sus superiores, permiten un transporte de ida y vuelta. Para intentar usarlas de esa forma, debemos copiar, hasta el último detalle, una túnica de emisario Crepuscular.\n\nReúne los materiales necesarios y llévaselos a Aurel Hojaurea, <nombre>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nMarca de Remulos"}
