MultiLanguageQuestData['mx'][8860] = {title = "¡Las fiestas de Año Nuevo!", objective = "Lleva la comida de Pastos de Bosquehumeante a la tabernera Allison de Ventormenta.", description = "¡Ventormenta celebra un festival por año nuevo! ¡Habrá bebidas gratis todo el día y fuegos artificiales por la noche! Seguro que está muy bien, pero también hay fiesta en la Bahía del Botín y seguro que es mejor.\n\nEn todo caso, Allison, la tabernera de Ventormenta, necesita comida de Pastos de Bosquehumeante para los juerguistas. ¿Puedes ir tú a llevársela?\n\n¡Gracias, <nombre>! La tabernera Allison está en La Rosa Áurea, en el Distrito de Mercaderes de Ventormenta.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8861] = {title = "¡Las fiestas de Año Nuevo!", objective = "Lleva la comida de Pastos de Bosquehumeante a la tabernera Pala de Cima del Trueno.", description = "¡Cima del Trueno va a celebrar el Año Nuevo! ¡Habrá bebidas durante todo el día, y por la noche tirarán fuegos artificiales!\n\nSeguro que está muy bien, pero también hay fiesta en la Bahía del Botín y seguro que es mejor.\n\nEn todo caso, Pala, la tabernera de Cima del Trueno, necesita provisiones de Pastos de Bosquehumeante para los juerguistas. ¿Puedes ir tú a llevársela?\n\n¡Gracias, <nombre>! La tabernera Pala está en la posada cerca del puente a Alto de los Cazadores.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8863] = {title = "Albóndigas festivas", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nAlbóndigas festivas"}
MultiLanguageQuestData['mx'][8864] = {title = "Vestidos para el Festival Lunar", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nVestido de fiesta verdeVestido de fiesta rosaVestido de fiesta morado\n\nTambién recibirás:\n\nPaquete de fuegos artificiales del Festival Lunar"}
MultiLanguageQuestData['mx'][8865] = {title = "Trajes pantalón para el Festival Lunar", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nTraje pantalón de fiesta negroTraje pantalón de fiesta verde azuladoTraje pantalón de fiesta azul\n\nTambién recibirás:\n\nPaquete de fuegos artificiales del Festival Lunar"}
MultiLanguageQuestData['mx'][8866] = {title = "Barbabronce el Ancestro", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nAutoforzarse: reverencia\n\nRecibirás:\n\nMoneda de linajeSobre rojo de la suerte"}
MultiLanguageQuestData['mx'][8867] = {title = "Fuegos artificiales lunares", objective = "Dispara 8 fuegos artificiales lunares y 2 cohetes y acude a una presagista del Festival Lunar de cualquier capital.", description = "Todos los años los druidas del Claro de la Luna celebran la gran victoria de nuestra ciudad sobre un antiguo mal.\n\nCelebramos la sabiduría de nuestros ancestros, participamos en magníficas fiestas y, por supuesto... ¡disparamos fuegos artificiales!\n\nA cambio de una pequeña donación puedes adquirir cohetes de colores de nuestro vendedor. Prueba a usarlos en uno de los lanzacohetes que hay por aquí, <nombre>.", progress = nil, completion = "Bien hecho, &lt;nombre&gt;.\n\nAhora que ya estás metido en el ambiente, ¿por qué no aceptas esta invitación al Festival Lunar?\n\nEs una celebración fantástica si tienes algo de tiempo. Hay comida, bebida, se cuentan cuentos y... claro, ¡hay más fuegos artificiales!\n\nAbre la invitación cuando estés dentro del círculo de La Gran Luz de Luna y serás transportado directamente al Claro de la Luna.", rewards = "Recibirás:\n\nInvitación al Festival LunarCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8869] = {title = "Dulce serenidad", objective = "Viaja a Stratholme y mata al forjamartillos Carmesí. Consigue el delantal del forjamartillos Carmesí y regresa con Lilith.|n", description = "En los confines de El Bastión Escarlata se encuentra la dulce Serenidad. El Forjamartillos Carmesí protegerá su secreto con su vida. Derrótalo y tráeme su delantal. Si lo haces, te ayudaré a convertirte en <un forjador/una forjadora> de martillos.\n\nPero ten clara una cosa: una vez elegido el camino del forjador de martillos, los caminos de forjador de espadas y de forjador de hachas te quedarán vedados.\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nDiseño: martillo de batalla encantado"}
MultiLanguageQuestData['mx'][8873] = {title = "El Festival Lunar", objective = "Habla con la presagista del Festival Lunar en el Valle de la Sabiduría, en Orgrimmar. También puedes hablar con la presagista del Festival Lunar en otras capitales.", description = "¡Ha llegado ese momento del año, <nombre>! El Círculo Cenarion invita a todos los ciudadanos de Azeroth a participar en la celebración del Festival Lunar. Encontrarás a la presagista del Festival Lunar en esta misma ciudad. Busca el lugar marcado por un círculo sagrado de Luz de Luna. Ella podrá decirte más cosas sobre el Festival.", progress = nil, completion = "Bienvenido, &lt;nombre&gt;. ¿Estás aquí para unirte a la celebración?", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8874] = {title = "El Festival Lunar", objective = "Habla con la presagista del Festival Lunar en la entrada de Entrañas. También puedes hablar con otras presagistas del Festival Lunar de otras capitales.", description = "¡Ha llegado ese momento del año, <nombre>! El Círculo Cenarion invita a todos los ciudadanos de Azeroth a participar en la celebración del Festival Lunar. Encontrarás a la presagista del Festival Lunar en esta misma ciudad. Busca el lugar marcado por un círculo sagrado de Luz de Luna. Ella podrá decirte más cosas sobre el Festival.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8875] = {title = "El Festival Lunar", objective = "Habla con la presagista del Festival Lunar en el Alto de los Ancestros de Cima del Trueno. También puedes hablar con otras presagistas del Festival Lunar de otras capitales.", description = "¡Ha llegado ese momento del año, <nombre>! El Círculo Cenarion invita a todos los ciudadanos de Azeroth a participar en la celebración del Festival Lunar. Encontrarás a la presagista del Festival Lunar en esta misma ciudad. Busca el lugar marcado por un círculo sagrado de Luz de Luna. Ella podrá decirte más cosas sobre el Festival.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8883] = {title = "Valadar Cantoestelar", objective = "Utiliza tu Invitación al Festival Lunar en la Luz de Luna y viaja al Claro de la Luna. Cuando llegues, habla con Valadar Cantoestelar en Amparo de la Noche.", description = "Ahora que tienes tu Invitación al Festival Lunar, puedes viajar al Claro de la Luna. Allí encontrarás a muchos juerguistas, además, en el poblado del Amparo de la Noche, Valadar Cantoestelar y su hermana Fariel aguardan a los que desean participar en las celebraciones.\n\nViaja al Claro de la Luna a través de La Gran Luz de Luna y habla con Valadar Cantoestelar; ¡mira qué premios puedes ganar durante el festival!", progress = nil, completion = "¡&lt;nombre&gt;, bienvenido al Amparo de la Noche, sede de El Festival Lunar! Aunque nuestro poblado está alejado y remoto para las gentes de Azeroth, durante estos días de celebración abrimos nuestros brazos y corazones a todo el mundo.\n\nDisfruta de tu visita, &lt;nombre&gt;, y vuelve a hablar conmigo o con mi hermana cuando estés listo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8884] = {title = "Aquí, pescadito...", objective = "Consigue 8 cabezas de múrlocs Malaescama. Llévaselas a Hathvelion Mirasol en el Bosque Canción Eterna, encima de la Orilla Tranquila.", description = "Saludos, <clase>. Echa un vistazo a la orilla. ¿Qué ves? Eso es, nuestra playa... nuestra Orilla Tranquila está infectada de múrlocs.\n\n¡No podemos seguir así!\n\nTengo una tarea para ti. Si crees poder estar a la altura, ¡quiero sus cabezas! Veamos si podemos diezmar sus filas para que, si tienen algo en la sesera, vuelvan a las apestosas profundidades de las que salieron.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8885] = {title = "El anillo de Mmmrrrggglll", objective = "Consigue el anillo de Mmmrrrggglll de las garras sin vida del jefe Malaescama. Llévaselo a Hathvelion Mirasol en el Bosque Canción Eterna, en el acantilado que domina la Orilla Tranquila.", description = "Los múrlocs Malaescama no se han asustado por lo que has hecho. Pero creo que sé lo que hará que se asusten y, de paso, lo que hará que yo me sienta mucho, mucho mejor.\n\nTienen un jefe múrloc que se hace llamar Mmmrrrggglll. Vaga por La Ensenada Dorada, al sur del brazo del río. Esa bestia mató a uno de mis compatriotas y ahora lleva puesto su anillo desafiándonos abiertamente.\n\nMata a Mmmrrrggglll y tráeme el anillo de mi amigo. ¡¡Entonces esos monstruos se asustarán!!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Rodela de ErranteHoja de forestal ligeramente usadaGuantes forrados de saténArco de forestal desgastadoRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8886] = {title = "¡Piratas Malaescama!", objective = "Recupera 6 piezas de la carga de la capitana Kelisendra y llévaselas al campamento fortificado que hay al este del Fondeadero Vela del Sol en el Bosque Canción Eterna.", description = "¡Suerte que estás aquí, <clase>! ¡Esos asquerosos múrlocs Malaescama me han robado la carga! Los desdichados se llevaron todos los objetos mágicos, ¡y los múrlocs se han llevado el resto! ¿Adónde iremos a parar?\n\n¿Puedes recuperar mi carga? No todo, por supuesto, pero a estas alturas te agradeceré cualquier cosa que me traigas. ¡Seguro que fueron los múrlocs de las cabañas que hay al oeste y sur de El Puerto de La Ensenada Dorada!\n", progress = "Agradezco la ayuda de alguien como tú, <nombre>. Casi me hace sonreír, pero entonces me acuerdo de lo que esos monstruos le han hecho a mi nave y de lo que está pasando en Quel'Thalas.\n\n¿Conseguiste recuperar parte de mi carga?", completion = "¡Fantástico! ¡Me has salvado de la ruina y me has vengado de esas asquerosas criaturas!\n\nAhora a ver si consigo que esas forestales tan guapas me ayuden con la carga y podré marcharme por fin. Tendré que volver cuando Velendris retome el astillero.\n\nTen esta moneda. No puedo permitirme más, pero lo menos que puedo hacer es pagarte por tu ayuda.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8887] = {title = "Rutas perdidas de la capitana Kelisendra", objective = "Devuelve los planes de navegación perdidos a la capitana Kelisendra, que está en el campamento fortificado que hay al este del Fondeadero Vela del Sol, en el Bosque Canción Eterna.", description = "Qué interesante... Has encontrado un cilindro de cuero estanco con varios pergaminos. A juzgar por los gráficos, se trata de planes de navegación, todos ellos firmados por una tal capitana Kelisendra.\n\nHas oído hablar de un campamento fortificado al este del Fondeadero Vela del Sol. A lo mejor la capitana está allí.", progress = "Hola, <clase>, me alegro de verte. Sé que es absurdo que esté aquí cuando El Puerto ha sido invadido por los desdichados. Velendris y sus forestales han jurado protegerme a condición de que me vaya en cuanto haya recuperado mi carga.\n\n¿Qué traes? Eso me suena.", completion = "¡Estupendo, &lt;clase&gt;! ¡No sabía que los múrlocs Malaescama se habían llevado también mis planes de navegación! Sin ellos no habría podido salir a la mar aun después de haber retomado El Puerto y reparado la nave.\n\n¡Muchas gracias! Acepta esta moneda en muestra de gratitud.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8888] = {title = "La aprendiza", objective = "Habla con la aprendiza Loralthalis cerca de la Aguja Ocaso Marchito en el Bosque Canción Eterna.", description = "<clase>, tengo que pedirte algo. Por motivos que ahora no vienen al caso, decidí cerrar mi escuela, que está cerca de aquí. Envié a una pupila, la aprendiza Loralthalis, para que se ocupara de todo, pero no he sabido nada de ella.\n\n¿Podrías ir a Aguja Ocaso Marchito y comprobar si está bien? Para ir, ve hacia el norte desde El Retiro del Errante y gira a la derecha en la bifurcación.", progress = nil, completion = "¿El magister estaba preocupado por mí? Qué tierno; podría haberse interesado antes, cuando estábamos en la Aguja.\n\nNo importa. Escucha atentamente, &lt;clase&gt;: tengo que pedirte un favor.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8889] = {title = "Desactivando la Aguja", objective = "Desactiva las 3 fuentes de poder de la Aguja Ocaso Marchito. Después devuelve la joya desactivadora a la aprendiza Loralthalis en el Bosque Canción Eterna.", description = "Puede que sepas que el magister Ocaso Marchito me envió a apagar las fuentes de poder de la Aguja. Hay tres, situadas en puntos diferentes.\n\nPor desgracia, parece que llego demasiado tarde: la Aguja Ocaso Marchito ha sido invadida por extrañas criaturas mágicas. No tengo experiencia en este tipo de tareas, pero seguro que para <un/una> <clase> como tú será pan comido.", progress = "No veo bien desde tan lejos... ¿Has desactivado las fuentes de poder de la Aguja Ocaso Marchito?", completion = "Te agradezco tu ayuda, pero me apena saber que algunos de mis aprendices han sucumbido a su adicción.\n\nAhora que las líneas de poder de la Aguja están cortadas, me quedaré un poco a esperar que las cosas se calmen para salir a buscar sus restos.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8890] = {title = "Un mensaje de la Aguja", objective = "Regresa junto al magister Ocaso Marchito en El Retiro del Errante, en el Bosque Canción Eterna.", description = "<nombre>, necesito pedirte un último favor. ¿Informarías de lo ocurrido aquí al magister Ocaso Marchito, allá en El Retiro del Errante? Dile que estoy bien pero asegúrate de que está al corriente de que algunos aprendices se han vuelto malvados.\n\n¡Gracias por tu ayuda!", progress = nil, completion = "¡No! Llegué demasiado tarde. Todo es culpa mía.\n\nMi investigación en fuentes mágicas purificadoras alternativas se me fue de las manos antes de que pudiera detenerlo. Si por lo menos hubiera yo... ¡o si me hubieran escuchado y tenido en cuenta mis advertencias!\n\nTengo sangre en las manos, &lt;clase&gt;. Te agradezco, sin embargo, que hayas aportado descanso a las torturadas almas de mis anteriores aprendices. Es un pequeño consuelo que ya no permanezcan en ese estado en el que a un elfo de sangre más le vale estar muerto.", rewards = "Recibirás:\n\nToga de aprendiz caídoCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8891] = {title = "Investigación abandonada", objective = "Devuélvele su diario al magister Ocaso Marchito, que se encuentra en El Retiro del Errante, en el Bosque Canción Eterna.", description = "Has descubierto lo que parece ser un diario de investigación que el magister Ocaso Marchito se habría dejado. Tras un breve vistazo al contenido, te enteras de que había intentado filtrar flujos de magia corrupta, lo que podría explicar lo ocurrido en la Aguja Ocaso Marchito. Seguro que al magister le gustaría recuperar el diario.", progress = "¿Qué es esto? Me suena. Oh no, este diario... mi investigación... esta es la causa de todo esto desde el principio.", completion = "Aquí tienes, &lt;nombre&gt;, la prueba de mi delito. En este diario se recogen todos mis perversos estudios.\n\nHaciendo oídos sordos ante las advertencias, seguí con mi investigación hasta que fue casi demasiado tarde. Cuando me di cuenta de mi error, hice lo que pude. Pero para entonces, algunos de mis alumnos ya habían llegado demasiado lejos. Hice que evacuaran la Cumbre para alejarlos de la corrupción, pero en mi apresuramiento, olvidé cortar las fuentes de poder.\n\nQuemaré este libro para que nadie más caiga víctima de su contenido. Solo pretendía ayudar a los sin'dorei.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8892] = {title = "Problemas en el Fondeadero Vela del Sol", objective = "Mata a 5 matones desdichados y 5 gamberros desdichados e informa al forestal Degolien en el Bosque Canción Eterna.", description = "Esos malditos desdichados han ocupado el Fondeadero Vela del Sol. En cuanto lleguen los refuerzos les enseñaremos quién manda aquí, <nombre>.\n\nMientras tanto, dales algunas lecciones de disciplina. Ve a demostrarles que con nosotros no se juega. El Fondeadero Vela del Sol está al oeste de la Aldea Brisa Pura.", progress = nil, completion = "Así aprenderán que con nosotros no se juega. Buen trabajo, &lt;nombre&gt;.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8894] = {title = "Limpieza a fondo", objective = "Mata 6 serpientes de maná y 6 malignos de éter y ve a ver al guardés Wyllithen a las Tierras Ocaso Marchito, en el Bosque Canción Eterna.", description = "¡Es terrible! Han pasado cosas raras en la cumbre, el magister y sus aprendices han huido ¡y ahora resulta que todo está invadido por esas bestezuelas mágicas! ¿Y quién avisó a Wyllithen? ¡Nadie!\n\nAyúdame a limpiar, <clase>. ¡No puedo mantener esto en condiciones con esas..., esas anomalías corriendo por ahí!", progress = nil, completion = "Muy bien, no podemos hacer más. Gracias por tu ayuda, &lt;clase&gt;. Espero tener tiempo de limpiar todo esto antes de que el magister vuelva a la Aguja Ocaso Marchito. \n\nTen estas monedas; no es mucho, pero ahora no dispongo de más. Y por supuesto, si te apetece liquidar a unas cuantas bestias más mientras sigues tu camino, no te prives.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8895] = {title = "Entrega para el Sagrario del Norte", objective = "Entrégale la carta sin marcar al vigilante-Ley Caidanis en el Sagrario del Norte en el Bosque Canción Eterna.", description = "Me alegra descubrir que tienes cierta competencia, <nombre>. Te asignaré otra tarea puesto que pareces tan impaciente por demostrar tu valía.\n\nEsta es una carta del vigilante-Ley Caidanis, el arcanista a cargo del Sagrario del Norte. Dirígete al suroeste de la Plaza Alalcón y lo encontrarás. Es una eminencia, así que no le entretengas innecesariamente con charlitas.", progress = "¿Sí, <clase>?", completion = "Gracias, &lt;nombre&gt;. Esperaba esta carta.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][8900] = {title = "Queridísima Elenia:", objective = "Entrega la nota arrugada a Elenia Haydon, que está cerca del banco en Entrañas.", description = "Estaba disgustada, se le veía. Aunque es normal, ¿no?\n\nPero al hablar con ella vi la conexión. Creí que nadie me entendería, pero ella lo hizo.\n\nCuando se lo dije a los demás, se rieron de mí, así que no volví a hablar con ella. Pero la echo de menos. ¿Te importa llevarle esta carta? Quiero asegurarme de que la recibe.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][8901] = {title = "Queridísima Elenia:", objective = "Entrega la carta muy bien escrita a Elenia Haydon, que está cerca del banco en Entrañas.", description = "¿Has amado alguna vez? Yo nunca, hasta que hace poco conocí a Elenia, una chica de Entrañas. Ya es raro que mi gente salga con alguien de fuera, y mucho menos una de los Renegados.\n\nPero ahora pienso en ella noche y día.\n\n¿Te importaría llevarle esta carta? Quiero que venga a Mulgore. Espero que acepte.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][8904] = {title = "Amor peligroso", objective = "Lleva una tarjeta mohosa de guardián a Fenstad Argyle a Entrañas.", description = "Esta epidemia de amor no es natural. Es repugnante y debilita nuestras defensas, podría ser peligroso para todos nosotros.\n\nYa es bastante molesto ver cuánta gente se ha contagiado con esta tontería. Creo que afecta incluso a los guardias, que deberían ser inmunes a estas cosas.\n\nHabla con uno de ellos para ver si también ha perdido el oremus.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][8905] = {title = "Una propuesta seria", objective = "Lleva 15 muestras de sangre de Cuna del Invierno, 20 piezas de oro y 1 par de brazales Corazón Salvaje a Deliana a Forjaz.", description = "Saludos, <clase>. Tengo algo que puede interesarte.\n\nDispongo de una armadura muy parecida a las que se usan en tu profesión, pero de mucha mejor calidad. Te cambiaré los brazales por otros normales a cambio de un favor.\n\nLa sangre de los osos y los sables de hielo que viven en Cuna del Invierno tiene propiedades que necesito. Tráeme un frasco grande de sangre, los brazales y un poco de oro. Tus esfuerzos se verán recompensados.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBrazales cuoroferal"}
MultiLanguageQuestData['mx'][8907] = {title = "Una propuesta seria", objective = "Lleva 15 muestras de sangre de Cuna del Invierno, 20 piezas de oro y 1 par de brazales de magister a Deliana a Forjaz.", description = "Saludos, <clase>. Tengo algo que puede interesarte.\n\nDispongo de una armadura muy parecida a las que se usan en tu profesión, pero de mucha mejor calidad. Te cambiaré los brazales por otros normales a cambio de un favor.\n\nLa sangre de los osos y los sables de hielo que viven en Cuna del Invierno tiene propiedades que necesito. Tráeme un frasco grande de sangre, los brazales y un poco de oro. Tus esfuerzos se verán recompensados.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAtaduras de hechicero"}
MultiLanguageQuestData['mx'][8908] = {title = "Una propuesta seria", objective = "Lleva 15 muestras de sangre de Cuna del Invierno, 20 piezas de oro y 1 par de brazales Forjaluz a Deliana a Forjaz.", description = "Saludos, <clase>. Tengo algo que puede interesarte.\n\nDispongo de una armadura muy parecida a las que se usan en tu profesión, pero de mucha mejor calidad. Te cambiaré los brazales por otros normales a cambio de un favor.\n\nLa sangre de los osos y los sables de hielo que viven en Cuna del Invierno tiene propiedades que necesito. Tráeme un frasco grande de sangre, los brazales y un poco de oro. Tus esfuerzos se verán recompensados.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBrazales Forjaalma"}
MultiLanguageQuestData['mx'][8913] = {title = "Una propuesta seria", objective = "Lleva 15 muestras de veneno de Silithus, 20 piezas de oro y 1 par de brazales Corazón Salvaje a Mokvar a Orgrimmar.", description = "¡Saludos, <clase>! Se diría que has hecho y visto mucho en este mundo. Pero apuesto a que nunca has visto una armadura como esta.\n\nTe la cambiaré por un par de brazales normales si me haces un favor.\n\nNecesito bastante veneno de araña y escorpión de Silithus. Tráeme el veneno y algunas monedas de oro y haremos el intercambio.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBrazales cuoroferal"}
MultiLanguageQuestData['mx'][8914] = {title = "Una propuesta seria", objective = "Lleva 15 muestras de veneno de Silithus, 20 piezas de oro y 1 par de brazales de acechabestias a Mokvar a Orgrimmar.", description = "¡Saludos, <clase>! Se diría que has hecho y visto mucho en este mundo. Pero apuesto a que nunca has visto una armadura como esta.\n\nTe la cambiaré por un par de brazales normales si me haces un favor.\n\nNecesito bastante veneno de araña y escorpión de Silithus. Tráeme el veneno y algunas monedas de oro y haremos el intercambio.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAtaduras de maestro de bestias"}
MultiLanguageQuestData['mx'][8915] = {title = "Una propuesta seria", objective = "Lleva 15 muestras de veneno de Silithus, 20 piezas de oro y 1 par de brazales de magister a Mokvar a Orgrimmar.|n", description = "¡Saludos, <clase>! Se diría que has hecho y visto mucho en este mundo. Pero apuesto a que nunca has visto una armadura como esta.\n\nTe la cambiaré por un par de brazales normales si me haces un favor.\n\nNecesito bastante veneno de araña y escorpión de Silithus. Tráeme el veneno y algunas monedas de oro y haremos el intercambio.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAtaduras de hechicero"}
MultiLanguageQuestData['mx'][8917] = {title = "Una propuesta seria", objective = "Lleva 15 muestras de veneno de Silithus, 20 piezas de oro y 1 par de brazales arte sombrío a Mokvar a Orgrimmar.|n", description = "¡Saludos, <clase>! Se diría que has hecho y visto mucho en este mundo. Pero apuesto a que nunca has visto una armadura como esta.\n\nTe la cambiaré por un par de brazales normales si me haces un favor.\n\nNecesito bastante veneno de araña y escorpión de Silithus. Tráeme el veneno y algunas monedas de oro y haremos el intercambio.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBrazales Mantoscuro"}
MultiLanguageQuestData['mx'][8918] = {title = "Una propuesta seria", objective = "Lleva 15 muestras de veneno de Silithus, 20 piezas de oro y 1 par de ataduras de elementos a Mokvar a Orgrimmar.|n", description = "¡Saludos, <clase>! Se diría que has hecho y visto mucho en este mundo. Pero apuesto a que nunca has visto una armadura como esta.\n\nTe la cambiaré por un par de brazales normales si me haces un favor.\n\nNecesito bastante veneno de araña y escorpión de Silithus. Tráeme el veneno y algunas monedas de oro y haremos el intercambio.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAtaduras de los Cinco Truenos"}
MultiLanguageQuestData['mx'][8920] = {title = "Una propuesta seria", objective = "Lleva 15 muestras de veneno de Silithus, 20 piezas de oro y 1 par de brazales de valor a Mokvar a Orgrimmar.|n", description = "¡Saludos, <clase>! Se diría que has hecho y visto mucho en este mundo. Pero apuesto a que nunca has visto una armadura como esta.\n\nTe la cambiaré por un par de brazales normales si me haces un favor.\n\nNecesito bastante veneno de araña y escorpión de Silithus. Tráeme el veneno y algunas monedas de oro y haremos el intercambio.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBrazales de heroísmo"}
MultiLanguageQuestData['mx'][8921] = {title = "El destilador ectoplásmico", objective = "Vuelve a ver a Mux Cazamaná a Gadgetzan cuando tengas 1 conversor de arcanita delicado, 4 esencias eternas superiores, 10 unidades de aceite de escama pétrea, 25 cenizas volcánicas y 40 piezas de oro.", description = "¡Ah! Necesitas mi última creación... ¡el detector de fantasmas extradimensional! Lamentablemente, no tengo ni el dinero ni el personal necesarios.\n\n¿Te apetece echarme una mano? ¡Excelente! Nuestra primera tarea consiste en fabricar un dispositivo capaz de atrapar a la propia Muerte. Construir un destilador ectoplásmico no será tarea fácil, <nombre>.\n\nNecesito que me traigas un convertidor de arcanita, algunas esencias eternas superiores y aceite de escama pétrea. También necesitaré cenizas volcánicas de los charcos de lava que se encuentran en Las Estepas Ardientes para fabricar un filtro.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nVíveres de calidad de Mux"}
MultiLanguageQuestData['mx'][8923] = {title = "Un artefacto sobrenatural", objective = "Lleva el frasco de veneno sellado a Mux Cazamaná a Gadgetzan.", description = "Tienes que ser muy valiente para haberte quedado después de eso. O eso, o te ha interesado mucho la armadura que te di. Si quieres seguir ayudándome, podría enseñarte otras.\n\nEl veneno que te pedí antes es para Mux Cazamaná, un ingeniero interesado en lo sobrenatural. ¡Su último proyecto es un instrumento para comunicarse con los muertos! Mi última esperanza es ponerme en contacto con Anthion y averiguar algo más sobre mi situación.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8924] = {title = "Caza de ectoplasmas", objective = "Utiliza el destilador ectoplásmico cerca de los no-muertos incorpóreos y consigue 12 ectoplasmas agostados en Silithus, 12 ectoplasmas helados en Cuna del Invierno y 12 ectoplasmas estables en las Tierras de la Peste del Este. Llévaselos, junto con el destilador ectoplásmico, a Mux Cazamaná a Gadgetzan.", description = "¡Es una obra maestra de ingeniería, modestia aparte! Me temo que tendrás que viajar un poco para encontrar a los no-muertos incorpóreos que necesitamos.\n\nSabes, los distintos climas proporcionan consistencias diferentes a los tejidos espectrales de los muertos. Los torturados elfos de la noche de Silithus, los espíritus de los Altonato de Cuna del Invierno y los fantasmas y almas en pena de las Tierras de la Peste del Este deberían proporcionarnos los diferentes tipos de ectoplasma que necesitamos. ¡Asegúrate de situar el destilador cerca de ellos para poder cazarlos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8930] = {title = "Buscando a Anthion", objective = "Usa el detector de fantasmas extradimensional en la entrada de Stratholme y habla con el fantasma de Anthion Harmon.\n\nObjeto provisto: \n", description = "Muy bien, <nombre>. Ya solo queda probar el invento goblin. Se dice que Anthion fue acribillado por las legiones de los no-muertos de Stratholme cuando intentaba cruzar sus puertas.\n\nIntenta usar el instrumento allí y... ¡veamos si consigues hablar con los muertos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8948] = {title = "Un viejo amigo de Anthion", objective = "Lleva el estandarte de Provocación incompleto a Falrin Tallarbol que está en la biblioteca de La Masacre.", description = "Theldren no es dado a participar en combates justos si puede evitarlo. He creado este estandarte con los colores de su familia.\n\nCon un poco más de magia, este estandarte le provocará de tal forma que no podrá resistirse.\n\nUn viejo conocido mío llamado Falrin sabe exactamente qué hay que hacer. Tiene una forma muy personal de... enervar a la gente. Lo encontrarás en la biblioteca de La Masacre.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8949] = {title = "La vendetta de Falrin", objective = "Reúne 25 abalorios de guerra de ogro de los ogros de La Masacre o de la Cumbre de Roca Negra y vuelve a El Athenaeum de La Masacre a hablar con Falrin Tallarbol.", description = "Sí, es cierto, estoy familiarizado con el encantamiento que necesitas, <clase>. Pero no suelo hacer favores gratis, aunque vengas de parte de un viejo amigo.\n\nNo siento más que odio y desprecio por nuestros salvajes vecinos ogros. Y también odio a los seguidores de Omokk, casi tanto como odio a los devotos al rey Gordok.\n\nQuiero que los mates. ¡Mata a muchos de ellos! Y tráeme esos abalorios que llevan colgados del cuello como prueba de que has cumplido. Hazlo y hablaremos de tus necesidades.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nCuentas de Poderío de ogroCuentas de mojo de ogro\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][8961] = {title = "Tres reyes de Fuego", objective = "Recolecta la incendicita de Incendius, el ascua del Brasadivino y el rescoldo de las brasas junto con el blandón sagrado y llévaselos a Bodley en el interior de la Montaña Roca Negra.", description = "Para invocar a Lord Valthalak, primero tendremos que reunir los otros dos tercios del amuleto. Así que necesito un blandón y un carbón especial que quemaré en él.\n\nHay tres reyes de Fuego, Lord Incendius en las Profundidades de Roca Negra, el Piroguardián de la Llama en la Cumbre de Roca Negra y el duque de las Brasas en Silithus, con lo que necesito. Recoge una pieza de los restos de cada uno y vuelve aquí con un blandón sagrado; puedes comprarlo en El Alba Argenta si te consideran honorable.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][8979] = {title = "El presentimiento de Fenstad", objective = "Lleva 1 frasco de colonia y 1 de perfume a la boticaria Zinge, que está en El Apothecarium de Entrañas.", description = "Creo haber descubierto la causa de todo esto. ¿Te has fijado en la fragancia que lleva el viento, por encima del hedor de los canales? Fíjate en los perfumes que se han puesto de moda.\n\nAlguna alquimia maléfica nos está enturbiando el juicio.\n\nSolo hay un modo de averiguarlo: llévale un frasco de colonia y uno de perfume a la boticaria Zinge. La Sociedad Real de Boticarios averiguará qué está pasando aquí.\n\nTe pagaré lo que te hayan costado cuando vuelvas.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][8981] = {title = "Ofrecer regalos", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nFlecha con astil de plataPuñado de pétalos de rosaCohete del amor\n\nTe van a lanzar el siguiente hechizo:\n\nFestividad: San Valentín, obsequio entregado\n\nTambién recibirás:\n\nCaja de bombones"}
MultiLanguageQuestData['mx'][8984] = {title = "El descubrimiento de la fuente", objective = "Encuentra al boticario Staffron Lerent en las Laderas de Trabalomas, pasada la Mansión Ravenholdt.", description = "Mira, los actos de un boticario desquiciado no tienen nada que ver conmigo. Si está en tu contra, mejor que sepas quién es.\n\nSi es inocente no tendrá nada que ocultar, ¿correcto?\n\nCompré las esencias al boticario Staffron Lerent. Trabaja en una zona aislada más allá de la Mansión Ravenholdt, en las Laderas de Trabalomas. Para decirte la verdad, me pareció un poco raro.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][9010] = {title = "Guardar lo mejor para el final", objective = "Dale a Mokvar tu almete y tu guerrera arte sombrío.", description = "¡Qué historia tan increíble, <nombre>! Tienes mi agradecimiento y la más sentida gratitud de todos los implicados. Gracias a ti, hemos enmendado los errores del pasado.\n\nEn cuanto a tu recompensa, tengo unas cuantas cosas que te has ganado y te van a gustar.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAlmete MantoscuroGuerrera Mantoscuro"}
MultiLanguageQuestData['mx'][9023] = {title = "El veneno perfecto", objective = "Dirk Truenedera quiere que le lleves glándulas de veneno de Venoxis y Kurinnaxx al Fuerte Cenarion.", description = "Mi hermano y yo nos ocupamos del transporte de veneno desde la Mansión Ravenholdt.\n\nLord Ravenholdt me encargó que localizara un compuesto venenoso nuevo y muy efectivo que se puede fabricar con las glándulas de veneno de las arañas de Zul'Gurub y las Ruinas de Ahn'Qiraj.\n\nEn las ruinas hay dos arañas especialmente venenosas que tienen lo que estoy buscando, <clase>. Tráeme glándulas de veneno de Kurinnaxx y Venoxis y tendrás nuestro agradecimiento eterno.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Ballesta de repetición de recarga de FahradPrima de CondemulusEl atizador TruenederaCercenadora RavenholdtChafarote de ShivsprocketMartillo de cultivo de SimoneRecibirás:\n\n"}
MultiLanguageQuestData['mx'][9033] = {title = "Ecos de Guerra", objective = "El comandante Eligor Albar de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere que mates 5 monstruosidades vivientes, 5 gárgolas piel de piedra, 8 capitanes caballero de la Muerte y 3 acechadores venenosos.", description = "Hace cinco años que terminó la última guerra...\n\nDecenas de miles de vidas perdidas, ¿y para qué? La amenaza no fue exterminada.\n\nEl Rey Exánime vuelve a la vida... Su lugarteniente, Kel'Thuzad, prepara otro ataque a nuestras tierras.\n\n¡No podemos permitirlo! Demuéstranos que lo arriesgarás todo para detener esta locura y tendrás a las fuerzas de la Cruzada y de El Alba a tu disposición.\n\nVe a Naxxramas y elimina la Plaga.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9035] = {title = "Asaltantes de caminos", objective = "Habla con el aprendiz Meledor en el Bosque Canción Eterna en el camino hacia el sur desde Ciudad de Lunargenta.", description = "¡Eh, tú! ¡Ayúdame, por favor!\n\n¡Los desdichados nos han atacado! Estaban tan ansiosos de magia que se han llevado todo lo que han encontrado: cristales de maná, varitas, libros de hechizos... ¡Todo!\n\nMeledor, mi compañero, ha salido tras ellos; yo me he quedado a vigilar lo que no se han llevado. Sigue el camino, a ver si puedes echarle una mano.", progress = nil, completion = "Han huido. ¡Casi los mato de miedo con una bola de Fuego bien colocada! Por desgracia, han tirado nuestra preciada carga al río.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][9052] = {title = "Veneno de Sangrepétalo", objective = "Reúne 8 champiñones de sangre y 8 aguijones Gorishi, y ve a ver de nuevo a Torwa Abrecaminos al Cráter de Un'Goro.", description = "Te pediría ayuda para crear una toxina o algo así para apaciguar a la gran criatura que vive en el cráter. No es muy peligroso y solo los ávidos ojos de <un/una> <clase> pueden buscar estos ingredientes.\n\nPuedes encontrar los champiñones de sangre que crecen dentro de los brotes Sangrepétalo a lo largo del cráter. Los aguijones Gorishi los podrás obtener de los insectos que se encuentran dentro y alrededor de La Cicatriz Serpenteante, en la parte sur del cráter.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPoción de sanación sublime"}
MultiLanguageQuestData['mx'][9053] = {title = "Un ingrediente mejor", objective = "Consigue una vid pútrida de las que custodia el guardián en las profundidades del Templo Sumergido y después ve a ver de nuevo a Torwa Abrecaminos.", description = "Es lo que yo me temía, la toxina es demasiado débil para una criatura tan poderosa.\n\nSi queremos crear una toxina lo suficientemente potente, tendrás que adentrarte hasta el fondo de El Templo de Atal'Hakkar, desentrañar los secretos del altar y conseguir una vid pútrida que custodia el guardián. El templo es peligroso por lo que debes buscar a algún amigo que te acompañe.\n\nVuelve a mí cuando lo hayas hecho.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Abrazo del bosquePelambre grisáceaBáculo Sombra LunarBastón Sombra LunarAbrazo de matorralPellejo grisáceoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][9062] = {title = "Papel mojado", objective = "El aprendiz Meledor del Bosque Canción Eterna quiere que busques el grimorio elemental de Antheol en las aguas bajo el puente.", description = "Esos malditos desdichados corren que se las pelan cuando alguien les planta cara, pero eso ahora no importa. Tengo que encontrar el grimorio elemental de mi instructor.\n\nEstoy seguro de haber visto a uno de esos cobardes tirarlo al río, pero no lo encuentro. Échame una mano; si lo encuentras, te ganarás unas monedas.", progress = "Qué, ¿no ha habido suerte? Sigue buscando; ese libro es importantísimo, <clase>.", completion = "El libro está completamente empapado. El instructor Antheol no va a estar nada contento.\n\nTen, toma estas monedas. Tengo una idea.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][9063] = {title = "Torwa Abrecaminos", objective = "Habla con Torwa Abrecaminos en el Cráter de Un'Goro.", description = "Un cazador llamado Torwa Abrecaminos ha solicitado la ayuda de un druida. Dijo que solo nosotros tenemos las habilidades necesarias y el respeto por la naturaleza para ayudarlo.\n\nExiste un camino que conecta el Cráter de Un'Goro con el desierto de Tanaris. Encontrarás a Torwa justo al terminar el camino, al llegar al Cráter.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9064] = {title = "Asumiendo la responsabilidad", objective = "Lleva el grimorio elemental de Antheol al instructor Antheol a la Charca Plácido Susurro en el Bosque Canción Eterna.", description = "Antheol se va a poner hecho una fiera cuando vea lo que le ha pasado al libro. Te propongo un trato.\n\nLlévale este libro y no le digas nada. Si comenta algo, dile que se te ha caído en un charco. No tiene autoridad sobre ti, así que no podrá hacerte nada.\n\nDa sus conferencias en la Charca Plácido Susurro, al sureste de Lunargenta. ¡Te recompensaré bien por este favor!", progress = "¿Cómo te atreves a interrumpirme, <clase>?", completion = "¿Que esos dos incompetentes te sobornaron para que me mintieras? Has hecho bien en decírmelo, &lt;nombre&gt;.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][9066] = {title = "La letra con sangre entra", objective = "Usa la vara de castigo de Antheol en el aprendiz Ralen y el aprendiz Meledor. Devuélvele la vara a Antheol en Charca Plácido Susurro en Bosque Canción Eterna.", description = "Hoy debes aprender una lección importante, <nombre>: no esperes que nadie mienta por ti.\n\nQuiero que vayas a castigar a mis dos discípulos inútiles con esta vara. Están en el camino al oeste, al otro lado de La Cicatriz Muerta.\n\nDespués ven a verme; te daré una pequeña recompensa.", progress = "¿Has hecho lo que te he pedido, <nombre>?", completion = "Excelente trabajo, &lt;nombre&gt;. No te preocupes, no se quedarán con esa forma. Sin embargo, no recuperarán su aprendizaje hasta que se lo ganen.", rewards = "Recibirás:\n\nFaltriquera de magisterCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][9067] = {title = "Fiesta interminable", objective = "Compra 1 botella de Toquesol especial, aperitivos de garragil y 1 paquete de fuegos artificiales y llévaselo todo a Lord Saltheril al Refugio de Saltheril en el Bosque Canción Eterna.", description = "¡Me encanta dar fiestas, aunque solo sea para celebrar la magnificencia de Quel'Thalas!\n\nPero tengo un problema: me faltan suministros.\n\nVe a ver al maestro vinícola Toquesol a la posada de Ciudad de Lunargenta y recoge una botella de Toquesol especial. Zalene Albatemprana de El Retiro del Errante te dará aperitivos de garragil. Y recoge los fuegos artificiales en la tienda de Halis Caminalba en la Aldea Brisa Pura.\n\n¡Y no te entretengas por ahí!", progress = "¿No te acabo de mandar a buscar provisiones para la fiesta? ¿No eras tú? Bueno, no voy a acordarme de las caras de todo el mundo, ¿no? Conozco a tantos p... Personajes interesantes, quiero decir.\n\n¿Qué quieres?", completion = "Tienes mucha energía, ¿verdad?\n\nQué adecuado. Te mereces una compensación por todo el trabajo que has hecho, e incluso te has ganado una propina.\n\nCasi lo olvido, aquí tienes una invitación a la fiesta. Una cosa más, &lt;clase&gt;, la próxima vez que vengas, ponte algo un poco más... desenfadado.", rewards = "Recibirás:\n\nInvitación a la fiesta del Refugio de SaltherilCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][9076] = {title = "El jefe de los desdichados", objective = "Lleva la cabeza de Aldaron a Velendris Albodía cerca del Fondeadero Vela del Sol en Bosque Canción Eterna.", description = "Los desdichados están tan ocupados atiborrándose de magia impura que no se han dado cuenta de que hemos recuperado casi todas las armas. Es el momento de atacar; demos ejemplo con su jefe, Aldaron. Ha sido visto en el piso superior del edificio junto al puerto. Tráeme su cabeza y te recompensaré.", progress = "¿Me traes la cabeza? No tengo tiempo que perder, <nombre>.", completion = "¡Lo derrotaste! Claro que mis hombres lo habían ablandado un poco antes.\n\nEs broma, &lt;clase&gt;. Lo hiciste muy bien. No te metas en líos y te harás de una buena reputación.", rewards = "Brazales navegasolBrazales de estibadorBraciles de sedaRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][9085] = {title = "Sombras del Apocalipsis", objective = "Ve a un Círculo de Invocación, mata a una Sombra de fatalidad e informa al comandante Thomas Helleran en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Después de reducir las defensas de un círculo de invocación de la Plaga, debes enfrentarte a los acólitos que los protegen.\n\nEn realidad, no se trata de hombres. Son sombras, una de las criaturas más temidas del Rey Exánime. Pueden dejarse ver si usas las runas necróticas que llevan y destruirlas con magia o la fuerza de las armas.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nPiedra de afilar consagradaAceite de zahorí bendito"}
MultiLanguageQuestData['mx'][9094] = {title = "Guantes de El Alba Argenta", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Guanteletes de matanza de no-muertosManijas de matanza de no-muertosManoplas de matanza de no-muertoGuantes de limpieza de no-muertos"}
MultiLanguageQuestData['mx'][9119] = {title = "Disfunción en el Sagrario del Oeste", objective = "Habla con la vigilante-Ley Velania en el Sagrario del Oeste, en el Bosque Canción Eterna.", description = "Ya que estás aquí, <nombre>, tengo un favor que pedirte. La aprendiza de la vigilante-Ley Velania se pasó por aquí antes para pedir ayuda. Por lo visto hay alguna disfunción en el Sagrario del Oeste. He estado algo ocupado entreteniendo a nuestro... encantador... invitado enano. A ver si puedes ayudarla. Encontrarás el Sagrario del Oeste al suroeste de este lugar.", progress = nil, completion = "Mira a tu alrededor. Las cosas no están exactamente en orden.\n\nPor lo visto hay una grave disfunción en el Sagrario del Oeste. Hagamos todo lo posible para evitar que empeoren.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][9120] = {title = "La caída de Kel'Thuzad", objective = "Lleva la filacteria de Kel'Thuzad a la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "La filacteria es lo único que queda del señor de Naxxramas. Tu sentido común te dice que la destruyas para que el exánime no pueda volver nunca. Por suerte, no sueles escuchar la voz de la razón.\n\nSeguro que en Esperanza de la Luz te pagan una fortuna por ella. ¿A quién le importa si Kel'Thuzad se regenera y vuelve?Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nMarca del CampeónMarca del Campeón\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][9121] = {title = "La ciudadela del terror: Naxxramas", objective = "La archimaga Angela Dosantos de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 5 cristales Arcanos, 2 cristales nexo, 1 orbe recto y 60 piezas de oro. También tienes que ser Honorable con El Alba Argenta.|n", description = "La espesura del Bosque de la Peste esconde la entrada a la temida ciudadela de Naxxramas. Nadie a logrado acceder a ella a causa de los resguardos mágicos situados sobre el portal rúnico. Mejor dicho: hasta ahora.\n\nHemos descubierto que sería posible entrar con un velo Arcano permanente; es un antiguo conjuro del Kirin Tor que he modificado un poco. Como tu dedicación a la causa de El Alba deja mucho que desear, <nombre>, el velo te costará muy caro. Puedes renunciar ahora y volver cuando llegues al nivel de Venerado o Exaltado; así el precio bajará.Cuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][9122] = {title = "La ciudadela del terror: Naxxramas", objective = "La archimaga Angela Dosantos de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 2 cristales Arcanos, 1 cristal nexo y 30 piezas de oro. También tienes que ser Venerado con El Alba Argenta.", description = "La espesura del Bosque de la Peste esconde la entrada a la temida ciudadela de Naxxramas. Nadie a logrado acceder a ella a causa de los resguardos mágicos situados sobre el portal rúnico. Mejor dicho: hasta ahora.\n\nHemos descubierto que sería posible entrar con un velo Arcano permanente; es un antiguo conjuro del Kirin Tor que he modificado un poco. El velo es muy caro. Puesto que muestras una admirable dedicación a la causa de El Alba, deseamos hacernos cargo de parte de los costes.Cuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][9123] = {title = "La ciudadela del terror: Naxxramas", objective = "La archimaga Angela Dosantos de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, se ofrece a costear tu velo Arcano. Debes ser Exaltado con El Alba Argenta.", description = "La espesura del Bosque de la Peste esconde la entrada a la temida ciudadela de Naxxramas. Nadie a logrado acceder a ella a causa de los resguardos mágicos situados sobre el portal rúnico. Mejor dicho: hasta ahora.\n\nHemos descubierto que sería posible entrar con un velo Arcano permanente; es un antiguo conjuro del Kirin Tor que he modificado un poco. El velo es muy caro. Puesto que muestras una dedicación inquebrantable a la causa de El Alba, deseamos hacernos cargo de los costes.Cuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][9124] = {title = "La armadura de acechacriptas no se hace sola...", objective = "El montero Leopold, de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 30 trozos de maligno de cripta.", description = "¿Querrías ganarte algunas de estas brillantes monedas?\n\n<Leopold levanta una Insignia de la Cruzada.>\n\nTengo un pequeño problema en el que quizás me puedas ayudar, <nombre>. Verás, yo hago armaduras de acechacriptas para los tontos que se aventuran a entrar en Naxxramas. Ellos me suministran los materiales básicos de la armadura, pero siempre se me acaban las piezas de maligno de cripta. Tráeme un montón de piezas y te pagaré con una insignia... Una que podrás utilizar en la Intendencia.", progress = "¿Cómo va la caza?", completion = "Estupendo, &lt;nombre&gt;. Recuerda que puedes traerme todas las piezas que quieras. Por cada montón que me traigas, te recompensaré con una insignia.", rewards = "Recibirás:\n\nInsignia de la Cruzada"}
MultiLanguageQuestData['mx'][9126] = {title = "Excavaciones para la armadura Segahuesos", objective = "Rohan el Asesino, de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 30 trozos de huesos.|n", description = "El dibujo de la armadura Segahuesos de Don Julio requiere trozos de hueso. Muchos trozos de huesos. Aquellos que están suficientemente locos para aventurarse a entrar en Naxxramas me proporcionan materia prima para forjar la armadura, pero yo siempre estoy buscando más trozos de huesos de la Plaga.\n\n¿Qué me dices? ¿Te interesa ensuciarte las manos a la vez que destruyes algún miembro de la Plaga que otro? Todo son beneficios.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nInsignia de la Cruzada"}
MultiLanguageQuestData['mx'][9128] = {title = "La ecuación elemental", objective = "La archimaga Ángela Dosantos, de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 30 núcleos de elementos.|n", description = "¡Saludos, <aventurero/aventurera>! ¿Te interesaría trabajar para mí? Pago con insignias. Mis insignias pueden utilizarse en la Intendencia para comprar objetos de poder.\n\nTodo lo que necesito es que me traigas tantos núcleos de elementos como puedas cargar. ¡Cuantos más, mejor!\n\nLos encontrarás en elementales de diferentes formas y tamaños por todo el mundo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nInsignia de El Alba"}
MultiLanguageQuestData['mx'][9130] = {title = "Mercancía de Ciudad de Lunargenta", objective = "Entrégale la solicitud de Sathiel al maestro del cielo Alba Brillante en la Aldea Brisa Pura.", description = "¡Bienvenido <voluntario/voluntaria>! Andamos cortos de suministros pero Lunargenta nos ha prometido ayuda material. Aquí es donde entras tú.\n\nLleva esta lista al maestro del cielo Alba Brillante. Él te dará más instrucciones sobre la mejor manera de llegar a la Ciudad de Lunargenta.", progress = "Sí, ¿qué es esto?", completion = "Sathiel quiere que vayas a la Ciudad de Lunargenta y le lleves sus bienes, ¿vale? Desde luego que puedo llevarte allí rápidamente... por una módica cantidad, claro.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9131] = {title = "Armar la acorator", objective = "Korfax, de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 30 fragmentos de hierro negro.", description = "¿Alguna vez has visto una armadura acorator, <clase>? No, claro que no. Aún eres <un niño/una niña>... Pues deja que te lo diga: son gloriosas.\n\nTe estarás preguntando qué tiene que ver contigo, ¿verdad? Pues te lo diré: necesito fragmentos de hierro negro y pagaría muy bien todos los que me trajeras. Cuantos más, mejor.\n\nNecesito los restos para conformar armaduras acorator para nuestros campeones. Tráeme restos y te pagaré.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nInsignia de El Alba"}
MultiLanguageQuestData['mx'][9133] = {title = "Vuelo a la Ciudad de Lunargenta", objective = "Compra un vuelo a la Ciudad de Lunargenta y entrégale la solicitud de Sathiel a Sathren Azurocaso en la Ciudad de Lunargenta.", description = "<clase>, por una módica cantidad de monedas, puedo enviarte volando por el aire en una de estas magníficas bestias. Y es más seguro que caminar por estos lares, ¡te lo aseguro!\n\nCuando llegues a la Ciudad de Lunargenta busca a Sathren Azurocaso en El Bazar.\n\nVuelve a hablar conmigo cuando hayas decidido que estás <listo/lista> para los cielos.", progress = "Eso es una señora lista, amiga. A ver, a ver...", completion = "¿Qué es esto? ¡¿Qué Sathiel quiere todo esto!?\n\n¿Has traído a alguien para que te ayude a llevarlo?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9134] = {title = "La maestra del cielo Anochecer", objective = "Lleva los bienes de Sathiel a la maestra del cielo Anochecer, que está junto a la Puerta del Pastor en Ciudad de Lunargenta.", description = "No parece que tengas carro ni bestia de carga, así que solo te daré lo que puedas llevar tú. Si hablaste con el maestro del cielo Alba Brillante en la Aldea Brisa Pura, deberías llevarle esto a Sathiel lo antes posible volando de vuelta allí.\n\nLleva estos bienes para la inspección final a la maestra del cielo Anochecer junto a la Puerta del Pastor de Ciudad de Lunargenta.", progress = "¡Esa caja parece muy pesada! ¿No querrás cargarla en una de mis hermosuras voladoras?", completion = "¿Te vuelves a la Aldea Brisa Pura en el Bosque Canción Eterna? ¡Déjame a mí, verás qué pronto llegas!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9136] = {title = "Flora salvaje", objective = "Rayne, de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 30 hojas salvajes.", description = "Fabrico un tipo especial de armadura para los valientes héroes que entran en Naxxramas. Una armadura conocida como Caminasueños. Ellos me pueden conseguir la mayor parte de los materiales que necesito, pero siempre estoy buscando gente que pueda conseguirme hojas salvajes de la flora de nuestro mundo.\n\nQuizás pienses que este trabajo está muy por debajo de ti, pero es importante: sin las hojas, yo no podría hacer la armadura.\n\nAdemás, estoy en posición de pagarte con una insignia de tu elección, ya que tanto El Alba como la Cruzada me suministran fondos.\nPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][9138] = {title = "La Aldea Corona del Sol", objective = "Mata a 10 guardias Nerubis y después regresa junto al arcanista Vandril en Tranquillien, en las Tierras Fantasma.", description = "Estamos rodeados, <clase>. ¡Todas las aldeas vecinas han sido tomadas por la Plaga!\n\nDebes dirigirte al noreste a la Aldea Corona del Sol inmediatamente y ocuparte de la amenaza nerubiana de la Plaga. Es imposible pasarlas por alto, son criaturas aracnoides.\n\nNo hay tiempo que perder... ¡Debemos recuperar Quel'Thalas!", progress = nil, completion = "¡Asombroso! ¡Pero aún queda mucho por hacer antes de que la amenaza de la Plaga se aleje de la poderosa Quel'Thalas!\n\nAquí tienes, acepta esta moneda... no es gran cosa pero te la has ganado.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9139] = {title = "Aldea Bruma Dorada", objective = "Derrota a 6 fantasmas y 4 ánimas Quel'dorei en la Aldea Bruma Dorada y luego ve a ver al arcanista Vandril a Tranquillien en las Tierras Fantasma.", description = "Hemos ganado una batalla, pero aún quedan dos poblados por recuperar.\n\nNuestro próximo objetivo es la Aldea Bruma Dorada, al noroeste de aquí. Ha sido tomada por los fantasmas de los elfos nobles que vivieron en ella. Suena terrible, pero parece que es una táctica habitual de la Plaga.\n\nDerrota a los fantasmas y apariciones, <clase>. Sigue el camino hacia el oeste desde Tranquillien.", progress = nil, completion = "Tu éxito en la Aldea Bruma Dorada nos acerca un poco más a recuperar nuestra tierra. Pero no te engañes, &lt;clase&gt;: la lucha no ha terminado. \n\nTen; te lo has ganado de sobra. Puede que lo necesites cuando vayas a enfrentarte a la Aldea Brisaveloz.", rewards = "Recibirás:\n\nCerveza especial de Bruma DoradaArco curvo de Quel'Thalas"}
MultiLanguageQuestData['mx'][9140] = {title = "La Aldea Brisaveloz", objective = "Recolecta 6 sustancias fantasmales y 4 fragmentos de gárgola. Vuelve junto al arcanista Vandril en Tranquillien, en las Tierras Fantasma.", description = "<nombre>, la batalla final contra las aldeas de las Tierras Fantasma está cerca. La Aldea Brisaveloz al suroeste ha sido tomada por un contingente de las más poderosas fuerzas de choque de la Plaga: sombras y gárgolas. Serás la avanzadilla de nuestra ofensiva, diezmarás sus efectivos.\n\nLos magistri del Sagrario del Sol vecino nos han hecho llegar una petición especial; quieren los restos de estos miembros de la Plaga para estudiarlos con la esperanza de encontrar alguna innovadora manera de combatirlos.\n\n¡Buena caza!", progress = "<clase>, ¿está liberada la Aldea Brisaveloz? Esos malditos magistri del Sagrario del Sol me han amonestado, están locos por ponerle la mano encima a esos restos de la Plaga que te pedí que recolectaras.\n\nPero no te preocupes por eso. Tómate tu tiempo y haz bien tu trabajo. Yo me ocuparé de los magistri.", completion = "Lo has conseguido, &lt;nombre&gt;. ¡Has acabado con el control de la Plaga sobre tres aldeas! Ahora podemos dedicar el grueso de nuestras tropas a combatir las fuerzas de la Plaga en La Cicatriz Muerta, al sur de la Ciudad de la Muerte.\n\nAquí tienes, elige la pieza que quieras. Confío en que no te vayas a ningún sitio ¿verdad? ¡Nos vendría realmente bien que siguieras ayudándonos!", rewards = "Daga de arcanistaLeotardos de malla rescatadosBotas acolchadas de carrerasVarita de arcanistaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][9141] = {title = "Me llaman \"El Gallo\"", objective = "El comandante de envíos Metz de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere una muestra de valor de El Alba Argenta.|n", description = "¿Quieres una libranza? ¿Qué? ¿Esperas que te dé una de esas ambicionadísimas órdenes de trabajo cumplido solo por aparecer? Pues olvídalo. Aquí vienen todo tipo de personas de todo el mundo buscando trabajo.\n\nSi quieres una orden de trabajo, tendrás que demostrarme que estás <dispuesto/dispuesta> a sudar por la causa. Tráeme una muestra de valor y hablaremos.\n\nY solo hay una forma de que tus pequeñas manitas consigan hacerse con una: matar.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nLibranza de artesano lacrada"}
MultiLanguageQuestData['mx'][9143] = {title = "Encargarse de Zeb'Sora", objective = "Lleva 6 orejas de trol de Zeb'Sora a la forestal Valanna a las Tierras Fantasma.", description = "El teniente nos hizo entrar en combate sin estudiar la situación antes. ¡Nos masacraron por culpa de su estupidez! ¿Me oyes, Tomathren? ¡Eres un desgraciado!\n\n¿Nos ayudarás, <clase>? Hay que ocuparse de los trols, pero tengo que quedarme aquí a cuidar de este; me parece que ha perdido la cabeza.\n\nVe al este y rodea el lago hasta Zeb'Sora. Quiero venganza... ¡Tráeme sus orejas para hacerme un collar!", progress = "¿Traes las orejas de trol?\n\nSi Tranquillien nos enviara ayuda de vez en cuando, esto no sería un problema. Me alegro de que estés aquí.", completion = "Muchas gracias, &lt;clase&gt;. Ahora podemos decir que esta expedición y las vidas que ha costado no han sido en vano.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9144] = {title = "Desaparecido en las Tierras Fantasma", objective = "Sigue el camino hacia el sur desde la Aldea Brisa Pura y busca al mensajero Caminalba mientras te acercas a las Tierras Fantasma.", description = "Hace unos días enviaron a mi sobrino a las Tierras Fantasma. No dijo nada sobre su misión, salvo que era alto secreto.\n\nNo ha vuelto y me temo lo peor, <clase>. Supongo que un mensajero desaparecido no les quita el sueño a los insensibles magistri de Lunargenta, pero era como un hijo para mí. ¿Irás a buscarlo, <nombre>?", progress = nil, completion = "Ayúdame. Tengo que llegar a Tranquillien... No puedo fallar.\n\n&lt;El elfo de sangre pierde el conocimiento.&gt;", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][9145] = {title = "¡Ayuda a la forestal Valanna!", objective = "Encuentra a la forestal Valanna y al teniente Tomathren en la orilla del Lago Elrendar, en las Tierras Fantasma cerca de la Aldea Corona del Sol.", description = "<clase>, ¡no puedo quedarme aquí sentado esperando una audiencia con el Sumo Ejecutor o la Dama Aurífera! ¡Esto no puede esperar!\n\nEstábamos ocupándonos de los trols Sombrapino de Zeb'Sora al noreste después del Lago Elrendar. Pero el teniente no llevó bien el ataque y perdimos a muchos errantes. Después de eso todo se vino abajo. La forestal Valanna me envió aquí y a la forestal Salissa al Enclave del Errante en busca de ayuda.\n\nEncuéntralos, <clase>. A Valanna la hirieron gravemente y el teniente es un inútil.", progress = nil, completion = "Es una alegría oír que Lethvalin consiguió ponerse a salvo y que fue lo suficientemente listo para pedirte ayuda en lugar de seguir esperando allí.\n\nEspero que la forestal Salissa también lograra refugiarse en el Enclave del Errante.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9146] = {title = "Informar al capitán Helios", objective = "Habla con el capitán Helios en el Enclave del Errante, en la orilla sur del Lago Elrendar en las Tierras Fantasma.", description = "Tengo que pedirte un último favor, <clase>: ve al Enclave del Errante, en el extremo sur del lago, y pide refuerzos. Solo por si la forestal Salissa no consiguió llegar.\n\nPreséntate al capitán Helios y cuéntale lo que ha pasado. Seguro que enviará ayuda en cuanto pueda.", progress = nil, completion = "Eso es muy grave; he sobrestimado la capacidad de liderazgo a Tomathren. Enviaré a un grupo de escolta para él y Valanna.\n\nPor desgracia, seguimos sin noticias de la forestal Salissa; temo lo peor.\n\nHas prestado un gran servicio a los Errantes, &lt;clase&gt;. Acepta esto como muestra de nuestra gratitud.", rewards = "Guerrera de ErranteGuantes de cuidador de trolsEscudo de erranteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][9147] = {title = "El mensajero caído", objective = "La boticaria Thedra en el Bosque Canción Eterna quiere que le lleves 4 muestras de sangre apestada de las bestias de las Tierras Fantasma.", description = "¿Qué haces dando vueltas? ¿Acaso no ves que este niño necesita que lo atiendan inmediatamente? Por el aspecto, la peste se está adueñando de su cuerpo. En unos minutos ni siquiera una maestra boticaria como yo podrá salvarlo.\n\nTodos los animales al sur del río llevan la infección en la sangre. Cruza el puente y caza las bestias apestadas. Tráeme suficientes muestras de sangre apestada y destilaré un suero capaz de salvar a este elfo de sangre. ¡Date prisa!", progress = "¿Y bien? ¿Me has traído lo que necesito? ¡Apura, o adiós al lindo elfito de sangre!", completion = "¡Justo a tiempo, &lt;nombre&gt;! Iba a empezar a cavar un hoyo para nuestro amigo.\n\nParece que mi poción funciona; ya viene.\n\nEh, creo que intenta que te fijes en él. ¿Por qué no hablas con él?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9148] = {title = "Entrega en Tranquillien", objective = "Llévale la carta de Lunargenta al arcanista Vandril en Tranquillien, en las Tierras Fantasma.", description = "Estoy... Estoy demasiado débil para seguir. Llevo un amargo aviso del Señor regente Theron, en forma de carta. Tendrás que entregarla por mí.\n\nLlévasela al arcanista Vandril en Tranquillien. Encontrarás la ciudad más hacia el sur siguiendo por esta carretera. Ve allí y... encuentra a Vandril...", progress = "¿Tienes la carta?", completion = "¡Por fin! ¡Llevamos semanas esperando una respuesta del Señor regente! A ver...\n\n&lt;Vandril empieza a leer la carta.&gt;\n\n¿Qué es esto? ¿Una presencia oscura? ¡¿Que siente una presencia oscura en las Tierras Fantasma?! Estará de broma; ¡yo podía haberle dicho eso!\n\n¿Para esto hemos estado esperando?", rewards = "Brazaletes de mensajeroBrazales de explorador de TranquillienBrazales de anillas de bronceRecibirás:\n\nBolsa de cartero"}
MultiLanguageQuestData['mx'][9149] = {title = "La costa apestada", objective = "Llévale 6 espinas dorsales de múrloc apestado al boticario Renzithen en Tranquillien, en las Tierras Fantasma.", description = "Para encontrar una cura para la peste necesitamos entender cómo afecta a las diferentes criaturas, desde las formas de vida más complejas hasta las más humildes subespecies.\n\nHe venido para estudiar a los múrlocs porque, como nosotros, han conservado albedrío en la no muerte. ¿Qué hace tan especiales a estos modestos bastardos? ¡Tengo que averiguarlo, <nombre>!\n\nDirígete al noroeste y tráeme sus espinas dorsales para que pueda examinar la acumulación de peste en su médula. ¿Quién sabe qué secretos nos revelarán sus huesitos?", progress = "¿Has encontrado los especímenes que te pedí, <nombre>?", completion = "¡Estupendo! ¡Estas espinas dorsales no tienen precio para mi investigación! Cuando encuentre una cura para la peste y se haga famoso mi nombre, ¡me aseguraré de que recibas el debido crédito!\n\nMientras tanto, acepta esto como recompensa. Pueden hacerte falta si decides volver a la costa.", rewards = "Recibirás:\n\nPoción de velocidad de nadoCapa polvorienta de Renzithen"}
MultiLanguageQuestData['mx'][9150] = {title = "Al rescate del pasado", objective = "El magister Darenis quiere que vayas al Sagrario de la Luna al oeste de Tranquillien y recuperes 8 esencias de maná cristalizado de los devoradores arcanos y de los conmutadores de maná que pueblan la estructura.", description = "¿Te lo puedes creer? Tenemos un auténtico sagrario Arcano funcionando al sureste: el Sagrario del Sol. Todo tipo de importantes magistri han acudido para ponerlo en marcha.\n\nPor supuesto, nadie se ha acordado del Sagrario de la Luna. Apenas queda nada de él y su energía se ha convertido en extrañas criaturas.\n\nNo me gusta que se desperdicien recursos que pueden ser de provecho. Ve al Sagrario de la Luna y mira a ver qué esencias cristalizadas puedes recuperar de aquellas criaturas.", progress = "¿Conseguiste las esencias, <nombre>?", completion = "Eso es increíblemente potente, &lt;nombre&gt;. Estoy muy satisfecho con tu trabajo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9151] = {title = "El Sagrario del Sol", objective = "Ve al Sagrario del Sol en las Tierras Fantasma y habla con el magister Idonis.", description = "Has demostrado tu lealtad a Tranquillien y nos has ayudado a defenderla de la amenaza de la Plaga. Algunos de nuestros más poderosos magistri han venido de Lunargenta para ayudarnos a combatir al enemigo en su territorio.\n\nHan reconstruido el sagrario del sur y han expulsado a la Plaga de los alrededores. Planean lanzar una ofensiva sobre la Ciudad de la Muerte, el bastión de Dar'Khan. Convendría que te unieras a ellos, <nombre>. No me cabe la menor duda de que <un/una> <clase> con tu experiencia les vendrá bien.", progress = nil, completion = "¿Te envía Darenis? Bueno, supongo que tu ayuda nos vendrá bien para luchar contra las huestes de Dar'Khan.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9152] = {title = "Los suministros de Sepulturero", objective = "Recupera los suministros de Rathis Sepulturero y llévaselos a Tranquillien, en las Tierras Fantasma.", description = "¡¿Cómo se supone que he de abastecer los preparativos para la guerra si ni siquiera mis suministros pueden llegar aquí sin peligro?! Me prometieron una escolta que nunca apareció. ¡Y entonces tuve que dejar atrás una de mis carretas al oeste cuando una cuadrilla de demonios me atacó!\n\n¿Quieres ayudar y de paso echarme una mano en volver a la actividad? Ve por la carretera del oeste saliendo del pueblo y sigue hasta que pases el cementerio. Al otro lado de La Cicatriz Muerta verás una bifurcación en la carretera. La colina donde tuve que abandonar mi carreta está justo detrás.", progress = "Tan pronto como consiga el resto de mis suministros, podré abrir. Las tropas del lugar no llegarán muy lejos si no pueden comprar lo que necesitan para ejercer su oficio.\n\nLas zonas de conflicto bélico pueden generar mucho negocio, ¿no crees, <clase>? Bien, ¿has conseguido volver a mi carro a través de todos estos necrófagos?", completion = "Con el resto de mis suministros al fin podré abrir el negocio. Seguro que el Sumo Ejecutor también se alegrará de oír que la guerra contra Dar'Khan y la Plaga puede empezar.\n\nAh, y claro, está el asuntillo de tu recompensa. Muy bien, &lt;clase&gt;, aquí está la moneda de la que te hablé. No dejes de pasarte si necesitas cualquier producto.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9153] = {title = "Bajo la Sombra", objective = "Busca en tu mapa una zona que esté bajo el ataque de la Plaga. Ve y derrota a los miembros de la Plaga que custodian la necrópolis. Lleva 10 runas necróticas al comandante Thomas Helleran a la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Las necrópolis flotantes de la Plaga arrasan las tierras de la Horda y la Alianza por igual. Tanaris, Las Tierras Devastadas, Cuna del Invierno y Las Estepas Ardientes están cubiertas con las sombras de la fortaleza voladora.\n\nSolo podremos rechazarlas si combinamos nuestros esfuerzos.\n\nCada necrópolis está suspendida sobre círculos mágicos sobre los cuales revolotea un huésped de las criaturas no-muertas. Hemos decidido que aniquilar las hordas salvajes acabará con las defensas del círculo.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nPiedra de afilar consagradaAceite de zahorí bendito"}
MultiLanguageQuestData['mx'][9154] = {title = "Capilla de la Esperanza de la Luz", objective = "Lleva la llamada a las armas al Guardián de los Pergaminos de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "La Plaga ha regresado con un ejército más numeroso que nunca. ¡Debe ser por culpa del Rey Exánime! El Alba Argenta está reclutando a todo hombre o mujer capaz de defender nuestra tierra.\n\nSi compartes nuestra causa, llévale este documento al Guardián de los Pergaminos de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", progress = "¿Has venido en respuesta a la llamada a las armas?", completion = "Has respondido a la llamada a las armas de El Alba Argenta, como otros. No hay tiempo para entrenamientos; tendremos que confiar en tu capacidad y tu voluntad de ayudarnos contra la Peste.", rewards = nil}
MultiLanguageQuestData['mx'][9155] = {title = "Limpiar La Cicatriz Muerta", objective = "Mata 10 hambrientos resucitados y 10 caníbales gangliosos en La Cicatriz Muerta. Ve a ver al mortacechador Rathiel a Tranquillien para recibir una recompensa.", description = "Si has llegado hasta aquí, ya sabrás lo que es La Cicatriz Muerta y cómo todavía hoy las hordas de la Plaga recorren el sendero de destrucción que creó Arthas de camino a Ciudad de Lunargenta.\n\nReduce el número de miembros de la Plaga en La Cicatriz Muerta. Si demuestras que vales, te recomendaré.", progress = nil, completion = "No está mal, &lt;nombre&gt;. Sigue así; necesitamos a más gente como tú por aquí.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9156] = {title = "SE BUSCAN: Putrenudillos y Luzran", objective = "Busca a Putrenudillos y Luzran en las Tierras Fantasma. Lleva sus cabezas al mortacechador Rathiel a Tranquillien y recibirás una recompensa.", description = "Se ofrece recompensa por las abominaciones conocidas como Putrenudillos y Luzran. Estas espantosas creaciones de Dar'Khan son extremadamente peligrosas y han sido vistas cerca de los Zigurats Sangrante y Aullante. Para recibir la recompensa, preséntense sus cabezas al mortacechador Rathiel.", progress = "¿Tienes algo que enseñarme, <nombre>?", completion = "Ah... ¡Luzran y Putrenudillos! Ya no son tan duros, ¿eh? Pero siguen igual de feos.\n\nElige una recompensa, &lt;nombre&gt;. Te la has ganado.", rewards = "Podrás elegir una de estas recompensas:\n\nSortija del asesinoSello de invocador\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][9157] = {title = "Rituales olvidados", objective = "Lleva 8 medallones rompeolas a Geranis Albodía a las Tierras Fantasma.", description = "Cada año los habitantes de Aldea Corona del Sol tomamos parte en un ritual para mantener el control sobre los diferentes aspectos de la naturaleza. El dominio del elemento agua se simbolizaba mediante la invocación y dominación de un elemental llamado Aquantion. ¡Pero el muy canalla pervirtió nuestra magia, consiguió liberarse y nos esclavizó a nosotros!\n\nDurante el ritual llevamos unos medallones con forma de ola. Búscalos en el fondo del lago; los necesitaremos para liberar a los espíritus de mis compatriotas.", progress = "¿Traes los medallones, <nombre>? ¡Los ahogados siguen vagando por el lago!", completion = "Con esto invocaremos a Aquantion una vez más. ¡Ese elemental rebelde pagará por lo que hizo y nuestras muertes serán vengadas!", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][9158] = {title = "Transmisores de la peste", objective = "La errante Sedina del Enclave del Errante en las Tierras Fantasma quiere que mates 10 linces garrafantasma.", description = "Demuestras valor al venir a las Tierras Fantasma, <nombre>. Hay mucho por hacer y pocas almas valientes para hacerlo.\n\nSi quieres ayudarnos, tengo una misión bastante desagradecida para ti. La fauna y flora sufren la mácula de la peste; queremos evitar que la corrupción se extienda. Mata a los linces garrafantasma que hay al este y al sur de aquí. Vuelve cuando hayas matado los suficientes.", progress = nil, completion = "Muy bien, &lt;nombre&gt;. Es importante que la peste no se extienda a la fauna y flora sanas de Canción Eterna. Si buscas trabajo, tengo más tareas para ti.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9159] = {title = "Control de plagas", objective = "La errante Sedina del Enclave del Errante en las Tierras Fantasma quiere que mates 8 rondadores husaraña y 10 murciélagos brumosos vampiros.", description = "Has probado tu valía como <aliado/aliada>, <nombre>. Necesito que sigas trabajando y que busques más fauna apestada. Esta vez ve a por las bestias peligrosas. Hay rondadores husaraña al oeste de La Cicatriz Muerta y murciélagos brumosos vampiros al sur de aquí. Vuelve cuando termines.", progress = nil, completion = "Te has tomado la tarea en serio y me gustaría ofrecerte una recompensa adecuada. Necesitamos más aliados con tu coraje y tu osadía, &lt;nombre&gt;.", rewards = "Fajín de forestalCinturón de vagabundoFaja de anillas oxidadaRecibirás:\n\nCuchillo de supervivencia"}
MultiLanguageQuestData['mx'][9160] = {title = "Explorando An'daroth", objective = "Investiga la zona en An'daroth, mata a 12 espías centinela y ve a ver a la Dama Aurífera a Tranquillien en las Tierras Fantasma.", description = "<clase>, tenemos problemas con un grupo de elfos de la noche que han invadido una isla cercana. Tienen el campamento al noroeste, en An'daroth, antiguo nexo de línea Ley de los elfos nobles. Hay un sendero justo después de La Cicatriz Muerta.\n\nSi quieres ayudarnos, ve a investigar y mata a tantos elfos de la noche como puedas.", progress = nil, completion = "Esperaba que los planes de los elfos de la noche en An'daroth fueran más evidentes. Pero lo que cuentas sobre esa especie de arbolitos mágicos con orbes de poder es muy interesante. Tendremos que ser más directos para conseguir información.\n\nTen esta moneda y estas pociones. Las necesitarás antes de terminar este asunto con los elfos de la noche.", rewards = "Recibirás:\n\nPoción de sanación inferior"}
MultiLanguageQuestData['mx'][9161] = {title = "La sombra del traidor", objective = "Ve a la Aguja de la Estrella del Alba en las Tierras Fantasma y busca pistas sobre el pasado de Dar'Khan.", description = "Se dice que Dar'Khan Drathir ha vuelto de entre los muertos para gobernar sobre los ejércitos de la Plaga en las Tierras Fantasma. Hace mucho que se alió con la Plaga, y sin embargo una vez fue un elfo vivo. Pasaba mucho tiempo en Aguja de la Estrella del Alba, al noreste de aquí. Se escondió allí muchas noches conspirando contra los suyos.\n\nRegistra la torre para encontrar más información, <nombre>. Puede que tuviera un diario o anotaciones. Nunca se sabe lo que se puede encontrar.", progress = nil, completion = "Echas un vistazo a las primeras páginas del viejo libro y llegas a la conclusión de que perteneció a Dar'Khan Drathir.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9162] = {title = "Huellas del pasado", objective = "Lleva el diario de Dar'Khan a la forestal Vynna al Enclave del Errante.", description = "Mientras ojeas el diario, tienes la inquietante sensación de que te están observando.\n\nEl contenido del diario también es inquietante. Dar'Khan no sentía más que odio y desprecio por su propia gente. El diario detalla minuciosamente sus maquinaciones y conjuras.\n\nPuede que Vynna encuentre algo útil en él.", progress = "Dime, <nombre>, ¿qué has averiguado?", completion = "Esta información es muy valiosa, &lt;nombre&gt;. Sabíamos que Dar'Khan planeaba robar el poder de La Fuente del Sol para la Plaga, pero la información que hay aquí es completamente nueva. El magister Kaendris del Sagrario del Sol la encontrará muy interesante.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9163] = {title = "En territorio ocupado", objective = "Roba los Planes de los elfos de la noche: An'daroth, los Planes de los elfos de la noche: An'owyn y los Planes de los elfos de la noche: Espiar a los sin'dorei, y llévaselos a Dama Aurífera en Tranquillien en las Tierras Fantasma.", description = "Bien, nuestra acción más directa ahora para averiguar qué están tramando los elfos de la noche será enviarte a su isla para que te enteres de todo lo que puedas.\n\nQuiero que vayas al oeste por la carretera que sale del pueblo hacia la Isla Shalandis, cerca de la costa. Ve allí y recupera cualquier plan que puedan tener en la isla o en su barco.", progress = "¿Por dónde vas en tu intento de descubrir la trama de los elfos de la noche en la Isla Shalandis, <clase>?", completion = "¡Problemas! Estos planes muestran las tropas de los elfos de la noche en An'daroth, lo que ya sabíamos, pero también en An'owyn, un lugar nexo más remoto del sureste.\n\nHay un tercer nexo hacia el este que no se menciona llamado An'telas. Todo esto me da muy mala espina, &lt;clase&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9164] = {title = "Cautivos en la Ciudad de la Muerte", objective = "Lleva el jarabe vigorizante de Renzithen a la Ciudad de la Muerte y rescata al aprendiz Varnis, a la boticaria Enith y al forestal Vedoran. Ve a ver a la arcanista Janeda al Sagrario del Sol y recibirás una recompensa.", description = "Ah, sí; una de mis mejores creaciones. Esta poción elimina casi todas las formas de estupor inducido alquímicamente.\n\nSus efectos secundarios son desorientación, náuseas y, muy raramente, ceguera temporal. Todo lo cual me parece preferible a lo que sea que la Plaga planea hacer con los prisioneros de la Ciudad de la Muerte.\n\nSuerte, valiente <clase>. La vas a necesitar.", progress = "¿Qué pasó con los prisioneros de la Ciudad de la Muerte? ¿Has estado allí?", completion = "Excelente trabajo, &lt;nombre&gt;. Sin ti esos prisioneros habrían perdido el juicio y el alma a manos de la Plaga.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][9165] = {title = "La libranza de salvoconducto", objective = "Entrega la libranza de salvoconducto firmado al comandante de envíos Metz que está en la Capilla de la Esperanza de la Luz de las Tierras de la Peste del Este.", description = "¡Sin la ayuda de los aventureros, mi caravana no habría sobrevivido! La Plaga apareció de quién sabe dónde e intentó impedir que llegáramos aquí.\n\n<El guardia Didier se seca la frente.>\n\nAhora tenemos que esperar aquí a que llegue el mariscal de campo Cuevas. Él firmará tu libranza de salvoconducto para que lo puedas llevar al comandante de envíos Metz a la Capilla de la Esperanza de la Luz.\n\nY... <nombre>, cuidado con lo que dices frente a Cuevas. Es el tipo de hombre que te arrancaría la cabeza de un mordisco y luego te la metería por la tráquea si le cruza el cable... y le suele pasar...Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de El AlbaInsignia de la Cruzada"}
MultiLanguageQuestData['mx'][9166] = {title = "Entregando los planes a An'telas", objective = "Entrega los planes de los elfos de la noche al magister Sylastor en An'telas en las Tierras Fantasma.", description = "Tienes que llevar los planes de los elfos de la noche a An'telas. Está hacia el este, en la ladera meridional de Cima Rasguño de Sol, al noreste del Sagrario del Sol.\n\nEl magister Sylastor está estudiando la energía del nexo de la línea Ley para ver si podemos usarla para luchar con la Plaga. Enséñale los planes para que sepa qué traman los elfos de la noche.", progress = "¡Menos mal que estás aquí!", completion = "¡Fue horrible! Los elfos de la noche invocaron sus cristales lunares aquí por alguna nefanda razón, pero me escabullí y reuní a bastantes de nuestros exploradores y taumaturgo del Sagrario del Sol. Los matamos a casi todos y el resto del grupo está persiguiendo a los supervivientes.\n\nMe alegro de que estés aquí; ¡solo me quedan un par de exploradores como escolta! ¡Esto es muy peligroso!\n\nDéjame leer estos planes para ver qué pretenden esos elfos de la noche.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9167] = {title = "La muerte del traidor", objective = "Mata a Dar'Khan Drathir en la Ciudad de la Muerte y lleva su cabeza al magister Kaendris al Sagrario del Sol en las Tierras Fantasma.", description = "Todo lo que hemos hecho en las Tierras Fantasma ha sido para recuperar lo que es nuestro. Hace demasiado tiempo que la Plaga tiene esta región dominada.\n\nHa llegado el momento de la revancha, <nombre>. Gracias a tu ayuda y la de nuestros nuevos aliados, los Renegados, pronto podremos vengarnos.\n\nEl que intentó robar el poder de La Fuente del Sol debe morir. Ve a la Ciudad de la Muerte, la fortaleza de la Plaga que está al sur de La Cicatriz Muerta. ¡Tráeme la cabeza de Dar'Khan y tu hazaña pasará a la historia!", progress = "¿Lo has hecho? ¿Has matado a Dar'Khan?", completion = "Has asestado un golpe mortal al dominio de la Plaga en esta región.\n\nAhora que ha muerto el traidor, no tardaremos en recuperar nuestras tierras y nuestra grandeza.", rewards = "Bastón del SolArco largo de ErranteHojalbaHoja de guerra sin'doreiRecibirás:\n\n"}
MultiLanguageQuestData['mx'][9169] = {title = "Desactivando An'owyn", objective = "Recupera el orbe de control y úsalo para desactivar el cristal lunar de los elfos de la noche en An'owyn. Después ve a ver al magister Sylastor a An'telas en las Tierras Fantasma.", description = "Sus cristales lunares son dispositivos de adivinación, ¡van a espiarnos! Sé que An'daroth no puede proporcionar suficiente energía, pero An'owyn, al sur, sí que puede.\n\nGracias a los planes tengo nociones básicas sobre el funcionamiento de los cristales; las suficientes como para apagarlos. Ve a An'owyn, róbale el orbe de control a uno de los elfos de la noche y úsalo para apagar los cristales e impedir que se lleve a cabo el plan.\n\n¡Date prisa, <clase>!", progress = nil, completion = "¡Qué alivio, &lt;clase&gt;! Te aseguro que si no hubieras desactivado los orbes de visión, nuestra posición sería aún más delicada de lo que ya es. Imagínatelo: ¡rodeados de enemigos y uno de ellos capaz de espiar todos nuestros movimientos!\n\nPero gracias a ti ya no tenemos que preocuparnos por eso. Ten; te mereces una recompensa y tengo unas cuantas cosas que ya no uso.\n\n¡Gracias otra vez, &lt;nombre&gt;!", rewards = "Capa de SylastorCamisa de escamas An'telasPodrás elegir una de estas recompensas:\n\nCristal adivinador\n\nTambién recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][9170] = {title = "Los tenientes de Dar'Khan", objective = "El magister Idonis quiere que vayas a la Ciudad de la Muerte para matar a Masophet el Negro, Jurion el Falsario, Borgoth el Flebotomista y Mirdoran el Caído. Cuando hayas terminado, vuelve a verle en el Sagrario del Sol en las Tierras Fantasma.", description = "Ese odioso traidor que es Dar'Khan ha conseguido mucho poder en la Plaga. Sus tenientes dirigen enormes ejércitos de no-muertos, y nosotros somos cada vez menos.\n\nMasophet el Negro, Jurion el Falsario, Borgoth el Flebotomista, Mirdoran el Caído. Apréndete estos nombres, porque en las Tierras Fantasma el único ser más importante que estos jefes de la Plaga es el propio Dar'Khan. Acaba con ellos y sus estúpidas tropas se dispersarán.", progress = nil, completion = "El ejército de Dar'Khan no tardará en caer. La Plaga no tiene ninguna posibilidad de resistir ante el poder conjunto de los sin'dorei y los Renegados.", rewards = "Blasón Quel'dorei reforjadoVarita de vigilante-LeyLeotardos garrafantasmaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][9171] = {title = "Texturas crujientes", objective = "Lleva 5 patas de araña crujientes al maestro cocinero Mouldier a Tranquillien en las Tierras Fantasma.", description = "¡Esto es intolerable, así no se puede trabajar! La Dama me pidió que viniera de Ciudad de Lunargenta porque quería un chef a la altura de su rango, ¿verdad? Pero resulta que no hay comida. Sal a cazar, <clase>; necesito algo que echar a las cazuelas.\n\nA la Dama Aurífera le gustan las texturas crujientes; hay muchos rondadores husaraña al suroeste, al otro lado de La Cicatriz Muerta. Ya sé que es repugnante, pero no hay otra cosa.", progress = "¡Oigo rugir el estómago de la dama desde aquí! ¿Me traes las patas de araña?", completion = "Bien, me apañaré con estas. No me describas a los bichos vivos, ¡no quiero saberlo! Les daré mi toque mágico a estas patas y saldrán muy buenas. Un poquito de especias, finas hierbas y por supuesto algunos ingredientes arcanos, y voilà, una comida digna de una reina. O de una dama en este caso.\n\nBuen trabajo, &lt;clase&gt;. Ten, una receta y unas muestras.", rewards = "Recibirás:\n\nSorpresa de araña crujienteReceta: sorpresa de araña crujiente"}
MultiLanguageQuestData['mx'][9172] = {title = "Informa al magister Kaendris", objective = "Lleva el diario de Dar'Khan al magister Kaendris al Sagrario del Sol en las Tierras Fantasma.", description = "Los magistri del Sagrario del Sol han aprendido mucho sobre los puntos débiles de la Plaga con ayuda de los Renegados. El magister Kaendris sabrá qué hacer con los datos.\n\nEl Sagrario del Sol está hacia el suroeste. Tienes que darte prisa, <nombre>. ¡Dar'Khan es muy astuto y vigila todos nuestros movimientos!", progress = "¿Querías hablar conmigo?", completion = "¿Qué...? ¡No puede ser! Es la letra de Dar'Khan; aquí tiene que haber información que revele algún punto débil de nuestro enemigo.\n\nHas hecho bien en venir a vernos, &lt;nombre&gt;. Los Errantes han demostrado buen juicio al dejar este asunto en nuestras manos. Esta armadura te ayudará a luchar por nuestra causa.", rewards = "Calzas de seda rojaChaleco de cuero negroLeotardos de escamas de TranquillienRecibirás:\n\n"}
MultiLanguageQuestData['mx'][9173] = {title = "Recuperar Aguja Brisaveloz", objective = "Mata a 8 acólitos de la Ciudad de la Muerte y a 10 forestales caídas y ve a ver al sumo ejecutor Mavren a Tranquillien en las Tierras Fantasma.", description = "¡<clase>, quiero que recuperes Aguja Brisaveloz!\n\nEs un honor para ti: fue el primer hogar de Lady Sylvanas Brisaveloz, reina de los Renegados y antigua General Forestal de los elfos. La Aguja ha sido invadida por la Plaga.\n\nSigue el camino hacia el sur y gira a la derecha en la bifurcación; cuando llegues a La Cicatriz Muerta, ve hacia el suroeste. No tiene pérdida.", progress = nil, completion = "A Lady Sylvanas le complacerá saber que hemos hecho progresos en este asunto.\n\nTen, acepta esta moneda en pago por tus esfuerzos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9174] = {title = "Derrotar a Aquantion", objective = "Geranis Albodía quiere que nades hasta el fondo del lago al este de la Aldea Corona del Sol y uses los medallones ante el Altar del Dominio de las Mareas. Invoca al elemental llamado Aquantion, ejecútalo y regresa junto a Geranis.", description = "Ese obstinado elemental acabó con muchas vidas en aquel fatídico día cuando se rebeló. Recurriendo al modesto múrloc para sabotear nuestros ritos, pervirtió nuestra magia para atacarnos con ella.\n\n¡Demuéstrale que nuestra sed de venganza no ha menguado! Lleva estos medallones ante el Altar del Dominio de las Mareas, al fondo del lago. ¡Aquantion responderá sin tardar a la llamada!\n\n¡Ten cuidado, <raza>! Sin nuestra magia que lo controla, su ira se desatará sin límites. ¡Destruye a Aquantion para que podamos encontrar algún descanso!", progress = "¿Has destruido a Aquantion?", completion = "Has vengado nuestras muertes y has roto el dominio de Aquantion sobre nuestras almas. Por fin podremos descansar en paz.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9175] = {title = "El collar de Sylvanas", objective = "Llévale el collar de Sylvanas al sumo ejecutor Mavren en Tranquillien en las Tierras Fantasma.", description = "El collar resplandece, una extraordinaria joya que no sucumbe ante la penumbra que envuelve las Tierras Fantasma. Por la inscripción y el lugar donde lo encontraste ¡debe de pertenecer a la mismísima Lady Sylvanas Brisaveloz!\n\nCreo que habría que llevarlo al sumo ejecutor Mavren en Tranquillien. Al parecer, es el Renegado de más alto rango en esa zona y seguro que sabrá qué hacer con él.", progress = "¿Qué tienes ahí, <nombre>?", completion = "¡¿Dices que lo tenía uno de los miembros de la Plaga en la Aguja Brisaveloz y que hay una inscripción?! ¡A ver!\n\nAquí tienes, una moneda por un buen trabajo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9176] = {title = "Los zigurats gemelos", objective = "Dirígete al Zigurat Sangrante y al Zigurat Aullante y recupera la piedra de luz y la piedra de llama. Regresa junto al magister Kaendris en el Sagrario del Sol tras recuperar los objetos.", description = "Según este diario, Dar'Khan prometió a la Plaga dos poderosos artefactos elfos: la piedra de luz y la piedra de llama. Estas estaban imbuidas de la energía mágica de La Fuente del Sol y estaban diseñadas para dar protección frente a la Plaga.\n\nLas llevaron donde ahora se elevan el Zigurat Aullante y el Zigurat Sangrante, en medio de La Cicatriz Muerta. Si aún están allí, debemos recuperarlas. Su poder será de gran ayuda frente al enemigo.", progress = "¿Ya has recuperado las piedras?", completion = "¡Los rumores eran ciertos! ¡La piedra de luz y la piedra de llama existen! Usaremos su poder para crear armas contra Dar'Khan.\n\nÚsalas en el momento apropiado y la energía de La Fuente del Sol, atrapada en estos objetos, lo derrotará ¡con el mismísimo poder que él creía habernos arrebatado!", rewards = "Hoja de La Fuente del SolPodrás elegir una de estas recompensas:\n\nOrbe de La Fuente del Sol\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][9177] = {title = "Viaje a Entrañas", objective = "Ve al Barrio Real, en Entrañas, y entrégale el collar de Sylvanas a Lady Sylvanas Brisaveloz.", description = "¡Qué extraordinario! Parece ser un regalo para Lady Sylvanas Brisaveloz de su hermana, Alleria.\n\nDebes llevárselo a Entrañas rápidamente. Lady Sylvanas está en el Barrio Real.\n\nPara llegar allí, utiliza el orbe de traslado que está en el Sagrario Interior de la Aguja Furia del Sol, en la Ciudad de Lunargenta para cruzar a Entrañas. Cuando llegues, utiliza el elevador hasta la ciudad. Usa tus mapas si necesitas orientación para encontrar el Barrio Real.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9178] = {title = "Libranza del artesano: contrapeso denso", objective = "Entrega 120 contrapesos densos y la libranza del artesano: contrapeso denso al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo BS-091:\n\n120 contrapesos densos.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba ArgentaPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9179] = {title = "Libranza del artesano: peto de placas imperiales", objective = "Entrega 3 petos de placas imperiales y la libranza del artesano: peto de placas imperiales al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo BS-428:\n\n3 petos de placas imperiales.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba ArgentaPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9180] = {title = "Viaje a Entrañas", objective = "Ve al Barrio Real, en Entrañas, y entrégale el collar de Sylvanas a Lady Sylvanas Brisaveloz.", description = "¡Qué extraordinario! Parece ser un regalo para Lady Sylvanas Brisaveloz de su hermana, Alleria.\n\nDebes llevárselo a Entrañas rápidamente. Lady Sylvanas está en el Barrio Real.\n\nPara llegar allí, utiliza el orbe de traslado que está en el Sagrario Interior de la Aguja Furia del Sol, en la Ciudad de Lunargenta para cruzar a Entrañas. Cuando llegues, utiliza el elevador hasta la ciudad. Usa tus mapas si necesitas orientación para encontrar el Barrio Real.", progress = "¿Y tú eres...?\n\n¿Qué traes ahí? Ese collar me suena. ¡Dámelo!", completion = "&lt;Sylvanas te arranca el collar de las manos.&gt;\n\n¡No puede ser! Después de tanto tiempo, lo creía perdido para siempre.\n\n&lt;Al cabo de un momento parece volver en sí y recobra la compostura.&gt;\n\n¿Creías que esto me haría gracia? ¿Pensabas acaso que añoro los tiempos anteriores a mi reinado sobre los Renegados? Como tú, esto no significa nada para mí, y Alleria Brisaveloz no es más que un lejano recuerdo!\n\n&lt;Arroja el amuleto al suelo.&gt;\n\nPuedes retirarte, &lt;clase&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9181] = {title = "Libranza del artesano: martillo volcánico", objective = "Entrega 3 martillos volcánicos y la libranza del artesano: martillo volcánico al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo BS-697:\n\n3 martillos volcánicos.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba ArgentaPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9182] = {title = "Libranza del artesano: hacha de batalla de torio enorme", objective = "Entrega 3 hachas de batalla de torio enormes y la libranza del artesano: hacha de batalla de torio enorme al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo BS-6020:\n\n3 hachas de batalla de torio enormes.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba ArgentaPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
