MultiLanguageQuestData['mx'][9185] = {title = "Libranza del artesano: refuerzo para armadura basto", objective = "Entrega 25 refuerzos para armadura bastos y la libranza del artesano: refuerzo para armadura basto al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.|n", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo LW-448:\n\n25 refuerzos para armadura bastos.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba ArgentaPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9186] = {title = "Libranza del artesano: cinturón de cuero maligno", objective = "Entrega 9 cinturones de cuero maligno y la libranza del artesano: cinturón de cuero maligno al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo LW-736:\n\n9 cinturones de cuero maligno.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba ArgentaPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9187] = {title = "Libranza del artesano: pantalones de cuero rúnico", objective = "Entrega 4 pantalones de cuero rúnico y la libranza del artesano: pantalones de cuero rúnico al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo LW-8485:\n\n4 pantalones de cuero rúnico.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba ArgentaPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9188] = {title = "Libranza del artesano: pantalones de paño brillante", objective = "Entrega 6 pantalones de paño brillante y la libranza del artesano: pantalones de paño brillante al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo TR-95:\n\n6 pantalones de paño brillante.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba ArgentaPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9189] = {title = "Entrega a El Sepulcro", objective = "Entrega las órdenes sin'dorei selladas al consejero Sorrelon en El Sepulcro en el Bosque de Argénteos.", description = "Has agitado el corazón de la dama, aunque ya no late.\n\nSin embargo, tengo instrucciones para entregarlo en El Sepulcro, en el Bosque de Argénteos. El consejero Sorrelon nos representa ante los Renegados.\n\nLa ruta más corta sin utilizar sus murciélagos voladores, es salir de Entrañas y tomar el camino del sur. Sigue las señales. Encontrar el lugar no te resultará difícil. Pero prepárate. El Sepulcro es una cripta dilapidada.\n\nEsos Renegados son unas criaturas de lo más extrañas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9190] = {title = "Libranza del artesano: botas de paño rúnico", objective = "Entrega 8 botas de paño rúnico y la libranza del artesano: botas de paño rúnico al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo TR-635:\n\n8 botas de paño rúnico.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba ArgentaPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9191] = {title = "Libranza del artesano: bolsa de paño rúnico", objective = "Entrega 8 bolsas de paño rúnico y la libranza del artesano: bolsa de paño rúnico al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo TR-9999:\n\n8 bolsas de paño rúnico.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba ArgentaPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9192] = {title = "Problemas en las Minas Sondaluz", objective = "Mata a 8 gnolls Patanegra, 6 carroñeros Patanegra y 4 chamanes Patanegra, y regresa junto al mortacechador Maltendis en Tranquillien, en las Tierras Fantasma.", description = "Un clan de gnolls que se hacen llamar los Patanegra han tomado las Minas Sondaluz al suroeste. ¡No necesito recordarte cuán importante son esas minas como activo estratégico en nuestra campaña actual en las Tierras Fantasma!\n\nToma la carretera del sur saliendo de la ciudad y en la bifurcación gira a la derecha. Nada más pasar el zigurat a la derecha verás un camino de tierra corto hacia el oeste. Síguelo.\n\n¡El mineral debe fluir!", progress = nil, completion = "Un buen trabajo de carnicería, &lt;clase&gt;. Ahora mandaremos a los mineros volver al trabajo. Seguro que lamentarán que se les acabe el descanso pero hay que fabricar armaduras y armas y eso requiere mineral que se debe extraer.\n\nToma, acepta esto como pago por cumplir con tu deber. Ve a que te reparen la armadura y las armas y tómate algo, invito yo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9193] = {title = "Investiga las Catacumbas Amani", objective = "Investiga en las Catacumbas Amani, quema los restos de 10 trols momificados y regresa junto a la consejera Valwyn de Tranquillien en las Tierras Fantasma.", description = "<clase>, según nuestras fuentes los trols enterrados en las Catacumbas Amani, en la Cima Rasguño de Sol, han resucitado. La Dama Aurífera te pide que investigues esas catacumbas y le prendas fuego a cualquier despojo inanimado que te encuentres a fin de impedir que ni una más de estas criaturas resucite.\n\nEl camino más rápido es saliendo del pueblo por el norte y en la primera bifurcación giras a la derecha. De esta manera llegarás a la cara norte de la cumbre así que busca la entrada hacia el sur.", progress = "Este es un asunto de lo más sombrío e indecoroso, <clase>. Confío en que completarás esta tarea como para satisfacer a mi señora.", completion = "Asqueroso pero necesario, te lo puedo asegurar. Nos has hecho un gran favor investigando este asunto, &lt;clase&gt;. Te lo ruego, acepta esto como muestra de nuestra generosidad y aprecio.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9194] = {title = "Libranza del artesano: toga de paño rúnico", objective = "Entrega 8 togas de paño rúnico y la libranza del artesano: toga de paño rúnico al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo TR-7229:\n\n8 túnicas de paño rúnico.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba ArgentaPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9195] = {title = "Libranza del artesano: carga de zapador goblin", objective = "Entrega 20 cargas de zapador goblin y la libranza del artesano: carga de zapador goblin al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo EN-11:\n\n20 cargas de zapador goblin.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba ArgentaPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9196] = {title = "Libranza del artesano: granada de torio", objective = "Entrega 20 granadas de torio y la libranza del artesano: granada de torio al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo EN-7:\n\n20 granadas de torio.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba Argenta\nPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9197] = {title = "Libranza del artesano: gallo de batalla gnómico", objective = "Entrega 4 gallos de batalla gnómicos y la libranza del artesano: gallo de batalla gnómico al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo EN-0:\n\n4 gallos de batalla gnómicos.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba ArgentaPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9198] = {title = "Libranza del artesano: tubo de torio", objective = "Entrega 14 tubos de torio y la libranza del artesano: tubo de torio al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo EN-558:\n\n14 tubos de torio.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba ArgentaPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9199] = {title = "Juju trol", objective = "Consigue 8 Jujus trol y llévaselos al mortacechador Maltendis en Tranquillien, en las Tierras Fantasma.", description = "Los cadáveres de los trols enterrados en las Catacumbas Amani ¡han resucitado! Quiero que vayas allí y traigas una prueba de su derrota definitiva. Algunas de estas momias trols, y su homólogo viviente, llevan Juju; unos objetos brillantes que albergan una fuente de energía desconocida. ¡Probablemente sea lo que los anime!\n\nLas catacumbas se encuentran en la Cima Rasguño de Sol, hacia el este. He oído que el acceso más fácil es por la cara norte de la montaña. ¡Ve a comprobarlo, <clase>!", progress = "No necesito recordarte que mal nos podemos permitir este jaleo con los muertos trols resucitando en nuestro jardín! ¡Ya tenemos suficiente con lo de la Ciudad de la Muerte al sur!", completion = "Momias erigidas por sacerdotes trols... ¡ingenioso! Los trols Sombrapino deben de estar intentando incrementar sus efectivos a través de estas prácticas nigrománticas. Apostaría a que estos oráculos usaban el Juju en su ritual de reanimación.\n\nUna vez más has cumplido con tu deber como cabe esperar de un &lt;clase&gt; de creciente reputación como la tuya. Acepta esto con nuestra gratitud.", rewards = "Manijas putrefactasGuantes de enterradorManoplas de MaltendisRecibirás:\n\n"}
MultiLanguageQuestData['mx'][9200] = {title = "Libranza del artesano: poción de maná sublime", objective = "Entrega 10 pociones de maná sublimes y la libranza del artesano: poción de maná sublime al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo AL-473:\n\n10 pociones de maná sublimes.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba Argenta\nPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9201] = {title = "Libranza del artesano: poción de Protección contra lo Arcano superior", objective = "Entrega 15 pociones de Protección contra lo Arcano superior y la libranza del artesano: poción de Protección contra lo Arcano superior al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.|n", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo AL-1420:\n\n15 pociones de Protección contra lo Arcano superior.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba Argenta\nPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9202] = {title = "Libranza del artesano: poción de sanación sublime", objective = "Entrega 20 pociones de sanación sublime y la libranza del artesano: poción de sanación sublime al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo AL-169110:\n\n20 pociones de sanación sublime.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba ArgentaPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9203] = {title = "Libranza del artesano: poción de petrificación", objective = "Entrega 1 poción de petrificación y la libranza del artesano: poción de petrificación al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo AL-90:\n\n1 poción de petrificación.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba ArgentaPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9204] = {title = "Libranza del artesano: anguila escama pétrea", objective = "Entrega 40 anguilas escama pétrea y la libranza del artesano: anguila escama pétrea al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo FS-5:\n\n40 anguilas escama pétrea.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba ArgentaPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9205] = {title = "Libranza del artesano: pez coraza de placas", objective = "Entrega 30 peces coraza de placas y la libranza del artesano: pez coraza de placas al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo FS-12:\n\n30 peces coraza de placas.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba ArgentaPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9206] = {title = "Libranza del artesano: anguila relámpago", objective = "Entrega 30 anguilas relámpago y la libranza del artesano: anguila relámpago al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "Páguese al portador de esta libranza con una insignia de su elección, una vez completada la orden de trabajo contratada.\n\nOrden de trabajo FS-9:\n\n30 anguilas relámpago.\n\nTodas las órdenes completadas deben ser entregadas al maestro de manada Mazadura en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\nEste contrato quedará anulado en caso de alteraciones o daños.\n\n-Comandante de envíos Metz, El Alba ArgentaPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nInsignia de la CruzadaInsignia de El Alba"}
MultiLanguageQuestData['mx'][9207] = {title = "Muestras de mena de Sondaluz", objective = "Reúne 6 menas de Sondaluz y entrégaselas al magister Quallestis en el Sagrario del Sol en las Tierras Fantasma.", description = "Me enviaron aquí desde el Sagrario del Sol para recolectar algunas muestras de menas ¡pero los gnolls han tomado el lugar! Servirán mi cabeza en una bandeja si no le llevo pronto esas muestras al magister pronto. ¿Podrías ayudarme, <clase>?\n\nPuedes encontrar menas en las vetas de estaño y cobre. Los gnolls también llevan encima. Cuando tengas suficientes, llévaselas al magister Quallestis en el Sagrario del Sol, hacia el este. Cruza La Cicatriz Muerta y encontrarás el sagrario justo al sur de la Cima Rasguño de Sol.", progress = "¿En qué puedo ayudarte, <clase>?", completion = "¿Mi aprendiza no fue capaz de ocuparse de esto ella sola? Tendré que hablar con ella cuando vuelva, con gnolls o sin ellos. Y hablando de la reina de Roma, ¿por qué no ha vuelto contigo?\n\n&lt;El magister suspira.&gt;\n\nMenuda fierecilla, no va a ser fácil instruirla debidamente. Gracias, &lt;clase&gt;, por traerme estas muestras. Esperamos poder descubrir alguna propiedad especial en ellas que ayude en la lucha contra la Plaga.\n\nAcepta esta moneda como muestra de mi agradecimiento.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9208] = {title = "La guardia salvaje: arcanum de protección", objective = "Zanza el Incansable de Zul'Gurub quiere un arcanum de protección.", description = "¡Zanza puede hacer muchos antiguos encantamientos trol si tiene los materiales adecuados! ¿Has oído hablar de la guardia salvaje? No, claro que no. Tu mente está nublada con la magia élfica menor.\n\nTráeme un arcanum de creación élfica para que pueda destruir la aberración. Hazlo y la guardia salvaje será tuya.\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGuardia salvajeCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][9209] = {title = "La guardia salvaje: arcanum de rapidez", objective = "Zanza el Incansable de Zul'Gurub quiere un arcanum de rapidez.", description = "¡Zanza puede hacer muchos antiguos encantamientos trol si tiene los materiales adecuados! ¿Has oído hablar de la guardia salvaje? No, claro que no. Tu mente está nublada con la magia élfica menor.\n\nTráeme un arcanum de creación élfica para que pueda destruir la aberración. Hazlo y la guardia salvaje será tuya.\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGuardia salvajeCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][9210] = {title = "La guardia salvaje: arcanum de enfoque", objective = "Zanza el Incansable de Zul'Gurub quiere un arcanum de enfoque.", description = "¡Zanza puede hacer muchos antiguos encantamientos trol si tiene los materiales adecuados! ¿Has oído hablar de la guardia salvaje? No, claro que no. Tu mente está nublada con la magia élfica menor.\n\nTráeme un arcanum de creación élfica para que pueda destruir la aberración. Hazlo y la guardia salvaje será tuya.\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGuardia salvajeCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][9211] = {title = "El guardahielo", objective = "Mataus el Colérico, de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 10 insignias de la Cruzada y 30 piezas de oro.", description = "Ah, el guardahielo. Es una fina capa de magia protectora que recubre ciertas piezas de equipamiento. Aquellos que combaten contra criaturas de escarcha y hielo ganarán protección frente a sus ataques utilizando el guardahielo.\n\nPero como todas las cosas que crea Mataus el Colérico, tiene un precio. Un precio que no rebajaré, aunque me llores. ¿Te interesa la cosa?Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGuardiahielo"}
MultiLanguageQuestData['mx'][9212] = {title = "Huida de las catacumbas", objective = "Escolta a la forestal Lilatha junto al capitán Helios hasta el Enclave del Errante en las Tierras Fantasma.", description = "Estos trols me tendieron una emboscada y me enjaularon. ¡Creo que van a sacrificarme! ¡Ayúdame a salir de aquí!\n\nLa cerradura de la jaula no es tan compleja... es que no la puedo abrir desde dentro. Te ruego que me escoltes hasta el Enclave del Errante. Seguro que el capitán Helios te da una recompensa, ¡y claro, mi eterna gratitud!", progress = nil, completion = "Tienes madera de héroe, &lt;clase&gt;, para sacarla de allí con vida. Supongo que tendremos que lanzar un ataque para despejar esas catacumbas también. ¡Como si no tuviéramos ya bastante con los trols vivos!\n\nHoy has hecho una proeza, debo recompensarte. Elige aquí lo que quieras.", rewards = "Chanclos de trolChanclos de trolChanclos de trolRecibirás:\n\n"}
MultiLanguageQuestData['mx'][9213] = {title = "El guardasombras", objective = "Mataus el Colérico, de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 10 insignias de la Cruzada y 30 piezas de oro.", description = "¡La creación de un genio! Como el guardahielo, el guardasombras recubre con una ligera capa de magia protectora algunas piezas de equipamiento. Y, como el guardahielo, el guardasombras te va a costar una estupenda cantidad de dinero.\n\n<Mataus se frota las manos.>\n\n¿Te interesa la cosa?Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGuardasombras"}
MultiLanguageQuestData['mx'][9214] = {title = "Armas Sombrapino", objective = "Reúne 3 hachas de rebanacabezas, 3 mazas de taumaturgo umbrío, 3 zarpas de señor de los felinos y 3 bastones de aojador. Llévaselos al capitán Helios en el Enclave del Errante, en las Tierras Fantasma.", description = "<clase>, quiero que mates a tantos trols Sombrapino como puedas. Necesitamos reducir significativamente sus efectivos antes de poder centrarnos en la Ciudad de la Muerte. Y ya que estás, podríamos matar dos pájaros de un tiro, así que tráeme también una pila de sus armas. Mejor que no se desperdicien, y las podemos usar en nuestra guerra contra la Plaga.\n\nAtaca sin miramientos sus campamentos al sur y al este en Zeb'Tela y en Zeb'Nowa.", progress = "¿Ya tienes esas armas? Con los efectivos de los Sombrapino diezmados, por fin podremos centrar nuestra atención en combatir a la Plaga.", completion = "Enviaré inmediatamente a unos forestales para que investiguen el daño que has causado a los trols Sombrapino. Seguro que podremos barrerlos después de tu ofensiva y lanzaremos un ataque sobre la Plaga pronto si estas armas son una muestra de tu éxito.\n\nAquí tienes, toma esta moneda como pago. De todos modos, me está haciendo un agujero en la faltriquera.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9215] = {title = "¡Tráeme la cabeza de Kel'gash!", objective = "Llévale la cabeza de Kel'gash el Malvado al capitán Helios en el Enclave del Errante, en las Tierras Fantasma.", description = "SE BUSCA: Llévale la cabeza de Kel'gash el Malvado, jefe de los trols Sombrapino, al capitán Helios. No habrá preguntas. Kel'gash mora en algún lugar del sur, en Zeb'Nowa.\n\n\n\nRECOMPENSA: Sí ¡pero nada de anticipos!", progress = "¿Qué es este tufo asqueroso?", completion = "Ah, era la cabeza de Kel'gash lo que olía tan mal. ¡Un trabajo de categoría, &lt;clase&gt;!\n\nCon su jefe muerto, la confusión debe reinar entre los trols Sombrapino. Combinado con tus últimas acciones para diezmar sus efectivos, debería ser el momento perfecto para lanzar nuestro contraataque y borrarlos del mapa de una vez por todas.\n\nTienes mi agradecimiento, &lt;nombre&gt;. ¿Crees que te gustaría uno de estos?", rewards = "Arco largo bien hechoEspada bien hechaBastón bien hechoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][9216] = {title = "Corazones putrefactos", objective = "Llévale 10 corazones putrefactos a la magistrix Aminel en Tranquillien.", description = "He oído que los trols Amani se comen el corazón de sus enemigos para robarles la fuerza. Puede que ahora estén tramando algo, <nombre>. Con el trato adecuado, los corazones de los muertos pueden producir potentes elixires.\n\nCaza los zombis que vagan por La Cicatriz Muerta y tráeme sus corazones. Te mostraré el tipo de mejora que podemos aplicar a tu pericia física frente a los no-muertos.", progress = "¿Tienes los corazones de zombi que te pedí, <nombre>?", completion = "Tómate este jarabe, &lt;nombre&gt;. Cuando lo tomes notarás un subidón en tu fuerza física frente a la Plaga. Si necesitas más que esta muestra, tráeme más corazones.", rewards = "Recibirás:\n\nJarabe finiquiplaga"}
MultiLanguageQuestData['mx'][9217] = {title = "Más corazones putrefactos", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nJarabe finiquiplaga"}
MultiLanguageQuestData['mx'][9218] = {title = "Polvo de espina dorsal", objective = "Llévale 10 puñados de polvo de espina dorsal a la magistrix Aminel en Tranquillien.", description = "La energía oscura que fluye por los cuerpos de los esqueletos reanimados tiende a acumularse sobre todo en la espina dorsal. He descubierto un método para imbuir esta energía en una poción que potencia las facultades mágicas frente a los no-muertos.\n\nTráeme polvo de espina dorsal y te daré una muestra. Encontrarás un gran número de esqueletos deambulantes por La Cicatriz Muerta, hacia el oeste.", progress = "¿Tienes las muestras que te pedí, <nombre>?", completion = "Tómate esto, &lt;nombre&gt;. ¡Notarás el cambio enseguida!\n\nTrae todo el polvo de espina dorsal que quieras, puedo usar tanto como puedas suministrar. ¿Efectos secundarios? Podrías notar que las articulaciones te dan un poco de guerra. Nada permanente, ¡te lo garantizo!", rewards = "Recibirás:\n\nInfusión finiquiplagaCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][9219] = {title = "Más polvo de espina dorsal", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nInfusión finiquiplaga"}
MultiLanguageQuestData['mx'][9220] = {title = "Guerra a la Ciudad de la Muerte", objective = "Mata 5 ojos de Dar'khan, 6 centuriones Nerubis y 6 plañideras en la Ciudad de la Muerte y regresa junto al magister Idonis en el Sagrario del Sol, en las Tierras Fantasma.", description = "Si quieres contribuir a nuestra causa, has venido al lugar adecuado y en el momento justo.\n\nAl reconstruir el Sagrario del Sol, hemos lanzado un desafío en las mismísimas puertas del cuartel general del enemigo: Ciudad de la Muerte.\n\nAdelante, lucha contra las hordas de no-muertos que moran en la fortaleza de la Plaga.", progress = nil, completion = "La Plaga ha sentido nuestra cólera, &lt;nombre&gt;. Su maldita ciudadela no tardará en convertirse en ruinas.\n\nCon sus efectivos reducidos, es hora de lanzar un ataque sobre objetivos más estratégicos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9221] = {title = "Armamento superior de batalla: amistoso con El Alba", objective = "Por 30 insignias de El Alba y 30 de la Cruzada, puedes elegir un objeto del tesoro de El Alba Argenta.|n", description = "Saludos, <amigo/amiga>. ¿Tienes alguna insignia de El Alba o la Cruzada que quieras canjear por objetos de poder?\n\nPermite que te diga que las compras efectuadas con un nivel de reputación amistoso con El Alba llevan un recargo muy elevado. Te aconsejo que ganes una mejor reputación con El Alba antes de seguir con tus planes.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Último recurso de VerimondeYelmo de cuero santificadoLeotardos del Cazador de pestePodrás elegir una de estas recompensas:\n\nSortija de piedadSortija de resoluciónBolsa de suministros"}
MultiLanguageQuestData['mx'][9222] = {title = "Armamento épico de batalla: amistoso con El Alba", objective = "Por 110 insignias de El Alba y 110 de la Cruzada, puedes elegir un objeto del tesoro de El Alba Argenta.", description = "Saludos, <amigo/amiga>. ¿Tienes alguna insignia de El Alba o la Cruzada que quieras canjear por objetos de gran poder?\n\nPermite que te diga que las compras efectuadas con un nivel de reputación amistoso con el Alba llevan un fuerte recargo. Te aconsejo que ganes una mejor reputación con El Alba antes de seguir con tus planes.\nPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "El PurificadorBrazales de esperanzaBrazales de subterfugioPodrás elegir una de estas recompensas:\n\nAmuleto del AlbaMedallón del AlbaDije de Ascendiente"}
MultiLanguageQuestData['mx'][9223] = {title = "Armamento superior de batalla: honorable con El Alba", objective = "Por 20 insignias de El Alba y 20 de la Cruzada, puedes elegir un objeto del tesoro de El Alba Argenta.", description = "Saludos, <amigo/amiga>. ¿Tienes alguna insignia de El Alba o la Cruzada que quieras canjear por objetos de poder?\n\nPermite que te diga que las compras efectuadas con un nivel de reputación honorable con El Alba llevan un recargo prohibitivo. Te aconsejo que ganes una mejor reputación con El Alba antes de seguir con tus planes.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Último recurso de VerimondeYelmo de cuero santificadoLeotardos del Cazador de pestePodrás elegir una de estas recompensas:\n\nSortija de piedadSortija de resoluciónBolsa de suministros"}
MultiLanguageQuestData['mx'][9224] = {title = "Armamento épico de batalla: honorable con El Alba", objective = "Por 75 insignias de El Alba y 75 de la Cruzada, puedes elegir un objeto del tesoro de El Alba Argenta.", description = "Saludos, <amigo/amiga>. ¿Tienes alguna insignia de El Alba o la Cruzada que quieras canjear por objetos de gran poder?\n\nPermite que te diga que las compras efectuadas con un nivel de reputación honorable con el Alba llevan un fuerte recargo. Te aconsejo que ganes una mejor reputación con El Alba antes de seguir con tus planes.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "El PurificadorBrazales de esperanzaBrazales de subterfugioPodrás elegir una de estas recompensas:\n\nAmuleto del AlbaMedallón del AlbaDije de Ascendiente"}
MultiLanguageQuestData['mx'][9225] = {title = "Armamento épico de batalla: venerado con El Alba", objective = "Por 45 insignias de El Alba y 45 de la Cruzada, puedes elegir un objeto del tesoro de El Alba Argenta.", description = "Saludos, <amigo/amiga>. ¿Tienes alguna insignia de El Alba o la Cruzada que quieras canjear por objetos de gran poder?\n\nHe de advertirte: las compras épicas hechas con un nivel de reputación venerado con el Alba, siguen siendo bastante caras. Te aconsejo que ganes una mejor reputación con El Alba antes de seguir con tus planes.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "El PurificadorBrazales de esperanzaBrazales de subterfugioPodrás elegir una de estas recompensas:\n\nAmuleto del AlbaMedallón del AlbaDije de Ascendiente"}
MultiLanguageQuestData['mx'][9226] = {title = "Armamento superior de batalla: venerado con El Alba", objective = "Por 7 insignias de El Alba y 7 de la Cruzada, puedes elegir un objeto del tesoro de El Alba Argenta.|n", description = "Saludos, <amigo/amiga>. ¿Tienes alguna insignia de El Alba o la Cruzada que quieras canjear por objetos de poder?\n\nTenemos precios bastante razonables para aquellos que tengan un nivel de reputación venerado con El Alba... Te animo a que compres algo.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Último recurso de VerimondeYelmo de cuero santificadoLeotardos del Cazador de pestePodrás elegir una de estas recompensas:\n\nSortija de piedadSortija de resoluciónBolsa de suministros"}
MultiLanguageQuestData['mx'][9233] = {title = "Vademécum de Omarion", objective = "Lleva el vademécum de Omarion al artesano Wilhelm a la Capilla de la Esperanza de la Luz de las Tierras de la Peste del Este.|n", description = "Wilhelm:\n\nsi estás leyendo esto, quiere decir que he muerto... por fin. Quiero que sepas que mis últimos pensamientos han girado en torno a ti y a tu inabarcable ineptitud como artesano. Por desgracia, quien te lleva este manual tiene incluso peores dotes artesanales que tú.\n\nRespecto al libro: contiene el resto de mis recetas. Atiende al portador del libro en lo que te solicite. Sé que le cobrarás una considerable suma por tus servicios porque, al fin y al cabo, eres un sinvergüenza.\n\nCon todo mi desdén,\n\nOmarion", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][9234] = {title = "Los guanteletes Deliriohelado", objective = "El artesano Wilhelm de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 5 runas heladas, 12 barras de torio, 2 barras de arcanita, 2 esencias de agua y 200 piezas de oro.", description = "Gracias a ti y a Omarion (que espero que descanse en paz), ahora puedo confeccionar los guantes Deliriohelado. Todo lo que necesito es que me traigas los materiales y pagues una pequeña suma.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGuanteletes Deliriohelado"}
MultiLanguageQuestData['mx'][9235] = {title = "Los brazales Deliriohelado", objective = "El artesano Wilhelm de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 4 runas heladas, 12 barras de torio, 2 barras de arcanita, 2 esencias de agua y 200 piezas de oro.", description = "Gracias a ti y a Omarion (que en paz descanse), ahora puedo crear brazales Deliriohelado. Solo necesito que me traigas los materiales y que me pagues un pequeño honorario por la mano de obra.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBrazales Deliriohelado"}
MultiLanguageQuestData['mx'][9237] = {title = "La capa glacial", objective = "El artesano Wilhelm de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 5 runas heladas, 4 madejas de paño rúnico, 2 esencias de agua, 4 sedas de araña Tejehierro y 200 piezas de oro. Además, debes tener un nivel de reputación de exaltado con El Alba Argenta.", description = "Gracias a ti y a Omarion (que espero que descanse en paz), ahora puedo confeccionar la capa glacial. Todo lo que necesito es que me traigas los materiales y pagues una pequeña suma.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCapa glacial"}
MultiLanguageQuestData['mx'][9244] = {title = "Los brazales de escamas heladas", objective = "El artesano Wilhelm de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 4 runas heladas, 16 escamas de escórpido pesado, 5 esencias de agua, 3 pellejos bastos curtidos y 200 piezas de oro.", description = "Gracias a ti y a Omarion (que espero que descanse en paz), ahora puedo confeccionar los brazales de escamas heladas. Todo lo que necesito es que me traigas los materiales y pagues una pequeña suma.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBrazales de escamas heladas"}
MultiLanguageQuestData['mx'][9245] = {title = "Los guanteletes de escamas heladas", objective = "El artesano Wilhelm de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 5 runas heladas, 16 escamas de escórpido pesado, 5 esencias de agua, 3 pellejos bastos curtidos y 200 piezas de oro.", description = "Gracias a ti y a Omarion (que en paz descanse), ahora puedo crear guanteletes de escamas heladas. Solo necesito que me traigas los materiales y que me pagues un pequeño honorario por la mano de obra.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGuanteletes de escamas heladas"}
MultiLanguageQuestData['mx'][9247] = {title = "La llamada de los guardianes", objective = "Llévale la carta del Guardián de los Pergaminos a la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", description = "<nombre>,\n\nEn el pasado has servido a los intereses de El Alba Argenta de modo muy satisfactorio. Una vez más lanzamos una llamada de auxilio.\n\n<nombre>, si deseas ayudarnos una vez más, preséntate al Guardián de los Pergaminos de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nPiedra de afilar consagradaAceite de zahorí bendito\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][9248] = {title = "Una humilde ofrenda", objective = "Aurel Hojaurea quiere que le lleves 1 cetro abisal al Fuerte Cenarion, en Silithus. También deben considerarte honorable con el Círculo Cenarion.", description = "Ishnu-alah, <raza>. Dame una prueba de la muerte de un Señor del Consejo Abisal y te recompensaré con un objeto que te ayudará a luchar contra los qiraji.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSortija de Cenarius"}
MultiLanguageQuestData['mx'][9250] = {title = "Cuerpo de Atiesh", objective = "Busca a alguien que te ayude a buscar las dos piezas del báculo que faltan y a exorcizar el bastón.", description = "Con la formación del cuerpo, Atiesh ya está casi completo. Solo falta la cabeza y la base del báculo. Y está el problema menor de que el bastón es un conducto de la maldad de Sargeron.\n\nBusca a alguien que te ayude a buscar las piezas que faltan y a exorcizar el bastón.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9252] = {title = "Defender la Aldea Brisa Pura", objective = "Mata 4 merodeadores Carnepútrea y 4 espectros oscuros, y regresa junto a la forestal Sareyn en Aldea Brisa Pura, en el Bosque Canción Eterna.", description = "Hemos sufrido un significativo aumento de los ataques de la Plaga, <nombre>. Nuestras defensas están en las últimas y no hay signo de refuerzos de la Ciudad de Lunargenta. Échanos una mano para defender la aldea, diezma los efectivos de no-muertos que deambulan por La Cicatriz Muerta.", progress = nil, completion = "Muchas gracias, &lt;nombre&gt;. Nuestro trabajo es muy ingrato pero hoy tú lo has hecho un poco más fácil.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9253] = {title = "El celador de las runas Deryan", objective = "Habla con el celador de las runas Deryan en el Bosque Canción Eterna, cerca de la frontera con las Tierras Fantasma.", description = "Este aumento de los ataques de la Plaga me hace creer que podría haber una disfunción en alguna de las piedras rúnicas protectoras de la frontera con las Tierras Fantasma.\n\nHemos usado estas piedras antiguas para protegernos de los no-muertos. Casi todas quedaron destruidas o se perdieron después del ataque a La Fuente del Sol.\n\nToma la carretera del sur, hacia las Tierras Fantasma, y busca al oeste un caminito. Encontrarás al celador de las runas Deryan junto a las piedras rúnicas cercanas, él sabrá si algo no está funcionando bien.", progress = nil, completion = "Debe de enviarte alguien de la Aldea Brisa Pura. Sabía que era solo cuestión de tiempo hasta que llegara la ayuda.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][9254] = {title = "El aprendiz de díscolo", objective = "Habla con la aprendiza Mirveda en el Sagrario del Este, en el Bosque Canción Eterna.", description = "Gracias por tu ayuda, <nombre>. Mientras restablezco el orden aquí, me gustaría pedirte un favor. Una de mis antiguas aprendices eligió una línea de investigación muy peligrosa. Se dirigió al Sagrario del Este, en medio de La Cicatriz Muerta.\n\nMe preocupa si seguirá bien. A ver si la encuentras y la convences de que sea más sensata.", progress = nil, completion = "Es muy bonito que quien fuera mi mentora se preocupe por mí. Lástima que perdiera la fe en mi investigación hace mucho tiempo.\n\nNo pierdas el tiempo intentando que vuelva junto a ella; elige entre ayudarme en mi investigación o marcharte.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][9255] = {title = "Notas de investigación", objective = "Llévale las notas de la investigación a la magistrix Landra Caminalba en la Aldea Brisa Pura, en el Bosque Canción Eterna.", description = "A pesar de lo desalentadores que puedan ser los resultados de mi investigación, contienen datos valiosos. Tengo que conseguir que un magister revise mi trabajo para que lo tomen en serio. Lleva estas notas a la magistrix Landra Caminalba en la Aldea Brisa Pura, hacia el oeste.", progress = "¿Tienes algo para mí?", completion = "Estas anotaciones... son sorprendentes. Si son correctas, significa que el daño causado a la tierra de La Cicatriz Muerta es irreversible.\n\nNotificaré al gran magister ahora mismo. Más razón para que nuestra raza escape de este mundo y encuentre su verdadero destino en Terrallende.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][9256] = {title = "La Aldea Brisa Pura", objective = "Habla con el forestal Degolien en la Aldea Brisa Pura, en el Bosque Canción Eterna.", description = "Tengo otra tarea para ti, <nombre>. Enviaron al forestal Degolien a la Aldea Brisa Pura para averiguar algo más sobre un ataque de los desdichados a un astillero cercano. Ha pedido refuerzos que no podemos darle todavía. Búscalo y préstale toda la ayuda que puedas.\n\nPuedes llegar a la Aldea Brisa Pura siguiendo la carretera que sale de la Plaza Alalcón hacia el sur hasta el final. Suerte, <nombre>.", progress = nil, completion = "Gracias por venir, &lt;nombre&gt;. Las cosas están peor de lo que habíamos previsto. Los desdichados se han adueñado del Fondeadero Vela del Sol.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][9258] = {title = "La Arboleda Agostada", objective = "Encuentra a Larianna Ríobrisa cerca de La Arboleda Agostada al suroeste del Bosque Canción Eterna.", description = "Una mancha asquerosa en el suelo precede la expansión de la Plaga en un nuevo territorio. La piedras rúnicas de la frontera con las Tierras Fantasma nos han resguardado frente a esta mancha en el pasado.\n\nEn un ataque de la Plaga quedó destruida la piedra rúnica situada más hacia el oeste, lo que nos obligó a quemar el territorio que la rodeaba para impedir que la mancha se extendiera.\n\nMi hermana, Larianna Ríobrisa, vigila La Arboleda Agostada. Encuéntrala, podría tener algún trabajo para ti.", progress = nil, completion = "Ah, te envía mi hermano. Sí que tengo una tarea en la que podrías ayudar.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][9259] = {title = "Un traidor de Velasangre", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][9260] = {title = "Investigar la Plaga de Ventormenta", objective = "Recoge 3 piedras necróticas oscuras de la Plaga a las afueras de Ventormenta e investiga los círculos rúnicos que hay cerca de su campamento.", description = "El Rey Exánime ha mandado sus no-muertos a nuestro umbral, ¡no podemos quedarnos de brazos cruzados! ¿Verdad que nos ayudarás a defender Ventormenta de estos malditos invasores?\n\nFuera hay unos extraños círculos rúnicos que brillan con la misma energía que rodea a los no-muertos y la Necrópolis. Seguro que tienen algún significado; quiero que vayas a averiguarlo. Aprovecha para liquidar a unas cuantas de esas abominaciones. Tráeme pruebas de las muertes, además de respuestas, y te recompensaré. ¡Ve!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][9261] = {title = "Investigar la Plaga de Forjaz", objective = "Recoge 3 piedras necróticas oscuras de la Plaga a las afueras de Forjaz e investiga los círculos rúnicos que hay cerca de su campamento.", description = "El Rey Exánime ha mandado sus no-muertos a nuestro umbral, ¡no podemos quedarnos de brazos cruzados! ¿Verdad que nos ayudarás a defender Forjaz de estos malditos invasores?\n\nFuera hay unos extraños círculos rúnicos que brillan con la misma energía que rodea a los no-muertos y la Necrópolis. Seguro que tienen algún significado; quiero que vayas a averiguarlo. Aprovecha para liquidar a unas cuantas de esas abominaciones. Tráeme pruebas de las muertes, además de respuestas, y te recompensaré. ¡Ve!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
