MultiLanguageQuestData['mx'][10464] = {title = "La promesa del sabio", objective = "Devuelve tu sortija de eternidad a Soridormi en las Cavernas del Tiempo después de alcanzar la reputación de honorable ante La Escama de las Arenas.", description = "Ya has hecho tu promesa, <clase>. Ahora depende de ti cumplirla.\n\nSirve a La Escama de las Arenas y recibirás una recompensa.\n\n¡Fracasa y el discurrir del tiempo tal como lo conocemos se desvanecerá!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSortija de eternidad"}
MultiLanguageQuestData['mx'][10465] = {title = "La promesa del restaurador", objective = "Devuelve tu sortija de eternidad a Soridormi en las Cavernas del Tiempo después de alcanzar la reputación de honorable ante La Escama de las Arenas.", description = "Ya has hecho tu promesa, <clase>. Ahora depende de ti cumplirla.\n\nSirve a La Escama de las Arenas y recibirás una recompensa. ¡Fracasa y el discurrir del tiempo tal como lo conocemos se desvanecerá!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSortija de eternidad"}
