MultiLanguageQuestData['mx'][10468] = {title = "La palabra del sabio", objective = "Devuelve tu sortija de eternidad a Soridormi en las Cavernas del Tiempo después de alcanzar la reputación de venerado ante La Escama de las Arenas.", description = "Has cumplido tu promesa, <nombre>. Y, por ello, has ganado el reconocimiento que merecías.\n\nMientras sigues estudiando los sucesos pasados relacionados con el Monte Hyjal, yo seguiré estudiando el poder de tu anillo. Pronto habrá llegado a su poder absoluto.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSortija de eternidad"}
MultiLanguageQuestData['mx'][10469] = {title = "La palabra del restaurador", objective = "Devuelve tu sortija de eternidad a Soridormi en las Cavernas del Tiempo después de alcanzar la reputación de venerado ante La Escama de las Arenas.", description = "Has cumplido tu promesa, <nombre>. Y, por ello, has ganado el reconocimiento que merecías.\n\nMientras sigues estudiando los sucesos pasados relacionados con el Monte Hyjal, yo seguiré estudiando el poder de tu anillo. Pronto habrá llegado a su poder absoluto.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSortija de eternidad"}
