MultiLanguageQuestData['mx'][10471] = {title = "La palabra del defensor", objective = "Devuelve tu sortija de eternidad a Soridormi en las Cavernas del Tiempo después de alcanzar la reputación de venerado ante La Escama de las Arenas.", description = "Has cumplido tu promesa, <nombre>. Y, por ello, has ganado el reconocimiento que merecías.\n\nMientras sigues estudiando los sucesos pasados relacionados con el Monte Hyjal, yo seguiré estudiando el poder de tu anillo. Pronto habrá llegado a su poder absoluto.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSortija de eternidad"}
MultiLanguageQuestData['mx'][10472] = {title = "El pacto del sabio", objective = "Devuelve tu sortija de eternidad a Soridormi en las Cavernas del Tiempo después de alcanzar la reputación de exaltado ante La Escama de las Arenas.", description = "Tus logros han sobrepasado con creces todas mis expectativas, <nombre>.\n\nEntras y sales del tiempo tranquilamente como cualquier dragón de bronce. Tu destino es conseguir un gran poder y me encantará ayudarte a llegar ahí.\n\nSigue sirviendo a La Escama de las Arenas y yo haré que consigas tu máximo potencial.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSortija del sabio eterno"}
MultiLanguageQuestData['mx'][10473] = {title = "El pacto del restaurador", objective = "Devuelve tu sortija de eternidad a Soridormi en las Cavernas del Tiempo después de alcanzar la reputación de exaltado ante La Escama de las Arenas.", description = "Tus logros han sobrepasado con creces todas mis expectativas, <nombre>.\n\nEntras y sales del tiempo tranquilamente como cualquier dragón de bronce. Tu destino es conseguir un gran poder y me encantará ayudarte a llegar ahí.\n\nSigue sirviendo a La Escama de las Arenas y yo haré que consigas tu máximo potencial.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSortija del restaurador eterno"}
