MultiLanguageQuestData['mx'][10475] = {title = "El pacto del defensor", objective = "Devuelve tu sortija de eternidad a Soridormi en las Cavernas del Tiempo después de alcanzar la reputación de exaltado ante La Escama de las Arenas.", description = "Tus logros han sobrepasado con creces todas mis expectativas, <nombre>.\n\nEntras y sales del tiempo tranquilamente como cualquier dragón de bronce. Tu destino es conseguir un gran poder y me encantará ayudarte a llegar ahí.\n\nSigue sirviendo a La Escama de las Arenas y yo haré que consigas tu máximo potencial.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSortija del defensor eterno"}
MultiLanguageQuestData['mx'][10476] = {title = "Enemigos encarnizados", objective = "El celador Moi'bff Jill de Telaar quiere que consigas 10 abalorios de guerra de obsidiana de los distintos ogros que viven en Nagrand.", description = "Si quieres demostrar tu lealtad, no hay mejor manera que combatiendo a nuestros enemigos.\n\nEntre estos, ninguno puede igualarse a los ogros en fuerza y ferocidad. Tráeme los abalorios de guerra que llevan alrededor del cuello como prueba de su derrota y correré la voz sobre tu proeza.", progress = "¿Y bien, <nombre>? ¿Solo vienes a charlar o tienes algo para mí?", completion = "Has empezado a demostrar tu valía como aliada y como combatiente. Sigue así.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10477] = {title = "Más abalorios de guerra", objective = "¿Tienes más abalorios de guerra de obsidiana, <nombre>?", description = nil, progress = "¿Tienes más abalorios de guerra de obsidiana, <nombre>?", completion = "Sigues demostrándonos tu valía, &lt;nombre&gt;. Que tu fuerza nunca te falle.", rewards = nil}
MultiLanguageQuestData['mx'][10478] = {title = "¡Más abalorios de guerra!", objective = "¿Has conseguido más abalorios de guerra, <nombre>?", description = nil, progress = "¿Has conseguido más abalorios de guerra, <nombre>?", completion = "Sigues demostrando tu fuerza y tu honor, &lt;nombre&gt;.", rewards = nil}
MultiLanguageQuestData['mx'][10479] = {title = "Demostrar tu fuerza", objective = "El celador Tororroc de Garadar quiere que consigas diez abalorios de guerra de obsidiana de los diferentes ogros que habitan Nagrand.", description = "Aunque queremos una vida tranquila, nuestros enemigos son muchos. De todos ellos, ninguno está a la altura de los ogros en fuerza bruta pura.\n\nSi intentas demostrarnos tu valentía, tráeme los abalorios de guerra que llevan en el cuello. Hablaré a otros de tus hazañas.", progress = "¿Tienes algo que enseñarme, <nombre>?", completion = "Sin duda eres un aliado fuerte, &lt;nombre&gt;. Enfrentarse directamente a los ogros de Terrallende no es algo que pueda hacer cualquiera.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10480] = {title = "Espíritus de agua iracundos", objective = "El ensalmador de la tierra Torlok de El Altar de Condenación, en el Valle Sombraluna, quiere que uses el Tótem de espíritus para capturar 5 almas acuáticas.|n", description = "Los nagas Illidari de la región se han hecho con el control de la única agua limpia que hay en el Valle Sombraluna.\n\nDirectamente hacia el norte encontrarás el refugio de los nagas: la Cicatriz Espiral. En los alrededores de la Cicatriz Espiral hay bolsas de agua agitada que aúllan angustiadas a la tierra. Estas son las bolsas por las que ahora se pasean los espíritus de agua iracundos.\n\nVe a la Cicatriz Espiral y usa el Tótem de espíritus para capturar las almas acuáticas. Encontrarás la mayor concentración de estos espíritus cerca de la Cisterna Cicatriz Espiral.\n", progress = "Doquiera encuentres nagas, casi seguro que encuentras espíritus del agua torturados.", completion = "Ya solo falta el aire, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10481] = {title = "Espíritus de aire iracundos", objective = "El ensalmador de la tierra Torlok de El Altar de Condenación, en el Valle Sombraluna, quiere que uses el Tótem de espíritus para capturar 10 almas aéreas.", description = "Dirígete al sureste, <héroe/heroína>. Cuando veas los campos de cristales azules gigantescos que sobresalen de la tierra, habrás llegado a tu destino. Es allí, en los Campos del Ala Abisal, donde encontrarás a los espíritus de aire iracundos. Deambulan por los acantilados y las faldas de las montañas que rodean los campos.\n\nDestruye su forma torturada y captura sus almas con el Tótem de espíritus. Vuelve junto a mí cuando lo hayas hecho.", progress = "Pronto hablaremos con las almas.", completion = "Permíteme recompensarte por acometer tan ardua tarea, héroe.\n\n¡Y ahora a trabajar! Retrocede un poco para que pueda colocar el tótem y liberar a las almas.|n", rewards = "Mandiletes del VacíoCincho de ManimalBotas del rompecielosEspaldares rompecielosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10482] = {title = "Orcos viles carroñeros", objective = "Mata a 20 orcos Mascahuesos y vuelve con Amadi al Bastión del Honor.", description = "Los carroñeros, orcos del clan Mascahuesos, andan por las ruinas que dan a El Camino a la Gloria. Debemos asumir que están recogiendo partes de máquinas de guerra para sus maestros en la Ciudadela del Fuego Infernal. ¡Hay que detenerlos!\n\nBusca orcos Mascahuesos al norte, <nombre>. ¡Búscalos y mátalos! Pero anda con cuidado, aunque sean los orcos inferiores de los clanes viles, su fortaleza es comparable a la de cualquier orco que hayamos encarado hasta ahora...", progress = nil, completion = "Muy bien. Sé bien que su pérdida será bien sentida en la Ciudadela del Fuego Infernal. A pesar de que ese bastión oscuro se cierne sobre nosotros, ¡con movimientos valientes como el tuyo obtendremos la victoria sobre los orcos viles!", rewards = "Picador de Fuego InfernalVara de desolaciónBallesta de repetición FerroestrellaRodela de desprendimientoEscudo oblongo de adamantitaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10483] = {title = "Malos augurios", objective = "La teniente Amadi, del Bastión del Honor, quiere que le lleves un dije maldito al cabo Crestahierro, de la Punta de Expedición.", description = "<nombre>, en nuestras batallas frente al clan de orcos viles Foso Sangrante, hemos visto unos abalorios. Esos orcos han ido coleccionando las insignias de los soldados caídos del Bastión del Honor y han creado dijes malditos. ¡Tememos que la magia oscura de los Foso Sangrante haya transformado nuestras insignias en encantamientos malignos contra nosotros!\n\nEncuentra uno de esos talismanes de los orcos Foso Sangrante de Zeth'Gor al este y llévaselo al cabo Crestahierro en la Punta de Expedición, al noreste de Zeth'Gor.", progress = "¿Información del Bastión del Honor, <nombre>? Eso es bueno, nuestra campaña contra los demonios y los orcos viles empieza a estar necesitada de gente capaz.", completion = "Ah, ¿has recuperado una insignia de los orcos Foso Sangrante? Bien, ¡es intolerable que usen nuestros propios símbolos en nuestra contra y se rían de nuestros compañeros caídos ante las bestias de piel roja!", rewards = "Te van a lanzar el siguiente hechizo:\n\nSet Rails Flag\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10484] = {title = "Dijes malditos", objective = "Lleva 12 dijes malditos al cabo Crestahierro, en la Punta de Expedición.", description = "¡<nombre>, no podemos permitir que los orcos Foso Sangrante posean los dijes malditos! Debes apropiarte de ellos para que tal vez puedan ser honrados los soldados que los poseyeron por su sacrificio. \n\nVe a Zeth'Gor, morada maldita de los Foso Sangrante y lleva a cabo tu tarea... tráeme los dijes malditos.", progress = "¿Dónde están los dijes, <nombre>?", completion = "Gracias, &lt;nombre&gt;. Se me entristece el corazón al verlos. Son el recuerdo de las grandes pérdidas que hemos tenido frente a los orcos viles en el Bastión del Honor. Si matamos suficientes, quizás podamos salir victoriosos de esta guerra.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10485] = {title = "Señor de la guerra del Foso Sangrante", objective = "Lleva la armadura destrozada del señor de la guerra Morkh al cabo Crestahierro, en la Punta de Expedición.", description = "Has dado muestras de gran fuerza y fortuna, ¡te has adentrado en Zeth'Gor y has sobrevivido! Ahora, esperemos que se mantenga tu fortuna pues tengo una tarea ardua para ti...\n\nEl señor de la guerra Morkh se encuentra en el cuartel de Zeth'Gor, dirigiendo tropas viles en nuestra contra. Sus tácticas son tan ávidas como crueles y debo admitir que sus éxitos contra nosotros han hecho mella. Así que, <nombre>, te pido que arranques a Mokh de su trono. ¡Tráeme su armadura para levantarles el ánimo a nuestros soldados!", progress = "¿Tienes la armadura destrozada de Morkh? ¿Te has adentrado en Zeth'Gor de nuevo?", completion = "¡Lo has conseguido! ¡Morkh ha muerto! ¡Ahora tenemos una oportunidad frente a los orcos viles! \n\nGracias, &lt;nombre&gt;. Tú ayuda aquí ha sido encomiable.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10486] = {title = "La naturaleza invasora", objective = "Mata a doce flebotomistas Alacuchilla.", description = "El clan del Señor del Trueno era antaño un clan de orcos orgullosos, hasta que fueron transformados en orcos viles a través de la sangre de Mannoroth.\n\nRecientemente recuperamos este bastión orco de los ogros que infestan el barranco que hay abajo. Se habían trasladado aquí cuando el clan del Señor del Trueno lo abandonó.\n\nMantendremos este lugar y contaré con tu ayuda para hacerlo.\n\nEn la Cresta Dentada, al sur y al oeste, hay flebotomistas que se han convertido en una plaga para nosotros. Comen y se multiplican sin cesar.\n\nMátalos y vuelve a mí.", progress = nil, completion = "No has tardado tanto como pensaba. ¿Seguro que te has ocupado de tantos como era necesario?\n\nMuy bien, hay algo más en lo que quiero que nos ayudes. Algo mucho más importante.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10487] = {title = "Polvo de los dracos", objective = "Reúne cuatro polvos de draco hada.", description = "Recientemente, la Alianza se ha trasladado al oeste, utilizando su magia élfica para hacer crecer una ciudad y una arboleda en un breve espacio de tiempo. Debemos mantener sus defensas débiles para que no se pongan gallitos.\n\nTengo un plan para conseguir esto y más. Quiero que cruces el puente al suroeste, que cruza por el Barranco Machacasangre y conduce a la Arboleda Viviente.\n\nAtaca sus defensas de draco hada en la Arboleda Viviente y trae de vuelta el polvo mágico que a veces se puede encontrar en sus alas.", progress = "Parece como si la Alianza estuviera decidida a seguirnos dondequiera que vayamos. Enseñémosles que no nos intimida su presencia.\n\n¿Tienes lo que te pedí?", completion = "No solo has debilitado su defensa, sino que vamos a utilizar este polvo para reforzar nuestra propia defensa contra la Alianza.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10489] = {title = "Talar un antiguo árbol", objective = "Consigue el tronco de Manofirme Raizhonda.", description = "¡SE BUSCA!\n\nManofirme Raizhonda, Anciano de la Guerra y defensor jefe de La Arboleda Viviente, al sur de Sylvanaar.\n\nEncuéntralo hacia el oeste cruzando el puente sobre el Barranco Machacasangre.\n\nLleva su tronco talado a Tor'chunk Dosgarras.", progress = "¿Qué tienes ahí? ¡Sí que eres fuerte!", completion = "¡El tronco de Manofirme Raizhonda! ¿Lo talaste tú sola?\n\nApuesto a que sí. ¿Sabes? Una &lt;clase&gt; joven y fuerte, como tú, siempre viene bien para ayudar por aquí, sobre todo con los problemas que los ogros no dejan de causarnos. No dejes de venir a verme si te interesa.\n\nBueno, ese tronco es sin duda una prueba, lo que significa que estás aquí para cobrar la recompensa y no para escucharme hablar. Adelante, elige lo que quieras.", rewards = "Leotardos de acción oscuraArnés de fuerza de osoYelmo de cornamenta salvajeBotas del asesino antiguoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10493] = {title = "Una propuesta seria", objective = "Lleva 15 muestras de veneno de Silithus, 20 piezas de oro y 1 par de brazales Forjaluz a Mokvar, en Orgrimmar.", description = "¡Saludos, <clase>! Se diría que has hecho y visto mucho en este mundo. Pero apuesto a que nunca has visto una armadura como esta.\n\nTe la cambiaré por un par de brazales normales si me haces un favor.\n\nNecesito bastante veneno de araña y escorpión de Silithus. Tráeme el veneno y algunas monedas de oro y haremos el intercambio.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBrazales Forjaalma"}
MultiLanguageQuestData['mx'][10502] = {title = "Los ogros Machacasangre", objective = "Destruye 30 ogros Machacasangre en la Avanzada Machacasangre.", description = "Sobre Sylvanaar pesa una amenaza mucho más letal que la Horda en el Bastión Señor del Trueno.\n\nHablo de los ogros nativos de estas montañas. Justo hacia el sur y el este, en el barranco, vive el clan Machacasangre. No son los únicos ogros que nos amenazan aquí, pero son los más cercanos.\n\nMe gustaría que fueses hacia el sur a través de La Arboleda Viviente y, a continuación, sigas el camino hacia el este hasta que llegues a su avanzada. Mata todos los ogros Machacasangre que puedas en la Avanzada Machacasangre.", progress = nil, completion = "Se trata de un buen primer paso a la hora de asegurar Sylvanaar y La Arboleda.\n\nAl haber reducido sus filas, los ogros Machacasangre se lo pensarán dos veces antes de atacarnos.\n\nOjalá fuera el único clan de ogros del que tenemos que preocuparnos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10503] = {title = "La amenaza Aguja del Filo", objective = "Destruye 30 ogros Aguja del Filo y 10 raptores Aguja del Filo en el Bastión Aguja del Filo y los Dominios Aguja del Filo.", description = "Hay una amenaza que pesa sobre el Bastión Señor del Trueno mucho peor que la Alianza en Sylvanaar.\n\nHablo de los ogros de estas montañas. Justo hacia el oeste, en el barranco, está el clan Aguja del Filo. Si bien no son los únicos ogros, son los más cercanos y los que tuvimos que destruir para poder ocupar este lugar.\n\nDirígete al norte a través de la Cresta Dentada y sigue por el camino que lleva al bastión. Mata a todos los ogros Aguja del Filo y a todos los raptores que puedas en el Bastión Aguja del Filo y los Dominios Aguja del Filo.", progress = nil, completion = "Se trata de un buen primer paso a la hora de asegurar nuestra posición contra los ogros.\n\nAl haber reducido sus filas, los Aguja del Filo se lo pensarán dos veces antes de intentar conquistar el Bastión Señor del Trueno.\n\nOjalá fuera el único clan de ogros del que tenemos que preocuparnos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10504] = {title = "Los ogros Aguja del Filo", objective = "Destruye 30 ogros Aguja del Filo en el Bastión Aguja del Filo y en los Dominios Aguja del Filo.", description = "Hacia el norte del clan Machacasangre yace una amenaza mucho más grave: el Bastión Aguja del Filo.\n\nLos ogros Aguja del Filo son el clan más fuerte de las montañas y tienen el favor del gronn conocido como Gruul el Asesino de Dragones y sus siete hijos.\n\nAhora que nos hemos encargado de los Machacasangre, ha llegado la hora de ir a por sus rivales.\n\nDesde la Avanzada Machacasangre dirígete al norte atravesando el barranco hasta que llegues al Bastión Aguja del Filo y los Dominios Aguja del Filo. Mata a todos los ogros Aguja del Filo que puedas.", progress = nil, completion = "Tus acciones contra los clanes Machacasangre y Aguja del Filo han significado un gran paso adelante a la hora de asegurar el futuro de Sylvanaar. Si bien no pretendemos expandirnos más allá de este trozo de tierra que, inicialmente, encontramos vacío, tampoco estamos dispuestos a permitir que nos destruyan.\n\nComo nos has hecho un gran servicio, lo recompensaré con el reconocimiento y el agradecimiento de la Alianza.", rewards = "Cinturón de vencedor ogroBrazales de montaña ágilesEspaldares de defensor de SylvanaarGuantes del comandante CielosombraRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10505] = {title = "Los ogros Machacasangre", objective = "Destruye 30 ogros Machacasangre en la Avanzada Machacasangre.", description = "Hacia el sur del clan Filo de Aguja otra amenaza: la Avanzada Machacasangre.\n\nSi bien los ogros Machacasangre no son el clan más fuerte de las montañas ya que no tienen el favor del gronn conocido como Gruul el Asesino de Dragones, están en segundo lugar.\n\nAhora que nos hemos encargado de los Aguja del Filo, ha llegado la hora de ir a por sus rivales.\n\nDesde el Bastión Aguja del Filo dirígete al sur atravesando el barranco hasta que llegues a la Avanzada Machacasangre. Mata a todos los ogros Machacasangre de la zona que puedas.", progress = nil, completion = "Tus acciones contra los clanes Aguja del Filo y Machacasangre han significado un gran paso adelante a la hora de asegurar el futuro del Bastión Señor del Trueno. No estamos dispuestos a permitir que se interpongan en nuestro destino.\n\nComo nos has hecho un gran servicio, lo recompensaré con el reconocimiento y el agradecimiento de la Horda.", rewards = "Manos rojas del Señor del TruenoCubrepiés de Tor'chunkBrazales de montaña bastosCinturón de golpeador ogroRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10506] = {title = "Una situación extrema", objective = "Rina Lunabril quiere que te lleves sus polvos de disminución y se los apliques a 5 de los lobos temibles Machacasangre, que se pueden encontrar en la Avanzada Machacasangre y en el Barranco Machacasangre.", description = "Con su manada de lobos reducida, la Horda busca sustitutos. Desafortunadamente, hay otra fuente cerca.\n\nLos ogro Machacasangre del barranco que hay abajo, al este, mantienen una manada fuerte como avizores. Odiaba enviarte a matar a los lobos del Señor del Trueno, así que, ¿por qué no hacemos algo diferente esta vez?\n\nHe obtenido polvos mágicos del polvo que se desprende de manera natural de las alas de nuestros dracos hada. Espolvoréalo sobre los lobos temibles Machacasangre para hacerlos indeseables para la Horda.", progress = "¿Ha habido algo de suerte? Sé que es peligroso estar haciendo esto entre los ogros Machacasangre, pero si podemos evitar la matanza de más animales, estaré satisfecha.", completion = "Me alegro de oír que funcionó. Cuantas menos criaturas de la naturaleza tengan que morir, mejor.\n\nCon todo lo que ya has hecho por nosotros, tengo que decir que empiezo a aficionarme mucho a tu compañía.\n\nCuídate, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10507] = {title = "Punto de inflexión", objective = "Usa la piedra de teletransporte de Socrethar en el Punto de Invasión: Señor Supremo, al norte de la Base Forja: Olvido, para transportar a tu grupo hasta el Embarcadero de Socrethar. Una vez allí, utiliza la Presencia de Voren'thal para vencer a Socrethar.\n\nLlevar a cabo misiones para los Arúspices hará que tu reputación Aldor disminuya.", description = "Esta es la oportunidad que estábamos esperando, <nombre>. No solo descubrimos las pruebas que necesitamos para mostrar a nuestro pueblo para quién trabaja Kael'thas en realidad, sino que podemos demostrar nuestra fuerza venciendo a sus nuevos amos.\n\nMi delicada salud me impide ayudarte en persona en este esfuerzo, pero te ofrezco un objeto que te permitirá proyectar mis poderes en todo el continente.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Faja de SocretharEspaldares de fusión abisalGrebas de poder con hechizosGuanteletes del vencedorVarita del videnteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10510] = {title = "En el interior de la Mina Draenetista", objective = "Consigue 5 cristales de la Mina Draenetista.", description = "¡Me alegro de ver que hay alguien dispuesto a ayudar!\n\nBorgrim y yo pertenecemos a la Liga de Expedicionarios y hemos venido a estudiar estas montañas. Nos han contado muchas cosas sobre este lugar y me muero de ganas por explorarlo.\n\nHay algo que ha llamado mi atención. Los elfos de la noche hablan sobre un lugar en el barranco conocido como la Mina Draenetista, hacia el este. Queda en la frontera sur de la Avanzada Machacasangre. Me gustaría conseguir algunos de los cristales que crecen allí.", progress = "¿No te parece excitante? Después de toda la suciedad y los insectos de Silithus, este lugar es como un paraíso.", completion = "Ahh, por la pinta que tienen, son unos cristales excelentes. Me muero por recoger mis herramientas y ponerme a estudiarlos.\n\n¡Muchas gracias!", rewards = "Manto de SpelunkerGuantes de mineroGuardabrazos todoterrenoBotas de expedicionarioRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10511] = {title = "Una extraña cerveza", objective = "Reúne 11 cervezas Machacasangre aterrabrutos.", description = "Para empezar bien este permiso, voy a necesitar más cerveza. Lamentablemente, los elfos no tienen ni idea del refinado arte de la fermentación.\n\nHe oído que los ogros Machacasangre allá en el barranco tienen en abundancia. No me importaría probarla.\n\n¿Me harías un favor? Ve al sur por La Arboleda Viviente y luego por la rampa hacia el este hasta la Avanzada Machacasangre y serías un encanto si me consiguieras algo de cerveza. Por lo visto, tienen barriles enormes por todas partes y además sus maestros cerveceros la reparten para que ningún ogro se quede sin ella.", progress = "La cosa está muy seca por aquí. ¿Cómo voy a disfrutar de mi descanso sin algo que beber?", completion = "¿Qué es ese olor? ¡¿Oh no, no me digas que es la cerveza de los ogros?!\n\nCasi me da miedo probarla. ¡Bah, da igual, al diablo! ¡De un trago!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10512] = {title = "Repostando Aguja del Filo", objective = "Utiliza el barril de Machacasangre aterrabrutos para intentar emborrachar a 5 ogros Aguja del Filo.", description = "¡No pienso volver a probar esa guarrería apestosa! Pero me ha dado una idea.\n\n<Borgrim te guiña el ojo.>\n\nEste es el plan. Sabemos que los Machacasangre viven prácticamente de esta bazofia. Y me pregunto qué piensan de eso sus enemigos, los ogros Aguja del Filo.\n\n<nombre>, quiero que cojas el resto de esta basura y se la lleves a los ogros Aguja del Filo. Les encontrarás hacia el norte de la Avanzada Machacasangre, atravesando el barranco.", progress = "¿Qué tal todo? ¿Los ogros Aguja del Filo son tan poco selectivos como los Machacasangre, o casi les ha matado como me pasó a mí?", completion = "¡Ah, ja, ja, ja! Justo lo que yo pensaba. Supongo que los ogros se pueden beber cualquier cosa.\n\n¡Qué idiotas son todos!\n\nBueno, debo decir que, aunque no conseguí mi brebaje, me has dado un gran comienzo de vacaciones.\n\nMira... tenemos un montón de cosas aquí que no usamos mucho. ¿Puedo ofrecerte algo?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10513] = {title = "Oronok Corazón Roto", objective = "Busca a Oronok Corazón Roto en la Barrera Arrasada – al norte de la Cisterna Cicatriz Espiral.|n", description = "No sé cómo podemos adquirir el hechizo que los espíritus mencionaron, <nombre>. A decir verdad, ni siquiera sé dónde empezar tal búsqueda.\n\n<Torlok mira fijamente a la distancia, perdido en sus pensamientos.>\n\nMmm... Es una posibilidad remota, pero podría ser nuestra única oportunidad. Hay un orco al que he visto visitar esta zona con anterioridad. Hablé con él brevemente una vez. Es un ermitaño que afirma vivir sobre la Cisterna Cicatriz Espiral, al noreste. Busca a este orco, Oronok Corazón Roto.\n\nComo dije, es una posibilidad remota.", progress = nil, completion = "¿Palabras de condenación? Nunca he oído hablar de ellas. Sigue mi consejo: deja que los muertos descansen.\n\nPero, ya que has venido hasta aquí, me vendría bien algo de ayuda con otros asuntos. ¿Qué me dices?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10514] = {title = "Yo era muchas cosas...", objective = "Oronok Corazón Roto, de la Granja de Oronok, en el Valle Sombraluna, quiere que recuperes diez tubérculos de Sombraluna de las Llanuras Devastadas.\n\nTambién quiere que le devuelvas el silbato de jabalíes de Oronok cuando hayas terminado.", description = "He sido muchas cosas, <extraño/extraña>, pero lo que fui una vez no es lo importante. Lo que importa es lo que soy ahora, y ahora lo que soy es granjero.\n\nSolía entrenar a jabalíes viles para que desenterraran tubérculos de la tierra endurecida de las Llanuras Devastadas. Sin embargo, recientemente, despellejadores de un nido que está al noreste han estado atacando a mis animales, impidiéndome que reuniera tubérculos.\n\n¿Irías a la zona al norte de aquí y reunirías tubérculos para mí? ¡Usa este silbato cuando estés sobre un túmulo de tubérculo y vendrá un jabalí para desenterrarlo!", progress = "¡Tráeme esos tubérculos!|n", completion = "¿Dices que había más despellejadores de los que esperabas? Parece que es hora de sacar la basura.", rewards = "Podrás elegir una de estas recompensas:\n\nTubérculo curativo de OronokTubérculo de agilidad de OronokTubérculo de fuerza de OronokTubérculo de poder con hechizos de Oronok\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][10515] = {title = "Una lección aprendida", objective = "Oronok Corazón Roto, de la Granja de Oronok, en el Valle Sombraluna, quiere que destruyas diez huevos de despellejador voraz de las Llanuras Devastadas.", description = "¡Tenemos que enseñar a esos despellejadores lo que sucede cuando te entrometes en los asuntos de Oronok!\n\nQuiero que vuelvas a las Llanuras Devastadas y destruyas cada huevo de despellejador que veas. Estarán en las profundidades del territorio de los despellejadores, así que mantente alerta.", progress = nil, completion = "¡Eso enseñará a esos malditos animales asquerosos a no matar a mis jabalíes! ¡Bien hecho, &lt;nombre&gt;!|n", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10516] = {title = "Las armas de un vindicador", objective = "Recupera la espada y el escudo de la vindicadora Vuuleen.", description = "Sé que parece extraño pero quiero quedarme en esta jaula. Me permite cumplir mi objetivo cuando vine: reunir información sobre los Aguja del Filo.\n\nPuedo marcharme cuando lo desee pero me gustaría recuperar mi espada y mi escudo.\n\nEstán en manos de sus líderes. Droggam tiene mi espada y Mugdorg tiene mi escudo.\n\nSi hiciera falta, consigue cerveza de la Avanzada Machacasangre, hacia el sur, y úsala para limitar la ayuda que puedan conseguir y engañar a esos dos líderes, ¡y ten cuidado con sus guardias sobrios que no prueban la bebida!", progress = "<clase>, ¿tienes mi espada y mi escudo?\n\nAunque podría marcharme en cualquier momento, sería vergonzoso volver a Sylvanaar sin mis armas.", completion = "Estoy en deuda contigo puesto que has contribuido a recuperar mi honor. Pero aún no hemos acabado nuestro trabajo aquí.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10517] = {title = "Gorr'Lelo, ha llegado tu hora...", objective = "Mata a Gorr'Lelo, líder de los ogros del Bastión Aguja del Filo.", description = "El líder del Bastión Aguja del Filo responde al nombre de Gorr'Lelo. Créeme... el nombre le va que ni pintado.\n\nAun así, no conviene subestimarlo. Tiene la pericia suficiente para haber elevado su clan hasta ser el favorito de Gruul el Asesino de Dragones y ahora dominan estas montañas. Además Gorr'Lelo se mantiene constantemente bien rodeado, y esto incluye guardaespaldas que han jurado no beber la cerveza Machacasangre.\n\nPor la seguridad de Sylvanaar, te pido que vuelvas allí y te ocupes de él.", progress = nil, completion = "Muy bien. Eres alguien con recursos, &lt;clase&gt;, sin duda alguna.\n\nMe pregunto si no habrá alguna otra cosa que pudieras hacer por mí y Sylvanaar...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10518] = {title = "Clavar el estandarte", objective = "Usa el estandarte de los Aguja del Filo sobre la Torre Quiebranorte para atraer a Gurn Jalazampa. Obtén el estandarte Aguja del Filo y el yelmo de Gurn Jalazampa.", description = "Quiero que robes el estandarte Aguja del Filo de uno de sus campeones y lo lleves al sur, a la Avanzada Machacasangre. Clávalo en lo alto de la Torre Quiebranorte.\n\nEsto enfurecerá a los Machacasangre y te atacarán sin descanso. Así centrarán su odio en el Bastión Aguja del Filo, lejos de Sylvanaar.\n\nSabrás que has logrado la hazaña cuando derrotes a Gurn Jalazampa y le arrebates el yelmo. Llévalo a Sylvanaar.\n\n<nombre>, esto no va a ser fácil. Será mejor que te acompañen un par de amigos.", progress = "¿Qué te trae hasta aquí? ¿No irás a decirme que el clan ogro Machacasangre vuelve a dar problemas?", completion = "¿El yelmo de Gurn Jalazampa y el estandarte Aguja del Filo? \n\nAstuta esa idea tuya y de la vindicadora de urdir ese plan. \n\nAl atraer la atención del clan Machacasangre sobre el Bastión Aguja del Filo, has aliviado la presión que empezaban a ejercer sobre nosotros aquí. \n\nTe lo ruego, &lt;nombre&gt;, acepta un humilde regalo de Sylvanaar.", rewards = "Armadura de taumaturgo de élite de SylvanaarCalzones de asesino ogroCasco astado de GurnSobrehombros de campeón de SylvanaarRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10519] = {title = "La Clave de Condenación: historia y verdad", objective = "Oronok Corazón Roto, en la Granja de Oronok del Valle Sombraluna, quiere que escuches su relato. Habla con Oronok para comenzar a escuchar su relato.", description = "<Oronok se endereza y deja ver su altura real.>\n\nTenía que asegurarme, <nombre>. Y para estar seguro, tenía que ponerte a prueba. Te ruego disculpes esta farsa. Soy tan granjero como tú <un/una> jabalí vil. Es decir, ni por asomo.\n\nSi vas a recuperar la Clave de Condenación, escucha atentamente lo que voy a decirte. Cuando estés <listo/lista> dímelo y te lo contaré todo.", progress = nil, completion = "¿Entiendes lo que se debe hacer? Encuentra a los hijos de Oronok. Encuentra a mis chicos...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10520] = {title = "Ayuda al archidruida Corzocelada", objective = "Habla con el archidruida Fandral Corzocelada en Darnassus.", description = "Perdona, <clase>, ¿podrías concederme un momento?\n\nEl Círculo Cenarion de Darnassus está buscando la ayuda de aventureros curtidos para un importante proyecto de investigación. No tengo muchos detalles pero puedo decirte que es el mismísimo archidruida Fandral Corzocelada quien encabeza esta investigación.\n\nSi la cosa te interesa, habla con él directamente. Lo encontrarás en el Enclave Cenarion, en Darnassus.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10521] = {title = "Grom'tor, hijo de Oronok", objective = "Encuentra a Grom'tor, hijo de Oronok, en el Alto Cicatriz Espiral del Valle Sombraluna.", description = "Mi primogénito, Grom'tor, se marchó para registrar el Alto Cicatriz Espiral, justo al suroeste..\n\nEs el guerrero de la familia, de muy mal carácter y sediento de sangre... Rasgos que ha heredado de su madre. Busca por las afueras del Alto Cicatriz Espiral. Si ves cadáveres de nagas, seguro que Grom'tor no andará lejos.\n\nCuando lo encuentres, dile lo siguiente: \"Derramamos sangre por una causa justa.\" Así sabrá que eres amigo de Corazón Roto y evitaremos tu muerte prematura.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10522] = {title = "La Clave de Condenación: La carga de Grom'tor", objective = "Grom'tor, hijo de Oronok, en el Alto Cicatriz Espiral del Valle Sombraluna, quiere que recuperes el primer fragmento de la Clave de Condenación.", description = "Esta escoria naga es el sexto al que interrogo hoy. Lleva una armadura especial, así que pensé que sabría algo. Los demás eran unos inútiles.\n\n<Grom'tor señala los cadáveres nagas a su alrededor.>\n\nSolo tuve que pegarle una vez y cantó como un ruiseñor.\n\nLa primera parte de la clave está oculta en un cofre naga en el Alto Cicatriz Espiral o en la Cisterna Cicatriz Espiral, al este. Dice que los nagas llevan las llaves. Mátalos, quítales las llaves y úsalas para abrir los cofres de la Cicatriz Espiral. Vuelve junto a mí cuando hayas encontrado la clave.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10523] = {title = "La Clave de Condenación - Primer trozo recuperado", objective = "Lleva la caja fuerte de Grom'tor a Oronok Corazón Roto en la Granja de Oronok, en el Valle Sombraluna.", description = "<Grom'tor coge los documentos y los mete en una caja fuerte.>\n\nLleva esta caja a padre. Te espera en la granja, al noreste de aquí.\n\nDile que pronto estaré en casa. En cuanto haya terminado la diversión...Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Vendas ensangrentadas de Grom'torGuerrera del primo del amigo de Grom'torBrazales viejos de OronokPodrás elegir una de estas recompensas:\n\nColgante de conquista de Grom'tor\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][10524] = {title = "Artefactos del clan Señor del Trueno", objective = "Recupera el tambor del clan Señor del Trueno, la flecha del clan Señor del Trueno, y la tablilla del clan Señor del Trueno.", description = "El artefacto tiene marcas que indican sus orígenes como creado por el clan de orcos del Señor del Trueno. Estos orcos solían vivir en Bastión Señor del Trueno antes de convertirse en orcos viles.\n\nDurante algún tiempo, los ogros Aguja del Filo habitaron el bastión hasta hace poco, cuando la Horda los expulsó.\n\nHas oído hablar de otros artefactos que se perdieron. Un tambor, una flecha y una tablilla vienen a la mente como objetos que sabes que se buscan.\n\nEncuéntralos en el Bastión Aguja del Filo y devuélveselos a Rokgar Agarre Sangriento.", progress = "¿Nos conocemos?", completion = "¡No me creo lo que ven mis ojos! ¡Si es algún tipo de truco, te arrancaré la carne de los huesos, &lt;clase&gt;!\n\nRápido, déjame examinar estos artefactos de valor incalculable antes de que las rompas con tus torpes manos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10527] = {title = "Ar'tor, hijo de Oronok", objective = "Encuentra a Ar'tor, hijo de Oronok, en el Alto Illidari del Valle Sombraluna.", description = "El menor de mis hijos, Ar'tor, se marchó para realizar una búsqueda en el Alto Illidari, un lugar remoto al suroeste, ubicado entre el Bastión de la Legión y el Bastión Martillo Salvaje.\n\nAunque Ar'tor es un gran cazador de extraordinaria habilidad y un experto rastreador, me temo que esta vez pueda estar en un aprieto. El Alto Illidari es el terreno de pruebas de los demonios de Illidan. ¡Estos son demonios que abandonaron la Legión Ardiente para unirse al traidor!\n\nVe al Alto Illidari y encuentra a Ar'tor, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10528] = {title = "Cárceles de cristal demoníacas", objective = "Busca a la maestra del dolor Gabrissa en el Alto Illidari, mátala y vuelve junto al cadáver de Ar'tor, hijo de Oronok, con la llave cristalina.", description = "Tras examinar el lugar, te das cuenta de que Ar'tor está sujeto por rayos de energía de los cristales que sobrevuelan la runa. Aunque lo intentes con todas tus fuerzas, no hay forma de mover a Ar'tor.\n\nTe fijas en una ranura en la base de los cristales, quizás sea para una llave. También parece que las súcubos realicen algún tipo de ritual en este lugar de forma habitual.\n\nBusca a su líder en el Alto Illidari. Quizás ella tenga la llave para liberar a Ar'tor.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10531] = {title = "La batalla por la Cuenca de Arathi", objective = "Asalta la mina, el aserradero, la herrería y la granja y vuelve entonces junto al mariscal de campo Uluz en el Refugio de la Zaga.", description = "<nombre>, la batalla por la Cuenca de Arathi se libra por los recursos y el territorio. Hay que mantener y dirigir los puntos clave de esa región para que nuestras fuerzas tengan asegurado el suministro de materias primas. Te encargo que asaltes los puntos más alejados de nuestra base en la Cuenca de Arathi.\n\nAsalta la granja, la mina, el aserradero y la herrería cuando estén en poder del enemigo. Encuentra el estandarte enemigo ¡y arráncalo del poste donde ondee!\n\nCuando lo hayas hecho en las cuatro posiciones vuelve aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10532] = {title = "Córtale el suministro a la Liga de Arathor", objective = "Llévate la victoria en la batalla por la Cuenca de Arathi, consigue una caja de suministros de Arathi y llévasela a Mortacechador Mortis en Sentencia.", description = "La Liga de Arathor no repara en gastos en su avance para recuperar Arathi. Ellos, y todas las razas de la Alianza, se dirigen ahora hacia esa distante región con la intención de extender su dominio desde el Refugio de la Zaga. Debemos detenerlos y la mejor manera es arrebatarles los suministros.\n\nPuedes ayudarnos, <nombre>. Adéntrate en la Cuenca de Arathi, famosa por sus abundantes minas, fértiles tierras y los más finos artesanos. Captura y hazte con el control de todas las bases que puedas, gana la batalla y vuelve con los recursos que hayas obtenido.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][10535] = {title = "Los recursos de la Cuenca de Arathi", objective = "Llévate la victoria en la batalla por la Cuenca de Arathi, consigue una caja de suministros de Arathi y llévasela al sargento Maclear en el Refugio de la Zaga.", description = "Hacen falta soldados para combatir en una guerra, cualquier soldado te lo dirá. También dicen que una guerra librada con equipamiento en malas condiciones o con el estómago vacío ¡está perdida antes de empezar!\n\nPor eso la Cuenca de Arathi es importante. Hay zonas clave en la cuenca donde se encuentran recursos esenciales. Metales, armas, comida, madera... todo lo que necesitamos, y todo se puede conseguir allí.\n\nEso es lo que quiero de ti, <nombre>. Adéntrate en la Cuenca de Arathi, consigue la victoria tomando posesión de más bases que el enemigo y vuelve aquí con una caja de recursos.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][10537] = {title = "Lohn'goron, arco del corazón roto", objective = "El espíritu de Ar'tor en el Alto Illidari, en el Valle Sombraluna, quiere que recuperes Lohn'goron, arco del corazón roto. Lo tiene un demonio de la zona.", description = "Es una señal, <nombre>. Incluso muerto soy imparable. Mi destino es recuperar una parte de la Clave de Condenación. Con tu ayuda, podré cumplir mi destino.\n\nAntes de embarcarnos en ese viaje, debo recuperar mi arco, Lohn'goron. Es una reliquia familiar que ha pasado de generación en generación de hombres Corazón roto.\n\nMi instinto me dice que un demonio lo robó de mi cadáver. Mata a los demonios hasta que encuentres mi arco.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10538] = {title = "Sangre en ebullición", objective = "Vierte la sangre de Foso Sangrante en su caldera maldita para obtener sangre hervida. Lleva 12 muestras de sangre hervida al boticario Albreck en la Avanzada Rompeloma.", description = "El último experimento no fue un fracaso absoluto. Tengo un poco de la sangre que me trajiste guardada. Ahora, hervida debería estar libre de la maldición que las brujas de Foso Sangrante vertieron en la sangre de su gente.\n\nNecesito más para estudiarla. Vete y consigue sangre de Foso Sangrante de los orcos de Zeth'Gor. Cuando la tengas, viértela en el interior de su caldera maldita y hiérvela. Tráeme la sangre hervida.", progress = "¿Tienes la sangre hervida, <nombre>? Qué ganas tengo de estudiarla sin interrupciones esta vez...", completion = "Muy bien. Ahora podré realizar mis pruebas con más facilidad...\n\nGracias, &lt;nombre&gt;. Tienes mucho talento.", rewards = "Recibirás:\n\nObjeto #12"}
MultiLanguageQuestData['mx'][10540] = {title = "La Clave de Condenación. La carga de Ar'tor", objective = "El espíritu de Ar'tor en el Alto Illidari, en el Valle Sombraluna, quiere que consigas el segundo fragmento de la Clave de Condenación que tiene Veneratus el Múltiple.\n\nLas criaturas que ataque o dañe el espíritu cazador no proporcionan botín ni experiencia.", description = "Por fin estamos listos. Te entregaré una parte de mi espíritu, <héroe/heroína>. Te protegerá y te ayudará en la batalla contra el mal.\n\nDespués tendrás que viajar al sur, hacia la parte trasera del Alto Illidari. En el éter, oculta, hay una malvada criatura conocida como Veneratus el Múltiple. El espíritu cazador le llamará cuando esté cerca.\n\nDestruye a Veneratus y coge de su cadáver la segunda parte de la Clave de Condenación.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10542] = {title = "Mi pipaaa me la robaaaron...", objective = "Recupera la pipa de agua de T'chali y 10 cervezas Machacasangre aterrabrutos.", description = "T'chali solía ser un trol simpático. Mí venir aquí para enseñar a los Machacasangre a fabricar su cerveza. Pero cuando mí hacer eso, ¡los Machacasangre enterrar T'chali y dejar él pudrirse!\n\n¡Lo peor es que ellos robaron a mí la pipa de agua!\n\nAsí que, ¿tú ayudar T'chali? Tú traer a mí la pipa de agua. T'chali pensar los ogros ladrones ir suroeste junto a la mina.\n\nY mientras tú allí, ¡también traer unas cervezas!", progress = "Hola, ¿tienes ya mi pipa de agua y esas cervezas?", completion = "Sí, ¡a eso se refiere T'chali! Aunque mí no estar seguro de lo que esos ogros poner ahí dentro; olor en la pipa de agua no ser marca de tabaco de T'chali.\n\nDa igual, T'chali es feliz. Tan feliz y contento como para pedirte una cosa más.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10546] = {title = "Borak, hijo de Oronok", objective = "Encuentra a Borak, hijo de Oronok, cerca de Punta Eclipse, en el Valle Sombraluna.", description = "Mientras Ar'tor salía a cazar y Grom'tor salía a luchar, Borak estudiaba. Al final, sintió su vocación como erudito y partió hacia Draenor. Volvió a casa hace unos años como si fuera un orco completamente diferente.\n\nSu elevado sentido de la percepción y su agudeza mental habían hecho de él un asesino silencioso.\n\nAhora es un orco con confianza en sí mismo y muy poderoso y ha decidido conseguir la pieza más protegida de la clave.\n\nEncuentra a Borak, está escondido cerca de Punta Eclipse, hacia el sur. Vigila desde las sombras del puente.", progress = nil, completion = "&lt;Borak se queda en silencio durante un momento.&gt;\n\nLlevo semanas observando a estos elfos de sangre, intentando descubrir dónde han escondido la tercera parte de la Clave de Condenación.\n\nHasta ahora, no he tenido éxito. Lo único que sé es que Illidan manda a un enviado desde el Templo Oscuro una vez al día.\n\nEste enviado es intocable. Le he seguido durante una semana intentando descubrir cómo separarle de su guardaespaldas. Por desgracia, el guardaespaldas nunca le deja solo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10547] = {title = "Sobre cabezacardos y huevos...", objective = "Borak, hijo de Oronok en el puente al norte de Punta Eclipse, quiere que encuentres un huevo de arakkoa podrido y se lo lleves a Tobias el Comeporquería en la Ciudad de Shattrath, al noroeste del Bosque de Terokkar.", description = "Lo peor es que no me había dado ni cuenta... es un cabezacardo. Al principio no podía saberlo, pero todas las señales estaban ahí...\n\nSi pudiéramos conseguir algo de cardo de sangre, podríamos hacer algo.\n\nEn mis viajes, conocí a un Tábido sombrío en Shattrath llamado Tobias.\n\nTobias creó un negocio comerciando cardo de sangre con los elfos de sangre a cambio de huevos de arakkoa podridos.\n\nDirectamente al oeste de aquí están las ruinas de los arakkoa. Búscalos para que te den un huevo y dirígete al Bajo Arrabal de Shattrath. Allí encontrarás a Tobias.", progress = "<Tobias eleva una ceja.>\n\n¿Cardo de sangre? Nuna había oído hablar de eso... ¿Eres un pacifista? Sabes que deberías decírmelo si lo fueses... ¡Tengo mis derechos!", completion = "¿Tienes un huevo de arakkoa podrido? ¿Y por qué no me lo has dicho antes? Creo que podemos hacer negocios.\n\n&lt;Tobias sonríe, dejando a la vista una dentadura podrida y muy sucia.&gt;", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10551] = {title = "Lealtad hacia los Aldor", objective = "¿Tienes clara tu decisión, <nombre>? Los Aldor te darán la bienvenida como aliado, pero los Arúspices no olvidarán fácilmente tu elección.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][10552] = {title = "Lealtad a los Arúspices", objective = "¿Tienes clara tu elección, <nombre>? Los Arúspices te darán la bienvenida como aliado, pero los Aldor no olvidarán fácilmente tu decisión.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][10553] = {title = "Voren'thal el vidente", objective = "Habla con Voren'thal el Vidente dentro de la Biblioteca del Profeta, en la Grada del Arúspice de la Ciudad de Shattrath.\n\nLlevar a cabo misiones para los Arúspices hará que tu nivel de reputación Aldor disminuya.", description = "Ahora que has escogido un bando, <nombre>, deberías reunirte con el líder de los Arúspices.\n\nEncontrarás a Voren'thal el Profeta dentro de la Biblioteca del Profeta, en la Grada del Arúspice.\n\nMira a ver si puedes serle de ayuda. Se alegrará de oír que has decidido echarle una mano.", progress = nil, completion = "¿Khadgar envía un nuevo recluta? Te vamos a poner a trabajar, &lt;clase&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10554] = {title = "Ishanah", objective = "Habla con Ishanah dentro del Santuario de Luz Inagotable, en Alto Aldor, de la Ciudad de Shattrath.\n\nCompletar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices.", description = "Ahora que has decidido ponerte del lado de los Aldor, harías bien en presentarte ante su líder. Encontrarás a la Suma Sacerdotisa Ishanah dentro del Santuario de Luz Inagotable.", progress = nil, completion = "Bienvenido, &lt;nombre&gt;. Me alegro de oír que has decidido unirte a nosotros en nuestra misión. Que la Luz siempre te proteja.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10555] = {title = "Malestar", objective = "Reúne 18 plumas de Lashh'an arrancadas.", description = "La magia que los arakkoa Lashh'an practican es sobrenatural. ¡Se arrancan las propias plumas, a puñados ¿o debería decir garras?, como componentes!\n\nEso no me suena a buena magia. He venido aquí para aprender más cosas sobre sus hechizos pero, por desgracia, acercarme es demasiado para mí.\n\nTú podrías conseguirlo: lánzate a ti mismo uno de sus hechizos y regresa junto a mí. Tendrás que encontrar uno de sus libros de hechizos, en lo alto de los árboles de Velo Lashh.\n\nY a menos que te hayan salido plumas que no veo, tendrás que conseguir algunas de esas.\n", progress = "Por los rudimentarios pictogramas de las páginas del libro envejecido, deduces que se necesitarán muchas plumas Lashh'an para lanzar los hechizos ahí descritos.", completion = "Hojeando las páginas con notas garabateadas y alargada escritura de los arakkoa Lashh'an, encuentras una página con un pictograma de los círculos de poder que has visto en Velo Lashh.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10556] = {title = "Arañazos", objective = "Usa el manojo de plumas en el círculo de hechizos de Lashh'an.", description = "Los pictogramas indican el uso de plumas para lanzar el hechizo a uno de los círculos de poder de Velo Lashh.\n\nUna iconografía confusa parece mostrar a un arakkoa bañado por el espíritu de un kaliri.", progress = "¡Esto es emocionante! No puedo esperar a estudiar el funcionamiento del hechizo.", completion = "No sé qué decir. Este hechizo es muy extraño. No es un simple conjuro o encantamiento, sino algún tipo de hechizo de comunión o comunicación.\n\nNo sé con seguridad qué pensar, &lt;nombre&gt;. Tendré que pensar en ello algo más de tiempo.\n\n¡Pero gracias por tu ayuda de todos modos! Seguro que lo resolveré tarde o temprano.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10557] = {title = "Vuelo de prueba: el Cefirium Capacitorium", objective = "Habla con Rally Pillazas para usar el Cefirium Capacitorium.", description = "Recientemente construí un dispositivo increíble, el Cefirium Capacitorium, y, aunque seguro que funcionará perfectamente... ¿quieres ayudarme a probarlo?\n\n¡Hay varias bonificaciones por peligrosidad!\n\nSi quieres, habla con mi gemelo, Rally. Ah, y buena suerte, <nombre>. Vuelve después del experimento... Y si eso no es posible porque has sufrido un accidente, puede venir tu pariente más próximo para recoger tu paga.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10562] = {title = "¡Asediados!", objective = "El comandante del aire Nuainn, fuera del Bastión Martillo Salvaje, quiere que mates a diez agresores infernales.", description = "No bajes la guardia, <raza>. Estamos bajo ataques constantes de la Legión Ardiente.\n\nDesde su base del Bastión de la Legión, al noroeste, los demonios lanzan una lluvia incesante de infernales. En cuanto los matamos, impactan los nuevos meteoros y comienza una nueva ola de ataques.\n\nMis hombres están harapientos y exhaustos. No sé cuánto más resistirán. Por favor, <nombre>, presta tu ayuda a nuestras defensas. ¡Ocupa tu lugar en las filas y detén el avance de los infernales!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10563] = {title = "Al Bastión de la Legión", objective = "Ponte en camino hacia el Bastión de la Legión y ubica el aparato de comunicación de la Legión. Cuando estés cerca del aparato, usa tu disfraz y averigua los planes de la Legión. Vuelve con el comandante del aire Nuainn al Bastión Martillo Salvaje cuando hayas completado tu misión.", description = "La fortaleza del Bastión de la Legión es casi impenetrable y, para ser sincero, no puedo prescindir de las tropas para un ataque. Nuestras esperanzas están puestas en ti, <nombre>.\n\nLa poca información que hemos podido reunir indica que la Legión tiene y prepara a sus infernales en el bastión. Con la ayuda de un disfraz que te proporcionaré, debes entrar en el Bastión de la Legión y averiguar sus planes. Tu mejor esperanza es interceptar u oír por casualidad comunicaciones entre sus comandantes. Buena suerte, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10565] = {title = "Las piedras de Vekh'nir", objective = "Recoge y usa un cristal Vekh'nir del círculo de hechizos de los Vekh'nir para crear un cristal Vekh'nir cargado.", description = "Los arakkoa de Vekh'nir llevan muchos años siendo una espina que tenemos clavada. Los guía alguna extraña religión, una religión que mantiene a los arakkoa en un frenesí de actividad. Ahora llevan unos cristales consigo, que han cambiado con algún oscuro propósito.\n\nSé algunas cosas de sus rituales. Llevan los cristales a sus círculos de hechizos para imbuirlos. A la gente del pueblo nos gustaría saber más. Aborda a unos cuantos de los arakkoa hasta que encuentres un cristal, cárgalo y tráemelo de vuelta.", progress = "Los arakkoa Vekh'nir han sido benignos durante muchos años, pero ahora, algo los ha agitado.", completion = "¡Ah, mira cómo brilla! Debo probarlo de inmediato.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][10567] = {title = "Crear el colgante", objective = "Busca 6 garras de Ruuan'ok y úsalas para invocar a un presagista del Cuervo en el Círculo del Oráculo Ruuan'ok. Mátalo y obtén su colgante de presagista.", description = "Los arakkoa de la Foresta Ruuan veneran sobre los demás a los Heraldos del Cuervo, ministros de su dios.\n\nCreen que los Heraldos los vigilan desde el cielo, donde reciben las enseñanzas del Cuervo y descienden para transmitir su palabra.\n\nLos Heraldos tienen una gran influencia sobre las almas de los arakkoa. Usan colgantes mágicos que necesitamos.\n\nAtrae a uno de los Heraldos matando a sus súbditos y cogiendo sus garras. Coloca las garras en el altar para llamar su atención.", progress = "En cuanto el presagista perciba tu ataque, responderá rápidamente.", completion = "¡Lo tienes!\n\nCon este colgante, podré acercarte a los arakkoa de Grishnath tanto que hasta podrás entender su idioma.\n\nCon esto, comprenderemos mejor a los arakkoa y la naturaleza del Cuervo. Voy a necesitar tu ayuda.", rewards = "Recibirás:\n\nObjeto #6"}
MultiLanguageQuestData['mx'][10568] = {title = "Las tablillas de Baa'ri", objective = "La anacoreta Ceyla del Altar de Sha'tar quiere que recojas 12 tablillas Baa'ri del suelo y de los trabajadores Lengua de ceniza en las Ruinas de Baa'ri.\n\nCompletar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices.", description = "Hace años, el temido brujo Gul'dan provocó el volcán del medio de Sombraluna. La aldea draenei de Baa'ri, al suroeste, quedó sepultada bajo la lava junto con sus habitantes y artefactos religiosos importantes.\n\nUna traicionera tribu de Tábidos, los Lengua de ceniza, tienen órdenes de Illidan de excavar en la zona. Tenemos que aprovechar esta oportunidad para recuperar las Tablillas de Baa'ri, un antiguo texto que dicen que contiene secretos del templo de Karabor, conocido como el Templo Oscuro.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10569] = {title = "Las Ruinas de Sketh'lon", objective = "Recupera las páginas 1, 2 y 3 del diario del comandante Skethlon del cónclave oscuro arakkoa en las Ruinas de Sketh'lon y entrégaselas al jinete de grifo Kieran.", description = "Nuestros exploradores nos traen informes preocupantes de los campamentos arakkoa en ruinas de la zona.\n\nLos fantasmas de poderosos magos arakkoa tienen poderes que no sospechábamos. Parece que se están organizando, como si se estuvieran preparando para algo, pero nos falta información. No podemos seguir a oscuras.\n\nVe hacia el norte hasta las Ruinas de Sketh'lon, al noroeste de La Forja Muerta y busca más información sobre sus intenciones.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10573] = {title = "La Forja Muerta", objective = "Preséntate al agitador Ewan Alasalvaje en la Torre de La Forja Muerta.", description = "Gracias a tus hallazgos en el Bastión de la Legión, sabemos que el Consejo de la Sombra, aliado de la Legión, está produciendo infernales en La Forja Muerta. He enviado un grupo reducido de exploradores para vigilar el área pero no pueden encargarse de todo lo que necesitamos.\n\nSi dejamos que La Forja Muerta siga en funcionamiento, volverán a producir las reservas de infernales que destruiste en el Bastión de la Legión.\n\nQuiero que te reúnas con el agitador Ewan Alasalvaje. Lo encontrarás en la Torre de La Forja Muerta, justo al sur de la propia forja..Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10578] = {title = "La Clave de Condenación: La carga de Borak", objective = "Borak, hijo de Oronok, en el puente próximo a la Punta Eclipse en el Valle Sombraluna, quiere que recuperes la tercera parte de la Clave de Condenación de Ruul el Ensombrecedor.\n\nPara esta misión hará falta un grupo.", description = "Ese fragmento del código nunca le llegará a Zuluhed. Vas a tenderle una emboscada a Ruul el Ensombrecedor antes de que pueda entregarlo.\n\nLa Fortaleza Faucedraco está directamente al este, pasados los Campos del Ala Abisal. En algún lugar entre la Fortaleza Faucedraco y el Sagrario de las Estrellas encontrarás a Ruul. ¡Ataca sin piedad y rápido! Ah, <nombre>, yo diría que no va a ser fácil enfrentarse a Ruul. No bajes la guardia.\n\nTráeme el código cuando lo hayas recuperado.\n", progress = "¡Debes actuar sin perder un minuto!", completion = "¡Por fin! ¡El fragmento del código es nuestro!\n\n&lt;Borak coloca el fragmento en una caja.&gt;", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10579] = {title = "La Clave de Condenación: Tercer trozo recuperado", objective = "Lleva la caja fuerte de Borak a Oronok Corazón Roto en la Granja de Oronok, en el Valle Sombraluna.", description = "Llévale esta caja a mi padre. Todavía vive en la Granja de Oronok, muy lejos hacia el norte, más allá de la Cisterna Cicatriz Espiral. Cuando se unen los 3 fragmentos, las antiguas palabras se conocerán de nuevo.\n\nSuerte, <nombre>. Dile a mi padre que pronto volveré a casa.", progress = "¡<nombre>!", completion = "En cuanto los 3 fragmentos de la clave se junten, se conocerán las antiguas palabras.\n\nRecuperar este fragmento ha tenido que ser todo un reto. Mereces una recompensa por semejante heroísmo.", rewards = "Bufas del corazón rotoBotas de pellejo de jabalí vilCollera de UmbraullidoPilares de Ar'torCinturón bizarro de BorakLas manos del destinoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10580] = {title = "¿Dónde se han metido esos malditos gnomos?", objective = "Busca hacia el sur de la Cresta Dentada, en las Montañas Filospada, alguna pista sobre el paradero de Toshley y los demás gnomos.", description = "A pesar del bien que hemos hecho aquí, me siento mal por una cosa: haber echado a Toshley y a sus amigos gnomos.\n\nNo teníamos elección; estaban retrasando nuestro trabajo en la arboleda con toda su tecnología y experimentos.\n\nTe lo agradecería si averiguas qué ha sido de ellos. Lo último que hemos oído es que se dirigían al este después de cruzar el puente. Seguro que tuvieron que encaminarse al sur, lejos del Bastión Señor del Trueno.\n\nBusca alguna pista sobre su paradero en la parte sur de la Cresta Dentada.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10581] = {title = "Sigue el rastro", objective = "Sigue el rastro de piezas sueltas por la rampa que conduce a Loma Tajo. Habla con Toshley en la Estación de Toshley, en las Montañas Filospada.", description = "BIEN, POR LA PRESENTE TE AVISO DE QUE NO ENCONTRARÁS NADA EN LA CRESTA.\n\n¡NO SIGAS EL RASTRO DE PIEZAS QUE LLEVAN A LA ESTACIÓN DE TOSHLEY! NO ENCONTRARÁS A TOSHLEY, NI A NINGÚN OTRO GNOMO ALLÍ.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10583] = {title = "El destino de Flanis", objective = "El agitador Ewan Alasalvaje, en la Torre de La Forja Muerta, quiere que busques en La Forja Muerta a Flanis Alapresta y recuperes su talega.", description = "Éramos tres en el grupo enviado por el comandante del aire Nuainn para vigilar La Forja Muerta y para recabar información. Flanis Alapresta se ofreció voluntario para infiltrarse en La Forja Muerta pero no hemos sabido nada de él desde hace varios días.\n\nMe temo lo peor, <nombre>. Flanis es un explorador hábil pero si está metido en un aprieto, no hay forma de saberlo. Búscalo por toda La Forja Muerta y recupera cualquier información u objetos que pueda haber conseguido.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10584] = {title = "Recoger transformadores de energía", objective = "Usa el acumulador magnético protovoltaico para reunir 5 electromentales.", description = "Esos ogros idiotas de la Avanzada Aguja del Filo, hacia el norte, han robado nuestros convertidores de energía. ¡Y tú vas a devolvérmelos! O eso espero...\n\nSin duda, con esas manos tan patosas que tienen, los ogros han dañado los transformadores. Así que, lo que quiero que hagas es utilizar este acumulador magnético protovoltaico en el electromental resultante para guardarlo.\n\nSeguro que te hace daño, así que tendrás que 'matarlo' mientras está en la esfera magnética.", progress = "¡Esta línea de investigación que seguimos con los electromentales es interesantísima! Imagínate... criaturas eléctricas inteligentes que podemos crear a nuestro antojo ¡y que obedecerán todas nuestras órdenes!\n\n¿Qué podría salir mal?", completion = "¡Excelente! Con todo este poder que has recuperado podremos mantener la maquinaria funcionando una temporada.\n\n¡El Cefirium Capacitorium es una auténtica ruina en cuanto al consumo!\n\nEspero que no fuera demasiado difícil ocuparte de esos electromentales. Estoy pensando en otra cosa de la que podrías encargarte y me parece que podría ser un poco más peligroso.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10585] = {title = "La cámara de invocación", objective = "Consigue 1 desplazador elemental de un herrero Forja Muerta o de un manitas Forja Muerta, y úsalo para perturbar el ritual de la cámara de invocación. Preséntate al agitador Ewan Alasalvaje en la Torre de La Forja Muerta cuando hayas completado la tarea.", description = "Para que el Consejo de la Sombra fabrique infernales tan rápidamente como están acostumbrados, deben de tener un área dedicada a invocar elementales corruptos que sirven de alma de las criaturas.\n\nLa cámara de invocación es probablemente subterránea, cerca de un charco de lava o agua podrida. Localiza la cámara de invocación en La Forja Muerta y encuentra la forma de acabar con sus rituales de invocación. Es posible que el Mo'arg implicado en la fabricación de infernales lleve una herramienta que contribuya a afectar la magia del invocador.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10587] = {title = "Patio de Armas de Karabor", objective = "La exarca Onaala del Altar de Sha'tar quiere que consigas 8 gujas de Furia del Sol de los suplicantes cazademonios y de los iniciados cazademonios que se encuentran en las Ruinas de Karabor, al sureste del Altar de Sha'tar.\n\nCompletar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices.", description = "Según informan nuestros exploradores, hay un enorme contingente de elfos de sangre Furia del Sol que se dirige a las Ruinas de Karabor. En circunstancias normales esto representaría una amenaza meramente militar, pero creemos que hay algo más.\n\nLa descripción de sus ropajes y estilo de combate se parece sospechosamente a los del mismísimo Illidan. No quiero que cunda el pánico si no hay una sólida razón para ello, así que me gustaría que fueras allí y me trajeras varias de sus armas. Concluiremos entonces si mis temores son fundados o no.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10588] = {title = "La Clave de Condenación", objective = "Usa la Clave de Condenación en El Altar de Condenación para invocar a Cyrukh el señor del Fuego.\n\nDestruye a Cyrukh el señor del Fuego y habla con el ensalmador de la tierra Torlok, que también se encuentra en El Altar de Condenación.", description = "¿Cuántas veces se habrá usado este hechizo en la historia de nuestros mundos? Sin duda, su poder de destrucción no tiene parangón.\n\nLo que debes hacer ahora es llevarte la clave, ahora recompuesta, y leerla en El Altar de Condenación, donde se encuentra el recuerdo de Gul'dan.\n\nLo que verás cuando pronuncies las palabras son los recuerdos grabados en la tierra. Mantente firme y espera la llegada de Cyrukh.\n\nDebes lograrlo, <nombre>. Esta tierra no podrá soportar otro desastre.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Cetro antiguo de OronokBastón del redentorHacha de batalla del corazón rotoCarga de Grom'torLohn'goron, arco del corazón rotoRecordatorio de BorakRecibirás:\n\nAmuleto del corazón roto"}
MultiLanguageQuestData['mx'][10590] = {title = "Demuestra tu odio", objective = "Mehlar Hojalba en El Baluarte quiere que le lleves 20 piedras de la Plaga de los esbirros.", description = "Ya era hora de que recordases la historia que no debe ser olvidada... la matanza de nuestra gente a manos de Arthas y su ejército de la Plaga.\n\nLa única forma de calmar tu dolor será vengarse de la Plaga. Por desgracia, ellos no sienten miedo ni dolor. Solo su completa destrucción te proporcionará una mínima satisfacción.\n\nHabla con el oficial Argenta Garush para que te informe sobre las piedras de la Plaga y cómo obtenerlas. Tendré que ver muchas como prueba de tu lealtad antes de que volvamos a hablar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10592] = {title = "La sabiduría de la reina alma en pena", objective = "Llévale los fragmentos de piedra de la Plaga a Lady Sylvanas Brisaveloz en Entrañas.", description = "Las piedras de la Plaga son débiles cuando se separan del esqueleto que las contenía. Simplemente al recogerlas en las manos se rompen.\n\n<Mehlar aplasta la piedra de la Plaga y la convierte en un montón de escombros.>\n\nLleva estos trozos a la Reina alma en pena, Lady Sylvanas Brisaveloz, a Entrañas. Ella tiene el conocimiento para convertir estos escombros en un arma contra la Plaga.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10593] = {title = "Mal ancestral", objective = "Descubre los secretos de El Templo de Atal'Hakkar para soltar a Atal'alarion y recuperar la vid pútrida de su carne. Vuelve a ver a Mehlar en El Baluarte cuando lo hayas hecho.", description = "Si quieres convertir estas piedras en un arma para luchar contra la Plaga debes adquirir algo igualmente maligno para fortificarlas.\n\nUn mal ancestral yace oculto en el fondo del Templo de Atal'Hakkar en el Pantano de las Penas. Suelta a la criatura que está allí y mátala. Lleva una pequeña parte de su cuerpo a Mehlar Hojalba. Mis guardias entregarán los fragmentos de la piedra de la Plaga a Mehlar.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFiniquiplaga"}
MultiLanguageQuestData['mx'][10594] = {title = "Medir la frecuencia resonante", objective = "Coloca los escáneres de frecuencia oscilante de tal forma que cuando estés de pie en medio de los mismos, te alcancen 5 campos de oscilación superpuestos.", description = "Llévate estos escáneres a la Cresta Canto. Allí déjalos en el suelo formando un patrón, así crearás campos que se superpondrán y que leerán la amplitud de los cristales, pero solo si mientras estás de pie en medio de los mismos, tus campos de oscilación llegan a cinco.\n\nTus escáneres funcionarán incluso con los que otros dejan caer.\n\n¡Ah, y es probable que se forme una grieta! No tengo ni idea de qué puede salir de ella, pero prepárate para lo peor.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Piernas adelgazantes de MetroArnés experimental de NicopicoSombrero de fiesta fallidoCinturón \"a la moda\" del año pasadoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10595] = {title = "¡Asediados!", objective = "El Guardia de sangre Gulmok, de las afueras de la Aldea Sombraluna, quiere que mates a 10 agresores infernales.", description = "<Gulmok eleva la mirada al cielo.>\n\nNuestros exploradores están luchando con uñas y dientes ¡pero no dejan de aparecer infernales!\n\nDesde su base del Bastión de la Legión al suroeste, ¡los demonios nos bombardean con total impunidad! Ni siquiera el guardia de Élite Kor'kron podrá plantarles cara para siempre.\n\nEstoy trayéndome a todo soldado apto para el combate, <raza>, para que contribuyan a la defensa de la Aldea Sombraluna. Esto va muy en serio, <clase>. Nos jugamos la supervivencia de la aldea. ¡Cumple con tu deber para con la Horda y únete a la lucha!", progress = nil, completion = "Estoy impresionado de que hayas logrado sobrevivir a la masacre. Puede que seas exactamente la persona que necesitaremos para una peligrosa misión.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10596] = {title = "Al Bastión de la Legión", objective = "Encamínate al Bastión de la Legión, encuentra el aparato de comunicación de la Legión y averigua los planes de la Legión mientras estés <disfrazado/disfrazada>. Regresa junto al Guardia de sangre Gulmok en la Aldea Sombraluna cuando hayas completado la misión.", description = "Tu objetivo es la fortaleza del Bastión de la Legión. No tendrás refuerzos, así que un ataque frontal es imposible.\n\nLa poca información que tenemos indica que la Legión almacena y prepara sus infernales en el bastión. Con la ayuda de un disfraz que te daré, debes entrar en el Bastión de la Legión y descubrir sus planes.\n\nTu mejor estrategia es interceptar o escuchar las comunicaciones entre sus comandantes.", progress = "¿Qué has descubierto?", completion = "&lt;El Guardia de sangre Gulmok escucha tu informe, el semblante cada vez más preocupado.&gt;\n\n¿A qué te refieres con que van a intensificar el bombardeo? No podemos permitir que eso ocurra. ¡Vuelve allí y ocúpate de eso mientras queda algo de la Aldea Sombraluna!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10606] = {title = "El Arte del Cuidado de los Atracadores Viles", objective = "Mata al doctor Gutrick y consigue su llave. Usa la llave para abrir la caja fuerte del doctor para recuperar El Arte del Cuidado de los Atracadores Viles y llévale este libro a Plexi en el Punto de invasión: Cataclismo.", description = "La mejor forma de destruir el resto de los suministros de la Legión es usar sus propias armas contra ellos. He estado trabajando en un aparejo que te permitirá controlar uno de esos atracadores viles centinelas de abajo.\n\nHay un par de cosas que aún debo mejorar. Para lograrlo, necesitaré el manual que el Doctor Gutrick guarda bajo llave en un arcón en la parte de abajo de la rampa. Dudo que te dé la llave sin luchar, así que tendrás que quitársela. ¡Tráeme el manual de atracadores viles y yo me ocuparé del resto!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10607] = {title = "Susurros del Dios Cuervo", objective = "Mata al arakkoa Grishna para poder entender la palabra del Cuervo durante 2 minutos. Mientras estés bajo los efectos del hechizo, podrás encontrar y recibir la profecía de los cuatro santuarios.", description = "En Grishnath, gracias a los tótems que los oráculos del Cuervo dejaron, los arakkoa oyen la palabra del Cuervo. Por desgracia, para nosotros el idioma de los arakkoa es indescifrable.\n\nSi usamos el colgante del heraldo, lo comprendemos. Podrás tomar las almas de los arakkoa para entender su idioma. Mientras estés impregnado del espíritu de los arakkoa, puedes visitar los tótems y entender su mensaje.\n\nDescúbrelo para nosotros, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Ataduras de tela de ánimaBotas de cuero flexibleBufas diluvianasGuanteletes nudillo blancoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10608] = {title = "Limpieza de despellajadores", objective = "Mata a 10 despellejadores de cristal.", description = "¡Los malditos despellejadores de roca me mantienen apartado de mi investigación en la Cresta Canto! Al excavar los cristales que allí se encuentran, con cada arañazo echan por tierra mis posibilidades de estudiar las armonías de los cristales canto.\n\nTienes aspecto de alguien que me puede ayudar a resolver el problema. Ve al sur y liquida a esos despellejadores de cristal.", progress = nil, completion = "¡Adiós y buen viaje! Eso digo yo. ¡Qué asco de criaturas!\n\nBien, si estás seguro de que has eliminado a esa peste, entonces tengo otro proyectito de investigación para ti. Creo que te gustará.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10609] = {title = "¿Qué fue primero? ¿El draco o el huevo?", objective = "Reúne 3 esencias de draco protoinfernal, 3 esencias de draco adolescente y 3 esencias de draco adulto.", description = "Estoy investigando las aplicaciones de las esencias de draco para mi trabajo como médico. ¡Creo que podrían ser la panacea para innumerables enfermedades!\n\nNecesito que alguien vaya al sur, a la Cresta Canto, y me consiga algunas.\n\n¿Qué te parecería llevarte mi modulador de fase temporal y usarlo sobre las crías que nacen de los huevos de draco abisal? Recupera las esencias de lo que sea en lo que se conviertan.\n\nDe lo cual, dicho sea de paso, no estoy seguro porque aquí usamos tecnología para modificar el tiempo y el espacio bastante peligrosa.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Manto de caza de dracos de FizitGuantes precisos de prontitudFaja de draco involucionadoBotas de TictacRecibirás:\n\nEsencia de draco medicinal"}
MultiLanguageQuestData['mx'][10617] = {title = "Capullos de Alaseda", objective = "Recoge ocho capullos de Alaseda de las larvas de Alaseda.\n\nMata a la larva rápidamente o se convertirá en Alaseda, destruyendo el capullo.", description = "La seda de los capullos de Alaseda se utiliza para todo tipo de cosas en la aldea. Nunca podemos conseguir la suficiente y nunca tenemos suficiente.\n\nEs difícil recoger los capullos de las larvas en cuanto comienzan el proceso de metamorfosis.\n\nNuestros guerreros están ocupados con el asalto a nuestra aldea. Si pudieras recogerlos para nosotros, sería de gran ayuda.", progress = "Se necesita una mano rápida y firme para recoger. Espero que tengas éxito.", completion = "Son capullos de buena calidad. Veo que le has cogido el tranquillo a lo de recogerlos.\n\nHemos experimentado intentando criar a nuestras propias larvas de Alaseda, pero, por desgracia, los pequeños no producen la seda suficiente como para que nos sean útiles.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10618] = {title = "Las alas más suaves", objective = "Recoge doce alas iridiscentes.", description = "Cazar larvas de Alaseda es un reto difícil para nuestros jóvenes guerreros, pero, por suerte, incluso en el caso de que no consigan recoger el capullo de la larva, podemos seguir usando las alas de Alaseda eclosionados.\n\nDe hecho, usamos las alas para mucho más que los capullos, y nunca tenemos demasiadas.\n\nSi piensas salir, sería de gran ayuda que me trajeras algunas.", progress = "Las alas son bastante delicadas, pero se pueden incrustar como elemento decorativo en muchos de nuestros diseños.", completion = "Gracias, &lt;nombre&gt;. Las usaremos antes de lo que piensas.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10619] = {title = "La tribu Lengua de Ceniza", objective = "El vindicador Aluumen quiere que vayas a las Ruinas de Baa'ri y mates a 3 cuidadores Lengua de ceniza, 4 guerreros Lengua de ceniza y 6 chamanes Lengua de ceniza.\n\nCompletar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices.", description = "La tribu de los Lengua de ceniza inspira terror entre todos los Tábidos. Son los individuos más sádicos y sedientos de sangre, y los ha elegido el propio Akama. Son feroces y despiadados como cualquier naga, demonio o elfo de sangre del ejército de Illidan y hay un gran contingente desplegado por las Ruinas de Baa'ri, al suroeste de este lugar. Ve allí y reduce sus efectivos antes de que les surja la oportunidad de organizar un ataque contra nosotros.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10620] = {title = "La amenaza de Crestaespina", objective = "Mata a diez acechadoras Crestaespina.", description = "Contratamos ayuda para Toshley cuando decidió trasladarse a Terrallende, y hemos ido avanzando desde entonces.\n\nPero parece que, finalmente, hemos echado raíces. Todos los científicos locos e ingenieros tienen sus proyectos en marcha, y nosotros, los Jinetes Férreos, estamos aquí para protegerlos.\n\nLo que realmente necesitamos ahora es que alguien vaya al norte a la Loma Tajo, o al este a Plataforma Alaescama, y mantenga la zona despejada ocupándose de las acechadoras. Son arañas sigilosas que viven entre los salientes rocosos, y saltan sobre transeúntes confiados.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nVisión de acechador destiladaSigilo del acechador\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][10621] = {title = "El fragmento aterraillidari", objective = "Lleva el fragmento aterraillidari a Ordinn Tronapuño en el Bastión Martillo Salvaje.", description = "Parece ser que el trozo es parte de un arma más grande. Hay runas incrustadas en el metal que brillan con una luz amenazadora.\n\nTienes claro para qué sirve el arma. La mayoría de los Mo'arg en el Bastión de la Legión parecen estar trabajando con fragmentos del mismo metal que ahora sostienes en tus manos. Quizás uno de los herreros del Bastión Martillo Salvaje pueda contarte algo más.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10623] = {title = "El fragmento aterraillidari", objective = "Lleva el fragmento aterraillidari a Grokom Ojomuerte en la Aldea Sombraluna.", description = "Parece ser que el trozo es parte de un arma más grande. Hay runas incrustadas en el metal que brillan con una luz amenazadora.\n\nTienes claro para qué sirve el arma. La mayoría de los Mo'arg en el Bastión de la Legión parecen estar trabajando con trozos del mismo metal que ahora sostienes en tus manos. Quizás uno de los herreros de la Aldea Sombraluna pueda contarte algo más.", progress = "¿Qué tienes ahí?", completion = "&lt;Grokom acepta el fragmento del arma.&gt;\n\nHacía mucho tiempo que no veía nada parecido. Seguro que está hecho de un mineral extraño, pero este fragmento no está destinado a un arma normal y corriente, &lt;nombre&gt;.\n\nHa sido infundido con magia para dominar demonios. Esto demuestra cuánto odia la Legión a Illidan, si es que están dispuestos a armar a sus propias tropas con armas para la destrucción de demonios. Podría venirnos bien.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10624] = {title = "Una de fantasmas", objective = "La boticaria jefe Hildagard de la Aldea Sombraluna, en el Valle Sombraluna, quiere que le lleves 15 muestras de ceniza siempreardiente.", description = "¿Has notado un escalofrío? ¿Quizás algo que te ha parecido una mano en el hombro? No son imaginaciones tuyas, <raza>. En esta tierra hay fantasmas. Los alrededores están plagados de fantasmas, atrapados aquí para toda la eternidad.\n\n¿Te gustaría verlos? ¿Seguro que quieres? Este tipo de cosas suelen cambiarte, y no para mejor.\n\nComo quieras, necesitaré que recojas ceniza siempreardiente que encontrarás cerca de cualquiera de las pozas de lava vil, al oeste de Sombraluna. Cualquier sitio cerca de la lava verde...\n", progress = "¿A qué te refieres? Voy a hacer algo con la ceniza, claro.", completion = "Tu mundo está a punto de cambiar, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10626] = {title = "Tomar las armas", objective = "Ordinn Tronapuño en el Bastión Martillo Salvaje quiere que le lleves las gujas de Mazakradon y de Morgroron.", description = "Con un suministro mayor de este material, podríamos forjar un arma para ti.\n\nLos dos señores del foso del Bastión de la Legión, Makazradon y Morgroron, ya están equipados con estas armas anti demonios. No tenemos forma de saber cuántas más va a producir la Legión, pero si pudiéramos conseguir los prototipos, tendríamos bastante para nuestro proyecto.\n\n<Ordinn sonríe.>\n\nHay algo de satisfacción en el hecho de usar las propias armas de la Legión contra ellos, ¿no te parece?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Borceguíes de caminante de cenizaSobrehombros golpe azurCincho de CazasombrasAvambrazos chamuscadosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10627] = {title = "Tomar las armas", objective = "Grokom Ojomuerte, de la Aldea Sombraluna, quiere que le lleves la guja de Mazakradon y la guja de Morgroron.", description = "Con un suministro mayor de este material, puedo forjar un arma adecuada para ti.\n\nLos dos señores del foso de la Bastión de la Legión, Makazradon y Morgroron, ya han sido equipados con estas armas antidemoníacas. Tomar estas dos armas debería proporcionarnos material suficiente para hacer tu arma, y luego algunas.\n\nNo puedo esperar a llevar la batalla al enemigo usando estas armas. Eso enseñará a la Legión a jugar con magia antidemoníaca.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Borceguíes de caminante de cenizaSobrehombros golpe azurCincho de CazasombrasAvambrazos chamuscadosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10629] = {title = "Un trabajo que te cagas", objective = "Usa el silbato de can manáfago para invocar un can de guardia vil. Dale un paseo al can de guardia vil y mata varios jabinfernos trastornados. Busca las llaves de la trituradora en los \"desechos\" del can de guardia vil. Devuélvele las llaves de la trituradora al supervisor Razelcraz en la mina al noroeste de Thrallmar.", description = "Por fin he conseguido que funcione mi trituradora pero, por lo visto, he perdido las llaves. Tengo varios canes manáfagos para proteger mi campamento. No es que se luzcan demasiado y parecen disfrutar mordiéndome. También les gustan las cosas que brillan. Me parece que alguno se podría haber comido las llaves de mi trituradora. Te pagaré si te llevas a mi can manáfago a dar un paseo. Mata unos jabinfernos y que se los coma. No tardará en hacer sus cosas y cuando acabe, mira a ver si puedes encontrar las llaves en sus \"desechos.\"", progress = "¿Has logrado encontrar mis llaves? Seguro que algún can manáfago se las comió. Probablemente el que envié contigo. Probablemente.", completion = "Apestas. ¡Pero has encontrado mis llaves! Muchísimas gracias. Ahora podré encender mi trituradora y ganar algo de dinero. Pronto tendré suficiente dinero para marcharme de Terrallende. No sé por qué te quedas, odio este lugar. ¿No preferirías volver a Bahía del Botín?\n\nNo sé, ¿dedicarte a la pesca?", rewards = "Recibirás:\n\nDinamita para tontos II"}
MultiLanguageQuestData['mx'][10630] = {title = "El subsuelo de Thrallmar", objective = "Mata a Urga'zz y regresa junto al supervisor Razelcraz en la mina al noroeste de Thrallmar.", description = "Estoy a punto de volver al negocio. El problema son todos esos Gan'arg en mi mina. No puedo enviar a mis peones y cuando arregle esta trituradora no quiero arriesgarla en el combate. El líder de los Gan'arg se encuentra en lo más recóndito de la mina. Si lo matas, quizás se marchen. Entonces podría ganar algo de dinero para poder largarme de aquí.", progress = nil, completion = "Seguro que esos Gan'arg se largarán ahora. Estaré de vuelta en Bahía del Botín como mucho en una semana. Estoy impaciente por volver a pescar. Fue un error venir a Terrallende. Si de algo te vale mi consejo, volverás por donde viniste. Pasa una temporada en Tuercespina, o si acaso, si buscas un poco más de emoción, ve al Cráter de Un'Goro. Todo menos quedarte aquí.", rewards = "Pico partepiedrasCasco del submundoPodrás elegir una de estas recompensas:\n\nFarol de núcleo profundo\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][10632] = {title = "Cortar tus dientes", objective = "Consigue 5 dientes Faucedaga extra afilados.", description = "Es muy amable por tu parte que hayas estado ayudando a Toshley y a sus científicos. Sin embargo, yo no tengo el lujo de poder dedicarme a mis intereses 'personales'.\n\nSi quieres distinguirte por aquí, harás lo que te pido y, ahora mismo, te pido armas.\n\nNuestras pistolas son efectivas a distancia, pero cuando los bichos se acercan necesitamos tener potentes armas cuerpo a cuerpo como refuerzo.\n\nLos dientes de los colazotes Faucedagas en Loma Tajo, hacia el norte, son perfectos para hacer armas vibrofilo. Tráeme algunos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "VibrofacaVibrodagaVibroespadaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10634] = {title = "Adivinación: la armadura de Sanguino", objective = "El espíritu Sombraluna ancestral en El Altar de las Sombras, al sureste del Valle Sombraluna, quiere que consigas la armadura de Sanguino.", description = "En vida, Sanguino fue un monstruo pero, en la muerte, fue un terror absoluto.\n\nHacia el sureste encontrarás el Arrecife del Ala Abisal. Lo que una vez perteneció a la península de Sombraluna, ahora es una isla flotante en el cielo.\n\nVhel'kur, la regeneración de Alamuerte, vivió allí, pero ahora es únicamente su tumba. Vuela incesantemente en círculo sobre la isla, furioso por haber sido vencido por Sanguino.\n\nSi quieres conseguir la armadura de Sanguino, tienes que derrotar a Vhel'kur.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10635] = {title = "Adivinación: la capa de Sanguino", objective = "El espíritu Sombraluna ancestral en El Altar de las Sombras, al sureste del Valle Sombraluna, quiere que consigas la capa de Sanguino.", description = "Cometió innumerables actos crueles, pero ninguno tan frío como la matanza de los clérigos de Karabor.\n\nCuando la Horda de Gul'dan derrotó a los draenei de Karabor, los clérigos supervivientes de Karabor fueron atacados y les llevaron a la Ciudadela del Fuego Infernal como prisioneros de guerra.\n\nSanguino, que todavía no era un caballero de la Muerte, asesinó a todos ellos a sangre fría. Ahora vagan por delante del Templo Oscuro con el ansia de venganza ardiendo en sus corazones.\n\nLos clérigos de Karabor tienen la capa de Sanguino.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10636] = {title = "Adivinación: la clava de Sanguino", objective = "El espíritu Sombraluna ancestral en El Altar de las Sombras, al sureste del Valle Sombraluna, quiere que consigas la clava de Sanguino.", description = "Uno a uno se arrodillaron ante él, ofreciendo sus vidas como muestra de lealtad. Sanguino cogió su hoz y cortó sus cabezas. Poco después de la matanza, Sanguino se quitó su propia vida.\n\nPero no se trató de un acto de contrición. No, Sanguino buscaba la inmortalidad. De los cadáveres de los caballeros de la Muerte se elevaron los jinetes fantasmales de Karabor.\n\nAhora cabalgan por los caminos de La Mano de Guldan, esperando el día en que regrese su maestro. Ellos tienen la clava de Sanguino. Recupérala...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10637] = {title = "Una distracción necesaria", objective = "La exarca Onaala quiere que vuelvas a las Ruinas de Karabor y encuentres una forma de liberar a Azaloth de sus captores.\n\nCompletar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices.", description = "Las armas son auténticas, como nos temíamos. Illidan está adiestrando cazademonios en las Ruinas de Karabor y tenemos que ponerle fin.\n\nQue no te engañe su nombre, <nombre>, usarán su poder contra nosotros tanto como contra cualquier otro demonio.\n\nSus brujos invocan a demonios y los someten para usarlos como parte de la instrucción de los iniciados. Un Señor del foso llamado Azaloth ha resultado ser demasiado fuerte para que lo puedan usar en el adiestramiento y lo han desterrado. Encuentra una forma de liberarlo de sus captores. Eso debería darnos el tiempo que necesitamos.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][10640] = {title = "Altruis", objective = "Dirígete al oeste de Nagrand y encuentra a Altruis el Sufridor.\n\nCompletar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices.", description = "En esta era y en la actualidad es raro oír hablar de alguien que sigue el camino de un cazademonios. Escasean aún más los que siguen este camino y no deben lealtad a Illidan.\n\nSe rumorea que hay uno de estos individuos aquí en Terrallende. Un nombre que despierta más miedo en los campos de la Legión de Nagrand de lo que lo haría todo un ejército de vindicadores Aldor. Ese nombre es Altruis.\n\nVe al oeste de Nagrand y encuéntralo. Puede que nos aclare algo sobre estos nuevos patios de armas de cazademonios.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10641] = {title = "Contra la Legión", objective = "Altruis el Sufridor quiere que consigas sangre recién extraída de una sacerdotisa de la cólera de la Base Forja: Gehenna en Tormenta Abisal. Derrámala en el suelo y mata al avatar de Sathal. Regresa junto a Altruis cuando hayas completado esta tarea.", description = "La Legión Ardiente ha demostrado su capacidad para corromper almas mortales una y otra vez. Si he de confiarte el conocimiento que buscas, debo tener alguna prueba de tu fidelidad.\n\nHay una demonio conocida como Sathal que se me ha escapado durante mucho tiempo ya que está dotada de una forma incorpórea.\n\nLa susodicha vigila a las sacerdotisas de la cólera mientras obedecen sus órdenes en la Base Forja: Gehenna. Mata a una de sus secuaces y derrama su sangre en el suelo. Esta afrenta debería hacer que Sathal se materialice temporalmente. Aprovecha esta ocasión para matarla.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][10642] = {title = "Un fantasma en la máquina", objective = "Zorus el Justiciero en el Bastión Martillo Salvaje, en el Valle Sombraluna, quiere que le lleves 15 muestras de ceniza siempreardiente.", description = "Me temo que esos enanos no comprenden lo que han hecho. Estos terrenos fueron en su día las Tierras Ancestrales de los orcos Sombraluna. Hablo de espíritus, <raza>.\n\nDurante casi veinte años han permanecido adormecidos bajo el Bastión Martillo Salvaje pero, recientemente, algo les ha agitado.\n\nAventúrate más allá de las puertas del bastión Martillo Salvaje y busca los estanques y los ríos de lava vil que cruzan esta tierra. Cerca de la lava encontrarás ceniza siempreardiente. Tráemela para que pueda crear algo que nos sirva.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10643] = {title = "Presagistas de Sombraluna", objective = "Zorus el Justiciero en el Bastión Martillo Salvaje, en el Valle Sombraluna, quiere que mates a 12 presagistas de Sombraluna.", description = "Queda claro que Zorus tiene sentido del humor.\n\nYa basta de cháchara. Ponte los espectróculos para que puedas ver a los espíritus de los orcos Sombraluna que vagan por el bastión. No te asustes, nosotros somos los verdaderos invasores aquí. Hay que destruirlos, ya que su tiempo hace mucho que pasó.\n\nDestruye a los presagistas de Sombraluna que infestan el Bastión Martillo Salvaje y vuelve a verme.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10645] = {title = "Yo, Teron Sanguino", objective = "El espíritu Sombraluna ancestral te ha utilizado como si fueras un títere. Ahora que has conseguido los objetos que necesitaba, ha revelado su verdadera identidad, Teron Sanguino. Para liberarte de su posesión, debes hacer lo que te pide y matar a Karsius el vigía anciano.\n\nSi tienes éxito, vuelve a ver a Zorus el Justiciero en el Bastión Martillo Salvaje.", description = "Ahora que tenemos los objetos de Sanguino, solo queda la última pieza del rompecabezas: un anfitrión.\n\n<Los labios del espíritu Sombraluna ancestral forman una malvada sonrisa.>\n\nSeguro que no te has creído la tontería que te conté. El Altar de las Sombras es mi prisión. Sin tu ayuda, me habría quedado aquí toda la eternidad. Ahora, tomaré tu cuerpo y tú destruirás a quienes me tienen prisionero y romperás mis ataduras. Niégate y ambos tendremos que permanecer aquí para siempre.\n\n¡Teron Sanguino volverá a ser libre!Cuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Casco de la clarividencia de evocadorCasco de la clarividencia de Señor SupremoCasco de la clarividencia de acechadorCasco chamanístico de clarividenciaCasco de la clarividencia sigilosoCasco druídico de clarividencia"}
MultiLanguageQuestData['mx'][10646] = {title = "El pupilo de Illidan", objective = "Escucha el relato de Altruis.", description = "Has demostrado tu fidelidad, <nombre>. Debes disculpar mi recelo pero las cosas de este mundo no son lo que parecen.\n\nTe hablaré de Varedis cuando estés <listo/lista>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10647] = {title = "SE BUSCA: Uvuros, la Plaga de Sombraluna", objective = "Mata a Uvuros y recupera su crin ígnea. Vuelve junto al clamaguerras Sardon Cortecertero de la Aldea Sombraluna, en el Valle Sombraluna.", description = "Se busca - MUERTO:\n\nUvuros, plaga del Valle Sombraluna.\n\nPor orden del señor supremo Or'barokh, la bestia vil, Uvuros, debe morir en cuanto se le vea y se le debe arrancar la crin ígnea como prueba de su muerte. Llevar la crin ígnea de la bestia al clamaguerras Sardon Cortecertero en caso de lograrlo.\n\nUvuros fue visto por última vez en La Mano de Gul'dan, sita en el corazón del Valle Sombraluna, al este de la Aldea Sombraluna.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de pellejo de uvurosBotas de pellejo de uvurosCincho de pellejo de uvurosBufas de placas de uvurosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10648] = {title = "SE BUSCA: Uvuros, la Plaga de Sombraluna", objective = "Mata a Uvuros y recupera su crin ígnea. Vuelve junto al clamaguerras Birramorro del Bastión Martillo Salvaje, en el Valle Sombraluna.", description = "Se busca - MUERTO:\n\nUvuros, plaga del Valle Sombraluna.\n\nPor orden del Señor feudal Yoregar, la bestia vil, Uvuros, debe morir en cuanto se le vea y se le debe arrancar la crin ígnea como prueba de su muerte. Llevar la melena ígnea de la bestia al clamaguerras Birramorro en caso de lograrlo.\n\nUvuros fue visto por última vez en La Mano de Gul'dan, sita en el corazón del Valle Sombraluna, al noreste del Bastión Martillo Salvaje.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de pellejo de uvurosBotas de pellejo de uvurosCincho de pellejo de uvurosBufas de placas de uvurosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10651] = {title = "Hay que detener a Varedis", objective = "La exarca Onaala quiere que vayas a las Ruinas de Karabor y mates a Alandien, Theras, Netharel y Varedis. Utiliza el Libro de Nombres Viles para debilitar a Varedis cuando use la metamorfosis. Vuelve a ver al exarca Onaala con el libro cuando hayas acabado.\n\nCompletar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices.", description = "Tenemos que deshacernos de este artefacto hediondo pero no antes de usarlo para eliminar los poderes de Varedis.\n\nTenemos que cerrar para siempre el Patio de Armas de las Ruinas de Karabor, lo que significa matar no solo a Varedis sino también a los tres maestros elfos de sangre que lo ayudan: Alandien, Theras y Netharel.\n\nReúne un grupo de ataque apropiado y regresa a las Ruinas de Karabor. Sigue las instrucciones de Altruis para derrotar a Varedis. Por el bien de todos, espero que funcione.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Camisote de KaraborMusleras Furia del SolHoja de invocadorClamasalvajeHacha de destripadorKris ceremonialRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10652] = {title = "Tras las líneas enemigas", objective = "Habla con Veronia cuando quieras ir a la Forja de Maná Coruu. Cuando llegues, habla con Caledis Alba Brillante.\n\nCompletar misiones para los Arúspices hará que disminuya tu nivel de reputación con los Aldor.", description = "Ya está todo solucionado para que puedas viajar hasta el escondite de nuestros espías. Ven a verme cuando estés <listo/lista> y te pondré de camino.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10653] = {title = "Marcas de Sargeras", objective = "Lleva 10 marcas de Sargeras a Adyen el Celador de la Luz en la Ciudad de Shattrath.\n\nCompletar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices.", description = "Ahora ya deberías tener claro por qué nos enfrentamos a la Legión Ardiente y a quienes les sirven.\n\nSi quieres demostrar tu valía a los Aldor, tráeme las insignias de los miembros de alto rango de la Legión y de sus seguidores del Consejo de la Sombra. Los miembros de la Legión de rango más alto están en la Tormenta Abisal y en el Valle Sombraluna.", progress = "¿Tienes alguna insignia de nuestros enemigos, <nombre>?", completion = "Enfrentarse a los demonios de la Legión Ardiente y a los cultores locos es toda una proeza, &lt;nombre&gt;. Has demostrado gran dedicación y coraje. Sigue así y tu reputación entre los Aldor seguirá aumentando.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10654] = {title = "Más marcas de Sargeras", objective = "¿Tienes más insignias de nuestros enemigos, <clase>? La Legión Ardiente sigue siendo una amenaza y nosotros seguimos persiguiéndoles siempre que podemos.", description = nil, progress = "¿Tienes más insignias de nuestros enemigos, <clase>? La Legión Ardiente sigue siendo una amenaza y nosotros seguimos persiguiéndoles siempre que podemos.", completion = "Sigue demostrándonos tu valía, &lt;nombre&gt;. Lucha contra los enemigos de la Luz cada vez que los encuentres; tus acciones se verán recompensadas.", rewards = nil}
MultiLanguageQuestData['mx'][10655] = {title = "Marca de Sargeras única", objective = "Me quedaré con las insignias que te sobran. No te preocupes, tus acciones serán tenidas en cuenta.", description = nil, progress = "Me quedaré con las insignias que te sobran. No te preocupes, tus acciones serán tenidas en cuenta.", completion = "Sigue demostrándonos tu valía, &lt;nombre&gt;. Lucha contra los enemigos de la Luz cada vez que los encuentres; tus acciones se verán recompensadas.", rewards = nil}
MultiLanguageQuestData['mx'][10656] = {title = "Sellos Furia del Sol", objective = "La magistrix Fyalenn en la Ciudad de Shattrath quiere que le lleves 10 sellos Furia del Sol.\n\nCompletar misiones para los Arúspices hará que disminuya tu nivel de reputación con los Aldor.", description = "Sabrás que los Arúspices y los ejércitos de Kael'thas están en guerra. Kael nos considera como una amenaza a su influencia sobre los elfos de sangre y ha intentado acabar con nosotros varias veces.\n\nSi quieres ayudarnos en nuestra batalla contra Kael'thas, hay muchos objetivos. Los soldados de mayor rango de Kael llevan sellos Furia del Sol para marcar su rango. Les encontrarás en la Tormenta Abisal y en el Valle Sombraluna.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10657] = {title = "A lomos del relámpago", objective = "Usa la esfera de magneto repolarizado para absorber 25 golpes de relámpago de las serpientes Alaescama. Consigue también 5 glándulas de relámpagos de Alaescama.", description = "El uso del Cefirium Capacitorium se nos ha pasado de presupuesto. Pero se me acaba de ocurrir que las serpientes de la Plataforma Alaescama tienen un aliento relampagueante y glándulas que podríamos usar.\n\nHe repolarizado la esfera de magneto para que absorba los golpes de relámpago y quiero que vayas hasta allí y que la actives sobre ti. De paso, consíguenos algo de combustible barato de esas serpientes.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Cubremuñecas energizadosCalzado cargadoGuantes de AlaescamaCinturón tonificador de músculosRecibirás:\n\nEnergía pura"}
MultiLanguageQuestData['mx'][10658] = {title = "Más sellos Furia del Sol", objective = "¿Qué has hecho por nosotros últimamente, <nombre>? Diría que la guerra contra Kael'thas no va a librarse sola, ¿no te parece?", description = nil, progress = "¿Qué has hecho por nosotros últimamente, <nombre>? Diría que la guerra contra Kael'thas no va a librarse sola, ¿no te parece?", completion = "¡Excelente! Eso le demostrará a Kael'thas que no debe subestimar nuestro poder.", rewards = nil}
MultiLanguageQuestData['mx'][10659] = {title = "Sello Furia del Sol único", objective = "Agradecemos hasta la más pequeña contribución a nuestra causa, <nombre>. Nuestros enemigos son muy numerosos ¡pero venceremos!", description = nil, progress = "Agradecemos hasta la más pequeña contribución a nuestra causa, <nombre>. Nuestros enemigos son muy numerosos ¡pero venceremos!", completion = "El ejército de Kael caerá pronto.", rewards = nil}
MultiLanguageQuestData['mx'][10660] = {title = "Extrañas criaturas", objective = "El investigador Tiorus de la Aldea Sombraluna, en el Valle Sombraluna, quiere que recuperes 8 bazos de fuego vil.", description = "Me interesa aprender más cosas de los extraños reptiles que pululan por los ríos de lava del Valle Sombraluna. ¡Jamás había visto bestia alguna capaz de soportar el calor abrasador de la lava derretida!\n\nEn las afueras de la Aldea Sombraluna, donde el suelo se ha agrietado y la lava fluye por las fallas, encontrarás diemetradones de fuego vil. Mátalos y tráeme sus bazos. Los analizaré y podré realizar un estudio preliminar sobre su resistencia al calor.\n\nEmpieza tu búsqueda por el sureste.\n", progress = "¡Bazos! ¡Necesito bazos!", completion = "&lt;El investigador Tiorus toma los bazos y empieza a examinarlos.&gt;\n\nEsto podría llevar algún tiempo. Aquí tienes unas monedas por tu esforzado trabajo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10661] = {title = "Para darte un 'abazo'", objective = "Gnomus, del Bastión Martillo Salvaje en el Valle Sombraluna, quiere que recuperes 8 bazos de fuego vil.", description = "¿Alguna vez has oído hablar de comida que se cocina sola y se mantiene siempre caliente? ¡Hay que atreverse a soñar! ¡Digo!\n\n¡Pero quizás no sea un sueño! En el exterior de la fortaleza, cerca de los charcos de lava, encontrarás bestias que viven en un calor abrasador. Se llaman diemetradones de fuego vil.\n\nLos enanos de por aquí me han contado que esos diemetradones tienen los bazos más sabrosos que han probado nunca ¡y vienen prácticamente precocinados! Tráeme esos bazos y te daré unas monedas.\n\nEmpieza la búsqueda directamente hacia el este.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10662] = {title = "El herrero ermitaño", objective = "Lleva la caja de lingotes a David Wayne en el Refugio de Wayne, en el Bosque de Terokkar.", description = "<Ordinn examina el resultado de su intento de forjar el metal y se sacude la cabeza.>\n\nEsto supera mis facultades pero eso no significa que no se pueda volver a crear el arma para ti.\n\nHabía un herrero con mucho talento que acompañaba a los Hijos de Lothar a Draenor, un tal David Wayne. Era un herrero extraordinario pero decidió abandonar la expedición. Hoy en día vive en un pequeño campamento en una península al este del Alto Ala de Fuego, en el Bosque de Terokkar. Llévale los lingotes y a ver si puede ayudarte con el arma.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10664] = {title = "Más materiales", objective = "David Wayne del Refugio de Wayne quiere que le lleves 1 marco de adamantita, 4 piezas de cuero de pellejo nudoso grueso y 1 Tótem de amparo demoníaco.", description = "Los lingotes que has traído contienen casi todo el metal que necesitaré para forjar la hoja de la espada pero necesitaré varias cosas para el resto de piezas del arma.\n\nVeamos, entre ellas necesitaría un marco de adamantita, algo de cuero de pellejo nudoso grueso y un Tótem de amparo demoníaco. Los buenos artesanos deberían poder producir los dos primeros artículos pero solo encontrarás el tercero en la tienda del vendedor de componentes Fantei, en el Bajo Arrabal de Shattrath. Lo encontrarás donde los demás comerciantes.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10666] = {title = "El Lexicón demoníaco", objective = "Consigue el Lexicón demoníaco del maestro mayor Vorpil y llévaselo a David Wayne en el Refugio de Wayne.", description = "Para recrear los encantamientos de la espada, se deben recitar varios hechizos en demoníaco.\n\nNo me lo enseñaron en mi época de aprendiz, pero no hay otra opción. Hay un libro, llamado Lexicón demoníaco, donde encontraremos casi todas las palabras que necesito, pero se encuentra en manos de un poderoso brujo del Consejo de la Sombra.\n\nEl maestro mayor Vorpil lo guarda en lo más remoto del Laberinto de las Sombras, en Auchindoun. Haz lo que sea necesario para recuperar el libro y tráemelo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10667] = {title = "Marga del submundo", objective = "Consigue 1 vial de marga del submundo de la hidromántica Thespia y llévaselo a David Wayne en el Refugio de Wayne.", description = "El marco que me has traído antes no bastará para sujetar el metal derretido sin refuerzos. Se puede usar un tipo de tierra rara para enfriar e imbuir el marco, lo que conferirá a la adamantita una solidez sobrenatural.\n\nLos nagas tienen en muy alta consideración la marga del submundo, que es como se conoce a esta tierra rara. Unos pocos la poseen y en Terrallende solo conozco a una naga que la usa, la hidromántica Thespia, que vive en La Cámara de Vapor, en la Reserva Colmillo Torcido.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10668] = {title = "Contra los Illidari", objective = "Altruis el Sufridor quiere que mates a Lothros del Alto Illidari en el Valle Sombraluna.", description = "Todavía respeto a Illidan. Sin él no habría encontrado mi camino.\n\nAunque ya no es el que era. El poder ha corrompido su alma, la derrota ha pervertido su mente. Se ha convertido en aquello que he jurado aniquilar y sus fieles sirvientes, los Illidari, son una abominación como cualquier demonio de la Legión Ardiente.\n\nSe le está escapando el control de Terrallende pero su dominio todavía es muy extendido. Demuestra que no estás con él y asesina a su teniente Lothros del Alto Illidari en el Valle Sombraluna.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10669] = {title = "Contra todo pronóstico", objective = "Altruis el Sufridor quiere que lleves la lanza de plata imbuida y la uses en el Portal del Claro del Lago Luz Pantanosa, en la Marisma de Zangar, para despertar a Xeleth. Regresa junto a Altruis cuando hayas matado al demonio.", description = "Algunos demonios solo se juran fidelidad a sí mismos. Un verdadero enemigo de los demonios, sin embargo, encuentra a su presa y acaba con ella, sin importar su afiliación.\n\nEl demonio Xeleth, un desertor de la Legión, fue objeto de adoración como un dios entre las primitivas criaturas de la Marisma de Zangar. Cuando casi destruyeron Draenor, se retiró en una especie de somnolencia a lo más hondo del Lago Luz Pantanosa. Encuentra el portal en el lago y clava esta lanza en el suelo.\n\nXeleth se despertará, estate <preparado/preparada> para matarlo y demostrar así que todos los demonios son tus enemigos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10670] = {title = "La lágrima de la Madre Tierra", objective = "Recupera la lágrima de la Madre Tierra del belisario O'mrogg y llévasela a David Wayne en el Refugio de Wayne.", description = "Los encantamientos de la espada deben estar en un contenedor con enfoque poderoso, como una gema. Conozco una gema que podemos usar para este fin, porque pocas hay que sirven para albergar tan poderosa magia sin desmoronarse.\n\nLa gema que necesitamos se llama la lágrima de la Madre Tierra. Es un potente artefacto y está en manos de los ogros que la crearon; el belisario O'mrogg, actual poseedor de la gema, tiene muchos aliados poderosos en Las Salas Arrasadas de la Ciudadela del Fuego Infernal Ten cuidado cuando recuperes la lágrima, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10671] = {title = "Medio kilo de carne de primera", objective = "Consigue 5 trozos de carne con energía de éter.", description = "<nombre>, tengo algo más que encargarte. Uno de mis cerebritos quiere estudiar las bestias de carne malignas que se encuentran por la Zona de Aterrizaje Razaan, al norte de la Loma Tajo.\n\nMás concretamente, quieren analizar la carne de las bestias de carne que allí se encuentran.\n\n<La cara de Vértigo se tuerce en una mueca de asco.>\n\nPero claro, no quieren ensuciarse las manos, y solo quieren la carne con energía de éter, que no es probable que tengan todos.\n\nEn mi opinión, a caballo regalado... ¿pero crees que podrías ayudarnos?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10674] = {title = "Atrapar la Luz fantástica", objective = "Utiliza la trampa de luz para atrapar 15 orbes de luz Razaani.", description = "Los etéreos de Razaani han estado jugando con una tecnología muy interesante en la Zona de Aterrizaje Razaan, hacia el norte.\n\nSeguro que no les importa que utilices este dispositivo trampa para recoger un par de muestras de sus pequeños orbes flotantes de luz rosa. De todas formas, probablemente solo sirven para decorar.\n\nLa trampa tiene una propiedad especial que, al abrirse, debería atraer una de las bolas flotantes. Aunque, probablemente, también alerte a los Razaani de tu presencia.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10675] = {title = "¡Gnomas piedad!", objective = "Recupera la colección de almas.", description = "<A Toshley se le queda la cara pálida.>\n\nEstos orbes están hechos de energía abisal y almas, ¡algunas de ellas son almas de gnomos!\n\n¿Cómo se atreven? ¿Eran ellos quienes mataban a los nuestros que viajaban hacia el norte?\n\n<nombre>, debes poner fin a esto y la única forma de hacerlo es acabar con su líder, el Príncipe del Nexo Razaan.\n\nTendrás que conseguir que salga de su guarida. Supongo que podrás hacerlo si matas a muchos de sus etéreos Razaani.\n\nTráeme la colección de almas que tiene.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Botas taumaturgas gnomasSombrero de héroe de Estación de ToshleyLeotardos ahuyenta RazaaniPeto de salvador de almasRecibirás:\n\nConvertidor de energía"}
MultiLanguageQuestData['mx'][10677] = {title = "De segundo...", objective = "Gnomus, del Bastión Martillo Salvaje en el Valle Sombraluna, quiere que recuperes 1 molleja de fuego vil hipertrofiada.", description = "Recuerdo haber visto diemetradones más grandes al este de La Mano de Gul'dan, cerca de los ríos de lava que rodean las Ruinas de Baa'ri. Pero ahora lo que quiero es que me consigas 1 molleja de fuego vil hipertrofiada de las bestias que andan por esa zona. Puede que tengas que matar a varios para encontrar una molleja como la que te he descrito. ¡Sé tenaz! Aparecerá una que debe tener mi próxima comida.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10678] = {title = "¡El plato fuerte!", objective = "Gnomus, del Bastión Martillo Salvaje en el Valle Sombraluna, quiere que recuperes el pellejo de Lomovil.", description = "Resumiendo, antes trabajaba para un elfo de sangre llamado Tiorus. Mi colaboración con Tiorus se acabó cuando descubrí el mundo del gourmet. Decidió seguir solo nuestra investigación con MIS inventos. El caso es tenía a varios de sus matones de la Horda usando mis sondas Arcanoscórpicas en los ríos de lava de las Ruinas de Baa'ri ¡y descubrió la madre de todos los diemetradones!\n\nNecesito que vayas allí antes de que él lo haga y mates al diemetradón, Lomovil, y me traigas su pellejo.\n\n¡Date prisa!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10680] = {title = "La Mano de Gul'dan", objective = "Habla con el ensalmador de la tierra Torlok en El Altar de Condenación del Valle Sombraluna.", description = "¡Los elementos necesitan tu ayuda, <raza>! El Valle Sombraluna ha sufrido perversidades inenarrables. Los espíritus viven en permanente tortura. Muchos están iracundos y no desean comulgar con el Anillo de la Tierra.\n\nAyuda a curar este mundo, <amigo/amiga>.\n\nDirectamente al noreste del Bastión Martillo Salvaje encontrarás un área conocida como El Altar de Condenación. Dirígete hacia allí y habla con el ensalmador de la tierra Torlok.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10681] = {title = "La Mano de Gul'dan", objective = "Habla con el ensalmador de la tierra Torlok en El Altar de Condenación del Valle Sombraluna.", description = "¡Los elementos necesitan tu ayuda, <raza>! El Valle Sombraluna ha sufrido perversidades inenarrables. Los espíritus viven en permanente tortura. Muchos están iracundos y no desean comulgar con el Anillo de la Tierra.\n\nAyuda a curar este mundo, <amigo/amiga>.\n\nDirectamente al sureste de la Aldea Sombraluna, en pleno corazón del Valle Sombraluna, encontrarás un área conocida como El Altar de Condenación. Dirígete hacia allí y habla con el ensalmador de la tierra Torlok.", progress = nil, completion = "Qué bien que hayas venido, no-muerto. Tenemos mucho trabajo pendiente.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10682] = {title = "Tiempos de negociación...", objective = "Negocia con el sobrestante Nuaar.", description = "Cuando llegamos a la Foresta Ruuan, los cultores de vermis no salían de El Aquelarre Alanegra, al final del túnel hacia el oeste. Pero ahora se acercan a nosotros.\n\nNecesito que encuentres al sobrestante del Culto Vermis. Se sabe que patrulla habitualmente entre los distintos campamentos de la Foresta Ruuan.\n\nNegocia con él. Que sepa que hay margen para un acuerdo pero que no perdonaremos ni permitiremos la masacre total de los animales, ni que se talen todos los árboles.", progress = nil, completion = "¡¿QUÉ?! ¿Te despacharon a ti y a nuestras propuestas inmediatamente?\n\n¡Esto es indignante! Acudimos a ellos de buena fe y, ¿te rechazan sin intentar llegar a un acuerdo?\n\nBueno, ¡pues ahora verán!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10683] = {title = "Las tablillas de Baa'ri", objective = "El arcanista Thelis del Sagrario de las Estrellas quiere que consigas 12 tablillas Baa'ri en las Ruinas de Baa'ri.\n\nA medida que completas tareas para los Arúspices disminuye tu nivel de reputación con los Aldor.", description = "Illidan ha ordenado a los Tábidos Lengua de ceniza que excaven las Ruinas de Baa'ri. Buscan artefactos draenei, no me cabe la menor duda, Baa'ri era el hogar de muchas reliquias Baa'ri antes de que Gul'dan enterrara la ciudad en una erupción volcánica. Tenemos que aprovechar esta oportunidad para recuperar las tablillas Baa'ri, un texto antiguo que, según se rumorea, encierra los secretos del Templo de Karabor. Un lugar que quizás conozcas como el Templo Oscuro.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10684] = {title = "Oronu el Anciano", objective = "El arcanista Thelis del Sagrario de las Estrellas quiere que consigas las órdenes de Akama de Oronu el Anciano en las Ruinas de Baa'ri.\n\nA medida que completas tareas para los Arúspices disminuye tu nivel de reputación con los Aldor.", description = "Según las tablillas, en Baa'ri se guardaba un artefacto conocido como el medallón de Karabor. Solo se concedía a los sacerdotes draenei de rango más elevado, ya que daba acceso ilimitado al Templo de Karabor.\n\nTenemos que averiguar si los Lengua de ceniza han recuperado ya el medallón que se guardaba en Baa'ri. Su poder sería de gran ayuda en nuestro enfrentamiento con Illidan.\n\nEl teniente de Akama en Baa'ri, Oronu el Anciano, recibe órdenes escritas de él a diario. Consíguelas y tráemelas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10685] = {title = "Los corruptores Lengua de Ceniza", objective = "Recupera los 4 trozos de los medallones de Haalum, Eyeknen, Lakaan y Uylaru, regresa junto al arcanista Thelis del Sagrario de las Estrellas, en el Valle Sombraluna.\n\nA medida que completas misiones para los Arúspices disminuye tu nivel de reputación con los Aldor.", description = "Según la carta de Akama, se desenterraron 4 trozos del medallón y se entregaron a los corruptores Lengua de ceniza. Estos temidos Tábidos fueron otrora poderosos chamanes que ahora profanan los mismos elementos que antes reverenciaban.\n\nHaalum, corruptor del aire, se encuentra en el Desfiladero del Ala Abisal. Eykenen y Uylaru, corruptores de la tierra y del fuego, fueron avistados por última vez junto a Las Fosas Viles, cerca de La Mano de Gul'dan. Lakaan, corruptor del agua, al parecer anda por el Alto Cicatriz Espiral.\n\nEncuéntralos y recupera los trozos del medallón.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10686] = {title = "La Jaula de la Guardiana", objective = "El arcanista Thelis quiere que entres en la Jaula de la Guardiana, al sur de las Ruinas de Baa'ri e interrogues a Sanoru sobre el paradero de Akama.\n\nCompletar misiones para los Arúspices hará que tu nivel de reputación entre los Aldor descienda.", description = "Los trozos que has obtenido son solo la mitad del medallón. El líder de los Lengua de ceniza, Akama, debe de tener la otra mitad.\n\nOdio tener que pedirte esto, ya que Akama es tan malvado como astuto.\n\nSe rumorea que él y los Juramorte Lengua de ceniza, los más viles y brutales de la tribu, tienen una cámara de tortura dentro de la Jaula de la Guardiana.\n\nQuiero que encuentres la prisión y descubras dónde está Akama. Su segundo al mando es un Tábido llamado Sanoru. Interrógale si tienes que hacerlo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10687] = {title = "Patio de Armas de Karabor", objective = "Larissa Golpe Solar en el Sagrario de las Estrellas quiere que consigas 8 gujas de Furia del Sol de suplicantes cazademonios y de iniciados cazademonios en las Ruinas de Karabor, al noreste del Sagrario de las Estrellas.\n\nA medida que completas misiones para los Arúspices disminuye tu nivel de reputación con los Aldor.", description = "Según informan nuestros exploradores, hay un enorme contingente de elfos de sangre Furia del Sol que se dirige a las Ruinas de Karabor. En circunstancias normales esto representaría una amenaza meramente militar, pero creemos que hay algo más.\n\nLa descripción de sus ropajes y estilo de combate se parece sospechosamente a los del mismísimo Illidan. No quiero que cunda el pánico si no hay una sólida razón para ello, así que me gustaría que fueras allí y me trajeras varias de sus armas. Concluiremos entonces si mis temores son fundados o no.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10689] = {title = "Altruis", objective = "Dirígete al oeste de Nagrand y encuentra a Altruis el Sufridor.\n\nA medida que completas tareas para los Arúspices disminuye tu nivel de reputación con los Aldor.", description = "Es raro oír hablar de alguien que sigue el camino de un cazademonios en los tiempos que corren. Escasean aún más los que siguen este camino y no deben lealtad a Illidan. Su propia gente los mira con recelo.\n\nSe rumorea que hay uno de estos individuos aquí en Terrallende. Un nombre que despierta más miedo en los campos de la Legión de Nagrand de lo que lo haría todo un ejército de vindicadores Aldor. Ese nombre es Altruis.\n\nVe al oeste de Nagrand y encuéntralo. Puede que nos aclare algo sobre estos nuevos patios de armas de cazademonios.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][10690] = {title = "La madre del cubil", objective = "Mata a Rema.", description = "¡SE BUSCA!\n\nRema, la madre del cubil y principal defensora de la Cresta Dentada al sur del Bastión Señor del Trueno.\n\nEncuéntrala dirigiéndote al este, fuera de la ciudad, y cruzando el puente que atraviesa el Barranco Machacasangre. Se mantiene apartada en el túnel que hay en el extremo sur de la cresta.\n\nVuelve con noticias de su fallecimiento al comandante Cielosombra de Sylvanaar.", progress = nil, completion = "Increíble. ¿Mataste a Rema tú solo?\n\nPor tu aspecto, diría que sí. Sabes, estamos buscando a un &lt;clase&gt; joven y fuerte, como tú, para que nos ayude, especialmente con los problemas que tenemos continuamente con los ogros. Asegúrate de que exploras conmigo esa posibilidad.\n\nBueno, sin duda te has ganado la recompensa que puse en ese cartel de \"Se busca\".\n\nPor favor, tómala.", rewards = "Puntilla élfica pesadaHacha de labralobosVarita Arcana de SylvanaarRecibirás:\n\n"}
MultiLanguageQuestData['mx'][10692] = {title = "Hay que detener a Varedis", objective = "Larissa Golpe Solar quiere que vayas a las Ruinas de Karabor y mates a Alandien, Theras, Netharel y Varedis. Utiliza el Libro de Nombres Viles para debilitar a Varedis cuando use la metamorfosis. Vuelve a verla con el libro cuando hayas acabado.\n\nA medida que completas misiones para los Arúspices disminuye tu nivel de reputación con los Aldor.", description = "Tenemos que deshacernos de este libro, pero no antes de usarlo para destruir a Varedis.\n\nTenemos que cerrar esta academia de imitadores de Illidan, lo que significa matar no solo a Varedis sino también a los tres maestros elfos de sangre que lo ayudan: Alandien, Theras y Netharel.\n\nReúne un grupo de ataque apropiado y regresa a las Ruinas de Karabor. Sigue las instrucciones de Altruis para derrotar a Varedis. Espero que este plan funcione, si no... habrá sido un placer trabajar con ustedes.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Camisote de KaraborMusleras Furia del SolHoja de invocadorClamasalvajeHacha de destripadorKris ceremonialRecibirás:\n\nObjeto #1"}
