MultiLanguageQuestData['mx'][11106] = {title = "Ya no es defensor", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nSortija del campeón eternoSortija del sabio eternoSortija del restaurador eterno"}
MultiLanguageQuestData['mx'][11107] = {title = "Inclínate ante el Alto Señor", objective = "Habla con el señor supremo Mor'ghor en el Campamento Faucedraco en el Valle Sombraluna.|n", description = "Ni siquiera soy digno de portar este mensaje para usted, señor. Perdone mi osadía. ¡El señor supremo Mor'ghor requiere su presencia en su cámara de inmediato!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][11108] = {title = "Lord Illidan Tempestira", objective = "Ve al encuentro de Illidan Tempestira. Si vives para contarlo, busca a Barthamus en el Bajo Arrabal de Shattrath.", description = "¡Ven, <alto señor/alta señora> <nombre>! ¡Illidan en persona nos espera!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
