MultiLanguageQuestData['mx'][11788] = {title = "Dando media vuelta... Otra vuelta más", objective = "Desmonta a Twonky, ED-210, Max Blasto y El Moledor y vuelve para informar a Jinky Alatuerca en la Pista de Aterrizaje de Palanqueta.", description = "Vale, creo que estamos preparados para el penúltimo asalto... Antes de que puedas acabar con Mecazod, vas a tener que desmontar a sus tenientes.\n\nEncontrarás a Twonky, ED-210, Max Blasto y El Moledor en las estaciones de la Punta Oeste, de la Punta Norte, de la Punta Central y de la Punta Sur respectivamente.\n\nPara que aparezcan, gira las válvulas en las estaciones para desbaratar aquello que estén intentando hacer. No tiene pérdida, cada lugar tiene unas luces giratorias.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11789] = {title = "Un soldado en apuros", objective = "El médico Espino, a las afueras de la Fortaleza Denuedo, quiere que te adentres en la bodega de El Rompetormentas y recuperes el contraveneno de Espino de un cajón de suministros de primeros auxilios.", description = "¡Tú! Por favor, necesito que me ayudes. Este soldado sucumbirá al veneno de los demonios de cripta a no ser que actuemos de inmediato.\n\nHe tratado de ralentizar el efecto, pero sin el antídoto adecuado no puedo contrarrestarlo.\n\nMe prometieron un nuevo suministro de contraveneno tras el último viaje al sur de El Rompetormentas. Adéntrate en su bodega y busca una caja de suministros de primeros auxilios.\n\n¡Date prisa, <clase>! No podemos permitirnos perder más hombres innecesariamente.", progress = "El contraveneno… ¿lo tienes?", completion = "Gracias, &lt;nombre&gt;. La recuperación de este hombre será lenta, pero no lo perderemos.\n\n¿Qué dices? ¿Qué encontraste cultores dentro de El Rompetormentas? Más vale que avises a alguien... Y que traigas pruebas.", rewards = "Recibirás:\n\nSuperpoción de rejuvenecimiento"}
MultiLanguageQuestData['mx'][11790] = {title = "Cultores entre nosotros", objective = "Habla con el capitán \"Zurdo\" Vela al Tercio a bordo de El Rompetormentas en la Fortaleza Denuedo.", description = "Este altar tiene la marca del Culto de los Malditos. Parece que algunos fanáticos del continente han logrado llegar hasta Rasganorte. Lo más prudente sería avisar al Capitán del barco.\n\nQuizás esté en la cubierta.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11791] = {title = "Informa a Arlos", objective = "Habla con el general Arlos dentro del cuartel en la Fortaleza Denuedo.", description = "Tenemos que avisar al general Arlos inmediatamente. Conozco al capitán desde hace muchos años y, créeme, él es uno de los más cuidadosos.\n\nQuién sabe cuántos cultores se han infiltrado en nuestros asentamientos de Rasganorte desde otros barcos. Esto podría resultar desastroso.", progress = nil, completion = "Gracias por preocuparte, &lt;nombre&gt;. Nos enteramos de la situación hace poco.\n\nEl consejero Talbot me asegura que este fue un incidente aislado y no una razón de preocupación militar.\n\nNuestras autoridades civiles se encargarán de que todo aquel que esté involucrado sea perseguido.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11792] = {title = "Enemigos de la Luz", objective = "El presagista Vurenn quiere que luches contra los cultores necrólitos cerca de Lindeallá al norte de la Fortaleza Denuedo y les arrebates el comunicado de cultor.", description = "Espera, no tan rápido. No sé quién eres, <clase>, pero las palabras del general no llegaron a convencerme. Sonaban inseguras... como si no fueran suyas.\n\nAlgo falla. Todos nuestros esfuerzos por colaborar se han obstaculizado y retrasado. Ya es hora de que investiguemos por nuestra cuenta.\n\nSi queremos averiguar más sobre los cultores dentro de la fortaleza... quizás debamos investigar a los que están fuera.\n\nLos informes de nuestros espías hablan sobre un pequeño grupo que está ayudando a la Plaga al norte de aquí. Ve a ver si llevan alguna pista.", progress = "Has vuelto, <nombre>.", completion = "Sé discreto, &lt;nombre&gt;. No podemos examinar estas pruebas delante de todas esas miradas entrometidas.", rewards = "Musleras de caminamarismasAlmófar zancatundraCoraza de piedra de poderíoPodrás elegir una de estas recompensas:\n\nCólera del presagista\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][11793] = {title = "Más investigación", objective = "Lleva el comunicado de cultor a la vindicadora Yaala dentro de la posada en la Fortaleza Denuedo.", description = "Me temo que este es un tema que debo delegar en alguno de mis espías... alguien que sepa trabajar en secreto. Guárdate las pruebas y llévaselas a la vindicadora Yaala dentro de la posada.\n\nDile que vas de mi parte y que no hable de este asunto con nadie más. No sabemos quién podría estar trabajando para el culto.", progress = "¿Te envía el presagista Vurenn?", completion = "Habla rápido, &lt;clase&gt;. ¿Qué sabes sobre el culto?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11794] = {title = "La veda está abierta", objective = "La vindicadora Yaala quiere que uses el óculo del exorcista en tres puntos diferentes de la Fortaleza Denuedo para descubrir y derrotar a los miembros del Culto de los Malditos.", description = "Me he tomado como algo personal averiguar y aprender todo lo posible sobre ese endemoniado culto de muerte, incluyendo su lenguaje secreto.\n\nVurenn tenía razón. Los cultores mencionan a varios espías disfrazados en varios puntos de la Fortaleza Denuedo: los muelles inferiores, la cárcel en el interior de la fortaleza y la cocina de la posada.\n\nToma este óculo y úsalo en esos tres lugares: cualquiera que haya usado recientemente la nigromancia del culto quedará rodeado de un aura oscura. Encárgate de los cultores antes de que ocurra algo nefasto.", progress = nil, completion = "Bien hecho, &lt;nombre&gt;. Sin embargo, no puedo dejar de tener la sensación de que esta no es la última vez que veremos a esos cultores muertos.\n\nLa oscuridad tiene su manera de ocultar incluso lo más evidente.", rewards = "Leotardos transborealesEspaldares de caminamarismasCota guarnecida zancatundraYelmo de piedra de poderíoPodrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][11795] = {title = "Protocolo de emergencia: sección 8.2, párrafo C", objective = "Recupera 6 insignias de piloto de Palanqueta de los cuerpos de los pilotos de reconocimiento de Palanqueta y devuélveselas a Iggy \"Barrena\" Conmutador en Las Pozas Escaldantes.", description = "Herido o no, como comandante del escuadrón, yo soy el responsable de encontrar y devolver las insignias de todos los pilotos caídos bajo mis órdenes. En todos los años que he volado con Palanqueta, nunca hemos dejado de devolver el sello de un piloto.\n\nHerido como estoy, sería peligroso alejarme de la seguridad de los restos del avión, pero quizás tú puedas ayudarme a recuperar las insignias. Mientras tanto, haré los preparativos para llevar a cabo mi último deber como comandante de escuadrón.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11796] = {title = "Protocolo de emergencia: sección 8.2, párrafo D", objective = "Iggy \"Barrena\" Conmutador quiere que hundas unos restos al este, unos restos al sur y unos restos al noroeste.", description = "Solo queda una cosa por hacer antes de que por fin pueda volver a la pista de aterrizaje para elaborar mi informe. La sección 8.2, párrafo D del protocolo de emergencia indica que debo hundir todos los restos posibles del avión para evitar que nuestra tecnología caiga en manos del enemigo.\n\nTe daré mi antorcha si aceptas ayudarme a terminar mi último deber. No quiero ni pensar en lo que harían los aliados goblin de la Horda si estas máquinas cayesen en sus manos.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][11797] = {title = "El asedio", objective = "El sargento Colinamartillo quiere que mates 6 reptadores de cripta en las Arenas de Nasam, a las afueras de la Fortaleza Denuedo.", description = "Bueno, bueno, bueno. Me alegra ver que Arlos está quitándole el polvo a las armas pesadas.\n\nNo me malinterpretes... nuestros muchachos están haciéndolo lo mejor que pueden, pero si alguno de los tuyos con renombre luchara junto a ellos podríamos lograr dar un giro inesperado a la situación. No sé muy bien cuánto tiempo más podremos resistir contra esos nerubianos no-muertos.\n\n¿Qué me dices, saldrías ahí fuera y matarías a algunos de esos arrastrados? Enséñales a los chicos cómo se hace.", progress = nil, completion = "Bien hecho, &lt;nombre&gt;. Enséñales cómo se hace. ¡El mejor reptador es un reptador muerto!", rewards = "Bastón largo aviesoMaza con pinchos de soldadoHoja de hechizo sañosaEstrella de la mañana de médicoEspada magna de combatienteArco largo de valentíaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][11798] = {title = "El maestro de palancas", objective = "Busca el manual del maestro de palancas y vuelve con la cabeza de Mecazod junto a Palanqueta Todogás.", description = "¡El maestro de palancas Mecazod está loco! ¡Dice que nos ofrece la inmortalidad liberándonos de la llamada \"maldición de la carne\", pero en realidad solo está creando esclavos robóticos!\n\n<nombre>, estamos seguros de que aún está en la estación de bombeo en el centro de las pozas del este.\n\nLa última vez que lo vimos estaba en la cabaña de mando arriba. Sube allí y busca entre sus cosas.\n\nSi quieres que los gnomos de todo el mundo... ¡no! todo el mundo de todas partes siga con vida, has de enfrentarte a Mecazod.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Casquete de curanderoArnés de pellejo regenerativoBotas de malla fríasPodrás elegir una de estas recompensas:\n\nAnillo destripador helado\n\nTambién recibirás:\n\n"}
