MultiLanguageQuestData['mx'][11862] = {title = "Honrar la llama", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11864] = {title = "Objetivos de una misión", objective = "El demonio tiene muchos nombres y cada nombre ha tenido un significado especial en algún momento. Aunque los detalles fueran a veces insignificantes, el resultado final siempre era el mismo: la muerte.\n\nPero es ahora, casi cincuenta años después de que todo comenzara, cuando los detalles encontrarán al diablo y lo llevarán a su perdición.\n\nEsta vez, lo tenemos... Nesingwary no tendrá escapatoria.\n\nRasganorte será el campo de batalla para nuestra guerra. ¡El cazador será cazado!", description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11865] = {title = "No se merecen la muerte", objective = "Zaza en el Campamento D.E.H.T.A. en la Tundra Boreal quiere que utilices el montón de pellejos falsos para tender una trampa a 8 tramperos de Nesingwary.|n", description = "Justo al sur de aquí los caribús solían pastar libre y pacíficamente. Entonces apareció Nesingwary y todo cambió. Ahora los caribús están en un estado perpetuo de pánico, siempre aterrados. Se ven acechados por los cazadores y tramperos que se esconden por la zona.\n\nLos ejecutores de Nesingwary no se merecen la muerte. ¡Deben sentir la misma tortura que hacen sufrir a los caribús!\n\nToma este montón de pellejos falsos y tiéndelos sobre las trampas de caribú al sur. Observa cómo los cazadores caen en sus propias trampas mortíferas.", progress = nil, completion = "Haces bien el trabajo de la Madre Tierra, &lt;nombre&gt;, pero no cantes victoria aún. Hemos descubierto el escondrijo del líder de los tramperos.", rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][11866] = {title = "Las orejas de nuestros enemigos", objective = "El archidruida Lathorius en el Campamento D.E.H.T.A. en la Tundra Boreal ha dicho que te recompensará si le traes 15 orejas de lacayo de Nesingwary.", description = "Ya sean buscadores de tesoros o cazadores sedientos de sangre, cualquiera que apoye a Nesingwary y se atreva a dañar nuestro amado entorno salvaje será considerado como un enemigo de la D.E.H.T.A.\n\nSi consigues matar a esos simpatizantes de Nesingwary, tráeme una prueba de su desaparición y te recompensaré con una bendición de los druidas de la D.E.H.T.A.\n", progress = "Las orejas servirán...", completion = "Voy a ponérmelas alrededor del cuello. ¡Que oigan nuestro mensaje y que estas orejas sean las portadoras de nuestra verdad!", rewards = "Aprenderás:\n\nBendición de D.E.H.T.A.\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][11867] = {title = "No tenemos suficientes orejas...", objective = "El archidruida Lathorius en el Campamento D.E.H.T.A. en la Tundra Boreal ha dicho que te recompensará si le traes 15 orejas de lacayo de Nesingwary.", description = "Ya sean buscadores de tesoros o cazadores sedientos de sangre, cualquiera que apoye a Nesingwary y se atreva a dañar nuestro amado entorno salvaje será considerado como un enemigo de la D.E.H.T.A.\n\nSi consigues matar a esos simpatizantes de Nesingwary, tráeme una prueba de su desaparición y te recompensaré con una bendición de los druidas de la D.E.H.T.A.\n", progress = "Ya sean buscadores de tesoros o cazadores sedientos de sangre, cualquiera que apoye a Nesingwary y se atreva a dañar nuestro amado entorno salvaje será considerado como un enemigo de la D.E.H.T.A.\n\nSi consigues matar a esos simpatizantes de Nesingwary, tráeme una prueba de su desaparición y te recompensaré con una bendición de los druidas de la D.E.H.T.A.", completion = "Voy a ponérmelas alrededor del cuello. ¡Que oigan nuestro mensaje y que estas orejas sean las portadoras de nuestra verdad!", rewards = "Aprenderás:\n\nBendición de D.E.H.T.A."}
MultiLanguageQuestData['mx'][11868] = {title = "La llegada de la Asesina", objective = "Zaza en el Campamento D.E.H.T.A. en la Tundra Boreal quiere que mates a Karen la Asesina de Caribús.", description = "Cerca del extremo sur de estos riscos es donde encontrarás a la infame líder de los tramperos de caribús. Es la más salvaje de entre todas las criaturas. Se mofa de los cadáveres de los animales asesinados, ¡bebiendo de su sangre y aullando a las lunas!\n\nEncuentra a esa asesina, esa tal Karen, y acaba con su despreciable existencia.\n\nVe bien <preparado/preparada>, <nombre>, ¡Karen la Asesina de Caribús se ha estado alardeando de las riquezas que ha recibido de Nesingwary!", progress = nil, completion = "Quizás su muerte sirva de ejemplo a otros que se atrevan a matar animales por diversión y dinero.", rewards = "Medias de ninfaEmbozo de atacanteLigas de vinculadorQuijotes de vigilante de la llanuraRecibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][11869] = {title = "Cada almeja con su pareja", objective = "La hierofante Cenius en el Campamento D.E.H.T.A. en la Tundra Boreal quiere que mates a 10 buzos enloquecidos despojadores.", description = "Al oeste de aquí encontrarás el Lago Kum'uya. Por cuanto sabemos, es el único hábitat de almejas gigantes de agua dulce del mundo.\n\nClaro que los lacayos de Nesingwary están usando el lago como una granja de perlas gigantes. ¡Debemos detenerlos! Hay que dar una lección a todo aquel que pretenda poner en peligro a una especie entera.\n\nVe al Lago Kum'uya y localiza a los buzos enloquecidos despojadores. ¡Mátalos hasta que el agua se vuelva roja! ¡Vuelve a verme cuando hayas dado ejemplo!", progress = nil, completion = "¡Ahora veamos cómo se les hincha la vena cuando vean lo que les ocurrió a sus compañeros!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11870] = {title = "El Tramo Abandonado", objective = "Busca a la hierofante Liandra en El Tramo Abandonado.", description = "Acabamos de tener noticias por Liandra de que los mercenarios contratados por Nesingwary están sacando suministros de la playa para meterlos en la embarcación principal de mercancías de Nesingwary. ¡No cabe duda de que pretenden sacar una fortuna con su sanguinario comercio!\n\nLiandra nos ha pedido que mandemos ayuda a El Tramo Abandonado, que está al sur de aquí en la orilla de la Tundra Boreal.\n\nDate prisa, ¡Liandra te espera allí!\n", progress = nil, completion = "¿Cenius te envía? ¡Pues no llegas muy pronto que digamos!|n", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11871] = {title = "No durante nuestra guardia", objective = "La hierofante Liandra en El Tramo Abandonado en la Tundra Boreal quiere que recuperes 12 envíos de piezas de animales.", description = "Por esta playa, entre los restos del naufragio, hay esparcidos cajones y sacos con piezas de animales. Parece que Nesingwary está compinchado con los Filibusteros del Mar del Norte. Esos sucios piratas están transportando suministros que los lacayos asesinos de Nesingwary reúnen en la costa. Sin duda alguna, acabarán en las casas y en las manos de individuos ricos y sin escrúpulos de Azeroth.\n\nTal cosa no ocurrirá. No durante nuestra guardia. Tráeme todos los envíos que encuentres en la playa. ¡No los tendrán nunca!", progress = "Esos pobres animales serán enterrados dignamente.", completion = "Buen trabajo, &lt;nombre&gt;. ¡Ahora atacaremos al líder pirata!|n", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11872] = {title = "El villano maestro de almejas...", objective = "Mata al maestro de almejas K y vuelve con la hierofante Cenius en el Campamento D.E.H.T.A.|n", description = "De verdad, es despreciable designarse uno mismo como el \"maestro de almejas\", como si se tuviera el dominio sobre todas las criaturas del mar. ¡Nadie puede guardarse ese derecho!\n\nDebemos encontrar a ese \"maestro de almejas\" y matarlo. La última vez que lo vieron estaba en el naufragio de la costa de El Tramo Abandonado. Encuéntralo y mátalo.\n\nCuando lo hagas, vuelve con la hierofante Cenius en el Campamento D.E.H.T.A., al norte de aquí, e infórmale de que la misión ha tenido éxito.", progress = nil, completion = "Un trabajo excelente, &lt;nombre&gt;. ¡Nos acercamos a Nesingwary!", rewards = "Palo de castigo de cazador furtivoVarilla para buscar aguaVarita del guardaHoja diestraR.E.H.T.A.Resguardo borealRecibirás:\n\n"}
MultiLanguageQuestData['mx'][11873] = {title = "Dale la noticia a Palanqueta", objective = "Ábrete camino hasta la Pista de Aterrizaje de Palanqueta y habla con Palanqueta Todogás.", description = "¿Volverías a la pista de aterrizaje para informar a Palanqueta de que dentro de muy poco estaré allí para entregarle un informe completo? Tengo que ocuparme de los restos de mi máquina voladora y luego me pondré en camino.\n\nSeguro que Palanqueta sabe que tiene que agradecerte mi supervivencia y el rescate.\n\nMe pregunto qué habría hecho el viejo si hubiera volado con nosotros. Echo de menos los viejos tiempos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Manto de ira cuajadaLeotardos de pellejo de caribú reforzadosYelmo espinado de MagmothMandiletes de placas ámbarRecibirás:\n\n"}
MultiLanguageQuestData['mx'][11875] = {title = "Lograr ventaja", objective = "Llévale 8 residuos abisales al emisario Mordin en la Ciudad de Shattrath.", description = "Las tropas de la Ofensiva Sol Devastado necesitarán ganar toda la ventaja posible para abatir a los aliados de Kil'jaeden. Mis compañeros en Ventormenta han elaborado unos aceites que reforzarán las hojas y armaduras de nuestras tropas.\n\nEl ingrediente clave, el residuo abisal, abunda en Terrallende, si sabes dónde buscar. Cualquier herborista, desollador o minero con experiencia que conozca los signos sabe encontrarlo mientras ejerce su labor. Cualquiera de esas hierbas, menas y bestias de Terrallende pueden contener residuo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPoción de rejuvenecimiento sublime"}
MultiLanguageQuestData['mx'][11876] = {title = "Ayuda a aquellos que no pueden valerse por sí mismos", objective = "El archidruida Lathorius en el Campamento D.E.H.T.A. en la Tundra Boreal quiere que utilices el aplasta trampas de D.E.H.T.A. para liberar a 8 crías de mamut.", description = "Son unas bestias majestuosas, ¿verdad?\n\n<Lathorius señala a los mamuts de la tundra septentrional.>\n\nCada día que pasa su número se reduce. Los demonios que se hacen llamar cazadores matan a los animales por diversión y dinero.\n\n<El rostro de Lathorius se retuerce de rabia.>\n\nSon sus quejidos los que me hacen hervir la sangre, <nombre>. Puedes oírlos porque los lleva el viento. Las crías de mamut, atrapadas en las viles trampas de los cazadores, necesitan nuestra ayuda.\n\nToma este martillo y aplasta esas trampas. ¡Libera a las crías!", progress = nil, completion = "&lt;El archidruida Lathorius se seca las lágrimas.&gt;\n\nNunca han tenido una oportunidad. Ahora huérfanos y solos, seguramente mueran.", rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][11877] = {title = "Planes de ataque de Furia del Sol", objective = "Lord Torvos en la Ciudad de Shattrath quiere que consigas los planes de ataque Furia del Sol.", description = "Al preparar la ofensiva contra Quel'Danas, hemos descubierto que los esbirros de Kael'thas están preparando el contraataque. Espera que desviemos nuestra atención de La Fuente del Sol ordenando a los elfos de sangre Furia del Sol, cuya base está en Tormenta Abisal, que carguen contra nuestras operaciones en Terrallende.\n\nNo podemos permitir que esto ocurra, <nombre>. Necesitamos cada hoja en las líneas de frente.\n\nVe a Tormenta Abisal y captura sus planes de ataque. Cualquier elfo de sangre Furia del Sol podría tenerlos. Buena suerte, <nombre>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSuministros de Sol Devastado"}
MultiLanguageQuestData['mx'][11878] = {title = "Khu'nok sabrá qué hacer", objective = "Llévale la cría de mamut huérfana a Khu'nok el Behemoth en la Tundra Boreal.", description = "Aunque has actuado con valentía al liberar a las crías atrapadas, muchas de ellas morirán. ¿Sabes?, sin un cuidador, esos pequeños deberán arreglárselas solos en el entorno salvaje.\n\n¡Pero existe una solución! ¡Queda esperanza!\n\nAl norte de aquí, en los pastos de mamuts, en los aledaños de Las Pozas Escaldantes, encontrarás a Khu'nok el Behemoth, un mamut tan sabio como viejo. Llévale a este mamut huérfano y preséntalo ante él. Sabrá qué hacer.", progress = nil, completion = "&lt;Oyes una voz en tu cabeza. Es Khu'nok.&gt;\n\nTu nombre ha viajado con el viento susurrante, &lt;nombre&gt;. Has realizado un acto grandioso para mi estirpe. Por esto te consideraremos como nuestro aliado. No obstante, nuestro tormento no terminará sin derramamiento de sangre y violencia.\n\nLa paz de los mamuts llegará con la muerte de Kaw...|n", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11879] = {title = "Kaw el Destructor de Mamuts", objective = "Mata a Kaw el Destructor de Mamuts y consigue la alabarda de guerra de Kaw. Llévasela al archidruida Lathorius del Campamento D.E.H.T.A. en la Tundra Boreal.", description = "No puedes acabar tú <solo/sola> con el responsable de los asesinatos de mi gente. ¡Los mamuts de la tundra te ayudarán!\n\nAdéntrate en las llanuras y busca a un mamut dominante. Te dejará montarte encima y controlar sus movimientos y acciones. Monta sobre su lomo y encuentra a Kaw, al norte de aquí en la Percha de Kaw. Juntos serán el detonador de la muerte de Kaw.\n\nAcaba con los ejércitos de Kaw y arrebátale su codiciada alabarda de guerra. Vuelve a ver a Lathorius en el Campamento D.E.H.T.A. si tienes éxito.", progress = "¿Qué ha pasado?", completion = "&lt;Lathorius te coge la alabarda.&gt;\n\n¿Esto es lo que creo que es?\n\n&lt;Lathorius esboza una amplia sonrisa.&gt;\n\n¡Estupendo! ¡Excelente! ¡Otro lacayo de Nesingwary que se ha llevado un merecido castigo!", rewards = "Sobrecamisa de D.E.H.T.A.Caperuza de polipielCharreteras éticasEscarpes de moralRecibirás:\n\n"}
MultiLanguageQuestData['mx'][11880] = {title = "La investigación multifase", objective = "El presagista Haronem de la Ciudad de Shattrath quiere que uses las gafas espectrográficas multifase para obtener 6 lecturas multifase.", description = "Seguro que ese 'inventor gnomo' es un excéntrico. Estaba farfullando acerca de unas nubes rojas que han comenzado a formarse sobre los Campos de Espíritus alrededor de Oshu'gun, en Nagrand.\n\nSegún él, estas, ehm, gafas multifase espectroalgo permitirán a quien las lleve puestas ver las nubes y obtener ciertas lecturas. Insistió en que estos datos son de suma importancia para nuestra campaña en La Fuente del Sol. Creo que está loco, pero tengo órdenes de investigar cualquier cosa que pueda servir de algo. ¿Te importaría obtener algunas lecturas?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11881] = {title = "¡Cárgala!", objective = "Fezzix Girarrosca quiere que ayudes a Jenny a llegar desde el lugar del accidente hasta el Poblado Taunka'le sin perder todo su cargamento.", description = "¿Has visto las máquinas volando como moscones alrededor? Eso sí que es innovación gnoma en su máximo apogeo.\n\nHe esperado mucho tiempo para poner mis manos sobre su tecnología y se me ha presentado la oportunidad perfecta. Una de sus naves de reconocimiento se estrelló en Las Pozas Escaldantes, en la zona suroeste de Los Campos de Géiseres.\n\nUtiliza este silbato cerca de alguna de las máquinas estrelladas y mi fiel mula Jenny contestará. Te seguirá y llevará los objetos que recuperes, pero debe permanecer a salvo. Si la atacan, empezará a soltar el cargamento.", progress = nil, completion = "&lt;Fezzix observa los objetos recuperados.&gt;\n\nJenny está un poco herida, pero se recuperará. En cuanto a los objetos, están un poco más... rotos de lo que esperaba, pero aún podría darles uso. Tú aún no te escapes, tenemos que reconstruir a este pequeño.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][11882] = {title = "Jugando con fuego", objective = "Habla con un maestro tragafuegos en cualquiera de las capitales de la Alianza.", description = "¿Deseas aprender nuevas y calientes habilidades?\n\nNo sé si serás capaz algún día de alcanzar mi curtida experiencia, pero quizás puedas aprender uno o dos truquillos si te aplicas. Habla con un maestro tragafuegos en cualquier capital de la Alianza. Ellos podrán ayudarte.", progress = nil, completion = "Me alegro de verte. ¿Has venido a aprender más sobre cómo tratar con fuego?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11883] = {title = "¿Danza con fuego?", objective = "Habla con un maestro de danza del fuego en cualquier capital de la Horda.¿Deseas aprender el arte de la danza con fuego?\n\nBien. Habla con un maestro de danza del fuego en cualquier capital de la Horda. Ellos podrán ayudarte.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", description = "¿Deseas aprender el arte de la danza con fuego?\n\nBien. Habla con un maestro de danza del fuego en cualquier capital de la Horda. Ellos podrán ayudarte.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11884] = {title = "Nedar, señor de rinocerontes...", objective = "Kilinger el Vigía del Cubil en el Campamento D.E.H.T.A. en la Tundra Boreal quiere que mates a Nedar, señor de rinocerontes y a su compañero, \"Fiambrera.\"", description = "Al oeste de aquí, en los altos riscos que asoman al Lago Kum'uya, mora un ser despreciable conocido como Nedar. El autoproclamado \"señor de rinocerontes\" caza rinocerontes heridos o demasiado jóvenes como para defenderse contra sus cobardes ataques. Por si no fuera ya bastante insultante, Nedar ha domesticado a un rinoceronte para usarlo de montura y como guardaespaldas.\n\nEs extraño que la D.E.H.T.A. quiera la muerte de un animal, pero ese rinoceronte deshonrado de Nedar debe desaparecer... Mátalos a los dos y vuelve a verme.", progress = nil, completion = "Al menos por ahora los rinocerontes conocerán la paz. Gracias, &lt;nombre&gt;.", rewards = "Tela regenerativaLeotardos de vigía del cubilCelada de clarividenteBloqueo de guardián de llanuraRecibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][11885] = {title = "Sangre adversaria", objective = "Encuentra los montones de cráneos en el centro de los círculos de invocación de Skettis. Invoca y derrota a cada uno de los descendientes usando 10 Pergaminos perdidos en el Tiempo en el montón de cráneos. Vuelve a ver a Hazzik al Alto de los Vientonegro.", description = "Los descendientes mantenidos como prisioneros por los sacerdotes de la garra de Skettis aparecen listados en este libro: Gezzarak la Cazadora, Karrog el gigante de cristal, el hereje conocido como el Estridador oscuro Akkarai y Vakkiz la Furia del Viento. Habrá que matarlos a todos antes de que Terokk regrese a este mundo.\n\nNecesitarás los pergaminos que llevan los arakkoa tiempo perdido para invocarlos en los círculos de invocación de Skettis. Te enfrentas a seres poderosos, te convendría llevar amigos.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nOfrenda tiempo perdido"}
MultiLanguageQuestData['mx'][11886] = {title = "Actividad sospechosa", objective = "Ve hasta el nuevo Campamento Crepuscular, al sur de la entrada a las Cavernas de Brazanegra en La Ensenada de Zoram de Vallefresno, y recupera la correspondencia Crepuscular de los cultores. Después, invoca al guía del Anillo de la Tierra mediante la baliza totémica.", description = "Mientras otros se divierten, <clase>, algunos de nosotros debemos ocuparnos de asuntos más peliagudos.\n\nCuando comenzó el festival, recibimos informes de La Ensenada de Zoram acerca de un severo aumento en la actividad del Culto Crepuscular. El origen de esta fiesta proviene de los mismísimos poderes que esos locos veneran; no puede tratarse de una coincidencia. Ve al campamento al sur de la entrada de las Cavernas de Brazanegra, en las ruinas, y consigue información de esos cultores, aunque tengas que hacerlo por la fuerza si es necesario. Cuando lo logres, usa esta baliza totémica para invocar a un guía.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11887] = {title = "Suministros de emergencia", objective = "Consigue 7 equipos de emergencia gnomos de los cuerpos de los pilotos de reconocimiento de Palanqueta estrellados y llévaselos a Fezzix Girarrosca al Poblado Taunka'le.", description = "Mientras saqueas las posesiones del gnomo muerto, tropiezas con un pequeño paquete lleno de víveres, herramientas y un práctico rollo gnomo de cinta adhesiva. Puede que los contenidos de este equipo le sirvan a Fezzix Girarrosca cuando tenga que volver a ensamblar las piezas de las máquinas voladoras gnomas.\n\nQuizás si llevas unos cuantos equipos a Fezzix te lleves una recompensa maja.", progress = "¿Qué es eso que tienes ahí?", completion = "¿Herramientas gnomas? ¿Para mí? Seguro que me harán la tarea más fácil de lo que pensaba a la hora de reconstruir esa máquina voladora.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11888] = {title = "Vuela al Poblado Taunka'le", objective = "Habla con el sabio Tierra y Cielo en el Poblado Taunka'le.", description = "<raza>, el cabecilla me está haciendo esperar... ¡tiempo del que Taunka'le no dispone!\n\nSe ha hablado mucho de tu valentía. En vez de esperar a que Garrosh envíe ayuda, te pido que vayas y ayudes a mi pueblo.\n\nEl Poblado Taunka'le se encuentra al noreste. Sigue el camino al este que sale del bastión, y gira hacia el norte en el cruce. Poco después te encontrarás con otro cruce. Sigue el camino hacia el este, pasando por el sur y luego por el este de las grandes pozas bordeando Las Llanuras Anegadas.\n\nVe a hablar con el sabio Tierra y Cielo cuando llegues.", progress = nil, completion = "No me sorprende que ese cabecilla orco no tenga tiempo de escuchar nuestros problemas. Los esfuerzos del embajador serán probablemente como la bruma que se lleva el viento.\n\nPero ahora estás aquí. Ahora veremos si hizo bien en enviarte.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11889] = {title = "La muerte cae desde el cielo", objective = "El sargento Colinamartillo quiere que utilices la red reforzada para ayudarte a matar a 6 escupefuegos plagados a las afueras de la Fortaleza Denuedo.", description = "Estamos haciendo un buen trabajo manteniendo el frente contra esos bichos. Sin embargo, algunos de esos demonios descarados pueden volar por encima de ese frente y están causando verdaderos estragos a nuestras defensas.\n\nHe requisado redes de pesca reforzadas de nuestros barcos civiles, así que si tienes un brazo lo suficientemente fuerte, te ayudarán a eliminarlos del aire. Reduce su número para que nuestras defensas puedan contener el ataque.", progress = nil, completion = "Los derrotaremos si vienen por tierra y los derrotaremos si vienen por aire. Si esos no-muertos desgraciados vienen por mar entonces les daremos la paliza de sus vidas.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][11890] = {title = "¿Qué se traen entre manos?", objective = "Investiga la zona que rodea la Estación de Bombeo de Palanqueta. Después, vuelve a ver al sabio Tierra y Cielo en el Poblado Taunka'le.", description = "Los gnomos se han encontrado con algunos problemas en las pozas al oeste. Se lo merecen por haber estado estropeando la tierra con eso que ellos llaman inventos.\n\nQuiero que vayas a su estación de bombeo y te enteres de qué les ha ocurrido. Vuelve junto a mí después.", progress = nil, completion = "Son noticias inquietantes.\n\nMi pueblo abandonará pronto este lugar. Vamos a atravesar las líneas de la Plaga para llegar hasta nuestra capital, Bruma de Hielo, en el Cementerio de Dragones.\n\nPero, antes de eso, debemos ocuparnos de lo que esos gnomos han ocasionado con su falta de cordura.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11891] = {title = "Un disfraz inofensivo", objective = "Utiliza el orbe del reptador para espiar en el nuevo Campamento Crepúsculo al oeste de la entrada de las Cavernas de Brazanegra en La Ensenada de Zoram en Vallefresno.", description = "Según esto, parece que hay otro campamento de cultores al noroeste de la gran congregación en La Ensenada de Zoram y que están dialogando con algunos... \"invitados\"...\n\nPodríamos averiguar muchas cosas de esas conversaciones, <raza>. Toma este orbe: con él podrás hacerte pasar por uno de los reptadores de la playa. Espía la conversación con esos \"invitados\" de los cultores y vuelve a informarme si tienes éxito.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11892] = {title = "El asesinato de Harold Sendero", objective = "El archidruida Lathorius en el Campamento D.E.H.T.A. en la Tundra Boreal quiere que mates a Harold Sendero.", description = "Has hecho tanto por los animales de la Tundra Boreal, <nombre>... Los lacayos de Nesingwary han sido derrotados y han aprendido una lección que tardarán mucho en olvidar.\n\nSe apunta a Harold Sendero, el agente principal responsable de los asesinatos en masa en Nagrand, como el hombre que estaba a cargo de las operaciones de Nesingwary en la tundra. Se encuentra en el Lago Kum'uya, al oeste de aquí.\n\n<Lathorius te extiende un cuerno de roble laboriosamente grabado.>\n\nEncuentra a Sendero y mátalo. Utiliza este cuerno si necesitas nuestra ayuda.\n", progress = nil, completion = "Por desgracia, Nesingwary ya no está. Quizás nunca estuvo aquí para empezar a...\n\n&lt;Lathorius suspira.&gt;\n\nEse demonio es resbaladizo, pero sus días están contados. Lo encontraremos, y cuando lo hagamos...", rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1Sello de explosión de activistaAnillo de rabia indignadaSortija de conservación saludable\n\nTambién recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][11893] = {title = "El poder de los elementos", objective = "Dorain Pezuña Helada en el Poblado Taunka'le quiere que utilices el tótem alma de viento para reunir la energía de 10 furibundos de vapor.", description = "Sigo intentando decirle a ese goblin tonto que sus máquinas no son fiables.\n\nPero el poder de los elementos es profundo y perdurable. Cuando termine mi periodo de aprendizaje, manejaré todo su poder. Sin embargo, lo que ya sé será suficiente para echar una mano a nuestro amigo Fezzix.\n\nCoge este tótem alma de viento y colócalo cerca de alguno de los furibundos de vapor al oeste del poblado. El tótem reunirá las energías de los elementales asesinados. Devuélveme el tótem completamente cargado y yo haré el resto.", progress = nil, completion = "&lt;Dorain asiente.&gt;\n\nBien. Esto servirá para hacerle ver a Fezzix perfectamente lo que he estado intentando decirle.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][11894] = {title = "Yo lo remendaba, yo lo remendé", objective = "Fezzix Girarrosca del Poblado Taunka'le quiere que le lleves 5 cueros curados con vapor.", description = "¿Recuerdas toda esa cinta adhesiva que me trajiste?\n\nPues bien, le he encontrado un uso. El casco de esta máquina voladora está tan destrozado que voy a tener que reforzarlo si algún día quiero volar con ella.\n\nDorain, ese de ahí, me ha estado diciendo que los taunka utilizan pieles curadas con vapor para fabricar recipientes herméticos. Los caribúes de marisma viven por todo el poblado y en las Llanuras Anegadas al sur. Consigue los mejores cueros que encuentres y cúralos sobre las corrientes de vapor de Los Campos de Géiseres.", progress = "¿Me has conseguido todo ese cuero curado de caribú?", completion = "¡Fantástico! ¡Un par de ajustes más y seré un goblin en el aire!", rewards = "Cubrehombros pijeríoBanda elástica reforzadaProtectores de muñeca de anillasPodrás elegir una de estas recompensas:\n\nTubo fino para mejorar destreza\n\nTambién recibirás:\n\nObjeto #5"}
MultiLanguageQuestData['mx'][11895] = {title = "Domina a la tormenta", objective = "Vence a la tempestad tormentosa y vuelve junto al sabio Tierra y Cielo en el Poblado Taunka'le.", description = "Por tu descripción, las criaturas de metal deberían ser fáciles de derrotar. Pero primero, tienes que dominar la tormenta.\n\nDetrás de mí, en el refugio, hay un tótem. Cuando estés <preparado/preparada>, concéntrate en él y la tormenta vendrá. Debes vencer a la tormenta y, al hacerlo, absorber su esencia.\n\nSi alguien más está alrededor, bastará con que todos se unan para vencerla. Vuelve a verme después, <clase>.", progress = nil, completion = "¡Siento el poder de la tormenta fluir en tu interior!\n\nEstás preparado, &lt;nombre&gt;. Comencemos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11896] = {title = "Débiles ante el relámpago", objective = "Mientras estén debilitados por el Poder de la tormenta, destruye a 15 unidades robóticas, exceptuando a los mecagnomos, en la gran área de pozas que rodean la Estación de Bombeo de Palanqueta.\n\nDespués, vuelve junto al sabio Tierra y Cielo en el Poblado Taunka'le.", description = "Ahora tienes en ti el poder de la tormenta. Te facilitaré los medios para concentrarlo y debilitar a los robots de las pozas.\n\nToma esta vara de relámpagos y úsala contra las creaciones robóticas de los mecagnomos que encontrarás en la gran área de pozas al oeste. Ni te molestes en usarla contra los mecagnomos; la abuela Taiga tiene en mente otros planes para ellos.\n\nCuando los robots estén debilitados por el poder de la tormenta, ¡desmóntalos completamente!", progress = nil, completion = "Ya que nos hemos ocupado de sus esbirros robóticos, es hora de que avancemos hacia el pez gordo. Por desgracia, siento el poder de la tormenta decreciendo en ti.\n\nSin embargo, sirvió su propósito y creo que eres más que capaz de dar el paso siguiente sin él.", rewards = "Te van a lanzar el siguiente hechizo:\n\nWeakness to Lightning: On Quest Complete\n\nRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][11897] = {title = "Obstruye los sumideros", objective = "El sargento Colinamartillo quiere que uses los explosivos incendiarios para hacer explotar los sumideros suroeste y noroeste de la Fortaleza Denuedo.", description = "La Plaga no da muestras de debilidad, <nombre>. Son esos malditos sumideros: conectan con túneles hasta Corona de Hielo, según la información que tenemos. Unas lombrices no-muertas gigantes están cavando bajo tierra para crearlos.\n\nSi hay algo que haya aprendido tras años trabajando en las minas es que sin elementos sustentantes los túneles se hundirán con facilidad tras una explosión.\n\nToma estos explosivos y colócalos a la entrada de los sumideros, en lo alto de la cresta al oeste, más allá de la playa. Vuelve cuando los hayas hecho explotar.", progress = nil, completion = "Has hecho un trabajo excelente, &lt;nombre&gt;. Sin ti, la Fortaleza Denuedo no podría haber resistido contra los atacantes. Gracias a tu ayuda viviremos para luchar un día más.", rewards = "Casquete transborealPechera de caminamarismasLeotardos de La Falla OesteEspaldares de piedra de poderíoRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][11898] = {title = "Abriéndose paso", objective = "Derrota al príncipe Valanar y a sus tenientes, Vanthryn el Despiadado y Luthion el Vil, e informa de ello al cabecilla Vendaval de Invierno en el Poblado Taunka'le.", description = "En el piso más bajo de la Ciudad Templo existe un altar gris bañado de luz. Súbete y accederás a la temible necrópolis de Naxxanar.\n\nTen cuidado, <nombre>. El príncipe Valanar estará protegido por sus criados personales, que preferirían morir antes que dejarte subir hasta el piso alto de la necrópolis.\n\nDebes abrirte camino por la necrópolis hasta el trono del príncipe. Si no logras derrotarlo, <nombre>, me temo que mi pueblo no conocerá nunca la seguridad que Bruma de Hielo puede ofrecer.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nAgarre de voluntad eternaGargantilla de redención fuerteCadena del pensamiento vigilante\n\nTambién recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][11899] = {title = "Las almas de los desembrujados", objective = "Usa el cazador de almas de la Abuela para capturar las almas de 10 mecagnomos de Palanqueta. Después, vuelve junto a la abuela Taiga en el Poblado Taunka'le cuando hayas terminado.", description = "Los mecagnomos de las pozas al oeste encierran un gran misterio que no hemos logrado descifrar. Aparecieron poco después de que los gnomos desaparecieran de su estación de bombeo y de sus alrededores.\n\nSon un peligro alarmante y deben morir.\n\nToma este cazador de almas y úsalo sobre los restos de los mecagnomos para capturar sus almas. Cuando vuelvas, las liberaremos para intentar averiguar lo que les ocurrió.", progress = nil, completion = "Ahora debemos liberar las almas que has atrapado.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][11900] = {title = "Lectura de medidores", objective = "El archimago Berinand en el Escudo de Tránsito te ha pedido que recojas las lecturas de sus instrumentos en Gelidar.", description = "Esperaba que el impacto de El Nexo se limitase a esta zona. Sin embargo, hace poco ha surgido una avalancha de información de todo Azeroth según la cual la inestabilidad geológica está creciendo de manera exponencial.\n\nNecesito observar El Nexo con frecuencia mientras trabajo para solucionar el problema.\n\nHe colocado instrumentos de precisión por Gelidar, camuflados como si fueran orbes de visión de Malygos. Hay uno en la trinchera cercana a El Nexo y otros tres escondidos por las estructuras que rodean el valle. Ve a ver a cada uno y vuelve con la lectura de los datos.", progress = nil, completion = "Esto es aún peor de lo que pensaba.\n\nMalygos está canalizando demasiado poder a este lugar. Si no lo detenemos, ¡Azeroth será el próximo Terrallende!\n\nLa buena noticia es que creo haber encontrado una solución temporal...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11901] = {title = "¿Destacamento? ¿Qué destacamento?", objective = "Gerald Verde de Lindeallá quiere que vayas a la mina del norte y descubras qué le ocurrió al destacamento militar que enviaron allí.", description = "La Plaga está por todas partes, <clase>. Hemos organizado a los granjeros y a los mineros en una milicia, pero no servirá.\n\nEl único destacamento que envió la Fortaleza Denuedo está defendiendo la mina. ¡No hemos vuelto a saber nada de ellos desde hace días!\n\nSi de verdad deseas ayudarnos, ¿por qué no vas a la mina y vas a ver lo que se cuece? Quizás podamos conseguir que nos envíen refuerzos.", progress = nil, completion = "A medida que te acercas al grano, tu estómago empieza a revolverse. El olor es casi insoportable.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11902] = {title = "Una evidencia perniciosa", objective = "Vuelve junto a Gerald Verde en Lindeallá.", description = "Los sacos de grano emanan un hedor fétido que has llegado a asociar con la Plaga. Esto explica probablemente lo que les ocurrió a los trabajadores que defendían la mina.\n\nDeberías volver a informar a Gerald Verde.", progress = nil, completion = "Esos pobres chicos... ¡no tuvieron ninguna oportunidad!\n\nEsto parece un trabajo organizado desde dentro. Probablemente un infiltrado del Culto de los Malditos. ¡Malditos sean esos locos!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11903] = {title = "Es hora de actuar", objective = "Gerald Verde en Lindeallá quiere que mates a 14 carroñeros apestados.", description = "Bien, <nombre>. Con nuestras últimas fuerzas en Lindeallá, ya muertas o algo peor, solo nos queda una opción: luchar nosotros mismos contra la Plaga.\n\nHemos desplegado una milicia en lo que queda de Lindeallá. Sin tu ayuda, no tendrán muchas posibilidades de ganar. Ve allí y échales una mano. Los muchachos y yo observaremos este camino. ¡No podemos permitir que la Plaga avance!", progress = nil, completion = "Te has comunicado con la Plaga en el único idioma que entienden: violencia y muerte. ¡Por desgracia continúan viniendo!", rewards = "Brazales transborealesJubón ribereñoBotines de mendigoPodrás elegir una de estas recompensas:\n\nCollera pugnaz\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][11904] = {title = "Frutos de nuestro trabajo", objective = "Ve hasta la mina de Lindeallá, consigue la llave para liberar la vagoneta del capitán Jacobs y utilízala para liberar la vagoneta de mena. Vuelve a ver a Gerald Verde en Lindeallá cuando hayas completado esta misión.", description = "Los de la Plaga siguen llegando... ¡pero no podemos rendirnos! Escucha, <nombre>. Dentro de esa mina hay una vagoneta con la última mena que la Alianza va a ver a este lado del continente en mucho tiempo.\n\nEl problema es que la vagoneta está cerrada con llave y no se puede liberar. Cuando los soldados entraron ahí, el capitán Jacobs se incautó de todo el equipamiento importante, incluyendo la llave para liberar la vagoneta.\n\nLa peste que contagió a los soldados en la mina también ha debido afectar a Jacobs. Consigue la llave, que estará en su poder, y recupera la mena.", progress = nil, completion = "Te doy las gracias, &lt;nombre&gt;. Esta mena será de vital importancia para la Alianza en los tiempos venideros. Quiero pensar que hoy hemos hecho algo importante.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][11905] = {title = "Posponiendo lo inevitable", objective = "La imagen de la maga de guerra Kaitlyn de El Nexo quiere que uses el refabricador interdimensional cerca de la falla.", description = "Las líneas Ley de Azeroth se están canalizando hacia El Nexo.\n\nEl influjo de energías arcanas está creando una brecha entre las dimensiones.\n\nNo puedo detenerlo, pero he descubierto una manera de ralentizarlo.\n\nToma esto y actívalo cerca de la falla que se está formando.", progress = "¿Has estado en la falla?", completion = "Un trabajo excelente, &lt;nombre&gt;. Los temblores ya han empezado a calmarse.\n\nCon un poco de suerte, nos habrás conseguido el tiempo suficiente para frustrar los planes de Malygos.", rewards = "Manijas de tiempo retorcidoGuantes de tiempo paradoAtaduras de sabotajeGuanteletes del gigante afectadoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][11906] = {title = "Limpiando las Pozas", objective = "Recoge 15 piezas de repuesto de Palanqueta y entrégaselas a Ojos de Hierro en el Poblado Taunka'le.", description = "<Una lágrima se desliza por la cara de Ojos de Hierro.>\n\nHe oído que vuelves a las pozas al oeste. Tengo una tarea para ti mientras estés por allí, <raza>.\n\nLos gnomos, que apenas se preocupan por la tierra, la han contaminado con sus máquinas. Quiero que recojas cualquier pieza suelta que te encuentres.\n\nTráemelas aquí. Me encargaré de que se desechen debidamente antes de que abandonemos este lugar para siempre.", progress = "Si no cuidamos de la tierra, pagaremos las consecuencias.", completion = "Es la manera taunka de dejar la tierra prístina antes de continuar nuestro camino.\n\nMuy pronto viajaremos hacia nuestra capital, Bruma de Hielo. Nos has ayudado a acelerar nuestra partida.\n\nGracias.", rewards = "Manto de ira cuajadaLeotardos de pellejo de caribú reforzadosYelmo espinado de MagmothMandiletes de placas ámbarRecibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][11907] = {title = "Los subtenientes", objective = "Derrota a Twonky, ED-210, Max Blasto y El Moledor, y vuelve a ver al sabio Tierra y Cielo al Poblado Taunka'le.", description = "Se sabe que el maestro de palancas Mecazod cuenta con la ayuda de cuatro subtenientes que dirigen a los robots de las pozas.\n\n¡Debemos acabar con ellos!\n\nNuestros enviados y rastreadores de nieve dicen que si giras las válvulas en las Estaciones de la Punta Oeste, de la Punta Norte, de la Punta Central y de la Punta Sur, cada uno de estos subtenientes acudirá rápidamente para detenerte y que no puedas desbaratar sus operaciones.\n\nLas Estaciones se encuentran en medio de las luces giratorias de las pozas que rodean la estación de bombeo.\n\n¡Date prisa, <nombre>!", progress = nil, completion = "Gracias, &lt;nombre&gt;.\n\nAl acabar con esas extrañas criaturas, será pan comido encargarse del resto de las pozas.\n\nTe estamos inmensamente agradecidos.", rewards = "MascaescarchaPuño de hielo dentadoGran bastón hambrientoCapa de sanador estremecidoPodrás elegir una de estas recompensas:\n\nCollar de hablaescarcha\n\nTambién recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][11908] = {title = "Material de referencia", objective = "Jeremiah Hawning quiere que recuperes el libro \"Campos, fábricas y talleres\" del edificio en llamas junto a la mina en Lindeallá.", description = "Yo me encargaba de los gólems de la cosecha... un trabajo importante hasta que la Plaga destruyó la mayor parte de nuestras tierras de cultivo. Pero tengo una idea para que los gólems vuelvan a ser útiles.\n\nCreo que puedo alterar el sistema eléctrico de los recolectores para que nos echen una mano en la lucha contra la Plaga.\n\nNo soy un experto aún, así que necesitaré mi manual. El problema es que lo dejé en el taller... que resulta que es ese edificio en llamas al lado de la mina. ¿Crees que podrías ir a recuperarlo?", progress = "¿Has recuperado mi libro?", completion = "¡Excelente! La información que necesito debería estar aquí.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11909] = {title = "Vence al maestro de palancas", objective = "Busca el manual del maestro de palancas y llévale la cabeza de Mecazod a la abuela Taiga en el Poblado Taunka'le.", description = "No me cabe duda alguna de que ese tal maestro de palancas Mecazod no está bien de la cabeza. Si su oferta de cura e inmortalidad significa que todos debemos convertirnos en esclavos robóticos, ¡debemos detenerlo!\n\nLos vientos que me guían susurran que se encuentra en lo alto de la estación de bombeo en medio de las pozas al oeste.\n\nLo más probable es que lo encuentres en la barraca que hay en lo alto de la estructura.\n\n<nombre>, ¡debes enfrentarte a Mecazod si quieres que sobrevivamos!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Arco tenso de madera de naufragioGrebas PortaterraBáculo del NatovientoBáculo del clamaespíritusMartillo de guerra Cuna de FuegoRecibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][11910] = {title = "Secretos de los ancestros", objective = "El archimago Berinand en el Escudo de Tránsito quiere que recojas 3 esquirlas glaciales y 3 esquirlas de vinculado a magia de los ancestros de Gelidar.", description = "No hay duda de que la inestabilidad de la región ha afectado a sus criaturas autóctonas.\n\nTengo especial interés por los ancestros glaciales y sus recientes adaptaciones. Sospecho que su transformación en esos ancestros \"vinculados a magia\" puede darnos pistas para salir de este apuro.\n\nNecesito muestras de ambos para mis estudios. Apresúrate...", progress = "¿Has conseguido las muestras que te pedí?", completion = "Sí, sí... estas servirán.\n\nGracias, &lt;raza&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11911] = {title = "Acelerando", objective = "La imagen de la maga de guerra Kaitlyn de El Nexo quiere que reúnas 5 astillas arcanas de protectores cristalinos.", description = "He aprendido más en el corto periodo que he pasado aquí que en décadas de estudio.\n\nEstos ancestros se están exponiendo a niveles increíbles de energía arcana. Literalmente, les está transformando en algo... diferente.\n\nSeguro que hay otro nivel en su metamorfosis. Consigue alguna prueba de su última fase.", progress = "Los ancestros cristalinos... ¿Existen?", completion = "¡Fascinante!\n\nY también son agresivos, por lo que dices. Eso me indica que hay algún tipo de organización detrás de toda esta manipulación.\n\nNo puede ser natural...", rewards = "Sandalias de evolución místicaBotines de futuro destrozadoBotines con pinchos de mutaciónEscarpes vigorizadoresBotas del protector erguidoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][11912] = {title = "Locos por unos gelifructus", objective = "La bibliotecaria Serrah del Escudo de Tránsito quiere que recojas 10 gelifructus de los arbustos de gelifructus de Gelidar.", description = "¡Da gusto ver caras nuevas! Ya empezaba a pensar que nos habían olvidado.\n\nNos cortaron las líneas de abastecimiento hace días, y las cosas han estado algo... bueno, sombrías. Sinceramente, para empezar esta era una misión suicida.\n\nQuizás es que no estoy hecha para tanta violencia, ¡sin mencionar este frío atroz! Preferiría, con diferencia, volver a estar en Dalaran estudiando textos antiguos.\n\nPero al grano, nuestro abastecimiento de comida está casi agotado. Por favor, reúne lo que puedas y tráemelo.", progress = "¿Has logrado encontrar algo de comida?", completion = "Bueno, no es mucho, pero nos podrá mantener con vida un día más.\n\nCreo que esto será una compensación justa por tu ayuda.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11913] = {title = "No tientes a la suerte", objective = "Wendy Darren quiere que uses la antorcha de Wendy para quemar 8 sacos de grano de Lindeallá.", description = "He oído lo que le dijiste a Gerald y no me gusta un pelo. Si los cultores consiguieron envenenar el grano en las minas con su peste hedionda, es fácil que hayan hecho lo mismo con el grano que había fuera.\n\nNo hay tiempo para separar el buen grano del malo. Debemos actuar con rapidez y quemarlo todo.\n\nToma esta antorcha y prende fuego a cualquier saco de grano que encuentres por ahí. Sería una tragedia si sobreviviésemos a este ataque para sucumbir luego a la peste.", progress = nil, completion = "Gracias, &lt;nombre&gt;. No podría haber soportado ver a los supervivientes del ataque de Lindeallá tropezar con grano apestado.", rewards = "Manto transborealCasquete ribereñoCoselete de heridas con ungüentoPodrás elegir una de estas recompensas:\n\nSello de explorador\n\nTambién recibirás:\n\nSuministros de aventura de RasganorteObjeto #1"}
MultiLanguageQuestData['mx'][11914] = {title = "Guarda el secreto", objective = "La bibliotecaria Serrah del Escudo de Tránsito necesita que mates serpientes arcanas cerca de El Nexo para reunir 5 muestras de esencia de maná nexa.", description = "Nuestra vida aquí depende completamente de que permanezcamos escondidos. Si el escudo falla, incluso por un momento, los esbirros de Malygos nos cazarán.\n\nUna de mis responsabilidades es restaurar el maná de los magos de guerra para que su enfoque no se debilite. Con la falta de líneas de abastecimiento he tenido que improvisar.\n\nMe vendría bien tu ayuda, <nombre>.\n\nMuy cerca de El Nexo, las serpientes arcanas se dan un festín con la abundante energía mágica. Una vez muertas, soltarán esencia de maná que podré utilizar.", progress = "¿Tienes las esencias de maná que pedí?", completion = "La ayuda que has prestado a Dalaran no pasará desapercibida, &lt;raza&gt;.\n\nEspero que esto sea bastante.", rewards = "Manteo de escamas chamuscadoCadeneta cauterizadoraGuanteletes del guardián carmesíPodrás elegir una de estas recompensas:\n\nEstrella de Serrah\n\nTambién recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][11916] = {title = "El campeón de Grito Infernal", objective = "Busca al cabecilla Vendaval de Invierno en el Poblado Taunka'le.", description = "Te has enfrentado a todos los retos que se te han planteado y te los has comido con patatas. Gracias a ti, <nombre>, la Horda se ha atrincherado en Rasganorte.\n\nPero nuestro trabajo no ha hecho más que empezar. ¡Debemos emprender el camino a Corona de Hielo y derrumbar sus muros!\n\nTu próxima tarea empieza al este, en el Poblado Taunka'le. Nuestros aliados taunka están en apuros y necesitan ayuda. Consigue transporte con el maestro de establos, Durkot Hermano Lobo, y busca al cabecilla Vendaval de Invierno en Taunka'le.", progress = nil, completion = "Me temo que llegas un poco tarde, campeón. Muchos de mis hermanos y hermanas ya han abandonado Taunka'le en busca de refugio en el Cementerio de Dragones, al este.\n\nQueda mucho por hacer por aquí y pocos que quieran brindarnos su fuerza...", rewards = "Hacha de muerte congeladaMachacador borealTorre de la mente infinitaBastón del mendigo resueltoFuria del dragón enfurecidoColmillo del alma desoladaRecibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][11917] = {title = "El contraataque", objective = "Mata al teniente Olaescarcha que invoques desde la piedra de hielo situada en La Ensenada de Zoram en Vallefresno. Después, ve a ver al anciano del Anillo de la Tierra en alguna de las capitales.", description = "¡Debemos hacer algo por mantener la balanza en equilibrio! Tenemos el tiempo en contra.\n\nRegresa a La Ensenada de Zoram con esas grandes piedras de hielo. Las usan para comunicarse con los elementales, es algo similar a lo que hacen en Silithus. Aunque no me gusta nada la idea de hacer esto, sé que los espíritus lo entenderán. Tienes que invocar a alguno de esos tenientes de Ahune y acabar con él. Quizás con esta precaución sea suficiente...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11918] = {title = "Entrenamiento básico", objective = "Raelorasz en el Escudo de Tránsito quiere que mates a 10 tejehechizos de Gelidar.", description = "Esto es la guerra, mortal, y nosotros somos la punta de la lanza.\n\nTus pequeñas rencillas por la tierra o la moneda son ridículas en comparación con este conflicto. Nos enfrentamos al Aspecto Malygos y a todo su Vuelo Azul. Todo lo que necesitas saber es que si consigue su cometido, este mundo dejará de existir.\n\nSolo somos unos pocos aquí, y volamos contra muchos. Moriremos con toda seguridad, y nuestro último éxito yace en un mero entorpecimiento de nuestro enemigo.\n\nAhora, vete. Mantente <ocupado/ocupada> mientras decido qué hacer contigo.", progress = nil, completion = "Bien, &lt;clase&gt;, ahora que te has familiarizado con el enemigo es hora de que te pongas a trabajar.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11919] = {title = "Caza de dracos", objective = "Raelorasz quiere que uses la lanza de Raelorasz para dominar a una prole de draco de El Nexo y regreses junto a él en el Escudo de Tránsito.", description = "Los azules han empezado a cubrir a sus dracos con unas runas misteriosas. Tengo que averiguar su significado.\n\n<Raelorasz se pincha la mano con una lanza y cubre la punta con su sangre.>\n\nToma esto y úsalo con uno de ellos. Espera a dominarlo y luego tráelo aquí antes de que se acabe el efecto.\n\nSu prole busca alimento por los alrededores del extremo noroeste del valle.", progress = nil, completion = "El destino de estos jóvenes dracos no debe ser una carga en tu conciencia, &lt;raza&gt;. Malygos es el único responsable de todo esto.\n\nEstoy trabajando sin descanso para revelar los secretos de esas runas. No acabaremos con más vidas de las que sean necesarias.", rewards = "Togas sofocantesCinturón de pellejo de draco carbonizadoAtaduras imbuidas con llamasYelmo del dracónido carmesíRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][11920] = {title = "Cultores entre nosotros", objective = "Habla con el capitán \"Zurdo\" Vela al Tercio a bordo de El Rompetormentas en la Fortaleza Denuedo.", description = "Este altar tiene la marca del Culto de los Malditos. Parece que algunos fanáticos del continente han logrado llegar hasta Rasganorte. Lo más prudente sería avisar al Capitán del barco.\n\nQuizás esté en la cubierta.", progress = nil, completion = "¿Cultores? ¿Bajo la cubierta? ¡Tendría que azotar a toda mi tripulación!\n\nEscucha... ¿por qué no hacemos que la almirante Cantlebree se ocupe de esta... situación?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11921] = {title = "Más lanzamiento de antorchas", objective = "Gana la prueba de lanzamiento de antorchas y ve a hablar con el maestro tragafuegos.", description = "¡Hola, malabarista de fuego! ¿Te estás divirtiendo y causando un fogoso alboroto? ¡Así me gusta! Pero, ¿te crees con mucha experiencia lanzando antorchas? Pues tengo una prueba para ti...\n\nYa conoces el funcionamiento: lanza antorchas a los blandones marcados. Pero esta vez tienes un poco menos de tiempo y MUCHOS más blandones.\n\n¿<Preparado/Preparada>?", progress = nil, completion = "¡Vaya, lo conseguiste! ¡Eres genial! ¡Quizás puedas pedir un puesto de trabajo para el festival del año que viene!", rewards = "Recibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11922] = {title = "Lanzamiento de antorchas", objective = "Gana la prueba de lanzamiento de antorchas y ve a hablar con el maestro tragallamas.", description = "¿Así que quieres ser malabarista de fuego? ¿Tienes lo que hay que tener? ¿La destreza? ¿Los reflejos? ¿...El valor? Si eso es lo que crees, ¡empecemos a practicar!\n\nToma estas antorchas y corre cerca de la fogata. Verás unos blandones con unas marcas intermitentes por encima. Lanza una antorcha a los blandones marcados. ¡Actúa rápido! ¡Hazlo antes de que la marca se desvanezca si quieres conseguir puntos por cada lanzamiento!\n\nAcierta sobre los blandones antes de que expire el tiempo límite, y luego vuelve aquí para tu próxima lección.", progress = nil, completion = "¡Bien hecho! ¡Te convertirás en malabarista de fuego más rápido que lo que tarda en arder la mecha de un petardo! Prepárate... ¡En la próxima prueba la cosa está que arde!", rewards = "Recibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11923] = {title = "Caza de antorchas", objective = "Atrapa 4 antorchas seguidas y después ve a hablar con el maestro tragallamas.", description = "Ahora que puedes lanzar una antorcha, ¡veamos si eres capaz de atrapar una!\n\nToma este montón de antorchas apagadas. Ve hasta la hoguera y lanza al aire una antorcha. ¡Atrápala antes de que llegue al suelo y luego vuelve a lanzarla! Atrapa 4 seguidas y después ven a verme.\n\n¡Ten cuidado! Si tocan el suelo son muy peligrosas. ¡Y no dejes caer ninguna! Si no, tendrás que ir de nuevo hasta la hoguera y volver a empezar. ¡Buena suerte!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFlores ardientesAntorcha de malabarismos"}
MultiLanguageQuestData['mx'][11924] = {title = "Más caza de antorchas", objective = "Atrapa 10 antorchas seguidas y después ve a hablar con el maestro tragafuegos.", description = "Atrapar antorchas es sin duda algo que requiere mucho afán. ¿Crees que podrás aguantar?\n\nVamos a comprobarlo...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11925] = {title = "Más caza de antorchas", objective = "Atrapa 10 antorchas seguidas y después ve a hablar con el maestro tragallamas.", description = "Atrapar antorchas es sin duda algo que requiere mucho afán. ¿Crees que podrás aguantar?\n\nVamos a comprobarlo...", progress = nil, completion = "¿Cómo va ese brazo, &lt;nombre&gt;? ¡Lo has hecho fenomenal! ¡Estás hecho un experto malabarista!", rewards = "Recibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11926] = {title = "Más lanzamiento de antorchas", objective = "Gana la prueba de lanzamiento de antorchas y ve a hablar con el maestro tragallamas.", description = "¡Hola, malabarista de fuego! ¿Te estás divirtiendo y causando un fogoso alboroto? ¡Así me gusta! Pero, ¿te crees con mucha experiencia lanzando antorchas? Pues tengo una prueba para ti...\n\nYa conoces el funcionamiento: lanza antorchas a los blandones marcados. Pero esta vez tienes un poco menos de tiempo y MUCHOS más blandones.\n\n¿<Preparado/Preparada>?", progress = nil, completion = "¡Vaya, lo conseguiste! ¡Eres genial! ¡Quizás puedas pedir un puesto de trabajo para el festival del año que viene!", rewards = "Recibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11927] = {title = "Dicen por la calle", objective = "Busca a Leryssa en la posada de la Fortaleza Denuedo.", description = "Hola, <nombre>. Hay una chica en la posada que está preguntando por ti. Se llama Leryssa.\n\nNo creo que te conozca, pero dice que necesita tu ayuda. Parecía realmente desesperada.", progress = nil, completion = "Gracias por venir, no sabía con quién más contactar.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11928] = {title = "Lindeallá", objective = "Viaja a Lindeallá, en la Tundra Boreal, y habla con Gerald Verde.", description = "Mis muchachos deberían poder luchar desde ahora, <nombre>. La Fortaleza Denuedo está construida para soportar golpes peores que este. Pero me preocupan los campos de cultivo y la mina.\n\nEnviamos un destacamento entero para proteger nuestras actividades mineras justo antes de la invasión, ellos podrán defender a los civiles.\n\nGerald Verde está al cargo de los aldeanos allí. Existe un pasadizo desde el muro norte de la Fortaleza Denuedo; te llevará directamente a él. Intenta ayudarlos.", progress = nil, completion = "¿Vienes a ayudarnos? ¡Entonces llegas justo a tiempo!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11929] = {title = "La caída del Poblado Taunka'le", objective = "Habla con Madre Tauranuk a las puertas del Poblado Taunka'le.", description = "Estamos perdidos, <nombre>. Este lugar ha sido nuestro hogar durante muchas generaciones, pero ya no es seguro. Tan solo queda muerte... Muerte y recuerdos de lo que solía ser.\n\nHe pedido la evacuación de Taunka'le. Los taunka restantes deben marcharse y dirigirse hacia nuestra capital, Bruma de Hielo, situada en el Cementerio de Dragones.\n\n<Vendaval de Invierno señala al este.>\n\nTienes que poner a salvo a mi pueblo, <nombre>. Madre Tauranuk te espera a las puertas del poblado. ¡Deprisa! ¡La Plaga acecha por todos lados!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11930] = {title = "Cruzando Transborea", objective = "Escolta a los evacuados de Taunka'le a través de Transborea hasta Guerratuk Hielonato, que se encuentra en la frontera con Cementerio de Dragones.|n", description = "La ruta a través de Transborea, al este, es el único camino para llegar a Cementerio de Dragones. A medida que avances en tu viaje por la tundra te enfrentarás a numerosos peligros. Ten cuidado con la Plaga y su influencia sobre las bestias de la zona. ¡Se ha empezado a correr el rumor de que nuestros propios hermanos taunka resucitan de entre los muertos para atacar a las caravanas en su camino a Cementerio de Dragones! ¡Defiende tu caravana y pon a salvo a los evacuados!\n\nGuerratuk Hielonato te espera al otro lado del puente que lleva a Cementerio de Dragones.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][11931] = {title = "Interpretar el código", objective = "Raelorasz en el Escudo de Tránsito quiere que consigas el códice azur del inquisidor Caleras y que reúnas 3 runas fulgurantes de sus vinculahechizos de Gelidar.", description = "Siento una clara peculiaridad en estos dracos, pero el significado de las runas que cubren su cuerpo aún se me escapa.\n\nSin un códice, llevará más tiempo del que podemos permitirnos interpretarlas.\n\nNo muy lejos de aquí hay un traidor del Kirin Tor, Caleras, que seguramente tenga una copia del tomo que necesito. Sus subordinados guardan las runas que necesitaré para hacer mi traducción.\n\nDate prisa, mortal. Malygos se hace más fuerte cada momento que pasa.", progress = "Deprisa, mortal.\n\nCada minuto que pasa Malygos se hace más fuerte.", completion = "Has hecho un buen trabajo, &lt;raza&gt;.\n\nEsperemos que esto nos dé una pista de qué podemos usar contra Malygos.", rewards = "Recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][11932] = {title = "Cobardes e insensatos", objective = "Habla con Ataika en Kashala, al noreste de la Fortaleza Denuedo.", description = "Mira, <nombre>, no te ofendas, pero la operación a cuyo mando pusieron a Thassarian era un suicidio en toda regla.\n\nUn puñado de nuestros hombres iba a lanzar un ataque sobre la mayor presencia de la Plaga de la zona. Llámame loco, pero asaltar un zigurat de la Plaga a las afueras de una ciudad plagada de nerubianos con doce hombres no es la idea de diversión que yo tengo.\n\nSi aún te interesa encontrar a Thassarian, se supone que teníamos que acordar nuestro paso al este con un colmillarr llamado Ataika en Kashala, al noreste. Buena suerte con tu empresa descabellada.", progress = nil, completion = "Recuerdo a ese hombre del que hablas. Llevaba las marcas de Karkut.\n\nQue Karkut proteja a nuestros caídos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11934] = {title = "Unlocking Your Potential [PH]", objective = "Bring this dude some stuff.", description = "Today you unlock a page in your spellbook, one you may not have realized it was there.  Bring me something, and I'll open it up for you.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11935] = {title = "Robar la llama de Lunargenta", objective = "Devuelve la Llama de Lunargenta al maestro cultural del Festival.", description = "Esta llama, robada de Lunargenta, te inunda de calor. No conoces este poder tan primitivo, pero puede que el maestro cultural tenga más información...Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nEsmorc tostadoBrebaje festivo ígneoSalchicha de solsticio de veranoPan tostadoTarta de bayas de saúcoPuñado de pétalos estivales\n\nTe van a lanzar el siguiente hechizo:\n\nHas Completed all Torch Quests\n\nTambién recibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11936] = {title = "Incubando un plan", objective = "Raelorasz en el Escudo de Tránsito quiere que mates vermintes de Gelidar y uses sus hachas congeladas para romper 5 huevos de dragón Azul.", description = "Nuestro cometido es sencillo. Vamos a permanecer escondidos de la vista de Malygos, a observar a su raza y a frustrar sus intentos todo lo posible. Para ello te encargaré algo.\n\nLos azules están posando sus huevos en la base de El Nexo. La exposición a tanta energía arcana los hará salir del huevo antes. No se puede predecir el efecto que eso tendrá en las crías.\n\nNo quiero averiguarlo. Mata a los vermintes y usa sus hachas congeladas para romper los huevos.", progress = nil, completion = "Me duele tener que ordenar que se destruyan estos huevos de dragón, sean enemigos o no.\n\nQue los fines de esta guerra justifiquen los medios...", rewards = "Recibirás:\n\nObjeto #5"}
MultiLanguageQuestData['mx'][11938] = {title = "Ganar algo de tiempo", objective = "Thassarian en El Zigurat de los Lamentos en la Tundra Boreal quiere que provoques 20 bajas entre los miembros de la Plaga dentro de la Ciudad Templo de En'kilah. Usa los huesos de Escabroso si necesitas ayuda.", description = "Ahora que tenemos la filacteria no me costará mucho conseguir la información que necesito. Pero la Plaga en la Ciudad Templo no tardará en darse cuenta de que algo está ocurriendo.\n\nNo podré repeler un ataque a gran escala aquí. O quizás sí... pero prefiero no tener que averiguarlo.\n\nQuiero que te dirijas ahí abajo y causes unas cuantas muertes. Espero que eso los distraiga lo suficiente para que estos dos desembuchen... Llévate a Escabroso contigo, quizás te ayude.", progress = nil, completion = "Eso nos dará algo de tiempo. Isidorus nos ha ayudado, pero de veras necesitaba ese rato a solas con el exánime.", rewards = "Cinturón de guardián del ocasoGuantes de baño de sombrasBotas zancatundraPodrás elegir una de estas recompensas:\n\nAngustia del caballero de la Muerte\n\nTambién recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][11940] = {title = "Caza de dracos", objective = "Raelorasz quiere que uses la lanza manchada de sangre para dominar a una prole de draco de El Nexo y regreses junto a él en el Escudo de Tránsito.", description = "Necesito más proles de draco para seguir estudiando las runas que cubren sus cuerpos.\n\nSe encuentran por el extremo noroeste del valle...\n\n<Raelorasz se pincha la mano con una lanza y cubre la punta con su sangre.>\n\nCoge esto y úsalo con uno de ellos. Espera a dominarlo y luego tráelo aquí antes de que se acabe el efecto.", progress = nil, completion = "El destino de estos jóvenes dracos no debe ser una carga en tu conciencia, &lt;raza&gt;. Malygos es el único responsable de todo esto.\n\nEstoy trabajando sin descanso para revelar los secretos de esas runas.\n\nPuedes estar seguro de que no acabaremos con más vidas de las que sean necesarias.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][11941] = {title = "Juntando las piezas...", objective = "Lleva el fragmento centelleante a Raelorasz al Escudo de Tránsito.", description = "Hay algo en este pedacito de metal que te impide desecharlo.\n\nQuizás Raelorasz sepa revelar algo sobre su utilidad.", progress = "¿Qué has encontrado, <clase>?", completion = "Has hecho bien en traerme esto, &lt;nombre&gt;.\n\n\n\nSi de verdad deseas ayudarnos, sin importar el riesgo, tendré que revelarte su significado.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11942] = {title = "Palabras de poder", objective = "Thassarian en El Zigurat de los Lamentos quiere que vayas a la Ciudad Templo de En'kilah y recuperes el pergamino del sumo sacerdote Talet-Kha de la Aguja de Dolor, el pergamino del sumo sacerdote Naferset de la Aguja de Putrefacción y el pergamino del sumo sacerdote Andorath de la Aguja de Sangre.", description = "El exánime ha hablado, <nombre>. Los sumos sacerdotes de En'kilah conocen el secreto para entrar en Naxxanar.\n\nVe a la Aguja de Sangre, a la Aguja de Dolor y a la Aguja de Putrefacción y mata al sacerdote de cada una.\n\nRegresa cuando hayas conseguido los tres pergaminos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11943] = {title = "La celda", objective = "Raelorasz en el Escudo de Tránsito quiere que consigas los marcos de la prisión del general Cerulean y el núcleo de energía del belisario Goredrak.", description = "Has descubierto un fragmento de una prisión especial, <nombre>.\n\nLos esbirros de Malygos usan prisiones similares para retener a los magos que capturan y a otras entidades arcanas, pero esta prisión fue construida para contener algo... más fuerte.\n\nDebes buscar los demás fragmentos de la prisión, con la esperanza de que el enemigo de nuestro enemigo demuestre ser nuestro amigo.\n\nProbablemente los tengan los esbirros de confianza de Malygos.", progress = "¿Has encontrado algún otro fragmento de la prisión?", completion = "&lt;Los fragmentos que has conseguido comienzan a brillar en las manos de Raelorasz.&gt;\n\nYa está.\n\nSiento una fuerte presencia en esta prisión. Espero que sea un aliado.", rewards = "Recibirás:\n\nPrisión Arcana aumentada"}
MultiLanguageQuestData['mx'][11944] = {title = "¡Rodeados!", objective = "El cabo Venn en el Confín de la Muerte quiere que mates a 7 defensores del zigurat.", description = "Nuestra situación es casi desesperada. Nos ordenaron tomar El Zigurat de los Lamentos con unos cuantos hombres.\n\nTendremos suerte si podemos defender esta posición contra la Plaga. Nos superan en número, estamos heridos y no hay escapatoria.\n\nSi alivias un poco la presión, quizás podamos afianzar nuestra posición. Mata a algunos de los no-muertos que merodean alrededor de la estructura, nosotros detendremos su avance.", progress = nil, completion = "Eso nos dará algo de tiempo, &lt;nombre&gt;. Ojalá recibamos refuerzos de la Fortaleza Denuedo.", rewards = "Leotardos sofocantesGuardarrenes de caminamarismasCharreteras de cazador de llanuraCoraza de líder de batallaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][11945] = {title = "Preparándose para lo peor", objective = "Utaik quiere que reúnas 8 suministros de Kashala en Kashala.", description = "Atravesamos por momentos muy difíciles. El espíritu de Karkut camina por la tierra y reúne a los espíritus de los colmillarr fallecidos.\n\nLos hijos de la niebla han secuestrado a muchos de los nuestros. Muy pronto nuestra amada Kashala se verá reducida a cenizas.\n\nPero aún queda esperanza. Quizás no para nosotros, pero hemos enviado a nuestras familias a Unu'pe. Nosotros luchamos aquí para que así ellos tengan un futuro.\n\nNecesitarán suministros o se morirán de hambre. No queda suficiente comida en Unu'pe. Rescata cualquier suministro antes de que se haga demasiado tarde para nuestras familias.", progress = "¿Has tenido éxito, <nombre>? Nuestros parientes en Unu'pe dependen de tu éxito.", completion = "Gracias, &lt;nombre&gt;. Estos suministros alimentarán a nuestros primos e hijos. Incluso si Kashala cae, nuestras tribus podrán continuar con sus vidas.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11946] = {title = "Keristrasza", objective = "Keristrasza quiere que hables con ella cuando estés <preparado/preparada> para enfrentarte a Malygos.\n\nSi pierdes tu prisión Arcana aumentada, habla con Raelorasz en el Escudo de Transito.", description = "¿Soy... libre?\n\nEstaba destinada a pasar toda una eternidad vagando por un abismo vacío, ¿y ahora estoy salvada? No puedes hacerte una idea de mi gratitud, mortal.\n\nCuando me negué a entregarme a su voluntad, Malygos me destinó a esa prisión, y luego la hizo añicos y esparció las piezas. Aunque viva cien veces más que tú, jamás olvidaré tu gesto.\n\nQuizás, en un futuro, sepa cómo devolvértelo. Pero, por ahora, debemos poner nuestra atención sobre Malygos. Estoy débil, y queda mucho por hacer.\n\nNecesito tu ayuda, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11947] = {title = "El contraataque", objective = "Mata al teniente Granizo que invoques desde la piedra de hielo situada en Ethel Rethor en Desolace. Después, ve a ver al anciano del Anillo de la Tierra en alguna de las capitales.", description = "¡Debemos hacer algo por mantener la balanza en equilibrio! Tenemos el tiempo en contra.\n\nHay un campamento situado en la zona sombría de Ethel Rethor en la parte noroeste de Desolace. Allí usan piedras de hielo para comunicarse con los elementales, es algo similar a lo que hacen en Silithus. Aunque no me gusta nada la idea de hacer esto, sé que los espíritus lo entenderán. Tienes que invocar a alguno de esos tenientes de Ahune y acabar con él. Quizás con esta precaución sea suficiente...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11948] = {title = "El contraataque", objective = "Mata al teniente Viento Gélido que invoques desde la piedra de hielo situada en la isla de los elementales de agua en la zona oeste de Vega de Tuercespina. Después, ve a ver al anciano del Anillo de la Tierra en alguna de las capitales.", description = "¡Debemos hacer algo por mantener la balanza en equilibrio! Tenemos el tiempo en contra.\n\nHace tiempo ya que Neptulon tenía una base de operaciones en una isla en la zona oeste de Tuercespina. Allí, el Culto Crepuscular ha colocado piedras de hielo para comunicarse con los Cazamareas, algo similar a lo que hacen en Silithus. Aunque no me gusta nada la idea de hacer esto, sé que los espíritus lo entenderán. Tienes que invocar a alguno de esos tenientes de Ahune y acabar con él. Quizás con esta precaución sea suficiente...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11949] = {title = "¡No sin luchar!", objective = "Ataika quiere que mates a 12 asaltantes Kvaldir en Kashala.", description = "Kashala es un lugar sagrado para nosotros, <raza>. Nuestros ancestros fueron guiados hasta aquí por el mismísimo espíritu de Tayutka.\n\nAhora esas criaturas locas nos están atacando desde la niebla sin motivo aparente.\n\nLes vamos a demostrar que nuestras lanzas no sirven solo para cazar ballenas. Lucha junto a nosotros, <amigo/amiga>, quizás mi pueblo te devuelva el favor algún día.", progress = nil, completion = "Gracias, &lt;nombre&gt;. Me siento en deuda contigo. Te devolveré el favor si es que conseguimos salir de aquí con vida.", rewards = "Borceguíes de celliscaCinturón de correolasGuardamuñecas de interiorPodrás elegir una de estas recompensas:\n\nAnillo de colmillo del fondo del mar\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][11950] = {title = "La sabiduría de Muahit", objective = "Encuentra al anciano Muahit en Kashala.", description = "Mira, <nombre>, los guerreros como yo no son difíciles de encontrar. Si caigo, mis hermanos y primos recogerán mi lanza y lucharán.\n\nMi pueblo no puede sobrevivir sin sabios ancianos. El terco de Muahit, nuestro más venerado chamán, se niega a abandonar el altar del centro de la isla dedicado a Tayutka. Sufriríamos una enorme pérdida si esos monstruos lo mataran.\n\nTú vienes de fuera, quizás a ti te escuche. Hazle entrar en razón... pídele que huya para ponerse a salvo en Unu'pe antes de que sea demasiado tarde.", progress = nil, completion = "Te envía Ataika, ¿verdad? No me vas a convencer.\n\nNo todo está perdido. Los espíritus aún nos acompañan.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11951] = {title = "Caer en el anzuelo", objective = "Keristrasza te ha pedido que reúnas 10 fragmentos de maná cristalizado que se encuentran por Gelidar.\n\nSi pierdes tu prisión Arcana aumentada, habla con Raelorasz en el Escudo de Tránsito.", description = "Durante mi cautiverio pude aprender mucho sobre Malygos. Ahora el destino nos permite que usemos esas lecciones en su contra.\n\nExiste un gran dragón Azul, Saragosa, que vuela en círculos sobre El Nexo. Sirve tanto de guardiana del Aspecto como de su consorte. En caso de seria amenaza, avisa a su maestro del peligro.\n\nYo sufrí mucho por culpa de Saragosa durante mi cautiverio, y ahora ha llegado el momento de que muera. Pero antes debemos idear el cebo perfecto...", progress = "¿Has reunido los fragmentos de maná que necesito?", completion = "Gracias, &lt;nombre&gt;.\n\nEstoy agotada por los efectos de mi confinamiento y estoy recuperando mi fuerza muy despacio.\n\nDebo manejar el poder de estos cristales con prudencia. Son producto de la confabulación malévola de Malygos. Con un poco de suerte, contribuirán a su perdición.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11952] = {title = "El contraataque", objective = "Mata al teniente Frígido que invoques desde la piedra de hielo situada en la cueva bajo Cresta Vigía en el noroeste de La Garganta de Fuego. Después, ve a ver al anciano del Anillo de la Tierra en alguna de las capitales.", description = "¡Debemos hacer algo por mantener la balanza en equilibrio! Tenemos el tiempo en contra.\n\nLa Cresta Vigía en La Garganta de Fuego es un bastión donde el Culto Crepuscular desarrolla sus actividades. Recientemente han estado utilizando piedras de hielo en la cueva para comunicarse con los Cazamareas, algo similar a lo que hacen en Silithus. Aunque no me gusta nada la idea de hacer esto, sé que los espíritus lo entenderán. Tienes que invocar a alguno de esos tenientes de Ahune y acabar con él. Quizás con esta precaución sea suficiente...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11953] = {title = "El contraataque", objective = "Mata al teniente Glacial que invoques desde la piedra de hielo situada en el Paseo Crepúsculo en la zona norte de Silithus. Después, ve a ver al anciano del Anillo de la Tierra en alguna de las capitales.", description = "¡Debemos hacer algo por mantener la balanza en equilibrio! Tenemos el tiempo en contra.\n\nSilithus es la base que Azeroth ha establecido para el Culto Crepuscular. Al norte han estado usando nuevas piedras de hielo para comunicarse con los Cazamareas. Aunque no me gusta nada la idea de hacer esto, sé que los espíritus lo entenderán. Tienes que invocar a alguno de esos tenientes de Ahune y acabar con él. Quizás con esta precaución sea suficiente...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11954] = {title = "El contraataque", objective = "Mata al templario glacial que invoques desde la piedra de hielo situada cerca de El Portal Oscuro en la Península del Fuego Infernal. Después, ve a ver al anciano del Anillo de la Tierra en alguna de las capitales.", description = "¡Debemos hacer algo por mantener la balanza en equilibrio! Tenemos el tiempo en contra.\n\nPara asegurar el éxito de Ahune, el Culto ha establecido una base cerca del propio Portal Oscuro en Draenor. Allí utilizan piedras de hielo para organizar la llegada del Señor de la Escarcha. Aunque no me gusta nada la idea de hacer esto, sé que los espíritus lo entenderán. Tienes que invocar a alguno de esos templarios protectores de Ahune y acabar con él. Quizás con esta precaución sea suficiente...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11955] = {title = "Ahune, el Señor de la Escarcha", objective = "Viaja hasta el Recinto de los Colmillo Torcido en Marisma de Zangar y habla con Numa Nubesoror.", description = "Creo que eres suficientemente fuerte para realizar la última tarea que nos aguarda.\n\nNo podemos permitir que el Culto Crepuscular y los herejes naga de Neptulon ejecuten con éxito su conspiración. Por el bien de Azeroth y de todo lo que en él vive, debemos actuar. Nuestra trayectoria está clara. Debes viajar hasta el Recinto de los Esclavos dentro de la Reserva Colmillo Torcido y encontrarte allí con nuestro chamán. Ve, ¡y rápido!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11956] = {title = "Encuentra la filacteria", objective = "Ve hasta Confín de la Muerte y cabalga con Anochecer hasta el lugar donde se encuentra la filacteria de Tanathal. Hazte con ella y llévasela a Thassarian dentro de El Zigurat de los Lamentos.", description = "No hay tiempo para charlas, <nombre>. Me enviaron a lo que resultó ser una misión suicida para tomar este zigurat. He cumplido mi misión como soldado, ahora es el momento de obtener ciertas respuestas.\n\nEste exánime tiene la información que busco, pero no puedo infligir daño alguno a su cuerpo físico para obtenerla.\n\nEl exánime ha guardado su alma en una filacteria y mientras permanezca escondida no podré arrebatarle información alguna.\n\nVuelve al campamento y toma mi caballo, Anochecer: te llevará hasta la filacteria. Tráemela.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11957] = {title = "El final de Saragosa", objective = "Keristrasza quiere que uses el foco de poder para atraer a Saragosa y que después la derrotes.", description = "He creado este foco de poder con los cristales de maná que me trajiste.\n\nSaragosa es una glotona y no podrá resistirse a su señuelo. Contiene una magia que disminuirá enormemente su poder. Esperemos que no se dé cuenta de la trampa...\n\nPrepárate, <nombre>, y vuelve a hablar conmigo cuando estés <preparado/preparada> para hacer frente a Saragosa.\n", progress = "¡No debemos permitir que Saragosa viva!", completion = "Ahora, sin Saragosa, el mundo es un lugar mejor, pero aún no hemos terminado el trabajo.\n\n¡Ha llegado la hora de ir a por Malygos!", rewards = "Pretina endurecida al fuegoAtaduras endurecidas al fuegoLeotardos de anillas cauterizadoresPodrás elegir una de estas recompensas:\n\nFuria del draco carmesí\n\nTambién recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][11958] = {title = "No dejes que nada se eche a perder", objective = "Recupera 6 bienes Moa'ki robados de los wolvar y devuélveselos al anciano Ko'nani en el Puerto Moa'ki.", description = "Los wolvar nacieron siendo enemigos nuestros, pero la incursión de tu pueblo en el glorioso Cementerio de Dragones los ha obligado a afincarse en una pequeña zona en el claro al norte.\n\nY con el temblor de esta mañana, se han vuelto incluso más agresivos que nunca. Han realizado varios asaltos a nuestros bienes... cosas que necesitaremos si queremos sobrevivir al penoso camino desde nuestro hogar aquí.\n\nComo muestra de buena fe y amistad, recupera nuestros bienes de los wolvar de Claro Avalancha.", progress = "Últimamente la balanza natural ha estado basculando, hacia un lado, luego hacia el otro.\n\nEspero que puedas ayudarnos a sobrevivir al gran trastorno que estamos padeciendo.", completion = "No puedo decir que me encante pedirte hacer ciertas cosas en nuestro nombre. Es todo cuanto podemos hacer para preparar nuestra marcha con prontitud, aunque aún no sabemos adónde ir.\n\nMis hechiceros me dicen que estás aquí para salvar al mundo de El Que Camina por las Sombras.\n\nConfío en que salvarás también a los pueblos de esas tierras.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11959] = {title = "Mata a Loguhn", objective = "Embadúrnate con la sangre de Loguhn y vuelve junto al anciano Ko'nani en el Puerto Moa'ki.", description = "Esto ya va de mal en peor. Solo queda una manera... por desgracia, ¡Loguhn debe morir!\n\nEs el macho dominante de la tribu Claro Avalancha y un wolvar malvado. Pero es la única forma de que consigamos descansar de sus ataques y robos.\n\nEncontrarás al \"Desgarrador de carne\" en su casucha sobre la elevación septentrional del claro. Es mayor que el resto, no tiene pérdida. Mátalo y embadúrnate con su sangre para mostrar tanto tu dominio como tu respeto.", progress = nil, completion = "El honorable sacrificio de Loguhn que has realizado es exactamente lo que mi pueblo necesita. Ahora aprovecharemos al máximo la disputa de los wolvar para ocupar su lugar.\n\nEso bastará.", rewards = "Brazales de buceatiburonesGuanteletes oxidados por el marPodrás elegir una de estas recompensas:\n\nAnillo de colmillo relucienteCollera trenzada de barba de ballena\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][11960] = {title = "Pensando en el futuro", objective = "Recoge 12 cachorros de Claro Avalancha. Llévaselos al trampero Mau'i al Puerto Moa'ki.", description = "Debemos actuar con decisión contra los wolvar si queremos tener alguna opción de sobrevivir. Sin embargo, temo que en nuestro fervor, mataremos a demasiados.\n\nLos wolvar de Claro Avalancha tienen el mismo derecho que nosotros a existir. Tú y yo nos ocuparemos de que tengan esa opción.\n\nSi el anciano Ko'nani no lo ha hecho ya, te pedirá que acabes con ellos. Mientras estés ahí arriba en el claro al norte, quiero que recojas a sus cachorros y me los traigas.", progress = "¿Cuántos cachorros puedes haber salvado en tan poco tiempo?", completion = "Bueno, supongo que has salvado a muchos. Gracias, &lt;raza&gt;.\n\nAhora los wolvar tendrán una oportunidad de sobrevivir junto con nosotros. Si es que logramos sobrevivir, claro.\n\n¿Crees que podrías volver mañana para salvar a más cachorros?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11961] = {title = "Los espíritus nos protegen", objective = "El anciano Muahit en Bahía Aliento de Njord quiere que encuentres el cadáver de Iruk dentro del agua y recuperes el tótem de Issliruk.", description = "Los poderosos espíritus cuidan de mi tribu, no perderemos Kashala.\n\nIssliruk nos dará fuerzas, Tayutka se asegurará de que nuestros supervivientes siempre dispongan de comida y abrigo, y Karkut cuidará de los caídos para que no se sientan perdidos.\n\nIssliruk es a quien más necesitamos ahora mismo. Le pedí a mi sobrino, Iruk, que me trajera el tótem de Issliruk, pero cayó bajo las lanzas de los Kvaldir y su cuerpo cayó a las aguas del norte. Tráeme el tótem, <nombre>. No permitas que la muerte de mi sobrino sea en vano.", progress = "El tótem, <raza>. ¿Lo tienes?", completion = "¿Puedes sentir la presencia de Issliruk, &lt;nombre&gt;? Él no quiere que sus hijos perezcan en manos de los caminantes de la niebla.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11962] = {title = "Una última entrega", objective = "Llévale el cajón de mena de Lindeallá a Hilda Forjapiedra en la Fortaleza Denuedo.", description = "Entonces ya está. Con esa última mena que recuperaste ahora tenemos suficiente para enviar a la Fortaleza Denuedo.\n\nSi Lindeallá desaparece de la faz de Azeroth, al menos nos permitirá que nos recuerden como los primeros en defender su tierra y los últimos en rendirse.\n\nLlévale esta mena a Hilda Forjapiedra, es una buena amiga mía. Dile que fabrique unas buenas armas con esta mena. Necesitaremos muchas de ellas en los próximos días.", progress = "¿Qué tienes ahí?", completion = "¿Mena de Lindeallá? No teníamos prevista ninguna entrega aún. ¿Va todo bien?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11963] = {title = "Armas para Lindeallá", objective = "Vuelve junto a Gerald Verde en Lindeallá.", description = "¿Lindeallá está invadida y en todo lo que piensa Gerald es en enviarme mena? Ese hombre tiene tanta amabilidad como cualquiera de nuestros soldados en el frente de batalla.\n\nSi estamos dispuestos a luchar por ellos, no podemos permitir que nuestros civiles pierdan su tierra. Quizás no dispongamos de tropas para enviarles, pero sí podemos enviarles armas.\n\nEstas estaban destinadas a los nuevos reclutas, pero podré reponerlas con la mena que me has traído. Informa a Gerald de que las armas están en camino.", progress = nil, completion = "¿Hilda nos va a enviar armas? Qué buena noticia, &lt;nombre&gt;. Estaba a punto de decir a los muchachos que empezaran a hacer las maletas.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11964] = {title = "Incienso para los agostizos de verano", objective = "El maestro cultural del Festival quiere que le lleves incienso de verano a algún agostizo de verano a las afueras de cualquier asentamiento de la Alianza.", description = "¿Sabías que los fuegos del Festival arden en todo territorio en que se asienta la Alianza? Los celadores de las llamas cuidan de ellos en los campamentos situados a las afueras de las ciudades, asegurándose de que las hogueras arden para continuar con la celebración.\n\nCada celador de las llamas va acompañado de un agostizo de verano, un emisario de los elementales espíritus de fuego.\n\n¿Te gustaría honrar a un agostizo, <nombre>? Toma este incienso de verano y llévaselo a algún agostizo de verano. Apacigua al pequeño espíritu de fuego y quizás te recompense.", progress = "Fogosos saludos, honrado <clase>. Recibe mi más sincera bienvenida a este suelo sagrado del Festival de Fuego del Solsticio de Verano.", completion = "Ah, ¿qué tenemos aquí? ¡Qué aroma tan delicioso! ¡Seguro que arderá con una llama pura y viva!\n\nToma estas flores, &lt;nombre&gt;. Cógelas y déjame... Debo cuidar de este precioso combustible...", rewards = "Te van a lanzar el siguiente hechizo:\n\nDar incienso a agostizo de verano\n\nRecibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11965] = {title = "¡Llamamiento a las armas!", objective = "Ve hasta el concejo de Lindeallá y toca la campana que hay en su interior.", description = "Ahora Lindeallá tiene la oportunidad de luchar, <nombre>. Eso es todo lo que podíamos desear y tú lo has hecho posible.\n\nAhora solo necesitamos un punto de encuentro. Haré que mis hombres lleven las armas a nuestro concejo. Ve y haz sonar la campana del concejo para que los supervivientes sepan que vamos a reunirnos allí.\n\nHa llegado el momento de mostrar a la Plaga de qué estamos hechos.", progress = nil, completion = "Gracias de nuevo por ayudarnos, &lt;nombre&gt;. La gente de Lindeallá siempre te recordará.", rewards = "Podrás elegir una de estas recompensas:\n\nCadena de la campana de llamadaGargantilla de luz indómitaColgante de ideas revolucionarias\n\nTambién recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][11966] = {title = "Incienso para los agostizos del Festival", objective = "El cuentacuentos del Festival quiere que le lleves incienso de verano a algún agostizo del Festival a las afueras de cualquier asentamiento de la Horda.", description = "¿Sabías que los fuegos del Festival arden en todo territorio en que se asienta la Horda? Los vigilantes de las llamas cuidan de ellos en los campamentos situados a las afueras de las ciudades, asegurándose de que las hogueras arden para continuar con la celebración.\n\nCada vigilante de las llamas va acompañado de un agostizo del Festival, un emisario de los elementales espíritus de fuego.\n\n¿Te gustaría honrar a un agostizo, <nombre>? Toma este incienso de verano y llévaselo a algún agostizo del Festival. Apacigua al pequeño espíritu de fuego y quizás te recompense.", progress = "Fogosos saludos, honrada <clase>. Recibe mi más sincera bienvenida a este suelo sagrado del Festival de Fuego del Solsticio de Verano.", completion = "Ah, ¿qué tenemos aquí? ¡Qué aroma tan delicioso! ¡Seguro que arderá con una llama pura y viva!\n\nToma estas flores, &lt;nombre&gt;. Cógelas y déjame... Debo cuidar de este precioso combustible...", rewards = "Te van a lanzar el siguiente hechizo:\n\nDar incienso a agostizo de verano\n\nRecibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11967] = {title = "Reunir a los Rojos", objective = "Keristrasza te ha pedido que la lleves junto a Raelorasz en el Escudo de Tránsito.", description = "No hay duda de que Malygos se ha dado cuenta de que algo falla.\n\nLo conozco. Su foco está fragmentado. Estoy segura de que puedo atraerlo y sacarlo de la seguridad de su reino cuando se entere de lo que le ha ocurrido a su preciosa Saragosa.\n\nLlévame enseguida hasta Raelorasz, <nombre>. Debemos incitar a todos los dragones que lidera a que se enfrenten a Malygos.", progress = "¿Tienes noticias para mí, <nombre>?", completion = "Me han llegado noticias del rescate de Keristrasza. Permite que te elogie.\n\nEstoy ansioso por volver a hablar con ella.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11968] = {title = "Las circunstancias cambian", objective = "El anciano Muahit quiere que mates a Heigarr el Horrible en Bahía Aliento de Njord.", description = "Los espíritus han oído nuestra súplica de ayuda, <nombre>. Es un indicio de que Kashala aún puede salvarse.\n\nAprovecha la situación de confusión creada por el clima y mata al líder de los Kvaldir. Con ello, obtendremos ventaja en la batalla... estoy seguro.", progress = nil, completion = "Nos has hecho un gran favor, &lt;raza&gt;. Aún no hemos ganado la batalla, pero ahora mi gente tendrá una oportunidad.", rewards = "Trinchante para aletasMolinillo para grasa de ballenaCachava de ZookFilo de los colmillarrPodrás elegir una de estas recompensas:\n\nManual de las mareas\n\nTambién recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][11969] = {title = "Soltar la trampa", objective = "Raelorasz quiere que uses la chispa de Raelorasz en la señal de fuego de Gelidar.", description = "Debemos esta oportunidad en gran parte a tus esfuerzos, <nombre>.\n\nLo más apropiado es que tú inicies el ataque contra Malygos.\n\nToma esta chispa y úsala para encender la señal de fuego al noroeste de El Nexo. Keristrasza te dirigirá desde allí.", progress = nil, completion = "Le hemos asestado un golpe a Malygos, pero nos ha costado muy caro.", rewards = "Corvo de escamas serradoAguijón ígneoGarfa humeanteVara del guarda carmesíVoluntad carmesíCapa de escamas de llamaRecibirás:\n\nSuministros de aventura de RasganorteObjeto #1"}
MultiLanguageQuestData['mx'][11970] = {title = "El maestro en tradición de verano", objective = "Habla con el maestro cultural del Festival en cualquiera de las capitales de la Alianza.", description = "El festival es una ocasión para divertirse y reír, de eso no hay duda. Sin embargo, es importante que comprendas el origen de esta fiesta. El conocimiento se debe buscar y disfrutar.\n\nEl maestro cultural del Festival en las capitales de la Alianza podrá guiarte en dicha empresa. Ve y aprende.", progress = nil, completion = "Estaré encantado de contarte lo que sé.", rewards = "Recibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11971] = {title = "El tejedor de historias de verano", objective = "Habla con el cuentacuentos del Festival en cualquiera de las capitales de la Horda.", description = "El festival es una ocasión para divertirse y reír, de eso no hay duda. Sin embargo, es importante que comprendas el origen de esta fiesta. El conocimiento se debe buscar y disfrutar.\n\nEl cuentacuentos del Festival en las capitales de la Horda podrá guiarte en dicha empresa. Ve y aprende.", progress = nil, completion = "Estaré encantado de contarte lo que sé.", rewards = "Recibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11972] = {title = "Fragmentos de Ahune", objective = "Lleva los fragmentos de hielo a Luma Cielomater.", description = "Estos fragmentos despiden una sensación perturbadora. ¿Acaso contienen la última esencia del Señor de la Escarcha?", progress = "Saludos, <nombre>. Se te ve preocupado, pero deberías alegrarte. ¡El Señor de la Escarcha ha sido derrotado!", completion = "Sí, estos fragmentos contienen la última esencia en este mundo del Señor de la Escarcha. Nos desharemos de ellos y desterraremos a Ahune a las regiones abisales del frío.\n\nGracias, &lt;nombre&gt;. Tu nombre resonará en los cantos del Anillo de la Tierra para siempre. Haznos el honor de aceptar este vestigio, símbolo de tu parentesco con la cordialidad y la luz.", rewards = "Podrás elegir una de estas recompensas:\n\nTabardo de cielos estivalesTabardo de llamas estivales\n\nTambién recibirás:\n\nFlores ardientes"}
MultiLanguageQuestData['mx'][11973] = {title = "Prisionera de guerra", objective = "La maga de guerra Kaitlyn quiere que liberes a Keristrasza.", description = "¡Malygos ha tomado a Keristrasza para que sea su consorte!\n\nNo podemos permitir que ocurra.\n\n<raza>, debes hacer lo que sea necesario para evitar que sufra ese destino.", progress = nil, completion = "Así que ya está...\n\nLos nuestros nunca deberían olvidar el sacrificio que Keristrasza ha hecho por la causa.", rewards = "Embozo de golpes fluidosManto de KeristraszaCapa de las luces azurRecibirás:\n\n"}
MultiLanguageQuestData['mx'][11976] = {title = "Fragmentos de hielo", objective = "Lleva los fragmentos de hielo a Luma Cielomater.", description = "Estos fragmentos despiden una sensación perturbadora. ¿Acaso contienen la última esencia del Señor de la Escarcha?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11977] = {title = "Un tauren entre los taunka", objective = "Busca a la emisaria Pezuña Brillante en el Campo de Refugiados de Viento Oeste.", description = "<Guerratuk apunta hacia el noreste.>\n\nEs muy amable, ¿sabes? Si no fuera por tu emisaria, los refugiados supervivientes habrían abandonado toda esperanza. Aunque no sea taunka de nacimiento, la tribu la ha acogido hasta ahora como a una antigua vecina.\n\nSi tú eres quien yo creo, por favor, ve a visitar a la emisaria Pezuña Brillante al campo de refugiados. Te está esperando.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11978] = {title = "En el redil", objective = "La emisaria Pezuña Brillante del Campo de Refugiados de Viento Oeste, en el Cementerio de Dragones, quiere que recuperes 10 armamentos de la Horda.", description = "Antes de que podamos meter oficialmente a esos taunka en la Horda, debemos recuperar nuestro armamento de los nerubianos Anub'ar que invaden el bosque cercano. Los armamentos se perdieron cuando la Plaga tendió una emboscada sobre una caravana de Martillo de Agmar, anoche de madrugada.\n\nAdéntrate en el bosque al este del Campo de Refugiados de Viento Oeste y recupera los armamentos, <raza>.", progress = "Sin armaduras ni armas, los miembros más recientes se verán indefensos en su ruta hacia Martillo de Agmar.", completion = "¡Esto es exactamente lo que necesitamos, &lt;nombre&gt;! Al blandir las armas de la Horda, sus espíritus se regocijarán y obtendrán la protección necesaria contra la Plaga.\n\n¿Estás preparado para la ceremonia de iniciación?\n\n\n\nSerás el único en admitir a nuestros nuevos aliados en la Horda.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11979] = {title = "Los taunka y los tauren", objective = "Busca a la emisaria Pezuña Brillante en el Campo de Refugiados de Viento Oeste.|n", description = "La Plaga se ha hecho con el control de la capital de los taunka, ¡el Poblado Bruma de Hielo! Todos los taunka con vida que escaparon a la masacre están protegidos y bajo custodia en el Campo de Refugiados de Viento Oeste en la frontera oeste del Cementerio de Dragones.\n\nEl señor Grito Infernal cree que los taunka deben unirse a la Horda si quieren sobrevivir y ha enviado a una emisaria tauren a Viento Oeste para reforzar nuestros lazos con los tauren del invierno. Viaja hasta el Campo de Refugiados de Viento Oeste y busca a la emisaria Pezuña Brillante. Debes ayudarla.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11980] = {title = "Orgullo de la Horda", objective = "El guardia de sangre Roh'kill en el Campo de Refugiados de Viento Oeste en el Cementerio de Dragones quiere que mates a 15 emboscadores Anub'ar.|n", description = "Yo fui uno de los soldados elegidos para escoltar a la caravana que transportaba el envío de armamento a este campamento. El ataque fue muy rápido e imprevisto. Luchamos y matamos a decenas de bestias, pero al final resultaron ser demasiados. Tor'zin y yo apenas conseguimos salir con vida...\n\nSi no fuera por las heridas, ahora estaríamos cazando a esos desgraciados con nuestras propias manos. ¿Nos ayudarías a recuperar nuestro orgullo? Busca en el bosque al este de aquí a nerubianos Anub'ar y mátalos. ¡Por la Horda!", progress = nil, completion = "&lt;Roh'kill te saluda.&gt;\n\nNos has devuelto nuestro honor, &lt;nombre&gt;. Tanto Tor'zin como yo te agradecemos tu gesto desinteresado.", rewards = "Brazales de guardarañasCinturón de errante de claroCoraza de quitina abrasadoraQuijotes del valedor AgmarPodrás elegir una de estas recompensas:\n\nEscarabajo de Isanoth\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][11981] = {title = "¡Encuentra a Kurun!", objective = "Habla con Kurun en la colina que da a Thor Modan.", description = "La superficie de piedra del guerrero terráneo está cubierta de grietas y agujeros. Aunque no sangra, puedes sentir que el guerrero está casi muerto.\n\nUna voz deprimida y ronca escapa de la boca del guerrero moribundo.\n\n\"Encuentra a... Kurun... debes encontrar a... Kurun.\"\n\nTe mira desesperanzado mientras te preguntas quién o qué puede ser Kurun.\n\n\"Nuestro... líder... está en... la colina que da a Thor Modan... nos lidera. Por favor... dile que... no podemos tomar... la ciudad...\"Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11982] = {title = "Llueve destrucción", objective = "Kurun en la colina que da a Thor Modan quiere que interrumpas el trabajo de los enanos férreos tirando rocas al área descubierta de Thor Modan.", description = "Debajo de nosotros se encuentra el antiguo bastión de hierro, Thor Modan. Hace miles de años, los gigantes de piedra partieron la tierra en dos, haciendo que parte de la ciudad se derrumbara y dejando al descubierto el resto.\n\nIncluso ahora, los enanos férreos tratan de reclamar su antigua capital, pero no lo permitiremos. Mis gigantes llenan la trinchera de rocas y escombros con la esperanza de sellarla y matar a los sirvientes férreos mientras trabajan. Levanta las rocas que veas cerca de la trinchera al noreste para ayudarnos a poner fin a sus aspiraciones.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #5\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][11983] = {title = "El juramento de sangre de la Horda", objective = "Habla con los taunka en el Campo de Refugiados de Viento Oeste y haz que 5 de ellos juren lealtad a la Horda.\n\nDevuelve el juramento de sangre de la Horda a la emisaria Pezuña Brillante cuando hayas completado esta tarea.", description = "Están preparados, <nombre>. Todos estos taunka se unirán gustosamente a la Horda y lo darán todo para echar a la Plaga de este mundo.\n\n<Pezuña Brillante te acerca un pergamino con la insignia de la Horda.>\n\nEn este pergamino encontrarás el juramento de sangre de la Horda. La tradición dicta que nuestros nuevos hermanos y hermanas taunka pronuncien las palabras sagradas que contiene.\n\nCoge el pergamino y toma juramento a los taunka que ingresan en la Horda, comandante. Devuélveme el pergamino cuando hayas cumplido con tu deber.", progress = "Ellos harán a la Horda más fuerte, comandante.", completion = "Gracias, comandante &lt;nombre&gt;. No les quedaba nada. Tú les has brindado un propósito, y el propósito brinda esperanza... Esperanza para un futuro nuevo... para una nueva vida.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11984] = {title = "Llenar las jaulas", objective = "Samir, en el Manantial de Granito, quiere que uses la Jaula de Cazarrecompensas con un trol Drakkari que haya aturdido Budd.", description = "El viejo Budd ha visto mejores días.\n\nNo nos es útil desde que estuvimos en las Tierras Fantasma. Hemos tenido que encontrar formas para sobrevivir por nuestra cuenta, y hoy eso significa vender trols al mejor postor.\n\nPor suerte hace poco le hemos encontrado un uso a Budd. En su estado, algo le permite mezclarse con los trols locales, así que le hemos enseñado un jueguecito que nos ha dado buenos beneficios.\n\nMíralo tú mismo. Habla con Budd, llévale al suroeste hasta las Ruinas de Drak'Zin y usa esta jaula en cuanto marque a un trol.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Moledor de emancipación de reservaMutiladora de yugosPúa de anatomía renunciadaArco trinadorEspada de la mente enjauladaMaza de servidumbreRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][11985] = {title = "Abriendo brecha", objective = "Kurun en la colina que da a Thor Modan quiere que mates al Señor feudal férreo Argrum.", description = "Si no podemos derrotar a los defensores que hay en el interior de Thor Modan, los enanos férreos podrán resistir indefinidamente. Los terráneos están tomando osadamente las máquinas construidas por los hijos de hierro, pero no pueden adentrarse en la ciudad.\n\nLos túneles se estrechan demasiado rápido como para que mis compañeros gigantes puedan atravesarlos, así que nos quedan pocas opciones. ¿Querrías adentrarte en la ciudad y matar al enano que lidera la resistencia?", progress = nil, completion = "Bien hecho, &lt;nombre&gt;. La pérdida del comandante de los enanos férreos bastará para acabar con los defensores que quedan. Los terráneos deberían ahora ser capaces de encargarse de los supervivientes.", rewards = "Zapatos marcados con forjaLeotardos trizahierroCoselete probado en llamasMandiletes de temple con imperfeccionesRecibirás:\n\n"}
MultiLanguageQuestData['mx'][11986] = {title = "El diario deteriorado", objective = "Recupera 8 hojas de diario desaparecidas, completa con ellas el diario incompleto y devuélvele el diario completo a Torthen Cavahondo en el Campamento de la Brigada de los Páramos de Poniente.", description = "Este diario, muy deteriorado y lleno de barro, ha visto mejores días. Al hojear sus páginas descubres numerosas notas, diagramas y mapas.\n\nLa escritura del autor te resulta algo familiar, pero no sabes decir de quién hasta que descubres una entrada firmada como Brann Barbabronce.\n\nLa segunda mitad del libro, con las entradas más recientes, está arrancada. Las páginas inundan el campo de batalla y va a ser imposible saber lo que Brann descubrió aquí hasta que el libro vuelva a estar completo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #8"}
MultiLanguageQuestData['mx'][11987] = {title = "zzOLDFortune Card: Silver", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][11988] = {title = "La piedra angular rúnica", objective = "Lleva 5 fragmentos de piedra angular rúnica a Torthen Cavahondo al Campamento de la Brigada de los Páramos de Poniente.", description = "El diario de Brann menciona que usaba una piedra angular rúnica para iluminar las importantes runas que descubrió sobre la placa. Sin la piedra angular, no se podrán leer más que unos garabatos.\n\nAl final de la última entrada de Brann, describe cómo los defensores enanos férreos le arrebataron la piedra angular, la hicieron pedazos y se los repartieron. Para poder descifrar la placa rúnica debemos conseguir los fragmentos. Cualquiera de los enanos de Thor Modan o los edificios que lo rodean pueden tener fragmentos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11989] = {title = "¿Tregua?", objective = "Drakuru en el Manantial de Granito quiere uses el trinchante tosco junto a su jaula y que luego hables con él.", description = "Ten cuidao, <tío/tía>.\n\nDrakuru ha encogío más cabezas de <raza> de las que puedo recordar... y si lo recordara, no podría contar tantas. Po' suerte p'a ti, 'toy en e'hta jaula y no he añad'ío más a la lista.\n\nPero las cosas son como son, quizás podamos olvidar nuestra'h diferencia'h un rato, ¿eh?\n\nDrakuru se ha enter'ao de algo, algo que t'ayudará aquí en tu lucha.\n\n<Drakuru se hace un corte en la mano y te la tiende a través de las barras.>\n\nBueno, ¿qué dices, colega? ¿Hay tregua?Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][11990] = {title = "Vial de visiones", objective = "Drakuru, en el Manantial de Granito, quiere que le traigas un vial de cristal, un ejemplar de hoja de alga y 3 hojas de neblina.", description = "Lo primero es lo primero, <tío/tía>. ¡Hay preparativos que hacé'h!\n\nNo sé cuánto tiempo me van a tené'h aquí encerra'o. Tú necesitas un elixir poderoso p'a que podamos e'tar en conta'hto.\n\nPor suerte p'a ti ¡sé qué cosa é'! Y los ingrediente'h están todos cerca.\n\nNecesito un vial d'ese trol pequeñín d'ahí, una'h hojas de algas de'hl lago al no'hte d'aquí y una'h hojas de neblina qu'encontrará'h a las afuera'h del campamento.\n\nVe, deprisa, colega, antes de que me lleven d'aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11991] = {title = "Requiere interpretación", objective = "Drakuru quiere que consigas 5 muestras de mojo congelado de los trols Drakkari en las Ruinas de Drak'Zin y que luego uses el elixir en el Pedestal de Drakuru.\n\nObjeto provisto: \n", description = "Siste un legendario conjunto d'artefactos, perdidos durante años, creados p'a volver invulnerable la Fortaleza de Drak'Tharon.\n\nMuchos creen que es un mito, pero Drakuru sabe mejor...\n\n'Taba a punto de descubrir dónde había uno, pero me capturaron antes de poder terminar de interpretá' los jeroglíficos. ¡Tienes que invocá’ mi alma ahí p’a que pueda acabá’ de leeh’los!\n\nUsa mi elixir en el pedestá' en Ruinas de Drak'Zin, al suroeste de aquí. El elixir requiere algo de mojo congelado p'a funsioná'. Odio ver caer a mis hermanos, pero será p'a mejor.\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Caperuza etéreaYelmo espantoso de DrakuruYelmo de enlaces espiritualesYelmo forjado con espíritusRecibirás:\n\nObjeto #5"}
MultiLanguageQuestData['mx'][11992] = {title = "Cartas de navegación (Deprecated)", objective = "Consigue las partes que faltan de la carta de navegación de Skadir y llévaselas a Karuk en el Litoral Tralladón.", description = "Has descubierto la primera parte de una carta de navegación dibujada sobre el pellejo de un dragón. Si pudieras completarla, podrías encontrar los futuros planes de ataque de los Kvaldir.\n\nQuizás otros marineros de Tralladón tengan las partes que faltan. Seguro que a Karuk le interesará la información que contienen.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11993] = {title = "Las profecías rúnicas", objective = "Torthen Cavahondo en el Campamento de la Brigada de los Páramos de Poniente quiere que descifres las tres placas rúnicas.", description = "¡No tenemos tiempo que perder! Ahora que hemos reconstruido la piedra angular rúnica... bueno, la mayor parte, podemos descifrar el contenido de las mismas placas rúnicas con las que estaba trabajando Brann antes de huir.\n\nNo tenemos manera de saber si consiguió leer el contenido de las tres placas, pero tendremos que dar por sentado que consiguió información suficiente para determinar su próximo destino.\n\nPonte delante de las placas y utiliza la piedra angular para averiguar el contenido de cada una. ¡Brann cuenta con nosotros!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Brazales del buscarrutasMitones de descubridorBufas de eliminador de rastrosFaja de caminalíneasPodrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][11995] = {title = "Se requiere tu presencia en Reposo Estelar", objective = "Habla con la imagen de la archimaga Modera en Reposo Estelar.", description = "<clase>, sé que estos colmillarr te van a pedir muchos favores, ¡pero tienes que llegar a Reposo Estelar lo antes posible!\n\nLa agitación de la tierra de esta mañana tendrá peores repercusiones, mayores que una simple molestia para los nativos.\n\nReposo Estelar está hacia el oeste, pasada la intersección del camino que lleva al norte saliendo del puerto. Allí hay una archimaga llamada Modera. Te estará esperando.", progress = nil, completion = "Te he estado esperando, &lt;clase&gt;. Tú y yo tenemos mucho trabajo por delante.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11996] = {title = "Se requiere tu presencia en Martillo de Agmar", objective = "Habla con la imagen del archimago Aethas Atracasol en Martillo de Agmar.", description = "<clase>, sé que estos colmillarr te van a pedir muchos favores, ¡pero tienes que llegar a Martillo de Agmar lo antes posible!\n\nLa agitación de la tierra de esta mañana tendrá peores repercusiones, mayores que una simple molestia para los nativos.\n\nMartillo de Agmar está hacia el oeste, pasada la intersección del camino que lleva al norte saliendo del puerto. El mismísimo archimago Aethas Atracasol te estará esperando.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11998] = {title = "Suavizar el golpe", objective = "Lleva un barril de licor excelente a Brugar Petraescucha al Campamento de la Brigada de los Páramos de Poniente.", description = "Nuestra mejor apuesta para desplazar a nuestras fuerzas al Glaciar Corona de Hielo con rapidez depende de la red de túneles más allá de la antigua ciudad de enanos férreos de Thor Modan.\n\nBrugar Petraescucha y sus muchachos de la Liga de Expedicionarios no se van a alegrar demasiado, pero las órdenes son las órdenes.\n\nLa noticia quizás le siente algo mejor si le traes un barril de ese licor excelente que vende ese trampero Hugh Copa en Puesto de Venta de Madera Roja, al sureste de aquí bordeando la línea de árboles.\n\nEse hombre está mal de la cabeza, pero no encontrarás mejor licor que el de allí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][11999] = {title = "Saquea los cadáveres", objective = "Encuentra los planes de los Jardines Reposo Lunar y llévaselos a la imagen del archimago Aethas Atracasol en Martillo de Agmar.", description = "Los Jardines Reposo Lunar al suroeste eran el lugar de reposo final de un grupo de elfos Altonato, además de un nexo de línea Ley.\n\nEl Vuelo Azul utilizó un aparato mágico llamado aguja de flujo para destruir ese nexo, liberando el poder para desviarlo a su antojo.\n\nQuiero más información y tú me la vas a conseguir.\n\nTras la destrucción en las ruinas, los fantasmas de los Altonato se levantaron y diezmaron a la mitad de los cazadores de los magos que había allí. Ve a saquear sus cadáveres en busca de pistas.", progress = "Has vuelto. ¿Qué has descubierto?", completion = "Qué curioso, buscan un acuerdo con El Etereum. Los etéreos podrían resultar un poderoso aliado para Malygos y su locura.\n\n¡No puede ser!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12000] = {title = "Saquea los cadáveres", objective = "Encuentra los planes de los Jardines Reposo Lunar y llévaselos a la imagen de la archimaga Modera en Reposo Estelar.", description = "Los Jardines Reposo Lunar al suroeste eran el lugar de reposo final de un noble grupo de elfos Altonato, además de un nexo de línea Ley.\n\nEl Vuelo Azul utilizó un aparato mágico llamado aguja de flujo para destruir ese nexo, liberando el poder para desviarlo a su antojo.\n\nQuiero más información y espero que me la consigas.\n\nTras la agitación en las ruinas, los fantasmas de los Altonato se levantaron y diezmaron a la mitad de los cazadores de magos presentes. Ve a saquear sus cadáveres en busca de pistas.", progress = "Has vuelto. ¿Qué has descubierto?", completion = "Qué curioso, buscan un acuerdo con El Etereum. Los etéreos podrían resultar un poderoso aliado para Malygos y su locura.\n\n¡No puede ser!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12001] = {title = "zzOLDHunting Tarot: Lesser Beasts", objective = "Recoge 12 pellejos rotos y después invoca al Montero usando el tarot de caza. Los pellejos rotos solo se consiguen con bestias de nivel 5 o superior.", description = "Al mirar el naipe, la imagen se vuelve borrosa hasta que te ves a ti <mismo/misma> <cubierto/cubierta> con las pieles de muchos lobos y osos. Das por hecho que este será tu destino si invocas el poder del tarot.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12002] = {title = "Hermanos en guerra", objective = "Mata a 10 gólems de batalla rúnicos y vuelve junto a Brugar Petraescucha en el Campamento de la Brigada de los Páramos de Poniente.", description = "Espero que Gryan sepa que retiré a mis hombres de Thor Modan cuando empezó la batalla. No hay manera de que excavemos nada hasta que ese lugar recupere la normalidad.\n\nPero pareces valiente, y cuentas con la confianza de Mantorrecio.\n\nThor Modan se encuentra al noreste de aquí y la batalla entre nuestros hermanos terráneos y las creaciones de esos malditos enanos férreos aún continúa. Ayuda a nuestros hermanos a cambiar la situación y empezaré a plantearme cómo realizar ese estudio en Thor Modan.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12003] = {title = "Destapando los túneles", objective = "Brugar Petraescucha en el Campamento de la Brigada de los Páramos de Poniente quiere que explores el edificio norte, el edificio este y el edificio sur de Thor Modan.", description = "El primer lugar en el que buscaremos entradas al sistema de túneles de Thor Modan serán los edificios periféricos.\n\nCuando me iba de la excavación con mis hombres, parecía como si los enanos férreos defensores estuvieran refugiándose dentro de los edificios. Ten cuidado cuando los explores.\n\nCualquier entrada a los túneles puede ir hacia la parte trasera de los edificios. No estoy seguro de lo que cree Mantorrecio que vamos a encontrar allí, pero dudo que los enanos férreos nos faciliten la búsqueda.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12004] = {title = "Evita el acuerdo", objective = "Lleva los restos del comerciante de viento Mu'fah y las escamas de Goramosh a la imagen de la archimaga Modera en Reposo Estelar.", description = "Tenemos que matar dos pájaros de un tiro, <clase>. Tú eres el tiro.\n\nLos dos pájaros son el comerciante de viento Mu'fah y Goramosh. Deberías poder encontrarlos por la mitad oeste de los Jardines Reposo Lunar. Seguramente estén en el gran edificio de dos pisos que da al foso.\n\nTe pediré que me traigas una prueba de que han muerto, si eres tan amable.", progress = "¿Has evitado el acuerdo entre el Vuelo Azul y El Etereum?", completion = "Es una lástima que Goramosh afirmara que ya se había llegado a un acuerdo.\n\nNo obstante, son dos gusanos menos de los que preocuparnos. Pasemos a asuntos más importantes.", rewards = "Cogulla de iniciado del Kirin TorBrazales de acechador VioletaMusleras de cazador azurProtegecabezas de avizor de DalaranRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12005] = {title = "Evita el acuerdo", objective = "Lleva los restos del comerciante de viento Mu'fah y las escamas de Goramosh a la imagen del archimago Aethas Atracasol en Martillo de Agmar.", description = "Tenemos que matar dos pájaros de un tiro, <clase>. Tú eres el tiro.\n\nLos dos pájaros son el comerciante de viento Mu'fah y Goramosh. Deberías poder encontrarlos por la mitad oeste de los Jardines Reposo Lunar. Seguramente estén en el gran edificio de dos pisos que da al foso.\n\nTe pediré que me traigas una prueba de que han muerto, si eres tan amable.", progress = "¿Has evitado el acuerdo entre el Vuelo Azul y El Etereum?", completion = "Está bien, &lt;clase&gt;, ponlos en el suelo, ahí delante del trono de Agmar.\n\n\n\nEs una lástima que Goramosh afirmara que el acuerdo ya se había alcanzado.\n\nNo obstante, eso hace dos gusanos menos de los que preocuparnos. Pasemos a asuntos más importantes.", rewards = "Cogulla de iniciado del Kirin TorBrazales de acechador VioletaMusleras de cazador azurProtegecabezas de avizor de DalaranRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12006] = {title = "¡Vénganos de esa atrocidad!", objective = "Mata cualquier combinación de 15 cazadores de magos de Cementerio de Dragones, acechadores Reposo Lunar, hechiceros de Aguja de Flujo y zahorís de enfoque. Cuando lo hayas hecho, vuelve junto a Ethenial Umbraluna en los Jardines Reposo Lunar.", description = "Esos cazadores de magos llegaron aquí y destruyeron nuestro lugar de descanso.\n\nVénganos, ¡o me aseguraré de que los espíritus de los muertos invadan tu base de operaciones!", progress = nil, completion = "Muy bien, has satisfecho mi petición con creces.\n\nGracias, &lt;raza&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12007] = {title = "Es necesario hacer sacrificios", objective = "Drakuru quiere que le traigas el ojo de los profetas a su blandón de Drakuru en Zeb'Halak.\n\nTendrás que recoger mojo de Zim'Bo para usar el elixir de Drakuru allí.", description = "¡Lo tengo, colega!\n\nAl norte, sobre el zigurat de Zeb'Halak hay una cabeza de piedra con ojos de rubí. ¡Uno d'ellos es el ojo de los profetas! Tráelo al pedestá’h y bebe mi elixir.\n\nVas a volver a necesitá' mojo p'a que funcione mi elixir, esta vez del señor de la Guerra, Zim'bo. Estará escond’io en una de las cabañas de Zeb'Halak.\n\nEs una pena matá' a Zim'bo, colega, pero hizo el juramento de sangre de defendé' Drak'Tharon y ha falla'o. Ahora su mojo nos ayudará a recuperá' Drak'Tharon.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12008] = {title = "El Martillo de Agmar", objective = "Viaja hasta el Martillo de Agmar, en el Cementerio de Dragones, y habla con el señor supremo Agmar.|n", description = "Justo al este de este campo de refugiados se encuentra Martillo de Agmar, prueba del poder de la Horda en el Cementerio de Dragones.\n\nAunque no me cabe duda de que nuestros hermanos y hermanas de la Horda ya han visto el resultado de nuestro esfuerzo por atraer a los taunka a la Horda, quiero que anuncies personalmente nuestro éxito al señor supremo Agmar.\n\n¡Ve ya, <nombre>! ¡Más rápido que un rayo! ¡En marcha hacia el este, a Martillo de Agmar!\n", progress = nil, completion = "Aunque no cabe duda de que has apoyado la causa de la Horda por doquier, muchos otros han estado trabajando para propagar nuestra influencia en Rasganorte. Incluso ahora tenemos fuerzas estableciendo sus bases en los espacios congelados de estos desolados páramos.\n\nTenemos rodeada a la Plaga. La victoria se acerca a medida que nuestro ejército se aglomera a los pies de la Puerta de Cólera, Angrathar. Pronto echaremos abajo la puerta y abriremos una brecha en Corona de Hielo.\n\nPero aún queda mucho trabajo por hacer...\n\n¡Primero hay que detener a los nerubianos!", rewards = "Recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12009] = {title = "Trampas de cangrejos de Tua'kea", objective = "Reúne 8 trampas de cangrejos de Tua'kea en el Puerto Moa'ki.", description = "Con tanto problema, he perdido a mis ayudantes. Me preguntaba si tú podrías ayudarme...\n\nTengo muchas trampas de cangrejos bajo el agua del puerto. ¿Podrías recuperarlas y devolvérmelas? Estoy demasiado viejo para esas cosas y las aguas pueden ser muy peligrosas.\n\nCoge esta bombona, te ayudará a respirar mientras estés ahí abajo.", progress = "¿Cuántos cangrejos has conseguido?", completion = "Soy un simple pescador. El mundo se ha vuelto del revés de repente. Es absurdo.\n\nEspero que consigas volverlo a poner otra vez del derecho.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12010] = {title = "El destino de Orlond", objective = "Encuentra al perito Orlond en Thor Modan.", description = "Cuando empezamos a excavar la ciudad, envié al perito Orlond a comprobar la estabilidad de los túneles en Thor Modan. No le vi escapar cuando nos retiramos al principio de la batalla y me preocupa que aún esté atrapado en la ciudad.\n\nSi vamos a llevar un ejército por Thor Modan, necesitaremos la información que estaba recabando. ¡Mantorrecio y sus superiores me despellejarían si los túneles se desplomasen sobre alguna de sus brigadas!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12011] = {title = "Signos de importantes disturbios acuáticos", objective = "Informa a Tua'kea del Puerto Moa'ki acerca de la trampa de cangrejos destrozada.", description = "Parece que esta trampa de cangrejos ha sido destruida por algo mucho más grande que los tiburones que merodean la zona.\n\nQuizás deberías informar a Tua'kea, el pescador del Puerto Moa'ki.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12012] = {title = "Informa al anciano", objective = "Viaja a una capital y habla con el anciano del Anillo de la Tierra.", description = "Debemos informar a todo El Anillo de la Tierra. No sé muy bien cómo proceder, pero el anciano que te encomendó esta tarea quizás sí sepa. Por favor, vuelve a ver al anciano y entérate de cómo seguir adelante... ¡Debemos actuar!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12013] = {title = "Acaba con Arcanimus", objective = "Destruye a Arcanimus y vuelve junto a Ethenial Umbraluna en los Jardines Reposo Lunar.", description = "Queda una última cosa que querría que hicieras, <raza> <nombre>. ¡Quiero que destruyas a Arcanimus!\n\nLos hechiceros al oeste utilizaron ese enorme dispositivo desde el aire para cavar un foso gigantesco en nuestro lugar de descanso. Después, ¡soltaron a esa monstruosidad!\n\nNo me preocuparía si solo afectase a los mortales, pero Arcanimus se alimenta de los espíritus de los muertos.\n\n¡Tú vas a poner fin a eso ahora mismo!", progress = nil, completion = "Tienes mi más sincera gratitud, &lt;nombre&gt;.\n\nSi aún no lo has hecho, deberías alertar a tus superiores del peligro que el Vuelo Azul ha desatado. ¡Amenazan con destruirnos a todos haciendo estallar el eje de líneas Ley que fluye bajo los Jardines!", rewards = "Manijas desvaídasBotas de toquemuerteEspaldares de placas de cristalPodrás elegir una de estas recompensas:\n\nAnillo del más allá\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12014] = {title = "¿Duro como una piedra?", objective = "Recupera el sismógrafo portátil y úsalo para recoger lecturas de estabilidad en Thor Modan. Después, vuelve con Brugar Petraescucha en el Campamento de la Brigada de los Páramos de Poniente.", description = "Las notas de Orlond indican que llevaba consigo un instrumento llamado sismógrafo portátil, pero el aparato ha desaparecido.\n\nEl registro del estudio revela que Orlond completó todas las lecturas del túnel de Thor Modan, excepto una que llamó \"extremo oriental del túnel expuesto\".\n\nLas últimas anotaciones del registro indican que Orlond intentó refugiarse en el agua y fue atacado por los trilladores subterráneos, que debieron de llevarse su equipo. Tendrás que recuperarlo para poder realizar la última lectura.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Leotardos de minero polvorientosGuardamuñecas sucios de ectoplasmaGuardarrenes de fantasmaGuardahombros de acero de choqueRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12015] = {title = "Test Quest for Craig", objective = "Craig Amai at wherever wants you to bring him 5 whatevers.", description = "klajsdklajlsdRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12016] = {title = "El cebo", objective = "Consigue la carne de \"Dos Pinzas Enormes\" y llévasela a Tua'kea en el Puerto Moa'ki.", description = "Estoy seguro... nuestra antigua némesis acuática, Tu'u'gwar, \"El que Juega con la Comida\", ha regresado. Debemos tenderle una trampa, tú y yo.\n\nSi Tu'u'gwar tiene alguna debilidad, es su estómago. Existe una carne de la que, sin duda, no podrá pasar.\n\n\"Dos Pinzas Enormes\", la madre de todos los cangrejos, Kili'ua, ronda por su isla en las aguas al suroeste. Tienes que hacerle una visita y volver con su carne.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12017] = {title = "Carne en el anzuelo", objective = "Mata a Tu'u'gwar y luego vuelve con Tua'kea en el Puerto Moa'ki.", description = "Ha llegado el momento, <amigo/amiga>, ¡Tu'u'gwar debe morir!\n\nHe preparado la carne; sin duda la bestia acudirá una vez que pongas un cebo al anzuelo que he dejado en el agua. Debes seguir el sedal para encontrarlo.\n\nDa igual lo que ocurra, ¡no permitas que Tu'u'gwar te trague <entero/entera>, <nombre>!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Calientaorejas de pescadorGuerrera de piel de trillador Moa'kiLeotardos de buceatiburonesApisonadoras crustáceasRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12018] = {title = "Dulce venganza", objective = "Consigue dos trozos de piedra de gárgola de gárgolas carroñeras en el este de Los Campos de Carroña. Vuelve con Lord Bevis cuando termines.", description = "Sí, tú... Tienes pinta de ser de esos a quienes les va la pelea. Busco una dulce venganza contra los miembros de la Plaga que mataron a mi familia. Consígueme dos trozos de piedra de gárgola para que pueda lanzarlos al suelo y pisotearlos hasta que se queden hechos trocitos pequeñitos, chiquititos e insignificantes.\n\nSí. Ve. Mata.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12019] = {title = "Los últimos ritos", objective = "Ve hasta la Ciudad Templo de En'kilah y encuentra el orbe de teletransporte que se encuentra bajo la ciudadela flotante de la Plaga en Naxxanar. Úsalo para alcanzar el punto más alto y ayudar allí a Thassarian.", description = "Serví a Arthas en la muerte porque no tenía otra opción. Él controlaba mi voluntad y mi cuerpo. El Culto de los Malditos sirve a Arthas en vida… por voluntad propia.\n\nAhora que conocemos las palabras de poder para entrar en Naxxanar, podemos acabar con ese culto pérfido. Ve hasta En'kilah y busca el orbe de teletransporte bajo la ciudadela flotante.\n\nConsigue llegar hasta arriba y búscame en lo alto. Ármate de todo el valor que puedas, quizás no consigamos salir de esta con vida.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Hacha de muerte congeladaMachacador borealTorre de la mente infinitaBastón del mendigo resueltoFuria del dragón enfurecidoColmillo del alma desoladaRecibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12020] = {title = "Ese día que estaba borracho...", objective = "Habla con Boxey Bolahuso en el campamento de la Fiesta de la Cerveza.", description = "¡Esos Hierro Negro se han enterado de lo que vale un peine! Mientras se apresuraban a regresar hasta el Tragapenas, una parte de lo que transportaban se cayó. Pero lo más importante es que conseguiste mantener el campamento a salvo... por hoy.\n\nDirígete a Boxey y explícale tu heroico triunfo sobre los enanos Hierro Negro.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFicha para la Fiesta de la Cerveza"}
MultiLanguageQuestData['mx'][12021] = {title = "Una carta a casa", objective = "Lleva la carta a casa a Lady Alustra a Los Campos de Carroña del este.Parece que la carta va dirigida a un habitante de Ventormenta y la envía uno de los últimos pobladores de Los Campos de Carroña. Quizás a alguno de sus supervivientes en el campo este le interese hacerla llegar a su destinatario.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", description = "Parece que la carta va dirigida a un habitante de Ventormenta y la envía uno de los últimos pobladores de Los Campos de Carroña. Quizás a alguno de sus supervivientes en el campo este le interese hacerla llegar a su destinatario.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12022] = {title = "¡Traga y tira!", objective = "Utiliza la jarra de degustación de la Fiesta de la cerveza de obsequio para golpear a la G.U.A.O. 5 veces, y luego ve a hablar con Boxey Bolahuso.", description = "¡Hola! Tienes pinta de saber sujetar tu cerveza, pero, ¿sabes usar tu jarra?\n\nLos Hierro Negro han vuelto para vengarse y arruinarnos la fiesta. Lanzarles jarras es la mejor manera de detenerlos, pero primero, veamos si sabes lanzar una a esta vieja G.U.A.O. de aquí.\n\nEs fácil, busca una jarra de degustación de obsequio y toma un trago. Asegúrate de estar de frente a la G.U.A.O. Ven a verme cuando la hayas golpeado 5 veces.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFicha para la Fiesta de la Cerveza"}
MultiLanguageQuestData['mx'][12024] = {title = "Registro de los fallecidos", objective = "Busca documentos de Acuerdo de la Alianza entre los esqueletos de Campos de Carroña.", description = "Gracias por venir, <nombre>. No hemos tenido noticias de la Fortaleza de Hibergarde. Estoy segura de que aún siguen luchando contra la Plaga, pero creo que nos han dejado solos en esta matanza.\n\nTenemos que reunir los nombres de los fallecidos para que podamos notificárselo a sus familias. Cuando el ejército de la Alianza nos trajo aquí, todos tuvimos que completar un documento de acuerdo y nos pidieron que lo llevásemos encima.\n\nBusca en los cadáveres y tráeme los documentos que encuentres para poder empezar a escribir una lista con los nombres.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12025] = {title = "Un Escarlata entre nosotros", objective = "Busca pistas sobre la Cruzada Escarlata sobre los necrófagos carroñeros recién levantados en Los Campos de Carroña. Vuelve a ver a Lady Alustra con cualquier información que encuentres.", description = "Es bueno saber que no has sufrido la devastación de la Plaga. Quizás puedas echar una mano.\n\nLa Cruzada Escarlata ha tomado por la fuerza un puesto al norte con el fuerte propósito de enfrentarse a la Plaga. Lo que más me preocupa es que estaban construyéndolo antes de que nos atacaran... Debían de saber algo.\n\nNecesito saber si alguno de nuestros aldeanos estaba involucrado. Investiga entre los que fuimos resucitados como necrófagos. Si encuentras algo, tráemelo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12026] = {title = "El diario deteriorado", objective = "Recupera 8 hojas de diario desaparecidas, completa con ellas el diario incompleto y devuélvele el diario completo a la sabia Paluna en el Campamento Oneqwah.", description = "Este diario, muy deteriorado y lleno de barro, ha visto mejores días. Al hojear sus páginas descubres numerosas notas, diagramas y mapas en idioma enano.\n\nEl único texto que eres capaz de distinguir es el nombre de Brann Barbabronce garabateado al final de una de las entradas.\n\nLa segunda mitad del libro, con las entradas más recientes, está arrancada. Alguien pensaría que las notas eran lo suficientemente importantes como para intentar destrozarlas. Quizás recogiendo las páginas que faltan, esparcidas por el campo de batalla, consigas algunas pistas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #8"}
MultiLanguageQuestData['mx'][12027] = {title = "La arriesgada aventura de Floppy", objective = "Ayuda a Emily y a Floppy a volver al Campamento de la Brigada de los Páramos de Poniente.", description = "Perdone, <señor/señora>, ¿conoce el camino de vuelta al campamento de los soldados?\n\nFloppy y yo decidimos dar un paseo por el bosque, y mi hermano Walter iba a venir con nosotros, pero tenía obligaciones como escudero.\n\nAsí que Floppy y yo nos fuimos solos, pero nos perdimos, y había un montón de lobos hambrientos, pero encontramos esta torre.\n\nLos lobos se fueron, pero nosotros seguimos perdidos.\n\nLe he preguntado a Floppy, pero él no conoce el camino de vuelta. ¿Nos ayudarás? Por favor...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Cordón de cortacaminosBotas del viaje seguroMusleras de navegación infalibleBrazales del chaperónRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12028] = {title = "Visión espiritual", objective = "Habla con Toalu'u el Místico en el Puerto Moa'ki una vez que hayas alcanzado tu visión espiritual.", description = "<raza>, ¡no hemos tenido noticias de los nuestros en el Poblado Indu'le desde que la tierra tembló y se abrió!\n\n¿Nunca has participado en una misión de visión? Has superado a Loguhn, así que serás capaz.\n\nTe daré un incienso especial para que lo extiendas sobre mi blandón. Inspira profundamente sus vapores y tu espíritu viajará hasta que puedas ver lo que ocurrió en Indu'le.\n\nMientras tu espíritu vuele, podré ver lo mismo que tú.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12029] = {title = "Plaga chamuscada", objective = "Mack en Manantial de Granito quiere que uses su grog para matar a 20 trols de la Plaga famélicos en Drak'Tharon.", description = "<Hip>... Hay que quemar eshosh cadáveresh antesh de que vuelvan a eshtar shueltosh po'hr ahí.\n\nPappa shiempre decía que lo único peor que tener que matar a un trol esh tener que matar a un trol dosh vecesh.\n\nOye, <hip>... hablando de la Plaga, no podemosh llegar hashta ese trol tan bien eshcondido al norte hashta que rebajemosh un poco el número de trols.\n\n¿Qué me dicesh si te pido que te tomesh un trago de mi birra y acabesh con la misheria de esosh misherablesh?Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12030] = {title = "El ancestro Mana'loa", objective = "Habla con la estatua del ancestro Mana'loa en el Poblado Indu'le.", description = "Mi pueblo...\n\n<El místico está al borde de una crisis.>\n\nMientras tu espíritu volaba por el poblado, intuí que el ancestro Mana'loa advirtió tu presencia. <nombre>, desea hablar contigo. Nosotros reverenciamos a los ancestros de piedra como fuente de experta sabiduría.\n\nSupongo que el ancestro quiere ayudar. Búscalo en el rincón noroeste del poblado.", progress = nil, completion = "Te he estado esperando, &lt;raza&gt;. Vi volar a tu espíritu y pude sentir algo místico en tu mirada.\n\nTu destino y el de los Kalu'ak ahora están unidos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12031] = {title = "Libertad para los que padecen", objective = "Devuelve la paz a cualquier combinación de 15 pescadores Indu'le, místicos Indu'le y guerreros Indu'le y vuelve a ver al ancestro Mana'loa al Poblado Indu'le.", description = "El suelo sagrado de los ancianos elfos al oeste ha quedado destrozado. Ahora su magia está atravesando la tierra, destrozando cualquier sitio por el que fluye.\n\nLas almas de los Kalu'ak estarán en peligro mientras las fuerzas de los dragones Azules intenten controlar la magia.\n\nEl poder surgió del lago y la mayoría del poblado murió al instante. Los que sobrevivieron se volvieron locos.\n\n<nombre>, tienes que liberar a esos espíritus para que sigan adelante. Pero deja tranquilos a los vivos afectados... quizás recobren la cordura a tiempo.", progress = nil, completion = "No es una tarea muy agradable, pero sí es necesaria y compasiva.\n\nY ahora hay algo más esperándote que puedes hacer por los Kalu'ak.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12032] = {title = "Conversando con las profundidades", objective = "Reza ante La Perla de las Profundidades y haz todo lo que te indique la diosa marina Oacha'noa.\n\nSi sobrevives al penoso calvario, vuelve a ver a Toalu'u el Místico en el Puerto Moa'ki.", description = "Debemos consultar a la diosa del agua, Oacha'noa; solo ella sabrá qué destino depara a los Kalu'ak. Y solo La Perla de las Profundidades puede hacerla salir de ese abismo tenebroso.\n\nSaliendo de la costa hacia el suroeste se eleva El Pináculo Salobre. En lo alto se encuentra el altar sobre el que descansa la perla.\n\nReza ante el altar para que Oacha'noa oiga tu llamada. Haz lo que te diga para no provocar su cólera y atraiga la perdición sobre todos los colmillarr.\n\nSi sobrevives, vuelve hasta el místico.", progress = nil, completion = "¿Hablaste con Oacha'noa?\n\nSi su deseo es que permanezcamos con tu pueblo, que así sea. El ancestro Ko'nani lo aceptará como nuestro destino, sea para bien o para mal.\n\nMi pueblo cree que todas las almas se funden con la magia del mundo. ¡Tenemos que luchar contra los intentos de controlar la magia del dragón Azul o estaremos todos perdidos!\n\nNunca pensé que un &lt;raza&gt; se convertiría en el campeón de los Kalu'ak, pero queda demostrado que me equivoqué. En nombre de todo mi pueblo te doy las gracias, &lt;nombre&gt;.\n\nQue los dioses te sonrían y te mantengan a salvo.", rewards = "Bastón de guerra CongelamientoMaza de hueso de dragón talladoBastón de la bestia con púasHoja de hielo relucienteMachacatestas fríoBallesta de hierro importadaRecibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12033] = {title = "Un mensaje desde el Oeste", objective = "Lee la carta de Colmillosauro y después destrúyela.\n\nHabla con el mensajero Torvus cuando hayas terminado esta tarea.", description = "<Torvus te estrecha la mano y te extiende una carta.>\n\n<Torvus habla en voz baja.>\n\nSígueme la corriente, <nombre>.\n\n¡Qué bueno verte por aquí, soldado! No cabe duda de que el Señor Grito Infernal ha enviado a sus mejores guerreros al Señor Agmar!\n\n<Torvus habla en voz baja.>\n\nLéela y luego destrúyela en este recipiente que tengo al lado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12034] = {title = "La victoria se acerca...", objective = "Habla con el capataz primero Juktok en el Martillo de Agmar.", description = "Tan solo nos quedan dos amenazas principales que quitarnos de en medio. Una es la espantosa ciudadela de Naxxramas, al este, por encima de la Fortaleza de Hibergarde de la Alianza, y la otra, El Foso de Narjun, punto de salida de los ejércitos de no-muertos de Azjol-Nerub. Desde El Foso de Narjun es desde donde los nerubianos Anub'ar asaltaron y acabaron por arrasar el poblado taunka Bruma de Hielo.\n\nDestruiremos a los Anub'ar y bloquearemos El Foso de Narjun.\n\nInforma al capataz primero Juktok para recibir órdenes.", progress = nil, completion = "Por tierra y por aire: así es como acabaremos con la amenaza Anub'ar.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12035] = {title = "Tecnología con otro propósito", objective = "Jeremiah Hawning en Lindeallá quiere que destruyas a 5 recolectores de cosecha y que luego uses las herramientas de Jeremiah para alterar su sistema eléctrico.", description = "Vale, ¡lo tengo! Es un poco complicado alterar su sistema eléctrico, pero nada de lo que <un/una:c> <clase> tan inteligente como tú no sea capaz.\n\nCoge mis herramientas y deja a algunos de los recolectores fuera de servicio. Cuando hayan dejado de funcionar, utiliza las herramientas para conectar todos los cables rojos en los enchufes azules. Eso hará que se pongan en modo de autodefensa. Rápido, <nombre>. Dentro de poco ya nada quedará a salvo.", progress = "¿Has terminado, <nombre>?", completion = "¡Buen trabajo! Por fin me vuelvo a sentir útil... y eso ya es algo.", rewards = "Capa de obrero desgastadaBotas de caminamarismasCubremanos de La Falla OesteQuijotes de piedra de poderíoRecibirás:\n\nSuministros de aventura de RasganorteObjeto #1"}
MultiLanguageQuestData['mx'][12036] = {title = "Desde las profundidades de Azjol-Nerub", objective = "Explora El Foso de Narjun y cuéntale lo que hayas descubierto al capataz primero Juktok en Martillo de Agmar.", description = "Los nerubianos no-muertos que atacaron el Poblado Bruma de Hielo vinieron de un foso conocido como El Foso de Narjun. Si nadie lo impide, no hay duda de que esos demonios atacarán a nuestro ejército en Puerta de Cólera e imposibilitarán nuestra victoria.\n\nNecesito observación en el terreno, <nombre>. Dirígete al oeste e investiga El Foso de Narjun. ¡Tenemos que encontrar su principal punto de salida y sellarlo! Encuéntralo.\n", progress = nil, completion = "Ese maldito foso debe de estar conectado directamente con Azjol-Nerub. Esto es peor de lo que pensaba.\n\n&lt;Juktok se para a pensar.&gt;\n\nBuscar y destrozar... Ese será el siguiente paso.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12037] = {title = "Búsqueda y rescate", objective = "Mack, en el Manantial de Granito, quiere que vayas a Drak'Tharon y averigües que le ha pasado a Kurzel.", description = "Orcosh... No eshcuchan... <hip> Tú ya sabesh de lo que hablo, ¿verdad, <raza>?\n\nKurzel ha eshtado con nosotrosh variosh añosh. Pensé que se acoshtumbraría a nueshtra manera de hacer lash cosash... Atraer a esos idiotash, hacer el trabajo peligroso, deshpuesh llevarse las recompensash una vez a salvo. ¿Qué esh tan difícil de entender?\n\nPero ella no... ella she ocupa sola del ashunto. Puede que ya eshté muerta, pero me shentiría fatal si no la bushcáshemosh, y no eshtoy en forma para ir yo <hip>.\n\n¿Qué dicesh, colegui?Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nIra de KurzelAngustia de KurzelSortija de guerra de Kurzel\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12038] = {title = "Plaga chamuscada", objective = "Mack en Manantial de Granito quiere que uses su grog para matar a 30 trols de la Plaga famélicos en Drak'Tharon.", description = "¿A qué eshtásh eshperando, <clase>? Esosh trolsh infeshtadosh no she van a matar solosh...\n\nYa conocesh lash inshtruccionesh. Ve hacia Drak'Tharon por el norte...Bebe un poco de eshto y lánzashelo deshde lejosh, pod ejempdlo... <hip>. Luego shiéntate y mira cómo she queman.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12039] = {title = "Sangre negra de Yogg-Saron", objective = "Borus Doblahierro en Martillo de Agmar en el Cementerio de Dragones quiere que consigas 10 muestras de sangre negra de Yogg-Saron.", description = "Angrathar, la Puerta de Cólera... ¡Vi cómo el metal que sostenía la puerta palpitaba y ondulaba, como si estuviera vivo! En 50 años jamás he visto que el metal \"respirara\".\n\nLos únicos que sabían algo eran los colmillarr. Lo llamaban \"sangre negra de Yogg-Saron\" y me dijeron que guardara las distancias.\n\nHay una poza a las afueras del Poblado Bruma de Hielo al oeste llamado El Foso de Narjun. He oído que esa poza es muy rica en este extraño mineral. Si vas por ahí, ¿podrías conseguirme unas muestras?", progress = "¿Qué es la vida sin riesgos?", completion = "Es tan ligero... ¡como si no pesase nada! Necesitaré tiempo para analizar el metal y ver qué puedo hacer con él. ¡Pruebas! ¡Tengo que realizar pruebas!\n\nSeguiré en contacto, &lt;nombre&gt;. Si sale algo de esto, serás el primero en saberlo.", rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12040] = {title = "Un enemigo en Arthas", objective = "Kilix el Desenmarañador, en El Foso de Narjun del Cementerio de Dragones, te ha pedido que mates 6 infraseñores Anub'ar.|n", description = "Estamos sumidos en una guerra civil. En el corazón de este mundo los últimos supervivientes de mi especie luchan contra la aniquilación total. El Rey Exánime quiere controlar el reino de Azjol-Nerub cueste lo que cueste. Aquellos que se oponen son tachados de enemigos y marcados para morir.\n\nAmbos consideramos a Arthas un enemigo...\n\n¡Únete a nuestra causa y erradica la amenaza de los Anub'ar de este lugar! ¡Deja que el propio Anub'arak escuche la angustia de sus moribundos gritos!", progress = nil, completion = "Hay miles más y ocupan cada oscuro hueco de Rasganorte. Tú solo no podrás, pero juntos... Quizás...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12041] = {title = "El imperio perdido", objective = "Llévale el plan de batalla de Kilix al señor supremo Agmar en Martillo de Agmar al este.", description = "Has demostrado tu disposición a ayudar al Imperio Azjol en estos momentos de necesidad y por ello el Imperio Azjol ayudará a la Horda.\n\nDevuelve este pergamino a tu líder. Acredita las virtudes y debilidades de los nerubianos que atacan el Poblado Bruma de Hielo. Considéralo como un gesto de buena fe, como la voluntad de ayudar a tu pueblo. Utiliza la información contenida en esas páginas para aplastar a los Anub'ar y nos habrás prestado buen servicio a todos.\n\nHasta pronto, <raza>.\n", progress = "¿Qué tienes ahí?", completion = "&lt;El señor supremo Agmar mira el documento.&gt;\n\n¿Esto es lo que creo que es? Con la información de estas páginas ¡APLASTAREMOS a los Anub'ar que nos asalten!\n\nHas obrado correctamente al traerme este documento, &lt;nombre&gt;. ¡Quizás te permitamos observar o incluso participar en la batalla final de Angrathar! ¡LOK'TAR!", rewards = "Cincho de viento residualGuantes de espetadora AvalanchaAtaduras cortahieloEscarpes de senda pedregosaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12042] = {title = "Corazón de los ancestros", objective = "Drakuru quiere que vayas al punto más alto del Aserradero Cielo Azul y que encuentres el corazón de los ancestros.", description = "Secretos de las eras, ¡Revelao' ante mí!\n\n<Drakuru trata de ver a través del ojo de los profetas.>\n\nOoh, grande es mi destino, <nombre>. Tú tienes suerte de conos'erme.\n\n¡Ahí! ¡Lo veo, colega! El corazón de los ancestros. ¡Es demasia'o fácil!\n\nVas a encontrá' ese corazón cerca del cadáver d'un goblin al este d'aquí, no mu' lejos. Está arriba d'una habitación, cerca d'un río d'árboles tronchados.\n\n¡Date prisa colega antes d'que alguien má' lo encuentre!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCorazón de los ancestros"}
MultiLanguageQuestData['mx'][12043] = {title = "Defensa de Boquilla Oxidada", objective = "Mata a 12 cavadores de la Plaga y a 1 capataz del baldío en las excavaciones que rodean Reposo de Galakrond. Vuelve con Narf en el Puesto Boquilla Oxidada cuando hayas completado esta tarea.", description = "¡Tú, <clase>! Los no-muertos al sur de aquí están siendo una molestia continua para nuestro trabajo. Apártalos del camino, ¿Lo harás?", progress = nil, completion = "Ah, sí, los no-muertos. Aquí está tu premio, piérdete.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12044] = {title = "Abastecerse", objective = "Reúne 8 montones de mena de amalgama de las excavaciones que rodean Reposo de Galakrond y llévaselos a Xink en el Puesto Boquilla Oxidada.", description = "¡Hola, hola! La Plaga al sur está excavando algún tipo de cosa de dragones antigua. La verdad es que podría no interesarme por lo que estén haciendo allí, pero es que están sacando carros de mena de amalgama durante el proceso.\n\nChoriza un montón de mena de esa, seguro que me proporciona un dinerito majo para todas las armas que la Horda está haciendo.\n", progress = "¿Has conseguido la mena? Mi transportista volverá en breve... ¡Debemos sacar este envío mientras la batalla continúe!", completion = "¡Ja! ¡Ese es un buen cargamento! ¿Qué tal tu espalda, bien?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12045] = {title = "Hielo afilado", objective = "Recoge 4 montones de fragmentos de hielo de los elementales de hielo al norte y llévaselos a Zivlix en el Puesto Boquilla Oxidada.", description = "No te había visto nunca... ¿eres <nuevo/nueva> en el Vicio? Me alegro de que estés aquí, la ayuda siempre es útil.\n\nTú consigues los materiales, yo termino mi máquina, luego podremos vendérsela a esos comandantes y volver a casa ricos.\n\nYa tengo casi todos los componentes principales, así que solo necesito algunos materiales para el arma. Narf dijo que unos fragmentos de hielo afilados de esos elementales al norte serían una metralla perfecta para mis bombas. Échale el guante a algunos, ¿quieres?\n", progress = "¿Tienes los fragmentos? Ya casi he terminado con la unidad de refrigeración principal.", completion = "¡Perfecto! Son incluso más puntiagudos de lo que esperaba. Los apilaré en la nieve hasta que la bomba esté lista.\n\nVeamos, ¿qué viene ahora...?|n", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12046] = {title = "Un recubrimiento suave", objective = "Recoge 12 pellejos de animal finos de los tuneladores jormungar o de los cóndores de hueso de dragón en los aledaños del Puesto Boquilla Oxidada. Cuando hayas encontrado los pellejos, llévaselos a Zivlix.", description = "Necesito un recubrimiento nuevo para las bombas de metralla. Todo lo que tengo es demasiado duro y la metralla no se dispersa cuando explota.\n\nLo que necesitamos es un pellejo de animal bien fino. Esos tuneladores jormungar al oeste valdrán... O quizás los cóndores de hueso de dragón que hurgan entre los huesos de dragón. Tráeme lo que encuentres.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12047] = {title = "Algo que no se derrita", objective = "Busca 12 trozos de hueso astillados entre los huesos de dragón al este del Puesto Boquilla Oxidada.", description = "¡No, no, no! ¡Esos fragmentos de hielo han sido un auténtico fracaso! Se derretirán antes de que puedan llegar a hacer daño. Es la última vez que confío en lo que Narf me diga sobre materiales. Esto significa que necesitamos otra cosa completamente diferente para la metralla.\n\n¡Ya sé! Qué lista que soy. Astillas de hueso.\n\nHay huesos por allí donde los jormungar han andado royendo a fondo. Ve a hacerles una visita e intenta encontrarme algunos huesos astillados que me sirvan.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Hombreras refractivasJubón de cuero natural hiperamplificadoBotas de cadenas tensadasPodrás elegir una de estas recompensas:\n\nCondensador de truenosLubricante de armas automático\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12048] = {title = "Armamentos de la Plaga", objective = "Borus Doblahierro en Martillo de Agmar en el Cementerio de Dragones quiere que le traigas 8 armamentos de la Plaga.", description = "No puedo hacer nada con esta mena. Básicamente, no se mantiene unida. A pesar de todos mis esfuerzos, ¡el metal de la Plaga no se dobla!\n\nSi tuviera algunas muestras de armamentos forjados de la Plaga sería capaz de idear el proceso inverso de la elaboración de los objetos.\n\nEl Poblado Bruma de Hielo está plagado de nerubianos de la Plaga que llevan armaduras. ¡Ve allí y consígueme algunos armamentos de la Plaga! Con tu ayuda podría conseguir crear algo de esta mena.\n\nEncontrarás Bruma de Hielo al oeste.", progress = "<Borus tira sus herramientas al suelo.>\n\n¡Estas no sirven!", completion = "Estos están en un estado excelente, &lt;nombre&gt;. Tengo que ponerme a trabajar inmediatamente. Si sale algo de esto, ¡serás el primero en saberlo!", rewards = "Leotardos de viento residualLeotardos de espetadora AvalanchaYelmo de caparazón de Anub'arCoselete de senda pedregosaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12049] = {title = "Difícil de tragar", objective = "Lucha contra un jormungar descomunal al este del Puesto Boquilla Oxidada hasta que abra la boca y lánzale una carga explosiva potente dentro de la garganta. Recoge 6 trozos de carne de jormungar chamuscada del suelo cuando haya explotado y llévaselos a Xink.", description = "Sin lugar a dudas, sus tropas van a necesitar llenarse bien el estómago.\n\nTe contaré un secretillo que <un aprensivo/una aprensiva:r> <raza> como tú nunca sabría. Esos gusanos jormungar saben a pollo.\n\nVe a provocar a alguno de esos jormungar descomunales al este. Seguramente no puedas matar a uno a la primera, así que tírale esto a la garganta cuando abra la bocaza. Coge todos los trozos de carne que puedas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12050] = {title = "¡Más madera!", objective = "Utiliza el dispositivo de control de la trituradora de Xink para llamar a una trituradora una vez que llegues a los nidales de las arpías al norte. Reúne 50 montones de madera de los árboles de la zona y luego vuelve junto a Xink en el Puesto Boquilla Oxidada.\n\nSi pierdes el dispositivo de control de la trituradora de Xink, habla con Xink en el Puesto Boquilla Oxidada para que te dé uno nuevo.", description = "Sigamos... Necesitamos transportar madera para todas las torres que la Alianza está construyendo. Al sur hay algunos árboles no muy robustos, pero los árboles en los que las arpías están anidando al norte parecen mucho más adecuados para la construcción.\n\nCoge esto. Cuando llegues a los nidales de las arpías, usa el mando y una de mis trituradoras vendrá hasta ti. Reúne toda la madera posible. Es muy probable que a las arpías no les guste la idea de que eches abajo sus hogares... Haz lo que sea necesario.\n\n¡Marchando!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Poste para rascarse vientofríoAstilla de hueso de dragón imbuidoBastón de espinas de arpía compuestoHacha de guerra reactivaDispositivo de entrega explosivo compactoTriturahuesos montadoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12052] = {title = "¡Toma arpía!", objective = "Mata a la maestra del Viento Helado y a 15 arpías Viento Helado en las montañas al noroeste del Puesto Boquilla Oxidada. Vuelve con Narf cuando hayas completado esta tarea.\n\nSi necesitas el dispositivo de control de la trituradora de Xink, habla con Xink en el Puesto Boquilla Oxidada.", description = "<clase>, ¿has visto eso? ¡Esa es la arpía que ha estado liderando el ataque a nuestro envío de cargamentos a la puerta! Ya la he visto por la parte trasera de Altos Vientos Helados.\n\nEsas arpías ya nos han perjudicado bastante. ¡Mátalas a todas!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Banda calientarrenes milagrosaCeñidor antiexplosivos de NarfLigas de anillas dentadasCinturón de utilidad experimentalRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12053] = {title = "El poder de la Horda", objective = "El capataz primero Juktok en Martillo de Agmar en el Cementerio de Dragones quiere que utilices el confalón de batalla Grito de Guerra en el Poblado Bruma de Hielo y lo defiendas de sus atacantes.\n\nDevuelve el confalón de batalla Grito de Guerra cuando hayas terminado.", description = "Los taunka son ahora nuestros hermanos de armas. Debemos mostrar solidaridad y retomar el Poblado Bruma de Hielo.\n\nEncontrarás el Poblado Bruma de Hielo al oeste de Martillo de Agmar, al pie de las montañas. Ve hasta allí ¡y desafía a los nerubianos Anub'ar! Clava nuestro amado estandarte de la Horda en el Poblado Bruma de Hielo y acaba con todo aquel que se atreva a derribarlo.\n\n¡Haz sentir a los Anub'ar el verdadero poder de la Horda! ¡Que nuestro estandarte de guerra sea lo último que vean antes de morir!", progress = "¡Es un desafío, <nombre>!|n", completion = "¡Los hemos aplastado en tierra! ¡Pronto lo haremos en el aire!", rewards = "Manijas benditas de favoritoBotas de espetadora AvalanchaPretina de Viento OesteGuanteletes de senda pedregosaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12054] = {title = "Descifrar el diario", objective = "Llévale una ramita de aliento de espíritus a la sabia Paluna en el Campamento Oneqwah.", description = "Vor'takh tiene razón, no podemos dejar escapar esta oportunidad.\n\nPor suerte, creo que sé cómo podríamos traducir el diario de ese Brann.\n\nLos chamanes de los fúrbolgs Colmillorrojo, que se congregan en el Santuario Sangre de Corazón al suroeste del campamento, cultivan una hierba conocida como aliento de espíritus. Los místicos expertos pueden usar un incienso derivado de la hierba para obtener la sabiduría de los espíritus de sus ancestros.\n\nBusca al chamán conocido como Grumbald Monóculo. Seguro que lleva hierba para sus rezos a Ursoc.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12055] = {title = "Un extraño aparato", objective = "Lleva el extraño dispositivo de Goramosh a la imagen de la archimaga Modera en Reposo Estelar.", description = "Al recoger este extraño aparato, tienes la seguridad de que tiene cierta naturaleza mágica. Pero no parece tener ninguna otra utilidad.\n\nQuizás la archimaga de Reposo Estelar al este de los Jardines Reposo Lunar pueda decirnos para qué sirve.", progress = "¿Qué tienes ahí?", completion = "&lt;nombre&gt;, si no me equivoco, ¡has descifrado la clave que nos permitirá averiguar exactamente qué se traen entre manos las fuerzas de los cazadores de magos!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12056] = {title = "Marcado para morir: Sumo cultor Zangus", objective = "Mata al Sumo cultor Zangus y lleva la cabeza del Sumo cultor Zangus al capitán Gort en el Martillo de Agmar en el Cementerio de Dragones.", description = "¡Yo mismo fui testigo de su traición! Ese traidor dirigió un asalto Anub'ar sobre este fuerte, y se llevó a algunos de mis mejores soldados.\n\n<Gort sacude la cabeza.>\n\n¡Estuvo trabajando con la Plaga todo el tiempo y no teníamos ni idea! ¿Cuántos más como Zangus existen? Los encontraremos a todos y cuando lo hagamos...\n\n<Gort hace como si se cortara el cuello de un lado al otro.>\n\nEl primero de la lista es Zangus. Nuestros exploradores nos han informado de que se esconde en el Foso de Narjun, al oeste de aquí. Encuéntralo, mátalo, tráeme su cabeza.\n", progress = "¿Eso que llevas es una cabeza de orco cortada o tan solo te alegras de verme?", completion = "&lt;Gort levanta la cabeza y mira a los ojos sin vida.&gt;\n\nTe dije que te cogería...\n\nAquí está tu recompensa, &lt;clase&gt;. Ya tenemos un dolor de cabeza menos.|n", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12057] = {title = "El escrito encuadernado en carne", objective = "Devuelve el escrito encuadernado en carne al capitán Gort del Martillo de Agmar.", description = "El escrito está encuadernado con carne y parece estar sangrando. Cuando lo examinas, descubres que todas las páginas están llenas de extraños símbolos que parecen estar escritos con sangre.\n\nLa información contenida en las páginas de este libro tiene que ser importante. Devuélveselo al capitán Gort en Martillo de Agmar al este del Poblado Bruma de Hielo.", progress = "<Gort levanta una ceja.>", completion = "&lt;Gort coge el escrito.&gt;\n\nSalvajes... encuadernado con carne de orco... Este idioma... Nunca se ha podido demostrar su existencia. Es el idioma de la muerte... El idioma de la Plaga.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12058] = {title = "Las profecías rúnicas", objective = "La sabia Paluna en el Campamento Oneqwah quiere que descifres las tres placas rúnicas.", description = "El diario de Brann también contenía una guía de símbolos de los enanos férreos. He inscrito algunos en una piedra angular que te ayudará a comprender las palabras inscritas sobre las placas rúnicas.\n\nPor las anotaciones del diario parece que Brann ha estado buscando pruebas sobre los orígenes de su pueblo. Mantén los ojos bien abiertos ante cualquier pista que nos indique su destino.\n\nVuelve a Thor Modan, ponte delante de las placas y utiliza la piedra angular para averiguar el contenido de cada una. No podemos permitir que la Alianza la encuentre primero.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Brazales del buscarrutasMitones de descubridorBufas de eliminador de rastrosFaja de caminalíneasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12059] = {title = "Un extraño aparato", objective = "Lleva el extraño dispositivo de Goramosh a la imagen del archimago Aethas Atracasol a Martillo de Agmar.", description = "Al recoger este extraño aparato, tienes la seguridad de que tiene cierta naturaleza mágica. Pero no parece tener ninguna otra utilidad.\n\nQuizás el archimago de Martillo de Agmar al noreste de los Jardines Reposo Lunar pueda decirnos para qué sirve.", progress = "¿Qué tienes ahí?", completion = "&lt;nombre&gt;, si no me equivoco, ¡has descifrado la clave que nos permitirá averiguar exactamente qué se traen entre manos las fuerzas de los cazadores de magos!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12060] = {title = "Proyecciones y planos", objective = "Acércate y observa la proyección en la cumbre de la Aguja de Flujo que hay flotando sobre los Jardines Reposo Lunar.\n\nLuego vuelve hasta la imagen de la archimaga Modera en Reposo Estelar con la información.", description = "Este aparato sirve para teletransportarse. Me atrevería a decir que lleva hasta la plataforma de la Aguja de Flujo que hay sobre los Jardines Reposo Lunar al oeste.\n\nNecesito que lo uses para investigar lo que está ocurriendo ahí arriba. Parece que funciona en ambos sentidos así que no tendrás que bajar de un salto.\n\nEspero que una vez que te teletransportes a la Aguja de Flujo haya algún tipo de aparato con el que puedas observar.\n\nPodrás usar el teletransportador desde cualquier punto dentro de los jardines.", progress = nil, completion = "Eso que describes... ¡es una proyección del Arcanomicón!\n\n&lt;Rápidamente, el archimago oculta su preocupación tras un rostro impasible.&gt;\n\nEl Arcanomicón es un mapa de todas las intersecciones de líneas Ley mágicas del mundo. El Vuelo Azul lo ha estado usando para encontrar y destruir los \"pilares principales\" de líneas Ley para devolver el poder mágico a El Nexo.\n\nLa cuestión es: ¿por qué dirigir un sendero de destrucción tal hacia el este cuando debería dirigirse hacia el oeste?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12061] = {title = "Proyecciones y planos", objective = "Acércate y observa la proyección en la cumbre de la Aguja de Flujo que hay flotando sobre los Jardines Reposo Lunar.\n\nLuego vuelve hasta la imagen del archimago Aethas Atracasol en Martillo de Agmar con la información.", description = "Este aparato sirve para teletransportarse. Me atrevería a decir que lleva hasta la plataforma de la Aguja de Flujo que hay sobre los Jardines Reposo Lunar al suroeste.\n\n<nombre>, necesito que lo uses para investigar lo que está ocurriendo ahí arriba. Parece que funciona en ambos sentidos así que no tendrás que bajar de un salto.\n\nEspero que una vez que te teletransportes a la Aguja de Flujo haya algún tipo de aparato con el que puedas observar.\n\nPodrás usar el teletransportador desde cualquier punto dentro de los jardines.", progress = nil, completion = "Eso que describes... ¡es una proyección del Arcanomicón!\n\n&lt;Rápidamente, el archimago oculta su preocupación tras un rostro impasible.&gt;\n\nEl Arcanomicón es un mapa de todas las intersecciones de líneas Ley mágicas del mundo. El Vuelo Azul lo ha estado usando para encontrar y destruir los \"pilares principales\" de líneas Ley para devolver el poder mágico a El Nexo.\n\nLa cuestión es: ¿por qué dirigir un sendero de destrucción tal hacia el este cuando debería dirigirse hacia el oeste?", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12062] = {title = "Insulta a Coren Cerveza Temible", objective = "Habla con Coren Cerveza Temible.", description = "Coren Cerveza Temible está en la sala de al lado, enardeciendo a los enanos Hierro Negro para un nuevo ataque a la Fiesta de la cerveza. ¡Derrótalo!\n\nVe hasta Coren y provócale. Dile que su cerveza no es ni para los cerdos.\n\nCuando lo hagas, prepárate para luchar. Al último que se burló de su cerveza... lo echaron de comer a los jabalíes.Cuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][12063] = {title = "Fuerza de Bruma de Hielo", objective = "Encuentra a Banthok Bruma de Hielo en el Poblado Bruma de Hielo.", description = "<La abuela Bruma de Hielo se inclina.>\n\nEs un honor conocerte, <héroe/heroína>. Si muchos de nosotros estamos aquí, vivos y preparados para luchar contra la Plaga, te lo debemos a ti.\n\nHas hecho tanto por nosotros que me avergüenza volver a solicitar tu ayuda. A pesar de mis súplicas, Banthok, mi único hijo, se fue de aquí en busca de su padre, el gran jefe Bruma de Hielo. La última vez que alguien lo vio se dirigía al oeste, hacia el Poblado Bruma de Hielo. Por favor, encuentra a Banthok. No sé qué haría si perdiese a mi hijo.", progress = nil, completion = "¡Mi padre aún vive! ¡Tenemos que salvarlo! No puedo hacerlo solo, &lt;raza&gt;, ¡tienes que ayudarme!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12064] = {title = "Las cadenas de los Anub'ar", objective = "Banthok Bruma de Hielo en el Poblado Bruma de Hielo en el Cementerio de Dragones te ha pedido que le traigas el fragmento de la llave de Anok'ra, el fragmento de la llave de Tivax y el fragmento de la llave de Sinok.|n", description = "Tienen a mi padre atado con cadenas mágicas en medio del Poblado Bruma de Hielo. Por la información que he conseguido reunir, la prisión está controlada por tres poderosos magi Anub'ar. Cada uno posee una pieza de la llave.\n\nPeina Bruma de Hielo y encuentra a los magi. Mátalos y hazte con los fragmentos de la llave. Con las tres piezas podremos liberar a mi padre. Cuando esté libre...\n\nLlegará tu recompensa.", progress = "¡Tráeme esos fragmentos!", completion = "Sí, esto servirá.\n\n&lt;Banthok manipula con manos expertas los fragmentos de la llave.&gt;\n\nAquí está, &lt;clase&gt;. Con esta llave, mi padre podrá salir de la prisión de los Anub'ar.", rewards = "Espaldares de viento residualEspaldares de espetadora AvalanchaGuardahombros de caparazón de Anub'arEspaldares de senda pedregosaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12065] = {title = "El foco de la playa", objective = "Consigue el anillo de control de foco de línea Ley y úsalo para conseguir información del foco de línea Ley en la Orilla Resplandeciente.\n\nLuego, vuelve con la imagen de la archimaga Modera en Reposo Estelar.", description = "Las fuerzas de magos cazadores están actuando en la Orilla Resplandeciente, al sur de los Jardines Reposo Lunar. Apuesto a que te encontrarás con un foco muy bien vigilado en la playa y al capitán que está al cargo.\n\nSin duda alguna el capitán guardará consigo algún tipo de mando de control. Consíguelo y úsalo sobre el foco.\n\nCon suerte, obtendremos más información sobre lo que están tramando.", progress = nil, completion = "Qué extraño que grabara esta información sobre ti por medio de la magia.\n\nBueno, entonces no solo sabemos que han canalizado el flujo de poder que salía de los Jardines Reposo Lunar, sino que también lo están modificando de alguna manera. Pero, ¿qué quieren hacer con toda esa magia?\n\nEsto se está poniendo feo, &lt;nombre&gt;. No me gusta, ¡ni un pelo!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12066] = {title = "El foco de la playa", objective = "Consigue el anillo de control de foco de línea Ley y úsalo para conseguir información del foco de línea Ley en la Orilla Resplandeciente.\n\nLuego, vuelve con la imagen del archimago Aethas Atracasol en Martillo de Agmar.", description = "Los cazadores de magos están actuando en la Orilla Resplandeciente al sur de los Jardines Reposo Lunar. Apuesto a que te encontrarás con un foco muy bien vigilado en la playa y al capitán que está al cargo.\n\nSin duda alguna el capitán del ejército guardará consigo algún tipo de mando de control. Consíguelo y úsalo sobre el foco.\n\nSi eres lo suficientemente hábil, obtendremos más información sobre lo que están tramando.", progress = nil, completion = "Qué extraño que grabara esta información sobre ti por medio de la magia.\n\nBueno, entonces no solo sabemos que han canalizado el flujo de poder que salía de los Jardines Reposo Lunar, sino que también lo están modificando de alguna manera. Pero, ¿qué quieren hacer con toda esa magia?\n\nEsto se está poniendo feo, &lt;nombre&gt;.", rewards = "Te van a lanzar el siguiente hechizo:\n\nThe Focus on the Beach: Quest Complete\n\nRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12067] = {title = "Una carta para casa", objective = "Lleva la carta de la capitana Malin a la comandante Saia Aceroazur a Reposo Estelar.", description = "Encuentras una carta ocultada en el forro de sus ropas. Dice así:\n\n\"Padre,\n\nSiento haber desaparecido sin darte noticias. Si estás leyendo esta carta es porque he muerto.\n\nMe han obligado a trabajar para el ejército de Malygos amenazando con matar a mi familia si me negaba. Me siento tan avergonzada...\n\nSi hay algo que puedas hacer para luchar contra ellos, no te preocupes por mí. Los he engañado y los estoy saboteando desde dentro.\n\n¡Te quiero, papá!\n\nEm\"\n\n¡Seguro que la comandante Saia Aceroazur quiere ver esto!", progress = "¿Una carta para mí?\n\n<La comandante estudia tu expresión durante un momento.>\n\nSupongo que no... deben de ser malas noticias.", completion = "Ah, no... y te enviamos ahí para matarla, ¿verdad?\n\n&lt;La comandante mueve la cabeza suspirando.&gt;\n\nLo siento. Me encargaré de que su padre, el archimago Malin de Ventormenta, reciba la carta inmediatamente. No te preocupes, no tendrá consecuencias sobre ti... no fue culpa tuya.\n\nIntenta olvidarlo. No había manera posible de que lo supieras, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12068] = {title = "Voces entre las ruinas", objective = "Drakuru quiere que reúnas las tablillas Drakkari de las Ruinas de Drakil'jin y 5 muestras de mojo sacro de los oráculos y protectores Drakkari. Después tendrás que utilizar el elixir de Drakuru en el pedestal de Drakuru en las ruinas para invocar su imagen.", description = "<Drakuru se coloca el ojo de los profetas sobre la frente y el corazón de los ancestros sobre el pecho.>\n\nE'tamos cerca, colega, ¡muy cerca!\n\nLas tablillas Drakkari son to' lo que queda po' encontrar. Nadie sabe ni su edá' ni lo que dicen, pero con el ojo y el corazón Drakuru puede lee'hlas. E'htán dentro de la cripta de Drakil'jin, al este d'aquí.\n\nCuando tengas las tablillas, es necesario que tomes mojo de los oráculos y protectores p'a invocarme allí. E'tarán orgullosos de morí' por la causa.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Hombreras menudasYelmo de humo crecienteBotas rompeplanosMusleras forjadas con espíritusPodrás elegir una de estas recompensas:\n\nCuentas del espíritu vengativo\n\nTambién recibirás:\n\nSuministros de aventura de RasganorteObjeto #5"}
MultiLanguageQuestData['mx'][12069] = {title = "El regreso del Gran Jefe", objective = "Libera al gran jefe Bruma de Hielo utilizando la llave de la prisión Anub'ar y ayúdale a derrotar al infrarrey Anub'et'kan.\n\nRecupera un fragmento del caparazón de Anub'et'kan y devuélveselo al señor supremo Agmar en Martillo de Agmar en el Cementerio de Dragones.", description = "<Banthok te da la llave de la prisión.>\n\nTienes que darte prisa, <nombre>. Coge la llave y úsala para liberar a mi padre de la prisión Anub'ar. Cuando sea libre, ayúdale a acabar con el líder Anub'ar, el infrarrey Anub'et'kan. Cuando el infrarrey esté muerto, coge de su caparazón un fragmento como trofeo para presentar ante la Horda en Martillo de Agmar. ¡Muéstrale a Agmar el poder del Gran Jefe!", progress = "¿Qué ocurre, <nombre>? Estoy muy ocupado.", completion = "Eres un valeroso &lt;clase&gt;, &lt;nombre&gt;. Has hecho un gran favor a la Horda rescatando al Gran Jefe.", rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12070] = {title = "Alentando a las tropas", objective = "Utiliza el fragmento de la Tierra para alentar a los gigantes de las Colinas Pardas que luchan en las Colinas Pedrusco, mata a cualquier enano férreo que se enfrente a ti y luego ve a informar a Kurun a la colina que da a Thor Modan.", description = "Los hijos de hierro se han servido de sus runas para esclavizar a muchos de mis hermanos y los están utilizando para romper el asedio de Thor Modan. Desearía no tener que luchar contra ellos, pero no tenemos opción.\n\nMis gigantes no resistirán mucho más.\n\nHe imbuido este fragmento de la Tierra con una bendición que ayudará a nuestros aliados. Llévalo contigo a la batalla en las Colinas Pedrusco al norte, y úsalo para dar confianza y fuerza a mis hermanos.\n\nMata a cualquier enano férreo que se interponga en tu camino.", progress = nil, completion = "Has dado a nuestros aliados la fuerza para continuar luchando y por ello te doy las gracias. Sin embargo, debemos comenzar a idear una manera de poner fin a esta batalla antes de que nos ganen ventaja.", rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12071] = {title = "¡Ataque aéreo!", objective = "Habla con Valnok Furia del Viento en el Martillo de Agmar.", description = "¡Ahora que ya conocen el poder en tierra de la Horda, deben sentir su poder desde el aire! ¡Quiero que te presentes ante Valnok Furia del Viento inmediatamente! Lo encontrarás aquí, en el Martillo de Agmar.\n\nValnok ya ha sido informado acerca de tu misión y te está esperando.\n", progress = nil, completion = "&lt;Valnok saluda.&gt;\n\nAsí que tú eres el que está armando tanto revuelo, ¿eh?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12072] = {title = "¡Malditas bestias de añublo!", objective = "Usa la pistola de bengalas de Valnok para llamar a un jinete de guerra Kor'kron en el Poblado Bruma de Hielo. Monta sobre el jinete de guerra Kor'kron y úsalo para matar a 25 bestias de añublo Anub'ar.\n\nSi completas esta misión, vuelve junto a Valnok Furia del Viento en el Martillo de Agmar.", description = "Sin duda habrás visto el ejército de bestias de añublo Anub'ar que se está formando en el Poblado Bruma de Hielo. Los Anub'ar planean enviar a esos monstruos para enfrentarse a nuestros soldados en la Puerta de Cólera. ¡No podemos permitirlo!\n\nAventúrate en el Poblado Bruma de Hielo con esta pistola de bengalas y úsala para llamar a uno de mis jinetes de guerra. Monta sobre su lomo y ordénale que destruya a las bestias de añublo que están fuera de alcance desde tierra.\n\n¡Cuando hayas diezmado sus fuerzas aéreas, vuelve a verme para recoger tu recompensa!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Brazales de viento residualBrazales de errante de claroCoselete de hueso petrificadoPodrás elegir una de estas recompensas:\n\nObjeto #1Collera de necrófago de la Plaga\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12073] = {title = "Golpear el hierro", objective = "Mata a 10 enanos férreos que defienden Thor Modan y vuelve al Campamento Oneqwah para informar al explorador Vor'takh.", description = "La Alianza no es nuestra única fuerza enemiga en las Colinas Pardas. Los enanos férreos mantienen un fuerte control en la costa este, aunque Thor Modan, al noreste, está sitiado por gigantes de piedra.\n\nUn buen guerrero utiliza la debilidad de su enemigo como arma y seríamos tontos si ignorásemos la vulnerabilidad de los enanos férreos en Thor Modan. No tengas piedad con los enanos férreos. Mata a todo aquel que se interponga en tu camino.\n\nLos \"hijos del hierro\" aprenderán a temer a la Horda.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12074] = {title = "Un aliado muy oportuno", objective = "Habla con Kurun en la colina que da a Thor Modan.", description = "La antigua capital enana de Thor Modan, al noreste, se encuentra bajo el asedio de una misteriosa banda de gigantes de piedra y terráneos.\n\nLa razón por la que las creaciones de los titanes luchan unas contra otras escapa a mi entendimiento y al interés de la Horda, pero ha surgido una oportunidad de debilitar a un enemigo mutuo.\n\nVe hasta Thor Modan y busca a ese tal \"Kurun\" que lidera a los gigantes y a los terráneos. Acordad una misma causa y sírvete de su ejército para aplastar a los enanos férreos.", progress = nil, completion = "&lt;Te presentas a Kurun.&gt;\n\n¿Así que los férreos son también enemigos suyos?\n\nMi ejército tiene a los enanos férreos bien sujetos dentro de su ciudad, pero podríamos aceptar ayuda para adelantar el ataque. ¿Nos ayudarás?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12075] = {title = "Pocos restos", objective = "Consigue una muestra de carne de roca del cadáver del gigante de hielo de la entrada a la caverna en el Vicio de Cristal, al norte del emplazamiento de Zort. Cuando hayas hecho esto, vuelve junto a Zort, cerca del centro del cañón.", description = "Hace frío por aquí, ¿verdad, <raza>? \n\nKo'char se ha negado a recibirme. Parece que tiene cosas más urgentes en las que pensar... Concretamente, los jormungar los han estado atacando desde la caverna de abajo. Quizás puedas ayudarme a convencer a Ko'char de que soy de los buenos.\n\nVi cómo algunos de los gusanos a la entrada de la caverna al norte de aquí se comían a un gigante... Aún estoy conmocionado por la facilidad con la que esos gusanos los están matando. Tráeme una muestra de una de sus heridas.", progress = "¿Así que has vuelto con mi muestra? Me alegro de que el frío no te venciera.", completion = "Esto es perfecto. Gracias, &lt;clase&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12076] = {title = "Negocios sucios", objective = "Recoge 2 viales de flema corrosiva de los jormungar utilizando la rasqueta en ti. Lleva los viales a Zort en el Vicio de Cristal cuando hayas terminado.", description = "Incluso a simple vista la muestra que me has traído es una prueba evidente de algún tipo de flema corrosiva. Sería natural pensar que la misma sustancia que esos gusanos utilizan para cavar el suelo les ha otorgado un arma formidable contra los gigantes de hielo.\n\nToma esta rasqueta y lucha contra alguno de los gusanos. Cuando te escupan, utiliza la rasqueta para retirarla y tráemela.\n\nConsígueme un par de muestras, voy a tener que usarla como base para un elixir.", progress = "Parece que aún te quedan unas flemas sobre el hombro, <raza>. Ten cuidado o te corroerá a través de la armadura.", completion = "Aún están frescas... Dame un minuto y mezclaré esto con el resto del elixir que he preparado.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12077] = {title = "Aplicar dos veces al día", objective = "Ofrécele a Ko'char el Irrompible el elixir que ha preparado Zort.", description = "Este elixir debería proteger de su saliva. Ofréceselo a Ko'char de mi parte, ¿vale? Dile que le conseguiré mucho más si me devuelve el favor.", progress = "Supongo que lo que quiere ese pigmeo es que luchemos por él. Mira mi cara de sorpresa.", completion = "Seré sincero, pequeña. No me fío de esta mezcla y no la usaré. Guárdala... Si te fías más de ese pigmeo verde que yo, quizás te sea de ayuda.", rewards = "Recibirás:\n\nElixir protector de Zort"}
MultiLanguageQuestData['mx'][12078] = {title = "Retador de gusanos", objective = "Entra en las cavernas del Vicio de Cristal y captura a 3 engendros jormungar dentro de cajones robustos. ¡No te olvides de recoger los cajones cuando los engendros jormungar estén bien atrapados dentro!\n\nLlévale los engendros jormungar a Zort en el Vicio de Cristal.", description = "Está bien. Si los gigantes no vienen a ayudarnos, quizás podamos usar estos gusanos. Seguro que hay algunos engendros junto a su madre de camada en la caverna de abajo. Toma esta caja, captura tres engendros y tráemelos.\n\nCuando la diplomacia falla, la esclavitud es una alternativa de lo más aceptable.", progress = "¡Has regresado! ¿Tienes las bestias? Tengo que salir de aquí... Seguro que Ko'char ha intentado pisarme hace unos minutos.", completion = "Estos servirán. Quizás cuando estas bestias hayan crecido del todo, las llevaré para presentárselas personalmente a los gigantes.\n\nPor si quieres saber mi opinión, no son más que un montón de rocas inútiles.", rewards = "Recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12079] = {title = "Territorio preferido", objective = "Adéntrate en la caverna al extremo norte del Vicio de Cristal y mata a 8 alimentadores jormungar Corazón de Hielo para Ko'char el Irrompible.", description = "Saludos <pequeño/pequeña>. No sé qué clase de locura te ha hecho venir al Vicio de Cristal, pero te doy la bienvenida.\n\nEsos gusanos de hielo... esos jormungar le han cogido el gusto a comerse a mis hermanos. Dudo que mi gente te parezca amigable en estos tiempos de guerra, pero si has venido para ayudar con los gusanos, tienes toda mi atención.\n\nSi queremos recuperar la caverna, primero tendremos que limpiar el cañón de alimentadores jormungar. ¡Únete a la batalla, <raza>!", progress = nil, completion = "Una satisfactoria muestra de matanza.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12080] = {title = "Un gusano muy grande", objective = "Entra en la Caverna Corazón de Hielo y mata a Cascabore. Si aún está en tu posesión, asegúrate de usar el elixir protector de Zort para protegerte de la flema corrosiva de jormungar. \n\nVuelve a ver a Ko'char el Irrompible en el Vicio de Cristal cuando hayas completado la tarea.", description = "La madre reproductiva de los jormungar vive en las cavernas de debajo. La llamamos Cascabore, un nombre que le otorgó una aventurera de las Tierras de la Peste. Solo la vi durante un segundo, mientras intentaba rechazar su primer ataque: es lo suficientemente grande como para devorarme de un bocado. La caverna no será nuestra hasta que la echemos de ella.", progress = nil, completion = "Así que está muerta. Como deber ser. Has demostrado que tus intenciones son más nobles que las del cachorro.\n\nAtravesando el cañón del norte encontrarás el Bosque Canto de Cristal, un lugar maldito y peligroso, &lt;raza&gt;. Si te diriges hacia allí, ten cuidado.\n\nToma esto por tus esfuerzos, pequeña, y abandona esta tierra de conflictos con mi bendición.", rewards = "Ataduras de jormungar finasLeotardos del destripador de CascaboreCoselete Corazón de HieloMusleras de placas de cristalRecibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12081] = {title = "Gavrock", objective = "Habla con Gavrock en las Ruinas de Tethys.", description = "Sin tu ayuda no habríamos sido capaces de dar ese giro radical a la batalla de Thor Modan. Esta antigua ciudad ha sido durante mucho tiempo el campo de batalla para las fuerzas de tierra y piedra. Solo espero que la hayamos silenciado de manera definitiva.\n\nLos enanos férreos siguen pudiendo usar su magia para capturar y esclavizar a mis hermanos. Gavrock está buscando la manera de liberar a los gigantes con runas. Búscalo por un pequeño grupo de islas llamado las Ruinas de Tethys, saliendo de la zona central de la Costa Viento del Este hacia el sur.", progress = nil, completion = "Sé que Kurun te agradece tu ayuda. La derrota de Thor Modan será un gran logro para nosotros, pero no liberará a nuestros hermanos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12082] = {title = "¡Tralarí, tralará!", objective = "Escolta a Harrison de las Ruinas de Drakil'jin, después habla con Harkor en el Campamento de Harkor.", description = "Escucha, <chico/chica>. Este no es lugar para que andes jugando.\n\nYo voy a intentar largarme. Quédate conmigo y te sacaré de aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Sandalias de escape rápidoGuanteletes de cuero enrolladoGuardamuñecas sobrehiladosFaja de maestroRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12083] = {title = "En lo alto del bosque", objective = "Consigue el amuleto de control de foco de línea Ley del Bosque Lothalor.\n\nDespués, vuelve con la imagen de la archimaga Modera en Reposo Estelar.", description = "Tengo la convicción de que debe de haber más de uno de esos focos canalizando la energía de las líneas Ley, uno detrás del otro. Pero aún no sabemos con precisión qué están haciendo con todo ese poder.\n\nSeguro que encuentras otro foco en lo alto del Bosque Lothalor al sureste. Una vez más, deberás encontrar a la persona al cargo y hacerte con cualquiera que sea el mando de control que guardan, porque estoy segura de que cada foco tiene uno.\n\nTen cuidado, <nombre>, ese bosque es muy peligroso.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Zapatos de iniciado del Kirin TorHombreras de acechador VioletaManoplas de cazador azurGuardabrazos de avizor de DalaranRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12084] = {title = "En lo alto del bosque", objective = "Consigue el amuleto de control de foco de línea Ley y úsalo para obtener información sobre el foco de línea Ley en el Bosque Lothalor.\n\nDespués, vuelve con la imagen del archimago Aethas Atracasol en Martillo de Agmar.", description = "Tengo la convicción de que debe de haber más de uno de esos focos canalizando la energía de las líneas Ley, uno detrás del otro. Pero aún no sabemos con precisión qué están haciendo con todo ese poder.\n\nSeguro que encuentras otro foco en lo alto del Bosque Lothalor al sur. Una vez más, deberás encontrar a la persona al cargo y hacerte con cualquiera que sea el mando de control que guardan, porque seguro que cada foco tiene uno.\n\nActúa rápido, <clase>. Presiento que el tiempo se acaba.", progress = nil, completion = "¿Están usándolo para dar más poder a su ejército? No tiene sentido, los cazadores de magos no son tan poderosos.\n\nEsto tiene que significar que solo usan la magia en el punto final del lugar al que están canalizando la línea Ley.\n\n¡Vamos a necesitar más información si tengo que idear un plan para detenerlos!", rewards = "Zapatos de iniciado del Kirin TorHombreras de acechador VioletaManoplas de cazador azurGuardabrazos de avizor de DalaranTe van a lanzar el siguiente hechizo:\n\nAtop the Woodlands: Quest Complete\n\nRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12085] = {title = "Una carta para casa", objective = "Entrega la carta del teniente Ta'zinni al señor supremo Agmar en Martillo de Agmar.", description = "Encuentras una carta ocultada en el forro de sus ropas. Dice así:\n\n\"Deino,\n\nTa'zinni siente haber desaparecido sin darte noticias. Si estás leyendo esta carta es porque he muerto.\n\nMe han obligado a trabajar para el ejército de Malygos amenazando con matar a mi familia si me negaba. ¡Ta'zinni no podía permitirlo!\n\nNo te preocupes por mí, solo mantén a tus hijos a salvo. Los he engañado y los estoy saboteando desde dentro.\n\n¡Te quiero, hermana!\n\nTa'zinni\"\n\n¡Seguro que el señor supremo Agmar quiere ver esto!", progress = "¿Qué es esto? ¿Acaso pretendes enviar una carta?\n\nTodo el correo debe pasar por mí antes. ¡Hay espías y traidores entre nosotros!\n\n<El Señor Supremo te mira de arriba abajo y tú te preguntas si va a ordenar que te maten ahí mismo.>\n\nMuy bien, seré rápido. Pero si no me gusta lo que leo, voy a darte de comer a mis huargos.\n\n<Agmar sonríe malévolamente mientras Gar'mak y Lak'tuk se vuelven y te imaginan como su próximo almuerzo.>", completion = "Aajajaja... buuu, uuh, qué tierno.\n\n&lt;La condescendencia en la risa del Señor Supremo queda patente.&gt;\n\n¿Qué dije? ¡Traidores! Aunque es verdad que conocí a Deino. ¡Ella al menos es una trol con honor!\n\nMe encargaré de que se entere de lo que le ocurrió a su hermano. Incluso olvidaré decirle que fuiste tú quien lo mató.\n\n&lt;Agmar te dirige una mirada insistente.&gt;\n\n¡Pero ahora me perteneces, &lt;clase&gt;!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12086] = {title = "El hijo de Karkut", objective = "Ve al Confín de la Muerte, pasando Unu'pe.", description = "El hombre que buscas se marchó hacia el este, a un lugar cercano a la costa llamado Confín de la Muerte, pasando Unu'pe.\n\nTen cuidado si vas en su búsqueda, <nombre>, llevaba la marca de Karkut... aquel que vela por los muertos.", progress = nil, completion = "¿Thassarian? Sí, estuvo aquí... ¿qué ocurre? Ahora mismo tenemos problemas mucho más importantes, amigo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12087] = {title = "¿Un poco de ayuda? DEPRECATED", objective = "El cabo Venn en el Confín de la Muerte quiere que mates a 8 defensores del zigurat.", description = "Nos enviaron aquí para apoderarnos del Zigurat Aullante, situado al norte. No esperábamos volver con vida... Demonios, ya hemos perdido a la mitad de nuestros hombres.\n\nThassarian estaba en primera fila de fuego... y los superiores, bueno, había algo que no les gustaba de él.\n\nSalió esta mañana... quizás se haya ido solo hasta el zigurat. Pero ahora mismo tenemos problemas más importantes de los que preocuparnos. La Plaga sigue acercándose al campamento, tenemos que encargarnos de ellos... ¡de inmediato!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12088] = {title = "Thassarian, el caballero de la Muerte", objective = "Busca a Thassarian dentro de El Zigurat de los Lamentos, al norte de Confín de la Muerte.", description = "Bueno, <nombre>, nos has ayudado... así que supongo que deberíamos ayudarte a ti también.\n\n¿Estás buscando a Thassarian? Ha desaparecido esta mañana. Creemos que fue hacia el norte, al Zigurat de los Lamentos. Si no hubiéramos luchado codo con codo, pensaría que es un traidor.\n\nYa sabes, es un caballero de la Muerte... y sé que están de nuestro lado y eso... pero no hace demasiado eran siervos de Arthas.\n\nPero Thassarian no, él es un buen tipo. Ve al Zigurat de los Lamentos a ver si está bien.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12089] = {title = "SE BUSCA: Magister Keldonus", objective = "Mata al magister Keldonus y ve a ver al capitán Gort al Martillo de Agmar en el Cementerio de Dragones.", description = "Por orden del señor supremo Agmar:\n\nObjetivo: Magister Keldonus\n\nCrimen: Traición\n\nEstado: vivo\n\nMagister Keldonus, otrora comandante mago en Martillo de Agmar, debe ser asesinado en nombre de la Horda en caso de ser visto.\n\nKeldonus fue visto por última vez viajando hacia el suroeste, hacia los Jardines Reposo Lunar, para unirse al Vuelo Azul en su campaña contra la magia.\n\nEl acercamiento ha de realizarse con precaución, pues Keldonus es un mago poderoso.\n\nTodas las recompensas corren a cargo del capitán Gort en el Martillo de Agmar.", progress = nil, completion = "No es el primero de esos hechiceros cobardes en traicionarnos, y seguro que tampoco será el último. Pero qué pena también... Era uno de nuestros mejores magos. Podía invocar un buffet que te hacía la boca agua y a tu corazón dar brincos de alegría...\n\n¡BUÁ!", rewards = "Robustez del depositario de hechizosFilo de hechizo perdido de KeldonusTornadorsalesRifle de MatamagosTerror del magisterBrutalizador manchado de sangreRecibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12090] = {title = "SE BUSCA: Gigantauro", objective = "Mata a Gigantauro y vuelve a ver al capitán Gort al Martillo de Agmar en el Cementerio de Dragones.|n", description = "Por orden del señor supremo Agmar:\n\nObjetivo: Gigantauro\n\nCrimen: Ataques a la Horda; \"ser feo\"\n\nEstado: vivo\n\nSe busca al señor magnatauro, Gigantauro, por una serie de ataques a soldados e instalaciones de la Horda en el Cementerio de Dragones.\n\nLa última vez que fue visto, Gigantauro caminaba por los bosques y carreteras del sur, al sureste del Martillo de Agmar.\n\nDebería considerarse que Gigantauro está armado y es extremadamente peligroso.\n\nTodas las recompensas corren a cargo del capitán Gort en el Martillo de Agmar.", progress = nil, completion = "Mataste a ese hijo de víbora, ¿eh? Bien, nuestros soldados tendrán una cosa menos de la que preocuparse en esos Baldíos Helados.", rewards = "Capa de ensalmador del caosBrazales de caminabosques LothalarGuanteletes cazacrestasLeotardos de magnatauro de placasRecibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12091] = {title = "SE BUSCA: Garra Temible", objective = "Mata a Garra Temible y vuelve a ver al capitán Gort al Martillo de Agmar en el Cementerio de Dragones.", description = "Por orden del señor supremo Agmar:\n\nObjetivo: Garra Temible\n\nCrimen: Ataques a la Horda\n\nEstado: vivo\n\nSe busca a Garra Temible por numerosos ataques a caravanas de la Horda que viajaban hacia y desde Rencor Venenoso.\n\nGarra Temible habita en una cima con vistas al Santuario de Dragones Rubí, al este del Martillo de Agmar. El acercamiento ha de realizarse con extremada precaución.\n\nTodas las recompensas corren a cargo del capitán Gort en el Martillo de Agmar.", progress = nil, completion = "¡Ya era hora de que alguien pusiera fin a la racha de matanzas de esa inmunda bestia! Bien hecho, &lt;nombre&gt;.", rewards = "Plumas del Baldío del DragónSobrehombros de caminabosques LothalarCoselete cazacretasAgarre de Garra TemibleRecibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12092] = {title = "Devuelve la fuerza a los ancestros", objective = "Usa la corteza de los caminantes para devolver la fuerza a 3 ancestros Lothalor y luego vuelve con Sarendryana en Reposo Estelar.", description = "No solo los de tu raza se han visto afectados por lo que han hecho las fuerzas del Vuelo Azul, sino también los ancestros del Bosque Lothalor al sureste.\n\nAlgunos están corruptos (evítalos a toda costa) pero muchos aún pueden salvarse. Sin embargo, los antárboles del bosque parecen ser inmunes a la magia que se filtra por la tierra y las vermis arcanas que han resultado de ella.\n\nPide a los antárboles su corteza y alimenta con ella a los ancestros. Esperemos que eso baste para salvarlos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Brazales de furia de la naturalezaCinturón de caminabosques LothalarBotines de Reposo EstelarEspaldares cubiertos de cortezaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12093] = {title = "Runas de coacción", objective = "Gavrock en las Ruinas de Tethys quiere que neutralices las cuatro runas de coacción. Para ello tendrás que derrotar al sobrestante Durval, al sobrestante Korgan, al sobrestante Lochli y al sobrestante Brunon.", description = "Al mismo tiempo que Kurun ataca Thor Modan, los enanos férreos están empleando su magia contra nuestros hermanos. Invocándolos desde la tierra y luego sujetándolos con runas, los hijos de hierro los obligan a luchar contra los hijos de piedra.\n\nA lo largo de toda la Costa Viento del Este utilizan las runas de coacción para enviar a sus gigantes esclavizados a los campos de batalla que hay al norte.\n\nEncuentra las cuatro runas de coacción y obliga a sus sobrestantes a mostrarse. Aparecerán cuando derrotes a los tejerrunas que controlan cada runa. Sin los sobrestantes, las runas son inútiles.", progress = nil, completion = "Bien. Ahora, debemos actuar sin dilación antes de que los hijos de hierro se den cuenta de que hemos anulado el poder dañino de sus runas.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12094] = {title = "Poder latente", objective = "Carga el Fragmento de Gavrock en la primera piedra antigua, la segunda piedra antigua y la tercera piedra antigua, después regresa con Gavrock en las Ruinas de Tethys.", description = "Mientras las runas de compulsión sigan dormidas, existirá la posibilidad de que liberemos a los gigantes con runas.\n\nTe daré un trozo de piedra que ha formado parte de mí desde mi creación. Si se imbuye adecuadamente, puede utilizarse para liberar a los gigantes.\n\nDos antiguas señales de piedra descansan sobre lugares de poder entre la Senda de Hierro y el linde del bosque, lugares que tu gente llamaría intersección de líneas Ley. La otra está en una isla en el borde sur de estas ruinas. Carga el fragmento en cada piedra y vuelve.", progress = "¿Has encontrado las antiguas piedras?", completion = "Puedo detectar el poder con el que has imbuido al fragmento y espero que sea suficiente para romper la magia rúnica.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12095] = {title = "A Caída del Dragón", objective = "Habla con Rokhan en Caída del Dragón en el Cementerio de Dragones.", description = "Al este de aquí, en el corazón del Cementerio de Dragones, existe un campo lleno de huesos de dragón y nieve. La Plaga ha establecido numerosos campamentos en la tundra central y están criando vermis de escarcha para lanzarlas contra nuestras fuerzas en la Puerta de Cólera. Aunque para Rokhan y sus cazadores de dragones es fácil librarse de la mayoría de esas vermis de escarcha, una está siendo especialmente problemática.\n\nVe al noreste y busca a Rokhan en Caída del Dragón. Ayuda a Rokhan y a sus hombres a acabar con Sarathstra ¡y recibirás una recompensa generosa!", progress = nil, completion = "¿Qué te hasía pensá que tú lo conseguiría'h cuando Rokhan no lo consiguió?", rewards = "Recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12096] = {title = "Devuelve la fuerza a los ancestros", objective = "Utiliza la corteza de los caminantes para devolver la fuerza a 3 ancestros Lothalor y vuelve con el celador de la tierra Grife en Martillo de Agmar.", description = "Los ancestros del Bosque Lothalor al sur están siendo corrompidos por las vermis arcanas... ¡Vermis que han surgido de la tierra!\n\nLos que ya están corruptos son mortales y no nos sirven, pero muchos aún pueden salvarse. Por suerte, los antárboles del bosque parecen ser inmunes a todo aquello.\n\nPide a los antárboles su corteza y alimenta con ella a los ancestros. Eso debería devolverles la fuerza.\n\n¡Ahora déjame ocuparme de mis asuntos! Tengo que estar pendiente de esos boticarios.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Brazales de furia de la naturalezaCinturón de caminabosques LothalarBotines de Reposo EstelarEspaldares cubiertos de cortezaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12097] = {title = "Sarathstra, Plaga del norte", objective = "Habla con Rokhan para atraer a la vermis de escarcha Sarathstra.\n\nMata a Sarathstra y lleva el corazón congelado de Sarathstra al capitán Gort en Martillo de Agmar.", description = "Mis cazadores eh'tán muertos o congelados, <nombre>. ¿Aún quieres haceh'lo? Solo pronuncia la palabra y llamaré al dragón otra vez.\n\nSi lo matas, lleva el corazón helado de la beh'tia a Martillo de Agmar y dáselo a Gort. Seguro que te recompensa, <tío/tía>.", progress = "<Gort levanta una ceja.>\n\n¿De vuelta tan pronto?", completion = "¡JA! ¡Lo has conseguido! ¡Los soldados en Puerta de Cólera están en deuda contigo, &lt;nombre&gt;! Seguro que para muchos de ellos esto supondrá un día más de vida.", rewards = "Envoltura de destrucción vigorosaEslabones de Persecución rectaCinturón de Purificación vengativaFaja de aniquilación forzadaRecibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12098] = {title = "Busca por el Poblado Indu'le", objective = "Busca al comandante de las fuerzas de cazadores de magos en el Poblado Indu'le y en el Lago Indu'le.", description = "Estoy segura de que encontrarás el próximo foco de línea Ley en alguna parte entre los restos del Poblado Indu'le al sureste. El problema es que no teníamos ninguna información de que hubiera uno allí.\n\nNecesito que busques por el poblado algún indicio del foco o de los cazadores de magos y de su comandante en la zona.\n\nBusca también por el lago si fuera necesario.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12099] = {title = "Por fin libres", objective = "Utiliza el romperrunas de Gavrock para liberar a 4 gigantes con runas y luego vuelve junto a Gavrock en las Ruinas de Tethys.", description = "El trozo de roca que has imbuido debería ser lo bastante poderoso como para romper la magia rúnica que retiene a mis hermanos.\n\nLlévatelo contigo y encuentra a los gigantes con runas caminando por la Playa Viento Este. Libera el poder de la piedra y observa los resultados.\n\nSi funciona, los gigantes con runas deberían volver en sí mismos y parar de obedecer a los enanos férreos. Si la piedra no funciona, puede que los gigantes te ataquen debilitados. Pero, ¿qué otra opción tenemos? Si no lo intentamos, seguirán esclavizados sin esperanza.", progress = nil, completion = "Así que no es algo seguro. Desearía que la suerte no tuviera nada que ver, pero al menos estamos en el buen camino. Sin tu ayuda esto nunca habría sido posible. Si descubres algo más sobre las maquinaciones de los enanos férreos y sus planes hacia los hijos de la piedra, búscanos, &lt;nombre&gt;, y te escucharemos.", rewards = "Rama de espíritu vagabundoGarfa de LibertadHoja de liberadorFrancotirador de lazoAguja de reflexión voladoraPodrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12100] = {title = "Contener la putrefacción", objective = "Soar Furia de Halcón en Martillo de Agmar en el Cementerio de Dragones quiere que mates a 15 ejemplares de fauna infectada y recuperes un órgano resistente a la putrefacción.", description = "La Plaga supone muerte y enfermedad. Solemos dar por hecho que la vida salvaje de una zona infestada por la Plaga acaba por destruirse o por pudrirse e infestarse.\n\nPara la mayoría de las bestias indígenas del Cementerio de Dragones ya es demasiado tarde. La enfermedad degenerativa que la Plaga trae consigo ya ha contagiado a las bestias y ahora están rabiosas y en estado de putrefacción.\n\nDebes aventurarte hacia el oeste, hacia el Foso de Narjun, y matar a las criaturas infestadas. Busca en sus cadáveres algún órgano sano, necesitamos uno para elaborar una vacuna.", progress = "Mata a las bestias para evitar que se propague y tráeme un órgano resistente a la putrefacción.", completion = "Me duele tener que matar a los animales, pero tenemos esa obligación. Ahora debemos dar el siguiente paso: la inoculación.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12101] = {title = "El buen doctor...", objective = "Entrega el órgano resistente a la putrefacción al doctor Sintar Malefious en Martillo de Agmar.|n", description = "Nuestros aliados Renegados han enviado a sus principales boticarios para ayudarnos a acabar con la Plaga en la Puerta de Cólera. Uno de ellos, el doctor Sintar Malefious, es experto en la putrefacción de la Plaga y en los métodos para contener el contagio. Acordamos concebir una vacuna para la fauna salvaje. Desde entonces, ha estado esperando el órgano.\n\nEntrega este órgano resistente a la putrefacción al doctor Malefious e infórmale de que vas de mi parte. Él te indicará tu próxima tarea.", progress = "¿Y ahora qué?", completion = "¿De veras que ese hombre vaca lerdo consiguió un órgano resistente a la putrefacción? Maldición... estaba seguro de que esa tarea mantendría a ese cabeza de chorlito ocupado durante el próximo milenio.\n\nBueno, dámelo, chico, tengo mucho que hacer y no quiero que tus míseras necesidades se interpongan en mi camino.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12102] = {title = "En busca de la lila de color rubí", objective = "El doctor Sintar Malefious en Martillo de Agmar en el Cementerio de Dragones quiere que consigas una lila de color rubí.", description = "Qué curioso que el Santuario de Dragones Rubí esté justo al este de aquí. Allí es donde encontrarás una flor llamada lila de color rubí. Esta flor vigorosa es todo lo que necesito para preparar una vacuna para las bestias sanas de esta zona.\n\nViaja hacia el este y busca lilas por el Santuario de Dragones Rubí.\n\nUna cosa más: en este santuario de dragones, al igual que en el resto de santuarios de dragones de estos malditos baldíos, amenaza la Plaga. Ten cuidado. No estaría bien que te devorara alguna vermis de brasas.\n\n<Sintar se ríe>.", progress = "¿Tienes la lila de color rubí?", completion = "No fue tan difícil, ¿verdad que no?\n\nAhora dame un segundo para preparar la vacuna.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12104] = {title = "Regresa junto a Soar", objective = "Entrega la vacuna de Sintar a Soar Furia de Halcón en Martillo de Agmar.", description = "<El doctor Malefious te entrega un vial lleno de líquido turbio.>\n\nPues aquí lo tienes, <raza>. Llévale esto a esa arpía y dile que ya he pagado todas mis deudas. Oficialmente, estamos en paz.\n\nAhora déjame antes de que te eche a Jennings.", progress = "¿Has conseguido la vacuna?", completion = "&lt;Soar levanta el vial y examina su contenido.&gt;\n\nAhora solo queda una cosa más.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12105] = {title = "Descenso a la oscuridad", objective = "Llévale el diario de Mikhail al teniente Dumont en el Refugio Pino Ámbar.", description = "El diario fue escrito por un habitante de Arroyoplata llamado Mikhail. En él, detalla la llegada de un grupo de cultores sombríos llamado el \"culto del lobo\".\n\nAl principio, los habitantes se negaron a acoger el culto, pero poco a poco empezaron a surgir simpatizantes entre los ciudadanos.\n\nPreocupado, Mikhail mandó a su hija Sasha lejos de Arroyoplata mientras intentaba hacer entrar en razón al resto de ciudadanos.\n\nLas últimas anotaciones de Mikhail mencionan una reunión entre líderes locales para tratar sobre ciertos acontecimientos en la Mina Piedrahueca.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Caperuza abandonadaChaleco de minero desechadoEspaldares de trampero con remiendosApisonadoras de cuevas oxidadasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12106] = {title = "Busca por el Poblado Indu'le", objective = "Busca al comandante de las fuerzas de cazadores de magos en el Poblado Indu'le y en el Lago Indu'le.", description = "Seguro que encontrarás el próximo foco de línea Ley en alguna parte entre los restos del Poblado Indu'le al sureste. El problema es que no teníamos ninguna información de que hubiera uno allí.\n\nNecesito que busques por el poblado algún indicio del foco o de los cazadores de magos y de su comandante en la zona.\n\nBusca también por el lago si fuera necesario.", progress = nil, completion = "Encuentras el cadáver del comandante de los cazadores de magos.\n\nA juzgar por su apariencia, y por las condiciones en las que está el ejército a su alrededor, no debieron de ahogarse solamente. Más bien, cuando invocaron el foco hacia sí, no se esperaban que los elementales surgieran de las profundidades del lago para atacar.\n\nParece que los cazadores de magos fueron los causantes de su propia muerte.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12107] = {title = "El final de la línea", objective = "Utiliza el talismán de control de foco de línea Ley para obtener información del foco de línea Ley bajo el Lago Indu'le. Después, dirígete al este hasta el Santuario de Dragones Azur cerca del sur central del Cementerio de Dragones y observa lo que está ocurriendo desde el extremo oeste.\n\nLuego, vuelve junto a la imagen de la archimaga Modera en Reposo Estelar.", description = "En sus ropas encuentras dos objetos interesantes.\n\nUno es un talismán que, sin duda alguna, sirve de dispositivo de control de foco. El otro es una serie de órdenes de alguien llamado Sidragos. Las órdenes van dirigidas al líder en los Jardines Reposo Lunar.\n\nEl pergamino empapado informa a Goramosh de que debe desplazar a todas las fuerzas de cazadores de magos al este hasta el Santuario de Dragones Azur.\n\nQuizás deberías llevarte toda la información que puedas del foco y dirigirte al este para observar el santuario desde su lado oeste.", progress = nil, completion = "¿¡QUÉ!?\n\n&lt;La imagen que tienes ante ti se distorsiona por un segundo mientras la archimaga intenta recuperar la calma.&gt;\n\nClaro, tendríamos que haber adivinado que eso era lo que han estado haciendo todo este tiempo. Rápido, no hay tiempo que perder.\n\n¡Debemos alertar en Reposo del Dragón!", rewards = "Bastón del ensalmador LeyChafarote desechado de DaschalMaza del guardián violetaGarra imbuida de manáPodrás elegir una de estas recompensas:\n\nEscrito de la Torre Violeta\n\nTambién recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12109] = {title = "Informa a Gryan Mantorrecio... otra vez", objective = "Habla con el capitán Gryan Mantorrecio en el Campamento de la Brigada de los Páramos de Poniente.", description = "Enviamos a los chicos de los Páramos de Poniente a buscar un camino que llevase hasta las tierras del norte. Su segundo objetivo es asegurar puntos estratégicos de recursos, así que seguro que no les importará investigar alguna mina.\n\nBusca el Campamento de la Brigada de los Páramos de Poniente al noreste y busca a Gryan Mantorrecio. Si has pasado por los Páramos de Poniente alguna vez, seguro que te acuerdas de él. Dile que yo te envío.\n\nSe alegrará de que reclames una mina operativa para el rey.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12110] = {title = "El final de la línea", objective = "Utiliza el talismán de control de foco de línea Ley para obtener información del foco de línea Ley bajo el Lago Indu'le. Después, dirígete al este hasta el Santuario de Dragones Azur cerca del sur central del Cementerio de Dragones y observa lo que está ocurriendo desde el extremo oeste.\n\nLuego, vuelve junto a la imagen del archimago Aethas Atracasol en Martillo de Agmar.", description = "En sus ropas encuentras dos objetos interesantes.\n\nUno es un talismán que, sin duda alguna, sirve de dispositivo de control de foco. El otro es una serie de órdenes de alguien llamado Sidragos. Las órdenes van dirigidas al líder en los Jardines Reposo Lunar.\n\nEl frágil pergamino empapado informa a Goramosh de que debe desplazar a todas las fuerzas de cazadores de magos al este hasta el Santuario de Dragones Azur.\n\nQuizás deberías llevarte toda la información que puedas del foco y dirigirte al este para observar el santuario desde su lado oeste.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Bastón del ensalmador LeyChafarote desechado de DaschalMaza del guardián violetaGarra imbuida de manáPodrás elegir una de estas recompensas:\n\nEscrito de la Torre Violeta\n\nTe van a lanzar el siguiente hechizo:\n\nThe End of the Line: Quest Complete\n\nTambién recibirás:\n\nSuministros de aventura de RasganorteObjeto #1"}
MultiLanguageQuestData['mx'][12111] = {title = "Donde vagan las cosas salvajes", objective = "Soar Furia de Halcón en Martillo de Agmar en el Cementerio de Dragones quiere que uses el paquete de vacunas para vacunar a 5 alces de avalancha y a 5 pardos árticos.", description = "Dentro de este paquete hay varios viales que contienen la vacuna que Sintar creó. Ahora quiero que busques alces de avalancha y pardos árticos por el bosque cercano. Cuando localices a los animales, ponte a una distancia segura y lanza un vial hacia ellos. El vial se romperá, liberando un pequeño gas que actuará como agente inoculador. Para que las bestias queden vacunadas, y se salven, solo tienen que entrar en el área del gas.\n\nInocula todas las bestias que puedas y luego vuelve aquí.\n", progress = nil, completion = "Has realizado un gesto digno de honra, &lt;nombre&gt;. Elige una recompensa.", rewards = "Bastón de madera de rubíBáculo de los Jardines Reposo LunarCorvo de los bosques cortanteGarrote Viento Helado con pinchosTriturador de magnatauro desgastado por la batallaBallesta de forestal duroPodrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12112] = {title = "Negociaciones difíciles", objective = "Encuentra a Zort en el centro del Vicio de Cristal al noreste del Puesto Boquilla Oxidada.", description = "Bueno, parece que al final fuiste útil. No conocí a casi <ningún/ninguna> <raza> que lo fuera.\n\nYa no te necesitamos por aquí. Dirígete al Vicio y pregúntale a mi hermano Zort si podrías echar una mano. Fue a ver si podía convencer a los gigantes que dieran sus vidas para que nosotros no tuviéramos que hacerlo. Sin duda, no se lo conocía por ser el más inteligente de la familia.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12113] = {title = "Encantado de carnecerte", objective = "Harkor en el Campamento de Harkor quiere que consigas 10 trozos de carne fibrosa de huargo de los merodeadores aúllaocaso y 10 filetes de cornopala de los pastadores Pezuña Larga.", description = "¡Buen día, <clase>! ¿Te sientas al fuego conmigo?\n\nTe ofrecería una comida caliente, pero no tengo. Estoy aquí atascado esperando a un socio, si no estaría afuera intentando resolver esto yo mismo.\n\nDime, parece que tienes un montón de tiempo libre y por aquí hay bastante carne. ¿Qué te parece si me ayudas un poquillo y juntas algo de comer?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12114] = {title = "Terapia", objective = "Harkor en el Campamento de Harkor quiere que mates a 10 protectores Drakkari y a 10 oráculos Drakkari fuera de las Ruinas de Drakil'jin.", description = "Trols... ¡los odio a todos! <Harkor escupe.>\n\nUna vez me capturó un grupo de esas bestias... ¡estuve a esto de acabar con la cabeza reducida!\n\nMis amigos me dicen que debo dejarlo atrás, pero eso no me parece bien.\n\n¿Quieres saber qué me haría sentirme mejor, <raza>? ¡Ver un montón de sus cadáveres tan alto que llegue a cubrir el sol! Si puedes hacer que eso suceda, te puedo pagar con oro.", progress = nil, completion = "Gracias, &lt;clase&gt;.\n\nCuando tenga tiempo me daré un paseo y echaré un vistazo.", rewards = "Falda de reclamo tranquiloCapa terapéuticaLeotardos de control de inquinaManoplas de exterminaciónCoselete de furia expresaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12115] = {title = "Koltira y el idioma de la muerte", objective = "Llévale el escrito encuadernado en carne a Koltira Tejemuerte.", description = "Hay alguien que hace poco se unió a nuestra causa que pueda ser capaz de descifrar este escrito. Un caballero de la Muerte conocido como Koltira Tejemuerte se ha instalado de manera temporal aquí en Martillo de Agmar. Como fue un caballero de la Muerte al servicio de Arthas y un miembro de la Plaga, podría ser capaz de traducir el idioma de los muertos.\n\nLlévale el escrito encuadernado en carne a Koltira y pídele que traduzca las páginas.\n", progress = "¿Qué pasa, <raza>?", completion = "Solo hay dos cosas en la vida que me interesan, y ninguna de ellas incluye traducir un escrito de la Plaga para ti.\n\nSin embargo… quizás podamos idear algo que nos sea de provecho a los dos.\n\n&lt;Koltira desenfunda su arma.&gt;\n\nEsta es mi hojarruna, Bifrost. Bifrost está sedienta de la sangre del Rey Exánime y de sus esbirros, pero primero debo grabarla con runas de poder: símbolos de escarcha, sangre y profano. Tráeme las fuentes apropiadas de poder y traduciré tu escrito.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12116] = {title = "Requiere agallas…", objective = "Kraz en Campamento de Harkor quiere que entres en las Ruinas de Drakil'jin y recojas 5 vasos canopes Drakkari.", description = "Saludos, <clase>. Es un detalle por tu parte pararte a escuchar la historia de Kraz.\n\nDurante muchos años Kraz se ha esforzado por escuchar a los espíritus y seguir sus instrucciones.\n\nÚltimamente muchas voces han estado llorándole a Kraz desde estas ruinas. Buscan una paz que no pueden encontrar por sí solos.\n\nSi ayudases a los espíritus de aquellos que han venido antes, entra en esta cripta y recoge algo que perteneciera anteriormente a esas almas atormentadas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12117] = {title = "Viaja hasta el Puerto Moa'ki", objective = "Viaja hasta el Puerto Moa'ki en el Cementerio de Dragones y habla con el ancestro Ko'nani.", description = "<raza>, acaban de llegar noticias del Puerto Moa'ki. ¡Esta mañana ocurrió algo horrible!\n\nNos has sido de gran ayuda. ¿Considerarías usar el barco desde Unu'pe para ir hasta el Cementerio de Dragones?\n\nSegún están las cosas, el ancestro Ko'nani podría necesitar tu ayuda.", progress = nil, completion = "¿Qué dices, &lt;raza&gt;? ¿Te envía Hotawa?\n\nBien, bien... hay mucho trabajo. ¡Toda ayuda es bien recibida!", rewards = "Falda del sanador erranteMandiletes de llanuras azotadas por el vientoManteo de pellejo de huargo durablePodrás elegir una de estas recompensas:\n\nGargantilla del Viento del Norte\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12118] = {title = "Viaja hasta el Puerto Moa'ki", objective = "Viaja hasta el Puerto Moa'ki en el Cementerio de Dragones y habla con el ancestro Ko'nani.", description = "<raza>, acaban de llegar noticias del barco que venía del Puerto Moa'ki. ¡Esta mañana ha ocurrido algo horrible!\n\nNos has sido de gran ayuda. ¿Considerarías usar el barco para ir hasta el Cementerio de Dragones?\n\nSegún están las cosas, el anciano Ko'nani podría necesitar tu ayuda.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Falda del sanador erranteMandiletes de llanuras azotadas por el vientoManteo de pellejo de huargo durablePodrás elegir una de estas recompensas:\n\nGargantilla del Viento del Norte\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12119] = {title = "Conseguir una audiencia", objective = "Entrega tu carta de presentación para el Templo del Reposo del Dragón a Tariolstrasz en el Templo del Reposo del Dragón.", description = "<nombre>, debes dirigirte lo más rápido posible al Templo del Reposo del Dragón y entregar esta carta al administrador, Tariolstrasz.\n\nEl templo está situado en el centro del Cementerio de Dragones. Sigue el camino hacia el este hasta el final, y luego cruza el Baldío del Dragón.\n\nSeguro que cuando el administrador lea tu introducción, se ocupará de arreglarte una reunión con la reina Alexstrasza. Nuestra única esperanza es que no sea ya demasiado tarde.\n\nGracias por todo lo que has hecho por nosotros. ¡Buen viaje!", progress = "¿Qué puedo hacer por ti, <raza>?", completion = "¿Una carta de presentación para un encuentro con la reina? Déjame ver.\n\nCualquiera que sea este asunto, espero que sea importante. ¡El cielo está lleno de atacantes azules hoy!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12120] = {title = "La marra de Drak'aguul", objective = "Kraz en el Campamento de Harkor quiere que mates a Drak'aguul a las afueras de las Ruinas de Drakil'jin y vuelvas con la marra de Drakil'jin.", description = "Corrupción...\n\nIncluso antes de que entregaras esos tarros, Kraz pudo sentirlo. La corrupción invade a los viejos espíritus Drakkari con gran angustia y les impide conseguir el descanso que buscan.\n\nKraz no mentirá, <clase>. Limpiar este lugar requerirá un gran sacrificio, pero hablaremos de ello más tarde.\n\nHay uno entre los vivos que tiene la clave para dicha limpieza. Busca a Drak'aguul y vuelve junto a Kraz con la marra que lleva.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Hombreras de éxitoGuardarrenes de obtención de expedienteYelmo de cuerno de venado pulidoGuanteletes de portamartilloRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12121] = {title = "Te veo al otro lado", objective = "Kraz en Campamento de Harkor quiere que uses la marra de Drakil'jin en los gongs a las afueras de las Ruinas de Drakil'jin. Cuando te hayan matado, deberás entrar a las ruinas y hablar con el espíritu de Gan'jo mientras estés <muerto/muerta>.", description = "Esos Drakkari solo te han recibido con hostilidad salvaje. No les debes nada. De hecho, muy pocos realizarían la tarea que Kraz te pide hoy.\n\nPara limpiar este lugar y enviar a los espíritus a su lugar de descanso eterno, debes unirte a ellos en la muerte.\n\nHay uno en el interior de la cripta que te está esperando... al otro lado. Él conoce la información que buscamos, <nombre>.\n\nUtiliza la marra con los gongs. El espíritu de aquel que corrompe este lugar te llevará al mundo de los espíritus.\n\nKraz espera tu regreso.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12122] = {title = "Conseguir una audiencia", objective = "Entrega tu carta de presentación para el Templo del Reposo del Dragón a Tariolstrasz en el Templo del Reposo del Dragón.", description = "<nombre>, debes dirigirte lo más rápido posible al Templo del Reposo del Dragón y entregar esta carta al administrador, Tariolstrasz.\n\nEl templo está situado en el centro del Cementerio de Dragones. Sigue el camino hacia el este hasta el final, y luego cruza el Baldío del Dragón.\n\nSeguro que cuando el administrador lea tu introducción, se ocupará de arreglarte una reunión con la reina Alexstrasza. Nuestra única esperanza es que no sea ya demasiado tarde.\n\nGracias por todo lo que has hecho por nosotros. ¡Buen viaje!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12123] = {title = "Informar a la reina", objective = "Entrega tu carta de presentación para el Templo del Reposo del Dragón a Alexstrasza la Protectora en el Templo del Reposo del Dragón.", description = "<El dragón administrador saca tu carta de presentación de su manga.>\n\nSí, sí... creo que estás <preparado/preparada> para ver a la reina ahora.\n\nCuando estés <listo/lista>, vuelve a hablar conmigo y me encargaré de que uno de esos dracos te escolte hasta lo alto del templo. Tendrás que llevar tu carta personalmente a la reina Alexstrasza.", progress = "Me alegro de por fin conocerte en persona, <nombre>. Te he conocido incluso desde antes de que nacieras.", completion = "Eres realmente valiente al traernos esta información. Empezaba a preguntarme por qué el Vuelo Azul había mostrado tanto atrevimiento para iniciar un ataque sobre el templo. Ahora que sabemos que están usando cantidades ingentes de magia pura, suponen una grave amenaza para Azeroth.\n\n&lt;La reina sacude la cabeza con resignación.&gt;\n\nHipócrita, pero así es. Si Malygos no entra en razón, no nos queda más opción que responder a su ataque.", rewards = "Recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12124] = {title = "Informar a la reina", objective = "Entrega tu carta de presentación para el Templo del Reposo del Dragón a Alexstrasza la Protectora en el Templo del Reposo del Dragón.", description = "<El dragón administrador saca tu carta de presentación de su manga.>\n\nSí, sí... creo que estás <preparado/preparada> para ver a la reina ahora.\n\nCuando estés <listo/lista>, vuelve a hablar conmigo y me encargaré de que uno de esos dracos te escolte hasta lo alto del templo. Tendrás que llevar tu carta personalmente a la reina Alexstrasza.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12125] = {title = "Al servicio de la sangre", objective = "Koltira Tejemuerte en Martillo de Agmar en el Cementerio de Dragones quiere que uses la gema de sangre sobre un habitante de Indu'le trastornado y vuelvas con una gema de sangre llena.", description = "Sangre inocente se usó una vez para saciar la sed de la hoja. Por desgracia, ya no dispongo de tal opción.\n\n<Koltira se para a pensar.>\n\nDebemos improvisar. Al sur de aquí, sobre los altos riscos, se encuentra el poblado colmillarr Indu'le. Como han sido invadidos por la magia caótica del Vuelo Azul, los habitantes colmillarr de Indu'le se han vuelto locos.\n\nCoge esta gema de sangre y úsala sobre un habitante trastornado. Si no puedo conseguir sangre inocente, ¡tendré que conseguir la sangre de los débiles!", progress = "Tráeme la sangre de los sumisos.|n", completion = "Una tarea simple para un simplón. Has actuado según mis expectativas.|n", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12126] = {title = "Al servicio de lo profano", objective = "Koltira Tejemuerte en Martillo de Agmar en el Cementerio de Dragones quiere que uses la gema profana sobre el duque Vallenhal y vuelvas con una gema profana llena.", description = "El poder de lo profano es muy codiciado entre los de mi clase. Constituye lo más profundo de nuestra existencia, ¡otorgando la muerte a los que se atreven a burlarse de él! Por suerte existe una fuente de la que podría abastecerme en mis momentos de necesidad.\n\nCoge esta gema profana y llega hasta el Santuario de Dragones Rubí, al este de aquí. Allí es donde encontrarás al duque Vallenhal, caballero de la Muerte de Arthas. Debilítalo durante la batalla y libera el poder de la gema sobre él. Eso lo rematará ¡y le robará su energía profana!\n", progress = "¡Llena la gema con el poder de lo profano!", completion = "&lt;Koltira abre mucho los ojos.&gt;\n\nImpresionante. Has superado a uno de los caballeros de la Muerte de Arthas... No cabe duda de que no estabas solo, pero aun así...|n", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12127] = {title = "Al servicio de la escarcha", objective = "Koltira Tejemuerte en Martillo de Agmar en el Cementerio de Dragones quiere que uses la gema de escarcha con aparecidos de hielo y vuelvas con la gema de escarcha llena.", description = "El frío punzante protege al caballero de la Muerte, al mismo tiempo que repele a sus enemigos. El que dirige el poder de la escarcha puede provocar el caos y la destrucción.\n\nCoge esta gema de escarcha y viaja a través de toda la tundra extensa del Cementerio de Dragones, hasta que topes con El Espejo del Alba, al este del Templo Reposo del Dragón. Allí es donde te enfrentarás a las legiones de los aparecidos de hielo que moran la superficie de los lagos y de donde conseguirás la esencia de escarcha. ¡Utiliza el poder de la gema cuando estén débiles, <nombre>!", progress = "Todos los que estamos en Rasganorte estamos al servicio de la escarcha.", completion = "Ya puedo sentir el frío fluyendo en mi interior, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12128] = {title = "Visita a Raegar", objective = "Habla con Raegar Rompecejas en el Altozano del Prospector.", description = "Con todo el lío del ejército intentando cruzar Thor Modan casi me olvido de la gente de Raegar en el Altozano del Prospector.\n\nMandé a Raegar y a sus ayudantes junto a un amigo montaraz para que levantasen un pequeño puesto cerca de Dun Argol, en el extremo sur de la Playa Viento Este.\n\nTenían que investigar la presencia de los enanos férreos en las colinas del sur, pero todavía no he recibido ningún informe. Si te coge de camino, ¿podrías ir a visitarlo?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12129] = {title = "El plan perfecto", objective = "Llévale el plano de gólem de guerra completo a Raegar Rompecejas en Altozano del Prospector.", description = "Los enanos férreos no están ocultando el hecho de que se están preparando para la guerra. Con sus gigantes, gólems y sus elementales de relámpago, cuentan con una ventaja tecnológica frente a la Brigada de los Páramos de Poniente. Si no encuentran el paso al norte a tiempo, los férreos podrían cogerlos por sorpresa.\n\nTenemos que contenerlos aquí y sé cómo hacerlo. Dun Argol está lleno de forjadores de runas creando gólems como churros. Llevan planos para piezas específicas, así que tienes que encontrar y juntar todos los trozos.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12130] = {title = "¿Por qué fabricarlo cuando puedes apropiártelo?", objective = "Llévale 8 piezas de gólem de guerra a Raegar Rompecejas en el Altozano del Prospector.", description = "Ya tenemos las copias de los planos, ¡pero no podemos sacarles provecho si no tenemos las piezas! No tenemos acceso a ninguna forja ni mucho menos a materiales, pero hay un montón de piezas en Dun Argol.\n\n¿Tu tarea?\n\nDales un nuevo hogar.\n\nProbablemente estarán esparcidas por los edificios en los que trabajan los forjadores Runaférrea, pero no culparía a los férreos por cabrearse cuando intentes birlarles sus trabajos. Cuantas más piezas puedas traer, mejor nos saldrá el gólem.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12131] = {title = "Tenemos el poder...", objective = "Llévale la célula de energía de Durar y la célula de energía de Kathorn a Raegar Rompecejas en el Altozano del Prospector.", description = "Ya casi lo tenemos, pero el gólem de guerra no funcionará sin células de energía. De la información que pude obtener en Dun Argol antes de que nos descubrieran, tanto el forjador de runas Durar como el forjador de runas Kathorn crearon, cada uno, una célula de energía.\n\nNecesitaremos una de cada uno de los forjadores de runas para que nuestro gólem pueda funcionar.\n\nDeberías poder encontrar a los forjadores en sus respectivos talleres en el piso central de Dun Argol.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12132] = {title = "El poder para destruir", objective = "Koltira Tejemuerte en Martillo de Agmar en el Cementerio de Dragones quiere que entres en el mundo de las sombras y derrotes a 6 torturadores enigmáticos.\n\nHabla con Koltira Tejemuerte si necesitas volver a entrar en el mundo de las sombras.", description = "Aunque has hecho mucho por mí, aún falta algo.\n\nMás allá del mundo que conoces existe otro mundo. Es desde ese mundo, el mundo de las sombras, del que me atormentan mis torturadores. Dado que me falta el poder para enfrentarme a mis propios demonios, tú podrías ser quien termine con su reinado de terror. Tú tienes la fuerza, yo mismo lo he visto.\n\nEntra en el mundo de las sombras y ¡enfréntate a los demonios que me atormentan!\n\nHaz esto y traduciré el escrito tal y como te prometí.", progress = nil, completion = "El poder que ostento me cuesta un precio muy alto, &lt;nombre&gt;. Muchos caballeros, tanto de la luz como de las sombras, perdieron sus vidas en la última batalla en la Esperanza de la Luz. El futuro se presenta desalentador, pero al menos ahora sé a lo que me enfrento. El Rey Exánime nunca flaqueará y, aunque solo sea por esa razón, ¡debe morir!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12133] = {title = "Aplasta la calabaza", objective = "Dale el símbolo sagrado chamuscado a la supervisora de huérfanos disfrazada.", description = "Esta gran calabaza iluminada se encuentra en el centro de la ciudad. Observa a aquellos que la miran, revelando una oscura amenaza en su interior.\n\nAl aplastar la calabaza se descubre un viejo símbolo sagrado chamuscado.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObsequio mal envuelto"}
MultiLanguageQuestData['mx'][12134] = {title = "La caza de Sasha", objective = "Sasha quiere que mates a 12 cazadores del solsticio en el Poblado Solsticio.", description = "Esto... esta maldición... está afectando a Arroyoplata y al Poblado Solsticio... convierte a la gente en bestias.\n\nMi padre intentó advertirles, pero prefirieron escuchar al culto del lobo.\n\nAhora han llegado demasiado lejos. Es hora de sacrificarlos... por su propio bien.", progress = nil, completion = "La muerte de esos monstruos no me devolverá a mi padre... pero eso ahora no importa, ¿verdad?", rewards = "Blasón de matalobosBaluarte sangrientoBastón de venganza rectaPodrás elegir una de estas recompensas:\n\nCetro de Represalia apasionada\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12135] = {title = "\"¡Dejen que el fuego se acerque!\"", objective = "La supervisora de huérfanos disfrazada quiere que ayudes a apagar todos los incendios de la ciudad que provoque el Jinete decapitado. Cuando termines, vuelve a hablar con ella.", description = "¡Tienes que ayudarnos! ¡El Jinete decapitado atacará el poblado en cualquier momento! ¡Habrá fuego por todas partes! ¡Los niños están en peligro! \n\nPor favor, <nombre>, ¿lucharás contra el fuego del Jinete decapitado? Cuando llegue, únete a la brigada antiincendios, hazte con un cubo de agua y échalo al fuego, o pásalo a algún amigo que esté más cerca de las llamas. Si apagas todos los fuegos, ¡entonces estaremos salvados!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGolosinas de calabaza de HalloweenCalabaza iluminada pesada"}
MultiLanguageQuestData['mx'][12136] = {title = "El escrito traducido", objective = "Entrega el escrito encuadernado en carne traducido al capitán Gort en Martillo de Agmar.", description = "Aquí está, <nombre>. He traducido todas las páginas del escrito. Dentro encontrarás una lista con los nombres de los miembros del Culto de los Malditos de todo el continente.\n\nSu red de espías y operativos es, cuando menos, impresionante.\n\nBuena suerte, <amigo/amiga>. Que el libro les sea de ayuda a ti y a tu pueblo.", progress = "¡Ya era hora! ¿Dónde te habías metido?", completion = "&lt;Gort coge el escrito de tus manos y empieza a leer.&gt;\n\n¿QUÉ? No puede ser verdad. ¡Conozco a algunos de estos orcos desde hace años!\n\nDéjame, &lt;nombre&gt;, tengo mucho que hacer y muchos traidores que ejecutar.\n\nCoge alguno de estos objetos por las molestias. Hoy has rendido un gran servicio a la Horda.", rewards = "Cimera de viento residualCoraza de espetadora AvalanchaLeotardos de caparazón de Anub'arYelmo de senda pedregosaRecibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12137] = {title = "Relá'hatee, coleega", objective = "Gan'jo quiere que recojas la nieve de sueño eterno de su cofre en las Ruinas de Drakil'jin.\n\nDeberás usar la nieve sobre los antiguos espíritus Drakkari allí y llevar sus partículas de espíritus Drakkari a Kraz en Campamento de Harkor.", description = "Que se haga como dicen las profecías, colega. <Un/Una:r> <raza> <clase> vendrá a devolver la paz a nuestro'h eh'píritu'h. ¡Hemo'h esperado mucho tiempo ya!\n\nLos Drakkari se han convertido en un pueblo perdido, fiero y salva'he.\n\nPero aquí sufrimo' no po' nuestra culpa, colega. E'te lugar necesita limpieza y solo lo' vivo' pueden hace'lo.\n\nHabla conmigo cuando estés <listo/lista> pa' unirte con tu cuerpo. Co'he la nieve del cofre a mi la'o y pon a mi' hermano' a dormí.\n\nLleva su' resto' a tu guía espirituá'. Él sabrá qué hacé' de'pué.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12139] = {title = "\"¡Dejen que el fuego se acerque!\"", objective = "La supervisora de huérfanos enmascarada quiere que ayudes a apagar todos los incendios en los poblados. Cuando estén apagados, vuelve a hablar con ella.", description = "¡Tienes que ayudarnos! ¡El Jinete decapitado atacará el poblado en cualquier momento! ¡Habrá fuego por todas partes!\n\nPor favor, <nombre>, ¿lucharás contra el fuego del Jinete decapitado? Cuando llegue, únete a la brigada antiincendios, hazte con un cubo de agua y échalo al fuego, o pásalo a algún amigo que esté más cerca de las llamas. Si apagas todos los fuegos, ¡entonces estaremos salvados!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nGolosinas de calabaza de HalloweenCalabaza iluminada pesada"}
MultiLanguageQuestData['mx'][12140] = {title = "¡Viva Roanauk!", objective = "Busca a Roanauk Bruma de Hielo en Martillo de Agmar e iníciale como miembro y líder de las fuerzas de la Horda.\n\nVuelve junto al señor supremo Agmar con el juramento de sangre de la Horda cuando completes esta misión.|n", description = "Al igual que los tauren, los Renegados, trols y elfos de sangre, los taunka también necesitan un líder de su misma sangre. Aquel que salvaste en Bruma de Hielo, Roanauk, será su líder.\n\n<El señor supremo Agmar te entrega un pergamino.>\n\nTe doy algo familiar: el juramento de sangre de la Horda.\n\nLlévale el juramento a Roanauk Bruma de Hielo e inícialo en la Horda como líder de los taunka.\n\nNo le hagamos esperar.\n\n<Agmar asiente.>\n", progress = nil, completion = "¡Con la ayuda de un chamán tan poderoso, seguro que salimos victoriosos en la Puerta de Cólera!|n", rewards = "Capa de honornatoGuardapiés de hueso petrificadosPodrás elegir una de estas recompensas:\n\nObjeto #1Sello de juramentoFlores Toquesol\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12141] = {title = "Una misión diplomática", objective = "Habla con Karuk en el Litoral Tralladón, al suroeste de la Fortaleza Denuedo.", description = "\"Veo que tienes intención de ayudar, <nombre>. ¡No has venido hasta Rasganorte para quedarte <encerrado/encerrada> en una ciudad! Tengo la misión perfecta para ti... algo que te llevará lejos de aquí.\n\nDurante mucho tiempo, hemos querido ganar el favor de los colmillarr originarios de Rasganorte. Recientemente, un joven colmillarr vino hasta aquí pidiendo ayuda, algo que entonces no podíamos ofrecer.\n\nAhora que estás aquí, quizás puedas echarle una mano. Busca a Karuk cerca del Litoral Tralladón, al suroeste de aquí, y ve cómo puedes ayudarlo.\"", progress = nil, completion = "¿Has venido en mi ayuda? Gracias, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12142] = {title = "Control de plagas", objective = "Duane en el Frente de la Séptima Legión quiere que mates a 10 snóbolds Llano Nevado y a 3 magnatauros del Cementerio de Dragones en los campos de magnatauros que rodean Reposo del Dragón.", description = "¡Puaj! Uno de esos pequeños snóbolds destrozó nuestro campamento mientras nos ocupábamos del último dragón. Vienen a molestar en el momento en que nos damos la vuelta. ¡Ya basta!\n\nAl sur encontrarás a los snóbolds escondidos bajo las faldas de alguno de los magnatauros locales. Ve a matarlos.\n\nSi el magnatauro interfiere para defender a sus esclavos, mátalo también.", progress = nil, completion = "Ya era hora.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12143] = {title = "Persecución por el cañón", objective = "Duane quiere que persigas a los snóbolds por el cañón al noreste del Frente de la Séptima Legión y que acabes con su líder.", description = "¡No me lo puedo creer! Otra panda de esos ratones acaba de intentar largarse con más de nuestros suministros. Se alejan a toda prisa hacia el cañón al norte, ¡ve tras ellos y acaba con cualquiera que les acompañe!", progress = nil, completion = "Colmillo Helado, ¿eh? Ya había oído ese nombre antes. Bien hecho, &lt;clase&gt;. Con un poco de suerte, podremos volver a dedicarnos a la amenaza de los dragones.", rewards = "Casquete de resguardo de vermisChaleco del corredor del cañónGuardarrenes de cazador de vermisGuardamuñecas de AterravermisRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12144] = {title = "Control de plagas", objective = "Kontokanis en Caída del Dragón quiere que mates a 10 discípulos Llano Nevado y a 3 magnatauros alfa en los campos de magnatauros que rodean Reposo del Dragón.", description = "¡Qué aburrimiento, colega! Uno de esos pequeños snóbolds destrozó nuestro campamento durante la última caza de dragones. Vienen a incordiar desde el momento en que nos damos la vuelta y ya estamos hartos.\n\nAl sur encontrarás a los snóbolds escondiéndose bajo las faldas de alguno de los magnatauros locales. Ve a matarlos. Si el magnatauro interfiere para defender a sus esclavos, mátalo también.", progress = nil, completion = "Ya era hora, colega.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12145] = {title = "Persecución por el cañón", objective = "Kontokanis quiere que persigas a los snóbolds por el cañón al sur de Caída del Dragón y que acabes con su líder.", description = "¡No me lo puedo creer! Otra panda de esos ratones acaba de intentar largarse con más de nuestros suministros. Se alejan a toda prisa hacia el cañón al norte, ¡ve tras ellos y acaba con cualquiera que les acompañe!", progress = nil, completion = "Puño de Hielo, ¿eh? Ya había oído ese nombre antes. Bien hecho, tron. Con un poco de suerte, los Lanza Negra podremos volver a dedicarnos a la amenaza de los dragones.", rewards = "Casquete de resguardo de vermisChaleco del corredor del cañónGuardarrenes de cazador de vermisGuardamuñecas de AterravermisRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12146] = {title = "Implicaciones inquietantes", objective = "Lleva el cuerno de batalla blasonado hasta Reposo del Dragón y busca a alguien que pudiera estar interesado en evaluar el nivel potencial de amenaza.", description = "Por la parte inferior del cuerno se ve un sello adornado con un martillo y un rayo. Resulta muy extraño encontrar un objeto así en el cadáver de un magnatauro, pues no suelen organizarse sino en pequeños grupos.\n\nLleva el cuerno al sur por la Senda de los Titanes hasta Reposo del Dragón y busca a alguien que pudiera estar interesado en estas amenazadoras implicaciones.", progress = "¿Sí, <raza>?", completion = "Sí, que un magnatauro lleve un objeto como este es extraño... y preocupante. Me alegro de que me lo hayas traído.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12147] = {title = "Implicaciones inquietantes", objective = "Lleva el cuerno de batalla blasonado hasta Reposo del Dragón y busca a alguien que pudiera estar interesado en evaluar el nivel potencial de amenaza.", description = "Por la parte inferior del cuerno se ve un sello adornado con un martillo y un rayo. Resulta muy extraño encontrar un objeto así en el cadáver de un magnatauro, pues no suelen organizarse sino en pequeños grupos.\n\nLleva el cuerno al este a través del Baldío del Dragón hasta Reposo del Dragón y busca a alguien que pudiera estar interesado en estas amenazadoras implicaciones.", progress = "¿Sí, <raza>?", completion = "Sí, es extraño que un magnatauro lleve un objeto como este... y preocupante. Me alegro de que me lo hayas traído.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12148] = {title = "Único", objective = "Encuentra y mata a Hiendehuesos cerca del cañón al noroeste del Santuario de Dragones Azur. Llévale cualquier prueba que encuentres a Aurastrasza en el Templo del Reposo del Dragón.", description = "Es un sello un poco raro para un magnatauro... sugiere cierta organización.\n\nLos magnatauros no suelen dejar de lado su naturaleza agresiva para cooperar. Sospecho que lo que pretenden es asaltar un gran asentamiento.\n\nDudo mucho que este cuerno sea único, pero tú tienes que confirmarlo. En el cañón al noroeste del Santuario de Dragones Azur encontrarás a Hiendehuesos. Desafíalo y tráeme cualquier prueba que confirme mis temores.", progress = "¿Has encontrado algo?", completion = "Así que es cierto. No podrían haber elegido mejor momento para un ataque así... Entre la Plaga y la lucha contra el Vuelo Azul es poco probable que alguien más se haya dado cuenta.", rewards = "Recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12149] = {title = "Un poderoso magnatauro", objective = "Da caza y muerte a Sangría, Trizahielo y a Dracogor al este de Reposo del Dragón.\n\nSangría se encuentra en el rincón sureste del Baldío del Dragón, al norte del Santuario de Dragones Esmeralda. Trizahielo patrulla el extremo norte de El Espejo del Alba. Dracogor vaga por la parte inferior de los acantilados al oeste del Santuario de Dragones Bronce.\n\nVuelve junto a Aurastrasza en el Templo del Reposo del Dragón cuando hayas matado a los magnatauros.", description = "Los magnatauros son criaturas espantosamente violentas... Por eso es raro que se junten grandes cantidades sin que se maten los unos a los otros. Un líder poderoso se ha alzado entre ellos y necesitamos darle caza si queremos detener esta amenaza.\n\nEmpezaré a indagar. Mientras tanto, tengo que causarles tantas complicaciones como pueda.\n\nAl este de aquí hay 3 antorchas en pie. Junto a ellas, hay 3 magnatauros dominantes: mátalos para darnos más tiempo para acabar con su líder.", progress = nil, completion = "Excelente trabajo. Nadie fue capaz de decirme quién podría ser ese líder, pero pude desvelar el nombre de alguien que tenía la respuesta.", rewards = "Recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12150] = {title = "Un maestro de runas solitario", objective = "Encuentra a Dregmar Runarrama cerca de su cueva en la senda que dirige a los acantilados que dan a El Espejo del Alba. Desafíale y revela el nombre del líder magnatauro utilizando los medios necesarios. Vuelve junto a Aurastrasza en el Templo del Reposo del Dragón cuando hayas obtenido la información.", description = "Dregmar Runarrama es un maestro de runas magnatauro... único en su especie. Suele ser solitario, pero se sabe que lleva colaborando algún tiempo con los magnatauros más poderosos e influyentes del Cementerio de Dragones. Él sabrá quién es ese nuevo líder.\n\nCon los crecientes problemas que está habiendo con la Plaga y con el Vuelo Azul, no creo que consigamos ayuda, así que necesito que hagas todo lo necesario para conseguir la información de Dregmar.\n\nMe han dicho que se encuentra entre los acantilados que asoman a El Espejo del Alba.", progress = nil, completion = "Grom'thar el Portador del Trueno. Bien. Terminemos con cualquier amenaza que constituyan esos magnatauros, aquí y ahora.", rewards = "Recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12151] = {title = "Un Señor de la Guerra atroz", objective = "Viaja hasta el anillo de antorchas al sur del Santuario de Dragones Azur y sopla el cuerno de batalla blasonado. Derrota a Grom'thar el Portador del Trueno y llévale su cabeza a Aurastrasza en el Templo del Reposo del Dragón.", description = "No hay ninguna razón para sospechar que las palabras de Dregmar no sean la pura verdad. Tanto si Grom'thar te derrota como si tú lo derrotas a él, se lavará las manos.\n\nSigue sus instrucciones... lleva el cuerno que me trajiste antes, viaja hasta el anillo de antorchas al sur del Santuario de Dragones Azur y sóplalo para hacer oír tu desafío.\n\nCuando Grom'thar el Portador del Trueno llegue, mátalo y tráeme su cabeza.", progress = "¿Has acabado con la amenaza para siempre?", completion = "Eres realmente formidable.\n\nCon la muerte de Grom'thar el Portador del Trueno, podemos dejar que el resto de los magnatauros se peleen entre ellos y volver a concentrarnos en otras amenazas más importantes.\n\nExcelente trabajo, &lt;clase&gt;.", rewards = "Hoja de hechizo perdida de EmmeTaigashaEspada corta del aliado rubíHoja doble de magnatauro maltrechaArco largo de jinete de rubíPodrás elegir una de estas recompensas:\n\nTalismán de vinculador de vida\n\nTambién recibirás:\n\nSuministros de aventura de RasganorteObjeto #1"}
MultiLanguageQuestData['mx'][12152] = {title = "El final de Jin'arrak", objective = "Kraz en Campamento de Harkor quiere que recojas la ofrenda Drakkari sacra de las Ruinas de Drakil'jin y eches el polvo de espíritus Drakkari sobre ella. Debes usar la ofrenda Drakkari imbuida con los gongs que hay a las afueras de las Ruinas de Drakil'jin.", description = "Qué bien verte de nuevo entre los vivos. Muchos de los que atraviesan el camino de los muertos no sobreviven para contarlo.\n\nDurante tu ausencia Kraz tuvo una visión que le indicaba lo que queda por hacer.\n\nDentro de la cripta se esconde una ofrenda sagrada. Toma este polvo de espíritus, elaborado a partir de los restos que recogiste, y úsalo para la ofrenda.\n\nLa ofrenda imbuida pondrá fin al corrupto Señor de la Guerra y liberará a las numerosas almas atormentadas.\n\nQue los espíritus guíen tus actos, <nombre>.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Desgarradora de trol dentadaHacha de fallecimiento del Señor de la GuerraDaga con picoCercenadora de hierro frío dentadaPodrás elegir una de estas recompensas:\n\nOrbe de vudú resplandecienteRama de sueños perspicaces\n\nTambién recibirás:\n\nSuministros de aventura de RasganorteObjeto #1"}
MultiLanguageQuestData['mx'][12155] = {title = "Aplasta la calabaza", objective = "Dale el símbolo sagrado chamuscado a la supervisora de huérfanos enmascarada.", description = "Esta gran calabaza iluminada se encuentra en el centro de la ciudad. Observa a aquellos que la miran, revelando una oscura amenaza en su interior.\n\nAl aplastar la calabaza se descubre un viejo símbolo sagrado chamuscado.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObsequio mal envuelto"}
MultiLanguageQuestData['mx'][12157] = {title = "El mensajero perdido", objective = "Habla con el mensajero Lanson en Reposo Estelar, en el Cementerio de Dragones.", description = "Tenemos suerte de haber llegado tan lejos, <nombre>. La Plaga nos tendió una emboscada en el mismo momento en el que llegábamos.\n\nUno de nuestros hombres resultó ser un espía del Culto de los Malditos. Parece que Thassarian tiene más pruebas de la infiltración de cultores. Aparentemente, afecta hasta a los rangos más altos.\n\nHe enviado a uno de mis mejores mensajeros hasta nuestra avanzada al oeste del Cementerio de Dragones, pero aún no ha vuelto. Me temo que haya caído en manos de la Plaga. ¿Irías al Cementerio de Dragones a buscarlo? Responde al nombre de mensajero Lanson.\n", progress = nil, completion = "Mientras cruzaba el puente hasta el Cementerio de Dragones ¡un pequeño grupo de Anub'ar me tendió una emboscada! ¡Estaba rodeado! Esos bastardos sabían que llegaría. Apenas pude escapar con el pescuezo intacto. Esta lista que guardo debe llegar hasta la Fortaleza de Hibergarde, pero estoy demasiado herido como para hacer el viaje.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12158] = {title = "Mina Piedrahueca", objective = "Busca pistas dentro de la Mina Piedrahueca al noroeste del Campamento de la Brigada de los Páramos de Poniente.", description = "Hace tiempo que quiero enviar a algunos de nuestros muchachos a observar la Mina Piedrahueca, pero aún no he tenido ocasión... Estamos ocupados con la Horda al oeste y con los enanos férreos al este.\n\nPero si te envió Dumont, lo mínimo que puedo hacer es indicarte la dirección a seguir.\n\nEncontrarás la entrada de la mina al noroeste, no muy lejos de aquí. Ve a ver si podríamos retomar nuestra actividad allí. No nos vendrían mal otros recursos hasta que nuestra mina en Lindeallá vuelva a estar operativa.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12159] = {title = "Almas sin descanso", objective = "Petrov en Mina Piedrahueca quiere que uses la linterna de minero para quemar los cadáveres de 8 mineros Piedrahueca.", description = "<Petrov parece muy preocupado, respirara con fuerza y mira con nerviosismo por toda la mina.>\n\nMis compañeros... ¡sus almas deben descansar! No dejo de matarlos, ¡pero vuelven a aparecer!\n\nTengo una idea desde hace tiempo pero no el valor para llevarla a cabo yo mismo.\n\nQuizás tú puedas hacerlo por mí. Coge esta linterna y usa el aceite para quemar sus restos para que no se vuelvan a levantar.\n\nDespués responderé a tus preguntas. ¡Primero ayuda a mis amigos!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Togas tratadas especialmenteYelmo de piel de osoCoselete con rayas ocultasCaparazón del caídoRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12160] = {title = "Un nombre del pasado", objective = "Vuelve con el capitán Gryan Mantorrecio en el Campamento de la Brigada de los Páramos de Poniente.", description = "¡Ha funcionado, ha funcionado! Mis compañeros por fin pueden disfrutar de su merecido descanso...\n\nYo me quedaré aquí a terminar el trabajo. Nosotros, los mineros Piedrahueca, siempre terminamos el trabajo... ¡nunca nos rendimos!\n\nPor eso Arugal nos convirtió en modelo a seguir. No caeríamos como moscas, ¿verdad? ¡No nos uniríamos a su culto de lobos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12161] = {title = "Ruuna la Ciega", objective = "Habla con Ruuna la Ciega en el Campamento de Ruuna cerca del Paso de Vordrassil.", description = "Hola. He oído lo que le estabas diciendo al capitán y solo quiero que sepas... que las cosas no son tan fáciles en Rasganorte.\n\nSolo porque alguien esté muerto, no significa que nuestros problemas se hayan acabado.\n\nAl suroeste de aquí, cerca del Paso de Vordrassil, vive una mujer ciega con el nombre de Ruuna la Ciega. Dicen que habla con los muertos y que tiene visiones del pasado y del futuro.\n\nNo conozco toda la historia pero me parece que ella te vendrá de perlas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12164] = {title = "La hora del huargo", objective = "Sasha en el Puesto de Venta de Pino Blanco quiere que vayas a la Isla Luna de Sangre y mates a Selas, Varlam, Buchegore y a la sombra de Arugal.", description = "Ha llegado el momento, <nombre>. Arugal debe ser derrotado.\n\nLlévate a un par de personas de confianza y dirígete a Isla Luna de Sangre. Se encuentra justo al lado de la costa, al este de aquí.\n\nLes asestaremos el golpe perfecto. Acaba con los tenientes de Arugal... me uniré a ti cuando llegue el momento de acabar con ese monstruo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Guardahombros de enlucido de huargoBufas de colmillo tajante cortantesBufas de matahuargos forradasGuardahombros de cuernocortadoSobrehombros de placas de hielo de hueso pulidoRecibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12165] = {title = "Un plan intrigante", objective = "Llévale el plano gólem de guerra completo al prospector Rokar en el Campamento Oneqwah.", description = "El prospector Rokar ha decidido ayudarnos. Ha elaborado un plan para usar la fuerza de los enanos férreos contra ellos.\n\nDebo admitirlo, nuestro nuevo \"amigo\" es más perspicaz de lo que parece. Tiene razón en que somos muy pocos como para realizar un ataque directo.\n\nViaja hasta Dun Argol, en las regiones nevadas que hay al sureste, y consigue todos los trozos del plano de su gólem de guerra, en manos de sus forjadores Runaférrea. Llévale la copia del plano completa a Rokar y veremos si su plan merece realmente la pena.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12166] = {title = "El fuego líquido de Elune", objective = "La celadora Jodi Canción de Luna en Reposo Estelar te ha pedido que uses el fuego líquido de Elune para limpiar los cadáveres de 6 alces contagiados y 6 pardos rabiosos.", description = "<raza>, ¿me ayudarás?\n\nLa Plaga se ha internado en Bruma de Hielo al norte. Allá donde va, extiende su inmundicia y las criaturas de la tierra sufren.\n\nCoge este vial, lleno con fuego líquido de Elune de la Poza de la Luna. Usa este líquido para limpiar los cadáveres de animales salvajes contagiados que encuentres.", progress = nil, completion = "Hemos hecho lo que podíamos por las criaturas de esta tierra. ¡Ahora debemos actuar directamente contra los causantes de todo esto!", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12167] = {title = "Mata a los cultores", objective = "Reúne 5 trajes funcionales de cultor para la celadora Jodi Canción de Luna en Reposo Estelar.", description = "Los cultores Anub'ar son responsables indirectos de la infección de los animales ¡y debemos poner fin a la situación!\n\nEl humo que emana de los trajes de los cultores se filtra por todo aquello a lo que se acercan, envenenando y corrompiendo lo que los rodea.\n\nDebes ir al norte hasta el Poblado Bruma de Hielo y matarlos. Trae cualquiera de sus trajes que sobreviva a tu ataque y me encargaré de que se les dé un uso adecuado.", progress = "¡Los cultores son una peste para la creación!", completion = "Bien hecho.\n\n¡Me desharé de estas prendas mugrientas limpiándolas en la Poza de la Luna y destruyéndolas mediante el poder de la diosa!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12168] = {title = "El Favor de Zangus", objective = "Entrega el Favor de Zangus a la celadora Jodi Canción de Luna en Reposo Estelar.", description = "Una inscripción en la parte posterior del Favor dice así:\n\n\"A mi alumno preferido:\n\nSi sigues mostrando potencial, te enseñaré maravillas que nunca imaginarías.\n\nSi no, ¡acabaré contigo!\n\nComo siempre,\n\nSumo cultor Zangus\"\n\nSeguro que la celadora de Reposo Estelar querrá ver esto.", progress = "Siento que algo repugnante se acerca.\n\n¡Lo tienes tú! ¿Qué es, <nombre>?", completion = "Así que el líder de los cultores se ha revelado. Tenemos un nombre.\n\n¡La vanidad y el orgullo serán su perdición!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12169] = {title = "El sumo cultor", objective = "La celadora Jodi Canción de Luna en Reposo Estelar te ha pedido que mates al sumo cultor Zangus.", description = "He soñado con Zangus anteriormente, pero al desconocer el contexto que tú has descubierto, no comprendía su significado. Has dado claridad a la visión que la diosa me ha concedido y ahora sé que podremos encontrarle dentro del Foso de Narjun al norte.\n\nYa conoces tu objetivo, <nombre>. Si queremos poner fin al sufrimiento de la tierra, ¡el sumo cultor deberá morir!", progress = nil, completion = "Tras la destrucción del sumo cultor, podremos barrer del mapa al resto de sus fuerzas, y la tierra y sus criaturas se recuperarán.\n\nGracias, &lt;nombre&gt;. Que la diosa ilumine tu camino.", rewards = "Leotardos de viento residualLeotardos de espetadora AvalanchaYelmo de caparazón de Anub'arCoselete de senda pedregosaRecibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12170] = {title = "Pelea en Río Negro", objective = "El capitán de asaltantes Kronn quiere que mates a 10 unidades o jugadores de la Alianza en el Aserradero Río Negro.", description = "Ventura y Cía. abandonaron las operaciones al poco de nuestra llegada. Está claro que tenían miedo de lo que les íbamos a hacer a sus codiciosos pellejos.\n\nSin ellos, sus aserraderos son nuestros. Nuestra maquinaria de guerra es una bestia hambrienta... si no renovamos los suministros no llegaremos a Corona de Hielo.\n\nPor desgracia, la Alianza ha tenido la misma idea, y debemos asegurarnos de que prevalecemos nosotros. Ve al aserradero y ayúdanos a luchar contra la escoria de la Alianza.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPuntos de honor"}
MultiLanguageQuestData['mx'][12171] = {title = "De traidores y traición", objective = "Enséñale la misiva de la Alianza a Palena Nube de Plata en Reposo Estelar.", description = "Esta lista tiene que llegar al alto comandante Halford Aterravermis. Él es quien lidera la Séptima Legión, apostada en la Fortaleza de Hibergarde, en la frontera oriental del gran Cementerio de Dragones.\n\nSi alguno de los traidores de esta lista está apostado en Hibergarde podría ser catastrófico.\n\nDate prisa, <nombre>. Enséñale el documento a Palena Nube de Plata aquí en Reposo Estelar y explícale el cometido de tu misión. ¡Te montará sobre el hipogrifo más rápido hacia Hibergarde!", progress = "Hola, <raza>.", completion = "&lt;Palena lee la nota.&gt;\n\n¡Vas a coger el hipogrifo más rápido que tengo, &lt;raza&gt;! Esta información debe llegar al alto comandante Aterravermis sin dilación!|n", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12172] = {title = "Armonización hacia Dalaran", objective = "La imagen de la archimaga Modera en Reposo Estelar te ha pedido que te armonices con las líneas Ley de Rasganorte.", description = "Saludos, <mago/maga>.\n\nAhora mismo te debes de estar preguntando dónde está Dalaran y cómo llegar allí. Yo te ayudaré.\n\nPero antes de que te enseñe cómo teletransportarte hasta nuestra gran ciudad, debes armonizarte con las líneas Ley de Rasganorte. Si no, te arriesgas a morir durante el proceso.\n\nCoge este cristal de armonización y úsalo en el foso que hay bajo la aguja de flujo en los Jardines Reposo Lunar al oeste. Después estarás <listo/lista> para aprender el hechizo.Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nTeletransporte a: Dalaran\n\nTe van a lanzar el siguiente hechizo:\n\nTeletransporte a: Dalaran\n\nTambién recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12173] = {title = "Armonización hacia Dalaran", objective = "La imagen del archimago Aethas Atracasol en Martillo de Agmar te ha pedido que te armonices con las líneas Ley de Rasganorte.", description = "Hola, <mago/maga>.\n\nAhora mismo te debes de estar preguntando dónde está Dalaran y cómo llegar allí. Yo te ayudaré.\n\nPero antes de que te enseñe cómo teletransportarte hasta nuestra gran ciudad, debes armonizarte con las líneas Ley de Rasganorte. Si no, te arriesgas a morir durante el proceso.\n\nCoge este cristal de armonización y úsalo en el foso que hay bajo la aguja de flujo en los Jardines Reposo Lunar al suroeste. Después estarás <listo/lista> para aprender lo que tengo que enseñarte.Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nTeletransporte a: Dalaran\n\nTe van a lanzar el siguiente hechizo:\n\nTeletransporte a: Dalaran\n\nTambién recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12174] = {title = "Alto comandante Halford Aterravermis", objective = "Entrega la misiva de la Alianza al alto comandante Halford Aterravermis en la Fortaleza de Hibergarde al este del Cementerio de Dragones.|n", description = "<Palena te devuelve la misiva.>\n\nTormenta de Nieve te llevará a Hibergarde, <nombre>. Te garantizo que será el vuelo más rápido que nunca has cogido. ¡Ve ahora!\n", progress = "¿Qué tienes ahí, soldado?", completion = "&lt;El Alto comandante lee la misiva y la estruja.&gt;\n\n¿Sabes dónde están ahora los de esta lista? Mira afuera, junto a la puerta principal. Son los que cuelgan de los arcos.\n\nCebo de necrófagos...|n", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12175] = {title = "Pieles de huargo gris", objective = "Jun'ik, el comerciante de pellejos en Bastión de la Conquista quiere que le consigas 3 pieles de huargo gris de los cazadores brumagris que hay en los bosques al norte.", description = "Deja que te diga algo, <tron/titi>. Cuando te mandan vestir a los ejércitos de la Horda, ¡utilizas un montón de pieles!\n\nLa Conquistadora Krenna, la loba que lleva este lugar, me ha puesto una fecha límite muy justa. Si no visto a todo su regimiento a finales de semana, va a echarme al pozo para que luche contra osos.\n\nAyúdame y te pagaré un buen precio. Necesito pieles de cazadores brumagris.\n\nLos encontrarás al norte, en grupos, cazando venados. Recuerda <tron/titi>. ¡Un buen precio!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Caperuza abandonadaChaleco de minero desechadoEspaldares de trampero con remiendosApisonadoras de cuevas oxidadasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12176] = {title = "Un pequeño cambio", objective = "El comerciante de pellejos Jun'ik quiere que le lleves 6 pellejos de oso pardo.", description = "Krenna quiere pieles de huargo para todos los trajes. Pero no va a haber suficientes para todo su ejército. Ni ahora ni nunca.\n\n¡Esos huargos apenas tienen pellejo, <tron/titi>! Vamos a hacer lo siguiente... si sabes mantener un secreto, claro.\n\nAl este de Runavold hay osos pardos gordos como ogros. ¡Usaremos esas grandes pieles!\n\nRápido <tío/tía>, Krenna no es famosa por su paciencia.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Togas tratadas especialmenteYelmo de piel de osoCoselete con rayas ocultasCaparazón del caídoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12177] = {title = "La mentirijilla de Jun'ik", objective = "Llévale 1 trozo de carbón y 5 paquetes de harina simple al comerciante de pellejos Jun'ik en Bastión de la Conquista en las Colinas Pardas.", description = "Oye, tenemos un pequeño problema. Las pieles de oso pardo... ¡son marrones, <tron/titi>!\n\n¡Piensa... piensa!\n\n¡Ya lo tengo, <tron/titi>! Verás, el gris es negro y blanco mezclados. Consígueme algo de carbón y algo de harina, lo machacaré todo y rociaré las pieles con eso. ¡Nadie se enterará nunca!\n\nLos herreros venden carbón para fundir y puedes conseguir la harina del proveedor.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12178] = {title = "Entrega a Krenna", objective = "Lleva el fardo de pellejos a Krenna en Bastión de la Conquista.", description = "Ya está, <tron/titi>. Llévale estos pellejos a Krenna, a ver si pasan su prueba.\n\nMás nos vale que Krenna no note nada.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12179] = {title = "Specialization 1 [PH]", objective = "LOG: Complete this quest for Specialization 1.", description = "DESCRIPTION: Complete this quest for Specialization 1.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12180] = {title = "Los prospectores cautivos", objective = "Libera al prospector Gann, al prospector Torgan y a la prospectora Varana, y luego vuelve junto al montaraz Kilian en Altozano del Prospector.", description = "Raegar envió a un equipo de prospectores a Dun Argol en busca de artefactos e información sobre la historia del asentamiento. El equipo de Raegar no esperaba que Dun Argol estuviera tan poblado.\n\nLos tienen cautivos mientras los enanos férreos se preparan para la guerra. No tenemos hombres para cargar contra ellos y Raegar, demasiado ocupado fantaseando sobre la derrota de los férreos, no sirve de mucha ayuda.\n\nRecae sobre ti, <nombre>. Cualquiera de los férreos o sus sirvientes podría llevar las llaves a las jaulas que encierran a nuestros hombres.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #3\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12181] = {title = "Ponle un nombre", objective = "Enséñale el espécimen de añublo a Tobias Sarkhoff en Nuevo Agamand.|n", description = "Ay, ay, ¿pero cuánto tiempo ha pasado ya? ¿Cuánto tiempo llevamos trabajando en esta maldita peste? Por fin, tras una eternidad de fracasos, se nos ha otorgado la perfección. Esto... ¡ni siquiera tiene un nombre aún! Este añublo... Eso es, ¡AÑUBLO! ¡Este añublo acabará con toda forma de vida!\n\n<Harris te acerca un vial.>\n\nAhora, encuentra a Tobias, el cuidador de murciélagos, y muéstrale el espécimen. Te facilitará un viaje hasta Rencor Venenoso.\n", progress = "¿Una entrega de gas venenoso y letal hasta Rencor Venenoso? ¡Sube!", completion = "Claro, claro, adelante, y cuida bien ese vial, amigo. Confío en ti.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12182] = {title = "¡A Rencor Venenoso!", objective = "Entrega el espécimen de añublo al jefe pesteador Middleton en Rencor Venenoso, al este del Cementerio de Dragones.", description = "Tengo un murciélago especial preparado para ti, <amigo/amiga>. El medio más rápido y agradable que tengo. Te llevará directamente a Rencor Venenoso... a lo grande.\n\nSolo tienes que entregar el vial al jefe pesteador Middleton cuando aterrices.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12183] = {title = "Dando el pego", objective = "Llévale el uniforme de sobrestante al montaraz Kilian en Altozano del Prospector.", description = "Si, como dijo la prospectora Varana, solo algunos férreos pueden comunicarse con el tal Loken, seguramente sean los sobrestantes quienes tengan ese privilegio.\n\nTenemos que meterte ahí para ver de qué trata todo esto, pero no será fácil. Lo primero será conseguirte un uniforme apropiado.\n\nDespués, nos pondremos a trabajar en el maquillaje.\n\nEncuentra a alguno de los sobrestantes en Dun Argol, mátalo y trae su uniforme. Si se mancha de sangre, <el único/la única> culpable serás tú.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12184] = {title = "Cultivando una imagen", objective = "Utiliza la cámara de Kilian para grabar las imágenes de 8 enanos férreos en Dun Argol y luego vuelve junto al montaraz Kilian en Altozano del Prospector.", description = "Ahora que tenemos el uniforme, tenemos que conseguir información suficiente para completar tu camuflaje.\n\nRaegar se trajo esta cámara para registrar los hallazgos del equipo, pero he pensado darle otro uso. Quiero que te la lleves a Dun Argol y la uses para capturar imágenes de los enanos férreos.\n\nClaro está que tus modelos no van a cooperar mucho, así que primero tendrás que... ehh... someterlos. Trae la cámara y las imágenes de vuelta cuando hayas terminado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12185] = {title = "Ponte tu mejor cara para Loken", objective = "Disfrázate de sobrestante Runaférrea, intercepta el mensaje de Kronus y luego informa al montaraz Kilian en Altozano del Prospector.", description = "Usando las imágenes que has conseguido, he creado todo lo que necesitas para tener un conjunto de disfraz de sobrestante. Pasarás <desapercibido/desapercibida> entre los enanos férreos, si me permites decirlo.\n\nLleva el conjunto a Dun Argol, úsalo para disfrazarte y después ve hasta el edificio que queda más al este en el amplio nivel medio de la ciudad.\n\nAllí verás un pedestal donde el señor feudal y sus sobrestantes reciben las órdenes de ese tal Loken. Actívalo mientras llevas puesto el disfraz y entérate de todo lo que puedas.", progress = nil, completion = "¿Es posible que Loken esté exagerando? Los hijos de los titanes de piedra y de hierro luchando unos contra otros por el control de la antigua ciudad de Ulduar... Es una locura, &lt;nombre&gt;, ¡y podría echar por tierra nuestra única oportunidad para conocer la verdadera historia de la raza enana!", rewards = "Bufas de previsiónCinturón de oído finoHombreras del desastre inminenteApisonadoras susurrantesRecibirás:\n\nSuministros de aventura de RasganorteObjeto #1"}
MultiLanguageQuestData['mx'][12188] = {title = "El añublo de los Renegados y tú: cómo no morir", objective = "El jefe pesteador Middleton en Rencor Venenoso en el Cementerio de Dragones quiere que le traigas 10 muestras de residuo ectoplásmico.", description = "Los detalles sobre el funcionamiento del añublo no importan demasiado. Todo lo que tienes que saber es que cumple los objetivos para los que fue diseñado. He conseguido sintetizar una cepa del añublo inerte.\n\n<Middleton destapa un vial e inhala de él.>\n\nMira, mi cuerpo está casi intacto. Si ahora mezclara esto con un agente activador, todos nos convertiríamos en montones deformes de baba.\n\nEn la playa al sur de aquí encontrarás a un montón de patéticos espectros de los antiguos soldados de la Alianza. Mátalos y tráeme su residuo ectoplásmico.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Manijas de viento residualBraciles furialesCinturón de esencia fantasmalQuijotes de brilloánimaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12189] = {title = "Los tontos abundan", objective = "Viaja hasta Rencor Venenoso en el Cementerio de Dragones y habla con el jefe pesteador Middleton.|n", description = "El envío desde Nuevo Agamand tenía que llegar a Rencor Venenoso la semana pasada y llegar a mis manos tras algunos sencillos ensayos de campo. Es un imperativo de la Horda... la última pieza del \"rompecabezas de la victoria\".\n\n<Sintar suspira.>\n\n¡Es bastante descorazonador saber que estás rodeado de idiotas y tontos incompetentes!\n\nDebes ir hasta Rencor Venenoso, cerca de la frontera este del Cementerio de Dragones. Encuentra a ese bufón Middleton y dile que sigo esperando ese envío.", progress = nil, completion = "Hemos tenido un problemilla... SIN IMPORTANCIA. Todo aquel que ha intentado tocar el añublo se ha vaporizado. Estamos trabajando para ajustar un poco la fórmula y que así no te mate al instante solo con mirarla. ¡La buena noticia es que creo que ya casi la tengo!|n", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12190] = {title = "Saluda a mi amiguito", objective = "Prigmon quiere que le lleves a Harkor sus ingredientes al Campamento Harkor.", description = "Harkor va a alucinar cuando vea estos ingredientes. Ahora solo queda llevárselos.\n\nSu campamento se encuentra en la costa este, cerca de las ruinas encantadas, Drakil'jin las llaman.\n\nLo más probable es que llegues allí antes de que pueda acabar con estos cadáveres... a menos que... ¿te gustaría probar ser un embalsamador?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12191] = {title = "¡Traga y tira!", objective = "Utiliza la jarra de degustación de la Fiesta de la cerveza de obsequio para golpear a la G.U.A.O. 5 veces, y luego ve a hablar con Bizzle Birlotutti.", description = "¡Esos malditos Hierro Negro han vuelto! Tenemos que estar seguros de que sabes defenderte si fuera necesario. Pero, lo que es más importante, ¡tenemos que asegurarnos de que puedes defender nuestra propiedad!\n\nEsta G.U.A.O. está lista para la acción, ¿y tú? ¡Bebe de las jarras de degustación de la Fiesta de la cerveza de obsequio y luego lanza la jarra a la G.U.A.O.! Acierta en el blanco 5 veces y luego ven a hablar conmigo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFicha para la Fiesta de la Cerveza"}
MultiLanguageQuestData['mx'][12192] = {title = "Ese día que estaba borracho...", objective = "Habla con Bizzle Birlotutti en el campamento de la Fiesta de la Cerveza.", description = "¡Esos Hierro Negro se han enterado de lo que vale un peine! Mientras se apresuraban a regresar hasta el Tragapenas, una parte de lo que transportaban se cayó. Pero lo más importante es que conseguiste mantener el campamento a salvo... por hoy.\n\nDirígete a Bizzle y explícale tu heroico triunfo sobre los enanos Hierro Negro.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nFicha para la Fiesta de la Cerveza"}
MultiLanguageQuestData['mx'][12194] = {title = "Oye, ¿no habrá por casualidad un souvenir este año?", objective = "Entrega el vale de jarra de la Fiesta de la Cerveza a Blix Chirimbolo en la parte trasera del campamento de la Fiesta de la Cerveza.", description = "No solo estamos suministrando cerveza a todo el mundo, ¡sino que además regalamos jarras! ¡Preciosas y conmemorativas jarras obtenidas de una manera muy legal! Aquí tienes un vale para una.\n\nHabla con Blix cerca de la parte trasera del campamento de la Fiesta de la Cerveza. Es un poco raro, sobre todo ahora que lleva esas gafas todo el rato. Te canjeará el vale y hará cualquier otra operación de la Fiesta de la Cerveza.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nJarra de la Fiesta de la Cerveza azul"}
MultiLanguageQuestData['mx'][12195] = {title = "El \"invitado\" inesperado", objective = "Llévale 5 cuernos de venado adulto a Tormak el Cicatrices en el Campamento Oneqwah.", description = "Una expedición de caza reciente trajo algo más que presas.\n\nSe encontraron un enano herido que huía del bastión de los enanos férreos de Dun Argol. Quizás sepa información que podamos usar para atacar a nuestro viejo enemigo, pero antes, para que pueda ayudarnos, tenemos que bajarle la fiebre.\n\nLos cuernos de los venados peloplata, que pastan en el bosque cercano, se han usado siempre para preparar cataplasmas curativas. Si me traes los cuernos suficientes, veremos si la cataplasma puede reanimar a nuestro \"invitado\".", progress = "¿Has traído los cuernos?", completion = "Estos servirán. Ahora, veamos si funciona.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12196] = {title = "Desde cero", objective = "Llévale 8 trozos de gólem de guerra al prospector Rokar en el Campamento Oneqwah.", description = "No tenemos suficiente tiempo para que yo me ponga solo a forjar las piezas, pero las fundiciones de Dun Argol funcionan noche y día para crear trozos de gólem como si fueran churros.\n\nCreo que deberías volver ahí y recoger los suficientes como para crear un gólem a partir de este plano.\n\nSeguramente estén esparcidos por cualquiera de los edificios en los que trabajan los forjadores Runaférrea.\n\nPor favor, <nombre>, date prisa. ¡Ese Tormak parece estar esperando cualquier excusa para cumplir sus amenazas!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12197] = {title = "Tenemos el poder...", objective = "Llévale la célula de energía de Durar y la célula de energía de Kathorn al Prospector Rokar en el Campamento Oneqwah.", description = "Bueno, tenemos la carcasa de un gólem, pero eso no es bastante para Tormak. ¡No se da cuenta de que estas cosas no vienen juntas, ni empiezan a funcionar por arte de magia! Para animarlo vamos a necesitar células de energía.\n\nCuando estaba en Dun Argol me di cuenta de que el forjador de runas Durar y el forjador de runas Kathorn eran los únicos que fabricaban esas células. Necesitaremos una de cada energía para nuestros gólems.\n\nDeberías poder encontrar a cada Forjador de runas en su taller en el nivel central de Dun Argol.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12198] = {title = "... O quizás no", objective = "Carga tu gólem de guerra con la energía de 10 avizores de relámpagos y regresa con el Prospector Rokar en el Campamento Oneqwah.", description = "Las células de los gólems tienen energía suficiente para funcionar a los niveles más bajos, pero no podemos encender sus sistemas de combate.\n\nLa buena noticia es que el perímetro de Dun Argol está patrullado por avizores de relámpagos. Deberíamos poder utilizar su energía para recargar los sistemas de armas de los gólems.\n\nLlévate al gólem y acércalo a ellos, absorberá la energía cuando los avizores mueran.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12199] = {title = "Acaba con el señor feudal férreo", objective = "Usando las habilidades de tu gólem de guerra derrota al señor feudal férreo Martillo Furioso y después habla con Tormak el Cicatrices en el Campamento Oneqwah.", description = "Ahora que el gólem está completamente cargado, puede utilizarse contra el líder de Dun Argol.\n\nCuando estudié al señor feudal férreo Martillo Furioso descubrí que siempre estaba protegido por un gólem personal que le escudaba de todo daño.\n\nA ese ensamblaje, llamado el Yunque, se le puede distraer y hacer que baje el escudo. Usa la capacidad de PEM de tu gólem para lograrlo. Serás capaz de activar y de controlar tu gólem dentro de Dun Argol.\n\nEl señor feudal está en la planta principal en la cumbre y supervisa la producción del nivel inferior.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Guantes con toma de tierraBufas descabelladasBotas de cortocircuitoGrebas de jinete de gólemRecibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12200] = {title = "Lágrimas de dragón esmeralda", objective = "El jefe pesteador Middleton en Rencor Venenoso en el Cementerio de Dragones quiere que recojas 8 lágrimas de dragón esmeralda.", description = "Con un espécimen inerte del compuesto de añublo completo y el agente activador a mano, solo nos queda conseguir un recipiente apropiado donde meter los componentes.\n\nAl suroeste de aquí, en las costas del centro del Cementerio de Dragones, es donde encontrarás el Santuario de Dragones Esmeralda. En el santuario encontrarás restos de lágrimas solidificadas de dragón Verde. No me sé toda la historia, pero, al parecer, lloran mucho antes de morir. A saber.\n\nVe al Santuario de Dragones Esmeralda y recoge lágrimas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12201] = {title = "La sombra del Sobrestante", objective = "Llévale un uniforme de sobrestante al Explorador Vor'takh en el Campamento Oneqwah.", description = "Parece que este tal Loken es la mente maestra detrás de los repentinos preparativos para la guerra de los enanos férreos.\n\nSolo los férreos de más alta posición tendrán acceso a él, así que tendremos que convertirte en un sobrestante para descubrir qué pasa ahí dentro.\n\nTengo un plan, pero para que funcione vamos a necesitar algunos suministros.\n\nEncuentra a uno de los sobrestantes runaférreas de Dun Argol, al sureste, mátalo y tráeme su uniforme.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12202] = {title = "Cultivando una imagen", objective = "Usa la Cámara de Rokar para conseguir las imágenes de 8 enanos férreos en Dun Argol, después regresa con el Explorador Vor'takh en el Campamento Oneqwah.", description = "Ahora tenemos que acabar el trabajo de hacerte tan repulsivo como esos enanos férreos.\n\nLa mejor forma de hacerlo es basar tu disfraz en los feos caretos de los enanos férreos reales.\n\nCuando la partida de caza de Tormak descubrió al prospector descarriado, le cogieron la cámara que llevaba. Supongo que ahora es el momento de usarla.\n\nLlévatela a Dun Argol, mata a algunos enanos férreos y consigue sus retratos con este artefacto. Cuando tengas ejemplos suficientes, tráelo otra vez.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12203] = {title = "Las órdenes de Loken", objective = "Disfrázate de sobrestante Runaférrea, intercepta el mensaje de Loken y después informa al Explorador Vor'takh en el Campamento Oneqwah.", description = "He creado todo lo que necesitas para tu disfraz de capataz. Intenta no vomitar cuando te lo pongas. Me ha costado mucho hacerlo tan fiel a la realidad.\n\nLlévatelo contigo al sureste de Dun Argol, disfrázate con él y después vete al edificio más al este en el gran nivel medio de la ciudad.\n\nAllí deberías ver un pedestal donde el señor feudal y los sobrestantes reciben sus órdenes de Loken. Actívalo mientras estás disfrazado y descubre todo lo que puedas de la comunicación.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12204] = {title = "En nombre de Loken", objective = "Pregunta a Hugh Copa y a Gavrock acerca de Loken, después informa de tus descubrimientos al Explorador Vor'takh en el Campamento Oneqwah.", description = "Los enanos férreos están entre los enemigos más fieros y mejor coordinados de Rasganorte. Vayamos a donde vayamos, luchan contra nosotros con el nombre de Loken en los labios.\n\nDebemos descubrir quién es este Loken y qué quiere. Los lugareños pueden ayudarnos.\n\nAl noreste, en el Puesto de Venta de Madera Roja, un humano llamado Hugh Copa vende sus mercancías. Más al este, en las Ruinas de Tethys, encontrarás a un gigante de piedra llamado Gavrock. Pregúntales por este Loken. Tienen que saber algo útil.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12205] = {title = "SE BUSCA: El Embate Escarlata", objective = "Mata a 20 miembros de El Embate Escarlata e informa al sumo ejecutor Wroth en Rencor Venenoso.", description = "Por orden del sumo ejecutor Wroth, todos los miembros de la organización ilegal conocida como El Embate Escarlata deberán ser ejecutados de inmediato.\n\nNo se mostrará piedad alguna y aquellos que ejecuten la acción del presente decreto deberán saber que cualquiera que sea capturado por los humanos morirá, ¡O algo peor!\n\nEl mensaje del Sumo ejecutor es el siguiente: \"¡Pintad la nieve de rojo con su sangre!\"Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12206] = {title = "Una extremaunción con añublo", objective = "La boticaria Vicky Levine en Rencor Venenoso te ha pedido que pruebes el frasco de añublo sobre un prisionero de El Embate Escarlata.", description = "¿Has leído el cartel de Se busca? ¡¿En qué estará pensando el sumo ejecutor?!\n\n<Vicky mira alrededor y continúa hablando en voz baja.>\n\nNo podemos tener a esos idiotas de El Embate Escarlata aprendiendo de sus sacerdotes, o lo que es peor, surgiendo como la Plaga, ¿o sí?\n\nNo, estoy totalmente de acuerdo contigo, tenemos que hacer algo con los cadáveres.\n\nTengo lo que necesitamos. Coge este añublo que acabamos de crear y pruébalo con el prisionero de esa jaula de ahí.\n\nQuien algo quiere, algo le cuesta, o tendremos a nuestros enemigos de vuelta.", progress = nil, completion = "¿QUÉ! ¡Imposible! Hemos perfeccionado el añublo. Es cien por cien letal.\n\n&lt;La boticaria retuerce las manos, mientras la preocupación invade su rostro sin vida. Claramente frustrada, continúa con un tono de enfado.&gt;\n\nEsto es muy raro. Dame ese frasco, &lt;clase&gt;. ¡No me daré a conocer como la boticaria que lo echó todo a perder!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12207] = {title = "La caída de Vordrassil", objective = "La Vidente del viento Cuerno Gris en Bastión de la Conquista quiere que vayas a la Extremidad de Vordrassil, al Corazón de Vordrassil o a las Lágrimas de Vordrassil y consigas 6 muestras de babosa de los mocos entrópicos.", description = "Hace mucho, druidas poderosos plantaron un árbol al noreste de aquí.\n\nSe llamó Vordrassil y debía haber sido un Árbol del Mundo. No se sabe por qué, pero cuando el árbol creció por completo, los druidas decidieron que debían destruirlo.\n\nDesde que llegamos aquí, la tierra me ha estado hablando, <nombre>. Sus gritos de dolor vienen de los lugares en los que cayeron al suelo los restos de Vordrassil.\n\nMocos corruptos vagan por estos lugares. Tráeme muestras para que podamos empezar a sanar a la tierra.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Toga de expurgaciónCoselete enceradoCamisote resistente a ácidoPeto de recompensas prematurasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12208] = {title = "La caza de trols", objective = "El sargento Thurkin quiere que hables con Samir en el Manantial de Granito.", description = "¡Idiotas que no sirven para nada!\n\nPodrían haberlo tenido fácil. Extendimos nuestra mano en señal de paz. Lo único que tenían que hacer era dejarnos pasar por Drak'Tharon y los habríamos dejado en paz.\n\nPero no, esos pequeños y orgullosos trols de hielo decidieron ir de duros. Ahora acabaremos con ellos y pasaremos por su preciosa fortaleza para llegar a Zul'Drak.\n\nHemos contratado a una banda para que nos consiga trols capturados. Si quieres formar parte de la acción, habla con Samir. Podrás encontrarlo al noroeste de aquí, al sur de Zeb'Halek.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12209] = {title = "Saqueo de material", objective = "El intendente Bartlett en Rencor Venenoso te ha pedido que robes 8 armaduras y 8 armas de El Embate Escarlata.", description = "Mmm, bien... carne fresca. ¿Quieres ponerte a prueba, carne fresca?\n\nEl Embate Escarlata, los más fervientes y racistas de la Cruzada Escarlata, están en nuestro patio trasero al sur. Si vamos a enfrentarnos a ellos, necesitaremos más armaduras y armas de las que me dará tiempo a fabricar en tan poco tiempo.\n\n¿Por qué no cogemos las suyas?\n\nEs más, ¿por qué no coges TÚ las suyas?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12210] = {title = "¡Temporada de trols!", objective = "El teniente Dumont en el Refugio Pino Ámbar quiere que hables con Samir en el Manantial de Granito.", description = "¡Tú, <raza>! ¡No tiene sentido que estés ahí <parado/parada> cuando hay trabajo que hacer!\n\nLa ruta más directa hasta Zul'Drak pasa por la Fortaleza Drak'Tharon. DEBEMOS capturarla para asegurarle un camino seguro a la Alianza. Pero hasta que tengamos fuerzas para lanzar un asalto, tendremos que contentarnos con debilitar a los trols de hielo y obtener información.\n\nPara ese fin, hemos contratado a un grupo de matones para que capturen y nos traigan trols vivos para interrogarlos. Viaja al noroeste y habla con Samir en el Manantial de Granito. Él te contará más.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12211] = {title = "¡No dejes que se levanten!", objective = "La boticaria Vicky Levine en Rencor Venenoso te ha pedido que uses su contenedor de ratas para no dejar ni rastro de 15 miembros de El Embate Escarlata en Nueva Vega del Amparo.", description = "Es que no lo entiendo. ¡El añublo tendría que haber funcionado!\n\nNo vale la pena lamentarse.\n\n<La boticaria, por alguna razón, parece aliviada.>\n\nAunque por alguna extraña razón no funciona con El Embate, todavía necesitamos evitar que sus sacerdotes les levanten.\n\nTengo otra idea, una contra la que sus cadáveres no tendrán protección alguna.\n\n<nombre>, coge mi contenedor de ratas y libéralas sobre cualquier cadáver de cualquier miembro de El Embate Escarlata con el que te cruces en Nueva Vega del Amparo. Privo de comida a esas alimañas, así que ¡serán como bestias!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Fajín de la peste roedoraGuanteletes de cuidador de alimañasProtegecabezas a prueba de roedoresMandiletes a prueba de picadurasRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12212] = {title = "Reabasteciendo el almacén", objective = "El maestro trabajador forestal Anderhol del Refugio Pino Ámbar quiere que mates a venados Cornalta y que consigas 8 trozos de venado suculento.", description = "Buenas, <clase>.\n\nEl bueno del teniente dice que la Horda ha atacado nuestro almacén y que nuestros suministros de comida escasean.\n\nNo dudo de que se lo haremos pagar a esos cretinos, pero primero debemos ocuparnos de reabastecernos. Mis hombres hacen todo lo que pueden, pero vamos a necesitar a todo el mundo si queremos evitar una crisis.\n\nTú no deberías tener problemas para conseguir carne de los venados de la zona. ¡Feliz cacería!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12213] = {title = "La oscuridad interior", objective = "La Vidente del viento Cuerno Gris en Bastión de la Conquista quiere que vayas a la Extremidad de Vordrassil, al Corazón de Vordrassil y a las Lágrimas de Vordrassil y que uses el Orbe de geomántico en las profundidades de la superficie.", description = "Algo... oscuro... le paso al árbol Vordrassil. Después de que los druidas decidiesen destruirlo, sus restos huecos echaron raíces profundas en la tierra.\n\nQuiero que vayas a los tres lugares al noreste, donde el tronco del árbol se rompió, y que profundices en el suelo todo lo que puedas.\n\nUsa este orbe cuando llegues allí para conseguir una huella de la energía que rodea la zona. Esto puede decirnos algo sobre qué le sucedió a Vordrassil y por qué no logró llegar a ser un Árbol del Mundo.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12214] = {title = "Monturas frescas", objective = "Hansel Bauer en Rencor Venenoso te ha pedido que robes 3 caballos de guerra de El Embate Escarlata y se los lleves. Para ello, entrégale las riendas.", description = "Hola, soy Hansel, encantado de conocerte, <señor/señora>.\n\nEl Sumo Ejecutor vino y me dijo: \"Hansel, quiero que nos consigas nuevas monturas\".\n\n¿De dónde se cree que salen los corceles nefastos, de la tierra?\n\n<Susurrando> De hecho sí, si encuentras un cementerio de caballos.\n\nPero no tenemos uno de esos, así que necesitamos que vayas al sur hasta Nueva Vega del Amparo, mates a los caballeros, cojas sus fustas y robes sus caballos de guerra.\n\nVuelve aquí sobre el caballo y entrégame las riendas, si fueras tan amable.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12215] = {title = "¡O ellos, o nosotros!", objective = "Anderhol en el Refugio Pino Ámbar quiere que encuentres y mates a 6 cazadores Brumacana en Las Colinas Pardas.", description = "Como si no tuviéramos suficiente de lo que preocuparnos...\n\nCon la crisis de alimentos que atravesamos, nos vemos compitiendo por comida con los huargos locales. La situación se está volviendo más difícil y me temo que, si no abordamos el problema inmediatamente, pronto nos encontraremos sin nada que cazar.\n\nRastrea el bosque, <raza>. Mata a cualquier Brumacana que encuentres. Informes recientes señalan una concentración al otro lado del río al oeste de aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12216] = {title = "¡Quítales el trasero!", objective = "Anderhol en el Refugio Pino Ámbar quiere que recojas 8 costillares de oso de los osos pardos de Colinas Pardas.", description = "Todos hemos trabajado mucho y estamos empezando a ver los resultados, pero aún estamos lejos de nuestro objetivo. Necesitamos mucha más carne de la que tenemos y es cada vez más evidente que la población local de venados no bastará.\n\nMe temo que necesitamos que desvíes tu atención a una presa más peligrosa: los pardos que dan nombre a esta región. Son abundantes y están bien alimentados por el abundante pescado que nada en estas corrientes.\n\n¡Ten cuidado, <clase>!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12217] = {title = "Ojos de águila", objective = "Anderhol en el Refugio Pino Ámbar quiere que mates a 5 águilas imperiales y que luego vuelvas a informarle.", description = "Bien, <nombre>, hemos averiguado cómo la Horda pudo localizar nuestros almacenes de comida ocultos.\n\nResulta que estaban vinculando su vista a las águilas desprevenidas que planean por encima de los árboles. Usando la visión de águila pudieron espiar con eficacia cada uno de nuestros movimientos.\n\nPor órdenes del teniente, tenemos que cazar a esas aves majestuosas para frustrar a nuestro enemigo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12218] = {title = "Transmite la buena nueva", objective = "El jefe pesteador Middleton en Rencor Venenoso en el Cementerio de Dragones quiere que utilices la bomba de añublo del propagador del añublo de los Renegados para acabar con 30 muertos hambrientos a las afueras de Los Campos de Carroña.", description = "Antes de que pueda mandarte al doctor Malefious con las buenas noticias, tendrás que realizar un ensayo de campo de añublo con las modificaciones que he hecho.\n\nLa multitud de muertos hambrientos sale a raudales de los pocos restos que quedan del antiguo Hibergarde. Requisa un vehículo de la puerta este y condúcelo hasta el noreste a través de Paso Venganza hasta que llegues a las torres gemelas al extremo sureste de Hibergarde. Deja caer la bomba de añublo sobre los no-muertos que invaden la zona. ¡Vuelve a informarme de los resultados!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12219] = {title = "El Árbol del Mundo fallido", objective = "La Hierofante Thayreen en el Refugio Pino Ámbar quiere que vayas a la Extremidad de Vordrassil, al Corazón de Vordrassil o las Lágrimas de Vordrassil y que le traigas 6 muestras de babosas de mocos entrópicos.", description = "Antaño mis ancestros plantaron un árbol en mitad de las Colinas Pardas.\n\nSe llamó Vordrassil e iba a convertirse en un Árbol del Mundo.\n\nPor razones ya olvidadas, después de que el árbol se desarrollase por completo, decidieron que debían destruirlo. Su gigantesco tronco se partió en tres lugares en la zona al norte.\n\nAllá donde el árbol tocó el suelo, mocos asquerosos comenzaron a reptar por la tierra. Tráeme muestras de babosas para que pueda empezar mi trabajo y sanar la tierra.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Toga de expurgaciónCoselete enceradoCamisote resistente a ácidoPeto de recompensas prematurasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12220] = {title = "Una influencia oscura", objective = "La Hierofante Thayreen en el Refugio Pino Ámbar quiere que vayas a la Extremidad de Vordrassil, al Corazón de Vordrassil y a las Lágrimas de Vordrassil y que uses el orbe de geomántico en las profundidades bajo la superficie.", description = "Cuando Vordrassil cayó, sus restos huecos echaron raíces profundas en la tierra.\n\nQuiero que vayas al norte de aquí, a los tres lugares donde el tronco se rompió y que profundices en la tierra todo lo que puedas. Los encontrarás al oeste de Fauceparda.\n\nUsa este orbe cuando llegues allí para conseguir una huella de la energía que rodea la zona. Si vamos a sanar la tierra primero debemos saber qué hizo que Vordrassil fracasase al ser un Árbol del Mundo hace todos estos años.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12221] = {title = "El añublo de los Renegados", objective = "Entrega el añublo de los Renegados al doctor Sintar Malefious en Martillo de Agmar.", description = "He preparado un paquete para el doctor Sintar Malefious en Martillo de Agmar. Entre otras cosas, el paquete incluye el espécimen final del añublo, además de instrucciones para su preparación y muestras del agente activador.\n\nEncontrarás Martillo de Agmar al oeste del Cementerio de Dragones. Tan solo tienes que buscar los edificios orcos negros y escarpados de metal... Eso es Martillo de Agmar.\nPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Hoja de hechizo con matices sangrientosMaza del sacerdote cuervo caídoMaza de batalla de BastiónArma de capitán de asedioHacha del Déspota de almenaPodrás elegir una de estas recompensas:\n\nÍdolo de restos\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12222] = {title = "Secretos de las vinculadoras de llamas", objective = "Llévale 3 talismanes imbuidos en llamas al trabajador forestal Draco en el Refugio Pino Ámbar.", description = "Mientras intentamos rechazar a la Horda, la tribu Desuelladragones se reúne en su pueblo de Runavold, cerca de la costa al sur.\n\nA los soldados más poderosos del poblado se les entregan talismanes imbuidos en llamas que les dan la capacidad de controlar a los poderosos y salvajes protodracos. Si podemos obtener el control de uno de esos dracos, quizás podríamos utilizarlo para neutralizar la amenaza que supone Runavold.\n\nLas vinculadoras de llamas Desuelladragones crean los talismanes y los imbuyen con energía. Mátalas y coge sus talismanes.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12223] = {title = "Disminuir las filas", objective = "Mata a 12 huscarles Desuelladragones y habla con el trabajador forestal Draco en el Refugio Pino Ámbar.", description = "En el poblado Runavold, al sur, hay mucha actividad. El señor feudal Torvald Eriksson y sus huscarles se preparan para la guerra. Con la mayoría de nuestros hombres desplegados ocupándose de la traición de la Horda, Pino Ámbar es vulnerable.\n\nViaja a Runavold, que está cerca de la costa sur y demuéstrale a esos Desuelladragones que no somos blanco fácil.\n\nMata a tantos de esos huscarles como encuentres. Haz que se lo piensen dos veces antes de aprovecharse de nuestro conflicto con la Horda.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12224] = {title = "¡La Vanguardia Kor'kron!", objective = "Preséntate ante Colmillosauro el Joven en la Vanguardia Kor'kron.", description = "Has hecho lo correcto, <hermano/hermana>. Te has enfrentado a todo como <un verdadero campeón/una verdadera campeona> de la Horda. ¡Has aplastado a la Plaga Anub'ar de Azjol-Nerub! ¡Los taunka son bravos y poderosos nuevos miembros de la Horda gracias a ti! ¡Nuestra súper arma contra la Plaga ha sido probada y perfeccionada por ti!\n\nHa llegado el momento, ahora. Nuestros soldados de élite en la Puerta de Cólera te necesitan. El hijo de Colmillosauro espera tu llegada en la Vanguardia Kor'kron. Ve ya, está al noreste de la Puerta de Cólera.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Sandalias de resolución de caosTrituradores de zombi implacablesBotines de la lucha valerosaBotas de viajero reforzadasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12225] = {title = "Mmm... ¡Grano ámbar!", objective = "Habla con el maestro trabajador forestal Anderhol en el Refugio Pino Ámbar.", description = "Tu estómago ruge cuando el acre olor de unas sustanciosas nueces desvía tu atención hacia el cubo de semillas.\n\nNo cabe duda de que algún alma cándida dejó aquí estos bocaditos como obsequio para rejuvenecer a los fatigados visitantes. <Agradecido/Agradecida>, coges los pocos que quedan y los devoras.\n\nEl grano no te desagrada. Con ganas de más, te propones descubrir de dónde ha salido...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12226] = {title = "Digiriendo", objective = "Anderhol en Refugio Pino Ámbar quiere que le traigas 5 tallos de raíz negra.", description = "¡Debemos reaccionar rápido, <raza>! No podemos dejar que digieras esos preciados granos. Tienen que salir, AHORA.\n\nBusca un poco de raíz negra de la orilla al oeste y te prepararé un purgante para que te ayude a cumplir con tus asuntos.\n\n¡Date prisa, corre! Y recuerda que te lo has buscado tú <solito/solita>...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12227] = {title = "Cumplir con tu deber", objective = "Anderhol en Refugio Pino Ámbar quiere que cojas la sidra hidra de Anderhol y que uses la letrina cercana para recuperar el grano ámbar semiprocesado.", description = "Bien, <raza>. Aquí está el jugo.\n\nHace efecto inmediatamente, así que no lo uses hasta que estés a salvo dentro de la letrina.\n\n¡Ahora ve por esos granos!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nAnillo fétidoSello rancioAnillo un tanto deslustrado\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12229] = {title = "Una posible relación", objective = "La Vidente del viento Cuerno Gris en el Bastión de la Conquista quiere que consigas 8 unidades de sangre de fúrbolg enloquecido de los fúrbolgs en el Santuario Colmillo Iracundo y en el Santuario Sangre de Corazón.", description = "No hace mucho mandamos a una expedición al este, donde fue atacada por fúrbolgs enloquecidos. Uno de los supervivientes dijo que al matar a uno de ellos de su cuerpo salió una sustancia oscura y pegajosa.\n\nLos fúrbolgs de esta zona han sido pacíficos durante miles de años. Es posible que haya una relación entre el comportamiento de los fúrbolgs y la energía oscura que pudimos detectar antes.\n\nTráeme muestras de su sangre. Los encontrarás al este, en el Santuario Colmillo Iracundo y en el Santuario Sangre de Corazón.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de instigadorGrilletes de corduraYelmo del purificador de fúrbolgBufas salpicadas de sangreRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12230] = {title = "Robando a los herreros de asedio", objective = "El guardia de la Muerte Molder en Rencor Venenoso te ha pedido que recojas 6 bombas de herrero de asedio.", description = "Me han encargado la destrucción de las balistas de El Embate Escarlata. Lo malo es que los boticarios y yo estamos en conflicto por el uso de nuestros recursos, así que ¡no tengo nada con lo que destruirlas!\n\nAl noreste se encuentran Los Campos de Carroña. Los herreros de asedio de la Plaga, en sus forjas y carros de despojos, son unos ases de la demolición.\n\nPor suerte para nosotros, también dejan tiradas sus bombas por ahí.\n\nQuiero que recojas unas pocas del suelo o que se las quites a los herreros, me da igual.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12231] = {title = "La progenie del dios oso", objective = "La Vidente del viento Cuerno Gris en el Bastión de la Conquista quiere que hables con Orsonn en el Santuario Colmillo Iracundo y con Kodian en el Santuario Sangre de Corazón.", description = "Es posible que los fúrbolgs de las Colinas Pardas sufran el mismo mal que contaminó a Vordrassil. Tras años de coexistencia pacífica recientemente se han visto involucrados en una guerra tribal mortal.\n\nLos santuarios que protegen al este son el hogar de la progenie de Ursoc.\n\nSi la corrupción ha afectado a los fúrbolgs, es posible que debido a su linaje, Kodian y Orsonn se hayan mantenido a salvo.\n\nSi ese es el caso, encuéntralos y escucha lo que tengan que decirte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12232] = {title = "Bombardea las balistas", objective = "El guardia de la Muerte Molder en Rencor Venenoso te ha pedido que uses las bombas de herrero de asedio para bombardear 5 balistas de Nueva Vega del Amparo.", description = "¡Por fin tenemos la oportunidad de asestar un golpe a sus máquinas de asedio! No metas la pata.\n\nEs broma.\n\nUn poco.\n\n<clase>, bombardea las balistas de Nueva Vega del Amparo con estas bombas.\n\nLes enseñaremos a los de la Sociedad Real de Boticarios cómo se hace a la antigua usanza. ¡Sin mejunjes!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Capa de saboteadorPodrás elegir una de estas recompensas:\n\nGuardacuellos de ritualAnillo de antorcha de maestro de asedio\n\nTambién recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12234] = {title = "Tengo que saber", objective = "La maestra de espías Lamento en Rencor Venenoso te ha pedido que robes las órdenes diarias de El Embate Escarlata: Abadía, las órdenes diarias de El Embate Escarlata: Barracones y las órdenes diarias de El Embate Escarlata: Playa.", description = "Tengo que saber qué traman en Nueva Vega del Amparo.\n\nQuiero que robes sus órdenes diarias para poder averiguarlo.\n\nDirígete al sur y adéntrate en la abadía, en los barracones y en la playa. ¡Encuentra esos planes diarios!\n\nEn caso de que te sientas un poco <confuso/confusa>, los barracones son el gran edificio que hay junto a la herrería.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12235] = {title = "Naxxramas y la caída de Hibergarde", objective = "Habla con el comandante de grifos Urik en la estación de grifos en la Fortaleza de Hibergarde.", description = "Lord Fordragón ha dirigido un asalto aplastante contra Arthas en la Puerta de Cólera. En respuesta a esta ofensa, Arthas ha enviado a Naxxramas contra nosotros. Mientras Kel'Thuzad se esconde en la ciudadela flotante, su comandante en tierra, Thel'zan, asedia la Fortaleza de Hibergarde. La ciudad inferior está prácticamente perdida y cualquier posibilidad de sacar supervivientes de las ruinas disminuye con cada minuto que pasa.\n\n¡Debemos actuar con rapidez! ¡Informa al comandante de grifos Urik en la estación de grifos de inmediato! Él te pondrá al corriente de todo.\n\n¡Vete!\n", progress = nil, completion = "&lt;Urik señala a un grifo.&gt;\n\n¿Has montado uno alguna vez? Es sencillo, amigo. Tan solo súbete y dile adónde ir.|n", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12236] = {title = "Ursoc, el dios oso", objective = "La Vidente del viento Cuerno Gris en Bastión de la Conquista quiere que encuentres a Tur Patafuria cerca de la guarida de Ursoc y que derrotes a Ursoc con su ayuda. Cuando hayas logrado eso, usa las Cenizas purificadas de Vordrassil con el cadáver de Ursoc.", description = "Ha llegado la hora, <nombre>. Ahora descubriremos si nuestros esfuerzos servirán para lograr lo que necesitamos o no.\n\nCoge estas cenizas y busca al fúrbolg del que te habló Kodian, Tur Patafuria, cerca de la guarida de Ursoc. Encontrarás la guarida al norte de Fauceparda.\n\nConvence a Tur para que te ayude, porque vas a necesitar toda la ayuda que puedas conseguir.\n\nUna vez hayas derrotado al dios oso, usa estas cenizas sobre su cuerpo.\n\nAunque su forma terrenal sea destruida, hay que salvar su espíritu.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Musleras de esperanza perdidaLeotardos de purificación enérgicaFalda de tormento deificadoPantalones de viento purificadoGrebas de disolución santificadaRecibirás:\n\nBaluarte del dios atormentadoSuministros de aventura de RasganorteObjeto #1"}
MultiLanguageQuestData['mx'][12237] = {title = "Vuelo del defensor de Hibergarde", objective = "Rescata a 5 habitantes de Hibergarde indefensos y vuelve con el comandante de grifos Urik a la Fortaleza de Hibergarde.", description = "Con este silbato puedes llamar a un grifo de Hibergarde. Monta sobre la criatura y dirígete hacia las ruinas del Poblado Hibergarde, ahora conocido como Los Campos de Carroña, al sureste de aquí. Cuando llegues, abre bien los ojos en busca de habitantes de Hibergarde indefensos. Cuando localices a alguno, vuela bajo y utiliza el grifo para rescatarlo. Vuelve aquí, a la estación de grifos, con el habitante que hayas rescatado.\n\nLa Plaga está por todas partes así que estate alerta, <héroe/heroína>. ¡Buena suerte!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12238] = {title = "Limpiar Drak'Tharon", objective = "Drakuru quiere que uses el elixir de Drakuru en su pedestal dentro de Drak'Tharon. Para usar el elixir de Drakuru ahí vas a necesitar 5 mojos de resistencia.", description = "Drak'Tharon pronto eh'tará limpio de esos no mueh'tos locos y volverá a su noble propósito. A cambio de tu ayuda, ¡los tesoros más valiosos de la foh'taleza serán tuyos, colega!\n\nCuando llegues a lo alto, me tienes que invocar una última vez. Protégeme, colega, y ejecutaré el ritual.\n\nPor deh'gracia, pa' invocah'me hay un precio a cambio. Tienes que recoger el mojo de los supervivientes de la foh'taleza.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Escarpes tentadoresSobrehombros del seductorGrilletes de oscuros susurrosEmbozo de la tentaciónRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12239] = {title = "La espía en Nueva Vega del Amparo", objective = "Entrega las órdenes diarias de El Embate Escarlata a la agente Skully en Nueva Vega del Amparo.", description = "Cuento con una espía entre las filas de El Embate Escarlata. Necesito que le entregues estas órdenes diarias para que pueda planificar la próxima fase de nuestro asalto.\n\nResponde al nombre de agente Skully y se esconde tras un disfraz mágico para parecer la cuidadora del cementerio de El Embate.\n\nToma, llévale estas órdenes y luego haz lo que te pida. La encontrarás en el cementerio que hay al extremo de la abadía.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12240] = {title = "Medios para un fin", objective = "La boticaria Vicky Levine en Rencor Venenoso te ha pedido que uses las termitas de la familia Levine para sacar al supervisor Kaleiki y matarlo.", description = "Con el último envío me han llegado unas barricas de termitas de parte de mi hermana desde casa, en El Baluarte. Creo que servirán para algo que quiero encargarte.\n\nLas operaciones del aserradero en Nueva Vega del Amparo nos están causando algunos problemas, pero hasta ahora no hemos conseguido meter a nadie allí para sacar a su supervisor.\n\nCreo que si soltaras a estas termitas en su preciado taller, saldría corriendo.\n\n¿Estás <listo/lista> para sacarlo de ahí, <clase>?Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12241] = {title = "Destruir el árbol joven", objective = "La Vidente del viento Cuerno Gris en el Bastión de la Conquista quiere que cojas la Antorcha verdeante y que la uses para quemar el árbol joven de Vordrassil. Dale las Cenizas de Vordrassil a la Vidente del viento Cuerno Gris.", description = "Hay que deshacer el trabajo de los fúrbolgs, <nombre>. Las mejores intenciones no sirven de nada cuando el resultado está contaminado por una corrupción tan fuerte.\n\nEl árbol joven debe ser destruido, pues es la fuente de esta oscura influencia. Coge esta antorcha y úsala para prenderle fuego al árbol joven corrupto y tráeme sus cenizas.\n\nUna vez purificado por el fuego, utilizaré el poder que pueda para quitarles la corrupción. Necesitarás las cenizas para purificar a Ursoc del poder malvado que lo tiene subyugado.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12242] = {title = "Las semillas de Vordrassil", objective = "La Vidente del viento Cuerno Gris en el Bastión de la Conquista quiere que vayas a Fauceparda y consigas 8 semillas de Vordrassil.", description = "Debemos asegurarnos de que Vordrassil no vuelva a crecer jamás. Los fúrbolgs deben haber cosechado su semilla.\n\nVe a Fauceparda, en el centro de las Colinas Pardas y coge todas las semillas que puedas encontrar. Yo me aseguraré de que sean destruidas de la forma adecuada.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Mantón del alma posesivaPodrás elegir una de estas recompensas:\n\nSortija del TiernoCollar de acaparador\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12243] = {title = "Fuego sobre las aguas", objective = "La boticaria Vicky Levine en Rencor Venenoso te ha pedido que uses el agua de fuego de la boticaria para prender fuego a las velas del Locura del Pecador.\n\nMientras los marineros de cubierta estén ocupados intentando apagar el fuego, dirígete a la cubierta inferior y recupera las rutas del capitán Shely, en posesión del capitán.", description = "Tengo otra misión para ti.\n\nPude reutilizar parte del añublo para elaborar mi famosa agua de fuego. ¡Quiero que la cojas y hagas cenizas las velas del Locura del Pecador!\n\nÚsalo desde la cubierta. Cuando las velas estén ardiendo, los marineros de cubierta estarán ocupados apagándolas, y tú te colarás bajo cubierta para \"recuperar\" las rutas del capitán.\n\nEncontrarás el barco en El Tramo del Cruzado debajo y al sur de Nueva Vega del Amparo. Busca el camarote del capitán en la primera cubierta inferior, detrás de las escaleras.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Cubremuñecas altamarBotas de errante de claroGuardahombros de Viento OestePodrás elegir una de estas recompensas:\n\nArrepentimiento del Pecador\n\nTambién recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12244] = {title = "Reparación de trituradoras", objective = "Synipus del Aserradero Cielo Azul quiere que le traigas de vuelta 3 trituradoras averiadas.", description = "Escucha, <amigo/amiga>. ¿Por qué no te arremangas y coges una llave? ¡Hay trabajo pendiente! Necesitan estas trituradoras arregladas y enviadas de vuelta a Bahía Ventura... y las necesitan para ayer...\n\n¿No tienes llave? ¿Entonces de qué me sirves? ¡Deberías irte con el resto de tontainas y jugar con la Horda!\n\nMientras estás allí, mira a ver si puedes traer algunas de esas trituradoras averiadas hasta aquí para repararlas. ¡Pero cuidado! Están en muy mal estado.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nLlave de trituradora reformada"}
MultiLanguageQuestData['mx'][12245] = {title = "Ninguna piedad con los cautivos", objective = "La maestra de espías Lamento te ha pedido que mates al guardia de la Muerte Schneider, al escribano jefe Kinnedius, al ingeniero Burke y al canciller Amai.\n\nCuando hayas cumplido esta tarea, informa de tu éxito al sumo ejecutor Wroth en Rencor Venenoso.", description = "Tenemos unos cuantos idiotas más para que mates.\n\nMis agentes me dicen que algunos de nuestros buenos ciudadanos estimaron que era pertinente caer en manos de El Embate Escarlata.\n\nNo va a funcionar.\n\nVuelve a Nueva Vega del Amparo y elimina al guardia de la Muerte Schneider, al escribano jefe Kinnedius, al ingeniero Burke y al canciller Amai.\n\nPor lo que he oído, están por toda la zona. Seguro que están encerrados en jaulas aguardando la tortura.\n\n¡Habla con ellos y luego mátalos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12246] = {title = "Una posible relación", objective = "La Hierofante Thayreen en el Refugio Pino Ámbar quiere que consigas 8 unidades de sangre de fúrbolg enloquecido de los fúrbolgs en el Santuario Colmillo Iracundo y en el Santuario Sangre de Corazón.", description = "Los fúrbolgs que viven al este de aquí son más agresivos y bestiales de los que estamos acostumbrados. Nuestras fuerzas se han enfrentado a ellos más de una vez y todos los supervivientes hablan de una sustancia oscura y pegajosa que cae de sus cadáveres.\n\nSu estado podría estar relacionado con los contaminantes que encontramos en los restos de Vordrassil.\n\nTráeme muestras de la sangre de los fúrbolgs. Los encontrarás en el Santuario Colmillo Iracundo y en el Santuario Sangre de Corazón, muy al este.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de instigadorGrilletes de corduraYelmo del purificador de fúrbolgBufas salpicadas de sangreRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12247] = {title = "Hijos de Ursoc", objective = "La Hierofante Thayreen en el Refugio Pino Ámbar quiere que hables con Orsonn en el Santuario Colmillo Iracundo y con Kodian en el Santuario Sangre de Corazón.", description = "Los fúrbolgs de las Colinas Pardas sufren alguna clase de corrupción, está claro. Después de años de existencia pacífica ha tenido lugar una guerra tribal.\n\nLo que queda por ver es si los osos a los que adoran como dioses también han sido corrompidos.\n\nLos dos hijos de Ursoc, Orsonn y Kodian, viven en el Santuario Sangre de Corazón y en el Santuario Colmillo Iracundo, al sur y al sureste de Fauceparda.\n\nIntenta hablar con ellos para saber qué ha pasado aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12248] = {title = "El árbol joven de Vordrassil", objective = "La Hierofante Thayreen en el Refugio Pino Ámbar quiere que cojas la Antorcha verdeante y que la uses para quemar el árbol joven de Vordrassil. Llévale las cenizas de Vordrassil a la Hierofante Thayreen.", description = "Los druidas de antaño parecían tener buenas razones para destruir Vordrassil. No podemos permitir que los fúrbolgs lo vuelvan a dejar crecer.\n\nPor el otro lado, salvar el espíritu de Ursoc debilita la magia contenida en el árbol joven.\n\nCoge esta antorcha y úsala para quemar el árbol. Lo encontrarás en mitad de Fauceparda, dentro del viejo tronco de Vordrassil.\n\nTráeme las cenizas de Vordrassil. Espero que una vez purificado por el fuego, podamos utilizar su magia para purificar el espíritu de Ursoc de su oscura mancha.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12249] = {title = "Ursoc, el dios oso", objective = "La Hierofante Thayreen en el Refugio Pino Ámbar quiere que encuentres a Tur Patafuria cerca de la guarida de Ursoc y derrotes a Ursoc con su ayuda. Cuando hayas logrado esto, usa las Cenizas purificadas de Vordrassil en el cadáver de Ursoc.", description = "Es la hora, <nombre>. Coge estas cenizas y busca al fúrbolg del que habló Kodian. Si ha ido a buscar a Ursoc, estará cerca de su guarida al norte de Fauceparda.\n\nNecesitarás su ayuda. No podrás derrotar <solo/sola> a Ursoc.\n\nUna vez hayas derrotado a Ursoc, usa estas cenizas para purificar su espíritu. Solo entonces sabremos si nuestros esfuerzos han sido en vano o no.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Musleras de esperanza perdidaLeotardos de purificación enérgicaFalda de tormento deificadoPantalones de viento purificadoGrebas de disolución santificadaRecibirás:\n\nBaluarte del dios atormentadoSuministros de aventura de RasganorteObjeto #1"}
MultiLanguageQuestData['mx'][12250] = {title = "Las semillas de Vordrassil", objective = "La Hierofante Thayreen en el Refugio Pino Ámbar quiere que vayas a Fauceparda y consigas 8 semillas de Vordrassil.", description = "No podemos permitir que Vordrassil vuelva a crecer. Si los fúrbolgs lo han hecho una vez, pueden volver a hacerlo.\n\nVe a Fauceparda, en el centro de las Colinas Pardas y consigue las semillas de Vordrassil. Me aseguraré de que sean destruidas adecuadamente.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Mantón del alma posesivaPodrás elegir una de estas recompensas:\n\nSortija del TiernoCollar de acaparador\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12251] = {title = "Regresa junto al Alto comandante", objective = "Habla con el alto comandante Halford Aterravermis en la Fortaleza de Hibergarde en el Cementerio de Dragones.", description = "Vuelve junto al alto comandante Halford Aterravermis de inmediato, <nombre>. Infórmale de que tu misión fue un éxito y que los pocos habitantes restantes que fueron rescatados están de vuelta al trabajo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Manijas benditas de favoritoBotas de espetadora AvalanchaPretina de Viento OesteGuanteletes de senda pedregosaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12252] = {title = "Tortura al torturador", objective = "El sumo ejecutor Wroth en Rencor Venenoso quiere que uses el hierro de marcar 5 veces sobre el torturador Alphonse para sonsacarle la información. Después, mátalo.", description = "¡Ya basta! ¡Quiero que termines con la tortura de mi pueblo!\n\nEl torturador de El Embate, Alphonse, ¡ha estado extorsionando a todo aquel que capturan esos demonios para obtener información! Necesito saber qué saben.\n\nMis fuentes me dicen que se ha establecido en la planta baja de sus barracones, justo al lado de la herrería.\n\nTe prestaré mi hierro de marcar personal para asegurarme de que el trabajo se hace bien.\n\nEncuéntralo y consigue esa información.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Ropas antiguas de viento residualCaperuza de espetadora AvalanchaEspaldares cortahieloGuanteletes de placas de cristalRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12253] = {title = "Rescátalos de Plaza de la Ciudad", objective = "El alto comandante Halford Aterravermis en la Fortaleza de Hibergarde en el Cementerio de Dragones quiere que rescates a 6 habitantes de Hibergarde atrapados.", description = "Justo al final de este sendero está la plaza de la ciudad de Hibergarde. En otros tiempos fue un hervidero de actividad para los ciudadanos de Hibergarde, y ahora es zona de guerra, llena de geists asesinos absolutamente decididos a vengarse de los vivos.\n\n¡En los edificios que rodean la plaza de la ciudad hay habitantes atrapados que debemos rescatar! Te pido demasiado, <nombre>, pero eres <el único/la única> soldado <del/de la> que dispongo. Libera a los nuestros. Coge este sendero hasta la plaza de la ciudad y entra en esas casas. ¡Mata a cualquier cosa que se interponga en tu camino! Vuelve a verme si sobrevives.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12254] = {title = "Sin una oración", objective = "La agente Skully en Nueva Vega del Amparo te ha pedido que consigas el libro de oración del Obispo Calle.", description = "Estos planes indican que algo inminente se está cociendo.\n\nPero primero, está el asunto sobre esa extraña protección que tienen las fuerzas de El Embate. Si Rencor Venenoso va a terminar con ellos de una vez por todas, debemos averiguar quiénes están detrás y acabar con ellos.\n\nHe notado que el obispo de la capilla del extremo más alejado de Nueva Vega del Amparo, al otro lado del aserradero, ha intensificado su bendición a las tropas. Mátalo y róbale su libro de oración.\n\nQuizás eso nos dé alguna pista.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12255] = {title = "El señor feudal de Runavold", objective = "Usa a Evocallamas para derrotar al señor feudal Torvald Eriksson e informa al trabajador forestal Draco en el Refugio Pino Ámbar.", description = "Ahora que has conseguido los talismanes imbuidos en llamas y debilitado las defensas de Runavold ya podemos atacar a su líder el señor feudal Torvald Eriksson.\n\nSu montura favorita es un protodraco indómito al que llama Evocallamas. Lo tiene encadenado en la parte occidental de Runavold, pero con los talismanes deberías poder controlarlo lo suficiente como para usarlo contra el señor feudal.\n\nCuando tengas a Evocallamas bajo tu control, busca al señor feudal en lo alto de las torres de Runavold y no tengas piedad.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Corona de archivatestasGuerrera del señor feudal rectificadoMusleras de feudalismo refutadoYelmo de remodelacráneosPodrás elegir una de estas recompensas:\n\nSello de segador del señor\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12256] = {title = "Los secretos de las vinculadoras de llamas", objective = "Llévale 3 talismanes imbuidos en llamas al Sargento Nazgrim en el Bastión de la Conquista.", description = "Mientras los cobardes de la Alianza atacan nuestras posiciones, el puesto destacado de Desuelladragones de Runavold, al sureste, se prepara para la guerra. Los vrykuls no son los enemigos más fuertes a los que nos hemos enfrentado aquí, pero debemos eliminarlos antes de que puedan convertirse en una amenaza.\n\nSus guerreros más poderosos pueden cabalgar sobre protodracos medio entrenados en la batalla. Para controlar a las bestias, sus vinculadoras de llamas crean poderosos talismanes. Si queremos que nuestro plan funcione, deberás matarlas y coger sus talismanes.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12257] = {title = "Una demostración de fuerza", objective = "Mata a 12 huscarles Desuelladragones y habla con el Sargento Nazgrim en el Bastión de la Conquista.", description = "El poblado vrykul de Runavold, al sureste, se está preparando para la guerra. Su señor feudal no puede reunir un gran ejército, pero con nuestras fuerzas tan dispersas, representa un riesgo.\n\nNo podemos darles la oportunidad de que nos ataquen, así que debemos combatirlos. Si eres <un verdadero/una verdadera> <clase> de la Horda, aprovecharás esta oportunidad para demostrarles nuestra fuerza.\n\n¡Acaba con los huscarles y demuéstrale al clan Desuelladragones que no hay que jugar con la Horda!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12258] = {title = "El destino de los muertos", objective = "La comandante Lynore Ventostryke en la Fortaleza de Hibergarde en el Cementerio de Dragones quiere que mates a 15 geists vengativos.|n", description = "La plaza de la ciudad, al final de este camino, ¡está invadida con ciudadanos no-muertos de Hibergarde! Nuestra propia cripta proporciona lo que parece un suministro interminable de soldados de la Plaga contra nosotros. Pero no tengas piedad de ellos, <nombre>. Aunque una vez fueron mortales, capaces de sentir compasión y reflexión, ahora son no-muertos saqueadores con un único propósito: destruirnos.\n\nAdéntrate en la plaza de la ciudad y entrega los geists vengativos a su creador. Dales la paz.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Cincho de viento residualGuantes de espetadora AvalanchaAtaduras cortahieloEscarpes de senda pedregosaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12259] = {title = "El señor feudal de Runavold", objective = "Usa a Evocallamas para derrotar al señor feudal Torvald Eriksson e informa al Sargento Nazgrim en el Bastión de la Conquista.", description = "Al fin podemos desafiar al señor feudal, gracias a los talismanes imbuidos en llamas.\n\nSu montura favorita es un protodraco feroz llamado Evocallamas. Lo tiene encadenado en el lado oeste de Runavold, pero con los talismanes deberías poder hacer que te obedeciese y utilizarlo contra el señor feudal.\n\nCuando lo tengas bajo tu control, busca al señor feudal en la parte alta de las torres de Runavold y usa a Evocallamas para destruirlo.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Corona de archivatestasGuerrera del señor feudal rectificadoMusleras de feudalismo refutadoYelmo de remodelacráneosPodrás elegir una de estas recompensas:\n\nSello de segador del señor\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12260] = {title = "La máscara perfecta", objective = "La agente Skully en Nueva Vega del Amparo te ha pedido que robes la imagen de un sacerdote cuervo del Embate. Devuélvele el espejo mágico de alma en pena cuando hayas terminado.", description = "Debes de estar preguntándote cómo puedo mantener este disfraz. Utilizo un espejo mágico que me prestó la maestra de espías.\n\nPor sí solo contiene mucho poder, pero creo que hay suficiente para <los/las> dos. Mira, cógelo. Quiero que lo uses para que te hagas pasar por uno de los sacerdotes cuervo del Embate.\n\nSé <rápido/rápida>... no tengo ni idea de cuánto tiempo durará mi atractivo mientras tú tengas el espejo.\n\nRecuerda que no quedarás perfectamente <disfrazado/disfrazada> de inmediato, así que no cuentes con que sea infalible hasta que yo pueda ayudarte.Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nThe Perfect Dissemblance: Quest Completion\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12261] = {title = "Sin escapatoria", objective = "Coloca un resguardo destructivo en la senda de salida del Santuario de Dragones Obsidiana donde la carretera empieza a dar paso a la nieve. Protege el resguardo hasta que se cargue por completo y luego vuelve junto a Serinar.", description = "Están sacando poder de los huesos de mis hermanos muertos.\n\nNo siento afición por el culto, pero me desconcierta su audacia. No habrá ninguna compasión hacia ellos... no es que fueran a tenerla.\n\nAsegúrate de que no tienen adónde huir cuando empiece la matanza. Coloca un resguardo destructivo en la senda de salida del santuario donde la carretera empieza a dejar paso a la nieve. Defiéndelo hasta que se termine de cargar.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12262] = {title = "Nadie para salvarte", objective = "Mata a 6 necrólitos de las profundidades ardientes y a 10 esqueletos en el exterior del Santuario de Dragones Obsidiana. Vuelve junto a Serinar cuando hayas completado la tarea.", description = "No dejaremos ni uno.\n\nAfuera, unos despreciables necrólitos junto con sus sirvientes esqueléticos deshonran mi tierra con su presencia. Mátalos a todos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12263] = {title = "La mejor de las intenciones", objective = "Espera a Serinar para que te administre el disfraz de un necrólito de las profundidades ardientes y luego entra hasta la parte posterior de las Fauces de Neltharion para averiguar lo que el Culto de los Malditos está haciendo allí. Vuelve junto a Serinar con los detalles de sus intenciones.", description = "El Culto de los Malditos no ha venido solo para extraer el poder de los dragones muertos. Sospecho que sé lo que traman, pero necesito que tú lo confirmes.\n\nTe daré este disfraz de necrólito muerto. Ve hasta la parte trasera de la cueva y confirma las intenciones que tienen para estar en este lugar sagrado. Yo veré a través de tus ojos.\n\nTen cuidado, <nombre>, cualquier daño que te provoquen podría romper esta frágil ilusión.Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nEliminar disfraz y vista de Serinar\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12264] = {title = "La matanza de los Malditos", objective = "Mata a 3 nigromantes de las profundidades ardientes, 6 ensamblajes en llamas y 6 geists en llamas en las Fauces de Neltharion, y luego vuelve junto a Serinar.", description = "La cueva de ahí estaba plagada de abominaciones del Culto. Solo hay una manera de acabar con esas criaturas... Ya sabes qué hacer.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12265] = {title = "Profanando a los profanadores", objective = "Encuentra y destruye 8 runas nigrománticas que se han dibujado en el suelo dentro de las Fauces de Neltharion. Vuelve junto a Serinar cuando completes esta misión.", description = "Sentí una gran acumulación de magia en las runas que observamos mientras estabas explorando la cueva. No te pondré a jugar extrayendo la magia... Normalmente la solución más directa es la más efectiva.\n\nAcaba con las runas... Destrúyelas y asegúrate de que el Culto no tenga acceso al poder que hayan acumulado ahí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12266] = {title = "Historias de destrucción", objective = "Vuelve a Reposo del Dragón e informa a Nalice de que has completado la misión de Serinar.", description = "Ya te puedes ir, <raza>.\n\nVe a decirle a Nalice que se ha perdido una buena matanza.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12267] = {title = "La llama de Neltharion", objective = "Utiliza la llama de Neltharion para apagar la zona de invocación de la parte posterior de las Fauces de Neltharion. Cuando llames la atención de Rothin el Putrefacto, mátalo y vuelve junto a Serinar delante de la cueva.", description = "Ahora que las filas del culto se han reducido y parte de su poder se ha aplacado, es hora de atacar el origen de la corrupción.\n\nRothin el Putrefacto está resucitando dragones Negros en forma de magmavermis al fondo de la cueva. Ve hasta la cámara de invocación y limpia los huesos sobrantes del único modo posible, para asegurarnos de que nadie vuelva a jugar con ellos: con llamas.\n\nAl quemar los huesos es muy probable que llamemos la atención de Rothin; asegúrate de acabar también con él.\n\nLa magia de este vial cumplirá con esta tarea.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Togas del sumo sacerdote ForithMantón de Lord PrestorQuijotes del caballero conquistadoPodrás elegir una de estas recompensas:\n\nCollera de vermis esclava\n\nTambién recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12268] = {title = "Piezas y partes", objective = "Pipthchiflo en el Aserradero Cielo Azul quiere que consigas 4 engranajes con muescas, 3 ruedas dentadas y 2 resortes de alta tensión.", description = "¡Ag! ¡Esta cosa es un lío!\n\nLa ingeniería goblin deja mucho que desear, créeme. ¡Es que mira esto! Para empezar, ya es sorprendente que siquiera funcionase.\n\nÉchame una mano, ¿quieres? Para hacer que esto se acerque a funcionar necesitaré cambiar algunos muelles, tuercas y engranajes. No deberías tener problemas para encontrarlos por la zona del aserradero.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12269] = {title = "No en nuestra mina", objective = "El alto señor Leoric Von Zeldig en la Fortaleza de Hibergarde en el Cementerio de Dragones quiere que recuperes 10 tarjetas de minero de Hibergarde.", description = "¡El ataque de esa maldita necrópolis nos pilló por sorpresa! Tras su destrucción, perdimos la Mina de Hibergarde. Y lo que es peor, los acólitos de Kel'Thuzad han resucitado a los mineros muertos como miembros de la Plaga ¡y los están usando para abastecer a sus herreros de asedio con materiales de nuestra mina!\n\nDebemos detener ese abastecimiento y dejar a nuestros hermanos fallecidos descansar.\n\nViaja hasta la Mina de Hibergarde, al noreste de aquí en Los Campos de Carroña, y acaba con los mineros resucitados. Vuelve a verme con sus tarjetas de minero para que pueda anotar su muerte en nuestro registro.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12270] = {title = "Machaca a la Alianza", objective = "Grekk en el Aserradero Cielo Azul quiere que consigas 3 trituradoras y se las lleves.", description = "Lee mis labios, <clase>: ¡necesito esas trituradoras! Y lo que es más importante, ¡las necesito lejos de las manos de la Alianza!\n\nHan estado modificando las trituradoras y utilizándolas contra nuestros hermanos en Bahía Ventura. ¡Ahora vamos a darles un poco de su propia medicina!\n\nSi ves una trituradora ahí fuera, ¡la coges! Si ves a escoria de la Alianza montada en una, ¡mátalo y cógela! Cuando tengas una, tráemela hasta aquí y nos pondremos a trabajar en ella.\n\n¡Rompan filas!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nLlave de trituradora reformada"}
MultiLanguageQuestData['mx'][12271] = {title = "La vara de coacción", objective = "Entrega la vara de torturador al sumo ejecutor Wroth en Rencor Venenoso.", description = "Una vara cae de la mano sin vida de Alphonse. A lo largo tiene unas runas mágicas que laten.\n\n¿Será quizás así como conseguía las confesiones?\n\nSerá mejor que el sumo ejecutor la vea.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12272] = {title = "La mena sangrante", objective = "El ingeniero de asedio Quartoflash en la Fortaleza de Hibergarde en el Cementerio de Dragones quiere que consigas 10 muestras de mena extraña de la Mina de Hibergarde.", description = "Horas antes de la invasión de Naxxramas, uno de los mineros tropezó con una mena oscura que rezumaba un fluido viscoso. En medio del caos que ocurrió durante la evacuación de la mina, perdimos las muestras tomadas del extraño nódulo. Ahora la Plaga está buscando la mena para usarla en sus máquinas de muerte.\n\nDebes volver a la Mina de Hibergarde, al noreste de aquí en Los Campos de Carroña, y recuperar la mena extraña. ¡Es imprescindible para el éxito de nuestra misión!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12273] = {title = "La acusación", objective = "El sumo ejecutor Wroth en Rencor Venenoso te ha encargado la tarea de usar la vara de coacción con el comandante Jordan, el cañonero mayor Zierhut, el herrero Buenhombre y el maestro de establos Mercer.\n\nCuando hayas usado la vara con ellos, mátalos para coaccionarlos a hacer de sus últimas palabras una acusación contra El Embate Escarlata.", description = "¡Ya es hora de que por fin desmoralicemos al ejército de El Embate!\n\nQuiero que cojas la vara y la uses sobre cuatro de sus líderes: el comandante Jordan en la parte de arriba de los barracones; el cañonero mayor Zierhut abajo en el desnivel al sureste que asoma a la playa; el herrero Buenhombre en la herrería, y el maestro de establos Mercer en los establos.\n\nPonlos bajo la coacción de la vara, concéntrate en hacerles acusar a El Embate y luego ¡mátalos!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Toga de lágrimas calcificadasLeotardos hechos con carne de torturadorGuardamuñecas de dador de dolorEscarpes del déspotaRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12274] = {title = "Caída en desgracia", objective = "La agente Skully en Nueva Vega del Amparo te ha pedido que toques la campana de la abadía y luego vayas a hablar con el sumo abad para sonsacarle información.", description = "Necesitamos más información del sumo abad, y ahora que conocemos el rostro de uno de los sacerdotes cuervo, creo que podemos acercarte a él para que habléis.\n\nSin embargo, tenemos que separarlo de sus guardaespaldas o nunca le sacarás la información.\n\n<La agente se apoya sobre su pala y piensa durante un momento.>\n\n¡Creo que ya lo tengo! Mientras tengas el disfraz puesto, ve a lo alto de la abadía y haz sonar la campana. Eso debería atraer corriendo a los guardaespaldas del abad y entonces podrás bajar a hablar con él.Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nA Fall from Grace: Quest Completion\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12275] = {title = "El Demognomo", objective = "Habla con el ingeniero de asedio Quartoflash en la Fortaleza de Hibergarde en el Cementerio de Dragones.", description = "Quartoflash se apropió hace poco de mi grupo para coger a algún especialista que pudiera enviar a una misión de reconocimiento a la Mina de Hibergarde. Para ese fin, envié a Slinkin, mi demoledor. Fui tonto al pensar que podría dejar zanjado ese foso de condenación después de que completara su misión para Quartoflash, otorgándonos otra victoria contra la Plaga.\n\nAhora ha pasado un día entero y Slinkin no ha vuelto. ¡Quiero respuestas! ¡Habla con el ingeniero de asedio Quartoflash y localiza a mi agente desaparecido!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][12276] = {title = "La búsqueda de Slinkin", objective = "Encuentra a Slinkin el Demognomo en la Mina de Hibergarde. Utiliza el buscabot de Quartoflash si necesitas ayuda para encontrar la mina.\n\nObjeto provisto: \n", description = "Aunque no he sabido nada de Slinkin ni sé cuál fue su destino, quizás pueda ayudar para encontrarlo.\n\n<Quartoflash sujeta un juguetito mecánico.>\n\nEsto no es un juguete, flamante compatriota. Es, de hecho, mi última creación mecánica. La máquina fue creada con el único propósito de encontrar lo que se ha perdido. Estas son circunstancias desafortunadas, pero la máquina te brindará la mejor oportunidad para encontrar a Slinkin.\n\nCuando estés <preparado/preparada> para comenzar tu búsqueda, coloca el robot en el suelo a mi lado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12277] = {title = "No dejes nada a la suerte", objective = "Recupera una bomba de la Mina de Hibergarde y úsala para volar por los aires el eje de la Mina de Hibergarde alta y el eje de la Mina de Hibergarde baja. Vuelve a informar al ingeniero de asedio Quartoflash en la Fortaleza de Hibergarde en el Cementerio de Dragones cuando hayas completado esta misión.", description = "Si tu corazón es bondadoso y tu conciencia está limpia, sigue leyendo.\n\nEn esta mina, cerca del andamio del capataz, hay un cargamento considerable de dinamita. Ve allí, coge unos cuantos paquetes de explosivos y ábrete camino hacia la entrada de la mina. Una vez allí, coloca la dinamita y vuela la entrada por los aires. Recuerda hacer esto tanto por la parte superior como por la inferior de la Mina de Hibergarde.\n\nNo dejes nada a la suerte. No debemos permitir que salga el mal que aquí reside. Que la Luz te guíe.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Capa de honornatoGuardapiés de hueso petrificadosPodrás elegir una de estas recompensas:\n\nObjeto #1Sello de juramentoFlores Toquesol\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12279] = {title = "Hambre de osa", objective = "Llévale 6 salmones del norte a Hugh Copa en el Puesto de Venta Madera Roja.", description = "¡Menos mal que has vuelto, <Cojito/Cojita>! Me preocupaba que Griselda y yo fuésemos a quedarnos solos.\n\nEstoy cocinando algo para nosotros, pero Griselda no va a comer nada.\n\nElla quiere los peces que viven en la costa de la Playa Viento Este, al este. Yo no los soporto, pero ella siempre ha sido muy picajosa para la comida. Seis peces de buen tamaño deberían contentarla durante un rato.\n\nAhora corre... err... cojea, Joe. No querrás hacer esperar a la muchacha, ¿verdad?", progress = "Si no te das prisa, va a rugirle algo más que el estómago...", completion = "¡Tú! ¡Tú no eres Joe el cojo!", rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12280] = {title = "Haciendo arreglos", objective = "Lurz en el Aserradero Cielo Azul quiere que consigas 4 engranajes con muescas, 3 ruedas dentadas y 2 resortes de alta tensión.", description = "¡Veinte trituradoras para mañana al mediodía!\n\n¿Pero quién hace estos planes? Seguro que nadie que haya montado uno de esos cubos de basura...\n\nPara cumplir el encargo, voy a necesitar ayuda. Ayúdame y te daré parte de mi comisión, ¿te parece bien?\n\nNecesito engranajes, muelles y ruedas. Están por el suelo, cerca de las trituradoras.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12281] = {title = "Comprender la máquina de guerra de la Plaga", objective = "Entrega el paquete de Quartoflash al alto comandante Halford Aterravermis en la Fortaleza de Hibergarde.", description = "Debemos consolarnos por el hecho de que la muerte de Slinkin, aunque trágica, fue por nuestro bien. Su descubrimiento hizo posible tu hazaña en la mina y las muestras que nos has traído nos ayudan a comprender un poco más la máquina de guerra de la Plaga.\n\nLlévale este paquete al alto comandante Halford Aterravermis, contiene una muestra de mena extraña y mi análisis.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12282] = {title = "Huellas en el pasado", objective = "Zelig el Visionario en la Fortaleza de Hibergarde del Cementerio de Dragones quiere que recuperes su orbe de visión.", description = "Las memorias del pasado atormentan esta tierra, <nombre>. Oigo los gritos de los caídos resonar a través de Rasganorte llamándome.\n\nArthas dejó una huella terrible en todo lo que tocó. Tras su paso, solo quedan descomposición y falta de vida. Es importante estudiar el pasado para poder conocer mejor a nuestro enemigo, quizás saquemos a la luz verdades jamás contadas que puedan ayudarnos en nuestra campaña.\n\nPrimero, tienes que recuperar mi orbe de visión del concejo, <nombre>. Sal de esta torre y gira a la izquierda por el camino hasta llegar a la plaza.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Togas de visionarioGuantes del vidente orientadoresCapacete vigilantePodrás elegir una de estas recompensas:\n\nAnticipación de previsión\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12283] = {title = "La verdad saldrá", objective = "La agente Skully te ha pedido que consigas el diario de la alta general Abbendis y se lo lleves al sumo ejecutor Wroth en Rencor Venenoso.", description = "Tenemos que averiguar qué está ocurriendo. ¡Necesitamos el diario de la General!\n\nEstoy segura de que lo encontrarás sobre su mesilla de noche en el piso superior de su casa. Es la siguiente a la iglesia, al otro lado de los establos y del aserradero.\n\nCuando consigas el diario, llévaselo al sumo ejecutor en Rencor Venenoso.\n\nTendrás que hacer esto a la antigua... el poder del espejo es débil y solo queda lo justo para mí.\n\n<La agente sonríe con suficiencia>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12284] = {title = "Que se queden donde están", objective = "El comandante Bargok quiere que mates a 15 unidades o jugadores de la Alianza en el Aserradero Cielo Azul.", description = "Hemos sufrido muchas bajas, <raza>.\n\nLa única buena noticia es que hemos dado tanto como nos han dado. He pedido más tropas, pero la mayoría de nuestras fuerzas están atascadas en Bahía Ventura. Parece que por ahora estamos solos.\n\nDa igual lo mal que se ponga, ¡DEBEMOS mantener las líneas! Los valiosos recursos de esta región son esenciales para el éxito a largo plazo de la Horda en Rasganorte.\n\nTenemos que mantener a raya a la Alianza hasta que llegue ayuda. Ve allí y dales algo en lo que pensar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12285] = {title = "Hacer a los demás", objective = "El sumo ejecutor Wroth te ha ordenado que vuelvas con la cabeza de la Alta General.", description = "Su ataque es inminente, <clase>. Necesito que te adentres allí y cercenes la cabeza de El Embate Escarlata, ¡literalmente!\n\nNo te va a resultar fácil... Abbendis estará rodeada de muchos de sus hombres.\n\nTrae su cabeza y me encargaré de que se te recompense adecuadamente por salvar Rencor Venenoso.\n\n¡Si fracasas, no te molestes en volver!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Sortijas de guerra ungidas en purezaGuardamuñecas del arrepentidoAtaduras del vencedor vigorosoPuños del DecapitadorRecibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12286] = {title = "Cubo de caramelos", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nTruco o trato\n\nRecibirás:\n\nPuñado de golosinas"}
MultiLanguageQuestData['mx'][12287] = {title = "Orik Corazón Veraz y La Orilla Olvidada", objective = "Busca la ayuda de Orik Corazón Veraz en Tramo del Alba en el Cementerio de Dragones.", description = "He observado el orbe y he visto el camino que deberás seguir, <nombre>.\n\nHace muchos años se cometió una atrocidad en las costas del Cementerio de Dragones. El acto en sí permanece cubierto de misterio, pero seguro que tu destino está al sur, entre las ruinas de La Orilla Olvidada.\n\nToma el camino al sureste a través de la plaza devastada. Sigue el camino hasta que llegues a Tramo del Alba. Allí te encontrarás con un viejo amigo mío conocido como Orik Corazón Veraz. Te estará esperando.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12288] = {title = "¡Abrumado!", objective = "Aumana en el Aserradero Cielo Azul quiere que uses el Torniquete de renovación en 10 hostigadores heridos.", description = "¡Oye, tú, <clase>! ¡Ayúdame!\n\n¡Estamos perdiendo vidas valiosas! Hay demasiados heridos para que yo pueda ocuparme de todos. ¡Y si no podemos sanar a nuestros soldados, puede que nos echen de las Colinas Pardas!\n\nCoge este torniquete y úsalo en los heridos en el campo de batalla.\n\n¡Rápido, <nombre>! ¡Que se muereeeen!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12289] = {title = "Golpéalos mientras han caído", objective = "El sargento Hartsman quiere que derrotes a 15 unidades o jugadores de la Horda en el Aserradero Cielo Azul.", description = "Es un día triste para la Alianza. Aquí han muerto o agonizan muchos hombres buenos. Nuestro único consuelo es que lucharon bien y se llevaron con ellos a muchos enemigos.\n\nCon el grueso de nuestras fuerzas en Bahía Ventura, solo nosotros podemos capear el temporal. Los recursos de esta región son vitales para la Alianza y pueden marcar la diferencia en nuestra guerra contra la Horda. ¡No debemos fracasar!\n\nVe, <nombre>. Golpéalos mientras se lamen sus heridas. ¡Venga a tus hermanos caídos y mantén vivas nuestras esperanzas!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12290] = {title = "El elixir de hierba tiniebla", objective = "Orik Corazón Veraz en Tramo del Alba en el Cementerio de Dragones quiere que recojas 5 muestras de hierba tiniebla de las Cumbres Fantasmales.", description = "Los espíritus de los malditos atormentan la costa. En vida eran soldados valientes y nobles de la Alianza, pero en muerte están malditos... atrapados en este mundo hasta el final de los tiempos. Debemos descubrir el origen de su angustia si queremos liberarlos.\n\nAl sureste, en las Cumbres Fantasmales, encontrarás una hierba poco común conocida como hierba tiniebla. Esa hierba tiniebla será la que usaré para hervir un elixir que te permitirá entrar temporalmente al mundo de los olvidados. Ve a buscar hierba.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12291] = {title = "La historia olvidada", objective = "Orik Corazón Veraz en Tramo del Alba en el Cementerio de Dragones quiere que escuches las historias de un campesino olvidado, un fusilero olvidado, un caballero olvidado y un lacayo olvidado.", description = "Las toxinas del elixir de hierba tiniebla te dejarán inconsciente. El efecto de la hierba tiniebla es tan fuerte que también afectará a tu espíritu, permitiéndote acceder temporalmente al mundo de los muertos.\n\nCuando seas un espíritu, deberás hablar con los moradores fantasmales de La Orilla Olvidada. Averigua la causa de su angustia y vuelve conmigo.\n\nRecuerda, <nombre>, esos espíritus eran soldados de la Alianza. Trátalos con respeto, honor y dignidad.\n\nAhora, elixir en mano, aventúrate hacia el sur a La Orilla Olvidada.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12292] = {title = "Apoyo local", objective = "El teniente Dumont en el Refugio Pino Ámbar quiere que vayas al Puesto de Venta de Siempreverde y consigas el cofre de cedro.", description = "Estamos estancados con la Horda en las Colinas Pardas. Nuestras fuerzas están a punto de igualarse y hasta ahora todo señala a un punto muerto.\n\nHasta esta mañana, quiero decir. Los tramperos locales han pedido nuestra ayuda. Al parecer, la Horda se llevó algo que les pertenece... algún tipo de reliquia.\n\nLes conseguimos eso y ellos nos dan la ventaja que necesitamos. Dirígete al Puesto de Venta de Siempreverde al oeste del Bastión de la Conquista y busca un cofre de cedro.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Leotardos antizarzasCapa de trampero malheridoPantalones de piel de parcheMusleras de búsqueda prestaQuijotes chascadientesRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12293] = {title = "Cierra el trato", objective = "Llévale el cofre de cedro a Ivan en el Puesto de la Alameda.", description = "Tenemos lo que quieren los tramperos. Ahora les toca a ellos cumplir su parte del trato.\n\nLlévale el cofre a un trampero llamado Ivan en el Puesto de la Alameda, justo al norte de aquí.\n\nSi todo va bien, tendremos a los trabajadores forestales de la zona trabajando como exploradores para el ejército del rey en un santiamén.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12294] = {title = "Un pacto provisional", objective = "Vuelve junto al teniente Dumont en el Refugio Pino Ámbar.", description = "Muy bien, <nombre>. Los tuyos han cumplido su parte del trato.\n\nDile a Dumont que cumpliremos la nuestra.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12295] = {title = "Un ejercicio de diplomacia", objective = "Habla con el enviado Ducal en Arroyoplata.", description = "Llevamos semanas intentando negociar con los tramperos, pero no conseguimos nada hasta que encontraste ese maldito cofre.\n\nSeguramente nuestro enviado en Arroyoplata se alegrará de saberlo. Enviamos a Ducal allí hace cerca de una semana y su última carta indicaba que no había logrado mucho.\n\nVe a Arroyoplata y ayúdalo en su misión diplomática. Toma los caminos que se dirigen al noroeste y llegarás tras cruzar un par de puentes.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12296] = {title = "A vida o muerte", objective = "Rheanna en el Aserradero Cielo Azul quiere que uses el vendaje de renovación en 10 soldados de infantería de los Páramos de Poniente heridos.", description = "Oh, la matanza...\n\nHe estado en muchas batallas, <clase>, y esta ha sido la más brutal que he visto. Nuestra guerra con la Horda es más intensa que nunca. En Rasganorte somos nosotros o ellos, es a vida o muerte.\n\nSi queremos sobrevivir aquí otro día, debemos curar a nuestros heridos. Son demasiados para que los salve yo sola.\n\nHe preparado unos vendajes especiales que te permitirán ayudarme. Toma uno y ocúpate de aquellos que todavía no hayan sucumbido a sus heridas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12297] = {title = "De traidores y traición", objective = "El capitán Adams te ha pedido que le enseñes la misiva de la Alianza a Greer Martillo de Mena en la Fortaleza de la Guardia Oeste.", description = "Esta lista tiene que llegar al alto comandante Halford Aterravermis. Él es quien lidera la Séptima Legión, apostada en la Fortaleza de Hibergarde, en la frontera oriental del gran Cementerio de Dragones.\n\nSi alguno de los traidores de esta lista está apostado en Hibergarde... podría ser catastrófico.\n\nDate prisa, <nombre>. Enséñale el documento a Greer Martillo de Mena, que está aquí, en la Fortaleza de la Guardia Oeste, y explícale el cometido de tu misión. ¡Te montará sobre el grifo más rápido hacia Hibergarde!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12298] = {title = "Alto comandante Halford Aterravermis", objective = "Entrega la misiva de la Alianza al alto comandante Halford Aterravermis en la Fortaleza de Hibergarde al este del Cementerio de Dragones.|n", description = "<Greer te devuelve la misiva.>\n\nCantocielo te llevará hasta Hibergarde, <nombre>. Te garantizo que será el vuelo más rápido de tu vida. ¡Vete ya!\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12299] = {title = "La hospitalidad norteña", objective = "Sergei en Arroyoplata quiere que mates a 8 maleantes del Bastión de la Conquista.", description = "Es un placer conocerte. Celebremos nuestro acuerdo mediante un poco de matanza de la Horda a la antigua usanza.\n\nEncontrarás a algunos maleantes del Bastión de la Conquista a las afueras de la ciudad al oeste de aquí. ¿Por qué no sales ahí y los cazas como sucios animales que son?\n\nVeamos si nuestros nuevos aliados pueden demostrar su palabrería con un poco de acción.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nTalismán de mendigoGarfa de OdioInsignia de fuego sangriento\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12300] = {title = "Prueba de valor", objective = "Encuentra al sargento Cascahueso al oeste de Arroyoplata y supera la prueba de valor.", description = "Muy bien, <amigo/amiga>. Nos has hecho un par de favores, pero esa no es la verdadera prueba del valor de una persona.\n\nAquí no se es un verdadero cazador hasta que no se lleva encima la piel de la presa.\n\n<Sergei desenvaina su cuchillo para desollar y te lo entrega.>\n\nEl líder de esos orcos sin madre que atacan nuestra ciudad es un tal Cascahueso. Lo encontrarás en un campamento más al oeste.\n\nEso es. Vas a despellejar a ese monstruo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12301] = {title = "La verdad nos hará libres", objective = "Orik Corazón Veraz en Tramo del Alba en el Cementerio de Dragones quiere que uses el orbe cristalino de Orik en las ruinas de La Orilla Olvidada para redimir a los Olvidados.", description = "Zelig me dio esta bola de cristal hace algunos años con instrucciones específicas sobre su uso. Durante cinco años, cuando sentía rabia, ansiedad o pena por los acontecimientos que ocurrían, debía concentrar mis pensamientos sobre el orbe.\n\nAhora entiendo por qué Zelig me dio este cristal.\n\nLlévate mi orbe cristalino a La Orilla Olvidada. Encuentra las ruinas de mi antigua base en lo alto de la playa y coloca el orbe en el centro de la ciudad. Deja que los olvidados vean el mundo a través de mi corazón y alma.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12302] = {title = "Una advertencia", objective = "Ve al extremo noroeste de Arroyoplata.", description = "Gracias por tu ayuda, <nombre>. Me llamo Sasha. Mira, tengo que salir de aquí.\n\nLa gente que te ha enviado aquí... mi gente... ha cambiado. Han perdido la bondad y quieren convertirte a ti en uno de ellos...\n\nEsta... \"prueba\" por la que te hacen pasar es solo el principio.\n\nDirígete al extremo noroeste de Arroyoplata. Encontrarás algo que te interesará.\n\nBuena suerte... y no te fíes de nadie.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12303] = {title = "Financiar la guerra", objective = "El intendente Bartlett de Rencor Venenoso te ha pedido que recuperes 6 tesoros olvidados.", description = "<El intendente baja la voz y te susurra.>\n\n<clase>, necesito tu ayuda. Nuestros cofres están vacíos. La vanguardia Kor'kron de la Puerta de Cólera se ha llevado todo nuestro dinero para esa pelea.\n\nPero he oído rumores de que tiene que haber un tesoro entre los náufragos en La Orilla Olvidada en el sureste.\n\nTenemos que hacer algo pronto o no podremos seguir luchando contra El Embate Escarlata. ¡Ya sabes que la guerra no es barata!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Caperuza del fusilero olvidadoPechera del Capitán olvidadoHoja de guerra del lacayo olvidadoPodrás elegir una de estas recompensas:\n\nAro del mercenario olvidadoRecuerdos de Valonante\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12304] = {title = "Propiedad delante de la playa", objective = "El perito Hansen, justo en el norte de La Orilla Olvidada, te ha pedido que mates a 20 fantasmas olvidados.", description = "¡Ha llegado la hora de expandir Rencor Venenoso!\n\nNos ocuparemos del Embate en su debido tiempo, pero quiero que te dirijas al sureste a un lugar conocido como La Orilla Olvidada. La propiedad tiene un gran potencial y ¿te has fijado en la vista?\n\nDesafortunadamente, hay una plaga de fantasmas humanos, tripulaciones naufragadas, que no parecen haberse dado cuenta de que están muertos.\n\nLimpia la playa y el agua de la orilla y quizás tú y yo hablaremos de construir un nuevo y acogedor mausoleo ahí abajo pronto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12305] = {title = "Pensamientos de despedida", objective = "Vuelve junto a Zelig el Visionario en la Fortaleza de Hibergarde en el Cementerio de Dragones.", description = "Me has honrado a mí y a la memoria de cientos de veteranos de la Alianza, <nombre>. Zelig fue sabio al enviarte aquí. Por favor, vuelve con él y dale las gracias de mi parte. Se alegrará al saber lo que ocurrió en La Orilla Olvidada.\n\nYo no tengo el don de la videncia como Zelig, pero seguro que te esperan cosas grandiosas, <amigo/amiga>.\n\nAdiós.\nPodrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Caperuza del fusilero olvidadoPechera del Capitán olvidadoHoja de guerra del lacayo olvidadoPodrás elegir una de estas recompensas:\n\nRecuerdos de ValonanteAro del mercenario olvidado\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12306] = {title = "Club de la Cerveza del Mes", objective = "Llévale el formulario de socio del Club de la \"Cerveza del Mes\" a Ray'ma en Orgrimmar.", description = "La unión hace la fuerza, <nombre>. Formar parte del Club de la \"Cerveza del Mes\" significa saber que tú y los tuyos podrán conseguir siempre la mejor cerveza.\n\nLlévale tu formulario de socio del Club de la \"Cerveza del Mes\" a Ray'ma en Orgrimmar.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][12307] = {title = "Raíz aterralobos", objective = "Katja en Arroyoplata quiere que arranques 8 raíces de aterralobos.", description = "¿Has oído hablar de la planta aterralobos? Es una hierba horrible... destruye nuestras cosechas.\n\nLa semana pasada estuvimos cortándola, pero las raíces han vuelto a aparecer.\n\nPuede que no parezca algo urgente, pero la reaparición de la planta podría ser un verdadero... desastre. ¿Crees que podrías ayudarnos arrancándolas cuando te las encuentres cerca del poblado?Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Mantón de esterilización horticulturalEspaldares de herboristaFaja de viñas crecientesPodrás elegir una de estas recompensas:\n\nColgante de poda\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12308] = {title = "Huye de Arroyoplata", objective = "Abre la jaula de madera y ayuda al explorador de la Alianza liberado a escapar de Arroyoplata. Cuando llegues al Refugio Pino Ámbar, informa al teniente Dumont.", description = "Tú... ¿no eres <uno/una> de ellos? ¡Rápido! ¡Déjame salir!\n\n¡Debemos llegar al Refugio Pino Ámbar inmediatamente! Cuando el teniente Dumont se entere de quiénes son estas personas en verdad, ¡esta ciudad se verá reducida a escombros!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Vestiduras de la bestia enjauladaBotas de conflicto internoGuardamuñecas del alma atormentadaEscarpes de humanidad machacadaPodrás elegir una de estas recompensas:\n\nAnillo de matahuargos\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12309] = {title = "¡Encuentra a Durkon!", objective = "Busca al hidalgo Durkon en la Cripta de Hibergarde, Cementerio de Dragones.|n", description = "Después de que la Plaga destrozara el muro del sur, ordené al hidalgo Durkon que investigara la cripta municipal. Hace un momento me entregaron este informe.\n\nLos no-muertos que nos afligen vienen de dos lugares: las ruinas de Hibergarde, ahora terreno de producción para la Plaga, y ¡nuestra propia cripta municipal! En medio del caos y la confusión, la Plaga se las ha apañado para meter a un necroseñor dentro de la cripta.\n\nEn su mensaje, Durkon solicitaba ayuda. Lo encontrarás y ayudarás, <nombre>. La cripta está en la zona oeste de la plaza de la ciudad.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12310] = {title = "Una reacción inmediata", objective = "El teniente Dumont quiere que vayas al Puesto Fronterizo del Bosque y mates a Vladek y a 7 cazadores de Arroyoplata.", description = "Debemos responder de inmediato. Con decisión. Debemos enseñarles a esos salvajes a no meterse con nosotros.\n\nNuestros exploradores han localizado lo que queda de los tramperos de Arroyoplata... ya sabes, a los que no pudiste envolver en llamas. Parece que están bloqueando el camino hacia el sureste... quizás estén intentando atraparnos.\n\nDirígete al Puesto Fronterizo del Bosque y ocúpate de ellos. Se dice que su líder se llama Vladek... encárgate de él.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12311] = {title = "La cripta del noble", objective = "El hidalgo Durkon en la Fortaleza de Hibergarde quiere que mates al necroseñor Amarion.", description = "Los restos de los nobles y dignatarios que murieron en Rasganorte se encuentran dentro de las frías piedras de los muros de esta cripta. En su núcleo se encuentra un necroseñor que levanta a los cadáveres como sirvientes de la Plaga.\n\nTienes que seguir el camino hasta el final de la cripta de Hibergarde y matar al necroseñor Amarion. ¡Solo entonces parará esta agresión interna!\n\n<nombre>, fíjate en cualquier información que pueda encontrarse en la habitación donde reside Amarion.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Ropas antiguas de viento residualCaperuza de espetadora AvalanchaEspaldares cortahieloGuanteletes de placas de cristalRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12312] = {title = "Secretos de la Plaga", objective = "Entrega el escrito encuadernado en carne al hidalgo Durkon en la Fortaleza de Hibergarde en el Cementerio de Dragones.", description = "Entre los capítulos de este escrito encuadernado en carne hay garabateados unos extraños símbolos y formas que parecen haber sido escritos rayando con una cuchilla. No tienes ni idea de lo que está escrito, pero tienes la certeza de que, sea lo que sea, debe de ser importante.\n\nLlévale el escrito al hidalgo Durkon que hace guardia en lo alto de la Cripta de Hibergarde.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12313] = {title = "UNUSED Save Brewfest!", objective = "Habla con el espía de la Fiesta de la cerveza en el Tragapenas de las Profundidades de Roca Negra.|n¡Salva la Fiesta de la cerveza! Habla con el espía de la Fiesta de la cerveza en el Tragapenas de las Profundidades de Roca Negra.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", description = "¡Salva la Fiesta de la cerveza! Habla con el espía de la Fiesta de la cerveza en el Tragapenas de las Profundidades de Roca Negra.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12314] = {title = "¡Abajo la capitana Zorna!", objective = "Mata a la capitana Zorna e informa al Barón Hombrelibre en Bahía Ventura.", description = "Si no actuamos, las fuerzas de la Horda atravesarán nuestras líneas y completarán su conquista de Bahía Ventura. Las fuerzas de la Horda en el puerto están comandadas por la capitana Zorna, cerca del barco en el lado más alejado de la bahía.\n\nSi la derrotas, la ofensiva de la Horda flaqueará y tendremos la oportunidad de capturar el puerto. Cuidado, <nombre>, pues Zorna es una guerrera fiera. Puede que hagan falta varias personas para derrotarla o si tienes acceso a una trituradora reparada, puede que quieras usarla para tener ventaja.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSuministros de aventura de RasganortePuntos de honor"}
MultiLanguageQuestData['mx'][12315] = {title = "¡Aplasta al Capitán Agualuz!", objective = "Mata al capitán Agualuz e informa al general Khazgar en Bahía Ventura.", description = "Nuestros hombres se topan con refuerzos frescos de la Alianza a cada paso. ¡Es casi como si su comandante se anticipase a mis movimientos!\n\nHa llegado la hora de que el bueno del capitán Agualuz se enfrente a su final. Dirige a sus tropas desde el destructor de la Alianza en lado alejado de la bahía.\n\n<nombre>, esta no será una pelea fácil. Llévate a un par de amigos de confianza o si tienes la llave de una de esas trituradoras reparadas, ¡úsala para destripar a Agualuz! ¡Debe caer, sea como sea!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSuministros de aventura de RasganortePuntos de honor"}
MultiLanguageQuestData['mx'][12316] = {title = "¡Mantenlos a raya!", objective = "Derrota a 10 unidades o jugadores de la Horda en Bahía Ventura y regresa con el teniente Stuart.", description = "No podemos permitir que la Horda controle Bahía Ventura. El puerto es esencial para nuestras operaciones en las Colinas Pardas y más allá.\n\nEl capitán Mantorrecio ha llevado al resto de su Brigada de los Páramos de Poniente al este, en busca de un paso que cruce las montañas, así que no tenemos refuerzos.\n\nVe al campo de batalla, <nombre>, y mata a los rabiosos del Bastión de la Conquista que la Horda ha lanzado contra nosotros. Machácalos hasta que no quede ninguno. ¡El puerto debe ser de la Alianza!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPuntos de honor"}
MultiLanguageQuestData['mx'][12317] = {title = "¡Mantenlos a raya!", objective = "Derrota a 10 unidades o jugadores de la Alianza en Bahía Ventura y regresa con el centurión Kaggrum.", description = "Esta condenada Brigada de los Páramos de Poniente está demostrando ser un oponente más duro de lo que pensamos. Aunque son pocos, luchan bien y con valor, pero no podemos permitirnos esperar a que se vayan.\n\nLas órdenes de la conquistadora Krenna son capturar el puerto rápidamente. Debes romper este empate, <nombre>. Encuentra a los marines del enemigo y acaba con ellos hasta que cese toda resistencia. Solo entonces podremos reclamar el puerto.\n\nVete, deprisa. No queremos hacer esperar a la conquistadora Krenna.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPuntos de honor"}
MultiLanguageQuestData['mx'][12318] = {title = "¡Salva la Fiesta de la Cerveza!", objective = "Habla con el espía de la Fiesta de la cerveza en el Tragapenas de las Profundidades Roca Negra.|n", description = "<nombre>, ¡nuestros espías han descubierto un complot!  ¡Los enanos Hierro Negro quieren destruir nuestra querida Fiesta de la cerveza!\n\nCoren Cerveza Temible, cabeza de una familia de cerveceros chaqueteros, ha organizado a los enanos de Profundidades de Roca Negra.  Sus malvadas máquinas topo nos atacan constantemente.\n\nNuestro espía está en el Tragapenas, una taberna en las entrañas de las Profundidades de Roca Negra.  Él tendrá más información sobre el complot de Cerveza Temible.\n\nEncuentra a nuestro espía.  ¡Salva la Fiesta de la cerveza!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12319] = {title = "El misterio del escrito", objective = "Llévale el escrito encuadernado en carne al alto comandante Halford Aterravermis en la Fortaleza de Hibergarde en el Cementerio de Dragones.", description = "¿Qué puede ser, <nombre>? ¡No cabe duda de que ese maldito exánime te lanzó una maldición poco normal!\n\n<Durkon hojea las espeluznantes páginas del escrito.>\n\nNi siquiera sé si estoy mirándolo desde la posición correcta. ¡Debemos averiguar qué información contiene este tomo!\n\n<Durkon te devuelve el libro.>\n\nEl Alto comandante sabrá qué hacer. Llévale el escrito encuadernado en carne y cuéntale lo que ha pasado con todo detalle.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12320] = {title = "Comprender el idioma de la muerte", objective = "Llévale el escrito encuadernado en carne al inquisidor Hallard en la prisión de la Fortaleza de Hibergarde.", description = "Coge el escrito y sigue el sendero que lleva hasta los barracones. Una vez dentro de los barracones, toma la escalerilla que baja a la prisión. En la prisión encontrarás al inquisidor Hallard y a nuestro alcalde, Godfrey. Creo que Godfrey será la pieza perdida de nuestro rompecabezas y Hallard el hombre que las unirá todas.\n\n¡Ve!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12321] = {title = "Un sermón de rectitud", objective = "Espera a que el inquisidor Hallard termine su sermón de rectitud y vuelve junto al alto comandante Halford Aterravermis en la Fortaleza de Hibergarde, en el Cementerio de Dragones, con la información que averigües.", description = "Godfrey Goodard, una vez un hombre recto y alcalde de Hibergarde, es ahora un agente de la Plaga. Su transformación de hombre a necrófago zombi ha ocurrido despacio, progresivamente. Oye la llamada del Rey Exánime y solo vive para servir a su maestro.\n\nPero como ocurre con todo miembro perteneciente a la Plaga, Godfrey conoce el idioma de los muertos y con la motivación apropiada, nos dirá lo que necesitamos saber sobre el escrito.\n\nCuando oigas lo que necesites oír, vuelve junto al Alto comandante, en la primera línea. Yo iré limpiando por aquí cuanto sea necesario.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Cubremuñecas altamarBotas de errante de claroGuardahombros de Viento OestePodrás elegir una de estas recompensas:\n\nArrepentimiento del Pecador\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12323] = {title = "Ahúmalos", objective = "Usa la bomba de humo para sacar a 20 rezagados de Ventura y Cía. de sus edificios y después informa al sargento Downey.", description = "Todavía quedan bolsas de esos cobardes de Ventura y Cía. escondidas en los edificios del centro de Bahía Ventura. Necesito a todos los hombres para luchar contra la Horda, pero tampoco podemos tolerar que esos vagos de Ventura y Cía. acampen en esos edificios.\n\nA lo mejor podemos \"convencerlos\" para que se larguen a su barco. Coge esta bomba de humo y úsala para ahuyentar a los rezagados de sus escondites en el barracón, el aserradero o los establos. Pero no te acerques demasiado, lo más probable es que muerdan.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1Puntos de honor"}
MultiLanguageQuestData['mx'][12324] = {title = "Ahúmalos", objective = "Usa la bomba de humo para sacar a 20 rezagados de Ventura y Cía. de sus edificios y después informa al guardia de piedra Tótem de Ira.", description = "Este puerto no solo está infestado de lloricas cobardes de la Alianza, sino que, para empeorar las cosas, todavía hay empleados de Ventura y Cía. refugiados en algunos edificios. No son lo bastante dignos para que ocupemos el tiempo en matarlos y, de todas formas, tampoco podemos perder guerreros.\n\nQuizás podríamos \"convencerlos\" para que se dirijan hacia su barco. Coge esta bomba de humo y úsala para ahuyentar con el humo a esos rezagados de sus escondites en el barracón, el aserradero o los establos. Pero no te acerques demasiado porque no sabemos qué enfermedades llevan.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1Puntos de honor"}
MultiLanguageQuestData['mx'][12325] = {title = "En territorio hostil", objective = "Habla con el comandante de grifos Urik para reservar un viaje hasta el Puesto de Thorson. Informa al duque August Martinimigos cuando llegues al Puesto de Thorson, en el Cementerio de Dragones.|n", description = "Has hecho mucho para hacer progresar nuestros esfuerzos contra la Plaga, <nombre>. De hecho, ¡la moral de todos aquellos que han estado cerca de ti está subiendo! Esta es tu influencia sobre los soldados y ciudadanos de Hibergarde, <aliado/aliada>.\n\nY gracias a ti, ¡estamos preparados para la ofensiva! Debes informar al duque August Martinimigos, al otro lado de Los Campos de Carroña en el Puesto de Thorson, al este de aquí. El comandante de grifos Urik, en la estación de grifos, ha preparado un grifo especial para que te lleve tras las líneas enemigas. ¡Ve!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12326] = {title = "Tanque de vapor con sorpresa", objective = "Utiliza un tanque de vapor de la Alianza para destruir 6 vagones de peste y para llevar a las Élites de la Séptima Legión al Mausoleo de Hibergarde. Si lo logras, habla con Ambo Calderilla dentro del Mausoleo de Hibergarde en el Cementerio de Dragones.", description = "Esta es una misión de búsqueda y aniquilación. Conducirás un tanque en los campos de carroña para desmantelar los vagones de la Plaga. Con el tanque viene una compañía de tres soldados de la Séptima Legión. ¡Todos tienen que sobrevivir si quieres acabar esta misión con éxito!\n\nTendrás que acercarte a un vagón apestado para poner en marcha tu motor. Deja que actúen y pasa al siguiente. Cuando el campo esté limpio de vagones apestados, dirígete al mausoleo frente a la fortaleza en ruinas y deja allí al resto de tu equipo. Dentro te encontrarás con Ambo Calderilla.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Capa de saboteadorPodrás elegir una de estas recompensas:\n\nGuardacuellos de ritualAnillo de antorcha de maestro de asedio\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12327] = {title = "Una experiencia extracorporal", objective = "Bebe la poción delicada mientras estás junto a la bola de cristal de Ruuna y contempla la visión del pasado.", description = "Ah, quieres una visión del pasado. Eres <un/una:r> <raza> muy inteligente.\n\nSiempre que se presenta alguien aquí para alguna revelación, suele preguntar por el futuro. Cuando llegues a mi edad, aprenderás que las visiones del pasado suelen resultar, casi siempre, más útiles.\n\nBebe esta poción y observa con atención el interior de mi bola de cristal. Veamos qué información podemos obtener.", progress = "¿Sí, <nombre>?", completion = "¿Aprendiste algo de tu visión? Mencionaste el Poblado Solsticio mientras estabas en trance... Es la segunda vez que alguien menciona el nombre de ese lugar hoy.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12328] = {title = "La petición de Ruuna", objective = "Ruuna la Ciega quiere que consigas 4 puñados de polvo delicado.", description = "No te cobraré nada, pues presiento que tus actos son necesarios y lo que aprendas hoy será decisivo.\n\nSin embargo, te pediré que recojas un reactivo y me lo traigas. Consigue un poco de polvo delicado de las palomillas helechil que hay al noreste de aquí. Hazlo y te prepararé una poción que te llevará al momento y lugar donde todo ocurrió y que necesitas presenciar.", progress = "¿Conseguiste el polvo, <nombre>?", completion = "Bien. Esto servirá.\n\nLa poción estará preparada enseguida.", rewards = "Faja de pronosticadorEspaldares del profetaMandiletes manchados delicadosProtector purificador de pensamientosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12329] = {title = "Destino y coincidencia", objective = "Habla con Sasha en el Puesto de Venta de Pino Blanco.", description = "En este mundo, hay dos tipos de personas, <nombre>: los que creen en las coincidencias y los que no.\n\nEl día que perdí la vista recibí el don de la clarividencia. Supongo que te preguntarás a qué tipo de personas pertenezco yo.\n\nHoy vino una joven llamada Sasha que tuvo la misma visión que tú. Ve a hablar con ella.\n\nLa encontrarás al este de aquí en el Puesto de Venta de Pino Blanco de camino hacia el Poblado Solsticio.", progress = nil, completion = "Me preguntaba cuándo aparecerías. ¿Crees que podrías echarme una mano?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12330] = {title = "Anatoly hablará", objective = "Sasha en el Puesto de Venta de Pino Blanco quiere que cojas el dardo sedante y lo uses con Tatjana en el Poblado Solsticio. Trae a Tatjana de vuelta al Puesto de Venta de Pino Blanco.", description = "Mi hermana anda por alguna parte, y no consigo que este monstruo hable.\n\nNo parece que le importe su propio bienestar, pero tengo una idea. Yo conocía a la mujer de Anatoly, Tatjana, antes de que el culto del lobo llegara... era cuidadora de caballos.\n\nCoge este dardo sedante. Tráela de vuelta viva, la necesitaremos si es que queremos sacarle algo a Anatoly.\n\nTe ayudaré a encontrar a la persona que está detrás de todo esto cuando hayamos salvado a mi hermana.", progress = nil, completion = "Por los pelos.\n\nTenemos que salvar a Anya. ¡Ya!", rewards = "Podrás elegir una de estas recompensas:\n\nSello de solsticioSello del lobo durmienteColgante de Tatjana\n\nTambién recibirás:\n\nObjeto #1"}
