MultiLanguageQuestData['mx'][12947] = {title = "Cubo de caramelos", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nTruco o trato\n\nRecibirás:\n\nPuñado de golosinas"}
MultiLanguageQuestData['mx'][12948] = {title = "El campeón de angustia", objective = "¡Entra en la arena del Anfiteatro de la Angustia y derrota a Vladof el Carnicero! Habla con Wodin, el sirviente trol, para recoger tu recompensa.", description = "¡Esto se acaba, <amigo/amiga> <mío/mía>! Tu último oponente será tu mayor desafío. Es un campeón vrykul de las estepas de Corona de Hielo, ¡y quiere sangre! ¡Derrótalo y serás <coronado/coronada> <el/la> <campeón/campeona> del Anfiteatro de la Angustia! ¡Esta pelea nos hará ricos a los dos!\n\nCuando estés <listo/lista>, dímelo y empezaremos.", progress = nil, completion = "¡&lt;nombre&gt;, lo has logrado! ¡Ha sido la pelea más emocionante que he visto! ¿Qué vas a hacer con tus ganancias? ¿Yo? Me voy a Dalaran y me lo voy a gastar todo en Los Bajos Fondos. ¡Allí pasan muchas cosas interesantes!", rewards = "Lanza con púas más heladaHacha de guerra perturbadaAldababa fríaSuperpega con resorteTrituracráneos carmesíSegunda mejor faca de WodinRecibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12949] = {title = "Consigue la llave", objective = "Vaelen el Despellejado en la Sala de Ufrang te ha pedido que recuperes la llave de las cadenas de Vaelen.", description = "<clase>, la llave de mis grilletes está colgada al cuello del Instructor Hroegar, que está fuera.\n\nA lo mejor si le separas la cabeza de los hombros, puedes recuperarla.", progress = "¿La tienes?", completion = "Gracias, &lt;raza&gt;. Dame la llave, yo puedo cuidarme solo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12950] = {title = "Cubo de caramelos", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nTruco o trato\n\nRecibirás:\n\nPuñado de golosinas"}
MultiLanguageQuestData['mx'][12951] = {title = "Que el Barón lo sepa", objective = "Habla con el Barón Tajada en La Cámara de las Sombras.", description = "Lo más importante que tienes que hacer ahora es volver a La Cámara de las Sombras e informar al Barón Tajada de que he fracasado.\n\nVerás, no he sido el único al que han capturado estos demonios vrykul. Todo mi contingente de caballeros de la Muerte fue capturado.\n\nDebería haber visto venir la trampa, pero agua pasada no mueve molino, ¿verdad?\n\n¡Vete antes de que te capturen a ti también! Te volveré a ver en la cámara.", progress = nil, completion = "¡¿Qué?! ¡Apenas podemos permitirnos perder un caballero de la Muerte, mucho menos un contingente entero!", rewards = "Te van a lanzar el siguiente hechizo:\n\nThe Shadow Vault: See Vaelen's Invisibility\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12952] = {title = "Gemas perfectas", objective = "Llévale dos citrinos enormes, dos jades oscuros y dos cristales de Sombras a Carter Tiffens en Campo Venganza.", description = "En este lugar asqueroso voy a perder mis habilidades. He dedicado muchos años a aprender a tallar gemas de forma perfecta, ¡y no tengo nada con lo que trabajar! Pareces ser alguien al que podría enseñarle la habilidad de gemas perfectas. Esto te permitirá que a veces talles una gema perfecta, con mayor bonificación, cuando intentes tallar una gema de calidad inusual de Rasganorte.Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nPerfección de gemas\n\nTambién recibirás:\n\nBolsa de terciopelo pequeña"}
MultiLanguageQuestData['mx'][12953] = {title = "Valkyrion debe arder", objective = "Usa los cañones de arpones de Valkyrion para incendiar 6 fardos de heno secos.", description = "La caja está llena de arpones incendiarios. Recuerdas haber visto cañones de arpones y fardos de heno secos fuera.\n\nQuizás Iva aprecie el esfuerzo extra y te recompense adecuadamente.", progress = nil, completion = "¡A eso lo llamo yo dedicación! Puede que esas traidoras tengan ahora un nuevo señor, pero jamás olvidarán el regalo de despedida de sus hermanas.", rewards = "Corona del librallamasApisonadoras de lanaBotas de nieve con puntas de aceroCoselete de rastreador de ValkyrionRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12954] = {title = "El Anfiteatro de la Angustia: ¡Yggdras!", objective = "¡Entra en la arena del Anfiteatro de la Angustia y derrota a Yggdras! Habla con Wodin, el sirviente trol, para recoger tu recompensa.", description = "¡Me preguntaba cuando aparecerías, <nombre>! ¡Tener a <un antiguo/una antigua> <campeón/campeona> de El Círculo de Sangre aquí es algo grande! ¡Vamos a ser ricos, colega! ¡RICOS!\n\nPor cierto, este vertedero es Zul'Drak. Al parecer es el retrete de todos los trols de hielo. No sé, ¡si me lo preguntas te diré que esto huele fatal! Pero qué más da, ¿verdad? ¡Estamos aquí para ganar oro!\n\nYa sabes cómo funciona esto, <nombre>. Cuando estés <listo/lista>, dímelo, ¡y empezará el espectáculo!\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12955] = {title = "Eliminar a la competencia", objective = "El Saltador en La Cámara de las Sombras quiere que desafíes a duelo y derrotes a Sigrid Hielonato, Efrem el Leal, Ono'zun y a Mañosa Silbatín.", description = "Mrrfrmrrmrrr...\n\n<El Saltador se aclara la garganta.>\n\nLo lamento. A veces puede costar entender lo que digo. Ya sabes cómo es.\n\nQuería asegurarme de que si pasas por la Cornisa Salvaje, pasando las montañas al oeste, te encargases de eliminar a la competencia que hay allí.\n\nEn especial me gustaría que desafiases a duelo y humillases a Sigrid Hielonato, a Efrem el Leal, a Onu'zun y a Mañosa Silbatín delante de todos los vrykuls.", progress = nil, completion = "Esto era importante, &lt;nombre&gt;. Al espantarlos evitas que interfieran con lo que tengas que hacer por allí.", rewards = "Tapa de ataúd de hierroMitones de SigridBrazales de EfremPeto del cruzado glacialGuanteletes de Onu'zunRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12956] = {title = "Una chispa de esperanza", objective = "Tienes que llevar la mena reluciente refinada a Thorim en el Templo de las Tormentas.", description = "Es obvio que esto es algo más que un trozo normal de metal.\n\nA diferencia de cualquier mineral que conozcas, es duro pero no quebradizo, mucho más ligero de lo que parece y brilla cuando está frío.\n\nAl mirarlo más de cerca, puedes distinguir una de las runas de Thorim que brilla bajo la superficie.", progress = "¿Qué tienes ahí, pequeño?", completion = "Ves cómo el severo rostro de Thorim se ilumina al reconocer el material que le muestras.", rewards = "Recibirás:\n\nEmblema de heroísmo"}
MultiLanguageQuestData['mx'][12957] = {title = "Esclavos de los Tronaforjado", objective = "Pedruscón el Creador de rocas en el Refugio de Pedruscón quiere que liberes a 6 mecagnomos cautivos y que mates a 3 capataces Tronaforjado.", description = "Al suroeste, en el lado occidental de las Llanuras Ventisquero, los enanos férreos han excavado una mina en la ladera. Allí utilizan mecagnomos cautivos, sirvientes del guardián Mimir, para extraer menas.\n\nNo sé de dónde han salido esos mecagnomos ni qué harían si fueran libres, pero quizás podamos conseguir que nos ayuden.\n\nVe a la Mina Gélida, <nombre>, y libera a esas criaturas de sus ataduras. Pregúntales si quieren luchar a nuestro lado contra la tiranía de los enanos férreos.", progress = nil, completion = "Esperaba que más cautivos se unieran a nosotros, pero no los culpo. Los aliados voluntarios escasean y tenemos suerte de que tu hoja sirva a nuestra causa.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12958] = {title = "Envío: amuleto de jade de sangre", objective = "Reúne un amuleto vrykul, un jade oscuro y una sangrita para hacer un amuleto de jade de sangre, y llévaselo a Timothy Jones en Dalaran.\n\nPodrás encontrar amuletos vrykul en cualquier vrykul de Rasganorte.", description = "Un comerciante muy rico ha pedido una colección de amuletos de jade de sangre para venderlos en Minahonda. Si me traes uno, te recompensaré con una muestra de joyero de Dalaran.\n", progress = "¿Tienes un amuleto de jade de sangre para mi envío a Minahonda?", completion = "Aquí tienes tu muestra de joyero de Dalaran, como te prometí. Vuelve mañana, ¡sin duda necesitaré que me traigas otro objeto!", rewards = "Recibirás:\n\nObjeto #1Muestra de joyero de DalaranCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][12959] = {title = "Envío: figurilla de marfil resplandeciente", objective = "Reúne un trozo de marfil de Rasganorte, una calcedonia y un cristal de Sombras para crear una figurilla de marfil resplandeciente, y llévasela a Timothy Jones en Dalaran.\n\nPodrás encontrar marfil de Rasganorte en cualquier colmipala o mamut de Rasganorte.", description = "Un comerciante muy rico ha pedido una colección de figurillas de marfil resplandecientes para venderlas en Minahonda. Si me traes una, te recompensaré con una muestra de joyero de Dalaran.\n", progress = "¿Tienes una figurilla de marfil resplandeciente para mi envío a Minahonda?", completion = "Aquí tienes tu muestra de joyero de Dalaran, como te prometí. Vuelve mañana, ¡sin duda necesitaré que me traigas otro objeto!", rewards = "Recibirás:\n\nObjeto #1Muestra de joyero de DalaranCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][12960] = {title = "Envío: broche de sol maligno", objective = "Reúne un broche de enano de hierro, un citrino enorme y un cristal de sol para hacer un broche de sol maligno, y llévaselo a Timothy Jones en Dalaran.\n\nPodrás encontrar broches de enano de hierro en cualquier enano férreo de Rasganorte.", description = "Un comerciante muy rico ha pedido una colección de broches de sol maligno para venderlos en Minahonda. Si me traes uno, te recompensaré con una muestra de joyero de Dalaran.\n", progress = "¿Tienes un broche de sol maligno para mi envío a Minahonda?", completion = "Aquí tienes tu muestra de joyero de Dalaran, como te prometí. Vuelve mañana, ¡sin duda necesitaré que me traigas otro objeto!", rewards = "Recibirás:\n\nObjeto #1Muestra de joyero de DalaranCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][12961] = {title = "Envío: figurilla de hueso intrincada", objective = "Reúne un hueso de protodraco, un cristal de sol y un jade oscuro para hacer una figurilla de hueso intrincada, y llévasela a Timothy Jones en Dalaran.\n\nPodrás conseguir huesos de protodraco de cualquier protodraco de Rasganorte.", description = "Un comerciante muy rico ha pedido una colección de figurillas de hueso intrincadas para venderlas en Minahonda. Si me traes una, te recompensaré con una muestra de joyero de Dalaran.\n", progress = "¿Tienes una figurilla de hueso intrincada para mi envío a Minahonda?", completion = "Aquí tienes tu muestra de joyero de Dalaran, como te prometí. Vuelve mañana, ¡sin duda necesitaré que me traigas otro objeto!", rewards = "Recibirás:\n\nObjeto #1Muestra de joyero de DalaranCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][12962] = {title = "Envío: reliquia de armadura brillante", objective = "Reúne un fragmento de armadura elemental, una sangrita y un citrino enorme para hacer una reliquia de armadura brillante, y llévasela a Timothy Jones en Dalaran.\n\nPodrás encontrar fragmentos de armadura elemental en cualquier aparecido de Rasganorte.", description = "Un comerciante muy rico ha pedido una colección de reliquias de armadura brillante para venderlas en Minahonda. Si me traes una, te recompensaré con una muestra de joyero de Dalaran.\n", progress = "¿Tienes una reliquia de armadura brillante para mi envío a Minahonda?", completion = "Aquí tienes tu muestra de joyero de Dalaran, como te prometí. Vuelve mañana, ¡sin duda necesitaré que me traigas otro objeto!", rewards = "Recibirás:\n\nObjeto #1Muestra de joyero de DalaranCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][12963] = {title = "Envío: bibelot de sol cambiante", objective = "Reúne un bibelot de la Plaga, un cristal de sol y un cristal de Sombras para hacer un bibelot de sol cambiante, y llévaselo a Timothy Jones en Dalaran.\n\nPodrás encontrar bibelots de la Plaga en cualquier Plaga de Rasganorte.", description = "Un comerciante muy rico ha pedido una colección de bibelots de sol cambiante para venderlos en Minahonda. Si me traes uno, te recompensaré con una muestra de joyero de Dalaran.\n", progress = "¿Tienes un bibelot de sol cambiante para mi envío a Minahonda?", completion = "Aquí tienes tu muestra de joyero de Dalaran, como te prometí. Vuelve mañana, ¡sin duda necesitaré que me traigas otro objeto!", rewards = "Recibirás:\n\nObjeto #1Muestra de joyero de DalaranCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][12964] = {title = "La mena oscura", objective = "Llévale 5 muestras de mena a Pedruscón el Creador de rocas en el Refugio de Pedruscón.", description = "En la Mina Gélida, en la parte occidental de las Llanuras Ventisquero, los enanos férreos Tronaforjado han construido una mina en la que trabajan esclavos.\n\nEstá muy lejos de las fronteras, así que no hemos podido descubrir qué está pasando allí, pero mis exploradores me han informado de que han visto cómo se llevaban carros llenos con unas menas oscuras de aspecto asqueroso.", progress = "¿Qué has descubierto sobre las menas?", completion = "&lt;Pedruscón se acerca a coger la mena, pero retrocede.&gt;\n\nEsta mena... no puedo tocarla. Rebosa energía antinatural. Ninguna criatura de piedra puede manejarla. ¿Qué quieren hacer con esto?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12965] = {title = "Los obsequios de Loken", objective = "Destruye la Furia de Loken, el Poder de Loken y el Favor de Loken. Después regresa junto a Pedruscón el Creador de rocas en el Refugio de Pedruscón.", description = "El líder de los enanos férreos Tronaforjado se llama Valduran Vidente de Runas. Aunque no los he visto nunca, se dice que su señor, el guardián Loken, quien se hizo con Ulduar, le ha dado a Valduran unos poderosos artefactos de los titanes.\n\nEso podría explicar la fuerza y ferocidad que han observado mis hombres en los guerreros Tronaforjado.\n\nLa base de Valduran, Nidavelir, se encuentra al suroeste, cruzando las Llanuras Ventisquero. <nombre>, ve allí y neutraliza su poder. Destruye esos obsequios de Loken y ayúdanos a minar la fuerza de sus seguidores.", progress = nil, completion = "&lt;Pedruscón asiente con aspecto lúgubre.&gt;\n\nHas debilitado bastante a los Tronaforjado, pero seguirán luchando. Sus bajas no significan nada para ellos, mientras que nuestros defensores siguen muriendo. Incluso si les cuesta un centenar o un millar de cadáveres férreos, seguirán luchando hasta que nos hayan convertido en gravilla.", rewards = "Leotardos de Esperanza renovadaManto de BarbapiedraResolución de PedruscónPodrás elegir una de estas recompensas:\n\nColgante de Pedruscón\n\nTambién recibirás:\n\nEmblema de heroísmo"}
MultiLanguageQuestData['mx'][12966] = {title = "No tiene pérdida", objective = "El rey Jokkum en Dun Niffelem quiere que busques a Njormeld en el Yunque de Fjorn.", description = "<Jokkum escucha pacientemente tu petición y se lo piensa mucho antes de responder.>\n\n¿Así que es a ti a quién debemos agradecerle el fin de Fjorn?\n\nAunque es verdad que nos has ayudado cuando lo hemos necesitado, todavía queda mucho por hacer para recuperar nuestras relaciones con Thorim.\n\nPor ahora, permitiré que Njormeld vuelva a forjar la armadura que le regalamos al Señor de la Tormenta hace ya mucho tiempo. Considérala el pago por tu ayuda contra Fjorn.\n\nNjormel ha ido a recuperar el Yunque de Fjorn, allí deberías encontrarlo.", progress = nil, completion = "¿Volver a forjar la armadura de Thorim? Puede hacerse.\n\nPero antes está el asuntillo del yunque...", rewards = nil}
MultiLanguageQuestData['mx'][12967] = {title = "Luchar contra los elementales", objective = "Njormeld quiere que acompañes a Snorri al Yunque de Fjorn y que lo ayudes a matar a 10 aparecidos hirvientes.", description = "Hubo un tiempo en el que Snorri era el orgullo de nuestra nación. Era un poderoso guerrero y muchos enemigos habían perecido bajo su maza.\n\nLo honramos, aunque ya no sea lo que fue. La edad se ha cobrado su precio, embotando sus sentidos y robándole su fuerza. Pero sigue siendo tan orgulloso como siempre, jamás pierde la oportunidad de ir a la batalla.\n\nHablando de batallas, estamos enfriando el Yunque de Fjorn para poder llevarlo a casa. Los aparecidos de fuego que quedan están dando algunos problemas. Ayuda a Snorri a revivir sus días de gloria, <raza>. Guíalo contra este enemigo.", progress = nil, completion = "Una actuación honrosa, &lt;raza&gt;. Informaré al rey de tu ayuda.\n\nEl yunque ya se ha enfriado casi lo bastante. Te veré en Dun Niffelem pronto.", rewards = "Te van a lanzar el siguiente hechizo:\n\nKill Credit"}
MultiLanguageQuestData['mx'][12968] = {title = "La insensatez de Yulda", objective = "Iva la Vengativa en el Poblado Brunnhildar quiere que mates a Yulda la Hablatormentas en Valkyrion.", description = "La bruja que lo empezó todo, Yulda la Hablatormentas vino a nuestra aldea. Se atrevió a insultar nuestras nobles tradiciones y profirió las venenosas promesas de poder del Rey Exánime.\n\nTenía que haberse marchado con una espada atravesándola, pero su magia era fuerte y logró escapar.\n\nBúscala en Valkyrion, dentro del asentamiento más grande y demuéstrale que con nosotros no se juega.", progress = nil, completion = "Yulda se lo merecía. Nadie insulta al Encuentro Hyldnir y queda impune. Ni siquiera una de las nuestras.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12969] = {title = "¿Es ese tu goblin?", objective = "Desafía a Agnetta Tyrsdottar para salvar a Zeev Chispeante. Cuando lo hayas conseguido, regresa junto a Lok'lira la Vieja Bruja en el Poblado Brunnhildar.", description = "Espero que ese sea el pequeño verdezuelo que estabas buscando. Si yo fuera tú, haría algo antes de que esa Hyldnir lo parta en dos.\n\nHas llegado en mitad del Encuentro Hyldnir, así que los participantes tienen que aceptar todos los desafíos. Nada te impide ocupar el lugar de tu amigo verde.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12970] = {title = "El Encuentro Hyldnir", objective = "Escucha la propuesta de Lok'lira la Vieja Bruja.", description = "Tanto si te has dado cuenta como si no, al derrotar a tu primera Hyldnir en combate cuerpo a cuerpo has entrado en el Encuentro Hyldnir, la gran competición de Hyldnir contra Hyldnir para determinar quién gobernará junto a Thorim.\n\nEl Encuentro Hyldnir es la razón por la que me encarcelaron, pues ansiaba participar en la competición pero soy demasiado frágil y vieja como para competir contra las Hyldnir.\n\nSi quieres escucharla, tengo una propuesta para ti.", progress = nil, completion = "Entonces tenemos un trato. Competirás en el Encuentro Hyldnir y con mi ayuda devolverás al gran Thorim a su lugar legítimo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12971] = {title = "Enfrentarse a todos los retos", objective = "Lok'lira la Vieja Bruja en el Poblado Brunnhildar quiere que derrotes a 6 contendientes victoriosas.", description = "Empecemos. La buena noticia es que al derrotar a Agnetta te has ganado un puesto en la siguiente ronda de combates.\n\nLa mala es que tus oponentes también habrán derrotado a alguien en la primera ronda. No esperes algo fácil.", progress = nil, completion = "Lo has logrado, &lt;nombre&gt;. Has derrotado a algunas de las guerreras más feroces de la raza Hyldnir.", rewards = "Partetestas HyldnirCorona HyldnirPantalones de protoescamaAtuendo de Tejerruna HyldnirRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12972] = {title = "Necesitarás un oso", objective = "Habla con Brijana a las afueras del Poblado Brunnhildar.", description = "Has tenido éxito en las primeras rondas de El Encuentro Hyldnir. Para continuar avanzando, necesitarás tu propio oso de guerra.\n\nPor desgracia las Hyldnir no se lo dan a cualquiera. Tendrás que vencer en una batalla de verdad, no solo en combates de gladiadores.\n\nActualmente las Hyldnir de Brunnhildar mantienen una disputa contra los Hijos de Hodir, los antiguos aliados de Thorim. Habla con Brijana a las afueras del poblado y entérate de cómo puedes ayudarlas y demostrar tu valía en el proceso.", progress = nil, completion = "¿Crees que te vamos a dar tu propio oso así como así? Antes de que te demos nada vas a tener que demostrar lo que vales.\n\nNo te tengas en demasiada estima solo porque hayas derrotado a algunas contendientes en El Encuentro Hyldnir.", rewards = "Recibirás:\n\nEmblema de heroísmo"}
MultiLanguageQuestData['mx'][12974] = {title = "¡La llamada del campeón!", objective = "Busca a Gurgthock en el Anfiteatro de la Angustia en Zul'Drak.", description = "Pfft, lo que ocurre aquí abajo no se puede llamar pelear. Son un par de tipos bailando alrededor de una bandera.\n\n¿Buscas acción de verdad, <amigo/amiga>? Porque si es así, tengo lo mejor de la zona.\n\n¿Alguna vez has oído hablar de Gurgthock y Wodin? ¿El goblin y el trol que dirigían El Círculo de Sangre de Terrallende? Bueno, pues están en Rasganorte y han montado un nuevo club de lucha en Zul'Drak. Si te interesa, vete a Zul'Drak, al este de Canto de Cristal. Están en la gran arena del centro. ¡Diles que vas de parte de Furti!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][12975] = {title = "En memoria", objective = "El rey Jokkum en Dun Niffelem quiere que recojas 8 fragmentos de cuerno en Truenotoño.", description = "Sin duda Thorim te ha hablado de la tragedia que nos divide.\n\nEstos acontecimientos sucedieron en Truenotoño, al noreste de aquí. Los fósiles congelados que hay allí son un recordatorio de ese día oscuro, al igual que los espíritus que recorren ese lugar.\n\nSi mi pueblo va a perdonar a Thorim, algo debe reemplazar esas imágenes. Se debe construir un monumento que traiga la paz a nuestros corazones.\n\nVe allí, <raza>. Recoge los fragmentos del cuerno de Hodir que se rompieron ese día.", progress = "¿Has encontrado las piezas del cuerno de Hodir?", completion = "Otra buena acción que has realizado en nombre de Thorim, &lt;clase&gt;.\n\nEsto ayudará a ablandar los corazones de mi pueblo hacia él.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12976] = {title = "Un monumento a los caídos", objective = "El rey Jokkum quiere que le lleves los fragmentos del cuerno de Hodir a Njormeld, en Dun Niffelem.", description = "Llévale estos fragmentos a Njormeld. Usará los pedazos de la reliquia sagrada para construir un gran monumento.\n\nPuede que calme el dolor y sane las heridas que mi pueblo ha sufrido durante tantos años.\n\nOjalá su existencia nos ayude a alcanzar una nueva era en la que volvamos a librar gloriosas batallas al lado de Thorim.\n\nVete ya, <clase>. Njormeld te espera.", progress = "¿Has traído los fragmentos del cuerno de Hodir, <raza>?", completion = "&lt;Los ojos de Njormeld se humedecen mientras pone los contenidos de la bolsa sobre el yunque.&gt;\n\nEl cuerno de Hodir...\n\nFue un regalo sagrado del propio Hodir a nuestro pueblo, &lt;raza&gt;. Es una reliquia muy importante para nosotros.\n\nCuando vuelvas a nuestra fortaleza, verás los frutos de tu trabajo.\n\nAdiós.", rewards = "Recibirás:\n\nEmblema de heroísmo"}
MultiLanguageQuestData['mx'][12977] = {title = "Llamado de Hodir", objective = "Debes vencer a 5 antepasados de Niffelem y a 5 Natoescarchas inquietos en Truenotoño. Después, utiliza el cuerno de Hodir sobre sus cadáveres y vuelve al cuerno de Hodir en Dun Niffelem.", description = "Has prestado un gran servicio a los gigantes de Dun Niffelem. Sin tu ayuda, este monumento no existiría.\n\nMientras meditas en silencio sobre su importancia, tu corazón se llena de sensaciones. Las sensaciones llenan tu mente con pensamientos e imágenes... y una sensación de urgencia.\n\nLas sensaciones se desvanecen, pero ya sabes qué debes hacer. Los espíritus inquietos de Truenotoño han de encontrar reposo.\n\nMientras te vas, descubres que tus manos sostienen un cuerno etéreo.", progress = nil, completion = "Al saber que las atormentadas almas de Truenotoño por fin descansan en paz te invade un sentimiento de paz y satisfacción.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12978] = {title = "Enfrentarse a la tormenta", objective = "Bruor Temeferro en el Refugio de Pedruscón quiere que mates a 10 Tronaforjado de Nidavelir. Puedes matar campeones Tronaforjado, magi Tronaforjado o gólems de guerra Tronaforjado.", description = "Al igual que Pedruscón, yo también serví a los guardianes como artesano en Ulduar, pero tras la traición de Loken, dirigí mi martillo hacia nuestros nuevos enemigos.\n\nCuando hubo hombres suficientes, lideré ataques contra Nidavelir para reducir la presión sobre nuestros defensores, pero nuestras líneas están a punto de desmoronarse.\n\nHas demostrado ser <un/una> combatiente capaz y <un/una> fiel <aliado/aliada>. Quizás quieras portar nuestro estandarte y llevar la lucha hasta Nidavelir, la fortaleza de los enanos férreos al suroeste, cruzando las Llanuras Ventisquero.", progress = nil, completion = "Puede que aún queden esperanzas de victoria, &lt;nombre&gt;. Nunca hemos podido mantener un ataque contra los Tronaforjado, pero con tus esfuerzos, ¡puede que Valduran caiga!", rewards = "Recibirás:\n\nEmblema de heroísmo"}
MultiLanguageQuestData['mx'][12979] = {title = "Armadura de oscuridad", objective = "Llévale 4 muestras de armadura oscura a Bruor Temeferro en el Refugio de Pedruscón.", description = "Esta armadura de placas es gruesa y más grande que el resto de las defensas del gólem. Un examen rápido del cadáver del gólem muestra que esta parte más pesada ha sido clavada en el último momento o como mejora rústica.\n\n¿Por qué iban a colocar los enanos férreos esta armadura gigantesca y que no encaja en sus gólems de guerra?\n\nQuizás Bruor Temeferro lo descubra si examina varias de estas placas de gólems de guerra Tronaforjado.", progress = "¿Qué es lo que tienes ahí?", completion = "Ahora cuidado. Mantén esa placa tan lejos de mí como puedas. Con estar en su presencia ya causa dolor.\n\nPero tienes razón, &lt;nombre&gt; son armaduras de placas gigantescas para un gólem de guerra de tamaño normal. ¿Qué van a hacer los Tronaforjado con ellas? Solo hay una forma de descubrirlo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12980] = {title = "Los secretos de la armadura", objective = "Lleva la placa de armadura oscura al Taller de Mimir y pídele al auxiliar Tock que lo examine. Cuando esto esté hecho, vuelve junto a Bruor Temeferro al Refugio de Pedruscón.", description = "La presencia de esa placa de armadura me desorienta, pero debemos descubrir todo lo que podamos sobre ella. Podría formar parte de uno de los planes de Valduran.\n\nHa dedicado muchos esfuerzos a extraer, refinar, forjar y probar este metal.\n\nAl este, junto a la cara norte de la montaña, hay un edificio llamado el Taller de Mimir. Lleva sin usarse algún tiempo, pero si tenemos suerte algunos de sus ayudantes aún seguirán funcionando. Lleva allí la placa de armadura y descubre lo que puedas sobre ella.", progress = "¿Qué has descubierto?", completion = "&lt;Bruor te escucha mientras le describes lo que has descubierto en el taller.&gt;\n\nAsí que el maestro de Valduran le ha dado este siniestro metal para que construya un arma gigante. ¡Eso debe ser lo que quiere utilizar para darnos el golpe final! Debemos detenerlo antes de que pueda terminarla y utilizarla.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12981] = {title = "Caliente y frío", objective = "Ve al Lago Campo de Escarcha, mata a los aparecidos frágiles que hay allí y utiliza la Esencia de Hielo en la chatarra ardiente en el Yunque de Fjorn. Después deberás recoger 6 de los fragmentos de hierro congelado y volver junto al Yunque de Fjorn en Dun Niffelem.", description = "Mientras miras el yunque revives tus logros recientes, en particular los que han hecho que este artefacto llegue aquí.\n\nDe repente se te ocurre que aún quedan cosas por hacer. Al este el paisaje está cubierto de chatarra ardiente, restos de la batalla que tuvo lugar ahí.\n\nSi se pudieran enfriar y recoger de alguna forma, los gigantes de escarcha tendrían un abundante suministro de metal y la región quedaría libre de esos restos de la guerra.", progress = "Un brillo luminoso azulado envuelve el yunque.", completion = "Notas una sensación de éxito cuando te das cuenta de que tus esfuerzos siguen fortaleciendo los lazos entre Thorim y los Hijos de Hodir.", rewards = "Recibirás:\n\nObjeto #6"}
MultiLanguageQuestData['mx'][12982] = {title = "Prisioneros de la Espada de Ébano", objective = "Vaelen el Despellejado en La Cámara de las Sombras quiere que liberes a 8 prisioneros de la Espada de Ébano. Los podrás encontrar en las jaulas en la región de Jotunheim.", description = "Ahora que he vuelto, seguro que el barón querrá que recupere a mis hombres. Apenas estamos aguantando. Las fuerzas del Rey Exánime están a punto de abrirse paso y no podremos contenerlas sin los caballeros de la Muerte que fueron capturados. ¿Puedes ayudarme otra vez, <nombre>?\n\nVuelve a Jotunheim y sácalos de esas jaulas.\n\nRompe las condenadas cerraduras, me da igual lo que tengas que hacer. Probablemente los vrykuls tendrán llaves.\n\n¡Libera a mis hombres como sea!", progress = nil, completion = "Gracias, &lt;clase&gt;. Con los caballeros de la Muerte libres, podremos mantener las líneas... por ahora.", rewards = "Espaldares de ébanoCapucha de La Cámara de las SombrasGuantes del despellejadoEslabones del ensalmador de batallaRecibirás:\n\nObjeto #8"}
MultiLanguageQuestData['mx'][12983] = {title = "La última de su raza", objective = "Astrid Bjornrittar en el Poblado Brunnhildar quiere que rescates una matriarca Faucehielo en la Caverna Hibernal.", description = "Desde que tengo conocimiento hemos conseguido nuestros mejores osos de la Caverna Hibernal al este.\n\nPuede que esos tiempos hayan terminado. La cueva ha sido asaltada por los voraces jormungar y los osos salvajes casi están extinguidos.\n\nPero si encontraras una matriarca viva, te garantizo que lucharía mejor que cualquiera de los osos nacidos en cautividad.\n\nLleva este arnés a la Cueva Hibernal y rescata una matriarca. Que tengas suerte y encuentres a una.", progress = nil, completion = "Estoy impresionada. Jamás pensé que volvería a ver una matriarca Faucehielo. Sobre todo una de este tamaño.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12984] = {title = "Valduran el Natormento", objective = "Usa el cuerno de Guerra de Pedruscón cuando hayas encontrado a Valduran el Natormento. Vence a Valduran el Natormento y vuelve junto a Pedruscón el Creador de rocas en el Refugio de Pedruscón.", description = "No tenemos elección, <nombre>. Lo que has descubierto en el taller de Mimir indica que debemos actuar antes de que Valduran pueda completar y utilizar su nueva arma.\n\nIncluso ahora, los defensores del refugio luchan para darnos tiempo para que nos ocupemos de Valduran el Natormento.\n\nDebes ir a Nidavelir, cruzando las Llanuras Ventisquero al suroeste y encontrar y enfrentarte a Valduran. Pero no estarás <solo/sola>. Lleva este cuerno de guerra contigo y hazlo sonar cuando te prepares para luchar contra el líder de nuestros enemigos. Bruor y yo te ayudaremos en esta batalla.", progress = nil, completion = "Al fin, Valduran ha muerto y los Tronaforjado se han debilitado, pero si su bravuconería es cierta, debemos luchar contra los Tronaforjado aún en su ausencia. Esta arma que están construyendo podría acabar con nosotros.", rewards = "Guantes de cuero ensangrentadosCinturón de los TronaforjadoApisonadoras de PedruscónPodrás elegir una de estas recompensas:\n\nLinterna de llama encantada\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12985] = {title = "Forjar una cabeza", objective = "Njormeld en Dun Niffelem necesita que uses el pico con punta de diamante en los gigantes de hierro muertos en el lago Campo de Escarcha y vuelvas cuando tengas 8 ojos de Tronaforjado.", description = "Saludos, <raza>.\n\nTengo una tarea para la que el rey Jokkum cree que estás <capacitado/capacitada>, suponiendo que todavía quieras ganarte el favor de nuestro pueblo.\n\nHe creado los planos para otro artefacto, uno que le concederá la bendición de protección de Hodir a nuestra fortaleza. Tengo casi todo lo necesario para su construcción. Ya solo queda recoger los ojos de nuestros enemigos caídos.\n\nCoge esta herramienta y recoge los ojos de los cadáveres de los gigantes de hierro que llenan nuestros campos.", progress = "¿Has conseguido los últimos componentes que quiero, <raza>?", completion = "Casi está terminado.\n\nCon este artefacto colocado, Dun Niffelem conocerá los peligros que se avecinan antes de que caigan sobre nosotros.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12986] = {title = "El destino de los titanes", objective = "Creteus en Las Estepas Inferiores te ha pedido que viajes al Templo de la Invención, el Templo del Invierno, el Templo de la Vida y el Templo del Orden para utilizar el banco de datos y examinar cada zona.", description = "El núcleo de Norgannon no está aquí. No sé por qué lo buscas, <raza>, y no estoy del todo seguro de que conozcas de verdad el propósito de lo que buscas.\n\nMe gustaría que me ayudases antes de pensar en ofrecerte mi ayuda... Recientemente he recibido información sobre el vigilante, Thorim. Su poder está en peligro y su destino es incierto. Esto me preocupa, pues no conozco a los otros vigilantes. Utiliza este banco de datos para examinar sus templos al noreste y tráeme esa información.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Botas de escalador de hielo con pinchosPuños de invenciónManto del largo invernoPodrás elegir una de estas recompensas:\n\nObjeto #1Anillo de orden\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][12987] = {title = "La presentación del yelmo de Hodir", objective = "Njormeld quiere vueles a la cumbre de la Punta de Hielo del Norte de Dun Niffelem y uses las tablillas de Dictamen.", description = "El yelmo está forjado.\n\nTus esfuerzos no han pasado desapercibidos, <pequeño/pequeña>. Aunque queda mucho por hacer, los Hijos de Hodir te agradecemos tus logros.\n\nA cambio, te ofrezco la oportunidad de llevarle el yelmo de Hodir a nuestro rey y a nuestra gente.\n\nVuela hasta la brillante cumbre de la pequeña punta de hielo enfrente de mí y léele a nuestra gente lo que pone en esta tablilla.\n\nDisfruta del privilegio, <clase>. ¡Nunca antes un forastero había disfrutado de tal honor!", progress = nil, completion = "&lt;Njormeld contempla el yelmo de Hodir, visiblemente conmovido.&gt;\n\nEso servirá, pequeño &lt;raza&gt;.\n\nEso servirá...", rewards = "Recibirás:\n\nEmblema de heroísmo"}
MultiLanguageQuestData['mx'][12988] = {title = "¡Destruye las forjas!", objective = "Destruye la forja de relámpagos norte, la forja de relámpagos central y la forja de relámpagos sur con las bombas de Pedruscón y después vuelve junto a Pedruscón el Creador de rocas al refugio de Pedruscón.", description = "En mi locura pensé que el proyecto de Valduran en la Cuna de Narvir, una gran zona de construcción al sur, no era más que un monumento grotesco a la crueldad del \"Guardián\" Loken.\n\nAhora sabemos la verdad: va a utilizarse como arma contra nosotros y nuestros aliados. No debemos permitir que este coloso de hierro se complete, <nombre>, pues será el final del refugio.\n\nVe a la Cuna de Narvir, encuentra las forjas de relámpagos que usan los artesanos Tronaforjado y sabotéalas.", progress = nil, completion = "¡Excelente trabajo! Oh, eso no detendrá a los enanos férreos, pero necesitarán un tiempo valioso para reconstruir esas forjas. Me atrevo a decir que llevamos ventaja.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12989] = {title = "La oscuridad reptadora", objective = "Astrid Bjornrittar quiere que mates a 8 jormungar voraces en la Caverna Hibernal al este del Poblado Brunnhildar.", description = "Los viles jormungar han tomado la Caverna Hibernal casi por completo. Son seres despreciables... hijos de Loken, el repugnante hermano de Thorim.\n\nComo sirvientes de Thorim, nos dedicamos a matar a esa escoria allá donde la encontramos. Encontrarás la caverna al este de aquí, fuera de la aldea.", progress = nil, completion = "Los jormungar son criaturas viles. Has hecho bien en acabar con ellos.", rewards = "Galochas de jormungarColmillo de jormungarCoselete HibernalMusleras frías de BjornrittarProtector de jormungar escamadoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12990] = {title = "El agujero de gusano", objective = "Llévale a Jon LeCraft los materiales que necesita para evitar una muerte rápida y para aprender un nuevo hechizo muy chulo.", description = "Tráeme los materiales y te enseñaré a usar tu generador de agujeros de gusano.Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nAgujero de gusano: Gadgetzan"}
MultiLanguageQuestData['mx'][12991] = {title = "Dales donde más duele", objective = "Mata a 10 artificieros Tronaforjado y vuelve junto a Bruor Temeferro al Refugio de Pedruscón.", description = "Pedruscón tiene un buen plan para obstaculizar a los enanos férreos de la Cuna de Narvir y yo tengo otra idea. Sin artesanos, deberán detener los trabajos en el coloso de hierro.\n\nLa Cuna de Narvir está en el lado sur de la colina que abriga el Refugio de Pedruscón. Ve allí y mata a todos los artificieros Tronaforjado que encuentres en tu camino. Puede que no sean diferentes de lo que fuimos nosotros, pero están construyendo un arma que nos amenaza a todos.", progress = nil, completion = "Hubo un tiempo en el que jamás le habría pedido a nadie que hiciera lo que has hecho, pero mi experiencia con los enanos férreos ha acabado con esos sentimientos. Hemos ganado tiempo frente al avance del enemigo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12992] = {title = "¡Aplastar a los vrykuls!", objective = "Vil en La Cámara de las Sombras quiere que mates a 15 vrykuls cualesquiera en la región de Jotunheim.", description = "¡Machacar a los vrykuls en Jotunheim!\n\n¡<nombre> machacar bien!", progress = nil, completion = "¡&lt;nombre&gt; es mi &lt;raza&gt; más mejor!", rewards = "Triturador vrykulAtizador de VilBastón fraguahierroArco de hueso y tendónCaña sin uniones de VilRecibirás:\n\n"}
MultiLanguageQuestData['mx'][12993] = {title = "Una amenaza colosal", objective = "Recupera el plan de ataque de coloso y el plan de defensa de coloso y llévaselos a Pedruscón el Creador de rocas en el Refugio de Pedruscón.", description = "Has hecho un gran trabajo retrasando los trabajos en el coloso de hierro, pero me temo que solo hemos hecho que los Tronaforjado se vuelquen en completar el arma.\n\nIncluso ahora están llevando a nuevos trabajadores y sobrestantes hasta el límite. Puede que al final no podamos evitar que activen al coloso. Vuelve a la Cuna de Narvir, al sur, y encuentra los documentos que describan las capacidades ofensivas y defensivas del coloso. Deberían estar cerca de las tiendas de campaña y las forjas del nivel inferior.", progress = "¿Has encontrado los documentos que estamos buscando?", completion = "&lt;Pedruscón comienza a leer los documentos, con los ojos muy abiertos.&gt;\n\n¡No tenía ni idea de que los férreos fueran capaces de esto! Si completan este behemoth, nuestros hombres no tendrán ni una posibilidad. Por suerte, al parecer todavía les falta una pieza clave.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12994] = {title = "Cazador de espías", objective = "Debes derrotar a 3 espías Tronaforjado en el Valle de los Viejos Inviernos.\n\nUsa el colmillo de huargo etéreo sobre el cadáver de huargo caído para invocar a un huargo de escarcha etéreo que descubrirá a los enemigos ocultos. Debes volver junto a la madre del cubil huargo de escarcha en Dun Niffelem cuando hayas acabado con los espías del valle.", description = "La relación que has establecido con los habitantes de Dun Niffelem ha proporcionado algunos descubrimientos inesperados.\n\nPor ejemplo, de alguna forma ahora puedes entender los gruñidos guturales y las bromas mordaces de la madre del cubil... o al menos eso crees.\n\nAl parecer, ella siente peligro fuera de la fortaleza y quiere que hagas algo al respecto.\n\nSe quita la cadena que lleva alrededor del cuello con su pata delantera y la deja caer a tus pies. Cuando la recoges, te fijas en el colmillo antiguo que lleva atado...", progress = nil, completion = "Mientras vuelves a deslizar la cadena alrededor de su cuello, la madre del cubil te lame la cara con aprobación.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12995] = {title = "Dejar nuestra huella", objective = "El Barón Tajada en La Cámara de las Sombras quiere que coloques 15 estandartes de la Espada de Ébano sobre los cadáveres de los vrykuls que encuentres en la región de Jotunheim.", description = "Debemos atacar a los vrykuls de Jotunheim de muchas maneras. La fuerza bruta es, por supuesto, una buena opción, pero yo prefiero un enfoque más cerebral.\n\nQuiero que los desmoralices.\n\nMis hombres han forjado varios estandartes para ti. Me gustaría que los cogieses y los colocases sobre los cadáveres de los vrykuls muertos.\n\nDeja que los estandartes sirvan como recordatorio constante de que se enfrentan a una amenaza más inmediata que la cólera del Rey Exánime.", progress = nil, completion = "Buen trabajo, &lt;nombre&gt;. Dejemos que vean los cadáveres profanados de sus camaradas caídos. ¡Seguro que ahora se piensan dos veces el atacarnos!\n\nSi vuelves mañana, tendré preparados más estandartes para ti.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12996] = {title = "El calentamiento", objective = "Astrid Bjornrittar del Poblado Brunnhildar quiere que uses las riendas de matriarca oso de guerra para derrotar a Kirgaraak.", description = "Has tenido mucha suerte, hermana. Esta es una matriarca como no se ha visto en años.\n\nTener un buen oso no te servirá de nada sin la habilidad de montarlo.\n\nVoy a dejarte practicar algunos movimientos con Kirgaraak. Es el yeti más grande que hemos conseguido capturar hasta la fecha, así que ten cuidado. Que no te de miedo irte si te pega una paliza... si lo tenemos encadenado es por algo.", progress = nil, completion = "No está mal. Esperaba que Kirgaraak te partiese el cuello para poder quedarme tu oso.\n\nSolo bromeaba, hermana. Bueno, iba medio en broma. Tienes un oso muy bueno.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][12997] = {title = "Al foso", objective = "Astrid Bjornrittar del Poblado Brunnhildar quiere que uses las riendas de matriarca oso de guerra dentro del Foso del Colmillo y derrotes a 6 osos de guerra de El Encuentro Hyldnir.", description = "Superar a un oponente atado es una cosa. Luchar con otras jinetes de oso en igualdad de condiciones, es otra cosa.\n\nVe al Foso del Colmillo y usa lo que has aprendido para derrotar a tus oponentes. Buena suerte, hermana.\n\nSi tienes éxito te aguarda la gloria.", progress = nil, completion = "¡Lo has logrado! Has salido indemne. Ojalá pudiéramos decir lo mismo de tu osa.\n\nVa a necesitar tiempo para recuperarse. Por suerte no la necesitarás durante un tiempo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12998] = {title = "El Corazón de la Tormenta", objective = "Pedruscón el Creador de rocas en el Refugio de Pedruscón quiere que viajes a Uldis e intentes evitar que el Sobrestante Narvir consiga el Corazón de la Tormenta.", description = "Según los documentos que conseguiste en la Cuna de Narvir, al coloso de hierro solo le falta un componente clave para estar acabado: el Corazón de la Tormenta.\n\nSin él, las armas del coloso de hierro serían mucho más débiles de lo que prevé el diseño. Si podemos impedir que el Sobrestante Narvir consiga el corazón, ¡podríamos derrotar al coloso!\n\nLas notas en los documentos que encontraste indican que el corazón está en Uldis, una instalación de los titanes muy al sur. Su entrada está en el lado sur de una gran montaña sobre el Río del Aliento de Bor.", progress = nil, completion = "¡Con el corazón en manos de Narvir, el coloso funcionará a plena potencia! La única opción que tenemos es luchar contra él.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][12999] = {title = "La Bruja Osaria", objective = "Habla con la Bruja Osaria en la cueva del poblado Njorndar.", description = "Te acuerdas de Lady Bosqueténebro, ¿verdad? Ella sí que se acuerda de ti. Es el alma en pena furiosa y desesperada a la que \"salvaste\" cuando también nos liberaste a Vil y a mí del dominio del Rey Exánime.\n\nLa dama ha ido a Jotunheim y ha poseído a su Bruja Osaria. Quiere sembrar el caos entre los vrykuls desde dentro.\n\nHa pedido que la busques. La encontrarás en la cueva que hay en el lado sur del poblado de Njorndar, al suroeste de Jotunheim.", progress = nil, completion = "&lt;nombre&gt;, has venido.\n\nYa he oído hablar de tus actividades en la Cornisa Salvaje. Eso está bien. Me alegra ver que quieres ayudar a debilitar a los vrykuls de Jotunheim.\n\n\n\n¡Tú y yo nos vamos a divertir mucho con ellos!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13000] = {title = "Medidas de emergencia", objective = "La guardia de sangre Lorga quiere que vayas a la Guarida de Gimorak al este y que consigas 6 pieles de huargo.", description = "El frío en estas montañas es brutal. Nos queda un día o dos antes de que quememos toda la madera del naufragio.\n\nHemos visto unos huargos dentro de una caverna al este de aquí. Necesito que la encuentres y nos consigas algunas pieles. Puede que no parezca mucho, pero puede marcar la diferencia entre morir congelado y vivir otro día.\n\nLos huargos no cazan solos, así que te voy a dar una bengala. Te debería conseguir algo de tiempo si ves que te superan en número.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Cincho AúllaescarchaBrazales nómadasPeto del forestal del norteQuijotes de pasión fríaRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][13001] = {title = "La forja de la lanza de Hodir", objective = "El Tradicionalista Randvir en Dun Niffelem quiere que recojas 3 fragmentos de siempreescarcha en las profundidades de la Caverna Hibernal y 3 pieles de mamut estoico de los mamuts estoicos del Valle de los Viejos Inviernos.", description = "Ha llegado el momento, <pequeño/pequeña:c> <clase>. Las estrellas han predicho este día.\n\nHe recibido una visión del mismísimo Hodir, revelándome el secreto de la creación de un gran artefacto.\n\n¡Debemos obedecer! Si no logramos recibir este regalo, seguro que estaremos perdidos.\n\nTe pido que me ayudes en esta tarea sagrada.\n\nVe al otro lado del valle, a las profundidades de la Caverna Hibernal y recoge fragmentos de siempreescarcha del cráter helado que hay allí, después consigue pieles de los mamuts que hay fuera de la caverna.Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nSee Hodir's Spear Primer\n\nRecibirás:\n\nEmblema de heroísmo"}
MultiLanguageQuestData['mx'][13002] = {title = "Gemas perfectas", objective = "Llévale dos citrinos enormes, dos jades oscuros y dos cristales de Sombras a Geba'li en el Bastión Grito de Guerra.", description = "<Bienvenido/Bienvenida> al frío, <tron/titi>. Este garito puede que no mole para mantener el cuerpo caliente, pero he aprendido cómo tallar gemas perfectas. Lo único que necesito son algunas para trabajar.\n\nEsto te permitirá que a veces talles una gema perfecta, con mayor bonificación, cuando intentes tallar una gema de calidad inusual de Rasganorte.Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nPerfección de gemas\n\nTambién recibirás:\n\nBolsa de terciopelo pequeña"}
MultiLanguageQuestData['mx'][13003] = {title = "Cómo matar a tu dragón", objective = "Debes usar la lanza de Hodir para retar a una vermis salvaje en el Valle de los Viejos Inviernos. Cuando estés entre sus garras, lucha contra ella hasta la muerte.", description = "La lanza de Hodir es un icono de gran destreza en la batalla.\n\nSu mera presencia provoca una fuerte sed de gloria a todos los que entran en Dun Niffelem. De hecho, con solo estar cerca de ella te has sentido <impulsado/impulsada> a probar tus propias facultades.\n\nMirando hacia el horizonte, tu mirada se posa en una vermis salvaje que vuela por las cercanías.\n\nEstá decidido. Solo uno de ustedes dos volverá a ver amanecer...", progress = nil, completion = "Ya está.\n\nHas mirado a la muerte a los ojos y has salido victoriosa.\n\n¡Al derrotar tú sola a una bestia así, has proporcionado un gran honor a Dun Niffelem!", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][13004] = {title = "Gemas perfectas", objective = "Llévale dos citrinos enormes, dos jades oscuros y dos cristales de Sombras a Alestros en la Fortaleza Denuedo.", description = "¡Hay una guerra en marcha y cada uno de nosotros debe cumplir con su parte! La mía es tallar gemas y no solo puedo tallar gemas normales, también sé cómo tallar gemas perfectas. Si me traes algunas gemas sin tallar para contribuir a la causa, puedo enseñártelo a ti también. Esto te permitirá que a veces talles una gema perfecta, con mayor bonificación, cuando intentes tallar una gema de calidad inusual de Rasganorte.Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nPerfección de gemas\n\nTambién recibirás:\n\nBolsa de terciopelo pequeña"}
MultiLanguageQuestData['mx'][13005] = {title = "El juramento terráneo", objective = "Thorim, en el Bancal de los Creadores, quiere que uses el cuerno de Las Cumbres para llamar a los terráneos y derrotar a 20 enanos férreos y a 7 centinelas de hierro.", description = "Durante años he ignorado mis deberes, cediendo ante la derrota y la autocompasión.\n\nPero los valientes terráneos no lo han hecho. Su juramento de proteger estas tierras con sus vidas nunca se ha roto.\n\nIncluso ahora, luchan contra la corrupción del hierro de forma altruista, esperando el momento en el que cambien las tornas.\n\nEse momento ha llegado. Debemos reunir a los defensores terráneos que quedan y liderarlos hacia una victoria gloriosa. Toca el cuerno de Las Cumbres para llamarlos a tu lado y recuperar el Bancal de los Creadores.", progress = nil, completion = "Es un buen comienzo. Pero las fuerzas de mi hermano no tardarán en reagruparse. Debemos hacer que nuestra victoria sea firme.", rewards = "Guantes de observador del bancalBrazales de TarbashGarra de ThorimSobrehombros de poder terráneoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][13006] = {title = "Una limpieza viscosa", objective = "Debes entrar en la Caverna Hibernal al oeste de Dun Niffelem y recoger 5 unidades de aceite viscoso de los aceites viscosos que hay allí.\n\nDespués debes volver a Dun Niffelem y aplicar el aceite sobre el yelmo de Hodir.", description = "Cuando te acercas al yelmo, te fijas en que el glacial entorno ya está pasando factura a la superficie del objeto. Lo que ahora es una delgada capa de hielo, acabará cubriéndolo por completo.\n\nComo no estás <dispuesto/dispuesta> a dejar que tus enormes esfuerzos se echen a perder, decides recorrer la región en busca de una solución.\n\nJusto cuando te dispones a salir, los ojos del yelmo brillan y una imagen de la cercana Caverna Hibernal aparece en tu mente.", progress = "Mientras miras, la escarcha se va haciendo más gruesa y comienzan a formarse carámbanos en los bordes…", completion = "Cuando cubres el yelmo con una fina capa de aceite, la escarcha cae y su superficie comienza a brillar.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13007] = {title = "El coloso de hierro", objective = "Usa a un jormungar domado para derrotar al coloso de hierro y volver con Pedruscón el Creador de rocas en el Refugio de Pedruscón.", description = "No hemos podido evitar que completasen el coloso de hierro, <nombre>, lo que significa que no nos queda otra elección que combatir contra él.\n\nBruor ha diseñado un plan para aprovecharnos de la única debilidad del coloso.\n\nDa igual lo dura que sea la armadura del coloso, sigue siendo vulnerable al ácido de jormungar. Controla a uno utilizando los orbes del lado norte de las Llanuras Ventisquero y úsalo para luchar contra el coloso de hierro en las Llanuras. Si necesitas ayuda para controlar a las criaturas, habla con uno de los cuidadores cercanos.", progress = nil, completion = "¡Lo hemos logrado, lo hemos logrado de verdad! ¡El refugio se ha salvado y los Tronaforjado han sido derrotados! Debemos avisar a Brann antes de que Loken se recupere e intente reconstruir sus fuerzas. La única forma de asegurar la victoria que has conseguido es ir a Ulduar y derrotar a Loken, ¡de una vez por todas!", rewards = "Bombachos de VentisqueroLeotardos de renovación agudizadaMusleras de pellejo de jormungarQuijotes de coloso férreoRecibirás:\n\nEmblema de heroísmo"}
MultiLanguageQuestData['mx'][13008] = {title = "Tácticas de la Plaga", objective = "El Comandante de Cruzada Entari en La Vanguardia Argenta en Corona de Hielo te ha pedido que liberes a 8 cruzados enredados.", description = "¡Teníamos de nuestra parte el elemento sorpresa! Hicimos un agujero en un lado de la montaña y cargamos contra la Ciudad de la Plaga. La oposición de la Plaga fue feroz y no pasó mucho tiempo hasta que nos superaron en número. Retrocedimos hasta el valle y comenzamos a disparar con la artillería a la Plaga que nos siguió. Esto los retrasó un poco hasta que... esos monstruos empezaron a usar cruzados como escudos vivos. Tuvimos que parar de disparar por miedo a matar a nuestros propios soldados.\n\n¡Libera a nuestros cruzados atrapados en el campo que hay fuera de la base, <clase>!", progress = nil, completion = "Todavía quedan muchos soldados de la Cruzada Argenta en ese campo y en la Ciudad de la Plaga, &lt;nombre&gt;. Aunque agradezco tu ayuda, aún queda mucho por hacer.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13009] = {title = "Un nuevo comienzo", objective = "Njormeld quiere que le lleves la armadura reforjada a Thorim en el Templo de las Tormentas.", description = "No se sabe si nuestro pueblo podrá reavivar el afecto que teníamos antaño por Thorim.\n\nSi no hay otra cosa, que esta armadura le recuerde los días en los que estábamos unidos por el honor y éramos invencibles.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13010] = {title = "Krolmir, el Martillo de las Tormentas", objective = "Thorim quiere que hables con el rey Jokkum en Dun Niffelem y que descubras lo que sabe sobre Krolmir.", description = "Antes de que pueda reclamar mi hogar en el Bancal de los Creadores queda una cosa por hacer.\n\nHay que encontrar a Krolmir.\n\nEn aquel fatídico día, lo lancé a la tierra con toda la fuerza y rabia que tenía. Hubo una gran explosión.\n\nDurante todos estos años creí que lo había perdido, pero necesito asegurarme.\n\nVuelve con el rey Jokkum y descubre si sabe algo sobre el destino de mi martillo.", progress = nil, completion = "Las palabras no pueden expresar mi gratitud, &lt;clase&gt;.\n\nMe has servido con honor. Por favor, acepta esta muestra de mi gratitud.", rewards = "Puños deteriorados por la tormentaAgarre del acechatormentasMandiletes ambiguosPodrás elegir una de estas recompensas:\n\nGuardapelo de cresta de nieve\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][13011] = {title = "La última cena de Jorcuttar", objective = "El rey Jokkum en Dun Niffelem quiere que mates a Jorcuttar en la Caverna Hibernal.", description = "Tengo una oportunidad que te ayudará a ganarte la aprobación de mi pueblo, suponiendo que lo consigas.\n\nLos jormungar son una molestia de la que es mejor ocuparse rápido. Si se les da la oportunidad, se reproducen como conejos y se extienden como el fuego.\n\nHan aparecido al suroeste de aquí, en la Caverna Hibernal. Si su madre reproductora no muere pronto, conseguirán un punto de apoyo en nuestra región.\n\nJormuttar es incapaz de resistirse a la comida. Coge este cuchillo y corta el costillar del cadáver de un oso de la cueva de Jormuttar. Ponlo cerca de su cráter y mátala mientras se alimenta.", progress = nil, completion = "Así que ya está.\n\nHemos escuchado los gritos de Jorcuttar que resonaban por el valle.\n\nHoy le has prestado un buen servicio a nuestro pueblo, pequeño &lt;raza&gt;.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][13012] = {title = "Sardis el Ancestro", objective = "Me alegra saber que la gente de esta tierra aún honra a las razas antiguas. Te deseo lo mejor, <nombre>, y te ofrezco este regalo...", description = nil, progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nAutoforzarse: reverencia\n\nRecibirás:\n\nMoneda de linajeSobre rojo de la suerte"}
