MultiLanguageQuestData['mx'][13476] = {title = "Cuestión de honor", objective = "Entrega 1 marca de Honor de cada campo de batalla a un belisario de la Horda en cualquiera de las capitales de la Horda, Shattrath, Dalaran o Conquista del Invierno.", description = "¡Servir a la Horda en una de las grandes batallas contra la Alianza es fuente de gran honor! Pero los pocos que han servido a la Horda en TODOS los frentes de batalla activos son los más grandes de nuestros combatientes. Debemos derrotar a nuestros oponentes, pero no luchando en escaramuzas aisladas sino en una guerra bien coordinada.\n\n¡Adelante, derrota a la Alianza en todos los frentes! ¡Por el honor! ¡Por la Horda!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13478] = {title = "Esfuerzos concertados", objective = "Entrega 1 marca de Honor de cada campo de batalla a un general de brigada de la Alianza en cualquiera de las capitales de la Alianza, Shattrath, Dalaran o Conquista del Invierno.", description = "Ya no estamos combatiendo en batallas aisladas contra la Horda, <muchacho/muchacha>.\n\nLa victoria en uno de los frentes supone negar a la Horda recursos que utilizarían contra nosotros en otra batalla. Por eso mismo, perder una batalla daría ventaja a nuestros adversarios en algún otro lugar del mundo.\n\nLa Alianza necesita más combatientes que comprendan esta realidad... ¡veteranos realmente avezados! <nombre>, vuelve a verme cuando hayas servido contra la Horda en todos nuestros campos de batalla activos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13479] = {title = "La gran búsqueda de huevos", objective = "El recolector primaveral quiere que consigas 20 trozos de cáscara.", description = "El Jardín Noble, ¡la celebración de la vida y de la primavera! Espero que te estés divirtiendo con la búsqueda de huevos, <amigo/amiga>, porque me gustaría hacer uso de alguien tan capaz como tú.\n\nNo sé con certeza qué tipo de magia se usó para crear los huevos, y los druidas no parecen querer explicármelo. Quizás puedas recogerme unos trozos de cáscara mientras buscas huevos. Te puedes quedar con lo que hay dentro. Solo necesito una muestra suficiente de los huevos en sí.", progress = "¿Tienes los trozos?", completion = "¡Fantástico, fantástico, gracias! Puede que me haga falta más de una muestra para conseguir resultados verdaderamente concluyentes, pero lo has hecho muy bien por hoy.", rewards = "Recibirás:\n\nRama en flor"}
MultiLanguageQuestData['mx'][13480] = {title = "La gran búsqueda de huevos", objective = "El colector primaveral quiere que consigas 20 trozos de cáscara.", description = "El Jardín Noble, ¡la celebración de la vida y de la primavera! Espero que te estés divirtiendo con la búsqueda de huevos, <amigo/amiga>, porque me gustaría hacer uso de alguien tan capaz como tú.\n\nNo sé con certeza qué tipo de magia se usó para crear los huevos, y los druidas no parecen querer explicármelo. Quizás puedas recogerme unos trozos de cáscara mientras buscas huevos. Te puedes quedar con lo que hay dentro. Solo necesito una muestra suficiente de los huevos en sí.", progress = "¿Tienes los trozos?", completion = "¡Fantástico, fantástico, gracias! Puede que me haga falta más de una muestra para conseguir resultados verdaderamente concluyentes, pero lo has hecho muy bien por hoy.", rewards = "Recibirás:\n\nRama en flor"}
MultiLanguageQuestData['mx'][13481] = {title = "¡Salgamos de aquí!", objective = "Escolta al padre Kamaros hasta un lugar seguro y después preséntate ante el hermano Keltan a bordo del Martillo de Orgrim.", description = "La Luz me sonríe. Aún no he muerto en esta pesadilla viviente, pero la Plaga me matará y hará pedazos mi cuerpo para usarlo en su \"trabajo\" si no consigo escapar.\n\nNo puedo conseguirlo solo, <clase>, pero con tu ayuda puede que viva para volver a luchar contra la Plaga.\n\n¿Me ayudarás a escapar antes de que los carniceros de la Plaga vengan a darme el golpe de gracia?", progress = nil, completion = "Lo has hecho bien. Pensábamos que habíamos perdido al padre Kamaros de verdad. Tu valentía servirá de ejemplo a aquellos que se opongan a la Plaga.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13482] = {title = "¡Salgamos de aquí!", objective = "Escolta al padre Kamaros hasta un lugar seguro y después preséntate ante Absalan el Piadoso a bordo de El Rompecielos.", description = "La Luz me sonríe. Aún no he muerto en esta pesadilla viviente, pero la Plaga me matará y hará pedazos mi cuerpo para usarlo en su \"trabajo\" si no consigo escapar.\n\nNo puedo conseguirlo solo, <hijo mío/hija mía>, pero con tu ayuda puede que viva para volver a luchar contra la Plaga.\n\n¿Me ayudarás a escapar antes de que los carniceros de la Plaga vengan a darme el golpe de gracia?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13483] = {title = "Recolectores primaverales", objective = "Habla con un recolector primaveral en Cerrotajo, Rémol, Poblado Pezuña de Sangre o Plaza Alalcón.", description = "Si buscas algo que hacer, he oído que hay magos en los asentamientos cercanos a las capitales: Cerrotajo, Rémol, Poblado Pezuña de Sangre y Plaza Alalcón que han estado reclutando cazadores de huevos para que les ayuden con una investigación que están llevando a cabo. No me sé bien los detalles, pero seguro que ellos te informan.", progress = nil, completion = "¡Sí! ¡Sí, creo que tengo la tarea perfecta para ti!", rewards = nil}
MultiLanguageQuestData['mx'][13484] = {title = "Colectores primaverales", objective = "Habla con un colector primaveral en Villadorada, Kharanos, Dolanaar o Avanzada Azur.", description = "Si buscas algo que hacer, he oído que hay magos en los asentamientos cercanos a las capitales: Villadorada, Kharanos, Dolanaar y Avanzada Azur que han estado reclutando cazadores de huevos para que les ayuden con una investigación que están llevando a cabo. No me sé bien los detalles, pero seguro que ellos te informan.", progress = nil, completion = "¡Sí! ¡Sí, creo que tengo la tarea perfecta para ti!", rewards = "Recibirás:\n\n"}
