MultiLanguageQuestData['mx'][13502] = {title = "¿Qué llevas en la cestita?", objective = "El vendedor del Jardín Noble quiere que reúnas 10 chocolates del Jardín Noble y que se los lleves de vuelta junto a la cesta de huevos prestada.", description = "Toma esta cesta de huevos y vete a buscar huevos de colores vivos. Ven a verme con la cesta cuando hayas encontrado 10 chocolates del Jardín Noble.", progress = "¿Tienes los 10 chocolates del Jardín Noble?", completion = "¡Buen trabajo! ¡Ten... quédate con la cesta!\n\nRecuerda, ¡puedes venir cuando quieras a canjear chocolates del Jardín Noble por otros objetos!", rewards = "Recibirás:\n\nCesta de huevos"}
MultiLanguageQuestData['mx'][13503] = {title = "¿Qué llevas en la cestita?", objective = "El mercader del Jardín Noble quiere que reúnas 10 chocolates del Jardín Noble y que se los lleves de vuelta junto a la cesta de huevos prestada.", description = "Toma esta cesta de huevos y vete a buscar huevos de colores vivos. Ven a verme con la cesta cuando hayas encontrado 10 chocolates del Jardín Noble.", progress = "¿Tienes los 10 chocolates del Jardín Noble?", completion = "¡Buen trabajo! ¡Ten... quédate con la cesta!\n\nRecuerda, ¡puedes venir cuando quieras a canjear chocolates del Jardín Noble por otros objetos!", rewards = "Recibirás:\n\nCesta de huevos"}
MultiLanguageQuestData['mx'][13506] = {title = "Espías a la vista", objective = "Lleva las órdenes Rompelanzas a la teniente Morra Brisa Estelar en las Ruinas de Mathystra.", description = "Estas parecen órdenes dirigidas a los sobrestantes de las ruinas de parte de algún superior del Campamento de Guerra Rompelanzas. Casi todo el documento contiene apreciaciones estratégicas insignificantes, pero unas cuantas líneas te llaman la atención.\n\n\"Hemos capturado a otra elfa que espiaba nuestras operaciones. Se la ha trasladado al campamento para ser torturada a cambio de información. Permaneced atentos por si hubiera más espías, no podemos permitir que la operación se vea comprometida.\"\n\nSeguro que a la teniente le interesa esta información.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13510] = {title = "Una llegada oportuna", objective = "Escolta a la centinela Aynasha hasta que esté a salvo.", description = "Me alegra verte. No esperaba soportar lo que le hicieron a Alanndarian así que, gracias por rescatarme.\n\nAntes de ser capturada, vi al líder trol y pensé que se me había presentado la oportunidad perfecta para matarlo, pero estaba protegido por algún tipo de escudo mágico. Morra necesitará esta información antes de preparar el asalto, pero, primero, hay que salir de aquí.\n\nAyúdame a llegar al muelle, llegaré hasta Lor'danel por el agua. Tú puedes volver junto a Morra con tu astucia.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de MorraEspada de repuesto de AynashaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][13514] = {title = "La ira de los Ancestros", objective = "Utiliza a un protector vengativo para matar a 30 trols Rompelanzas y destruir 6 edificios Rompelanzas.", description = "¿Has venido a unirte a la ofensiva? Si estás buscando a Sandrya Puestaluna, la encontrarás dirigiendo el ataque contra el líder Rompelanzas en la cueva de detrás del valle.\n\nAunque, ya que estás aquí, podrías ayudarnos a eliminar al resto de la tribu. Dirígete allí, sírvete de uno de los protectores vengativos y asegúrate de no dejar títere con cabeza. No podemos arriesgarnos a que regresen en busca de venganza cuando estemos menos preparados, ¿no?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13519] = {title = "El Martillo Crepuscular", objective = "Mata al sumo cultor Azerynn y a 10 fanáticos Crepusculares en el Campamento Crepuscular.", description = "Un grupo de cultores Crepusculares han levantado un campamento al suroeste de aquí. Están reuniendo un ejército de elementales de agua para atacar Lor'danel.\n\nSu líder, el sumo cultor Azerynn, ha pactado con los oscuros dioses antiguos que otorgan a su secta poderes sobre los elementales. Encárgate de ellos antes de que sea tarde, <nombre>.\n\nEl Cataclismo ha vuelto confusos a los espíritus de los elementales... es cuestión de tiempo que reúnan a los elementales necesarios para reducir nuestras defensas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Botines fanáticosGuantes de puño enmalladoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][13522] = {title = "Amenaza acuífera", objective = "Mata a 8 rocíos viles.", description = "Todavía hay algunos supervivientes del último ataque a Auberdine que intentan llegar a la costa para ponerse a salvo. Solo hemos oído que se dirigen hacia aquí en esta última hora. Ojalá recibiéramos más avisos...\n\nLa línea de costa del oeste está plagada de rocíos viles; unos pequeños y despiadados elementales de agua. Tenemos que eliminarlos para que los supervivientes puedan llegar hasta Lor'danel. Parte inmediatamente y mata a todos los elementales que encuentres.", progress = nil, completion = "Valoramos mucho tus esfuerzos. Desde el Cataclismo, los elementales se han descontrolado. Tenemos pocas esperanzas de recuperar Auberdine sin eliminar antes su presencia.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13523] = {title = "Poder sobre las olas", objective = "Utiliza el orbe de Elune en los restos de 6 espíritus de mareas iracundos.", description = "No te preocupes por mí. Mis heridas son profundas y la muerte se cernirá pronto sobre mí.\n\nAhora todo depende de ti... tienes que detener al Martillo Crepuscular.\n\nLos dioses antiguos a los que adoran les han otorgado poderes sobre los espíritus del agua agitados... pero es un poder débil. Canaliza la presencia de Elune a través de este orbe cuando hayas derrotado a los elementales.\n\nUsa el poder de Elune para expulsar a los espíritus para siempre.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Capa de la mareaBendición de TharillRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][13524] = {title = "Huye de Arroyoplata", objective = "Abre la jaula de madera y ayuda al explorador de la Alianza liberado a escapar de Arroyoplata. Cuando llegues al Refugio Pino Ámbar, informa al teniente Dumont.", description = "Tú... ¿no eres <uno/una> de ellos? ¡Rápido! ¡Déjame salir!\n\n¡Debemos llegar al Refugio Pino Ámbar inmediatamente! Cuando el teniente Dumont se entere de quiénes son estas personas en verdad, ¡esta ciudad se verá reducida a escombros!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Vestiduras de la bestia enjauladaBotas de conflicto internoGuardamuñecas del alma atormentadaEscarpes de humanidad machacadaPodrás elegir una de estas recompensas:\n\nAnillo de matahuargos\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][13525] = {title = "¿Qué ocurre con los fúrbolgs Bosque Negro?", objective = "Habla con el anciano Brolg en el Fuerte del Bosque Negro.", description = "Nuestros ancestros convivieron con los fúrbolgs Bosque Negro durante generaciones. Pero recientemente, hemos perdido el contacto con sus asentamientos situados en lo más profundo del bosque. Uno de sus mayores campamentos, el Fuerte del Bosque Negro, se sitúa en el sur.\n\nDirígete allí y busca al anciano Brolg. Pregúntale por qué su pueblo nos ha retirado su apoyo y ofrécele tu ayuda si es necesario.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13526] = {title = "La pata de oso", objective = "Lleva 8 tallos de pata de oso al anciano Brolg al Fuerte del Bosque Negro.", description = "Los malditos sátiros de Frondavil han empezado a introducir su veneno en nuestras tierras de Costa Oscura. Su corrupción mata la tierra y enloquece a las criaturas que la habitan. Mi pueblo tampoco se ha librado.\n\nNuestra magia no es suficiente para hacerles recuperar el juicio. Existe una hierba llamada pata de oso que utilizamos para combatir la fiebre y fortalecer a los débiles. Con su ayuda, podríamos detener la influencia de los sátiros. La hierba crece en la maleza que hay alrededor del poblado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13537] = {title = "Sabor a mero", objective = "Usa tu habilidad para la pesca para obtener 4 meros de Costa Oscura.", description = "Entre los viajes en barco y la construcción, estoy exhausto... y hambriento. ¿Sabes qué parece rico? El pescado. El pescado parece delicioso.\n\nCosta Oscura es famosa por su mero. Si me pescas unos cuantos, te recompensaré.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCaña de pescar de Staats"}
MultiLanguageQuestData['mx'][13538] = {title = "Sabotaje al sur", objective = "Destruye la Torre de la Vista de las Sombras, la Torre de la Guardia en Llamas o la Torre Filoinvierno y vuelve a ver al oficial de táctica Ahbramis en Conquista del Invierno.", description = "¡Las tres torres al sur del Río Conquista del Invierno drenan poder de la fortaleza! \n\nDestruye la Torre de la Vista de las Sombras, la Torre de la Guardia en Llamas o la Torre Filoinvierno y luego vuelve a verme. ¡Recuerda, solo los vehículos de asedio pueden dañar una torre, así que protégelos de la Horda!", progress = nil, completion = "¡Oí la explosión desde aquí! Has hecho un trabajo excelente, ya hemos empezado a redirigir el poder hacia la reliquia de titán para cargar nuestras fuerzas al máximo.", rewards = "Recibirás:\n\nPuntos de honorFragmento de vigilante de piedra"}
MultiLanguageQuestData['mx'][13539] = {title = "Derribar las torres", objective = "Destruye la Torre de la Vista de las Sombras, la Torre de la Guardia en Llamas o la Torre Filoinvierno y vuelve a ver al oficial de táctica Kilrath en Conquista del Invierno.", description = "Aunque la Alianza esté aporreando nuestras puertas, un verdadero táctico ve más allá de lo que es evidente.\n\n\"Atacar cuando no están preparados, aparecer cuando nadie te espera.\"\n\n<nombre>, Necesito que vayas a través del Río Conquista del Invierno y que destruyas una de las tres torres al sur. Nuestros brujos nos han informado de que las torres drenan poder que podemos usar para reforzar nuestras tropas.\n\nVuelve a verme cuando hayas destruido una torre.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPuntos de honorFragmento de vigilante de piedra"}
MultiLanguageQuestData['mx'][13542] = {title = "A contraviento", objective = "Utiliza la Poza de la Luna de las Ruinas de Auberdine para destruir 8 conjuntos de brazales de ciclón demenciado.", description = "Si vamos a arrebatar las Ruinas de Auberdine al Martillo Crepuscular, debemos ocuparnos para siempre de los elementales que han invocado.\n\nAhí es donde entras tú.\n\nVerás, no espero que recuperes la ciudad pero, mientras seguimos curándonos por aquí, podrías debilitar su resistencia.\n\nPara acabar de una vez por todas con los ciclones demenciados, dirígete al oeste, mátalos, coge sus brazales y deposítalos en la Poza de la Luna. Eso evitará que vuelvan a ser invocados.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Brazales mansosBrazales muy tranquilosRecibirás:\n\nObjeto #12"}
MultiLanguageQuestData['mx'][13543] = {title = "Los tres cultores Crepusculares", objective = "Mata a Domanubes Ferocrín, al Maestro del Viento Tzu-Tzu y al Señor del Cielo Braax.", description = "He volado sobre las Ruinas de Auberdine en misión de exploración. Hay tres cultores Crepusculares responsables de los elementales que han invadido la ciudad en ruinas.\n\nDirígete a las ruinas situadas al oeste. Busca y mata a Domanubes Ferocrín, al Maestro del Viento Tzu-Tzu y al Señor del Cielo Braax.\n\nSolo así, la centinela Selarin y sus fuerzas tendrán la oportunidad de recuperar su hogar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13545] = {title = "Purificando a los afectados", objective = "El anciano Brolg quiere que utilices el fardo de hierbas benditas para purificar a 7 fúrbolgs del Fuerte del Bosque Negro y mates a los espíritus de corrupción que les hicieron enloquecer.", description = "Con las hierbas sagradas y la bendición del oso, utiliza este fardo de hierbas para purificar a mis hermanos. La corrupción que se ha desbordado desde Frondavil les ha hecho enloquecer y atacarán a cualquiera que se les acerque. No te sorprendas si los Bosque Negro afectados se muestran enfadados contigo hasta que mates a los espíritus de la corrupción que les hechizaron.\n\nCuando hayas liberado a mis hermanos de su locura, vuelve conmigo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][13546] = {title = "El Rapiñador", objective = "El anciano Brolg en el Fuerte del Bosque Negro quiere que mates a Sharax el Rapiñador.", description = "Los sátiros Fuego de Jade de Frondavil han conseguido entrar en Costa Oscura y han contaminado la tierra, el agua y a las criaturas que se han encontrado por el camino. Ya has visto lo que ha ocasionado la corrupción a mi pueblo y a sus hogares. Si no expulsamos a los sátiros, todos compartiremos el mismo destino.\n\nEn la cueva situada al este, se encuentra Sharax el Rapiñador, el sátiro responsable de los males de los Bosque Negro. Mátalo, <nombre>, y libéranos de su influencia. Demuestra a los sátiros que los Bosque Negro no se rendirán a la muerte tan fácilmente.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Botas Bosque NegroArco de cazador Bosque NegroPalo ritual Bosque NegroRecibirás:\n\n"}
MultiLanguageQuestData['mx'][13547] = {title = "Sonsacando a los espíritus", objective = "Sonsaca a los espíritus de Thundris Tejevientos, Elissa Brisa Estelar, Taldan y Caylais Plumalunar.", description = "Esos amigos tuyos que regresaron al campamento de refugiados no son conscientes del verdadero e inminente peligro que los cultores Crepusculares han traído al mundo.\n\nPara poder abordar este asunto, primero necesitaremos ayuda de los muertos de Auberdine.\n\nBusca entre las ruinas de la ciudad y encuentra los cadáveres de Thundris Tejevientos, Elissa Brisa Estelar, Taldan y Caylais Plumalunar. Sonsaca a los espíritus de sus cuerpos y vuelve aquí con ellos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13548] = {title = "Cubo de caramelos", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nTruco o trato\n\nRecibirás:\n\nPuñado de golosinas"}
MultiLanguageQuestData['mx'][13549] = {title = "Arriba la cola", objective = "El cronista To'kini en Zim'Torga quiere que utilices la cerbatana de To'kini sobre leopardos de escarcha y osos Patahielo. Vuelve con tres hembras de cada especie.", description = "Además de los artefactos Drakkari, me interesa volver a Zandalar con algo de la vida salvaje de Zul'Drak. Tengo machos de los leopardos de escarcha y de los osos Patahielo, ¡pero necesito hembras!\n\nEs una pena que mi trampero muriera en un accidente de lo más desafortunado. ¿Quizás quieras reemplazarlo?\n\nDuerme a los leopardos y a los osos con esta cerbatana, y después levántales la cola... y vuelve con alguna hembra si eres tan amable. Podrás encontrarlos cerca de los Altares de Rhunok, Quetz'lun y Har'koa.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][13556] = {title = "Huevos para Dubra'Jin", objective = "Ha'wana en Dubra'Jin necesita que recojas 12 huevos de raptor de Gundrak.", description = "¿Qué passa, <tron/titi>? ¿Me puedes echar una mano? Bah'Kini necesita muchos huevos de raptor p'al sacrificio en honor a Dubra'Jin.\n\n¿Por qué crees que aún no nos han invadío los Drakkari? ¡Dubra'Jin nos preh'ta su ayuda!\n\nNecesitamos que recojas huevos de raptor de alrededor de los árboles que hay a las afueras de Gundrak. A veces los raptores los llevan encima p'a mantene'hlos calientes.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13557] = {title = "Portar la buena suerte", objective = "Libera a 8 osos cardos o ratardeceres incorruptos de las jaulas de la Cuenca Fonroca.", description = "Esta llave parece servir para las jaulas de animales que hay por toda la Cuenca Fonroca. Seguro que Tharnarium agradecería que aprovecharas la ocasión para liberar a algunos de los ratardeceres y osos cardos incorruptos que aún permanecen cautivos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13559] = {title = "El tributo de Hodir", objective = "Los tributos ordinarios no eran suficientemente buenos para el gran Hodir cuando caminaba entre los gigantes de escarcha.\n\nPuede que ya no esté entre nosotros, pero hemos mantenido la tradición de ofrecer tributo a su fuerza y sabiduría. Sería muy provechoso para tu renombre que participaras en esta tradición, pequeño <clase>.", description = nil, progress = "Los tributos ordinarios no eran suficientemente buenos para el gran Hodir cuando caminaba entre los gigantes de escarcha.\n\nPuede que ya no esté entre nosotros, pero hemos mantenido la tradición de ofrecer tributo a su fuerza y sabiduría. Sería muy provechoso para tu renombre que participaras en esta tradición, pequeño <clase>.", completion = "Los Hijos de Hodir aceptan tu tributo, pequeño. Continúas probando tu valía como aliado de varias maneras.", rewards = nil}
MultiLanguageQuestData['mx'][13561] = {title = "Consuelo para los Altonato", objective = "Mata a 6 Altonato malditos y a 6 Altonato en pena.", description = "He venido a Bashal'Aran a traer la paz a los espíritus atormentados de los Altonato, pero mi mano duda en cada golpe que asesto. Si quisieras ayudarme, tendrías mi gratitud.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13565] = {title = "Eliminar por segunda vez", objective = "Utiliza la raíz petrificada para resucitar a 6 ents marchitos y matar a Lady Janira, la líder naga.", description = "No podemos tolerar la violencia sin miramientos; no forma parte de nuestra naturaleza. Sin embargo, hay veces que las consecuencias de evitar la batalla son demasiado tangibles para ser ignoradas, como en el caso de estos nagas.\n\nCuando la tierra de la zona se quebró, un pequeño grupo de ruinas emergió en el este. Estas ruinas una vez albergaron a los fieles de la reina Azshara, y parece que los suyos han regresado en busca de algo.\n\nTen esta raíz petrificada. Puedes utilizarla en sus caídos para resucitar ents que te ayudarán. Ocúpate pronto de ellos y de su líder.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Botas musgosasBrazales de escamas de nagaRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][13566] = {title = "Materiales de ritual", objective = "Consigue 3 bigotes de Acechalunas, 3 mechones de pelo de cierva jaspeada y 3 pelajes de oso cardo.", description = "Mientras cuidamos a Zarpadura, me gustaría que recogieras pacíficamente algunos materiales de la fauna local.\n\nNecesito bigotes de Acechalunas del oeste. Quítaselos a los que duermen y sal corriendo.\n\nNecesito pelo de cierva del este; evita los venados.\n\nFinalmente, necesito pelajes de los osos que merodean cerca del agua en el noreste. Espera hasta que vayan a pescar, coge la muestra rápidamente y vete antes de que terminen de comer.\n\nTe ruego que no hieras a ninguno.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13567] = {title = "El espíritu del venado", objective = "El vigilante Karithus te ha indicado cómo recibir la bendición del gran espíritu del venado.", description = "En estos bosques residen los tres grandes espíritus: el del venado, el del oso cardo y el acechalunas. Estos espíritus son poderosos aliados, pero solo te puedes alinear con uno de ellos.\n\nSi quieres alinearte con el gran espíritu del venado, lleva este incienso al bosque al norte de Bashal'Aran. Medita ante el gran espíritu mientras quemas el incienso en el suelo que los separa y enfréntate a su juicio para recibir su bendición. Si lo consigues, vuelve conmigo.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][13569] = {title = "El vínculo del ritual", objective = "Respira el incienso delante del vigilante Karithus y, después, elige la bendición del gran espíritu del venado, el gran espíritu del oso cardo o el gran espíritu Acechalunas.\n\nTen presente que solo podrás recibir la bendición de un espíritu, así que, elige sabiamente.", description = "Cuidaré de Zarpadura hasta que termine su reposo; pronto estará listo para volver. Tengo una tarea más para ti mientras esperamos... En realidad, se trata de concederte un favor si lo aceptas.\n\nLos grandes espíritus de la fauna yerran entre nosotros a la espera de que alguien nos ayude a detener la destrucción. Incluso ahora están presentes mientras hablamos, y, con los materiales que me has traído, puedo garantizarte que los veas. Habla con los espíritus, elige uno y vuelve cuando recibas su bendición.Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Brazales de AcechalunasCapa del venadoFaja de oso cardoTe van a lanzar el siguiente hechizo:\n\nVínculo ritual\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][13571] = {title = "Objetos perdidos de Flechero", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Aprenderás:\n\nKungaloosh\n\nTe van a lanzar el siguiente hechizo:\n\nKungaloosh"}
MultiLanguageQuestData['mx'][13572] = {title = "Los blandones Fuego de Jade", objective = "Gren Pelajirón del Fuerte del Bosque Negro quiere que destruyas 8 blandones Fuego de Jade.", description = "Los sátiros de Frondavil han empezado a extender su odio y su corrupción por nuestras tierras. Han enviado a Sharax el Rapiñador para que subyugue partes del bosque a las que, nosotros los Bosque Negro, llamamos hogar.\n\nAdemás de envenenar la tierra, los animales y las plantas, ha colocado varios brazales por el poblado para aumentar su control sobre los habitantes. No podremos detenerlo solo con destruir los brazales, pero ayudará a reducir su influencia mientras trabajas con el anciano Brolg para liberar a nuestros hermanos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Cinturón de pelaje rasgadoApisonadoras de fuegoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][13573] = {title = "El retorno de Malfurion", objective = "Busca a Malfurion Tempestira en El Ojo del Vórtice al sureste del Campamento de Refugiados de Costa Oscura.", description = "Fue recientemente cuando escuchamos la noticia del resurgimiento de Malfurion; un momento antes de que tuviera lugar el Cataclismo.\n\nTan pronto como recobró la consciencia, lanzó un misterioso mensaje que afirmaba que la tierra se partirá en dos si no actuamos y que todas las ondas expansivas convergían aquí en Costa Oscura.\n\nEntonces, se nos informó de que se estableció en algún lugar de las inmediaciones. Fui enviado para encontrarlo, pero estoy demasiado ocupado atendiendo a los refugiados.\n\nQuizás podrías ir a buscarlo al sureste por nosotros.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13575] = {title = "La tierra está en su sangre", objective = "Habla con el anciano Zarpamarrón en el Campamento Bosque Negro al suroeste del Ojo del Vórtice.", description = "Si nos proponemos estabilizar las fuerzas de la naturaleza, necesitaremos toda la ayuda posible. Los fúrbolgs de la tribu Bosque Negro han habitado la zona durante mucho tiempo y han establecido fuertes vínculos con la tierra.\n\nEl chamán anciano Zarpamarrón ejerce un gran poder sobre los elementos; su ayuda sería muy valiosa. Averigua si podemos conseguir que se ponga de nuestro lado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13577] = {title = "Los últimos lechúcicos salvajes", objective = "Habla con Aroom en el Cubil Lunadón, al norte de El Ojo del Vórtice.", description = "Los lechúcicos salvajes solían abundar en Costa Oscura. Sus vínculos con la tierra son tan profundos que, el Cataclismo que quebró Costa Oscura, también redujo su número.\n\nEl lechúcico salvaje Aroom es el último de su tribu; un poderoso anciano con una fuerte conexión con Elune. Su ayuda sería imprescindible para sanar la tierra. Lo encontrarás al norte de aquí, en el Cubil Lunadón.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13579] = {title = "El protector de Ameth'Aran", objective = "Habla con Selenn en las Ruinas de Ameth'Aran.", description = "Nada podrá reparar la tierra antes que la fuerza de los que la habitan. Nosotros, los elfos de la noche, tenemos suerte de que algunos de nuestros mejores aliados resultan ser la tierra y sus habitantes al mismo tiempo.\n\nEl anciano de la guerra conocido como Selenn se encargaba de guardar las ruinas de Ameth'Aran, situadas al sur. Ve allí y pídele ayuda.", progress = nil, completion = "Si el gran Malfurion solicita mi presencia, mi deber es atender su llamada. Sin embargo, también debo proteger estas ruinas.\n\n&lt;nombre&gt;, quizás podrías ayudarme a cumplir con ambas obligaciones...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13583] = {title = "El juramento de los lechúcicos salvajes", objective = "Vuelve con Malfurion Tempestira a El Ojo del Vórtice.", description = "Lechúcicos con Elune. Aroom en deuda ahora.\n\nAroom ayudar ahora. Volver con Malfurion, yo unirme pronto.Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nReacción a la fuerza 1\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][13586] = {title = "El Sueño Esmeralda", objective = "Atraviesa el portal pesadilla en la Caverna Rompetierra y habla con Thessera.", description = "Nuestros esfuerzos por evitar la destrucción no parecen ser suficientes. Me temo que necesitaremos ayuda más allá del mundo consciente.\n\nLos cultores Crepusculares de la Caverna Rompetierra del este han abierto un portal a una sección infestada de pesadillas del Sueño Esmeralda. Allí, retienen a una dragona verde prisionera llamada Thessera.\n\nAtraviesa el portal y libérala. Se convertirá en una aliada poderosa.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13587] = {title = "La pesadilla despierta", objective = "Consigue el pergamino esmeralda del guardián pesadilla en la Caverna Rompetierra.", description = "Las palabras de Malfurion son verdaderas, <pequeño/pequeña>. La falla que amenaza con partir en dos Costa Oscura también amenaza con separar este mundo y el tuyo.\n\nDéjame ayudarte en lo que pueda, no vaya a ser que aparezcan más fallas entre los dos mundos que fomenten la destrucción de ambos.\n\nPrimero, debes liberarme de estos grilletes encantados recuperando el pergamino esmeralda del guardián pesadilla que patrulla por los pasillos de abajo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nRegalo de Thessera"}
MultiLanguageQuestData['mx'][13592] = {title = "Instrucción en el campo de un Valeroso", objective = "Sir Marcus Barlowe en los Campos del Torneo Argenta quiere que mates a 10 héroes transformados.", description = "El torneo es el lugar para probar tus habilidades contra tus semejantes, pero no tenemos que olvidarnos de que el enemigo real, la Plaga, no se va a quedar de brazos cruzados. Mientras perfeccionas tus habilidades contra otros, sigue combatiendo al enemigo.\n\nViaja al área que hay al suroeste de El Valle de los Héroes Caídos y al norte de Corp'rethar. Allí, la Plaga resucita héroes muertos y los vuelve en nuestra contra. Derrota a esos esbirros de la Plaga, honra a nuestros aliados y prepárate para el combate.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valeroso"}
MultiLanguageQuestData['mx'][13593] = {title = "Valeroso de Ventormenta", objective = "Habla con el mariscal Jacob Alerius de nuevo si quieres convertirte en <un Valeroso/una Valerosa> de Ventormenta.", description = "Te doy la bienvenida, <Campeón/Campeona>. Han llegado hasta mí las noticias de tu habilidad en combate. ¿Buscas unirte a la delegación de Ventormenta en el torneo?\n\nTe instruirás y avanzarás por las filas como has hecho anteriormente, pero cuando seas <Campeón/Campeona> de Ventormenta, tu escudero podrá optar a llevar nuestro estandarte a la batalla.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13594] = {title = "No te olvides de la Horda", objective = "Mata a 10 miembros de la Horda en las Ruinas de Bathran.", description = "Puede que Evenar y los demás aprendices no sean de mucha utilidad en una batalla, pero parece que tú puedes valer para echar una mano. La escoria de la Horda de la carretera del este que está en las Ruinas de Bathran necesita aprender una lección.\n\nSu nuevo señor de la guerra, Garrosh Grito Infernal, no los lleva por el buen camino. ¿Quieres enseñarles un par de cosas?\n\nIría contigo, pero mi cometido es permanecer aquí y proteger a los aprendices de Orendil y eso es exactamente lo que voy a hacer.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13595] = {title = "De su propio diseño", objective = "Consigue una botella de fuego salvaje y tírala sobre el cadáver de Bathran para quemarlo.", description = "Estas criaturas... los que se hacen llamar Horda... me talaron en mi momento de plenitud y están recolectando mi pelo para sus malvados planes.\n\n¿Me ayudarás a acabar con esto, <pequeño/pequeña> <raza>?\n\nHe oído a sus herboristas hablar de algo llamado fuego salvaje sentados a la mesa en su puesto. Si fueses a buscar ese material antinatural y lo echases sobre mi cadáver, en el noreste, ardería y no crecería más pelo.\n\nYa estoy muerto y es un pequeño precio que debo pagar para detenerlos.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][13596] = {title = "Los planes del Martillo Crepuscular", objective = "Consigue los planes Crepusculares en el Campamento Crepuscular.", description = "No somos plenamente conscientes de lo que traman los cultores Crepusculares del suroeste. Tememos un ataque contra Lor'danel, pero sus intenciones pueden ir aún más allá.\n\nNecesito que vayas al Campamento Crepuscular y que te hagas con sus planes. Aprisa, <nombre>. No tenemos mucho tiempo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13598] = {title = "Remedios indeseables", objective = "Recoge 6 setas humeantes.", description = "No me cabe duda de que Zarpadura se recuperará con la ayuda de mi magia sanadora, aunque no puedo decir lo mismo de los furtivos que lo atacaron. Aun así, podría utilizar un ungüento para cerrar sus heridas y paliar su dolor mientras se cura.\n\nAl este, encontrarás las Ruinas de Lornesta. Entre las piedras que se han desmoronado, existe una variedad de seta humeante que florece en entornos húmedos. Tráeme algunas setas para prepararle un ungüento a nuestro amigo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13600] = {title = "Un arma digna", objective = "Lleva la hoja de Drak'Mar al mariscal Jacob Alerius en los Campos del Torneo Argenta.", description = "¡Maldita sea mi suerte!\n\n¡He perdido la espada del torneo! He oído que los bardos cuentan historias de viajantes que ofrecían jacintos de invierno a una doncella solitaria a cambio de obsequios. Esos jacintos solo crecen en el hielo de la Presa del Muro de Hierro, en el extremo noroeste del Bosque Canto de Cristal que limita con Corona de Hielo. Recoge las flores y llévalas al círculo de luces del Lago Drak'Mar al noreste del Cementerio de Dragones, cerca de Zul'Drak y las Colinas Pardas. Pídele a la doncella solitaria una espada digna.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valerosoObjeto #4"}
MultiLanguageQuestData['mx'][13601] = {title = "Ayudar a los refugiados", objective = "La centinela Lendra de Lor'danel quiere que hables con la sacerdotisa Alinya en el Campo de Refugiados.", description = "¡Por Elune! Parece que muchos de los que temíamos que habían muerto en el ataque a la antigua Auberdine han encontrado refugio en un campamento situado en las afueras de las ruinas de la ciudad.\n\nLos cultores del Campamento Crepuscular estaban planeando borrarlos del mapa de un plumazo. Menos mal que atacaste sus posiciones con éxito.\n\nBusca a la sacerdotisa Alinya en el Campo de Refugiados, al este de la antigua Auberdine y al sur de aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13602] = {title = "Naga de la ensenada", objective = "Mata 15 nagas Colafuria en la Ensenada de Zoram.", description = "El mal acecha desde la costa del oeste.\n\nLa Ensenada de Zoram es el lugar de descanso de la ciudad maldita de Zoram que fue destruida durante la formación de la Brecha y quedó sumergida bajo los mares. Ha estado perdida para los elfos de la noche desde hace mucho. Está perdida y casi olvidada.\n\nAhora, los nagas han regresado sin que conozcamos el motivo. Pero la razón importa poco: ¡debemos acabar con esos demonios y devolverlos a las profundidades!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13603] = {title = "Una espada de Campeón", objective = "Recupera la espada de Lago Fresno y llévasela al mariscal Jacob Alerius en los Campos del Torneo Argenta.", description = "El buen acero afilado y honesto no triunfa. Los demás combatientes usan espadas encantadas y estoy en desventaja, pero aún hay esperanza.\n\nCuenta una antigua leyenda de las Colinas Pardas que hay una doncella bajo el aspecto de una rana que protege la espada que tanto tiempo lleva custodiando. Vive entre las ranas de lago a las orillas del Lago Fresno, al este del Puesto Fresno. Cuentan que solo un beso voluntarioso puede romper la maldición. Ponte este cacao antes de besar nada, <nombre>, si no te saldrán pupas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valeroso"}
MultiLanguageQuestData['mx'][13604] = {title = "Disco de datos de El Archivum", objective = "Lleva el disco de datos de El Archivum a la consola de El Archivum en Ulduar.", description = "El disco de platino es sorprendentemente simétrico y no tiene ni un solo arañazo o imperfección. En el borde hay unas runas grabadas que forman la palabra \"ARCHIVUM\".\n\nDebe de haber un dispositivo en Ulduar capaz de leer el disco.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13605] = {title = "El último refugiado", objective = "Escolta a la arqueóloga Hollee hasta que esté a salvo.", description = "Cuando estalló el terremoto devastador, todo se sumió en la oscuridad. Lo siguiente que recuerdo es que me desperté aquí siendo una prisionera. ¡Los elementales de aire han invadido toda la zona!\n\nEspero que todos estén bien. ¡La escoria del Martillo Crepuscular lamentará haber herido a cualquiera de mis amigos!\n\nAprisa, <clase>, utiliza algo afilado para forzar la cerradura de esta bola y esta cadena. Juntos, deberíamos ser capaces de llegar hasta el Campo de Refugiados.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Peto de arqueólogoCalzones de arqueólogoBastón de excavaciónRecibirás:\n\n"}
MultiLanguageQuestData['mx'][13606] = {title = "El sigilo de Freya", objective = "El prospector Doren en El Archivum de Ulduar quiere que consigas el sigilo de Freya.\n\nSi quieres más información sobre cómo conseguirlo, consulta la consola de El Archivum.", description = "Me parece que el sigilo de Freya va a ser uno de los más difíciles de conseguir.\n\nSegún El Archivum, la esencia del sigilo está vinculada a sus tres ancestros sirvientes: Hojabrillante, Hierrorrama y Cortezapiedra. Si alguno de los ancestros resulta herido la integridad del sigilo se verá en compromiso.\n\nSi no los tocamos, Freya será más poderosa cuando te enfrentes a ella.\n\nEn fin, <nombre>. Estamos entre la espada y la pared.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13609] = {title = "El sigilo de Hodir", objective = "El prospector Doren en El Archivum de Ulduar quiere que consigas el sigilo de Hodir.\n\nSi quieres más información sobre cómo conseguirlo, consulta la consola de El Archivum.", description = "El sigilo de Hodir no será fácil de conseguir. ¡No solo tendrás que derrotar al mismísimo Hodir sino que tendrás que hacerlo antes de que destruya el cofre que lo contiene!\n\nConsulta la consola de El Archivum si necesitas más información. ¡Contiene más sabiduría que todas las bibliotecas del mundo juntas!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13610] = {title = "El sigilo de Thorim", objective = "El prospector Doren en El Archivum de Ulduar quiere que consigas el sigilo de Thorim.\n\nSi quieres más información sobre cómo conseguirlo, consulta la consola de El Archivum.", description = "Thorim no está bien, <nombre>. Ha caído bajo una influencia oscura.\n\nUna presencia maligna se hace pasar por la mujer que perdió, Sif.\n\nNo puedes permitir que el embrujo de esta impostora le subyugue. Si eso ocurre, ¡la ubicación de su sigilo podría perderse para siempre!\n\nVas a tener que hacer que entre en razón y rápido.\n\nComo siempre, la consola de El Archivum te proporcionará toda la información con pelos y señales, la que no te va a gustar también.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13611] = {title = "El sigilo de Mimiron", objective = "El prospector Doren en El Archivum de Ulduar quiere que consigas el sigilo de Mimiron.\n\nSi quieres más información sobre cómo conseguirlo, consulta la consola de El Archivum.", description = "Mimiron es muy inteligente. Su morada está equipada con un mecanismo de autodestrucción.\n\nPor desgracia vas a tener que enfrentarte a él si quieres conseguir su sigilo. Consulta la consola de El Archivum si necesitas más información.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13612] = {title = "La defensa de Mor'shan", objective = "Kadrak en la Empalizada de Mor'shan quiere que mates a 5 hostigadores de Vallefresno y a 5 asaeteadores de Vallefresno.", description = "¡Lok'tar, <raza>!\n\n¡La campaña está por fin en el buen camino! Pronto, todo Vallefresno estará bajo el control de la Horda.\n\nComo esperábamos, nuestra ofensiva fuerza al enemigo a probar nuestras defensas en todas las posiciones.\n\n¡Aquí, en Mor'shan, su asalto ha quedado diezmado! Pero al crecer lo vicioso de la lucha, no tendrán más elección que presionarnos aquí.\n\nExplora la región, <clase>. ¡Busca elfos de la noche supervivientes y acaba con ellos antes de que puedan reagruparse para otro asalto!", progress = nil, completion = "¡Buen trabajo, &lt;clase&gt;!\n\n¡Tus esfuerzos mantendrán al enemigo a raya mientras nuestras fuerzas barren la tierra!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13613] = {title = "Rescatar a los caídos", objective = "Utiliza el ungüento medicado en 5 defensores Mor'shan heridos.", description = "Nuestras fuerzas están resistiendo de forma admirable, <clase>.\n\nPor muchos que sean, sigue habiendo heridos que atender: muchos siguen en el campo de batalla.\n\nHe creado un ungüento que debería permitirnos dar a los heridos fuerzas suficientes para volver a la empalizada y poder tratarlos. Adminístrasela a cualquiera que la necesite antes de que los perdamos.", progress = nil, completion = "Gracias, &lt;raza&gt;. Incluiré tu servicio a la Horda en mi informe.\n\n¡Esos soldados deberían estar en estado de combatir en muy poco tiempo!", rewards = "Leotardos del médico viajanteGuantes de la Media LunaBufas del Primer intervinienteRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][13614] = {title = "Algalon", objective = "Lleva los sigilos de los vigías a la consola de El Archivum en Ulduar.", description = "Lo conseguiste, <nombre>. Lleva los sigilos a la consola de El Archivum y mira si puedes acceder al Planetario Celestial.\n\nMás vale que te des prisa, <chico/chica>. El tiempo es esencial.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nLlave de El Planetario CelestialSaco de botín de Ulduar"}
MultiLanguageQuestData['mx'][13615] = {title = "Carcajes vacíos", objective = "Truun, en la Empalizada de Mor'shan quiere que recojas 10 flechas útiles en la región del Lago Cielo Estrellado.", description = "Saludos, <clase>, <bienvenido/bienvenida> a la empalizada.\n\nLas cosas pueden parecer un poco caóticas, pero no te preocupes. Kadrak mantiene todo en orden. ¡Ni un solo elfo ha traspasado nuestras líneas!\n\nMientras estás aquí... espero un envío de suministros frescos de Orgrimmar en cualquier momento, pero nuestros veladores se están quedando sin flechas preocupantemente.\n\nTráeme las que encuentres y haré que la molestia valga la pena.", progress = "¿Has recogido las flechas que necesitamos, <clase>?", completion = "Bien hecho, &lt;clase&gt;.\n\nEsto debería ayudarnos a tirar adelante hasta que llegue el envío.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13616] = {title = "El Filo del invierno", objective = "El mariscal Jacob Alerius en los Campos del Torneo Argenta quiere que le lleves Filoinvierno.", description = "¡Maldito sea ese caballero de la Muerte por romper mi espada!\n\nAl sur del Bosque Canto de Cristal, vigilando la salida hacia el Vicio de Cristal está Lord Llama Perpetua. Mátalo y toma su ascua de llama perpetua.\n\nLlévala al centro del Lago Aliento Invernal, en la parte norte del Fiordo Aquilonal y úsala para liberar a la doncella encerrada en hielo. Es la guardiana de una espada ancestral y recompensará a su libertad<or/ora>.\n\nDemuestra tu valía y consigue la espada que ha estado custodiando durante tanto tiempo, <nombre>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valerosoObjeto #1"}
MultiLanguageQuestData['mx'][13617] = {title = "Arena a la Ensenada", objective = "Habla con Talen en el Campamento Brazanegra en Vallefresno.", description = "<nombre>, tengo un amigo que podría utilizar bien esos talentos particulares. Su nombre es Talen y es algo parecido a un arqueólogo. Últimamente ha estado fascinado con la agitación de la vieja ciudad de Zoram y sus tesoros.\n\nSi quieres echarle una mano, puedes encontrarle en el Campamento Brazanegra en el camino hacia el oeste.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13618] = {title = "¡Busca a Gorat!", objective = "Kadrak en la Empalizada de Mor'shan quiere que rastrees la región del Lago Cielo Estrellado para buscar a Gorat.", description = "Gorat es uno de los asesinos más expertos de la Horda.\n\nEl mero hecho de mencionar su nombre, infunde miedo en los corazones de nuestros enemigos de la Alianza.\n\nEs fiable, terriblemente leal y, hasta ahora, puntual.\n\nAlgo no va bien, <clase>.\n\nLa misión de Gorat consistía en encontrar y eliminar al elfo a cargo de este asalto a la empalizada.\n\nDebería encontrarse en alguna parte de la región del Lago Cielo Estrellado.\n\n¡Encuéntralo!", progress = nil, completion = "Escucha con atención, &lt;raza&gt;...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13619] = {title = "El último informe", objective = "Gorat quiere que lleves el Vial de sangre de Gorat a Kadrak en la Empalizada de Mor'shan.", description = "<Gorat tose profundamente mientras se esfuerza para hablar.>\n\nFue... una emboscada...\n\nEstábamos... volviendo a la empalizada. Todos... perdidos...\n\nNosotros... descubrimos a su líder... \n\n<Gorat rellena con esfuerzo un vial con la sangre que brota de una de sus heridas.>\n\nMis hombres... debemos vengarlos... Llévale esto... a Kadrak...\n\nÉl sabrá lo que hacer...\n\n<Gorat expira.>", progress = "¿Encontraste a Gorat, <clase>?", completion = "&lt;Kadrak escucha atentamente mientras relatas las últimas palabras de Gorat.&gt;\n\nEs lo que me temía, entonces. Que descanse en paz... ¡pero no todavía!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13620] = {title = "¡A Dinah, a la una!", objective = "Kadrak quiere que lleves el Vial de sangre de Gorat a Dinah en la Empalizada de Mor'shan.", description = "Puede que la Horda no haya conocido a nadie más leal que Gorat. Nunca ha dejado de completar una misión y parece que se resiste a que esta sea la primera.\n\nGorat te mandó entregar este vial con un objetivo. Dinah es la hija de un chamán venerado, y es más poderosa de lo que parece. Llévale el vial y esperemos que no sea demasiado tarde.", progress = "¿Qué tienes ahí, <raza>?", completion = "Déjame echar un vistazo, &lt;clase&gt;.", rewards = "Te van a lanzar el siguiente hechizo:\n\nDinah Dummy Spell\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][13621] = {title = "La venganza de Gorat", objective = "Utiliza la sangre imbuida de Gorat sobre el cadáver de Gorat y derrota al capitán Elendilad.", description = "Hoy nos acompaña la fortuna, <raza>.\n\nLa sangre de Gorat era suficientemente fresca para que pudiese llevar a cabo un ritual que me enseñaron de niña.\n\nUtiliza esta sangre imbuida sobre el cadáver de Gorat para invocar allí su espíritu persistente.\n\nHaz lo que te pida y vuelve para informar a Kadrak.\n\nQue los espíritus te protejan, colega.", progress = nil, completion = "Bien hecho, &lt;raza&gt;.\n\nEl capitán elfo está muerto y el alma de uno de nuestros queridos hermanos puede descansar en paz.\n\nHablaré de tus logros a mis superiores en Orgrimmar.", rewards = "Legado de GoratPechera de KadrakRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][13622] = {title = "Historia antigua", objective = "Lleva los fragmentos rotos de Val'anyr a la consola de El Archivum en El Archivum de Ulduar.", description = "Los trozos encajan y forman un martillo elegante. Su construcción parece ser al menos parcialmente de naturaleza titánica.\n\nQuizás haya información sobre este artefacto en la consola de El Archivum.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][13623] = {title = "Un envío para Orendil", objective = "Lleva la bolsa de cabello de Bathran a Orendil Hojagrande en la Atalaya de Maestra, Vallefresno.", description = "Rápido, <nombre>. Meteré el cabello de Bathran en esta bolsa, pero deberás llevárselo a mi maestro, Orendil Hojagrande. Lo encontrarás en la Atalaya de Maestra, al sur por la carretera de la izquierda\n\nPero cuidado, ¡hemos recibido informes de que la atalaya está siendo atacada por la Horda!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13624] = {title = "Tu propio escuadrón", objective = "Utiliza un escuadrón de centinelas de la Atalaya de Maestra para destruir 3 asoladores de Vallefresno y asesinar a 10 invasores de la Horda.", description = "De verdad espero que estés aquí para ayudar, <clase>. La situación es tan terrible como aparenta. Simplemente, ¡estamos perdiendo!\n\nMis chicas y yo somos la última línea de defensa contra la Horda, pero no vamos a salir de aquí sin pelear contra ellos. ¿Te apetece un desafío?\n\nTengo un pequeño escuadrón de centinelas que te puedo prestar. Acércalos y estoy seguro de que sus flechas mágicas podrán destruir esos asoladores e invasores.\n\nVuelve a hablar conmigo si necesitas reemplazos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13625] = {title = "Aprende a llevar las riendas", objective = "Golpea a un objetivo cuerpo a cuerpo con Estocada 5 veces, usa Romper escudo sobre 2 objetivos a distancia vulnerables, usa Cargar sobre 2 objetivos de carga vulnerables y luego vuelve a ver a la exploradora Shalyndria en los Campos del Torneo Argenta.\n\nSi pierdes tu lanza, puedes coger otra de cualquier expositor de lanzas que hay cerca de los establos o en el Pabellón de El Pacto de Plata.", description = "En la mayoría de las competiciones del torneo es indispensable que domines una montura en combate. Pusimos muñecos de entrenamiento en la parte norte de los Campos del Torneo para que te acostumbres al combate sobre montura.\n\nVe a los establos que hay fuera del pabellón, equipa tu lanza y monta sobre un corcel Quel'dorei. Familiarízate con las tácticas que tienes y úsalas para derrotar a los tres tipos de muñecos de entrenamiento.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de AspiranteObjeto #1"}
MultiLanguageQuestData['mx'][13626] = {title = "Respeto a los caídos", objective = "Recupera el martillo sagrado de Feero y el libro de oración del Purificador.", description = "Aquí estuvieron dos humanos: Feero Ferramán y Delgren el Purificador. Eran miembros de una organización sagrada conocida como El Alba Argenta. Ambos cayeron defendiendo la atalaya frente al primer ataque de la Horda.\n\nTe voy a prestar mi capa mágica. Fue un regalo de Cenarius que me permite moverme a la vez que soy invisible.\n\nEncuentra los dos cadáveres y recupera el martillo de Feero y el libro de oración de Delgren. El cadáver de Feero está en el patio y el de Delgren en la parte superior de la torre.\n\nCuidado, el brujo que está allí arriba te verá.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Leotardos de DelgrenGuantes de OnaeyaEspaldares de FeeroRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][13627] = {title = "Agénciame unos maderos", objective = "Llévale 12 tablones sin rematar a Bezzle Cargarrayo en los Campos del Torneo Argenta.", description = "Acércate. No, no tanto. No hay necesidad de levantar sospechas, ¿verdad?\n\nLas reservas que tenemos no son suficientes para el coliseo y no pienso pagar para que me manden nada de las Colinas Pardas. En el extremo oeste del Bosque Canto de Cristal, por El Gran Árbol, hay varios robles Canto de Cristal jóvenes. De ellos se saca el tipo de tablón que nos hace falta para la construcción y el andamiaje. Coge esta hacha para talar los árboles y cortar los tablones. ¡Que no te vea nadie!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][13628] = {title = "¿Tienes madera?", objective = "Truun quiere que montes a Brutusk hasta el Campo de trabajos forzados Grito de Guerra.\n\nHabla con Kadrak para obtener las riendas de Kadrak para montar a Brutusk.", description = "Kadrak acaba de recibir órdenes frescas para nuestras tropas. ¡He oído que vamos a iniciar ofensivas en Vallefresno!\n\nPor desgracia no tengo suministros suficientes como para llevar a cabo un asalto, y mi envío de Orgrimmar aún no ha llegado.\n\nMe veo obligado a improvisar... Y tú podrías serme útil, <clase>.\n\nHabla con Kadrak y pídele las riendas de Brutusk. El kodo te llevará al Campo de trabajos forzados Grito de Guerra. Una vez allí, busca a Gorka y pídele que cargue al kodo con troncos para mí.", progress = nil, completion = "Bienvenido, &lt;clase&gt;. Me alegro de ver que la carretera a la Empalizada de Mor'shan sigue limpia.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13630] = {title = "El porqué", objective = "Desactiva las piedras lunares azul, verde y roja.", description = "Los fúrbolg han bajado desde la parte alta y han arrasado las Ruinas de Ordil'Aran del norte. Creo que lo hicieron porque se sentían atraídos por lo que allí descubrieron los cultores muertos: tres piedras lunares.\n\nLiladris Rioluna te aconsejará que te ocupes de los fúrbolg de una forma más directa y no la voy a contradecir, pero te pediría que fueses a las ruinas y desactivases las piedras lunares.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13631] = {title = "Bien está lo que bien acaba", objective = "Lleva el código de respuesta Alfa a Rhonin en Dalaran.", description = "Será mejor que nos demos prisa, <nombre>. Vamos a tener que transmitir el código de respuesta desde Dalaran.\n\nLlévaselo a Rhonin, nos veremos allí.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Mantón del heraldo del cieloMantón de rayo tenue de solPodrás elegir una de estas recompensas:\n\nEstampa de BrannSello de brillo estelar\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][13632] = {title = "Turno de retaguardia", objective = "Mata a 10 fúrbolgs cualesquiera en las Ruinas de Ordil'Aran.", description = "La sacerdotisa lunar tiene un plan para asegurarnos de que no desciendan más fúrbolgs de las tierras altas. A mí me preocupan los que ya están en las ruinas; algunos se están agrupando a las puertas de la atalaya.\n\nPor muy desagradable que sea, he de pedirte que te dirijas al norte, a las Ruinas de Ordil'Aran, y acabes con los fúrbolgs. ¡No podemos luchar en dos frentes!\n\nGracias, <clase>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13633] = {title = "¿El Caballero Negro de los Páramos de Poniente?", objective = "Investiga la afirmación del Caballero Negro y vuelve a ver a la cruzada Rhydalla en los Campos del Torneo Argenta con lo que hayas descubierto.", description = "Sin duda habrás oído los inquietantes rumores sobre el contendiente al que los demás llaman el Caballero Negro. Se dice que todo jinete que tuviera previsto enfrentarse a él en combate ha conocido un fin prematuro.\n\nEso sí, no tenemos pruebas que lo inculpen de nada, pero no haría daño a nadie estudiar el pasado de este caballero.\n\nAfirma ser descendiente de la familia Cooper de los Páramos de Poniente. Hazle una visita a su casa en la parte oeste de Arroyo de la Luna. Mira a ver si puedes encontrar algo que pruebe su historia.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13634] = {title = "¿El Caballero Negro del Bosque de Argénteos?", objective = "Investiga la afirmación del Caballero Negro y vuelve a ver a la cruzada Rhydalla en los Campos del Torneo Argenta con lo que hayas descubierto.", description = "Sin duda habrás oído los inquietantes rumores sobre el contendiente al que los demás llaman el Caballero Negro. Se dice que todo jinete que tuviera previsto enfrentarse a él en combate ha conocido un fin prematuro.\n\nEso sí, no tenemos pruebas que lo inculpen de nada, pero no haría daño a nadie estudiar el pasado de este caballero.\n\nAfirma ser natural del Campo de Valgan en el Bosque de Argénteos. Se trata de una pequeña granja en la orilla oeste del Lago Lordamere. Hazle una visita a la granja y dime si hay algo de verdad en su historia.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13636] = {title = "Órdenes Pico Tormenta", objective = "Entrega las órdenes de Pico Tormenta al Montaraz Pico Tormenta en la Estación de Algaz.", description = "Necesito llevar unas órdenes al Montaraz Pico Tormenta en su puesto de la Estación de Algaz. Si no te importa llevarlas, sigue la carretera hacia el noroeste y no tendrás problemas para encontrar el búnker principal.\n\nSi también nos echas una mano con esas tareas, estaremos encantados de recompensarte por ello.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13637] = {title = "Ram Delivery", objective = "The mountaineers at South Gate Outpost have requested a delivery of rams for their patrols. I didn't think we'd be able to spare any, but we can get them at least one thanks to you.\n\nMind riding it over and delivering it to Private Hammerfall for me? Just let me know when you're ready to go.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", description = "The mountaineers at South Gate Outpost have requested a delivery of rams for their patrols. I didn't think we'd be able to spare any, but we can get them at least one thanks to you.\n\nMind riding it over and delivering it to Private Hammerfall for me? Just let me know when you're ready to go.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13638] = {title = "El montaraz capturado", objective = "El Capitán Regulfuss de Thelsamar quiere que localices al Montaraz Gravelgau.Has demostrado ser más que capaz para la pelea. Ahora tengo que pedirte algo con un poco más de presión.\n\nUno de mis hombres, el Montaraz Gravagau, fue capturado por los troggs contra los que hemos estado luchando en las montañas del sur. Bueno, en realidad se entregó por voluntad propia en vez de ser capturado, pero el resultado final es el mismo. Creo que tenía la esperanza de identificar a su líder desde el interior.\n\nNecesito que vayas a sacarlo. Probablemente lo tengan preso en una de las cuevas superiores, en las profundidades de las montañas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", description = "Has demostrado ser más que capaz para la pelea. Ahora tengo que pedirte algo con un poco más de presión.\n\nUno de mis hombres, el Montaraz Gravagau, fue capturado por los troggs contra los que hemos estado luchando en las montañas del sur. Bueno, en realidad se entregó por voluntad propia en vez de ser capturado, pero el resultado final es el mismo. Creo que tenía la esperanza de identificar a su líder desde el interior.\n\nNecesito que vayas a sacarlo. Probablemente lo tengan preso en una de las cuevas superiores, en las profundidades de las montañas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13639] = {title = "Aprovisionar la excavación", objective = "Localiza a Huldar, a Miran y a Saean.", description = "Vetaferro tiene una excavación al sureste y necesita grandes cantidades de explosivos de la Liga para la extracción. Huldar, Miran y Saean acaban de salir con el último cargamento y seguro que les va bien un poco de ayuda.\n\nNo deben de haber llegado muy lejos todavía, por muy fuertes que sean. No pueden avanzar demasiado rápido cargados con esos barriles.\n\nHan tomado el camino habitual a la excavación: salir por la parte sur de la ciudad y seguir la curva del lago. Ve a su encuentro y ayúdales, ¿quieres?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13640] = {title = "Material de gestión", objective = "Convence a los peones desmoralizados para que trabajen y recojan 5 fardos de madera recién cortada.", description = "Así que Truun necesita madera, ¿eh? Normalmente podría darte, pero no hoy.\n\nCon ataques constantes de los elfos, recoger madera es un trabajo peligroso. Los peones que me quedan no están muy convencidos de aventurarse al bosque.\n\n¿Quieres madera? Pues ve a convencer a los peones de que trabajen.\n\n¡Y protégelos! ¡No puedo permitirme perder ninguno más!", progress = "¿Conseguiste la madera que necesitas?", completion = "Bueno, &lt;clase&gt;, parece que has solucionado un problema para pasar a otro peor...", rewards = "Ropaje de campo de trabajos forzadosManto de GerenteManos de ÁnimoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][13641] = {title = "El cristal de vidente", objective = "Llévale un cristal de vidente a la cruzada Rhydalla en los Campos del Torneo Argenta.", description = "Ahora que sabemos que todas las historias del Caballero Negro son mentira, hay que encontrar la manera de vincularlo a los caballeros asesinados.\n\nSé cómo descubrir la verdadera causa de su muerte, pero necesito un material raro. Tenemos que conseguir un cristal de vidente, se encuentra solo entre los sátiros que se congregan cerca de las ruinas de los elfos de la noche en el Bosque Desolado y en el área central del Bosque Canto de Cristal. Encuentra a uno de esos videntes, <nombre>, y tráeme el cristal que posee.", progress = "¿Has localizado un cristal de vidente?", completion = "Este nos vendrá muy bien. Solo nos queda imbuirlo con el poder de la Luz para darle la capacidad de discernir la verdad de la mentira.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13642] = {title = "Bañado en luz", objective = "Crea un brebaje sumergido.", description = "El brebaje aún no está listo; debemos bañarlo dentro de la Luz de Elune antes de que ni pensemos en dárselo a los niños.\n\nHay una ubicación conocida justo al oeste del Lago Falathim, donde siempre cae la luz de luna de la diosa, ya sea de día o de noche. Por favor, <nombre>, te suplico en nombre de Relara, lleva el brebaje y báñalo en la radiancia de Elune.\n\nPero cuidado, cosas extrañas acontecen en la zona del lago y temo que ya no sea seguro ir allí.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][13643] = {title = "Historias que cuentan los muertos", objective = "Usa el cristal de vidente en las tumbas de Sir Wendell Balfour, Lorien Resplandor y Conall Empuñadura de Hierro para determinar la causa de su muerte, luego vuelve a ver a la cruzada Rhydalla.", description = "El cristal revelará la verdad sobre el origen de la muerte de tres de los combatientes del torneo. Llévatelo al cementerio que hay al este de los Campos del Torneo y úsalo ante las tumbas de Sir Wendell Balfour, Lorien Resplandor y Conall Empuñadura de Hierro.\n\nSi han sido asesinados, hay que encontrar la manera de relacionarlo con el Caballero Negro antes de que actúe de nuevo. Mira bien lo que te dice el cristal, <nombre>, tenemos que tener la certeza de que esas muertes no fueron fortuitas.", progress = nil, completion = "¿Así que dices que Lorien Resplandor fue envenenado y que quemaron vivo a Sir Wendell? Qué maneras tan terribles de morir. Solo Conall murió por el frío acero, y según tu descripción, fue un golpe cobarde e indigno el que le mandó a la tumba.\n\nLos tres entrenaban juntos y tenían que luchar contra el Caballero Negro. No puede ser una mera coincidencia. Tenemos que probar que fue obra del Caballero Negro.", rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][13644] = {title = "Los que se han levantado", objective = "Mata al presagista Aphotic.", description = "Cuando sentía como estas... cosas... se levantaban desde el suelo, vine para devolverlas a su agujero. Encontré el cadáver de tu amigo y lo arrastré todo lo lejos que pude hasta que se rompió uno de mis huesos del pie. Es lo único que puedo hacer para mantener alejados esos zarcillos repugnantes.\n\nHay uno que controla los zarcillos y los ojos. Se hace llamar presagista Aphotic; estoy seguro de que lo habrás escuchado gritar desde el sur.\n\nEl presagista queda fuera del alcance de mi magia, pero tú podrías llegar hasta él. Si te atreves...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Zapatillas de abluciónBotines dolorososFavor Corazón SabioRecibirás:\n\n"}
MultiLanguageQuestData['mx'][13645] = {title = "A Raene Correlobo", objective = "Lleva la gema resplandeciente a Raene Correlobo en Astranaar, Vallefresno.", description = "Me gustaría que llevases la gema directamente a Raene Correlobo. Por lo último que sé, aún estaba en Astranaar, al sureste.\n\nAl menos el camino entre aquí y allí sigue siendo relativamente seguro, así que sería una simple cuestión de seguirlo hasta allí. Claro, si quieres, creo que la centinela Avana estaría encantada de prestarte uno de sus sables de la noche para que el viaje sea más presto.\n\nElijas lo que elijas, buena suerte, <nombre>. Espero que nos volvamos a encontrar pronto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13646] = {title = "Ligado a Astranaar", objective = "Habla con la centinela Luara en Astranaar en Vallefresno.", description = "Nos has sido de gran ayuda, <nombre>. Sin tu ayuda, ya nos habrían borrado del mapa.\n\nPara mí será un placer ofrecerte uno de mis sables de la noche siempre que quiera ir hasta Astranaar y hacia el sureste. No me cabe duda de que tienes asuntos de la mayor importancia que atender allí.\n\nSería un gesto muy amable por tu parte si, una vez allí, fueses a ver a mi hermana, la centinela Luara, y le dijeses que estoy bien.\n\nHabla conmigo cuando estés <listo/lista> para partir. Y recuerda que siempre que lo necesites, el sable está a tu disposición.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13647] = {title = "Únete a la cacería", objective = "Habla con Marek Coracero en la Cabaña de los Errantes.", description = "No hay duda de que llevas la lucha dentro de ti.\n\n¿Sabes? Hay algunos cazadores en la cabaña que hay al este de aquí, en lo alto de las montañas, que encajarían contigo. ¿Por qué no vas a visitarlos y de paso ves si tienen algo de trabajo que te pueda interesar?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13648] = {title = "SE BUSCA: El espía Hierro Negro", objective = "Mata a Gorick Agriojarabe.", description = "Un espía Hierro Negro se ha infiltrado en la ciudad, ha robado unos documentos del establecimiento de la Liga de Expedicionarios y ahora se esconde en algún lugar de las proximidades. La última vez fue visto en la cima de la colina del sur de la ciudad.\n\nUna recompensa considerable espera al que pueda entregar al espía a la justicia. Vivo o muerto, preferiblemente muerto.", progress = nil, completion = "¡Has entregado a ese maldito espía a la justicia! Buenas noticias. Ahora todos podremos descansar mejor, sin preocuparnos por ese sujeto.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13649] = {title = "Justin's Fun Test", objective = "Utiliza la jarra de degustación de la Fiesta de la cerveza de obsequio para golpear a la G.U.A.O. 5 veces, y luego ve a hablar con Boxey Bolahuso.", description = "Hey there!  You look like you can handle your brew.  But can you handle your brew mug? \n\nThe Dark Irons have come back with a vengeance to ruin our celebration.  Tossing mugs at them is the best way to stop them, but first, let's see if you can toss one at old S.T.O.U.T. here.\n\nIt's easy, pick up a complimentary sampler and take a drink.  Just make sure you're facing S.T.O.U.T.  Talk to me after you've hit him 5 times.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][13651] = {title = "Les falta aceite", objective = "Gorka, en el Campo de trabajos forzados Grito de Guerra, quiere que recojas 5 aceites naturales de las babosas en podredumbre de Vallefresno.", description = "Tienes la madera, pero los elfos invasores han hecho imposible que tu kodo pueda volver a la Empalizada de Mor'shan.\n\nHe enviado un corredor a El Hachazo para pedir ayuda. No debería pasar mucho tiempo hasta que sus fuerzas despejen el camino.\n\nMientras, voy a pedirte que nos hagas un favor. El óxido ha estropeado nuestras trituradoras. Un poco de lubricación y estarán como nuevas.\n\nEl aceite de las babosas en podredumbre que hay al norte de aquí debería funcionar a la perfección.", progress = "<clase>, ¿pudiste recoger todo el aceite que necesitamos?", completion = "Gracias por el aceite, &lt;clase&gt;. ¡Ahora prepárate!\n\nMi corredor ha vuelto con noticias desesperadas...\n\n¡El Hachazo está rodeado!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13652] = {title = "Defensa de la Presa de las Tres Cabezas", objective = "Busca al ingeniero jefe Hinderweir VII en la Presa de las Tres Cabezas.Te agradecemos tu ayuda. Con un poco de tiempo, recuperaremos el control de la excavación. Yo me conformo con saber que en el proceso de esta ocupación no se ha destruido todo nuestro trabajo.\n\nYa hemos abusado bastante de tu tiempo. Tengo un amigo al realmente le vendría muy bien tu ayuda, si estás <dispuesto/dispuesta> a ofrecérsela. Ve a la parte más alejada de Loch Modan y encontrarás la Presa de las Tres Cabezas. Una vez allí, busca al ingeniero jefe Hinderweir VII.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", description = "Te agradecemos tu ayuda. Con un poco de tiempo, recuperaremos el control de la excavación. Yo me conformo con saber que en el proceso de esta ocupación no se ha destruido todo nuestro trabajo.\n\nYa hemos abusado bastante de tu tiempo. Tengo un amigo al realmente le vendría muy bien tu ayuda, si estás <dispuesto/dispuesta> a ofrecérsela. Ve a la parte más alejada de Loch Modan y encontrarás la Presa de las Tres Cabezas. Una vez allí, busca al ingeniero jefe Hinderweir VII.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13653] = {title = "Crisis en El Hachazo", objective = "Gorka quiere que la acompañes hasta la Empalizada de Mor'shan a informar a Kadrak.\n\nHabla con ella cuando estés <listo/lista> para partir.", description = "No vendrá ayuda de El Hachazo.\n\n¡Los elfos han lanzado un gran ataque contra nuestro bastión allí y tienen el lugar rodeado!\n\n¡Debemos informar a Kadrak o morir en el intento!\n\nHemos cargado tu kodo con la madera que has recogido. Avísame cuando estés <listo/lista> y cargaremos contra las líneas enemigas.", progress = nil, completion = "Gorka...\n\nSiempre debemos estar preparados para la pérdida. Su servicio honorable a la Horda no se olvidará.\n\n¡Y su sacrificio no será en vano!", rewards = "Estola de dolienteLeotardos de pérdidaCarga de sacrificioRecibirás:\n\n"}
MultiLanguageQuestData['mx'][13654] = {title = "Algo pasa con el escudero", objective = "Consigue un fémur grande de un cortador de leña esquelético y úsalo para incapacitar a Maloric. Registra a Maloric en busca de pruebas, luego preséntate ante la cruzada Rhydalla en los Campos del Torneo Argenta.", description = "Todos los días, el escudero del Caballero Negro, Maloric, monta un espectáculo al dirigirse al Bosque Canto de Cristal con el hacha al hombro. Supongo que quiere que nos creamos que va a cortar madera, pero siempre vuelve con solo unas ramas.\n\nNormalmente va hacia las ruinas al suroeste de El Espejo del Crepúsculo. Pasa mucho tiempo allí, incluso para un escudero con muchas responsabilidades para con su caballero.\n\nEncuentra la manera de distraerle o incapacitarle y regístrale. Si trama algo, lo averiguaremos.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][13655] = {title = "Documento de la Liga de Expedicionarios (2 de 6)", objective = "Devuelve el documento de la Liga de Expedicionarios a Torren Mandicuadrada en Thelsamar.", description = "El documento lleva el blasón de la Liga de Expedicionarios y parece detallar excavaciones potenciales de Loch Modan. Viejos borrones te llevan a creer que es probable que lo robasen los espías Hierro Negro de la zona.\n\nRecuerdas que se habían mencionado unos documentos perdidos en el edificio de la Liga de Expedicionarios de Thelsamar.", progress = nil, completion = "Vaya, ¡has encontrado uno de nuestros documentos robados!\n\nTe estamos muy agradecidos por devolverlo. ¿Satisfará un poco de oro tus honorarios como recompensa por el hallazgo?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13656] = {title = "Documento de la Liga de Expedicionarios (1 de 6)", objective = "Devuelve el documento de la Liga de Expedicionarios a Torren Mandicuadrada en Thelsamar.", description = "El documento lleva el blasón de la Liga de Expedicionarios y contiene una amplia información sobre las criaturas indígenas de Loch Modan. Viejos borrones te llevan a creer que es probable que lo robasen los espías Hierro Negro de la zona.\n\nRecuerdas que se habían mencionado unos documentos perdidos en el edificio de la Liga de Expedicionarios de Thelsamar.", progress = nil, completion = "¡Hola, chico! Parece que has encontrado uno de nuestros documentos robados, ¿eh?\n\nGracias de corazón por devolvérnoslo. Te daremos con gusto unas monedas a cambio.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13657] = {title = "Documento de la Liga de Expedicionarios (3 de 6)", objective = "Devuelve el documento de la Liga de Expedicionarios a Torren Mandicuadrada en Thelsamar.", description = "El documento lleva el blasón de la Liga de Expedicionarios y contiene registros históricos sobre todas las ubicaciones destacables de Loch Modan. Viejos borrones te llevan a creer que es probable que lo robasen los espías Hierro Negro de la zona.\n\nRecuerdas que se habían mencionado unos documentos perdidos en el edificio de la Liga de Expedicionarios de Thelsamar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13658] = {title = "Documento de la Liga de Expedicionarios (4 de 6)", objective = "Devuelve el documento de la Liga de Expedicionarios a Torren Mandicuadrada en Thelsamar.", description = "El documento lleva el blasón de la Liga de Expedicionarios y parece detallar rutas de transporte utilizadas por la liga para entrar y salir de Loch Modan. Viejos borrones te llevan a creer que es probable que lo robasen los espías Hierro Negro de la zona.\n\nRecuerdas que se habían mencionado unos documentos perdidos en el edificio de la Liga de Expedicionarios de Thelsamar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13659] = {title = "Documento de la Liga de Expedicionarios (6 de 6)", objective = "Devuelve el documento de la Liga de Expedicionarios a Torren Mandicuadrada en Thelsamar.", description = "El documento lleva el blasón de la Liga de Expedicionarios y contiene evaluaciones detalladas sobre las varias amenazas de Loch Modan. Viejos borrones te llevan a creer que es probable que lo robasen los espías Hierro Negro de la zona.\n\nRecuerdas que se habían mencionado unos documentos perdidos en el edificio de la Liga de Expedicionarios de Thelsamar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13660] = {title = "Documento de la Liga de Expedicionarios (5 de 6)", objective = "Devuelve el documento de la Liga de Expedicionarios a Torren Mandicuadrada en Thelsamar.", description = "El documento lleva el blasón de la Liga de Expedicionarios y contiene una lista detallada de los artefactos excavados por los obreros de Vetaferro en el sureste de Loch Modan. Viejos borrones te llevan a creer que es probable que lo robasen los espías Hierro Negro de la zona.\n\nRecuerdas que se habían mencionado unos documentos perdidos en el edificio de la Liga de Expedicionarios de Thelsamar.", progress = nil, completion = "¡Nuestros registros de artefactos! Tenía bastante miedo de que los Hierro Negro pudiesen intentar robar al contar con esta información.\n\nGracias por devolvernos el documento. Te haremos entrega de unas monedas gustosamente para expresar nuestra gratitud.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13661] = {title = "Aprecio de corazón", objective = nil, description = "¡Has localizado todos los documentos! Nunca podremos agradecértelo lo suficiente... todos habíamos perdido la esperanza. Parecía seguro que los Hierro Negro podrían atacar pronto gracias a toda esta información. Me alegra saber que quedarán en blanco para los ataques durante un tiempo.\n\nComo agradecimiento a todos tus esfuerzos en nuestro nombre, nos gustaría darte un regalo. En realidad, un artefacto... algo que recuperamos en una de nuestras excavaciones. Cuentas con el aprecio de todas la Liga de Expedicionarios.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "DisparaestrellasCoraza descubiertaMartillo enano viejoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][13662] = {title = "Conseguir aceptación", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][13663] = {title = "Las órdenes del Caballero Negro", objective = "Usa la brida encantada para controlar al grifo del Caballero Negro y que te lleve a su destino. Cuando llegues, coge la invitación para el torneo robada y las órdenes del Caballero Negro y llévaselas a la cruzada Rhydalla en los Campos del Torneo Argenta.", description = "Tenemos que descubrir quién envió al Caballero Negro al torneo y qué quiere conseguir matando a los competidores.\n\nEl Kirin Tor nos ha ofrecido su ayuda con este asunto y nos ha proporcionado algo que nos ayudará en nuestra búsqueda.\n\nLleva esta brida encantada al campamento del Caballero Negro, en el extremo oriental de los campos de torneo, y úsala para controlar al grifo del Caballero Negro. El encantamiento de la brida obligará al grifo a llevarte hasta el hogar de su maestro. Rebusca y trae cualquier cosa que encuentres.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][13664] = {title = "La caída del Caballero Negro", objective = "Derrota al Caballero Negro y luego habla con la cruzada Rhydalla en los Campos del Torneo Argenta.", description = "Tenemos que acabar con la conspiración del Caballero Negro y demostrarles a los que se enfrentan a nosotros que no permitiremos que asesinen a nuestros campeones.\n\nTienes que retar al Caballero Negro y vencerle en combate, <nombre>.\n\nUsa mi destrero Argenta para la batalla. Está en los establos.\n\nHabla con el escudero Cavin en La Liza de los Campeones. El escudero llamará a armas al Caballero Negro, pero tú harás que responda de sus crímenes.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][13665] = {title = "El gran combate cuerpo a cuerpo", objective = "Llévale 3 marcas del Valeroso al capitán Joseph Holley en los Campos del Torneo Argenta.\n\nSi pierdes tu lanza, puedes coger otra de cualquier expositor de lanzas que hay cerca de los establos o en el Pabellón de El Pacto de Plata.", description = "El gran combate cuerpo a cuerpo es la competición más importante del torneo. El pueblo de Ventormenta adora a sus caballeros y espera verlos alzarse con la victoria. A tal fin, han perfeccionado sus habilidades contra otros valerosos.\n\nSugiero que hagas lo mismo.\n\nVe a los establos que hay fuera del pabellón, equipa tu lanza, monta el corcel de Elwynn y desafía a los valerosos. Aguardan en La Liza de los Valerosos de la Alianza que hay justo al salir de nuestra tienda.\nTe van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nQuitar lanza\n\nRecibirás:\n\nSello de valerosoObjeto #1"}
MultiLanguageQuestData['mx'][13666] = {title = "Una espada de Campeón", objective = "Recupera la espada de Lago Fresno y llévasela al arcanista Taelis en los Campos del Torneo Argenta.", description = "Algunos campeones creen que un arma antigua originaria de Rasganorte les dará suerte en el torneo. He accedido a ayudarles a buscar esa arma.\n\nCuenta una antigua leyenda de las Colinas Pardas que hay una doncella bajo el aspecto de una rana que protege la espada que tanto tiempo lleva custodiando. Vive entre las ranas de lago a las orillas del Lago Fresno, al este del Puesto Fresno. Cuentan que solo un beso voluntarioso puede romper la maldición. Ponte este cacao antes de besar nada, <nombre>, si no te saldrán pupas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de AspiranteObjeto #1"}
MultiLanguageQuestData['mx'][13667] = {title = "El Torneo Argenta", objective = "Habla con el arcanista Taelis en los Campos del Torneo Argenta para inscribirte en el torneo.", description = "Te hemos invitado aquí para poner a prueba tu habilidad y tu valor frente a otros que se han enfrentado valientemente a la Plaga. Muchas cosas nos han dividido, pero ha llegado el momento de que los héroes que luchan bajo todos los estandartes pongan a prueba sus filos, unos contra otros, para preparase para enfrentarse a un enemigo mutuo.\n\nEl arcanista Taelis es el representante de El Pacto de Plata en el torneo, y registrará tu nombre e iniciará tu entrenamiento. Búscalo en la gran tienda de la Alianza, en la parte nordeste de los campos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13668] = {title = "El Torneo Argenta", objective = "Habla con el magister Edien Vacuosol en los Campos del Torneo Argenta para inscribirte en el torneo.", description = "Te hemos invitado aquí para poner a prueba tu habilidad y tu valor frente a otros que se han enfrentado valientemente a la Plaga. Muchas cosas nos han dividido, pero ha llegado el momento de que los héroes que luchan bajo todos los estandartes pongan a prueba sus filos, unos contra otros, para preparase para enfrentarse a un enemigo mutuo.\n\nEl magister Edien Vacuosol es el representante Atracasol en el torneo, y registrará tu nombre e iniciará tu entrenamiento. Búscalo en la gran tienda de la Horda, en la parte sureste de los campos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13669] = {title = "Un arma digna", objective = "Llévale la hoja de Drak'Mar al arcanista Taelis en los Campos del Torneo Argenta.", description = "Nuestros campeones se han aficionado a las armas antiguas que se fabricaron aquí en Rasganorte.\n\nHe oído que los bardos cuentan historias de viajantes que ofrecían jacintos de invierno a una doncella solitaria a cambio de obsequios. Esos jacintos solo crecen en el hielo de la Presa del Muro de Hierro, en el extremo noroeste del Bosque Canto de Cristal que limita con Corona de Hielo. Recoge las flores y llévalas al círculo de luces del Lago Drak'Mar al noreste del Cementerio de Dragones, cerca de Zul'Drak y las Colinas Pardas. Pídele a la doncella solitaria una espada digna.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de AspiranteObjeto #4"}
MultiLanguageQuestData['mx'][13670] = {title = "El Filo del invierno", objective = "El arcanista Taelis en los Campos del Torneo Argenta quiere que le lleves Filoinvierno.", description = "El escudero del Gran Campeón de Forjaz me contó una historia intrigante.\n\nAl sur del Bosque Canto de Cristal, vigilando la salida hacia el Vicio de Cristal está Lord Llama Perpetua. Mátalo y toma su ascua de llama perpetua.\n\nLlévala al centro del Lago Aliento Invernal, en la parte norte del Fiordo Aquilonal y úsala para liberar a la doncella encerrada en hielo. Es la guardiana de una espada ancestral y recompensará a su libertad<or/ora>.\n\nDemuestra tu valía y consigue la espada que ha estado custodiando durante tanto tiempo, <nombre>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de AspiranteObjeto #1"}
MultiLanguageQuestData['mx'][13671] = {title = "Instrucción en el campo", objective = "Avareth Golpeveloz en los Campos del Torneo Argenta quiere que mates a 8 miembros de la Plaga de Corona de Hielo. Puedes matar a los miembros de la Plaga en cualquier parte de Corona de Hielo excepto en El Bombardeo.", description = "El torneo es el lugar para probar tus habilidades contra tus semejantes, pero no tenemos que olvidarnos de que el enemigo real, la Plaga, no se va a quedar de brazos cruzados. Mientras aprendes a dominar el combate sobre montura, practica las habilidades que te han servido tan bien todos estos años. Demuéstranos que puedes enfrentarte a la Plaga con honor y valentía, y que te ganarás el derecho a participar en este torneo.\n\nViaja a Corona de Hielo y enfréntate a cualquier miembro de la Plaga que veas, mantente lejos de El Bombardeo, arrasarían contigo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de Aspirante"}
MultiLanguageQuestData['mx'][13672] = {title = "A la altura del desafío", objective = "Entrégale al arcanista Taelis en el Torneo Argenta 15 sellos de aspirante para indicarle que estás a punto para aceptar el desafío del aspirante.", description = "Cuando domines las habilidades del aspirante, podrás optar a aceptar el desafío del aspirante. El desafío probará tus habilidades en combate sobre montura y evaluará si estás a punto para recibir el título de <Valeroso/Valerosa>. Si pasas la prueba, podrás unirte a la delegación de tu capital en calidad de <Valeroso/Valerosa>.\n\nCuando estés <listo/lista> para aceptar el desafío, ven a verme.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13673] = {title = "Una espada de Campeón", objective = "Recupera la espada de Lago Fresno y llévasela al magister Edien Vacuosol en los Campos del Torneo Argenta.", description = "Algunos campeones creen que un arma antigua originaria de Rasganorte les dará suerte en el torneo. He accedido a ayudarles a buscar esa arma.\n\nCuenta una antigua leyenda de las Colinas Pardas que hay una doncella bajo el aspecto de una rana que protege la espada que tanto tiempo lleva custodiando. Vive entre las ranas de lago a las orillas del Lago Fresno, al este del Puesto Fresno. Cuentan que solo un beso voluntarioso puede romper la maldición. Ponte este cacao antes de besar nada, <nombre>, si no te saldrán pupas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de AspiranteObjeto #1"}
MultiLanguageQuestData['mx'][13674] = {title = "Un arma digna", objective = "Llévale la hoja de Drak'Mar al magister Edien Vacuosol en los Campos del Torneo Argenta.", description = "Nuestros campeones se han aficionado a las armas antiguas que se fabricaron aquí en Rasganorte.\n\nHe oído que los bardos cuentan historias de viajantes que ofrecían jacintos de invierno a una doncella solitaria a cambio de obsequios. Esos jacintos solo crecen en el hielo de la Presa del Muro de Hierro, en el extremo noroeste del Bosque Canto de Cristal que limita con Corona de Hielo. Recoge las flores y llévalas al círculo de luces del Lago Drak'Mar al noreste del Cementerio de Dragones, cerca de Zul'Drak y las Colinas Pardas. Pídele a la doncella solitaria una espada digna.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de AspiranteObjeto #4"}
MultiLanguageQuestData['mx'][13675] = {title = "El Filo del invierno", objective = "El magister Edien Vacuosol en los Campos del Torneo Argenta quiere que le lleves el Filoinvierno.", description = "Uno de los valerosos de Orgrimmar me contó una historia interesante.\n\nAl sur del Bosque Canto de Cristal, vigilando la salida hacia el Vicio de Cristal está Lord Llama Perpetua. Mátalo y toma su ascua de llama perpetua.\n\nLlévala al centro del Lago Aliento Invernal, en la parte norte del Fiordo Aquilonal y úsala para liberar a la doncella encerrada en hielo. Es la guardiana de una espada ancestral y recompensará a su libertad<or/ora>.\n\nDemuestra tu valía y consigue la espada que ha estado custodiando durante tanto tiempo, <nombre>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de AspiranteObjeto #1"}
MultiLanguageQuestData['mx'][13676] = {title = "Instrucción en el campo", objective = "Amariel Jurasol en los Campos del Torneo Argenta quiere que mates a 8 miembros de la Plaga de Corona de Hielo. Puedes matar a los miembros de la Plaga en cualquier parte de Corona de Hielo excepto en El Bombardeo.", description = "El torneo es el lugar para probar tus habilidades contra tus semejantes, pero no tenemos que olvidarnos de que el enemigo real, la Plaga, no se va a quedar de brazos cruzados. Mientras aprendes a dominar el combate sobre montura, practica las habilidades que te han servido tan bien todos estos años. Demuéstranos que puedes enfrentarte a la Plaga con honor y valentía, y que te ganarás el derecho a participar en este torneo.\n\nViaja a Corona de Hielo y enfréntate a cualquier miembro de la Plaga que veas, mantente lejos de El Bombardeo, arrasarían contigo.", progress = nil, completion = "Has demostrado ser una oponente capaz, &lt;nombre&gt; y me servirás de ejemplo para el resto de los aspirantes que dicen a voces competir en nombre de la Horda.", rewards = "Recibirás:\n\nSello de Aspirante"}
MultiLanguageQuestData['mx'][13677] = {title = "Aprende a llevar las riendas", objective = "Golpea a un objetivo cuerpo a cuerpo con Estocada 5 veces, usa Romper escudo sobre 2 objetivos a distancia vulnerables, usa Cargar sobre 2 objetivos de carga vulnerables y luego vuelve a ver a Galathia Alba Brillante en los Campos del Torneo Argenta.\n\nSi pierdes tu lanza, puedes coger otra de cualquier expositor de lanzas que hay cerca de los establos o en el Pabellón Atracasol.", description = "En la mayoría de las competiciones del torneo es indispensable que domines una montura en combate. Hemos instalado muñecos de entrenamiento en la parte norte de los Campos del Torneo para que te acostumbres al combate sobre montura.\n\nVe a los establos que hay fuera del pabellón, equipa tu lanza y monta sobre un halcón zancudo Atracasol. Acostúmbrate a la montura y usa sus habilidades para derrotar a los tres tipos de muñecos de entrenamiento.\n", progress = nil, completion = "Bien hecho, &lt;nombre&gt;. El combate sobre montura generalmente es difícil de entender para los que tienen costumbre de luchar a pie. No tengo duda de que continuarás mejorando con la práctica, que ya es más de lo que puedo decir de algunos guerreros.", rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\nSello de Aspirante"}
MultiLanguageQuestData['mx'][13678] = {title = "A la altura del desafío", objective = "Entrégale al magister Edien Vacuosol en el Torneo Argenta 15 sellos de aspirante para indicarle que estás a punto para aceptar el desafío del aspirante.", description = "Cuando domines las habilidades del aspirante, podrás optar a aceptar el desafío del aspirante. El desafío probará tus habilidades en combate sobre montura y evaluará si estás a punto para recibir el título de <Valeroso/Valerosa>. Si pasas la prueba, podrás unirte a la delegación de tu capital en calidad de <Valeroso/Valerosa>.\n\nCuando estés <listo/lista> para aceptar el desafío, ven a verme.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13679] = {title = "El desafío del aspirante", objective = "Habla con el escudero David para llamar a tu oponente. Cuando hayas derrotado al Valeroso Argenta, regresa con el arcanista Taelis en los Campos del Torneo Argenta.\n\nSi pierdes tu lanza, puedes coger otra de cualquier expositor de lanzas que hay cerca de los establos o en el Pabellón de El Pacto de Plata.", description = "Te has entrenado duro como aspirante, <nombre>, y ha llegado la hora de que se pongan a prueba tus habilidades en combate sobre montura frente a un contrincante diestro.\n\nEquipa tu lanza, luego ve a los establos que hay fuera del pabellón y monta el corcel Quel'dorei de establo.\n\nEn La Liza de los Aspirantes en la parte norte de los Campos del Torneo, encontrarás a un joven escudero humano llamado David. Te preguntará si estás <listo/lista> y llamará a tu contrincante.\n\nBuena suerte, <nombre>. Que tu montura se mantenga firme y que tu puntería sea buena.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13680] = {title = "El desafío del aspirante", objective = "Habla con el escudero David para invocar a tu oponente. Cuando hayas derrotado al valeroso Argenta, vuelve a hablar con el magister Edien Vacuosol en los Campos del Torneo Argenta.", description = "Te has entrenado duro como aspirante, <nombre>, y ha llegado la hora de que se pongan a prueba tus habilidades en combate sobre montura frente a un contrincante experto.\n\nEquipa tu lanza, luego ve a los establos que hay fuera del pabellón y monta el halcón zancudo Atracasol.\n\nEn La Liza de los Aspirantes en la parte norte de los Campos del Torneo, encontrarás a un joven escudero humano llamado David. Te preguntará si estás <listo/lista> y llamará a tu contrincante.\n\nBuena suerte, <nombre>. Que tu montura se mantenga firme y que tu puntería sea buena.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13681] = {title = "Un trozo del bloque de Ulduar", objective = "Llévale 15 bloques de piedra pequeños a Bozzle Cargarrayo en los Campos del Torneo Argenta.", description = "¡Conseguir piedra para este trabajo ha sido pesadilla total! Hay piedra a punta pala en ruinas en sitios seguros, pero los santurrones de los paladines no van a por ella. Dicen algo de unos artefactos de valor inestimable.\n\nTotal que a mí tanto lloriqueo no me construye el coliseo. Hay montones de bloques de piedra caídos y sueltos alrededor de las ruinas titánicas en las Estepas Inferiores y en la Biblioteca del Inventor, en las Cumbres Tormentosas. Llévate mi, eh..., cincel, y mira a ver si puedes desmenuzar esos bloques en trozos más útiles.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][13682] = {title = "Amenaza desde el cielo", objective = "Eadric el Puro, en el Torneo Argenta, quiere que derrotes a Yertafauce y a 3 bombarderos cultor.", description = "El alto señor Tirion Vadín ha doblado la guardia desde que descubriste al infiltrado del Culto de los Malditos. No cree que se detengan solo porque su Caballero Negro haya sido derrotado.\n\nNuestros exploradores garfacielo informan que han visto una vermis de escarcha llamada Yertafauce en cabeza de un grupo de asalto del culto. Si no los interceptamos, atacarán durante el torneo. Los exploradores informaban que habían visto a Yertafauce al suroeste, sobrevolando el área entre la Fortificación del Muro de Hierro y Aldur'thar.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nMonedero de CampeónLibranza del Campeón\n\nTambién recibirás:\n\nSuministros de aventura de RasganorteSello de CampeónCurrency Token Test Token 2"}
MultiLanguageQuestData['mx'][13683] = {title = "Detener los rituales", objective = "Interrumpe 8 gemas rituales.", description = "No he podido evitar oír la conversación sobre la pérdida de Illiyana. Entiendo su necesidad de venganza. Me pregunto si mientras te ocupas de eso podrías hacernos un favor.\n\nNo hay duda de que ya has visto al sátiro de Satyrnaar y Xavian realizando rituales viles. Creo que están preparando sus rituales para corromper a cualquier elfo de la noche que capturen y transformarlos en sátiros. Los draenei también tenemos problemas con la exposición a la magia vil.\n\n¿Interrumpirías sus gemas rituales mientras estás allí?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13684] = {title = "Un Valeroso de Ventormenta", objective = "Habla con el mariscal Jacob Alerius en los Campos del Torneo Argenta para convertirte en <un Valeroso/una Valerosa> de Ventormenta.", description = "Has demostrado que eres <digno/digna> de competir bajo el estandarte de Ventormenta, <nombre>. Ahora preséntate ante el mariscal Jacob Alerius, que dirige la delegación de Ventormenta. Como Gran Campeón de Ventormenta, te inscribirá en el torneo en nombre de la ciudad, supervisará tu entrenamiento y te pondrá a prueba para convertirte en <Valeroso/Valerosa>.\n\nHa sido un honor trabajar contigo, <nombre>, te deseo suerte en la competición que te espera.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13685] = {title = "Un Valeroso de Forjaz", objective = "Habla con Lana Martillotenaz en los Campos del Torneo Argenta para convertirte en <un Valeroso/una Valerosa> de Forjaz.", description = "Has demostrado que eres <digno/digna> de competir bajo el estandarte de Forjaz, <nombre>. Ahora preséntate ante Lana Martillotenaz, que dirige la delegación de Forjaz. Como Gran Campeona de Forjaz, te inscribirá en el torneo en nombre de la ciudad, supervisará tu entrenamiento y te pondrá a prueba para convertirte en <Valeroso/Valerosa>.\n\nHa sido un honor trabajar contigo, <nombre>, te deseo suerte en la competición que te espera.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13691] = {title = "Un Valeroso de Orgrimmar", objective = "Habla con Mokra el Trituracráneos en los Campos del Torneo Argenta para convertirte en <un Valeroso/una Valerosa> de Orgrimmar.", description = "Has demostrado que eres <digno/digna> de competir bajo el estandarte de Orgrimmar, <nombre>. Ahora habla con Mokra el Trituracráneos, que dirige a los competidores de Orgrimmar. Como Gran Campeón de Orgrimmar, te inscribirá en el torneo en nombre de la ciudad, supervisará tu entrenamiento y te pondrá a prueba para convertirte en <Valeroso/Valerosa>.\n\nHa sido un honor trabajar contigo, <nombre>, te deseo suerte en la competición que te espera.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13692] = {title = "La espada y el mar", objective = "El viejo Barlo en el Bosque Canto de Cristal quiere que le lleves la espada de caballería.", description = "Perdí mi espada en el mar. ¡Encuéntrala y tráemela!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][13693] = {title = "Un Valeroso de Sen'jin", objective = "Habla con Zul'tore en los Campos del Torneo Argenta para convertirte en <un Valeroso/una Valerosa> de Sen'jin.", description = "Has demostrado que eres <digno/digna> de competir bajo el estandarte de Sen'jin, <nombre>. Ahora habla con Zul'tore, que dirige a los guerreros de Sen'jin. Como Gran Campeón trol, te inscribirá en el torneo en nombre de la ciudad, supervisará tu entrenamiento y te pondrá a prueba para convertirte en <Valeroso/Valerosa>.\n\nHa sido un honor trabajar contigo, <nombre>, te deseo suerte en la competición que te espera.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13694] = {title = "Un Valeroso de Cima del Trueno", objective = "Habla con Runok Ferocrín en los Campos del Torneo Argenta para convertirte en <un Valeroso/una Valerosa> de Cima del Trueno.", description = "Has demostrado que eres <digno/digna> de competir bajo el estandarte de Cima del Trueno, <nombre>. Ahora habla con Runok Ferocrín, que dirige a los competidores de Cima del Trueno. Como Gran Campeón de Cima del Trueno, te inscribirá en el torneo en nombre de la ciudad, supervisará tu entrenamiento y te pondrá a prueba para convertirte en <Valeroso/Valerosa>.\n\nHa sido un honor trabajar contigo, <nombre>, te deseo suerte en la competición que te espera.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13696] = {title = "Un Valeroso de Lunargenta", objective = "Habla con Eressea Cantoalba en los Campos del Torneo Argenta para convertirte en <un Valeroso/una Valerosa> de Lunargenta.", description = "Has demostrado que eres <digno/digna> de competir bajo el estandarte de Lunargenta, <nombre>. Ahora habla con Eressea Cantoalba, que dirige la delegación de Lunargenta. Como Gran Campeona de Lunargenta, te inscribirá en el torneo en nombre de la ciudad, supervisará tu entrenamiento y te pondrá a prueba para convertirte en <Valeroso/Valerosa>.\n\nHa sido un honor trabajar contigo, <nombre>, te deseo suerte en la competición que te espera.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13697] = {title = "La carga del Valeroso", objective = "Lleva 25 sellos de Valeroso a Mokra el Trituracráneos en los Campos del Torneo Argenta.", description = "En tu entrenamiento como <Valeroso/Valerosa> tendrás la oportunidad de poner a prueba tu habilidad contra valerosos que representan a otras ciudades. Aunque las batallas de <un Valeroso/una Valerosa> no son parte formal de la competición, aprenderás una valiosa lección sobre los estilos de lucha y las debilidades de tus oponentes.\n\nLos valerosos son gente voluntariosa que compite entre sí en pos del honor y la notoriedad.\n\nEntrénate como <un Valeroso/una Valerosa> hasta que confíes en tu habilidad para derrotar a todo aquel que se enfrente a ti. Después tráeme los sellos que hayas ganado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13698] = {title = "Explosivos que trituran", objective = "Utiliza una trituradora Grito de Guerra para destruir 8 barriles de explosivos.", description = "Odio volver a enviarte allí, pero si nos basamos en tu descripción de lo que está pasando, ¡no podemos dejar que utilicen todos los explosivos que hemos almacenado!\n\nEs demasiado peligroso que intentes destruirlos tú <mismo/misma>, pero si robases una de sus trituradoras, estoy seguro de que sería lo suficientemente fuerte para resistir las explosiones.\n\nCuando hayas destruido sus explosivos, vuelve aquí con la trituradora. No tiene sentido que se la devolvamos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Hoja de trituradoraJubón quemado con pólvoraMusleras de guardabosquesRecibirás:\n\n"}
MultiLanguageQuestData['mx'][13699] = {title = "El desafío del Valeroso", objective = "Habla con el escudero Danny para llamar a tu oponente. Cuando hayas derrotado al Campeón Argenta, regresa con el mariscal Jacob Alerius en los Campos del Torneo Argenta.\n\nSi pierdes tu lanza, puedes coger otra de cualquier expositor de lanzas que hay cerca de los establos o en el Pabellón de El Pacto de Plata.", description = "Ya casi estás <listo/lista> para competir en el gran combate cuerpo a cuerpo en nombre de Ventormenta. Para demostrar que eres <digno/digna> de entrar en las listas en nombre de nuestra ciudad, debes derrotar a un campeón de la Cruzada Argenta.\n\nVe a los establos que hay fuera del pabellón, equipa tu lanza y monta. Habla con el escudero Danny en La Liza de los Valerosos Argenta en el extremo oeste de los campos. El escudero llamará a tu oponente cuando estés <listo/lista>.\n\nCuando la batalla haya concluido, hablaremos del resultado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13702] = {title = "Se alza un Campeón", objective = "Habla con la justicar Mariel Corazón Veraz en los Campos del Torneo Argenta.", description = "Felicidades, <nombre>. Has dominado muchos tipos de combate y has superado todos los desafíos a los que te has enfrentado. No cabe duda de que estás <preparado/preparada> para competir con los mejores guerreros que se han reunido en este torneo, contra los campeones de las ciudades capitales.\n\nLa justicar Mariel Corazón Veraz ha solicitado hablar contigo, <nombre>, e introducirte formalmente en el gran combate cuerpo a cuerpo de los campeones.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nEscudero ArgentaSello de Campeón"}
MultiLanguageQuestData['mx'][13703] = {title = "Valeroso de Forjaz", objective = "Habla de nuevo con Lana Martillotenaz si quieres convertirte en <Valeroso/Valerosa> de Forjaz.", description = "Te doy la bienvenida, <Campeón/Campeona>. Ya he oído hablar de tu destreza en el combate. ¿Deseas unirte a la delegación de Forjaz en el torneo?\n\nTe entrenarás y subirás de rango como has hecho antes, pero cuando seas <nombrado Campeón/nombrada Campeona> de Forjaz tu escudero tendrá la opción de llevar nuestro estandarte a la batalla.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13704] = {title = "Valeroso de Gnomeregan", objective = "Habla de nuevo con Ambrose Chisparrayo si quieres convertirte en <Valeroso/Valerosa> de Gnomeregan.", description = "Te doy la bienvenida, <Campeón/Campeona>. Ya he oído hablar de tu destreza en combate. La delegación de Gnomeregan podría sacar partido de verdad a <un/una> <clase> como tú.\n\nTe entrenarás y subirás de rango como antes, pero cuando seas <nombrado Campeón/nombrada Campeona> de Gnomeregan tu escudero podrá optar a llevar nuestro estandarte a la batalla.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13705] = {title = "Valeroso de El Exodar", objective = "Habla con Colosos de nuevo si deseas convertirte en <Valeroso/Valerosa> de El Exodar.", description = "Te doy la bienvenida, <Campeón/Campeona>. Ya he oído hablar de tus gestas. ¿Deseas unirte a la delegación de El Exodar en el torneo?\n\nTe entrenarás y subirás de rango como antes, pero cuando seas <nombrado Campeón/nombrada Campeona> de El Exodar, tu escudero podrá optar a llevar nuestro estandarte a la batalla.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13706] = {title = "Valeroso de Darnassus", objective = "Habla de nuevo con Jaelyne Unicanto si quieres convertirte en <Valeroso/Valerosa> de Darnassus.", description = "Te doy la bienvenida, <Campeón/Campeona>. Ya he oído hablar de tus logros y nos honraría que te unieras a la delegación de Darnassus.\n\nTe entrenarás y subirás de rango como antes, pero cuando seas <nombrado Campeón/nombrada Campeona> de Darnassus, tu escudero podrá optar a llevar nuestro estandarte a la batalla.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13708] = {title = "Valeroso de Sen'jin", objective = "Habla de nuevo con Zul'tore si deseas convertirte en <un Valeroso/una Valerosa> de Sen'jin.", description = "Saludos, <Campeón/Campeona>. Si lo deseas, te doy la bienvenida a nuestra delegación de Sen'jin en el torneo.\n\nTe entrenarás y subirás de rango como antes, pero cuando seas <nombrado Campeón/nombrada Campeona> de Sen'jin, tu brutito podrá optar a llevar nuestro estandarte a la batalla.Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nBandera de elegibilidad del torneo de la Horda\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][13710] = {title = "Valeroso de Entrañas", objective = "Habla de nuevo con el mortacechador Visceri si deseas convertirte en Valeroso de Entrañas.", description = "Te doy la bienvenida, <Campeón/Campeona>. La delegación de los Renegados siempre podría emplear a <un/una> <clase> como tú. ¿Te gustaría unirte a nosotros?\n\nTe entrenarás y subirás de rango como antes, pero cuando seas nombrad<o Campeón/a Campeona> de Entrañas, tu brutito podrá optar a llevar nuestro estandarte a la batalla.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13711] = {title = "Valeroso de Lunargenta", objective = "Habla de nuevo con Eressea Cantoalba si quieres convertirte en <Valeroso/Valerosa> de Lunargenta.", description = "¿Así que ahora eres <un Campeón/una Campeona>? Entonces has demostrado ser <un combatiente digno/una combatiente digna> y me llena de orgullo darte la bienvenida a nuestra delegación de Lunargenta.\n\nTe entrenarás y subirás de rango como antes, pero cuando seas <nombrado Campeón/nombrada Campeona> de Lunargenta, tu brutito podrá optar a llevar nuestro estandarte a la batalla.Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nBandera de elegibilidad del torneo de la Horda\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][13712] = {title = "¡Al rescate!", objective = "Habla con Kadrak en la Empalizada de Mor'shan y acompáñale hasta el Puesto del Hachazo.", description = "Tú vienes conmigo, <nombre>.\n\nNo puedo prescindir de nadie más y no podemos permitirnos perder El Hachazo.\n\nPrepárate y ven a avisarme cuando estés <listo/lista>.", progress = nil, completion = "La muerte de Gorka no fue en vano, &lt;nombre&gt;.\n\nEl Hachazo habría caído si no hubiésemos acudido cuando lo hemos hecho.\n\nAhora debemos ponernos manos a la obra para apuntalar sus defensas.\n\nEsto no ha acabado...", rewards = "Recibirás:\n\nBanda de Gorka"}
MultiLanguageQuestData['mx'][13713] = {title = "El desafío del Valeroso", objective = "Habla con el escudero Danny para llamar a tu oponente. Cuando hayas derrotado al Campeón Argenta, regresa con Lana Martillotenaz en los Campos del Torneo Argenta.\n\nSi pierdes tu lanza, puedes coger otra de cualquier expositor de lanzas que hay cerca de los establos o en el Pabellón de El Pacto de Plata.", description = "Ya casi estás <listo/lista> para competir en el gran combate cuerpo a cuerpo en nombre de Forjaz. Para demostrar que eres <digno/digna> de entrar en las listas en nombre de nuestra ciudad, debes derrotar a un campeón de la Cruzada Argenta.\n\nVe a los establos que hay fuera del pabellón, equipa tu lanza y monta. Habla con el escudero Danny en La Liza de los Valerosos Argenta en el extremo oeste de los campos. El escudero llamará a tu oponente cuando estés <listo/lista>.\n\nCuando la batalla haya concluido, hablaremos del resultado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
