MultiLanguageQuestData['mx'][13726] = {title = "El desafío del Valeroso", objective = "Habla con el escudero Danny para llamar a tu oponente. Cuando hayas derrotado al Campeón Argenta, regresa con Mokra el Trituracráneos en los Campos del Torneo Argenta.\n\nSi pierdes tu lanza, puedes coger otra de cualquier expositor de lanzas que hay cerca de los establos o en el Pabellón Atracasol.", description = "Ya casi estás <listo/lista> para competir en el gran combate cuerpo a cuerpo. Para demostrar que eres <digno/digna> de este honor, debes derrotar a un campeón de la Cruzada Argenta.\n\nVe a los establos que hay fuera del pabellón, equipa tu lanza y monta. Habla con el escudero Danny en La Liza de los Valerosos Argenta en el extremo oeste de los campos. El escudero llamará a tu oponente cuando estés <listo/lista>.\n\nCuando la batalla haya concluido, hablaremos del resultado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13727] = {title = "El desafío del Valeroso", objective = "Habla con el escudero Danny para llamar a tu oponente. Cuando hayas derrotado al Campeón Argenta, regresa con Zul'tore en los Campos del Torneo Argenta.\n\nSi pierdes tu lanza, puedes coger otra de cualquier expositor de lanzas que hay cerca de los establos o en el Pabellón Atracasol.", description = "Ya casi estás <listo/lista> para competir en el gran combate cuerpo a cuerpo. Para demostrar que eres <digno/digna> de este honor, debes derrotar a un campeón de la Cruzada Argenta.\n\nVe a los establos que hay fuera del pabellón, equipa tu lanza y monta. Habla con el escudero Danny en La Liza de los Valerosos Argenta en el extremo oeste de los campos. El escudero llamará a tu oponente cuando estés <listo/lista>.\n\nCuando la batalla haya concluido, hablaremos del resultado.Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nColocar bandera de Campeón de la Horda\n\nRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][13728] = {title = "El desafío del Valeroso", objective = "Habla con el escudero Danny para llamar a tu oponente. Cuando hayas derrotado al Campeón Argenta, regresa con Runok Ferocrín en los Campos del Torneo Argenta.\n\nSi pierdes tu lanza, puedes coger otra de cualquier expositor de lanzas que hay cerca de los establos o en el Pabellón Atracasol.", description = "Ya casi estás <listo/lista> para competir en el gran combate cuerpo a cuerpo. Para demostrar que eres <digno/digna> de este honor, debes derrotar a un campeón de la Cruzada Argenta.\n\nVe a los establos que hay fuera del pabellón, equipa tu lanza y monta. Habla con el escudero Danny en La Liza de los Valerosos Argenta en el extremo oeste de los campos. El escudero llamará a tu oponente cuando estés <listo/lista>.\n\nCuando la batalla haya concluido, hablaremos del resultado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13729] = {title = "El desafío del Valeroso", objective = "Habla con el escudero Danny para llamar a tu oponente. Cuando hayas derrotado al Campeón Argenta, regresa con el mortacechador Visceri en los Campos del Torneo Argenta.\n\nSi pierdes tu lanza, puedes coger otra de cualquier expositor de lanzas que hay cerca de los establos o en el Pabellón Atracasol.", description = "Ya casi estás <listo/lista> para competir en el gran combate cuerpo a cuerpo. Para demostrar que eres <digno/digna> de este honor, debes derrotar a un campeón de la Cruzada Argenta.\n\nVe a los establos que hay fuera del pabellón, equipa tu lanza y monta. Habla con el escudero Danny en La Liza de los Valerosos Argenta en el extremo oeste de los campos. El escudero llamará a tu oponente cuando estés <listo/lista>.\n\nCuando la batalla haya concluido, hablaremos del resultado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13730] = {title = "Jugando con fuego vil", objective = "Draaka del Hachazo quiere que llenes el bote reforzado con 7 fuegos viles de Cerro Lumbrevil.", description = "<Draaka se inclina para hablar contigo.>\n\nEscucha... antes de que digas nada, SÉ que no debemos jugar con energías demoníacas...\n\n¡Pero mira a tu alrededor! Estamos en tiempos desesperados, <clase>.\n\nLo más probable es que muramos aquí de todas formas. ¡Al menos tengamos una salida gloriosa!\n\nEntonces... ¿cuento contigo?\n\nToma este bote y ve al sureste a Cerro Lumbrevil. Utilízalo cerca de los parches de fuego vil y tráemelo de vuelta cuando lo hayas rellenado.\n\nAh y mejor si no se lo decimos a nadie...", progress = nil, completion = "¡Sí!\n\n¡Esto le enseñará una lección a esos elfos, mira!", rewards = "Borde de la locuraJubón con marcas de fuego vilMusleras de virtud abandonadaRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][13731] = {title = "El desafío del Valeroso", objective = "Habla con el escudero Danny para llamar a tu oponente. Cuando hayas derrotado al Campeón Argenta, regresa con Eressea Cantoalba en los Campos del Torneo Argenta.\n\nSi pierdes tu lanza, puedes coger otra de cualquier expositor de lanzas que hay cerca de los establos o en el Pabellón Atracasol.", description = "Ya casi estás <listo/lista> para competir en el gran combate cuerpo a cuerpo. Para demostrar que eres <digno/digna> de este honor, debes derrotar a un campeón de la Cruzada Argenta.\n\nVe a los establos que hay fuera del pabellón, equipa tu lanza y monta. Habla con el escudero Danny en La Liza de los Valerosos Argenta en el extremo oeste de los campos. El escudero llamará a tu oponente cuando estés <listo/lista>.\n\nCuando la batalla haya concluido, hablaremos del resultado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13732] = {title = "Se alza un Campeón", objective = "Habla con la justicar Mariel Corazón Veraz en los Campos del Torneo Argenta.", description = "Felicidades, <nombre>. Has dominado muchos tipos de combate y has superado todos los desafíos a los que te has enfrentado. No cabe duda de que estás <preparado/preparada> para competir con los mejores guerreros que se han reunido en este torneo, contra los campeones de las ciudades capitales.\n\nLa justicar Mariel Corazón Veraz ha solicitado hablar contigo, <nombre>, e introducirte formalmente en el gran combate cuerpo a cuerpo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nEscudero ArgentaSello de Campeón"}
