MultiLanguageQuestData['mx'][13736] = {title = "Se alza un Campeón", objective = "Habla con la justicar Mariel Corazón Veraz en los Campos del Torneo Argenta.", description = "Te has ganado mi respeto y el de tus compañeros. Has derrotado a todo el que te ha desafiado y dominas el combate en torneo. ¡No dudo de que estás <preparado/preparada> para enfrentarte a los campeones de otras ciudades por la gloria de Orgrimmar!\n\nLa justicar Mariel Corazón Veraz ha solicitado hablar contigo, <nombre>, e introducirte formalmente en el gran combate cuerpo a cuerpo de los campeones.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBrutito ArgentaSello de Campeón"}
MultiLanguageQuestData['mx'][13737] = {title = "Se alza un Campeón", objective = "Habla con la justicar Mariel Corazón Veraz en los Campos del Torneo Argenta.", description = "Te has ganado mi respeto y el de tus compañeros. Has derrotado a todo el que te ha desafiado y dominas el combate en torneo. ¡No dudo de que estás <preparado/preparada> para enfrentarte a los campeones de otras ciudades por la gloria de Lanza Negra!\n\nLa justicar Mariel Corazón Veraz ha solicitado hablar contigo, <nombre>, e introducirte formalmente en el gran combate cuerpo a cuerpo de los campeones.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBrutito ArgentaSello de Campeón"}
