MultiLanguageQuestData['mx'][13739] = {title = "Se alza un Campeón", objective = "Habla con la justicar Mariel Corazón Veraz en los Campos del Torneo Argenta.", description = "Te has ganado mi respeto y el de tus compañeros. Has derrotado a todo el que te ha desafiado y dominas el combate en torneo. ¡No dudo de que estás <preparado/preparada> para enfrentarte a los campeones de otras ciudades por la gloria de los Renegados!\n\nLa justicar Mariel Corazón Veraz ha solicitado hablar contigo, <nombre>, e introducirte formalmente en el gran combate cuerpo a cuerpo de los campeones.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBrutito ArgentaSello de Campeón"}
MultiLanguageQuestData['mx'][13740] = {title = "Se alza un Campeón", objective = "Habla con la justicar Mariel Corazón Veraz en los Campos del Torneo Argenta.", description = "Te has ganado mi respeto y el de tus compañeros. Has derrotado a todo el que te ha desafiado y dominas el combate en torneo. ¡No dudo de que estás <preparado/preparada> para enfrentarte a los campeones de otras ciudades por la gloria de Lunargenta!\n\nLa justicar Mariel Corazón Veraz ha solicitado hablar contigo, <nombre>, e introducirte formalmente en el gran combate cuerpo a cuerpo de los campeones.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBrutito ArgentaSello de Campeón"}
MultiLanguageQuestData['mx'][13741] = {title = "Una espada de Campeón", objective = "Recupera la espada de Lago Fresno y llévasela a Lana Martillotenaz en los Campos del Torneo Argenta.", description = "El buen acero afilado y honesto no triunfa. Los demás combatientes usan espadas encantadas y estoy en desventaja, pero aún hay esperanza.\n\nCuenta una antigua leyenda de las Colinas Pardas que hay una doncella bajo el aspecto de una rana que protege la espada que tanto tiempo lleva custodiando. Vive entre las ranas de lago a las orillas del Lago Fresno, al este del Puesto Fresno. Cuentan que solo un beso voluntarioso puede romper la maldición. Ponte este cacao antes de besar nada, <nombre>, si no te saldrán pupas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valerosoObjeto #1"}
MultiLanguageQuestData['mx'][13742] = {title = "Un arma digna", objective = "Lleva la hoja de Drak'Mar a Lana Martillotenaz en los Campos del Torneo Argenta.", description = "¡Maldita sea mi suerte!\n\n¡He perdido la espada del torneo! He oído que los bardos cuentan historias de viajantes que ofrecían jacintos de invierno a una doncella solitaria a cambio de obsequios. Esos jacintos solo crecen en el hielo de la Presa del Muro de Hierro, en el extremo noroeste del Bosque Canto de Cristal que limita con Corona de Hielo. Recoge las flores y llévalas al círculo de luces del Lago Drak'Mar al noreste del Cementerio de Dragones, cerca de Zul'Drak y las Colinas Pardas. Pídele a la doncella solitaria una espada digna.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valerosoObjeto #4"}
MultiLanguageQuestData['mx'][13743] = {title = "El Filo del invierno", objective = "Lana Martillotenaz en los Campos del Torneo Argenta quiere que le lleves Filoinvierno.", description = "¡Maldito sea ese caballero de la Muerte por romper mi espada!\n\nAl sur del Bosque Canto de Cristal, vigilando la salida hacia el Vicio de Cristal está Lord Llama Perpetua. Mátalo y toma su ascua de llama perpetua.\n\nLlévala al centro del Lago Aliento Invernal, en la parte norte del Fiordo Aquilonal y úsala para liberar a la doncella encerrada en hielo. Es la guardiana de una espada ancestral y recompensará a su libertad<or/ora>.\n\nDemuestra tu valía y consigue la espada que ha estado custodiando durante tanto tiempo, <nombre>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valerosoObjeto #1"}
MultiLanguageQuestData['mx'][13744] = {title = "Instrucción en el campo de un Valeroso", objective = "Rolo Tiro Acertado en los Campos del Torneo Argenta quiere que mates a 10 héroes transformados.", description = "El torneo es el lugar para probar tus habilidades contra tus semejantes, pero no tenemos que olvidarnos de que el enemigo real, la Plaga, no se va a quedar de brazos cruzados. Mientras perfeccionas tus habilidades contra otros, sigue combatiendo al enemigo.\n\nViaja al área que hay al suroeste de El Valle de los Héroes Caídos y al norte de Corp'rethar. Allí, la Plaga resucita héroes muertos y los vuelve en nuestra contra. Derrota a esos esbirros de la Plaga, honra a nuestros aliados y prepárate para el combate.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valeroso"}
MultiLanguageQuestData['mx'][13745] = {title = "El gran combate cuerpo a cuerpo", objective = "Llévale 3 marcas del Valeroso a Clara Vueltabirra en los Campos del Torneo Argenta.\n\nSi pierdes tu lanza, puedes coger otra de cualquier expositor de lanzas que hay cerca de los establos o en el Pabellón de El Pacto de Plata.", description = "El gran combate cuerpo a cuerpo es la competición más importante del torneo. El pueblo de Forjaz espera tener noticias de nuestro éxito. A tal fin, han estado perfeccionando sus habilidades contra los valerosos que representan a las otras capitales de la Alianza.\n\nSugiero que hagas lo mismo. Los valerosos se entrenan en la liza que hay justo al salir de nuestra tienda. Equipa tu lanza, ve a los establos que hay fuera del pabellón, monta el carnero de Forjaz de establo y desafía a otros valerosos de la Alianza.\nTe van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nQuitar lanza\n\nRecibirás:\n\nSello de valerosoObjeto #1"}
MultiLanguageQuestData['mx'][13746] = {title = "Una espada de Campeón", objective = "Recupera la espada de Lago Fresno y llévasela a Ambrose Chisparrayo en los Campos del Torneo Argenta.", description = "El buen acero afilado y honesto no triunfa. Los demás combatientes usan espadas encantadas y estoy en desventaja, pero aún hay esperanza.\n\nCuenta una antigua leyenda de las Colinas Pardas que hay una doncella bajo el aspecto de una rana que protege la espada que tanto tiempo lleva custodiando. Vive entre las ranas de lago a las orillas del Lago Fresno, al este del Puesto Fresno. Cuentan que solo un beso voluntarioso puede romper la maldición. Ponte este cacao antes de besar nada, <nombre>, si no te saldrán pupas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valeroso"}
MultiLanguageQuestData['mx'][13747] = {title = "Un arma digna", objective = "Lleva la hoja de Drak'Mar a Ambrose Chisparrayo en los Campos del Torneo Argenta.", description = "¡Maldita sea mi suerte!\n\n¡He perdido la espada del torneo! He oído que los bardos cuentan historias de viajantes que ofrecían jacintos de invierno a una doncella solitaria a cambio de obsequios. Esos jacintos solo crecen en el hielo de la Presa del Muro de Hierro, en el extremo noroeste del Bosque Canto de Cristal que limita con Corona de Hielo. Recoge las flores y llévalas al círculo de luces del Lago Drak'Mar al noreste del Cementerio de Dragones, cerca de Zul'Drak y las Colinas Pardas. Pídele a la doncella solitaria una espada digna.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valerosoObjeto #4"}
MultiLanguageQuestData['mx'][13748] = {title = "El Filo del invierno", objective = "Ambrose Chisparrayo en los Campos del Torneo Argenta quiere que le lleves Filoinvierno.", description = "Es la última vez que entreno con un caballero de la Muerte.\n\nAl sur del Bosque Canto de Cristal, vigilando la salida hacia el Vicio de Cristal está Lord Llama Perpetua. Mátalo y toma su ascua de llama perpetua.\n\nLlévala al centro del Lago Aliento Invernal, en la parte norte del Fiordo Aquilonal y úsala para liberar a la doncella encerrada en hielo. Es la guardiana de una espada ancestral y recompensará a su libertad<or/ora>.\n\nDemuestra tu valía y consigue la espada que ha estado custodiando durante tanto tiempo, <nombre>.\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valerosoObjeto #1"}
MultiLanguageQuestData['mx'][13749] = {title = "Instrucción en el campo de un Valeroso", objective = "Tickin Trazagranaje en los Campos del Torneo Argenta quiere que mates a 10 héroes transformados.", description = "El torneo es el lugar para probar tus habilidades contra tus semejantes, pero no tenemos que olvidarnos de que el enemigo real, la Plaga, no se va a quedar de brazos cruzados. Mientras perfeccionas tus habilidades contra otros, sigue combatiendo al enemigo.\n\nViaja al área que hay al suroeste de El Valle de los Héroes Caídos y al norte de Corp'rethar. Allí, la Plaga resucita héroes muertos y los vuelve en nuestra contra. Derrota a esos esbirros de la Plaga, honra a nuestros aliados y prepárate para el combate.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valeroso"}
MultiLanguageQuestData['mx'][13750] = {title = "El gran combate cuerpo a cuerpo", objective = "Llévale 3 marcas del Valeroso a Flickin Trazagranaje en los Campos del Torneo Argenta.\n\nSi pierdes tu lanza, puedes coger otra de cualquier expositor de lanzas que hay cerca de los establos o en el Pabellón de El Pacto de Plata.", description = "El gran combate cuerpo a cuerpo es la competición más importante del torneo. Sabemos que todo el mundo espera tener noticias de nuestro éxito. A tal fin, hemos perfeccionado nuestras habilidades contra los valerosos que representan a las demás capitales de la Alianza.\n\nSugiero que hagas lo mismo.\n\nVe a los establos que hay fuera del pabellón, equipa tu lanza, monta el turbozancudo de establo y desafía a los valerosos. Aguardan en La Liza de los Valerosos de la Alianza que hay justo al salir de nuestra tienda.\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valeroso"}
MultiLanguageQuestData['mx'][13751] = {title = "¡No se lo digas a nadie!", objective = "Draaka de El Hachazo quiere que le lleves la nota escrita con prisas a Durak.\n\nObjeto provisto: \n", description = "¡Perfecto!\n\nEsto enseñará a los elfos de lo que somos capaces en la Horda cuando estamos acorralados en un rincón.\n\nEscucha, <nombre>. ¡No debes hablar de esto a nadie!\n\nGarrosh lo aprobará una vez que vea los resultados, pero si nos descubren antes, ¡colgarán nuestras cabezas de una punta!\n\n<Draaka te pasa una nota escrita con prisas.>\n\nLlévale esto a Durak. Puedes encontrarle en las minas que hay tras de mí, justo al norte. Él te dará más instrucciones.", progress = nil, completion = "¿Qué es esto? ¡¿Quién eres tú?!\n\n&lt;Durak lee la nota de Draaka.&gt;\n\nHrmphh...\n\nDraaka no debería ser tan descarada, pero parece que estás en esto hasta el cuello y que tienes tanto que perder como todos.\n\nMuy bien.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13752] = {title = "Una espada de Campeón", objective = "Recupera la espada de Lago Fresno y llévasela a Colosos en los Campos del Torneo Argenta.", description = "El buen acero afilado y honesto no triunfa. Los demás combatientes usan espadas encantadas y estoy en desventaja, pero aún hay esperanza.\n\nCuenta una antigua leyenda de las Colinas Pardas que hay una doncella bajo el aspecto de una rana que protege la espada que tanto tiempo lleva custodiando. Vive entre las ranas de lago a las orillas del Lago Fresno, al este del Puesto Fresno. Cuentan que solo un beso voluntarioso puede romper la maldición. Ponte este cacao antes de besar nada, <nombre>, si no te saldrán pupas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valerosoObjeto #1"}
MultiLanguageQuestData['mx'][13753] = {title = "Un arma digna", objective = "Lleva la hoja de Drak'Mar a Colosos en los Campos del Torneo Argenta.", description = "¡Maldita sea mi suerte!\n\n¡He perdido la espada del torneo! He oído que los bardos cuentan historias de viajantes que ofrecían jacintos de invierno a una doncella solitaria a cambio de obsequios. Esos jacintos solo crecen en el hielo de la Presa del Muro de Hierro, en el extremo noroeste del Bosque Canto de Cristal que limita con Corona de Hielo. Recoge las flores y llévalas al círculo de luces del Lago Drak'Mar al noreste del Cementerio de Dragones, cerca de Zul'Drak y las Colinas Pardas. Pídele a la doncella solitaria una espada digna.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valerosoObjeto #4"}
MultiLanguageQuestData['mx'][13754] = {title = "El Filo del invierno", objective = "Colosos en los Campos del Torneo Argenta quiere que le lleves Filoinvierno.", description = "Es la última vez que entreno con un caballero de la Muerte.\n\nAl sur del Bosque Canto de Cristal, vigilando la salida hacia el Vicio de Cristal está Lord Llama Perpetua. Mátalo y toma su ascua de llama perpetua.\n\nLlévala al centro del Lago Aliento Invernal, en la parte norte del Fiordo Aquilonal y úsala para liberar a la doncella encerrada en hielo. Es la guardiana de una espada ancestral y recompensará a su libertad<or/ora>.\n\nDemuestra tu valía y consigue la espada que ha estado custodiando durante tanto tiempo, <nombre>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valerosoObjeto #1"}
MultiLanguageQuestData['mx'][13755] = {title = "Instrucción en el campo de un Valeroso", objective = "Saandos en los Campos del Torneo Argenta quiere que mates a 10 héroes transformados.", description = "El torneo es el lugar para probar tus habilidades contra tus semejantes, pero no tenemos que olvidarnos de que el enemigo real, la Plaga, no se va a quedar de brazos cruzados. Mientras perfeccionas tus habilidades contra otros, sigue combatiendo al enemigo.\n\nViaja al área que hay al suroeste de El Valle de los Héroes Caídos y al norte de Corp'rethar. Allí, la Plaga resucita héroes muertos y los vuelve en nuestra contra. Derrota a esos esbirros de la Plaga, honra a nuestros aliados y prepárate para el combate.", progress = nil, completion = "Hola de nuevo tras los ejercicios, &lt;nombre&gt;. Incluso mientras practicamos para la competición, es bueno recordar que la Plaga sigue ahí fuera.", rewards = "Recibirás:\n\nSello de valeroso"}
MultiLanguageQuestData['mx'][13756] = {title = "El gran combate cuerpo a cuerpo", objective = "Llévale 3 marcas del Valeroso a Ranii en los Campos del Torneo Argenta.\n\nSi pierdes tu lanza, puedes coger otra de cualquier expositor de lanzas que hay cerca de los establos o en el Pabellón de El Pacto de Plata.", description = "El gran combate cuerpo a cuerpo es la competición más importante del torneo. El pueblo de El Exodar espera tener noticias de nuestro éxito. A tal fin, han perfeccionado sus habilidades contra los valerosos que representan a las demás capitales de la Alianza.\n\nSugiero que hagas lo mismo.\n\nVe a los establos que hay fuera del pabellón, equipa tu lanza, monta el elekk de Bruma Azur de establo y desafía a los valerosos. Aguardan en La Liza de los Valerosos de la Alianza que hay justo al salir de nuestra tienda.", progress = "¿Has terminado tu instrucción para el gran combate cuerpo a cuerpo?", completion = "Bien hecho. Entrenar con otros valerosos es una de las mejores maneras de prepararte para la competición del torneo. Sé que serás motivo de orgullo para nuestro pueblo, &lt;nombre&gt;.", rewards = "Te van a lanzar el siguiente hechizo:\n\nQuitar lanza\n\nRecibirás:\n\nSello de valerosoObjeto #1"}
MultiLanguageQuestData['mx'][13757] = {title = "Una espada de Campeón", objective = "Recupera la espada de Lago Fresno y llévasela a Jaelyne Unicanto en los Campos del Torneo Argenta.", description = "El buen acero afilado y honesto no triunfa. Los demás combatientes usan espadas encantadas y estoy en desventaja, pero aún hay esperanza.\n\nCuenta una antigua leyenda de las Colinas Pardas que hay una doncella bajo el aspecto de una rana que protege la espada que tanto tiempo lleva custodiando. Vive entre las ranas de lago a las orillas del Lago Fresno, al este del Puesto Fresno. Cuentan que solo un beso voluntarioso puede romper la maldición. Ponte este cacao antes de besar nada, <nombre>, si no te saldrán pupas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valerosoObjeto #1"}
MultiLanguageQuestData['mx'][13758] = {title = "Un arma digna", objective = "Lleva la hoja de Drak'Mar a Jaelyne Unicanto en los Campos del Torneo Argenta.", description = "¡Maldita sea mi suerte! ¡He perdido mi espada!\n\nHe oído que los bardos cuentan historias de viajantes que ofrecían jacintos de invierno a una doncella solitaria a cambio de obsequios. Esos jacintos solo crecen en el hielo de la Presa del Muro de Hierro, en el extremo noroeste del Bosque Canto de Cristal que limita con Corona de Hielo. Recoge las flores y llévalas al círculo de luces del Lago Drak'Mar al noreste del Cementerio de Dragones, cerca de Zul'Drak y las Colinas Pardas. Pídele a la doncella solitaria una espada digna.\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valerosoObjeto #4"}
MultiLanguageQuestData['mx'][13759] = {title = "El Filo del invierno", objective = "Jaelyne Unicanto en los Campos del Torneo Argenta quiere que le lleves Filoinvierno.", description = "Es la última vez que entreno con un caballero de la Muerte.\n\nAl sur del Bosque Canto de Cristal, vigilando la salida hacia el Vicio de Cristal está Lord Llama Perpetua. Mátalo y toma su ascua de llama perpetua.\n\nLlévala al centro del Lago Aliento Invernal, en la parte norte del Fiordo Aquilonal y úsala para liberar a la doncella encerrada en hielo. Es la guardiana de una espada ancestral y recompensará a su libertad<or/ora>.\n\nDemuestra tu valía y consigue la espada que ha estado custodiando durante tanto tiempo, <nombre>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valerosoObjeto #1"}
MultiLanguageQuestData['mx'][13760] = {title = "Instrucción en el campo de un Valeroso", objective = "Illestria Rugefilo en los Campos del Torneo Argenta quiere que mates a 10 héroes transformados.", description = "El torneo es el lugar para probar tus habilidades contra tus semejantes, pero no tenemos que olvidarnos de que el enemigo real, la Plaga, no se va a quedar de brazos cruzados. Mientras perfeccionas tus habilidades contra otros, sigue combatiendo al enemigo.\n\nViaja al área que hay al suroeste de El Valle de los Héroes Caídos y al norte de Corp'rethar. Allí, la Plaga resucita héroes muertos y los vuelve en nuestra contra. Derrota a esos esbirros de la Plaga, honra a nuestros aliados y prepárate para el combate.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valeroso"}
MultiLanguageQuestData['mx'][13761] = {title = "El gran combate cuerpo a cuerpo", objective = "Llévale 3 marcas del Valeroso a Airae Buscaestelar en los Campos del Torneo Argenta.\n\nSi pierdes tu lanza, puedes coger otra de cualquier expositor de lanzas que hay cerca de los establos o en el Pabellón de El Pacto de Plata.", description = "El gran combate cuerpo a cuerpo es la competición más importante del torneo. El pueblo de Darnassus espera tener noticias de nuestro éxito. A tal fin, han estado perfeccionando sus habilidades contra los valerosos que representan a las otras capitales de la Alianza.\n\nSugiero que hagas lo mismo.\n\nLa Liza de los Valerosos de la Alianza está justo al salir de nuestra tienda. Ve a los establos al salir del pabellón, equipa tu lanza, monta el sable de la Niebla darnassiano de establo y desafía a los valerosos.Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nQuitar lanza\n\nRecibirás:\n\nSello de valerosoObjeto #1"}
MultiLanguageQuestData['mx'][13762] = {title = "Una espada de Campeón", objective = "Recupera la espada de Lago Fresno y llévasela a Mokra el Trituracráneos en los Campos del Torneo Argenta.", description = "He oído que los campeones de la Alianza están buscando espadas antiguas para sus guerreros. No podemos permitir que obtengan semejante ventaja.\n\nCuenta una antigua leyenda de las Colinas Pardas que hay una doncella bajo el aspecto de una rana que protege la espada que tanto tiempo lleva custodiando. Vive entre las ranas de lago a las orillas del Lago Fresno, al este del Puesto Fresno. Cuentan que solo un beso voluntarioso puede romper la maldición. Ponte este cacao antes de besar nada, <nombre>, si no te saldrán pupas.", progress = "¿Pudiste conseguir la espada?", completion = "Así que la leyenda era cierta. Esta espada debería bastar para superar cualquier cosa con la que esos contendientes de la Alianza se presenten.", rewards = "Recibirás:\n\nSello de valerosoObjeto #1"}
MultiLanguageQuestData['mx'][13763] = {title = "Un arma digna", objective = "Lleva la hoja de Drak'Mar a Mokra el Trituracráneos en los Campos del Torneo Argenta.", description = "¡Maldita sea mi suerte!\n\n¡He perdido la espada del torneo! He oído que los bardos cuentan historias de viajantes que ofrecían jacintos de invierno a una doncella solitaria a cambio de obsequios. Esos jacintos solo crecen en el hielo de la Presa del Muro de Hierro, en el extremo noroeste del Bosque Canto de Cristal que limita con Corona de Hielo. Recoge las flores y llévalas al círculo de luces del Lago Drak'Mar al noreste del Cementerio de Dragones, cerca de Zul'Drak y las Colinas Pardas. Pídele a la doncella solitaria una espada digna.\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valerosoObjeto #4"}
MultiLanguageQuestData['mx'][13764] = {title = "El Filo del invierno", objective = "Mokra el Trituracráneos en los Campos del Torneo Argenta quiere que le lleves Filoinvierno.", description = "¡Maldito sea ese caballero de la Muerte por romper mi espada!\n\nAl sur del Bosque Canto de Cristal, vigilando la salida hacia el Vicio de Cristal está Lord Llama Perpetua. Mátalo y toma su ascua de llama perpetua.\n\nLlévala al centro del Lago Aliento Invernal, en la parte norte del Fiordo Aquilonal y úsala para liberar a la doncella encerrada en hielo. Es la guardiana de una espada ancestral y recompensará a su libertad<or/ora>.\n\nDemuestra tu valía y consigue la espada que ha estado custodiando durante tanto tiempo, <nombre>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valeroso"}
MultiLanguageQuestData['mx'][13765] = {title = "Instrucción en el campo de un Valeroso", objective = "Akinos en los Campos del Torneo Argenta quiere que mates a 10 héroes transformados.", description = "El torneo es el lugar para probar tus habilidades contra tus semejantes, pero no tenemos que olvidarnos de que el enemigo real, la Plaga, no se va a quedar de brazos cruzados. Mientras perfeccionas tus habilidades contra otros, sigue combatiendo al enemigo.\n\nViaja al área que hay al suroeste de El Valle de los Héroes Caídos y al norte de Corp'rethar. Allí, la Plaga resucita héroes muertos y los vuelve en nuestra contra. Derrota a esos esbirros de la Plaga, honra a nuestros aliados y prepárate para el combate.", progress = nil, completion = "Un buen día de entrenamiento no le hace daño a nadie. Me alegro de ver que sigues el ritmo.", rewards = "Recibirás:\n\nSello de valeroso"}
MultiLanguageQuestData['mx'][13766] = {title = "El cierre es algo natural", objective = "Utiliza la rama de Gnarl para cerrar 10 puertas demoníacas.", description = "Puedo sentir a través de la tierra cómo traen a más demonios a nuestro mundo. Pronto habrá demasiados y nos arrasarán sin esperanza de volver atrás.\n\nToma este pedazo de mí y vuelve al Barranco del Demonio y a la Cresta del Demonio, al sur de Cerro Lumbrevil. Apunta con la rama a la puerta demoníaca y concéntrate. He almacenado una porción de la vida del bosque en su madera y cerrará la puerta.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][13767] = {title = "El gran combate cuerpo a cuerpo", objective = "Llévale 3 marcas del Valeroso a Morah Hermana de Huargos en los Campos del Torneo Argenta.\n\nSi pierdes tu lanza, puedes coger otra de cualquier expositor de lanzas que hay cerca de los establos o en el Pabellón Atracasol.", description = "El gran combate cuerpo a cuerpo es la competición más importante del torneo. La victoria no será fácil, pero confío en que ganaremos. Debes practicar con tu montura hasta que los dos sean uno.\n\nTe ayudará a prepararte para los rigores del combate en el torneo.\n\nVe a los establos que hay fuera del pabellón, equipa tu lanza, monta el lobo de Orgrimmar de establo y desafía a los valerosos. Aguardan en La Liza de los Valerosos de la Horda que está justo al salir de nuestra tienda.", progress = "¿Has terminado tu instrucción para el gran combate cuerpo a cuerpo?", completion = "Entrenar con otros valerosos te ayudará a afilar las garras y a perfeccionar tus instintos de batalla. Cuando empiece la competición, estarás lista.", rewards = "Te van a lanzar el siguiente hechizo:\n\nQuitar lanza\n\nRecibirás:\n\nSello de valerosoObjeto #1"}
MultiLanguageQuestData['mx'][13768] = {title = "Una espada de Campeón", objective = "Recupera la espada de Lago Fresno y llévasela a Zul'tore en los Campos del Torneo Argenta.", description = "He oído que los campeones de la Alianza están buscando espadas antiguas para sus guerreros. No podemos permitir que obtengan semejante ventaja.\n\nCuenta una antigua leyenda de las Colinas Pardas que hay una doncella bajo el aspecto de una rana que protege la espada que tanto tiempo lleva custodiando. Vive entre las ranas de lago a las orillas del Lago Fresno, al este del Puesto Fresno. Cuentan que solo un beso voluntarioso puede romper la maldición. Ponte este cacao antes de besar nada, <nombre>, si no te saldrán pupas.", progress = "¿Pudiste conseguir la espada?", completion = "Así que la leyenda era cierta. Esta espada debería bastar para superar cualquier cosa con la que esos contendientes de la Alianza se presenten.", rewards = "Recibirás:\n\nSello de valerosoObjeto #1"}
MultiLanguageQuestData['mx'][13769] = {title = "Un arma digna", objective = "Lleva la hoja de Drak'Mar a Zul'tore en los Campos del Torneo Argenta.", description = "¡Maldita sea mi suerte!\n\n¡He perdido la espada del torneo! He oído que los bardos cuentan historias de viajantes que ofrecían jacintos de invierno a una doncella solitaria a cambio de obsequios. Esos jacintos solo crecen en el hielo de la Presa del Muro de Hierro, en el extremo noroeste del Bosque Canto de Cristal que limita con Corona de Hielo. Recoge las flores y llévalas al círculo de luces del Lago Drak'Mar al noreste del Cementerio de Dragones, cerca de Zul'Drak y las Colinas Pardas. Pídele a la doncella solitaria una espada digna.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valerosoObjeto #4"}
MultiLanguageQuestData['mx'][13770] = {title = "El Filo del invierno", objective = "Zul'tore en los Campos del Torneo Argenta quiere que le lleves Filoinvierno.", description = "¡Maldito sea ese caballero de la Muerte por romper mi espada!\n\nAl sur del Bosque Canto de Cristal, vigilando la salida hacia el Vicio de Cristal está Lord Llama Perpetua. Mátalo y toma su ascua de llama perpetua.\n\nLlévala al centro del Lago Aliento Invernal, en la parte norte del Fiordo Aquilonal y úsala para liberar a la doncella encerrada en hielo. Es la guardiana de una espada ancestral y recompensará a su libertad<or/ora>.\n\nDemuestra tu valía y consigue la espada que ha estado custodiando durante tanto tiempo, <nombre>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valerosoObjeto #1"}
MultiLanguageQuestData['mx'][13771] = {title = "Instrucción en el campo de un Valeroso", objective = "El cazador de las Sombras Mezil-kree en los Campos del Torneo Argenta quiere que mates a 10 héroes transformados.", description = "El torneo es el lugar para probar tus habilidades contra tus semejantes, pero no tenemos que olvidarnos de que el enemigo real, la Plaga, no se va a quedar de brazos cruzados. Mientras perfeccionas tus habilidades contra otros, sigue combatiendo al enemigo.\n\nViaja al área que hay al suroeste de El Valle de los Héroes Caídos y al norte de Corp'rethar. Allí, la Plaga resucita héroes muertos y los vuelve en nuestra contra. Derrota a esos esbirros de la Plaga, honra a nuestros aliados y prepárate para el combate.", progress = nil, completion = "Un buen día de entrenamiento no le hace daño a nadie. Me alegro de ver que sigues el ritmo.", rewards = "Recibirás:\n\nSello de valeroso"}
MultiLanguageQuestData['mx'][13772] = {title = "El gran combate cuerpo a cuerpo", objective = "Llévale 3 marcas del Valeroso a Gahju en los Campos del Torneo Argenta.\n\nSi pierdes tu lanza, puedes coger otra de cualquier expositor de lanzas que hay cerca de los establos o en el Pabellón Atracasol.", description = "El gran combate cuerpo a cuerpo es la competición más importante del torneo. La victoria no será fácil, pero confío en que ganaremos. Debes practicar con tu montura hasta que los dos sean uno.\n\nTe ayudará a prepararte para los rigores del combate en el torneo.\n\nVe a los establos que hay fuera del pabellón, equipa tu lanza, monta el raptor Lanza Negra de establo y desafía a los valerosos. Aguardan en La Liza de los Valerosos de la Horda que está justo al salir de nuestra tienda.", progress = "¿Has terminado tu instrucción para el gran combate cuerpo a cuerpo?", completion = "Entrenar con otros valerosos te ayudará a aprender rápidamente lo que tienes que saber para vencerlos. Mantén el ritmo y no tendrás ningún tipo de problema para derrotarlos en la competición.", rewards = "Te van a lanzar el siguiente hechizo:\n\nQuitar lanza\n\nRecibirás:\n\nSello de valerosoObjeto #1"}
MultiLanguageQuestData['mx'][13773] = {title = "Una espada de Campeón", objective = "Recupera la espada de Lago Fresno y llévasela a Runok Ferocrín en los Campos del Torneo Argenta.", description = "He oído que los campeones de la Alianza están buscando espadas antiguas para sus guerreros. No podemos permitir que obtengan semejante ventaja.\n\nCuenta una antigua leyenda de las Colinas Pardas que hay una doncella bajo el aspecto de una rana que protege la espada que tanto tiempo lleva custodiando. Vive entre las ranas de lago a las orillas del Lago Fresno, al este del Puesto Fresno. Cuentan que solo un beso voluntarioso puede romper la maldición. Ponte este cacao antes de besar nada, <nombre>, si no te saldrán pupas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSello de valerosoObjeto #1"}
