MultiLanguageQuestData['mx'][14175] = {title = "Los muertos agradecidos", objective = "Consigue pan de muerto y dáselo al espíritu de orco alegre en el cementerio de Orgrimmar.\n\nUsa una flor de muerto naranja para ver al espíritu que sin ella sería invisible.", description = "Es genial volver a visitar a la familia y a los amigos, pero puede que me haya pasado... ¡Ya me he comido todo lo que me han preparado!\n\n¿Puedes tomarte la molestia de conseguirme un poco más de ese delicioso pan de muerto? Estaría muy agradecido...\n\nCreo que Buhonero vende la receta allí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14176] = {title = "Los muertos agradecidos", objective = "Consigue pan de muerto y dáselo al espíritu de tauren alegre en el cementerio de Cima del Trueno.\n\nUsa una flor de muerto naranja para ver al espíritu que sin ella sería invisible.", description = "Es genial volver a visitar a la familia y a los amigos, pero puede que me haya pasado... ¡Ya me he comido todo lo que me han preparado!\n\n¿Puedes tomarte la molestia de conseguirme un poco más de ese delicioso pan de muerto? Estaría muy agradecido...\n\nCreo que Buhonero vende la receta allí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14177] = {title = "Los muertos agradecidos", objective = "Consigue pan de muerto y dáselo al espíritu de trol alegre en el cementerio de Orgrimmar.\n\nUsa una flor de muerto naranja para ver al espíritu que sin ella sería invisible.", description = "Es genial volver a visitar a la familia y a los amigos, pero puede que me haya pasado... ¡Ya me he comido todo lo que me han preparado!\n\n¿Puedes tomarte la molestia de conseguirme un poco más de ese delicioso pan de muerto? Estaría muy agradecido...\n\nCreo que Buhonero vende la receta allí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14178] = {title = "Llamamiento a las armas: Cuenca de Arathi", objective = "Gana un encuentro en el campo de batalla de la Cuenca de Arathi y vuelve a ver a un general de brigada de la Alianza en cualquier capital de la Alianza, Conquista del Invierno, Dalaran o Shattrath.", description = "La realidad de luchar en varios frentes, <chico/chica>, es que, si repartimos demasiado nuestras tropas, nos arriesgamos a perderlo todo.\n\nA diario son necesarios despliegues críticos de las tropas. Hoy es la batalla de la Cuenca de Arathi la que necesita refuerzos inmediatos.\n\n¡Tráeme noticias de nuestra victoria, <nombre>! ¡No podemos permitir que la escoria de la Horda consiga los recursos que nos pertenecen por derecho!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPuntos de arena"}
MultiLanguageQuestData['mx'][14179] = {title = "Llamamiento a las armas: Ojo de la Tormenta", objective = "Gana un encuentro en el campo de batalla del Ojo de la Tormenta y vuelve a ver a un general de brigada de la Alianza en cualquier capital de la Alianza, Conquista del Invierno, Dalaran o Shattrath.", description = "La lucha contra la Horda no entiende de límites, <nombre>. Incluso en Terrallende, las disputas territoriales y las antiguas rencillas bastan para inclinar la balanza hacia el lado de la guerra.\n\nVe al Ojo de la Tormenta y asegúrate de que la Alianza prevalece en Terrallende tal y como lo ha hecho en Azeroth.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14180] = {title = "Llamamiento a las armas: Garganta Grito de Guerra", objective = "Gana un encuentro en el campo de batalla de la Garganta Grito de Guerra y vuelve a ver a un general de brigada de la Alianza en cualquier capital de la Alianza, Conquista del Invierno, Dalaran o Shattrath.", description = "Los Centinelas Ala de Plata luchan para proteger el bosque en la Garganta Grito de Guerra. Les ayudamos, no porque seamos amantes de los árboles, sino porque el bosque forma una barrera protectora natural para el territorio de la Alianza.\n\nHoy nos necesitan más que nunca. Tenemos que desplegar refuerzos inmediatamente, ¡a menos que queramos ver Vallefresno fusionado con Los Baldíos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14181] = {title = "Llamamiento a las armas: Cuenca de Arathi", objective = "Gana un encuentro en el campo de batalla de la Cuenca de Arathi y vuelve a ver a un belisario de la Horda en cualquier capital de la Horda, Conquista del Invierno, Dalaran o Shattrath.", description = "¡La Cuenca de Arathi está a punto de caer en manos de las tropas de la Alianza! Debemos enviar refuerzos en este mismo instante o todos nuestros esfuerzos habrán sido en vano.\n\nNo te retrases, <clase>. Ve a la Cuenca de Arathi y aplasta al enemigo. ¡Victoria para la Horda!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14182] = {title = "Llamamiento a las armas: Ojo de la Tormenta", objective = "Gana un encuentro en el campo de batalla del Ojo de la Tormenta y vuelve a ver a un belisario de la Horda en cualquier capital de la Horda, Conquista del Invierno, Dalaran o Shattrath.", description = "Lucharemos y aplastaremos al enemigo allí donde lo encontremos. Azeroth, Terrallende, el lugar da lo mismo.\n\nNo podemos permitir a la Alianza que establezca su superioridad en el Ojo de la Tormenta. ¡Lleva la batalla ante ellos hoy, mañana puede ser demasiado tarde!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14183] = {title = "Llamamiento a las armas: Garganta Grito de Guerra", objective = "Gana un encuentro en el campo de batalla de la Garganta Grito de Guerra y vuelve a ver a un belisario de la Horda en cualquier capital de la Horda, Conquista del Invierno, Dalaran o Shattrath.|n", description = "La Alianza es un enemigo insidioso, <nombre>. Dice que protege Vallefresno para justificar sus agresiones contra nuestros territorios en Los Baldíos.\n\nHoy tenemos la oportunidad de echar al enemigo de nuestras tierras de una vez por todas. ¡Ve a la Garganta Grito de Guerra y recupera lo que nos pertenece por derecho!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14184] = {title = "Se acabó mi tiempo", objective = "Furien, de Tethris Aran, quiere que montes su dracohalcón hasta el Puesto de Furien e informes a su hermana Cerelia de su muerte.", description = "<Furien te hace señas débilmente para que te acerques e intenta hablar.>\n\nDescuidado... he sido abatido por el fuego de la Alianza...\n\nDebes... informar a mi hermana.\n\nCoge mi montura, <raza>... te llevará hasta ella...\n\n<Furien fenece.>", progress = nil, completion = "¿¡Qué!?\n\n¡¡Furien!! ¿Mi hermano ha fallecido?\n\n¡Lo pagarán! ¡Todos ellos!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14188] = {title = "¡Vengar a Furien!", objective = "Cerelia quiere que hables con Sorrem en el Puesto de Furien.", description = "¡No puede ser!\n\nMi querido hermano... ¡asesinado por la escoria de la Alianza!\n\n¡Hay que hacerles sufrir, <raza>! ¡Encuentra la forma de infligirles dolor! No descansaré hasta que lo paguen...\n\nFurien había estado investigando artefactos antiguos en las regiones del este antes de morir. Habla con Sorrem, quizás te pueda informar sobre los pasos que dio mi hermano.", progress = nil, completion = "El óbito de Furien es... lamentable.\n\nDebo hacer todo lo posible para ayudarte a vengar su muerte.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14189] = {title = "La traducción", objective = "Sorrem quiere que encuentres las tablillas antiguas.\n\nHabla con Narimar en el Puesto de Furien para viajar al lugar donde Furien realizaba sus estudios.\n\nObjeto provisto: \n", description = "Es cierto que Furien dedicó sus últimos días a un proyecto de investigación especial. No compartió conmigo de qué se trataba.\n\nAfortunadamente, pude recuperar su diario, pero está codificado y no lo he podido descifrar.\n\nQuizás haya pistas de cómo traducirlo en la región situada en el este, donde solía pasar el tiempo.\n\nToma el diario, <clase>, y habla con Narimar cuando estés <listo/lista> para investigar este misterio.", progress = nil, completion = "Si comparamos los caracteres de las tabillas antiguas con los del diario de Furien, queda claro que existe una correlación entre ellos.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14190] = {title = "El prisma perfecto", objective = "Consigue un colgante de cristal de un saboteador de Talrendis en la Cantera de la Ladera.", description = "Tiene que haber alguna forma de invertir la petrificación de los basiliscos. Esos irritantes saboteadores elfos de la noche que han estado merodeando por mi mina deben saber algo que nosotros no sepamos. ¡Parecen inmunes a la mirada de la bestia!\n\nQuiero descubrir su secreto, <nombre>. Elige unos cuantos de los saboteadores de Talrendis que merodean por la cantera y consigue una muestra del talismán o ding-dong que llevan para darles inmunidad. Infórmame por radio desde el edificio de la forja principal cuando hayas tenido éxito.", progress = "<Los extraños altavoces goblin silban y chasquean.>", completion = "&lt;La voz de Cuatrobitzip suena por los altavoces.&gt;\n\n¿Eres tú, &lt;nombre&gt;? ¿Sigues con vida? ¿No estás jugando con mis reservas de explosivos, no?\n\nHmmm... dices que encontraste un pendiente con un cristal claro. Tiene sentido. Un prisma perfecto podría refractar la mirada del basilisco. Puede que podamos sacarle provecho. ¡Hora de tirar de la ciencia!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14191] = {title = "Los pasos de Furien", objective = "Las tablillas antiguas del Santuario de Elune te han conducido a tres de las ruinas preeminentes de Sargeron.", description = "Has podido descifrar algunos trozos y fragmentos del texto, pero, para que el trabajo de Furien cobre coherencia, habría que realizar un estudio exhaustivo del mismo.\n\nDe momento, te encuentras en el noreste y te parece distinguir algunas de las ruinas descritas en el diario.\n\nPor lo que puedes deducir, estas ruinas parecen haber sido algo importantes para la investigación de Furien.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][14192] = {title = "Rompeprisma", objective = "Lleva el colgante de cristal al armario de armas en el Centro de Mando de la Cantera de la Ladera.", description = "Si ese prisma que tienes está afinado para que refracte la mirada del basilisco, podemos utilizar las propiedades del cristal para invertir el proceso. Lo único que necesitamos es una fuente de poder.\n\nEn el armario de armas que tienes a la derecha encontrarás nuestro prototipo de perforadora láser. Me encantaba esa cosa, pero los desmembramientos casi a diario se convirtieron en un problema. Agarra la perforadora láser e invierte ese cristal...", progress = "<El armario de armas está lleno de dispositivos experimentales atroces y rotos, algunos de ellos con miembros goblin aún adheridos. Descubres la perforadora láser cuidadosamente guardada en una caja de madera con funda de terciopelo.>", completion = "&lt;Sacas la unidad de lente y colocas el cristal en su lugar. El arma zumba inquietantemente.&gt;", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14193] = {title = "Nada que no puedan arreglar un par de melones", objective = "Recoge 8 melones.", description = "Las marcas de estas ruinas aclaran una cosa: hay algo especial en la antigua fuente del Santuario de Elune.\n\nParece que se podrían obtener poderes especiales al lavarte la cara en la fuente. Claro que, primero, debería haber algo en la antigua fuente con qué lavársela.\n\nSopesando este problema, localiza algunos melones bajo algún árbol cercano...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #8"}
MultiLanguageQuestData['mx'][14194] = {title = "Recarnificación", objective = "Utiliza el Recarnificador para despetrificar ocho mineros de ladera dentro de la Cantera de la Ladera.", description = "<La radio cercana te llama.>\n\nEy, <nombre>, ¿conseguiste la pistola? ¡Bien! No te apuntes directamente al ojo.\n\nApunta a mis trabajadores petrificados y la luz refractada debería revertir el proceso de petrificación. O los fundirá. Da igual. ¡Devuelve a mis trabajadores a un estado de rentabilidad! Y si el proceso de recarnificación los vuelve locos, debes matarlos por temas del seguro. ¡Horzak FUERA!", progress = "Oye, mira, tienes las extremidades intactas.", completion = "Bien. Ahora podemos devolver esos holgazanes al trabajo. Te has ganado una parte de los beneficios, menos las tasas habituales de la compañía. ¡Toma tu parte!", rewards = "Brazales recarnificadosPistola petrificadoraRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14195] = {title = "Todo se va aclarando", objective = "El diario de Furien te ha conducido al Palacio de Elune en ruinas en el norte de Sargeron.", description = "Algo ha cambiado... quizás sea un efecto secundario del ritual de limpieza de Elune.\n\nAunque aún no sea perfecta, tu comprensión de la lengua antigua del diario ha mejorado de forma significativa.\n\nLas ruinas de las montañas de Sargeron del norte parecen ser la fuente del entusiasmo de Furien porque percibió que allí había algo que le ayudaría a expulsar a la Alianza de esta región.\n\nCierras el diario <decidido/decidida> a encontrar las ruinas y a desentrañar sus secretos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14196] = {title = "La tormenta de fuego", objective = "Crea un vórtice enfurecido al derrotar a 7 discípulos de Elune durante la tormenta de Fuego.\n\nSi pierdes la gema de vórtice, podrás conseguir otra en la piedra rúnica del vórtice antigua.", description = "Ahora eres capaz de entender la escritura en la que está redactado el diario.\n\nEn la piedra rúnica se explica que las gemas del monumento estaban imbuidas de energía para invocar una tormenta de Fuego.\n\nLa tormenta podría convertirse en un arma poderosa si se adora constantemente a Elune o si se carga con energía espiritual de los caídos.\n\nMiras con desprecio a los nuevos espíritus de los discípulos de Elune, concluyes que no tienes el tiempo ni el deseo de venerar a la diosa de tu enemigo...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14197] = {title = "Una cuota que cumplir", objective = "Reúne 20 lingotes de hierro de ladera de la Cantera de la Ladera en Azshara.", description = "El hierro de ladera es una aleación frágil, pero con los trucos adecuados se ajusta a los estándares de seguridad de los goblins. Cuatrobitzip está teniendo problemas con la producción, pero eso no cambia ninguno de mis plazos. ¡Tengo una cuota que cumplir!\n\nDirígete a la Cantera de la Ladera y reúne lingotes de hierro de ladera cuando los encuentres. Debería haber montones de ellos pulidos y listos para el envío.", progress = "¿Recibiste mi envío?", completion = "¡Bien hecho! Cuando se trata de hierro, mejor siempre cantidad que calidad.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14198] = {title = "El jinete de la tormenta", objective = "Utiliza la gema de vórtice enfurecido en las ruinas de Punta de Nijel. Cuando invoques la tormenta de Fuego, mata a 40 defensores de Punta de Nijel y prende fuego a 15 mercaderes de Punta de Nijel.\n\nSi pierdes la gema de vórtice enfurecido, podrás conseguir otra en la piedra rúnica de vórtice antigua.", description = "No puedes evitar sentir una pizca de orgullo al haber desvelado el secreto perdido de los antiguos veneradores de Elune.\n\nAhora posees el poder para infligir un gran daño a tus enemigos.\n\nComo fue el trabajo incansable de Furien lo que ha hecho esto posible, solo parece justo liberar el arma contra aquellos que le quitaron la vida.\n\n¡La escoria de la Alianza en Punta de Nijel pagará por sus ofensas contra la Horda!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Capa de dedos diestrosPodrás elegir una de estas recompensas:\n\nObjeto #1Tranquilidad de FurienCollera fuego rápido\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][14199] = {title = "Prueba de defunción: El Caballero Negro", objective = "El archimago Lan'dalock en Dalaran quiere que le lleves un fragmento de alma del Caballero Negro.\n\nEsta misión solo puede realizarse en dificultad heroica.", description = "Mi homólogo, el archimago Tiemporeja, me ha pedido que te avise de algo terrible. Pronto participarás en la Prueba del Campeón en el Coliseo Argenta de Corona de Hielo. Ten cuidado con la intromisión de aquel al que llaman el Caballero Negro.\n\nTráeme un fragmento de su alma para que el Kirin Tor sepa que nos hemos encargado de él. Me han dicho que si fracasas será tu ruina.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPuntos de justiciaEmblema de triunfo"}
MultiLanguageQuestData['mx'][14201] = {title = "Mil historias en la arena", objective = "Consigue 5 artefactos recuperados en las ruinas que rodean el Lago Mennar en Azshara.", description = "Las ruinas que rodean el Lago Mennar, situado al este, narran una historia. Las razas inferiores, como esos enanos torpes, intentarían averiguar la verdad con picos y palas. <Malynea arruga la nariz.> Pero nosotros utilizaremos métodos más sofisticados.\n\nMi magia de visión está algo desgastada pero debería ser capaz desvelar los misterios del tiempo con el artefacto adecuado. Hace mucho que se han deshecho los huesos de mis antepasados, pero aún perduran algunos de sus tesoros personales. Tráeme unos cuantos.", progress = "¿Te has ensuciado las manos por mí?", completion = "&lt;Malynea arruga la frente y empieza a escudriñar los artefactos que le has traído.&gt;\n\nAsí que, los espíritus de los muertos aún rondan por esas viejas rocas, ¿eh? Bueno, &lt;nombre&gt;, da la casualidad de que cuento con su ayuda. Veamos lo que tienen que decir los muertos...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14202] = {title = "Peritaje en el lago", objective = "Escolta a una perita goblin hasta las tres piezas de equipo de perito que rodean el Lago Mennar y defiéndela mientras hace un registro. Siempre podrás invocar a otro perito con la baliza de perito.", description = "Si queremos ser testigos del pleno potencial de Azshara, hay que demoler esas viejas ruinas inservibles. Mira este mapa de aquí; ¿ves el Lago Mennar en el este? Te diré lo que veo: ¡un futuro depósito de combustible para cohetes!\n\nPero antes necesitamos un diseño de la zona antes de poder despejar el lago, demolerlo, deshacernos de los desechos y pavimentarlo. Todos mis peritos han huido despavoridos de esos fantasmas que vagan por la zona. Escolta a uno de mis peritos principiantes hasta allí y haz un registro del equipo que se ha instalado.", progress = "Ningún puñado de elfos muertos podrá detener el progreso. ¡No en mi presencia!", completion = "¡Un trabajo magnífico! Ahora que conocemos mejor la zona, podemos construir un nuevo lago.", rewards = "Te van a lanzar el siguiente hechizo:\n\nQuest Complete\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14203] = {title = "Receta con marcas de agua", objective = "Llévale la receta con marcas de agua a Christi Stockton en la Ciudad de Dalaran.", description = "Parecen los restos de una potente mezcla de vinos. Igual le interesa a la propietaria de Una Copa Más en Dalaran...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14204] = {title = "Desde las sombras", objective = "Derrota a 6 rondadores Colmillo de Sangre.", description = "Se convirtió en uno de ellos... ¿no? ¿Cómo podemos siquiera enfrentarnos a un enemigo que puede hacernos esto?\n\nEl arsenal de mi padre es sin duda un buen comienzo, me atrevo a decir.\n\nLos huargen se esconden en los callejones de enfrente. Lleva a uno de mis mastines para encontrarlos con más facilidad.\n\nVamos a tener que despejar el camino que nos aguarda si queremos mover esos cañones por la calle.", progress = "¿Lo has hecho ya, <nombre>?", completion = "Excelente. Empezaré por reunir algo de ayuda para colocar esos cañones en posición.", rewards = "Maza del extiendealarmasBallesta del maestro de canesVarita de instructor de mastinesTe van a lanzar el siguiente hechizo:\n\nForce Dismiss\n\nRecibirás:\n\nBastón vetustoObjeto #1"}
MultiLanguageQuestData['mx'][14209] = {title = "Mugre en el motor", objective = "Inspecciona el bulldozer de Clubnik y recoge una muestra de la ectosalpicadura que está obstruyendo el motor.", description = "Esas ruinas antiguas han sobrevivido a diez mil años de viento y erosión, así que traeré mi mayor y mejor bulldozer para arrasarlas. Lo llamo \"Margene\".\n\nPero últimamente me ha decepcionado un poco, <nombre>. El momento en el que me adentré con él en ese bosque encantado, el motor se paró emitiendo un sonido espeluznante. Ahora, mis ingenieros me dicen que algo está obstruyendo las válvulas. Ve allí e inspecciona el compartimento del motor de Margene. Después, tráeme una muestra de la mugre que la haya atascado.", progress = "Margene es una pasada de máquina, ¿verdad?", completion = "¡Por todos los cojinetes de bolas! Mira esta cosa... ¡puaj! HUELE esta porquería... ¡mi pobre bulldozer!\n\n&lt;nombre&gt;, me considero un experto en viscosidades pero esta no es natural. Es sobrenatural. Es ectoplasma. Necesitaremos algo más que un mecánico...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14212] = {title = "Sacrificios", objective = "Viaja con Lord Darius Crowley y reúne hasta 30 acechadores Colmillo de Sangre.", description = "No tienes que hacer esto, <nombre>. Ya has hecho más que suficiente.\n\nPero si decides quedarte... Sería necio rechazarte.\n\nMis hombres han fortificado su posición en el interior de la catedral y están listos para lo que viene a continuación.\n\nEstoy a punto de salir para allí y llevarme conmigo a tantos de esos demonios pulgosos como pueda. Eres más que <bienvenido/bienvenida> en la excursión.", progress = nil, completion = "Prepárate para luchar, &lt;nombre&gt;.\n\nAhí vienen.", rewards = "Te van a lanzar el siguiente hechizo:\n\nUpdate Bind Post-Sacrifices\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14213] = {title = "10 kilos de carne", objective = "Recoge 10 trozos de carne de sátiro de los sátiros de Sargeron y colócalos en el blandón de Elune.", description = "Según el diario de Furien, este viejo blandón fue ubicado en este lugar para realizar sacrificios.\n\nDe lo que podemos descifrar de las anotaciones, se deduce que el ser que coloque la carne de los enemigos de Elune en las brasas encendidas del blandón será bendecido.\n\nSi observas a tu alrededor, comprobarás que los sátiros que dominan esta región serían perfectos para el sacrificio.Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nDotación divina\n\nTambién recibirás:\n\nObjeto #10"}
MultiLanguageQuestData['mx'][14214] = {title = "Mensaje para Cringris", objective = "Habla con el rey Genn Cringris en el Distrito Militar.", description = "Es la hora, <nombre>. Nosotros nos encargamos del resto.\n\nInforma al rey Cringris de que el arsenal de mi padre estará a su disposición. Hay pólvora más que suficiente para reventar todos los huargen de aquí al Mar del Norte.", progress = nil, completion = "Sabía que Crowley lo conseguiría. Sus armas nos serán de gran utilidad.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14215] = {title = "Recuerdos de los muertos", objective = "Lleva el anillo de Kalytha a la orilla del Lago Mennar. Toca el espíritu de Kalytha para rememorar su pasado. Habla con los demás espíritus hasta que desveles el secreto del Lago Mennar.", description = "Las runas del anillo que encontraste aún son legibles: \"Kalytha\" lo recibió cuando fue admitida en la Academia. Con el hechizo o los hechizos apropiados, este abalorio personal es la puerta que abre su alma.\n\nLleva el anillo de vuelta al Lago Mennar. Ahora deberías poder ver el espíritu de Kalytha en la orilla del lago. Tócala y el anillo te permitirá ver el mundo como ella lo ve, y rememorarás sus últimas horas de vida. ¡Explora su mente, <nombre>! Habla con los demás y desvela los secretos del Lago Mennar...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14216] = {title = "El misterio de la piedra sarcita", objective = "Recoge la piedra sarcita del fondo del Lago Mennar.", description = "Antes de morir, Kalytha tenía que enterrar algo en el fondo del lago. Un poderoso artefacto que crearon los archimagos de Mennar en sus últimos momentos. No hay duda de que Malynea Atracacielo querrá ver el artefacto, si es que aún existe. Decides buscar la piedra sarcita en el fondo del Lago Mennar.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Botas de aves fondasMalla de Mennaran restauradaRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14217] = {title = "Ofrendas satíricas", objective = "Recoge 10 trozos de carne de sátiro de los sátiros de Sargeron y colócalos en el blandón de Elune.", description = "Lo más gracioso, si lo piensas, es que esta antigua reliquia te confiera una bendición que fue creada en pro de tus enemigos.\n\nAun así, decides aprovechar todo lo posible este regalo involuntario.Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nDotación divina\n\nTambién recibirás:\n\nObjeto #10"}
MultiLanguageQuestData['mx'][14218] = {title = "Sangre y cenizas", objective = "Mata a 80 acechadores Colmillo de Sangre con los cañones rebeldes.", description = "Ha llegado la hora, <nombre>. Si queremos diezmar sus filas, este es el momento.\n\nTenemos la posición.\n\nTenemos la pólvora.\n\nSolo falta por ver si tenemos el valor... y estoy seguro de no tener cobardes ante mí.", progress = nil, completion = "Lo has hecho bien, &lt;nombre&gt;. Has hecho más de lo que podría haber pedido un gilneano.\n\nNos estamos quedando sin munición. Es hora de reagruparnos en el interior.", rewards = "Botas de determinación férreaLeotardos de cañoneroRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14219] = {title = "¡Haz bien sin mirar a quién!", objective = "Recoge 20 sables de sátiro de los expositores de armas y de varios sátiros de la zona. Después, colócalos sobre la estatua de las Fámulas de Elune.", description = "Reconoces de inmediato la estatua de un boceto del diario de Furien.\n\nAunque no consigues acordarte de las palabras asociadas a la anotación, el boceto parece explicarse por sí solo. Tras la batalla, las armas de los enemigos debían fundirse en un cuenco a cambio de algún tipo de don divino.\n\nMientras reflexionas sobre el ritual, el brillo de acero atrae tu mirada desde un expositor de armas...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Sandalias de ritualLoriga con ribeteFaja recónditaRecibirás:\n\nObjeto #20"}
MultiLanguageQuestData['mx'][14220] = {title = "Este es el fin", objective = "Recibirás:\n\nCuando completes esta misión ganarás:\n\n", description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14221] = {title = "¿Rendirse? Nunca. ¿Retirarse? A veces", objective = "Habla con Lord Darius Crowley en el interior de la Catedral del Alba.", description = "Teníamos munición suficiente para seguir otro mes con la guerra civil. Pero el número de huargen es tan grande que casi la hemos gastado.\n\nNo queremos que nos agarren aquí en terreno abierto cuando eso suceda. Ve al interior de la catedral e informa al jefe. Estoy seguro de que el viejo Crowley sabrá qué hacer a continuación.", progress = nil, completion = "Lo hemos dado todo... pero siguen viniendo. No te preocupes, &lt;nombre&gt;. Mataremos muchos más antes de que acabe el día.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14222] = {title = "Resistencia final", objective = "Mata 8 acechadores demenciados.", description = "Estamos en un buen cuello de botella, <nombre>. Reza un poco si te van esas cosas.\n\nSeamos valientes y matemos a esos chuchos.", progress = nil, completion = "Han... han detenido el ataque.\n\nNo, &lt;nombre&gt;. Eso no es nada bueno.", rewards = "Te van a lanzar el siguiente hechizo:\n\nReproducir película\n\nRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][14223] = {title = "Paz mental", objective = "Sorrem, del Puesto de Furien, quiere que mates a Kohor.", description = "Somos una avanzada que se encarga de vigilar enemigos potenciales. Cuando la Horda lance su campaña en Desolace, nuestro trabajo asegurará que no haya sorpresas.\n\nRecientemente, uno de nuestros exploradores fue capturado y sacrificado por el Filo Ardiente en su bastión situado en el oeste. Desde entonces, hemos recibido burlas y amenazas de un desgraciado del Filo Ardiente llamado Kohor.\n\nSus días están contados, ¡pero pagaré generosamente a quien le silencie desde ya!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14225] = {title = "Lo sabrás cuando lo veas", objective = "Sorrem, del Puesto de Furien, quiere que encuentres el ritual de invocación antiguo en la Fortaleza del Hacha de Trueno.", description = "Kohor habló en su último aliento de invocar a un demonio que podría amenazar a toda la región.\n\nPuede que se tirara un farol, pero no es un riesgo que merezca la pena correr.\n\nNo podemos esperar a que la invasión de Desolace por parte de la Horda tome forma. Debes registrar la Fortaleza del Hacha de Trueno en busca de pistas y acabar con esta amenaza potencial.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14226] = {title = "Pisoteando problemas", objective = "Utiliza tu ayudante Arcano personal para convertir a 12 demonios Legashi en insectos y aplastarlos.", description = "Mírate; haciendo recados. Es bastante responsable por tu parte. ¡Estás yendo hacia arriba, arriba, arriba!\n\n¡Pero, más adelante, hay demonios! Demonios de muchas clases desagradables. ¡Demonios que devorarían tus entrañas con mucho gusto! ¡Demonios Legashi que se dirigen al sureste! Pero no te preocupes. No, no. ¡No tienes por qué preocuparte porque tendrás compañía!\n\nApunta, insecta y aplasta. ¡Apunta, insecta y aplasta! Bastante eficaz y bastante sucio... pero, de nuevo, no te preocupes. No, no; ¡no te preocupes porque después no hay que limpiar!", progress = nil, completion = "&lt;El archimago Xylem parece estar realizando algún tipo de danza cuando se vuelve hacia ti.&gt;\n\nNo te apures, pero, desde luego, te asegures, de no dejar el zumo de insecto reposar, o mucho tendrás que lamentar... Bueno, ¡realmente lamentarás el olor de tus botas! ¡Hoy no olerán bien y mañana todavía menos!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14227] = {title = "Juntar cabezas", objective = "Recoge 100 calaveras blanquecinas en la Fortaleza del Hacha de Trueno, colócalas en el Círculo de Invocación del Filo Ardiente y después mata a Nazargen.", description = "Así que es cierto...\n\nEl pergamino que descubriste en la Fortaleza del Hacha de Trueno describe los detalles de un poderoso ritual de invocación. El más poderoso que sepamos que posee el Filo Ardiente.\n\n¡Debemos impedir que se celebre este rito a toda costa!\n\nQuizás, si invocáramos a este demonio antes de tiempo, evitaríamos la crisis.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Capa de calavera agostadaPodrás elegir una de estas recompensas:\n\nAnillo de interrupción vigorosaGargantilla derribadora\n\nTambién recibirás:\n\nDeprecated Dwarven Squire's Pants"}
MultiLanguageQuestData['mx'][14230] = {title = "Mano de obra", objective = "Consigue el manual de lego en el Campamento Legashi.", description = "Los demonios de la zona parecen divertirse robándonos todos los manuales Arcanos. Dudo bastante que la mayoría de ellos pueda leer, así que, probablemente lo hagan para fastidiarnos.\n\nLa mayoría de los libros que han robado no me interesa especialmente, pero voy a necesitar el manual de lego si quiero que <los/las> aprendices como tú sobrevivan a las \"pruebas\" de Xylem. Busca a los demonios en el Campamento Legashi, situado al sureste, y consigue el manual de lego.\n\nEso es todo. Márchate.", progress = "Y aquí estás... de nuevo... hablando conmigo otra vez. Imagino que eso significa que tienes mi libro, ¿no?", completion = "Genial. Volvamos al trabajo.\n\nGracias, cariñín.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14231] = {title = "Useless quest record", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][14232] = {title = "Las orejas de Filo Ardiente", objective = "Lleva 25 orejas de Filo Ardiente a Sorrem en el Puesto de Furien.", description = "Sorrem no ha ocultado su desdén por el Filo Ardiente de la Fortaleza del Hacha de Trueno.\n\nSeguramente, la prueba de su muerte le resultarÍa valiosa.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14239] = {title = "¡No vayas hacia la Luz!", objective = "Ahora depende de ti. ¿Vas a regresar con vida y convertirte en el héroe que los supervivientes necesitan que seas o vas a quedarte aquí durante el resto de tus días?\n\nLa decisión depende de ti.\n\n¡No vayas hacia la Luz, <nombre>!Te van a lanzar el siguiente hechizo:\n\n", description = nil, progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nDon't Go Into The Light!: Quest Complete\n\nRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][14246] = {title = "Adopción prematura", objective = "Coloca 3 huevos de aguilón en los nidos de aguilón y protégelos hasta que los recojan.", description = "A medida que la región se vuelve más exuberante, las criaturas del desierto se ven confinadas a espacios cada vez más reducidos.\n\nLa extinción inminente de los aguilones locales es una consecuencia bastante angustiosa. Los depredadores se dan festines de los pájaros y sus huevos cuando encuentran sus nidos.\n\nHe conseguido algunos huevos de aguilón de Tanaris y los he rociado con una feromona irresistible. Coloca uno en cada nido que encuentres y protégelo hasta que llegue un aguilón se lo lleve.\n\nPrestarás un gran servicio al equilibrio de esta tierra.", progress = nil, completion = "Bien hecho, &lt;clase&gt;.\n\nEsta tierra está en deuda contigo.", rewards = "Leotardos plumaligeraGuanteletes acolchados del coleccionistaRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14247] = {title = "Tierras testarudas", objective = "Thunk, de la Morada de Thunk, quiere que encuentres el afloramiento antinatural.", description = "Por la autoridad del Círculo Cenarion, se me ordenó convertir estas ásperas tierras en una pradera exuberante.\n\nLas tierras situadas al sur de aquí han acogido el crecimiento, pero hay algo que lo está combatiendo y se resiste al reabastecimiento.\n\nQuizás tus ojos tengan más éxito que los míos.\n\nPor favor, <raza>. Explora estas tierras y descubre la fuente de la testarudez del desierto.", progress = nil, completion = "Miras a tu alrededor oteando el horizonte en busca de lo que podría haber colocado aquí esta piedra...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14249] = {title = "El deseo de esquilar", objective = "Consigue 80 plumas de tronatesta prístinas de los hipogrifos que hay cerca de las Ruinas de Nordessa.", description = "¡Sería estupendo! Archimagia... ¡Genial! Él ni siquiera me habla por no tener una estúpida toga y un sombrero. ¡Bah!\n\nEl archimago más increíble que han conocido estas tierras no puede tener solo una toga y un sombrero. Necesito demostrarle que soy especial, y sé justo cómo hacerlo.\n\nSal ahí fuera y mata a algunos de esos hipogrifuchos. ¡Tráeme una TONELADA de plumas!\n\n¿Me has oído? ¡Un buen puñado de plumas! Vamos, vamos, Tendré lista la toga para cuando hayas vuelto.", progress = "Mi toga tiene un aspecto estupendo. ¿Me has traído esas plumas?", completion = "¡Ja, ja! ¡Perfecto! Deja que añada esto en un momento. ¡Seguro que el archimago se quedará impresionado con mi estilo!", rewards = "Botas con plumas pegadasJubón de RobotrónHoja tijeraTe van a lanzar el siguiente hechizo:\n\nForcecast Ruins of Nordressa Invs Update\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14250] = {title = "Fuente renovable", objective = "Utiliza las cargas arcanas para recoger 5 basaltos animados de Balboa cerca de las Ruinas de Nordessa.", description = "Necesitaremos un poco más de basalto animado. Solo hay una fuente fiable en la zona: un gigante montés conocido como Balboa. No podemos matarlo si queremos seguir almacenando el mineral durante mucho tiempo así que, hemos estado extrayendo algunos pedazos hasta ahora.\n\nVerás el camino que conduce hasta él al noreste y al este de aquí. Encuéntralo, coloca la carga delante del camino y escóndete hasta que estalle. Cuando hayas despejado el área, recoge el basalto y tráemelo.", progress = "He oído un par de explosiones. Apenas puedo distinguir si una de ellas era la tuya... Estos goblins pueden ser bastante molestos.", completion = "Buen trabajo. Esto debería ser suficiente para unas cuantas horas antes de tener que volver a por más.\n\nNo parece ser el gigante más listo. Espero que podamos seguir haciendo esto durante algún tiempo antes de que se entere.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14251] = {title = "Un nuevo comienzo", objective = "Consigue 15 aguijoneros de escorpión.", description = "Nunca ha habido peligro de sufrir un ataque centauro tan al norte. Alguien los ha instado a hacerlo, ¡estoy seguro!\n\nDe todas formas, estoy acabado. Había invertido todo en este trayecto.\n\nAfortunadamente, hay algo que no podrán arrebatarme los centauros: ¡el ingenio goblin! ¡Empezaré desde cero y alzaré un imperio!\n\n<Bizby reconoce un escorpión en la distancia.>\n\nSiempre hay mercado para el pescado. ¿Qué dices, <amigo/amiga>?", progress = "Veamos esas colas de escorpión, amigo.", completion = "Así es como empecé, ¿sabes?\n\nLanzando veneno a los pícaros en Orgrimmar. Ay, qué tiempos aquellos...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14252] = {title = "Cuanto más viejo más rico", objective = "Encuentra 15 colas de basilisco viejas.", description = "¡Necesito un montón de colas, <clase>! Y no unas colas cualesquiera. Las que busco tienen que ser viejas o antiguas. Cuanto más decrépitas mejor.\n\nLas escamas de la cola de los basiliscos son únicas porque se endurecen con la edad y no se quiebran. Las escamas endurecidas son ideales para la elaboración de algunas armaduras.\n\nHan pasado muchos años desde que dejé de traficar con escamas de lagarto, pero quién sabe, ¡quizás fortalezca mi personalidad! Si es que se puede...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14253] = {title = "Plumas para empenachar", objective = "Recoge 25 plumas de aguilón aterrador.", description = "Dime, <clase>, cuando estés ahí fuera explorando los desechos del desierto, ¿me harías un favor?\n\nMantente alerta por si vieras aguilones aterradores. Sus plumas grasas son las mejores para empenachar, y un buen comprador pagaría una generosa suma por ellas.\n\nPor suerte para ti, ¡conozco a todos los buenos compradores!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Sobrehombros de cola de aguilónMusleras forradas de plumasApisonadoras DesgatalónRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14254] = {title = "Heavy Metal", objective = "Recoge 7 trozos de elemento 116 y llévaselos a Bizby a la Caravana de Bizby.", description = "Tienes un hondo presentimiento de que esta piedra, de alguna manera, es la responsable de que la zona se niegue a aceptar el afloramiento invasor.\n\nAl dirigir la mirada hacia el oeste, observas un rastro de desechos ardiendo débilmente que parecen estar relacionados con este misterio.\n\nConjeturas que limpiar los desechos podría resultarle de gran ayuda a Thunk.\n\nY, ¿quién sabe para qué podría servir esta basura?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14255] = {title = "Ethel Rethor", objective = "Cerelia, del Puesto de Furien, quiere que hables con Korrah en Ethel Rethor.", description = "Ya tenemos bastantes enemigos en la región como para provocar la ira del Círculo Cenarion.\n\nCuando establecimos nuestra avanzada aquí, se nos pidió que vigiláramos a uno de sus investigadores.\n\nKorrah fue vista por última vez en la torre situada en el oeste. Sé <bueno/buena> y hazle una visita. Ya ha pasado algún tiempo desde la última vez que fuimos a verla.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14256] = {title = "La amenaza emergente", objective = "Korrah quiere que vuelvas a hablar con ella cuando estés <listo/lista> para aprender sobre la amenaza de los nagas.", description = "Soy todo lo que queda de mi empresa cuando me enviaron a observar los cambios de la costa de Desolace.\n\nHe informado del aumento significativo de nagas en la zona, pero no he obtenido respuesta.\n\nMis compañeros están pendientes de otros asuntos, así que debo pedirte a ti, <un extraño/una extraña>, que me ayude en mi investigación.\n\nPero primero, deja que te enseñe la amenaza a la que nos enfrentamos.", progress = nil, completion = "¿Te das cuenta ahora? No son un simple grupo de nagas desplazados, sino de un ejército bien organizado capaz de causar una gran devastación.\n\n¿Aceptas ayudarme en mi investigación?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14257] = {title = "La matanza Filozante", objective = "Recoge 10 huesos de Filozante de los nagas Filozante, 30 escamas de Filozante de las hechiceras Filozante y 4 aletas de Filozante de los guerreros Filozante.", description = "Los nagas han demostrado constantemente ser enemigos del equilibrio natural. No tengo reparos en derramar su sangre.\n\nTu mayor esfuerzo apenas minaría sus fuerzas. Por cada uno que cae, aparecen dos más.\n\nTengo un plan, <clase>. Tu objetivo no es simplemente segar vidas enemigas, sino recopilar componentes necesarios para la siguiente etapa de nuestra investigación...Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nCrear traje de naga\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14258] = {title = "Haz señales al mortero", objective = "Recoge 5 morteros goblin de El Laboratorio Secreto en Azshara.", description = "Los nagas comenzaron a avanzar en esta península cuando terminamos de construir esta terminal de la cohetepista. ¡Pero no hay problema en el mundo que no se resuelva con explosiones excesivas! Eso es lo que solía decir mi padre. Antes del accidente.\n\nSin embargo, me estoy quedando sin suministros. Hazme un favor y recoge los morteros que dejé apilados en El Laboratorio Secreto, justo al oeste de aquí. ¡Abastéceme y te dejaré dirigir los ataques de artillería!", progress = "Espero que tengas más munición para mí. ¡No tengo nada que lanzar aparte de improperios!", completion = "¡Genial! ¡Magnífico! ¡Brillante! ¡Te quiero!\n\nCon todos los morteros que me has traído, te puedo ayudar a atacar a los nagas en el este. Utiliza estos marcadores para dirigir el ataque de artillería desde cualquier parte de los acantilados y les haremos saber lo que es el dolor. ¡Oh, deliciosa, despiadada y aleatoria destrucción! Espero que tengas una buena armadura...", rewards = "Recibirás:\n\nSeñal de artillería"}
MultiLanguageQuestData['mx'][14260] = {title = "El disfraz marino", objective = "Usa el talismán de Filozante.", description = "He creado un talismán que te permitirá infiltrarte entre los nagas, dándote la apariencia de uno de los suyos.\n\nCon este disfraz, podrás hablar y comprender su idioma. Serán incapaces de descubrir tu verdadera identidad.\n\n¡Pero ten cuidado! Los tiburones y otras criaturas marinas podrían ponerte en evidencia. Evítalos a toda costa.\n\nAhora vete. Habla con la sacerdotisa Azshara y haz lo que sea para averiguar sus propósitos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14261] = {title = "Frío polar", objective = "Utiliza la Criomática 16 para congelar y matar a 8 dracos sable.", description = "Tengo la solución perfecta para nuestro problema de dracos: mi propia Criomática 16.\n\nEn principio, la desarrollé para congelar a mis trabajadores cuando viajaban y en los cambios de turno para no tener que alimentarlos y entretenerlos, pero surgieron algunas... complicaciones. ¡Aunque debería ser perfecta para derribar a esos dracos mientras surcan el cielo!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14262] = {title = "Limpiar pescado", objective = "Mata a 6 furiatormentas y a 6 clamamares Látigo de Ira.", description = "Me saca de quicio tener que defenderme de criaturas que desaparecen en el mar a su antojo y salen a la superficie cuando les place. Pero no descansaré hasta que extermine a los de su especie en Azshara.\n\nLos nagas Látigo de Ira han reptado por los acantilados y están asediando este campamento desde el este. Destrúyelos, <nombre>. Ábrelos de cola a cabeza para que sufran toda la furia de mi Horda.", progress = nil, completion = "&lt;Torg otea el horizonte.&gt;¡Aún siguen viniendo! Son como una plaga, &lt;nombre&gt;. Pero con una fuerza como la tuya, les aplastaremos. Algún día...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14263] = {title = "Pérdida de tomillo", objective = "Recoge 8 ramas de tomillo ira viviente cerca de las Ruinas de Nordressa.", description = "Tomillo ira viviente. ¡Necesito más! Date prisa, ¿lo harás?", progress = "¿Tienes el tomillo?", completion = "Perfecto. Resulta bastante interesante lo útiles que acaban siendo para este tipo de encantamientos las cosas más inesperadas.\n\n¡Tenemos tanto que aprender!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14264] = {title = "Más húmedo que mojado", objective = "Derrota a 5 sirvientes de Neptulon. (Deberás adoptar la apariencia de naga cuando los derrotes).\n\nSi pierdes el tridente de Filozante, habla con Valishj.\n\nSi pierdes el talismán de Filozante, habla con Korrah en Ethel Rethor.", description = "Los esbirros de Neptulon han llegado y están haciendo todo lo posible para frustrar nuestros planes. Está claro que han descubierto nuestras intenciones.\n\n¡Lo que confirma mis sospechas de que lo que buscamos se encuentra en algún lugar de estas ruinas!\n\n¡Estos elementales de agua no están a la altura de nuestras fuerzas! Toma este tridente y utilízalo para destruir a los inútiles sirvientes de los Cazamareas.\n\nCuando encontremos lo que buscamos, ¡el propio Neptulon temerá por su vida!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14265] = {title = "Tu instructor", objective = "Habla con el sargento Cleese en el Distrito Militar.", description = "La mayoría hemos llegado con vida... pero también hay huargen en este lado de la ciudad.\n\nEn cuanto estemos todos seguiremos dirigiéndonos al sur.\n\nEso me recuerda que alguien preguntaba por ti. Un caballero que responde al nombre de Cleese dijo que eras <uno/una> de sus estudiantes y quería asegurarse de que estuvieses bien.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][14266] = {title = "Cargar", objective = "Habla con el sargento Cleese y aprende Cargar. Practica Cargar contra un huargen Colmillo de Sangre.", description = "¡Estás <vivo/viva>, <nombre>! Eso debe significar que he hecho algo bien.\n\nLamento que nuestras clases hayan concluido de forma algo prematura. Sin embargo, puede que haya un par de cosas que pueda enseñarte que te serán útiles en un momento como este.\n\nPrueba tu nueva técnica contra los huargen Colmillo de Sangre que hay al oeste.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][14267] = {title = "Investigando el santuario del mar", objective = "Investiga el santuario naga para Torg Doblegolpe.", description = "Los invasores nagas han construido una serie de santuarios a lo largo de los acantilados. Desconozco su propósito, <nombre>, pero creo que están fortaleciendo a nuestros enemigos. Necesito que alguien se dirija allí y elimine esta amenaza de raíz.\n\nCerca, se erige un santuario que no cuenta con una gran defensa. Cruza el primer puente que encuentres al este y dirígete al norte en dirección a la bahía. Lo encontrarás en un pequeño saliente. Investiga el santuario y vuelve con información útil.", progress = nil, completion = "La piedra del centro del santuario brilla débilmente y ruge con el poder del mar agitado.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14268] = {title = "Impacto profundo", objective = "La sacerdotisa Valishj quiere que encuentres los grabados de Neptulon antiguos.", description = "La reina Azshara está buscando la entrada al plano del agua, aunque desconozco el porqué.\n\nCree que los ancestros poseían la clave para encontrar su emplazamiento.\n\nSe me ha encargado personalmente registrar las ruinas de la zona, ¡así que no descansará nadie hasta que hallemos los secretos que andamos buscando!\n\nHay una concentración de ruinas sumergidas al norte. Utiliza este bastón para rebuscar entre los escombros.\n\n¡Vuelve conmigo únicamente cuando hayas localizado lo que buscamos!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #4Objeto #1"}
MultiLanguageQuestData['mx'][14270] = {title = "El fragmento de piedra angular", objective = "Busca el fragmento de piedra angular en las proximidades.", description = "El aire que rodea esta extraña piedra crepita de energía. Es suave al tacto y fría como el hielo. Cuando la palpas, sientes cómo late de vez en cuando, como el romper de las olas.\n\nAl parecer, falta una pieza con forma de cuña en la parte superior del artefacto. Este fragmento de piedra angular parece la llave para desvelar los secretos de la piedra. Investiga la zona cercana al templo y busca el fragmento de piedra angular.", progress = "La piedra de energía naga late con un golpeteo expectante.", completion = "El fragmento de piedra angular encaja en el hueco y, de repente, emergen unas runas que antes permanecían ocultas en la superficie de la piedra, brillando en tonos azules y morados. Tus rodillas se doblan cuando las poderosas corrientes de energía Arcana comienzan a recorrer tu cuerpo...", rewards = "Te van a lanzar el siguiente hechizo:\n\nGuardatormenta\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14271] = {title = "Informa a Doblegolpe", objective = "Vuelve con Torg Doblegolpe a la Terminal de la Cohetepista del Sur en Azshara para informarle de tu descubrimiento.", description = "Una barrera mágica vibra a tu alrededor y te hace temblar. Te sientes a salvo tras esa barrera encantada.\n\n¡A Torg Doblegolpe le gustaría saber lo que has descubierto!", progress = nil, completion = "¿Dices una barrera de energía? ¡Esto lo explica todo! He sido testigo de cómo los líderes nagas han podido desviar las espadas de mis mejores guerreros.\n\nAhora sabemos la fuente de su poder, &lt;nombre&gt;. ¡Acabemos con esto de una vez!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14280] = {title = "El viento sabe tu nombre... O eso parece", objective = "Habla con Celestina de La Cosecha en el Distrito Militar.", description = "La mayoría hemos llegado con vida... pero también hay huargen en este lado de la ciudad.\n\nEn cuanto estemos todos seguiremos dirigiéndonos al sur.\n\nEso me recuerda que alguien preguntaba por ti. Era la bruja de la cosecha, Celestina. Dijo que los vientos pronunciaron tu nombre.\n\nMejor date prisa, <nombre>. Cuando hayas terminado de comunicarte con la naturaleza nos hará falta que vuelvas a machacar cráneos de huargen.", progress = nil, completion = "¡Hoy nos han bendecido! ¡Estás sano y salvo!", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][14282] = {title = "Misterio resuelto", objective = "Lleva los grabados de Neptulon antiguos a la investigadora Cenarion Korrah.", description = "Tu esfuerzo ha merecido la pena. Los grandes riesgos que has corrido lo han demostrado.\n\nHas descubierto el objeto de deseo de los nagas y sus motivos para invadir la costa de Desolace.\n\nY, en cuanto a los grabados que has descubierto, está claro lo que tienes que hacer...Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Faja blasonadaCasco arrancapiedraTrituradores pillarocaTe van a lanzar el siguiente hechizo:\n\nStrip Naga Disguise\n\nRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14283] = {title = "Un toque de rejuvenecimiento", objective = "Habla con Celestina de la Cosecha y aprende Rejuvenecimiento. Practica Rejuvenecimiento con un guardia herido.", description = "Ya nos llevaron al límite de la extinción antes, <nombre>. Pero nosotros, los druidas, guardianes de los viejos hábitos, salvamos a nuestra gente de la inanición.\n\nCuando nos separamos del mundo exterior y nuestros cultivos dejaron de funcionar, fue nuestra orden la que llamó a las bendiciones de la tierra y recuperó la cosecha.\n\nComo lo hicimos esa vez, lo mejor es poner nuestro destino en manos de un poder superior. Únete a mí y aprende lo que nos tiene que enseñar lo salvaje.", progress = "La tierra nos habla, <nombre>. No nos abandonará ni en estos tiempos de peligro.", completion = "No está mal. Puede que aún haya esperanza para los viejos hábitos.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][14284] = {title = "La venganza del aparecido", objective = "Hydronis quiere que montes en él y derrotes a la sacerdotisa Valishj.", description = "Soy Hydronis, un sirviente de Neptulon el Cazamareas, Señor de todas las aguas.\n\nAzshara y sus siniestros nagas se han rebelado contra mi maestro y quieren declararle la guerra. Esta es la primera batalla de lo que promete ser un largo enfrentamiento.\n\nHe luchado estoicamente, <raza>, y me he desgastado.\n\nParece que mis actos han atraído la atención de su sacerdotisa.\n\nYo solo no tengo la fuerza suficiente para acabar con ella pero, quizás, juntos, prevalezcamos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14286] = {title = "Cuantos más, mejor", objective = "Habla con el rey Genn Cringris en el Distrito Militar.", description = "Te he enseñado todo lo necesario por ahora.\n\nEs hora de reunirnos con los demás supervivientes. Mencionaron que el rey Cringris y su guardia real están justo al sur de aquí.\n\nDeberíamos ir allí, donde nuestro número mayor nos servirá de protección.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14291] = {title = "Cuantos más, mejor", objective = "Habla con el rey Genn Cringris en el Distrito Militar.", description = "Te he enseñado todo lo necesario por ahora.\n\nEs hora de reunirnos con los demás supervivientes. Mencionaron que el rey Cringris y su guardia real están justo al sur de aquí.\n\nDeberíamos ir allí, donde nuestro número mayor nos servirá de protección.", progress = nil, completion = "Has hecho bien en venir aquí. Si los gilneanos nos mantenemos unidos, podremos derrotar a este terrible enemigo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14292] = {title = "El enemigo de tu enemigo", objective = "La investigadora Cenarion Korrah quiere que hables con Lord Hydronis.", description = "Nos has prestado un servicio excelente, <clase>.\n\nAunque sigan siendo una fuerza imponente, tus esfuerzos han evitado que los nagas posean un artefacto importante.\n\nDebo escribir a mis compañeros sobre tus hallazgos. Mientras tanto, el aparecido de agua de la Isla Ranazjar ha estado luchando solo contra un ataque continuo de nagas.\n\nEncuéntralo y comprueba si hay alguna forma de poder ayudarlo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14293] = {title = "Salvar a Krennan Aranas", objective = "Rescata a Krennan Aranas en el Distrito Militar.", description = "Han pasado tantos años desde la guerra y Crowley aún escondía suficiente pólvora en ese sótano para hacer volar la mitad del distrito.\n\nPodría haber acabado así, por desgracia.\n\nNo podemos abrir fuego aún, hay un civil atrapado al otro lado de la prisión.\n\nNo se trata de cualquier civil, por cierto. Krennan Aranas es uno de los alquimistas más brillantes que este mundo ha conocido.\n\nUna de sus pociones salvó a mi hija, Tess, de morir justo después de nacer.\n\nLlévate mi caballo y rescátalo. Krennan debe vivir.", progress = nil, completion = "Bien hecho, &lt;nombre&gt;. Nos aseguraremos de que Krennan salga con vida de la ciudad.", rewards = "Te van a lanzar el siguiente hechizo:\n\nForcecast Cannon Camera\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14294] = {title = "Hora de reagruparse", objective = "Habla con el rey Genn Cringris en el Patio de Cringris en la Ciudad de Gilneas.", description = "Hemos hecho todo lo que podíamos aquí. Que el rey Cringris sepa que hemos ganado algo de tiempo.\n\nAlgo me dice que los huargen no tardarán en volver a la carga.\n\nSi se da el caso tendremos que retroceder hasta el Patio de Cringris. Es el último lugar en el que podremos resistir sin quedarnos atrapados como ratas.", progress = nil, completion = "Nos quedan muy pocas opciones, &lt;nombre&gt;. Lo siguiente que hagamos será una decisión crítica.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14295] = {title = "Hermanas del mar", objective = "Mata a Lady Silisthra y a Lady Vesthra inutilizando sus piedras de energía.", description = "Dos brujas nagas han estado dirigiendo el asalto a esta avanzada. Han repelido los ataques directos de algunos de mis mejores brutos, pero tú podrías tener éxito donde otros han fracasado.\n\nBusca y mata a Lady Silisthra y a Lady Vesthra en el borde este de los acantilados, alrededor de las ruinas de los antiguos colosos de los elfos de la noche. Primero tendrás que destruir las piedras de energía que les otorgan su fuerza. ¡No me decepciones, <clase>!", progress = nil, completion = "ASÍ es como solíamos tratar a las serpientes en Durotar; ¡aplastándolas con nuestras botas! Has enorgullecido a la Horda, &lt;nombre&gt;. En cuanto lleguen los refuerzos, eliminaremos al resto de alimañas y reclamaremos esta península de una vez por todas.", rewards = "Jubón de hermana del marGuantes aplastasierpesRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14296] = {title = "Vigila tus pasos", objective = "Recibe 6 descargas de energía de los conductos de energía mientras asciendes a la cima del Pináculo Arcano.", description = "Esto es algo sencillo y a la vez complejo. Los conductos de energía llegan hasta arriba. ¡Se podría decir que son como este de aquí! De hecho, lo afirmo.\n\nY en cuanto a ti, utiliza los trampolines de salto para ascender el pináculo y toca todos los conductos que encuentres por el camino. Cuando te reúnas conmigo en la cima deberás rebosar de energía porque, realmente, es la única manera conseguirlo.\n\n¡Y asegúrate de seguir moviéndote o tendrás todas las papeletas para recibir un buen chispazo!", progress = "No, no, no, lo has entendido mal. Se supone que tenías que reunir energía de los conductos antes de subir hasta aquí, ¿recuerdas?\n\nInténtalo una vez más, ¡y con estilo!", completion = "Ahora es cuando la mayoría de mis aprendices se preguntan si existe una razón lógica por la que haya almacenado la energía de mi portal en esos conductos y haya que recogerla de una manera tan sofisticada.\n\n¡Por supuesto que hay una razón! Quiero estudiar tu comportamiento... las estrategias, los errores, las frustraciones, los triunfos... Ese es el objetivo de esta prueba.\n\nY ahora más. ¡Más pruebas! ¡¿A que suena emocionante?! Claro que sí.", rewards = "Togas cargadasBrazales jugososRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14297] = {title = "Pro liberación", objective = "Utiliza las llaves de hierro forjado de los cultores y de los dragonantes para liberar a 4 obreros goblin en Cumbre Cebellina.", description = "Sabía que estos tipos nos traerían problemas en cuanto empezáramos a construir la torre. Desprecian nuestros sobornos y nos roban a los trabajadores.\n\nLa mano de obra no es barata con toda la construcción que hay en Azshara. ¡Necesito que vuelvan esos hombres!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #4"}
MultiLanguageQuestData['mx'][14299] = {title = "El asilo de Xylem", objective = "Atraviesa el portal hasta la torre del archimago Xylem y busca dentro a Joanna.", description = "¡Qué maravilla! Es un placer digno de observar. Hay mucho que estudiar.\n\nAhora vete, retírate a mi torre. Joanna te ubicará. Abriré un portal para ti.", progress = nil, completion = "¡Bienvenido! Parece que has salido prácticamente indemne de las pruebas. Me alegro por ti, mi amor.\n\nTambién pareces tener algún propósito en mente: una pregunta. Tus pensamientos son muy ruidosos, me resulta difícil no oírlos.\n\nVenga, cariño; dispara.", rewards = "Zapatos del AsiloFajín de JoannaPodrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][14300] = {title = "La prueba de Fuego", objective = "Completa la prueba de Fuego permaneciendo en las runas de fuego sin que te alcancen las llamas durante 10 explosiones consecutivas.", description = "La prueba de Fuego... Oooh, intimida, ¿eh? ¿No? Mm. Bueno, eso creía yo también. Lo primero es lo primero, toca el cristal de fuego y se abrirá el portal a la prueba.\n\nPara superarla, tienes que ir dando saltos en las runas de fuego sin que te alcancen las llamas. Si permaneces fuera del alcance del fuego durante el tiempo suficiente, ¡ganas!\n\nHay unas cuantas señales que te ayudarán: el fuego que salta a una nueva runa se consume cuando la runa se enfría. Puedes intentar averiguar esas cosas si quieres. ¡O adivinarlas! Es lo que hacen casi todos.", progress = nil, completion = "¡Sí! ¡Me alegro por ti! Esa prueba realmente te puso el fuego en el trasero.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14301] = {title = "Vuelve e informa", objective = "Vuelve con la investigadora Cenarion Korrah a Ethel Rethor.", description = "¡Ya está! Juntos pudimos derrocar a un adversario peligroso.\n\nTus hazañas llegarán a oídos del mismísimo Neptulon, <clase>. Permíteme brindarte su agradecimiento...\n\nAhora debes irte. Este lugar no permanecerá a salvo por mucho tiempo. Pronto, los nagas reclamarán venganza por su sacerdotisa.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Arco largo de espinaescamaSobrevesta suaveJubón de agua corrienteFaja chisporroteanteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14302] = {title = "Evaluación oficial", objective = "La investigadora Cenarion Korrah quiere que lleves el informe de Korrah a Karnum al Claro de Karnum.\n\nObjeto provisto: \n", description = "Has conseguido mucho con tus esfuerzos contra los nagas, <nombre>. Pero me temo que aún no es suficiente...\n\nEsta es mi evaluación oficial de la presencia de los nagas.\n\nConfío en que mis compañeros de las Tierras Vírgenes adopten las medidas necesarias.\n\nLleva esto a Karnum al claro situado en el centro de las Tierras Vírgenes Cenarion, al sureste. Él sabrá qué hacer.\n\nGracias, <nombre>. Adiós.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14304] = {title = "Teoría sangrienta", objective = "Consigue 10 sanguijuelas llenas de sangre.", description = "La tierra no es lo único que ha cambiado en Desolace. Aquí, la naturaleza ha respondido al nuevo entorno de una manera extraña y, en ocasiones, emocionante.\n\nEstoy especialmente interesada en los truenagartos rejuvenecidos que merodean por el oeste.\n\nNecesito una muestra de su sangre.\n\nPuedes empezar a ayudarme utilizando esta jarra de sanguijuelas en unos pocos.\n\nCuando se hayan llenado de sangre de esas bestias, entrégamelas.", progress = "¿Conseguiste las muestras que necesito?", completion = "Con esto debería bastar.\n\nGracias, &lt;clase&gt;.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14305] = {title = "Recogida de plantas", objective = "Recoge 10 cardos áloe.", description = "Nadie sabe mejor que el Círculo Cenarion que este exuberante oasis podría desaparecer tan rápido como apareció.\n\nTenemos que tener cuidado de no interferir en los procesos que ocurren aquí, sino apoyarlos y preservarlos.\n\nUna nueva especie de planta que abunda en la región vecina comenzó a crecer desde el gran cambio.\n\nRecoge muestras de esta especie. Debo estudiarlas y ver qué tienen para ofrecernos.", progress = "¿Conseguiste las muestras que necesito?", completion = "Estos especímenes están bien, no-muerto.\n\nEmpezaré a estudiar de inmediato.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14306] = {title = "Quitar malas hierbas", objective = "Mata a 7 azotadores desarraigados.", description = "Con un cambio de ecología tan abrupto, es de esperar que parte de la flora y la fauna no reaccione tan bien como esperamos.\n\nLos azotadores desarraigados son un claro ejemplo del problema. Deambulan por los campos del este y del sur y constituyen un detrimento para la región, por lo que debemos deshacernos de ellos.\n\nCuando estés por ahí, elimina a todas estas mascotas que te encuentres.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guardamuñecas azotapicosBufas con ribetes agujereadosYelmo FitoresistenteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14307] = {title = "Vientos testarudos", objective = "Destruye a 5 caminatormentas espirálicos.", description = "Soplan vientos de cambio, <raza>. De eso no cabe duda.\n\nHay muchos asuntos acuciantes que requieren de nuestra atención y actuación. El jefe de los vientos es el responsable de expandir nuestro oasis creciente.\n\nSu crecimiento ha sobrepasado nuestras esperanzas y nuestro entendimiento, aunque ahora hay algo que se le resiste.\n\nAl oeste, donde la hierba se junta con la arena, los vientos espirálicos evitan que se expanda por el desierto.\n\n¡Ve y elimina este hostil obstáculo para la vida!", progress = nil, completion = "Lo has hecho muy bien, &lt;clase&gt;.\n\nSin duda te llamaremos para que nos ayudes con asuntos más importantes en el futuro.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14308] = {title = "Cuando la ciencia ataca", objective = "Utiliza el Fuegoeliminator X-21 para extinguir 8 llamas y rescatar a 6 becarios de investigación del incendio en El Laboratorio Secreto.\n\nVe a ver a la ayudante Greely a la Terminal de la Cohetepista del Sur si pierdes tu Fuegoeliminator.", description = "¿Has visto las explosiones al entrar? ¡El Laboratorio Secreto está envuelto en llamas otra vez! Si no extinguimos esas llamas, alcanzaremos unos niveles de temperatura críticos y nos convertiremos en una cascada de lava.\n\nToma, te confío este bote lleno de gel líquido experimental presurizado e hiperrefrigerado: ¡el líquido resistente al fuego más volátil que conoce la ciencia! (Mantén el bote alejado de las llamas). Extingue el fuego y riega a mis becarios. Después, contacta conmigo a través del graznófono del panel de control principal.", progress = "<La voz de pito de Greely chirria a través de un equipo de altavoces.>\n\n¡Cohetepista a Laboratorio Secreto! ¡Cohetepista a Laboratorio Secreto! Vamos, Laboratorio Secreto...", completion = "¡Buen trabajo, &lt;nombre&gt;! Ahora, separaremos la matriz del núcleo de reacción de los cárteres de combustible, o todo volará por los aires hasta Terrallende...", rewards = "Te van a lanzar el siguiente hechizo:\n\nUpdate Zone Auras\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14309] = {title = "Calmando al kodo", objective = "Utiliza el brebaje de kodo cerca de 5 kodos iracundos.", description = "Como has presenciado hasta ahora, los cambios bruscos de la región pueden tener efectos positivos y negativos para las criaturas locales.\n\nAl sur y al este de aquí, los kodos iracundos representan una amenaza constante para cualquiera que se encuentre cerca.\n\nEs hora de probar mi teoría. He utilizado la sangre de truenagarto rejuvenecido para elaborar este brebaje. Espero que los kodos se tranquilicen cuando se lo coman.\n\nColócalo cerca de un kodo iracundo ¡y asegúrate de estar a una distancia prudencial!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Sombrero de retador kodoLazo polvorientoEl tranquilizadorRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14310] = {title = "Fallo de segmentación: verter el núcleo", objective = "Activa la consola de control del reactor y escolta el núcleo de azsharita hasta la Terminal de la Cohetepista del Sur. Utiliza el Fuegoeliminator X-21 en el núcleo si empieza a recalentarse.", description = "Necesito que me traigas el núcleo para cuando limpiemos el reactor central. Es de cristal azsharita refinado 100% y resulta tan poderoso como peligroso. Y maravilloso... Ah, preciada azsharita, ¡el material que moldeará el mundo!\n\nLa palanca gigante situada a tu izquierda verterá el núcleo y me lo enviará por vía férrea. El núcleo estará recalentado, así que tendrás que sofocar las llamas con el Fuegoeliminator hasta llegar aquí... ¡no dejes que alcance una temperatura extrema!", progress = "No te preocupes por los efectos residuales de todos esos químicos en llamas del laboratorio. ¡El pelo vuelve a crecer!", completion = "Ufff, la muestra está a salvo. ¡Y aún echa humo! Gracias, &lt;nombre&gt;.\n\nLa azsharita es un complejo misterio envuelto en un enigma de peligro aterciopelado. Martillazos insiste en que averigüemos más sobre esta extraña sustancia.", rewards = "Te van a lanzar el siguiente hechizo:\n\nUpdate Zone Auras\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14311] = {title = "Participando", objective = "Usa las semillas Cenarion cerca de los 5 montones fértiles que hay alrededor de las Tierras Vírgenes Cenarion.", description = "¡Gloriosos sean los tiempos en los que vivimos!\n\nLos antiguos páramos de Desolace están floreciendo llenos de vida. ¡Imagina, <clase>, que ocurriera lo mismo en todos los páramos de Azeroth! Quizás algún día...\n\nEs cierto que acechan serios problemas pero, ¿por qué no nos tomamos un momento para admirar el milagro asombroso del que estamos siendo testigos?\n\nDe hecho, ¿por qué no participamos en él? Aquí hay algunas semillas Cenarion. Utilízalas en los lugares más fértiles de los páramos.\n\n¡La medicina perfecta para levantar el ánimo!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14312] = {title = "Una introducción en marcha", objective = "Garren Vientoscuro del Claro de Karnum quiere que hables con el Khan Leh'prah.", description = "Me han hablado de tus hazañas aquí en Desolace, <nombre>. Estamos en deuda contigo.\n\nMe temo que tendré que involucrarte en otro asunto; uno aún más urgente.\n\nEl paisaje no es lo único que ha cambiado por aquí últimamente. Los viejos conflictos han dado paso a otros nuevos aún más funestos. Debería dejar que nuestro invitado nos explicara más...\n\nEl Khan Leh'prah es uno de los últimos supervivientes de la tribu Kolkar que una vez reinó en todo el este de Desolace. Lo encontramos casi muerto en nuestra frontera. Escucha sus palabras.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14313] = {title = "Otra vez entre humanos", objective = "Habla con Krennan Aranas en el Refugio del Ocaso.", description = "¿Así que la poción de Krennan no te mató? Bueno, supongo que entonces eso significa que el humano de tu interior tiene el control.\n\nNo tendré que dispararte después de todo. Al menos no todavía.\n\nVe a hablar con Krennan Aranas y dale las buenas noticias. Es el responsable de la casa donde tenemos a... los de tu especie.\n\nPero no lo olvides, <nombre>. Te estoy vigilando. Intenta hacer algo raro y tendrás una bala entre los ojos.", progress = nil, completion = "¡Funcionó! ¡Por la Luz, funcionó!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14314] = {title = "¡A la fuga!", objective = "Mata al celador Magram en el Poblado Magram.", description = "Todo comenzó con un sueño que me avisaba repetidamente del peligro que se avecinaba. He visto a las legiones demoniacas cernirse sobre los nuestros invadiendo nuestras tierras.\n\nEl sueño se ha hecho realidad. El Filo Ardiente y sus maestros demoniacos han expulsado a los Magram de sus tierras del sur. A su vez, los Magram han derrotado a mi pueblo y se han quedado con sus hogares.\n\nEl enfrentamiento fue encarnizado. Solo consiguieron sobrevivir un puñado de Kolkar. Te pido que visites lo que una vez fue mi tierra en el este y que les liberes de su confinamiento.", progress = nil, completion = "Te lo agradezco, no-muerto.\n\nNuestra tribu no habría sobrevivido sin tu ayuda.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14316] = {title = "Propiedad de Cenarion", objective = "Recoge 7 cajones de suministros Cenarion en el Poblado Magram.", description = "Desde que los demonios han invadido sus tierras, los Magram se han desvinculado de cualquiera ajeno a su pueblo.\n\nSon desconfiados y hostiles y se dedican a robar a los demás en vez de mantenerse por ellos mismos.\n\nMuchos de nuestros preciados suministros han desaparecido últimamente y sospechamos que los Magram son los responsables.\n\nPor favor, <nombre>, ve a su territorio situado al este y busca nuestras pertenencias.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14318] = {title = "Negociaciones delicadas", objective = "El Khan Leh'prah quiere que coloques la lanza del Khan Kolkar en la Piedra del Patriarca y que la defiendas de los Magram hasta que aparezca el Khan Kammah.\n\nHabla con el Khan Leh'prah cuando estés <listo/lista> para trasladarte al lugar de la batalla.", description = "Solo existe una manera de ganarse la confianza y la lealtad de los Magram.\n\nA base de golpes.\n\nHan sufrido muchas pérdidas en su guerra contra mi clan y, ahora, poseen una tierra desconocida donde la lucha consiste en poder alimentarse.\n\nEs el momento de atacar.\n\nHabla conmigo cuando estés <listo/lista>, después vete y planta mi lanza en la Piedra del Patriarca. Si podemos matar a bastantes, su Khan se someterá a nuestra voluntad.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Mantón de sueños de centauroHombreras de la cumbre desafiantesMusleras obcecadasPodrás elegir una de estas recompensas:\n\nObjeto #1\n\nTe van a lanzar el siguiente hechizo:\n\nForzar reacción de Magram\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][14320] = {title = "Faltan ingredientes", objective = "Encuentra el cajón de esencia de mandrágora.", description = "Ah, sí. Por lo que sabemos, los efectos de la maldición no se podrán curar del todo.\n\nSin embargo, con tratamiento, tu mente seguirá siendo tuya... y no la de un animal salvaje.\n\nTenemos suerte de que el tratamiento funcionase contigo. Normalmente solo puedo tratar infecciones recientes.\n\nTendremos que continuar tu medicación si queremos invertir la maldición.\n\nNecesitaré esencia de mandrágora para prepararte otro lote de mi suero. Encontrarás un cajón escondido en un cobertizo que hay al suroeste de la ciudad.", progress = nil, completion = "El cajón está destrozado y los frascos de su interior parecen estar rotos.", rewards = "Te van a lanzar el siguiente hechizo:\n\nCámara de invasión\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14321] = {title = "Invasión", objective = "Habla con Gwen Armstead en el Refugio del Ocaso.", description = "<Un cuchillo largo decorado con una calavera sobresale de las costillas del miliciano. Al buscar pistas, localizas un par de barcos de guerra de apariencia amenazante en la orilla.>\n\n<Van a invadir Gilneas. Vuelve a informar a la alcaldesa de Refugio del Ocaso, Gwen Armstead.>", progress = nil, completion = "¡Renegados! ¡Rápido, &lt;nombre&gt;! Debemos establecer nuestras defensas.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14322] = {title = "¡Ciencia mala!", objective = "Mata a 8 hipogrifos cargados con electricidad estática.", description = "Estaba intentando domesticar a los hipogrifos autóctonos con una serie de descargas eléctricas debilitantes cuando, por alguna razón, ¡se pusieron como una fiera! Ahora, ¡los sujetos sometidos a las pruebas están destrozando este lugar sin razón alguna! <clase>, sacrifica a mis experimentos fallidos antes de que me encuentren.", progress = nil, completion = "¿Así que el mundo se encuentra a salvo para la ciencia de nuevo? ¡Excelente! La próxima vez probaré con agujas calientes o algo así.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14323] = {title = "Absorbente", objective = "Recoge 20 gotitas de agua tibia de las salpicaduras viles que hay al este de las Ruinas de Arkkoran.", description = "Necesito otra cosa más. Agua caliente.\n\nNo es fácil de encontrar por aquí. No hay fuentes termales ni amigos a quien pedírsela. Sin embargo, hay una manera de recogerla. Toma esta esponja... ¡es ultrabsorbente! Remójala en las salpicaduras viles del banco de arena situado hacia el este.\n\nCuando hayas recogido suficiente, ve a escurrirla cerca de la torre para invocar al elemental gigante. Él tiene agua caliente.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14324] = {title = "Lleno de agua caliente", objective = "Consigue un globo de agua hirviente de un señor Aguarviente en la Torre de Eldara.", description = "Ergll afirmó que deberías poder utilizar la esponja de mar de azsharita atiborrada para invocar a un elemental gigante cerca de la Torre de Eldara, al noreste.", progress = "¡Has vuelto!", completion = "Qué acertado, ¿no? ¿Quién necesita fuentes termales? Esto es perfecto.", rewards = "Guantes hirvientesJubón esponjosoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14325] = {title = "Trabajar para comer", objective = "Recoge 5 costillares de basilisco.", description = "<El Khan Kammah escucha tus explicaciones sobre la amenaza demoniaca y las visiones del Khan Leh'prah.>\n\nNo hace falta que nadie nos aleccione sobre demonios, <raza>. Son ellos los que expulsaron a nuestro clan de las tierras ancestrales.\n\nSon ellos los que nos obligaron a asentarnos en el páramo de Kolkar, donde luchamos por sobrevivir.\n\nMi pueblo tuvo que pagar un alto precio por la guerra contra los Kolkar. Los pocos que quedamos, estamos hambrientos y desgastados.\n\nTrae comida para mi pueblo y luego discutiremos el asunto de los demonios.", progress = "¿Has traído comida para mi clan, no-muerto?", completion = "Muy bien, no-muerto.\n\nPor ahora, este será nuestro sustento.", rewards = "Te van a lanzar el siguiente hechizo:\n\nForce Reaction Magram 4\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14327] = {title = "Mi palabra es sagrada", objective = "El Khan Kammah quiere que hables con el Khan Leh'prah.", description = "Parece que no nos queda otra opción.\n\nAunque soy reacio a cooperar con los Kolkar, las palabras del Khan son sabias.\n\nDale mi palabra de que pondremos nuestras lanzas a su disposición para la batalla.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14328] = {title = "Los tres príncipes", objective = "Mata a Rhoho, a Sherik y a Jorreth.", description = "Los Gelkis residen en el suroeste de Desolace. Son tan testarudos como los Magram y, como no han sufrido los estragos de la guerra y los traslados, son bastante más fuertes.\n\nConseguir que los Gelkis sean más humildes requeriría un esfuerzo extremo.\n\nEl Khan Shodo y sus tres hijos lideran el clan. Shodo se hace mayor y sufre de viejas heridas de guerra. Nunca abandona las profundidades de su cueva. La fuerza de su reinado yace en sus hijos.\n\nMátalos y convence al Khan de comprometerse con nuestra causa.", progress = nil, completion = "Mis hijos asesinados... mi clan en ruinas...\n\nSi gozara de juventud, ¡te despedazaría miembro a miembro!\n\nVete... Mátame o déjame llorarles a solas, no-muerto.", rewards = "Te van a lanzar el siguiente hechizo:\n\nForzar reacción de Gelkis\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14329] = {title = "¡Para el carro!", objective = "El Khan Shodo quiere que mates a 10 aplastadores Maraudine en el Valle de las Lanzas.\n\nBusca pistas del paradero de Kherrah en sus cadáveres.", description = "<El Khan del clan Gelkis te observa fijamente con una mirada vacía mientras le informas sobre la amenaza demoniaca y las visiones de Leh'prah.>\n\nYa no me incumbe lo que le ocurra a esta tierra. He fallado a mi clan y a mis antepasados...\n\nSolo hay una cosa que podría darle esperanza a mi viejo espíritu, y, probablemente, esté muerta también.\n\nEl clan Maraudine me arrebató a mi querida hija Kherrah. Si consiguieras traérmela con vida, consideraría tu propuesta.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14330] = {title = "A puerta cerrada", objective = "Encuentra a Kerrah en algún lugar tras las puertas de que conducen a Maraudon.\n\nObjeto provisto: \n", description = "Has descubierto el paradero de Karrah, la hija del Khan Shodo. ¡Se encuentra presa tras las puertas que conducen a Maraudon!\n\nEl intento de rescate puede ser arriesgado pero, si quieres que el clan Gelkis colabore, debes liberar a la hija del Khan.", progress = nil, completion = "¿Es seguro que me vaya, no-muerto?", rewards = "Te van a lanzar el siguiente hechizo:\n\nForce Reaction Gelkis 4\n\nRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14332] = {title = "Hora de cambiar", objective = "Kerrah quiere que hables con el Khan Leh'prah.", description = "<Kerrah te escucha mientras le explicas los sucesos acontecidos.>\n\nCoincido con las palabras del Khan Kolkar. Se acabaron las rencillas. Es una lástima que tengamos que haber sufrido una amenaza demoniaca para que las tribus se unan.\n\nDebo regresar junto a mi padre y convencerle de que apoye nuestra causa. Tienes mi palabra de que accederá.\n\nVuelve con el Khan Leh'prah e infórmale de que el pueblo de Gelkis está preparado para la batalla.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Daga forjada formalPechera de emisarioEscarpines silenciososRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14333] = {title = "Reliquias profanas", objective = "Rastrea el Valle de las Lanzas en busca de 6 reliquias profanadas.", description = "Los Maraudine han asaltado los campamentos Gelkis durante muchos años, robando todo lo que encontraran a su alcance.\n\nUna de sus costumbres favoritas es hacerse con estas reliquias de poder sagradas para los Gelkis y traerlas aquí para profanarlas.\n\nEl clan Gelkis estaría realmente agradecido si encontraras y destruyeras esos artefactos profanados.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #6"}
MultiLanguageQuestData['mx'][14334] = {title = "Tripasebo", objective = "Mai'Lahii quiere que mates a Tripasebo.", description = "¡Qué hay, colega!\n\n¿Crees que podrías hacer algo por eh'te poblado?\n\nNos las arreglamos bien con la mayoría de las ballenas pero hay una un poco eh'pecial que se resih'te a nueh'tras lanzas.\n\nTripasebo se hace cá' vez más grande; ¡comiéndose los peces con los que nos alimentamos!\n\nSal ahí fuera, encuentra al bicho, ¡y hazle pagar por su gula!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Mandiletes manchados de grasa de ballenaBufas tamaño orco curadasPodrás elegir una de estas recompensas:\n\nColgante de diente de ballenaAnillo de diente orco\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][14335] = {title = "Obstáculos en el camino", objective = "Mata a 5 reptadores Golpeseco y a 5 tenazarios Golpeseco.", description = "Sin duda, ya habrás notado que los recientes cambios de la tierra han traído bastantes consecuencias. Algunas beneficiosas, y otras que plantean serios problemas.\n\nAl sur de la aldea, los langostroks locales estás emergiendo del mar y obstaculizan el camino hasta la aldea.\n\nPor favor, <clase>, elimina esta plaga.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Hacha de batalla de aquelarreTogas de caparazónBotines de Espíritu ErranteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14336] = {title = "Mata o muere", objective = "Habla con el príncipe Liam Cringris en el exterior del Refugio del Ocaso.", description = "Los arrecifes siempre nos han protegido de un ataque por la costa. Los terremotos deben haber abierto un pasadizo para los barcos de los Renegados.\n\nRápido, <nombre>. Frena a los atacantes mientras preparo al resto de la milicia.\n\nCreo que puedo oír al Príncipe y a algunos de nuestros hombres enfrentarse a los Renegados mientras hablamos. Habla con Liam para que te diga qué puedes hacer para ayudar.\n\nAh... y asegúrate de que no lo maten. Me temo que podría ser un poco imprudente en su estado actual.", progress = nil, completion = "¡¡¡&lt;nombre&gt;!!! ¡Estás vivo de verdad!\n\nCreí que estaba soñando con los viejos tiempos cuando oí tu voz...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14337] = {title = "La Aldea Cazasombras", objective = "Karnum Tejedor de Marismas quiere que hables con Mai'Lahii.", description = "Hola de nuevo, <clase>.\n\nHe recibido noticias de que la Aldea Cazasombras necesita ayuda. Aquí estamos más que ocupados así que, debo pedirte que vayas allí y les ayudes.\n\nLa aldea se sitúa en la costa al suroeste de aquí. Cuando llegues, busca al que llaman Mai'Lahii.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14338] = {title = "Campamento del Espíritu Errante", objective = "Karnum Tejedor de Marismas quiere que hables Maurin Partehuesos.", description = "Saludos, <clase>.\n\nMe alegra ver que aún vives. Ha llegado la hora de contratar tus servicios.\n\nAl suroeste de esta arboleda se encuentra el Campamento del Espíritu Errante. Allí encontrarás a un Renegado llamado Maurin Partehuesos.\n\nPodría tener la solución para uno de los problemas a los que nos enfrentamos.\n\nHabla con él y préstale la ayuda que necesite.", progress = nil, completion = "Saludos, &lt;clase&gt;.\n\nMe alegro de que hayas llegado al fin...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14339] = {title = "El dispositivo de contención", objective = "Maurin Partehuesos quiere que consigas 3 cuernos de kodo huecos de kodos moribundos.", description = "El destino nos ha encomendado una tarea especial; una que nos beneficiará al Círculo Cenarion y a mí.\n\nMira, <clase>, estoy agobiado con la creación de un brebaje... digamos, especial. Creo que el trabajo está acabado pero necesito probarlo para asegurarme.\n\nEl objetivo de esta prueba son los nagas, que amenazan la región desde el oeste. Su desaparición sin duda beneficiará al Círculo.\n\nPero primero, necesito un dispositivo de contención. Los cuernos huecos de los kodos moribundos servirán.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14340] = {title = "Vístete para impresionar", objective = "Ponte tu nuevo sombrero de zahorí y habla con la imagen del archimago Xylem justo al noreste del Intercambiador de la Cohetepista del Norte.", description = "Supongo que cada hombre tiene que aprender sus propias lecciones.\n\nToma, coge mi sombrero de zahorí. Seguro que te acepta como aprendiz si aparentas serlo... Puede que al principio solo tengas que pasar por el aro. Un pequeño aro en llamas suspendido sobre pinchos con espadas giratorias al otro lado.\n\nDeberías encontrar la imagen del archimago Xylem en la cima de esa colina al noreste.", progress = nil, completion = "Vaya, mírate, ¡eres una maravillosa representación de la Magia moderna! Debo decir que llevas un sombrero muy elaborado.\n\n¿Aprendices? ¿Aprentici? Creo que ya tengo algunos pero, imagino que nunca se tienen demasiados apren... tici.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14341] = {title = "Los arneses de Smeed", objective = "Nataka del Campamento del Espíritu Errante quiere que entregues a Smeed los arneses de Smeed.\n\nObjeto provisto: \n", description = "Disculpa, joven <raza>.\n\nNecesito un poco de ayuda. Acabo de terminar de preparar un pedido de arneses que deberían entregarse enseguida.\n\nYa soy un poco viejo para el viaje, especialmente si consideramos lo peligrosas que se han puesto las cosas últimamente.\n\n¿Te importaría ir?\n\nSon para Smeed, un goblin que vive al sureste de aquí.", progress = nil, completion = "¡Ah, mis arneses!\n\n¡Gracias, amigo!", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14342] = {title = "Invasión infernal", objective = "Felgur Doscortes quiere que destruyas 10 infernales inferiores.", description = "¡Los demonios están de camino, <raza>!\n\nSi no actuamos, nos invadirán en cuestión de semanas. Acabo de regresar del Aquelarre Mannoroc, ¡donde los infernales caen del cielo!\n\nAl menos, tenemos que ganar algo de tiempo. ¡Dirígete allí y termina lo que empecé!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Daga sangreoscuraMáscara de matademoniosBaluarte arañadoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14343] = {title = "El brebaje de Maurin", objective = "Maurin quiere que entregues el brebaje de Maurin a Karnum en el Claro de Karnum.\n\nObjeto provisto: \n", description = "<Maurin sella solícitamente su brebaje en los cuernos de kodo huecos.>\n\nYa está, <clase>.\n\nLlévaselo a Karnum. Él verá cómo quiere usarlo contra los nagas.\n\n¡Estaré pendiente de evaluar la eficacia de mi fórmula!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14344] = {title = "La ruina de Jugkar", objective = "Utiliza el núcleo de energía infernal para controlar a Lord Azrethoc en el Altar de Jugkar y aprovecha su energía para matar a Jugkar Lug'vara.", description = "Reconoces la esencia de un demonio que ha sido invocado.\n\nExtrañas y peligrosas energías insondables se entretejen en esta superficie.\n\nCuando fijas tu mirada en ella, una visión inunda tu mente; una imagen de ti <mismo/misma> controlando esbirros demoniacos. Una oleada de emoción fluye en ti cuando te imaginas ejerciendo tal poder.\n\nAl observar a tu alrededor, te preguntas cómo podrías utilizar este tesoro contra el enemigo demoniaco...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14345] = {title = "Andar con ojo", objective = "Habla con Sorata Hilafuego en el Intercambiador de la Cohetepista del Norte.", description = "¡Estupendo!\n\nAzy siempre intenta apoderarse de algún artefacto mágico. Dice que estaba intentando entablar amistad con ese tal archimago... ¡Xylem!\n\nXylem tiene MUCHOS aprendices. Acoge a muchos tipos diferentes, les explota y les deja deambulando por doquier. Es un alto precio el que hay que pagar.\n\nEl último suceso tuvo lugar anoche. Alguien se dirigió hacia esa construcción goblin que parece una torre enorme, situada al oeste. Quizás te ayude a encontrar a Xylem y a lo mejor Xylem sabe dónde está Azy...\n\n¡Haz lo que debes!", progress = nil, completion = "Mira colega, hace apenas una semana que me encontraba en tu situación. ¡El gran y poderoso archimago acepta aprendices! ¡¿Quién podría dejar pasar una oportunidad como esa?!\n\nA veces, las cosas son demasiado buenas para ser verdad.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14346] = {title = "Limpiando la grieta", objective = "Karnum Tejedor de Marismas quiere que utilices el brebaje de Maurin para matar a 10 invasores Filozante, a 10 sirenas Filozante y a 3 gigantes de mar.", description = "Como ya sabes <nombre>, los nagas siguen representando una seria amenaza para la zona. ¡Ya ha llegado la hora de devolverles al mar!\n\nCuando estés <listo/lista>, Plumasiniestra te llevará hasta la grieta donde están planeando un asalto violento. Una vez allí, utiliza el brebaje de Maurin para darles una lección que no olvidarán fácilmente.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Leotardos del barranco ventosoLúas curtidasGuardamuñecas de tejedor de marismasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14347] = {title = "Mantener el frente", objective = "Mata a 10 invasores Renegados.", description = "¡<nombre>! Sigo sin estar seguro de si estás <vivo o muerto/viva o muerta>... si eres <humano/humana> o huargen...\n\nNi siquiera estoy seguro de estar despierto. Pero de una cosa estoy seguro...\n\nVamos a matar a una cantidad ingente de esos Renegados malnacidos.", progress = nil, completion = "¡Sí, &lt;nombre&gt;! Como en los viejos tiempos...\n\nVoy a tener que esforzarme mucho para no dispararte, pero Krennan nos lo ha explicado todo.", rewards = "Brazales repelentesPretina de soldado gilneanoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14348] = {title = "No puedes acabar con ellos solo", objective = "Utiliza los barriles de pólvora negra para reventar 4 abominaciones horrorosas.", description = "Presta atención, <nombre>. Los más gordos, abominaciones los llaman, no caen con facilidad, así que no vayas a por ellos <solo/sola>.\n\nPero tengo una idea tan loca que podría funcionar. Supongo que también podría matarte, si no tenemos cuidado.\n\nHay barriles de pólvora en los cobertizos y en los molinos. Agárralos y tíraselos a las abominaciones a la cara. Yo me ocuparé del resto con este viejo trabuco oxidado.", progress = nil, completion = "Tú y yo, &lt;nombre&gt;. Formamos un gran equipo...\n\nEs fantástico tenerte de vuelta.", rewards = "Podrás elegir una de estas recompensas:\n\nAgua de manantial refrescantePan de especias\n\nTambién recibirás:\n\nBotella de Dalaran NoirObjeto #4"}
MultiLanguageQuestData['mx'][14349] = {title = "La llamada del teniente", objective = "Viaja a Entrañas y habla con Sylvanas Brisaveloz.", description = "Ha llegado la orden, <clase>. La mismísima Sylvanas ha solicitado que envíe a mis mejores agentes a Entrañas para una operación táctica muy delicada.\n\nPor desgracia, mis mejores agentes murieron hace más de tres años. Ahora solo cuento con un mísero grupo de chusma descerebrada.\n\n<Nathanos te lanza una fría mirada.>\n\nParte de inmediato hacia Entrañas y preséntate ante la Dama Oscura. ¡Y no me hagas quedar mal, <clase>!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14350] = {title = "El mensajero carmesí", objective = "Vuelve a las Tierras de la Peste del Este y encuentra al mensajero carmesí. Mata al mensajero y recupera la Orden del Gran Cruzado.\n\nLleva el documento a Nathanos Clamañublo y espera sus instrucciones.", description = "No podemos atacar a la cúpula de la Cruzada Escarlata directamente, están demasiado protegidos. Pero hay más de una forma de acabar con una plaga. No son nada sin su fuerza principal.\n\nLos mortacechadores han estado reuniendo información sobre la actividad de la Cruzada en las afueras de Stratholme. Cada día envían un informe al puesto central de Mano de Tyr. ¡Ese informe es vital, <raza>! Encuentra al mensajero carmesí y recupera el informe. Llévaselo a Nathanos.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSuministros de aventura de Rasganorte"}
MultiLanguageQuestData['mx'][14352] = {title = "Una alianza impía", objective = "Lleva el pergamino pequeño a Bragor Puñosangre, que está en Entrañas.", description = "Estimada señora:\n\nComo muy bien sabe, le estamos ofreciendo la gran oportunidad de tomar Los Baldíos y tierras circundantes. A cambio, solo pedimos ayuda, y con ello nos referimos a la libertad de acción.\n\nRogamos que lo considere. Tenemos mucho poder y deseamos compartirlo con nuestros aliados. Por el momento me mantendré alejado de Zahúrda Rajacieno.\n\nSaludos,\nEmbajador MalcinRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14353] = {title = "Una alianza impía", objective = "Lleva la cabeza del embajador Malcin a Bragor Puñosangre, que está en Entrañas.", description = "Se supone que Malcin está en Zahúrda Rajacieno. No hay lugar a dudas: debe morir.\n\nMis contactos de Orgrimmar me dicen que sus exploradores han encontrado rastros de la Peste por allí. Los jabaespines también dan señales de estar apestados, son mucho más poderosos. No sé qué está haciendo la Plaga ahí abajo, pero tiene que acabar. Ya.\n\nEncuentra a ese tal Malcin y mátalo. Vuelve a verme cuando esté muerto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "PartecalaverasEscupeuñasToga de zeloteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14354] = {title = "Los dones de Elune", objective = "Visita las reliquias de Elune en Sargeron.", description = "¡Es sencillamente intolerable!\n\nSobre todo los sátiros, profanando nuestras tierras sagradas...\n\nSus días están contados, <raza>. Te lo aseguro. En cuanto seamos suficientes, lideraré un ataque que librará a esta tierra de estas criaturas infames.\n\nPero por ahora, ¿podrías hacer algo para tranquilizarme?\n\nDirígete a Sargeron, situado en el este, y explora las ruinas. Encuentra las reliquias de Elune y asegúrate de que se encuentren en buenas condiciones.\n\nTe recompensaré generosamente por el favor.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Guantes de incubaciónGuardahombros de protecciónPodrás elegir una de estas recompensas:\n\nGargantilla de renovaciónSello de Destripademonios\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][14355] = {title = "En el Monasterio Escarlata", objective = "Mata a la alta inquisidora Melenablanca, al comandante Escarlata Mograine, a Herod el Campeón Escarlata y al maestro de canes Loksey, y después ve a ver de nuevo a Bragor Puñosangre a Entrañas.", description = "Mientras esté destinado aquí uno de mis deberes es ayudar a los Renegados a vigilar sus fronteras, <clase>, y eso es exactamente lo que tú vas a hacer por mí.\n\nVivo y respiro, pero la Cruzada Escarlata abatiría a mi gente con la misma rapidez que a los no-muertos. Son un problema, uno muy grande, y vas a tener que hacer algo al respecto.\n\nVe al Monasterio y mata a la alta inquisidora Melenablanca y a sus tenientes.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Espada de AugurioPodrás elegir una de estas recompensas:\n\nCaña proféticaCollar de sangre de dragón\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][14356] = {title = "Poder destructivo", objective = "Llévale los libros Hechizos de las Sombras y Encantamientos desde el infierno a Bragor Puñosangre, que está en Entrañas.", description = "Escucha con atención, <clase>.\n\nEs posible que no lo sepas, pero Orgrimmar tiene un problema. Una secta del Consejo de la Sombra llamada Hoja Abrasadora está realizando actos siniestros en las profundidades de Sima Ígnea. Son orcos en su mayoría y no puedo confiarles información delicada a los brutos de allá. Ahí entras tú.\n\nDeberían tener dos libros consigo. Los quiero fuera del alcance tanto de la Hoja Abrasadora como de los Renegados. Tráemelos directamente a mí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Calzas espantosasLeotardos de cenagalLeotardos gárgolaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14357] = {title = "¡Haz bien sin mirar a quién!", objective = "Recoge 20 sables de sátiro de los expositores de armas y de varios sátiros de la zona.", description = "¡Las Fámulas de Elune! Son incluso más espectaculares que en las historias que cuentan.\n\nLas leyendas que rodean esta reliquia te vienen a la memoria a medida que te aproximas:\n\nEn tiempos ancestrales, tras la batalla, las armas de los enemigos se fundían en un cuenco a cambio de algún tipo de don divino.\n\nMientras reflexionas sobre el ritual, el brillo de acero atrae tu mirada desde un expositor de armas...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Sandalias de ritualLoriga con ribeteFaja recónditaRecibirás:\n\nObjeto #20"}
MultiLanguageQuestData['mx'][14358] = {title = "10 kilos de carne", objective = "Recoge 10 trozos de carne de sátiro de los sátiros de Sargeron.", description = "Según una antigua leyenda, este viejo blandón fue ubicado en este lugar para realizar sacrificios.\n\nDe lo poco que recordamos de las historias, se sabe que el ser que coloque la carne de los enemigos de Elune en las brasas encendidas del blandón será bendecido.\n\nSi observas a tu alrededor, comprobarás que los sátiros que dominan esta región cumplen los requisitos.Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nDotación divina\n\nTambién recibirás:\n\nObjeto #10"}
MultiLanguageQuestData['mx'][14359] = {title = "Bendiciones caídas del cielo", objective = "Recoge 10 trozos de carne de sátiro de los sátiros de Sargeron y colócalos en el blandón de Elune.", description = "Sientes una profunda conexión con el pasado lejano al haber recibido la antigua bendición de la reliquia.\n\nDecides aprovechar al máximo este don divino.Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nDotación divina\n\nTambién recibirás:\n\nObjeto #10"}
MultiLanguageQuestData['mx'][14360] = {title = "Nada que no puedan arreglar un par de melones", objective = "Recoge 8 melones y exprime su jugo en la Copa de Elune en Sargeron.", description = "Las marcas de las Ruinas de Sargeron y lo que has deducido del texto de Furien aclaran una cosa:\n\nHay algo especial en la antigua fuente del Santuario de Elune.\n\nParece que se podrían obtener poderes especiales al lavarte la cara en la fuente. Claro que, primero, debería haber algo en la antigua fuente con qué lavársela.\n\nSopesando este problema, localiza algunos melones bajo algún árbol cercano...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #8"}
MultiLanguageQuestData['mx'][14361] = {title = "Paz mental", objective = "Mata a Kohor.", description = "Somos una avanzada que se encarga de vigilar enemigos potenciales. Cuando la Alianza lance su campaña en Desolace, nuestro trabajo asegurará que no haya sorpresas.\n\nRecientemente, uno de nuestros exploradores fue capturado y sacrificado por el Filo Ardiente en su bastión situado en el oeste. Desde entonces, hemos recibido burlas y amenazas de un desgraciado del Filo Ardiente llamado Kohor.\n\nSus días están contados, ¡pero pagaré generosamente a quien le silencie desde ya!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14362] = {title = "Las orejas de Filo Ardiente", objective = "Consigue 25 orejas de Filo Ardiente.", description = "El capitán Pentigast no ha ocultado su desdén por el Filo Ardiente de la Fortaleza del Hacha de Trueno.\n\nSeguramente, la prueba de su muerte le resultarÍa valiosa.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14363] = {title = "Lo sabrás cuando lo veas", objective = "Encuentra el ritual de invocación antiguo en la Fortaleza del Hacha de Trueno.", description = "Kohor habló en su último aliento de invocar a un demonio que podría amenazar toda la región.\n\nPuede que se tirara un farol, pero no es un riesgo que merezca la pena correr.\n\nNo podemos esperar a que la invasión de Desolace por parte de la Alianza tome forma. Debes registrar la Fortaleza del Hacha de Trueno en busca de pistas y acabar con esta amenaza potencial.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14364] = {title = "Juntar cabezas", objective = "Recoge 100 calaveras blanquecinas en la Fortaleza del Hacha de Trueno, colócalas en el Círculo de Invocación del Filo Ardiente y después mata a Nazargen.", description = "Así que es cierto...\n\nEl pergamino que descubriste en la Fortaleza del Hacha de Trueno describe los detalles de un poderoso ritual de invocación. El más poderoso que sepamos que posee el Filo Ardiente.\n\n¡Debemos impedir que se celebre este rito a toda costa!\n\nQuizás, si invocáramos a este demonio antes de tiempo, evitaríamos la crisis.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Capa de calavera agostadaPodrás elegir una de estas recompensas:\n\nAnillo de interrupción vigorosaGargantilla derribadora\n\nTambién recibirás:\n\nDeprecated Dwarven Squire's Pants"}
MultiLanguageQuestData['mx'][14365] = {title = "Ethel Rethor", objective = "El cabo Melkins quiere que hables con Korrah en Ethel Rethor.", description = "Hemos recibido recientemente una petición de ayuda de uno de los investigadores del Círculo Cenarion.\n\nNo nos podemos permitir enviar a nadie, así que te pido que le hagas una visita de nuestra parte.\n\nKorrah se encuentra cerca de la torre en ruinas de Ethel Rethor, en la costa oeste.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14366] = {title = "Mantenerse firme", objective = "Habla con Gwen Armstead en el Refugio del Ocaso.", description = "Ya podemos seguir nosotros, <nombre>. Informa a la alcaldesa Armstead.\n\nEsta solo es una pequeña parte de las fuerzas Renegadas. Si no nos movemos con rapidez vamos a tener aún más problemas entre manos.\n\nMira a ver qué puedes hacer para combatir al ejército Renegado en su ubicación de desembarco.", progress = nil, completion = "Una noticia excelente, &lt;nombre&gt;. He enviado al resto de la milicia a la costa para que haga frente al ejército Renegado.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14367] = {title = "El refugio de tormentas de Allen", objective = "Habla con Lord Godfrey en el interior del refugio de tormentas de la Hacienda de Allen en Gilneas.", description = "Lord Godfrey lidera el ataque cerca de la zona de desembarco Renegada. Mira a ver qué puedes hacer para ayudarnos a retener a los Renegados.\n\nMe han dicho que Godfrey ha tomado el control del refugio de tormentas en la Hacienda de Allen, al oeste. Búscalo allí.", progress = nil, completion = "Los Renegados han llegado con su máxima fuerza, &lt;nombre&gt;. Andamos justos de hombres para retenerlos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14368] = {title = "¡Salva a los niños!", objective = "Rescata a Cynthia, Ashley y James en la Hacienda de Hammond.", description = "¡Los militares no me dejan salir del refugio, pero mis hijos siguen en la granja! Por favor, ve a buscarlos.\n\nLos Renegados no sienten pena por las vidas inocentes: ¡mis hijos están en peligro!\n\nSe llaman Cynthia, Ashley y James. Si los encuentras, tráemelos aquí. Siempre estaré en deuda contigo.", progress = nil, completion = "¡Mis hijos están a salvo! Has hecho algo maravilloso, &lt;nombre&gt;. ¡No sé cómo agradecértelo!", rewards = "Leotardos de cuidadorGuantes de protecciónRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14369] = {title = "Libera a la bestia", objective = "Mata 8 soldados de a pie o marineros Renegados.", description = "No te voy a mentir, <nombre>. No me gusta la idea de contar con un huargen en nuestras filas.\n\nQuién sabe cuándo perderá su efecto el brebaje de Krennan y tratarás de arrancarnos la cabeza de un mordisco.\n\nSin embargo, hasta ese momento, podemos hacer un gran uso de tu ferocidad.\n\nQuiero que vayas al campo de batalla y mates a tantos Renegados como puedas, de la forma más brutal posible.\n\nVamos a enseñarles a temer a los huargen, <nombre>.", progress = nil, completion = "No está mal, &lt;nombre&gt;. Creo que es bueno tenerte de nuestro lado.", rewards = "Daga de GodfreyLeotardos doradosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14370] = {title = "La misteriosa azsharita", objective = "Recoge 5 muestras de azsharita de los acantilados cercanos.", description = "¡Azsharita! La misteriosa sustancia cristalina se ha utilizado para forjar armas de poder vil pero, en nuestras manos, averiguamos que puede concentrar cantidades enormes de energía. Puede que sea el mayor descubrimiento goblin desde la kaja'mita.\n\nPero, ¿qué es? ¿De dónde procede? ¿Por qué solo se encuentra aquí? ¡La ciencia exige una respuesta! Necesito más muestras que estudiar. Busca depósitos de azsharita en los acantilados cercanos.", progress = "¿Has conseguido más muestras? Los aventureros negligentes han saqueado este material durante años; ¡no saben lo valioso que es!", completion = "Ah, excelente. Algunas de estas muestras parecen frescas. ¡Voy a dejarme los cuernos en intentar resolver este misterio!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14371] = {title = "Un aperitivo gigantesco", objective = "Reúne 8 cadáveres de Brumala mutilados de los habitariscos Brumala.", description = "A la vez que investigas por los acantilados, quizás podrías ayudarme con otra línea de investigación. Los gigantes que merodean por estos acantilados han estado aquí desde que se formaron estas montañas. Puede que sepan de dónde viene la azsharita. Es de nuestro mayor interés entablar amistad con ellos y averiguarlo.\n\n¡Reúne una comida gigantesca para ofrecérsela en son de paz! Mata a los habitariscos Brumala que hayan obstaculizado nuestros estudios y tráeme sus cadáveres.", progress = "Probablemente debería haberte avisado que las quimeras Brumala lanzan rayos.", completion = "¡Fiú! ¡Qué hedor! Bueno, afortunadamente esa enorme pila de cadáveres resulte más apetitosa para un gigante.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14372] = {title = "El Campo de Thargad", objective = "Karnum Tejedor de Marismas quiere que hables con Thargad.", description = "Me complace ver que aún vives, <clase>. He sido informado de la intensificación de la actividad demoniaca en el sur.\n\nHay un campamento en las tierras fronterizas que corre peligro de quedar incomunicado si los demonios ocupan el norte.\n\n¿Podrías echarles una mano?\n\nSé que el líder del campamento es Thargad. Él sabrá guiarte sabiamente.\n\nGracias, <amigo/amiga>. Que vaya bien.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14373] = {title = "Invasión infernal", objective = "Destruye a 10 infernales inferiores.", description = "Ahora atiende y mira.\n\n<Thargad señala hacia el este.>\n\n¿Ves las bolas verdes grandes y brillantes que caen del cielo?\n\nSon un puñado de sucios demonios que merodean por las tierras inexploradas... Les he estado dando algo para que se entretetuvieran; para que reflexionaran un poco.\n\n¿Qué tal si te acercas allí y acabas lo que empecé?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Daga sangreoscuraMáscara de matademoniosBaluarte arañadoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14374] = {title = "Los portales de la Legión", objective = "Destruye 6 Portales en el Aquelarre Mannoroc.", description = "Aquí está: la Mano de Iruxos.\n\nSe la he arrebatado a uno de los líderes del Filo Ardiente yo mismo.\n\n¡Es muy poderosa! Mira, ¡la usas en portales demoniacos y simplemente desaparecen! Es una magia espeluznante, pero corren tiempos desesperados...\n\nLos demonios siguen llegando a este paso y mi campamento será invadido en un abrir y cerrar de ojos.\n\nVete ahora, ¡ponte manos a la obra!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Bastón vinculanteBrazales de portalesBufas de estampaRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14375] = {title = "Última esperanza de humanidad", objective = "Necesito que lo superes, <nombre>. Esta dosis es lo suficientemente fuerte como para matar a un caballo.\n\nPero te conozco, sé de qué estás hecho. No te pasará nada.\n\nConfía en mí. Sé a qué te enfrentas.\n\nAhora bebe y cierra los ojos.", description = nil, progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nForcecast Worgen Intro Completion\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14376] = {title = "La ruina de Jugkar", objective = "Utiliza el núcleo de energía infernal para controlar a Lord Azrethoc en el Altar de Jugkar y aprovecha su energía para matar a Jugkar Lug'vara.", description = "Reconoces la esencia de un demonio que ha sido invocado.\n\nExtrañas y peligrosas energías insondables se entretejen en esta superficie.\n\nCuando fijas tu mirada en ella, una visión inunda tu mente; una imagen de ti <mismo/misma> controlando esbirros demoniacos. Una oleada de emoción fluye en ti cuando te imaginas ejerciendo tal poder.\n\nAl observar a tu alrededor, te preguntas cómo podrías utilizar este tesoro contra el enemigo demoniaco...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14377] = {title = "Entablar amistad con los gigantes", objective = "Habla con Gormungan fuera de la Terminal de la Cohetepista del Sur y averigua el secreto de la azsharita.", description = "Un somero estudio de la azsharita que me trajiste revela que no es biológica, es decir, que no se forma naturalmente. Hay otra criatura en Azshara con propiedades similares: los gigantes del risco que merodean por estos acantilados.\n\nUno de los gigantes parece estar dispuesto a colaborar en nuestra investigación. Lleva la carne que reuniste a Gormungan, el gigante que se encuentra justo al oeste de aquí. Entabla amistad con él y, después, interrógalo. ¡Averigua si conoce el secreto de la azsharita!", progress = nil, completion = "Habla más despacio; ¿qué dices? ¿He oído bien? En realidad, esas formaciones de azsharita están dónde los gigantes van al... madre mía. ¡¡Qué asco!! No se lo digas al Dr. Martillazos, ha hecho de esto el trabajo de su vida.\n\nBueno, por lo menos ya sabemos de dónde procede la azsharita y por qué es tan difícil de encontrar. ¡Tenemos que encontrar la forma de acelerar su, eh, \"producción\"!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14378] = {title = "Cazando a Brendol", objective = "Recupera la cartera de Brendol.", description = "Estoy demasiado ocupado reuniendo artefactos para entretenerme con nada más, pero tengo un problemilla que no me importaría solucionar.\n\nUn boticario Renegado ha andado fisgoneando desde hace ya algún tiempo. Normalmente, lo ignoraría, pero ya se ha colado tres veces en mi campo y me ha robado los suministros... ¡ya está bien!\n\n¡Encuentra al ladrón y tráeme lo que quede de mis cosas!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14379] = {title = "¡Delicias de langostrok!", objective = "Consigue 7 colas de langostrok tiernas.", description = "Thargad trabaja prácticamente día y noche en la búsqueda de reliquias de titán antiguas. Está tan ocupado que, si no fuera por mí, ¡probablemente se olvidaría de comer!\n\nHablando de comida, me gustaría prepararle algo especial; quizás podrías ayudarme.\n\nLos langostroks merodean por toda la costa oeste. Nunca sobreviviría a un combate con uno de ellos pero, si me traes algunas colas, ¡prepararé una comida deliciosa!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14380] = {title = "Un descubrimiento impactante", objective = "Lleva el brebaje misterioso a Karnum al Claro de Karnum.\n\nObjeto provisto: \n", description = "<Thargad hurga en la bolsa y saca un curioso objeto.>\n\nVaya, qué raro... es un cuerno de kodo hueco que contiene una especie de brebaje.\n\n<Thargad huele la poción.>\n\n¡PUAJ! Definitivamente no puede ser ningún tipo de elixir sano. Este desastre solo puede servir para una cosa... Matar.\n\n¿Qué tal si se lo devuelves a Karnum? Ya veremos si se puede hacer algo con él...Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14381] = {title = "Limpiando la grieta", objective = "Utiliza el brebaje de Maurin para matar a 10 invasores Filozante, a 10 sirenas Filozante y a 3 gigantes de mar.", description = "Reconozco esta creación abominable. Es una terrible enfermedad que mata casi al instante, y de la forma más violenta. Detesto recurrir a tales recursos pero me temo que no queda más remedio.\n\nComo ya sabes, los nagas siguen representando una seria amenaza para la zona. ¡Ya ha llegado la hora de devolverles al mar!\n\nCuando estés <listo/lista>, Plumasiniestra te llevará hasta la grieta, donde se preparan para un violento asalto.\n\n¡Utiliza el brebaje con los nagas y sus aliados para hacer de Desolace un lugar seguro!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Leotardos del barranco ventosoLúas curtidasGuardamuñecas de tejedor de marismasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14382] = {title = "Dos junto al mar", objective = "Utiliza las catapultas de los Renegados para abordar los barcos Renegados y mata al capitán Morris y al capitán Anson.", description = "Las catapultas de los Renegados nos están acribillando, <nombre>. Incluso aunque nos ocupemos de ellas, tienen dos barcos con hileras de cañones preparados.\n\nTengo un plan para matar dos pájaros de un tiro. Y tú eres el tiro en este plan.\n\nAcaba con los controladores de las catapultas. Después, utiliza las catapultas para lanzarte a bordo de los barcos Renegados.\n\nA no ser que tu puntería sea horrible, deberías aterrizar sin problemas. Una vez a bordo, ve bajo cubierta y acaba con el capitán de cada barco. Buena suerte, <clase>.", progress = nil, completion = "Bien hecho, &lt;nombre&gt;. Puede que seas una bestia sanguinaria, pero eres nuestra bestia.", rewards = "Guantes de los dos pájarosTogas de huargen \"Volador\"Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14383] = {title = "Los terribles manitas de Las Ruinas", objective = "Mata a Bingham Cacharretio, a 4 gnomos lanzarredes y a 6 gnomos machacados en Las Ruinas.", description = "¡Canallas! ¡Infieles! Desde que puse en marcha mi operación en Azshara, la familia Cacharretio ha obstaculizado mis estudios y saboteado mi investigación. Y ahora, ¡un puñado de manitas de segunda mediocres se ha unido a ellos! Tengo un asunto urgente que atender: ocúpate de acabar con esos gnomos de una vez por todas.\n\nDirígete a Las Ruinas situadas en la costa, al sur de El Laboratorio Secreto, y empieza a hacer rodar algunas de sus cabezas desproporcionadamente grandes.", progress = nil, completion = "Oh, maravilloso. Cuéntame más. ¿Y ese joven y precoz Cacharretio? ¿También ha muerto? Ah, estupendo. Mi trabajo aquí es importante pero, a veces, echo de menos las carnicerías que se forman al destrozar al enemigo de forma algo más personal. Toma, quizás puedas hacer buen uso de las piezas de mi equipo que ya no uso.", rewards = "Tapacubos de repuesto de HobartPodrás elegir una de estas recompensas:\n\nArtilugio con resorte\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][14384] = {title = "El desvío", objective = "La oficial Jankie quiere que utilices su montura para ir hasta Punta de Nijel y que hables con el cabo Melkins.", description = "¡Alto!\n\nEn nombre de la Guardia de Punta de Nijel, tengo órdenes de enviar a cualquier aliado capacitado a informar directamente al cabo Melkins.\n\nNo estoy autorizada a ofrecer más datos al respecto.\n\nLo que puedo proporcionarte es transporte. Puedes usar mi montura, te llevará directamente.\n\nRetírate.Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nMelkins' Dummy\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14385] = {title = "El primer experimento de azsharita", objective = "Coge un laxante de tamaño gigante de la torre de los gnomos situada en Las Ruinas. Después, intenta dárselo al gigante Gormungan.", description = "Bueno, puedo pensar en una manera infalible de enviar a un gigante corriendo al baño, pero no te va a gustar. Lo que necesitamos es una... ingente cantidad de... laxante. ¡Oye! ¿Te habrías imaginado que los gnomos tendrían algo parecido? No puede ser una coincidencia. Me pregunto qué estarán intentando sacar con eso...\n\nNuestro servicio de inteligencia nos informa de que el laxante se envió a la torre de Cacharretio, situada en la línea de costa al sur de El Laboratorio Secreto. ¡Consigue ese laxante y dáselo a Gormungan!", progress = "Cuando tengas el laxante, intenta dárselo a Gormungan. Y dale una revista o algo... ¡Hazlo por la ciencia!", completion = "¿Así que no puede ir? ¿Literalmente? Bueno, Martillazos no aceptará un no por respuesta. Tenemos que intentar otra cosa.\n\nQuizás haga que mis becarios introduzcan el laxante en el campamento de elfos de la noche. Al menos nos reiríamos un rato.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14386] = {title = "Líder de la manada", objective = "Utiliza el silbato para mastines para poder matar a la forestal oscura Thyala.", description = "Excelente trabajo hasta ahora, <nombre>. Nuestros exploradores han identificado a la líder del asalto terrestre de los Renegados.\n\nUna de las forestales oscuras elegidas por Sylvanas está supervisando el frente de batalla desde la casa de Walden cercana a la orilla. Lleva este silbato y úsalo cuando estés cerca de ella.\n\nHaré que mis hombres suelten nuestros mastines de ataque para acabar con ella. Ten cuidado, <nombre>. No te conviene hacerle frente <solo/sola>.", progress = nil, completion = "Lo lograste, &lt;nombre&gt;. Con eso deberían dejar de avanzar viento en popa.", rewards = "Jubón de forestal oscuraBotas de líderTe van a lanzar el siguiente hechizo:\n\nForcecast Cataclysm I\n\nRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14387] = {title = "Preparar el terreno", objective = "El capitán Pentigast quiere que hables con Vahlarriel en Punta de Nijel.", description = "Sí, sí. <Bienvenido/Bienvenida> a Desolace, <raza>.\n\nSiento que hayamos insistido tanto pero somos una avanzada pequeña y tenemos serios problemas en esta zona; la mayoría bastante urgentes.\n\nConclusión: necesitamos toda la ayuda que podamos reunir.\n\nPara empezar, nuestro amigo Vahlarriel se ha mostrado bastante inquieto e insiste en que enviemos un contingente a visitar las ruinas del este.\n\n¿Por qué no vas a presentarte tú <mismo/misma>...?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14388] = {title = "El segundo experimento de azsharita", objective = "Habla con la asistente Greely para que te encoja. Monta una rata de la Cohetepista y utilízala para aterrorizar al gigante Gormungan.", description = "Vale, pasemos al plan B. ¡Le ASUSTAREMOS hasta que lo expulse! Por mi experiencia, la mayoría de las criaturas grandes tienen miedo de las pequeñas; como las ratas. Mmm. Este lugar está plagado de ratas pero, ¿cómo lograremos echárselas al gigante?\n\nOye, no te importa que rompa tu matriz celular y te la recomponga, ¿no? Lo único que duele es el proceso. Podría encogerte para que te montes en una de esas bestias de ahí como si fuera un caballo. ¡Es tan descabellado que tiene que funcionar! Habla conmigo cuando estés <listo/lista> para que te encoja.", progress = nil, completion = "¿Así que tampoco funcionó lo de asustarlo? ¡Vaya doble fracaso! Tendré que darle la mala noticia a Martillazos: la azsharita va a seguir siendo la sustancia más difícil de encontrar del mundo. Tendremos que usarla con moderación.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14389] = {title = "¿No era obvio?", objective = "Utiliza el portal que hay detrás de Joanna en la Torre de Xylem para encontrar a Anara, el ángel de la Resurrección, y, con un poco de suerte, a Azuregos.", description = "¡Azuregos! Sí, claro. Un viejo dragón atribulado pero de corazón noble. No creo que todos estos años que le han estado atacando los vagabundos le hayan hecho ningún bien. Anda un poco raro últimamente.\n\nNo hace mucho, cuando volvía de nuevo junto a Anara, nuestro ángel de la Resurrección local, no pude evitar darme cuenta de que ella y Azuregos parecían estar entablando amistad muy rápido. Supongo que él aún le hace compañía.\n\nEl portal que hay detrás de mí probablemente es la forma más rápida de llegar hasta ella. Sin embargo, puede resultar algo doloroso.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14390] = {title = "Fácil significa aburrido", objective = "Convence a Azuregos para que regrese al mundo de los vivos y se reúna con Kalecgos.", description = "Finalmente has encontrado a Azuregos tras una larga búsqueda con algunos giros inesperados.\n\nAhora solo es cuestión de convencerle de que se reúna con Kalecgos y ponga fin a la amenaza del Vuelo Negro en Azshara.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14391] = {title = "Cambiando las tornas", objective = "Habla con Anara para regresar al mundo de los vivos. Después reúnete con Kalecgos en la Terminal de la Cohetepista del Norte.", description = "Azuregos y Kalecgos deben reunirse en la Terminal de la Cohetepista del Norte. Tú también deberías reunirte con ellos allí para comprobar que Kalecgos no necesita más ayuda.\n\nSi prefirieses no estar <muerto/muerta>, Anara estará dispuesta a colaborar.", progress = nil, completion = "¡Me alegro de verte de nuevo! Gracias por encontrar a Azuregos y enviarlo aquí.\n\nSiento que te debo una disculpa; puede que haya subestimado lo difícil que sería realizar la tarea que te encomendé. Lo has hecho admirablemente bien, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14392] = {title = "Adiós, pezqueñín", objective = "Habla con Sorata Hilafuego en el Muelle Pantoque.", description = "Gracias, <pequeño/pequeña>.\n\nA veces es fácil perderse en los lances del amor y perder la perspectiva de las cosas, incluso siendo un dragón. Pienso volver a dedicarme por completo a asegurar que Kalec nunca ascienda y ocupe el lugar de Malygos. Es la causa más noble que se me ocurre.\n\nDeberías regresar al puerto, creo que alguien te espera.\n\nIntenta que no te aplasten ni te coman por el camino.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nSombrero de zahorí descolorido"}
MultiLanguageQuestData['mx'][14393] = {title = "¡A la refriega!", objective = "El Khan Leh'prah quiere que derrotes a 15 brujos Filo Ardiente, 3 invasores guardias apocalípticos y a la sacerdotisa Than'darissa.\n\nHabla con el Khan Leh'prah para ir a la batalla.", description = "Durante generaciones incalculables, los clanes de centauros han luchado unos con otros, pero ya se acabó.\n\nGracias a tus hazañas nos hemos unido para combatir a un mismo enemigo. Recuperaremos las tierras ancestrales que han ocupado esos demonios o moriremos como hermanos.\n\n¿Y tú, <nombre>?\n\nTe has ganado el derecho a luchar junto a nosotros. Podrías liderar mi grupo de mejores centauros en la batalla.\n\n¿Alzarás tu lanza?", progress = nil, completion = "¡Bien hecho, &lt;nombre&gt;!\n\n¡Deja que rematemos la faena!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14394] = {title = "Muerte a Agogridon", objective = "Derrota a Agogridon", description = "¡Enemigo a la vista, <nombre>!\n\nSi matamos al líder, podemos quebrantar la voluntad de este ejército demoniaco. Si lo conseguimos, ¡Desolace será nuestro!\n\nCuando estés <listo/lista>, dirige un grupo de centauros por el paso hacia el sur hasta el Barranco Rompesombras. ¡Encuentra el escondrijo de Agogridon!\n\nMientras tanto, reuniré a los otros kahnes y nos reuniremos allí para hacerle frente.Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Alfanje de AgogridonMaza almastrellaCuchilla de KolkarTe van a lanzar el siguiente hechizo:\n\nDeath to Agogridon Complete\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14395] = {title = "Luchando por respirar", objective = "Rescata a 4 veladores sumidos.", description = "¡<nombre>! Estaba de camino cuando sucedió.\n\nNo hay tiempo que perder. La mitad de veladores de la ciudad estaba en la zona que se ha venido abajo. Ve allí y salva a todos los que puedas.\n\nAsegúrate de sacarlos del agua hasta la orilla. Yo me aseguraré de que reciban toda la ayuda que necesiten.", progress = nil, completion = "Hiciste lo que pudiste, &lt;nombre&gt;. Con un poco de suerte, unos pocos más conseguirán llegar a la orilla.", rewards = "Podrás elegir una de estas recompensas:\n\nPoción de sanación menorPoción de maná menor\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][14396] = {title = "Mientras la tierra se hace añicos", objective = "Habla con el príncipe Liam Cringris en la Hacienda de Allen.", description = "¿Qué narices ha sido eso, <nombre>?\n\nEso no eran cañones ni catapultas, no hay duda.\n\nSal a ver qué está pasando.", progress = nil, completion = "El océano, &lt;nombre&gt;. Se lo ha tragado todo... la tierra... los Renegados... ¡a nuestros hombres!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14407] = {title = "El blues de Azshara", objective = "Reúnete con Kalec en el Muelle Pantoque.", description = "¡Oye! Me alegro de haberte encontrado.\n\nVengo en nombre de mi maestro, Kalec. Necesita tu ayuda. ¡Ve a buscarlo bajo el puente de los suburbios en cuanto puedas!", progress = nil, completion = "Gracias por venir. Disculpa toda esta discreción, pero es de vital importancia que no me vean ciertos individuos.\n\nEstoy en un brete y he estado siguiendo algunas de tus hazañas más recientes. Escúchame, ayúdame y me ocuparé de que se te recompense en especie.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14408] = {title = "El plan de Nueve", objective = "Consigue los diseños del cohete secreto en el edificio de los archivos del laboratorio situado en el extremo este de El Laboratorio Secreto. Llama al timbre de la puerta que hay en el exterior y mata al director cuando salga.", description = "Mis benefactores utilizaban su diminuto intelecto para construir un medio de transporte interplanetario. Diseñado con ese fin, este famoso \"cohete\" constituye una trampa mortal. Pero sospecho que si rediseñamos el compartimento catalizador de combustible conseguiremos una mezcla estable además de un subproducto de oxígeno respirable. Para aplicar los cambios, necesito los diseños de ingeniería originales.\n\nLocaliza el archivo del Laboratorio y toca el timbre para acceder. Los planes los tendrá el director en persona, suponiendo que siga con vida.", progress = "Sospecho que los archivos están cerca, <nombre>. ¡Encuentra esos diseños!", completion = "&lt;El raptor agarra los documentos con sus garras prensiles y sostiene los esquemas a la altura de su cara, castañeteando sus afilados dientes con desdén.&gt;\n\nSon como los garabatos de un niño. ¡El sentido común descarta la posibilidad de asignar la ruta de la hidráulica de control tan cerca de los quemadores de segunda etapa! Aun así, se trata de algo salvable.\n\n¿Sabes cómo volver a determinar los factores de las matrices de combustible para cambios de presión a una aceleración determinada? ¿No? Muy bien, quizás puedas hacer algo por mí mientras vuelvo a configurar el cohete...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14409] = {title = "Un regreso cauteloso", objective = "Lleva el diario de Daros a Mordent Sombrapar en Darnassus.", description = "Te pido un momento de tu tiempo, <clase>.\n\nSe acercan cambios. Nos han obligado a salir de las ruinas de Eldre'Thalas y una vez más hemos vuelto al mundo. He venido a estudiar esta ciudad y no puedo abandonarla, pero si estás disponible tengo un encargo para ti.\n\nMi compañero de investigación se ha ido a Darnassus para hablar con su suma sacerdotisa, para ver si llegamos a un acuerdo. Llévale este diario a Mordent Sombrapar al templo. Puede que le sirva de ayuda en su misión diplomática.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14410] = {title = "Las tierras salvajes de Feralas", objective = "Viaja hasta Feralas y habla con Telaron Vuelavento en el Reposo de la Soñadora.", description = "Eres realmente valiente al ayudarnos a proteger estas tierras, <héroe/heroína>. Si quieres hacer algo más por las tierras salvajes, hay otros que necesitan tu ayuda.\n\nLos verdes bosques de Feralas quedan al sur. Allí, a la sombra de Los Dos Colosos, debes buscar a Telaron Vuelavento. En el Reposo de la Soñadora, él y sus compañeros, los druidas de la Garfa han encontrado rastros de una inquietante enfermedad.\n\nNecesitarán tu ayuda, <clase>. Ve en paz.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14411] = {title = "Feralas Breadcrumb [PH]", objective = "One day I will grow up to be a real breadcrumb! To Feralas!!!!1", description = "One day I will grow up to be a real breadcrumb! To Feralas!!!!1", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][14413] = {title = "El Pináculo del aprendizaje", objective = "Habla con la imagen del archimago Xylem en la base del Pináculo Arcano.", description = "¡Qué emocionante! Te preguntarás el qué. Bueno, ¡ESTO, por supuesto!\n\nHa llegado el momento de probar... TU momento de probar. Tantos retos que superar, tanto que aprender. Estás aprendiendo sobre pruebas, y yo aprendo sobre ti.\n\nAsí que, ahora, márchate. A mi Pináculo Arcano. Me reuniré allí contigo porque, prácticamente soy omnipresente.", progress = nil, completion = "¡Qué pronto has llegado! Espero que hayas tenido buen viaje. ¿Te has mareado mucho?\n\nVas a tener que correr y saltar mucho, así que un estómago asentado sería lo más práctico.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14414] = {title = "Feralas Breadcrumb [PH]", objective = "One day I will grow up to be a real breadcrumb! To Feralas!!!!1", description = "One day I will grow up to be a real breadcrumb! To Feralas!!!!1", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][14420] = {title = "Los mortacechadores", objective = "Consigue la carta de presentación de Astor y devuélvesela a Mennet Carkad, en el Barrio de los Pícaros.", description = "Si quieres formar parte de los mortacechadores, la guardia de élite de la Dama Oscura, tendrás que demostrar tu valía.\n\nNo quiero mentirte, <nombre>, esta misión puede suponer tu muerte.\n\nTengo asuntos pendientes. Necesito los efectos personales de Astor Hadren, un mensajero que viaja entre el Bosque de Argénteos y Entrañas. Te dejo a tu elección el método que debes utilizar.\n\nCuanto menos sepas sobre la naturaleza de este asunto, mejor para ti. Si realizas con éxito está misión, te contaré más.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14422] = {title = "Cohete raptor", objective = "Libera a 5 raptores experimentales de sus jaulas en El Laboratorio Secreto y llévalos hasta el cohete que hay al lado del Sujeto Nueve.", description = "Poco después de que me desarrollaran mi intelecto, me reproduje con el Sujeto Cuatro para crear una raza única de raptores cognoscitivos superiores. Consecuentemente, el Sujeto Cuatro nunca volvió a llamar ni a escribir, por lo que he decidido destriparlo en nuestro próximo encuentro.\n\nSin embargo, hay bastantes crías de raptor encerradas en este laboratorio para proporcionar la cantidad suficiente de genes apropiados para repoblar mi raza. Te ruego que los liberes de sus jaulas y que los lleves hasta el cohete.", progress = nil, completion = "¡Maravilloso! ¡Un trabajo ejemplar, &lt;nombre&gt;! Como habrás conjeturado sin duda alguna, mi objetivo en lo que se refiere a este cohete es utilizarlo como una especie de cuna astral; un arca si lo prefieres, que permitirá a mi raza recién creada deslizarse por los hoscos vínculos de este mundo devastado y colonizar un mundo que nos complazca. Has desempeñado un papel decisivo en nuestra causa. Te ruego que aceptes esta divisa ya que acuñaré mi propia unidad monetaria cuando lleguemos. ¡Adiós, &lt;nombre&gt;!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14423] = {title = "Bulldozexorcismo", objective = "Utiliza la pistola de bengalas bendita cerca del bulldozer de Clubnik para pedir ayuda. Después, exorciza el bulldozer.", description = "... ¡Lo que necesitamos es un sacerdote!\n\nAfortunadamente he ahorrado una pequeña cantidad para la maquinaria bendita. Toma esta pistola de bengalas y vete a ver a Margene, mi pobre y dulce bulldozer destrozado. Lanza la señal y uno de nuestros mejores sacerdotes del aire aterrizará para informarse bien de la situación. ¡Vuelve cuando te hayas ocupado de mi bulldozer!", progress = "¿Cómo está Margene? ¿Ha vuelto a andar como la que solía ser?", completion = "¿Qué?... ¿qué?\n\n¡Margene! ¡¡Mi querida Margene!!", rewards = "Jubón de bulldozerGuantes de reparación de MargeneCinturón del aire estándarRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14424] = {title = "Necesitamos más ciencia", objective = "Busca a la asistente Greely en la Terminal de la Cohetepista del Sur. Puedes utilizar la Cohetepista de los goblins para desplazarte rápidamente por Azshara.", description = "<Clubnik se seca una lágrima y deja sobresalir su barbilla con determinación.>\n\n¡Nunca más, <nombre>! Ningún bulldozer se merece el destino de mi Margene. Necesitaremos material a prueba de fantasmas. Este es un trabajo para nuestros mejores científicos, ¡y conozco a la persona perfecta para realizarlo! Busca a la asistente Greely en la Terminal de la Cohetepista del Sur. Es la administradora de El Laboratorio Secreto más famoso de Azshara, y me debe un favor.", progress = nil, completion = "¿De qué habla Clubnik? ¿Maquinaria de construcción embrujada? ¿Acaso crees que tengo tiempo para historias de fantasmas?\n\nTengo un laboratorio en pleno incendio, con llamas por doquier, animales mutados y, lo peor de todo, proyectos retrasados. ¡Socorro!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14427] = {title = "Item Quest", objective = "Get the items", description = "Item collection quest", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][14428] = {title = "El diario de Ventámbar", objective = "Mata a la tradicionalista Ventámbar en el Campamento Base Darnassiano y consigue su diario.", description = "Si mis fuentes son fiables, la tradicionalista Ventámbar está supervisando la investigación que lleva a cabo la Alianza en las ruinas del este. Aún no he explorado hasta dónde alcanzan sus facultades: espero que me entregues un informe completo tras luchar contra ella y destruirla.\n\nCon un título como tradicionalista, supongo que Ventámbar llevará consigo un diario que nos informará de qué están tramando exactamente los elfos de la noche. Consígueme ese diario. No hace falta que regreses; utiliza sus propias piedras de visión para contactar conmigo a distancia.", progress = "<El rostro distorsionado de Andorel aparece en la piedra de visión.>\n\n<nombre>, ¿has establecido contacto? Cuéntame...", completion = "¿Ventámbar estaba utilizando un ensamblaje Arcano? ¡Ja! Qué deliciosamente inexperta. Es como ver jugar a un niño con un arma de fuego.\n\nEchemos un vistazo a ese diario, &lt;nombre&gt;. Mantenlo a la altura de la piedra de visión... Déjalo quieto...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14429] = {title = "Deconstrucción Arcana", objective = "Asesina a aprendices de investigador y a aprendices de iluminador para reunir 10 piedras rúnicas armonizadas.", description = "Los ensamblajes Arcanos son criaturas surgidas de maná e intelecto puros. En las manos adecuadas, un ensamblaje permite a su usuario que asimile rápidamente grandes cantidades de conocimiento Arcano. Pero son peligrosos, <nombre>. ¡Tan inteligentes! ¡Tan poderosos! ¡Tan terriblemente vulnerables a las alteraciones externas!...\n\nVamos a darles una lección a estos aficionados utilizando su magia contra ellos. Asesina a los aprendices y reúne sus piedras rúnicas para mí. Ponte en contacto conmigo mediante la piedra de visión baja cuando hayas terminado.", progress = "<La imagen de Andorel está borrosa y poco definida. Él fuerza la vista para mirarte y toca el cristal de la piedra de visión.>\n\n<nombre>, ¿eres tú? La resolución de la piedra es terrible. ¿Qué tipo de hardware utilizan?", completion = "Has hecho un buen trabajo consiguiendo esas piedras rúnicas. En realidad solo necesitaba una, pero el mero hecho de pensar en la muerte inútil de tantos elfos de la noche por unas chucherías tan inservibles me llena de oscura alegría.\n\nPor favor, coloca una de las runas en la piedra de visión para que pueda verla. Mmmm. Tal y como suponía, no es más que el trabajo de un aficionado.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14430] = {title = "Manipulando el ensamblaje", objective = "Habla con el ensamblaje Arcano en el Campamento Base Darnassiano y pronuncia las palabras de poder Arcano.", description = "Ahora manipularemos a su ensamblaje Arcano y lo emplearemos para provocar el caos. ¿Has realizado este tipo de magia antes, <nombre>? ¿No? ¡Ja! Eso hace que mi plan resulte aún más delicioso. Aquí cerca verás un enorme ensamblaje Arcano que ellos han invocado. Gracias a las piedras rúnicas que has reunido, sabemos cómo comunicarnos con él. Habla con el ensamblaje y dile: \"Al'teth la c'tolgar\". ¿Lo tienes? Repítelo. Bueno, más o menos. ¡Vuelve para informarme de lo que ha pasado!", progress = nil, completion = "¡Ja, ja! ¡Ja, JA! \"Magos\" elfos de la noche liberando a su propia creación Arcana. Me has alegrado el mes, &lt;nombre&gt;. Por este motivo los elfos de sangre no usamos ya ensamblajes Arcanos; los prohibimos hace unos 1500 años. Me divierte muchísimo ver a nuestros enemigos repetir los errores del pasado. \"Magos\". ¡Menudos magos!", rewards = "Leotardos de rebanadorBrazales de magoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14431] = {title = "La escara de los Faucenegra", objective = "Asesina a 8 biólogos de Talrendis y reúne información de los Faucenegra de uno de los cadáveres.", description = "Los fúrbolgs Faucenegra que viven en esta zona rompieron filas con sus hermanos Fauces de Madera cuando comenzamos a asentarnos a la fuerza en Azshara. Están hechos unos salvajes, <clase>, y hostigan a nuestras fuerzas cada vez que tienen oportunidad. Y lo que es peor, los hemos visto acercarse a los elfos de la noche de Talrendis de forma amistosa. ¡No podemos permitir que se conviertan en aliados!\n\nJusto al suroeste de aquí, encontrarás una gran marca en la tierra. Mis exploradores informan actividad de los elfos de la noche en esa zona. Asesínalos y reúne toda la información que puedas.", progress = "Los Faucenegra son feroces. Si llegasen a organizarse, se convertirían en un auténtico problema para nuestro trabajo aquí.", completion = "Ya veo... Esto, desde luego, tiene pinta de ser el borrador de un tratado. Es el peor escenario para nosotros, &lt;nombre&gt;: los elfos de la noche coordinando sus ataques con sus aliados fúrbolgs atrincherados.\n\nSi llevamos a cabo mi primera opción: un ataque frontal, solo conseguiremos lanzarlos a los brazos de la Alianza. Tendremos que buscar un enfoque diferente...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14432] = {title = "Una infusión de hierbas", objective = "Reúne 10 muestras de infusión de brezoriz junto al Bastión Faucenegra.", description = "Parece que nuestros enemigos de la Alianza están haciendo progresos en sus conversaciones con los Faucenegra desde que emplean la lengua de los fúrbolgs en sus negociaciones. Si pretendemos sabotear su tratado, tendremos que hacer lo mismo.\n\nNo es tan difícil como parece, <nombre>. Los Faucenegra hacen un té de hierbas muy potente: los vapores de ese té inducen un estado cercano al trance en el que empiezas a hablar un idioma extraño; el de los Faucenegra, en concreto. ¡Ve al bastión Faucenegra al suroeste de aquí y tráeme unas muestras de esa infusión de brezoriz!", progress = "¿Cómo va la cosa? Una vez probé esa hierba, brezoriz, pero me supo demasiado amarga... y eso que estoy acostumbrado a comer gravilla.", completion = "Ah, muy bien, es más que suficiente. Herviremos esto y podrás respirar los vapores durante un buen rato... Hablarás igualito que un fúrbolg en menos que canta un gallo. Nuestro plan empieza a tomar cuerpo...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14433] = {title = "Diplomacia por otros medios", objective = "Reúne la agenda de la reunión de los Faucenegra en el bastión Faucenegra y mata a la embajadora de Talrendis para apoderarte de sus togas de embajadora.", description = "Para infiltrarte y desbaratar las negociaciones de los Faucenegra, necesitamos saber dónde las están manteniendo. Sospecho que encontrarás embajadoras elfas de la noche merodeando por el bastión Faucenegra, situado al suroeste, y poniendo en marcha algunos preparativos.\n\n<Haggrum escupe al suelo.>\n\nMátalas como te plazca, y explora la zona en busca de documentos importantes. Ah sí, coge un conjunto de togas de embajadora, las necesitaremos.", progress = "¿Tienes las togas? Andorel nos ha estado incitando a usar algo de magia.", completion = "¡Un trabajo excelente! Déjame ver esos documentos. Mmm. Ahora sabemos cuándo y dónde tendrán lugar las últimas negociaciones. No te preocupes si no te valen esas togas, lo tengo todo planeado.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14435] = {title = "La traición a los Faucenegra", objective = "Ponte el disfraz de embajador y habla con Andorel Jurasol para teletransportarte hasta Bastión Faucenegra. Habla con Ungarl para romper las negociaciones y después mata a 4 guerreros Faucenegra y a 4 chamanes Faucenegra en tu camino de vuelta.", description = "Andorel ha realizado un poco de magia para mí. Ven, acércate a mi fuego y empápate de los vapores del té. Cúbrete con la toga que tienes al lado y tomarás la apariencia de un embajador de los elfos de la noche ante los Faucenegra.\n\nPonte el disfraz y habla con Andorel aquí en el campamento. Él te teletransportará hasta el corazón del Bastión Faucenegra, donde tendrán lugar las negociaciones. Habla con el jefe Ungarl y sabotea el tratado. ¡Después, mata a todos los Faucenegra que puedas en tu camino de vuelta!", progress = "Si nuestra treta funciona, <nombre>, habremos abierto un abismo insalvable entre la Alianza y los Faucenegra.", completion = "¡Victoria! Los Faucenegra ya no sabrán en quién confiar.\n\nUna vez completado este asunto tan delicado, podré concentrarme en orquestar un asalto directo contra esas bestias sin preocuparme de que se unan a la Alianza.\n\nHas hecho un buen trabajo, &lt;nombre&gt;. Tal vez deberíamos darte una plaza en el cuerpo diplomático de la Horda. ¡Ja, ja!", rewards = "Cinturón diplomáticoApisonadoras de negociaciónGuantes del rompetratosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14436] = {title = "Una excavación de los enanos", objective = "Consigue 5 picos de prospector.\n\nRompe los picos de prospector en una forja para crear herramientas rotas.\n\nLlévale 5 herramientas rotas a Ahmo Tronacuerno a Poblado Pezuña de Sangre.", description = "Unos enanos están preparando una excavación al noroeste. Creen que la tierra esconde secretos; no les falta razón, pero vaciar y profanar la tierra no es la forma de aprender lo que puede enseñarnos.\n\nRecoge las herramientas que usan los enanos para excavar, rómpelas y vuelve a verme con las herramientas rotas.\n\nPuedes inutilizar las herramientas en una forja. Hay una en Cima del Trueno, pero cualquier forja (incluso las del campamento enano) te servirá.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #5Currency Token Test Token 4"}
MultiLanguageQuestData['mx'][14437] = {title = "Los ritos de la Madre Tierra", objective = "Llévale el tótem de Viento de Halcón a Ahmo Tronacuerno a Poblado Pezuña del Trueno. Sigue el camino que sale de Campamento Narache.", description = "Si quieres continuar con los ritos de la Madre Tierra, deberás superar dos pruebas más. Es hora de que amplíes tus horizontes, <nombre>.\n\nViaja a Poblado Pezuña de Sangre y busca a Ahmo Tronacuerno. Allí podrás seguir con tu viaje y ganarte el reconocimiento de los ancianos de Cima del Trueno.\n\nLlévale este tótem a Ahmo. Reconocerá mis inscripciones y te ayudará en tu viaje.\n\nSigue el camino que sale de Campamento Narache y no te demores. No te distraigas o te perderás.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14438] = {title = "Compartir la tierra", objective = "Mata a 15 gnolls Crines Pálidas y vuelve a ver a Ahmo Tronacuerno, que está en Poblado Pezuña de Sangre.", description = "<nombre>, hay muchos conflictos que hieren nuestra tierra. Mi esperanza es que tú no vivas tantos como nuestros ancianos, pero hay uno que debo pedirte que busques. Te dará una idea de lo terrible que puede ser para la tierra incluso una amenaza pequeña, si no se controla a tiempo.\n\nLos gnolls Crines Pálidas se han asentado al sur de Pezuña de Sangre y en una cueva al oeste. Se ríen de nuestros intentos de comunicarnos con ellos y matan los animales de Mulgore sin control.\n\nLas palabras ya no sirven.", progress = nil, completion = "&lt;nombre&gt;, es bueno que te hayas tomado la misión en serio. El respeto por la tierra y sus criaturas es importante. La vida y la muerte son un ciclo, una necesidad. No puede haber una sin la otra. Tómate un tiempo para reflexionar sobre ello y no lo olvides nunca.", rewards = "Recibirás:\n\nCapa TronacuernoCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][14439] = {title = "Viaje a Cima del Trueno", objective = "Habla con Baine Pezuña de Sangre en Cima del Trueno.Ahora serás reverenciado en nuestra gran ciudad. <Todo/Toda> <raza> <digno/digna> de completar los ritos de la Madre Tierra tiene ese honor.\n\nTu última tarea es visitar a nuestro joven líder, Baine Pezuña de Sangre, que vive en la meseta más alta de Cima del Trueno.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", description = "Ahora serás reverenciado en nuestra gran ciudad. <Todo/Toda> <raza> <digno/digna> de completar los ritos de la Madre Tierra tiene ese honor.\n\nTu última tarea es visitar a nuestro joven líder, Baine Pezuña de Sangre, que vive en la meseta más alta de Cima del Trueno.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14440] = {title = "Los ritos de la Madre Tierra", objective = "Baine Pezuña de Sangre quiere que le lleves el cuerno de Arra'chea a Cima del Trueno.", description = "Has superado los ritos de la Madre Tierra y te has ganado un sitio en Cima del Trueno.\n\nSin embargo, si quieres conservar el lugar que tanto te has esforzado por conseguir, deberás seguir demostrando tu valía para tu gente.\n\nSomos cazadores, <nombre>. Abajo, en Mulgore, hay un kodo muy poderoso llamado Arra'chea. Prueba tu habilidad en el rastreo y en la caza y tráeme el cuerno de Arra'chea.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nLeotardos de cazador kodo"}
MultiLanguageQuestData['mx'][14442] = {title = "Mi sujeto favorito", objective = "Localiza a Sujeto Nueve en algún lugar cerca del complejo de El Laboratorio Secreto en Azshara.", description = "¡No sé si te habrás dado cuenta, <nombre>, pero el complejo del laboratorio apesta! Puedo ignorar a todos esos hipogrifos, pero uno de mis experimentos más preciados ha desaparecido: ¡Sujeto Nueve!\n\nSujeto Nueve es un raptor que importamos de Los Baldíos. Me pregunto si seguirá con vida. Mira a ver en el complejo principal, al oeste de aquí, cerca del cohete gigante de alto secreto. No tiene pérdida.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14443] = {title = "La empuñadura maltrecha", objective = "Lleva la empuñadura maltrecha a Caladis Lanza Reluciente en el Reposo de Quel'Delar, al sur de los Campos del Torneo Argenta.", description = "Esta vieja y maltrecha empuñadura de espada ha visto tiempos mejores. Antes de separarse de la hoja debió ser un ejemplo magnífico de la artesanía del herrero.\n\nLos elegantes símbolos y las exóticas gemas que decoran la empuñadura sugieren que el arma pudo haber pertenecido a una persona muy poderosa. Sin duda el Pacto de Plata estará interesado en el descubrimiento de semejante tesoro. Busca a su representante en el Reposo de Quel'Delar, al sur de los Campos del Torneo Argenta.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14444] = {title = "Lo que saben los dragones", objective = "Habla con Krasus en lo alto del Templo del Reposo del Dragón.", description = "No cabe duda, esta empuñadura perteneció a un arma antigua y poderosa... ¿pero a cuál? No recuerdo ver ni oír hablar de una espada con estas inscripciones, pero aún queda esperanza.\n\nKorialstrasz, también conocido como Krasus, ha sido amigo de los quel'dorei y del Kirin Tor desde hace mucho tiempo. Su conocimiento y sus recursos son inagotables, seguro que sabe algo de esto. Viaja a la cima del Templo del Reposo del Dragón, pídele consejo e informa al arcanista Tybalin en el Enclave de Plata, en Dalaran.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14446] = {title = "¡Cataclismo!", objective = "Nambria quiere que mires en las Aguas de Clarividencia.", description = "¡Escucha lo que te digo, <clase>!\n\nLos vientos de cambio han formado una violenta tormenta que barre todo Azeroth.\n\n¿Tienes el valor necesario para enfrentarte a la auténtica razón de nuestra lucha?\n\nRefuerza tu determinación, <raza> y reza para tener la fuerza y la suerte que te hagan superar las pruebas que te aguardan.\n\nUn aliado inesperado ha lanzado una llamada para todo el que pudiera oírla. ¡Mira en las Aguas de Clarividencia y contempla el destino del mundo!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14447] = {title = "Coge uno para conocer a uno", objective = "El atracador del cielo Korm quiere que hables con Koltira Tejemuerte en el Martillo de Orgrim.Aunque es cierto que no debemos dejar pasar cualquier oportunidad de atacar a la Alianza, no podemos olvidarnos de la Plaga.\n\nNo tenemos muchos hombres para hacer un asalto como es debido en el glaciar durante semanas, pero eso no quita que podamos aprender todo lo posible sobre sus defensas.\n\nLe he pedido a nuestro caballero de la Muerte residente que te ayude en esta hazaña. ¿Quién mejor que ellos conoce a este enemigo después de todo?\n\nDéjame que te presente a Koltira Tejemuerte.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", description = "Aunque es cierto que no debemos dejar pasar cualquier oportunidad de atacar a la Alianza, no podemos olvidarnos de la Plaga.\n\nNo tenemos muchos hombres para hacer un asalto como es debido en el glaciar durante semanas, pero eso no quita que podamos aprender todo lo posible sobre sus defensas.\n\nLe he pedido a nuestro caballero de la Muerte residente que te ayude en esta hazaña. ¿Quién mejor que ellos conoce a este enemigo después de todo?\n\nDéjame que te presente a Koltira Tejemuerte.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14448] = {title = "Coge uno para conocer a uno", objective = "El atracador del cielo Korm quiere que hables con Koltira Tejemuerte en el Martillo de Orgrim.Aunque es cierto que no debemos dejar pasar cualquier oportunidad de atacar a la Alianza, no podemos olvidarnos de la Plaga.\n\nNo tenemos muchos hombres para hacer un asalto como es debido en el glaciar durante semanas, pero eso no quita que podamos aprender todo lo posible sobre sus defensas.\n\nLe he pedido a nuestro caballero de la Muerte residente que te ayude en esta hazaña. ¿Quién mejor que ellos conoce a este enemigo después de todo?\n\nDéjame que te presente a Koltira Tejemuerte.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", description = "Aunque es cierto que no debemos dejar pasar cualquier oportunidad de atacar a la Alianza, no podemos olvidarnos de la Plaga.\n\nNo tenemos muchos hombres para hacer un asalto como es debido en el glaciar durante semanas, pero eso no quita que podamos aprender todo lo posible sobre sus defensas.\n\nLe he pedido a nuestro caballero de la Muerte residente que te ayude en esta hazaña. ¿Quién mejor que ellos conoce a este enemigo después de todo?\n\nDéjame que te presente a Koltira Tejemuerte.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14449] = {title = "El primer paso", objective = "Sigue el camino que hay hacia el este saliendo del Campamento Narache y busca a Grull Viento de Halcón.", description = "Joven, lo que ves aquí es el resultado del trabajo de los jabaespines. Año tras año han asaltado nuestro poblado. El Gran Cataclismo acabó por alejarlos de sus cubiles y se reprodujeron como langostas por todo el territorio, y ahora ves el resultado. Mi propia madre murió a causa de su salvajismo.\n\nA día de hoy tú has madurado. Hoy vas a coger tu arma y vas a luchar por la tribu y a vengar a la abuela. Sigue el camino hacia el este y encuentra a mi hijo Grull. Él te guiará en nuestro ataque contra los jabaespines.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14450] = {title = "Random Drop Test Progressive", objective = "Get 10 Progressive Widgets.", description = "This quest tests random drops with progressive drop percentage.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][14451] = {title = "Random Drop Flat Rate", objective = "Get 10 Flat Widgets.", description = "This quest tests random drops with flat rate drop percentage.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][14452] = {title = "Rito de la fuerza", objective = "Mata a 6 invasores Erizapúas.", description = "Observa, <nombre>. La sola presencia de los Erizapúas es una plaga. No queda nada a su paso, excepto cadáveres y terreno arrasado. El Campamento Narache podría acabar igual en pocos días a no ser que resistamos y luchemos.\n\nEste será tu Rito de la Fuerza: la primera ceremonia de un valiente tauren. Adéntrate en el corazón de El Gruñospina y mata jabaespines Erizapúas. Después, vuelve conmigo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Brazal blanqueado por el solMartillo salpicado de barroDaga ceremonial rojaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14454] = {title = "El guerrero capturado", objective = "Consigue una llave rudimentaria de uno de los jabaespines Erizapúas y úsala para abrir la jaula de jabaespines que encierra a Valiente Cuerno Afilado.", description = "Los jabaespines no solo han arrasado nuestros edificios, sino que también han tomado a tauren cautivos. Los vi llevarse a Valiente Cuerno Afilado, nuestro joven instructor de guerreros, y lo encerraron en una de sus estúpidas jaulas. Por favor, ¡busca por los cuerpos de los jabaespines una llave y sálvalo!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14456] = {title = "Rito del Valor", objective = "Recupera 7 rifles robados de los ladrones de armas Erizapúas.", description = "<nombre>, una de las primeras lecciones que deberías aprender es la de no infravalorar nunca a tu presa.\n\nMientras nos ocupábamos del ataque al Campamento Narache, más Erizapúas se colaron inadvertidamente y robaron uno de nuestros alijos de rifles. Ahora se les puede ver al sur llenando el aire de plomo.\n\nEste es tu Rito del Valor: Afronta la salva de metralla, persigue a los ladrones de armas Erizapúas y recupera nuestros rifles.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Togas del solLeotardos de persigueconejosRifle de acechador lejanoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14458] = {title = "Ve con Adana", objective = "Ve con Adana Tronacuerno al suroeste.", description = "Hemos asestado un golpe rotundo a los jabaespines. Yo me quedaré aquí, pero tú debes continuar.\n\nBusca a Adana Tronacuerno: ella se ha llevado a algunos valientes al suroeste a acabar con el resto de los Erizapúas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14460] = {title = "Rito del Honor", objective = "Mata al chivato jefe Mantospina.", description = "El chivato jefe Mantospina lidera a esos jabaespines. Fue él quien agredió a la Abuela Viento de Halcón y le quitó la vida, que conllevó al ataque sobre el Campamento Narache. Después de aquello huyó y se escondió, pero lo hemos encontrado: se esconde al oeste, en su maligno cubil de espinas, y expulsa a todos los valientes que hemos enviado.\n\nHas demostrado ser <un/una> valiente <defensor/defensora> de nuestro pueblo, <nombre>. Mata a Mantospina y llévale sus crines al Jefe Viento de Halcón, ¡en honor a nuestra Abuela!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Zapatillas de gran honorCinturón del caminasolRecibirás:\n\nBolsa de espinas"}
MultiLanguageQuestData['mx'][14461] = {title = "Alimento maligno", objective = "Usa la antorcha de Adana para prender fuego a los 3 abrevaderos en El Cercado de Jabaguerreros.", description = "Aquí debemos hacer algo más que cazar jabalíes. Se debe purgar el adefesio que nos han dejado en la tierra.\n\nPara darles una sed de sangre insaciable, obligan a los jabaguerreros a comer carne cruda. Coge esta antorcha y úsala para reducir a cenizas los abrevaderos de carne y sangre.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14462] = {title = "¿Dónde tengo la cabeza?", objective = "Te enviaron a la base de la torre norte de Punta Talrendis para que te encuentres con la asesina goblin Finta Navajazos.", description = "¡Está aquí, <nombre>! El capitán Grunwald es un oficial de alto rango de la Alianza en el Fuerte del Norte; no cabe duda de que está aquí para coordinar un asalto contra Orgrimmar con sus aliados, los elfos de la noche. Lo hemos visto entrar en la torre al suroeste de aquí. Quiero su cabeza, <clase>. Quiero enviarla al Fuerte del Norte para generar enemistad entre nuestros enemigos.\n\nHe enviado a una asesina goblin, Finta Navajazos, a la torre pero no ha vuelto. Ve a buscarla. ¡Y consígueme esa cabeza!", progress = nil, completion = "Llegas justo a tiempo, &lt;clase&gt;. Estoy a punto de llevar a cabo un asesinato de altísima precisión. Veamos...\n\n¿Explosivos? Listos.\n¿Apuñalador neumático? Listo.\n¿Paracaídas portátil? Listo.\n¿Toxina paralizante?\n\n\n\nLista. Vamos allá.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14464] = {title = "Asesinato a golpe de relámpago", objective = "Habla con Finta Navajazos para ascender a la torre y asesinar al capitán Grunwald. Recoge la cabeza del capitán Grunwald.", description = "\"Los guardias de élite del Capitán patrullan la base de la torre. Así que esto es lo que haremos: usaremos ganchos para llegar a la cima, cortaremos en pedazos a los mandamases y saldremos con mi paracaídas de baja altitud portátil. Pondré explosivos para que la torre explote cuando hayamos salido. Asegúrate de tomar la cabeza del capitán Grunwald para Chawg. ¿Entendido?\n\nNO aceptes esta misión a menos que estés <listo/lista> para la AGRESIVIDAD MÁS ABSOLUTA. ¿Está claro?\"", progress = "<nombre>, confío en que traigas buenas noticias...", completion = "La inteligencia de nuestros nuevos aliados goblin me impresiona, pero tú me impresionas más, &lt;nombre&gt;. ¡Observa la mirada de terror en el rostro del Capitán! No predijo tu ataque. Imagínate el miedo que causará en el Fuerte del Norte cuando vean lo que le pasó a uno de sus oficiales más valiosos en las tierras de los elfos de la noche.\n\nBien hecho, &lt;clase&gt;. Continuemos con el ataque...", rewards = "Guantes del malaje sin remedioParacaídas de salto baseRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14468] = {title = "Otro recién llegado", objective = "Preséntate ante el comandante Molotov en la Loma Desolada.", description = "¡Oh, menudo encargo tengo para ti! ¡Tendrás que sumergirte en culturas extranjeras, vivir aventuras épicas, volar cosas por los aires y recibir dinero a cambio! Suena demasiado bien como para ser verdad, ¿eh? ¡Pues es verdad y es justo a lo que nos dedicamos!\n\nSi te interesa, dirígete al Puesto de Defensa Gallywix, en la Loma Desolada, hacia el norte, y busca al comandante Molotov.", progress = nil, completion = "El nuevo recluta, ¿eh?\n\nSeré breve y suave contigo. Te hemos contratado para evitar que los nagas de las ruinas alcancen a Gallywix o sus propiedades. Harás todo lo que te pidamos, y yo me encargaré de que recibas tu dinero cuando acabes con todos tus asaltos.\n\nBienvenido al Batallón Pantoque.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14469] = {title = "Material heredado", objective = "Recupera 12 paquetes de suministros militares en el campo de minas central.", description = "Lo primero es lo primero, necesitamos más suministros para ti y para el resto de reclutas. En los cuerpos de los reclutas de nuestro anterior asalto tiene que haber paquetes de suministros en perfecto estado; están en el campo de minas, hacia el norte.\n\nTe recomiendo que aprendas de sus errores y evites pisar las minas.", progress = "El material reciclado no tiene nada de malo.", completion = "Eres un tipo rápido, ¿eh? Buen trabajo.\n\nAquí tienes algunos de los suministros que te mantendrán con vida.", rewards = "Recibirás:\n\nCóctel molotov"}
MultiLanguageQuestData['mx'][14470] = {title = "Avance militar", objective = "Mata al Señor de la Guerra Krellen y recupera la GCS.", description = "Hemos perdido el contacto con el sargento Dínamo, que se encontraba en la siguiente colina hacia el norte del campo de minas central. Probablemente los hayan invadido.\n\nÉl tenía nuestra última GCS. Ve hasta allí y recupérala. Acaba con todos los nagas que hayan llegado hasta allí mientras estás en la zona.", progress = "¿Dónde está mi lanzacohetes, recluta?", completion = "Un trabajo rápido, recluta.\n\nEs una preciosidad, ¿verdad? La monté yo mismo. Tengo planes especiales para esta maravilla.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14471] = {title = "Mortero de primera", objective = "Usa un mortero goblin para asesinar a 60 agresores Látigo de Ira.", description = "¡Eh, colega! ¿Te gustan las explosiones? Pues claro que sí. ¡¿A quién no le gustan las explosiones?!\n\nHe colocado morteros en la colina al este de aquí para mantener a los nagas a raya. Avanza, recluta. Dales a probar el mortero... ¡Mortero para todos! Ja, ja, ja, ja.", progress = nil, completion = "Es increíble que nos PAGUEN por esto, ¿verdad?", rewards = "Leotardos KabumCinturón lanzamorteroGuerrera de SalvobangRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14472] = {title = "¡En toda la cara!", objective = "Usa una GCS para matar a un hijo de Arkkoroc esclavizado en el campo de minas del sur.", description = "Los nagas emplean a esos gigantes para abrirse camino en nuestros campos de minas. ¡Ha llegado el momento de usar la GCS!\n\nDirígete a la entrada del campo de minas del sur... supongo que lo demás ya puedes imaginártelo.", progress = nil, completion = "¡BUM! ¡En toda la cara! Bien hecho, chico.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14475] = {title = "¡En tierra!", objective = "Encuentra al capitán bombardero Smooks en la torre más austral de los elfos de la noche en Punta Talrendis.", description = "¿No ves nada raro en estos Jinetes del Viento, <nombre>? ¡Pues que no cabalgan el viento! A cada vuelo que envío, le llueven los proyectiles de los francotiradores de los elfos de la noche.\n\nLos tiradores certeros de Talrendis se ocultan en la torre más austral, contra las montañas. He mandado a uno de estos pequeños goblins a que se haga cargo del asunto de la torre, pero no he vuelto a saber nada de él. Ve a buscar al capitán bombardero Smooks y métele la prisa en el cuerpo, ¡a golpes si hace falta!", progress = nil, completion = "¡Refuerzos, por fin!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14476] = {title = "Preparado para la explosión", objective = "Arma las tres cargas explosivas localizadas alrededor de la base de la torre más austral en Punta Talrendis.", description = "Esta torre estaba fuera del alcance de los cañones, así que pensé que podríamos volarla al estilo tradicional: en persona. Hemos colocado todas las cargas, pero los guardianes nos expulsaron antes de que pudiésemos armar los detonadores.\n\n¡<nombre>! Ve allí y arma los tres detonadores que colocamos alrededor de la base de la torre. Estas cosas están conectadas a varias bombas termales que coloqué a lo largo de la columna... ¡Será todo un espectáculo!", progress = "¿Lo conseguiste? ¿Armaste las tres?", completion = "Genial. ¡Vamos a prender fuego a esa larguirucha!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14477] = {title = "¡Pulsa el botón!", objective = "¡Detona los explosivos!", description = "Deja que confirme las conexiones... Estamos listos. Haz los honores, <nombre>. Pulsa. ¡Pulsa el botón!\n\n¡Pulsa el botón, <nombre>!\n\nDespués de los fuegos artificiales ve a ver a Kroum en Valormok y dile que el cielo está despejado.\n\n¡Pulsa el botón!", progress = nil, completion = "¡Sí, deja que ardan! Deja que ardan toda la noche, para que su columna de fuego ilumine el campo de batalla a nuestros pies mientras nosotros dejamos caer el terror sobre sus cabezas.\n\nGracias, &lt;nombre&gt;. Quédate cerca: la invasión está a punto de comenzar...", rewards = "Podrás elegir una de estas recompensas:\n\nCírculo de detonaciónSello de KroumBanda de francotirador\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][14478] = {title = "Operación Pezentraña", objective = "Preséntate para el servicio ante el comandante Molotov, situado bajo el cañón principal del Puerto Pantoque.", description = "El batallón Pantoque está reclutando soldados para la OPERACIÓN PEZENTRAÑA.\n\nEl salario consiste en una moneda de oro al completar la operación para todos los soldados activos que estén en buen estado. En caso de muerte, se suspenderá el salario. Se cobrará una cuota de 20 platas por resucitar en cumplimiento del deber.\n\nTodos los reclutas deberán presentarse directamente ante las órdenes del comandante Molotov, situado bajo el cañón principal.", progress = nil, completion = "Bienvenido de nuevo al servicio, soldado. Me alegro de contar contigo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14479] = {title = "Hay muchos como ese", objective = "Usa un cohete para llegar a La Playa Arrasada y después preséntate ante el teniente Drex.", description = "Ya basta de charla. Levanta el trasero y súbete a un cohete, soldado.\n\nY recuerda que si mueres, no cobras.", progress = nil, completion = "¿Una travesía accidentada?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14480] = {title = "Exterminio", objective = "Mata a 30 nagas Látigo de Ira en las Ruinas de Eldarath.", description = "Te mandamos hasta allí para que acabes con la infestación de los nagas. Tienes autorización para emplear fuerza letal.\n\nEl escuadrón goblin te apoyará en esta misión, por lo que debería ser un auténtico paseo.", progress = nil, completion = "Tu nombre empieza a ser conocido... Casi has alcanzado el renombre del escuadrón goblin. Eres un tipo duro.", rewards = "Escudo del Escuadrón Gob honorarioCinturón de manijeroRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14482] = {title = "La llamada del deber", objective = "Viaja en el barco mercenario a la batalla.", description = "¡<Ciudadano/Ciudadana>!\n\nComo habrás oído, la Horda está atacando nuestras fronteras. La lucha ha sido feroz y sin tregua.\n\n¡Necesitamos a todos los individuos capaces ahí fuera repeliendo al enemigo!\n\nPreséntate en el muelle norte de inmediato para ser <llevado/llevada> a la batalla.\n\nAh, nuestros barcos de guerra oficiales se están... retrasando un poco, según lo previsto. Pero no te preocupes, hemos encargado barcos mercenarios que nos servirán mientras tanto.\n\nY ahora date prisa, <clase>. ¡Ventormenta te necesita!", progress = nil, completion = "No es exactamente la batalla que esperabas, supongo. Pero no deja de ser una batalla, como pronto verás...", rewards = "Te van a lanzar el siguiente hechizo:\n\nCancelar vinculación de fase\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14483] = {title = "Hay algo en el aire (y no es amor)", objective = "Llévale la tarjeta preciosa descolorida al detective Snap Tuerceganzúas en Orgrimmar.", description = "El interior de la tarjeta está garabateado con planes dementes y detallados para infectar a la mayor parte de Azeroth. ¡Deberías enseñárselo a uno de los investigadores de Bonvapor enseguida!", progress = "¿Te has encargado de esos villanos intrigantes?", completion = "¿Qué tienes ahí?\n\nOye, esto es grande. Muy grande. Casi hasta el último detalle en tamaño bolsillo. Gracias, nos has ayudado a controlar toda esta situación. Me alegro de haber trabajado contigo.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14484] = {title = "La cabeza de la serpiente", objective = "Mata a Lord Kassarus en el Templo de Zin-Malor.", description = "En el campamento de oficiales nos enseñaron a cortar siempre la cabeza a la serpiente. No parecía una gran lección ya que nunca nos enfrentamos con serpientes, pero supongo que ahora todo cobra sentido.\n\nLleva a tus hombres ahí dentro y mata a Lord Kassarus.", progress = nil, completion = "Me alegro de que estés de nuestro lado, soldado.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14485] = {title = "Necesitamos a Tictac", objective = "Lleva a Tictac a las ruinas y cúbrelo mientras coloca bombas en 3 de las piedras rúnicas Látigo de Ira.", description = "Nuestro mejor hombre para las demoliciones, Tictac, está en una misión con el escuadrón goblin. Tiene explosivos de SOBRA para todas las piedras rúnicas de las ruinas.\n\nLo único que tú tienes que hacer es llevarlo hasta allí y cubrirlo; él se encargará de lo demás.", progress = nil, completion = "Esperamos que eso interrumpa una fuente principal de magia. Aunque lo cierto es que no tenemos ni idea de si será así. Pero bueno, nunca hay que desperdiciar la oportunidad de volar algo por los aires.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14486] = {title = "Manejar la mercancía", objective = "Reúne 12 tablillas de Altonato en las Ruinas de Eldarath.", description = "Hola, colega. ¿Quieres hacer dinero fácil?\n\nTráeme todas las tablillas de Altonato que encuentres en las ruinas.", progress = "Los elfos de sangre se comen esas tablillas. Dan buena pasta.", completion = "Excelente. Aquí está tu parte.\n\nEs un placer hacer negocios contigo.", rewards = "Bastón de EldarathLeotardos ciervo rápidoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][14487] = {title = "Corazón palpitante", objective = "Recupera el corazón de Arkkoroc del centro de las Ruinas de Eldarath.", description = "El comandante Molotov ha encontrado a alguien en El Laboratorio Secreto interesado en comprar el artefacto que exploraste con anterioridad.\n\nSin duda, seguirá en el centro de las ruinas con la Suma sacerdotisa, donde lo viste por primera vez. Tráelo aquí intacto, soldado.", progress = "Me encanta que la gente deje artefactos de gran valor por ahí.", completion = "¡Ja, ja, ja! ¡Es ENORME!\n\nSe lo llevarás a Tío Jaleo en cuanto todo esté limpio por aquí y en cuanto tú estés listo para salir.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][14488] = {title = "¡Citado!", objective = "Entrega la citación judicial al boticario Hummel en el Castillo de Colmillo Oscuro.", description = "Lo has conseguido, ¿eh? Bien. Estaba esperando ayuda. Por qué dejar para mañana lo que puedes hacer hoy, ya sabes.\n\nToma este paquete y adéntrate para entregar una citación al líder de esa despreciable compañía de químicos, Hummel. Los papeles están dentro, junto con una sorpresa que te protegerá de cualquier truco químico que intenten. Usa uno de los neutralizadores cuando llegue el momento, ¿de acuerdo?", progress = "No recuerdo haber pedido un servicio de limpieza... Sí, soy el boticario Hummel, ¿por qué?\n\nUn momento, ¿qué significa esto? ¿Crees que estos míseros papeles pueden detenerme? ¡Ja!", completion = "Lo que hacemos aquí no es asunto tuyo...", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][14491] = {title = "La tierra inquieta", objective = "Utiliza los tambores de la tierra aliviada para calmar a 6 espíritus de tierra perturbados.", description = "Hasta que hace poco un grupo de enanos se colaron en nuestras tierras al oeste, agujereando la tierra sin mesura en busca de tesoros. Cuando la mismísima tierra se quebró, los espíritus de la tierra contra los que habían abusado se alzaron y se vengaron.\n\nLos espíritus agitados de la tierra aún vagan por el antiguo yacimiento, <nombre>. Debemos apaciguarlos.\n\nLlévate este tambor al oeste y tócalo para los espíritus. Puede que el ritmo calme su furia y confusión.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Guantes sin sosiegoCoselete del sonido del tamborTomahawk ceremonial desgastadoRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][20440] = {title = "Pozos envenenados", objective = "Reúne 6 garras de lobo de pradera y 4 garfas de zancudo de llanura.", description = "Nuestros pozos sagrados han sido mancillados y necesitaré tu ayuda para arreglar todo esto.\n\nPara limpiar cada uno de los pozos debo crear un tótem de limpieza. Después debes llevar el tótem al pozo y practicar un ritual de purificación.\n\nEn primer lugar crearemos un tótem de limpieza para el Pozo Pezuña Invernal. Para ello, la tierra debe ofrecernos su ayuda. Caza lobos de pradera para conseguir sus garras y a zancudos de llanura adultos para conseguir sus garfas. Están al suroeste.\n\nVuelve aquí con las garras y las garfas, <nombre>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][20441] = {title = "Rito de la Visión", objective = "Bebe el Agua de Visión delante del fuego tribal en el Poblado Pezuña de Sangre.", description = "<nombre>, una vez más, asegúrate de estar <preparado/preparada> para dejar atrás el Poblado Pezuña de Sangre. El siguiente paso de tu viaje te llevará lejos de aquí.\n\nTu trayecto continúa hacia delante, a través de los campos de Mulgore, y los ojos de la Tierra Madre velarán por ti en todo momento. Cuando estés <listo/lista>, consume las aguas cercanas al fuego tribal. Cuando hayas ingerido las aguas sagradas, tus ojos se abrirán y los espíritus te guiarán.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Jubón de la Madre TierraBrazal de caminante de lluviaRecibirás:\n\nObjeto #1Currency Token Test Token 4"}
MultiLanguageQuestData['mx'][24215] = {title = "Los ritos de los Vientos", objective = "Bebe el agua de Visión.\n\nObjeto provisto: \n", description = "Mira, <nombre>. Las extensas llanuras de Mulgore yacen ante ti: nuestro hogar, la cuna de la Madre Tierra. Aquí es donde nos provee con todo lo que podamos necesitar, una tierra verde y pacífica. Esto es lo que protegerás luchando.\n\nTu viaje te llevará mucho más allá de sus brazos protectores, a las regiones más lejanas y crueles de este mundo, y más allá.\n\nDebajo de nosotros está el Poblado Pezuña de Sangre. El primer paso de tu verdadero camino comienza ahora. Bebe el agua de Visión, y deja que los espíritus te guíen hacia adelante.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1Currency Token Test Token 4"}
MultiLanguageQuestData['mx'][24216] = {title = "Llamamiento a las armas: Garganta Grito de Guerra", objective = "Gana un encuentro en el campo de batalla de la Garganta Grito de Guerra y vuelve a ver a un belisario de la Horda en cualquier capital de la Horda, Conquista del Invierno, Dalaran o Shattrath.|n", description = "La Alianza es un enemigo insidioso, <nombre>. Dice que protege Vallefresno para justificar sus agresiones contra nuestros territorios en Los Baldíos.\n\nHoy tenemos la oportunidad de echar al enemigo de nuestras tierras de una vez por todas. ¡Ve a la Garganta Grito de Guerra y recupera lo que nos pertenece por derecho!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24217] = {title = "Llamamiento a las armas: Garganta Grito de Guerra", objective = "Gana un encuentro en el campo de batalla de la Garganta Grito de Guerra y vuelve a ver a un belisario de la Horda en cualquier capital de la Horda, Conquista del Invierno, Dalaran o Shattrath.|n", description = "La Alianza es un enemigo insidioso, <nombre>. Dice que protege Vallefresno para justificar sus agresiones contra nuestros territorios en Los Baldíos.\n\nHoy tenemos la oportunidad de echar al enemigo de nuestras tierras de una vez por todas. ¡Ve a la Garganta Grito de Guerra y recupera lo que nos pertenece por derecho!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24218] = {title = "Llamamiento a las armas: Garganta Grito de Guerra", objective = "Gana un encuentro en el campo de batalla de la Garganta Grito de Guerra y vuelve a ver a un general de brigada de la Alianza en cualquier capital de la Alianza, Conquista del Invierno, Dalaran o Shattrath.", description = "Los Centinelas Ala de Plata luchan para proteger el bosque en la Garganta Grito de Guerra. Les ayudamos, no porque seamos amantes de los árboles, sino porque el bosque forma una barrera protectora natural para el territorio de la Alianza.\n\nHoy nos necesitan más que nunca. Tenemos que desplegar refuerzos inmediatamente, ¡a menos que queramos ver Vallefresno fusionado con Los Baldíos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24219] = {title = "Llamamiento a las armas: Garganta Grito de Guerra", objective = "Gana un encuentro en el campo de batalla de la Garganta Grito de Guerra y vuelve a ver a un general de brigada de la Alianza en cualquier capital de la Alianza, Conquista del Invierno, Dalaran o Shattrath.", description = "Los Centinelas Ala de Plata luchan para proteger el bosque en la Garganta Grito de Guerra. Les ayudamos, no porque seamos amantes de los árboles, sino porque el bosque forma una barrera protectora natural para el territorio de la Alianza.\n\nHoy nos necesitan más que nunca. Tenemos que desplegar refuerzos inmediatamente, ¡a menos que queramos ver Vallefresno fusionado con Los Baldíos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24220] = {title = "Llamamiento a las armas: Cuenca de Arathi", objective = "Gana un encuentro en el campo de batalla de la Cuenca de Arathi y vuelve a ver a un general de brigada de la Alianza en cualquier capital de la Alianza, Conquista del Invierno, Dalaran o Shattrath.", description = "La realidad de luchar en varios frentes, <chico/chica>, es que, si repartimos demasiado nuestras tropas, nos arriesgamos a perderlo todo.\n\nA diario son necesarios despliegues críticos de las tropas. Hoy es la batalla de la Cuenca de Arathi la que necesita refuerzos inmediatos.\n\n¡Tráeme noticias de nuestra victoria, <nombre>! ¡No podemos permitir que la escoria de la Horda consiga los recursos que nos pertenecen por derecho!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24221] = {title = "Llamamiento a las armas: Cuenca de Arathi", objective = "Gana un encuentro en el campo de batalla de la Cuenca de Arathi y vuelve a ver a un belisario de la Horda en cualquier capital de la Horda, Conquista del Invierno, Dalaran o Shattrath.", description = "¡La Cuenca de Arathi está a punto de caer en manos de las tropas de la Alianza! Debemos enviar refuerzos en este mismo instante o todos nuestros esfuerzos habrán sido en vano.\n\nNo te retrases, <clase>. Ve a la Cuenca de Arathi y aplasta al enemigo. ¡Victoria para la Horda!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24223] = {title = "Llamamiento a las armas: Cuenca de Arathi", objective = "Gana un encuentro en el campo de batalla de la Cuenca de Arathi y vuelve a ver a un general de brigada de la Alianza en cualquier capital de la Alianza, Conquista del Invierno, Dalaran o Shattrath.", description = "La realidad de luchar en varios frentes, <chico/chica>, es que, si repartimos demasiado nuestras tropas, nos arriesgamos a perderlo todo.\n\nA diario son necesarios despliegues críticos de las tropas. Hoy es la batalla de la Cuenca de Arathi la que necesita refuerzos inmediatos.\n\n¡Tráeme noticias de nuestra victoria, <nombre>! ¡No podemos permitir que la escoria de la Horda consiga los recursos que nos pertenecen por derecho!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24224] = {title = "Llamamiento a las armas: Garganta Grito de Guerra", objective = "Gana un encuentro en el campo de batalla de la Garganta Grito de Guerra y vuelve a ver a un general de brigada de la Alianza en cualquier capital de la Alianza, Conquista del Invierno, Dalaran o Shattrath.", description = "Los Centinelas Ala de Plata luchan para proteger el bosque en la Garganta Grito de Guerra. Les ayudamos, no porque seamos amantes de los árboles, sino porque el bosque forma una barrera protectora natural para el territorio de la Alianza.\n\nHoy nos necesitan más que nunca. Tenemos que desplegar refuerzos inmediatamente, ¡a menos que queramos ver Vallefresno fusionado con Los Baldíos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24225] = {title = "Llamamiento a las armas: Garganta Grito de Guerra", objective = "Gana un encuentro en el campo de batalla de la Garganta Grito de Guerra y vuelve a ver a un belisario de la Horda en cualquier capital de la Horda, Conquista del Invierno, Dalaran o Shattrath.|n", description = "La Alianza es un enemigo insidioso, <nombre>. Dice que protege Vallefresno para justificar sus agresiones contra nuestros territorios en Los Baldíos.\n\nHoy tenemos la oportunidad de echar al enemigo de nuestras tierras de una vez por todas. ¡Ve a la Garganta Grito de Guerra y recupera lo que nos pertenece por derecho!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24226] = {title = "Llamamiento a las armas: Cuenca de Arathi", objective = "Gana un encuentro en el campo de batalla de la Cuenca de Arathi y vuelve a ver a un belisario de la Horda en cualquier capital de la Horda, Conquista del Invierno, Dalaran o Shattrath.", description = "¡La Cuenca de Arathi está a punto de caer en manos de las tropas de la Alianza! Debemos enviar refuerzos en este mismo instante o todos nuestros esfuerzos habrán sido en vano.\n\nNo te retrases, <clase>. Ve a la Cuenca de Arathi y aplasta al enemigo. ¡Victoria para la Horda!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24426] = {title = "Llamamiento a las armas: Valle de Alterac", objective = "Gana un encuentro en el campo de batalla del Valle de Alterac y vuelve a ver a un belisario de la Horda en cualquier capital de la Horda, en Conquista del Invierno, en Dalaran o en Shattrath.", description = "Hace poco hemos estado a punto de echar a los invasores Pico Tormenta del Valle de Alterac. Como resultado estamos enviando refuerzos a ayudar al clan Lobo Gélido.\n\nUna victoria decisiva allí liberaría los recursos que necesitamos para machacar a esa escoria de la Alianza en los demás frentes de guerra.\n\nVe, <nombre>. Consigue honor respondiendo a la llamada de los valientes guerreros Lobo Gélido.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24427] = {title = "Llamamiento a las armas: Valle de Alterac", objective = "Gana un encuentro en el campo de batalla del Valle de Alterac y vuelve a ver a un general de brigada de la Alianza en cualquier capital de la Alianza, en Conquista del Invierno, en Dalaran o en Shattrath.|n", description = "La realidad de luchar en varios frentes, <chico/chica>, es que, si repartimos demasiado nuestras tropas, nos arriesgamos a perderlo todo.\n\nA diario son necesarios despliegues críticos de las tropas. Hoy es la batalla por el Valle de Alterac la que necesita valientes guerreros.\n\n¡Ve, <nombre>, y ayuda a la Expedición Pico Tormenta! ¡No podemos permitir que el clan Lobo Gélido quede impune después de toda la violencia que ha infligido a nuestros hermanos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24428] = {title = "Una circunstancia desconcertante", objective = "Llévale la cabeza de Onyxia a Zardeth de los Zarpanegra al sótano de El Cordero Degollado.", description = "Has conseguido algo verdaderamente imposible. La madre de linaje del Vuelo Negro yace muerta a tus pies. Córtale la cabeza y llévasela a Zardeth de los Zarpanegra.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nColgante de diente de Onyxia chispeanteSello de matadragones pulidoDije de sangre de Onyxia purificado\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][24429] = {title = "Una circunstancia desconcertante", objective = "Llévale la cabeza de Onyxia a Neeru Hojafuego al Circo de las Sombras.", description = "Has conseguido algo verdaderamente imposible. La madre de linaje del Vuelo Negro yace muerta a tus pies. Córtale la cabeza y llévasela a Neeru Hojafuego.", progress = "¿Qué significa esto?", completion = "Me has traído la cabeza de alguien que... No, mejor no pensar demasiado en ello. Seguro que quieres una recompensa por tus heroicidades.", rewards = "Podrás elegir una de estas recompensas:\n\nColgante de diente de Onyxia chispeanteSello de matadragones pulidoDije de sangre de Onyxia purificado\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][24430] = {title = "Oscurecer el cielo", objective = "Monta en un jinete del viento en tierra y vuela hasta Punta Talrendis. Acaba con 6 lanzagujas de Talrendis y bombardea el Centro de mando.", description = "¡<nombre>! Échanos una mano, ¿quieres? Aquí el amigo Gorsch ha tenido una mala experiencia en el garito de bufé libre de pescado de la ciudad, y ahora nos falta un piloto.\n\nMi trabajo consiste en acabar con esos lanzagujas élficos antes de que ellos acaben con nuestras unidades aéreas. Monta en este jinete del viento y sube a las alturas. Uno de mis compañeros bombarderos volará contigo y bombardeará los objetivos siguiendo tus instrucciones.\n\n¡Y, oye! ¡Lanza una bomba justo en todo el medio del Centro de mando: el gran edificio al sur de aquí, al lado del puente! ¡Glorioso!", progress = nil, completion = "¡Oh, sí! ¡Me encanta el olor de la tierra recién reventada!\n\nEn el campamento se dice que la primera línea élfica se desmorona y retrocede hacia el río. Habla con Chawg y mira a ver si puedes hacer algo más para zanjar el asunto.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24431] = {title = "Receta encharcada", objective = "Llévale la receta encharcada a Christi Stockton en la Ciudad de Dalaran.", description = "Parecen los restos de una potente mezcla de vinos. Igual le interesa a la propietaria de Una Copa Más en Dalaran...", progress = "Siempre digo que el vino tiene la misma calidad que la degustadora.", completion = "Menudo hallazgo, &lt;nombre&gt;. No puedo permitir que le vendas esto a nadie más, te pagaré generosamente.", rewards = "Recibirás:\n\nPremio epicúreo"}
MultiLanguageQuestData['mx'][24432] = {title = "Piernas marinas", objective = "Erunak, en El Cúter Salobre, quiere que le lleves 3 estrellas marinas y una caracola de la Tumba del Navegante.", description = "<Bienvenido/Bienvenida> a El Cúter Salobre, <clase>.\n\nSoy Erunak, El último pasajero que queda de este antaño orgulloso navío.\n\nMe temo que tus tribulaciones no han hecho sino comenzar. Los nagas han estado atacando de forma incansable.\n\nAún no estás <equipado/equipada> de forma adecuada para ser de mucha ayuda aquí abajo, pero eso puedo arreglarlo.\n\nJusto fuera de este barco vive una raza especial de estrellas marinas. Tráeme algunas de ellas junto con una caracola. Prepararé un encantamiento que ayudará a aumentar tus posibilidades de supervivencia.", progress = "Me alegra ver que aún sigues con vida, <raza>.\n\n¿Has encontrado los objetos que necesito?", completion = "Aquí tienes, &lt;clase&gt;. Con esto, maniobrar en el mar debería resultarte algo sencillo.\n\nAhora tenemos que ponernos a trabajar. Hay mucho que hacer y muy poco tiempo.", rewards = "Aprenderás:\n\nPiernas de mar\n\nTe van a lanzar el siguiente hechizo:\n\nPiernas de mar\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][24433] = {title = "Dales un festín de terror", objective = "Ábrete camino a la fuerza a través de Punta Talrendis y mata a 12 defensores de Talrendis y a 6 centinelas de Talrendis.", description = "Nuestros brutos son fuertes, pero carecen de iniciativa. Pelean como jabatos en las primeras líneas. Pero <un/una> <clase> independiente como tú, vamos, alguien como tú podría infiltrarse tras las líneas enemigas y provocar el caos en los reductos enemigos.\n\n¡Abre una herida de destrucción en el corazón de Talrendis, <nombre>! Asesina a nuestros enemigos en el territorio que consideran seguro y deja un rastro de sangre y temor a tu paso.", progress = nil, completion = "¡Lok'tar ogar, &lt;nombre&gt;! A medida que descubran los cuerpos de sus camaradas comprenderán que no hay lugar seguro ante la furia de la Horda; y su voluntad de lucha flaqueará.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24434] = {title = "Teletransporte de comando", objective = "Asesina a 5 tradicionalistas de Talrendis y localiza una roca de invocación de tradicionalista en algún lugar en el interior de Punta Talrendis.", description = "¿Percibes los temblores de las líneas-ley de la zona, <nombre>? Yo noto un zumbido de vez en cuando, como la vibración de una cuerda. Es el tipo de resonancia que cabe esperar de un hechizo de invocación de largo alcance. Los tradicionalistas de Talrendis, con su irrisoria magia primitiva, están tratando de invocar refuerzos desde Darnassus.\n\nPodemos usar esto en nuestro favor, <nombre>. Si manipulas su roca de invocación, podremos teletransportar a un fantástico equipo de comandos tras las líneas enemigas.\n\n¡Localiza la roca de invocación en Talrendis!", progress = nil, completion = "Las imágenes de un enorme árbol distante invaden tu cerebro. Te da un vuelco el estómago en el momento en que reorientas la roca. Por un momento tus sentidos se ven invadidos por visiones de un portal de fuego, una enorme montaña, un gélido páramo y una terrible cicatriz que hiere la tierra.\n\nTras un momento, la energía mágica de la roca se calma, y sientes que estás a solo un paso de Valormok. La invasión de Andorel puede comenzar...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24435] = {title = "Haz limpieza", objective = "Mata a 12 nagas Látigo de Ira en La Playa Arrasada.", description = "Quedan un montón de nagas en esta playa. Parece que vas a tener que mojarte para el próximo trabajo, <chico/chica>.", progress = nil, completion = "Diversión limpia.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24436] = {title = "Ayuda aérea", objective = "Avisa a sacerdotes del aire desde los cuerpos de 8 soldados heridos en La Playa Arrasada.", description = "Tenemos un montón de \"soldados\" por toda la playa tratando de escaquearse de su labor, muriéndose. Encuentra a esos gandules y usa esta pistola de bengalas para llamar a un sacerdote que se haga cargo de la situación.\n\nNo podemos permitir que nuestros hombres piensen que se pueden escaquear tan fácilmente.", progress = nil, completion = "Has hecho un buen trabajo, chico. Limpiaremos esta playa en un santiamén.", rewards = "Capa desechableHacha de HortRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][24437] = {title = "El primero en llegar, se lo queda", objective = "Coloca la bandera de reivindicación territorial de Ruckus cerca de los inmuebles de alta calidad en La Playa Arrasada.", description = "Hay unas propiedades alucinantes en primera línea de playa. Podría vender esas propiedades por un precio 10 veces superior al precio de construcción.\n\nLas mejores propiedades son esas pagodas nagas que hay al sur, la torre que está pegada al agua y las ruinas del extremo norte de la playa. Te daré una buena pasta si reclamas esos territorios para mí antes de que acabe la batalla.", progress = nil, completion = "¡Ja, ja! Genial. Un gran trabajo, chico.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][24439] = {title = "La conquista de Azshara", objective = "Asesina al comandante Jarrodenus en Punta Talrendis y recoge su cabeza.", description = "¡<nombre>! ¿Eras tú quien pilotaba el jinete del viento que bombardeó el centro de mando? ¡Fue un golpe certero!\n\nMis exploradores me informaron que heriste de gravedad a Jarrodenus, maestro de vuelo de los Cazacielo elfos de la noche y comandante de facto del adversario.\n\nEs el momento de atacar, pero no tengo tiempo de organizar un ataque completo. Corre al edificio del centro de mando y mata al comandante Jarrodenus antes de que lleguen sus refuerzos. Tráeme su cabeza... ¡Y Azshara será nuestro!", progress = "¿Sigue Jarrodenus ladrando órdenes, o le has liberado ya de la carga de su cabeza?", completion = "...¡Entonces está hecho!\n\n&lt;Chawg supervisa el campo de batalla.&gt;\n\nTodavía quedan bolsas de resistencia alrededor de nuestro campamento, pero esta actividad de retaguardia parece ser una maniobra para una retirada completa hacia Vallefresno. ¡Azshara es nuestro!\n\nEl Jefe de Guerra será informado de esta victoria y del papel que tú has jugado en ella. Pero sin duda necesitaremos la ayuda de un &lt;clase&gt; como tú en algún otro lugar. Asegúrate de hablar con Kroum aquí en el campamento antes de irte.", rewards = "Escudo de conquista de AzsharaEscudo de Punta TalrendisVarita de jinete del vientoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24440] = {title = "La purificación de Pezuña Invernal", objective = "Utiliza el tótem de limpieza Pezuña Invernal en el Pozo Pezuña Invernal.", description = "He creado el tótem para purificar el Pozo Pezuña Invernal. Ahora debes llevarlo al pozo y realizar un ritual de purificación. El pozo está al sureste, pero ten cuidado: quienquiera que hizo esto seguirá allí, a la espera.\n\nEsta prueba puede resultar peligrosa, <nombre>. Ten cuidado... pero no permitas que escapen los profanadores de nuestro pozo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Guardabrazo de cazador de las llanurasPantalones del largo díaRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24441] = {title = "El tótem de Tronacuerno", objective = "Reúne 6 garras de acechador y 6 garras de puma de las estepas.", description = "Aún queda trabajo por hacer. Debemos crear un tótem nuevo para limpiar el Pozo Tronacuerno.\n\nDebes reunir las garras de los predadores de las llanuras de Mulgore. Caza a los acechadores de pradera y a los pumas de las estepas para conseguir sus garras. Después, vuelve conmigo.\n\nEncontrarás a los acechadores de pradera y a los pumas de las estepas al este y al oeste.", progress = "¿Traes lo que te pedí, <nombre>? El Pozo Tronacuerno se corrompe más cada minuto que pasa.", completion = "Gracias, &lt;nombre&gt;. La pureza con la que cazan esas bestias es vital en la creación del siguiente tótem de limpieza.\n\nEl Pozo Tronacuerno es un símbolo de mi propia tribu, y saber que ha sido profanado por los de nuestra propia raza hace crecer una furia en mí que no había sentido durante años.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24442] = {title = "Planes de batalla de los Kvaldir", objective = "Recupera el corazón de la neblina y llévaselo junto con los planes de ataque Kvaldir a la justicar Mariel Corazón Veraz en los campos del Torneo Argenta.", description = "Al ojear los planes de ataque requisados, te encuentras con un mapa de los Reinos del Este y de Kalimdor en el que hay varios grandes asentamientos marcados. Lees las órdenes y descubres que los capitanes Kvaldir están planeando una serie de asaltos devastadores.\n\nSegún las órdenes, los ataques comenzarán cuando el clamaneblina Yngvar \"consulte con el corazón de la neblina\". Quizás puedas retrasar los ataques si capturas el objeto profético de la Cueva del Clamaneblina, en el lado oeste del Desembarco de Hrothgar, y notificas a la justicar Mariel Corazón Veraz.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24443] = {title = "La cazadora cazada", objective = "Consigue una llave rudimentaria de uno de los jabaespines Erizapúas y utilízala para abrir la jaula de jabaespines que encierra a Honu Cazadora de Venados.", description = "Los jabaespines no solo han arrasado nuestros edificios, sino que también han tomado a tauren cautivos. Los vi llevarse a Honu Cazadora de Venados, nuestra joven instructora de cazadores, y la encerraron en una de sus estúpidas jaulas. Por favor, ¡busca una llave en posesión de los jabaespines y sálvala!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24444] = {title = "La chamán capturada", objective = "Consigue una llave rudimentaria de uno de los jabaespines Erizapúas y utilízala para abrir la jaula de jabaespines que encierra a Miira Pezuña Trueno.", description = "Los jabaespines no solo han arrasado nuestros edificios, sino que también han tomado a tauren cautivos. Los vi llevarse a Miira Pezuña Trueno, nuestra joven instructora de chamanes, y la encerraron en una de sus estúpidas jaulas. Por favor, ¡busca una llave en posesión de los jabaespines y sálvala!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24445] = {title = "La druida capturada", objective = "Encuentra a Keshu Pezuña de Árbol.", description = "La responsabilidad de defender nuestro campamento ha sido encomendada a algunos de los más jóvenes, <nombre>, y muchos de nuestros más valientes aprendices están ahí fuera mientras hablamos luchando contra los jabaespines. Temo por su seguridad...\n\nPor favor, busca a la joven druida Keshu Pezuña de Árbol al este en lo más profundo del territorio de los jabaespines. Si la encuentras a ella y al resto de aprendices con vida, deberían poder ayudarte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24446] = {title = "El Caminasol capturado", objective = "Consigue una llave rudimentaria de uno de los jabaespines Erizapúas y utilízala para abrir la jaula de jabaespines que encierra a Bowe Cuerno del Alba.", description = "Los jabaespines no solo han arrasado nuestros edificios, sino que también han tomado a tauren cautivos. Los vi llevarse a Bow Cuerno del Alba, un joven Caminasol, y lo encerraron en una de sus estúpidas jaulas. Por favor, ¡busca una llave en posesión de los jabaespines y sálvalo!Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nMulgore Quilboar Cage Invisibility Cancel\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24448] = {title = "Ascenso militar", objective = "Preséntate ante el capitán Tork en el puesto de avanzada en las Ruinas de Eldarath.", description = "El comandante Molotov ha mandado órdenes de que te enviemos a nuestro puesto de avanzada. Nos estamos preparando para enviar pelotones a las ruinas para expulsar a los nagas y recuperar el artefacto; y quiere que lideres uno de ellos.\n\nVe hasta el extremo noroeste de la playa y sigue el sendero que lleva hasta nuestra avanzada.", progress = nil, completion = "¡&lt;nombre&gt;! Has conseguido llegar de una pieza, bien.\n\nTienes que ocuparte de un montón de cosas en el interior de las ruinas. Te enviamos con los mejores para que se encarguen de todo. Ahora trabajas con la fuerza EGFA, Ejército Goblin: Fusiones y Adquisiciones. Molotov dice que estás preparado y con eso me basta.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24449] = {title = "Permiso para bajar a tierra", objective = "Lleva el corazón de Arkkoroc al Tío Jaleo en el Muelle Pantoque.", description = "La cosa va muy bien por ahora. Ha sido un auténtico placer trabajar contigo, soldado.\n\nSi estás <preparado/preparada> para llevar el artefacto de vuelta, tenemos un girocóptero listo para que te lleve de vuelta al Muelle Pantoque de modo que puedas entregárselo al Tío Jaleo en persona.", progress = "¡Ah, el hombre del momento!", completion = "¡Y vienes con el artefacto! Eso quiere decir que la operación ha sido un éxito. Fusiones y Adquisiciones funciona perfectamente solo. Esto nos supondrá un buen pellizco.\n\nEn cuanto a ti, he oído que has hecho un trabajo impresionante allá fuera. Es posible que tú solito hayas reducido los gastos en un 10%. ¡Ese es el tipo de inteligencia para los negocios que quiero en mi ejército!\n\nAquí tienes tu paga, tal como se te prometió. Y un pequeño añadido; espero que te guste.", rewards = "Brazales de adquisiciónArma de algarabíaEnvoltorio de corazónBotas fusionadorasPodrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][24451] = {title = "Audiencia con el arcanista", objective = "Consigue el escrito de Hojas antiguas forjadas por los dragones del arcanista Tybalin.", description = "He encantado el tabardo para que puedas atravesar las defensas del Enclave de Plata durante un breve período de tiempo. Debería darte tiempo a subir al nivel superior del Enclave de Plata y reunirte con el contacto de El Pacto de Plata; se le conoce como arcanista Tybalin.\n\nObtén la copia de Hojas antiguas forjadas por los dragones que sus hombres se llevaron de Reposo del Dragón, mientras tu disfraz aguante, y ven a verme.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24452] = {title = "Exploración rentable", objective = "Usa el generador de campo de sigilo para infiltrarte en las Ruinas de Eldarath e identifica el corazón de Arkkoroc.", description = "Las cosas parecen calmarse un poco. Seguramente Gallywix seguirá soltando pasta para que sigamos aquí apostados, pero tengo la sensación de que podemos sacarle más jugo al asunto.\n\nLos nagas y los gigantes de mar no son precisamente amigos, así que los nagas deben de estar controlándolos de algún modo. Toma este generador de campo de sigilo, entra en esas ruinas e infórmame si encuentras algo que tenga aspecto de ser muy valioso.", progress = nil, completion = "¡Ja, ja, ja! Estupendo. Ahora ya me encargo yo. Solo necesito encontrar un comprador y obtener el visto bueno del Tío Jaleo.\n\nAquí tienes tu paga por el trabajo que has hecho. Un trabajo excelente, soldado.", rewards = "Guantes molotovBrazales valiososRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][24453] = {title = "Charla entre soldados", objective = "Habla con el soldado Vinagreta en el Intercambiador de la Cohetepista de Orgrimmar.", description = "Escucha... un último favor antes de que te vayas.\n\nEl soldado Vinagreta sigue en esa torre \"reclutando\". Ve e infórmalo de que estamos listos para irnos. Para volver a la ciudad.\n\nHa sido un placer trabajar contigo, recluta.", progress = nil, completion = "¡¿Qué?! ¿Me han dejado completamente fuera de la acción? ¿Lo dices en serio?\n\nBueno, pues... el mensajero no tiene la culpa. Gracias por las noticias, colega. Tal vez vuelva a verte en la ciudad.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24455] = {title = "Despliegue rápido", objective = "Preséntate ante el capitán Desoto en el Muelle Pantoque para comenzar el despliegue.", description = "Se presentará de inmediato al servicio. El capitán Desoto está supervisando el despliegue justo debajo de la rampa en la estación de lanzamiento de cohetes.\n\nHáganos ricos, soldado. ¡Retírese!", progress = nil, completion = "Encantado de conocerte, soldado. El comandante Molotov habla muy bien ti.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24456] = {title = "La purificación de Tronacuerno", objective = "Utiliza el tótem de limpieza Tronacuerno en el Pozo Tronacuerno.", description = "Los Tótem Siniestro son una tribu que cree que todo Kalimdor debería pertenecer exclusivamente a los tauren. Su ira y su odio condujeron a una sed insaciable de poder. Magatha, su líder, envenenó a nuestro Gran jefe Cairne Pezuña de Sangre y trató de hacerse con Cima del Trueno. Fue derrotada y los Tótem Siniestro acabaron exiliados.\n\nAhora buscan arruinar al mismísimo Mulgore mientras son expulsados. Rápido, <nombre>, ¡debes ir al Pozo Tronacuerno al norte y realizar el ritual!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Guantes TronacuernoToque del AlbaEscudo de guerra Pezuña de SangreRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24457] = {title = "Rito de la Visión", objective = "Habla con Zarlman Dos Lunas en el Poblado Pezuña de Sangre.", description = "<nombre>, no sé cómo darte las gracias por limpiar el pozo de mi tribu y por luchar contra los despiadados Tótem Siniestro para hacerlo. Pero aún hay más, y ha llegado el momento de que tu viaje te lleve más allá del Poblado Pezuña de Sangre.\n\nZarlman Dos Lunas se encuentra frente al fuego que hay al extremo norte del poblado. Ve a hablar con él para saber cuál es el siguiente ritual que deberás superar.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24458] = {title = "La bienvenida armamentística", objective = "Entrega el núcleo de azsharita armado a Bleenik Fundefusibles en el Muelle Pantoque. Habla con Friz Girasuelo para conseguir un vuelo gratis.", description = "<nombre>, tomé la muestra de azsharita purificada que recuperaste del laboratorio y la convertí en un arma. Si mis cálculos son correctos, estallará con la fuerza suficiente para arrasar una ciudad.\n\nSi me equivoco, podríamos partir el mundo en dos.\n\n¡La única manera de averiguarlo es probándola! Lleva el núcleo de azsharita al cañón gigante en Pantoque e informa a Bleenik Fundefusibles. Friz Girasuelo, mi piloto de alquiler, puede llevarte.\n\nYo te seguiré... a una distancia prudente.", progress = "Qué es lo que tienes ahí... ¿Te envía Martillazos?", completion = "¡Oh! ¡Ahí está! ¡Es espectacular!\n\n&lt;Fundefusibles grita a sus trabajadores.&gt;\n\n¡Chicos, volvemos al tajo!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24459] = {title = "Morin Acechanubes", objective = "Busca a Morin Acechanubes al este del Poblado Pezuña de Sangre.", description = "Quizás hayas oído hablar de Ventura y Cía. Son un \"cártel\" goblin, algo así como una tribu.\n\nAunque uno de esos cárteles se ha unido a nosotros en la Horda, Ventura y Cía. es fiel a su codicia. Esos goblins codiciosos y sus trabajadores ya han intentado explotar los recursos de Mulgore antes, sin mucho éxito.\n\nMorin Acechanubes, uno de nuestros avanzados, ha ido a comprobar los restos de una de las caravanas goblin. Si quieres ayudarle, sigue la carretera que sale del poblado al este.", progress = nil, completion = "Saludos. Si Ahmo ya te ha explicado los pormenores sobre el tipo de goblins que vamos a echar de nuestras tierras, pongamos pezuñas a la obra.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24460] = {title = "Out of Order", objective = "Paul's Test Questgiver wants you to kill zombies.", description = "Hey there <clase>, I need you to solve the Cataclysm. Go hunt me some zombies.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24463] = {title = "Investigaciones en Vallefresno", objective = "Habla con Kulg Salpicasangre en Vallefresno.", description = "Incluso cuando la basura darnassiana se retira de Azshara, he recibido informes confusos de mis jinetes distribuidos por Vallefresno, al oeste. Puede que los elfos de la noche estén preparando un asalto contra nuestro territorio en Los Baldíos.\n\n<clase>, necesito que te cueles por la frontera y hables con uno de mis exploradores. Habla con Kulg Salpicasangre al otro lado del puente de la frontera suroeste de la Punta Talrendis. ¡Descubre qué está sucediendo en ese bosque!", progress = nil, completion = "¿Dices que Punta Talrendis ha caído? ¡Buenas noticias!\n\nEso también explica el éxodo de elfos que vi por este camino.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24467] = {title = "Fundido a negro", objective = "Mata al señor Crepuscular Katrana y a Malicion en la Cumbre Cebellina.", description = "Vamos a acabar con esta locura de una vez por todas. Tenemos que expulsar definitivamente al Vuelo Negro de Azshara antes de que vuelvan con noticias para su maestro.\n\nTodavía no sé qué pretenden capturándonos, así que te pediré una última cosa: ve a la Cumbre Cebellina y mata a sus líderes, al señor Crepuscular Katrana y a Malicion.\n\nSi la cosa se pone fea, iré en tu ayuda. Pero no quiero arriesgarme a caer en una trampa preparada para Azuregos.", progress = nil, completion = "Realmente me sorprendes, mortal. No es habitual encontrar a alguien tan entregado y con tantos recursos.\n\nEs probable que Azuregos y yo nos vayamos de Azshara y permanezcamos separados un tiempo. Pero espero sinceramente que nos volvamos a encontrar algún día. Tal vez para acabar con el mismísimo Alamuerte.\n\nAdiós, &lt;nombre&gt;. Mantente a salvo.", rewards = "Jubón de escamas azurRegalo de KalcgosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24469] = {title = "Mantén la posición", objective = "Mata a 6 invasores Comepiedras.", description = "¡Oye, tú! Pareces <un/una> <clase> tenaz. ¿Nos echas una mano?\n\nParece que el gran terremoto de hoy sacudió a un puñado de apestosos troggs, y seguro que están que echan humo. Mis hombres están haciendo lo posible para retenerlos, pero no nos vendría mal una ayuda.\n\nCumple con tu cometido; dirígete al sur y ayuda a mis montaraces a salir del apuro. ¡Tenemos que mantener la posición!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Calzones de perímetroManos prestadasMalla de anillas de repeledor de troggsRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24476] = {title = "Templar la hoja", objective = "Templa la Quel'Delar reforjada en el Crisol de Almas.", description = "Por fin se han reunido las piezas de Quel'Delar y la espada está completa, pero no podrá volver al campo de batalla hasta que la hayas templado. Este filo de saronita tan irregular es frágil y se quebrará con solo tocarlo.\n\nEn el interior de la Forja de Almas, en la Ciudadela de la Corona de Hielo, hay un lugar donde puedes templar la hoja sin riesgo. Llévate a Quel'Delar al dominio del Devoraalmas y busca su crisol. Introduce la hoja en el crisol para templarla y vuelve con ella a Las Cámaras Heladas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24478] = {title = "La Prueba de Escarcha", objective = "Completa la Prueba de Escarcha reuniendo 20 esencias de hielo sin sufrir Abrasión de Escarcha.", description = "¿Sabes?, algunos de mis aprendices dicen que tengo el corazón frío. Pero yo siempre digo que no permitiré que la temperatura de mis órganos internos se interponga en el camino del auténtico aprendizaje.\n\nPara llegar a la Prueba de Escarcha, toca el cristal de Escarcha para abrir un portal. Una vez allí, el objetivo es sencillo: reúne los pequeños orbes flotantes de hielo.\n\nPara ponerlo un poco difícil, las Abrasiones de Escarcha giratorias pueden reducir tu progreso. Si quieres lucirte, puedes usar las trampas de runa para saltar sobre ellas mientras giran. Inteligente, ¿eh?", progress = nil, completion = "Genial. Está claro que no te quedas frío ante el peligro.\n\n¿No?... ¿Demasiado pronto?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24479] = {title = "La Prueba de las Sombras", objective = "Completa la Prueba de las Sombras atrayendo a 20 almas sollozantes hasta las runas de la Sombra sin que te toquen.", description = "No dejemos que el repertorio típico de mago nos limite en esta ocasión. Por una vez, he decidido no ser clasista. ¡La nigromancia puede ser realmente divertida!\n\nToca el cristal de Sombras para abrir un portal hasta mi Prueba de las Sombras. Una vez allí, desplázate hasta el altar cuando estés <preparado/preparada> para comenzar.\n\nLas almas sollozantes empezarán a perseguirte... Tu objetivo consiste en arrastrarlas hasta las trampas. Y asegúrate de que no te tocan.", progress = nil, completion = "Me gusta cómo te mueves, aprendiz.\n\nNo te preocupes por el origen de todas estas almas. Las conseguí de una forma perfectamente humanitaria, te lo aseguro.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24488] = {title = "Los repuestos", objective = "Reúne 6 piezas de repuesto.", description = "¡Todo mi equipo está lesionado! ¡Y todas las trituradoras estropeadas! ¡El árbitro está a punto de suspender el partido!\n\n¡¡¡Estamos con el agua al cuello y te necesito, <nombre>!!!\n\nArregla una de esas trituradoras. Hay piezas de repuesto por todo el Puerto Pantoque. Cualquier kezaniense de sangre verde te las dará si hay una posibilidad de que los Bucaneros ganen.\n\n¡Le vamos a enseñar a esos cojos de los Tiburones Bonvapor a jugar al bombalón!", progress = "¡Contamos contigo, <nombre>!", completion = "¡Ese es mi chico! ¡Ahora vete a arreglar uno de esos trastos inútiles de metal y al partido!", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24494] = {title = "Runa potenciada", objective = "Lee la runa potenciada, luego ve a Yunquemar y habla con Teo Mazatormenta.", description = "<nombre>, me fue confiada esta runa para que te la entregara. Cuando tengas la oportunidad, léela. Creo que es de Teo, el instructor de chamanes. Échale un vistazo y, cuando puedas, ve a buscar a Teo a Yunquemar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24497] = {title = "Otra vez por el aire", objective = "Asegúrate un viaje a Valormok con los sacerdotes del aire en la zona este del Muelle Pantoque.", description = "Acabamos de recibir noticias de Valormok de que no podemos enviar a más jinetes del viento si no queremos que les derriben los francotiradores de Talrendis. No podemos ceder Valermok si queremos conseguir una ruta segura a Vallefresno, así que llegaremos de otra forma.\n\nLos sacerdotes del aire se han ofrecido amablemente a transportar a alguna gente evitando el alcance de los francotiradores. Dirígete al área militar y asegúrate un sitio en uno de sus aviones. Llegarás de una pieza y, con un poco de suerte, cuando estés allí, podrás volver a asegurar nuestras líneas de vuelo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24499] = {title = "Ecos de almas torturadas", objective = "Mata a Bronjahm y al Devoraalmas para asegurar el acceso al Foso de Saron.", description = "Somos muy pocos para arriesgarnos a entrar en la Ciudadela, pero las oportunidades como esta son demasiado escasas como para dejarlas pasar.\n\nAbre un camino hasta el otro lado y asegura el paso al Foso de Saron. Tendremos que controlarlo para poder introducir a nuestros hombres en la Ciudadela.", progress = nil, completion = "¡Justo a tiempo! Gracias, &lt;nombre&gt;.\n\nEl Foso de Saron está más adelante, y si nuestros exploradores están en lo cierto al otro lado están las Cámaras de Reflexión. Es ahí donde Arthas baja la guardia, y es ahí donde esperamos encontrar pistas sobre su debilidad... o tal vez, solo tal vez, su redención.", rewards = "Recibirás:\n\nPuntos de justicia"}
MultiLanguageQuestData['mx'][24500] = {title = "La cólera del Rey Exánime", objective = "Encuentra a Lady Jaina Valiente y escapa de Las Cámaras de Reflexión.", description = "Es difícil creer que haya esperanzas de derrotar a Arthas en los peldaños de su propio trono. ¿Y quién se hará con la corona del Rey Exánime si es así?\n\nQuedan demasiadas preguntas, pero tienes que encontrar a Jaina y escapar del Rey Exánime mientras aún haya tiempo.", progress = nil, completion = "&lt;Jaina aún está recuperando el aliento.&gt;\n\nNo me puedo creer que sigamos vivos. Fue una locura por mi parte seguirle. He cometido ese error demasiadas veces. Y tú... ¡has sido un insensato por seguirme en lugar de huir con la información! Pero... bueno... gracias. Eres todo un héroe.\n\nCon la ayuda de Uther, puede que tengamos posibilidades de derrotar a Arthas. Hoy no se habrán perdido vidas en vano.", rewards = "Recibirás:\n\nPuntos de justicia"}
MultiLanguageQuestData['mx'][24502] = {title = "Dureza necesaria", objective = "Entra en el Bucanero Pantoque y lanza el bombalón a 8 Tiburones Bonvapor.", description = "Solo nos queda una trituradora. Cuando nadie miraba, la cargué con, digamos, bombalones manipulados.\n\n<Chico/Chica>, ¡necesito que te metas en esa trituradora y les des una paliza!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24504] = {title = "Despejar El Paso Elevado", objective = "Mata a 3 exploradores de El Paso Elevado.", description = "¡Por aquí, <clase>! Veo que has descubierto El Paso Elevado.\n\nLa Alianza espera romper nuestros lazos con Sierra Espolón, pero se olvidan de que nosotros, los tauren, llevamos cazando en estas tierras durante generaciones. Conocemos todos los caminos serpenteantes de las montañas y senderos de caza de aquí a Las Mil Agujas.\n\nSin embargo, para que estos caminos permanezcan abiertos, debemos evitar que los humanos tracen mapas de ellos.\n\nPatrulla por el camino del este y mata a cualquier explorador de la carretera que te encuentres. Después, habla con Tunawa Viento Apacible al final del camino.", progress = nil, completion = "Patrullar por El Paso Elevado es un asunto muy serio, pero hay que hacerlo. Estos caminos montañosos estrechos son, por ahora, una de nuestras únicas vías de comunicación con Sierra Espolón y debemos preservarlos.\n\nGracias.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24505] = {title = "Resistencia en Cerro del Cazador", objective = "Habla con Onatay en Cerro del Cazador, en Los Baldíos del Sur.", description = "Puede que hayamos perdido El Alto del Honor, pero su espíritu nunca morirá. Incluso ahora, los supervivientes siguen resistiendo en un lugar llamado el \"Cerro del Cazador\".\n\nSigue por El Paso Elevado y encontrarás nuestro campamento justo enfrente. Habla con Onatay cuando llegues e infórmale de que el camino se encuentra despejado por el momento.", progress = nil, completion = "¿Con que la Alianza está explorando el terreno de El Paso Elevado?\n\nIncluso si quisieran delinearlo, no podrían atacar en masa estas colinas. Esta es nuestra tierra, &lt;nombre&gt;, y lo pagarán caro por suponer lo contrario.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24506] = {title = "Dentro de la Ciudadela helada", objective = "Entra en la Forja de Almas por el lado de la Ciudadela de la Corona de Hielo y encuentra a Lady Sylvanas Brisaveloz.", description = "¡<clase>! ¡Ven rápido, tengo que hablar contigo!\n\nMi reina, Lady Sylvanas Brisaveloz, ha descubierto un hueco en las defensas de la Ciudadela de la Corona de Hielo. Es un lugar al que se refirió como \"La Forja de Almas\". Antes de irse me dijo que le enviara guerreros feroces... Creo que tú servirás.\n\nReúnete con ella en la entrada de la forja, <clase>.", progress = nil, completion = "Bien. &lt;nombre&gt;, he oído hablar de ti. Eres perfecto para estas tareas.\n\nNos han brindado una rara oportunidad para entrar en la Ciudadela de la Corona de Hielo, pero debemos apresurarnos para evitar la atención de Arthas.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24507] = {title = "El camino a la Ciudadela", objective = "Libera a 15 esclavos de la Horda y mata al maestro de la forja Gargelus.", description = "¡A nuestros soldados capturados los han puesto a trabajar en la cantera!\n\nMata a sus captores y libéralos, <clase>. Necesitaremos su ayuda cuando nos enfrentemos al Señor de la Plaga Tyrannus.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24510] = {title = "Dentro de la Ciudadela helada", objective = "Entra en la Forja de Almas por el lado de la Ciudadela de la Corona de Hielo y encuentra a Lady Jaina Valiente.", description = "¡<clase>! ¡Ven rápido, tengo que hablar contigo!\n\nMi superior, Lady Jaina Valiente, ha descubierto una brecha en las defensas de la Ciudadela de la Corona de Hielo. Es un lugar al que se refirió como \"La Forja de Almas\". Antes de irse me dijo que buscara toda la ayuda que pudiera... Y, bueno, esperaba que fueras tú.\n\nPor favor, reúnete con ella lo antes posible.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24511] = {title = "Ecos de almas torturadas", objective = "Mata a Bronjahm y al Devoraalmas para asegurar el acceso al Foso de Saron.", description = "Entrar en la Ciudadela con tan poca gente es arriesgado en el mejor de los casos, pero las oportunidades como esta son demasiado raras como para dejarlas pasar.\n\nAbre un camino hasta el otro lado y asegura el paso al Foso de Saron. Tendremos que controlarlo para poder introducir a nuestros hombres en la Ciudadela.", progress = nil, completion = "El Foso de Saron está más adelante y, si nuestros exploradores están en lo cierto, al otro lado están las Cámaras de Reflexión.\n\nEs ahí donde Arthas baja la guardia, y es ahí donde esperamos encontrar pistas sobre su debilidad... Y el camino hacia una merecida venganza.", rewards = "Recibirás:\n\nPuntos de justicia"}
MultiLanguageQuestData['mx'][24512] = {title = "La redención del guerrero", objective = "Consigue 5 cajas de armas confiscadas de El Alto del Honor y equipa a 5 prisioneros del Espolón. Utiliza las cuerdas cercanas para entrar y salir sigilosamente del campamento de la Alianza.", description = "Los que se rindieron cuando cayó El Alto del Honor no son dignos de la Horda, <clase>. Pero aún no les doy por perdidos. La torre de prisioneros de abajo no cuenta con muchos guardias. Vamos a darles a esos prisioneros una última oportunidad de morir con honor.\n\nHe instalado unas cuerdas que te permitirán subir y bajar por la montaña fácilmente. Baja, apodérate de las armas confiscadas y rearma a los prisioneros de la torre.\n\nY <nombre>, ¡quédate cerca de la torre! Aún no estamos preparados para asaltar la base de forma adecuada.", progress = nil, completion = "Desde aquí arriba he presenciado a la perfección el caos que acabas de sembrar, &lt;nombre&gt;. Nuestros hermanos caídos reclamaron su dignidad y los perros de la Alianza salieron escaldados. ¡Buen trabajo, amigo!\n\nSi la Alianza duerme bien por la noche, no habremos cumplido con nuestra tarea.\n\nNunca bajaremos la guardia.\n\nNunca nos rendiremos.", rewards = "Arnés de escaladaBrazales de HolgomPodrás elegir una de estas recompensas:\n\nAnillo de honor reclamado\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][24513] = {title = "Ojo por ojo", objective = "Mata al capitán Peake y entrega los ojos a Oltarg.", description = "¿Quién va? Tus pisadas no suenan como los andares indolentes de un guardia.\n\n¿<Un/Una> <clase>, dices? ¿Aún valiente y libre? No hay esperanza para mí, <amigo/amiga>. He perdido la vista y ya no sirvo para la batalla.\n\nOsé protestar cuando el capitán Peake golpeó brutalmente a uno de los prisioneros. A cambio, me pateó la cabeza una y otra vez hasta que me quedé ciego, <raza>.\n\nEncontrarás al capitán Peake en lo alto de la torre. Si quieres hacer justicia, tráeme sus ojos.\n\nSi no se desprende de ellos por las buenas... que sea por las malas.", progress = "Peake es un monstruo. Si sus superiores lo supieran, agradecerían a la Horda que haya acabado con él.", completion = "¿Los tienes? Te tomo la palabra. Oír los aullidos de Peake ha sido la mejor recompensa como su víctima.\n\nAhora, déjame aquí, &lt;nombre&gt;. No quiero ser un lastre para mi clan.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24514] = {title = "Pellejos de raptor", objective = "Reúne 8 pellejos de corredores Dienterror y segadores Dienterror.", description = "Estamos sitiados, <clase>, y entre la sima y el hostigamiento de la Alianza, andamos cortos de suministros. Pero nos apañamos con lo que tenemos, como siempre hemos hecho los tauren.\n\nA falta de una forja, un peletero habilidoso puede reforzar y reparar nuestras armaduras dañadas con pieles de alta calidad.\n\nAbajo se encuentra el terreno de caza de los raptores Dienterror. No son tan fáciles de matar, en parte por lo resistente de su gruesa piel. Cázalos, <nombre>, ¡y tráeme sus pellejos!", progress = "Los raptores Dienterror cazan en manadas y rodean a su presa. Nosotros los cazamos, sí, pero también los respetamos.", completion = "&lt;Onatay observa detenidamente los pellejos frescos asintiendo despacio.&gt;\n\nSí &lt;nombre&gt;, puedo trabajar con ellos. ¡Eres rápido!\n\nEstos pellejos nos ayudarán a aguantar más tiempo hasta que lleguen los suministros. Gracias.", rewards = "Cinturón parcheado con cueroCapa de restos de raptorBrazales de pellejo de DienterrorRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24515] = {title = "Señales del cielo", objective = "Viaja al Campamento Una'fe en La Hojarasca de Los Baldíos del Sur y habla con Makaba Pezuña Plana.", description = "Dirige tu mirada hacia el sureste. ¿Ves el humo que sale de la hoguera del Campamento Una'fe?\n\nHace apenas diez minutos que he visto grandes nubes de humo blanco surcando el cielo desde el centro del campamento. Era una antigua señal que utilizaba mi pueblo para coordinar la caza a grandes distancias, pero, esta vez, se trataba de una señal de peligro.\n\n<nombre>, mi hermano Makaba se había adentrado en esa jungla antinatural. Te ruego que te vayas allí y te asegures de que no se encuentra en apuros.\n\nExisten varios caminos: busca tiendas en la naturaleza.", progress = nil, completion = "Así que, ¿mi hermana reconoció las señales antiguas? Su vista de cazadora es más nítida que nunca.\n\n&lt;nombre&gt;, la primera vez que montamos este campamento nos encontrábamos en los límites de la jungla. ¡Ahora mira!\n\nAquí pasa algo raro.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24517] = {title = "Sembrar el terror", objective = "Mata a 8 lacayos y a un oficial de El Alto del Honor.", description = "¿Ves el camino de ahí abajo, <nombre>? Es MI camino. Y si los perros de la Alianza osan utilizarlo, deberían guardarse las espaldas.\n\n¡Es hora de cobrar el peaje! Mata a los soldados de a pie de El Alto del Honor y comprueba si podemos enviarlos de vuelta a sus muros.\n\nAsegúrate de eliminar al menos a uno de los oficiales que patrullan el camino. Deben percibir que nadie está a salvo.", progress = nil, completion = "Excelente, &lt;nombre&gt;. Todavía falta tiempo hasta que podamos asaltar el bastión como está mandado, pero, hasta entonces, debemos enseñarles a temer los Baldíos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24518] = {title = "El Paso Bajo", objective = "Entrega los diseños de carretera a Kilrok Martisangre en El Alto del Honor, en Los Baldíos del Sur.", description = "Este montón de papeles fue encontrado en una bolsa de cuero escondida bajo las ropas de un oficial.\n\nLos mapas de batalla de la región dibujan El Alto del Honor comunicado con lo que parece ser una larga carretera inacabada que cruza los Baldíos desde Theramore. ¡Parece que la Alianza planea construir un camino desde la costa directo al corazón de Kalimdor!\n\nKilrok Martisangre querrá ver esto.", progress = "Ah, ¿dices que has encontrado algo en uno de los cuerpos?", completion = "&lt;Kilrok hojea los planes que encontraste.&gt;\n\nEsto aclara muchas cosas, &lt;nombre&gt;. Con razón nuestros enemigos están decididos a tomar Los Baldíos del Sur. ¡Sus planes para el continente se centran en ello!\n\nPero no contaban con nosotros, ¿verdad, &lt;clase&gt;?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24519] = {title = "Entorpecer el peritaje", objective = "Encuentra y mata al perito Henry Zykes.", description = "Todos estos diseños han sido dibujados por la misma mano. He visto a un perito humano subir y bajar por el camino entre el bastión y la jungla al este.\n\nPodemos entorpecer sus planes dándoles una lección a costa de este perito, <nombre>.\n\n<Kilrok señala la firma del final de los diseños.>\n\n¿Qué crees que pone? ¿\"Zykes\"? Hasta los nombres humanos suenan frágiles y débiles. Mátalo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de reconocimientoCinturón de ZykesRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24520] = {title = "Cuéntale a Sassy las nuevas", objective = "Habla con Sassy Malallave en la Central SCK, en Kezan.", description = "Lo celebraría contigo, <nombre>, pero parece que ese dragón dio problemas en el Monte Kajaro. Yo... eh... ¡Creo que voy a coger mis bártulos y me voy a meter en el primer barco que zarpe de la isla!\n\nDe todas formas, igual deberías ir a la central y contarle a Sassy que ganaste el título de bombalón para nosotros. Fijo que querrá saber también lo del dragón y el Monte Kajaro.\n\n¡Buena suerte!", progress = nil, completion = "Estás bromeando, ¡¿verdad?! ¡¡¡¿ALAMUERTE?!!!\n\n&lt;Sassy entra en pánico durante un segundo.&gt;\n\nBueno, todo va a salir bien. Damos tu fiesta y para cuando se acabe, seguro que el dragón ya se habrá ido y la tierra habrá parado de temblar.\n\nSi no, siempre podemos fletar un barco para irnos de la isla.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24522] = {title = "Viaje a La Fuente del Sol", objective = "Habla con Halduron Alasol en la entrada de la Meseta de La Fuente del Sol en la Isla de Quel'Danas.", description = "Llévate a Quel'Delar a La Fuente del Sol lo antes posible, <nombre>. Cree a Uther cuando te dice que no siempre serás capaz de controlar la hoja mientras siga bajo el influjo maligno del Rey Exánime. Debes viajar a la Isla de Quel'Danas y entrar en la mismísima Fuente del Sol, donde podrás purificar la espada.\n\nLos guardianes de La Fuente del Sol no te dejarán entrar sin más, así que tendrás que buscar a Halduron Alasol. Estará inspeccionando a los guardias del lugar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24523] = {title = "El tótem Ferocrín", objective = "Lleva 4 dientes de alfa de pradera de lobos alfa de pradera.", description = "Ya solo queda por limpiar el Pozo Ferocrín. Para ello, la tierra debe ofrecernos los dientes de un depredador feroz, el lobo alfa de pradera. Los encontrarás al norte. Vuelve cuando hayas conseguido los dientes.\n\nLos alfa suelen deambular alrededor de nuestra ciudad, Cima del Trueno.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24524] = {title = "La purificación de Ferocrín", objective = "Usa el tótem de limpieza Ferocrín en el Pozo Ferocrín.", description = "Los espíritus están complacidos contigo por la limpieza del Pozo Tronacuerno y el Pozo Pezuña Invernal, joven <nombre>. El tótem de Ferocrín ya está listo y tu última tarea te espera.\n\nEl Pozo Ferocrín está al norte de Cima del Trueno. ¡Lleva a cabo el ritual! ¡Limpia la tierra del veneno de los Tótem Siniestro! Que las aguas vuelvan a fluir puras y claras.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Togas de portaaguaLeotardos de vigilaalbaBotas de correr abismosRifle de ojo de halcónRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24525] = {title = "Mantener los carroñeros a raya", objective = "Mata a 6 carroñeros Dentecenado.", description = "No todos los que huyeron de Taurajo consiguieron llegar hasta Una'fe, <nombre>. Algunos murieron heridos por el camino. Otros fueron asaltados por jabaespines oportunistas.\n\nTengo que encargarme de la peliaguda tarea de encontrar y reunir los cuerpos. Pero hay algo que puedes hacer por mí.\n\nLos carroñeros Dentecenado rondan las tierras del sur y están destrozando los cuerpos, desgarrando sus entrañas y despedazando los miembros de los muertos. Por favor, reduce el número de carroñeros para que pueda practicar unos ritos funerarios dignos.", progress = nil, completion = "Así se hace.\n\nNormalmente, los carroñeros son parte del ciclo de la vida de la Madre Tierra. Pero, tras la devastación causada por la Alianza y por el Cataclismo, su número crece de forma preocupante. Está bien rebajarlo un poco.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24527] = {title = "Tu camino comienza aquí", objective = "Aprende Golpe primigenio de Teo Mazatormenta, luego usa el Golpe primigenio 2 veces contra los muñecos de entrenamiento cerca de la entrada de Yunquemar.", description = "¡Excelente! Empecemos.\n\nLa primera habilidad que aprenderás es la del Golpe primigenio. Los espíritus primigenios, cuando los llames, le darán fuerza a tu brazo para que descargues un poderoso golpe.\n\n¿A que es práctico?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24529] = {title = "De mal en peor", objective = "Rescata a 5 refugiados Taurajo enjaulados y mata cualquier combinación de 8 tejespinas o celadores de espadas Erizapúas.", description = "Cuando los refugiados huyeron al norte desde Taurajo, algunos se separaron a medida que se cernía la oscuridad. Muchos fueron tomados como prisioneros por los jabaespines Erizapúas, que montaron campamentos al oeste y al suroeste.\n\nDesconozco qué pretenden con capturar a nuestros refugiados; todo lo que han conseguido es mi ira. Y todo lo que obtendrán será venganza.\n\nRescata a mis hermanos y hermanas cautivos y mata a sus captores para enviar un mensaje a los jabaespines.", progress = nil, completion = "Ya es bastante triste que hayan saqueado nuestro poblado pero... ¿encima tenemos que pasar la noche en una jaula de jabaespín? Me alegro de que estuvieras allí para ayudar, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24531] = {title = "Preparándose para la batalla", objective = "Aprende Cargar de Thran Khorman, luego usa Cargar contra los muñecos de entrenamiento a la entrada de Yunquemar.", description = "Lección número uno. Aparte de tu espada y tu escudo, ¿cuál es la herramienta más importante que tienes en tu arsenal?\n\n<Thran espera tu respuesta>\n\n<Tranquilo/Tranquila>, contestaré por ti. Es tu movilidad. Uno de los puntos fuertes del guerrero es la capacidad de moverse rápido por el campo de batalla. Aquí, <nombre>, te entrenaré para que aproveches tus piernas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24532] = {title = "Eviscerando al enemigo", objective = "Aprende Eviscerar de Solm Hargrin, luego usa Eviscerar 3 veces contra los muñecos de entrenamiento a la entrada de Yunquemar.", description = "Una de las cosas que hacen peligrosos a los pícaros es nuestra habilidad para combinar maniobras de combate y esperar la oportunidad de usar una técnica devastadora.\n\nAhora que has tenido la oportunidad de dominar el Golpe siniestro, ya puedo enseñarte una nueva habilidad que podrás usar a continuación.\n\nPor favor, permíteme entrenarte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24533] = {title = "Palabras de poder", objective = "Aprende Sanación relámpago de Silo Khalder, luego usa Sanación relámpago 5 veces para curar a los miembros de la milicia de Yunquemar.", description = "Bien, si DE VERDAD quieres convertirte en alguien especial, tendrás que hablar conmigo. Un sacerdote no es nada sin conjuros. Y yo conozco un par de conjuros que podría enseñarte.\n\nEl primero es un conjuro de sanación rápida que te puede ayudar cuando te hayan herido. Dime <chico/chica>, ¿te hieren alguna vez?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24534] = {title = "Hablar su idioma", objective = "Sopla el cuerno de desafío en el círculo de desafío Erizapúas y derrota a Hozasable en un combate individual.", description = "Los jabaespines nos atacan porque perciben debilidad. La fuerza es el único idioma que entienden. Así que vamos a demostrarles la nuestra.\n\n<Makaba saca un cuerno grande de su bolsa.>\n\nEs un trabajo duro, pero servirá. Los líderes Erizapúas utilizan cuernos como estos para retarse unos a otros por motivos dominantes.\n\n<nombre>, quiero que retes al campeón Erizapúas Hozasable a un combate individual. Derrótalo en presencia de sus seguidores. Sopla el cuerno en el círculo de desafío Erizapúas situado al sur.", progress = "¿Ya les has bajado los humos a los Erizapúas?", completion = "¿Qué? ¿Te atacó con otra docena de jabalís? Supongo que los jabaespines tienen sus propias ideas de lo que significa un \"combate individual\".\n\nAun así, los Erizapúas tardarán en recuperarse después del duro golpe que les has asestado. No tardará mucho en alzarse un nuevo campeón entre ellos para causar problemas... pero, al menos, esto nos da algo de tiempo para reubicar a los refugiados de forma segura.\n\nGracias, &lt;nombre&gt;. Los supervivientes están en deuda contigo.", rewards = "Botas de JabapocalipsisCapa de HozasablePodrás elegir una de estas recompensas:\n\nCírculo de desafío Erizapúas\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][24536] = {title = "Algo apesta", objective = "Usa el analizador de aire de Tuerceganzúas para analizar el aire alrededor de 6 guardias altamente perfumados. Luego vuelve con el detective Snap Tuerceganzúas en Orgrimmar.", description = "¡Fíjate en estos tipos! Bonvapor se ha estado encargando del negocio de las fiestas todos estos años, y de repente estos tipos invaden el mercado. No son Bonvapor, así que el cártel me ha contratado para investigar. Algo apesta, y no solo el perfume.\n\nLleva este aparato que me he traído y analiza las nubes de perfume que hay alrededor de los guardias. Quiero saber qué ponen en esa sustancia. No es natural.", progress = nil, completion = "Oye, gracias, chico. Trae, vamos a ver.\n\n&lt;Toma el aparato y trastea con él.&gt;\n\nOh, esto no es bueno.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][24539] = {title = "Cuando atacan las plantas", objective = "Rescata a 5 refugiados Taurajo matando las hojarascas enredadoras que les atrapan.", description = "Este campamento fue construido en los límites de la jungla y ya está lleno de plantas. ¡Aquí sucede algo anormal!\n\nAntes, cometí el error de enviar a algunos de los refugiados en mejores condiciones a recolectar frutos secos y bayas. Los que regresaron, comentaban que las plantas estaban vivas y les agarraban las piernas o, incluso, los levantaban. Estoy preocupada por los que no han vuelto todavía.\n\nPor favor, <clase>, rescata a los refugiados atrapados en las plantas enredadoras cerca del campamento.", progress = nil, completion = "Gracias, &lt;nombre&gt;. Ahora viene la pregunta:\n\n¿De dónde viene esta hojarasca? ¿Y por qué está descontrolada?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24540] = {title = "Baile de guerra", objective = "Derrota a Orno Tótem Siniestro en el Paso del Espolón.", description = "Algunos ven a nuestro pueblo como gigantes amables o como salvajes nobles. Nunca nos han visto luchar contra los de nuestra propia raza... contra traicioneros desde dentro.\n\nA los Tótem Siniestro se les ofreció misericordia en el exilio, y ellos han dañado su propio hogar por despecho hacia nosotros. Ya no se les tolerará en Mulgore.\n\nYa he enviado a guerreros para que los expulsen a través del Paso del Espolón, al norte. Has luchado con valentía contra los Tótem Siniestro, <nombre>, y te pido que vuelvas a la batalla. Ve y ayúdanos a asestar este último golpe.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Raíz de árbol atrofiadaMarra de kodoAturdidor del caminasolBastón CaminasueñosRecibirás:\n\nAlforjas de kodo"}
MultiLanguageQuestData['mx'][24541] = {title = "Afanar el aroma", objective = "Mientras estés <disfrazado/disfrazada> de mensajero, ve al montón de cajones de Químicos La Corona, S.L. fuera de las puertas de Orgrimmar y vuelve con el paquete que te lancen a ver al detective Snap Tuerceganzúas en Orgrimmar.", description = "¡Sabía que no tramaban nada bueno! Aquí hay algún tipo de compuesto químico que afecta a la mente, pero con una muestra tan pequeña no consigo aislarlo. Necesito el de verdad.\n\n¡Ni se te ocurra comprarlo sin más! No quiero que les des ni una moneda a esos sinvergüenzas. No, quiero que lo cojas de la fuente, con discreción.\n\nTe disfrazaré de mensajero. He visto un montón de cajones custodiado por sus guardias, fuera de las puertas. Pasa corriendo, ¡y no te pares, o te descubrirán! Te tirarán un cajón. Tráemelo.", progress = nil, completion = "¿Lo has conseguido? Buen trabajo, chico. Inmejorable. A ver qué tenemos aquí.\n\n&lt;Fuerza el cajón y revuelve en su interior.&gt;", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24542] = {title = "Una floración curiosa", objective = "Reúne 10 capullos poco corrientes de flores en ciernes en La Hojarasca.", description = "El gran archidruida Naralex apareció recientemente en los Baldíos. Puede que esté detrás de este desastre o que lo esté intentando arreglar. En cualquier caso, ¡deberías hablar con él antes de que esta jungla se trague el mundo! Se encuentra en un pequeño campamento tauren al sureste.\n\nPor el camino, sería recomendable que recogieras algunas muestras de plantas para que las estudie. Los capullos nuevos le darán información importante sobre los cambios más recientes en la jungla.", progress = "Estoy extremadamente ocupado, <clase>.", completion = "Ah, ¿muestras de partes diferentes de La Hojarasca? Me resultarán verdaderamente útiles, sí. Gracias, &lt;clase&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24543] = {title = "Una familia dividida", objective = "Encuentra a Kirge Astadura en Punta Vendetta, en Los Baldíos del Sur.", description = "Todos estos niños fueron rescatados de Taurajo cuando comenzaron los enfrentamientos. Estoy intentando buscar a sus padres.\n\nUno de los refugiados que rescataste de los jabaespines reconoció al más fuerte de los niños como hijo de Kirge y de Mawre Astadura. Además, afirmó que Kirge se encontraba en el campamento de los Campos de Sangre, al norte del lugar de la masacre de Taurajo.\n\n<nombre>, ¡te ruego que vayas allí y le digas a Kirge Astadura que su hijo se encuentra sano y salvo!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24545] = {title = "Lo sagrado y lo corrupto", objective = "Coloca la Venganza de la Luz, 25 saronitas primordiales, sangre ácida de Carapútrea y sangre ácida de Panzachancro en la forja de runas del Alto señor Mograine en la Ciudadela de la Corona de Hielo.\n\nLa sangre ácida de Carapútrea y la sangre ácida de Panzachancro solo se pueden obtener en el modo de dificultad de 25 jugadores de la Ciudadela de la Corona de Hielo.", description = "Te asigno esta misión en contra de mi buen juicio, <raza>, ya que probablemente será tu fin.\n\nPasa por alto mi opinión y sigue con este encargo, y te aportaré el conocimiento y los recursos que necesitas para acabarlo.\n\nDebes volver a la Caverna Agonía de Escarcha y recuperar la Venganza de la Luz, el martillo que abandonó Arthas. Reforjado con saronita e inscrito con la sangre ácida de las abominaciones del Rey Exánime, será la base de nuestra obra.Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nForjar de Mograine\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24546] = {title = "Una línea en el suelo", objective = "Captura una colina neutral en los Campos de Sangre y defiéndela del contraataque de la Alianza.", description = "La Alianza carga con un gran número de asesinatos a sus espaldas en los Baldíos. Debemos detenerlos aquí o no nos quedarán alternativas.\n\nEn los Campos de Sangre, hay una serie de colinas estratégicas que están marcadas por torres de madera y estandartes grises neutrales. ¡Debemos tomar y resistir en estas colinas si queremos frenar el avance de la Alianza!\n\nBusca las torres al norte, al este y al sur de las ruinas de Taurajo. ¡Captura una bandera neutral y defiende la colina del contraataque!", progress = nil, completion = "¡Has mantenido la posición! Con una tenacidad como la tuya podríamos expulsar a la Alianza de nuestras tierras.", rewards = "Togas del Campo sangrientoEscudo de AstaduraLeotardos de TaurajoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24547] = {title = "Un festín de almas", objective = "El alto señor Darion Mograine quiere que utilices el Filo de las Sombras para matar a 1000 esbirros del Rey Exánime en la Ciudadela de la Corona de Hielo. Las almas se pueden obtener en el modo de 10 ó 25 jugadores.", description = "El Filo de las Sombras está entre las mejores armas que podría desear <un/una> <clase>.\n\n¿Se ha saciado tu ansia de poder, <raza>?\n\n<Sientes la mirada penetrante de Mograine.>\n\nYa sabía que no. Una última advertencia, entonces...\n\nTe estás embarcando en la parte más peligrosa de tu misión. Refrena tus aspiraciones, pues si tus objetivos son impuros tu vida, tu alma, está perdida.\n\nEl arma que blandes es una cáscara vacía, una simple sombra de lo que puede ser. Solo tras devorar un millar de almas desbloqueará su verdadero potencial.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24548] = {title = "El trono astillado", objective = "El Alto señor Darion Mograine quiere que obtengas 50 fragmentos de escarcha de las Sombras.\n\nLos fragmentos de escarcha de las Sombras solo se pueden obtener en el modo de dificultad de 25 jugadores.", description = "El trono del Rey Exánime una vez fue su prisión. El mismo Kil'jaeden creó el recipiente con cristales de hielo que extrajo del Vacío Abisal. Su único propósito era contener el espíritu vengativo de Ner'zhul.\n\nCuando Arthas golpeó el cristal con la Agonía de Escarcha liberó el alma de Ner'zhul, lo que le permitió fusionarse con la suya. Los fragmentos que resultaron de tal impacto están desperdigados por toda la ciudadela.\n\nQuiero esos fragmentos, que solo poseen los sirvientes más poderosos del Rey Exánime, para sellar el poder que contiene tu arma.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24550] = {title = "Viaje a Cima del Trueno", objective = "Habla con Baine Pezuña de Sangre en Cima del Trueno.", description = "Los pozos están limpios y las aguas de Mulgore vuelven a correr limpias y en armonía. Nos has salvado... pero también has sacado a la luz acontecimientos nefastos. Debemos difundir los actos de los Tótem Siniestro.\n\nHa llegado la hora de que entres en Cima del Trueno, nuestra gran ciudad en lo alto de la meseta. Ve a hablar con nuestro líder, Baine Pezuña de Sangre, hijo de Cairne. Debe saberlo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24551] = {title = "Conocer al nuevo jefe", objective = "Mata patrullas de reconocimiento del Fuerte del Norte y reúne 10 distintivos al mérito de Theramore.", description = "<nombre>, la defensa de los Baldíos no ha ido bien bajo las órdenes de Gar'dul. Garrosh ha enviado al Señor de la Guerra Sangrastil para que tome control de la situación. Ahora se encuentra en el campamento y, si quieres darle buena impresión, demuestra algo de iniciativa.\n\nDirígete a los Campos de Sangre del este y busca patrullas de reconocimiento del Fuerte del Norte. Si le entregas al nuevo Señor de la Guerra un puñado de distintivos al mérito, ¡será más fácil crearte un renombre!", progress = "Pareces la clase de <clase> que cumple con su trabajo. ¿Qué noticias traes del campo de batalla?", completion = "&lt;Sangrastil observa los distintivos y los deja caer de sus manos a la arena. Sus labios se retuercen mostrando una sonrisa dentuda.&gt;\n\n¡ESTO es lo que me gusta ver, &lt;clase&gt;! ¿Cuál era tu nombre?\n\nLlegarás lejos con nosotros.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24552] = {title = "Orgullo de león", objective = "Mata cualquier combinación de 5 merodeadores y melenaorgullos de las llanuras.", description = "Si lo que buscas en nuestros invasores de la Alianza es venganza, harías bien en fijarte en los depredadores más feroces de los Baldíos.\n\nLos leones que acechan entre la hierba alta son astutos, sigilosos y poderosos. Aprende de ellos y entenderás la clase de guerra a la que nos enfrentamos.\n\nCaza merodeadores y melenaorgullos de las llanuras y regresa para hablar de lo que has aprendido. A menudo se esconden entre las sombras de árboles altos.", progress = nil, completion = "Ah sí... percibo un brillo en tus ojos que no había antes. Bien hecho, &lt;clase&gt;.", rewards = "Te van a lanzar el siguiente hechizo:\n\nFuria del león\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24553] = {title = "La purificación de Quel'Delar", objective = "Sumerge la Quel'Delar templada en La Fuente del Sol. Habla con un celador de La Fuente del Sol cuando estés <listo/lista> para entrar en la Meseta de La Fuente del Sol.", description = "Admito que no me creía que hubieras reforjado Quel'Delar de verdad y no esperaba que el espíritu de Thalorien se te apareciera. No te puedes imaginar lo que significa para mí y para mi gente que Quel'Delar haya sido recuperada.\n\nComo te prometí, te permitiré entrar en La Fuente del Sol, donde encontrarás a los líderes de Lunargenta. Lleva la espada a la cámara de La Fuente del Sol y sumérgela. Se ligará a ti. Cuando eso ocurra, llévasela a Caladis Lanza Reluciente en el Reposo de Quel'Delar.Cuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][24554] = {title = "La empuñadura maltrecha", objective = "Lleva la empuñadura maltrecha a Myralion Resplandor al Reposo de Quel'Delar, al sur de los Campos del Torneo Argenta.", description = "Esta vieja y maltrecha empuñadura de espada ha visto tiempos mejores. Antes de separarse de la hoja debió ser un ejemplo magnífico de la artesanía del herrero.\n\nLos elegantes símbolos y las exóticas gemas que decoran la empuñadura sugieren que el arma pudo haber pertenecido a una persona muy poderosa. Sin duda los Atracasol estarán interesados en el descubrimiento de semejante artefacto. Busca a su representante en el Reposo de Quel'Delar, al sur de los Campos del Torneo Argenta.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24555] = {title = "Lo que saben los dragones", objective = "Habla con Krasus en lo alto del Templo del Reposo del Dragón.", description = "No cabe duda, esta empuñadura perteneció a un arma antigua y poderosa... ¿pero a cuál? No reconozco estas inscripciones en concreto, pero esto no es un callejón sin salida.\n\nKorialstrasz, también conocido como Krasus, ha sido amigo de los quel'dorei y del Kirin Tor desde hace mucho tiempo. Su conocimiento y sus recursos son inagotables, seguro que sabe algo de esto. Viaja a la cima del Templo del Reposo del Dragón, pídele consejo e informa al magister Hathorel dentro del Santuario de los Atracasol, en Dalaran.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24556] = {title = "Un disfraz apropiado", objective = "Consigue un tabardo prestado de Shandy Lustre Brillo.", description = "Meterte en el Enclave de Plata va a ser más difícil de lo que parece. Solo les permiten entrar a aquellos que llevan tabardos de El Pacto de Plata. Si nos hacemos con uno, un sencillo encantamiento hará el resto.\n\nEn el balcón que hay sobre Los Hilos del Destino encontrarás a Shandy Lustre Brillo. Le he echado una mano otras veces, así que me debe un favor. Les hace la colada a muchos habitantes de la ciudad. Quizás él te pueda \"prestar\" un tabardo por un tiempo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24557] = {title = "El plan de El Pacto de Plata", objective = "Consigue las órdenes de El Pacto de Plata.", description = "Uno de mis contactos en los Bajos Fondos ha visto a un agente de El Pacto de Plata que reunía información en la Taberna de los Cuervos. A los miembros de El Pacto de Plata no se les conoce por sus paseos por las cloacas, así que deben de tramar algo.\n\nVe a los Bajos Fondos, encuentra al agente de El Pacto de Plata y elimínalo. Registra el cuerpo en busca de cualquier información que nos pueda llevar a ese escrito de Reposo del Dragón. No podemos permitir que esos debiluchos patéticos de El Pacto de Plata se lo lleven a Corona de Hielo antes que nosotros.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24558] = {title = "Vuelve con Myralion Resplandor", objective = "Lleva Hojas antiguas forjadas por los dragones a Myralion Resplandor al Reposo de Quel'Delar.", description = "Tenemos que llevarle este libro a Myralion Resplandor. ¿Podrías hacerlo? No puedo confiar en nadie más para transportar el libro y ya has demostrado que sabes mantener a raya a los hombres de El Pacto de Plata.\n\nLlévatelo al Reposo de Quel'Delar, al sur de los campos del Torneo Argenta en Corona de Hielo. Myralion te estará esperando. Si es capaz de identificar la hoja, es posible que podamos reclamarla en nombre de Aethas Atracasol y enseñarle a Dalaran y a la Alianza que nosotros lideraremos el ataque contra el Rey Exánime.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24559] = {title = "Reforjar la espada", objective = "Obtén 5 barras de saronita imbuida y el martillo del maestro de forja, después combínalos con los restos de Quel'Delar para crear la Quel'Delar reforjada.", description = "No podemos permitir que Quel'Delar permanezca rota y deshonrada. Coge los restos de la espada, junto con la empuñadura maltrecha que encontraste, y adéntrate en el Foso de Saron en la Ciudadela de la Corona de Hielo.\n\nEn el foso el Rey Exánime usa esclavos para excavar, procesar y transformar mena de saronita. Esa misma saronita imbuida es la que usaremos para reparar Quel'Delar.\n\nDebes reunir barras de saronita imbuida y obtener el martillo del maestro de forja. Luego llévalo todo al yunque del maestro de forja y reforja la espada.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\nObjeto #5Objeto #1"}
MultiLanguageQuestData['mx'][24560] = {title = "Templar la hoja", objective = "Templa la Quel'Delar reforjada en el Crisol de Almas.", description = "Por fin se han reunido las piezas de Quel'Delar y la espada está completa, pero no podrá volver al campo de batalla hasta que la hayas templado. Este filo de saronita tan irregular es frágil y se quebrará con solo tocarlo.\n\nEn el interior de la Forja de Almas, en la Ciudadela de la Corona de Hielo, hay un lugar donde puedes templar la hoja sin riesgo. Llévate a Quel'Delar al dominio del Devoraalmas y busca su crisol. Introduce la hoja en el crisol para templarla y vuelve con ella. Te estaré esperando en las Cámaras Heladas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24561] = {title = "Las Cámaras de Reflexión", objective = "Lleva a Quel'Delar al Reposo de la Espada en las Cámaras de Reflexión.", description = "Has reforjado y templado la espada, pero permanece en su vaina en silencio, como si fuera un arma común. ¿Dices que la espada te atrae, como si tuviera voluntad propia?\n\n¿Te atreverás a llevarla a donde quiere ir? No es normal que la espada esté tan callada y tan insistente, pero temo que si no la llevas a su destino nunca sabremos por qué. Llévala a las Cámaras de Reflexión en la Ciudadela de la Corona de Hielo, pero no bajes la guardia. Te esperaré en las Cámaras Heladas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][24562] = {title = "Viaje a La Fuente del Sol", objective = "Habla con Halduron Alasol en la entrada de la Meseta de La Fuente del Sol en la Isla de Quel'Danas.", description = "Llévate a Quel'Delar a La Fuente del Sol lo antes posible, <nombre>. Cree a Uther cuando te dice que no siempre serás capaz de controlar la hoja mientras siga bajo el influjo maligno del Rey Exánime. Debes viajar a la Isla de Quel'Danas y entrar en la mismísima Fuente del Sol, donde podrás purificar la espada.\n\nLos guardianes de La Fuente del Sol no te dejarán entrar, así que preséntate ante Halduron Alasol. Estará inspeccionando a los guardias del lugar.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24565] = {title = "Intervención biológica", objective = "Mata a 5 dienterrores descarriados y a 5 zancudos de llanura descarriados.", description = "Las energías que se han liberado en la zona han fluido a través de la fauna y la han transformado en bestias poderosas e inestables. Si dejamos que se extienda por esta arboleda, el supercrecimiento sembrará el caos en el ecosistema actual devorando las presas y expulsando a las criaturas naturales más débiles.\n\nDirígete allí y reduce la población de La Hojarasca para eliminarla. Regresa cuando hayas completado tu misión.", progress = nil, completion = "Gracias, &lt;nombre&gt;. Me complace verte de vuelta de una pieza. La atrocidad que reina en estas criaturas es asombrosa.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24566] = {title = "Sembrar la solución", objective = "Utiliza semillas reconfortantes en 6 dienterrores descarriados o en zancudos de la llanura descarriados y observa los resultados.", description = "Basándome en lo que me has traído, creo que podemos encontrar una solución. He imbuido las semillas de parrazote con energías sanadoras.\n\nEl mero contacto con ellas debería imbuir las criaturas de la energía necesaria para expulsar la influencia corrupta.\n\nIntenta sanar a los raptores y a los zancudos de la llanura mutados esparciendo las semillas sobre ellos, y vuelve para informarme de los resultados.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][24567] = {title = "¡A por ellos!", objective = "Habla con el entrenador Paselargo en el Campo Kajaro en Kezan.", description = "<nombre>, el entrenador Paselargo te está buscando. Lleva nuestro valiente equipo de bombalón, los Bucaneros Pantoque.\n\n¡Dice que el título de división contra los Tiburones Bonvapor está en juego y que solo tú puedes traerlo a casa!\n\nDirígete hacia el oeste de la ciudad. Verás el Campo Kajaro.\n\nUna estrella del bombalón... ¡Esto va a ser la bomba para tu imagen!", progress = nil, completion = "¡Aquí estás, figura! ¡Rápido, no hay tiempo que perder! Tenemos que poner en marcha las trituradoras de nuevo.\n\nTe saco del banquillo... ¡Nos vas a ganar el partido y el título!", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24568] = {title = "¡A los muros!", objective = "Habla con Winnoa Bosque de Pinos en los Campos de Sangre para defender las puertas de Mulgore del ataque.", description = "<nombre>, ¡se están concentrando en las puertas! La Alianza está tratando de abrirse paso por Mulgore con soldados de a pie para asediar a los guardias.\n\nContamos con muy pocos para defender los muros. Nos hemos provisto de ollas con agua hirviendo para repeler a los atacantes hasta que llegue la ayuda... tendremos que apañarnos con eso.\n\nSin embargo, necesitamos a alguien que coordine nuestras defensas. Pídemelo y te daré una descripción detallada del campo de batalla.\n\n¡Te necesitamos, <nombre>!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24569] = {title = "Rompedor de asedio", objective = "Destruye 4 máquinas de asedio de Fuerte del Norte a las puertas de Mulgore.", description = "<nombre>, has demostrado tu valía en los Campos de Sangre. Sin embargo, la Alianza todavía amenaza a nuestros amigos tauren.\n\nLa maquinaria de asedio a las puertas de Mulgore es como una lanza enviada contra nuestro pecho. Quiero que vayas a las puertas, al sur de aquí, y dejes a esos vehículos de asedio fuera de juego.\n\nToma estas bombas lapa, cortesía de nuestros nuevos aliados goblins. Parece como si hubieran llenado de polvos explosivos lo que se asemeja a... unos calcetines cubiertos de grasa... Pero servirán.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de SangrastilBotas cubiertas de grasaVarita goblin nauseabundaLosa de peltreRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24570] = {title = "Substracción de víboris", objective = "Reúne 5 víboris enervadas.", description = "La corrupción a la que nos enfrentamos debe ser estudiada si queremos encontrar una forma apropiada para combatirla.\n\nAfortunadamente, no todas las criaturas se han alterado tanto como otras. Las serpientes pequeñas beben poca agua y no comen plantas, por lo que su exposición a las energías ha sido menor. Aun así, han absorbido bastante como para cambiar de tono.\n\nReúne unas cuantas serpientes de La Hojarasca y tráemelas para que podamos observar los cambios en las criaturas.", progress = "¿Has reunido suficientes? Necesitaremos varias para compararlas.", completion = "Estas servirán perfectamente. Los colores brillantes como estos no se suelen dar con frecuencia en los Baldíos, pero no han desarrollado otras mutaciones por el momento.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24571] = {title = "Semillas de parrazote", objective = "Recoge 4 semillas aviesas de parrazote.", description = "Tiene que haber una forma de curar a estas pobres criaturas sin tener que matarlas. Tengo una idea, pero necesito tu ayuda, <clase>.\n\nLas plantas de parrazote que recorren esta zona contienen semillas llenas de energía primigenia del lugar. Recoge algunas y tráemelas; veremos si hay algo que podamos hacer.", progress = "¿Tienes las semillas?", completion = "Me preocupa lo... activas que son. Sin embargo, solo significa que debemos seguir actuando rápido antes de que la corrupción se extienda más.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24572] = {title = "Recuperar Taurajo", objective = "Mata a 8 despojadores de Taurajo en las Ruinas de Taurajo.", description = "¡Hiciste un trabajo excelente a las puertas de la ciudad, <nombre>! El grueso de las fuerzas de la Alianza se está retirando, pero no estoy del todo satisfecho.\n\nSaquearon Taurajo, que no era más que un campamento de cazadores. Esa \"Alianza\" por fin se ha revelado como lo que realmente es: una panda renegada de carniceros.\n\nIncluso ahora hay un grupo de humanos que se han quedado a profanar lo que queda de Taurajo.\n\n<Sangrastil lanza un hacha que se clava en la tierra.>\n\nHazlos sufrir.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24573] = {title = "Honrar a los muertos", objective = "Utiliza el tótem funerario sobre los cuerpos sin vida de Krulmoo, Dranh, Ionada y Omusa en las Ruinas de Taurajo.", description = "Ahora que nos libramos de la amenaza más apremiante, ¿podrías ayudarnos con otro asunto escabroso?\n\nLos tauren no enterramos a nuestros muertos. Preparamos el cuerpo para su regreso a los elementos y lo colocamos en las tumbas sagradas. Los que murieron en la masacre de Taurajo no recibieron un funeral y me preocupa que los soldados de la Alianza quemen los cuerpos sin realizar los rituales apropiados.\n\n<nombre>, lleva este tótem a Taurajo y realiza los oficios para Krulmoo, Dranh, Ionada y Omusa. Ellos... no lograron salir de allí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24574] = {title = "Sembrar el caos", objective = "Mata a 5 supercrecimientos y encuentra un corazón retorciéndose.", description = "Si de verdad he sembrado el caos, es hora de cosechar.\n\n<nombre>, los supercrecimientos torpes de la flora se arrastran a través del arroyo imbuido. Representan una manifestación directa de las fuerzas inestables que están transformando la zona. Mata a todos los que puedas y, quizás así, seamos capaces de frenar el avance del supercrecimiento.\n\nY mientras tanto... permanece <atento/atenta> a las partes que parezcan especialmente corruptas. Tráeme cualquier pieza sospechosa.", progress = "Recortar el supercrecimiento solo nos concederá algo de tiempo. ¿Has encontrado alguna pieza sospechosa?", completion = "&lt;Naralex toma con cautela el corazón retorciéndose, visiblemente agitado.&gt;\n\nHe sido un ingenuo. La verdad que no me atrevía a aceptar estaba delante de mis narices durante todo este tiempo... esta cosa maligna lo constata.\n\nTú y yo tenemos mucho trabajo que hacer.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24575] = {title = "El día de la liberación", objective = "Libera 5 habitantes esclavizados en el interior de la Mina Piedra Ígnea.", description = "Recientemente hemos descubierto que los habitantes de la Aldea de Piedra Ígnea sobrevivieron a la mayoría de las penurias de la maldición.\n\nPor desgracia, su aldea no tuvo tanta suerte con la invasión de los Renegados.\n\nLos Renegados han tomado a los habitantes como prisioneros y los están obligando a trabajar en la mina cercana como esclavos.", progress = nil, completion = "Lo has vuelto a hacer, &lt;nombre&gt;. Los habitantes liberados están deseando ayudarnos contra los Renegados como puedan.", rewards = "Recibirás:\n\nObjeto #5"}
MultiLanguageQuestData['mx'][24576] = {title = "Una charla amistosa...", objective = "Ve a la torre de zepelín, en la meseta central de Orgrimmar, e interroga a Quejica Misilóxido sobre los suministros. Vuelve con cualquier prueba que te aporte.", description = "<Roka te escucha horrorizada mientras le cuentas por qué buscas a Quejica.>\n\n¿Quieres decir que he estado hechizada por un alquimista todo este tiempo? ¡No puedo creer que me tragara ese fraude! Si alguna vez le echo el guante a ese pequeño y taimado goblin, ¡lo haré pedazos!\n\nSi ha terminado todos sus recados, irá de camino a la torre de zepelín, en el centro de Orgrimmar. ¡Pase lo que pase, <nombre>, no puedes permitir que suba al zepelín y se escape!\n\n¡Corre a la torre de zepelín antes de que lo pierdas!", progress = "¿Lo has encontrado o se ha escurrido por alguna grieta?", completion = "¿Tienes su libro de contabilidad? ¿En serio? Genial, &lt;nombre&gt;. Seguro que hay un montón de información importante.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24577] = {title = "Inspeccionar el Bastión de la Desolación", objective = "Habla con: Señor de la guerra Sangrastil, ve al Bastión de la Desolación e informa a Gar'dul de que el Señor de la guerra Sangrastil está en camino.", description = "Gracias a ti, la amenaza inmediata ya ha desaparecido. Sin embargo, mi trabajo en los Baldíos no ha hecho más que empezar.\n\nEl Alto del Honor fue capturado y Taurajo fue saqueado mientras que el Señor de la Guerra Gar'dul se encontraba a cargo de la región. El Jefe de Guerra me ha enviado para enmendar sus errores.\n\nMe gustaría que viajaras de mi parte al sur hasta el Bastión de la Desolación y que informes a Gar'dul de que llegó la hora del juicio.\n\nRegresa cuando estés <listo/lista> para partir y reuniré a mi vanguardia para que te acompañe.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24579] = {title = "¡Sartharion debe morir!", objective = "Mata a Sartharion.\n\nEsta misión se puede completar con cualquier tamaño de banda en cualquier modo de dificultad.", description = "Sartharion, el Guardián ónice, vigila los huevos del Vuelo Crepuscular. Descansa en el Sagrario Obsidiana, en la Cámara de los Aspectos bajo el Templo del Reposo del Dragón.\n\n¡El Consejo de los Seis ha decretado que Sartharion debe morir!", progress = nil, completion = "Ahora que Sartharion ha muerto, los planes de Alamuerte y Sinestra tienen que haberse retrasado.", rewards = "Recibirás:\n\nEmblema de triunfoEmblema de escarchaPuntos de justicia"}
MultiLanguageQuestData['mx'][24580] = {title = "¡Anub'Rekhan debe morir!", objective = "Mata a Anub'Rekhan.\n\nEsta misión se puede completar con cualquier tamaño de banda en cualquier modo de dificultad.", description = "Anub'Rekhan, quien antaño fuera un poderoso Señor Araña del imperio nerubiano, ha caído en manos del Rey Exánime y ha sido corrompido hasta convertirse en no-muerto.\n\nAhora es un señor de la cripta y se encuentra en una sala del Arrabal Arácnido de Naxxramas, preparando estrategias para Kel'Thuzad.\n\n¡El Consejo de los Seis ha decretado que Anub'Rekhan debe morir!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nEmblema de triunfoEmblema de escarchaPuntos de justicia"}
MultiLanguageQuestData['mx'][24581] = {title = "¡Noth el Pesteador debe morir!", objective = "Mata a Noth el Pesteador.\n\nEsta misión se puede completar con cualquier tamaño de banda en cualquier modo de dificultad.", description = "¡Noth el Pesteador, traidor y cobarde! ¡Solo el Rey Exánime le supera en el número de almas que ha incorporado a la Plaga!\n\nDirígete a Naxxramas inmediatamente. Lo encontrarás en el Arrabal de la Peste, oculto tras sus esbirros no-muertos.\n\n¡Acaba con él! ¡El Consejo de los Seis ha decretado que Noth debe morir!", progress = nil, completion = "Un problema menos del que preocuparnos. Ahora que Noth ha caído, la investigación de la Plaga para refinar los métodos de creación de no-muertos se parará en seco.", rewards = "Recibirás:\n\nEmblema de triunfoEmblema de escarchaPuntos de justicia"}
MultiLanguageQuestData['mx'][24582] = {title = "¡El instructor Razuvious debe morir!", objective = "Mata al instructor Razuvious.\n\nEsta misión se puede completar con cualquier tamaño de banda en cualquier modo de dificultad.", description = "El instructor Razuvious se pasea con descaro por el Arrabal Militar de Naxxramas. Dicen que solo un caballero de la Muerte entrenado personalmente por él podría resistir la potencia de su espada.\n\nTu grupo y tú demostrarán lo contrario.\n\n¡El Consejo de los Seis ha decretado que el instructor Razuvious debe morir!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nEmblema de triunfoEmblema de escarchaPuntos de justicia"}
MultiLanguageQuestData['mx'][24583] = {title = "¡Remendejo debe morir!", objective = "Mata a Remendejo.\n\nEsta misión se puede completar con cualquier tamaño de banda en cualquier modo de dificultad.", description = "La supuesta \"encarnación de la guerra\", Remendejo, es la abominación definitiva. Está diezmando nuestras fuerzas en el Cementerio de Dragones.\n\nQuiero que reúnas a tus compañeros y entres en el Arrabal de los Ensamblajes de Naxxramas. Desmonta el ensamblaje.\n\n¡El Consejo de los Seis ha decretado que Remendejo debe morir!", progress = nil, completion = "Muchos niños van a dormir más tranquilos sabiendo que Remendejo ya no existe.", rewards = "Recibirás:\n\nEmblema de triunfoEmblema de escarchaPuntos de justicia"}
MultiLanguageQuestData['mx'][24584] = {title = "¡Malygos debe morir!", objective = "Mata a Malygos.\n\nEsta misión se puede completar con cualquier tamaño de banda en cualquier modo de dificultad.", description = "Nuestros recursos se agotan. Malygos, el Tejehechizos, absorbe toda la magia del mundo y la concentra en el Ojo de la Eternidad. Sin magia estamos perdidos.\n\n<clase>, la guerra de El Nexo debe acabar. ¡El Consejo de los Seis ha decretado que Malygos debe morir!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPuntos de justicia"}
MultiLanguageQuestData['mx'][24585] = {title = "¡El Leviatán de llamas debe morir!", objective = "Mata al Leviatán de llamas.\n\nEsta misión se puede completar con cualquier tamaño de banda en cualquier modo de dificultad.", description = "En el Campo de Formación se encuentra la primera línea de defensa de Ulduar: el Leviatán de llamas.\n\nEl Kirin Tor ha recibido información que sugiere que pronto transportarán esta máquina creada por los Guardianes a un lugar desconocido para sembrar el caos entre los mortales de Azeroth.\n\nEsto no debe ocurrir. ¡El Consejo de los Seis ha decretado que el Leviatán de llamas debe morir!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPuntos de justicia"}
MultiLanguageQuestData['mx'][24586] = {title = "¡Tajoescama debe morir!", objective = "Mata a Tajoescama.\n\nEsta misión se puede completar con cualquier tamaño de banda en cualquier modo de dificultad.", description = "Tajoescama suele tener su nidal cerca de la Forja Colosal, en Ulduar. Sin embargo, últimamente la han visto escupiendo fuego sobre las tierras cercanas al complejo de los titanes.\n\nAunque la de la madre de linaje es una triste historia, representa una amenaza inmediata para todo Rasganorte. ¡El Consejo de los Seis ha decretado que Tajoescama debe morir!", progress = nil, completion = "Ahora Veranus podrá descansar en paz.", rewards = "Recibirás:\n\nEmblema de triunfoEmblema de escarchaPuntos de justicia"}
MultiLanguageQuestData['mx'][24587] = {title = "¡Ignis el Maestro de la Caldera debe morir!", objective = "Mata a Ignis el Maestro de la Caldera.\n\nEsta misión se puede completar con cualquier tamaño de banda en cualquier modo de dificultad.", description = "El gran gigante de fuego, Ignis el Maestro de la Caldera, sigue trabajando en la Forja Colosal de Ulduar. Loken le ordena crear armas de un poder aterrador.\n\n¡El Consejo de los Seis ha decretado que Ignis debe morir!", progress = "Ignis sigue vivo. ¡El gigante de fuego debe caer!", completion = "Espero que no tuvieras que vértelas con muchos de sus ensamblajes férreos.", rewards = "Recibirás:\n\nEmblema de triunfoEmblema de escarchaPuntos de justicia"}
MultiLanguageQuestData['mx'][24588] = {title = "¡El Desarmador XA-002 debe morir!", objective = "Mata al Desarmador XA-002.\n\nEsta misión se puede completar con cualquier tamaño de banda en cualquier modo de dificultad.", description = "El Desarmador XA-002, otro de los extraños ensamblajes de Mimiron, cree que es el hijo de su creador. No te dejes engañar por su falsa inocencia. ¡Es una máquina letal!\n\nEncontrarás al Desarmador en la Chatarrería de Ulduar. ¡El Consejo de los Seis ha decretado que el Desarmador XA-002 debe morir!", progress = nil, completion = "El mayor punto débil de Ulduar es la fe ciega que sus señores tributan a sus invenciones para protegerla.", rewards = "Recibirás:\n\nEmblema de triunfoEmblema de escarchaPuntos de justicia"}
MultiLanguageQuestData['mx'][24589] = {title = "¡Lord Jaraxxus debe morir!", objective = "Mata a Lord Jaraxxus.\n\nEsta misión se puede completar con cualquier tamaño de banda en cualquier modo de dificultad.", description = "El archimago Tiemporeja ha previsto un suceso terrible que está a punto de ocurrir. Un insensato brujo gnomo está a punto de invocar accidentalmente a un señor eredar de la Legión Ardiente en mitad de la Prueba del Cruzado.\n\nDebes estar presente cuando ocurra, <clase>. Si Lord Jaraxxus escapa, abrirá un portal y la Legión Ardiente volverá a invadir nuestro mundo.\n\n¡El Consejo de los Seis ha decretado que Lord Jaraxxus debe morir!", progress = nil, completion = "Todo Azeroth tiene suerte de que Tiemporeja previera la llegada del señor eredar y tú estuvieras presente para acabar con él.", rewards = "Recibirás:\n\nEmblema de triunfoEmblema de escarchaPuntos de justicia"}
MultiLanguageQuestData['mx'][24590] = {title = "¡Lord Tuétano debe morir!", objective = "Mata a Lord Tuétano.\n\nEsta misión se puede completar con cualquier tamaño de banda en cualquier modo de dificultad.", description = "Lord Tuétano es el guardián del Trono Helado en la cámara de La Aguja. El Rey Exánime lo construyó a partir de los huesos de miles de aventureros derrotados y maneja el poder del mismísimo trono.\n\nSi no destruimos a este esqueleto no podremos tomar la Ciudadela de la Corona de Hielo.\n\n¡El Consejo de los Seis ha decretado que Lord Tuétano debe morir!", progress = nil, completion = "Gracias a ti el Trono Helado ha perdido a su guardián principal. Ahora nuestros ataques contra las fuerzas del Rey Exánime serán más efectivos.", rewards = "Recibirás:\n\nPuntos de justicia"}
MultiLanguageQuestData['mx'][24591] = {title = "El cambio de Gar'dul", objective = "Ve a lo alto de la torre del norte en el Bastión de la Desolación y ayuda al Señor de la Guerra Sangrastil a \"relevar\" del mando a Gar'dul.", description = "Cuando llegue Sangrastil, me gustaría... hablar en privado con él. ¿Podrías acompañarme para que las cosas sigan su cauce? Este Sangrastil es un... un... un peligro público.\n\n<Gar'dul intenta recomponerse.>\n\nReúnete conmigo en lo alto de la torre de norte e iremos juntos a hablar con Sangrastil.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24603] = {title = "Que continúe la desolación", objective = "Mata a 13 jabaespines Crines de Acero.", description = "Por un momento creí que mi odio se habría calmado. Mi mujer fue enterrada. Es la última ofrenda de la sangre de sus asesinos que acallará su espíritu atormentado. Pensé que, entonces, la paz me inundaría.\n\nPero me equivocaba.\n\n¡No descansaré hasta que yazcan muertos y destrozados todos y cada uno de esos sucios, rastreros y asesinos jabaespines! No puedo matarlos tan rápido solo con mis manos. Ve y mata a más por mí, <raza>.", progress = nil, completion = "Bien. Toma tu recompensa, este solo es el preludio.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24604] = {title = "La preocupación de Mankrik", objective = "Entrega el regalo de Mahka a Mankrik en el sur de Punta Piedra de Fuego.", description = "Tengo que pedirte un favor, <clase>.\n\nHace poco, un guerrero llamado Mankrik pasó por nuestro campamento durante su viaje solitario. Su mujer fue asesinada por los jabaespines hace mucho y aún tiene sed de venganza. Nunca olvidaré sus ojos... ardían con una ira inconsolable.\n\nNo hablamos mucho, pero no soporto pensar que vague por ahí solo. Por favor, llévale esto a Mankrik y dile que es de mi parte...", progress = "<Mankrik gruñe.>\n\n¿Qué es esto? ¡Estoy ocupado!", completion = "¿Te ha enviado Mahka?\n\n&lt;La furia de Mankrik se apacigua por un momento.&gt;\n\nEs algo reconfortante, pero nada me podrá consolar hasta que termine el trabajo que vine a hacer.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24606] = {title = "La sangre de los Baldíos", objective = "Reúne 6 abalorios de esquirla de sangre de jabaespines Crines de Acero.", description = "Esta piedra roja brillante fue hallada entre las garras de un jabaespín. Ha sido cuidadosamente tallada en forma de gran jabalí y vides con espinas que brotan de su espalda. La superficie es suave y está pulida con delicadeza.\n\n¿La han hecho los jabaespines? Si encuentras más, quizás uno de los chamanes de Punta Piedra de Fuego podría ofrecerte más información sobre ellas.", progress = "¿Sí?", completion = "Estas son esquirlas de sangre. Solían encontrarse por todos los Baldíos.\n\nSe dice que proceden de la sangre de Agamaggan, el gran semidiós del que descienden los jabaespines. Sé que les pusieron un precio, pero a nadie se le ocurriría que se tomaran tantas molestias en tallarlas como esta...\n\nPuede que aprendamos algo más con esto.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][24608] = {title = "Quebrantadientes", objective = "Mata a Quebrantadientes.", description = "Ya no me interesan el honor y la gloria, <clase>. Lo único que me importa es la muerte de los jabaespines, de la forma que sea y a manos de quien sea.\n\nQuebrantadientes, el jefe de estos sucios Crines de Acero, se encuentra en su guarida del noroeste, en lo alto de una colina. Acaba con su vida.\n\nTengo pensado quedarme aquí y apilar estos cuerpos hasta que no salga ninguna alimaña más del Horado...Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Brazales del HoradoDiente destrozadoBastón Crines de AceroPodrás elegir una de estas recompensas:\n\nAmuleto de Mankrik\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][24612] = {title = "Un regalo para el Jefe de Guerra", objective = "Regálale una pulsera de talismanes preciosos al Jefe de Guerra en Orgrimmar.", description = "¿Querías hacer una pulsera de talismanes preciosos para el Jefe de Guerra? Seguro que le encantará.\n\n¿Ya tienes un juego de coleccionista de talismanes preciosos?", progress = "Bienvenido, <clase>. ¿Tienes algo para mí?", completion = "Te \"agradezco\" esta pulsera de talismanes preciosos.", rewards = "Recibirás:\n\nPrueba de amorTarjeta de Orgrimmar preciosa"}
MultiLanguageQuestData['mx'][24613] = {title = "Un regalo para la Reina alma en pena", objective = "Regálale una pulsera de talismanes preciosos a Lady Sylvanas Brisaveloz en Entrañas.", description = "¿Querías hacer una pulsera de talismanes preciosos para la Reina alma en pena? Seguro que le encantará.\n\n¿Ya tienes un juego de coleccionista de talismanes preciosos?Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPrueba de amorTarjeta de Entrañas preciosa"}
MultiLanguageQuestData['mx'][24614] = {title = "Un regalo para el Gran jefe", objective = "Regálale una pulsera de talismanes preciosos a Baine Pezuña de Sangre en Cima del Trueno.", description = "¿Querías hacer una pulsera de talismanes preciosos para el Gran jefe? Seguro que le encantará.\n\n¿Ya tienes un juego de coleccionista de talismanes preciosos?Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPrueba de amorTarjeta de Cima del Trueno preciosa"}
MultiLanguageQuestData['mx'][24615] = {title = "Un regalo para el Señor regente de Quel'Thalas", objective = "Regálale una pulsera de talismanes preciosos a Lor'themar Theron en Lunargenta.", description = "¿Querías hacer una pulsera de talismanes preciosos para el Señor regente de Quel'Thalas? Seguro que le encantará.\n\n¿Ya tienes un juego de coleccionista de talismanes preciosos?Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPrueba de amorTarjeta de Ciudad de Lunargenta preciosa"}
MultiLanguageQuestData['mx'][24618] = {title = "Reclamar Marca de Guerra", objective = "Ve a Marca de Guerra. Busca la bandera y mata a 10 soldados Vanguarda de Triunfo.\n\nAl capturar la bandera, los jugadores de la Horda obtendrán ventaja en combate en la grieta.", description = "Hemos luchado contra la Alianza y la hemos neutralizado a pesar de que la tierra se abre bajo nuestros pies. Al este, encontrarás Marca de Guerra, una vasta franja de terreno diezmado. No es mucho más que una senda en la arena, pero debe ser NUESTRA.\n\nEn el centro de la grieta hallarás una bandera que marca quién controla la zona. Encuentra la bandera.\n\nSi aún no nos pertenece, captúrala para la Horda, pues, inclinará la balanza a nuestro favor. Investiga la grieta ¡y mata a todo lo que encuentres a tu paso!", progress = nil, completion = "¡Excelente! &lt;nombre&gt;, eres mi tipo de &lt;clase&gt;.\n\nCon tu ayuda haremos retroceder a los invasores hasta el mar.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24619] = {title = "La parte por el todo", objective = "Utiliza la sierrahuesos de Calder en los cadáveres de Marca de Guerra y reúne 15 extremidades cercenadas.", description = "Siempre quise crear una abominación. Parece bastante sencillo, pero ya sabes cómo son las cosas cuando aprendes de un libro. ¡No hay nada como la práctica!\n\nPrimero, voy a necesitar partes. Muchas partes. Y tú me las vas a conseguir.\n\nNo hace falta ponerse quisquilloso: humanos, orcos... da lo mismo, son todos parecidos.\n\nAun así, asegúrate de que los cadáveres que recolectes procedan de Marca de Guerra, para que sepa que están frescos.\n\n<Calder coloca en tus manos una sierrahuesos oxidada cubierta de sangre y sonríe encantadoramente.>Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24620] = {title = "Corazón de kodo", objective = "Mata a un toro Sacudetierras y consigue un corazón de kodo enorme.", description = "¡Estas partes son preciosas! Músculos, tendones, dedos de la mano o de los pies... tengo MUCHA hambre ahora mismo.\n\nPero lo primero es el trabajo. Una vez haya ensamblado esta pila de partes necesitaré un corazón suficientemente fuerte para hacer que el fango corra por el nido de venas de esta rata. Usaría el mío propio pero es una carcasa seca con pinta de nabo.\n\nNo, necesito potencia. Consigue un corazón de kodo de un toro Sacudetierras gigante del sur de Marca de Guerra.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24621] = {title = "Inteligencia cerebral", objective = "Mata a un capitán de Triunfo en la parte alejada de Marca de Guerra y consigue un cerebro fresco.", description = "¡Mi monstruosidad está cobrando forma! Lo único que falta es rellenar esta calavera con algo útil.\n\nMe refiero a un cerebro, <nombre>. Y ahora en este punto sí que me pondré quisquilloso. El proceso de abomificación provoca daños cerebrales importantes, por lo que es mejor empezar con uno que sea inteligente.\n\nUno de los oficiales de la Alianza serviría. Busca a uno de los capitanes en la parte más alejada de Marca de Guerra e intenta no dañar el material cuando lo mates.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Leotardos salpicados de sesosÚtiles de neurocirujanoJubón de abominaciónRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24629] = {title = "El punto perfecto de perfume", objective = "Rocía a 10 personas con el vaporizador de colonia La Corona.", description = "Pareces <todo un triunfador/toda una triunfadora>, <clase>. ¿Por qué no trabajamos en beneficio mutuo?\n\nEn La Corona queremos ofrecer muestras de nuestros últimos productos temáticos a tantos posibles clientes como sea posible. ¡Ayúdanos a repartir amor y te haremos un descuento en algunos productos magníficos de La Corona!\n\nTu tiempo, nuestro dinero, <amigo/amiga>. ¿Qué dices?Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPrueba de amorObjeto #1"}
MultiLanguageQuestData['mx'][24631] = {title = "Aerofobia", objective = "Utiliza el garfio de Tomusa en los grifos de guerra Triunfo para desmontar y matar a 5 mercenarios Martillo Salvaje.", description = "La Alianza ha contratado a mercenarios Martillo Salvaje para controlar los cielos de Marca de Guerra. Creo que esos jinetes de grifos fueron los que bombardearon Taurajo durante el ataque.\n\nQuiero que alguien peine esos cielos y los limpie.\n\nLos enanos Martillo Salvaje vuelan a tan poca altura que <un/una> <clase> con una buena vista podría engancharlos. Toma esto. Apunta a los grifos y desmonta a los jinetes. Cuando caigan, no muestres clemencia.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Leotardos vinculados a la tierraManto aerofóbicoEspada de TomusaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24632] = {title = "La venganza tauren", objective = "Busca a Gann Aguja de Piedra en Los Baldíos del Sur.", description = "Mi pueblo no es colérico por naturaleza, pero, en ocasiones, la sed de justicia nos hace levantarnos con ira.\n\nCuando mi viejo amigo Gann Aguja de Piedra se enteró de la carnicería de Taurajo, enfureció. Los ancestros tribales no han podido contener más su ira.\n\nAhora sigue el mismo camino que la Horda. Se ha convertido en pícaro, <nombre>, y pretende arremeter contra la Alianza junto con un pequeño grupo de partidarios de la causa.\n\nSi también buscas venganza, le encontrarás al sureste, al pie de Bael Modan.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24633] = {title = "La súplica de Mahka", objective = "Habla con Mankrik.", description = "No me lo puedo quitar de la cabeza, <nombre>. A veces, de noche, oigo el eco de sus aullidos de rabia y sufrimiento a través de las llanuras. Me lo imagino ahí fuera, solo y sufriendo tanto...\n\nTengo que pedirte un favor. Ve donde se encuentra Mankrik y dile que venga a verme.", progress = nil, completion = "Gracias, &lt;nombre&gt;.", rewards = "Te van a lanzar el siguiente hechizo:\n\nHabló con Mankrik cancelado\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24634] = {title = "Inteligencia bélica", objective = "Mata a un operativo de los Baldíos y consigue el informe de la IV:7.", description = "Estoy convencido de que la Alianza utiliza espías para explorar el terreno y recabar información. Sabían cuándo los cazadores de Taurajo se encontrarían fuera del poblado para atacarlo, y conocían todos y cada uno de los movimientos de Gar'dul como si fuera un libro abierto.\n\nBueno, <nombre>, no me voy a dejar vencer de ninguna manera. No aquí. Ganaremos esta batalla de inteligencia.\n\nMe han informado sobre operativos de la Alianza que se ocultan en las sombras, especialmente aquí, fuera de estos muros. Mátalos y tráeme algo de utilidad.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24635] = {title = "Cúmulo de colonia clásica", objective = "Rocía a 10 personas con el vaporizador de colonia La Corona.", description = "Pareces <todo un emprendedor/toda una emprendedora>, <clase>. ¿Te parece si hacemos un trato?\n\nLa Corona quiere ofrecer muestras de nuestros últimos productos temáticos a tantos clientes en potencia como sea posible. ¡Ayúdanos a extender nuestro amor al mismo tiempo que te ganas unos fantásticos productos La Corona!\n\nTu tiempo, nuestro dinero, <amigo/amiga>. ¿Qué opinas?", progress = nil, completion = "¡Buen trabajo, &lt;nombre&gt;! La gente va a comprar toneladas de colonias La Corona, ahora que han podido probarlos.\n\nToma esto por ayudarnos.", rewards = "Recibirás:\n\nPrueba de amorObjeto #1"}
MultiLanguageQuestData['mx'][24636] = {title = "Bombardeo de bombones", objective = "Lanza muestras de chocolate de La Corona a 10 personas.", description = "Parece que tienes buen ojo para la oportunidad, <clase>. ¿Qué te parece si entre los dos nos ganamos unas monedas?\n\nLa Corona tiene que entregar muestras de nuestros últimos productos temáticos a todos los clientes en potencia de la ciudad. ¡Ayúdanos a compartir el amor y compartiremos algunos de estos fantásticos productos La Corona contigo!\n\nTu tiempo, nuestro dinero, <amigo/amiga>. ¿Tenemos un trato?", progress = nil, completion = "¡Estupendo, &lt;nombre&gt;! La gente se va a dar de tortas por comprar chocolate La Corona, ahora que han podido probar estas delicias dulces y románticas.\n\nToma esto por ayudarnos.", rewards = "Recibirás:\n\nPrueba de amorObjeto #1"}
MultiLanguageQuestData['mx'][24637] = {title = "El Carnicero de Taurajo", objective = "Habla con Karthog. Después, captura y mata al general Hawthorne.", description = "El operativo tenía órdenes de asegurar las carreteras entre los dominios de la Alianza y Fuerte Triunfo. El general Hawthorne ya se ha puesto en marcha.\n\n<Sangrastil arruga los documentos en su puño.>\n\n¡Es ÉL, <nombre>! Hawthorne, escupo su nombre, ¡es el que ordenó el asalto a Taurajo! Ya sabemos cuándo y dónde atacarlo. Rápido, sigue el camino al norte de Marca de Guerra y reúnete con mi asesino Karthog. ¡APLASTA a Hawthrone y arrastra su cuerpo por todo el camino!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Sobrehombreras de Marca de GuerraCapa de miedo recolectadoCuchillo de carnicero de TaurajoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24645] = {title = "Aplasta La Corona", objective = "Mata a 5 matones de La Corona y utiliza la bomba de korio de Tuerceganzúas para destruir un vagón químico a las afueras de Molino Ámbar en el Bosque de Argénteos. Después, vuelve con el detective Snap Tuerceganzúas en Orgrimmar.", description = "Este libro de contabilidad está lleno de lugares y necesito que los investigues y tomes medidas, <amigo/amiga>. Esto tiene que acabar.\n\nEsta es la entrada que quiero que investigues: está justo a las afueras de Molino Ámbar en el Bosque de Argénteos. No puede ser bueno. Ve y dales una paliza.\n\nAh, y si ves algo grande y peligroso que haya que destruir, tírale esta bomba.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPrueba de amor"}
MultiLanguageQuestData['mx'][24648] = {title = "Aplasta La Corona", objective = "Mata a 5 macarras de La Corona y utiliza la bomba de korio de Tuerceganzúas para destruir un vagón químico a las afueras de Theramore en Marjal Revolcafango. Después, vuelve con el detective Snap Tuerceganzúas en Orgrimmar.", description = "Este libro de contabilidad está lleno de lugares y necesito que los investigues y tomes medidas, <amigo/amiga>. Esto tiene que acabar.\n\nEsta es la entrada que quiero que investigues: está justo a las afueras de Theramore en Marjal Revolcafango. No me mires así, ¿vale? También es un problema para nosotros. Ve y dales una paliza.\n\nAh, y si ves algo grande y peligroso que haya que destruir, tírale esta bomba.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPrueba de amor"}
MultiLanguageQuestData['mx'][24651] = {title = "Aplasta La Corona", objective = "Mata a 5 subordinados de La Corona y utiliza la bomba de korio de Tuerceganzúas para destruir un vagón químico al este de Shattrath, en el Bosque de Terokkar. Después, vuelve con el detective Snap Tuerceganzúas en Orgrimmar.", description = "Este libro de contabilidad está lleno de lugares y necesito que los investigues y tomes medidas, <amigo/amiga>. Esto tiene que acabar.\n\nEsta es la entrada que quiero que investigues: parece que está al este de Shattrath, en el Bosque de Terokkar. Ve y dales una paliza.\n\nAh, y si ves algo grande y peligroso que haya que destruir, tírale esta bomba.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPrueba de amor"}
MultiLanguageQuestData['mx'][24652] = {title = "Aplasta La Corona", objective = "Mata a 5 pulverizadores de La Corona y utiliza la bomba de korio de Tuerceganzúas para destruir un vagón químico en El Bosque Desolado en el Bosque Canto de Cristal. Después, vuelve con el detective Snap Tuerceganzúas en Orgrimmar.", description = "Este libro de contabilidad está lleno de lugares y necesito que los investigues y tomes medidas, <amigo/amiga>. Esto tiene que acabar.\n\nEsta es la entrada que quiero que investigues: parece que está en El Bosque Desolado de Canto de Cristal, al noroeste de El Espejo del Crepúsculo. Ve y dales una paliza.\n\nAh, y si ves algo grande y peligroso que haya que destruir, tírale esta bomba.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPrueba de amorObjeto #1"}
MultiLanguageQuestData['mx'][24653] = {title = "El eco de Agamaggan", objective = "Reúne 3 calaveras de jabalí pulidas.", description = "Creo que los jabaespines actúan por algo más que puro antojo. ¿Me ayudas a investigar un poco este asunto?\n\nAl oeste he visto que hay calaveras de jabaespín diseminadas entre sus asentamientos y campamentos. Brillan en la distancia, suaves y pulidas... diferentes de los restos acumulados en sus montañas de desechos. Creo que estos objetos pueden ser artesanales.\n\nTráeme algunos para que los examine, <nombre>.", progress = "¿Tienes las calaveras?", completion = "Sí, estos representan claramente símbolos de Agamaggan. Pero si los jabaespines aún sienten devoción por su dios muerto, ¿cuál es la razón de su despiadada agresividad? Se dice que Agamaggan era noble y que, incluso, dio su vida por luchar contra la Legión Ardiente...\n\nUn momento, &lt;nombre&gt;. Debemos consultar a los espíritus.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24654] = {title = "Silitidofobia", objective = "Utiliza el cubo de brea ardiente sobre los montículos de silítidos y mata a 10 enjambristas silítidos cuando salgan.", description = "¡Los silítidos! Son bichos, <nombre>. O algo parecido. No son naturales... y encima hemos construido una fortaleza sobre el equivalente hormiguero.\n\nToma esta brea ardiente, prenderá fuego a los bichejos y tapará sus madrigueras al mismo tiempo. Ten cuidado cuando la arrojes por allí, ¡los silítidos acudirán en enjambres!\n\nBusca los montículos de silítidos en el exterior del Bastión de la Desolación. Parecen montañas de arena. Mata a todo lo que salga.", progress = "La Alianza no asusta a nadie. ¿Enjambres de bichejos repugnantes?\n\n<Crawgol se estremece.>", completion = "¡Estás cubierto de alquitrán caliente y zumo de bicho! No te preocupes, amiga. Ya saldrá.\n\nAlgún día...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24661] = {title = "REUSE ME", objective = "Mata a 5 lacayos de La Corona y utiliza la bomba de korio de Tuerceganzúas para dañar un vagón químico al oeste de las puertas de Orgrimmar, en Durotar, y después vuelve con el detective Snap Tuerceganzúas en Orgrimmar.", description = "Este libro de contabilidad está lleno de lugares y necesito que los investigues y tomes medidas, <amigo/amiga>. Esto tiene que acabar.\n\nEsta es la entrada que quiero que investigues: ¡está justo al lado de las puertas de Orgrimmar, al oeste! No puede ser bueno. Ve y dales una paliza.\n\nAh, y si ves algo grande y peligroso que haya que destruir, tírale esta bomba.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24665] = {title = "Aplasta La Corona", objective = "Mata a 5 subordinados de La Corona y utiliza la bomba de korio de Tuerceganzúas para destruir un vagón químico al este de Shattrath, en el Bosque de Terokkar. Después, vuelve con el inspector Snip Tuerceganzúas en Ventormenta.", description = "Este libro de contabilidad está lleno de lugares y necesito que los investigues y tomes medidas, <amigo/amiga>. Esto tiene que acabar.\n\nEsta es la entrada que quiero que investigues: parece que está al este de Shattrath, en el Bosque de Terokkar. Ve y dales una paliza.\n\nAh, y si ves algo grande y peligroso que haya que destruir, tírale esta bomba.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPrueba de amor"}
MultiLanguageQuestData['mx'][24666] = {title = "Aplasta La Corona", objective = "Mata a 5 pulverizadores de La Corona y utiliza la bomba de korio de Tuerceganzúas para destruir un vagón químico en El Bosque Desolado en el Bosque Canto de Cristal. Después, vuelve con el inspector Snip Tuerceganzúas en Ventormenta.", description = "Este libro de contabilidad está lleno de lugares y necesito que los investigues y tomes medidas, <amigo/amiga>. Esto tiene que acabar.\n\nEsta es la entrada que quiero que investigues: parece que está en El Bosque Desolado de Canto de Cristal, al noroeste de El Espejo del Crepúsculo. Ve y dales una paliza.\n\nAh, y si ves algo grande y peligroso que haya que destruir, tírale esta bomba.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPrueba de amorObjeto #1"}
MultiLanguageQuestData['mx'][24667] = {title = "Punta Piedra de Fuego", objective = "Entrega la guía de campo de los silítidos de Crawgol a Tauna Cazacielo en Punta Piedra de Fuego en Los Baldíos del Sur.", description = "Ya llevamos en esta situación con los silítidos durante casi un mes, lo que me hace el experto local. La semana pasada el Anillo de la Tierra estaba de visita y querían que les escribiera todo lo que sé.\n\n<Crawgol te entrega un libro hecho jirones.>\n\nNo soy muy buen escritor, o lector, según se mire. Pero este libro es probablemente el definitivo sobre este asunto.\n\nEntrégaselo a Tauna Cazacielo en Punta Piedra de Fuego. Se encuentra hacia el sur, al oeste del camino principal.", progress = "Ah, ¿traes noticias del norte?", completion = "¿Esto es de parte de Crawgol? ¡Estupendo! A pesar de todos los conflictos en el mundo, no podemos dar la espalda a la amenaza silítida. ¡Es importante que personas como Crawgol estudien al enemigo de cerca y aprendan sus secretos para la batalla que se aproxima!\n\n&lt;Tauna abre el libro y echa un vistazo a la primera página. Hace una mueca.&gt;\n\nOh. Bueno, supongo que algo es algo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24682] = {title = "El Foso de Saron", objective = "Reúnete con Lady Sylvanas Brisaveloz dentro de la entrada del Foso de Saron.", description = "¡Rápido, al portal! Te veré al otro lado.", progress = nil, completion = "Necios incompetentes.\n\nEmpiezo a dudar de si alguno de los patanes del torneo servirá para algo. Quizás tú me demuestres lo contrario.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24683] = {title = "El Foso de Saron", objective = "Reúnete con Lady Jaina Valiente al entrar en el Foso de Saron.", description = "¡Rápido, al portal! Te veré al otro lado.", progress = nil, completion = "He subestimado a este Señor de la Plaga, y lo han pagado mis hombres. Justo cuando pienso que mi culpabilidad por la traición de Arthas ya no puede profundizarse, él me saca de mi error una vez más.\n\nDebemos continuar. No podemos permitir que su sacrificio sea en vano.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24684] = {title = "Weezil el espía", objective = "Dirígete a Fortaleza de Bael'Dun y mata a 10 enanos Bael'Dun (fusileros, soldados y oficiales). Después encuentra a Weezil Sombraligera, que debería estar escondido dentro.", description = "<Gann te agarra con una mano ensangrentada.>\n\nMis heridas se están sanando pero no descansaré hasta que los enanos de Bael Modan paguen por sus crímenes. <Suspiro> Durante nuestro último asalto, logramos infiltrar a uno de nuestros hombres en su fortaleza. Un saboteador goblin: Weezil Sombraligera.\n\nCausa algún trastorno en las puertas, mata a quien puedas, introdúcete en la fortaleza de Bael'dun situada al sur y encuentra a Weezil.\n\nEse bastión <tos> solo puede ser destruido desde dentro, y Weezil no puede hacerlo solo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24685] = {title = "La fortaleza de los enanos", objective = "Consigue los planos de la Fortaleza de Bael'Dun.", description = "No sé si te diste cuenta cuando entraste, pero esta fortaleza se erige sobre un cañón gigante. Si encontráramos el cartucho de munición, ¡volar este sitio por los aires sería pan comido!\n\nPero para averiguarlo, voy a necesitar los planos de la fortaleza, y no he conseguido robarlos aún.\n\nBúscalos en la planta baja, bajando esas escaleras.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24687] = {title = "El ramo de la muerte", objective = "Mata a 6 manadas de azotadores jóvenes.", description = "Ya te has familiarizado con la primera fase del ciclo de vida de los pétalos de sangre: la semilla acuática. Sin embargo, la siguiente fase no es tan sencilla: la manada de jóvenes.\n\nCuando los pétalos de sangre rompen el cascarón, enseguida forman manadas y viajan juntos, contrarrestando sus puntos débiles con su número aplastante. Estas manadas de azotadores jóvenes suelen ir a lo suyo, pero si molestas a uno molestarás a todos.\n\nPor nuestra seguridad y la de los demás, deshazte de ellos. Merodean por los alrededores del oeste y del norte.", progress = nil, completion = "Has regresado victorioso. Bien, bien... quizás el cráter sea ahora un poco más seguro para aquellos que lo atraviesen.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24688] = {title = "Zen'Aliri", objective = "Preséntate ante Zen'Aliri en el Alto de Marshal.", description = "Ya has conocido a uno de mis nuevos estudiantes: Garl, el joven huargen. Mi otro estudiante es un trol llamado Zen'Aliri. Actualmente acampa con los exploradores de Expediciones Marshal del oeste.\n\nLlévale estos resultados, <nombre>, y dile que los lea bien.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24691] = {title = "Un manjar peculiar", objective = "Consigue 96 patas de silítido.", description = "Oye <chaval/chavala>, ¿te interesa ganar unas perrillas?\n\nSé de buena mano que algunos interesados están pagando MUCHA pasta por patas de silítido. Si, has oído bien, ¡patas de silítido! Al parecer, si las cocinas bien son una exquisitez. Son como langostas subterráneas y habitan en el sur.\n\nLo que pasa es que necesitaré una buena cantidad de ellas para cubrir mis gastos. ¿Crees que podrías conseguirme 8 docenas o así?", progress = "Necesito muchas porque tengo que pagar por el envío, la entrega, el marketing... ah, y tengo que pagarte a ti también.", completion = "¡Brillante! Nos encontramos en la cúspide de algo grande, &lt;nombre&gt;. Toma tu parte de la inevitable e ingente cantidad de beneficios.\n\nAhora, a otra cosa mariposa...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24692] = {title = "El coloso volantón", objective = "Mata al coloso volantón Gorishi.", description = "Si has venido a ayudar, podrías echarnos una mano con una amenaza acechante.\n\nAl sur, se levanta La Cicatriz Serpenteante, una avanzada de silítidos estremecedora situada en medio de la jungla. No pasa desapercibida.\n\nUno de mis exploradores me ha informado de que los silítidos esconden a un joven coloso en su gran cámara central subterránea y, una vez se desarrolle por completo, ¡pretenden liberarlo en Un'Goro!\n\nNo debemos permitir que ocurra, <nombre>. Encuentra al coloso y mátalo.", progress = nil, completion = "Has realizado una tarea encomiable, &lt;nombre&gt;. Realmente eres digno de elogios. ¡Gracias y felicidades!", rewards = "Brazales pellizcabrotesBotines colosalesGuantes de escama de silítidoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24693] = {title = "El Pilote Musgoso", objective = "Preséntate ante Gremix en el Pilote Musgoso.", description = "En el Alto de Marshal no puedo especular mucho sin levantar sospechas entre los científicos. Sin embargo, puede que haya otro lugar donde pueda sacarte provecho.\n\nMi socio Gremix tiene un campamento en el noroeste, al otro lado del volcán. Tiene una gran mente y mejor ojo que yo para los negocios. Estoy seguro de que podría encargarte algún trabajo si quisieras ganar algo de dinero.", progress = nil, completion = "Muy bien, si Quixxil te recomienda, supongo que cumplirás bien. Durante todos estos años que hemos trabajado juntos, Quixxil nunca se ha equivocado.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24694] = {title = "El Bancal del Creador", objective = "Habla con el Examinador de Un'Goro para teletransportarte a El Bancal del Creador y, después, habla con Nablya.", description = "<Cuando observas el orbe que hay frente a ti, escuchas una voz.>\n\nLas torres de cristal se han activado. Se han reunido suficientes cristales. Los requisitos esenciales se han cumplido. Estamos preparados para teletransportarnos a El Bancal del Creador.\n\nHabla conmigo cuando estés <listo/lista>, <raza>. Consultaremos a La Observadora.", progress = nil, completion = "Te he estado observando, &lt;nombre&gt;. Tu llegada ya estaba prevista.\n\nDe hecho, tu llegada ya estaba predeterminada desde hace algún tiempo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24697] = {title = "Conseguir carne fresca con carne putrefacta", objective = "Lanza los restos de carne putrefacta a los dinosaurios cercanos para atraerlos a los fosos de los alrededores del Alto de Marshal.", description = "Creo que no nos conocemos... soy Nolen Chincheta, el nuevo jefe de los guardias de Expediciones Marshal. También soy su chef. En realidad estas dos profesiones se solapan más de lo que crees.\n\nTengo una tarea divertida que encomendarte. ¿Has visto los fosos de pinchos en el perímetro del campamento? Intenta atraer hacia ellos a algunos dinosaurios cercanos. Si les echas esta carne podrida cuando no miren, se pondrán hambrientos o furiosos. Cualquiera de los dos estados vale, ¡siempre y cuando te sigan hasta el foso!", progress = nil, completion = "Un trabajo excelente, &lt;nombre&gt;. Ahora nos encontramos algo más seguros frente a los ataques de los dinosaurios... además, tengo toda esta carne fresca para mis hombres.", rewards = "Maza de colmillo de estegodónCinturón osteodermoGuantes de placas de diemetradónRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][24698] = {title = "Aventura arqueológica", objective = "Preséntate ante Chispik Minamal en los Baños de Golakka.", description = "Eh, ¿quieres probar mis nuevos perritos de diemetradón? ¿No? ¿Risotto de raptor? ¿Ptacos de pterrordáctilo?\n\nVale. ¡Oh, acabo de acordarme! Tengo un amigo cerca de aquí que podría necesitar tu ayuda. Su nombre es Chispik Minamal y ejerce de oficial jefe de arqueología de Expediciones Marshal.\n\nSe le ha enviado a los Baños de Golakka en el oeste. Deberías encontrarlo en la orilla oeste de los Baños.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24699] = {title = "Gormashh el Glutinoso", objective = "Mata a Gormashh y consigue el alquitrán increíblemente pegajoso.", description = "¡Eh, ya sé! Nos hemos estado fijando en las criaturas de alquitrán equivocadas.\n\nGremix me dijo una vez que se encontró con una criatura de alquitrán más grande de lo normal. Merodea por las fosa de alquitrán situada al este, en el sur de Roca Fungal. Apuesto a que, cuanto más crecen estas criaturas, ¡más pegajosas se vuelven! ¡Aún podemos enriquecernos, <nombre>!\n\n¡No te olvides del rascador!", progress = "Cuento contigo, <nombre>. Estoy interesadísima en este asunto del \"alquitrán pegamento\", y sería una lástima que volvieras con las manos vacías.", completion = "Sí, este alquitrán es genial...\n\n¡Eh, espera un segundo! Mis manos... están pegadas...\n\nQuizás no haya sido tan buena idea. ¡Ah, eso es! ¡Quita-alquitrán muy pegajoso! ¡Ahí es donde está el dinero!", rewards = "Toga impermeabilizadaBrazales pegajososRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][24700] = {title = "Difícil de recolectar", objective = "Consigue 4 flores de miera.", description = "Las Fosas de Alquitrán Lakkari situadas al norte esconden un tesoro oculto: flores extrañas que crecen en el fondo de las fosas. Las llamadas mieras están muy valoradas por su belleza y su durabilidad. Hace ya mucho tiempo que recolectaba mieras, así que podría haber nuevas plantas en el fondo de las fosas. ¿Recogerías algunas para mí?\n\nPor cierto, buena suerte cuando nades en el alquitrán. Es muy diferente al agua.", progress = "¿Ya has recogido las mieras? No las veo...", completion = "¡Ah, ahí están! ¡Buen trabajo, hermoso! Toma algo de oro. Te lo has ganado.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24701] = {title = "Los desechos de Marshal", objective = "Consigue 10 suministros desechados.", description = "Hacer dinero requiere en su mayor parte desfachatez. Tienes que estar <dispuesto/dispuesta> a aprovecharte de las desgracias de los demás. Al final, todo se reduce a una simple pregunta: ¿cuánto amas el dinero?\n\nCuando Marshal y sus hombres abandonaron su refugio del norte, dejaron atrás muchos suministros. No son cosas extraordinarias o valiosas pero están ahí por si te interesan. Su campamento se sitúa en lo alto del precipicio, en el norte.\n\nAh, y permanece alerta por si te encuentras con lo que les hizo huir...", progress = "¿Has encontrado algo interesante?", completion = "Es un montón de basura, pero es un montón de basura GRATIS, y eso es lo único que me importa.\n\nBueno, medio gratis. Aquí está tu parte. ¡Gracias!", rewards = "Varita de DoreenLeotardos abandonadosBrazales desechadosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24702] = {title = "Aquí yace Dadanga", objective = "Consigue 10 brotes Sangrepétalo.", description = "Robusta montura y fiel amigo.\n\nMurió poco después del Cataclismo. Siempre odió los estruendos.\n\nEn lugar de flores, llévale unos brotes Sangrepétalo. Nunca hubo nada que le gustara más.Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Aprenderás:\n\nBendición de Dadanga"}
MultiLanguageQuestData['mx'][24703] = {title = "Una lección importante", objective = "Habla con Maximillian de Villanorte para aprender más sobre cómo convertirte en <escudero/escudera>.", description = "¡Qué hay, <viajero/viajera>! ¡Sabrás que acabas de pisar el suelo de Maximillian de Villanorte! ¿Quizás hayas oído canciones que relatan mis muchas proezas? Por tu mirada, deduzco que así es. Ese destello de reconocimiento brilla en tu rostro como el reflejo de la Dama Blanca en el Lago del Hito.\n\nEstá claro que buscas aventura. Como pareces bastante capaz y <bienintencionado/bienintencionada>, te ofrezco que te conviertas en mi <escudero/escudera>.", progress = nil, completion = "Me complaces, &lt;nombre&gt;. De hoy en adelante dejarás de ser un simple mendigo para convertirte en el fiel escudero de Maximillian de Villanorte. Buen escudero, prepárate para nuestra primera incursión y, juntos, ¡nos sumergiremos de lleno en lo que llaman aventura!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24704] = {title = "Los dragones malignos del Cráter de Un'Goro", objective = "Ayuda a Maximillian de Villanorte a matar a 15 \"dragones\".", description = "Este cráter está infestado de proles malignas de dragones. ¿Las has visto? Merodean por todas partes, se pasean por todo el cráter con sus espaldas punzantes y sus caras de lagarto.\n\nNo te dejes engañar, <escudero/escudera>, pues estos dragones no son esbirros de la grácil Alexstrasza. Son despiadados y merecen funestamente la hoja de un héroe.\n\nHe decidido que no mataré a menos de 15. Como eres mi <escudero/escudera>, me acompañarás. Si nos separamos, deberás reunirte conmigo de nuevo en Los Baños.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24705] = {title = "Todos los habitantes merecen salvación", objective = "Rescata al morador de la costa, la moradora de los acantilados y la moradora del norte.", description = "Tengo el presentimiento de que más dragones habitan este cráter. Mi instinto de paladín me dice que hay gente del pueblo en peligro por aquí. Jamás podría ignorar a los más necesitados.\n\n¡Partamos, <escudero/escudera> <nombre>! ¡Los habitantes de Un'Goro requieren nuestra ayuda!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][24706] = {title = "Los espíritus de los Baños de Golakka", objective = "Observa mientras Maximillian de Villanorte habla con 2 furias de vapor.", description = "Un momento de seriedad, <nombre>. Nos aguarda una misión importante. Los traicioneros dragones que infestan este valle no dejarán de causar estragos hasta que destruyamos a su repugnante madre de linaje. Antes de que intentemos llevar a cabo una tarea de tal envergadura, debemos pedir ayuda a la Luz.\n\nHe visto a la Luz manifestarse cerca, bajo la forma de espíritus que flotan sobre las orillas de los Baños de Golakka. Ven, debo hablar con ellos y pedirles ayuda.Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nQuest Complete: The Spirits of Golakka Hot Springs\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24707] = {title = "La balada de Maximillian", objective = "Ayuda a Maximillian de Villanorte a matar a la Reina Demosaurio. Si te separas de Maximillian, reúnete con él en los Baños de Golakka en el Cráter de Un'Goro.", description = "El tiempo que hemos estado esperando se cierne sobre nosotros, <escudero/escudera> <nombre>. La madre de linaje de Un'Goro perecerá entre mis manos. La importancia de nuestra tarea representa un gran peso con el que tengo que cargar, pero el poder de la Luz nos protege y tenemos garantizado el éxito.\n\n¿Estás <preparado/preparada> para partir?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24709] = {title = "La historia de dos cinceles", objective = "Mata a Durrin Palaferoz y consigue los descubrimientos arqueológicos de Durrin.", description = "Eh, espera un momento, este hueso tiene marcas de piqueta. No son tuyas, ¿verdad? No, reconozco esta marca... ¡Tiene que haber sido ese maldito enano! ¡Bah!\n\nDeja que me reponga y te explicaré. Hay otro arqueólogo en el sur llamado Durrin Palaferoz. Practica un tipo de arqueología imprudente y arriesgada que me ofende incluso a mí.\n\nUn fósil impagable arruinado por un trabajo de pica chapucero. ¡Esta es la gota que colma el vaso, Durrin!\n\n<nombre>, acaba con Palaferoz y con sus prácticas de excavación negligentes.", progress = "¿Has hecho lo que debías? ¿Conseguiste recuperar sus anotaciones?", completion = "¡Lo sabía! Durrin HA estado excavando por aquí. ¡Y lo ha hecho en lo que podría ser el descubrimiento arqueológico del siglo! Ahora solo tengo que descubrir dónde esconde los huesos...\n\nGracias, &lt;nombre&gt;. Me has servido de gran ayuda.", rewards = "Coberturas delicadasBrazales excavadosPodrás elegir una de estas recompensas:\n\nNotas de Minamal\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][24711] = {title = "La Agonía de Escarcha", objective = "Reúnete con Lady Jaina Valiente a la entrada de Las Cámaras de Reflexión.", description = "Debemos continuar, <héroe/heroína>. Hemos llegado tan lejos... Estamos muy cerca de nuestro objetivo.\n\nDebo detenerme un momento para mandar a Elandra de vuelta a la nave. No estoy segura de cómo vamos a escapar tras perder a tantos hombres, con tan poca gente para asegurar nuestro camino.\n\nSigue. Me reuniré contigo en las Cámaras de Reflexión.", progress = nil, completion = "Las Cámaras de Reflexión. Por fin.\n\nAvísame cuando estés listo. Es posible que Arthas no esté aquí, pero sería ingenuo pensar que deja la Agonía de Escarcha sin vigilancia alguna.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24713] = {title = "La Agonía de Escarcha", objective = "Reúnete con Lady Sylvanas Brisaveloz dentro de la entrada de Las Cámaras de Reflexión.", description = "Continúa, la espada está cerca.\n\nNecesito un minuto para mandar a una de mis forestales oscuras de vuelta a la nave. Ahora que perdimos toda nuestra carne de cañón, no me pillarán desprevenida. Necesitaremos toda la ayuda que nos puedan enviar.\n\nVe. Me reuniré contigo en las Cámaras de Reflexión.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24714] = {title = "Buscando a Memo 01", objective = "Encuentra a Memo 01 en Roca Fungal.", description = "Desafortunadamente, algo le ha ocurrido a uno de mis mejores inventos. Has visto ardillas mecánicas, ¿no? Bueno, para acercarme a los simios del Cráter de Un'Goro, he creado un simio mecánico para que se mezcle con los de su clase. La llamo Memo 01.\n\nHa estado estudiando la fauna y la flora de Roca Fungal durante varios meses, pero ya debería haber regresado. Me temo lo peor.\n\n¿Me puedes ayudar a encontrarla?", progress = nil, completion = "Memo yace inmóvil ante ti. Parece que la energía no fluye por sus componentes.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24717] = {title = "Los simios de Un'Goro", objective = "Entrega 2 pelambres de gorila de Un'Goro, 2 pelambres de vapuleador de Un'Goro y 2 pelambres de tronador de Un'Goro a Gremix en el Pilote Musgoso.", description = "Hay mucho dinero que hacer aquí en Un'Goro, ¡solo hay que saber dónde buscar!\n\nPuede que los simios abunden en Un'Goro, pero en el norte escasean. En Vista Eterna, ¡el pellejo de gorila vale diez veces lo que te pagarían aquí!\n\nNo te voy a enviar hasta Cuna del Invierno, eso sería irresponsable, pero podrías ayudarme a conseguir algunos pellejos.\n\nEncontrarás gorilas en la Roca de Fungal situada al noreste, cerca de una cascada. ¡No olvides mirar dentro de la cueva!", progress = "Nunca me aclaro con qué estilo está de moda, así que quiero unos cuantos colores diferentes. Intenta conseguir pellejos de distintas clases de gorila.", completion = "¡Guau, 2 de cada color! Superas con creces las expectativas, &lt;nombre&gt;. Mis compañeros y yo nos gustaría tener a un &lt;raza&gt; como tú por aquí. ¿Has considerado alguna vez meterte en especulación?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24718] = {title = "El poderoso U'cha", objective = "Entrega la pelambre de U'cha a Gremix en el Pilote Musgoso.", description = "Si observas a tu alrededor, comprobarás que hay trozos de piel roja en esta parte de la cueva. Parece coincidir con la consistencia de la piel de gorila.\n\nPor tus conversaciones con Gremix, sabes que le interesaría el pellejo de gorila rojo, si pudieras conseguir uno.", progress = "¿Piel roja? ¡A qué estás esperando! ¡Vuelve y atrapa a ese gorila rojo! ¡Te pagaré el doble!", completion = "¡Guau, mira este! No es solo el color, sino el tamaño... se podría cubrir a un tauren con esto.\n\nAquí tienes, &lt;nombre&gt;. Te lo has ganado. Quédate por aquí, seguro que encuentro algo más que puedas hacer.", rewards = "Machacador de bestiasAsesino de bestiasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24719] = {title = "Garras blancas", objective = "Consigue 5 garras blancas de ravasaurio.", description = "Detente, <raza>. Me vendría bien la ayuda de <un/una> <clase> como tú.\n\nJusto fuera del campamento acechan raptores con garras mortales. He estado utilizando las garras para rituales druidas pero no parece que funcionen. Sin embargo, me percaté de que algunos de esos raptores tienen garras blancas, cuando la mayoría posee unas negras mortales.\n\nLa naturaleza es caprichosa. ¿Podrías conseguirme algunas garras blancas para intentarlo por última vez?", progress = "¿Has conseguido alguna garra?", completion = "Mi maestro afirma que, a veces, tienes que tomar de la naturaleza para poder dar. Estos raptores... siento que han muerto por una buena causa.\n\nGracias, &lt;nombre&gt;.", rewards = "Moledora de hueso blancaVara de hueso blancaPodrás elegir una de estas recompensas:\n\nArmella de hueso blanca\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][24720] = {title = "Cristales de poder", objective = "Recoge 7 cristales de poder de cada color: rojo, azul, amarillo y verde.", description = "Estoy segura de que los has visto, <nombre>. ¡Están por todas partes!\n\n¿Que de qué estoy hablando? ¡De cristales, por supuesto!\n\nLos cristales... Se encuentran por todo el cráter. La mayoría los ignora, pero tengo un extraño presentimiento de que encierran un gran poder en su interior.\n\nDigamos que se me están acabando los cristales que tengo aquí, ¿crees que podrías traerme algunos?\n\nEncontrarás los amarillos en el noroeste, los rojos al... bueno, seguro que lo adivinas.", progress = "¡Solo sé que he dado con algo, <nombre>!", completion = "¡Ahora continuaré con mis experimentos! Gracias, &lt;nombre&gt;.", rewards = "Te van a lanzar el siguiente hechizo:\n\nQuest - J.D. Collie - Any Pylon Quest Completed Forcecast\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24722] = {title = "La Torre de cristal del Norte", objective = "Descubre la localización de la Torre de Cristal del Norte en el Cráter de Un'Goro.", description = "Nos has hecho unos cuantos favores, <nombre>... Ahora deja que Gremix te haga uno a ti. Los ataques al Refugio de Marshal fueron sin duda terribles. Nos pillaron desprevenidos y no tomaron prisioneros. Tuvieron suerte de que muchos de ellos sobrevivieran.\n\nHace unas semanas, me encontré una torre de cristal en los precipicios del noreste, al este del Refugio de Marshal. Creo que la torre y los ataques podrían estar relacionados de algún modo. ¿Puedes investigarlo? Seguro que alguien del Alto de Marshal te lo agradecerá.", progress = nil, completion = "&lt;nombre&gt;, ¿crees que esto podría tener relación con los ataques al Refugio de Marshal?", rewards = "Te van a lanzar el siguiente hechizo:\n\nQuest - J.D. Collie - Any Pylon Quest Completed Forcecast\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24723] = {title = "La Torre de cristal del Oeste", objective = "Descubre la localización de la Torre de Cristal del Oeste.", description = "La investigación de Durrin tocaba un área que me intriga: un vínculo potencial entre los titanes y los dinosaurios. Cuando J.D. Collie vuelve al campamento siempre habla que si de titanes, que si de cristales... Quizás esté interesada.\n\nPuede que quieras visitar la Torre de Cristal que hay cerca antes de ir a informarla. Se sitúa justo en lo alto de los precipicios, al oeste de aquí. Contiene cristales y siempre me pareció que tenía algo que ver con los titanes.", progress = nil, completion = "¿Una torre en el oeste? ¿Y una relación entre titanes y dinosaurios? Esto es mucho que asimilar, &lt;nombre&gt;.", rewards = "Te van a lanzar el siguiente hechizo:\n\nQuest - J.D. Collie - Any Pylon Quest Completed Forcecast\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24724] = {title = "El cristal de restauración", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nCristal de restauración"}
MultiLanguageQuestData['mx'][24725] = {title = "Carga de cristal", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][24726] = {title = "La fuerza de cristal", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][24727] = {title = "Aguja de cristal", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][24728] = {title = "Resguardo de cristal", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][24729] = {title = "Reducción de cristal", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][24730] = {title = "Choca esos huesos", objective = "Consigue 8 huesos de dinosaurio.", description = "Tal vez viendo que soy el jefe de excavaciones de las Expediciones Marshal, pienses que me gusta excavar. La verdad es que puede haber cosas peores en el mundo... pero no salto de alegría.\n\nSe supone que estábamos excavando en el Camino del Terror (un nombre FANTÁSTICO, por cierto) buscando diemetradones y stegodones muertos. ¡Y todavía quedan muchos vivos! Wil y Hol siguen estudiando este lugar, así que necesitamos huesos de esos dinosaurios. Pero entre tú y yo, también valdrá si traes huesos de ejemplares vivos.", progress = "Piensa lo que quieras de mí, pero les da igual si los huesos que investigan son de estegodones y diemetradones antiguos o de los que casi nos devoraron cuando intentábamos establecer nuestros campamentos. Yo solo quiero salir de aquí con vida...", completion = "Excelente, con esto será suficiente. Y, ahora, si me disculpas, en caso de que alguien esté escuchando...\n\nGRACIAS POR EXTRAER TODOS ESTOS HUESOS DEL SUELO PARA NOSOTROS SIN DAÑAR A LAS BESTIAS NATIVAS DE NINGUNA MANERA.\n\nSi lo hiciste o no, prefiero no saberlo. Dejémoslo así, ¿vale? Toma, quizás esto te ayude a mantener la boca cerrada sobre el asunto. ¡Lo que sea por salir de aquí con vida!", rewards = "Botas de utilidad de arqueólogoCinturón de cantera de excavadorRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24731] = {title = "La comida de Lar'korwi", objective = "Encuentra los restos de una presa fresca de Lar'korwi y roba un trozo de trillanodonte muerto.", description = "Una vez, hace mucho tiempo, mi hermano cogió un trozo de carne de una presa de Lar'korwi. En ese momento no se dio cuenta pero Lar'korwi le vio desde el bosque. Lar'korwi siguió a mi hermano durante días, destrozando todo lo que encontraba en su camino. Mi hermano, aterrorizado, decidió alejarse del cráter y olvidarse de Lar'korwi.\n\nLar'korwi lo mató no muy lejos de este emplazamiento.\n\nSi quieres provocar a Lar'korwi, encuentra una de sus presas recientes y coge algo de carne.\n\nComienza tu búsqueda por el oeste.", progress = "No tomes mis palabras a la ligera, <nombre>. Si realmente quieres enfrentarte a esta criatura, debes actuar con prudencia y habilidad. Conseguir que Lar'korwi venga a por ti y finalmente derrotarlo requerirá mucha fuerza y perspicacia por tu parte.", completion = "Esta carne servirá, &lt;nombre&gt;. Parece que Lar'korwi no pasa hambre, ¿eh? Me pregunto dónde habrá encontrado un trillanodonte... es extraño.\n\nDe cualquier modo, guardaré esto hasta que estés preparado para enfrentarte a él. No te preocupes por mí, pues seguro que has enfadado tanto a Lar'korwi que no me hará daño hasta que te haya echado el diente a ti.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24733] = {title = "El cebo para Lar'korwi", objective = "Utiliza el contenido de la faltriquera de Torwa para atraer la presencia de Lar'korwi y derrótalo. Después llévale la cabeza de Lar'korwi a Torwa Abrecaminos, que está cerca de la entrada del Cráter de Un'Goro.", description = "Esta es la parte más difícil debido a la complejidad que entraña el plan. Sigue el río hacia el norte y busca un meandro. Allí es donde vi a Lar'korwi por última vez. Sabrás que te encuentras en la zona que buscas por todos los restos de huesos de criaturas enormes que antes deambulaban por el lugar.\n\nCoge la carne que conseguiste y colócala allí. A continuación, unta esta mezcla que he creado en la carne.\n\nSi la mezcla de los dos señuelos no consigue atraer a Lar'korwi, no sé qué otra cosa podría.", progress = "No dejes que el miedo te bloquee, <nombre>. El miedo es traicionero... ¡pero debes superarlo!", completion = "¡Alabada sea la Madre Tierra! ¡Lo has conseguido! Buen trabajo, &lt;nombre&gt;. Has demostrado ser un gran cazador por ti mismo. Eres fuerte de espíritu. Tu valor no tiene igual. Y tu fuerza se ha fortalecido. Me inclino ante tus habilidades.\n\nSolo el más destacado de mis ancestros podría haber conseguido algo tan loable. Felicidades.", rewards = "Jubón de acechador de las llanurasMalla de anillas de escoltaPodrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][24735] = {title = "Un poco de ayuda de mis amigos", objective = "Lleva a Ringo con Spraggle Frock en el Alto de Marshal.\n\nSi Ringo se siente débil, abofetéalo. Si se desmaya, utiliza la cantimplora de Spraggle para revivirlo.", description = "Uf... hace tanto calor...\n\nEstaba explorando esta zona cuando, de repente, el calor se hizo realmente insoportable. Debo de haberme quedado exhausto.\n\nPor favor, ayúdame a volver con mi amiga Spraggle en el Alto de Marshal. Creo que tendré fuerzas para seguirte hasta allí.\n\nMe encuentro algo mal, así que, si me mareo, abofetéame. Si volviera a desmayarme, échame por encima algo de agua de la cantimplora de Spraggle. Debería funcionar... espero.", progress = nil, completion = "Ringo no está en plena forma, &lt;nombre&gt;, ¡pero me alegra tenerlo de vuelta de una sola pieza! \n\nGracias por encontrarle.", rewards = "Leotardos de los bosquesCelada de ClayridgeMusleras con joyasRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][24736] = {title = "El aparato volador de Shizzle", objective = "Recoge 35 escamas de pterrordáctilo palmeadas.", description = "¡Estoy construyendo una máquina voladora!\n\nMe he quedado varado aquí, y soy un desastre para orientarme. Utilizaría un grifo o un Jinete del Viento para regresar a Gadgetzan pero esas bestias me ponen los pelos como escarpias.\n\n¿Me ayudarás? Lo único que me queda por construir son las alas, y estaba pensando que las escamas palmeadas de los pterrordáctilos de la Cuenca de los Gritos del oeste serían ideales. De ninguna manera me enfrentaría a uno de esos, pero tú pareces bastante fuerte. ¿Por qué no lo intentas?", progress = "Todo vehículo que se precie tiene nombre... Estaba pensando en llamarlo... ¡Pwned!", completion = "Sí, estas escamas son perfectas. ¡Debería poder levantar del suelo la máquina con estas escamas!\n\n¡Gracias!", rewards = "Limpiador de bozal de ShizzleCobertura de bozal de ShizzleBloquealloviznas de ShizzleRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24737] = {title = "Superpegajoso", objective = "Reúne 8 muestras de alquitrán muy pegajoso.", description = "Siempre estoy pensando en un modo rápido de ganar una pieza de oro, <nombre>. Si me ayudas en mi nueva idea, te daré parte de los beneficios. ¿Qué te parece?\n\n¡Eso pensaba yo!\n\nVamos a hacer pasta gansa. Ve a las fosas de alquitrán del norte y recoge algo de alquitrán. Pero no cualquier alquitrán... Tendrás que coger el alquitrán depositado sobre las bestias que habitan en las fosas de alquitrán. Como ventaja, si utilizas mi rascador de alquitrán en sus cadáveres, no tendrás que ensuciarte las manos.", progress = "Tara lo ha vuelto a conseguir, ¡este pegamento superpegajoso hará furor!", completion = "Sí, supongo que este alquitrán es muy pegajoso. Es decir, es pegajoso, pero no es pegajoso \"ahora voy y me forro\". Supongo que tendré que seguir pensando.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][24740] = {title = "Actividad volcánica", objective = "Recoge 9 muestras de cenizas de Un'Goro de los elementales de fuego que están alrededor del volcán en el Cráter de Un'Goro.", description = "<Bienvenido/Bienvenida>. Soy Williden Marshal y, junto con mi hermana, lidero la expedición de exploradores y científicos. ¿Tienes un momento?\n\nNo me gustan esos elementales del volcán, <clase>. Tenemos demasiado equipo, demasiadas notas... Un elemental enloquecido podría abrirse camino hasta nuestro campamento y causar grandes estragos.\n\nMuéstrales que sus nuevos vecinos no se andan con chiquitas. Y entrégame las cenizas que dejan como rastro... Nosotros también cumpliremos con nuestra parte.", progress = "¿Crees que el volcán está activo? Me pregunto por qué no explotó cuando tuvo lugar el Cataclismo.", completion = "Espero que sirviera. Cogeré las cenizas... pueden resultarnos útiles en un futuro.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24742] = {title = "Busca la fuente", objective = "Krakle del Cráter de Un'Goro quiere que encuentres los puntos más calientes de la Cresta del Penacho en Llamas. \n\nCuando encuentres un punto caliente, utiliza el termómetro para comprobar la temperatura. Sigue buscando hasta que encuentres el más caliente.", description = "He creado un termómetro para registrar la temperatura del volcán y me gustaría descubrir cuáles son los ríos de lava más calientes. ¡Mide la temperatura en grados Kraklenheit!\n\nToma, llévatelo, ¡y registra la temperatura de la cresta cuando veas un punto caliente!\n\nLos puntos calientes suelen tener forma de pilar de brasas que sobresalen del suelo. Los encontrarás alrededor del suelo de la Cresta del Penacho en Llamas... una vuelta alrededor del perímetro probablemente bastará.", progress = "Iría allí yo mismo, pero... ¡me dan algo de miedo los elementales de fuego!", completion = "¡Los resultados son sorprendentes! Mi jefe se pondrá contentísimo. ¡Gracias, amable &lt;raza&gt;!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24743] = {title = "El Filo de las Sombras", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nFilo de las Sombras"}
MultiLanguageQuestData['mx'][24745] = {title = "Hay algo en el aire (y no es amor)", objective = "Llévale la tarjeta preciosa descolorida al inspector Snap Tuerceganzúas en Ventormenta.", description = "El interior de la tarjeta está garabateado con planes dementes y detallados para infectar a la mayor parte de Azeroth. ¡Deberías enseñárselo a uno de los investigadores de Bonvapor enseguida!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][24746] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][24747] = {title = "¡Sabotaje!", objective = "Sabotea una carcasa de artillería enana y huye de Bael'Dun antes de que explote.", description = "La artillería enana tiene un temporizador de explosiones en el aire incorporado. ¡Es fácil! Sabotea una artillería del muelle de carga y, a continuación, súbela para introducirla en el cargador. Sayonara baby. ¡BOOM!\n\nEncontrarás las artillerías en uno de los dos muelles de carga situados detrás del garaje de esta planta, justo al doblar la esquina.\n\nCuando hayas manipulado la artillería... ¡corre! ¡Corre como el viento, <nombre>! Después, regresa al campamento para informar a Gann. Yo estaré detrás de ti.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Yelmo de Punta de LanzaSobrehombros de PicopiedraPodrás elegir una de estas recompensas:\n\nAmuleto insuflado\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][24748] = {title = "La última batalla del Rey Exánime", objective = "El Alto señor Darion Mograine, en la Ciudadela de la Corona de Hielo, quiere que mates al Rey Exánime.", description = "Agonía de Sombras; un arma recién forjada que ya es parte de la historia de este mundo. Ha renacido para cumplir un destino incomparable.\n\nJunto con esta arma portas una gran responsabilidad, y la hora de cumplir con ella se acerca.\n\nToma esta arma de mitos y leyendas y carga contra el enemigo. Venga a los incontables héroes que hemos perdido en esta campaña inmisericorde. Ofréceles descanso a sus almas torturadas.\n\nSé fuerte, <clase>, y guía a la Agonía de Sombras para que cumpla el propósito de su creación.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24750] = {title = "El levantamiento de los Lanza Negra", objective = "Reúnete con Soratha en el Campo de Entrenamiento Lanza Negra.", description = "Los miembros de la tribu Lanza Negra hemos sío víctimas durante mucho tiempo. Parias. Nos veíamos obligaos a abandoná nueh'tros hogares con'tantemente... pero, ahora, eh'tamos aquí por otra razón.\n\nVol'jin nos ha ofrecido liderazgo a través de sabiduría, y hemos sobrevivío ha'ta ahora. Pero la mih'ma sabiduría augura un futuro caótico pa la Horda bajo el mando de Garrosh Grito Infernal.\n\nEh'ta vez no huiremos. Ahora lucharemos por un hogar que perdure.\n\nEs hora de empezá con el entrenamiento, <nombre>. Habla con Soratha al este.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24758] = {title = "El levantamiento de los Lanza Negra", objective = "Reúnete con Nekali en el Campo de Entrenamiento Lanza Negra.", description = "Los miembros de la tribu Lanza Negra hemos sío víctimas durante mucho tiempo. Parias. Nos veíamos obligaos a abandoná nueh'tros hogares con'tantemente... pero, ahora, eh'tamos aquí por otra razón.\n\nVol'jin nos ha ofrecido liderazgo a través de sabiduría, y hemos sobrevivío ha'ta ahora. Pero la mih'ma sabiduría augura un futuro caótico pa la Horda bajo el mando de Garrosh Grito Infernal.\n\nEh'ta vez no huiremos. Ahora lucharemos por un hogar que perdure.\n\nEs hora de empezá con el entrenamiento, <nombre>. Habla con Nekali al este.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24764] = {title = "El levantamiento de los Lanza Negra", objective = "Reúnete con Zen'tabra en el Campo de Entrenamiento Lanza Negra.", description = "Los miembros de la tribu Lanza Negra hemos sío víctimas durante mucho tiempo. Parias. Nos veíamos obligaos a abandoná nueh'tros hogares con'tantemente... pero, ahora, eh'tamos aquí por otra razón.\n\nVol'jin nos ha ofrecido liderazgo a través de sabiduría, y hemos sobrevivío ha'ta ahora. Pero la mih'ma sabiduría augura un futuro caótico pa la Horda bajo el mando de Garrosh Grito Infernal.\n\nEh'ta vez no huiremos. Ahora lucharemos por un hogar que perdure.\n\nEs hora de empezá con el entrenamiento, <nombre>. Habla con Zen'Tabra al este.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24770] = {title = "El levantamiento de los Lanza Negra", objective = "Reúnete con Legati en el Campo de Entrenamiento Lanza Negra.", description = "Los miembros de la tribu Lanza Negra hemos sío víctimas durante mucho tiempo. Parias. Nos veíamos obligaos a abandoná nueh'tros hogares con'tantemente... pero, ahora, eh'tamos aquí por otra razón.\n\nVol'jin nos ha ofrecido liderazgo a través de sabiduría, y hemos sobrevivío ha'ta ahora. Pero la mih'ma sabiduría augura un futuro caótico pa la Horda bajo el mando de Garrosh Grito Infernal.\n\nEh'ta vez no huiremos. Ahora lucharemos por un hogar que perdure.\n\nEs hora de empezá con el entrenamiento, <nombre>. Habla con Legati al este.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24776] = {title = "El levantamiento de los Lanza Negra", objective = "Reúnete con Ortezza en el Campo de Entrenamiento Lanza Negra.", description = "Los miembros de la tribu Lanza Negra hemos sío víctimas durante mucho tiempo. Parias. Nos veíamos obligaos a abandoná nueh'tros hogares con'tantemente... pero, ahora, eh'tamos aquí por otra razón.\n\nVol'jin nos ha ofrecido liderazgo a través de sabiduría, y hemos sobrevivío ha'ta ahora. Pero la mih'ma sabiduría augura un futuro caótico pa la Horda bajo el mando de Garrosh Grito Infernal.\n\nEh'ta vez no huiremos. Ahora lucharemos por un hogar que perdure.\n\nEs hora de empezá con el entrenamiento, <nombre>. Habla con Ortezza en el eh'te.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24777] = {title = "A golpe de entrenamiento", objective = "Destruye 6 dianas Tiki.", description = "Bien, colega. Empecemos con lo básico. Necesito saber si maneh'as bien esa arma que llevas a cueh'tas.\n\nDale una buena tunda a esas dianas Tiki. Tómatelo con calma. Sé natural. Observaré cómo luchas y pah'tiremos de esa base.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24778] = {title = "Las artes del cazador", objective = "Habla con Ortezza para aprender Disparo firme. Usa Disparo firme 5 veces contra una diana Tiki.", description = "Tengo algo que mostrah'te. En realidad es bah'tante sencillo, pero podría resultar útil.\n\nPodemoh' utilizar muchos tipos de dih'paros engañosos con arcos y armas de fuego pero, sin un pulso firme que los dirih'a, terminarás <agotao/agotá> y no matarás de forma eficiente. Tómate tu tiempo, eh'tabiliza tu arco y sigue lanzando flechas a tu diana. Deseh'tabiliza a tus objetivos.\n\nPrueba eh'te hechizo y ven a verme cuando creah' que lo dominas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24779] = {title = "Un duro comienzo", objective = "Consigue 6 pelajes de gato Ferocrín.", description = "Vamos a empezar a sacar pah'tido a tus habilidades. Empezaremos con algo fácil, colega.\n\nAlgunos gatos eh'tán atacando a nueh'tros jabalís. La comida no se compah'te. Necesitamos vivos a esos jabalís si quieres cená eh'ta noche.\n\nEh'tán por toda la isla. Tráeme algunos pelajes de gato.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24780] = {title = "Foso de pruebas", objective = "Habla con un carcelero Lanza Negra; después entra en el foso de pruebas y mata a un explorador Escama Maliciosa cautivo.", description = "Lo haces bah'tante bien tú <solo/sola>, <clase>. Seguro que podría enseñah'te un par de trucos aquí y allá, pero ya no te haré perder el tiempo con más dianas Tiki.\n\nTe voy a hacer una última prueba, colega. Dirígete al foso de pruebas en medio de eh'ta zona y enfréntate a un tipo duro de roer, uno capaz de matah'te durante la pelea. Avisa al carcelero del foso cuando eh'tés <lih'to/lih'ta> pa' comenzar.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nArco de cazador Lanza Negra"}
MultiLanguageQuestData['mx'][24781] = {title = "Mejor de lo esperado", objective = "Preséntate ante Vol'jin en el Bastión Lanza Negra.", description = "Definitivamente, eres mejor de lo que pensaba, colega. Seguro que hay cosas más impoh'tantes en las que inveh'tir tu talento. Ya no tienes por qué mezclah'te con los novatos.\n\nDirígete al poblao del sureh'te y date a conocé. Echa una mano por aquí y allá y aumentarás tu preh'tigio rápidamente.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24782] = {title = "El levantamiento de los Lanza Negra", objective = "Reúnete con Tunari en el Campo de Entrenamiento Lanza Negra.", description = "Los miembros de la tribu Lanza Negra hemos sío víctimas durante mucho tiempo. Parias. Nos veíamos obligaos a abandoná nueh'tros hogares con'tantemente... pero, ahora, eh'tamos aquí por otra razón.\n\nVol'jin nos ha ofrecido liderazgo a través de sabiduría, y hemos sobrevivío ha'ta ahora. Pero la mih'ma sabiduría augura un futuro caótico pa la Horda bajo el mando de Garrosh Grito Infernal.\n\nEh'ta vez no huiremos. Ahora lucharemos por un hogar que perdure.\n\nEs hora de empezá con el entrenamiento, <nombre>. Habla con Tunari al este.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
