MultiLanguageQuestData['mx'][24793] = {title = "El topo", objective = "Preséntate ante el investigador Fezzen Arreolatón en el Castillo de Colmillo Oscuro.", description = "Pareces lo bastante hábil para enfrentarte al cerebro de toda esta operación. El libro de contabilidad dice que se esconde en el Castillo de Colmillo Oscuro, así que allí te voy a enviar.\n\nYa tenemos a un hombre dentro, pero no puede desarticular una operación él solo. Entra y el investigador se reunirá contigo. Llévate unos amigos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24794] = {title = "Habla con Spraggle", objective = "Habla con Spraggle Frock en el Alto de Marshal.", description = "Mi buena amiga Spraggle lleva algún tiempo preocupada por algo. Le ayudaría, pero, como puedes observar, estoy bastante cómodo ahora mismo.\n\n¿Podrías ir a verla y comprobar qué necesita?", progress = nil, completion = "¿Qué? ¿Te ha enviado Krakle?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24796] = {title = "Una victoria para El Pacto de Plata", objective = "Llévale la Quel'Delar restaurada a Vereesa Brisaveloz a la Ciudadela Violeta de Dalaran.", description = "A pesar de la fanfarronería de la Reina Lana'thel, has restaurado Quel'Delar, <nombre>. Hemos soñado con reclamar Quel'Delar tanto tiempo.\n\nEl Pacto de Plata y por supuesto todos los quel'dorei están en deuda contigo.\n\nVereesa Brisaveloz, la líder de El Pacto de Plata, ha pedido verte tras tu vuelta de La Fuente del Sol. Llévate a Quel'Delar y ve a La Ciudadela Violeta de Dalaran donde te espera, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Quel'Delar, astucia de las SombrasQuel'Delar, lente de la menteQuel'Delar, poderío de los fielesQuel'Delar, ferocidad de los despechadosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24797] = {title = "REUSE", objective = "Cuando completes esta misión ganarás:\n\n", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][24798] = {title = "Una victoria para los Atracasol", objective = "Llévale la Quel'Delar restaurada a la justicar Mariel Corazón Veraz a los Campos del Torneo Argenta.", description = "¡Por fin, Quel'Delar ha sido restaurada por la gloria de los Atracasol y los sin'dorei!\n\nToda Lunargenta te aclamará como <un héroe/una heroína>, <nombre>.\n\nComo <clase>, la espada parece saber que no tienes la formación para blandirla y no se ha ligado a ti. ¿De dónde vendrá su próximo maestro? No ha aparecido ningún sin'dorei digno. Pidamos ayuda a la Cruzada Argenta. Ve al norte, a los Campos del Torneo Argenta y presenta la espada a la justicar Mariel Corazón Veraz en nombre de los Atracasol.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Cayada de justicia furiosaMartillo de llama purificadaAguja natoluzRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24799] = {title = "Una victoria para los Atracasol", objective = "Llévale la Quel'Delar restaurada a la justicar Mariel Corazón Veraz a los Campos del Torneo Argenta.", description = "¡Por fin, Quel'Delar ha sido restaurada por la gloria de los Atracasol!\n\nToda la Horda te aclamará como <un héroe/una heroína>, <nombre>.\n\nComo <clase>, la espada parece saber que no tienes la formación para blandirla y no se ha ligado a ti. ¿De dónde vendrá su próximo maestro? No ocultaré mi desilusión; esperaba que fuera un sin'dorei digno. Pidamos ayuda a la Cruzada Argenta. Ve al norte, a los Campos del Torneo Argenta y presenta la espada a la justicar Mariel Corazón Veraz en nombre de los Atracasol.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Cayada de justicia furiosaMartillo de llama purificadaAguja natoluzRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24800] = {title = "Una victoria para los Atracasol", objective = "Llévale la Quel'Delar restaurada al archimago Aethas Atracasol a la Ciudadela Violeta de Dalaran.", description = "¡Por fin, Quel'Delar ha sido restaurada por la gloria de los Atracasol y los sin'dorei! Toda Lunargenta y toda la Horda te proclamará <un héroe/una heroína>.\n\nEl archimago Aethas Atracasol, líder de los Atracasol, ha pedido verte tras tu regreso de La Fuente del Sol. Viaja a La Ciudadela Violeta en Dalaran en cuanto puedas, <nombre>, y lleva contigo a Quel'Delar. ¡El Archimago quiere felicitarte personalmente!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Quel'Delar, astucia de las SombrasQuel'Delar, lente de la menteQuel'Delar, poderío de los fielesQuel'Delar, ferocidad de los despechadosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24801] = {title = "Una victoria para los Atracasol", objective = "Llévale la Quel'Delar restaurada al archimago Aethas Atracasol a la Ciudadela Violeta de Dalaran.", description = "¡Por fin, Quel'Delar ha sido restaurada por la gloria de los Atracasol y la Horda! Es una bendición por nuestros esfuerzos contra el Rey Exánime.\n\nEl archimago Aethas Atracasol, líder de los Atracasol, ha pedido verte tras tu regreso de La Fuente del Sol. Viaja a La Ciudadela Violeta en Dalaran en cuanto puedas, <nombre>, y lleva contigo a Quel'Delar. ¡El Archimago quiere felicitarte personalmente!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Quel'Delar, astucia de las SombrasQuel'Delar, lente de la menteQuel'Delar, poderío de los fielesQuel'Delar, ferocidad de los despechadosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24802] = {title = "La cólera del Rey Exánime", objective = "Encuentra a Lady Sylvanas Brisaveloz y escapa de Las Cámaras de Reflexión.", description = "Es difícil creer que haya esperanzas de derrotar a Arthas en los peldaños de su propio trono. ¿Y quién se hará con la corona del Rey Exánime si es así?\n\nQuedan demasiadas preguntas, pero tienes que encontrar a Sylvanas y escapar del Rey Exánime mientras aún haya tiempo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nPuntos de justicia"}
MultiLanguageQuestData['mx'][24803] = {title = "Competición de pesca Kalu'ak", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nAnillo de pirata aterradorBotas de la bahía\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][24805] = {title = "Olores extraños", objective = "Preséntate ante el detective Snap Tuerceganzúas en Orgrimmar.", description = "Hay gato encerrado en Químicos La Corona, S.L. Los de Bonvapor le tienen echado el ojo, pero me vendría bien otro par.\n\nVe a Orgrimmar si te interesa ayudarnos. El detective Snap Tuerceganzúas dirige la investigación desde allí, y necesita toda la ayuda que podamos prestarle.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][24806] = {title = "Más suerte la próxima vez", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nBolsa de tesoros de pesca"}
MultiLanguageQuestData['mx'][24807] = {title = "Winnoa Bosque de Pinos", objective = "Habla con Winnoa Bosque de Pinos en Punta Vendetta, en Los Baldíos del Sur.", description = "Tras haber conseguido grandes logros, sería una tragedia que parte de la corrupción hubiera pasado inadvertida. Los pasillos de las Cuevas de los Lamentos se extienden por todos los Baldíos y, si otro foco de energía salvaje hubiera conseguido salir a la superficie...\n\nSin embargo, ya has hecho bastante por mí. Solo te pediré que informes a una camarada druida de lo que ha ocurrido. Encontrarás a Winnoa Bosque de Pinos en Punta Vendetta, al suroeste.", progress = nil, completion = "Desde aquí pude sentir lo que ocurrió, &lt;clase&gt;. Se me erizó hasta el último pelo.\n\nMe alegra oír que has conseguido diezmar a esos horrores, me aseguraré de registrar la zona por si hubiera criaturas descarriadas.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24815] = {title = "Elige tu camino", objective = "Para expiar los pecados que cometí cuando era uno de los caballeros de la Muerte del Rey Exánime, me he dedicado a crear anillos de gran poder para que los usen nuestros hermanos y hermanas en la guerra.\n\nHas demostrado ser un valioso aliado en la lucha contra la Plaga, <nombre>. A medida que progrese tu dedicación podré mejorar el diseño original del anillo.\n\nElige tu camino con cuidado. Cambiar de opinión tiene su precio.", description = nil, progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nSortija Cinérea de corajeSortija Cinérea de venganzaSortija Cinérea de destrucciónSortija Cinérea de sabiduríaSortija Cinérea de poderío\n\nTambién recibirás:\n\n"}
