MultiLanguageQuestData['mx'][24905] = {title = "Devolver un favor", objective = "Encuentra a Megs Trituramatic en el Campo de Reclutamiento Machacaduna.", description = "¿Sabes qué? Mientras estabas fuera encargándote de lo tuyo, Megs pasó por aquí. Hacía meses que no la veía, pero no se detuvo ni un instante, solo quería que te dijera que tenía más trabajo acumulado.\n\nDijo que se dirigía a la Base Machacaduna para abrir un negocio, algo relacionado con ogros. Como ya has acabado aquí, deberías irte para allá... yo no haría esperar a una goblin como ella.", progress = nil, completion = "Tengo algo grande para ti esta vez, &lt;nombre&gt;. Vamos a iniciar a estos ogros en la Horda... trabajando directamente bajo nuestro mando.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24906] = {title = "Salvamento costero", objective = "Recoge 7 suministros de Bonvapor.", description = "Tenemos que empezar a mover los productos en este mercado cuanto antes si queremos ser competitivos. Tengo una idea para nosotros.\n\nGadgetzan está sometida a bloqueo por los piratas, pero muchos de los productos que se tiran de los barcos permanecen intactos... sencillamente se los lleva la corriente. La mayoría acaban en los bancos de arena al sur de la ciudad.\n\nDirígete hacia allí y empieza a recuperar objetos; hay cajones llenos de puros beneficios flotando por allí.", progress = "Veamos lo que tienes.", completion = "Mmm, casi todo servible. Esto es genial. Por supuesto ya tengo a compradores haciendo cola.\n\nAquí tienes el adelanto para el resto del trabajo que vas a hacer para mí y para el Cártel Pantoque... socio.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24907] = {title = "Chapoteando en los charcos", objective = "Mata a 8 zancudos de marea.", description = "Esta es la situación. Si queremos establecer la presencia comercial del Cártel Pantoque en Gadgetzan, tendremos que empezar a proporcionar servicios a la comunidad.\n\nLa nueva costa ha resultado genial para hacer negocios, pero el mar también ha traído gigantes marinos hasta aquí. Son enormes, repugnantes y hacen que los valores inmobiliarios caigan.\n\nDirígete a los bancos de arena al sur de la ciudad y mata a todos los que puedas, y te daré una parte de los acuerdos que estoy negociando por aquí.", progress = nil, completion = "Los valores inmobiliarios ya han subido desde que te fuiste. A la gente le gustan las vistas al mar que no incluyen a salobres y retorcidos gigantes marinos chapoteando por todas partes.\n\nAquí está tu parte, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24910] = {title = "Rescate cohete", objective = "Entrega cohetes salvavidas a 5 supervivientes Bonvapor y usa bombas para matar a 40 bloqueadores de Costasur.", description = "Vale, <nombre>. Ya hemos hecho bastantes trabajillos pequeños por aquí; ha llegado el momento de cerrar el trato.\n\nLas ruinas de Puerto Bonvapor todavía están llenas de desventurados goblins Bonvapor, que esperan ser rescatados. Todos y cada uno de ellos son potenciales clientes. Están disparando contra todos los barcos que salen del puerto... Así que, ¡propongo que pasemos al cielo!\n\nHay un globo aerostático justo al salir de la ciudad cerca del muelle: podemos usarlo. Adelante súbete, yo te alcanzaré luego.", progress = nil, completion = "¿Verdad que resulta agradable realizar una buena acción, y observar el enorme potencial económico de la misma? Se me ablanda el corazoncito de goblin que tengo. Y mi enorme cartera de goblin, claro.\n\nLo has hecho genial, chico. Gadgetzan pronto será nuestra. Aquí tienes una pequeña muestra de mi agradecimiento.", rewards = "Cucharón de sopa de NasmiraYelmo Bonvapor rescatadoPrototipo de cohete salvavidas fallidoPodrás elegir una de estas recompensas:\n\nBomba falsa\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][24911] = {title = "El paraíso tropical te espera", objective = "Preséntate ante Williden Marshal en el Alto de Marshal en el Cráter de Un'Goro.", description = "Oye, tienes pinta de <aventurero/aventurera> sagaz. ¿Buscas nuevas experiencias? ¿Algo exótico? ¿Algo... rentable?\n\nBueno, sacúdete la arena de las botas porque tengo una propuesta que hacerte. Williden Marshal busca espadas competentes como la tuya. Su avanzada se encuentra en el Alto de Marshal, al sureste del volcán situado en centro del exuberante Cráter de Un'Goro.\n\nAunque, bueno, el paraíso no es para todos, <raza>. Depende de ti. Tu oasis tropical te espera.", progress = nil, completion = "Oye Hol'anyee, ¡mira a este!\n\n&lt;Williden se vuelve hacia ti.&gt;\n\nEjem, ¿te envía nuestro reclutador? Bien. Vamos a empezar con un poco de sinceridad: Un'Goro no es el nirvana perfecto que probablemente te habrán vendido. Pero seguro que ya te has dado cuenta cuando venías hacia aquí.\n\n¿Nos ponemos manos a la obra?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24913] = {title = "Recuerda la Luz", objective = "Ayuda al anacoreta Avuun a despedirse de Magtoor.", description = "Magtoor se debilita por momentos, <nombre>. He preparado el remedio. Debe funcionar... ¡Debe funcionar!\n\nHas hecho tanto por nosotros... Sería un honor para mí que te quedaras para lo que podrían ser los últimos momentos de Magtoor.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nAbrazo de la Luz"}
MultiLanguageQuestData['mx'][24916] = {title = "El guardapelo de Jaina", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nGuardapelo de Jaina"}
MultiLanguageQuestData['mx'][24917] = {title = "El lamento de Muradin", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nFavor de Muradin"}
MultiLanguageQuestData['mx'][24918] = {title = "La venganza de Sylvanas", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nCaja de música de Sylvanas"}
MultiLanguageQuestData['mx'][24919] = {title = "La redención del Iluminado", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nTabardo del Iluminado"}
MultiLanguageQuestData['mx'][24921] = {title = "Informa a Aubrey", objective = "Preséntate ante el almirante Aubrey en Fuerte del Norte.", description = "¡Oye tú! ¿<Forastero/Forastera>? <Bienvenido/Bienvenida> a Kalimdor, una tierra que te mata o en la que mueres en el intento.\n\nTenemos problemas en el bastión, como habrás comprobado en tu viaje. El almirante Aubrey necesita toda la ayuda posible si queremos salir airosos de la situación. ¡Considérate <reclutado/reclutada>, <clase>!\n\nSigue el camino por la colina y encontrarás a Aubrey en lo alto de la torre.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24922] = {title = "Classic Random Heroic (1st)", objective = "Recibirás:\n\nCuando completes esta misión ganarás:\n\n", description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24923] = {title = "Burning Crusade Random Heroic (Nth)", objective = "Recibirás:\n\nCuando completes esta misión ganarás:\n\n", description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24925] = {title = "Liberar a los cautivos", objective = "Libera a 5 goblins cautivos.", description = "Han capturado a algunos ciudadanos. Sé que están practicando extraños rituales con ellos. ¡Parece que les están drenando la energía vital!\n\n¡Debes dirigirte al poblado y liberar a los cautivos antes de que sea demasiado tarde!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24927] = {title = "Cofre de un hombre muerto", objective = "Mata a 15 filibusteros de los Mares del Sur de cualquier tipo.", description = "Mira, <tío/nena>, deberías comprender lo que está pasando aquí con bastante facilidad. Tenemos piratas, tenemos goblins, los goblins se enfrentan a los piratas. Hay unos pobres gnomos tratando de enfrentarse también a los piratas.\n\nTe lo diré bien clarito: tenemos que matar a un montón de piratas. Encárgate de eso, ¿de acuerdo? Después de todo, no estaría bien que los gnomos matasen más que nosotros.", progress = nil, completion = "Es un auténtico placer informarte de que el reconocimiento de nuestra marca ha subido como la espuma en esta zona ahora que has liquidado a la mayoría de la gente que no nos quería por aquí.", rewards = "Caperuza de los Mares del SurLeotardos de DellotGuantes marcadosEspaldares limpiadosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24928] = {title = "¡Hasta los cimientos!", objective = "Prende fuego a la cabaña noroeste, a la cabaña sureste y a la cabaña noreste.", description = "He realizado una valoración concienzuda de la propiedad inmobiliaria en la zona y, por desgracia, su valor de mercado es demasiado bajo como para que nos sirva de algo. Vamos a tener que renovarlo.\n\nPor suerte para ti, he aprendido algo sobre el arte del incendio. ¡Espero que tú también! Vas a lanzar estas botellas perfectamente seguras de ron inflamable contra esas asquerosas y destartaladas cabañas de ahí.\n\nIntenta no ponerte en la dirección del viento.", progress = nil, completion = "Un trabajo estupendo. ¿Has pensado alguna vez en dedicarte a los incendios de forma profesional? Tengo algunos contactos, es un trabajo agradable.\n\nBueno, ya charlaremos sobre eso más tarde. ¡Quedan cosas por hacer aquí!", rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][24929] = {title = "Envía un mensaje", objective = "Mata a Yngwie.", description = "El líder Oomlot, Yngwie, es demasiado poderoso como para dejarlo con vida. Está espetando tonterías desde la elevada parte oeste del poblado, al otro lado del puente colgante.\n\nDirígete allí y elimínalo antes de que envíe al resto del poblado contra nosotros.\n\n¡Es pan comido!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Jubón de YngwieCapa de pigmeoBastón oomlotRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24930] = {title = "Ya que estás en ello", objective = "Mata a 5 huargen Colmillo de Sangre.", description = "Si el rey Cringris quiere que arriesgues tu vida para rescatar a un traidor reconocido, yo no me voy a oponer.\n\nHazme un favor y haz algo útil mientras estás por ahí: mata a esos malditos sacos de pulgas.", progress = nil, completion = "Si no te hubiese visto matar a algunos esos sarnosos con mis propios ojos, pensaría que no habías completado la tarea que te había pedido.\n\nParece que apenas hemos afectado a su número.", rewards = "Brazales de ArmsteadCoselete de mercaderRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24931] = {title = "Añadido de observador", objective = "Reúne 5 cristales oculares de observadores Cristaldermo.", description = "Vas a cazar hienas, ¿eh? Si no te importa, tengo una oferta para ti. Necesito ojos de los observadores Cristaldermo que merodean por el norte. Sus ojos contienen maravillosos cristales, valiosos para... los coleccionistas.\n\nSeguramente habrás oído decir que algunos individuos penosos los usan para mejorar sus facultades parapsicológicas, ¡pero te aseguro que mi interés es puramente académico!\n\nTráeme unos cuantos y te los pagaré bien. ¡Al menos te pagaré más que esos avaros goblins!", progress = "Esto... ¿Los tienes?", completion = "¡Aah, perfecto! Justo lo que necesito... repleto de potentes energías de enfoque...\n\n...¡Ejem! Quiero decir, ¡perfecto para mi colección! ¡Narain Sabelotodo no necesita ningún tipo de mejora artificial en absoluto!\n\n¡Recoge tu paga y lárgate!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24932] = {title = "Reducir pérdidas", objective = "Mata a 15 silítidos Hazzali de cualquier tipo en la Sima Abierta.", description = "Llevo toda la semana mirando fijamente este horrendo foso y tratando de pensar en cómo sacarle partido a una panda de artrópodos peligrosos y violentos. Me he quedado sin ideas y tengo un hambre de muerte.\n\nEstas cosas no valen para nada, así que he decidido que ha llegado el momento de librarse de ellas. Dirígete al foso y empieza a matar bichos.", progress = nil, completion = "Esto no avanza lo bastante deprisa. Tiene que haber un modo más rápido...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24933] = {title = "Pollo del desierto", objective = "Reúne 6 piezas de carne de hiena.", description = "Tengo una idea, pero vamos a necesitar un cebo.\n\nEl otro día vi una hiena Llagapata rabiosa merodeando demasiado cerca de la sima, y uno de los silítidos salió de pronto de la nada. ¡Casi se la traga entera! Fue una visión horrible.\n\nAsí que vamos a necesitar carne de hiena, es evidente. Ve a buscar un poco, asegúrate de que es fresca, y tráela aquí. Tiene que haber de sobra justo al norte del campamento.", progress = "¿Es fresca, verdad? No irán a por nada que se haya estado secando al sol.", completion = "Vaya, esta movida tiene una pinta deliciosa. Me entran tentaciones de freír un poco para mí.\n\n¡No! Tenemos que centrarnos en salir de aquí.\n\nTal vez solo un trocito...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24934] = {title = "¡Al abordaje!", objective = "Habla con el almirante Aubrey para volar al Pozo Negro y mata a 6 lobos de mar Gruñefuria.", description = "<nombre>, el mar es nuestro único camino a la salvación y ahora la mayor parte de mi flota está zarpando de vuelta a Theramore para ser reparada o se encuentra encallada en el fondo de la bahía. Solo queda a flote el Pozo Negro para defender nuestro puerto.\n\n¡Pero parece que está siendo abordado!\n\nHabla conmigo cuando estés <listo/lista>, uno de mis grifos navales te dejará en la cubierta. Elimina a esos lobos de mar Gruñefuria que se atreven a asaltar mi preciado navío y preséntate ante el capitán Fisher para recibir instrucciones.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24937] = {title = "Problema de los Oomlot resuelto", objective = "Habla con Sassy Malallave en la Ciudad de Bolsillo, en Las Islas Perdidas.", description = "<nombre>, ¡tienes que regresar a la Ciudad de Bolsillo y alertar de la presencia de goblins zombis en la caldera del volcán!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24938] = {title = "Las armas del Fuerte del Norte", objective = "Habla con el cañonero Smythe.", description = "El capitán Fisher nos ha hecho señales desde abajo. ¿Que la Horda está desembarcando unidades en la orilla? Debemos impedir que nos flanqueen desde allí.\n\nYa he enviado a dos de mis mejores artilleros a defender la cabecera de la playa. Habla con el cañonero Smythe en la orilla.\n\nTendrás que abrirte paso por el patio para llegar hasta allí. ¡Intenta ayudar al resto a asegurar el bastión cuando bajes!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24939] = {title = "Apunta y dispara", objective = "Usa una batería de costa de Fuerte del Norte para destruir 10 botes de remos Gruñefuria.", description = "Contamos con el material pero no con la mano de obra, <nombre>. Maneja una de las carronadas de la orilla y hunde los botes que vayan llegando.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Cinturón de CarronaderBrazales de Fuerte del NortePodrás elegir una de estas recompensas:\n\nAnillo de Smythe\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][24940] = {title = "El volcán", objective = "Habla con Entrenador Paselargo en Pico Perdido, en Las Islas Perdidas.", description = "Muchos ciudadanos se han dirigido a la cima del volcán para planear una contraofensiva. Algo horrible se está cociendo en Pico Perdido.\n\nAguardan tu llegada antes de realizar cualquier movimiento contra los pigmeos. Esos pequeños seres malignos han transformado a muchos de nosotros en zombis.\n\n<nombre>, ¡sálvanos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24941] = {title = "Tiro de Crestalarga", objective = "Reúne 15 trozos de tiro de Crestalarga.", description = "¡<clase>! Gracias a la Luz, prácticamente nos han traído de nuevo a los muelles. ¡Invadieron el patio!\n\nYa no nos queda munición y los orcos se están preparando en lo alto de la colina para atacar. Tenemos que improvisar algunos disparos de dispersión, y rápido.\n\nApúrate, entra en la torre y busca cualquier cosa afilada o trozo de chatarra que puedas encontrar. Cuchillos, tenedores, clavos... ¡lo que sea! ¡Carga el cañón cuando tengas suficiente!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24942] = {title = "Zombis contra botas con súper cohetes propulsores", objective = "Usa las botas con súper cohetes propulsores para matar a 50 goblins zombis.", description = "Esos zombis que nos cruzamos no son nada comparado con la multitud que aguarda tras el desfiladero. Si no nos encargamos de ellos pronto, los médicos brujos pigmeos les ordenarán atacar la ciudad ¡y ni siquiera nuestros cañones bastarán para eliminarlos a todos!\n\nHe traído un par de botas trituradoras. Greely las manipuló ¡y ahora se han convertido en unas botas con súper cohetes propulsores!\n\nUsa las botas para prender fuego a los zombis en los poblados Oostan del este.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "B.S.C.P. Prototipo 1B.S.C.P. Prototipo 3B.S.C.P. Prototipo 2Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24943] = {title = "Defender el patio", objective = "Mata a 10 brutos Gruñefuria.", description = "Así se despeja una colina. ¡Esos cadáveres tienen atravesados cuchillos y tenedores!\n\nEl clan Gruñefuria ha abierto una brecha en los muros pero aún podemos darle la vuelta al resultado de la batalla. Desciende la colina y ayuda a nuestros hombres a conservar el patio de abajo...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Cinturón de PaxtonCapa de gruñefuria incautadaBotín del PatioRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24944] = {title = "Retomar la batalla", objective = "Utiliza las vendas impregnadas de hierbas en 6 defensores heridos.", description = "La lucha no ha terminado ni de lejos, <clase>. \n\nAlgunos soldados del patio aún tienen aire en los pulmones. ¡Podemos salvarlos! He impregnado estas vendas de un remedio de hierbas en el que solíamos confiar en Gilneas. El olor es asqueroso pero su cataplasma prácticamente resucita a los muertos.\n\nUtiliza estas vendas en los defensores heridos del patio de abajo y veamos si podemos hacer que retomen la batalla.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24945] = {title = "Los tres pigmeos", objective = "Mata a Gaahl, a Malmo y a Teloch.", description = "Mira, creo que está genial que eliminemos a los zombis, aunque sean amigos y familiares. Pero, ¿no crees que también deberíamos encargarnos de los pigmeos que los crean?\n\nEn los tres poblados Oostan, Nord, Sor y Ost, hay médicos brujos: Gaahl, Malmo y Teloch.\n\n¿Podrías encargarte de ellos? ¡No quiero convertirme en un zombi!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Leotardos de médico brujoBrazales de OysteinRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24946] = {title = "Polvo del Rock", objective = "Recoge 5 muestras de polvo del Rock.", description = "Hay que reconocerles algo a estos pigmeos... ¡desde luego saben pasárselo bien! Pero no son tan listos. Creo que he descubierto la fuente de sus poderes roqueros: ¡el polvo del Rock!\n\nResulta que este polvo que les convierte en estrellas del rock también es altamente explosivo. ¡Hay que hacerse con él!\n\nAsí que, cuando te encuentres en Oostan, al este, asegúrate de recoger un buen puñado de esa cosa. Créeme, ¡vas a necesitarlo para enfrentarte a lo que se nos avecina!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24947] = {title = "Momento", objective = "Encuéntrate con Megs Trituramatic en Cala del Aparejo Perdido.", description = "No podemos dormirnos en los laureles aquí, <tío/nena>. ¡Tenemos que aprovechar este momento! La gente habla de nosotros.\n\nPor desgracia también hablan de esa gnoma cabeza hueca, Kelsey, que por lo visto ha estado trabajando en lo mismo que nosotros. Si queremos echarla de lo que debería ser una ciudad goblin, tenemos que cerrar el trato aquí.\n\nNos vamos a encargar del problema de piratas de Gadgetzan, de una vez por todas. Dirígete hacia el sur, a Cala del Aparejo Perdido, nos encontraremos allí.", progress = nil, completion = "¡Qué bien que hayas venido! Voy a necesitar mucha ayuda si pretendemos adelantarnos a estos gnomos.", rewards = nil}
MultiLanguageQuestData['mx'][24948] = {title = "Levantar el asedio", objective = "Utiliza la antorcha de Paxton para quemar 3 catapultas Gruñefuria y 1 lanzacuchillas Gruñefuria.", description = "Mientras Gruñefuria y sus matones tengan artillería, no podremos volver a asegurar los muros de la fortaleza. Necesito que atravieses la sima y destruyas sus armas pesadas.\n\nLos orcos curten su maquinaria pesada con alquitrán de carbón, lo que la hace inflamable. Toma mi antorcha y prende fuego a todas las catapultas que veas al norte del Fuerte del Norte.\n\n¡Luego prende fuego a esos enormes lanzacuchillos en el campamento de Gruñefuria! Ya mataron a suficientes de nuestros hombres.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24949] = {title = "La llamada del botín", objective = "Reúne 10 piezas de botín pirata.", description = "No despilfarremos, <tío/nena>. Estos piratas tienen montones de historias valiosas por ahí desperdigadas, esperando a que alguien las embargue. Resulta increíble que sencillamente acumulen esas cosas.\n\n¿Para qué narices se molestan en conseguirlas si solo quieren acumularlas por ahí? Los productos robados hay que venderlos para poder comprar cosas nuevas y brillantes.\n\nPero bueno, vas a ser un cielito y me vas a traer todo el botín con el que puedas cargar mientras estás por ahí aplastando cabezas, ¿verdad? ¡Adiós!", progress = "Veamos lo que tienes. No escondes nada para quedártelo tú, ¿verdad? Nunca encontrarás comprador sin mí y lo sabes.", completion = "¡Una preciosidad! Y pensar que esos estúpidos sencillamente dejan que se acumule por ahí.\n\nAquí tienes un pequeño adelanto, ya hablaremos de bonificaciones por compartición de beneficios más adelante.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24950] = {title = "Capitán Barbatroz", objective = "Mata al capitán Barbatroz.", description = "Vale, <tío/nena>, tengo algo más importante para ti aquí.\n\nHemos avistado al capitán de los Mares del Sur en uno de sus barcos del sur; y me refiero a los del sur, NO a este al que hemos estado tratando de atacar de forma suicida durante varias horas. Está ahí sentado, con aire de suficiencia y tranquilidad, observando cómo luchamos aquí abajo.\n\nMe ahorraré los chistes sobre \"opas hostiles\". Sube a su barco, dale una buena paliza, ¡y aquí ya hemos terminado!", progress = nil, completion = "¿Gigantes marinos? ¿Crees que los estaba adiestrando para que se dirigieran a Gadgetzan a propósito?\n\nEs igual, ahora ha huido. ¡Y Gadgetzan nos debe un favor de los gordos! Estoy deseando ver la cara de Marin.\n\nAquí está tu parte, tío. Vas avanzando en este mundo.", rewards = "Togas de flirteoGuantes de estrangulador BarbatrozCinturón de investigadorBotas impacientesRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24951] = {title = "Una idea genial", objective = "Usa el cebo de insecto de Contrabandista para capturar a un enjambrista Hazzali.", description = "Ahora que tenemos un buen montón de trozos frescos, los atamos a esta cuerda y... ya puedes ir a cazarme un silítido.\n\n¿Qué? No me mires así, es perfectamente seguro. Bueno, casi seguro. Vale, puede que te mueras de dolor. ¡Pero será fácil! Solo tienes que lanzar esa carne ahí fuera, esperar que un insecto pique ¡y luego lo arrastras hasta aquí con la cuerda!\n\nVe tras uno de los enjambristas. No he visto a ninguno ir tras las hienas nunca y deberías encontrar un montón de enjambristas al extremo del foso.", progress = nil, completion = "¡Mira qué tamaño tiene! Es glorioso. Este feo chupador va a ayudarnos a acabar con el enjambre entero.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][24952] = {title = "El impulso de botas cohetes", objective = "Usa las botas cohetes imbuidas con polvo del Rock y entrégaselas a Hobart Martillazos.", description = "Tienes que llevar las botas a la caldera y entregárselas a Hobart Martillazos.\n\nAhora que están imbuidas con el polvo del Rock restante, deberían proporcionarte suficiente impulso como para recorrer todo el camino del tirón.\n\nCuando estés <listo/lista>, activa las botas. No te preocupes, están programadas para que el aterrizaje sea seguro.\n\nO eso creo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24953] = {title = "Intentando matar a un puñado de bichos", objective = "Habla con Narain Sabelotodo para pilotar el enjambrista bajo control mental hasta el interior de la colmena de Sima Abierta.", description = "Ha llegado el momento de llevar a efecto mi plan, por completo. Tenemos al bicho capturado atado a todos los explosivos que es capaz de transportar, y con los sorprendentes poderes mentales de Sabelotodo, vamos a dirigir a ese zoquete directamente hasta el centro de la colmena subterránea.\n\nY después... ¡BUM! ¡Se acabaron los bichos!\n\nTienes el honor de dirigir al bicho asqueroso. Ve a hablar con Narain y apáñatelas con tu amigo el bicho.", progress = nil, completion = "¡Vaya, eso ha sido genial! ¡Deberías haber visto las llamas que salían de la colmena!\n\nAquí está tu recompensa, ¡tanto por el entretenimiento como por limpiar la colmena!", rewards = "Guantes impresionantesBotas AtabotasQuijotes de contrabandistaPodrás elegir una de estas recompensas:\n\nColgante de la Sima Abierta\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][24954] = {title = "Los hijos del dios tortuga", objective = "Recoge 5 glándulas de fuego.", description = "Volcanoth es un dios tortuga que habita en la cueva que adoran estos primitivos.\n\nEn realidad no es un dios.\n\n<Hobart entorna los ojos.>\n\nPero es bastante resistente, por lo que tendré que diseñar una nueva arma para ti a partir de la bota que funciona todavía.\n\nCreo que el antiguo lema de \"echar más leña al fuego\" se aplica muy bien a este caso. Además, ¡me gusta el fuego!\n\nConsigue algunas glándulas de fuego de los hijos de Volcanoth, así ganaré tiempo para convertir la bota cohete en algo que se ajuste a nuestras necesidades.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24955] = {title = "Sin privilegios", objective = "Obtén 10 firmas de personajes de ogros de Machacaduna.", description = "Es posible que ya haya mencionado mi intención de conseguir que esos ogros de Machacaduna se unan a la Horda... y que trabajen para el Cártel Pantoque como mano de obra local barata.\n\nPara conseguirlo, tenemos que defender aunque sea de boquilla el proceso de iniciación y todo eso, si no me lloverán las críticas después. Así que he ideado un personaje, y he introducido los ritos de iniciación en las estipulaciones del contrato de trabajo por tiempo limitado.\n\nTengo un disfraz para ti aquí, así que póntelo y consigue todas esas firmas.", progress = nil, completion = "¡Vaya, buen trabajo! Me sorprende incluso que hayas sido capaz de conseguir que sostengan un boli sin comérselo.\n\nPuedes, eh, tirar el disfraz ahí mismo. Lejos de mí. En el fuego.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][24956] = {title = "Silenciar a los Gruñefuria", objective = "Mata a 4 tenientes Gruñefuria y consigue el yelmo Gruñefuria matando a Karga Gruñefuria.", description = "Ya me he topado anteriormente con el clan Gruñefuria, <nombre>. Su líder no es un orco, sino un monstruo, un desalmado amante de la guerra sin una pizca de compasión o decencia. Él y sus tenientes deben morir no solo para salvar Fuerte del Norte, sino por el bien de Azeroth.\n\nKarga Gruñefuria porta un yelmo. <clase>, mátalo y tráemelo. Tiene una importancia... especial.\n\nGruñefuria ha levantado su campamento en la sima, al este.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Botas del hermano caídoPodrás elegir una de estas recompensas:\n\nTrofeo gruñefuria\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][24957] = {title = "Centipaartes a raudales", objective = "Reúne 20 centipaartes de silítidos Centipaar.", description = "Vale, <tío/nena>. Tal y como te dije, los ogros son demasiado estúpidos como para saber lo que significa firmar ese contrato. Ahora tenemos que conseguir que de verdad se vengan con nosotros, así que tendremos que proporcionarles algo de su apreciado sabor local.\n\nSabor local para estúpidos redomados, quiero decir.\n\nDirígete a La Guarida Ponzoñosa, al oeste; es ese terrible foso lleno de peligrosos silítidos. Mata a unos cuantos silítidos Centipaar y tráelos aquí para que podamos repartir sus pedazos, ¿de acuerdo? Adiós.", progress = "¿Tienes suficientes? Estos ogros no parecen conformarse con porciones pequeñas.", completion = "¡Puaj! Este campamento es un auténtico muestrario de olores asquerosos.\n\nNo alarguemos esta situación más de lo necesario.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24958] = {title = "¡Volcanoth!", objective = "Usa la Botazuca para matar a Volcanoth.", description = "Me ha costado sudor, sangre y lágrimas, pero la Botazuca, pendiente de patente, ¡ya está lista para usar!\n\nEstos malvados pigmeos han estado alimentando a su \"dios\", Volcanoth, con nuestro pueblo, ¡y están a punto de liberarlo en nuestra ciudad!\n\n¡Tienes que ir a la cueva y matar a ese bicho antes de que sea demasiado tarde!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCordón de escala de rescate"}
MultiLanguageQuestData['mx'][24959] = {title = "Recién salido de la tumba", objective = "Preséntate ante el enterrador Mordo en las Tumbas del Camposanto, en los Claros de Tirisfal.", description = "¡<nombre>!\n\n¡Levántate, <nombre>!\n\n<Bienvenido/Bienvenida> al reino de los vivos. Gracias a la bendición y al poder de la Dama Oscura te he liberado de las garras de la muerte.\n\nNo eres <un esclavo/una esclava>, <nombre>. A partir de ahora eres libre de recorrer el camino que escojas. Si decides servir a la Dama Oscura Sylvanas, te recomiendo que hables con el enterrador Mordo. Está detrás de mí, en el cementerio.Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nInvocar a Agatha\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24963] = {title = "Atácalos con cariño", objective = "Usa los manjares promocionales del Cártel de Pantoque con 8 ogros de Machacaduna después de debilitarlos.", description = "Vale, <tío/nena>, escucha. Hay dos formas de conseguir que la gente haga lo que tú quieres. Puedes suministrarles productos, servicios y cosas que la gente quiera... o puedes darles una paliza de muerte.\n\nYo siempre he encontrado útil hacer las dos cosas a la vez, y tú ya estás lo bastante <familiarizado/familiarizada> con ambos métodos a estas alturas. Coge estas golosinas silítidas, ve a machacar a unos cuantos ogros, cuando estén atontados dales la golosina, justo antes de dejarlos inconscientes, ¿de acuerdo?", progress = nil, completion = "Buen trabajo, has enseñado a la mitad de los ogros del lugar a temer y respetar a todo lo que tenga el más ligero parecido con una &lt;raza&gt;.\n\nResulta sorprendente la pequeña recompensa necesaria para tener a la gente comiendo de tu mano, ¿verdad? Aquí tienes tu pago, por cierto.\n\n...¿A qué viene esa cara?", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][24974] = {title = "100 años de soledad", objective = "Utiliza la correa de múrloc en un múrloc Anca Vil en la Costa Murmurante y, después, entrégaselo a Sedrick Calston en los Dominios de Calston.", description = "Trabajas duro durante toda tu vida, ¿y qué consigues? Que una plaga te mate. Después, trabajas aún más duro en la no-muerte, ¿y qué obtienes? Dinero, sí, y una pequeña propiedad con unos cuantos aduladores apestosos, pero, ¿qué hay de la felicidad? No tanta.\n\nMe siento solo a mi edad, <nombre>. Necesito compañía. Usa esta correa en uno de los múrlocs de la Costa Murmurante, al noroeste. Deberás debilitarlo antes de atarle la correa. Después, tráemelo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][24975] = {title = "Campos de pena", objective = "Roba 10 calabazas de la Hacienda Solliden en Claros de Tirisfal.", description = "¿Qué tenemos aquí? Pareces <un/una> <clase> en ciernes. Si quieres demostrar tu valía a la Dama Oscura, necesitarás aprender las técnicas de los Renegados.\n\nAl oeste encontrarás una granja. Los humanos infestan la tierra como el moho en un cadáver putrefacto. Y, aún peor, la Cruzada Escarlata patrulla cerca de su torre. Dale una lección a esa escoria y roba 10 de sus preciadas calabazas.\n\nCuando tengas las 10, tráemelas.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24976] = {title = "La variedad es la sal de la muerte", objective = "Consigue 4 medupétalos, 4 espinas de Xavren y 8 pepinos de mar curados.", description = "Estas calabazas cumplen un propósito, <clase>. Servirán como mecanismo de transmisión de mi última pila de peste, que será especialmente dolorosa y virulenta. Sin embargo, la plaga requiere unos cuantos ingredientes excepcionales.\n\nNecesitaremos medupétalos, que crecen en el fondo de la Charca Aguaserena, en dirección este. También necesitaremos espina de Xavren, que crece en los rocosos acantilados del noroeste. Y, por último, necesitaremos algunos pepinos de mar curados, que se encuentran fuera del alcance de las olas de la Costa Murmurante.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Guantes de XavrenBotas de medupétaloRecibirás:\n\nBolsa de calabazasCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24977] = {title = "El experimento de Johaan", objective = "Lleva la calabaza envenenada al zelote Escarlata capturado que se encuentra en la glorieta de los Dominios de Calston.", description = "Con que calabazas inofensivas, ¿eh? O, al menos, eso parece. Si queremos detener el avance de la Plaga en el norte y derrotar a la infestación humana en el sur, tendremos que empezar a valorar el auténtico potencial de nuestro don de no-muertos.\n\nCon un poco de ingenuidad, una mera calabaza puede convertirse en el agente de nuestra Dama Oscura. Esta calabaza, envenenada con mi última fórmula, será algo más que un manjar.\n\nHemos capturado a otro zelote Escarlata y lo tenemos cerca de la glorieta. Llévale la calabaza al bobo ese.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24978] = {title = "Segar los segadores", objective = "Mata a 10 granjeros de Tirisfal o mozos de labranza de Tirisfal.", description = "Los humanos son criaturas veleidosas. Los granjeros del oeste no son una excepción. Seguro que se encuentran arando sus tierras plácidamente pero, mañana, quizás alcen sus hoces contra nosotros. La amenaza de la Alianza se acerca a Gilneas, y el poder de Ventormenta acecha en el sur... cualquiera de ellos podría reclutar a estos vástagos y utilizarlos en nuestra contra.\n\nQuiero que los mates. Encárgate de que así sea.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Barazales de CocerHoja de guadañaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][24979] = {title = "La carta Escarlata", objective = "Encuentra a la prisionera en el Acantilado Escarlata.", description = "Teniente Gebler:\n\nQué curioso que hayas decidido tomar como prisionera a una no-muerta... ¿en qué estabas pensando? ¿Creías que, gracias al estado anterior de la prisionera, se libraría de los decretos de la Cruzada Escarlata?\n\nTe has metido en un buen lío Gebler. Te recuerdo que existen castigos para ese tipo de comportamiento. Te ordeno que ejecutes de inmediato a la prisionera. Ya no forma parte de los nuestros.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][24980] = {title = "El Acantilado Escarlata", objective = "Mata a 10 guerreros Escarlata.", description = "Necesitamos a alguien con \"iniciativa\" como tú para dirigir a la Cruzada Escarlata a la tumba.\n\nDemuéstrame que eres capaz de servir a la Dama Oscura viajando hacia el oeste hasta la torre pasada la hacienda Solliden y mata a 10 guerreros de la Cruzada Escarlata.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24981] = {title = "Una espina clavada", objective = "Mata a 3 zelotes Escarlata y a 3 misioneros Escarlata, y consigue la epístola Escarlata.", description = "La información que hemos recibido del ejecutor Arren, en Camposanto, contiene todos los detalles necesarios para borrar a la peste humana de la tierra. Según los datos, la Cruzada Escarlata ha enviado al capitán Perrine y a una brigada a la torre en ruinas que se encuentra al suroeste de Rémol.\n\nMata a 3 de sus zelotes y a 3 de sus misioneros y, ya que estás, intenta recabar más información sobre sus planes.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24982] = {title = "Los nuevos Renegados", objective = "Preséntate ante el magistrado Sevren en Rémol en Claros de Tirisfal.", description = "Francamente, los Renegados de antaño éramos un grupo de lloricas patéticos. Nos apiñábamos en los decrépitos edificios de los humanos, huíamos de la Peste, temblábamos de miedo ante la Alianza y nos postrábamos ante la Horda.\n\nObserva a tu alrededor, y mira el producto de los nuevos Renegados. Nos hemos ganado una reputación en Azeroth que irá en aumento. ¡No tardaremos en dominar el mundo!\n\n¿Quieres mi consejo? Habla con el magistrado Sevren en Rémol, en dirección sur. Él dirige la ciudad.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24983] = {title = "Las obligaciones de los Renegados", objective = "Habla con la Guardia de la Muerte Linnea en el Apeadero del ocelo de la Muerte en Claros de Tirisfal.", description = "Necesito conocer las últimas noticias de nuestro puesto del Guardia de la Muerte situado al este de aquí.\n\nTengo que saber si las fuerzas de la Plaga han pasado por El Baluarte y han entrado en Tirisfal. Debemos mantener la vigilancia en la frontera con las Tierras de la Peste pues no podemos permitir que la Plaga afiance su presencia aquí.\n\nViaja hacia el sur siguiendo el camino y cuando este se bifurque, continúa en dirección este hasta el puesto. Habla con la Guardia de la Muerte Linnea. Ella tiene la información que necesito.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24988] = {title = "El frío de la muerte", objective = "Consigue 5 pelambres de Murciumbrío.", description = "Hace un frío estremecedor. La Peste de los no-muertos repta por mis venas como una serpiente helada. Pronto sucumbiré al estado descerebrado. Pero ningún destino, por maldito que esté, me impedirá servir a nuestra Dama Oscura. Cuando surgió la llamada, cosí bolsas de cadáveres para los soldados caídos de la poderosa armada de Sylvanas.\n\nAhora mis manos tiemblan de frío. Si me trajeras cinco pelambres de Murciumbrío, podría hacerme una manta. <nombre>, ayúdame a seguir sirviendo a la causa.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Chapines de GretchenPantalones de MurciumbríoBrazal del ocelo de la MuerteRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24989] = {title = "Regresa junto al magistrado", objective = "Ve a ver de nuevo al magistrado Sevren de Rémol.", description = "Ahora llévale la información que te he dado al magistrado Sevren. Le gustará recibirla lo antes posible así que date prisa.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24990] = {title = "Análisis de sangre", objective = "Recoge 5 viales de sangre de can oscuro.", description = "Lady Sylvanas convocó a la Sociedad Real de Boticarios. Nos desafió a preparar una plaga nueva, una plaga más mortífera que cualquier enfermedad de Azeroth. Esta nueva enfermedad conducirá a la ruina a nuestros enemigos, vivos y muertos.\n\nMis estudios muestran que la sangre de las bestias puede ser la clave. Toma, llena estos viales de sangre de can oscuro para que pueda probar mi teoría.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nElixir de sangre de trol débilCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24991] = {title = "La Granja de Garren", objective = "Preséntate ante el boticario Jerrod en la Granja de Garren en Claros de Tirisfal.", description = "Como habrás notado, la Sociedad Real de Boticarios es una organización de gran alcance. Nos tomamos muy en serio la alquimia en la Plaga. Creemos que cuantos más agentes haya realizando experimentos, antes alcanzaremos nuestro objetivo.\n\nUno de nuestros agentes lleva a cabo su trabajo en un pequeño campamento al norte de aquí. Su nombre es Jerrod, y no le vendría mal un aprendiz de tu... talla.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24992] = {title = "La huida de Gilneas", objective = "Informa de la presencia del huargen al ejecutor Zygand en Rémol en Claros de Tirisfal.Como ya sabes, un huargen pícaro que deambula por Tirisfal es un suceso nuevo. Creo que el ejecutor Zygand podría estar muy interesado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", description = "Como ya sabes, un huargen pícaro que deambula por Tirisfal es un suceso nuevo. Creo que el ejecutor Zygand podría estar muy interesado.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][24994] = {title = "Apocalíseas", objective = "Recoge 10 apocalíseas.", description = "Mi enviado acaba de entregarme un celemín de hierba luminiscente. ¡Hierba luminiscente! ¡No necesito hierba luminiscente, sino apocalíseas! Ya ves el aprieto en el que me encuentro, <nombre>.\n\nTe recompensaré generosamente si reúnes lo que necesito. Tráeme suficientes apocalíseas y premiaré tu esfuerzo.\n\nTengo entendido que les gusta infectar la flora cerca de la fosa común, al norte del cementerio de Rémol.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24995] = {title = "Escamas fuera", objective = "Consigue 5 escamas de Anca Vil.", description = "Mientras recogías muestras para mí, mis experimentos me han llevado a descubrir que necesitaré más agentes para propagar adecuadamente esta nueva enfermedad. Envenenar a un pobre desventurado es un juego de niños. Propagar una plaga a todo un mundo resulta algo más complejo.\n\nVoy a necesitar varias escamas de múrlocs de los alrededores. Encontrarás a las criaturas deambulando como descerebrados en la costa del norte.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Guantes de calderaCinturón Anca VilRecibirás:\n\nArena de sueñoCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24996] = {title = "El experimento de Holland", objective = "Lleva la bebida especial de Holland al montaraz capturado.", description = "Por lo visto acaban de capturar a otro de esos insensatos enanos montaraces. La Guardia de la Muerte lo tienen encerrado aquí, en este edificio, y lo han puesto bajo la vigilancia de uno de los suyos para que lo disuada de escapar.\n\n¿Por qué no vas a comprobar si al montaraz capturado le gusta la bebida especial que he preparado para él? Contiene una pequeña muestra de lo que la Dama Oscura tiene reservado para todo Azeroth.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Cinturón de montarazGuanteletes de La HorcaRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24997] = {title = "Profanadores", objective = "Mata profanadores y bastardos Putrepellejo y consigue 6 frascos de icor embalsamante.", description = "Las fosas comunes que hay en el bosque, al oeste de aquí, se hicieron para albergar la... impresionante... cantidad de cadáveres de aquellos que perecieron en Tirisfal cuando la Peste golpeó por primera vez.\n\nDe estas tumbas no había salido ni un solo no-muerto hasta el momento, pero ahora la Plaga envía a gnolls Putrepellejo a recoger cadáveres para que engrosen las filas de sus ejércitos. ¡Esto es inaceptable!\n\nTienes una doble tarea que cumplir: mata a los Putrepellejo de las fosas comunes y la Granja de Garren, y quítales el icor embalsamante que les da vida.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Botas de piel de zombiGuanteletes de acero fríoRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24998] = {title = "Ojo de cresa", objective = "Mata a Ojo de cresa y consigue su zarpa.", description = "Ojo de cresa es una bestia repugnante, incluso para ser un gnoll. Lidera un grupo de gnolls renegados que está arrasando los claros y robando todos los cadáveres que puedan encontrarse en su camino.\n\n¡Esos cadáveres son nuestros! ¡Teníamos planes para ellos!\n\nOjo de cresa habita en el camino de arriba. No muestres clemencia. La clemencia es para los débiles.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Cinturón del gnoll hediondoCinturón de RémolLeotardos de GarrenRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][24999] = {title = "La semilla del miedo", objective = "Persigue a 12 renacuajos Anca Vil hasta que se desmayen de miedo.", description = "Al parecer, Jarrod te envió a matar a los múrlocs del norte. Eso está bien... podemos usarlos para nuestras pociones. Pero, a veces, me preocupo...\n\nLas zonas de cría de los Anca Vil se encuentran cerca de la costa norte de Tirisfal, por lo que, probablemente, te habrás topado con algún renacuajo entre los adultos de la orilla. Si estos jóvenes múrlocs buscaran venganza... podrían fastidiarnos. Persíguelos y demuéstrales que no se juega con los Renegados y con la Horda.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25000] = {title = "El pueblo de Teegan", objective = "Mata a corredores y segadores Dienterror y reúne 8 pellejos de Dienterror.", description = "¡Oye, <clase>!\n\n¿Te diriges a apoyar al cabo Teegan? Él se encarga de mantener abiertas las vías de suministro.\n\nHay dos enanos de los más intratables que he conocido que se encargan de artículos diversos. Si quieres causarles buena impresión a esos dos cazadores malhumorados, vas a tener que demostrar que eres capaz de enfrentarte a los depredadores de la zona.\n\nLos raptores que se encuentran al oeste del bastión son especialmente feroces. Lleva a Goucho algunos pellejos de Dienterror frescos y matarás dos pájaros de un tiro impresionando a los enanos y proporcionando suministros a las tropas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25001] = {title = "Rascadunas", objective = "Mata a Rascadunas.", description = "Mis otros ayudantes se están asegurando de que nuestros orgullosos nuevos camaradas sean colocados en cómodas jaulas y enviados donde más se los necesita. Por la Horda. Mientras tanto, nos queda una última tarea en la agenda.\n\nRascadunas, el jefe del clan Machacaduna, probablemente sea tan zoquete que ni se haya percatado de lo que estamos haciendo aquí. Pero odio a muerte los asuntos inacabados, <tío/nena>. Está merodeando en el cubil de ahí al lado, hacia el oeste. Ve para allá, sácalo de allí y habremos terminado con todo esto, ¿de acuerdo?", progress = nil, completion = "¡Finiquitado! Aquí ya no queda nada para nosotros que no sea arena. Buen trabajo, tío.\n\nBueno, tal vez no debería ir tan rápido. ¿Encontraste algo en el cubil de ese ogro?", rewards = "Golpe de nudillosBrazales rascadunasRematanegociosPodrás elegir una de estas recompensas:\n\nBroche Pantoque\n\nTambién recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25002] = {title = "Hurgando", objective = "Consigue 10 cajones de suministros de Fuerte del Norte en la guarida de los raptores.", description = "<En el cuerpo, encuentras una declaración de cargamento que detalla una larga lista de artículos urgentemente necesarios en el frente.>\n\n<Un rastro de sangre en el camino indica que los cuerpos fueron arrastrados hacia el sur, en dirección a la guarida de los raptores.>\n\nPuede que los raptores también hayan arrastrado los suministros. Si se recuperan esos suministros para el cabo Teegan, ¡se podría arreglar este desastre!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25003] = {title = "La Cripta de la Familia", objective = "Mata a 5 ancestros gemebundos y a 5 ancestros en podredumbre.", description = "El punto fuerte de los molinos es la Cripta de la Familia Agamand. Con nigromancia, el capitán Dargol ha invocado a los ancestros de los Agamand y planea lanzar un ataque contra nosotros.\n\nNo puede ocurrir, debemos detenerlo. Viaja hasta la Cripta de la Familia Agamand y derrota a los ancestros invocados.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Leotardos de la familia de AgamandPulsera de la familia de AgamandBotas de montar de la familia de AgamandRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25004] = {title = "La invasión de los molinos", objective = "Reúne 5 costillas con cortes y 3 calaveras ennegrecidas.", description = "La Plaga está intentando montar una base en los Molinos de Agamand. Si lo consiguen, podrían organizar más ataques desde Tirisfal.\n\nYa se ha dado la orden. La Plaga de los Molinos debe ser destruida.\n\nReúne algunas costillas con cortes de soldados testapartida y armadóseos, y calaveras ennegrecidas de tirahuesos Ojosombra.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25005] = {title = "Habla con Sevren", objective = "Habla con el magistrado Sevren en Rémol en Claros de Tirisfal.", description = "He destruido los restos que me has traído, <nombre>. Eso es... todos menos estos.\n\nDevlin Agamand fue débil y mordaz en vida, y fue de los primeros en sucumbir a la peste. Sirvió como esclavo a la Plaga durante mucho tiempo, más que la mayoría. Como tal, posee información que nos resultaría muy útil.\n\nLleva los restos al magistrado Sevren e infórmale de lo que te he contado. Él sabrá lo que hay que hacer.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25006] = {title = "El yugo debilitado", objective = "Habla con la sacerdotisa de las Sombras Malia en Rémol y participa en la extracción de Devil Agamand.", description = "Mientras que el Trono Helado yace latente, el yugo que el Rey Exánime ejercía sobre la Plaga se debilita más que nunca. Su control sobre el alfeñique de Devlin Agamand no es muy poderoso, así que podríamos acabar con él.\n\nHabla con la sacerdotisa de las Sombras Malia en la mansión situada en la zona este de la ciudad. Ella te ayudará con el procedimiento.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Camisa de DevlinBotas de RémolRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25007] = {title = "Este... siempre al este", objective = "Preséntate ante el sumo ejecutor Derrington en El Baluarte en Claros de Tirisfal.", description = "Nos has servido de gran ayuda, <nombre>, pero <los/las> <hombres/mujeres> de tu calibre, se necesitan por doquier.\n\nAl este se encuentra El Baluarte, una barricada fortificada contra los estragos de las Tierras de la Peste. El Baluarte nos protege de las invasiones de la Plaga, y, gracias a su inviolabilidad, hemos podido acrecentar nuestras fuerzas en Claros de Tirisfal.\n\nHabla con el sumo ejecutor Derrington. Es nuestro aliado y apreciará cualquier ayuda que puedas prestarle.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25008] = {title = "Animales mugrientos", objective = "Mata a 6 carroñeros Dentecenado.", description = "Probablemente hayas visto a algunos carroñeros Dentecenado al venir. ¡Huelen peor que el viejo Pete! ¡Despreciables animaluchos! Nos roban las víctimas, hurgan en nuestros suministros y lo peor... no sirven para comérselos.\n\nMata a algunos.\n\nLuego mata a más, si quieres.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Cinturón de pellejo de dentecenadoPodrás elegir una de estas recompensas:\n\nAnillo de carroñero\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][25009] = {title = "En guerra con la Cruzada Escarlata", objective = "Mata a 3 zelotes Escarlata y a 4 frailes Escarlata.", description = "Todavía estamos en guerra a pesar de que las fuerzas de la Cruzada Escarlata menguan. El informe que me envió el ejecutor Arren afirma que los cruzados Escarlata han ido asaltando zonas desde la torre en ruinas al sureste de Tirisfal, cerca de la Hacienda Balnir, bajo las órdenes del capitán Vachon.\n\nMata a 3 de sus zelotes y a 4 de sus frailes. ¡Debería ser un duro golpe para la Cruzada!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25010] = {title = "Un nuevo aliado mortal", objective = "Busca a tu nueva aliada en el Campamento Escarlata en Claros de Tirisfal.", description = "Poco después de que llegaras a El Baluarte, se me acercó la joven no-muerta más extraña que he conocido. Juró su enemistad contra la Cruzada Escarlata, así que la envié a luchar contra nuestros enemigos del norte. ¿Dices que has visto antes a algunos cruzados muertos? Probablemente representen el fruto de su trabajo.\n\nVe a buscarla y pregúntale si necesita ayuda en su venganza contra la Cruzada... aunque no me sorprendería que ya los hubiera matado a todos.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25011] = {title = "Mejor y más grande", objective = "Habla con Timothy Cunningham en El Baluarte, en Claros de Tirisfal.", description = "No hay mucha más gloria en El Baluarte, <nombre>. Ya has hecho bastante. Sin embargo, puede que te aguarden más aventuras en el Bosque de Argénteos.\n\nHabla con Timothy Cunningham, mi hombre murciélago. Te llevará gratis hasta Rémol.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25012] = {title = "Hasta el infinito y más allá", objective = "Habla con el ejecutor Zygand en Rémol, en Claros de Tirisfal.", description = "Si tienes que regresar a Rémol, estaría bien que le hicieras una visita al ejecutor Zygand de camino. Dicen que hay movimiento en el Bosque de Argénteos, en el sur. Él sabrá más que yo.\n\nHabla conmigo cuando estés <listo/lista> para partir.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25013] = {title = "Un brebaje con cuerpo", objective = "Consigue 4 muestras de veneno de araña nocturácnida sañosa.", description = "<Dithers prueba su último brebaje.>\n\nMmm... le falta algo que le de más cuerpo. ¡Ya sé! Las arañas del norte segregan un potente veneno que servirá. ¿Puedes extraerles un poco, <nombre>?Recibirás:\n\n", progress = nil, completion = nil, rewards = "Ballesta Nocturácnida avanzadaGuantes de nocturácnidaRodela de segadorRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25014] = {title = "El tesoro de Rascadunas", objective = "Habla con Megs Trituramatic.", description = "En el interior de este cofre de piedra erosionado, escondido al fondo del cubil de Rascadunas, encuentras un artefacto de lo más curioso.\n\nTiene forma de escarabajo, su superficie es suave, de un tono azul brillante revestido de oro. Podría ser mecánico, pero no se parece a nada fabricado por manos mortales, además parece muy antiguo.\n\nSeguramente Megs esté interesada en ello.", progress = "¿Has encontrado algo?", completion = "¿Encontraste eso en el cubil de un ogro? Eso es...\n\n...nada del otro mundo, ¡seguro! No me cabe duda de que no es más que... una baratija perfectamente inofensiva... sobre la que te voy a dar instrucciones precisas y detalladas de cómo manipularla.\n\n&lt;Megs baja la voz y susurra.&gt;\n\nBaja la voz y no vayas enseñando eso por ahí.", rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][25015] = {title = "Que chillen", objective = "Mata cualquier combinación de 8 celadores de espadas Erizapúas o tejespinas descarriados y recoge una zarzarita de los tejespinas.", description = "Una de las especies locales de Kalimdor es el jabaespín. Pequeños bichos punzantes. Razón suficiente para odiar este continente.\n\nLos asaltos comenzaron poco después de establecer nuestros primeros campamentos. Peor aún, esos desalmados con pinchos se multiplican en esta endemoniada jungla espinosa. Necesito que me ayudes a hacerles retroceder para que podamos volver a comunicarnos con el Mando de Guardia.\n\nMientras permaneces ahí fuera, consigue una de esas ramas torcidas que parecen utilizar los taumaturgos para manipular el crecimiento de la jungla...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25017] = {title = "Obstáculos antiguos", objective = "Acaba con 6 gólems de arenisca.", description = "Durante años, este valle ha estado sellado tras unas puertas impenetrables. Ahora que el Cataclismo las ha derribado, nos corresponde a nosotros descubrir los secretos que el valle encierra.\n\nSin embargo hay algunos obstáculos. Las creaciones de antaño de los titanes que descansaban al otro lado de las puertas han despertado. Vagan sin rumbo por la arena, atacando a cualquiera que se acerque.\n\nAlguien debe acabar con los gólems que patrullan el valle. ¿Te ofreces?", progress = nil, completion = "Gracias, &lt;clase&gt;. Sin ti no daríamos abasto para enfrentarnos al enemigo.", rewards = "Cinturón de vigilante de la puertaSobrehombreras de examinadorBufas de areniscaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25018] = {title = "Andoren lo sabrá", objective = "Entrégale el artefacto a Andoren Alzalba en el Valle de los Vigías.", description = "Escucha, <nombre>. No sé cómo lograron hacerse con él esos ogros, pero esa cosa es un artefacto de los titanes. No soy un experto, pero tan solo ese hecho suponga que es bastante más antiguo que la arena sobre la que estamos.\n\nTambién sé que este tipo de cosas no dan más que problemas. No quiero tener nada que ver con ello. Llévalo al sur, al Valle de los Vigías y dáselo a un elfo de sangre llamado Andoren Alzalba. Y no hagas preguntas, cariño, por favor.", progress = nil, completion = "Por todos los... ¿Encontraste esto en un cubil de ogros? Impensable. Me asombra que no trataran de hacerlo añicos.\n\nCon un poco de suerte, &lt;clase&gt;, podremos conseguir incluso más antigüedades fascinantes... Si es que quieres ayudar.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25019] = {title = "Reivindicar la posesión", objective = "Mata a 10 enanos arqueólogos.", description = "No somos los únicos que hemos descubierto el valor de las Ruinas de Lunasur. Los enanos de la Liga de Expedicionarios han llegado en masa y se han llevado todo tipo de artefactos e inscripciones para la Alianza.\n\nNo creo que haga falta que te explique mucho más. No permitiremos que los descubrimientos encontrados aquí caigan en manos de la Alianza. Asesina a tantos enanos como puedas, ¡y échalos de las ruinas!", progress = nil, completion = "Excelente. Cuantas menos interferencias por parte de la Alianza, mejor.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25020] = {title = "Fragmentos de lenguaje", objective = "Reúne 5 jeroglíficos antiguos.", description = "En las Ruinas de Lunasur, justo al este de aquí, hemos hecho algunos hallazgos. Mis colegas han encontrado fragmentos de piedras tallados con escrituras antiguas, que han salido a la luz recientemente por los movimientos de arena.\n\nLos escritos no son de una lengua conocida, pero tienen cierto parecido a las marcas que hemos visto en las ruinas de los titanes. Si los desciframos podremos descubrir muchos más secretos.\n\nPor desgracia, mis colegas están ocupados defendiendo las tablillas contra de la Alianza. Necesito que vayas a las Ruinas de Lunasur para recuperar las tablillas.", progress = "¿Tienes las tablillas?", completion = "Gracias, &lt;nombre&gt;. Una vez resuelto esto, podremos concentrarnos en explorar la puerta.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25021] = {title = "Sangre a borbotones", objective = "Reúne 6 puñados de sangre de los trols Furiarena.", description = "Pa' sobreviví en el árido desierto, los Furiarena tuvieron que aprender todo' lo' secretos de la magia de sangre. Si bebes la sangre, tendrás el podé... vudú o'curo ¿sí? Pero no habrá posibilidá d' echarse atrás.\n\nSi queremos encontrá la espada, necesitamos sangre. Po' sue'te pa' ti, Mazoga es un traidor, ¿sí? Y hay muchos trols Furiarena vagando po' esas colinas.\n\nVe a conseguí la sangre de Mazoga... mucha sangre... y haremos el ritual pa' encontrá a Jang'thraze.", progress = "¿No te la habrás bebío tú, eh? Toda, toda, la necesito toda...", completion = "&lt;Mazoga reúne toda la sangre en sus manos y se la lleva a la boca. Se licúa y, espesa, recorre el interior de su garganta hacia abajo.&gt;\n\nBeben la sangre, tienen el podé. Yo me bebo su sangre...\n\n&lt;Mazoga te dedica una amplia y sangrienta sonrisa.&gt;", rewards = "Te van a lanzar el siguiente hechizo:\n\nTragar sangre\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25022] = {title = "Error de comunicación", objective = "Rescata al embajador Gaines de los jabaespines en La Hojarasca.", description = "Le dije que era un ingenuo, pero el embajador Gaines insistió en negociar una alianza con los jabaespines contra la Horda. Aunque tuviera éxito, no me agradaría luchar junto a esos... hombres cerdo.\n\nBueno, Gaines no ha regresado y el general Hawthorne me hará responsable si pierdo a uno de nuestros mejores negociadores por estos salvajes chillones.\n\nLocaliza al embajador en este caos de jungla y rescátalo si aún permanece con vida.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25023] = {title = "Viejos amigos", objective = "Habla con Thrall en la Atalaya del Jefe de Guerra, en Las Islas Perdidas.", description = "De acuerdo, sujétate a la escalera. ¡Tenemos que salir de aquí!\n\nSobrevolaremos la ciudad y, después, ¡te llevaré junto a unos viejos amigos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25024] = {title = "Repeler a los paracaidistas", objective = "Mata a 10 paracaidistas de la Alianza.", description = "La Alianza ha regresado en el peor momento, <amigo mío/amiga mía>. Nos ocupamos de sus barcos, pero aún tienen aviones que arrojan a su preciada unidad 127 de paracaidistas a la costa.\n\nPoco pueden hacer los juraluchas y los exploradores para contener las dos rampas contra el incontenible número de enemigos. Estoy seguro de que si les ayudas, cambiarán las tornas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25025] = {title = "Sang'thraze la Deflectora", objective = "Derrota a Zakkaru y recoge la Sang'Thraze lacrada.", description = "La sangre habla. Puedo sentir cómo fluye por la arena... impregnada de muerte, un desierto de sufrimiento...\n\n<Mazoga gira los ojos hacia atrás.>\n\n¡Ahí está! La sangre fluye hacia el sur, en el Valle de los Huesos. ¡Zakkaru! Zakkaru, Aparición de Makkari, el oscuro que exige un sacrificio... su padre expulsado de Zul'Farrak, su ascensión interrumpida... probará la sangre una vez más...\n\n<Mazoga se tambalea.>\n\nVete, <clase>. Zakkaru tiene Sang'thraze. Y confía en mí, desearás que no sea así por mucho tiempo.", progress = "¿Los e'píritus decían la verdá, colega? ¿La tienes?", completion = "&lt;Mazoga sonríe mientras te coge la espada con ambas manos.&gt;\n\nNo le guh'tah'te demasiado, ¿eh? No solo loh trols quieren sangre, colega.\n\nVamos a buscá la otra eh'pada...", rewards = "Maza del Valle de los HuesosTúnica HablasangreEspaldares DeseasangreRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25026] = {title = "Mojo más oscuro", objective = "Reúne 6 muestras de mojo más oscuro de los zombis Furiarena.", description = "Jang'thraze m'evita, colega... la sangre no es suficiente. Necesitamo'h algo má'h fue'te p'a encontra'la.\n\nCuando necesitas a todos los trols que tienes p'a ayudá a consegui'lo, y se te muere uno, es un gran p'oblema, colega, y p'o eso los Furiarena aprenden a levantá a nue'tros muertos con vudú. Si caes, te vuelve'h a levantá y continúas trabajando... ¡P'a siempre!\n\nLos zombis que hacemos están imbuidos de mojo más oscuro. Ve al oeste y encuentra un montón d'ellos. Consígueme ese mojo, ¿sí?", progress = "¿Tienes el material, colega?", completion = "&lt;Mazoga inclina la cabeza hacia atrás e inhala los montones de material misterioso. Se le iluminan los ojos.&gt;\n\nEsto es poderoso, colega... Ay, si tú pudieras vé lo que yo veo ahora... Tal vez tú lo pruebes algún día.\n\nL'o e'píritus llaman...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25027] = {title = "Cuestión de hojas", objective = "Usa la zarzarita en Tresdientes y mata a dos viejas brujas descarriadas en La Hojarasca.", description = "Según Gaines, los jabaespines llaman a su matriarca \"Tresdientes\". Ha estado enroscando esta jungla enloquecida para sus propios fines y ordenó que Gaines \"fuera desgarrado y echado a la hojarasca\". Qué mujer tan agradable.\n\nDémosle un poco de su propia medicina. Ten la zarzarita que recuperaste y úsala en Tresdientes para eliminarla del mapa. Después, mata a las viejas brujas que ha estado entrenando para asegurarnos de que nadie pueda ocupar su puesto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de bruja jabaespínBrazales de TresdientesRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25028] = {title = "Problemas térreos", objective = "Reúne 10 capullos poco corrientes de flores en ciernes en La Hojarasca.", description = "Teegan es muy ingenuo al pensar que los jabaespines causaron este supercrecimiento repentino. Observa a tu alrededor. He estado contemplando la floración de estas plantas y los nuevos brotes muestran más mutaciones que las últimas. Esto no es magia tribal sino algo primigenio. Y peligroso.\n\nAntes de ayer, un gran druida pasó por nuestro campamento. Busca a Naralex en algún lugar de esta jungla. Él sabrá qué hacer.\n\nY llévale algunas muestras de plantas de alrededor de La Hojarasca para sus estudios.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25029] = {title = "Muertes en la familia", objective = "Consigue los restos de Gregor, los restos de Nissa, los restos de Thurman y los restos de Devlin.", description = "Los Agamand eran la familia más próspera de los Claros de Tirisfal. Yo solía trabajar en sus molinos... antes de la Peste.\n\nCuando la Plaga apareció por primera vez, los Agamand fortificaron su casa y convencieron a todos sus empleados para que se quedaran y les ayudaran a defenderse. Fuimos unos insensatos pero, al menos, fuimos unos insensatos leales.\n\nLos Agamand, a causa de su orgullo, nos abocaron a todos a la desgracia. ¡Y ahora son esbirros de la Plaga!\n\nSirve a los Renegados y derrota a los Agamand, que sucumbieron a la peste. Sírveme a mí y tráeme sus restos.Recibirás:\n\n", progress = nil, completion = nil, rewards = "PartehuesosBastón LeñoscuroRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25030] = {title = "Los molinos fantasma", objective = "Lleva la calavera de Dargol a Coleman Farthing a los Molinos de Agamand.", description = "Has sentido una presencia maligna emanar de la calavera de la bestia. Seguro que a Coleman Farthing le interesaría ver esto.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25031] = {title = "En dirección a los molinos", objective = "Preséntate ante Coleman Farthing en los Molinos de Agramand en Claros de Tirisfal.", description = "Los Molinos de Agamand del oeste han sucumbido a la Plaga. La familia Agamand ha sido asesinada y la Plaga ha reclamado su residencia.\n\nProbablemente, este represente su mayor avance en Tirisfal, <nombre>. Si crees que eres <un/una> gran <clase>, dirígete allí y habla con Coleman Farthing. Se ha estado esforzando en recuperar las tierras, así que necesitará ayuda. Sigue este camino, te conducirá directamente a él.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25032] = {title = "Secretos en el oasis", objective = "Busca Jang'thraze la Protectora.", description = "Sí, ahora yo veo la otra mitad, colega... al sur...\n\nE'tamos cerca, colega. Está en un oasis, enterrado en la mugre, bajo l'agua. ¡No te retra'se!", progress = nil, completion = "¿Mazoga? ¿Ha cogido la espada? Ese asqueroso...\n\n&lt;Trenton frunce el ceño por un momento.&gt;\n\nAl menos escapaste con vida. La mordedura de azotador es muy peligrosa.", rewards = "Manta de oasisManipuladores de media verdadAlmófar desechado de MazogaEspaldares MazaligeraRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25034] = {title = "¡Al frente!", objective = "Localiza al embajador Gaines en el Mando de Vanguardia en Los Baldíos del Sur.", description = "Me encantaría contar contigo entre mis filas pero parece que se te ha asignado la primera línea. ¿Te acuerdas del embajador Gaines? Se ha trasladado al Mando de Vanguardia y en su última misiva solicitaba tu ayuda en persona.\n\nEncontrarás nuestra operación del Mando de Vanguardia al sur, en lo que se conoce como \"Campos de Sangre\".\n\nVe con cuidado, <nombre>. La Horda ha estado tendiendo emboscadas a algunos de nuestros oficiales por el camino.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25036] = {title = "La preocupación de Teegan", objective = "Preséntate ante el cabo Teegan en la Expedición de Teegan en Los Baldíos del Sur.", description = "Al almirante le complacerá que Fuerte del Norte esté asegurado pero si queremos controlar el continente, necesitaremos mantener las vías de suministro con el interior.\n\nJusto antes del asalto, recibí el más enigmático de los informes del cabo Teegan, que se encarga de mantener el contacto con el Mando de Vanguardia. Dice que tiene problemas con la \"jungla\". ¡Pero no hay jungla en Los Baldíos!\n\nSigue el camino hacia el norte fuera de Fuerte del Norte y descubre si puedes ofrecer ayuda a nuestro rebelde cabo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25037] = {title = "Pescar cangrejos", objective = "Mata reptadores de espuma pigmeos y recoge 5 trozos de carne de reptador fresca.", description = "Quizás al envejecer todos eh'tos años me haya vuelto cada vez más quisquilloso, pero la carne de jabalí ya no me sienta n'a bien. Así toca a más a esos nuevos reclutas.\n\nHemos pueh'to algunas trampas para cangrejos, pero si tuvieras la amabilidad de ayudar a un anciano trol impaciente, me encantaría comer ahora algo de carne freh'ca de reptador. Se encuentran por toda la ih'la, pero el mejor sitio para cazarlos es en la costa este.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25038] = {title = "La tarea de Gordo", objective = "Recoge 3 hierbas luminiscentes y entrégaselas al boticario auxiliar Holland en Rémol.", description = "Maestro querer hierbas. Nosotros manos grandes y no poder recoger. Si tú ayudas nosotros no hacer daño. Nosotros necesitar hierba luminiscente. Haber muchas por aquí y cerca de camino.\n\nCuando tú tener hierba luminiscente, llevar a maestro Holland a Rémol.\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25041] = {title = "Orgullo de león", objective = "Mata cualquier combinación de 5 merodeadores y melenaorgullos de las llanuras.", description = "¡Respeta al león, <nombre>! Es un asesino feroz. Debes admirar la elegancia de la bestia... Su músculo y sus garras... a la caza de su comida... tan fundamental...\n\nPerdona, estaba divagando. Como te decía, respeto a esos leones, pero son destructivos para nuestras patrullas. De verdad te lo digo. Mis hombres tienen miedo de ir solos al baño de noche. ¿Podrías ayudarnos a convertir nuestro campamento en un lugar un poco más seguro?\n\nA los leones de Los Baldíos les gusta estar debajo de los árboles.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25042] = {title = "Marchar con el estómago", objective = "Reúne 4 filetes de morrotormenta frescos que conseguirás matando a morrotormentas en Los Baldíos del Sur.", description = "Es cierto lo que dicen: un ejército marcha con el estómago. Y llevamos recorrido un trecho muy largo.\n\nEstoy pensando que si preparamos a la plancha unos pocos de esos Morrotormentas enormes y torpes, tendremos suficiente carne como para alimentarnos durante semanas.\n\nLos morrotormenta son grandes y lentos, así que debería resultarte fácil matarlos. Excepto si... Oye, no llevarás armas contigo, ¿verdad?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Losa de peltreCucharón de sopaBotas de pellejo de morrotormentaGuantes de TrawleyRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25043] = {title = "Campos de Sangre", objective = "Mata a 10 brutos de la Desolación en los Campos de Sangre en Los Baldíos del Sur.", description = "La Horda ha acabado bautizando a esta región \"Campos de Sangre\". Es un nombre adecuado: esos juncos se tiñen de rojo con la sangre de algunos de mis mejores hombres.\n\nHe enviado patrullas de reconocimiento para que aplasten a los jabaespines e informen sobre los avances de las tropas de la Horda, pero no todos ellos vuelven. No les vendría mal tu ayuda.\n\nPatrulla los campos y busca a los brutos de la Desolación que tanto mal nos están causando. No esperes que se rindan, su Jefe de Guerra los ha instruido para que luchen hasta la muerte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25044] = {title = "Diplomacia por otros medios", objective = "Lleva el cuerno de desafío al círculo de desafío Erizapúas en Los Baldíos del Sur. Sopla el cuerno para retar a Hozasable y mátalo.", description = "No he olvidado que estuve al borde de la muerte a manos de los jabaespines en aquella selva mugrienta. El General ha ordenado algunos ataques tácticos, pero quiere evitar el genocidio. Yo no tengo esos reparos.\n\nToma este cuerno que \"tomé prestado\" durante mis negociaciones. Sopla el cuerno dentro del círculo de desafío Erizapúas al oeste de nuestra posición, no tiene pérdida. Quiero que retes al campeón de los Erizapúas, Hozasable, a un combate singular. Su muerte delante de sus seguidores provocará el caos absoluto.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Botas de JabapocalipsisCapa de HozasablePodrás elegir una de estas recompensas:\n\nCírculo de desafío Erizapúas\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][25045] = {title = "Una línea en el suelo", objective = "Conquista una colina neutral en los Campos de Sangre y defiéndela del contraataque de la Horda.", description = "Estratégicamente, el control de una región requiere una observación constante. Mira en este mapa: he identificado algunas colinas estratégicas, parecidas a esta, que la Alianza debe conseguir si queremos mantener al enemigo en un puño.\n\nMis exploradores ya han marcado su emplazamiento en el campo. Lo que necesito es a alguien que encabece su conquista, y tú eres la persona ideal para el trabajo.\n\nBusca banderas grises neutras sobre las colinas al norte, al este y al sur de las ruinas de Taurajo. ¡Conquista una y defiéndela!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Escudo de HawthorneTogas del Campo sangrientoLeotardos de TaurajoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25046] = {title = "El abrazo de una hija", objective = "Lleva a Lilian Voss junto a su padre a la torre de la Senda del Cruzado.", description = "La voz susurrante continúa:\n\n<\"Mi nombre es Lilian Voss. Antes de morir, pertenecía a la Cruzada Escarlata. Mi padre, el sumo sacerdote Voss, me convirtió en un arma contra los apestados. Me instruí en sigilo, brujería, artes marciales, cualquier cosa que me hiciera más fuerte. Sacrifiqué mi niñez por él.\">\n\n<\"Después, por caprichos del destino, fallecí y me convertí en... esto. Mi padre se olvidó de mí enseguida y, cuando regresé, ordenó mi ejecución.\">\n\n<\"Ven. Hablaremos con él ahora en su torre del noroeste.\">Recibirás:\n\n", progress = nil, completion = nil, rewards = "Puntilla de DarringtonBastón de LilianCoraza del ejecutorRecibirás:\n\nBolsa de cortacabezasCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25047] = {title = "Figurilla de pantera rota", objective = "Repara la figurilla rota con tu habilidad y los materiales adecuados.", description = "El último propietario de esta figurilla gravemente dañada se deshizo de ella. Sin embargo, con los materiales adecuados y tu habilidad en joyería, se podría restaurar completamente.\nRecibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25048] = {title = "Salvamento costero", objective = "Recoge 7 suministros de Bonvapor.", description = "Si queremos convencer al señor Tragonublo de traer a más gnomos aquí, ¡tenemos que demostrarle lo majos que somos! Sé cómo.\n\nGadgetzan está bloqueado por piratas, pero muchos de los bienes que guardan en los barcos sobreviven después del estallido... se los lleva la marea. La mayoría quedan arrastrados hasta la costa justo al sur de la ciudad.\n\nSi pudieras recogerles sus suministros, ¡nos ayudarías a hacer amigos! Y eso evitaría que la chica goblin de allí siga llevándoselos para venderlos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25049] = {title = "Chapoteando en los charcos", objective = "Mata a 8 zancudos de marea.", description = "¡Tenemos un grave problema! Está muy bien que el océano llegara hasta tan lejos, porque ahora los barcos pueden llegar a Gadgetzan, ¡pero ahora hay un montón de gigantes marinos viejos y nauseabundos invadiendo la ciudad! Estoy segura de que el señor Tragonublo nos agradecería que nos ocupásemos de ellos por él.\n\nNo te preocupes, no te voy a pedir que lo hagas por amor al arte. Encárgate de ellos y te daré una recompensa.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25050] = {title = "Rescate cohete", objective = "Entrega cohetes salvavidas a 5 supervivientes Bonvapor y usa las bombas para matar a 40 bloqueadores de los Mares del Sur.", description = "Cuando el agua llegó hasta aquí, el Puerto Bonvapor al este quedó anegado, ¡y muchos pobres goblins siguen atrapados allí! Esos piratas malos disparan a cualquier barco que sale de nuestros muelles.\n\n¡Pero no se esperarán que volemos! Hay un globo aerostático en el muelle. Podemos usarlo, volar con él hasta los goblins para rescatarlos y, ya de paso, ocuparnos de los piratas. ¡El señor Bonvapor estará tan complacido...!\n\nVe a los muelles y métete en el globo, que yo llego enseguida, ¿de acuerdo? Voy a por unos cuantos cohetes...Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Cucharón de sopa de NasmiraYelmo Bonvapor rescatadoPrototipo de cohete salvavidas fallidoPodrás elegir una de estas recompensas:\n\nBomba falsa\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][25051] = {title = "Exterminio Niebla Negra", objective = "Destruye 8 huevos Niebla Negra en la Caverna Niebla Negra.", description = "Las arañas que habitan en la Caverna Niebla Negra del noroeste representan otra amenaza incesante. No es que los ogros no se puedan enfrentar a ellas pero, desviar nuestra atención cuando las fuerzas de Theramore se encuentran tan cerca, es un error mortal.\n\nNecesito que alguien destruya los huevos que hay dentro de la Caverna Niebla Negra para evitar que se propaguen. Encontrarás los huevos en la parte más profunda de las minas llenas telarañas... junto con sus guardianes.", progress = nil, completion = "Qué gran alivio, &lt;clase&gt;. Gracias.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25052] = {title = "Cofre de un hombre muerto", objective = "Mata a 15 piratas de los Mares del Sur.", description = "Bueno, como bien puedes ver por aquí hay una batalla importante contra esos piratas. Estamos haciendo todo lo posible para que no vuelvan a entrometerse en Gadgetzan o en nuestros hogares gnómicos ¡nunca más!\n\n...Matándolos.\n\n¿Qué tal si nos ayudas? Queremos estar bien seguros de que asesinamos a algo más que a ese narices verdes de ahí y a sus matones horribles. ¡Te lo agradecería mucho!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Caperuza de los Mares del SurLeotardos de sorpresaGuantes para rascarse la narizEspaldares limpiadosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25053] = {title = "¡Hasta los cimientos!", objective = "Utiliza el ron ardiente para prender fuego a la cabaña noroeste, la cabaña noreste y a la cabaña suroeste.", description = "Ya sabes, este sitio podría ser un hogar perfecto para nosotros los gnomos ¡de no ser porque está viejo y sucio y lleno de piratas! Nos estamos ocupando del problema de los piratas, pero el problema de la suciedad y el desgaste necesita arreglo.\n\n¡Ningún gnomo que se precie viviría en una casucha tan fea como estos edificios! Así que toma, ¡coge esta botella de ron ardiente y quema esas casuchas feas! ¡Hazlo por nosotros!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][25054] = {title = "Qué botín, qué botín", objective = "Reúne 10 piezas de botín de pirata.", description = "Es un verdadero desperdicio que todos esos piratas tengan tesoros esparcidos por ahí. ¡A algunas de esas cosas se les podría dar un uso práctico! Como fundirlas para hacer cables o matrices de revestimiento intrínseco, o para vendérselas a otras razas estúpidas que compran oro solo para llevarlo encima.\n\nHablando de otras razas estúpidas, te apuesto a que esos codiciosos goblins se lo van a llevar todo. ¡No podemos dejar que eso ocurra! ¡Ve a recoger ese tesoro para Gnomeregan!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25056] = {title = "Pellejos apestados", objective = "Consigue 5 pellejos de oso apestado.", description = "¿Has visto los osos apestados que deambulan al oeste de aquí? Esos pellejos... tan espantosos, tan enfermos, tan... ¡perfectos!\n\nConsígueme 5, ¡tengo una idea para desarrollar un veneno antiplaga que seguro que funciona!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25057] = {title = "Ajústales los hierros", objective = "Habla con los despojadores de Taurajo en las ruinas de Taurajo y ponlos bajo arresto. Utiliza las esposas de Fuerte del Norte para subyugar a 5 despojadores heridos.", description = "Nuestra política de reclutamiento de criminales no violentos de las Mazmorras de Ventormenta ha vuelto a atormentarnos, <nombre>. Algunos de mis soldados con menos escrúpulos rompieron filas después de nuestra victoria en Taurajo y están saqueando lo que queda de la ciudad.\n\nEsto es un incumplimiento de la disciplina. Y lo que es peor, la profanación de sus hogares solo espolea al enemigo para que luche con más fiereza, cuando nuestro principal objetivo debería ser la paz.\n\nCoge estas esposas de Fuerte del Norte y lleva a los despojadores de Taurajo ante la justicia. Habla primero con ellos, pero puede que necesites la fuerza para subyugarlos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25058] = {title = "Deshacerse de las minas a lo goblin", objective = "Detona 10 minas terrestres.", description = "¡Los paracaidistas han minado la playa!\n\nEl Jefe de Guerra me preguntó si podíamos hacer algo al respecto, y le dije: \"¡por supuesto que sí!\". Pensé que podrías coger esta cartera de granadas y detonar las minas terrestres a una distancia prudencial.\n\nAsí es como se hacen las cosas, ¿no?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25059] = {title = "La información de Taurajo", objective = "Busca por las ruinas de Taurajo 3 muestras de información de Taurajo.", description = "El General está muy preocupado por los despojadores de Taurajo. ¡Qué pérdida de tiempo! Deberíamos estar centrándonos en nuestro siguiente ataque contra la Horda.\n\nHay información de mucho valor que podría perderse si permitimos que las ruinas de Taurajo continúen quemándose. Mientras estés cumpliendo con las órdenes del General, mira en busca de cualquier mapa o nota que puedas encontrar. Hablo un poco de orco, así que podré entender lo que encuentres.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25060] = {title = "Define \"Loco\"", objective = "Mata a 10 supervivientes enloquecidos.", description = "Nos han llegado informes sobre un naufragio goblin en esta playa hace algún tiempo y los supervivientes quedaron a su suerte. Esperábamos que hubiera un mínimo de supervivientes, incluso quizás algunos a los que se pudiera interrogar.\n\nLo que encontramos fue una tripulación de goblins Pantoque, todos completamente majaras, delirando y maníacamente violentos... hasta un punto nunca antes visto.\n\nEn resumen, son inútiles y peligrosos. Gnomeregan recibirá un mejor servicio si matamos a todos los que podamos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25061] = {title = "El confín de la tierra", objective = "Habla con Kelsey Chispacero en la Estación Chispacero.", description = "¡Pss, oye! Acércate más, <tonto/tonta>, ¿esperas que te lea la mente o...? Bueno, ¡acércate!\n\n¡Has hecho un gran trabajo poniendo en orden los asuntos pendientes de Gnomeregan, <amigo/amiga>! Además de un trabajo increíble pretendiendo estar aquí solo por la guita, absolutamente espléndido. Pero ahora Kelsey Chispacero podría hacer uso de tu sincera ayuda.\n\nSe ha vuelto a mudar... Me ha pedido que te dijera que la busques al sur en la Playa Finisterrae. ¡Yo no le haría esperar!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25062] = {title = "A lo que vinimos", objective = "Busca pistas por los baúles de Pantoque.", description = "En Gnomeregan se habían enterado de que los goblins Bonvapor de la Horda sobrevivieron a un accidente en una isla desconocida cerca de Kalimdor antes de llegar a Durotar. Al principio vinimos a investigar qué técnicas y tecnología podrían permitir a un rebaño desesperado de imbéciles sobrevivir a tan duras condiciones.\n\nMientras los goblins estén confundidos, tenemos que averiguar qué ocurrió aquí. Busca restos y pertenencias por la playa y tráeme cualquier cosa que creas significativa.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25063] = {title = "Tortugador", objective = "Consigue una llave digerida por tortuga de un planoleador.", description = "No cabe duda de que debemos conseguir el objeto que describe este diario. Sacarlo de un cofre sería factible, pero parece que el propio objeto está dañado e inestable. Tratar de forzar el baúl conllevaría consecuencias desastrosas.\n\nPor suerte, sabemos dónde está la llave... estadísticamente hablando al menos. Hay una buena cantidad de tortugas marinas al extremo este de esta playa. Alguna de ellas podría tener la llave.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25064] = {title = "Moraya", objective = "Habla con Moraya.", description = "Moraya ha estado buscando ayuda con los raptores. Deberías hablar con ella al otro lado del Bastión Lanza Negra cuando tengas la oportunidad.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25066] = {title = "El orgullo de Kezan", objective = "Abate 10 cazas sigilosos de Gnomeregan.", description = "¡Es ridículo! ¡Esos gnomos no tienen medida!\n\n¡El orgullo goblin está en juego! ¡<nombre>, deberás subir al Orgullo de Kezan y demostrarles lo que vale un peine!\n\n¡Avísame cuando estés <preparado/preparada>!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de artilleroRestos de paracaídas gnómicoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25067] = {title = "Truenódromo: ¡El Enormus!", objective = "Derrota al Señor Enormus.", description = "Las reglas son sencillas: Dos hombres entran, uno... espera. A veces hay mujeres.\n\nDos personas entran, una... espera, no, a veces son más de dos... y eso significa que salen más de dos...\n\nVale, ¡la única regla es permanecer en el truenódromo! ¡No hay más reglas!\n\nEn primer lugar, te enfrentarás al mayor y más temible miembro de los bandidos Vagayermos. Puede ser un calentamiento o un baño de sangre... ¡De ti depende!", progress = nil, completion = "Un comienzo impresionante. Prepárate para más.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25068] = {title = "Un pasado ruinoso", objective = "Reúne 5 joyas terráneas.", description = "Las criaturas que merodean por estas ruinas son terráneas, los antiguos ancestros de los enanos, creados por los titanes para dar forma al mundo.\n\nLos terráneos originales traicionaron su propia esencia y se desviaron del buen camino hace miles de años, y estos que acaban de aparecer no parecen distintos. Pero podríamos sacar partido a estos ensamblajes desorientados e inestables.\n\nEntra en las ruinas, destruye a los terráneos y recoge las joyas que tienen incrustadas; su energía mágica será valiosa y digna de estudio.", progress = "Manéjalas con cuidado, <nombre>; son tan antiguas como el propio mundo.", completion = "Maravilloso. Y pensar que los creadores de nuestro mundo fabricaron esto...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25069] = {title = "Los secretos de Uldum", objective = "Registra la antecámara de Uldum en busca de un artefacto intacto.", description = "Ha llegado el momento de entrar en la propia antecámara, <nombre>. Este es un momento trascendental.\n\nSegún los escritos que nos trajiste, creo que estas ruinas fueron en otro tiempo la gran entrada al mismísimo Uldum. Los temblores que han abierto sus puertas, probablemente habrán colapsado los túneles, pero aun así, es posible que encontremos cosas sorprendentes ocultas en el interior.\n\nBusca en las ruinas cualquier cosa intacta que merezca la pena estudiarse. ¡La emoción del descubrimiento nos espera!", progress = nil, completion = "Este cofre permanece inalterado, sellado durante miles de años.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25072] = {title = "Algunos goblins buenos", objective = "Salva de los capullos Hazzali a 8 cazabichos goblins capturados.", description = "No estamos acampados aquí solo para cantar cancioncitas con los gnomos y jugar con maquinaria peligrosa, ¿sabes? ¡Mis hombres llevan ya una semana tratando de despejar esta colmena! El problema es que hemos tenido ya tantas pérdidas que los bichos son los que llevan ventaja.\n\nAfortunadamente, o a los bichos no les gusta comer goblins, o les gustamos tanto que nos usan como aperitivo, porque casi todos mis hombres siguen encerrados ahí arriba. Necesito que vayas a rescatarlos.", progress = nil, completion = "Gracias por tu ayuda, eso sí que es impresionante. Cuando empiezas a perder a tus hombres, empiezas a perder mano de obra. Y ánimos. Y armas. Y el polvorín que pediste prestado a aquel tipo...\n\nYa sabes.", rewards = "Cinturón cazabichosBrazales prestadosObsequio de estaño goblinPodrás elegir una de estas recompensas:\n\nPieza de maquinaria peligrosa\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][25074] = {title = "Reúnete conmigo en Triunfo", objective = "Preséntate ante el comandante Roberts en Fuerte Triunfo en Los Baldíos del Sur.", description = "Gracias en parte a tu trabajo, hemos estabilizado la situación aquí. Debemos volver nuestra atención hacia el sur, al Fuerte Triunfo.\n\nEl Fuerte Triunfo es la piedra angular de nuestra operación en Los Baldíos: el puente de unión esencial entre el Fuerte del Norte y Theramore.\n\nRecogeré mis cosas y nos dirigiremos allí por separado. Informa al comandante Roberts en la fortaleza y te veré allí muy pronto. Juntos, ¡tomaremos posesión de la frontera!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25075] = {title = "Por aquí y por allá", objective = "Recoge 8 piezas de chatarra de máquina de asedio de Marca de Guerra en Los Baldíos del Sur.", description = "Estas voluminosas máquinas de asedio enanas no están preparadas para las luchas a corta distancias de Marca de Guerra.\n\nTengo unos nuevos diseños que me gustaría probar, pero necesitaré algunas piezas. Hay mucha chatarra desperdigada por Marca de Guerra. Lo único que me hace falta es <un/una> <clase> <emprendedor/emprendedora> que me la consiga.\n\nY me refiero a ti, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25079] = {title = "Jugando con pólvora", objective = "Acaba con un zapador especialista cerca de Marca de Guerra y consigue un barril de polvo-de-bum.", description = "Nuestros envíos de salitre desde Revolcafango han sido retenidos, lo que significa que no podremos fabricar aquí nuestra propia pólvora.\n\nPero puedo adaptar nuestro armamento para que utilice polvo-de-bum goblin. Es inestable, peligroso, irrita la piel y es dañino si se ingiere... ¡pero podría funcionar!\n\nQuítale un barril a uno de esos zapadores especialistas goblin que han estado volando nuestros muros.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25080] = {title = "Pilas no incluidas", objective = "Consigue una electromolleja zumbante de un tronatesta en Los Baldíos del Sur.", description = "¡De acuerdo! Con las piezas que me trajiste he creado una estructura para mi nuevo vehículo de asalto versátil. Ahora solo me falta un suministro de energía compacto.\n\nMe he dado cuenta de que la fauna local es muy brillante, electroestáticamente hablando. ¿Podrías cazar algunos tronatestas de los alrededores y traerme una electromolleja intacta? Puede que te cueste varios intentos conseguir una glándula en condiciones.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Malla FaraguayPeto de MizzyPistola de PistónmartilloGuantes para niños de TronatestaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25081] = {title = "Reclamar Marca de Guerra", objective = "Ve a Marca de Guerra. Encuentra las banderas y mata a 10 asaltantes de la Desolación.\n\nCapturar las banderas otorgará a los jugadores de la Alianza una ventaja en el combate en la grieta.", description = "La Horda ha estado luchando contra nosotros y nos ha neutralizado desde su bastión al oeste de aquí. La guerra continúa, a pesar de que la tierra se abre bajo nuestros pies.\n\n¡Alguien tiene que poner fin a este enfrentamiento! Necesito que te internes en Marca de Guerra y que ayudes a que mis hombres opongan resistencia allí.\n\nEn el centro de la grieta encontrarás una bandera que marca quién controla la zona. Encuentra las banderas. Será muy útil reclamar la grieta para la Alianza, si nadie lo ha hecho antes.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25082] = {title = "Tapando agujeros", objective = "Utiliza el cubo de brea ardiente sobre los montículos de silítidos del exterior de Fuerte Triunfo para hacer salir y matar a 10 enjambristas silítidos.", description = "En buena hora se le ocurrió al alto mando que un montículo de silítidos era el mejor lugar para construir una fortaleza. Esos insectajos están agujereando nuestras fortificaciones y haciéndonos perder el tiempo. ¡Necesitamos erradicarlos!\n\nToma este cubo de brea ardiente y vuélcalo sobre los montículos de silítidos del exterior de la puerta principal. Parecen grandes montañas de arena. Mata a todo lo que salga, pero ten cuidado, <nombre>; esos bichejos revolotean cuando se prenden sus montículos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25084] = {title = "Amenaza creciente", objective = "Mata a 13 jabaespines Crines de Acero.", description = "Atiende un momento, <clase>.\n\nTenemos más problemas aparte del fin del mundo tal y como lo conocemos. Nuestra vigilia se ve amenazada por los jabaespines. Nos hemos conformado con dejarlos estar mientras permanecieran en el Horado pero, cada día, invaden más nuestro campamento.\n\nMahka, bendito sea su corazón verde, no me perdonaría jamás si anduviera por ahí cercenando cabezas pero te agradecería encarecidamente que nos ayudaras a hacer retroceder a los que merodean cerca del campamento.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25085] = {title = "Quebrantadientes", objective = "Mata a Quebrantadientes.", description = "Una solía pasar algún tiempo en el campamento Taurajo. Me habló de un jabaespín llamado Quebrantadientes que solía permanecer allí cautivo. Era bastante inteligente para ser un jabaespín.\n\nHe intentado pensar qué le ha podido irritar tanto últimamente, y puede que sea porque Quebrantadientes escapó con vida de Taurajo. Si estoy en lo cierto, se habrá convertido en el cabecilla.\n\nExiste una cabaña grande en lo alto de las colinas, al noroeste. Si encuentras a Quebrantadientes, elimínalo.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Diente destrozadoBrazales pelaje de jabaespínBastón de Tierra RojaPodrás elegir una de estas recompensas:\n\nAmuleto de Dorn\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][25086] = {title = "Punta Piedra de Fuego", objective = "Busca a Dorn Tierra Roja en Punta Piedra de Fuego en Los Baldíos del Sur.", description = "¿Me puedes hacer un gran favor, <nombre>? El tío de mi cuñada pertenece al Anillo de la Tierra y está aquí en los Baldíos para estudiar el impacto del Cataclismo, en Punta Piedra de Fuego. Dice que su campamento está rodeado de jabaespines y temo que le hagan daño.\n\n¿Puedes ver si Dorn Tierra Roja está bien? No soportaría que algo le ocurriera, por lo del estrecho vínculo familiar y eso.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25087] = {title = "Informa a Trenzado", objective = "Entrega el informe del frente al general Trenzado que está patrullando por Los Baldíos del Sur.", description = "La Alianza tiene una deuda con los enanos de Bael Modan, que construyeron algunas de nuestras primeras fortificaciones en los Baldíos.\n\nSu comandante, el general Trenzado, es fiel y leal. Uno de nuestros mejores. Su patrulla está al sur de aquí, manteniendo a la Horda a raya.\n\nDefinitivamente quiero ponerlo al tanto de la situación aquí para que podamos coordinar nuestro próximo movimiento. ¿Puedes entregarle este informe del frente en el campo?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25090] = {title = "Una tarea pútrida", objective = "Entrega 7 garras podridas al guardia de la Muerte Dillinger en la Mansión Fríogar.", description = "La Plaga ha alcanzado los Claros de Tirisfal y ha infestado esta área.\n\nNecesito a alguien que se encargue de dar una lección a los muertos en podredumbre y a los cuerpos devastados que han ocupado esta pequeña granja. Rompe sus huesos y tráeme sus garras podridas. Los guardias de la Muerte te recompensarán.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25091] = {title = "Vigía Penas de Arena", objective = "Habla con Trenton Mazaligera en Vigía Penas de Arena.", description = "Si estás buscando más trabajo, tengo algo para ti.\n\nConozco a un elfo llamado Trenton Mazaligera que lleva años obsesionado con los trols de arena de las inmediaciones. Está completamente decidido a encontrar una especie de espada mítica fabricada por ellos, y justo hace poco consiguió reunir un equipo para ir a Vigía Penas de Arena para buscarla.\n\nLo último que sé del asunto es que echaron a los trols de uno de sus campamentos y montaron un negocio allí. Búscalo hacia el oeste, cerca de Zul'Farrak.", progress = nil, completion = "¿Te envía Marin? Agradezco su ayuda.\n\nHe venido aquí en busca de Sul'thraze. Si quieres ayudar habla con Mazoga... hasta el momento ha cooperado con nosotros.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25093] = {title = "Los comandantes de la IV:7", objective = "Consigue las cabezas del comandante Arrington, de Cyn Filoscuro y de Alexi Aullido Silencioso.", description = "La Alianza asesinó a estos orcos a sangre fría en la costa. No hicimos nada para provocarles.\n\nSu muerte no debe quedar impune, <nombre>. ¿Les llevarás ante la justicia?\n\n<Aggra apenas puede contener la rabia.>\n\nTres comandantes de la IV:7 se encuentran repartidos por la playa. Tráeme sus cabezas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Fajín de AggraBandeja de plataRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25094] = {title = "Truenódromo: ¡Zumonga!", objective = "Derrota a Zumonga.", description = "¡Muy bien hecho! ¡Pero te vas a enfrentar a mucho más que a meros humanos!\n\nTu siguiente oponente es terrible... cuidado con su gancho de derecha. Y con su zurda. En fin, que yo me preocuparía de sus puños, en general.", progress = nil, completion = "No está mal. Pero todavía te queda mucho por delante.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25095] = {title = "Truenódromo: ¡Sarinexx!", objective = "Derrota a Sarinexx.", description = "Espero que estés <listo/lista> para lo siguiente, <nombre>. ¡Una sola equivocación puede significar una muerte violenta e instantánea! Pero la gente paga para ver eso, ¿no?\n\nEspero que no te den miedo los bichos...", progress = nil, completion = "Bastante impactante. Muy pocos son capaces de mirar cara a cara a un atracador silítido, y mucho menos derrotarlo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25098] = {title = "El Jefe de Guerra te reclama", objective = "Habla con Thrall en la Atalaya del Jefe de Guerra, en Las Islas Perdidas.", description = "Fiel a su palabra, Thrall nos va a guiar por el buen camino para rescatar a nuestro pueblo. Ha solicitado hablar contigo.\n\nBuena suerte, <nombre>, dependemos de ti.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25099] = {title = "Un préstamo bestial", objective = "Habla con Kilag Mandisangre en Costa Tranquila, en Las Islas Perdidas.", description = "Regresa a la costa e informa a Kilag de que me complacería que te prestara a Bastia. La pantera conoce el camino al lugar donde tus amigos permanecen cautivos.\n\nParte ahora. Volveremos a vernos antes de que movamos nuestra siguiente ficha contra el Príncipe mercante.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25102] = {title = "¡Al toro!", objective = "Mata a 4 kodos Sacudetierra y a un toro Sacudetierra.", description = "Las patrullas de Trenzado siempre nos conducen al centro del peligro. Cuando no son emboscadas de la Horda, es un golpe asestado por los jabaespines.\n\nEl problema son esos repugnantes kodos Sacudetierra. Grandes muros de pelo andantes que hacen retumbar el suelo... No podemos ver ni oír las emboscadas que nos tienden por la retaguardia.\n\nAhuyéntalos y aléjalos de nuestra patrulla. Si matas a unos cuantos, la manada debería desviarse hacia el sur y dejarnos tranquilos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Sobrehombros repelentes de kodoLeotardos de sacudetierraEspada de TirapiedrasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25103] = {title = "Avanzada del Contrabandista", objective = "Habla con Zeke Atabotas en la Avanzada del Contrabandista.", description = "Hemos hecho un trabajo alucinante aquí. Me voy a asegurar de que estos estúpidos acaben todo bien y después volveré a Gadgetzan durante un tiempo.\n\nSi quieres seguir quedando bien con nuestros amigos de Bonvapor, o sencillamente conseguir más dinero, deberías dirigirte hacia el suroeste. La Avanzada del Contrabandista está al borde de la Sima Abierta.\n\nHabla con Zeke Atabotas. Me apuesto algo a que necesita ayuda.", progress = nil, completion = "Estás con Megs, ¿eh? He oído que está empeñada en hacer buenas migas con Tragonublo.\n\nNo es que me importe. ¿Estás preparado para matar unos cuantos bichos?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25104] = {title = "El estado de la excavación", objective = "Localiza a Marley Trenzado fuera de la Excavación de Bael Modan en Los Baldíos del Sur.", description = "Hoy la patrulla ha estado muy callada y estoy preocupado, <nombre>.\n\nDesde que la Alianza saqueó Taurajo, ninguna de nuestras posiciones está a salvo. Parece que te vales por ti <mismo/misma>, ¿puedes hacerme un favor?\n\nAvisa a mi hijo Marley fuera de la excavación de Bael Modan, al sureste. La zona está expuesta y es propensa a sufrir ataques, y mi hijo es demasiado orgulloso para pedir ayuda si la necesita.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25105] = {title = "¡Mordisquitos! ¡No!", objective = "Talla tres cefiritas sólidas y dáselas a Isabel Jones en la Ciudad de Ventormenta.", description = "¡La mascota de Lila, Mordisquitos, se ha vuelto a meter en mi taller!\n\nEstaba elaborando un brazalete que tengo que entregar hoy. Casi había terminado el trabajo, solo me faltaban las gemas. Me he pasado toda la noche tallándolas, pero cuando me he ausentado un minuto para desayunar, ¡esa pequeña bestia ha entrado en mi taller y se ha tragado todas las gemas que había! Ese bicho lo digiere TODO, créeme, te dejarías la piel intentando hurgar en sus excrementos.\n\nTengo que encontrar gemas de repuesto y rápido, el mensajero va a venir esta noche. ¡Socorro!", progress = "¿Me has traído las cefiritas sólidas que necesito?", completion = "Me has salvado el pescuezo, &lt;nombre&gt;. ¡Gracias!", rewards = "Recibirás:\n\nMuestra de ilustre joyeroCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25106] = {title = "¡Quítame las manos de encima!", objective = "Mata a 8 asaltantes de excavación, rescata 5 artefactos de Bael Modan y consigue las herramientas de Trenzado en la Excavación de Bael'modan.", description = "¡Fíjate en el caos de ahí abajo, <nombre>! He ordenado a los supervisores que rescaten todos los artefactos que puedan. Quién sabe qué tipo de tesoros pueden llegar a robar los bestias de los tauren.\n\n¿Puedes echarnos una mano? Mata a los asaltantes y rescata todos los artefactos que puedas.\n\nMientras tanto, busca mis herramientas perdidas. Unas cuantas reparaciones rápidas y podré poner de nuevo en funcionamiento esta máquina voladora.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25107] = {title = "La gran tablilla", objective = "Lleva la gran tablilla a Andoren Alzalba.", description = "Al fondo del cofre encuentras una gran tablilla. Fabricada en un material parecido a la piedra, pero totalmente suave y sin mella, está cubierta de escrituras extrañas.\n\nAlgunas de las escrituras se parecen a las de los muros, pero el resto resultan completamente diferentes. Seguramente a Andoren le encantará ver esto.", progress = "¡Has vuelto! ¿Qué has encontrado?", completion = "Esto es realmente increíble. Los jeroglíficos son titánicos, no hay duda, pero las marcas de debajo...\n\nAlgunos de estos caracteres son parecidos a las antiguas escrituras de los kaldorei. ¿Y dices que la antecámara estaba cubierta de jeroglíficos?\n\nTu descubrimiento es más valioso que cualquier riqueza, &lt;nombre&gt;. Por favor, escoge la recompensa que prefieras.", rewards = "Yelmo de jeroglíficosBotas de traslaciónCinturón de tablilla enrojecidoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25108] = {title = "Feegly el Exiliado", objective = "Mata a Feegly el Exiliado en la Excavación de Bael Modan.", description = "Es la historia más triste que he oído en mi vida, <nombre>. Feegly era uno de nuestros cavadores más rápidos hasta que oyó hablar de esa... cosa. La llamamos la \"Lágrima de las Lunas\". Lo transformó. Lo cambió por completo. Ojalá nunca hubiera sido desenterrada.\n\nFeegly fue desterrado de Bael Modan pero me han llegado noticias de que ha estado husmeando por la excavación otra vez. Ya ha sufrido bastante, el desdichado. Si lo encuentras abajo, libra al antiguo Feegly de su miseria.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Sobrehombreras de Bael ModanEmbozo de FeeglyFin de la miseriaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25111] = {title = "Carroña de carroñeros", objective = "Usa el Robocarnicero para recoger 12 cadáveres de roc de fuego.", description = "Ahora que sé que no eres impresionable, tengo otro trabajo para ti. ¿Has visto los pájaros de alas rojas que merodean alrededor de los huesos ahí fuera? Son rocs de fuego. Te prenderán como una cerilla si no andas con cuidado.\n\nAdemás son bastante valiosos debido a su anatomía única. La mayoría de los cazadores que holgazanean por aquí no están a la altura, son incapaces de matar águilas ratoneras que escupen fuego solo por dinero... ¿Te ves capaz de encargarte tú?", progress = nil, completion = "Los alquimistas pagan un ojo de la cara por estas cosas. Sí, tal vez a algunos les diga que son trozos de dragón. No es mi problema, ¿verdad?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25112] = {title = "Robocarnicero", objective = "Usa el Robocarnicero para recoger 10 cadáveres de basiliscos Cristaldermo.", description = "Me gano el jornal vendiendo trozos de animales por la zona. He estado perfeccionando un método infalible para maximizar los beneficios: ¡el Robocarnicero!\n\nEstos pequeñajos están programados para recoger todos los trozos útiles de la fauna de la zona, uno por uno. Ellos hacen todo el trabajo, y lo mejor de todo es que solo yo sé cómo sacar los productos de su interior.\n\nSi te interesa hacerte con unas monedas, coge a uno de estos tipejos y llévatelo a dar una vuelta. Necesito trozos de basilisco Cristaldermo; encontrarás unos cuantos hacia el sur.", progress = nil, completion = "Esto va bien, chico. ¿No has perdido ningún dedo? Bien, entonces podremos conseguirte algo más de trabajo.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25115] = {title = "Carnicería de Llagapata", objective = "Usa el Robocarnicero para reunir 10 cadáveres de hienas Llagapata.", description = "Las hienas que vagan por estas tierras baldías pueden tener un aspecto escuálido, pero no encontrarás mandíbulas más fuertes en ninguna parte. Si no te andas con ojo, te arrancarán una pierna de un mordisco. Ese tipo de fuerza ósea es un recurso muy valioso, <amigo/amiga>. ¡Tan solo está esperando un comprador!\n\nLlévate a uno de mis Robocarniceros. Separar las mandíbulas no es una tarea fácil y este pequeño ha sido diseñado para saber con exactitud qué hacer. Solo tienes que devolvérmelo cuando esté lleno.", progress = nil, completion = "¡Qué bonitas! Les sacaré brillo a estos cachorros y los prepararé para venderlos en un periquete.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25118] = {title = "En busca de merodeadores", objective = "Mata a 8 rondadoras del bosque.", description = "No sé tú, pero yo no soy un gran amante de las arañas, y mucho menos de las que son más grandes que yo. Loch Modan es un lugar estupendo, pero desde mi punto de vista mejoraría mucho sin ese horror de criaturas paseándose por todas partes.\n\nTe diré lo que haremos: a mí me sobran unas monedas y tú pareces bastante fuerte... si sales ahí y te cargas a unos cuantos de esos bichos, te pagaré por el tiempo empleado.", progress = nil, completion = "Descansaré mejor sabiendo que uno de esos pesados ya no merodeará por mi habitación por las noches... de nuevo. Muchas gracias.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25120] = {title = "El vuelo final de Marley", objective = "Habla con Marley Trenzado y date una vuelta en su máquina voladora.", description = "¡Bueno, <nombre>! Lleva estos artefactos a mi padre y entrégale el informe de primera mano.\n\nGracias a tu ayuda, mi máquina voladora está lista para empezar a rodar. Podemos volar juntos hasta allí y compartir la gloria.\n\n¡Ven a verme cuando tengas todo preparado para partir!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25121] = {title = "Momento", objective = "Encuéntrate con Kelsey Chispacero en la Cala del Aparejo Perdido.", description = "¡Parece que tenemos más trabajo por hacer! Es todo un honor que el Sr. Tragonublo nos haya pedido que nos encarguemos del resto de los piratas.\n\nYa que has sido de TANTA ayuda, ¿por qué no te reúnes conmigo en la Cala del Aparejo Perdido? Yo tengo que ponerme algo más cómodo, así que no me esperes. Te veré allí, ¡te lo prometo!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25126] = {title = "Dientes afilados", objective = "Mata a 6 jabalíes jaspeados.", description = "El primer punto del día será fortalecer un poco tu espalda. Te podría enviar a Los Baldíos, a cazar kodos, pero, sinceramente, nos eres más útil <vivo/viva> que <muerto/muerta>.\n\nCreo que nos serás de más utilidad matando a los jabalíes que hay en las granjas del norte y el noreste.", progress = nil, completion = "Umm... no está mal, &lt;nombre&gt;. Pero que no se te suba a la cabeza... tendrás que luchar con cosas mucho más duras que un jabalí en tu carrera. \n\nSin embargo, has mostrado tu valía, y tu siguiente prueba será contra un adversario mucho más peligroso, necesitarás algo más de protección.", rewards = "Cinturón de pellejo de jabalíGuanteletes del fanfarroneadorBrazales jaspeadosRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25127] = {title = "Aguijón de escórpido", objective = "Consigue 8 colas de escórpido obrero.", description = "Tengo que enviarte al campo de nuevo, <clase>. Encontrarás un gran número de escórpido al noroeste de aquí. Tráeme ocho de sus colas.\n\nDe hecho, el antídoto para su picadura se hace con veneno extraído de sus aguijones. Solemos tener a mano grandes cantidades de antídoto para veneno de escórpido para sanar a jóvenes como tú...\n\nPero seguro que no te hará falta, ¿verdad?", progress = "El caparazón de un escórpido no es tan resistente como para disuadir la fuerza y determinación de un guerrero. Golpea fuerte y sin dudas, y los escórpidos serán una presa fácil.", completion = "De tus luchas con los escórpidos debes sacar una lección importante. Tanto el menor como el mayor de tus oponentes pueden enviarte directo al infierno. En el combate cualquier cosa y en cualquier número o tamaño puede llevarte a la perdición. \n\nNo tengo nada más que enseñarte, &lt;nombre&gt;. Te has portado bien y seguiré con mucho interés tus progresos.", rewards = "Botas caparazónCalzones curados con venenoTogas imbuidas de venenoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25129] = {title = "Sarkoth", objective = "Mata a Sarkoth y llévale su zarpa a Hana'zua.", description = "¡<clase>! Creía que iba morir ahí fuera sin que nadie se enterara. Cuando estaba cazando los escórpidos del valle me crucé con uno que tenía un aspecto especialmente atroz. Me lancé contra él y conseguí asestarle un enorme golpe antes de que se enrollara en mi pierna.\n\nPero no estaba listo para su aguijón, y consiguió deslizarse en mi peto, desgarrando y penetrando en mi piel y derramando mi sangre. Por favor, ¡debes matar a ese escórpido! ¡Hay que defender mi honor! Combatí con él en la meseta que está al Sur.", progress = "Aaah... mi padre siempre decía que nunca llegaría demasiado lejos y estando aquí, bajo un árbol viendo cómo mi vida se desvanece, parece que estaba en lo cierto.\n\nAl menos me gustaría morir sabiendo que mi último enemigo ha muerto.", completion = "Mis golpes no bastaron para matarle, pero cuando pienso en el daño que le hice siento algo de orgullo. Ese orgullo será todo lo que tenga si muero y, desde esa perspectiva, me enfurezco al pensar en las pocas cosas que he terminado en mi vida.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25130] = {title = "De vuelta a El Cubil", objective = "Informa de la situación de Hana'zua a Gornek en el Valle de los Retos.", description = "La hazaña que has hecho por mí llena de valor mi corazón. ¡No puedo caer tan fácilmente! ¡Debo resistir!\n\nPero lo cierto es que no puedo hacer el camino de vuelta a nuestro asentamiento sin ayuda. Por favor, <nombre>, vuelve e informa a Gornek de mi situación. Quizás él pueda ayudarme.", progress = nil, completion = "Según tu descripción de la bestia creo que estás hablando de Sarkoth. No me extraña que pudiera con Hana'zua. Le prestaremos ayuda inmediatamente, ya no necesitas seguir preocupándote por su situación. \n\nPero hay una cosa que debo decir, me ha impresionado saber que acabaste con la vida de Sarkoth. Es una hazaña de la que estar orgulloso, &lt;nombre&gt;. Además, el haber luchado por el honor de un desconocido, dejando a un lado tus propias tareas, es, sin duda alguna, todo un signo de honor por tu parte.", rewards = "Bandas de alabanzaFaja de honorGuantes de mano amigaRecibirás:\n\nBolsa polvorientaCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25131] = {title = "Familiares viles", objective = "Mata a 8 familiares viles.", description = "Estoy segura de que aprenderás mucho en el Valle de los Retos, joven <clase>.\n\nFui enviada al Valle para guiarte, pero aquí he descubierto una creciente corrupción...\n\nUn miembro del Filo Ardiente, un abominable culto adorador de demonios, tiene un aquelarre aquí mismo, en el Valle de los Retos. Se esconde en una cueva al Norte, y sus familiares viles se han esparcido desde la boca de la cueva sembrando el caos y la confusión.\n\nComo primera tarea contra el Filo Ardiente, quiero que derrotes a esos familiares. Aniquila a muchos y, si sobrevives, vuelve a verme.", progress = nil, completion = "Muy bien hecho, &lt;nombre&gt;. \n\nAunque los familiares viles no son más que mascotas de los poderes oscuros del Filo Ardiente, tu victoria presagia grandes hazañas.", rewards = "Botas vilesJersey vilZapatillas vilesRecibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25132] = {title = "El medallón del Filo Ardiente", objective = "Mata a 7 acechadores viles y consigue el medallón del Filo Ardiente.", description = "Mis adivinaciones me traen visiones de un objeto lleno de poder, un medallón, oculto en las profundidades del Aquelarre del Filo Ardiente y custodiado por bestias y magia negra. Debemos conseguirlo.\n\nEsos adoradores de demonios han mancillado nuestras tierras durante demasiado tiempo.Purifica el aquelarre de su corrupción demoníaca matando a esas bestias malignas y a su líder. Regresa con ese medallón como prueba de tu éxito.\n\nVete, <nombre>. Encontrarás el Aquelarre en una cueva, al Norte.", progress = "¿Has completado tu tarea, <nombre>?", completion = "¡Lo has recuperado! ¡Bien hecho! \n\nTus esfuerzos en el Aquelarre del Filo Ardiente son fundamentales para erradicar ese culto del Valle de los Retos. No obstante, temo que tienen más planes en esta tierra. \n\nAún no hemos visto su final.", rewards = "Guantes del Aquelarre del Filo ArdienteBandas de VistalongaLeotardos de expulsiónRecibirás:\n\nPoción de sanación menorCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25134] = {title = "Peones vagos", objective = "Utiliza la Cachiporra del supervisor con los peones vagos que estén durmiendo.", description = "¡Malditos peones! Trabajan muy duro recogiendo madera de los árboles del valle, ¡pero siempre se están echando siestas! Necesito a alguien que me ayude a mantener firmes a esos peones.\n\nPareces <el/la:r> <raza> <adecuado/adecuada> para esta tarea. Toma, coge esta cachiporra y utilízala con los perezosos peones que encontrarás durmiendo por ahí durante el trabajo. ¡Un buen golpe y volverán al trabajo! Devuélveme la cachiporra cuando hayas terminado.\n\nBúscalos bajo los árboles, en el valle. Qué vagos y flojos son estos peones...", progress = "Vaya holgazanes...\n\n¿Eh? ¿Tienes mi cachiporra? ¡¿Pillaste a algún peón durmiendo durante el trabajo?!", completion = "Bien, bien. ¡Quizás la próxima vez se lo piensen dos veces antes de ponerse a hacer el vago! ¡Gracias por la ayuda!", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25135] = {title = "Pico de Thazz'ril", objective = "Lleva el pico de Thazz'ril al supervisor Thazz'ril.", description = "<nombre>, eres <un/una:r> <raza> de confianza. ¿Puedo contar contigo para otra tarea?\n\nHace algún tiempo estaba inspeccionando la cueva del Norte en busca de minerales y olvidé allí mi pico favorito. ¡Pero cuando volví a recuperarlo descubrí que la cueva estaba plagada de despiadadas criaturas! ¿Irás a la cueva, el Aquelarre del Filo Ardiente, para recuperar mi pico?\n\nLo dejé en una caverna con cascadas. El pico tiene un hechizo que te permitirá verlo en la oscuridad, así que no tienes que preocuparte mucho por encontrarlo... ¡solo por lo que lo esté custodiando!", progress = "¿Entraste en el Aquelarre del Filo Ardiente, <nombre>? ¿Encontraste mi pico?", completion = "¡Genial, lo conseguiste! Muchas gracias, &lt;nombre&gt;. ¡Es mi pico favorito! Ahora, y si mis peones terminan de talar esos árboles de una vez, tal vez encuentre una bonita cueva para excavar.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25136] = {title = "Sorpresa de manzanas de cactus de Galgar", objective = "Consigue 6 manzanas de cactus.", description = "Hace mucho calor ahí fuera, en el Valle de los Retos.\n\n<Galgar se seca la frente.>\n\n¡Si al menos tuviera algunas manzanas de cactus podría hacer mi famosa sorpresa de manzana de cactus! Nada es tan refrescante como un bocado de ese manjar.\n\nTe diré algo, <nombre>: si me traes 6 manzanas de cactus te prepararé unas porciones de sorpresa de manzana de cactus para que las lleves a tus aventuras. Si estás <interesado/interesada>, encontrarás manzanas de cactus junto a las plantas de cactus que crecen en los alrededores.", progress = "¿Has terminado de recoger manzanas de cactus?", completion = "¡Fantástico, &lt;nombre&gt;! Como te prometí, toma una sorpresa de manzana de cactus... y algo más.", rewards = "Recibirás:\n\nSorpresa de manzana de cactusCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25139] = {title = "Disparo firme", objective = "Aprende Disparo firme de Karranisha en el Valle de los Retos. Localiza un muñeco de entrenamiento y practica Disparo firme 5 veces.", description = "Ya sabes cómo lanzar un disparo Arcano. Bien. Si lo haces, tu enfoque se verá reducido. Para recuperarlo, tendrás que lanzar un segundo tipo de ataque a distancia. Te lo enseñaré.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nBrazales de rastreador de bestiasCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25151] = {title = "¡Una de cerveza!", objective = "Dirígete a la Fortaleza de Bael'Dun y consigue una jarra de Ol' Barkerstout. Entrégasela a Marley Trenzado en la entrada.", description = "<Marley te agarra por la cabeza con una mano sangrienta y temblorosa.>\n\nCerveza... necesito... cerveza...\n\nEsa Ol' Barkerstout de ahí. <Tose.> Eso... servirá.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25152] = {title = "Tu lugar en el mundo", objective = "Habla con Gornek.", description = "Por fin ha llegado el momento, <nombre>... el momento de que combatas en nombre de la Horda. Conquistarás por la gloria de nuestro Jefe de Guerra.\n\nSí...\n\n<Kaltunk te examina.>\n\nLo harás bien.\n\nSupongo que estarás deseando encontrar un dragón o un demonio enorme para estrangularlo con las manos, pero quizás sería más inteligente empezar por algo menos... peligroso.\n\n<Kaltunk se ríe.>\n\nBusca a Gornek. Él podrá asignarte una tarea adecuada para ti, joven <clase>. Lo encontrarás sentado junto al fuego que hay detrás de mí.\n", progress = nil, completion = "Otro de los reclutas de Kaltunk, ¿eh?\n\nPues sí que están mal las cosas, si esto es lo mejor que puede ofrecer la Horda. No importa. Para cuando te llegue el momento de salir del Valle, serás un guerrero digno de la Horda.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25153] = {title = "El rescate de Bael'dun", objective = "Entra en la Fortaleza de Bael'dun y rescata a 10 supervivientes de Bael'dun de entre los escombros.\n\nUtiliza las válvulas antiincendio para protegerte de las llamas.", description = "¡Socorro, ayuda! ¡Tienes que hacer algo!\n\nAlgunos enanos todavía permanecen dentro, atrapados entre los deshechos. ¡Enterrados vivos entre las llamas! Es una pesadilla. No sabemos cuánto tiempo tenemos hasta que se derrumbe el techo...\n\n<clase>, ¡te ruego que los salves!\n\nApresúrate. Utiliza las válvulas antiincendio para protegerte de las llamas. Eres su última esperanza...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Leotardos de malla de Bael'dunHoja de supervivienteJubón de Fortaleza de Bael'dunRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25154] = {title = "Un regalo para Lila", objective = "Talla tres piedras nocturnas intemporales y dáselas a Isabel Jones, en la Ciudad de Ventormenta.", description = "Estoy intentando impresionar a una capitana de nave mercante llamada Lila. He estado trabajando en un collar que vaya con su precioso pelo morado, ¡pero las gemas han desaparecido! Las tenía cuando se las enseñé a mi buen amigo Bonder, anoche. Estábamos bebiendo licor y perdí el conocimiento; cuando desperté, ¡las gemas ya no estaban! Han debido de ser unos ladrones muy hábiles, porque Bonder no ha visto nada.\n\nEl barco de Lila viene esta noche y me hacen falta tres piedras nocturnas para acabar su regalo. ¡Ayúdame!", progress = "¿Me has traído las piedras nocturnas?", completion = "¡Gracias! ¡Con estas seguro que le gano a la tal Marith Lazuria de Orgrimmar! Me muero de ganas de verle los maravillosos ojos cuando se las dé.", rewards = "Recibirás:\n\nMuestra de ilustre joyeroCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25155] = {title = "Las ogrozonianas están de humor", objective = "Talla tres jaspes dentados y entrégaselos a Isabel Jones en la ciudad de Ventormenta.", description = "Se supone que tenía que recibir un cargamento de jaspe de Azeroth Express, pero acabo de enterarme de que su barco se hundió cerca de una isla diminuta llamada Ogrozonia. Me preocupa la tripulación pues se rumorea que las ogras gigantes de la isla llevan a cabo horribles rituales con los hombres que naufragan en sus costas. Sin embargo, mi trabajo debe continuar, y necesitamos esas gemas. Me han contado maravillas de tu habilidad como <joyero/joyera>; ¿podrías conseguirme tres jaspes dentados antes de que acabe el día?", progress = "¿Me has traído las gemas que necesito?", completion = "¡Tu trabajo es tan bueno como dicen!", rewards = "Recibirás:\n\nMuestra de ilustre joyeroCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25156] = {title = "Baba elemental", objective = "Reúne 10 babas elementales de cualquier elemental del Cataclismo y llévaselas a Isabel Jones, en Ciudad de Ventormenta.", description = "En lugar de utilizar el viejo y anticuado método de incrustar gemas en anillos y demás, yo empleo un método nuevo e innovador. ¡Me limito a pegar las gemas con la cola elemental de Barnsworth! Pero el profesor necesita más baba elemental para elaborar otra tanda, y yo tengo que incrustar un montón de gemas. ¿Me puedes traer un poco?", progress = "¿Me has traído la baba elemental?", completion = "Gracias. Eh... Tú déjala por ahí. Tengo que encontrar la forma de despegarme la mano de este tarro�", rewards = "Recibirás:\n\nMuestra de ilustre joyeroCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25157] = {title = "¡La última moda!", objective = "Prueba el polvo estelar nº 2 con 10 \"sujetos humanoides\".", description = "El profesor Barnsworth ha estado trabajando en un nuevo polvo estelar. Esta temporada en Ventormenta se lleva todo lo que brille, ¡así que si conseguimos comercializarlo seguro que es todo un éxito! Sin embargo, la Asociación de Joyeros no nos deja venderlo sin haber completado pruebas con humanoides; algo sobre que trastear con polvos mágicos es peligroso o alguna tontería por el estilo. Bueno, supongo que tendremos que seguirles la corriente. Llévate esta bolsa y prueba el polvo estelar nº 2 con sujetos humanoides.", progress = nil, completion = "¡¿Que ha qué?! ¡Estamos arruinados! Bueno, en realidad... A lo mejor el profesor puede buscarle otras aplicaciones...", rewards = "Recibirás:\n\nObjeto #1Muestra de ilustre joyeroCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25158] = {title = "¡Mordisquitos! ¡No!", objective = "Talla tres cefiritas sólidas y dáselas a Marith Lazuria, en Orgrimmar.", description = "¡La mascota de Lila, Mordisquitos, se ha vuelto a meter en mi taller!\n\nEstaba elaborando un brazalete que tengo que entregar hoy. Casi había terminado el trabajo, solo me faltaban las gemas. Me he pasado toda la noche tallándolas, pero cuando me he ausentado un minuto para desayunar, ¡esa pequeña bestia ha entrado en mi taller y se ha tragado todas las gemas que había! Ese bicho lo digiere TODO, créeme, te dejarías la piel intentando hurgar en sus excrementos.\n\nTengo que encontrar gemas de repuesto y rápido, el mensajero va a venir esta noche. ¡Socorro!", progress = "¿Me has traído las cefiritas sólidas que necesito?", completion = "Me has salvado el pescuezo, &lt;nombre&gt;. ¡Gracias!", rewards = "Recibirás:\n\nMuestra de ilustre joyeroCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25159] = {title = "¡La última moda!", objective = "Prueba el polvo estelar nº 2 con 10 \"sujetos humanoides\".", description = "El Dr. Vernstrom ha estado trabajando en un nuevo polvo estelar. Esta temporada en Orgrimmar se lleva todo lo que brille, ¡así que si conseguimos comercializarlo seguro que es todo un éxito! Sin embargo, la Asociación de Joyeros no nos deja venderlo sin haber completado ciertos \"estudios científicos\"; algo sobre que trastear con polvos mágicos es peligroso o alguna tontería por el estilo. Bueno, supongo que tendremos que seguirles la corriente. Llévate esta bolsa y prueba el polvo estelar nº 2 con sujetos humanoides.", progress = nil, completion = "¡¿Que ha qué?! ¡Estamos arruinados! Bueno, en realidad... A lo mejor el doctor puede buscarle otras aplicaciones...", rewards = "Recibirás:\n\nObjeto #1Muestra de ilustre joyeroCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25160] = {title = "Un regalo para Lila", objective = "Talla tres piedras nocturnas intemporales y dáselas a Marith Lazuria, en Orgrimmar.", description = "Estoy intentando impresionar a una capitana de nave mercante llamada Lila. He estado trabajando en un collar que vaya con su precioso pelo morado, ¡pero las gemas han desaparecido! Las tenía cuando se las enseñé a mi buen amigo Bonder, anoche. Estábamos bebiendo licor y perdí el conocimiento; cuando desperté, ¡las gemas ya no estaban! Han debido de ser unos ladrones muy hábiles, porque Bonder no ha visto nada.\n\nEl barco de Lila viene esta noche y me hacen falta tres piedras nocturnas para acabar su regalo. ¡Ayúdame!", progress = "¿Me has traído las piedras nocturnas?", completion = "¡Gracias! ¡Con estas seguro que le gano a Isabela Jones en Ventormenta! No puedo esperar a ver la mirada de su precioso ojo cuando le de esto.", rewards = "Recibirás:\n\nMuestra de ilustre joyeroCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25161] = {title = "Las ogrozonianas están de humor", objective = "Talla tres jaspes dentados y entrégaselos a Marith Lazuria en Orgrimmar.", description = "Se supone que tenía que recibir un cargamento de jaspe de Azeroth Express, pero acabo de enterarme de que su barco se hundió cerca de una isla diminuta llamada Ogrozonia. Me preocupa la tripulación pues se rumorea que las ogras gigantes de la isla llevan a cabo horribles rituales con los hombres que naufragan en sus costas. Sin embargo, mi trabajo debe continuar, y necesitamos esas gemas. Me han contado maravillas de tu habilidad como <joyero/joyera>; ¿podrías conseguirme tres jaspes dentados antes de que acabe el día?", progress = "¿Me has traído las gemas que necesito?", completion = "¡Tu trabajo es tan bueno como dicen!", rewards = "Recibirás:\n\nMuestra de ilustre joyeroCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25162] = {title = "Baba elemental", objective = "Reúne 10 babas elementales de cualquier elemental del Cataclismo y llévaselas a Marith Lazuria, en Orgrimmar.", description = "En lugar de utilizar el viejo y anticuado método de incrustar gemas en anillos y demás, yo empleo un método nuevo e innovador. ¡Me limito a pegar las gemas con la cola elemental de Vernstrom! Pero el doctor necesita más baba elemental para elaborar otra tanda, y yo tengo que incrustar un montón de gemas. ¿Me puedes traer un poco?", progress = "¿Me has traído la baba elemental?", completion = "Gracias. Eh... Tú déjala por ahí. Tengo que encontrar la forma de despegarme la mano de este tarro�", rewards = "Recibirás:\n\nMuestra de ilustre joyeroCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25163] = {title = "¿Quién lo hizo?", objective = "Busca un cadáver de la Horda dentro de la Fortaleza de Bael'dun.", description = "¡Sabotaje! Tiene que ser eso. El cargador de la fortaleza ha explotado por completo. La Horda ha debido de infiltrar a alguien...\n\n<clase>, si tienes los guijarros para introducirte en esa pesadilla ardiente... busca pistas sobre quién pudo causar este desastre. ¡El general querrá saberlo! Busca un cadáver de la Horda entre los restos y llega al fondo de este asunto...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25164] = {title = "Arrinconados", objective = "Defiende el campamento del Anillo de la Tierra hasta que los nagas se retiren.", description = "Los nagas están sobre nosotros, <clase>. ¡Ayúdanos a hacerlos retroceder!", progress = nil, completion = "Me alegra que estuvieses aquí.\n\nParece que Toshe quiere perseguirlos. Deberías ayudarles.", rewards = "Coraza LuzúmidaGuardahombros de poder carideanoSandalias de ostrácodoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25165] = {title = "Nunca te fíes de un gran pincho y una sonrisa", objective = "Consigue 6 muestras de veneno de escórpido colocando el tótem de extracción de veneno cerca de un escórpido castañeteante.", description = "Ahora, vamos a conseguir algo de veneno de los eh'corpiones que andan cerca de aquí. Pero no te preocupes, ¡Bom'bay no dejará que te hagan daño!\n\nBom'bay tiene un gran tótem que colocarás en el suelo cuando te ataque el eh'corpión. El tótem chupará todo el veneno y tú saldrás vivito y coleando. ¿Te va?", progress = nil, completion = "¡Esto es! ¡El juju de eh'córpido que Bom'bay ha eh'tao eh'perando! Ahora vamos a arreglarte, &lt;clase&gt;.\n\nVen a ver a Bom'bay cuando necesites un retoque. ¡Bom'bay tiene los hechizos para arreglarte!", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25166] = {title = "Capitán Barbatroz", objective = "Mata al capitán Barbatroz.", description = "Esto cada vez es más divertido, pero ¡no olvidemos que estamos aquí por Gnomeregan!\n\nHemos localizado al capitán de los Mares del Sur en uno de sus barcos al sur, pasada la zona de la lucha. Está solito en su barquito, ¡indefenso!\n\nSi vas a ocuparte de él, nosotros limpiaremos al resto de esos piratas en un momento.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Togas bellas de satisfacciónGuantes de estrangulador BarbatrozCinturón de investigadorBotas impacientesRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25167] = {title = "Rompiendo la cadena", objective = "Destruye 3 cajones de suministros de Fuerte del Norte y mata a 10 arrastradores del Fuerte del Norte.", description = "Colega, eh'to no va bien. Nada de nada.\n\nThrall se fue al mar, Vol'jin se eh'tá ocupando de asuntos en las Islas del Eco y el viejo maestro Gadrin se quedó atrás para ocuparse de Sen'jin. ¿Y qué pasa entonces? ¡Esos humanos salen del Fuerte del Norte y acampan en nueh'tro patio!\n\nPor sueh'te, acaban de llegar y aún eh'tán colocando su base. Puedes ayudar al viejo Gadrin deh'truyendo esos grandes cajones de suministros que llevan y matando a los obreros que los llevan. Los encontrarás al suroeste.", progress = nil, completion = "Bueno, hemos bloqueado sus eh'fuerzos por ahora, pero siguen aquí. Tendremos que seguir con la presión, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25168] = {title = "Purgar el valle", objective = "Derrota a 12 tropas de Fuerte del Norte en la Ciudadela del Fuerte del Norte.", description = "Fuerte del Norte es un bah'tión bien defendio al suroeste de aquí, más allá del puerto. Es un bah'tión eh'trategicamente situao que la Horda sigue intentando tomar con eh'fuerzo. No necesitamos que los humanos eh'tablezcan otro Fuerte del Norte aquí en Durotar.\n\nCruza el valle al oeste y mata a esos humanos, <nombre>. Haz que conozcan el poder y la furia de Sen'jin.", progress = nil, completion = "Una batalla bien luchada, &lt;clase&gt;, pero aún tengo mis dudas sobre nueh'tra efectividad. No parece que eh'tos humanos vayan a irse a ninguna parte.\n\nPero tú has hecho más de lo que se le podría pedir a cualquier miembro leal a la Horda. Gracias.", rewards = "Arco de Sen'jinBastón de Sen'jinRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25169] = {title = "La guerra de la agresión de Fuerte del Norte", objective = "Destruye 3 conjuntos de planes de ataque guardados en la Ciudadela del Fuerte del Norte.", description = "Eh'tos humanos del oeste, no solo quieren acampar en Durotar, colega. Tienen planes más grandes y esos planes incluyen tomar nueh'tro hogar y clavar nueh'tras calaveras en pinchos.\n\nNo me guh'ta. ¡No! ¡Nunca! ¡Tengo familia aquí en Sen'jin y me sentiré mal si dejo que uno de eh'tos brutos ponga la cabeza de mi Tai'tasi en un palo!\n\nTienen sus planes por eh'crito allí, colega. Grandes pergaminos, de apariencia importante. Quememos esos pergaminos antes de que acabemos quemaos.", progress = nil, completion = "Buen trabajo, héroe. Hoy le has hecho un favor a Sen'jin. No... se lo has hecho a todo Durotar.", rewards = "Guanteletes de DurotarCinturón de ThwarterRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25170] = {title = "Limpiando la costa", objective = "Consigue 5 puñados de mucosidad de reptador.", description = "¡Eh, colega! Bom'bay eh'tá trabajando en un nuevo mojo. ¿Quieres probar un poco? Bueno, antes Bom'bay necesita que consigas algunos jujus.\n\nPrimero, Bom'bay necesita que consigas algunos del moco de los cangrejos del agua. ¡Déjame verte las manos!\n\n<Bom'bay examina tus manos con atención.>\n\nBom'bay necesita 5 puñaos. ¡Venga!", progress = "Cuando traigas los jujus, te enseño mi mojo.", completion = "Sí, colega, eh'to es. Ahora necesitamos los otros jujus.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25171] = {title = "Dando una vuelta", objective = "Habla con el Asaltante Jhash para que te lleve a Cerrotajo. Una vez allí, habla con Gar'thok.", description = "Tenemos que llevar el mensaje a Cerrotajo. Puede que hoy eh'tos humanos eh'tén derrotaos, pero mañana volverán y, entonces, necesitaremos ayuda de los orcos.\n\nHabla con Jhash, fuera de las pueh'tas de Sen'jin. Te llevará hah'ta Cerrotajo. Sus lobos saben bien el camino.", progress = nil, completion = "¿Ese trol quiere que enviemos ayuda? Bah, que se olvide. Tengo mis propios problemas con los humanos de los que ocuparme e incluso esos son la menor de mis preocupaciones ahora mismo.\n\nEl Poblado Sen'jin está junto a las Islas del Eco y el Valle de los Retos. El viejo Gadrin debería encontrar suficientes jóvenes para que le ayuden con su infestación humana.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25172] = {title = "Invasores en nuestro hogar", objective = "Mata a 7 exploradores del Fuerte del Norte.", description = "No eres simplemente <un bruto/una bruta>, pareces <un/una> <clase> <serio/seria>. Bien, porque eso es justo lo que necesito.\n\nProcura que no corra la voz, no quiero que cunda el pánico... pero nos han llegado informes de la presencia de más humanos en la inmediaciones. ¡Esto viola claramente la paz que habíamos negociado con esa miserable de Jaina Valiente! No podemos permitir que los humanos entren aquí, en Durotar, y menos en el Valle.\n\nLos encontrarás al sur. Mátalos rápido, antes de que su número crezca aún más.", progress = nil, completion = "Ejecutados con rapidez y discreción. Un trabajo bien hecho.", rewards = "Leotardos de aversiónBrazales del defensor del corazónJubón de cazador exploradorRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25173] = {title = "De mal en peor", objective = "Mata 6 soldados del Fuerte del Norte, 6 tiradores certeros del Fuerte del Norte y al teniente Palliter en el Fuerte de Tiragarde.", description = "El Fuerte de Tiragarde se encuentra al sureste de aquí, en la costa este de Durotar. Es posible que hayas pasado por allí al ir hacia el Poblado Sen'jin. Ese castillo ha sido una molestia durante demasiado tiempo.\n\nLos humanos de Kul Tiras vivieron años en el castillo y frustraron todos mis intentos de aplastarlos. Cuando nos golpeó el Cataclismo, la costa estaba arrasada, junto con el castillo y los humanos. Sin embargo, ¡estos rebeldes de Fuerte del Norte se están moviendo para ocupar su lugar!\n\n<Gar'Thok ruge enfadado.>", progress = nil, completion = "Los relatos de tu valor viajan raudos, &lt;clase&gt;. Los de tu victoria en el Fuerte de Tiragarde serán anunciados en Orgrimmar.", rewards = "Leotardos de Kul TirasHoja de CerrotajoJubón de TiragardeRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25174] = {title = "Trenzado debe enterarse", objective = "Preséntate ante el general Trenzado en la Patrulla de Trenzado, en Los Baldíos del Sur.", description = "<El general Trenzado querrá conocer los detalles de este ataque cobarde. Recopila las pruebas.>Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25175] = {title = "Malas noticias", objective = "Lleva las malas noticias al general Trenzado en la Patrulla de Trenzado en Los Baldíos del Sur.", description = "<Cierras suavemente los ojos de Marley.>\n\n<Alguien va a tener que informar al general Trenzado de que la Horda ha matado a su único hijo.>\n\n<Y <ese/esa> eres tú.>Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25176] = {title = "Aprovechando la situación", objective = "Reúne 6 piezas de tesoro de Kul Tiras.", description = "<¡Eh, guapo! He estado observando esos bíceps fuertes y musculosos desde que llegaste a la ciudad./¿Qué miras> fea? ¡Te he visto paseándote por Cerrotajo, intentando robarme MIS hombres!;\n\nEscucha, hay algo que tienes que hacer. He oído que Gar'Thok te envió a Tiragarde. Mientras estás allí, ¿podrías buscar algunas joyitas Kul Tiras abandonadas?\n\n<¡Gracias, cielo!/¡No hagas preguntas> ponte a ello!;", progress = "<Gail envía un gruñido arrebatador.>", completion = "¡Me has traído mi tesoro! ¡Eres un cielo!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25177] = {title = "Arrasando las playas", objective = "Mata 11 elementales de mar espumosos.", description = "Ahora que esos humanos van a estar un tiempo callados, podemos pasar a asuntos más urgentes.\n\nEl Cataclismo diezmó radicalmente la costa este de Durotar. Ya viste el destrozo que hicieron en Tiragarde. La devastación fue aún peor en la costa al este de aquí.\n\nTras la primera ola, la playa fue tomada por elementales enfurecidos procedentes del mar. Envié brutos para que se ocupasen de ese asunto, pero la carnicería fue brutal. Creo que tu tendrás un poco más de suerte que ellos.\n\n¡Cuidado con las mareas!", progress = nil, completion = "El aroma del mar te rodea, &lt;nombre&gt;. Puede que tus esfuerzos hayan regalado otro día a Cerrotajo.\n\nHablaré de tus actos a mi círculo de mando. Tienes nuestra gratitud.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25178] = {title = "Rastreando el naufragio", objective = "Reúne 4 conjuntos de herramientas gnómicas.", description = "<¡Hola guapo, me alegro de volver a verte! ¿Podrías darte otro paseo, verdad? Estaría TAN agradecida.../¡Tú! ¡Quieta> lagarta! Aún no he acabado contigo.;\n\nHe oído que vas a la costa al este de aquí. La playa está llena de barcos estrellados y en esos barcos hay herramientas gnómicas... herramientas que puedo utilizar.\n\n<¡Nos vemos pronto, macizo!/¡Que te vea moverte> señorita!;", progress = "¿Ha regresado mi caballero andante?", completion = "Sabes muy bien cómo tratar a una chica, ¿sabes? Si alguna vez necesitas algo, cualquier cosa...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25179] = {title = "Reducción de bajas", objective = "Rescata 4 toscos de Cerrotajo heridos.", description = "Tienes que ayudarnos. Los elementales... son más fuertes de lo que parecen y vienen en oleadas. Nos cogieron por sorpresa y nos vimos superados.\n\nMuchos de mis toscos yacen agonizantes en la arena de la playa. Si los pudieses salvar... te estaría agradecido, igual que lo estaría Gar'Thok en Cerrotajo.", progress = nil, completion = "Ya he hablado con varios orcos que han regresado de la playa. Todos me dijeron que fuiste tú quien los salvó.\n\nHas hecho un trabajo noble, &lt;nombre&gt;. ¡Lok'tar ogar! ¡Por la Horda!", rewards = "Recibirás:\n\nBrazales de bruto de Corrotajo"}
MultiLanguageQuestData['mx'][25182] = {title = "¡Que no quede títere con cabeza!", objective = "Mata a 10 mineros Catacroquer en Filón Catacroquer, en Los Baldíos del Sur.", description = "¡<nombre>, quiero ver algunos goblins muertos! Al oeste, encontrarás una guarida de esos pequeños insectos excavada en la montaña.\n\nOcupémonos de que se caven su propia tumba.\n\nDestrúyelos. Arruina por completo su mugrienta operación. Firmaron su sentencia de muerte en Bael'dun, <clase>, y es hora de que conozcan a su verdugo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25183] = {title = "Y entierra al resto...", objective = "Monta 6 explosivos de Catacroquer en la mina del Filón Catacroquer.", description = "No basta con matarlos. Después de Bael'dun, quiero dar a esos goblins un poco de su propia medicina.\n\nMétete en la mina de Catacroquer y monta una pila de explosivos en el interior.\n\nEn la entrada de la mina deberías ver algún tipo de interruptor o desatascador. Una vez armados los explosivos, utiliza el desatascador para volar el lugar por los aires. ¡Haz que sientan miedo, <clase>!Te van a lanzar el siguiente hechizo:\n\n", progress = nil, completion = nil, rewards = "Te van a lanzar el siguiente hechizo:\n\nSee Frazzlecraz Cave-In\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25185] = {title = "Ya está hecho", objective = "Vuelve con el general Trenzado en la Patrulla de Trenzado en Los Baldíos del Sur.", description = "<Te proteges la vista de la explosión y de la metralla mientras la mina vuela por los aires.>\n\n<El general Trenzado se sentiría complacido pero, de alguna manera, dudas de que se calmara su sed de venganza.>Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Yelmo de minero goblinSobrehombros de TrenzadoPodrás elegir una de estas recompensas:\n\nCollar de Plumavieja\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][25186] = {title = "Resistencia inútil", objective = "Mata a Kona Camino del Trueno en la frontera entre el Espolón y Los Baldíos del Sur.", description = "<nombre>, sin duda no quiero entregar mi informe al comandante Monotono sin un ápice de buenas noticias. Debemos recuperar el control de estos caminos de manos de la Horda.\n\nPor lo que sé, Kona Camino del Trueno es el nombre de su jefe. Tienen un campamento al norte de aquí. Es un lugareño de Espolón, conoce estos caminos como la palma de su mano. Si podemos acabar con él, la resistencia del oeste podría desaparecer.\n\nEncuentra y acaba con Kona Camino del Trueno, ¡después informa al comandante Monotono!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes de Alto del HonorFajín de MonotonoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25187] = {title = "Perdidos en el desbordamiento", objective = "Utiliza el catalejo de Thonk para buscar supervivientes en la Cuenca Furia del Sur.", description = "Los recientes sucesos del Cataclismo han hecho más que arrastrar unos pocos barcos hasta nuestra orilla, <clase>. El río Furia del Sur se ha desbordado y la cuenca oeste de Durotar está totalmente inundada.\n\nAún queda gente ahí fuera. He estado investigando un rato, pero no he conseguido encontrar nada. ¿Te importaría utilizar mi catalejo y echar un vistazo por ti mismo?", progress = nil, completion = "Ya veo... así que el truco es que necesitas poner el extremo PEQUEÑO del catalejo en el ojo. Recordaré esa información.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25188] = {title = "La patrulla de la cuenca", objective = "Investiga la Cuenca Furia del Sur y ayuda a la gente que viste por el catalejo.", description = "Mi puesto está aquí en la torre y no puedo dejarlo, <nombre>. Necesito que alguien vaya a ayudar a la gente que sigue atrapada en el desbordamiento del río.\n\n¿Puedo contar contigo?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25189] = {title = "Alabados sean los espíritus", objective = "Escolta a la gran matrona Tekla a Raggaran.", description = "¿Quién eres? ¿Qué ha pasado?\n\nEstaba sola en mi cabaña, meditando, cuando...\n\nAhh, ahora lo recuerdo. Los espíritus gritaron y el río se desbordó. Tengo suerte de que me hayas encontrado. Soy vieja y ya no tengo fuerza para soportar los elementos en este estado. ¿Me sacarás de aquí?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25190] = {title = "La ira de Raggaran", objective = "Mata 4 jabaespines Crines de Acero y 4 exploradores Crines de Acero.", description = "Los jabaespines son una mancha en la tierra que ni el río puede limpiar. Me pidieron que me evacuase, pero les dije que mi trabajo no estaba acabado.\n\n¡Arrrrgh! ¡Odio tanto los jabaespines! ¿Me ayudarás a matarlos?", progress = nil, completion = "&lt;Raggaran parece haberse calmado un poco desde tu último encuentro.&gt;\n\nBien, bien. Un paso más cerca de eliminar a esos ojos brillantes, vistecestas, nariz de cerdo, dos dedos...\n\n&lt;La ira de Raggaran vuelve a aumentar claramente.&gt;\n\n... jorobados, chillones, espinosos... nada bueno... amantes de los gnomos... ¡ARRRRRGGH! ¡Jabaespines!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25191] = {title = "Peritar la destrucción", objective = "Habla con Milo Tocamotores en Alto del Honor para peritar la destrucción del Cataclismo.", description = "He oído que se han producido grandes anomalías sísmicas aquí en Kalimdor, ¡pero nunca presentí que el caos geológico fuera tan horrible!\n\nNecesito un estudio actualizado de la destrucción mientras me quedo aquí analizando las lecturas sismográficas. ¿Podrías reunir algunos datos con mi sistema de estudio automatizado? Yo me encargaré del transporte aéreo.\n\nCuando el peritaje esté completado, presenta los datos a mi colega Horton Coracardán en Fuerte del Norte.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25192] = {title = "La furia de Raggaran", objective = "Mata 5 polvorosos Crines de Acero y 5 guardias de batalla Crines de Acero.", description = "¡No descansaré hasta que los hayamos derrotado! ¡Mátalos a todos!\n\n<Raggaran toma un respiro.>\n\n¡Sus apestosas guaridas están al norte... o al suroeste!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Aguijón de jabaespínLeotardos de pellejo de jabaespínRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25193] = {title = "Perdido, pero no olvidado", objective = "Consigue 250 dientes de crocolisco.", description = "Hoy es el aniversario de la desaparición de mi hijo Kron. Me costó reconocerlo, pero por fin he conseguido admitirlo: Kron no volverá de su caza de crocoliscos.\n\nHe estado trabajando en un proyecto... algo que sirva de recordatorio de la pasión de Kron por la caza. Un collar de dientes de crocolisco... Filas y filas de dientes que solo podrá lucir el más valiente de los jóvenes orcos. Lo colocaré en su tumba.\n\nKron era valiente, pero no era fuerte como tú. ¿Me traerías los dientes para mi collar?Recibirás:\n\n", progress = nil, completion = nil, rewards = "Jubón tejido a manoCinturón bordado con amorGuerrera de celebraciónRecibirás:\n\nBolsa de caza nueva de Kron"}
MultiLanguageQuestData['mx'][25194] = {title = "Visitantes inesperados", objective = "Ataca a 3 zancudos de llanura díscolos hasta que huyan a los Baldíos.", description = "No te preocupes, Zen'Taji no da problemas. Solo ha eh'tao eh'tudiando lo que pasa cuando se desborda el río.\n\n¿Ves los grandes pájaros verdes posaos en la ribera del río? Zen'Taji cree que tienen problemas. El terremoto y la inundación echaron a los zancudos a eh'te lao del agua; no pueden volver volando y tienen demasiao miedo de nadar.\n\nMorirán si se quedan aquí. A Zen'Taji no le gusta la violencia, pero puede que TÚ puedas atacarlos pa asustarlos y que escapen al otro lado. ¿A que sí?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25195] = {title = "Este es el final de ese raptor", objective = "Mata al raptor llamado Gritotajo.", description = "Muchas criaturas murieron cuando el agua se abalanzó sobre el valle. Sin embargo, los raptores resih'tieron. Son predadores inteligentes y llevan mucho tiempo viviendo de la deh'gracia de las otras criaturas.\n\nUno de los raptores es particularmente cruel. ¡Está matando a los animales pequeños y dejando que se pudran en el agua sin ni siquiera comérselos! Se llama Gritotajo y si no tenemos cuidao podría romper gravemente el equilibrio de la naturaleza.\n\nViaja al norte, mátalo y devuelve su cuerpo a la naturaleza.", progress = nil, completion = "Zen'Taji piensa que algo le sucedió a Gritotajo cuando llegó el Cataclismo. No siempre fue tan violento e irracional.\n\nGracias por tu ayuda, &lt;nombre&gt;. Zen'Taji volverá ahora a su eh'tudio.", rewards = "Recibirás:\n\nCapa de Zen'Taji"}
MultiLanguageQuestData['mx'][25196] = {title = "El Bloqueo Dranosh'ar", objective = "Preséntate ante Gor el agente en el Bloqueo Dranosh'ar en Durotar.", description = "Deberías dirigirte al norte de aquí, <nombre>. Habla con Gor el agente en El Bloqueo Dranosh'ar. Está a cargo de asegurar las vías de navegación a Orgrimmar y Roca del Cráneo está justo al lado de su precioso muelle. Estoy seguro de que estará interesado en seguir donde lo dejamos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25197] = {title = "El almirante no se echa atrás", objective = "Preséntate ante el almirante Aubrey en Fuerte del Norte en Los Baldíos del Sur.", description = "¿Qué? ¿Quieres quedarte a luchar? Típico de <un/una> <clase>... siempre quieren quedarse y combatir a la Horda mientras tengan la posibilidad.\n\nMira, si de verdad quieres salvar Fuerte del Norte, deberías informar al almirante Aubrey en la torre que hay detrás de mí. Ha ordenado que sus barcos se queden a luchar en vez de evacuarnos a todos tal y como le rogué.\n\nAhora, si me disculpas, ¡tengo que terminar de hacer las maletas!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25198] = {title = "Winnoa Bosque de Pinos", objective = "Habla con Winnoa Bosque de Pinos en Punta Vendetta, en Los Baldíos del Sur.Tras haber conseguido grandes logros, sería una tragedia que parte de la corrupción hubiera pasado inadvertida. Los pasillos de las Cuevas de los Lamentos se extienden por todos los Baldíos y, si otra gota de energía salvaje hubiera conseguido salir a la superficie...\n\nSin embargo, ya has hecho bastante por mí. Solo te pediré que informes a una camarada druida de lo que ha ocurrido. Encontrarás a Winnoa Bosque de Pinos en los Campos de Sangre, al suroeste.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", description = "Tras haber conseguido grandes logros, sería una tragedia que parte de la corrupción hubiera pasado inadvertida. Los pasillos de las Cuevas de los Lamentos se extienden por todos los Baldíos y, si otra gota de energía salvaje hubiera conseguido salir a la superficie...\n\nSin embargo, ya has hecho bastante por mí. Solo te pediré que informes a una camarada druida de lo que ha ocurrido. Encontrarás a Winnoa Bosque de Pinos en los Campos de Sangre, al suroeste.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25205] = {title = "El lobo y el kodo", objective = "Escucha la historia con moraleja de Shin Columnapétrea.", description = "Mi \"asociado\" aquí presente tiene algunos planes para ti con los que no estoy de acuerdo. Sus acciones son precipitadas, descontroladas e irresponsables y tú podrías acabar pagando con tu vida.\n\nAntes de trabajar con Gor, escucha la historia que te voy a contar. Es una historia con moraleja, una fábula, pero creo que será una lección valiosa. Habla conmigo cuando estés <listo/lista>.", progress = nil, completion = "La moraleja de la historia: las actuaciones fáciles y precipitadas tienen resultados terribles. Debemos evitar los atajos... debemos trabajar por nuestras recompensas. He intentado contarle esta historia al \"Agente\", pero creo que su calavera adoradora de Grito de Guerra es demasiado cerrada.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25206] = {title = "Ignorando las advertencias", objective = "Destruye 12 elementales enfrentados. Puedes matar o bien guardias de tierra furiosos o guardias acuáticos prolíficos.", description = "Ignora al chamán, soldado. Ciertas personas poderosas de la Horda me exigen que lo mantenga a mi lado, pero te aseguro que ese clarividente que ama tanto a Thrall no ve más allá de los bordes de esta cabaña.\n\nLos elementales luchan entre ellos al oeste de aquí. Normalmente no me importaría, pero necesito esa tierra despejada para asegurar una ruta de envíos más amplia hasta y desde Los Baldíos. Los elementales son bastante fuertes normalmente, pero están debilitados por los ataques entre ellos. Utiliza ese conocimiento para destruirlos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Bandas casquivanasBotines descuidadosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25208] = {title = "Díselo a Silvia", objective = "Habla con Silvia en la Torre de Estulan.", description = "Parece que hemos encontrado una infestación mucho peor de la que esperábamos. Sin duda, Cho'gall está intentando utilizar a los Gordok para acceder a los restos de Eldre'thalas en el interior de La Masacre, con todos los poderes prohibidos que supusieron la caída de los Shen'dralar...\n\nNo consigo centrarme. Déjame, <nombre>. Cuéntale a Silvia lo que has averiguado. Debemos detener lo que sea que esté ocurriendo en La Masacre.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25209] = {title = "La amenaza Gordunni", objective = "Mata a 16 ogros Gordunni en las Altas Tierras Salvajes.", description = "En el interior de las Altas Tierras Salvajes, hacia el sur, hay infinidad de ruinas antiguas. Allí fue donde los ancestros de los elfos de la noche flirtearon con la Magia Arcana, y por allí mismo merodean ahora los ogros Gordunni, en busca de restos.\n\nObservarás que el bosque está completamente destruido en esa zona; el único rastro que dejan los ogros es mera mugre, lo que impide a la Horda obtener recursos valiosos.\n\nVe a matar a los Gordunni que encuentres allí, <nombre>. ¡Asegura la zona para la Horda, y solo para la Horda!", progress = nil, completion = "Demostraste que eres un aliado confiable, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25210] = {title = "Signos de cambio", objective = "Reúne 8 cornamentas de venados infectados.", description = "Una grave enfermedad ha recaído sobre las criaturas de este bosque. Al principio tenía la esperanza de que formase parte del curso de la naturaleza, pero no desaparece.\n\nLos venados del bosque que normalmente son fuertes y serenos, son los que más han sufrido. Unos han quedado completamente debilitados, otros escupen espuma presos de la rabia. Si pretendo consultar a los espíritus sobre esta enfermedad, necesitaré las cornamentas de los venados.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25211] = {title = "Limpiando las ruinas", objective = "Mata a 5 orcos Faucedraco en Dun Algaz.", description = "No escuches a Rharen, está como un cencerro. ¡Nos robaron la cerveza por su culpa!\n\nEs más, me imagino que habrá un problema mayor que el del robo de la cerveza. ¡El hecho de que una panda de orcos se pasee por Dun Algaz después de tanto tiempo es ridículo!\n\nTe contaré el plan, <clase>. Dirígete allí y asegúrate de expulsar de esas ruinas a todos los orcos que puedas. Para muchos, Dun Algaz ya no es lo que era pero, que me parta un rayo si les dejamos campar a sus anchas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25222] = {title = "Cuenca de Marea Argenta", objective = "Busca a Felora Coronafuego en la cuenca de Marea Argenta.", description = "La mayoría de los otros miembros del Anillo de la Tierra que escaparon a la masacre de los botes se han refugiado en una cueva que está a un momento nadando hacia abajo desde la cresta. Está a medio camino hacia arriba en una gran formación rocosa, al oeste de Nespirah, la concha gigante que hay en el horizonte. Necesito que te asegures de que están bien. No hay forma de saber cuántos nagas les habrán atacado.\n\nVoy a perseguir a ese señor de las profundidades. Ya te avisaré si encuentro la roca bajo la que se esconde.", progress = nil, completion = "¡Una cara amiga! ¡Bienvenido!\n\nQué amable por tu parte el que hayas venido a ver cómo nos va. Estamos bien. Nos encontró una fuerza de reconocimiento naga, pero estoy completamente segura de que ninguno escapó. Por ahora, deberíamos estar a salvo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25223] = {title = "Prueba de fuego", objective = "Derrota a 8 instructores ígneos.", description = "Me encantaría poder decir que ahora que la batalla se pone complicada para nuestra facción en Hyjal, cada uno de los reclutas es una ayuda para la causa y todo eso... pero la pura verdad es que la mayoría de ustedes no son más que una carga.\n\nSi tuviese una moneda por cada campesino asustado que huyó despavorido cuando sufrimos el Cataclismo y que ahora quiere unirse a nuestro bando... bueno, digamos que sería rica.\n\nPor suerte tenemos pruebas para separar la paja del trigo. Ve a demostrar lo que vales a los instructores ígneos más abajo. Esperemos que lo hagas mejor que los demás.", progress = nil, completion = "Supongo que tus habilidades son... aceptables. Estoy impresionada.", rewards = "Peto de expectativas excepcionalesGrebas impresionantesPodrás elegir una de estas recompensas:\n\nDardo Colafuego\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][25224] = {title = "En flor", objective = "Obtén 5 flores de llamas.", description = "Es costumbre enviar a los nuevos reclutas a realizar tareas realmente difíciles, incluso imposibles. A mí me enviaron a obtener una escama de dragón negro; el instructor del año pasado pidió una pluma de fénix.\n\nLos de tu grupo lo tienen relativamente fácil. Encuéntrame un puñado de flores de llamas.\n\nCrecen en esta zona con cierta abundancia. Ah, sí. Habrá un gigantesco can del Núcleo merodeando por los campos para darle un poco de emoción a la cosa. Haz lo posible por evitarlo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25227] = {title = "Thonk", objective = "Preséntate ante Thonk en la torre de vigilancia al noroeste de Cerrotajo.", description = "<¡Vaya, cielo, acabo de recordarlo!/Lo siento si he sido borde contigo. A veces me pongo un poco celosa cuando llegan nuevas mujeres a la ciudad> ya que me siento un poco insegura sobre mi apariencia.;\n\nMi MUY buen amigo Thonk trabaja en la torre de vigilancia de ese acantilado, al noroeste de Cerrotajo. Dijo algo sobre un río que se desbordó, mucho trabajo que hacer y esas cosas. En realidad no estaba prestando atención... Estaba mirando a sus profundos ojos castaños.\n\n<¿Qué, no podemos ver a otras personas?/Gracias.>Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25229] = {title = "Algunos gnomos buenos", objective = "Recluta ciudadanos gnomos de la Ciudad Manitas haciendo uso del Motivatrón y dirígelos al capitán Tread Chispaboquilla en el Almacén de Brasacerada.", description = "Nuestros ingenieros han estado trabajando para tener nuestras máquinas de guerra listas para el asalto a Gnomeregan, ¡pero no nos quedan pilotos!\n\nHemos creado un dispositivo llamado Motivatrón, que evita cualquier tipo de distracción de otras fuentes y da al gnomo el valor de alistarse.\n\nCuando hayas motivado a unos cuantos ciudadanos gnomos, dirígelos al capitán Tread Chispaboquilla en el Almacén de Brasacerada, al sur de Forjaz.\n\nAh, ten cuidado, el dispositivo aún está en fase experimental.\nRecibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25230] = {title = "Más que una enfermedad", objective = "Mata a 10 crías nocivas.", description = "Hemos encontrado una camada de crías de dragón cerca del camino hacia el norte, y sufren la misma enfermedad que los venados.\n\nLos dragones Verdes no son meras bestias de la naturaleza, son los mismísimos guardianes de las tierras salvajes. Son criaturas mágicas, y comprobar que ellos también enferman supone que esta es una amenaza muy peligrosa.\n\nTenemos que evitar a toda costa que esto se extienda aún más. Asesina a las crías infectadas, <nombre>, y vuelve conmigo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Bastón de Tótem de runaVelo esmeraldaGuardahombros de cría verdeMalla de anillas de KonuRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25232] = {title = "El Filo Ardiente", objective = "Consigue 6 pergaminos de hechizos del Filo Ardiente de los miembros del Filo Ardiente en la Cueva Viento Seco.", description = "Me han enviado para investigar la presencia de más agentes del Filo Ardiente en Durotar. Al noreste, encontrarás una cueva en que la organización entrena a sus nuevos reclutas. Estoy interesado en lo que le enseñan exactamente a esos neófitos.\n\nSolo te digo esto porque parece que buscas trabajo. Si estás interesado en conseguir unas monedas, saquea la cueva y trae sus pergaminos de hechizos.\n\nLa cueva está algo escondida: sal de Cerrotajo desde el este y sigue la colina del este del cañón.", progress = "¡Los pergaminos, <nombre>, los pergaminos!", completion = "Esto es bastante interesante. Estos ritos no son tan diferentes de los hechizos que se enseña a los brujos de la Horda. ¡Esto merece seguir investigando!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25233] = {title = "Fin de la línea de suministros", objective = "Asesina a 4 proveditores Crepusculares en la Senda del Lobo en Hyjal.", description = "Los proveditores Crepusculares de Cho'gall hacen un juramento de sangre por el que se comprometen a llevar los suministros hasta el frente, y prometen un kilo de su propia carne a cambio de cada kilo de suministros que no consigan entregar. Prefieren morir antes que fracasar.\n\nAsegúrate de que hagan ambas cosas.", progress = nil, completion = "¡Bien hecho! El caos que sembremos aquí, tendrá consecuencias hasta en lo más alto de su cadena de mando.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25234] = {title = "En retaguardia con los suministros", objective = "Reúne 36 suministros Crepusculares de los que abandonan los esclavos Crepusculares.", description = "Los prisioneros del Martillo Crepuscular son obligados a cargar con los artículos necesarios para la batalla, como si fuesen bestias de carga. Quiero esos suministros, y si entretanto podemos liberar a unas cuantas almas de las terribles garras del Martillo Crepuscular, mucho mejor.\n\nMata a los explotadores que hay por la carretera del sur y los esclavos de las inmediaciones huirán.\n\nBusca entre los paquetes que dejen atrás, recoge todo lo que encuentres de valor, y destruye todo aquello con lo que no puedas cargar.", progress = "¿Has causado un poco de conmoción ahí fuera, <nombre>?", completion = "&lt;Jadi abre de una patada uno de los cajones y coge una daga curvada de su interior. Inmediatamente se estremece de dolor.&gt;\n\n¡Ay! ¡Maldito, este metal está maldito, muerde!\n\n&lt;Al caer al suelo, la daga se rompe en mil pedazos, como si fuese de cristal.&gt;\n\n¿Qué tipo de absurda artesanía es esta? &lt;nombre&gt;, nunca me he enfrentado a un enemigo como este.", rewards = "Leotardos con escritura a mano oxidadosFaja Crepuscular de nueva funcionalidadPodrás elegir una de estas recompensas:\n\nSello Dienteafilado\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][25235] = {title = "El vulgar Vul'Gol", objective = "Mata a 15 ogros Puñastilla cualesquiera.", description = "Salve, <clase>. ¿Te importaría echar una mano al pueblo de Villa Oscura?\n\nExiste un enorme túmulo ogro bajando por esa colina de ahí. Los ogros Puñastilla normalmente rehúyen a los demás, pero se han malacostumbrado a atacar a los viajeros. El otro día, vi a uno llevarse a rastras al caballo de un pobre hombre para comérselo... ¡tuvo suerte de que no se lo llevara a él!\n\nLa Guardia Nocturna arriesgará las vidas de sus escasos miembros para detener más amenazas inminentes, y yo me incluyo. Pero si matas a algunos de esos ogros por mí, te pagaré por ello.", progress = nil, completion = "Te he visto derribar a algunos desde aquí. Buen trabajo.\n\nAquí tienes tu recompensa en nombre de la Guardia Nocturna.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25236] = {title = "Un trueno desde el fondo", objective = "Fija una soga de tejido mágico a 8 truenagartos ahogados en el Monte del Trueno.", description = "Nuestro ejército necesita agua y, por suerte, los elementos nos dieron un montón con el Cataclismo. El agua que llenó el cañón del suroeste debería servirnos.\n\nPor desgracia, aún yacen cadáveres de truenagartos en la parte inferior del cañón y sus descargas eléctricas son demasiado peligrosas. Tengo toscos que pueden sacarlos del agua, pero necesito a alguien ágil que ate el otro extremo de la cuerda. ¿Cuento contigo, <nombre>?", progress = nil, completion = "La electricidad era solo uno de los peligros. Si esos cadáveres se pudren demasiado bajo el agua, toda dejará de ser potable.\n\nBien hecho, &lt;clase&gt;.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25237] = {title = "Lágrimas de piedra", objective = "Reúne 7 lacrilitos.", description = "Tú <mismo/misma> has sido testigo, Ysondre nos ha dicho que las lágrimas de la tierra pueden sellar el portal del que emana esta corrupción.\n\nHace semanas, en el claro del oeste, observé la angustia de los gigantes monteses. La frustración les consumía y lloraban, y sus lágrimas caían sobre las rocas en forma de brillantes cristales.\n\nA pesar de que los gigantes ya no lloran, seguramente Ysondre se refería a esos lacrilitos; una fuente de la pureza natural. Tenemos que reunirlos.", progress = "Las lágrimas se encuentran entre las rocas sobre las que los mismísimos gigantes se yerguen. Tiene que haber varias sueltas cerca de la base de esos enormes monolitos.", completion = "Gracias de nuevo, &lt;nombre&gt;. Prepararé estos para nuestra tarea final.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25240] = {title = "El camino del poderío", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nSortija Cinérea de poderío sin igual"}
MultiLanguageQuestData['mx'][25241] = {title = "La tierra, corrupta", objective = "Mata a 7 gigantes del risco corruptos.", description = "Los gigantes del risco de Feralas son extensiones de la propia tierra, <nombre>. Cuando la naturaleza florece son protectores benévolos y guardianes pacíficos.\n\nPero ahora que el bosque está contaminado, también ellos lo están.\n\nSi la corrupción se ha extendido hasta ellos, azotarán a la fauna y a los de su propia especie, provocando la destrucción. Tienes que destruir a todos los gigantes corruptos con los que te encuentres.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25247] = {title = "Cambio de opinión", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nSortija Cinérea de sabiduríaSortija Cinérea de destrucciónSortija Cinérea de corajeSortija Cinérea de venganza"}
MultiLanguageQuestData['mx'][25248] = {title = "Cambio de opinión", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nSortija Cinérea de sabiduría superiorSortija Cinérea de destrucción superiorSortija Cinérea de coraje superiorSortija Cinérea de venganza superior"}
MultiLanguageQuestData['mx'][25250] = {title = "Sellar Rama Oniria", objective = "Usa la lágrima de Ysondre para sellar el portal en Rama Oniria.", description = "Está lista. Coge esto, <nombre>; fuente de esencia natural, bendecida por Ysondre.\n\nHacia el este, al otro lado del arroyo, está Rama Oniria. Allí se encuentra El Gran Árbol, el más alto de Feralas, un retoño del mismísimo Árbol del Mundo. En su tronco se halla un portal hacia el corazón del Sueño Esmeralda, y este portal es el que debes sellar.\n\nEl portal estará vigilado, tienes que ser valiente. Que la Madre Tierra te proteja.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Togas de Rama OniriaCinturón de esencia naturalRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25252] = {title = "Dirigentes de La Masacre", objective = "Mata a 6 agentes Gordok y a 6 magos ogros Gordok.", description = "Ahora que se la hemos devuelto en las ruinas, ha llegado el momento de atacar a los ogros en su propio territorio.\n\nLos Gordok son la \"clase alta\" del clan Gordunni, los elegidos para defender La Masacre. Sabrán que vamos en serio en cuanto comencemos a eliminar a sus miembros más fuertes.\n\nNada de florituras aquí, <nombre>. Sencillamente sal ahí y ponte a romper cráneos de Gordok.", progress = nil, completion = "¡Excelente! Incluso estos estúpidos comprenderán pronto que enfrentarse a la Horda significa la muerte.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25255] = {title = "Hostigar a los cazadores", objective = "Mata a 6 cazadores Crepusculares en Senda del Lobo en el Monte Hyjal.", description = "El Martillo Crepuscular se ha revelado como algo más que un mero culto. Son una máquina de guerra, una plaga de langostas que avanzan hacia la cima de la montaña, devorando todo lo que se encuentran en su camino.\n\nLas partes del bosque que no han arrasado con fuego, están siendo limpiadas de toda vida para alimentar a los cultores mortales.\n\nTenemos que detener a los cazadores que operan en Senda del Lobo, no solo para preservar la poca fauna que quede sino para obligar a los cultores a marchar con los estómagos vacíos. Busca por el sur de aquí, y por el camino que hay al este.", progress = nil, completion = "Gracias, &lt;nombre&gt;. Temo que nuestras acciones aquí no sean suficientes, y que lleguen demasiado tarde; pero la naturaleza siempre encuentra sorprendentes modos de reconstruirse.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25256] = {title = "Enviado a buscar ayuda", objective = "Preséntate ante Dientepincho en Costa de Mortojo en Durotar.", description = "Tú, <raza>, espera un momento.\n\nMi jefe, Dientepincho, me envió a buscar ayuda y suministros. No parece que seas un mercader, pero es probable que puedas ayudarle. Está al sureste de aquí, junto al carro estrellado. Ah y dile que yo te envío... Quiero asegurarme de que sepa que no estoy vagueando aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25257] = {title = "Ghislania", objective = "Derrota a Ghislania en un combate.", description = "Poseo un par de gladiadores a los que meto en competiciones por todo Kalimdor. Puedes ver a la mayoría encadenados por aquí... tuvimos suerte de atrapar a estos después de que se rompiese el carro.\n\nGhislania, esa naga de ahí... ha perdido sus tres últimas peleas. No le vendría mal un entrenamiento, incluso unos golpes. Ve a desafiarla, apuesto a que incluso TÚ eres más fuerte que ella.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25258] = {title = "Griswold Hanniston", objective = "Derrota a Griswold Hanniston en un combate.", description = "Griswold, encadenado arriba, en el barranco, es mi nuevo gladiador. Lo encontramos al sur de aquí, merodeando con soldados de Fuerte del Norte. Hice que mis hombres le echaran el guante y ahora trabaja para mí.\n\nParece bastante duro, pero aún no lo hemos probado en una batalla de verdad. Ve a pelear con él para ver si merece la pena tenerlo por aquí.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25259] = {title = "Gaur Hielocuerno", objective = "Derrota a Gaur Hielocuerno en un combate.", description = "Normalmente no tendría a un taunka cautivo debido a su relación cercana con la Horda... pero este es un traidor y un criminal al que castigar. Exiliado por su propia tribu, escapó en canoa hasta Azshara y lo encontraron robando suministros de Valormok. Habría muerto bajo una hacha si yo no hubiese estado al cargo, con la cartera en la mano.\n\nGaur es mi gladiador más exitoso, <clase>. Te apuesto 10 de plata a que no eres capaz de derrotarlo.", progress = nil, completion = "De acuerdo, aquí está el dinero... pero mejor sal de mi vista antes de que reconsidere mi política sobre tener esclavos de la Horda.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25260] = {title = "Fracasado", objective = "Consigue el orbe de Fizzle de Fizzle Garra Oscura en el Monte del Trueno.", description = "La inundación del suroeste arrasó uno de los pocos campamentos del Filo Ardiente que aún infectan Durotar. Este estaba liderado por un goblin llamado Fizzle Garra Oscura y créeme, estamos mejor sin él.\n\nSin embargo, Garra Oscura poseía un orbe en el que está interesado la Horda. Quién sabe por qué... le dejo eso a los brujos. Lo único que sé es que necesito ese orbe.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Guantes DéspotaGuantes de FizzleRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25261] = {title = "Margoz", objective = "Habla con Margoz.", description = "Uno de nuestros chamanes más útiles, Margoz, sabe más sobre la corrupción del Filo Ardiente. Habla de una cueva llamada Roca del Cráneo de las montañas, justo en el exterior de Orgrimmar, que esconde a una gran banda de cultores Filo Ardiente.\n\nAntes de partir a Roca del Cráneo, habla con Margoz. Él es sabio y su consejo es muy valioso.\n\nEstá acampado al sureste, entre la costa y el Barranco Árido.\n\nSigue su consejo, pero <nombre>, diga lo que diga Margoz, ¡sigo queriendo que aplastes a esos cultores!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25262] = {title = "Roca del Cráneo", objective = "Reúne 6 collares abrasadores de los cultores de Roca del Cráneo.", description = "<nombre>, el Filo Ardiente ha infestado la cueva que hay al este de Orgrimmar, Roca del Cráneo. En esa cueva celebran sus inmundos rituales y queman su propia carne con collares abrasadores.\n\nCreo que usando esos collares, los cultores entran en sintonía con los poderes demoníacos. Pero para confirmarlo, necesito estudiar esos collares.\n\nVe a Roca del Cráneo y recoge los collares abrasadores que lleven los cultores. Tráemelos y yo descubriré su secreto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Zapatillas de cultor del filoBrazales abrasadoresCinturón de Roca del CráneoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25263] = {title = "Neeru Hojafuego", objective = "Lleva un collar de muestra a Neeru Hojafuego a Orgrimmar.", description = "Los collares abrasadores que me trajiste son potentes instrumentos demoníacos. Pero me temo que discernir su origen está más allá de mis habilidades chamánicas. Necesitamos que los estudie un brujo.\n\nLleva un collar abrasador a Neeru Hojafuego. Es un brujo muy capacitado que dice que utiliza sus poderes contra los demonios. Asegura que sus investigaciones de lo oculto son beneficiosas. Sea esto cierto o no, creo que necesitaremos su ayuda para luchar contra el culto demoníaco de Durotar.\n\nEncontrarás a Neeru en Orgrimmar, en el Circo de las Sombras.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25264] = {title = "Ak'Zeloth", objective = "Habla con Ak'Zeloth en la Avanzada del Puente en Los Baldíos del Norte.", description = "Desde la última Gran Guerra, aquella en la que la Legión Ardiente fue derrotada, he buscado fuentes de corrupción demoníaca entre los orcos. El collar que me has traído confirma mis temores.\n\nPertenece al Filo Ardiente.\n\nTu tarea está casi completa, <nombre>. Ve a la Avanzada del Puente, hacia el oeste en la frontera de Los Baldíos y habla con mi ayudante, Ak'Zeloth. Pásale esta información.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25266] = {title = "El emisario del Jefe de Guerra", objective = "Entrega el paquete lacrado al leal Kor'kron en los muelles de la Bahía de Garrafilada, en Durotar.", description = "Los goblins y los orcos han conseguido muchos triunfos juntos como para dividirse ahora, <clase>. Me gustaría que el Cártel Pantoque se uniera a la Horda.\n\nQuiero que le entregues algo al nuevo Jefe de Guerra. Ofrécele este paquete a mi amigo Kor'kron en el muelle de la Bahía de Garrafilada, en Durotar. Él te ayudará a entrar en Orgrimmar sin peligro.\n\nHabla con Sassy Malallave en el barco cuando estés <listo/lista> para zarpar.\n\nHasta la próxima, <nombre>. Aka'Magosh, ¡una bendición para ti y para los tuyos!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25267] = {title = "Un mensaje para Garrosh", objective = "Entrega el emblema de IV:7 a Garrosh Grito Infernal en el Fuerte Grommash en Orgrimmar.", description = "<El leal Kor'kron abre el paquete y palpa un objeto mientras lee una carta que hay dentro. Cuando termina de leer la nota de Thrall, se le dibuja una sonrisa que muestra sus colmillos.>\n\nTienes que entrar en Orgrimmar y entregarle esto directamente al Jefe de Guerra Grito Infernal. Asegúrate de que Garrosh sepa que es de parte de Thrall.\n\nTen mi huargo de batalla. Aprisa pequeño goblin, ¡no hay tiempo que perder!Aprenderás:\n\n", progress = nil, completion = nil, rewards = "Bastón del inoportunoFaja de servidumbreArnés de vínculoAprenderás:\n\nHobgoblin de bolsillo\n\nTe van a lanzar el siguiente hechizo:\n\nHobgoblin de bolsillo\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][25268] = {title = "La voz de Goldrinn", objective = "Localiza a Ian Duran cerca del Santuario de Goldrinn en Hyjal.", description = "Al suroeste de aquí se encuentra el Santuario de Goldrinn, un monumento erigido en honor al espíritu del lobo ancestro y a su contribución durante la Guerra de los Ancestros.\n\nNuestros nuevos aliados huargen, inspirados por la memoria del dios lobo —¡imagínate!— están limpiando el santuario.\n\nHace días que no sé nada de mi contacto, Ian Duran. ¿Puedes volar hasta allí y encontrarlo? Tengo el presentimiento de que el Santuario de Goldrinn está en peligro...", progress = nil, completion = "¿Has venido a rescatarme, &lt;clase&gt;? ¡Gracias!\n\nNo, no, no te preocupes por la jaula por ahora. Mi vida no es importante. Primero tenemos que salvar el santuario.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25271] = {title = "La ferocidad de Goldrinn", objective = "Hazte con 6 muestras de incienso corrupto.", description = "Las bestias que ves aquí ya no son mis hermanos de Gilneas. Han sido corrompidos por algún tipo de locura, y se han apoderado del santuario.\n\nVinieron cuando el Martillo Crepuscular llegó a Hyjal, y aúllan el nombre de alguna distorsión blasfema de nuestro amado Goldrinn. Olvídate de mí... acaba con esos bárbaros antes de que sigan profanando el santuario.\n\nCuando los mates, busca el incienso que llevan consigo y tráeme algunas muestras.", progress = "A otros huargen, al igual que a mí, les atrajo la historia de Goldrinn, de su fuerza y de su sabiduría. Pero estos bárbaros adoran un aspecto completamente diferente del dios lobo.", completion = "&lt;Ian examina el incienso.&gt;\n\nTal y como sospechaba. Estos componentes tienen la marca del Martillo Crepuscular. Y mira: el nombre \"Lycanthoth\". Creo que los usan en rituales de invocación...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25273] = {title = "Lycanthoth el corruptor", objective = "Usa el incienso de Lycanthoth en el interior de Fauces de Lycanthoth en Hyjal para invocar y matar a Lycanthoth.", description = "Creo que empiezo a comprender lo que está pasando aquí. El Martillo Crepuscular teme que los ancestros se levanten un día contra ellos. Harían lo que fuera para evitar el regreso de Goldrinn.\n\nEse \"Lycanthoth\" es una versión retorcida de nuestro adorado dios lobo, invocado por el Martillo Crepuscular para reemplazarlo.\n\n¡Bah! No es más que la sombra del poder de Goldrinn. <nombre>, mata a esa bestia para que el auténtico ancestro pueda regresar. Coge este incienso, y quémalo en Fauces de Lycanthoth, al este de aquí. ¡Asesina a esa bestia y libera a Goldrinn!", progress = "Tu valentía resulta inspiradora para los demás, <clase>. Dime cómo te llamas.", completion = "Has sido muy valiente al enfrentarte a Lycanthoth, &lt;nombre&gt;. Al igual que yo, era una fuerza primigenia de la naturaleza... pero sus orígenes eran más oscuros.\n\nLos que dieron a luz a esa bestia se introdujeron en las profundidades de la negrura y canalizaron poderes que nunca debieron habitar este mundo.\n\nVen, &lt;clase&gt;. Súbete a mi espalda, ¡y enseñémosles a estas bestias el verdadero rostro de la ferocidad!", rewards = "Faja de fuerza primigeniaGarras del espíritu huargenPodrás elegir una de estas recompensas:\n\nGuardapelo de Goldrinn\n\nTe van a lanzar el siguiente hechizo:\n\nForce Player to Ride Goldrinn\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][25274] = {title = "Firmado con sangre", objective = "Atrae a un recluta Crepuscular lejos del grupo y quítale sus papeles de reclutamiento Crepusculares.", description = "Por fin has llegado, <nombre>. Y además justo a tiempo.\n\nLa noticia de la aparición de Ragnaros ha sido un acicate para que oleadas de reclutas traten de formar parte del Martillo Crepuscular.\n\nSi pretendes infiltrarte en el culto, este es el momento. Necesitaremos los papeles de reclutamiento, firmados con sangre por el miembro Crepuscular de referencia. Atrae a uno de los nuevos reclutas lejos del grupo y golpéalo con esta porra.\n\nSi tienes suerte, podrás robarle sus papeles de reclutamiento. Tráemelos y haremos lo posible para manipularlos.", progress = "¿Has conseguido los papeles?", completion = "Excelente. Haré lo que pueda para alterar estos documentos.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25275] = {title = "Informa al jefe de personal", objective = "Preséntate ante el jefe de personal Grabbit en la Puerta Trasera de Orgrimmar, en Azshara.", description = "Tu pueblo está ocupado con la transformación del paisaje de Azshara. ¡Rediseñaremos la tierra a imagen y semejanza de la Horda para que todos sepan que Kalimdor es nuestro!\n\nAtraviesa la ciudad en dirección norte. En la parte alejada del Valle del Honor, encontrarás la Puerta Trasera de Orgrimmar. Informa al jefe de personal Grabbit fuera de las puertas, goblin.\n\n¡¡¡Por la Horda!!!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25276] = {title = "Tu nueva identidad", objective = "Habla con Condenna la Incompasiva en el campo de entrenamiento en Hyjal.", description = "Ahí está. No es mi mejor trabajo, pero tampoco el peor. Los cultores te conocerán como \"<nombre>damus\".\n\nEstos papeles te permitirán adelantarte a los otros reclutas, de modo que podrás hablar directamente con los instructores Crepusculares.\n\nVe al terreno de pruebas y enséñale esto a Condenna la Incompasiva. Ella se encarga de separar la paja del trigo.\n\nDemuéstrale de lo que estás <hecho/hecha>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25278] = {title = "Limpiar la casa", objective = "Mata cualquier combinación de 8 toscos de la Casucha o taumaturgos umbríos de la Casucha en el interior de la Casucha de Gar'gol en Hyjal.", description = "Gracias a tus esfuerzos es posible que pronto podamos recuperar la antigua gloria de este santuario. Pero antes tenemos que asegurar este valle. Al sur de aquí, un grupo de ogros liderado por Gar'gol ha establecido un campamento en una casucha apestosa.\n\nNo es que Gar'gol sea una auténtica amenaza, pero sí que es un enorme obstáculo carnoso que han colocado en nuestro camino para distraer nuestra atención del auténtico peligro. Sea como fuere, tenemos que ocuparnos de él y de sus asesinos a sueldo.\n\n¡Mata a los secuaces de Gar'gol en el nombre de Goldrinn!", progress = nil, completion = "Realmente has limpiado la zona, ¿verdad? ¡Bien hecho!\n\nLos elfos de la noche me contaron una vez la historia de cómo Goldrinn se enfrentó y mató a un señor del terror, mientras otros tres, aferrados a sus flancos, le quemaban la piel. Me pregunto si tú o yo tendremos algún día la fortaleza para hacer eso.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25280] = {title = "El santuario recuperado", objective = "Vuelve con Ian Duran en el recuperado Santuario de Goldrinn en Hyjal.", description = "Sí, <nombre>. Soy Goldrinn. Tu persistencia frente al miedo me ha liberado de las garras Crepusculares.\n\nMi santuario está purificado y mis seguidores han vuelto al lugar que les corresponde, a mi pezuña derecha.\n\nVuelve con Ian y continúa con tu trabajo en Hyjal. Pronto te volveré a necesitar.", progress = nil, completion = "¡&lt;nombre&gt;, ha sido impresionante! El mismísimo Goldrinn apareció para liberarnos, su piel blanca brillaba como la luna en verano. Mi jaula se rompió y los bárbaros se derritieron como cera bajo la caricia de sus garras. Era hermoso, &lt;nombre&gt;. ¡Muy hermoso!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25281] = {title = "Cadena de favores", objective = "Utiliza la caracola encantada para rescatar a 6 soldados sumidos.", description = "Ahora puedes moverte libremente por este reino sin miedo de ahogarte.\n\nAquí es donde empieza tu labor.\n\nEn primer lugar, hay muchos aliados cerca que se están ahogando mientras hablamos. Igual que yo te he salvado, debes salvarlos.\n\nHe encantado la concha que me trajiste. Utilízala para rescatar a tus amigos.\n\n¡Date prisa!", progress = nil, completion = "Mientras estabas fuera, pude reanimar a algunos de los soldados caídos.\n\nNecesitaremos toda la ayuda posible si queremos sobrevivir en este lugar.", rewards = "Te van a lanzar el siguiente hechizo:\n\nAlliance Pay It Forward See Inv\n\nRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25283] = {title = "Preparar el discurso", objective = "Utiliza el dispositivo de reproducción gnómico delante de Ozzie Voltiflop al norte de Kharanos, Milli Plumasilba en el Almacén de Brasacerada y Tog Oxidentado fuera de la posada de Kharanos. Vuelve con Toby Relogiro cuando hayas dado todos los discursos.", description = "El manitas Mayor Mekkatorque me ha pedido que escriba un discurso para que pueda darlo antes del comienzo de la batalla, pero ya no sé qué discurso es bueno y cuál apesta.\n\n¿Crees que podrías probarlos con algunos de los residentes gnomos locales? Este dispositivo crea una imagen de Mekkatorque que pronuncia algunas líneas de cada uno de mis discursos.\n\nDime cuál de ellos funciona, ¿de acuerdo?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25284] = {title = "Alimentar el miedo", objective = "Mata a 5 celadores de la torre. Utiliza las cuerdas de al lado de Holgom para entrar y salir rápidamente de Alto del Honor.", description = "Nuestros recursos son limitados, <clase>, pero eso no significa que no podamos causar algunas molestias ahí abajo. Utiliza las cuerdas para descender por la ladera de la colina y mata a los celadores de la prisión humanos.\n\nMatar a unos cuantos celadores escuálidos no inclinará la balanza de la batalla, pero imagina el miedo y el caos que sembraremos cuando los humanos descubran los cuerpos mutilados...\n\n<Holgom sonríe con un brillo en la mirada y mostrando su dentadura amarillenta.>", progress = nil, completion = "Bien, bien. Aún les quedan muchas noches en vela hasta descubrir de dónde salimos y adónde fuimos tras la matanza...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25291] = {title = "Entrenamiento Crepuscular", objective = "Habla con la instructora Mylva en Hyjal.", description = "Has demostrado que mereces participar al menos en nuestro entrenamiento más básico.\n\nEncontrarás uno de nuestros asentamientos al este de aquí. Habla allí con la instructora Mylva.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25292] = {title = "Los más allegados", objective = "Llévale el proyectil enano a Alto Picopiedra en el Poblado Murohelecho en el Marjal Revolcafango.", description = "<Nato te lleva aparte y te habla en susurros.>\n\n<nombre>, le he sacado la bala a Gann del pecho, pero las burbujas de su sangre lo dicen todo. Tiene los pulmones perforados y la herida se está infectando. Pronto dejará este mundo.\n\nToma esto. Es la bala que lo mató. Su familia querrá saber lo que le ha ocurrido a su guerrero más joven.\n\nBusca a Alto Picopiedra. Está destinado en el Marjal Revolcafango. Ve al noreste y sigue los caminos que llevan al Poblado Murohelecho.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25294] = {title = "Paseando al perro", objective = "Reúne 5 piezas de carne de basilisco carbonizada y alimenta al engendro de Arderos.", description = "Mmmm... Parece que hoy en día dejan entrar a cualquiera.\n\nMuy bien. Sin duda has conocido a Arderos en el terreno de pruebas.\n\nBien, me han encargado el cuidado de uno de sus cachorros. Todo un machote, si al crecer se parece en algo a su padre, servirá bien a nuestra causa.\n\nReúne carne de basilisco de los de la zona para alimentarle con ella.", progress = nil, completion = "Excelente. Este pequeño cachorro crecerá y se volverá fuerte y despiadado como su padre.", rewards = "Te van a lanzar el siguiente hechizo:\n\nDespawn Spawn of Smolderos [INTERNAL]\n\nRecibirás:\n\nObjeto #5Objeto #1"}
MultiLanguageQuestData['mx'][25296] = {title = "Reúne información", objective = "Obtén el comunicado Crepuscular y los planes de batalla de Hyjal.", description = "¡Soy yo, <nombre>, Ortell!\n\nNo mires directamente a la letrina... o descubrirás mi posición.\n\n¿Entonces todo va según lo planeado? ¡Excelente!\n\nVoy a necesitar que consigas algo de información mientras estás aquí. Puede que no parezca gran cosa hacerse con un mapa o una carta, pero si conseguimos anticipar el próximo movimiento de nuestros enemigos podríamos salvar cientos de vidas en nuestra facción.", progress = "¿Has conseguido los documentos, <nombre>?", completion = "Un trabajo excelente, &lt;nombre&gt;. ¿O debería decir: \"&lt;nombre&gt;\"damus?\n\nDame un momento para leer esto.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25297] = {title = "De las fauces de la locura", objective = "Reúne cetraria, agriflor y un ascua de Flama Oscura.", description = "Conozco un jarabe que debería devolver a estos desorientados esclavos a la realidad. Reúne un poco de cetraria de las rocas que rodean la Casucha de Gar'gol, un poco de agriflor de la orilla del lago cercano y un ascua de Flama Oscura de uno de los blandones de la entrada de la Casucha. El efecto del jarabe no durará mucho, así que mezcla los ingredientes en un caldero Crepuscular a la entrada de la Casucha.\n\nUn trago de ese jarabe debería devolver la cordura a los esclavos a los que les han lavado el cerebro.", progress = "<El asqueroso líquido del caldero empieza a burbujear.>", completion = "&lt;Tiras al suelo el contenido del caldero, que acaba al instante con toda la vida vegetal que toca.&gt;\n\n&lt;El jarabe que has preparado en su lugar hierve a buen ritmo y apesta a repollo. Apartas la cara y lo embotellas.&gt;", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25298] = {title = "Libera tu mente, lo demás viene solo", objective = "Habla con 8 servidores Crepusculares para administrarles el jarabe y salvarlos.", description = "<Rio dijo que el jarabe no sería efectivo durante mucho tiempo.>\n\n<Será mejor que entres rápidamente en la casucha y se lo administres a tantos servidores Crepusculares como seas capaz de encontrar.>", progress = "¿Ha funcionado el jarabe?", completion = "¡Excelente! Esperemos que el daño no sea permanente.\n\nA juzgar por las pobres víctimas que siguen en el campamento, el Martillo Crepuscular ha hecho de las suyas con sus cerebros.", rewards = "Borgoñota ingrataBufas purificadorasRompeatadurasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25299] = {title = "Entrenamiento mental: El camino de la verdad hacia el poder", objective = "Usa el orbe de Ascensión y responde a 10 preguntas correctamente.", description = "Puede que creas que estás <preparado/preparada> para recibir los conocimientos que vamos a impartirte. Pero no lo estás.\n\nPiensa en tu cerebro como si fuese una caja en el interior de otra serie de cajas.\n\nCada paso de tu instrucción abrirá una de esas cajas, hasta que estés <listo/lista> para alcanzar la comunión directa con los elementos.\n\nToma el orbe de Ascensión y responde a todas las preguntas que te haga con sinceridad. Si no lo haces, las consecuencias podrían ser... fatales.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25300] = {title = "El Ojo del Crepúsculo", objective = "Busca el Ojo del Crepúsculo en la entrada de la Casucha de Gar'gol en Hyjal.", description = "El clan de ogros del otro lado del lago está liderado por Gar'gol. Yo diría que sin mucho rigor; Gar'gol tiene la inteligencia de un pedazo de carne cruda.\n\nPor lo que yo sé, Gar'gol recibe órdenes de un instrumento mágico: \"el Ojo del Crepúsculo\". Sigue sus órdenes sin cuestionarlas.\n\nSi somos capaces de sabotear el Ojo, podremos causar una auténtica conmoción.\n\nVe a la Casucha de Gar'gol y busca el Ojo del Crepúsculo cerca de la entrada. Estúdialo. Y encuentra la manera de subvertirlo. Ah, el caos, qué maravilla...", progress = nil, completion = "&lt;Te acercas al Ojo del Crepúsculo. A medida que acercas los dedos hacia su superficie luminosa, percibes una presencia maligna que te observa, que rebusca en tu alma.&gt;\n\n&lt;Instintivamente, retrocedes.&gt;", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25301] = {title = "Manejar marionetas", objective = "Localiza El Apócrifo Crepuscular en el interior de la Casucha de Gar'gol en Hyjal.", description = "<Durante tu breve comunión con el Ojo, percibiste que su poder surgía de lo más profundo de la casucha. Sentiste el peso de un poderoso libro que unía cuatro elementos.>\n\n<Para dominar el Ojo, tendrás que registrar la casucha en busca de ese libro.>", progress = nil, completion = "&lt;Un pesado libro encuadernado en piel se encuentra abierto sobre la mesa.&gt;\n\n&lt;El idioma, pictográfico y garabateado con tinta del color del óxido, te resulta indescifrable, pero descubres notas y traducciones en algunas páginas. Debe de tratarse de lo que estabas buscando.&gt;", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25303] = {title = "¡Elemental!", objective = "Activa los cuatro crisoles elementales que hay cerca, en el orden correcto, para tomar el control del Ojo del Crepúsculo.", description = "<No sabes leer el texto, pero los diagramas parecen indicar que los artefactos de tu alrededor deben activarse en un orden determinado.>\n\n<Un pasaje de El Apócrifo está traducido a lenguaje moderno:>\n\n   Al comienzo estaba la sombra eterna.\n   El odio ardía y nació el FUEGO.\n   Las heridas se cicatrizaron, y surgió la TIERRA.\n   Los gritos de angustia dieron a luz al VIENTO.\n   Y los cielos derramaron mares de LÁGRIMAS.\n      Vivimos en la sombra,\n      el mundo que conocemos fue\n   construido a partir de rabia, dolor, angustia y sufrimiento.", progress = "<Estudias cuidadosamente El Apócrifo para tratar de comprenderlo.>", completion = "&lt;En concordancia con los elementales capturados, te pones delante de El Apócrifo Crepuscular. Las páginas se pasan solas.&gt;\n\n&lt;De pronto, ves lo que ve el Ojo. ¡Está a tus órdenes!&gt;", rewards = "Faja de Gar'golCoselete de inescrutabilidadAtaduras apocríficasTe van a lanzar el siguiente hechizo:\n\nHacer ogros Gar'gol amistosos\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25304] = {title = "La batalla de Sardor", objective = "Habla con Tambre en la Isla de Sardor.", description = "Hemos perdido nuestro asentamiento en la Isla de Sardor contra los nagas Crestafuria. Nos superaban en número y tuvimos que retirarnos al continente. Mientras disfrutaban de su recién adquirido banco de arena, nosotros levantamos Nuevo Plumaluna en la orilla y reunimos un ejército todavía mayor.\n\nAhora, los Crestafuria volverán al mar. Busca a nuestro Anciano de la guerra en la costa. Te llevará a las primeras líneas, en las que Tambre lidera la ofensiva.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25305] = {title = "Nunca mires atrás", objective = "Mata a 10 naga Crestafuria y asesina a su líder.", description = "Hemos perdido nuestro asentamiento en la Isla de Sardor contra los nagas Crestafuria. Nos superaban en número y tuvimos que retirarnos al continente. Mientras disfrutaban de su recién adquirido banco de arena, nosotros levantamos Nuevo Plumaluna en la orilla y reunimos un ejército aún mayor.\n\nAhora, los Crestafuria volverán al mar. Habla con la centinela Ranadae para unirte a nuestras fuerzas en Sardor. Asesina a los nagas, y asegúrate de que la serpiente asquerosa de la que reciben las órdenes también desaparezca del mapa.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][25306] = {title = "¡Gnome digas que estás en el ejército!", objective = "[ph] Log Description", description = "[ph] War!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][25308] = {title = "Semillas de discordia", objective = "Distrae a Karr'gonn y asesina al Sumo cultor Azennios en el Trono de los Elegidos en Hyjal.", description = "Según la información que conseguiste, existe un roce enorme entre los ogros y el resto de razas en el interior del culto.\n\nEl Sumo cultor Azennios y el ogro mago Karr'gonn se reunirán en el Trono de los Elegidos para intentar suavizar el conflicto.\n\nEn el Trono de los Elegidos hay una letrina como esta. Ve para allá y ponte este disfraz de ogro. Encuentra la manera de matar a Azennios mientras realiza esta misión de paz.\n\n¡Tenemos que aprovechar esas diferencias todo lo que podamos!", progress = nil, completion = "¡Un trabajo excelente, &lt;nombre&gt;! Esta vez, te has superado.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25309] = {title = "Entrenamiento espiritual: La compasión es para los débiles", objective = "Mata a 5 suplicantes suspendidos en Vigilia de la Fatalidad.", description = "Has conseguido llegar hasta aquí. Otros no lo consiguieron.\n\nVe a Vigilia de la Fatalidad, justo al norte de aquí. Hemos reunido a todos los... fracasados. Quiero que nos ayudes a hacernos cargo de ellos. Será positivo para tu crecimiento espiritual.\n\nSi este acto despiadado te da problemas, piensa en él como su segunda oportunidad. Si alguno de ellos consigue matarte... conseguirá tu puesto.", progress = nil, completion = "Avanzas a pasos agigantados hacia el éxito. Esperemos que no lo estropees con nociones absurdas como la compasión o la humanidad.\n\nVenga, ven. Hablemos de tu futuro.", rewards = "Coselete de la promoción rápidaCinturón de Fracaso prestoBrazal desechado de suplicanteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25310] = {title = "El mayor de dos males", objective = "Usa el dije de ascendencia de llama y asesina a Garnoth, Puño de la Legión, en las Puertas de Sothann en Hyjal.", description = "Les arrebatamos a la fuerza Garganta Negro Rumor a los demonios de la Legión Ardiente. Hasta el momento mantenemos bien nuestro territorio, con una única excepción.\n\nHace poco perdimos las Puertas de Sothann contra un señor del foso y su ejército. No podemos permitir que eso siga así.\n\nUsa este dije cuando estés cerca de él. Obtendrás temporalmente los poderes de un ascendiente de llamas. Sácales buen partido.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25311] = {title = "Territorio Crepuscular", objective = "Asesina a 10 horroguardias en las Puertas de Sothann en Hyjal.", description = "Los demonios de la Legión Ardiente creen que pueden venir aquí y hacerse con el territorio que les venga en gana. Es cierto, el territorio era suyo en un principio, pero ese no es el tema.\n\nLes enseñaremos a no meterse en los asuntos del Martillo Crepuscular.\n\nDirígete a las Puertas de Sothann y arrasa el contingente de horroguardias que merodean por la zona.", progress = nil, completion = "Efectivo como siempre. No me decepcionas.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25312] = {title = "Vuelve con Susurro del Anochecer", objective = "Vuelve con Royce Susurro del Amanecer en el Santuario de Goldrinn en Hyjal.", description = "<Introduces tu propia imagen en el Ojo por la fuerza y lo manipulas para que les dé a los ogros órdenes diferentes. Mientras lo haces, puedes sentir otra presencia en el interior del Ojo que te explora en busca de algún punto débil. Un ser distante invadido de ira. ¡Hoy te has ganado más de un enemigo!>\n\n<Tu trabajo aquí está hecho. Vuelve con Royce Susurro del Amanecer en el Santuario de Goldrinn y explícale lo que has conseguido.>", progress = nil, completion = "Hola, ¿sí? ¿Qué? ¿Tú? Ah, eres uno de los que mandé tras el Ojo del Crepúsculo, ¿verdad?\n\nBuen trabajo, muy bien. Supongo que se extrae una valiosa lección:\n\nNo recibir nunca órdenes de una gran bola púrpura.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25314] = {title = "Redacción de discursos para principiantes", objective = "Mata a Okrog en el exterior del Trono de los Elegidos en Hyjal.", description = "Escucha, <nombre>. He descubierto lo que van a hacer con Jarod Cantosombrío. Los ogros del Martillo Crepuscular pretenden sacrificarlo en su ritual de iniciación de este año.\n\nHe oído que el iniciado encargado de dar el discurso previo al sacrificio es un ogro llamado Okrog, pero escucha esto: tú eres la segunda opción.\n\nNecesitamos que des ese discurso si queremos liberar a Jarod. No te preocupes, te escribiré unas notas a modo de chuleta, tú solo asegúrate de que Okrog tenga un \"accidente\" cuando salga del Trono de los Elegidos.", progress = nil, completion = "Un trabajo excelente, &lt;nombre&gt;. Nuestros planes están a punto de hacerse realidad.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25315] = {title = "Discurso de graduación", objective = "Usa el podio de iniciación en Vigilia de la Fatalidad para dar el discurso de graduación.", description = "Por fin estás <preparado/preparada>, <nombre>damus.\n\nEstoy muy orgullosa de ti y de todo lo que has conseguido.\n\nHoy darás un discurso ante tus compañeros y les inspirarás para que destrocen a nuestro enemigo hasta que Hyjal no sea más que un montón de cenizas.\n\nRecuerda, <nombre>damus. Lo mejor es interpretar las emociones de tu audiencia y emplear las palabras que mejor encajen con esas emociones.", progress = "¿Has venido a acabar conmigo?\n\nNo... parece que estás... cuerdo.", completion = "Tú. Claramente no estás con ellos.\n\n¿Un aliado tal vez?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25316] = {title = "Mientras Hyjal arde", objective = "Vuela hasta Hyjal usando a Aronus y habla con Ysera cuando llegues allí.", description = "¡<nombre>! Hemos oído hablar mucho de ti y de tus logros pasados.\n\nMenos mal que has venido en este momento, Azeroth se enfrenta a momentos de gran necesidad.\n\nLos secuaces de Alamuerte están atacando Hyjal y pretenden devolver a nuestro mundo al destructivo Ragnaros.\n\nAronus te llevará para que te unas a las fuerzas de Malfurion en Hyjal. Ayúdalos todo lo que puedas.", progress = nil, completion = "&lt;Ysera parece estar en una especie de trance.&gt;", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25317] = {title = "Protege el Árbol del Mundo", objective = "Habla con Malfurion Tempestira en la Arboleda Tranquila, en Monte Hyjal.", description = "<Los ojos de Ysera parecen distantes, como si no captase completamente tu presencia.>\n\nYo también lo percibo, <clase>. Ragnaros ha llegado.\n\nTenemos que derrotar a sus secuaces antes de que se reúnan con él para entregarles su fuerza.\n\nBusca a Malfurion Tempestira en la Arboleda Tranquila, al oeste de aquí, y ayuda a sus fuerzas todo lo que puedas.\n\nYo debo buscar una respuesta en el Sueño Esmeralda. Debes proteger el Árbol del Mundo hasta que yo vuelva.", progress = nil, completion = "Llegas justo a tiempo, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25319] = {title = "Guerra contra el Martillo Crepuscular", objective = "Mata a 4 clamallamas Crepusculares y a 10 vencedores Crepusculares.", description = "No te equivoques, <nombre>. Del resultado de esta guerra depende la supervivencia de nuestro mundo tal y como lo conocemos.\n\nEl Martillo Crepuscular es más poderoso que nunca desde el regreso de Alamuerte. Si consiguen apoderarse del Árbol del Mundo, podrían asestar un golpe del que nunca nos recuperaríamos.\n\nHa llegado el momento de que le devolvamos el golpe al enemigo. Ya es hora de que aplastemos al Martillo Crepuscular.", progress = nil, completion = "Lo has hecho bien, &lt;nombre&gt;. Pero temo que la batalla está aún muy lejos de su final.", rewards = "Placa de guardián druídicoYelmo de señor de la NaturalezaBáculo Crepuscular de nueva funcionalidadTrabuco del frenteRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25320] = {title = "La exploradora capturada", objective = "Encuentra a la exploradora Larandia en el Puesto de Mando Crepuscular, en Monte Hyjal.", description = "He oído hablar de ti, <nombre>, y de las noticias que trajiste del sur. Hemos llegado a un punto muerto en la batalla.\n\nY temo que el equilibrio se rompa con el nuevo despertar del Señor del Fuego.\n\nA no ser, por supuesto, que podamos inclinar la balanza a nuestro favor de alguna manera.\n\nEl Martillo Crepuscular capturó a una exploradora. Creo que tenía importante información en su poder. Búscala en los campamentos del Martillo Crepuscular, al oeste.", progress = nil, completion = "¡Por fin ha llegado la ayuda!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25321] = {title = "Cautiverio Crepuscular", objective = "Obtén una llave de sobrestante Crepuscular en el Puesto de Mando Crepuscular, en Hyjal.", description = "Llevaba casi un día explorando tras las líneas enemigas cuando me cazaron.\n\nEste ataque a nuestras primeras líneas no es lo que parece, <nombre>.\n\nTe daré todos los detalles, pero primero tenemos que encontrar la manera de sacarme de aquí.\n\nSolo los sobrestantes llevan las llaves de las jaulas.\n\nSi mal no recuerdo, están en mitad del cráter, en plena acción.\n\nMira a ver si consigues una llave de alguno de ellos.", progress = "La llave, <nombre>. ¿La has conseguido?", completion = "Te lo agradezco, &lt;nombre&gt;. Informaré a nuestro pueblo de mis averiguaciones.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25323] = {title = "Divisor de llamas", objective = "Mata a 30 espíritus flameantes desatados.", description = "Los grandes elementales que nos asedian no son una entidad singular.\n\nSon una amalgama de espíritus menores unidos gracias a la magia de los cultores del Martillo Crepuscular.\n\nEl bastón de vidente de llamas reconstruido nos dará suficiente poder como para debilitar esas uniones.\n\nEncárgate de los elementales menores una vez rotos los más grandes y peligrosos.", progress = nil, completion = "Bien hecho, &lt;nombre&gt;. Esto nos ayudará a cambiar el curso de la batalla contra el enemigo.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25324] = {title = "Un prisionero interesante", objective = "Habla con la capitana Saynna Corretormenta en los Túmulos, en Hyjal.", description = "¿El Martillo Crepuscular quiere liberar a Fandral Corzocelada?\n\nMalfurion sospechaba que su corrupción era profunda... esto lo corrobora.\n\nNo podemos permitir que nuestros enemigos pongan sus manos en un archidruida tan poderoso.\n\nTengo un plan, <nombre>. Trasladaremos al prisionero a través del Sueño Esmeralda. Será peligroso, pero con todos los cultores que hay aquí, es posible que sea la única manera de tener éxito.\n\nHabla con Saynna Corretormenta en el interior de los Túmulos, al noreste.", progress = nil, completion = "Es posible que la dragona tenga razón. El Martillo Crepuscular ha roto nuestras defensas y este es nuestro prisionero más peligroso.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25325] = {title = "A través del sueño", objective = "Lleva al archidruida Fandral Corzocelada con Alysra en la entrada de los Túmulos en Hyjal.", description = "Es posible que el plan de Alysra sea necesario, <nombre>. No sé cuánto tiempo más seremos capaces de retener a los cultores.\n\nFandral Corzocelada está sometido a poderosos hechizos. No podrá escapar de ti, ni siquiera en el interior del Sueño Esmeralda.\n\nPero ten cuidado, hasta donde sabemos, la pesadilla se ha extendido hasta esta parte del mundo en el interior del sueño.\n\nSaca a Fandral a la superficie y entrégaselo a Alysra. Esperemos que esté más seguro en el Claro de la Luna que aquí.", progress = nil, completion = "Lo has hecho bien, &lt;nombre&gt;. Yo me encargaré de llevar a Fandral al Claro de la Luna.\n\nAllí su prisión estará lo bastante alejada del campo de batalla.", rewards = "Mandiletes de encarcelamiento ArcanoCaperuza amortiguadoraDaga desgarrasueñosTe van a lanzar el siguiente hechizo:\n\nCue Fandral to Despawn\n\nRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25328] = {title = "Gar'gol tiene que largarse", objective = "Coge la llave calavera oxidada de la arqueta personal de Gar'gol.", description = "<Kristoff estira el cuello, tratando de mirarte a los ojos.>\n\nEscucha, tienes que sacarme de aquí. Si no, intentarán comerme o hacerme del Martillo Crepuscular. Incluso puede que ambas cosas.\n\nMe han encadenado, y Gar'gol guarda la llave en su arqueta personal. Mata a Gar'gol si es necesario, ¡pero consigue esa llave!\n\n<Kristoff sacude sus extremidades en vano.>", progress = "¿La llave? ¿Ahora? ¿Por favor?", completion = "&lt;Kristoff se estira para alcanzar la llave.&gt;\n\n¡Ya era hora!\n\n&lt;Se retuerce entre sus cadenas, tratando de alcanzar el candado que tiene a su espalda.&gt;\n\n... ¿Qué tal un poco de ayuda por aquí?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25329] = {title = "El poder de los Quebrantarrocas", objective = "Interrumpe el sermón crepuscular de Cho'Gall.", description = "¿Así que el Martillo Crepuscular cree que puede reunir su propio ejército de ogros en este lugar? ¿En mitad del territorio de la Horda? \n\nEso ya lo veremos.\n\nLos ogros solo respetan una cosa: la fuerza. Quiero que lideres el asalto contra el sermón de Cho'gall, <nombre>. Revienta las puertas de La Masacre, entra en la arena y elimina a sus seguidores.", progress = nil, completion = "¡Lo hemos hecho! Has humillado terriblemente a Cho'gall. Sus secuaces están muertos, los Gordok se han dispersado, ¡y ahora todos conocerán el poder de la Horda! Lok'tar, &lt;nombre&gt;. Has hecho méritos más que suficientes para ganarte tu recompensa.", rewards = "Lanzador QuebrantarrocasGuantes agarrasermonesAlmófar de ogroRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25330] = {title = "Carne desperdiciada", objective = "Usa el cristal vendaval helado para extinguir las llamas de 4 suplicantes inmolados.", description = "Mira a esos estúpidos. La mitad de ellos ni siquiera superarán esta prueba.\n\nNo merecen ascender a nuestros círculos internos. Pero tal vez... tal vez sirvan para realizar servicios de poca importancia.\n\nCoge esta gema y utiliza su poder para salvar a algunos de los suplicantes menos competentes. Algunos que no tengan ninguna opción de conseguirlo. Algunos que estén ya ardiendo, a ser posible.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25332] = {title = "¡Sácame de aquí!", objective = "Escolta a Kristoff hasta el exterior de la Casucha de Gar'gol.", description = "<Te acercas para desatar las cadenas de Kristoff.>\n\n¡Bien! Ábrete camino hasta la salida y te seguiré.\n\nSi nos separamos, vuelve aquí de nuevo para comprobar que no me han vuelto a capturar.", progress = nil, completion = "Kristoff, Kristoff... Ah sí, ahora me acuerdo. Recuerdo haberle enviado a una misión prácticamente suicida.\n\n¿Ha sobrevivido? Supongo que eso significa que ha fracasado.\n\nAun así te mereces unas monedas por las molestias.", rewards = "Guardahombros de la memoria vacíaEscarpines desatendidosCaperuza de sueños perdidosRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25336] = {title = "Probar la vasija", objective = "Mata a 10 osos Cueracero o corredores Dientelargo, y usa la vasija de muisek de bestia para reducir y capturar a las bestias caídas.", description = "El maestro Uzer'i me enseñó la forma de hacer armas espirituales de gran poder. Te ayudaré a que comiences a hacer algunas, y así tendré la oportunidad de practicar mi arte.\n\nEsta vasija puede reducir y capturar en su interior a una criatura derrotada. Primero necesitaremos el muisek de las bestias: osos Cueracero y lobos Dientelargo. Mátalos, y usa la vasija de muisek para reducirlos y capturarlos antes de que su espíritu escape.", progress = "¿Has conseguido muisek de bestia?", completion = "Como me dijo el maestro...\n\nAnte una muerte violenta, el muisek de una criatura puede escapar y buscar venganza. Reducir a las criaturas, tal como tú lo has hecho, &lt;nombre&gt;, evita que el muisek escape. ¡Ahora podremos usarlo como queramos!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25337] = {title = "Muisek de hipogrifo", objective = "Acaba con 10 hipogrifos Plumavieja de cualquier tipo y utiliza la vasija de muisek para encogerlos y capturarlos.", description = "El siguiente paso son los hipogrifos.\n\nComo decía siempre el maestro Uzeri: los hipogrifos han sido compañeros leales de los elfos de la noche durante muchos años, y sus espíritus son leales y firmes.\n\nNo creo que echen de menos a unos pocos, y la verdad es que si lo hacen me da igual. Necesitamos el muisek de 10 hipogrifos Plumavieja en las tierras salvajes del sur.", progress = "¿Lograste capturar a los hipogrifos?", completion = "El maestro decía siempre: \"después de matar a un animal, si permitimos que se escape el muisek, es posible que tome la forma de una criatura incluso mayor.\" Esto es peligroso. Gracias por ayudarme con mis estudios.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25338] = {title = "Muisek de antárbol", objective = "Mata a 3 caminabosques deambulantes. Utiliza la vasija de muisek de antárbol para reducir y capturar a los antárboles caídos.", description = "Los caminabosques deambulantes que vagan por el bosque son nuestro siguiente objetivo, <nombre>. Los elfos de la noche se han aliado con los antárboles para combatir a la Horda. Se mueven con lentitud, pero su papel como protectores es innegable.\n\nPronto podremos usar ese poder en nuestro beneficio.\n\nEncuentra a tres caminabosques deambulantes, mátalos y utiliza la vasija de muisek para reducirlos y capturarlos.", progress = "¿Lograste capturar a los caminabosques deambulantes?", completion = "Gracias, &lt;nombre&gt;. Es la primera vez que trabajo con muisek de antárboles...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25339] = {title = "Venganza contra Nortearroyo", objective = "Mata a 6 arpías Nortearroyo y a 6 clamavientos Nortearroyo.", description = "En mis tiempos fui un avezado cazador. No había criatura a la que temiera. Hasta que...\n\nUn día estaba en el bosque, afilando mi espada después de una dura batalla, cuando me tendieron una emboscada. Unas arpías me rodearon y apenas pude ponerme a salvo.\n\nTodavía puedo oír el eco de sus gritos...\n\nDespués de aso, no he vuelto a ser el mismo. Pasaron muchos años, pero el odio todavía hacer hervir mi sangre. Debo vengarme.\n\nLas arpías de Nortearroyo se encuentran al oeste de aquí. Véngame, <nombre>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25340] = {title = "Corazón oscuro", objective = "Mata a Edana Garfaodio y obtén el corazón oscuro de Edana.", description = "Edana Garfaodio es la reina de las arpías de Nortearroyo que viven en las ruinas del oeste. Es el mal encarnado. He oído que su corazón es de cristal. Carece de sentimientos... aparte del odio que siente por todo lo que no sea ella. Debes enfrentarte a Edana y traerme su corazón oscuro.\n\nHe oído hablar de un cuerno que llevan esas arpías... Si lo tocan en las Piedras Garfaodio, en la parte norte de las ruinas, su reina acude.\n\nImagina su sorpresa cuando vea que no son sus semejantes quienes la llaman, sino la muerte.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Pretina de cristal oscuroBrazales del corazón capturadoRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25341] = {title = "El orbe Gordunni", objective = "Recoge un orbe Gordunni de un brujo Gordunni.", description = "Mientras tú estabas por ahí destrozando cráneos...\n\nYo he recibido informes que me hacen pensar que estos ogros son algo más que la torpe amenaza de siempre. Hemos visto a sus brujos llevar orbes, probablemente objetos de potenciación.\n\nLo más fácil sería tomarlos por meras baratijas, pero tengo que asegurarme de que no haya sorpresas. Tráeme uno de esos orbes.", progress = "¿Tienes el orbe?", completion = "Bien hecho. Deja que eche un vistazo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25342] = {title = "Habla con Swar'jan", objective = "Lleva el orbe Gordunni a Swar'jan en Bastión Quebrantarrocas.", description = "En esto hemos tenido suerte y mala suerte, soldado. Suerte porque te convencí para que trajeras esto de vuelta, y mala suerte porque mis sospechas no eran infundadas. Esta cosa está llena de algo fétido y corrupto.\n\nY es demasiado nuevo como para ser algo rescatado de las ruinas. Alguien les suministra estas cosas a los ogros, y tenemos que averiguar quién es antes de que esto se vuelva peligroso.\n\nLleva esa asquerosidad arriba, a Swar'jan, el brujo de la torre vigía. Tiene buenas ideas; yo haría caso a sus sugerencias si fuese tú.", progress = "¿Sí?", completion = "¿Qué me traes aquí? ¿Y dices que los Gordunni tenían esto?\n\nAsqueroso...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25344] = {title = "Abducción de ogro", objective = "Utiliza la piedra de alma modificada para capturar a un ogro Gordok.", description = "Es imposible que los Gordunni hiciesen esto. Alguien les suministra estas cosas. Alguien les está dando regalos de poder, y tenemos que averiguar quién es.\n\nLos Gordok de la clase alta que vigilan La Masacre sabrán más de todo esto. Sin duda Orhan te tendrá reduciendo sus números, pero yo necesito al menos uno vivo.\n\nVuelve a llevar el orbe. Es parecido a una piedra de alma, así que le he hecho unos... ajustes. Ponla delante de un ogro debilitado, y una vez capturado, tráemelo aquí.", progress = nil, completion = "Aah, percibo a ese zoquete ahí dentro. Vamos a sacarle de ahí y a hacerle unas cuantas preguntas...", rewards = "Brazales del ladrón de almasEscudo contra hechizos modificadoSobrehombros de atrapaogrosCoberturas del AbductorRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25345] = {title = "Muisek de dragón feérico", objective = "Mata a 8 duendes dardo o duendes dragón. Utiliza la vasija de muisek para reducir y capturar a los dragones feéricos caídos.", description = "<nombre>, ahora quiero que captures a una criatura que es de apariencia frágil pero que posee un espíritu poderoso, que es lo que me interesa de ella. Hablo de los dragones feéricos, unas criaturas que han servido como aliadas a los elfos de la noche. Debemos capturar uno para que la Horda pueda beneficiarse de la fuerza de su espíritu.\n\nAquí tienes la vasija, <nombre>. Mata a 8 duendes dardo o duendes dragón y captura su muisek. Puedes encontrarlos al oeste de aquí.", progress = "¿Conseguiste hacerte con el muisek de los dragones feéricos?", completion = "Gracias, &lt;nombre&gt;. Ahora tenemos los poderes espirituales del dragón feérico a nuestra disposición. \n\nEspero que aceptes una tarea más.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25346] = {title = "Muisek de gigante montés", objective = "Mata a 7 gigantes monteses. Utiliza la vasija de muisek para reducir y capturar a los gigantes monteses caídos.", description = "Los gigantes monteses dejaron las montañas para ayudar a los elfos de la noche cuando la Legión Ardiente apareció en el mundo. Los reconocerás por su enorme tamaño y por la forma en que el suelo comienza a temblar a medida que recorres su terreno rocoso.\n\nEstoy deseando dominar un poder tal. Mata a 7 gigantes monteses y después usa la vasija de muisek para capturar su poderoso muisek.", progress = "¿Lograste capturar a los gigantes monteses?", completion = "Imagina las posibilidades que nos da lo que tenemos, &lt;nombre&gt;. Con los materiales que has reunido, podré atrapar para siempre el muisek de estas criaturas y hacer con él lo que me plazca.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25349] = {title = "Hermanas retorcidas", objective = "Mata a 7 dríades corruptas.", description = "He oído hablar de tu batalla contra los dragones corruptos, <nombre>, y te agradezco tu valentía... pero traigo noticias inquietantes.\n\nLas dríades del bosque, aunque son aliadas de los elfos de la noche, siempre nos han dejado en paz. Pero ahora se han vuelto crueles y retorcidas, y atacan a todo el que merodea por las tierras salvajes del este.\n\nTemo por la seguridad de los refugiados de esta zona, <nombre>. Por favor, acaba con estas retorcidas dríades.", progress = nil, completion = "Te lo agradezco, &lt;nombre&gt;, pero la historia de tu caza me preocupa. No debería haber tantas.\n\nLa enfermedad sigue extendiéndose...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25350] = {title = "El aprendiz perdido", objective = "Busca al aprendiz perdido en las Ruinas Niebla Negra.", description = "Si tienes un momento, <clase>...\n\nUno de los estudiantes bajo mi tutela se fue a explorar las Ruinas Niebla Negra, al sur, él solo. Le advertí de que era demasiado peligroso, pero estaba demasiado emocionado como para escucharme. Antes le había hablado de un amuleto oculto en las ruinas. Temo que haya salido a buscarlo por mi culpa...\n\nEstulan nos ha prohibido seguirle. Si vas allí, ¿podrías buscarle?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25352] = {title = "Limpieza de plataforma", objective = "Asesina a 8 clamatormentas Crepusculares y a 5 habitantes de falla aulladores.", description = "Has hecho un trabajo estupendo en la casucha, <nombre>. He estado rezando en el santuario mientras estabas fuera, y en mis visiones Goldrinn te vigilaba de cerca.\n\nPero llevamos a la defensiva demasiado tiempo: ha llegado el momento de enfrentarse directamente al Martillo Crepuscular.\n\nVuela hasta Saliente de Relámpagos y desbarata sus operaciones. ¡Mata a los clamatormentas y a las monstruosidades que pretenden liberar!", progress = nil, completion = "¡Tenías que haber visto la batalla desde aquí! ¡Los cadáveres caían desde el acantilado! ¡Espectacular!", rewards = "Cinturón de purificación vinculanteApisonadoras llamalobosBrazales del lobo melancólicoIra de Lo'GoshRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25353] = {title = "Relámpagos embotellados", objective = "Recoge un tarro condensador cargado de un canalizador de relámpagos Crepuscular.", description = "Mientras rezaba en el santuario, Goldrinn me concedió otra visión. Te vi a horcajadas del Saliente de Relámpagos, con relámpagos en las manos. Parece que Goldrinn lo considera de vital importancia, pero no comprendo lo que el ancestro tiene planeado...\n\n<nombre>, ve al Saliente de Relámpagos. El Martillo Crepuscular ha estado haciendo experimentos con algo llamado \"canalizador de relámpagos\". Investiga estos canalizadores y, después, usa este tótem para invocar al espíritu de Goldrinn. Así comprobaremos lo que tiene en mente...", progress = "Nos volvemos a encontrar, <clase>. Dejas un rastro de temor y confusión a tu paso.", completion = "¡De modo que es verdad! Ciertamente llevas el relámpago en tus manos.\n\nEres el elegido, &lt;nombre&gt;. Serás mi campeón, y llevarás mi venganza a reinos a los que yo no puedo acceder...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25354] = {title = "Limpieza de plataforma", objective = "Asesina a 8 clamatormentas Crepusculares y a 5 habitantes de falla aulladores.", description = "El santuario está asegurado, los ogros sumidos en la confusión. Es suficiente. Ha llegado el momento de tomar la ofensiva.\n\nAlgo siniestro se avecina desde lo alto, en el Saliente de Relámpagos. ¡Ha llegado el momento de desatar la furia de los ancestros!\n\nVuela hasta el Saliente de Relámpagos y acaba con el Martillo Crepuscular desplegado allí. ¡Destrózalos, <nombre>, asesina a sus creaciones y arroja sus cuerpos por la ladera de la montaña!", progress = nil, completion = "Impresionante, &lt;nombre&gt;. Realmente impresionante.\n\nPosees la fuerza del ancestro lobo y tienes la sabiduría necesaria para emplear bien tus poderes. Te presento mis respetos.", rewards = "Faja del lobo ancestralBotines del lobo de ensueñoBrazales de clamalobosPurificador de GoldrinnRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25356] = {title = "A la Cima", objective = "Pide prestado un jinete del viento a Shyn y habla con Kanati Nube Gris en Cima Tramo Oeste, en Las Mil Agujas.", description = "Estamos llevando a cabo una misión de socorro en Cima Tramo Oeste para toda la región de Las Mil Agujas. Shyn te prestará mi jinete del viento para que llegues a salvo hasta allí. Habla con Kanati Nube Gris cuando aterrices.\n\n¡Ve rápido por si hubiese vidas que salvar!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25357] = {title = "Consíguenos algo de tiempo", objective = "Mata a 8 asaltantes Zin'jatar.", description = "Hoy han muerto demasiados hombres buenos. Sin ti, ese número habría sido aún más alto.\n\nTienes nuestra gratitud.\n\nSi lo que dice el chamán es cierto, no hay tiempo que perder. Los nagas están peinando estas aguas en busca de supervivientes.\n\nAún no estamos listos para luchar. Tienes que ganar tiempo para que podamos hacer los preparativos. Encuentra a los nagas que vienen a por nosotros y retrasa sus esfuerzos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25360] = {title = "Clientes cangrejos", objective = "Mata a 10 cangrejos de arena verdes.", description = "Estos cangrejos no son amistosos. Nada amistosos.\n\nLa incansable perforación de Sam los está molestando. Por experiencia, sé que no hay manera de detener a Sam, así que mejor lo enfocamos desde el otro punto de vista, ¿vale?", progress = nil, completion = "¿Es que aquí abajo todo viene en tamaño familiar? Oh, es una idea. Quizás haya unos simpáticos goblins cerca, en alguna parte.\n\nGracias, por cierto.", rewards = "Apisonadoras de gran tamañoCoraza rompecangrejosLeotardos de braquiuro albinoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25361] = {title = "El lustre de una nueva capa", objective = "Lleva 10 alas de duende dardo iridiscente a Krueg Machacacráneos al Campamento Mojache.", description = "Saludos, <clase>. He viajado con mis compañeros hasta Feralas para realizar una misión para nuestros maestros de Orgrimmar.\n\nA mi compañera Korrin le encanta la ropa nueva, así que pretendo hacerle una nueva capa adornada con las delicadas alas de dragones feéricos. ¿Podrías ayudarme? Los duendes dardo con las maravillosas alas que busco están al oeste del Campamento Mojache.", progress = "Los duendes dardo pueden ser criaturas muy peligrosas si se les provoca. Ten cuidado cuando trates con ellos, <clase>. Y ten mucho más cuidado con los elfos de la noche que pueda haber por la zona. Esos molestos seres tienen por costumbre acechar en los bosques también.\n\nCuando tengas alas suficientes, dímelo. ¡Te recompensaré bien!", completion = "¡Estupendo, &lt;clase&gt;! Estas nos vienen de maravilla. Hay suficientes para hacerle la capa a Korrin, ¡incluso puede que sobren! Gracias. \n\nEspero que tu viaje no fuera demasiado peligroso. Feralas no es conocido por su compasión precisamente, pero está claro que no te ha ido tan mal. \n\nGracias otra vez, &lt;clase&gt;.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25362] = {title = "Un descubrimiento siniestro", objective = "Lleva 20 cuernos de Tótem Siniestro a Krueg Machacacráneos en el Campamento Mojache.", description = "¡El clan Tótem Siniestro! Esos traidores sin entrañas todavía merodean por este lugar, eh...\n\nTienes que volver, <clase>. Vuelve y tráeme sus cuernos... montones de ellos si puedes. A los Tótem Siniestro no hay que tomárselos a broma, ni infravalorarlos. Vuelve y mátalos; haz que los ríos de Feralas fluyan rojos con su oscura sangre.", progress = "Escucha bien lo que te digo, <clase>, el clan Tótem Siniestro es malvado. Si sabes dónde están, tienes que volver y atacarles. Tienes que asestar tú el primer golpe... antes de que vengan a nuestras tierras y arrasen nuestros poblados y saqueen nuestras tierras.", completion = "Traidores contra la Horda y traidores contra su propia gente...\n\nSupongo que algo bueno tienen que tener. Haremos unas petacas estupendas con ellos.", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25363] = {title = "En guerra con los Zarpaleña", objective = "Lleva 10 cabelleras de gnolls Zarpaleña a Hadoken Zanco Veloz al Campamento Mojache.", description = "Los gnolls... son algo más que una molestia. ¡Son una amenaza constante para este campamento! Que sean o no de Feralas es irrelevante. Si no redoblamos nuestros esfuerzos por controlarlos, acabarán por expulsarnos de la región entera.\n\nLos ataques de los gnolls al campamento se han intensificado últimamente. Necesitamos que nos ayudes a reducir su número. Tráeme 10 de sus cabelleras. Recompensaré generosamente tu esfuerzo.\n\n¡Ve!", progress = "¡Los hacemos retroceder y aun así, siguen atacando! Alguien o algo debe de estar arrastrándoles a este frenesí... Ah, <nombre>, ¿ya estás de vuelta? ¿Tienes las cabelleras necesarias para la recompensa?", completion = "Esto es un muy buen comienzo, &lt;nombre&gt;. Tu habilidad como soldado merece todos los elogios. \n\nNo solo te he encargado esta tarea a ti. Otros antes que tú han luchado contra ellos y en el pasado nuestros esfuerzos los mantuvieron a raya. Sin embargo, últimamente han redoblado sus esfuerzos por avanzar hacia el norte y entrar en nuestra zona. Además, sus ataques se han vuelto más salvajes, como si estuvieran desesperados. \n\nPero tengo un plan, &lt;nombre&gt;, que puede acabar con esto de una vez por todas.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25364] = {title = "Ataca a los Alfas", objective = "Mata a 5 alfas Zarpaleña.", description = "Por desgracia los gnolls son tan resistentes como brutos y estúpidos. He hecho retroceder a los gnolls una y otra vez de nuestro campamento, y de no ser por la piedad de nuestro gran jefe, ya los habríamos borrado del mapa por completo.\n\nA lo largo de los años, se ha convertido en una danza de fuerza y dominación. Cuando su número aumenta y amenazan el campamento, los alfas, los gnolls más fuertes, tienen que ser asesinados.\n\nDe esta forma regresan al bosque y nos dejan en paz hasta que vuelven a olvidar la lección.", progress = nil, completion = "Tú has hecho lo que te pedí y por ello te presento mis respetos. Acepta esta pequeña recompensa como premio por tus esfuerzos, &lt;nombre&gt;. \n\nAhora que sus líderes han muerto y hemos diezmado su número, se lo pensarán dos veces antes de irrumpir en el campamento. Pero eso no soluciona el problema. \n\nDebe de haber un motivo para que los gnolls hayan enloquecido. Y antes de que tengan tiempo de reagruparse, tenemos que averiguar qué es lo que causa su locura.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25365] = {title = "Investiga a los Zarpaleña", objective = "Encuentra los planes de batalla de los gnolls por los campamentos que hay al sur del Campamento Mojache.", description = "Los gnolls no son los tipos más rápidos del lugar, pero seguramente tendrán algún tipo de documentación sobre sus actividades. Si encontráramos sus planes, podríamos tener una idea más clara de lo que les está agitando tanto.\n\nQuiero que vuelvas a Zarpaleña y busques cualquier cosa que pueda parecer un plan de batalla. Tienen que tener algo: sus ataques han sido demasiado coordinados, han tenido que seguir un plan. Encuentra la documentación de sus planes y vuelve cuando la tengas.", progress = nil, completion = "Un examen del mapa revela que es el plan de ataque que quiere Hadoken Zanco Veloz. Hay muchas flechas que probablemente representan movimientos de tropas. La mayoría parecen dirigirse hacia el sur, no al norte, que es donde se encuentra el Campamento Mojache. \n\nEn otra sección del mapa hay un dibujo de lo que parece ser una especie de insecto enorme, con varias marcas debajo. Por el aspecto de los gnolls, puede que represente las bajas que esos insectos desconocidos han causado en sus filas...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25366] = {title = "Los planes de batalla", objective = "Lleva los planes de batalla de los gnolls Zarpaleña a Hadoken Zanco Veloz al Campamento Mojache.", description = "Ahora que has descubierto los planes de batalla de los gnolls, solo te queda llevárselos a Hadoken Zanco Veloz al Campamento Mojache. Quizás él o alguien de allí pueda averiguar qué están tramando los gnolls.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Botas de Zanco VelozPodrás elegir una de estas recompensas:\n\nSortija Hadoken\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][25367] = {title = "Infestación de Zukk'ash", objective = "Lleva 20 caparazones Zukk'ash a Hadoken Zanco Veloz al Campamento Mojache en Feralas.", description = "Por lo que hemos podido deducir de nuestras exploraciones, los enemigos que están al sur de los gnolls son una raza de insectos. Y francamente, me da igual que sean o no conscientes de lo que nos hacen. Si con sus actos empujan a los gnolls contra nosotros, entonces son una amenaza, como lo son los gnolls, si no peor.\n\nAdéntrate en Las Galerías Retorcidas, que es donde viven estos insectos Zukk'ash. Reduce su número y vuelve a informarme de lo que encuentres. Trae contigo sus caparazones como prueba de que has cumplido.", progress = "¿Cómo va la caza, <nombre>? ¿Has venido a informar de tu éxito?", completion = "Bien hecho, &lt;clase&gt;. Aunque los Zukk'ash están muy extendidos y no podremos librarnos de ellos sin una invasión a gran escala, nos has hecho ganar tiempo para elaborar una buena estrategia.\n\nHaré analizar estos caparazones. Tenemos que averiguar todo lo que podamos sobre ellos si queremos erradicar lo que, por desgracia, ha resultado ser un problema mucho mayor de lo que habíamos previsto.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25368] = {title = "Verinias el Retorcido", objective = "Derrota a Verinias el Retorcido.", description = "Los demás espíritus y yo estamos presos en este lugar por culpa de un cruel demonio llamado Verinias. Él es nuestro captor, una bestia retorcida y descerebrada que nos devora las almas durante milenios.\n\nEl cebo de almas y la magia Arcana que me has traído debería permitirte echarlo de aquí. Lleva esta esencia condensada al árbol muerto en el extremo norte de las ruinas. Utilízalo para atraer a Verinias y asesínalo, para que por fin sea libre...", progress = nil, completion = "¡Soy libre... por fin! Oh, es tan agradable ser libre...\n\nOh, lo has visto, ¿verdad?", rewards = "Embozo de SensiriaLeotardos retorcidosEscarpines atractivosBrazales de esencia condensadaRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25369] = {title = "Latigador con aguijón", objective = "Derrota al latigador con aguijón en Las Galerías Retorcidas y lleva sus glándulas a Hadoken Zanco Veloz al Campamento Mojache en Feralas.", description = "Uno de los exploradores que vigilaba Las Galerías Retorcidas avistó un insecto gigante, uno mucho más grande que los otros, deambulando por la zona. No solo es más grande que los demás, además parece secretar una especie de aura, cosa que los demás insectos no hacen. Le hemos dado un nombre: latigador con aguijón.\n\nNos vendría bien estudiar las tripas de esta bestia mientras intentamos averiguar cuál es la mejor manera de afrontar esta nueva amenaza. Corta sus glándulas secretoras y tráemelas de inmediato.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCaparazón cubierto de secreción"}
MultiLanguageQuestData['mx'][25370] = {title = "Instigar a los elementos", objective = "Alimenta a los dragones feéricos con bayas de enebro y asesina a 4 incitadores Crepusculares.", description = "Esto no es un mero fenómeno natural, <nombre>. Debe de haber una presencia Crepuscular tras nuestras líneas con la que no hemos contado.\n\nEs posible que quien sea que instiga la perturbación elemental utilice magia demoníaca para esconderse de nosotros.\n\nBusca la ayuda de los dragones feéricos que merodean cerca del Árbol del Mundo; ellos son capaces de ver a través de todas las ilusiones de nuestros enemigos.\n\nAliméntalos con las bayas de enebro que crecen por aquí cerca para ganarte su confianza.", progress = nil, completion = "Lo has hecho bien, &lt;nombre&gt;. ¡No podemos permitir que los espías del Martillo Crepuscular merodeen tan cerca del Árbol del Mundo!", rewards = "Recibirás:\n\nObjeto #4"}
MultiLanguageQuestData['mx'][25371] = {title = "Cabalgada abisal", objective = "Atrae y somete a un caballito de mar abisal.", description = "Si quieres llegar a alguna parte en este bosque de algas, tenemos que conseguirte una buena montura. Creo que se me ha ocurrido algo mejor que la tortuga marina y no está muy lejos.\n\nAta un cebo en la cuerda que hay justo al oeste de aquí y monta en el caballito de mar que este atraerá.\n\nQuedas advertido, tendrás que trabajar duro para someter a la bestia.", progress = "La gracia de estas criaturas es increíble. Serán las monturas perfectas.", completion = "¡Asombroso! Pareces agotado. Seguro que te ha hecho trabajar a fondo.\n\nAhora, la vida aquí abajo debería ser más fácil con una montura tan rápida a tu disposición. ¡Enhorabuena, &lt;nombre&gt;!", rewards = "Recibirás:\n\nCaballito de mar abisal subyugado"}
MultiLanguageQuestData['mx'][25372] = {title = "El milagro de Aessina", objective = "Lleva el corazón del bosque a Hamuul Tótem de Runa en la Arboleda de Aessina en Monte Hyjal.", description = "<Las ramas en forma de dedos de una de las extremidades ardientes de Nordu se mueven y dejan al descubierto una semilla iluminada intacta.>\n\nEste es el corazón del bosque. La semilla de vida.\n\nLleva esto a tu archidruida en la Arboleda de Aessina, Hamuul Tótem de Runa sabrá cómo invocar su poder. Te lo aseguro, el espíritu de la naturaleza no permanecerá en silencio. La nueva vida nacerá de las cenizas de la antigua.\n\nGracias, <raza>. Mi tiempo ha terminado.", progress = "¡Ya no sé qué más hacer, <nombre>! Aessina permanece en silencio.\n\n¿Has encontrado algo? ¿Qué es eso?", completion = "¡Esta es la clave, &lt;nombre&gt;! Con los esquejes que reuniste para mí anteriormente, los animales que salvaste en la zona de Hyjal y el corazón del bosque que acabas de descubrir, podremos regenerar estas tierras pisoteadas por el Martillo Crepuscular. Imagina su sorpresa cuando vean su trabajo neutralizado, cuando comprueben que la vida triunfa sobre el caos...\n\n¡Comenzaré la ceremonia de inmediato!", rewards = "Peto de renovación veridianaBotines de restauraciónGuantes de verdad incubadaBufas de renacerRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25373] = {title = "La amenaza de la colina", objective = "Mata a 5 guardias de cerros Gordunni.", description = "Estoy orgulloso de la reputación de Mojache de ser un remanso de seguridad en las tierras salvajes de Feralas, pero el campamento se enfrenta a muchas amenazas. Los ogros Gordunni se reúnen muy cerca, en las estribaciones del norte; reivindican su territorio y arrasan la flora y la fauna.\n\nCon la llegada de nuestros hermanos y hermanas en busca de refugio, no puedo permitir que sigan allí por más tiempo. Ve al norte y expulsa a los ogros.", progress = nil, completion = "Te lo agradezco, &lt;nombre&gt;, pero queda más trabajo por hacer para mantener el campamento a salvo. Escucha.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25374] = {title = "Avistamiento de pie grande", objective = "Mata a Puñogrande.", description = "Puede que lo hayas visto con tus propios ojos, pero mis enviados me han informado de algo que me inquieta. Los Gordunni de las colinas han capturado a un enorme pie grande de las tierras salvajes.\n\nNo sé cuánto tiempo lleva retenido, pero los ogros no se caracterizan por dedicarse a los pasatiempos. Temo que su plan sea liberar a la bestia torturada en el Campamento Mojache.\n\nVuelve a lo más profundo de la Avanzada Gordunni y asesina al pie grande, <nombre>.", progress = nil, completion = "Ahora podré descansar en paz, &lt;nombre&gt;. Has salvado nuestro campamento de una amenaza terrible.", rewards = "Calzones de pellejo de yetiCalzado grandeCapa de MojacheRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25375] = {title = "Domando a los domadores", objective = "Mata a 6 domadores Gordunni.", description = "Los Gordunni no son conocidos por domar animales. Y si están aprendiendo, resultaría alarmante. A pesar de que el pie grande que han domado es la mayor amenaza contra nuestro campamento, también tendríamos que encargarnos del Gordunni que lo capturó. Si lo dejamos, sencillamente capturarán otro.\n\nMata a los domadores Gordunni, ¡y asegúrate de que los ogros comprenden que no se tolerarán estas prácticas!", progress = nil, completion = "Bien, bien. ¡Esperemos que los ogros al menos sean lo bastante listos como para captar el mensaje!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25377] = {title = "El botín de la Horda", objective = "Debes derrotar a Akasha para obtener la llave del cofre de la Horda que debes utilizar para abrir el cofre de la Horda sumergido.", description = "No está claro qué tipo de criatura garabateó las marcas aparentemente aleatorias de este trozo de papiro pero, tras un examen a fondo, algunas de las oscuras formas comienzan a parecer lugares.\n\nAl pensar en la geografía del suelo marino, crees reconocer algunos puntos de referencia. Entre ellos, un barco hundido cercano. Si tu suposición es correcta, parece que hay algún tipo de tesoro cerca de los restos del barco.\n\nNo puedes evitar preguntarte qué será la figura escamosa y serpenteante que aparece en el mapa...", progress = "Esta cerradura ligeramente estropeada aún debería funcionar.", completion = "¡Has descubierto un tesoro perdido!\n\nLa cabeza te da vueltas al pensar en las cosas que puede haber ocultas en las profundidades del mar.", rewards = "Recibirás:\n\nRodela bioluminiscenteObjeto #1"}
MultiLanguageQuestData['mx'][25378] = {title = "La llamada de Ysondre", objective = "Habla con Ysondre en La Cumbre Esmeralda en las Bajas Tierras Salvajes.", description = "Los dragones de la naturaleza... Atiende a su llamada, <nombre>. No permanezcas más tiempo aquí. Su petición de ayuda es un gran honor para ti, pero también un terrible presagio de peligro inminente.\n\nEl lugar del que hablaba se llama La Cumbre Esmeralda. Un sendero, alejado del camino principal, que atraviesa las Bajas Tierras Salvajes lleva hasta lo alto de una de las altas mesetas rocosas; allí encontrarás un pequeño santuario.\n\nEl destino de Feralas recae completamente sobre tus hombros. Que la Madre Tierra te proteja.", progress = nil, completion = "Has venido.\n\nMe avergüenzo de tener que pedirte esto, &lt;clase&gt;, pero ya he huido de él demasiado tiempo. Hay que detener a Taerar.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25379] = {title = "La caída de Taerar", objective = "Derrota a Taerar.", description = "Emeriss y Lethon se han ido. Ya solo quedamos nosotros. Ya no puedo seguir escondiéndome. Todo lo que hice mientras formaba parte de ese linaje... todo el sufrimiento que he causado... debe repararse hoy mismo.\n\nTodavía estoy débil, <nombre>. No puedo asumir mi forma real, ni aunque me atreviese a intentarlo. Pero aun así estaré a tu lado en la batalla.\n\nSi estás <preparado/preparada>, atraeré a Taerar hasta nosotros. No podrá resistirse a la tentación de tratar de corromperme de nuevo.", progress = nil, completion = "Está hecho.\n\nEsta tierra que tanto ha sufrido puede ya descansar.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25381] = {title = "Luchar contra el fuego con... lo que sea", objective = "Asesina a 10 tormentas de fuego enfurecidas en el interior de El Averno.", description = "El Averno que arde con furia allá delante delimita la primera línea entre nuestras fuerzas y las del Señor del Fuego. Los elementales de fuego que se han liberado aquí no se parecen a ningún otro que yo haya conocido.\n\n¿Puedes ayudarnos a detener la oleada de destrucción? Asesina a las tormentas de fuego enfurecidas... antes de que devoren la Arboleda de Aessina y ¡acaben con toda esperanza de recuperar un día esta montaña!", progress = nil, completion = "Gracias, &lt;nombre&gt;. Nos has dado la oportunidad de intentar recuperar la ventaja.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25382] = {title = "Interrumpir los rituales", objective = "Mata a 6 señores del infierno Crepusculares en el interior del Inferno.", description = "Las tormentas de fuego que hay más adelante son elementales desatados en su forma más pura, algo que nunca creí que pudiera existir fuera de su propio plano. Solo los invocadores más hábiles son capaces de liberar algo así.\n\n<nombre>, dirígete a El Averno y busca a los señores del infierno Crepuscular. Seguro que están invocando refuerzos en este mismo momento. Siléncialos... ¡Para siempre!", progress = nil, completion = "¿Muertos? ¡Bien!\n\nPero parece que todavía queda mucho por hacer... fuegos que apagar... terreno que sanar...\n\n¡Espero que te quedes a nuestro lado y nos ayudes a recuperar Hyjal!", rewards = "Hojacortante de tormenta de FuegoCetro de señor de pesadillaPodrás elegir una de estas recompensas:\n\nAnillo del averno sofocado\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][25383] = {title = "La despedida de Ysondre", objective = "Habla con el Jefe Almaspina en el Campamento Mojache.", description = "Y así, soy la última que queda.\n\nAunque decidiese permanecer en este mundo, no podría reunirme con el Vuelo Verde. Pero esta victoria me da esperanza. Tal vez, con el tiempo, podré encontrar la paz llevando una vida sencilla entre los mortales.\n\nDebes volver con tu gente. Diles que los dragones pesadilla han desaparecido, y que ya no serán una amenaza para estas tierras.", progress = nil, completion = "Realmente la bendición de la Madre Tierra te acompaña, &lt;nombre&gt;, haber tenido el honor de enfrentarte con los guardianes de la naturaleza, y ¡haber sobrevivido!\n\nDebes saber que has mantenido a salvo a cada uno de los habitantes de este campamento, y posiblemente a los del bosque entero. Acepta estos regalos con mi más sentido agradecimiento.", rewards = "Podrás elegir una de estas recompensas:\n\nCadena de EmerissCadena de TaerarCadena de Lethon\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][25384] = {title = "Materias primas", objective = "Samir quiere que reúnas 3 chatarras de alquiler de orcas demenciadas en el Bosque de Algas.\n\nPuedes atraer a una orca usando entrañas de tenazario de tenazarios Chasclac.", description = "Gracias, <clase>. Te debemos la vida.\n\nPero, para poder volver a ver la superficie alguna vez, tendremos que luchar para salir de aquí. Eso significa que tendré que fabricar algunas armas y armaduras.\n\nAntes de que me encontrases, vi como una orca de las de ahí arriba se comía a un soldado.\n\nApuesto a que si abres unas cuantas en canal, encontrarás suficiente chatarra de metal como para que pueda trabajar.\n\nSi no quieres nadar hasta donde están, seguro que puedes atraer a una hacia ti con algunas entrañas...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Hombreras de caparazón de arpíaBotines de muerte decápodaTogas ligadas a abulónRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25385] = {title = "Salva a los animalitos", objective = "Ve a El Averno y rescata cualquier combinación de 10 conejitos aterrados o ardillas amedrentadas.", description = "¡Ayúdanos, <clase>! El bosque está en llamas, y los animales pequeños no son capaces de huir. No pueden luchar por sí mismos, ¡con sus pequeños colmillitos y sus suaves patitas peludas! Son blanditos y adorables.\n\n¡Tienen pequeños hocicos húmedos!\n\nSi no los salvas, no quiero ni PENSAR en lo que les ocurrirá.\n\n<Se tapa los ojos con las palmas de las manos.>\n\n¡No lo voy a pensar!", progress = "¿Salvaste a los animales pequeñitos? ¿Y a sus amiguitos?", completion = "¡Ayyyyyyyy!\n\n¿El simpático Sr. &lt;clase&gt; te sacó de las llamas, amiguito? ¡Ahora estás a salvo!\n\n¡Hurra!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25386] = {title = "A Bastión Quebrantarrocas", objective = "Habla con Orhan Hojaogra en el Bastión Quebrantarrocas.", description = "Debes informar de lo que ha ocurrido aquí, <nombre>. Hacia el sur se encuentra el Bastión Quebrantarrocas. Allí, nuestros aliados han reunido a unos cuantos ogros de la Horda para luchar contra los que arrasan el bosque.\n\nHabla con Orhan Hojaogra. Ella lidera el clan Quebrantarrocas aquí, y tiene que saber todo lo que ha ocurrido. Y ve con cuidado, no sea que quede algo de corrupción por ahí...Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25387] = {title = "A Campamento Mojache", objective = "Habla con el Jefe Almaspina en el Campamento Mojache.", description = "Has hecho un trabajo genial aquí, <nombre>. Con el Martillo Crepuscular avergonzado y los Gordunni destrozados y ensangrentados, podremos centrarnos por completo en la verdadera batalla contra la Alianza.\n\nNos llevará tiempo reunir fuerzas suficientes como para enfrentarnos a los elfos de la noche que infestan este lugar. Voy a enviarte de avanzada al Campamento Mojache, hacia el este; allí tienen sus propios problemas, y no podemos permitir que ningún territorio de la Horda caiga en esta zona.\n\n¡Lok'tar!", progress = nil, completion = "Te agradezco que hayas venido, &lt;clase&gt;. Nuestro campamento está acosado por muchos peligros, y aun así tenemos que ocuparnos de los que escapan de la devastación del Cataclismo.\n\nSi pretendemos refugiarnos aquí, tienes que ayudarnos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25388] = {title = "Cajón con carne de cangrejo", objective = "Lleva el cajón con carne de cangrejo a Adarrah en la Cicatriz del Contrabandista.", description = "Esta caja, con la etiqueta \"Carne de cangrejo\", parece haberse caído de un barco de carga que se hundió hace poco.\n\nSeguro que Adarrah agradecería un hallazgo así, después de la horrible experiencia por la que ha tenido que pasar.", progress = "¿Qué tienes ahí, <nombre>?", completion = "¡Guau, &lt;nombre&gt;! ¡Qué sorpresa!\n\nSi alguna vez alguien duda de ti, envíalo conmigo.\n\nLe diré a todo el que quiera escucharme que me has ayudado en un apuro.", rewards = "Recibirás:\n\nPeine de púas finas"}
MultiLanguageQuestData['mx'][25391] = {title = "Armas del espíritu", objective = "El médico brujo Uzer'i quiere que esperes mientras prepara las armas.", description = "Imbuir el muisek en las armas es un proceso difícil. Ahora que tengo todo el material que necesito y el muisek de las criaturas que has capturado, puedo empezar a trabajar. Por favor, espera. Volveré en un momento.", progress = nil, completion = "Tal y como prometí, &lt;nombre&gt;, el muisek de las criaturas ha quedado vinculado para siempre al poder de estas armas. \n\nAhora puedes hacer tuya su energía. Utilízala bien.", rewards = "Poder del HipogrifoPoder del gigante montésPoder del Dragón feéricoPoder del AntárbolRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25392] = {title = "¡Por todos los ciervos!", objective = "Rescata a tres cervatos heridos en El Averno y escóltalos de regreso con Mylune en la Arboleda de Aessina.", description = "¿Sabes hablar con los ciervos? La clave está en la nariz.\n\n<Se señala la nariz.>\n\nLas ciervas han escapado de las llamas, pero sus pequeños cervatillos... ¡Algunos siguen atrapados entre las llamas y el dolor!\n\nVuelve a El Averno y escolta a tres cervatos heridos hasta aquí, tráelos con sus madres, aquí a mi lado.\n\nPor favor salva a los cervatillos, ¡o te pondré ojos de corderito degollado!\n\n<Te mira con los ojos muy abiertos y aire ingenuo.>", progress = nil, completion = "¡Ay, yupi! ¡Alegre cervatillo!\n\nAhora podrán crecer y vivir AVENTURAS.\n\nEres genial.", rewards = "Coselete chupasalesLeotardos de salvaciervosCapa de flores alegresRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25394] = {title = "Más que una enfermedad", objective = "Mata a 10 crías nocivas.", description = "He descubierto una camada de crías de dragón cerca del camino hacia el norte, y sufren una enfermedad parecida. Los dragones Verdes son los custodios sagrados de la naturaleza. El hecho de que ellos padezcan también la enfermedad resulta tremendamente alarmante.\n\nTenemos que evitar a toda costa que esto se extienda aún más. Asesina a las crías infectadas, <nombre>, y vuelve conmigo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Bastón vuelovientoVelo esmeraldaGuardahombros de cría verdeMalla de anillas de TelaronRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25396] = {title = "Lágrimas de piedra", objective = "Reúne 7 lacrilitos.", description = "Tú <mismo/misma> has sido testigo, Ysondre nos ha dicho que las lágrimas de la tierra pueden sellar el portal del que emana esta corrupción.\n\nParece que no le falta razón. Hace semanas, en el claro del oeste, observé la angustia de los gigantes monteses. La frustración les consumía y lloraban, y sus lágrimas caían sobre las rocas en forma de brillantes cristales.\n\nA pesar de que los gigantes ya no lloran, seguramente Ysondre se refería a esos lacrilitos. Tenemos que reunirlos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25397] = {title = "La tierra, corrupta", objective = "Mata a 6 gigantes del risco corruptos.", description = "Los gigantes del risco de Feralas son extensiones de la propia tierra, <nombre>. Cuando la naturaleza florece son protectores benévolos y guardianes pacíficos.\n\nPero ahora que el bosque está contaminado, también ellos lo están.\n\nSi la corrupción se ha extendido hasta ellos, azotarán con violencia los árboles, la fauna y hasta las rocas que les dan forma.\n\nVe con cuidado. Si encuentras gigantes corruptos, acaba con ellos por el bien de los que aún no están contaminados.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25398] = {title = "Sellar Rama Oniria", objective = "Usa la lágrima de Ysondre para sellar el portal en Rama Oniria.", description = "Está lista. Coge esto, <nombre>: una fuente de esencia natural, bendecida por la voluntad de Ysondre.\n\nHacia el norte, al otro lado del arroyo, está Rama Oniria. Allí se encuentra El Gran Árbol, el más alto de Feralas, un retoño del mismísimo Árbol del Mundo. En su tronco se halla un portal hacia el corazón del Sueño Esmeralda, y este portal es el que debes sellar.\n\nEl portal estará vigilado, tienes que ser valiente.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Togas de Rama OniriaCinturón de esencia naturalRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25399] = {title = "Fuerzas Crestafuria", objective = "Mata a 10 nagas Crestafuria.", description = "¡Los Crestafuria están luchando ferozmente! Su líder es una prioridad, pero tenemos que matar a tantos como sea posible.\n\nVe delante de mí, nos encontraremos en el campo de batalla. ¡Sin compasión!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25400] = {title = "La amenaza Gordunni", objective = "Mata a 16 ogros Gordunni en las Altas Tierras Salvajes.", description = "Estulan, el Altonato de la torre, tiene tendencia a recluirse. Prácticamente no he tenido ocasión de hablar con él. Lo que sí que me ha dicho es que las ruinas de las Altas Tierras Salvajes que se encuentran hacia el sur están plagadas de ogros Gordunni.\n\nLos ogros no solo son una amenaza sino que además están destruyendo todo el bosque y la fauna de los alrededores. Estulan también me ha advertido de lo que podría ocurrir si encontrasen algún artefacto de poder de los Altonato entre las ruinas...\n\nDirígete hacia el sur, <nombre>, ¡y asesina a todos los Gordunni que te encuentres!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25401] = {title = "El orbe Gordunni", objective = "Recoge un orbe Gordunni de un brujo Gordunni.", description = "Además de deshacernos de los ogros...\n\nEstulan mencionó algo más sobre los ogros. Dijo que los brujos ogros debían de tener una especie de orbe, u otro objeto de poder.\n\nFue bastante lacónico con el tema, pero parecía disgustado... dijo que era \"imposible que fuesen Altonato\", así que supongo que querrá saber de dónde lo han sacado. Tráeme uno de esos orbes.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25404] = {title = "Si no estás contra nosotros...", objective = "Habla con Tyrus Cuerno Negro y convéncelo para que ayude en la lucha contra el Martillo Crepuscular.", description = "Al sur de aquí encontrarás una torre solitaria conocida como \"Penitencia de Cuerno Negro.\" A ella está atado un demonio: Tyrus Cuerno Negro.\n\nPuede que creas que estoy loca por ir pidiendo ayuda a un viejo enemigo, pero Cuerno Negro fue una vez mortal, y no puedo imaginar que quiera ver cómo el Martillo Crepuscular consigue su propósito.\n\nHabla con Cuerno Negro y mira si puedes convencerlo para que nos ayude en la lucha. Puede incluso que se redima.\n\n¡Pero no lo liberes!", progress = nil, completion = "Muy bien, &lt;raza&gt;. Los ayudaré, mortales, incluso desde mis ataduras.\n\nPero no me digan que es por mi redención. Lo hago por mis propios propósitos.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25405] = {title = "Descanso para los derrengados", objective = "Habla con el capitán Taylor.", description = "Lo has hecho muy bien, <raza>, pero aún queda mucho por hacer y me estoy desgastando.\n\nHe empleado gran parte de mis esfuerzos en enviar un mensaje urgente a los líderes del Anillo de la Tierra suplicando su ayuda.\n\nDebo descansar si quiero seguir siendo de ayuda aquí.\n\nHabla con el líder de los hombres que has salvado y haz lo posible por ayudarles a prepararse para la batalla.\n\nLos nagas están rastreando las aguas en nuestra busca. Solo es cuestión de tiempo que regresen, y seguro que vendrán pisando aún más fuerte.", progress = nil, completion = "Te escucho, &lt;raza&gt;.\n\nEntiendo la urgencia, pero estos hombres no están en condiciones de luchar.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25407] = {title = "Fuerzas de la naturaleza: Fuegos fatuos", objective = "Utiliza el silbato de Tessina para llamar a 3 fuegos fatuos Plumaluna.", description = "Los centinelas son el grueso de nuestras fuerzas en esta zona, pero un verdadero ejército de elfos de la noche no puede constar únicamente de elfos de la noche. Las criaturas de este bosque, nuestro hogar ancestral, nos han protegido durante siglos. Solo tenemos que reunirlas.\n\nCoge este silbato. Nuestros aliados conocen este sonido, así que podrás usarlo para llamarlos.\n\nAntes de que empieces a reunir criaturas, me gustaría que convocases a algunos de nuestros fuegos fatuos, solo para practicar. Los encontrarás justo al exterior de la fortaleza, entre los árboles.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25408] = {title = "Semillas de su desaparición", objective = "Recoge 8 bayas de bilis.", description = "Diezmaremos al Martillo Crepuscular corrompiéndolos y trastornándolos.\n\nYa que veo que no tienes intención de liberarme de mis ataduras, necesito que reúnas algunos componentes para mí. Mi propia esencia demoníaca ha corrompido la flora que rodea mi santuario. Necesito que recolectes algunas bayas de bilis de los hierbajos gemebundos que rodean esta torre.\n\nA cambio, mis pequeñas mascotas tratarán de recolectarte a TI. Trata de que no se inquieten unas a otras.", progress = "¿La flora local te lo está poniendo difícil?\n\n<Cuerno Negro se ríe de manera inquietante.>", completion = "Muy bien. Por favor, machaca las bayas hasta que se conviertan en un líquido pulposo. Tiene un aroma curioso, ¿verdad?\n\nVenga, no vomites. Es indigno de ti.", rewards = "Trituradores semillamuerteDeflector de filtro de semillasPodrás elegir una de estas recompensas:\n\nSales con olor a baya de bilis\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][25411] = {title = "Un nuevo amo", objective = "Utiliza el brebaje de baya de bilis embotellado sobre el cadáver de un señor del infierno Crepuscular y luego habla con él.", description = "La poción que has creado es lo suficientemente vil como para despertar a los muertos. Que es el propósito que tiene.\n\nMata a un señor del infierno Crepuscular y oblígale a tragar el brebaje. Revivirá, aunque brevemente, y quedará bajo tu dominio absoluto.\n\nHabla con él y averigua el verdadero nombre del elemental al que está canalizando hasta el mundo para quemar tu precioso bosque.", progress = nil, completion = "&lt;La horrible criatura que tienes ante ti habla con una voz titubeante, con el cuerpo roto pero brevemente resucitado por la poción vil de Cuerno Negro.&gt;\n\n¿Sí, maestro?", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25412] = {title = "El nombre nunca mencionado", objective = "Forma el verdadero nombre examinando las tres piedras de fuego.", description = "Hemos solicitado la ayuda de la furia y el fuego del Único, mi antiguo maestro.\n\nEl Averno es Su diseño.\n\nNunca mencionamos Su verdadero nombre ya que contiene su poder.\n\nCada uno de nosotros pronunciamos solo una parte. Cada parte está tallada en una piedra de fuego.\n\nEl nombre del Único está aquí, en El Averno. Busca las tres piedras...", progress = nil, completion = "¡Sí, sí! Muéstrame las runas que has descubierto.\n\n\"Vol'talo Thol'embaar\". Ese es el nombre de tu verdadero enemigo.\n\nEs posible que te enfrentes a uno de los generales de Ragnaros, enviado para incendiar la ladera de la montaña y allanar así el terreno para su conquista.\n\nTe explicaré cómo acabar con él.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25413] = {title = "Cambio de planes", objective = "Consigue el arpón oxidado y 3 espirales de cuerda.", description = "Bien, <chico/chica>. Un pequeño cambio de planes...\n\nCreo que se me ha ocurrido una manera de acabar con ese monstruo y tú me vas a ayudar.\n\nEn mi opinión, estás en deuda conmigo hasta que acabe con mi trabajo aquí. Y no me voy a marchar sin ese artefacto.\n\nEn primer lugar, tienes que registrar esos naufragios en busca de una buena cuerda y un arpón que aún se pueda utilizar.\n\nDespués... Bueno, ya te pondré al tanto más tarde.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25419] = {title = "El medallón de Lady La-La", objective = "Reúne los 5 trozos de medallón de los recolectores gilblin y combínalos para crear el medallón de Lady La-La.", description = "Esta pesada cadena está compuesta de docenas de eslabones de oro sin labrar.\n\nColgando del eslabón central está un fragmento opalescente de lo que una vez debió ser un gran medallón en forma de concha.\n\nTe preguntas si el resto de los fragmentos podrían estar cerca y si el medallón se podría recomponer en su forma original.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #5Objeto #1"}
MultiLanguageQuestData['mx'][25420] = {title = "Obstáculos antiguos", objective = "Acaba con 6 gólems de arenisca.", description = "Llevo años estudiando la puerta, tratando de encontrar una manera de entrar que no afecte a la arquitectura antigua que tras ella se esconde. ¡Parece que unos cuantos terremotos decidieron arrasarlo todo! Pero lo hecho, hecho está, y la entrada a Uldum se ha revelado.\n\nLo que no esperaba es que saliese nada de las ruinas antes de que pudiésemos entrar. Toda una muchedumbre de gólems, que han escapado del interior, corren como locos por el valle. ¡Alguien tiene que despejar la zona si queremos entrar ahí!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Cinturón de vigilante de la puertaSobrehombreras de decomisarioBufas de areniscaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25421] = {title = "La gran tablilla", objective = "Lleva la gran tablilla a Gunstan.", description = "Al fondo del cofre encuentras una gran tablilla. Fabricada en un material parecido a la piedra, pero totalmente suave y sin mella, está cubierta de escrituras extrañas.\n\nAlgunas de las escrituras se parecen a las de los muros, pero el resto resultan completamente diferentes. Seguramente a Gunstan le encantará ver esto.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Yelmo de jeroglíficosBotas de traslaciónCinturón de tablilla enrojecidoRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25422] = {title = "El legado de Niebla Negra", objective = "Reúne 6 montones de tierra resplandeciente.", description = "Estoy encadenada a este lugar... incluso hablar contigo me supone un gran esfuerzo. Casi no soy capaz de mantener esta forma.\n\nPuedo ayudarte, pero por favor, ayúdame primero a recomponerme un poco. Una vez que consiga centrarme mejor en este plano, podré hacerlo...\n\nSi pudiese abandonar esta tumba, la tierra del exterior está llena de depósitos arcanos antiguos, abandonados y olvidados durante siglos. ¿Podrías traerme algunos?", progress = "¿Tienes la tierra? Me cuesta mantenerme de una pieza... rápido...", completion = "¡Gracias! Gracias...\n\nMe siento mucho mejor. Solo con un poco más...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25423] = {title = "Sufrimiento antiguo", objective = "Reúne 6 esencias de alma.", description = "Debes tener cuidado al aventurarte más allá. Hay otros espíritus atrapados en este lugar, espíritus malévolos y odiosos. Todos han sufrido mucho.\n\nNo queda nada de lo que fueron en otro tiempo, solo el sufrimiento y la voluntad de vivir. Necesitaremos esa voluntad para invocar al señor supremo que me retiene aquí. Por favor, reúne la esencia de los espíritus, y tráemela.", progress = "¿Las has reunido?", completion = "Puedes sentir su angustia, ¿verdad?\n\nMis pobres amigos. Al menos podremos usaros para arreglar las cosas...", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25424] = {title = "Vuelve con Alysra", objective = "Vuelve con Alysra en las Ruinas de Lar'donir, en Hyjal.", description = "Te agradezco que me hayas liberado, <nombre>. Informaré a nuestros aliados de mis descubrimientos.\n\nTe sugiero que vuelvas con la dragona esmeralda que te envió.\n\nEl Martillo Crepuscular no solo pretende ganar terreno con este ataque. También buscan prisioneros.\n\nFandral Corzocelada está cautivo en los Túmulos. El ataque servirá de distracción para liberarlo. El porqué, lo desconozco. Tal vez nuestro dragón aliado pueda darte más información al respecto.", progress = nil, completion = "Estos acontecimientos son preocupantes, &lt;nombre&gt;. Debemos actuar con prontitud.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25426] = {title = "En guerra con los Zarpaleña", objective = "Reúne 10 cabelleras de gnoll Zarpaleña.", description = "La primera de las órdenes directas de Shandris es que nos encarguemos de los gnolls Zarpaleña de la zona. Se han extendido demasiado lejos y demasiado rápido, y se han convertido en una amenaza tanto para el bosque como para nuestros esfuerzos bélicos.\n\nSaben que estamos aquí. Desde que tomamos este campamento, hemos estado lanzando ataques encubiertos contra ellos. Ha llegado el momento de dar un golpe mayor; tráeme diez de sus cabelleras, y estaremos listos para pasar a la siguiente fase.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25428] = {title = "Corazón negro de fuego", objective = "Utiliza la rama carbonizada en El Averno para invocar a Thol'embaar. Mátalo y coge el corazón negro de Thol'embaar.", description = "Ahora utilizarás tu nueva información para atraer a Thol'embaar al plano mortal como una criatura salida del útero. Después, lo aplastarás.\n\nEl ritual es sencillo: toma esta rama carbonizada, golpea el suelo con ella tres veces y clama su nombre en voz alta.\n\nDebes llamarlo desde el corazón de El Averno. Acaba con él y tráeme su corazón negro.", progress = "¡Dime! ¿Ya has luchado contra Thol'embaar?\n\nEstoy viviendo gracias a ti, <raza>. ¡No me decepciones!", completion = "¡Aquí está! ¡Qué trofeo! Nacido en el fuego de otro plano...\n\nAdelante, &lt;raza&gt;. Aplástalo. Aplasta su corazón de carbón en tus manos y deja que el viento esparza las cenizas... Sí... Sí.", rewards = "Mandiletes de aplastaascuasCaperuza calcinadaPodrás elegir una de estas recompensas:\n\nSello de fuego naciente\n\nTe van a lanzar el siguiente hechizo:\n\nStart Quest: Good News... Bad News\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][25429] = {title = "Infestación de Zukk'ash", objective = "Reúne 20 caparazones Zukk'ash.", description = "Ahora que nos hemos quitado de en medio a los gnolls, podremos encargarnos de otros enemigos. Nuestros exploradores han descubierto en las inmediaciones lo que parece ser una colmena que se extiende bajo la tierra.\n\nLos insectos de la colmena son grandes y feroces, y muy probablemente representen una amenaza mayor que los propios gnolls. Quiero que te adentres en la colmena con precaución. Acaba con una buena cantidad de esos bichos y tráeme sus caparazones para analizarlos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25430] = {title = "Aliados esmeralda", objective = "Habla con Alysra en las Ruinas de Lar'donir, en Monte Hyjal.", description = "Los druidas de Hyjal no son los únicos que han jurado defender estas tierras. Los dragones esmeralda se han convertido de nuevo en importantes aliados de nuestra causa.\n\nHabla con Alysra en las Ruinas de Lar'donir, al norte, y averigua qué puedes hacer para ayudar.", progress = nil, completion = "Mi deber consiste en esto, en observar el movimiento del enemigo desde lo alto y en dirigir a nuestros ejércitos hacia donde se los necesita.\n\nTu ayuda es muy bienvenida.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25431] = {title = "Latigador con aguijón", objective = "Mata al latigador con aguijón en Las Galerías Retorcidas.", description = "La mayoría de los insectos que hemos visto merodear alrededor de la colmena eran enormes, pero mis exploradores me informan de la existencia de uno especialmente grande. Se supone que se trata de una avispa gigantesca, y parece que se encargaba de dirigir a las obreras de la superficie.\n\nNo sé demasiado sobre estos bichos, pero si empiezan a merodear más allá de ese hoyo en el suelo, tendremos que detenerlos. Mata a esa avispa gigante y vuelve a verme.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCaparazón cubierto de secreción"}
MultiLanguageQuestData['mx'][25432] = {title = "No es \"ogro\" todavía", objective = "Mata a 5 guardias de cerros Gordunni.", description = "Les hemos dado una buena a los ogros Gordunni en La Masacre, pero no hemos terminado el trabajo. Mis exploradores me han informado de que hay un grupo reunido en los cerros del norte; se reúnen por algún motivo.\n\nTal vez estén interesados en el asentamiento de la Horda que está cerca, y yo no quiero correr riesgos. Explora la zona, mata a todos los ogros con los que te encuentres y vuelve para informarme.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25433] = {title = "Avistamiento de pie grande", objective = "Mata a Puñogrande.", description = "Puede que lo hayas visto con tus propios ojos, pero otros exploradores han avistado una bestia enorme capturada por los ogros. Los informes dicen que se parece a un pie grande, pero si lo es, es el más grande que se haya visto nunca en Feralas.\n\nLo más probable es que los ogros estén tratando de adiestrarlo para que les obedezca. A pesar de que casi suena cómico, no pienso quedarme observando mientras consiguen adiestrarlo para que haga todo lo que le ordenen. Vuelve a los cerros y mátalo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Calzones de pellejo de yetiCalzado grandeCapa de Rama SombríaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25434] = {title = "Domando a los domadores", objective = "Mata a 6 domadores Gordunni.", description = "Puede que el pie grande suponga una amenaza mayor, pero también tenemos que deshacernos de los ogros. Los Gordunni llevan siendo una molestia demasiado tiempo, y Lady Shandris quiere que desaparezcan del mapa. Esperemos que estos sean los últimos.\n\nMata a los domadores Gordunni que tienen a la bestia encadenada, y asegúrate de que comprendan el precio que se paga por entrometerse.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25435] = {title = "La presión va en aumento", objective = "Obtén 3 tendones de tiburón de trilladores voraces y 2 pinzas de cangrejo afiladas de arácnidos Garrasable.\n\nEs posible atraer a los trilladores voraces con entrañas de cangrejo.", description = "Buenas, <chico/chica>.\n\nMe llamo Rendel.\n\nParece que la vieja Moanah y yo llegamos justo a tiempo, ¿eh?\n\n¡Erunak no estaba de broma cuando dijo que era cosa de vida o muerte!\n\nMientras nos encuentra un lugar seguro donde refugiarnos, voy a intentar conseguirte una alimaña para cabalgar.\n\nBueno, puede que no esté al tanto de lo último en vida marina, pero parece que los nagas saben montárselo bien aquí abajo.\n\nReúne unos cuantos chismes para hacer unas riendas y yo arreglaré un encantamiento.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25436] = {title = "Hermanas siniestras", objective = "Mata a 8 dríades corruptas.", description = "Ha ocurrido algo realmente alarmante. Mientras patrullaban, varios de mis exploradores sufrieron una emboscada por parte de las dríades.\n\nLas dríades son aliadas de los elfos de la noche y guardianas del bosque. Asumí que sencillamente se asustaron al ver a los huargen, pero los centinelas que envié después también fueron atacados.\n\nSea lo que sea lo que está pasando, no me gusta. Quiero que vayas a investigar tú también. Si las dríades están corrompidas... acaba con ellas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25437] = {title = "La llamada de Ysondre", objective = "Habla con Ysondre en lo alto de La Cumbre Esmeralda en las Bajas Tierras Salvajes.", description = "Un dragón del Sueño Esmeralda... ¿En qué lío te has metido, <nombre>?\n\nYo no la tendría esperando si fuese tú. El lugar del que hablaba se llama La Cumbre Esmeralda. Un sendero, alejado del camino principal y que atraviesa las Bajas Tierras Salvajes lleva hasta lo alto de una de las altas mesetas rocosas; allí encontrarás un pequeño santuario.\n\nBuena suerte, <nombre>. Espero volver a verte a salvo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25438] = {title = "La despedida de Ysondre", objective = "Habla con Adella en Rama Sombría.", description = "Y así, soy la última que queda.\n\nAunque decidiese permanecer en este mundo, no podría reunirme con el Vuelo Verde. Pero esta victoria me da esperanza. Tal vez, con el tiempo, podré encontrar la paz llevando una vida sencilla entre los mortales.\n\nDebes volver con tu gente. Diles que los dragones pesadilla han desaparecido, y que ya no serán una amenaza para estas tierras.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nCadena de TaerarCadena de EmerissCadena de Lethon\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][25439] = {title = "Corazón vengativo", objective = "Mata a 10 devastadores Zin'jatar.", description = "Estos son los nagas que se llevaron a nuestra gente. Solo necesito a uno para interrogarlo. Mata a los demás.\n\nNo les muestres piedad, <clase>. Ellos no la tendrían con nosotros.", progress = nil, completion = "Me alegro de tener de mi lado a un guerrero de verdad. Normalmente, mis hermanos chamanes no tienen agallas para el trabajo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25441] = {title = "Vórtice", objective = "Usa los globos de agua tumultuosa para atrapar a 30 serpientes enjambradoras.", description = "No siento especial predilección por las serpientes, y menos aquí abajo. Por suerte para nosotros, los elementos acuosos aún se doblegan a mi voluntad.\n\nToma estos globos y lánzalos en el terreno para que el agua cercana se convierta en un vórtice que se lleve a todas las serpientes cercanas. Con seguridad, los nagas volverán a las serpientes en nuestra contra, así que ten los globos a mano.", progress = nil, completion = "Con frecuencia, se nos confunde con druidas. Puede que eso sea cierto en el caso de algunos chamanes, pero no te dejes engañar por la ignorante creencia de que siempre somos pacíficos.\n\nNo hay nada que yo haga que sea armonioso. Yo impongo mi voluntad a los elementos sin ofrecer nada a cambio. No lo aceptaría de otra forma.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25442] = {title = "Una perla de sabiduría", objective = "Lleva la perla luminiscente al ensalmador de la tierra Duarn en la Cuenca de Marea Argenta.", description = "Esta perla es diferente a todo lo que has visto antes. Irradia luz y, si no estás equivocado, también una poderosa magia.\n\nSeguro que el ensalmador de la tierra Duarn, allá en la Cuenca de Marea Argenta, estará interesado en ella.", progress = "¿Sí, <clase>? ¿Has encontrado algo?", completion = "¿Qué es esto? ¿Una perla? Creo que mucho más.\n\nEsto es exactamente lo que estaba buscando. Gracias por traérmelo.", rewards = "Guanteletes de estrella marinaFaja de pejepuercoCorona de blanquilloRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25443] = {title = "El nombre nunca mencionado", objective = "Forma el verdadero nombre examinando las tres piedras de fuego en El Averno.", description = "¿Funcionó mi jarabe? ¿Hablaste con uno de ellos?\n\nEntonces ya sabes qué hacer. El nombre de su maestro elemental está escrito en tres piedras de fuego desperdigadas por El Averno. Examina cada una de estas piedras y tendremos el nombre que necesitamos.\n\n¡Date prisa! ¡Tu preciado bosque está en llamas!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25444] = {title = "E'pías pe'fectos", objective = "Captura a 5 ranas de Sen'jin y armonízalas con la visión de Vanira en su Tótem avizor.", description = "Sería tonto ir a ciegas, así qu'he creao unos pequeños e'pías p'a que reúnan información p'a Vol'jin. Tiene que sabé lo que ocurre en las i'las.\n\nPodría usá tu ayuda, si tú quieres. Te diré cómo. Primero, tienes que atrapá a las ranas. Les gusta ponese a la sombra de las palmeras de Sen'jin.\n\nCuando tengas las ranas, tráelas aquí a mi tótem y armonízalas con mi visión.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #5"}
MultiLanguageQuestData['mx'][25447] = {title = "Signos de cambio", objective = "Reúne 8 cornamentas de venados infectados.", description = "Una grave enfermedad ha recaído sobre las criaturas de este bosque. Al principio tenía la esperanza de que formase parte del curso de la naturaleza, pero no desaparece.\n\nLos venados del bosque que normalmente son fuertes y serenos, son los que más han sufrido. Unos han quedado completamente debilitados, otros escupen espuma presos de la rabia. Si pretendo consultar a los espíritus sobre esta enfermedad, necesitaré las cornamentas de los venados.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25448] = {title = "La amenaza de Nortearroyo", objective = "Mata a 6 arpías Nortearroyo y a 6 clamavientos Nortearroyo.", description = "Mi deber aquí consiste en proteger a Telaron. Incluso siendo vulnerable sin su meditación, hay suficientes amenazas en este bosque como para tenernos a los dos en guardia.\n\nPor eso me saca de quicio no tener la posibilidad de abandonar el campamento. El noroeste está completamente infestado de arpías, más de las que he visto jamás... Criaturas asquerosas que no hacen más que extender su porquería por las antiguas ruinas sin ningún miramiento.\n\nSon una amenaza para este campamento y no hay lugar para ellas en estas tierras. Te pagaré bien si te deshaces de ellas.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25449] = {title = "La marca de la calidad", objective = "Reúne 10 pellejos de yeti gruesos.", description = "Mi filosofía respecto a la peletería consiste en que el trabajo debe ser de la mayor calidad posible, sin concesiones. ¡Cualquiera que te diga que la calidad no importa tratará de venderte propiedades en primera línea de playa en Dun Morogh!\n\nEn mi más reciente búsqueda de materiales de alta calidad, me he encontrado con pellejos de yeti gruesos. Los yetis son autóctonos de Feralas, se han encontrado muchos en los Dominios de los Cicatriz de Rabia, al noreste. Quiero unos pocos, y te daré uno de mis productos de piel a cambio de diez pellejos. Si te parece justo, tenemos un trato.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Botas hechas a mano de PrattGuantes hechos a mano de PrattRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25451] = {title = "Pellejo de yeti prístino", objective = "Lleva el pellejo de yeti prístino a Pratt McGrubben al Bastión Plumaluna de Feralas.", description = "Has encontrado un pellejo de yeti impecable, increíblemente grueso y robusto. Mucho más que las que has visto en la Cicatriz de Rabia.\n\nSabes que Pratt McGrubben del Bastión Plumaluna busca siempre pellejos de yeti. Seguro que este pellejo le interesa.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25452] = {title = "La marca de la calidad", objective = "Reúne 10 pellejos de yeti gruesos.", description = "Me enorgullezco de mi trabajo con la piel, y creo que eso se nota; la calidad debe ser lo primero. ¡Cualquiera que te diga que la calidad no es importante, también te hará creer que la tierra no esconde secretos!\n\nEn mi más reciente búsqueda de materiales de alta calidad, me he encontrado con pellejos de yeti gruesos. Los yetis son autóctonos de Feralas, se han encontrado muchos al norte, en los Dominios de los Cicatriz de Rabia. Te daré uno de mis productos de piel a cambio de diez pellejos. Si te gusta el trato, lo cerramos ahora mismo.", progress = "¿Has podido conseguir diez pellejos de yeti grueso? Mis productos de piel son inmejorables, y te daré una muestra de ello si consigues los pellejos.", completion = "¡Ah, excelente! ¡Estos pellejos, con el tratamiento adecuado, son tan resistentes como el hierro, te lo aseguro! Voy a tener que hacer muchos intentos para obtener la mezcla adecuada para el curtido, pero no me cabe duda de que conseguiré dar un paso más allá con mi marca de calidad.\n\nPor lo que a ti respecta, &lt;nombre&gt;... tu ayuda ha sido valiosísima para mí. Elige el producto que quieras de todos los que he fabricado.", rewards = "Guantes hechos a mano de JangdorBotas hechas a mano de JangdorRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25453] = {title = "Calidad mejorada", objective = "Reúne 10 pellejos de yeti Cicatriz Feral de yetis Cicatriz Feral.", description = "No entiendo nada. El yeti Cicatriz de Rabia solía ser la mejor fuente de cuero de estas tierras... pero estas pieles son blandas, incluso están podridas en algunos puntos. Debe de tratarse de algún tipo de enfermedad que asola a estas criaturas.\n\nTendré que confiar en otra fuente. Los yetis de Vega Cicatriz Feral, al sur, tienen pellejos prácticamente igual de fuertes. Pero también son mucho más feroces así que no trates de cazarlos sin tomar las precauciones adecuadas, <clase>.", progress = "¿Siguen allí los yetis Cicatriz Feral? ¿Conseguiste las pieles?", completion = "¡Excelente, excelente! Estos pellejos van a quedar estupendos. Cuando estén bien curados serán incluso más resistentes que ahora.\n\nGracias de nuevo por tu ayuda, &lt;nombre&gt;. Ten, acepta una de mis últimas creaciones.", rewards = "Recibirás:\n\nJubón hecho a mano de Jangdor"}
MultiLanguageQuestData['mx'][25454] = {title = "Pellejo de yeti perfecto", objective = "Lleva el pellejo de yeti perfecto a Jangdor Zanco Veloz en Bastión Quebrantarrocas, Feralas.", description = "Has encontrado algo que podría ser el pellejo de yeti perfecto. Este pellejo es excepcionalmente grueso y robusto, mucho más que los de los yetis Cicatriz de Rabia.\n\nSabes que Jangdor Zanco Veloz del Bastión Quebrantarrocas siempre anda buscando pellejos de yeti. Este en concreto le interesará mucho.", progress = "¿Qué ocurre, <nombre>? ¿Tienes algo especial para mí?", completion = "¡Qué hallazgo! ¡Creo que es el pellejo de yeti más perfecto que he visto en mi vida!\n\nSin duda merece una buena recompensa. No suelo pagar mucho por un solo pellejo, pero sé que con este podré hacer algo muy especial. ¡Gracias por haber pensado en mí, &lt;nombre&gt;!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25458] = {title = "General Skessesh", objective = "Mata al general Skessesh y hazte con su cabeza.", description = "¡El líder de estas fuerzas debe caer! La ofensiva naga estará derrotada si nadie la dirige.\n\nVi al muy cobarde retirarse a uno de los edificios abandonados de la zona. ¡Acaba con todo el que se te ponga por delante y hazte con la cabeza del líder! Lady Shandris querrá verla con sus propios ojos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25460] = {title = "La tierra se levanta", objective = "Mata a 8 elementales roca hirviente.", description = "Los efectos del ataque del Martillo Crepuscular pueden percibirse incluso aquí, tan cerca del Árbol del Mundo.\n\nMientras nuestro bosque se consume por las llamas, la propia tierra se vuelve contra nosotros en un frenesí descontrolado.\n\nNo podemos permitir que los elementales campen a sus anchas. Ve a ayudar a nuestros hombres a encargarse de ellos.", progress = nil, completion = "Te lo agradezco, &lt;nombre&gt;. Tu destreza para la lucha es admirable. Serás un elemento crucial para detener el ataque de los elementales.", rewards = "Hombreras Piedraescama escaldadasGuantes de trituranúcleosTogas de romperrocasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25462] = {title = "Los osos de ahí arriba", objective = "Trepa a los árboles de la Arboleda Sibilante, agarra a los ositos de Hyjal atrapados y lánzalos al objetivo blando desde lo alto del árbol. Es perfectamente seguro.", description = "No tengas miedo de los osos de esta arboleda, <clase>, por el momento he conseguido calmarlos.\n\nLo que me preocupa ahora es el bienestar de los oseznos. El fuego hizo que los pequeños trepasen a los árboles, y ahora están atrapados. ¡Tenemos que bajar al suelo a los osos sanos y salvos!\n\nLas criaturas voladoras los asustan, así que tendrás que trepar a los árboles. Busca puntos de apoyo en los troncos. Trepa a los árboles, agarra a los oseznos y lánzalos... ¡SUAVEMENTE! hasta este objetivo.\n\nEl plan no puede fallar.", progress = nil, completion = "Te lo agradezco, &lt;nombre&gt;. Esos ositos están un poco conmocionados, pero sobrevivirán.\n\nAl menos los que cayeron en la colchoneta.", rewards = "Defensor de la naturalezaPantalones agarradores de árbolesSandalias pegapiéRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25463] = {title = "Preséntate ante Silvia", objective = "Preséntate ante Silvia en la Torre de Estulan.", description = "Un mago Altonato llamado Estulan, separado de sus hermanos supervivientes, ha construido una torre hacia el este en la que entrena a jóvenes elfos de la noche en el arte de la magia Arcana.\n\nDe no ser por la reciente compasión de Lady Tyrande hacia los de su clase, su ejecución sería mi deber ateniéndome a la ley. Lo vigilaremos de cerca, pero no negaré ayuda a mis centinelas por puro orgullo.\n\nHe enviado a Silvia de avanzada a la Torre de Estulan para comenzar una ofensiva contra los ogros que infestan el bosque de las inmediaciones. Preséntate ante ella para recibir más órdenes.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25464] = {title = "El regreso del barón Geddon", objective = "Canaliza el bastón de vidente de llamas para debilitar al barón Geddon.", description = "Ragnaros no es el único elemental poderoso que ha resurgido en nuestro mundo.\n\nEl temible barón Geddon lidera el ataque, y debemos acabar con esta destrucción.\n\nEl bastón de vidente ha demostrado ser poderoso. Tal vez tenga el poder suficiente como para debilitarlo hasta tal punto que nuestros archidruidas puedan retenerlo donde está.\n\nVe, <nombre>, y ten cuidado. El barón Geddon es un ser vengativo y traicionero.", progress = nil, completion = "Bien hecho, &lt;nombre&gt;. No podemos permitirnos perder más terreno en Hyjal.\n\nAl detener al barón Geddon, hemos asestado un enorme golpe al enemigo.", rewards = "Muñequeras de placas de vinculacalorMaza de canalizador druídicoHacha de fuego domeñadoRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25465] = {title = "A vueltas con los gigantes machacados", objective = "Utiliza el ultra-reductor de Zorbin para machacar a los zancaorillas y reúne 6 residuos de miniaturización.", description = "¡Eh, <amigo/amiga>! Todavía estoy trabajando en una variante del rayo reductor gnómico, ¡para su construcción estoy empleando avances tecnológicos GOBLIN superiores! Trato de evitarme problemas, como por ejemplo la muerte, así que me gustaría que lo probases en uno de los gigantes marinos que hay por la costa. Después de reducirlos, encontrarás unos residuos de miniaturización, ¡tráeme algunos!", progress = "Tuve que retocar el aparato para evitar que funcionase en los gigantes monteses. A pesar de que no fui yo quien iba por ahí machacando cosas, esos elfos de la noche me dieron una buena lección cuando descubrieron a esos tipos reducidos.", completion = "¡Espléndidamente espléndido! ¡No solo me alegro de que vuelvas con el residuo, sino de comprobar que mantienes todos tus apéndices principales intactos! Eso es, bueno, en realidad nunca fue peligroso utilizar el ultra-reductor, ¿verdad que no?\n\nTe agradezco el esfuerzo que has hecho por mí, &lt;nombre&gt;. Realmente eres un amigo de los goblins dondequiera que vayas. ¡Acepta esto como muestra de mi agradecimiento!", rewards = "Recibirás:\n\nMegatrituradora de ZorbinObjeto #1"}
MultiLanguageQuestData['mx'][25466] = {title = "Todavía más combustible para el Ultra-reductor", objective = "Reúne 10 núcleos de elemental de agua de los elementales marinos y de los rocíos marinos.", description = "Si en contra de lo que me dicta el sentido común, me quedo en La Costa Olvidada para montar una tienda de ingeniería, tendré que tratar con esos apestosos elementales. ¡Malditos sean esos descontrolados poderes de elementalismo!\n\nPor suerte para mí —y también para ti, mi <estimado/estimada> agente provocador— los elementales son una estupenda fuente de alimentación para mi Ultra-reductor. ¡Démosles un propósito en la vida! Eso sí, cuando los reduzcas, ¡guárdame los núcleos de elementales de agua!", progress = "Podría aburrirte con los detalles técnicos o la utilidad de los núcleos de elementales, pero en lugar de eso, te tentaré para que completes esta importante tarea ofreciéndote una valiosa recompensa. ¿De verdad has acabado?", completion = "¡Fantastiquísimo! Estos núcleos me darán trabajo un buen tiempo. Y si añadimos a eso el hecho de que ya hay menos elementales en la costa, ¡creo que no volveré a tener esa pesadilla en la que me veo obligado a montar mi negocio en el peor sitio que se pueda imaginar!\n\nGracias por tus esfuerzos, &lt;nombre&gt;. Aunque me repatea financieramente, quiero mostrarte mi agradecimiento con algo que seguramente apreciarás: ¡pasta!", rewards = "Recibirás:\n\nSombrero resistente al agua de Zorbin"}
MultiLanguageQuestData['mx'][25467] = {title = "El buche de Kliklak", objective = "Obtén la llave corroída de Kliklak para abrir el baúl semienterrado en el Bosque Kelp'thar.", description = "El hecho de que este mapa aún sea bastante legible, después de haber sido devorado y digerido por un cangrejo gigante, te sorprende gratamente.\n\nIndica claramente que se enterró un baúl en el Bosque Kelp'thar, detrás de un molusco gigante.\n\nUn boceto bien dibujado en la parte posterior del mapa muestra que el propietario, junto con su llave, fue devorado por un crustáceo hiperdesarrollado llamado Kliklak.", progress = "El ojo de la cerradura del cofre está cubierto de lapas, pero aún se puede utilizar.", completion = "Al satisfactorio sonido que produce un cofre al abrirse le sigue la visión de un tesoro antaño oculto.", rewards = "Recibirás:\n\nGran hacha cubierta de percebesObjeto #1"}
MultiLanguageQuestData['mx'][25468] = {title = "Fuerzas de la naturaleza: Dragones feéricos", objective = "Utiliza el reclamo de dragones feéricos de Jesana para reunir a 10 duendes dragón o duendes dardos.", description = "Nadie lo diría por su aspecto, pero los adorables dragones feéricos que habitan este bosque pueden volverse realmente feroces si se los adiestra adecuadamente. Pueden hacer cosas alucinantes con la energía mágica... absorberla, redirigirla, incluso anularla por completo.\n\nSolos son prácticamente inofensivos, pero en grandes grupos pueden tener efectos sorprendentes en una batalla. Encontrarás algunos en los campos del noroeste, pero ten cuidado, la Horda está cerca.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25472] = {title = "El bastón de vidente de llamas", objective = "Obtén 8 fragmentos de bastón carbonizados.", description = "Durante el ataque inicial de las fuerzas enemigas se perdió un poderoso artefacto conocido como el bastón de vidente de llamas. Era un antiguo bastón de hueso que otorgaba a su portador el control del elemento del fuego.\n\nSus fragmentos están desperdigados por la zona en la que nos encontramos. Encuéntralos y llévaselos a Malfurion. Tal vez el poder del artefacto sirva todavía para algo.", progress = "¿Sí, <nombre>?", completion = "Excelente, &lt;nombre&gt;. Esto será un arma genial contra las fuerzas enemigas.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25473] = {title = "Kaja'Cola", objective = "Llévale la caja de seis Kaja'Colas a Sassy Malallave en la Central SCK, en Kezan.", description = "Sassy ha estado dándome la paliza para que consiguiera Kaja'Cola para la fiesta que se da en tu honor hoy más tarde.\n\nUuuups, ¿se suponía que era una sorpresa? ¡Yo no te he dicho nada!\n\nDe todas formas, con la baja producción actual, esto es todo lo que he podido conseguir. ¿Se lo puedes llevar?", progress = "<Sassy mira con recelo la caja de seis, como si fuera a explotar cuando se la dieras.>\n\n¡Necesitamos más Kaja'Cola!\n\n¡Te juro que voy a despedir a Mechamojada si no lo mato antes!", completion = "Para que lo sepas, encontrarás Kaja'Cola en toda la ciudad. ¡Es el producto estrella del Cártel Pantoque de todos los tiempos!\n\nSolo recuerda esto, ¡la imagen lo es todo si queremos promocionarte a Príncipe mercante! No, espera, ¡los beneficios lo son todo! ¡Le siguen de cerca las explosiones en segundo lugar! ¡Y después, la imagen!", rewards = "Recibirás:\n\nKaja'ColaCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25475] = {title = "¡Encuentra a OOX-22/FE!", objective = "Lleva el localizador de emergencia al robot mensajero de Oglethorpe a una cueva que hay cerca de Vega Cicatriz Feral.", description = "Has descubierto un extraño instrumento metálico con forma de huevo. Jugueteas con uno de los botones del huevo y este cobra vida y se convierte en una especie de artilugio robótico gnomo. Del interior del huevo robótico sale una voz.\n\n\"Mi nombre es Oglethorpe Obnoticus, ¡y mi robot mensajero se ha averiado! Te recompensaré por su rescate. Por favor, lleva este localizador hasta el robot.\"\n\n\"He procesado las coordenadas del robot: se encuentra en una cueva, cerca de la Vega Cicatriz Feral.\"", progress = "Parece que has descubierto los restos de... ¿un pollo robótico? La voz que proviene del huevo vuelve de nuevo a la vida:\n\n\"¡Sí, un trabajo excelente! Este es sin duda mi robot mensajero, aunque mis sensores indican que necesita un empujón para que pueda volar de regreso a Bahía del Botín para ser reparado. Coloca el localizador en el interior del robot. ¡El localizador hará todo lo demás!\"", completion = "Colocas el huevo... el localizador de emergencia... dentro del pollo... del robot mensajero. \n\nOyes murmullos y zumbidos dentro del robot mientras se esfuerza por levantarse. Cuando el robot vuelve a la vida, oyes la voz de Oglethorpe una vez más, pero ahora proviene del interior del robot: \n\n\"¡OOX-22/FE está funcionando, pero necesita reparaciones! Pesa demasiado para que cargues con él, pero creo que tengo una idea. ¿Te apetece vigilarlo un poco más?\"", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][25476] = {title = "¡Escolta a OOX-22/FE!", objective = "Escolta a OOX-22/FE para que llegue sano y salvo y después preséntate ante Oglethorpe Obnoticus en Bahía del Botín.", description = "Vuelves a oír la voz del gnomo que sale del robot:\n\n\"Tengo que llevar a OOX-22/FE a un lugar abierto y seguro en el que pueda iniciar el largo proceso de despegue. Tiene un dispositivo de invisibilidad integrado, pero necesito tiempo para que vuelva a estar operativo. ¡Escolta al robot hasta, digamos, el camino principal! Allí podré tomarme mi tiempo para hacer que todo vuelva a funcionar correctamente.\"\n\n\"¡Escóltalo para que llegue sano y salvo y después ven a verme a Bahía del Botín! Oglethorpe Obnoticus. ¡Corto y cierro!\"Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Experimento volador fallidoFelpa de tela metálicaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][25477] = {title = "Más vale tarde que muerto", objective = "Usa la barrita de cebo de Moanah con una tortuga marina moteada y móntala de vuelta hasta ella.", description = "Saludos, <amigo/amiga>.\n\nMe alegra ver que sobreviviste a la batalla de una pieza.\n\nMientras Erunak intenta augurar un lugar donde estemos todos a salvo, te ayudaré a conseguir un medio de transporte menos agotador.\n\nHe preparado esta barrita de cebo para que la uses cerca de una tortuga marina. Es algo basto, pero tendría que servir para poner a una bajo tu control.\n\nCuando ya te sientas <cómodo/cómoda> con el animal, guíalo de vuelta aquí conmigo.", progress = nil, completion = "Qué lástima...\n\nBueno, si lo piensas, es un consuelo que al menos hayas vuelto ileso.", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][25478] = {title = "A la Cima", objective = "Pide prestado un jinete del viento a Dyslix Kami-Kaze y habla con Kanati Nube Gris en Cima Tramo Oeste en Feralas.", description = "Estamos llevando a cabo una misión de socorro en Cima Tramo Oeste para toda la región de Las Mil Agujas. El goblin Dyslix Kami-Kaze te prestará mi jinete del viento para que llegues a salvo hasta allí. Habla con Kanati Nube Gris cuando aterrices.\n\n¡Ve rápido por si hubiese vidas que salvar!", progress = nil, completion = "¿Te ha enviado Nyse? ¡Bien! ¡Necesitamos tu ayuda!", rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25479] = {title = "A Nueva Thalanaar", objective = "Pide prestado un hipogrifo a Dyslix Kami-Kaze y habla con Caryssia Cazaluna en Nueva Thalanaar en Feralas.", description = "Estamos llevando a cabo una misión de socorro en Nueva Thalanaar para toda la región de Las Mil Agujas. El goblin Dyslix Kami-Kaze te prestará un hipogrifo para que llegues a salvo hasta allí. Habla con Caryssia Cazaluna cuando aterrices.\n\n¡Ve rápido por si hubiese vidas que salvar!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][25481] = {title = "A Nueva Thalanaar", objective = "Pide prestado un hipogrifo a Seyala Mechón Nocturno y habla con Caryssia Cazaluna en Nueva Thalanaar en Feralas.", description = "Estamos llevando a cabo una misión de socorro en Nueva Thalanaar para toda la región de Las Mil Agujas. Seyala Mechón Nocturno te prestará mi hipogrifo para que llegues a salvo hasta allí. Habla con Caryssia Cazaluna cuando aterrices.\n\n¡Ve rápido por si hubiese vidas que salvar!Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
