MultiLanguageQuestData['mx'][28807] = {title = "Opinión experta", objective = "Llévale los distintivos sospechosos a Mathias Shaw al puesto de mando de IV:7 en Ventormenta.", description = "<Anduin sostiene los dos distintivos idénticos.>\n\n¡El medallón que encontramos en la granja es idéntico al de las notas de Samuelson! No puede tratarse de una coincidencia. Creo que Samuelson está tramando algo, pero necesitamos pruebas concluyentes antes de acusar a uno de los guardias en quien más confía mi padre.\n\nSolo hay una persona en quien confíe para aclarar esto: Mathias Shaw, director de IV:7. Enséñale estos distintivos a ver qué opina. Mientras tanto, ¡volveré al castillo y vigilaré a Samuelson como un halcón!", progress = "¿Qué es lo que me has traído?", completion = "¿Anduin ha estado investigando al Martillo Crepuscular? ¿No se supone que tenías que EVITAR que se metiera en líos?\n\nMmm. A ver esos distintivos que has encontrado.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28810] = {title = "No temerás peligro alguno", objective = "Revive a 4 soldados de Ventormenta heridos.", description = "¿Ya te has entregado a la Luz Sagrada, <hermano/hermana>? ¡Es la Luz Sagrada la que nos salva! ¡Es la Luz Sagrada la que me permite sanar a estos soldados demasiado exigentes! ¡La misma Luz Sagrada que te permitirá adentrarte en el campo que hay al norte y rescatar a nuestros hermanos caídos!\n\nLlévate este libro de oraciones al campo y aplica el toque de sanación de la Luz a los heridos.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTe van a lanzar el siguiente hechizo:\n\nUpdate Player Phase/Auras\n\nTambién recibirás:\n\nZapatos de abad de Villanorte"}
MultiLanguageQuestData['mx'][28814] = {title = "Seguidores y líderes", objective = "Mata a la Suma sacerdotisa Azil y a 101 seguidores devotos.", description = "Los documentos relatan la llegada de la Suma sacerdotisa Azil a las profundidades de El Núcleo Pétreo.\n\nDescribe a Azil como un miembro de alto rango del Consejo Crepuscular. Además, su cortejo de más de un centenar de seguidores devotos se prepara para un ritual profano de oscuridad inaudita.\n\nParece tratarse de un acontecimiento que debes detener.", progress = "Has vuelto, <nombre>. ¿Qué noticias traes?", completion = "¿Una suma sacerdotisa, dices? ¿Miembro del Consejo Crepuscular?\n\nUn trabajo excelente. Espero que las recompensas te plazcan.", rewards = "Espaldares de rituales profanosSortija de los ciento unoPodrás elegir una de estas recompensas:\n\nSello de Suma Sacerdotisa\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][28815] = {title = "Documentos Crepusculares", objective = "Hazte con los documentos Crepusculares.", description = "Hemos estado siguiendo a uno de los operativos del Martillo Crepuscular. Se hace llamar Molino Tormenta de Maná.\n\nTenemos razones para sospechar que lleva unos documentos importantes.\n\nSin embargo, no podemos ir más lejos sin abandonar nuestra tarea de defender el perímetro interior del Templo de la Tierra.\n\nLocaliza a Tormenta de Maná y quítale los documentos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28816] = {title = "A las profundidades", objective = "Preséntate al comandante Thorak en la Bahía de Garrafilada, en Durotar.", description = "El Anillo de la Tierra ha identificado el reino acuático de Vashj'ir como una fuente de energías destructoras del adversario.\n\nLos peligros que podríamos afrontar allí aún son inciertos, así que toda la información que puedas reunir será muy valiosa.\n\nLa Horda está enviando naves de guerra a la región. Para que te lleven habla con el comandante Thorak en la Bahía de Garrafilada.\n\nQue los espíritus te guíen, <nombre>.", progress = nil, completion = "¡Lok'tar, camarada! Has llegado justo a tiempo.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28820] = {title = "Retaguardia despejada", objective = "Preséntate ante el alguacil McBride frente a la Abadía de Villanorte, en el Bosque de Elwynn.", description = "¡Un trabajo excelente, <nombre>! Ahora la retaguardia está oficialmente despejada. Nos encargaremos de los rezagados. Quiero que vuelvas a ver al alguacil McBride, que se encuentra frente a la Abadía de Villanorte, y le cuentes que la situación goblin está controlada.\n\nAdiós, <clase>.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28825] = {title = "Una invocación personal", objective = "Habla con Naraat el Hablatierra en Ventormenta.", description = "<Una sensación extraña aflora dentro de ti, inundando tu mente con pensamientos e imágenes.>\n\nEscucha mis palabras, <nombre>.\n\nNuestro mundo se encuentra atrapado entre las garras de una crisis terrible.\n\nTe estoy llamando para que nos prestes tu ayuda en este momento de desesperación.\n\nSoy Naraat.\n\nVen a verme de inmediato y te revelaré tu mensaje.\n\nTe espero en El Santuario de la Tierra del Este, en la ciudad de Ventormenta.", progress = nil, completion = "Que tu sentido del honor y el deber sirva bien a Azeroth, &lt;clase&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28826] = {title = "El ojo de la tormenta", objective = "Naraat el Hablatierra quiere que mires en las Aguas de Clarividencia.", description = "Saludos, <héroe/heroína> de Azeroth.\n\nEn nombre de El Anillo de la Tierra te doy las gracias por responder a mi llamada.\n\nTu nombre nos es conocido, <nombre>.\n\nMuchas son tus hazañas y tus logros. Azeroth ya está en deuda contigo y necesita a sus héroes una vez más.\n\nYo solo soy el mensajero. Una poderosa presencia desea tener una audiencia contigo.\n\nObserva las Aguas de Clarividencia y contempla el dilema de nuestro mundo.", progress = nil, completion = "Ahora que has visto la verdad, ¿dónde servirás?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28827] = {title = "A las profundidades", objective = "Habla con el reclutador Burns en el Puerto de Ventormenta, en la ciudad de Ventormenta.", description = "El Anillo de la Tierra ha identificado el reino acuático de Vashj'ir como una fuente de energías destructoras del adversario.\n\nLos peligros que podríamos afrontar allí aún son inciertos, así que toda la información que puedas reunir será muy valiosa.\n\nLa Alianza está enviando naves de guerra a la región. Para que te lleven, viaja al noroeste de Ventormenta y habla con el reclutador Burns en el Puerto de Ventormenta.\n\nQue los espíritus te guíen, <nombre>.", progress = nil, completion = "Todos nuestros barcos de guerra han partido a luchar contra la Horda. Tendrás que coger el barco mercenario.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28828] = {title = "Manda huevos", objective = "Obtén 40 huevos de Viento Gélido.", description = "No tengo un paladar muy refinado, pero ni yo soporto el sabor de las quimeras que habrás visto por estos lares. Sus huevos, por otra parte, son otro asunto.\n\nLos huevos de quimera son los más ricos y cremosos que encontrarás fuera de Orgrimmar. Mucho mejores que esos huevos de búho tan sosos, y no son tan sulfúreos como los de los lechúcicos.\n\nQuiero tantos como puedas reunir. Ve al noreste y busca sus nidos en la nieve.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Fajín de golosoBrazales de nido de nieveGuardabrazos de escamas de OrvalloCapa de BuenazampaPodrás elegir una de estas recompensas:\n\nColgante de corazón de quimera\n\nTambién recibirás:\n\nTortilla de Orvallo"}
MultiLanguageQuestData['mx'][28829] = {title = "Picos afilados y cuernos puntiagudos", objective = "Mata 12 lechubestias en el Matorral del Ala del Búho.", description = "¿Que qué me ha pasado? Escucha, <clase>, y escucha bien, porque mi historia es una tragedia...\n\nMe enviaron al Matorral del Ala del Búho para buscar reliquias. Solo llegué hasta aquí antes de que me rodeara un torbellino de alas y espolones.\n\n¡Cómo rugían y cortaban, <clase>!\n\nAhora yazgo aquí, un orco destrozado sin nada más que la venganza en mente. Te lo ruego, <clase>: si tienes el más mínimo sentido del honor, ve al Matorral del Ala del Búho y ayúdame a recuperar el mío.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28830] = {title = "De tal palo...", objective = "Mata 8 revolcadores Machacahielo.", description = "Mis misteriosos benefactores me dieron más de una tarea. La segunda me llevó más al sur, al Cañón Levescarcha. ¡Cuál fue mi sorpresa al ver que el puente del cañón se había partido en dos y no se podía pasar de un lado al otro!\n\nAdemás, los revolcadores Machacahielo quedaron separados de sus padres, adultos y más fuertes. Pensé que podría derrotarlos en combate.\n\nEstaba equivocado. Me vi obligado a huir deshonrado.\n\nDales una lección a esos revolcadores, <nombre>. Lucha contra ellos y gana.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28831] = {title = "Maldito seas, Escárchido", objective = "Mata a Escárchido.", description = "Los gigantes Machacahielo no habrían supuesto un problema si no hubiera sido por ese maldito Escárchido. Cuando la tierra tembló y el puente se partió, sus amigos elementales de agua y él salieron de entre las rocas y ocuparon la zona inferior del Cañón Levescarcha, expulsando así a los gigantes.\n\n¡Maldito seas, Escárchido!\n\nMe harías un gran favor si lo metieras de nuevo en la tierra, <clase>. Lo encontrarás al sur, al fondo del cañón.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Capucha de vientos silbadoresPellejo de EscárchidoCinturón de alas de búhoCoraza del orco poéticoPodrás elegir una de estas recompensas:\n\nCercenadores de Jadrag\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][28832] = {title = "Orillas Crepusculares", objective = "Habla con el teniente Fawkes en Bancalto, en las Tierras Altas Crepusculares.", description = "Bien, solo tienes que subirte al hidroavión que hay detrás de mí y te llevaré a las Tierras Altas.\n\nTenemos que presentarnos ante un tipo llamado \"teniente Fawkes.\" Le prometí al Rey que llegaríamos allí en un abrir y cerrar de ojos así que me he tomado la libertad de deshacerme de todo el exceso de peso. Como los cinturones de seguridad. Los paracaídas. Los mapas. Los estabilizadores. El tren de aterrizaje.\n\nDe hecho yo nunca \"aterrizo\" con estas cosas de todas formas.", progress = nil, completion = "Ustedes dos son la última cosa que esperaba ver caer del cielo. ¡Bancalto está siendo atacado!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28834] = {title = "¡Rescata al Hablatierra!", objective = "Rescata a Erunak Hablapiedra.", description = "¡Bien! Has traído aliados.\n\nSi quieres rescatar a Erunak debes darte prisa.\n\nAhora ve. Ábrete paso por las salas de Neptulon. Encuentra al chamán y libéralo de aquellos gusanos... Si aún sigue con vida.\n\nNo temas que se te acerquen por la espalda. ¡Nada se me escapará!Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Cinturón de mil muertesLeotardos de golpes oportunosPodrás elegir una de estas recompensas:\n\nTalismán de bruja de mar\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][28836] = {title = "Los pecados de la Bruja del Mar", objective = "Mata a Lady Naz'jar en el Trono de las Mareas.", description = "¡Ese vil gusano se ha ganado un millar de muertes!\n\nNo va a ser fácil. Sus esbirros y ella se han atrincherado aquí, pero debe estar agotada tras su pelea con Neptulon.\n\n¡Es el momento de atacar! No tendremos otra oportunidad como esta.\n\n¡Atraviésala con tu acero, <nombre>!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Togas BrumadensaCinturón del HablapiedraJubón del Bosque de AlgasRecibirás:\n\n"}
MultiLanguageQuestData['mx'][28838] = {title = "La defensa de las lechubestias", objective = "Consigue un atrapasueños de lechubestia en Dun Mandarr.", description = "Qué lástima. Sea lo que sea lo que ha hecho Umbranse, no soy capaz de invertir su magia.\n\nEs más inteligente de lo que esperaba.\n\nPero tengo una alternativa. He visto que las lechubestias entran y salen de Mazthoril, aunque Umbranse la controle. Su magia druídica antigua debe de ser capaz de inutilizar la de Umbranse. Por suerte, resulta que soy una experta en sus métodos.\n\nVe hacia el sur, hasta Dun Mandarr. Encontrarás un cofre con un atrapasueños dentro.\n\nEse será tu primer paso.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28839] = {title = "Magia prehistórica", objective = "Hazte con la esencia del tótem garra, la esencia del tótem de vida y la esencia del tótem luna.", description = "Las cuevas sagradas de las lechubestias se encuentran al este. Dentro de algunas de ellas verás unos tótems. Quiero que te acerques a ellos y recojas toda la esencia que puedas de ellos. El atrapasueños debería poder absorber la esencia para poder usarla en Mazthoril.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nObjeto #1\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][28840] = {title = "Agua invernal", objective = "Hazte con 7 aguas invernales de los avatares de hielo del Cañón Levescarcha.", description = "No quiero que nuestra maniobra fracase, <nombre>. Eso no haría más que llamar la atención sobre nuestro trabajo y le daría a Umbranse la oportunidad de afinar sus defensas. No, tenemos que hacerlo bien a la primera.\n\nEl Cañón Levescarcha, al sur, nos da acceso a poderosos elementales de hielo. El agua que contienen los cuerpos de los elementales debería amplificar el poder de tu atrapasueños y garantizar nuestro éxito.\n\nHazte con el agua, <nombre>, y luego vuelve a nuestro pequeño campamento.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Ataduras cálidas de HalehMusleras de avatar de hieloCapa de agua invernalRecibirás:\n\n"}
MultiLanguageQuestData['mx'][28841] = {title = "La Tormenta Arcana interior", objective = "Utiliza el atrapasueños potenciado para cerrar 5 teseractos Arcanos dentro de Mazthoril.", description = "La magia natural de Mazthoril puede provocar un desastre terrible si se utiliza mal. Los hechizos caprichosos que lanza Umbranse dentro de la caverna han abierto cierta cantidad de teseractos (portales, en otras palabras) que conectan con otros mundos. Para que pueda volver a Mazthoril antes debemos cerrar los portales.\n\nEl atrapasueños cerrará los portales y te permitirá entrar en la guarida de Umbranse. Primero derrota a todo lo que salga de los teseractos y utiliza el atrapasueños para cerrarlos antes de que libere nada más en este mundo.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][28842] = {title = "La hora de Umbranse", objective = "Mata a Umbranse el Hablaalmas.", description = "Umbranse se esconde al fondo de Mazthoril. Ha llegado su hora.\n\nPor desgracia, no puedo acompañarte en esta misión. Aunque me encantaría echarle el guante a esa sabandija, la magia de Mazthoril me haría pedazos en este estado. No, necesito que lo termines tú por mí.\n\nCuando esté hecho, utiliza este talismán. Te devolverá al egreso <sano y salvo/sana y salva>.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Brazales de MazthorilYelmo de atrapasueñosGuanteletes de NamBastón de UmbranseRecibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][28845] = {title = "La Cumbre del Vórtice", objective = "Busca a Itesh dentro de la entrada a La Cumbre del Vórtice.", description = "Los elementales del aire hicieron prisionero a uno de nuestros líderes civiles.\n\nSeguramente le estén torturando para que hable mientras tenemos esta conversación.\n\nVe a La Cumbre del Vórtice, el lugar de donde salieron esas repugnantes criaturas y busca a Itesh.\n\nEncontrarás la entrada a La Cumbre del Vórtice sobre la costa sureste de Uldum.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28847] = {title = "La persecución de Umbranse", objective = "Preséntate ante Haleh en el Egreso de Berilo, en Cuna del Invierno.", description = "Hemos aislado la ubicación de Umbranse en Cuna del Invierno. Es lo que sospechaba.\n\nUmbranse está en Mazthoril, la caverna que antes pertenecía al Vuelo Azul, al suroeste. Mi madre, Haleh, te recibirá allí. Se encuentra fuera de la cueva, en un pequeño campamento con otros supervivientes.\n\nBusca su hoguera.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28848] = {title = "Rastrear al Hablaalmas", objective = "Preséntate ante Nymn en Vista Eterna, en Cuna del Invierno.", description = "He oído historias de Umbranse, aunque nunca lo he visto en persona. Se rumorea que ha estado reuniendo artefactos mágicos, aunque no sabría decir con qué propósito.\n\nLo mejor es transmitirle esta información a un aliado en quien confiemos. Nymn, el elfo noble, se encuentra en Vista Eterna, la ciudad goblin al noreste. Cuéntale lo que hemos descubierto hoy.", progress = nil, completion = "Umbranse... Entiendo. Transmitiré esta información a mi gente.\n\nNos pondremos en contacto contigo si nos vuelves a hacer falta.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28850] = {title = "El tejado de la prisión", objective = "Habla con Darius Crowley en el tejado de la Prisión Guardapétrea, en la ciudad de Gilneas.", description = "No entiendo por qué el Rey quiere perder tiempo salvando su pellejo, pero si quieres arriesgar tu vida, allá tú.\n\nCrowley y sus hombres están en el tejado, ¡seguramente conspirando contra el Rey mientras hablamos!", progress = nil, completion = "Cringris tiene razón. Esas bestias no se preocupan por nuestras afiliaciones políticas.\n\nGilneas necesita permanecer unida.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28852] = {title = "Debilítalos", objective = "Libera a un draco rojo dentro de Grim Batol y úsalo para eliminar a 30 habitantes trogg y 15 esbirros del Martillo Crepuscular.", description = "¡Por fin llegan refuerzos! Me alegro tanto de verte. Nunca nos imaginamos lo atrincheradas que podían estar las fuerzas del Martillo Crepuscular. ¡Y son tantos!\n\nHan capturado a varios de nuestros dracos justo en la sala principal. Rompe sus cadenas y libéralos.\n\nCuando estén libres podremos arrasar con fuego las salas. Móntate sobre un draco rojo y llama la atención de tus objetivos. Más te vale reducir las líneas enemigas antes de adentrarte más en las ruinas.", progress = nil, completion = "¡Excelente, &lt;nombre&gt;! Me alegro de que nuestros dracos pudieran servirte de ayuda. Gracias por rescatarlos de las garras del Martillo Crepuscular.", rewards = "Recibirás:\n\nTesoros de Grim Batol"}
MultiLanguageQuestData['mx'][28853] = {title = "Mata al mensajero", objective = "Mata a Drahga Quemasombras y toma su misiva para Cho'gall.", description = "Gracias, <clase>, por hacer frente a los horrores de este oscuro y terrible lugar.\n\nLas entrañas de Grim Batol son el corazón de la máquina de guerra de Cho'gall. Si queremos detener sus maquinaciones por las Tierras Altas, tenemos que averiguar todo lo que podamos sobre estas profundidades.\n\nBusca en ellas a Drahga Quemasombras. Es el mensajero de Cho'gall, el enlace entre este sitio y El Bastión del Crepúsculo. Debemos conocer los secretos que porta.", progress = "¿Qué has descubierto, <clase>?", completion = "&lt;Tooranu echa un vistazo a los documentos que has descubierto.&gt;\n\nEstá todo aquí, &lt;nombre&gt;. Los detalles sobre cómo el culto está devastando las Tierras Altas, a quién han enviado, quiénes son y qué planean hacer. No tiene precio.\n\nVoy a compartir esta información con el resto de El Anillo de la Tierra inmediatamente. Gracias, amigo.", rewards = "Yelmo de conocimientos secretosSandalias del mensajeroBufas de TooranuRecibirás:\n\n"}
MultiLanguageQuestData['mx'][28854] = {title = "Cerrando un oscuro capítulo", objective = "Mata a Erudax, el Duque de las profundidades.", description = "Este terrible lugar era la pesadilla de Alexstrasza. Durante lo que los mortales llaman la Segunda Guerra, fue encadenada en las profundidades que hay abajo y su atormentado retoño fue obligado a servir a la Horda corrupta por los demonios.\n\nAlexstrasza ahora es libre, pero la bestia conocida por Erudax aún corrompe a su retoño abajo.\n\n<El cuerpo de Fardollama se tensa de ira.>\n\nMátalo, <clase>. ¡Aplástalo para que podamos poner fin a estos horrores de una vez por todas!", progress = nil, completion = "Está hecho.\n\nSi pudiera derrumbar esta montaña, lo haría.", rewards = "Coraza del testigoGuantes de FardollamaBrazales del erradicadorRecibirás:\n\n"}
MultiLanguageQuestData['mx'][28856] = {title = "Las arenas de Silithus", objective = "Preséntate ante la clamavientos Cuerno Digno en Fuerte Cenarion, en Silithus.", description = "Vamos a ver... ¡Ah, aquí hay una buena! ¡Silithus!\n\nParece que el Círculo Cenarion necesita ayuda con una infestación de insectos de algún tipo.\n\n<Vizzie se estremece.>\n\n¡Aj! No, gracias, no es para mí. Si la alternativa son bichos, prefiero mil veces congelarme aquí en Vista Eterna.\n\nMmm... Aquí dice que los visitantes deberían hablar con la clamavientos Cuerno Digno, y la manera más fácil de llegar allí es el camino que atraviesa los riscos del noroeste del Cráter de Un'Goro.\n\n¿Te interesa?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28857] = {title = "Las Tierras Devastadas: la otra punta del mundo", objective = "Preséntate ante el intendente Lungertz en el Castillo de Nethergarde.", description = "Este es interesante. Dice que hay que presentarse ante el intendente Lungertz en el Castillo de Nethergarde, en las Tierras Devastadas. ¡Es prácticamente el punto más lejano de este lugar!\n\nAquí dice que tienen problemas con los ataques de la Horda. ¡Pff! ¡Ni me había enterado de que la Horda tuviera una avanzada en las Tierras Devastadas! Tengo entendido que por aquellos lares se suelen preocupar más por los demonios que por la rivalidad.\n\nVas a tener que cruzar el Mare Magnum y viajar al sur desde el Pantano de las Penas.\n\n¿Te interesa?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28858] = {title = "Las Tierras Devastadas: la otra punta del mundo", objective = "Preséntate ante Okrilla en el Bastión Machacamiedo, en las Tierras Devastadas.", description = "Esto es interesante. Dice que los miembros de la Horda deberían hablar con Okrilla en el Bastión Machacamiedo.\n\n¡Mmm! ¡Ni me había enterado de que la Horda controlara el Bastión Machacamiedo!\n\nSupongo que Okrilla necesita ayuda para luchar contra los ogros y la Alianza. ¡No debe de tener suficiente con la cantidad de demonios que hay allá abajo!\n\nLa mejor forma de llegar al Bastión Machacamiedo es cruzar el Mare Magnum y tomar el camino al sur desde el Pantano de las Penas.\n\n¿Te interesa?Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28859] = {title = "Las dunas de Silithus", objective = "Preséntate ante la clamavientos Cuerno Digno en Fuerte Cenarion, en Silithus.", description = "Fuerte Cenarion, en Silithus, es uno de los mayores asentamientos de druidas de Kalimdor. Es casi tan grande como Claro de la Luna, colega.\n\nAlgún día Zen'Aliri igual se va a Fuerte Cenarion... A luchar contra el Martillo Crepuh'cular, a sanar la tierra allá donde los silítidos la quiebran... Pero a Zen'Aliri le dicen que eh'pere.\n\nAsí que Zen'Aliri eh'pera.\n\nLa forma más fácil de llegar hah'ta allí es el camino que atraviesa los riscos al noroeste del Cráter de Un'Goro.\n\nSi a ti no te dicen nada... Nada te impide marcharte.", progress = nil, completion = "Bienvenido a Fuerte Cenarion, viajero.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28860] = {title = "Manteniendo a raya a los Faucedraco", objective = "Mata a maleantes Faucedraco y recoge 8 insignias Faucedraco. Los personajes con nombre propio de las Ruinas de Bramal también llevarán insignias.", description = "Con tu ayuda, le hemos asestado un buen golpe a los Faucedraco, pero aun así, sus ataque diarios en las afueras de Bramal persisten. ¡Tenemos que mantener la presión!\n\nRegresa a la batalla que se está librando en las Ruinas de Bramal, al sur y al suroeste. Mata a maleantes Faucedraco y recoge las insignias que llevan sus mejores guerreros.", progress = "¿Cómo va la lucha, <clase>?", completion = "Sí, ¡así se hace! Con héroes como tú al mando, estoy orgulloso de ser parte de la Alianza.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28861] = {title = "Lucha como un Martillo Salvaje", objective = "Recoge 10 barriles de cerveza de Bramal de las Ruinas de Bramal. Ten cuidado, ¡es fuerte!", description = "<Blundy gira su copa.>\n\n¡Me he quedado sin cerveza, <nombre>!\n\nDirígete a las Ruinas de Bramal y mira a ver si queda algo, antes de que le hinquen el diente esos sucios Faucedraco.\n\nNo tengas reparo en echar un par de tragos. Una buena jarra del viejo Bramal reforzará tus habilidades de combate.", progress = "¿Tienes algo?", completion = "¡Oh sí, es un buen cargamento! Esto me durará... digamos que hasta mañana.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28862] = {title = "Nunca te dejes la comida atrás", objective = "Reúne 10 provisiones de comida Martillo Salvaje en las Ruinas de Bramal.", description = "Los refugiados siguen llegando en masa a Bramal, huyen de la lucha, ¡y tengo hambre! Es decir, ellos. Los refugiados tienen hambre.\n\n¡Consígueme algo de comida de las Ruinas de Bramal! Registra las ruinas hacia el sur, el este y el sudoeste en busca de las provisiones que puedan quedar. Sobre todo si son grandes patas de jamón. ¡Me encantan! Eh, a los refugiados les encantan.\n\nY mira a ver si puedes encontrar salchichas.", progress = "¿Tienes algo de comida?", completion = "¡Oh, sí, llegas justo a tiempo! Se me estaba abriendo el apetito... al trabajar tan duro para alimentar a estos hambrientos refugiados. Sí, señor.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28863] = {title = "El señor de la guerra Halthar ha regresado", objective = "Mata al señor de la guerra Halthar.", description = "Lo está haciendo otra vez, <nombre>. El señor de la guerra Halthar... el terror de la comarca. Los han visto a él y a su draco causando problemas en el sur, en las Ruinas de Bramal.\n\n¡Mata a Halthar, <nombre>! Enviaremos algunas bandas de guerreros para ayudarte una vez que entres en acción.", progress = nil, completion = "Mal asunto, pero bien hecho de todas formas. Gracias, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28864] = {title = "Que corra la cerveza", objective = "Habla con Hammelhand en el camino que hay al sudeste del Monte del Rayo y escolta a una caravana de provisiones hasta Kirthaven.", description = "Después de la boda de mi hermana, le cogí el gusto a esa cerveza Cebatruenos que Kurdran importó de Dun Morogh. Hay más de camino, ¡pero los Faucedraco no paran de atacar nuestra caravana!\n\nDirígete al lado sudeste del Monte del Rayo y alcanza la caravana. Busca a un tipo llamado Hammelhand, junto al camino y ayúdale a llevarla a través del paso.\n\nTú llévala hasta Kirthaven y la recogeremos allí.", progress = nil, completion = "Imagínate. Nunca pensé que llegaría a gustarme una cerveza importada. ¡Gracias, &lt;nombre&gt;!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28865] = {title = "La llamada de la matrona de guerra", objective = "Preséntate ante Okrilla en el Bastión Machacamiedo, en las Tierras Devastadas.", description = "Nuestra venerable matrona de guerra, Okrilla, me ha enviado a los confines del mundo en busca de héroes dignos de unirse a nuestra causa. ¿Te interesa reforzar el control de la Horda sobre los Reinos del Este? Si es el caso, atraviesa este portal a las Tierras Devastadas y preséntate ante Okrilla en el Bastión Machacamiedo.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28866] = {title = "En El Núcleo Pétreo", objective = "Habla con la Celadora de la tierra Yrsa dentro de El Núcleo Pétreo.", description = "¿Dices que ese tal Molino Tormenta de Maná y la Suma sacerdotisa Azil se iban a reunir en El Núcleo Pétreo?\n\nSuena importante. Será mejor que les sigamos el rastro. No queremos que el Martillo Crepuscular arme la gorda justo delante de nuestras narices.\n\nHabla con la Celadora de la tierra Yrsa dentro de El Núcleo Pétreo. Está destacada allí para impedir que el Martillo Crepuscular intente recuperar el Templo de la Tierra.", progress = nil, completion = "Ya era hora de que enviaran algo de ayuda.\n\n¿Molino Tormenta de Maná? Parece que los dos buscamos a la misma persona.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28867] = {title = "¡Nethergarde te necesita!", objective = "Habla con el intendente Lungertz en el Castillo de Nethergarde, en las Tierras Devastadas.", description = "¡Nethergarde te necesita, <clase>! Me ha enviado el intendente Lungertz para acabar con los esbirros malvados de Okrilla y reclutar héroes capaces de la Alianza. ¡Ayúdanos a luchar contra la Horda!\n\nSi estás <dispuesto/dispuesta> a ayudar, atraviesa este portal que tengo delante para ir a las Tierras Devastadas y habla con el intendente.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28868] = {title = "La vista desde ahí abajo", objective = "Usa la encogemática con 5 constructores Peloescarcha en Refugio Peloescarcha.", description = "Tenemos que detener la construcción de ese poblado Peloescarcha. Si les dejamos avanzar demasiado, será más difícil impedir que se establezcan aquí de forma permanente.\n\n¡Ha llegado la hora de hacer que esos brutos vean el mundo desde la perspectiva de un gnomo! Coge esta encogemática gnoma y úsala para que los constructores Peloescarcha se pongan a nuestro nivel. No podrán levantar sus herramientas y la construcción llegará a un punto muerto.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][28871] = {title = "Aplastando el Martillo Salvaje", objective = "Mata aceros de guerra Martillo Salvaje para recoger 8 insignias Martillo Salvaje. Los personajes con nombre propio de las Ruinas de Bramal también llevan insignias.", description = "Los Martillo Salvaje se vuelven más osados ahora que tienen a sus aliados de la Alianza. Se atreven a cruzar el río. ¡Hazlos retroceder!\n\nBusca y aplasta a los aceros de guerra Martillo Salvaje que luchan en el lecho del río y dentro de las Ruinas de Bramal a lo largo de la orilla norte. Los mejores llevan insignias: reúnelas y tráemelas para demostrar tu lealtad a la causa Faucedraco.", progress = "Enséñame las insignias que has conseguido, <clase>.", completion = "¡Mira lo que tenemos aquí! Un simple &lt;clase&gt; de la Horda puede acabar con los Martillo Salvaje por docenas. ¿Qué esperanza les queda ahora?", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28872] = {title = "Guerra total", objective = "Rompe 10 barriles de cerveza de Bramal en las Ruinas de Bramal.", description = "Algunos Martillo Salvaje todavía se aferran a la esperanza de reclamar las Ruinas de Bramal en el norte, al otro lado del río. ¡Quémalas! Rompe barriles de cerveza de Bramal. Ese odioso brebaje es lo suficientemente potente como para explotar cuando le prendes fuego.\n\nNo me preguntes por qué.\n\nY no me preguntes cómo pueden bebérselo.", progress = nil, completion = "Sí, sí. Quémalos, como si hicieras que las marmotas salieran de sus agujeros...\n\nBien hecho, &lt;nombre&gt;.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28873] = {title = "Otras fauces que alimentar", objective = "Reúne 10 provisiones de comida Martillo Salvaje en las Ruinas de Bramal.", description = "<A Griff le rugen las tripas.>\n\nSigo teniendo hambre. Es así... todos los días, tengo hambre.\n\nTengo entendido que hay más comida almacenada en las Ruinas de Bramal, al otro lado del río, al norte, donde están luchando. Trae algo de esa comida a mi boca.", progress = "<Griff se relame.>", completion = "&lt;Griff agarra ávidamente un montón de comida, suficiente para alimentar a una docena de hombres.&gt;\n\n¡Fantástico! ¡Esto me llenará durante... horas!", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28874] = {title = "Engánchalos", objective = "Usa el enganchacarnes con púas para desmontar y matar a 4 jinetes de grifos de Bramal.", description = "Los Martillo Salvaje tardan menos en entrenar grifos de guerra que nosotros en someter y controlar a los dracos. ¡No podemos dejar que nos sigan superando en número!\n\nCaza a los jinetes de grifos que están volando sobre el río al norte de Garganta de Sangre. Coge este gancho y lánzaselo cuando pasen volando cerca de ti. Su ímpetu hará que salgan disparados de su silla y caigan a tus pies. ¡Mata a los jinetes de grifos caídos!", progress = nil, completion = "Hiciste que pareciera fácil, &lt;nombre&gt;.\n\n¡Quítale su montura a los Martillo Salvaje y no son nada!", rewards = "Recibirás:\n\nObjeto #1"}
MultiLanguageQuestData['mx'][28875] = {title = "Destruye al chamán", objective = "Mata al alto chamán MacKilligan.", description = "Nuestros exploradores en el campo informan de que el alto chamán MacKilligan ha salido de Bramal y está luchando entre las Ruinas de Bramal, al noroeste de aquí, al otro lado del río.\n\nEs un tipo peligroso, <nombre>, responsable de la muerte de muchos Faucedraco. CAERÁ, de eso no hay duda.\n\nLa pregunta es: ¿serás tú quien tenga el honor de matarlo?", progress = nil, completion = "¡El alto chamán ha caído! Seguro que Bramal intenta enviar a otros, pero hoy los Faucedraco han triunfado.", rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28876] = {title = "Hacia La Empalizada Mor'shan", objective = "Preséntate ante Kadrak en La Empalizada de Mor'shan en la frontera entre Los Baldíos del Norte y Vallefresno.Kadrak nos pide ayuda desde La Empalizada Mor'shan, al norte de aquí.\n\nLa empalizada se encuentra en la frontera entre Los Baldíos del Norte y Vallefresno. Es la línea de batalla en el enfrentamiento contra la Alianza.\n\nEstamos expulsando a los elfos de la noche fuera del bosque. ¡Nos haremos con sus recursos para la Horda!\n\nPara llegar hasta allí, toma el Camino del Oro hacia el norte desde El Cruce.\n\n¡El destino te aguarda!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", description = "Kadrak nos pide ayuda desde La Empalizada Mor'shan, al norte de aquí.\n\nLa empalizada se encuentra en la frontera entre Los Baldíos del Norte y Vallefresno. Es la línea de batalla en el enfrentamiento contra la Alianza.\n\nEstamos expulsando a los elfos de la noche fuera del bosque. ¡Nos haremos con sus recursos para la Horda!\n\nPara llegar hasta allí, toma el Camino del Oro hacia el norte desde El Cruce.\n\n¡El destino te aguarda!Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28877] = {title = "Se llama Movedaga y mata arpías", objective = "Localiza a Darsok Movedaga en Los Baldíos del Norte.Hay un orco que vive al oeste, en el borde dentado del camino de destrucción del Cataclismo.\n\nLo llaman Movedaga, <nombre>. Lo llaman así porque... su... en realidad creo que es su nombre de verdad.\n\n<Ollaboquilla se encoge de hombros.>\n\nA lo que iba: es una máquina de matar arpías. Mata arpías. Y le encanta. Así se gana la vida. ¡Ve a verle! Aprende cómo se hace, realiza tus sueños. A lo mejor te haces profesional.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", description = "Hay un orco que vive al oeste, en el borde dentado del camino de destrucción del Cataclismo.\n\nLo llaman Movedaga, <nombre>. Lo llaman así porque... su... en realidad creo que es su nombre de verdad.\n\n<Ollaboquilla se encoge de hombros.>\n\nA lo que iba: es una máquina de matar arpías. Mata arpías. Y le encanta. Así se gana la vida. ¡Ve a verle! Aprende cómo se hace, realiza tus sueños. A lo mejor te haces profesional.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][28878] = {title = "Un obsequio del Festival de Invierno", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['mx'][28879] = {title = "De vuelta al orfanato", objective = "Regresa con tu pupilo al orfanato de Dalaran y entrega el silbato de huérfano Oráculo a la supervisora de huérfanos Aria en Dalaran.Nos la pasamos mejor que nunca contigo, <nombre>. Ojalá pudieras ser <nuestro papá/nuestra mamá>, pero tienes que llevarnos de nuevo con la supervisora de huérfanos Aria, en Dalaran.\n\n¿Quizás puedas venir a visitarnos de nuevo alguna vez? Nos encantó conocer proles aletas invernales y ver a la reina dragón. ¡Nadie nos creerá cuando digamos que conocimos a un Magno!\n\nTe vamos a extrañar, <nombre>. Prometemos escribirte algún día, ¿sí?Podrás elegir una de estas recompensas:\n\n", description = "Nos la pasamos mejor que nunca contigo, <nombre>. Ojalá pudieras ser <nuestro papá/nuestra mamá>, pero tienes que llevarnos de nuevo con la supervisora de huérfanos Aria, en Dalaran.\n\n¿Quizás puedas venir a visitarnos de nuevo alguna vez? Nos encantó conocer proles aletas invernales y ver a la reina dragón. ¡Nadie nos creerá cuando digamos que conocimos a un Magno!\n\nTe vamos a extrañar, <nombre>. Prometemos escribirte algún día, ¿sí?Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nGalleta de mascota mágicaPago de cascarrabias\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][28880] = {title = "De vuelta al orfanato", objective = "Regresa con tu pupilo al orfanato de Dalaran y entrega el silbato de huérfano wolvar a la supervisora de huérfanos Aria en Dalaran.¿Sabes qué? No estás mal después de todo, <nombre>. Llevas a Kekek a un montón de sitios divertidos. Kekek hace muchos amigos nuevos y hace cosas que ningún otro cachorro hace.\n\nTú y Hemet Nesingwary y los cachorros de Claro Avalancha son ahora mis nuevos mejores amigos. ¿Quizás alguna vez traes a Kekek ese libro de las verdes colinas? Kekek promete escribir algunas veces también, contarte cómo van las cosas. A veces puede que hasta ser bueno con los niños lengua-grande.\n\nAhora Kekek tiene que volver con la señorita de los huérfanos, Aria, en la ciudad púrpura de los humanos.Podrás elegir una de estas recompensas:\n\n", description = "¿Sabes qué? No estás mal después de todo, <nombre>. Llevas a Kekek a un montón de sitios divertidos. Kekek hace muchos amigos nuevos y hace cosas que ningún otro cachorro hace.\n\nTú y Hemet Nesingwary y los cachorros de Claro Avalancha son ahora mis nuevos mejores amigos. ¿Quizás alguna vez traes a Kekek ese libro de las verdes colinas? Kekek promete escribir algunas veces también, contarte cómo van las cosas. A veces puede que hasta ser bueno con los niños lengua-grande.\n\nAhora Kekek tiene que volver con la señorita de los huérfanos, Aria, en la ciudad púrpura de los humanos.Podrás elegir una de estas recompensas:\n\n", progress = nil, completion = nil, rewards = "Podrás elegir una de estas recompensas:\n\nGalleta de mascota mágicaPago de cascarrabias\n\nTambién recibirás:\n\n"}
MultiLanguageQuestData['mx'][28882] = {title = "Victoria en Tol Barad", objective = "Gana una batalla en Tol Barad y vuelve con el mayor Marsden en el Campamento de Baradin en la Península de Tol Barad.", description = "Hemos peleado mucho para controlar esta horrible roca como para permitir que la Horda se interponga ahora en nuestros planes. Mantener el control sobre Tol Barad es nuestra prioridad, y necesitamos que nos ayudes, <nombre>. Consigue la victoria en Tol Barad y vuelve a informarme de tu triunfo.", progress = nil, completion = "¿A qué huele? Ah... Huele a victoria. Tus esfuerzos en Tol Barad son un gran triunfo para toda la Alianza, no olvidaremos tu contribución.", rewards = "Recibirás:\n\nMención de honor de Tol BaradPuntos de honor"}
MultiLanguageQuestData['mx'][28884] = {title = "Victoria en Tol Barad", objective = "Gana una batalla de Tol Barad y vuelve con el coronel Karzag en los Dominios Grito Infernal en la Península de Tol Barad.", description = "Mantener el control en Tol Barad es la clave de nuestro plan estratégico en los Reinos del Este, <raza>. Tenemos que hacer todo lo necesario para mantener a la Alianza fuera de esta isla; lo que quiere decir que necesitamos tu ayuda. Enfréntate a todo lo necesario para hacerte con el control de Tol Barad e infórmame de la victoria.", progress = nil, completion = "¡Me traes noticias de la victoria, como yo esperaba! Todo triunfo en Tol Barad es un triunfo para la Horda. No te quepa duda, tus esfuerzos aquí serán recompensados.", rewards = "Recibirás:\n\nMención de honor de Tol BaradPuntos de honor"}
