MultiLanguageQuestData['mx'][30112] = {title = "Ajuste de cuentas", objective = "La forestal oscura Marrah quiere que mates al príncipe Keleseth en la Fortaleza de Utgarde.", description = "Las fuerzas de Utgarde se organizan bajo la tutela del príncipe Kelesath, un embajador San'layn de la Plaga.\n\nNo podemos permitir que los vrykuls se beneficien por más tiempo de sus consejos. Siléncialo.", progress = nil, completion = "¡Qué bien sienta la venganza! Y pensar que esto es solo un aperitivo antes del plato fuerte.\n\nArthas recibirá pronto su merecido.", rewards = "Envoltura de los San'laynAtaduras de vendettaBrazales de taumaturgoAvambrazos del liberador de VenganzaRecibirás:\n\n"}
MultiLanguageQuestData['mx'][30120] = {title = "Limpiar Drak'Tharon", objective = "Drakuru quiere que uses el elixir de Drakuru en su pedestal dentro de Drak'Tharon. Para usar el elixir de Drakuru ahí vas a necesitar 5 mojos de resistencia.\n\nObjeto provisto: \n", description = "¡Eh, colega, eh'tás aquí! ¡Eh'tá bien, colega!\n\nDrak'Tharon pronto eh'tará limpio de esos no mueh'tos locos y volverá a su noble propósito. A cambio de tu ayuda, ¡los tesoros más valiosos de la foh'taleza serán tuyos, colega!\n\nCuando llegues a lo alto, me tienes que invocar y ejecutaré el ritual.\n\nPor deh'gracia, pa' invocah'me hay un precio a cambio. Tienes que recoger el mojo de los supervivientes.", progress = nil, completion = "¡Hemos hecho algo grande, tron! Y eh'to solo es el comienzo...\n\nCuando llegue el momento, búh'came en Zul'Drak.\n\n¡Hay que ganar una guerra, tío!", rewards = "Escarpes tentadoresSobrehombros del seductorGrilletes de oscuros susurrosEmbozo de la tentaciónRecibirás:\n\nObjeto #1"}
