MultiLanguageQuestData['mx'][31443] = {title = "Gurami tigre volador", objective = "Lleva el gurami tigre volador a Nat Pagle al Muelle de los Pescadores.", description = "Has pescado un pez único… con alas. Tal vez sea digno de la experta opinión de Nat Pagle en el Muelle de los Pescadores.Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nCurrency Token Test Token 4"}
MultiLanguageQuestData['mx'][63448] = {title = "Una entrega de lujo", objective = "Saludos, <nombre>, estaba esperándote. Un conocido mío me pidió que te diera esto cuando pasaras por aquí. Dijo algo sobre una recompensa por una compra que le hiciste a unos amigos en común.\n\n¿Tú entiendes a qué se refería?\n\nDa igual, aquí está tu recompensa. Ah, y una cosa más. Mi conocido, Landro Tirolargo, dijo que si alguna vez pierdes este objeto, podrá darte un reemplazo si lo buscas en Bahía del Botín.", description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nCazador de fase reanimadoPortal OscuroSenda de Illidan"}
