MultiLanguageQuestData['mx'][64845] = {title = "Campaña de guerra de la Alianza", objective = "Gana una partida en un campo de batalla y ve a hablar con un general de brigada de la Alianza de cualquier capital de la Alianza o Shattrath.", description = "¡La guerra se avecina y la Alianza necesita combatientes para aplastar a la Horda!\n\nNuestra misión consiste en frustrar sus operaciones en todos nuestros campos de batalla activos.\n\nHas venido a alistarte, ¿cierto?", progress = nil, completion = "¡Magníficas noticias, &lt;clase&gt;! Si nuestros despliegues tácticos continúan teniendo este éxito, la Horda se retirará del todo dentro de poco.", rewards = "Recibirás:\n\nBonificación de reclutamiento"}
MultiLanguageQuestData['mx'][65284] = {title = "Tetera de potaje goblin", objective = "Saludos, <clase>, estaba esperándote. Un conocido mío me pidió que te diera esto cuando pasaras por aquí. Dijo algo sobre una recompensa por una compra que le hiciste a unos amigos en común.\n\n¿Tú entiendes a qué se refería?\n\nDa igual, aquí está tu recompensa. Ah, y una cosa más. Mi conocido, Landro Tirolargo, dijo que si alguna vez pierdes este objeto, podrá darte un reemplazo si lo buscas en Bahía del Botín.", description = nil, progress = nil, completion = nil, rewards = "Recibirás:\n\nTetera de potaje goblin"}
