MultiLanguageQuestData['mx'][78137] = {title = "Un nuevo comienzo", objective = "Busca un instructor de <clase> en Orgrimmar.", description = "Aparece una carta por arte de magia en el revestimiento de tu armadura. Dice:\n\n\"¡Te damos la bienvenida a Orgrimmar, capital de la Horda!\n\nBusca un instructor de <clase> para comenzar tu entrenamiento. Te ayudará a prepararte para las aventuras que te esperan por todo Azeroth y más allá\".Recibirás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\nEquipo de supervivencia de Azeroth"}
MultiLanguageQuestData['mx'][78151] = {title = "Herramientas para la supervivencia", objective = "Abre el equipo de supervivencia y equipa un arma.", description = "Antes de comenzar, tendrás que equiparte con armas y armadura adecuadas a tus talentos. ¡La vida de los aventureros nunca es aburrida, y nunca se sabe qué puede pasar!\n\nPreparé un equipo de supervivencia para tus aventuras. Contiene más armas, armaduras y raciones. Confío en que le darás un buen uso.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][78158] = {title = "Entrenamiento de combate", objective = "Practica un hechizo hablando con un instructor de <clase>.", description = "A medida que crece tu poder, también crecen tus capacidades para convertirte en <un/una> hábil <clase>.\n\nPuedes encontrar instructores en todo Azeroth, y en las capitales como Orgrimmar, Cima del Trueno o Entrañas.\n\nEl conocimiento también tiene su precio, pero haré una excepción por hoy y te reembolsaré. Cuando te hayas preparado, vuelve a hablar conmigo para entrenar tus habilidades.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
MultiLanguageQuestData['mx'][78752] = {title = "Prueba de defunción: Protocolo gamma de runa titánica", objective = "El archimago Lan'dalock de Dalaran quiere que vuelvas con el medallón de profanador de cualquier jefe final de calabozo. \n\nEsta misión solo se puede completar en cualquier calabozo de dificultad Protocolo gamma de runa titánica.", description = "¡La presencia del Rey Exánime no puede extenderse más! \n\n¡El Consejo de los Seis ha decretado que todos aquellos con la fuerza suficiente deben tomar armas y ayudar a proteger la seguridad de Azeroth!", progress = "Volvemos a hablar, <nombre>. ¿Eso significa que tuviste éxito en tus obligaciones?", completion = "¡Puedo sentir la maldad que hay en su interior! Llevaré esto al \n\nConsejo de los Seis para que lo investiguen.", rewards = "Recibirás:\n\nPuntos de justicia"}
MultiLanguageQuestData['mx'][78753] = {title = "Prueba de defunción: Amenazas contra Azeroth", objective = "El archimago Lan'dalock de Dalaran quiere que vuelvas con el artefacto misterioso de cualquier jefe final de calabozo. \n\nEsta misión solo se puede completar en cualquier calabozo de dificultad heroica.", description = "¡Debemos seguir presionándolos en todos los frentes!\n\n¡El Consejo de los Seis ha decretado que todos aquellos dispuestos a luchar deben tomar las armas y ayudar a proteger la seguridad de Azeroth!", progress = "¿Qué sucede? ¿Por qué no te has encargado de las amenazas?", completion = "¡Qué hallazgo tan interesante! Llevaré esto al \n\nConsejo de los Seis para que lo investiguen.", rewards = "Recibirás:\n\nPuntos de justicia"}
MultiLanguageQuestData['mx'][82984] = {title = "Talentoso", objective = "Activa la interfaz de talentos y asigna 5 puntos de talento.", description = "Cada <clase> usa facultades, talentos y capacidades distintas. Nos diferenciamos en que cada uno tiene intereses e inclinaciones particulares.\n\nCuando aumenta tu nivel de poder, puedes mejorar y especializar tus facultades a partir de tus talentos, sin necesidad de recibir entrenamiento.\n\nSi cambias de opinión sobre estos talentos, puedes hablar con un instructor de <clase> para modificarlos.Recibirás:\n\nCuando completes esta misión ganarás:\n\n", progress = nil, completion = nil, rewards = "Recibirás:\n\n"}
